-- 6. TESTAR CONEXÃO BÁSICA
-- ============================================================

SELECT
  'CONNECTION TEST' as test_group,
  current_user as connected_as,
  current_database() as database,
  version() as postgres_version,
  NOW() as current_time;

-- ============================================================
-- 7. VERIFICAR ÍNDICES
-- ============================================================

SELECT
  'ÍNDICES' as test_group,
  schemaname,
  tablename,
  indexname,
  indexdef
FROM pg_indexes
WHERE schemaname = 'public'
ORDER BY tablename, indexname;

-- ============================================================
-- 8. VERIFICAR CONSTRAINTS
-- ============================================================

SELECT
  'CONSTRAINTS' as test_group,
  tc.table_name,
  tc.constraint_name,
  tc.constraint_type
FROM information_schema.table_constraints tc
WHERE tc.table_schema = 'public'
ORDER BY tc.table_name, tc.constraint_type;

-- ============================================================
-- 9. VERIFICAR FOREIGN KEYS
-- ============================================================

SELECT
  'FOREIGN KEYS' as test_group,
  tc.table_name,
  kcu.column_name,
  ccu.table_name AS foreign_table_name,
  ccu.column_name AS foreign_column_name
FROM information_schema.table_constraints AS tc
JOIN information_schema.key_column_usage AS kcu
  ON tc.constraint_name = kcu.constraint_name
  AND tc.table_schema = kcu.table_schema
JOIN information_schema.constraint_column_usage AS ccu
  ON ccu.constraint_name = tc.constraint_name
  AND ccu.table_schema = tc.table_schema
WHERE tc.constraint_type = 'FOREIGN KEY'
  AND tc.table_schema = 'public'
ORDER BY tc.table_name;

-- ============================================================
-- 10. VERIFICAR FUNÇÕES CRIADAS
-- ============================================================

SELECT
  'FUNÇÕES' as test_group,
  routine_name,
  routine_type,
  data_type as return_type
FROM information_schema.routines
WHERE routine_schema = 'public'
  AND routine_name IN (
    'is_admin',
    'is_manager_or_admin',
    'get_user_role',
    'is_order_owner',
    'sync_order_payment_status',
    'update_updated_at_column'
  )
ORDER BY routine_name;

-- ============================================================
-- 11. VERIFICAR TRIGGERS
-- ============================================================

SELECT
  'TRIGGERS' as test_group,
  event_object_table as table_name,
  trigger_name,
  event_manipulation as event,
  action_statement as action
FROM information_schema.triggers
WHERE trigger_schema = 'public'
ORDER BY event_object_table, trigger_name;

-- ============================================================
-- 12. ESTATÍSTICAS DAS TABELAS
-- ============================================================

SELECT
  'ESTATÍSTICAS' as test_group,
  schemaname,
  relname as table_name,
  n_tup_ins as inserts,
  n_tup_upd as updates,
  n_tup_del as deletes,
  n_live_tup as live_rows,
  n_dead_tup as dead_rows
FROM pg_stat_user_tables
WHERE schemaname = 'public'
ORDER BY relname;

