-- >>> BEGIN 20251231023800_2b909a8a-cd0f-484e-8abf-bc0656fe3b54.sql >>>

-- Criar tabela de roles para RBAC
CREATE TABLE IF NOT EXISTS public.roles (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  name VARCHAR(50) NOT NULL UNIQUE,
  description TEXT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);

-- Inserir roles padrão
INSERT INTO public.roles (name, description) VALUES 
  ('admin', 'Administrador com acesso total'),
  ('manager', 'Gerente com acesso a relatórios e aprovações'),
  ('seller', 'Vendedor com acesso básico'),
  ('viewer', 'Visualizador apenas leitura')
ON CONFLICT (name) DO NOTHING;

-- Adicionar coluna role_id na tabela profiles se não existir
DO $$ 
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns 
    WHERE table_schema = 'public' 
    AND table_name = 'profiles' 
    AND column_name = 'role_id'
  ) THEN
    ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS role_id UUID REFERENCES public.roles(id);
  END IF;
END $$;

-- Definir role padrão (seller) para profiles existentes
UPDATE public.profiles 
SET role_id = (SELECT id FROM public.roles WHERE name = 'seller')
WHERE role_id IS NULL;

-- Enable RLS
ALTER TABLE public.roles ENABLE ROW LEVEL SECURITY;

-- Policies para roles
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'roles' AND policyname = 'Roles are viewable by authenticated users') THEN
    CREATE POLICY "Roles are viewable by authenticated users"
    ON public.roles
    FOR SELECT
    USING (auth.role() = 'authenticated');
  END IF;
END $$;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'roles' AND policyname = 'Only admins can manage roles') THEN
    CREATE POLICY "Only admins can manage roles"
    ON public.roles
    FOR ALL
    USING (
      EXISTS (
        SELECT 1 FROM public.profiles p
        JOIN public.roles r ON p.role_id = r.id
        WHERE p.user_id = auth.uid() AND r.name = 'admin'
      )
    );
  END IF;
END $$;

-- <<< END 20251231023800_2b909a8a-cd0f-484e-8abf-bc0656fe3b54.sql <<<

-- >>> BEGIN 20251231024259_526ec13a-dacb-4a65-a724-61688978e5fb.sql >>>

-- Tabela para solicitações de reset de senha pendentes
CREATE TABLE IF NOT EXISTS public.password_reset_requests (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  email TEXT NOT NULL,
  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected')),
  requested_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
  reviewed_at TIMESTAMP WITH TIME ZONE,
  reviewed_by UUID,
  reviewer_notes TEXT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);

-- Enable RLS
ALTER TABLE public.password_reset_requests ENABLE ROW LEVEL SECURITY;

-- Políticas RLS
-- Qualquer pessoa pode criar uma solicitação (não autenticado)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'password_reset_requests' AND policyname = 'Anyone can create password reset request') THEN
    CREATE POLICY "Anyone can create password reset request"
    ON public.password_reset_requests
    FOR INSERT
    WITH CHECK (true);
  END IF;
END $$;

-- Gestores e admins podem ver todas as solicitações
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'password_reset_requests' AND policyname = 'Managers and admins can view all requests') THEN
    CREATE POLICY "Managers and admins can view all requests"
    ON public.password_reset_requests
    FOR SELECT
    USING (
      has_role(auth.uid(), 'admin'::app_role) OR
      EXISTS (
        SELECT 1 FROM public.profiles p
        JOIN public.roles r ON p.role_id = r.id
        WHERE p.user_id = auth.uid() AND r.name IN ('admin', 'manager')
      )
    );
  END IF;
END $$;

-- Gestores e admins podem atualizar (aprovar/rejeitar)
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'password_reset_requests' AND policyname = 'Managers and admins can update requests') THEN
    CREATE POLICY "Managers and admins can update requests"
    ON public.password_reset_requests
    FOR UPDATE
    USING (
      has_role(auth.uid(), 'admin'::app_role) OR
      EXISTS (
        SELECT 1 FROM public.profiles p
        JOIN public.roles r ON p.role_id = r.id
        WHERE p.user_id = auth.uid() AND r.name IN ('admin', 'manager')
      )
    );
  END IF;
END $$;

-- Index para busca por email e status
CREATE INDEX IF NOT EXISTS idx_password_reset_requests_email ON public.password_reset_requests(email);
CREATE INDEX IF NOT EXISTS idx_password_reset_requests_status ON public.password_reset_requests(status);

-- <<< END 20251231024259_526ec13a-dacb-4a65-a724-61688978e5fb.sql <<<

