-- >>> BEGIN 20260322215809_62dd4de8-256f-4131-9e83-b7878e64edf4.sql >>>
-- Fix CRITICAL: order_items SELECT policy is too permissive (USING true)
DROP POLICY IF EXISTS "Sellers can read order items" ON public.order_items;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'order_items' AND policyname = 'Sellers can read own order items') THEN
    CREATE POLICY "Sellers can read own order items"
    ON public.order_items
    FOR SELECT
    TO authenticated
    USING (
      EXISTS (
        SELECT 1 FROM public.orders o
        WHERE o.id = order_items.order_id
        AND (o.seller_id = auth.uid() OR has_role(auth.uid(), 'admin'::app_role) OR is_manager_or_admin())
      )
    );
  END IF;
END $$;

-- Fix WARN: login_attempts INSERT allows forging records
DROP POLICY IF EXISTS "Authenticated can insert login attempts" ON public.login_attempts;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'login_attempts' AND policyname = 'Users can insert own login attempts') THEN
    CREATE POLICY "Users can insert own login attempts"
    ON public.login_attempts
    FOR INSERT
    TO authenticated
    WITH CHECK (
      email = (SELECT email FROM auth.users WHERE id = auth.uid())
      OR user_id = auth.uid()
      OR user_id IS NULL
    );
  END IF;
END $$;
-- <<< END 20260322215809_62dd4de8-256f-4131-9e83-b7878e64edf4.sql <<<

-- >>> BEGIN 20260322222206_f51714c7-31f4-48de-950e-5de6a2533fc0.sql >>>

DROP POLICY IF EXISTS "Users can insert own login attempts" ON public.login_attempts;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'login_attempts' AND policyname = 'Users can insert own login attempts') THEN
    CREATE POLICY "Users can insert own login attempts"
    ON public.login_attempts
    FOR INSERT
    TO authenticated
    WITH CHECK (
      (email = (SELECT users.email FROM auth.users WHERE users.id = auth.uid())::text)
      OR (user_id = auth.uid())
    );
  END IF;
END $$;

-- <<< END 20260322222206_f51714c7-31f4-48de-950e-5de6a2533fc0.sql <<<

-- >>> BEGIN 20260322224817_54541d0b-46a0-471b-8386-fd60f4bc7d34.sql >>>
-- Drop the current INSERT policy that requires auth
DROP POLICY IF EXISTS "Users can insert own login attempts" ON public.login_attempts;

-- Create new INSERT policy allowing both authenticated and anonymous inserts
-- This is needed because failed login attempts happen before auth
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'login_attempts' AND policyname = 'Anyone can insert login attempts') THEN
    CREATE POLICY "Anyone can insert login attempts"
    ON public.login_attempts
    FOR INSERT
    TO authenticated
    WITH CHECK (true);
  END IF;
END $$;

-- Also add anonymous insert capability for pre-auth logging
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'login_attempts' AND policyname = 'Anon can insert login attempts') THEN
    CREATE POLICY "Anon can insert login attempts"
    ON public.login_attempts
    FOR INSERT
    TO anon
    WITH CHECK (true);
  END IF;
END $$;

-- <<< END 20260322224817_54541d0b-46a0-471b-8386-fd60f4bc7d34.sql <<<

