-- >>> BEGIN 20260326193116_2c55f931-6722-4778-bff4-71f5b4c39752.sql >>>

-- Fix prevent_role_self_update to allow trigger/migration context
CREATE OR REPLACE FUNCTION public.prevent_role_self_update()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $$
BEGIN
  IF OLD.role IS DISTINCT FROM NEW.role THEN
    IF auth.uid() IS NOT NULL AND NOT has_role(auth.uid(), 'admin') THEN
      RAISE EXCEPTION 'Only admins can change roles';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

-- Drop duplicate trigger (prevent_profile_role_change and prevent_profile_role_change_trigger are duplicates)
DROP TRIGGER IF EXISTS prevent_profile_role_change ON public.profiles;

-- Fix prevent_profile_role_change to allow trigger/migration context  
CREATE OR REPLACE FUNCTION public.prevent_profile_role_change()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $$
BEGIN
  IF OLD.role IS DISTINCT FROM NEW.role THEN
    IF auth.uid() IS NOT NULL AND NOT has_role(auth.uid(), 'admin') THEN
      RAISE EXCEPTION 'Only admins can change the role field on profiles';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

-- Now run the one-time sync
UPDATE public.profiles p
SET role = ur.role::text,
    updated_at = now()
FROM public.user_roles ur
WHERE p.user_id = ur.user_id
  AND (p.role IS DISTINCT FROM ur.role::text);

-- <<< END 20260326193116_2c55f931-6722-4778-bff4-71f5b4c39752.sql <<<

-- >>> BEGIN 20260326193133_c0cc9d48-fecb-4bec-9cf7-a065eb468c7d.sql >>>

-- Update handle_new_user to NOT set profiles.role (the sync trigger handles it)
CREATE OR REPLACE FUNCTION public.handle_new_user()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public'
AS $$
BEGIN
  -- Create profile (role will be synced by trg_sync_role_to_profile)
  INSERT INTO public.profiles (id, user_id, email, full_name)
  VALUES (
    NEW.id,
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', '')
  )
  ON CONFLICT (id) DO UPDATE SET
    user_id = EXCLUDED.user_id,
    email = EXCLUDED.email,
    full_name = COALESCE(EXCLUDED.full_name, public.profiles.full_name);
  
  -- Create default role (triggers sync to profiles.role)
  INSERT INTO public.user_roles (user_id, role)
  VALUES (NEW.id, 'vendedor');
  
  RETURN NEW;
END;
$$;

