-- >>> BEGIN 20260416184056_e28ea309-c50d-46b1-85e5-9e283352d97d.sql >>>
-- IP access control table (manual allowlist/blocklist)
CREATE TABLE IF NOT EXISTS public.ip_access_control (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  ip_address TEXT NOT NULL UNIQUE,
  list_type TEXT NOT NULL,
  reason TEXT,
  expires_at TIMESTAMPTZ,
  created_by UUID NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.ip_access_control ENABLE ROW LEVEL SECURITY;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'ip_access_control' AND policyname = 'Admins can manage ip_access_control') THEN
    CREATE POLICY "Admins can manage ip_access_control"
      ON public.ip_access_control
      FOR ALL
      TO authenticated
      USING (has_role(auth.uid(), 'admin'::app_role))
      WITH CHECK (has_role(auth.uid(), 'admin'::app_role));
  END IF;
END $$;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'ip_access_control' AND policyname = 'Service role full access ip_access_control') THEN
    CREATE POLICY "Service role full access ip_access_control"
      ON public.ip_access_control
      FOR ALL
      TO service_role
      USING (true)
      WITH CHECK (true);
  END IF;
END $$;

-- Validate list_type
CREATE OR REPLACE FUNCTION public.validate_ip_access_control()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.list_type NOT IN ('allow', 'block') THEN
    RAISE EXCEPTION 'Invalid list_type: must be allow or block';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_validate_ip_access_control ON public.ip_access_control;
CREATE TRIGGER trg_validate_ip_access_control
BEFORE INSERT OR UPDATE ON public.ip_access_control
FOR EACH ROW EXECUTE FUNCTION public.validate_ip_access_control();

DROP TRIGGER IF EXISTS trg_ip_access_control_updated_at ON public.ip_access_control;
CREATE TRIGGER trg_ip_access_control_updated_at
BEFORE UPDATE ON public.ip_access_control
FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

CREATE INDEX IF NOT EXISTS idx_ip_access_control_ip ON public.ip_access_control(ip_address);
CREATE INDEX IF NOT EXISTS idx_ip_access_control_type_expires ON public.ip_access_control(list_type, expires_at);

-- Atomic check function used by edge functions
CREATE OR REPLACE FUNCTION public.check_ip_access(_ip TEXT)
RETURNS TEXT
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _type TEXT;
BEGIN
  SELECT list_type INTO _type
  FROM public.ip_access_control
  WHERE ip_address = _ip
    AND (expires_at IS NULL OR expires_at > now())
  LIMIT 1;
  
  RETURN _type; -- returns 'allow', 'block', or NULL
END;
$$;
-- <<< END 20260416184056_e28ea309-c50d-46b1-85e5-9e283352d97d.sql <<<

-- >>> BEGIN 20260416190742_b0ea9bfc-96ba-4eda-9dd0-22ef4fb7d1f8.sql >>>
-- Seed function for E2E discount approval tests
-- Creates two fixed test users (seller-test, admin-test) and cleans up test data

CREATE OR REPLACE FUNCTION public.seed_discount_test_users()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _seller_id uuid;
  _admin_id uuid;
BEGIN
  -- Find existing test users by email in profiles
  SELECT user_id INTO _seller_id FROM public.profiles WHERE email = 'seller-test@discount-approval.test' LIMIT 1;
  SELECT user_id INTO _admin_id FROM public.profiles WHERE email = 'admin-test@discount-approval.test' LIMIT 1;

  -- If users don't exist, return error (auth.users insertion requires Supabase Admin API, not SQL)
  IF _seller_id IS NULL OR _admin_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Test users not found. Create them via Supabase Admin API first.',
      'seller_exists', _seller_id IS NOT NULL,
      'admin_exists', _admin_id IS NOT NULL
    );
  END IF;

  -- Ensure roles
  INSERT INTO public.user_roles (user_id, role)
  VALUES (_seller_id, 'vendedor')
  ON CONFLICT (user_id, role) DO NOTHING;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (_admin_id, 'admin')
  ON CONFLICT (user_id, role) DO NOTHING;

  -- Sync role on profiles
  UPDATE public.profiles SET role = 'vendedor' WHERE user_id = _seller_id;
  UPDATE public.profiles SET role = 'admin' WHERE user_id = _admin_id;

  RETURN jsonb_build_object(
    'ok', true,
    'seller_id', _seller_id,
    'admin_id', _admin_id
  );
END;
$$;

-- Cleanup function for test data only (orphan-safe, scoped to test users)
CREATE OR REPLACE FUNCTION public.cleanup_discount_test_data()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _seller_id uuid;
  _admin_id uuid;
  _quotes_deleted int := 0;
  _requests_deleted int := 0;
  _notifs_deleted int := 0;
BEGIN
  SELECT user_id INTO _seller_id FROM public.profiles WHERE email = 'seller-test@discount-approval.test' LIMIT 1;
  SELECT user_id INTO _admin_id FROM public.profiles WHERE email = 'admin-test@discount-approval.test' LIMIT 1;

  IF _seller_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'note', 'no test seller found, nothing to clean');
  END IF;

  -- Delete approval requests for seller-test quotes
  WITH deleted AS (
    DELETE FROM public.discount_approval_requests
    WHERE seller_id = _seller_id
    RETURNING 1
  ) SELECT count(*) INTO _requests_deleted FROM deleted;

  -- Delete quotes from test seller
  WITH deleted AS (
    DELETE FROM public.quotes
    WHERE seller_id = _seller_id
    RETURNING 1
  ) SELECT count(*) INTO _quotes_deleted FROM deleted;

  -- Delete test notifications
  WITH deleted AS (
    DELETE FROM public.workspace_notifications
    WHERE user_id IN (_seller_id, _admin_id)
      AND category IN ('discount', 'quotes')
    RETURNING 1
  ) SELECT count(*) INTO _notifs_deleted FROM deleted;

  RETURN jsonb_build_object(
    'ok', true,
    'requests_deleted', _requests_deleted,
    'quotes_deleted', _quotes_deleted,
    'notifications_deleted', _notifs_deleted
  );
END;
$$;

