-- >>> BEGIN 20260425212616_93c0f5da-1e8e-4eaf-a3b4-19e01441c115.sql >>>
-- =========================================================
-- Hardening: validate_mcp_key re-checa is_dev() do emissor para chaves full
-- Defesa em profundidade — se o criador perdeu o papel dev, a chave é
-- revogada automaticamente em runtime e a chamada é negada.
-- =========================================================
CREATE OR REPLACE FUNCTION public.validate_mcp_key(_key_plain text)
RETURNS TABLE(key_id uuid, scopes text[])
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  _hash text;
  _row record;
  _is_full boolean;
  _grantor_is_dev boolean;
BEGIN
  IF _key_plain IS NULL OR length(_key_plain) < 16 THEN
    RETURN;
  END IF;

  _hash := encode(extensions.digest(_key_plain, 'sha256'), 'hex');

  SELECT id, mcp_api_keys.scopes, expires_at, revoked_at, created_by
  INTO _row
  FROM public.mcp_api_keys
  WHERE key_hash = _hash
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF _row.revoked_at IS NOT NULL THEN
    RETURN;
  END IF;

  IF _row.expires_at IS NOT NULL AND _row.expires_at < now() THEN
    RETURN;
  END IF;

  -- Re-checagem crítica para chaves FULL: o emissor ainda precisa ser dev
  _is_full := _row.scopes @> ARRAY['*']::text[];
  IF _is_full THEN
    IF _row.created_by IS NULL THEN
      _grantor_is_dev := false;
    ELSE
      _grantor_is_dev := public.is_dev(_row.created_by);
    END IF;

    IF NOT _grantor_is_dev THEN
      -- Auto-revoga e audita
      UPDATE public.mcp_api_keys
        SET revoked_at = now()
        WHERE id = _row.id AND revoked_at IS NULL;

      INSERT INTO public.admin_audit_log (
        user_id, action, resource_type, resource_id,
        status, source, details
      ) VALUES (
        _row.created_by,
        'mcp_key.auto_revoked',
        'mcp_api_key',
        _row.id,
        'denied',
        'validate_mcp_key',
        jsonb_build_object(
          'reason', 'grantor_lost_dev',
          'is_full_access', true,
          'auto_revoked_at', now()
        )
      );
      RETURN;
    END IF;
  END IF;

  UPDATE public.mcp_api_keys SET last_used_at = now() WHERE id = _row.id;

  RETURN QUERY SELECT _row.id, _row.scopes;
END;
$$;

COMMENT ON FUNCTION public.validate_mcp_key(text) IS
'Valida chave MCP em runtime. Para chaves com escopo *, re-checa se o emissor (created_by) ainda é dev — caso contrário a chave é auto-revogada e a chamada negada.';
-- <<< END 20260425212616_93c0f5da-1e8e-4eaf-a3b4-19e01441c115.sql <<<

-- >>> BEGIN 20260425212807_54b0bb33-1b1f-47d7-a5d3-4409ca43bf80.sql >>>
-- =========================================================
-- Auditoria padronizada de concessões de FULL scope
-- =========================================================

-- 1) Helper RPC: chamada pelas edges após emitir/rotacionar/escalar uma chave full.
--    Escreve um evento "full_scope_granted" em step_up_audit_log com correlação
--    completa (challenge → token → key) + quais verificações foram aplicadas.
CREATE OR REPLACE FUNCTION public.log_full_scope_grant(
  _operation TEXT,                  -- 'issue' | 'rotate' | 'escalate'
  _key_id UUID,
  _key_prefix TEXT,
  _challenge_id UUID DEFAULT NULL,
  _token_id UUID DEFAULT NULL,
  _justification TEXT DEFAULT NULL,
  _confirmation_phrase_ok BOOLEAN DEFAULT NULL,
  _expires_at TIMESTAMPTZ DEFAULT NULL,
  _ip INET DEFAULT NULL,
  _user_agent TEXT DEFAULT NULL,
  _request_id TEXT DEFAULT NULL,
  _extra JSONB DEFAULT '{}'::jsonb
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _uid UUID := auth.uid();
  _action public.step_up_action;
  _id UUID;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF;

  -- Mapeia operação → step_up_action
  _action := CASE _operation
    WHEN 'escalate' THEN 'mcp_full_escalate'::public.step_up_action
    ELSE 'mcp_full_issue'::public.step_up_action
  END;

  INSERT INTO public.step_up_audit_log (
    user_id, action, target_ref, event_type,
    challenge_id, token_id, ip_address, user_agent, metadata
  ) VALUES (
    _uid, _action, _key_id::text, 'full_scope_granted',
    _challenge_id, _token_id, _ip, _user_agent,
    jsonb_build_object(
      'operation',          _operation,
      'key_id',             _key_id,
      'key_prefix',         _key_prefix,
      'expires_at',         _expires_at,
      'justification',      _justification,
      'verifications', jsonb_build_object(
        'is_dev_recheck',         true,    -- garantido pela edge antes de chamar
        'step_up_token_consumed', _token_id IS NOT NULL,
        'can_grant_mcp_full',     true,    -- garantido pela edge antes de chamar
        'confirmation_phrase_ok', COALESCE(_confirmation_phrase_ok, true),
        'has_justification',      _justification IS NOT NULL AND length(_justification) > 0
      ),
      'request_id',         _request_id,
      'granted_at',         now(),
      'extra',              _extra
    )
  )
  RETURNING id INTO _id;

  RETURN _id;
END;
$$;

COMMENT ON FUNCTION public.log_full_scope_grant IS
'Registra concessão de FULL scope (issue/rotate/escalate) em step_up_audit_log com correlação completa (challenge, token, key) e checklist de verificações server-side aplicadas.';

REVOKE ALL ON FUNCTION public.log_full_scope_grant(
  TEXT, UUID, TEXT, UUID, UUID, TEXT, BOOLEAN, TIMESTAMPTZ, INET, TEXT, TEXT, JSONB
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.log_full_scope_grant(
  TEXT, UUID, TEXT, UUID, UUID, TEXT, BOOLEAN, TIMESTAMPTZ, INET, TEXT, TEXT, JSONB
) TO authenticated;

-- 2) View consolidada para o time de segurança
CREATE OR REPLACE VIEW public.v_full_scope_grants AS
SELECT
  sual.id                                              AS audit_id,
  sual.created_at                                      AS granted_at,
  sual.user_id                                         AS granted_to_user_id,
  p.full_name                                          AS granted_to_name,
  u.email                                              AS granted_to_email,
  sual.action                                          AS step_up_action,
  (sual.metadata->>'operation')                        AS operation,
  (sual.metadata->>'key_id')::uuid                     AS key_id,
  (sual.metadata->>'key_prefix')                       AS key_prefix,
  (sual.metadata->>'expires_at')::timestamptz          AS key_expires_at,
  (sual.metadata->>'justification')                    AS justification,
  sual.challenge_id,
  sual.token_id,
  sual.ip_address,
  sual.user_agent,
  (sual.metadata->>'request_id')                       AS request_id,
  (sual.metadata->'verifications')                     AS verifications_applied,
  (sual.metadata->'extra')                             AS extra
FROM public.step_up_audit_log sual
LEFT JOIN public.profiles p ON p.id = sual.user_id
LEFT JOIN auth.users u      ON u.id = sual.user_id
WHERE sual.event_type = 'full_scope_granted';

COMMENT ON VIEW public.v_full_scope_grants IS
'Histórico completo de concessões de FULL scope (chaves MCP com escopo *). Restringida via RLS herdada de step_up_audit_log: apenas dev ou o próprio usuário.';

-- security_invoker faz a view respeitar as policies RLS de step_up_audit_log
ALTER VIEW public.v_full_scope_grants SET (security_invoker = on);
-- <<< END 20260425212807_54b0bb33-1b1f-47d7-a5d3-4409ca43bf80.sql <<<

-- >>> BEGIN 20260425213721_47f572b3-7d65-413d-a0b4-9d9d88db0740.sql >>>
-- Auditoria automática a nível de DB para mcp_api_keys
-- Rede de segurança: cobre QUALQUER mutação (mesmo via service_role direto, fora das edge functions),
-- complementando a auditoria já feita por mcp-keys-issue / rotate / update / revoke.
-- A coluna `source` distingue 'db_trigger:mcp_api_keys' das origens das edges (mcp-keys-*).

CREATE OR REPLACE FUNCTION public.audit_mcp_api_keys_changes()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_action       text;
  v_user_id      uuid;
  v_resource_id  text;
  v_details      jsonb;
  v_old_scopes   text[];
  v_new_scopes   text[];
  v_old_revoked  timestamptz;
  v_new_revoked  timestamptz;
  v_old_expires  timestamptz;
  v_new_expires  timestamptz;
  v_old_name     text;
  v_new_name     text;
  v_changed      jsonb := '{}'::jsonb;
BEGIN
  -- Resolve identidade: created_by da linha, fallback para auth.uid(), fallback para zero-uuid (system)
  IF TG_OP = 'DELETE' THEN
    v_user_id    := COALESCE(OLD.created_by, auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
    v_resource_id := OLD.id::text;
    v_action     := 'mcp_key.db_deleted';
    v_details    := jsonb_build_object(
      'name',       OLD.name,
      'key_prefix', OLD.key_prefix,
      'scopes',     to_jsonb(OLD.scopes),
      'was_revoked', (OLD.revoked_at IS NOT NULL),
      'created_by', OLD.created_by
    );
  ELSIF TG_OP = 'INSERT' THEN
    v_user_id    := COALESCE(NEW.created_by, auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
    v_resource_id := NEW.id::text;
    v_action     := 'mcp_key.db_inserted';
    v_details    := jsonb_build_object(
      'name',         NEW.name,
      'key_prefix',   NEW.key_prefix,
      'scopes',       to_jsonb(NEW.scopes),
      'is_full',      (NEW.scopes @> ARRAY['*']::text[]),
      'expires_at',   NEW.expires_at,
      'rotated_from', NEW.rotated_from,
      'created_by',   NEW.created_by
    );
  ELSE -- UPDATE
    v_user_id    := COALESCE(auth.uid(), NEW.created_by, '00000000-0000-0000-0000-000000000000'::uuid);
    v_resource_id := NEW.id::text;

    v_old_scopes  := OLD.scopes;
    v_new_scopes  := NEW.scopes;
    v_old_revoked := OLD.revoked_at;
    v_new_revoked := NEW.revoked_at;
    v_old_expires := OLD.expires_at;
    v_new_expires := NEW.expires_at;
    v_old_name    := OLD.name;
    v_new_name    := NEW.name;

    -- Detecta o que mudou para um diff conciso
    IF v_old_name IS DISTINCT FROM v_new_name THEN
      v_changed := v_changed || jsonb_build_object('name', jsonb_build_object('old', v_old_name, 'new', v_new_name));
    END IF;
    IF v_old_scopes IS DISTINCT FROM v_new_scopes THEN
      v_changed := v_changed || jsonb_build_object('scopes', jsonb_build_object('old', to_jsonb(v_old_scopes), 'new', to_jsonb(v_new_scopes)));
    END IF;
    IF v_old_expires IS DISTINCT FROM v_new_expires THEN
      v_changed := v_changed || jsonb_build_object('expires_at', jsonb_build_object('old', v_old_expires, 'new', v_new_expires));
    END IF;
    IF v_old_revoked IS DISTINCT FROM v_new_revoked THEN
      v_changed := v_changed || jsonb_build_object('revoked_at', jsonb_build_object('old', v_old_revoked, 'new', v_new_revoked));
    END IF;

    -- Sem mudanças relevantes (ex.: somente touch em colunas auditadas externamente como last_used_at)
    -- Não auditamos: barulho desnecessário e last_used_at é registrado pelo mcp-server.
    IF v_changed = '{}'::jsonb THEN
      RETURN NEW;
    END IF;

    -- Sub-ação semântica para facilitar busca
    IF v_old_revoked IS NULL AND v_new_revoked IS NOT NULL THEN
      v_action := 'mcp_key.db_revoked';
    ELSIF v_old_scopes IS DISTINCT FROM v_new_scopes
          AND (v_new_scopes @> ARRAY['*']::text[])
          AND NOT (COALESCE(v_old_scopes, ARRAY[]::text[]) @> ARRAY['*']::text[]) THEN
      v_action := 'mcp_key.db_scope_escalated';
    ELSE
      v_action := 'mcp_key.db_updated';
    END IF;

    v_details := jsonb_build_object(
      'name',       NEW.name,
      'key_prefix', NEW.key_prefix,
      'changed',    v_changed,
      'is_full_now', (NEW.scopes @> ARRAY['*']::text[]),
      'created_by', NEW.created_by
    );
  END IF;

  -- Insere com source identificando trigger (edge functions usam 'mcp-keys-*')
  INSERT INTO public.admin_audit_log (
    user_id, action, resource_type, resource_id,
    details, source, status, created_at
  ) VALUES (
    v_user_id,
    v_action,
    'mcp_api_key',
    v_resource_id,
    v_details,
    'db_trigger:mcp_api_keys',
    'success',
    now()
  );

  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  -- Nunca bloquear a operação principal por falha de auditoria
  RAISE WARNING 'audit_mcp_api_keys_changes failed: %', SQLERRM;
  RETURN COALESCE(NEW, OLD);
END;
$$;

DROP TRIGGER IF EXISTS trg_audit_mcp_api_keys ON public.mcp_api_keys;

DROP TRIGGER IF EXISTS trg_audit_mcp_api_keys ON public.mcp_api_keys;
CREATE TRIGGER trg_audit_mcp_api_keys
AFTER INSERT OR UPDATE OR DELETE ON public.mcp_api_keys
FOR EACH ROW
EXECUTE FUNCTION public.audit_mcp_api_keys_changes();

COMMENT ON FUNCTION public.audit_mcp_api_keys_changes IS
'Rede de segurança: registra automaticamente toda mutação em mcp_api_keys no admin_audit_log com source=db_trigger:mcp_api_keys, complementando a auditoria das edge functions mcp-keys-*.';
-- <<< END 20260425213721_47f572b3-7d65-413d-a0b4-9d9d88db0740.sql <<<

