-- >>> BEGIN 20260512163629_onda3_storage_recibos.sql >>>
-- ============================================================
--  Storage bucket pra recibos de entrega
--  Padrão: cotacoes/{cotacao_id}/recibo.jpg
-- ============================================================
--
-- Nota de sincronização (2026-05-12, T19 redeploy Fase 1):
-- Migration aplicada direto no banco prod via MCP e órfã no repo até agora.
--
-- ⚠️ ATENÇÃO: este bucket é PÚBLICO (`public = true`). Isso diverge da
-- política oficial PUBLIC_BUCKETS (docs/storage/PUBLIC_BUCKETS.md) — todo
-- bucket deveria ser privado por default. Revisar com sponsor se o uso
-- (link público de recibo) ainda justifica.
-- ============================================================

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM storage.buckets WHERE id = 'recibos-entrega') THEN
    INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
    VALUES (
      'recibos-entrega',
      'recibos-entrega',
      true,                           -- público (qualquer um com link vê)
      10 * 1024 * 1024,               -- 10 MB max por arquivo
      ARRAY['image/jpeg','image/png','image/webp','application/pdf']
    );
  ELSE
    UPDATE storage.buckets
    SET
      public = true,
      file_size_limit = 10 * 1024 * 1024,
      allowed_mime_types = ARRAY['image/jpeg','image/png','image/webp','application/pdf']
    WHERE id = 'recibos-entrega';
  END IF;
END $$;

-- Policies de Storage
DROP POLICY IF EXISTS "recibos_public_read" ON storage.objects;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'recibos_public_read') THEN
    CREATE POLICY "recibos_public_read"
      ON storage.objects FOR SELECT
      TO public
      USING (bucket_id = 'recibos-entrega');
  END IF;
END $$;

DROP POLICY IF EXISTS "recibos_authenticated_write" ON storage.objects;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'recibos_authenticated_write') THEN
    CREATE POLICY "recibos_authenticated_write"
      ON storage.objects FOR INSERT
      TO authenticated, service_role
      WITH CHECK (bucket_id = 'recibos-entrega');
  END IF;
END $$;

DROP POLICY IF EXISTS "recibos_authenticated_update" ON storage.objects;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND tablename = 'objects' AND policyname = 'recibos_authenticated_update') THEN
    CREATE POLICY "recibos_authenticated_update"
      ON storage.objects FOR UPDATE
      TO authenticated, service_role
      USING (bucket_id = 'recibos-entrega');
  END IF;
END $$;

-- <<< END 20260512163629_onda3_storage_recibos.sql <<<

-- >>> BEGIN 20260512164738_onda3_simplifica_nf_e_retry.sql >>>
-- ============================================================
--  Ajustes Onda 3.1 pós-decisões de design:
--  1) Chave NF agora opcional (só número obrigatório no fluxo)
--  2) Campos pra rastrear tentativas do cron (retry indefinido)
-- ============================================================
--
-- Nota de sincronização (2026-05-12, T19 redeploy Fase 1):
-- Migration aplicada direto no banco prod via MCP e órfã no repo até agora.
-- ============================================================

-- 1) Remove o CHECK rígido de chave_nf (continua aceitando 44 dígitos OU vazio)
ALTER TABLE public.cotacoes
  DROP CONSTRAINT IF EXISTS cotacoes_chave_nf_check;

-- Mantém o check só pra garantir formato quando preenchida (44 dígitos)
ALTER TABLE public.cotacoes
  ADD CONSTRAINT cotacoes_chave_nf_check
  CHECK (chave_nf IS NULL OR chave_nf = '' OR chave_nf ~ '^\d{44}$');

-- 2) Campos pra observabilidade do cron
ALTER TABLE public.cotacoes
  ADD COLUMN IF NOT EXISTS tracking_ultima_tentativa  timestamptz,
  ADD COLUMN IF NOT EXISTS tracking_ultimo_sucesso    timestamptz,
  ADD COLUMN IF NOT EXISTS tracking_falhas_seguidas   int default 0,
  ADD COLUMN IF NOT EXISTS tracking_ultimo_erro       text;

-- Index pra cron varrer eficientemente
CREATE INDEX IF NOT EXISTS idx_cotacoes_cron_scan
  ON public.cotacoes(tracking_ultima_tentativa NULLS FIRST)
  WHERE tracking_ativo = true
    AND status IN ('aguardando_coleta','em_transito','em_risco','atrasado');

COMMENT ON COLUMN public.cotacoes.tracking_falhas_seguidas IS
  'Contador de falhas consecutivas. Útil pra debug, mas cron tenta sempre.';

-- <<< END 20260512164738_onda3_simplifica_nf_e_retry.sql <<<

-- >>> BEGIN 20260512201500_t15_fix_system_health_dashboard_exposure.sql >>>
-- ============================================================
--  T15 — Fix `auth_users_exposed` advisor em v_system_health_dashboard
--  (redeploy 2026-05 Fase 1 - bloqueador B3)
-- ============================================================
--
-- Nota de sincronização (2026-05-12, T19 redeploy Fase 1):
-- Esta migration foi aplicada direto no banco prod via MCP `apply_migration`
-- mas a entrada em `supabase_migrations.schema_migrations` ficou com SQL
-- válido (não summary), então este arquivo é cópia fiel.
--
-- Contexto: o advisor `auth_users_exposed` apontava que a view
-- `public.v_system_health_dashboard` expunha colunas vindas de `auth.users`
-- para qualquer cliente PostgREST (anon/authenticated). Solução:
--  1) `security_invoker = true` — view roda com permissões de quem chama,
--     não do dono, então RLS de `auth.users` se aplica.
--  2) REVOKE de leitura para anon/authenticated — só service_role consulta.
-- ============================================================

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_views WHERE schemaname = 'public' AND viewname = 'v_system_health_dashboard'
  ) THEN
    ALTER VIEW public.v_system_health_dashboard SET (security_invoker = true);
    REVOKE ALL ON public.v_system_health_dashboard FROM anon;
    REVOKE ALL ON public.v_system_health_dashboard FROM authenticated;
  END IF;
END $$;

-- <<< END 20260512201500_t15_fix_system_health_dashboard_exposure.sql <<<

-- >>> BEGIN 20260512201600_t16_move_backup_tables_to_schema_backup.sql >>>
-- ============================================================
--  T16 — Move 17 tabelas `_backup_*` de `public` para schema `backup`
--  (redeploy 2026-05 Fase 1 - bloqueador B4)
-- ============================================================
--
-- Nota de sincronização (2026-05-12, T19 redeploy Fase 1):
-- A migration aplicada via MCP `apply_migration` gravou só um SUMMARY em
-- `supabase_migrations.schema_migrations` (linha `ALTER TABLE public._backup_*
-- SET SCHEMA backup; (17 tabelas)` que é SQL inválido). Este arquivo é a
-- reconstrução fiel a partir da lista real de tabelas que hoje residem em
-- `schema backup` (validado por `pg_tables WHERE schemaname='backup'`).
--
-- Objetivo: zerar o advisor `rls_disabled_in_public` para tabelas `_backup_*`
-- que ficaram fora do PostgREST/REST API ao mudar de schema. RLS deny-all
-- não é necessário pq o schema `backup` em si não está exposto.
-- ============================================================

CREATE SCHEMA IF NOT EXISTS backup;

-- Move 17 tabelas (idempotente — `IF EXISTS` evita falha em reruns)
DO $$
DECLARE
  v_tbl text;
  v_tables text[] := ARRAY[
    '_backup_20260425_tabela_preco_gravacao_oficial_faixa',
    '_backup_20260425_tecnicas_gravacao',
    '_backup_collection_products_b2b_20260511',
    '_backup_collections_b2b_20260511',
    '_backup_collections_policies_b2b_20260511',
    '_backup_functions_d12',
    '_backup_guardachuva_setup_20260425',
    '_backup_plaquinha_sugestao_20260425',
    '_backup_silk_ajustes_20260426',
    '_backup_storage_buckets_20260511_d11',
    '_backup_storage_policies_20260511_d11',
    '_backup_system_settings_legacy_20260511',
    '_backup_unif_funcoes_20260425',
    '_backup_unif_funcoes_f3_20260425',
    '_backup_unif_limpeza_fatmin_20260425',
    '_backup_unif_setup_fatmin_20260425',
    '_backup_unif_setup_fatmin_faixa_20260425'
  ];
BEGIN
  FOREACH v_tbl IN ARRAY v_tables LOOP
    IF EXISTS (
      SELECT 1 FROM pg_tables
      WHERE schemaname = 'public' AND tablename = v_tbl
    ) THEN
      EXECUTE format('ALTER TABLE public.%I SET SCHEMA backup;', v_tbl);
      RAISE NOTICE 'Moved public.% → backup.%', v_tbl, v_tbl;
    ELSE
      RAISE NOTICE 'Skipped (not in public): %', v_tbl;
    END IF;
  END LOOP;
END $$;

-- Defesa em profundidade: schema `backup` não exposto via PostgREST.
REVOKE ALL ON SCHEMA backup FROM anon, authenticated, PUBLIC;
GRANT USAGE ON SCHEMA backup TO postgres, service_role;

-- <<< END 20260512201600_t16_move_backup_tables_to_schema_backup.sql <<<

