-- >>> BEGIN 20260512210000_t17_fix_function_search_path.sql >>>
-- ============================================================================
-- T17: Garantir search_path seguro em funções públicas (postgres-owned)
-- ============================================================================
-- Contexto (Tarefa #17 do redeploy Promo_Gifts 2026-05-12):
--   A Supabase Security Advisor alerta quando funções não têm search_path
--   explícito — vetor de SQL injection via search_path hijacking.
--
-- Diagnóstico (2026-05-12 via pg_proc query):
--   - 768 funções postgres-owned em public: TODAS já têm search_path definido.
--   - 4 funções supabase_admin-owned (unaccent): NÃO podem ser alteradas
--     — são gerenciadas pela plataforma Supabase (pg_catalog-owned extension).
--
-- Esta migration é IDEMPOTENTE e serve como guardrail futuro:
--   Re-execução em ambiente onde funções ainda não têm search_path aplica
--   a correção. Em produção (2026-05-12), o DO block completa sem ALTER.
--
-- SEGURANÇA: NÃO altera funções de supabase_admin (platform-managed).
--   Alterá-las causaria erro de permissão ou comportamento inesperado.
-- ============================================================================

DO $$
DECLARE
  r          RECORD;
  v_count    INT := 0;
  v_skipped  INT := 0;
BEGIN
  FOR r IN
    SELECT
      p.oid,
      p.proname,
      n.nspname AS schema_name,
      pg_get_userbyid(p.proowner) AS owner
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND pg_get_userbyid(p.proowner) = 'postgres'
      AND (
        p.proconfig IS NULL
        OR NOT EXISTS (
          SELECT 1 FROM unnest(p.proconfig) AS cfg
          WHERE cfg LIKE 'search_path=%'
        )
      )
  LOOP
    BEGIN
      EXECUTE format(
        'ALTER FUNCTION %s SET search_path = public',
        r.oid::regprocedure
      );
      v_count := v_count + 1;
      RAISE NOTICE 'T17: search_path definido em %.% (owner=postgres)',
        r.schema_name, r.proname;
    EXCEPTION WHEN OTHERS THEN
      v_skipped := v_skipped + 1;
      RAISE WARNING 'T17: não foi possível alterar %.% — %',
        r.schema_name, r.proname, SQLERRM;
    END;
  END LOOP;

  IF v_count = 0 AND v_skipped = 0 THEN
    RAISE NOTICE 'T17: todas as funções postgres-owned já têm search_path definido. Nada a fazer.';
  ELSE
    RAISE NOTICE 'T17: concluído — % função(ões) corrigida(s), % ignorada(s).', v_count, v_skipped;
  END IF;
END $$;

-- <<< END 20260512210000_t17_fix_function_search_path.sql <<<

-- >>> BEGIN 20260512210001_enable_pg_stat_statements.sql >>>
-- Enable pg_stat_statements for slow-query monitoring (T24 Observability)
-- pg_stat_statements tracks execution statistics for all SQL statements.
-- Required for the observability dashboard slow-query panel.
--
-- Note: This extension must be enabled by a superuser. In Supabase, it is
-- available via the dashboard → Database → Extensions → pg_stat_statements.
-- This migration acts as documentation and idempotent activation.
CREATE EXTENSION IF NOT EXISTS pg_stat_statements;

-- View: slow queries (p95 > 100ms) — consumida pelo AppHealthDashboard
-- Exposta apenas para o role `service_role` (read-only, admin-only).
CREATE OR REPLACE VIEW public.slow_queries_view AS
SELECT
  pg_stat_statements.userid::regrole::text AS "user",
  pg_stat_statements.dbid,
  pg_stat_statements.queryid,
  left(pg_stat_statements.query, 200) AS query_snippet,
  pg_stat_statements.calls,
  round((pg_stat_statements.total_exec_time / pg_stat_statements.calls)::numeric, 2) AS avg_ms,
  round(pg_stat_statements.min_exec_time::numeric, 2) AS min_ms,
  round(pg_stat_statements.max_exec_time::numeric, 2) AS max_ms,
  round(pg_stat_statements.stddev_exec_time::numeric, 2) AS stddev_ms
FROM pg_stat_statements
WHERE pg_stat_statements.calls > 5
  AND (pg_stat_statements.total_exec_time / pg_stat_statements.calls) > 100
ORDER BY avg_ms DESC
LIMIT 50;

-- RLS: view is accessible only via service_role (no anon/authenticated access)
REVOKE ALL ON public.slow_queries_view FROM anon, authenticated;
GRANT SELECT ON public.slow_queries_view TO service_role;

COMMENT ON VIEW public.slow_queries_view IS
  'Queries lentas (avg > 100ms, calls > 5) via pg_stat_statements. Acessível apenas por service_role. Consumida pelo painel de observabilidade.';

-- <<< END 20260512210001_enable_pg_stat_statements.sql <<<

