        v_category_slug := 'bowl_vidro';
        v_category_id := 'd9127ba5-a035-48d9-a30a-8dd712f277aa'::uuid;
    ELSIF v_name ~ 'PLASTIC|ACRILIC|ACRÍLICO|PP|PS|PET' THEN
        v_material := 'PLASTICO';
