  BEFORE INSERT OR UPDATE OF subtotal, discount_percent, negotiation_markup_percent, status
  ON public.quotes
  FOR EACH ROW
  EXECUTE FUNCTION public.validate_quote_real_discount();

CREATE TRIGGER trg_quotes_calc_real_values
  BEFORE INSERT OR UPDATE OF subtotal, discount_amount, negotiation_markup_percent
  ON public.quotes
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_quotes_calc_real_values();

DO $g$ BEGIN
  CREATE TRIGGER trg_kit_print_area_normalizar_eixos
    BEFORE INSERT OR UPDATE OF max_width, max_height
    ON public.kit_component_print_areas
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_kit_print_area_normalizar_eixos();
EXCEPTION WHEN undefined_table THEN NULL; END $g$;

-- 5. RECREATE view (definição idêntica à original — só rebuild para usar novo tipo)
-- Guardada: referencia tabela_preco_gravacao_oficial(_faixa) (out-of-band).
DO $g$ BEGIN
  CREATE OR REPLACE VIEW public.v_audit_paradoxos_gravacao AS
  WITH faixas_ord AS (
    SELECT t.id,
      t.codigo_tabela,
      t.nome,
      t.grupo_tecnica,
      t.custo_setup,
      t.markup_percent,
      f.quantidade_minima,
      f.quantidade_maxima,
      f.preco_unitario,
      lag(f.preco_unitario) OVER (
        PARTITION BY t.id,
          (COALESCE(f.largura_min, 0::numeric)),
          (COALESCE(f.largura_max, 0::numeric)),
          (COALESCE(f.altura_min, 0::numeric)),
          (COALESCE(f.altura_max, 0::numeric))
        ORDER BY f.quantidade_minima
      ) AS preco_anterior,
      lag(f.quantidade_maxima) OVER (
        PARTITION BY t.id,
          (COALESCE(f.largura_min, 0::numeric)),
          (COALESCE(f.largura_max, 0::numeric)),
          (COALESCE(f.altura_min, 0::numeric)),
          (COALESCE(f.altura_max, 0::numeric))
        ORDER BY f.quantidade_minima
      ) AS qty_max_anterior
    FROM public.tabela_preco_gravacao_oficial t
    JOIN public.tabela_preco_gravacao_oficial_faixa f
      ON f.tabela_preco_gravacao_id = t.id
    WHERE t.ativo = true
  )
  SELECT
    codigo_tabela,
    nome,
    grupo_tecnica,
    qty_max_anterior AS qty_pico_ant,
    preco_anterior,
    round(GREATEST(qty_max_anterior::numeric * preco_anterior, custo_setup) * (1::numeric + markup_percent / 100::numeric), 2) AS venda_no_pico,
    quantidade_minima AS qty_inicio,
    preco_unitario AS preco_atual,
    round(GREATEST(quantidade_minima::numeric * preco_unitario, custo_setup) * (1::numeric + markup_percent / 100::numeric), 2) AS venda_inicio,
    round(GREATEST(quantidade_minima::numeric * preco_unitario, custo_setup) - GREATEST(qty_max_anterior::numeric * preco_anterior, custo_setup), 2) AS economia_cliente_se_subir_faixa,
    CASE
      WHEN preco_anterior IS NULL THEN 'primeira_faixa'::text
      WHEN qty_max_anterior IS NULL THEN 'sem_pico_anterior'::text
      WHEN GREATEST(quantidade_minima::numeric * preco_unitario, custo_setup) < GREATEST(qty_max_anterior::numeric * preco_anterior, custo_setup) THEN 'PARADOXO_NATURAL'::text
      ELSE 'OK'::text
    END AS status_natural
  FROM faixas_ord
  WHERE preco_anterior IS NOT NULL AND qty_max_anterior IS NOT NULL
  ORDER BY codigo_tabela, quantidade_minima;
EXCEPTION WHEN undefined_table THEN NULL; END $g$;

-- <<< END 20260515030000_onda19_numeric_precision.sql <<<

-- >>> BEGIN 20260515040000_onda19_followup_track_functions_fix_view_security.sql >>>
-- =================================================================
-- Onda 19 follow-up: rastrear funções de trigger + restaurar segurança da view
--
-- Contexto (PR #214 review items não resolvidos):
--
-- P1 (CodeRabbit) — fn_quotes_calc_real_values e fn_kit_print_area_normalizar_eixos
--   existiam apenas como drift de PROD; não estavam em nenhuma migration.
--   Em `supabase db reset` / novo ambiente, os triggers recriados pela Onda 19
--   falhariam com "function does not exist". Este migration registra as
--   definições exatas conforme extraído de PROD em 2026-05-15.
--
-- P1/P2 (Copilot + CodeRabbit) — DROP+RECREATE de v_audit_paradoxos_gravacao
--   na Onda 19 resetou `security_invoker` e grants: anon e authenticated
--   receberam acesso completo (confirmado via pg_class.relacl). A view é
--   classificada como "auditoria interna / service_role apenas" em
--   docs/redeploy/REDEPLOY-FASE2-EXECUTION-LOG.md — hardening revertido.
--
-- Padrão aplicado (idêntico a T15 e t34b):
--   ALTER VIEW ... SET (security_invoker = true)
--   REVOKE ALL ... FROM anon
--   REVOKE ALL ... FROM authenticated
-- =================================================================

BEGIN;

-- ----------------------------------------------------------------
-- 1. fn_quotes_calc_real_values
--    Trigger BEFORE em quotes: calcula real_subtotal e real_discount_percent
--    a partir do subtotal com markup já aplicado (negotiation_markup_percent).
--    Limite de markup: 0-50% (LEAST/GREATEST).
-- ----------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_quotes_calc_real_values()
  RETURNS trigger
  LANGUAGE plpgsql
  SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_markup numeric;
BEGIN
  v_markup := LEAST(50, GREATEST(0, COALESCE(NEW.negotiation_markup_percent, 0)));
  NEW.negotiation_markup_percent := v_markup;

  IF v_markup > 0 THEN
    NEW.real_subtotal := ROUND(NEW.subtotal / (1 + v_markup / 100.0), 2);
  ELSE
    NEW.real_subtotal := NEW.subtotal;
  END IF;

  IF NEW.real_subtotal > 0 THEN
    NEW.real_discount_percent := ROUND(
      ((NEW.real_subtotal - (NEW.subtotal - COALESCE(NEW.discount_amount, 0))) / NEW.real_subtotal) * 100,
      2
    );
  ELSE
    NEW.real_discount_percent := 0;
  END IF;

  RETURN NEW;
END
$function$;

COMMENT ON FUNCTION public.fn_quotes_calc_real_values() IS
  'Onda 19 follow-up: registra em migrations função que existia só como drift. '
  'Calcula real_subtotal e real_discount_percent a partir do subtotal COM markup; '
  'clamp markup 0-50%. Usada pelo trigger trg_quotes_calc_real_values.';

-- ----------------------------------------------------------------
-- 2. fn_kit_print_area_normalizar_eixos
--    Trigger BEFORE em kit_component_print_areas: arredonda max_width/max_height
--    a 2 casas decimais e garante largura >= altura (normalização de eixos).
-- ----------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_kit_print_area_normalizar_eixos()
  RETURNS trigger
  LANGUAGE plpgsql
  SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_temp numeric;
BEGIN
  -- Arredondar a 2 casas decimais (resolução 1mm) - GAP #6
  IF NEW.max_width IS NOT NULL THEN
    NEW.max_width := ROUND(NEW.max_width::numeric, 2);
  END IF;
  IF NEW.max_height IS NOT NULL THEN
    NEW.max_height := ROUND(NEW.max_height::numeric, 2);
  END IF;

  -- Normalizar eixos: largura sempre >= altura - GAP #10
  IF NEW.max_height IS NOT NULL AND NEW.max_width IS NOT NULL
     AND NEW.max_height > NEW.max_width THEN
    v_temp        := NEW.max_width;
    NEW.max_width  := NEW.max_height;
    NEW.max_height := v_temp;
  END IF;

  RETURN NEW;
END
$function$;

COMMENT ON FUNCTION public.fn_kit_print_area_normalizar_eixos() IS
  'Onda 19 follow-up: registra em migrations função que existia só como drift. '
  'Arredonda max_width/max_height a 2 casas e normaliza eixos (largura >= altura). '
  'Usada pelo trigger trg_kit_print_area_normalizar_eixos.';

-- ----------------------------------------------------------------
-- 3. Restaurar hardening de v_audit_paradoxos_gravacao
--    A Onda 19 fez DROP + CREATE OR REPLACE que resetou reloptions e ACL.
--    pg_class.relacl pós-Onda19 confirmou: anon e authenticated com acesso total.
--    View é interna/service_role-only (REDEPLOY-FASE2-EXECUTION-LOG.md).
-- ----------------------------------------------------------------
DO $g$ BEGIN
  IF to_regclass('public.v_audit_paradoxos_gravacao') IS NOT NULL THEN
    ALTER VIEW public.v_audit_paradoxos_gravacao SET (security_invoker = true);

    REVOKE ALL ON public.v_audit_paradoxos_gravacao FROM anon;
    REVOKE ALL ON public.v_audit_paradoxos_gravacao FROM authenticated;
  END IF;
END $g$;

COMMIT;

-- <<< END 20260515040000_onda19_followup_track_functions_fix_view_security.sql <<<

-- >>> BEGIN 20260515040001_fix_profiles_user_id_definitive.sql >>>
-- ============================================================
-- FIX: Garantir user_id em profiles + corrigir RLS policies
-- Resolve schema drift: migrações 20250103* criam profiles sem
-- user_id; este arquivo garante consistência idempotente tanto
-- no preview branch quanto em produção.
-- ============================================================

-- 1. Garantir que user_id existe em profiles
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'profiles' AND column_name = 'user_id'
  ) THEN
    ALTER TABLE public.profiles ADD COLUMN user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE;
    UPDATE public.profiles SET user_id = id WHERE user_id IS NULL;
    BEGIN
      ALTER TABLE public.profiles ADD CONSTRAINT profiles_user_id_key UNIQUE (user_id);
    EXCEPTION WHEN duplicate_table OR unique_violation THEN NULL;
    END;
    ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_id_fkey;
    ALTER TABLE public.profiles ALTER COLUMN id SET DEFAULT gen_random_uuid();
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Fix profiles user_id skipped: %', SQLERRM;
END $$;

-- 2. Corrigir policies usando SQL dinâmico (compatível com ambos os schemas)
DO $$
DECLARE
  v_auth_col text;
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'profiles' AND column_name = 'user_id'
  ) THEN
    v_auth_col := 'user_id';
  ELSE
    v_auth_col := 'id';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='profiles' AND policyname='Users can view their own profile') THEN
    EXECUTE format('CREATE POLICY "Users can view their own profile" ON public.profiles FOR SELECT USING (auth.uid() = %I)', v_auth_col);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='profiles' AND policyname='Users can update their own profile') THEN
    EXECUTE format('CREATE POLICY "Users can update their own profile" ON public.profiles FOR UPDATE USING (auth.uid() = %I)', v_auth_col);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='public' AND tablename='profiles' AND policyname='Users can insert their own profile') THEN
    EXECUTE format('CREATE POLICY "Users can insert their own profile" ON public.profiles FOR INSERT WITH CHECK (auth.uid() = %I)', v_auth_col);
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Fix profiles RLS policies skipped: %', SQLERRM;
END $$;

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

-- <<< END 20260515040001_fix_profiles_user_id_definitive.sql <<<

