-- >>> BEGIN 20260515124035_fix_audit_ownership_orphans_only_uuid_columns.sql >>>

-- Fix: audit_ownership_orphans tentava cast ::uuid em colunas TEXT, quebrava com
-- valores como "system" em enriched_contacts.created_by. Agora só considera
-- colunas com data_type='uuid'. Mais robusto que manter blacklist.
--
-- ORIGEM: applied directly via apply_migration in another Claude session
-- on 2026-05-15. Now committed to git for migration history parity.

CREATE OR REPLACE FUNCTION public.audit_ownership_orphans(_triggered_by text DEFAULT 'manual'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_report_id uuid;
  v_owner_columns text[] := ARRAY['seller_id', 'user_id', 'owner_id', 'created_by'];
  v_table record;
  v_col text;
  v_null_count bigint;
  v_orphan_count bigint;
  v_total_null bigint := 0;
  v_total_orphan bigint := 0;
  v_tables_scanned int := 0;
  v_details jsonb := '[]'::jsonb;
  v_table_entry jsonb;
  v_rls jsonb;
  v_rls_gaps int := 0;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT (has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'dev'::app_role)) THEN
    RAISE EXCEPTION 'audit_ownership_orphans: acesso negado';
  END IF;

  FOR v_table IN
    SELECT c.table_name, c.column_name
    FROM information_schema.columns c
    JOIN information_schema.tables t ON t.table_schema = c.table_schema AND t.table_name = c.table_name
    WHERE c.table_schema = 'public'
      AND c.column_name = ANY(v_owner_columns)
      AND c.data_type = 'uuid'  -- FIX: ignora colunas TEXT como enriched_contacts.created_by ('system')
      AND t.table_type = 'BASE TABLE'
      AND c.table_name NOT IN ('login_attempts','step_up_audit_log','search_analytics','query_telemetry','mcp_access_violations','product_views','quote_history','optimization_queue','kit_templates')
    ORDER BY c.table_name
  LOOP
    v_col := v_table.column_name;
    v_tables_scanned := v_tables_scanned + 1;
    EXECUTE format('SELECT count(*) FROM public.%I WHERE %I IS NULL', v_table.table_name, v_col) INTO v_null_count;
    EXECUTE format('SELECT count(*) FROM public.%I t WHERE t.%I IS NOT NULL AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = t.%I)',
      v_table.table_name, v_col, v_col) INTO v_orphan_count;
    IF v_null_count > 0 OR v_orphan_count > 0 THEN
      v_table_entry := jsonb_build_object('table', v_table.table_name, 'owner_column', v_col,
        'null_owner_count', v_null_count, 'missing_user_count', v_orphan_count);
      v_details := v_details || v_table_entry;
    END IF;
    v_total_null := v_total_null + v_null_count;
    v_total_orphan := v_total_orphan + v_orphan_count;
  END LOOP;

  v_rls := public.audit_rls_coverage();
  SELECT COALESCE(SUM(jsonb_array_length(elem->'missing_ops')),0)::int INTO v_rls_gaps
  FROM jsonb_array_elements(v_rls) elem;

  INSERT INTO public.ownership_audit_reports (
    total_tables_scanned, total_issues_found, null_owner_count, missing_user_count, details,
    triggered_by, duration_ms, rls_coverage, rls_gaps_count
  ) VALUES (
    v_tables_scanned, (v_total_null + v_total_orphan)::int, v_total_null::int, v_total_orphan::int, v_details,
    coalesce(_triggered_by, 'manual'),
    EXTRACT(MILLISECONDS FROM (clock_timestamp() - v_started_at))::int,
    v_rls, v_rls_gaps
  ) RETURNING id INTO v_report_id;

  RETURN v_report_id;
END;
$function$;

-- Comentário documental
COMMENT ON FUNCTION public.audit_ownership_orphans(text) IS
  'Audita propriedade de registros em tabelas com colunas UUID owner. Versão corrigida (15/mai/2026): ignora colunas TEXT como enriched_contacts.created_by que armazenam valores não-UUID como "system".';

-- <<< END 20260515124035_fix_audit_ownership_orphans_only_uuid_columns.sql <<<

-- >>> BEGIN 20260515125758_onda_20a_check_login_rate_limit_rpc.sql >>>
-- =====================================================================
-- Onda 20.A — B-6: Server-side login rate limit (close last blocker)
-- =====================================================================
-- Cria RPC SECURITY DEFINER que pode ser chamada por anon/authenticated
-- ANTES do signInWithPassword. Consulta tabela login_attempts (persistente),
-- não bypassa via aba anônima / sessionStorage.clear() / trocar de browser.
--
-- Política: 5 falhas consecutivas (por email OR ip) em 15 min → bloqueado
-- 5 min após a 5ª falha. Após sucesso, contador "zera" (success conta como
-- delimitador).
--
-- ORIGEM: applied directly via apply_migration in another Claude session
-- on 2026-05-15. Now committed to git for migration history parity.
-- =====================================================================

CREATE OR REPLACE FUNCTION public.check_login_rate_limit(
  _email text,
  _ip text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  _max_failures int := 5;
  _window_minutes int := 15;
  _lockout_minutes int := 5;
  _failed_count int := 0;
  _last_failure timestamptz;
  _last_success timestamptz;
  _lockout_until timestamptz;
BEGIN
  -- Sanitiza input
  IF _email IS NULL OR length(trim(_email)) = 0 THEN
    -- Fail-CLOSED em input inválido (Onda 20)
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'invalid_email',
      'remaining_seconds', 0
    );
  END IF;

  _email := lower(trim(_email));

  -- Último sucesso por este email (delimita janela de falhas)
  SELECT max(created_at) INTO _last_success
  FROM public.login_attempts
  WHERE email = _email AND success = true;

  -- Conta falhas POR EMAIL na janela, ignorando as anteriores ao último sucesso
  SELECT count(*), max(created_at)
    INTO _failed_count, _last_failure
  FROM public.login_attempts
  WHERE email = _email
    AND success = false
    AND created_at > now() - (_window_minutes || ' minutes')::interval
    AND (_last_success IS NULL OR created_at > _last_success);

  -- Se atingiu o limite por EMAIL → lockout 5 min após última falha
  IF _failed_count >= _max_failures THEN
    _lockout_until := _last_failure + (_lockout_minutes || ' minutes')::interval;
    IF _lockout_until > now() THEN
      RETURN jsonb_build_object(
        'allowed', false,
        'reason', 'rate_limited_email',
        'failed_count', _failed_count,
        'remaining_seconds', ceil(extract(epoch FROM (_lockout_until - now())))::int,
        'lockout_until', _lockout_until
      );
    END IF;
  END IF;

  -- Adicional: se _ip fornecido, verifica também por IP (mais agressivo: 20 falhas / 15min)
  IF _ip IS NOT NULL AND length(trim(_ip)) > 0 AND _ip <> 'unknown' AND _ip <> 'client' THEN
    SELECT count(*), max(created_at)
      INTO _failed_count, _last_failure
    FROM public.login_attempts
    WHERE ip_address = _ip
      AND success = false
      AND created_at > now() - (_window_minutes || ' minutes')::interval;

    IF _failed_count >= 20 THEN
      _lockout_until := _last_failure + (_lockout_minutes || ' minutes')::interval;
      IF _lockout_until > now() THEN
        RETURN jsonb_build_object(
          'allowed', false,
          'reason', 'rate_limited_ip',
          'failed_count', _failed_count,
          'remaining_seconds', ceil(extract(epoch FROM (_lockout_until - now())))::int,
          'lockout_until', _lockout_until
        );
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'failed_count', _failed_count,
    'remaining_seconds', 0
  );
EXCEPTION WHEN OTHERS THEN
  -- Fail-CLOSED em erro (padrão das Ondas 6/7/B-7)
  RETURN jsonb_build_object(
    'allowed', false,
    'reason', 'rate_limit_check_error',
    'error', SQLERRM,
    'remaining_seconds', 0
  );
END;
$$;

-- Permite anon (formulário de login) e authenticated chamar
REVOKE ALL ON FUNCTION public.check_login_rate_limit(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.check_login_rate_limit(text, text) TO anon, authenticated;

COMMENT ON FUNCTION public.check_login_rate_limit(text, text) IS
'B-6 close: pre-signInWithPassword rate limit check. SECURITY DEFINER + fail-closed. Consulta login_attempts (persistente, bypass-proof). Onda 20.A.';

