CREATE TABLE IF NOT EXISTS public.frontend_telemetry (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  event_type  text NOT NULL,
  name        text NOT NULL,
  duration_ms numeric,
  metadata    jsonb DEFAULT '{}'::jsonb,
  url         text,
  user_agent  text,
  session_id  text,
