-- >>> BEGIN 20260525193202_sync_user_organizations_to_organization_members_20260525.sql >>>
-- Aplicada via Supabase dashboard em 2026-05-25 19:32 UTC
-- Recuperada do schema_migrations para sincronizar o repo
-- ============================================================
-- MIGRATION: sync user_organizations → organization_members
-- ============================================================

-- Replay-safe: em preview-branches a coluna user_organizations.updated_at pode
-- ainda não existir neste ponto da sequência (drift de ordem de aplicação) → 42703.
-- O backfill só roda quando a coluna existe (em prod ela existe → roda normal); no
-- preview, organization_members já vem populado do clone, então é no-op de qualquer
-- forma. O IF EXISTS só planeja o INSERT quando o ramo é tomado (evita o 42703).
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'user_organizations' AND column_name = 'updated_at'
  ) THEN
    INSERT INTO public.organization_members (organization_id, user_id, role, joined_at, created_at, updated_at)
    SELECT uo.organization_id, uo.user_id, uo.role, uo.created_at AS joined_at, uo.created_at, uo.updated_at
    FROM public.user_organizations uo
    WHERE NOT EXISTS (
      SELECT 1 FROM public.organization_members om
      WHERE om.organization_id = uo.organization_id AND om.user_id = uo.user_id
    );
  END IF;
END $$;

CREATE OR REPLACE FUNCTION public.sync_user_org_to_org_members()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  IF (TG_OP = 'INSERT') THEN
    INSERT INTO public.organization_members (organization_id, user_id, role, joined_at, created_at, updated_at)
    VALUES (NEW.organization_id, NEW.user_id, NEW.role, NEW.created_at, NEW.created_at, NEW.updated_at)
    ON CONFLICT (organization_id, user_id) DO UPDATE SET role = EXCLUDED.role, updated_at = EXCLUDED.updated_at;
    RETURN NEW;
  ELSIF (TG_OP = 'UPDATE') THEN
    UPDATE public.organization_members SET role = NEW.role, updated_at = NEW.updated_at
    WHERE organization_id = NEW.organization_id AND user_id = NEW.user_id;
    RETURN NEW;
  ELSIF (TG_OP = 'DELETE') THEN
    DELETE FROM public.organization_members WHERE organization_id = OLD.organization_id AND user_id = OLD.user_id;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_user_org_to_org_members ON public.user_organizations;
CREATE TRIGGER trg_sync_user_org_to_org_members
  AFTER INSERT OR UPDATE OR DELETE ON public.user_organizations
  FOR EACH ROW EXECUTE FUNCTION public.sync_user_org_to_org_members();

-- <<< END 20260525193202_sync_user_organizations_to_organization_members_20260525.sql <<<

-- >>> BEGIN 20260525200101_corrections_indexes_performance.sql >>>
-- PASSO 41-43: Índices críticos para eliminar seq_scans (T03/T42)
-- Nota: sem CONCURRENTLY para compatibilidade com transações de migration (Supabase branching).
-- Em produção os índices são criados com IF NOT EXISTS, portanto sem downtime relevante.

-- user_roles: 101k seq_scans (96% do total) — queries RLS por user_id
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='user_roles' AND column_name IN ('user_id')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_user_roles_user_id
  ON user_roles(user_id);
  END IF;
END $$;

-- integration_credentials: 101k seq_scans (100%) — lookup por name
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='integration_credentials' AND column_name IN ('name')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_integration_creds_name
  ON integration_credentials(name);
  END IF;
END $$;

-- quotes: 65k seq_scans (100%) — RLS + listagem por usuário/organização/status
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='quotes' AND column_name IN ('user_id','organization_id','status')) = 3 THEN
    CREATE INDEX IF NOT EXISTS idx_quotes_user_org_status
  ON quotes(user_id, organization_id, status);
  END IF;
END $$;

-- quote_items: 14k seq_scans (99%) — sempre acessa por quote_id
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='quote_items' AND column_name IN ('quote_id')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_quote_items_quote_id
  ON quote_items(quote_id);
  END IF;
END $$;

-- color_variations: 7k seq_scans (100%) — acessa por product_id
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='color_variations' AND column_name IN ('product_id')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_color_variations_product_id
  ON color_variations(product_id);
  END IF;
END $$;

-- product_images: high n_distinct sem índice
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='product_images' AND column_name IN ('product_id')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_product_images_product_id
  ON product_images(product_id);
  END IF;
END $$;

-- image_import_log: 2339 distinct products sem índice
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='image_import_log' AND column_name IN ('product_id')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_image_import_log_product_id
  ON image_import_log(product_id);
  END IF;
END $$;

