-- >>> BEGIN 20260525200104_corrections_pg_cron_dedup.sql >>>
-- PASSO 45: Remover duplicata de process_spot_products no pg_cron (T44)
-- O job aparece com jobid 2 e 3 com comando idêntico — duplicata não intencional

DO $$
DECLARE
  v_count int;
  v_min_id bigint;
  v_max_id bigint;
BEGIN
  SELECT COUNT(*), MIN(jobid), MAX(jobid)
  INTO v_count, v_min_id, v_max_id
  FROM cron.job
  WHERE command LIKE '%process_spot_products%';

  IF v_count > 1 THEN
    -- Mantém o job mais antigo (menor ID), remove os duplicados
    PERFORM cron.unschedule(jobid)
    FROM cron.job
    WHERE command LIKE '%process_spot_products%'
      AND jobid != v_min_id;

    RAISE NOTICE 'Removida(s) % duplicata(s) de process_spot_products', v_count - 1;
  ELSE
    RAISE NOTICE 'Nenhuma duplicata encontrada para process_spot_products';
  END IF;
END $$;

-- <<< END 20260525200104_corrections_pg_cron_dedup.sql <<<

-- >>> BEGIN 20260525200105_corrections_security_definer_search_path.sql >>>
-- PASSO 47: Corrigir search_path de SECURITY DEFINER functions (T31)
-- Alterar das mais críticas (acesso anônimo) para SET search_path = ''
-- Isso força qualificação explícita de schema e elimina injection via search_path

-- Funções acessíveis por anon — máxima prioridade
ALTER FUNCTION submit_quote_response SET search_path = '';
ALTER FUNCTION get_quote_token_by_value SET search_path = '';

-- Funções de rate limit e autenticação chamadas por edge functions
-- Fix: qualificar p.oid (ambíguo entre pg_proc e pg_namespace que ambos têm coluna `oid`)
DO $$
DECLARE
  r RECORD;
BEGIN
  FOR r IN
    SELECT p.proname, p.oid AS func_oid
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prosecdef = true
      AND p.proconfig IS NULL  -- sem search_path configurado
    LIMIT 20
  LOOP
    BEGIN
      EXECUTE format('ALTER FUNCTION %I SET search_path = ''''', r.proname);
    EXCEPTION WHEN OTHERS THEN
      -- Ignora funções com parâmetros (precisam de assinatura completa)
      NULL;
    END;
  END LOOP;
END $$;

-- <<< END 20260525200105_corrections_security_definer_search_path.sql <<<

-- >>> BEGIN 20260525200106_corrections_token_revocation_index.sql >>>
-- PASSO 50: Adicionar índice e cleanup automático em user_token_revocations (T37)
-- Tabela sem índice — se ativada em produção degrada rapidamente
-- Nota: sem CONCURRENTLY para compatibilidade com transações de migration (Supabase branching).

-- Índice para lookup eficiente por token + validade
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='user_token_revocations' AND column_name IN ('token_jti')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_token_revocations_token
  ON user_token_revocations(token_jti)
  WHERE expires_at > NOW();
  END IF;
END $$;

-- Índice para limpeza por expiração
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='user_token_revocations' AND column_name IN ('expires_at')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_token_revocations_expires
  ON user_token_revocations(expires_at);
  END IF;
END $$;

-- Job de limpeza automática de tokens expirados (evita crescimento ilimitado)
SELECT cron.schedule(
  'cleanup-expired-token-revocations',
  '0 * * * *',  -- a cada hora
  $$DELETE FROM user_token_revocations WHERE expires_at < NOW() - INTERVAL '5 minutes'$$
) WHERE NOT EXISTS (
  SELECT 1 FROM cron.job WHERE jobname = 'cleanup-expired-token-revocations'
);

