-- >>> BEGIN 20260526103000_quote_update_transactional_rpc.sql >>>
-- RPC: update_quote_transactional
-- Versão corrigida: alinhada ao schema real do banco (discount_amount, total, valid_until,
-- discount_percentage, location_code, personalized_quantity, colors_count)
create or replace function public.update_quote_transactional(
  _quote_id uuid,
  _quote_patch jsonb,
  _items jsonb
)
returns public.quotes
language plpgsql
security invoker
set search_path = public
as $$
declare
  _updated_quote public.quotes;
  _item          jsonb;
  _pers          jsonb;
  _new_item_id   uuid;
begin
  update public.quotes
  set
    client_id                  = coalesce(nullif(_quote_patch->>'client_id','')::uuid, client_id),
    client_name                = coalesce(nullif(_quote_patch->>'client_name',''), client_name),
    client_email               = coalesce(_quote_patch->>'client_email',   client_email),
    client_phone               = coalesce(_quote_patch->>'client_phone',   client_phone),
    client_company             = coalesce(_quote_patch->>'client_company', client_company),
    status                     = coalesce(_quote_patch->>'status',         status),
    shipping_type              = coalesce(_quote_patch->>'shipping_type',  shipping_type),
    shipping_cost              = coalesce((_quote_patch->>'shipping_cost')::numeric,               shipping_cost),
    payment_method             = coalesce(_quote_patch->>'payment_method', payment_method),
    payment_terms              = coalesce(_quote_patch->>'payment_terms',  payment_terms),
    delivery_time              = coalesce(_quote_patch->>'delivery_time',  delivery_time),
    notes                      = coalesce(_quote_patch->>'notes',          notes),
    internal_notes             = coalesce(_quote_patch->>'internal_notes', internal_notes),
    discount_percent           = coalesce((_quote_patch->>'discount_percent')::numeric,            discount_percent),
    discount_amount            = coalesce((_quote_patch->>'discount_amount')::numeric,             discount_amount),
    subtotal                   = coalesce((_quote_patch->>'subtotal')::numeric,                    subtotal),
    total                      = coalesce((_quote_patch->>'total')::numeric,                       total),
    negotiation_markup_percent = coalesce((_quote_patch->>'negotiation_markup_percent')::numeric,  negotiation_markup_percent),
    valid_until                = coalesce((_quote_patch->>'valid_until')::date,                    valid_until),
    updated_at                 = now()
  where id = _quote_id
  returning * into _updated_quote;

  if _updated_quote is null then
    raise exception 'Orçamento não encontrado: %', _quote_id
      using errcode = 'no_data_found';
  end if;

  delete from public.quote_item_personalizations
  where quote_item_id in (
    select id from public.quote_items where quote_id = _quote_id
  );
  delete from public.quote_items where quote_id = _quote_id;

  for _item in select value from jsonb_array_elements(coalesce(_items,'[]'::jsonb)) loop
    insert into public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal, discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name
    )
    values (
      _quote_id,
      nullif(_item->>'product_id','')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer,0),
      coalesce((_item->>'unit_price')::numeric,0),
      coalesce((_item->>'subtotal')::numeric,0),
      coalesce((_item->>'discount_percentage')::numeric,0),
      coalesce((_item->>'discount_amount')::numeric,0),
      _item->>'color_name', _item->>'color_hex',
      nullif(_item->>'size_code',''), nullif(_item->>'gender',''),
      coalesce((_item->>'sort_order')::integer,0),
      _item->>'notes',
      nullif(_item->>'kit_group_id','')::uuid,
      nullif(_item->>'kit_name','')
    )
    returning id into _new_item_id;

    for _pers in select value from jsonb_array_elements(coalesce(_item->'personalizations','[]'::jsonb)) loop
      insert into public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      values (
        _new_item_id,
        nullif(_pers->>'technique_id','')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code', _pers->>'location_name',
        nullif(_pers->>'personalized_quantity','')::integer,
        coalesce((_pers->>'colors_count')::integer,1),
        coalesce((_pers->>'positions_count')::integer,1),
        nullif(_pers->>'area_cm2','')::numeric,
        nullif(_pers->>'width_cm','')::numeric,
        nullif(_pers->>'height_cm','')::numeric,
        coalesce((_pers->>'setup_cost')::numeric,0),
        coalesce((_pers->>'unit_cost')::numeric,0),
        coalesce((_pers->>'total_cost')::numeric,0),
        _pers->>'notes'
      );
    end loop;
  end loop;

  return _updated_quote;
end;
$$;

-- <<< END 20260526103000_quote_update_transactional_rpc.sql <<<

-- >>> BEGIN 20260526120000_fix_schema_divergences_4_tables.sql >>>
-- ============================================================
-- Fix: 4 divergências de schema identificadas na auditoria de migrations
-- Executado em 2026-05-26
-- ============================================================

-- 1. RPC update_quote_transactional — schema completo correto
-- (ver migration 20260526121000 para o corpo completo)
-- Divergências corrigidas:
--   quotes: discount_value→discount_amount, total_amount→total, expires_at→valid_until
--   quote_items: discount_percent→discount_percentage, discount_value→discount_amount, line_total→subtotal
--   quote_item_personalizations: location→location_code, colors→colors_count, quantity→personalized_quantity

-- 2. integration_credentials — índice no campo real (provider, não name)
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='integration_credentials' AND column_name IN ('provider','is_active')) = 2 THEN
    CREATE INDEX IF NOT EXISTS idx_integration_creds_provider
  ON public.integration_credentials(provider, is_active);
  END IF;
END $$;
-- Guard precisa verificar TAMBÉM is_active (usado no WHERE do índice parcial).
-- is_active não está no schema original (criado fora de migration em produção).
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='integration_credentials' AND column_name IN ('secret_name','is_active')) = 2 THEN
    CREATE INDEX IF NOT EXISTS idx_integration_creds_secret_name
  ON public.integration_credentials(secret_name)
  WHERE is_active = true;
  END IF;
END $$;

-- 3. color_variations — índice nos campos reais de query (group_id, não product_id)
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='color_variations' AND column_name IN ('group_id','is_active')) = 2 THEN
    CREATE INDEX IF NOT EXISTS idx_color_variations_active_group
  ON public.color_variations(group_id, is_active)
  WHERE is_active = true;
  END IF;
END $$;
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='color_variations' AND column_name IN ('color_group_id')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_color_variations_color_group
  ON public.color_variations(color_group_id)
  WHERE color_group_id IS NOT NULL;
  END IF;
END $$;

-- 4. user_token_revocations — adiciona token_jti + expires_at para revogação granular
ALTER TABLE public.user_token_revocations
  ADD COLUMN IF NOT EXISTS token_jti   text,
  ADD COLUMN IF NOT EXISTS expires_at  timestamptz,
  ADD COLUMN IF NOT EXISTS reason      text;
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='user_token_revocations' AND column_name IN ('token_jti')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_token_revocations_jti ON public.user_token_revocations(token_jti) WHERE token_jti IS NOT NULL;
  END IF;
END $$;
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='user_token_revocations' AND column_name IN ('expires_at')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_token_revocations_expires ON public.user_token_revocations(expires_at) WHERE expires_at IS NOT NULL;
  END IF;
END $$;
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='user_token_revocations' AND column_name IN ('user_id','revoked_at')) = 2 THEN
    CREATE INDEX IF NOT EXISTS idx_token_revocations_user_id ON public.user_token_revocations(user_id, revoked_at DESC);
  END IF;
END $$;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'cleanup-expired-token-revocations') THEN
    PERFORM cron.unschedule('cleanup-expired-token-revocations');
  END IF;
END $$;
SELECT cron.schedule('cleanup-expired-token-revocations','0 * * * *',
  $$DELETE FROM user_token_revocations WHERE (expires_at IS NOT NULL AND expires_at < now() - interval '5 minutes') OR (expires_at IS NULL AND revoked_at < now() - interval '30 days');$$);

-- <<< END 20260526120000_fix_schema_divergences_4_tables.sql <<<

