-- >>> BEGIN 20260527120000_update_quote_transactional_hardening.sql >>>
-- Harden update_quote_transactional to ensure atomic replace of quote + items + personalizations
create or replace function public.update_quote_transactional(
  _quote_id uuid,
  _quote_patch jsonb,
  _items jsonb
)
returns public.quotes
language plpgsql
security invoker
set search_path = public
as $$
declare
  _updated_quote public.quotes;
  _item          jsonb;
  _pers          jsonb;
  _new_item_id   uuid;
begin
  update public.quotes
  set
    client_id                  = coalesce(nullif(_quote_patch->>'client_id','')::uuid, client_id),
    client_name                = coalesce(nullif(_quote_patch->>'client_name',''), client_name),
    client_email               = coalesce(_quote_patch->>'client_email',   client_email),
    client_phone               = coalesce(_quote_patch->>'client_phone',   client_phone),
    client_company             = coalesce(_quote_patch->>'client_company', client_company),
    status                     = coalesce(_quote_patch->>'status',         status),
    shipping_type              = coalesce(_quote_patch->>'shipping_type',  shipping_type),
    shipping_cost              = coalesce((_quote_patch->>'shipping_cost')::numeric,               shipping_cost),
    payment_method             = coalesce(_quote_patch->>'payment_method', payment_method),
    payment_terms              = coalesce(_quote_patch->>'payment_terms',  payment_terms),
    delivery_time              = coalesce(_quote_patch->>'delivery_time',  delivery_time),
    notes                      = coalesce(_quote_patch->>'notes',          notes),
    internal_notes             = coalesce(_quote_patch->>'internal_notes', internal_notes),
    discount_percent           = coalesce((_quote_patch->>'discount_percent')::numeric,            discount_percent),
    discount_amount            = coalesce((_quote_patch->>'discount_amount')::numeric,             discount_amount),
    subtotal                   = coalesce((_quote_patch->>'subtotal')::numeric,                    subtotal),
    total                      = coalesce((_quote_patch->>'total')::numeric,                       total),
    negotiation_markup_percent = coalesce((_quote_patch->>'negotiation_markup_percent')::numeric,  negotiation_markup_percent),
    valid_until                = coalesce((_quote_patch->>'valid_until')::date,                    valid_until),
    updated_at                 = now()
  where id = _quote_id
  returning * into _updated_quote;

  if _updated_quote is null then
    raise exception 'Orçamento não encontrado: %', _quote_id using errcode = 'no_data_found';
  end if;

  delete from public.quote_item_personalizations
  where quote_item_id in (
    select id from public.quote_items where quote_id = _quote_id
  );

  delete from public.quote_items where quote_id = _quote_id;

  for _item in
    select value from jsonb_array_elements(coalesce(_items, '[]'::jsonb))
  loop
    insert into public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal, discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name
    )
    values (
      _quote_id,
      nullif(_item->>'product_id','')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer,0),
      coalesce((_item->>'unit_price')::numeric,0),
      coalesce((_item->>'subtotal')::numeric,0),
      coalesce((_item->>'discount_percentage')::numeric,0),
      coalesce((_item->>'discount_amount')::numeric,0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code',''),
      nullif(_item->>'gender',''),
      coalesce((_item->>'sort_order')::integer,0),
      _item->>'notes',
      nullif(_item->>'kit_group_id','')::uuid,
      nullif(_item->>'kit_name','')
    )
    returning id into _new_item_id;

    for _pers in
      select value from jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb))
    loop
      insert into public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      values (
        _new_item_id,
        nullif(_pers->>'technique_id','')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity','')::integer,
        coalesce((_pers->>'colors_count')::integer,1),
        coalesce((_pers->>'positions_count')::integer,1),
        nullif(_pers->>'area_cm2','')::numeric,
        nullif(_pers->>'width_cm','')::numeric,
        nullif(_pers->>'height_cm','')::numeric,
        coalesce((_pers->>'setup_cost')::numeric,0),
        coalesce((_pers->>'unit_cost')::numeric,0),
        coalesce((_pers->>'total_cost')::numeric,0),
        _pers->>'notes'
      );
    end loop;
  end loop;

  return _updated_quote;
exception
  when others then
    raise exception 'Falha na atualização transacional do orçamento %: %', _quote_id, sqlerrm
      using errcode = sqlstate;
end;
$$;

-- <<< END 20260527120000_update_quote_transactional_hardening.sql <<<

-- >>> BEGIN 20260527121746_4e6187e6-a340-4b6a-8caa-71fd82f4044c.sql >>>
CREATE TABLE IF NOT EXISTS public.system_error_logs (
    id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
    user_id UUID,
    function_name TEXT NOT NULL,
    error_message TEXT NOT NULL,
    stack_trace TEXT,
    metadata JSONB DEFAULT '{}'::jsonb,
    severity TEXT DEFAULT 'error',
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);

-- Use GRANT to set permissions
GRANT INSERT ON public.system_error_logs TO authenticated;
GRANT SELECT ON public.system_error_logs TO authenticated;
GRANT ALL ON public.system_error_logs TO service_role;

-- Enable RLS
ALTER TABLE public.system_error_logs ENABLE ROW LEVEL SECURITY;

-- Create policies
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'system_error_logs' AND policyname = 'Users can insert their own error logs'
  ) THEN
    CREATE POLICY "Users can insert their own error logs" 
ON public.system_error_logs 
FOR INSERT 
WITH CHECK (auth.uid() = user_id OR user_id IS NULL);
  END IF;
END $$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'system_error_logs' AND policyname = 'Users can view their own error logs'
  ) THEN
    CREATE POLICY "Users can view their own error logs" 
ON public.system_error_logs 
FOR SELECT 
USING (auth.uid() = user_id);
  END IF;
END $$;

-- Index for performance
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='system_error_logs' AND column_name IN ('user_id')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_system_error_logs_user_id ON public.system_error_logs(user_id);
  END IF;
END $$;
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='system_error_logs' AND column_name IN ('function_name')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_system_error_logs_function_name ON public.system_error_logs(function_name);
  END IF;
END $$;
DO $$
BEGIN
  IF (SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='system_error_logs' AND column_name IN ('created_at')) = 1 THEN
    CREATE INDEX IF NOT EXISTS idx_system_error_logs_created_at ON public.system_error_logs(created_at);
  END IF;
END $$;
-- <<< END 20260527121746_4e6187e6-a340-4b6a-8caa-71fd82f4044c.sql <<<

-- >>> BEGIN 20260527143139_482b086d-660c-4025-91c5-619a87933d31.sql >>>
-- 1. Atualizar o nome da única organização existente no banco para Promo Brindes
UPDATE public.organizations 
SET name = 'Promo Brindes', slug = 'promo-brindes'
WHERE id = '35c6a2a6-5d6d-4ddb-8dbd-8e842a0118e5';

-- 2. Criar função para atribuição automática de organização
-- Isso garante que novos usuários sempre pertençam à Promo Brindes,
-- mantendo as políticas de RLS funcionando sem alterações manuais.
CREATE OR REPLACE FUNCTION public.auto_assign_user_to_promo_brindes()
RETURNS TRIGGER AS $$
BEGIN
  -- Guard: em preview snapshots sem a organização Promo Brindes, viramos no-op
  -- para evitar FK violation em todo INSERT em profiles.
  IF EXISTS (
    SELECT 1 FROM public.organizations
    WHERE id = '35c6a2a6-5d6d-4ddb-8dbd-8e842a0118e5'
  ) THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    VALUES ('35c6a2a6-5d6d-4ddb-8dbd-8e842a0118e5', NEW.user_id, 'member')
    ON CONFLICT (organization_id, user_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- 3. Trigger na tabela profiles
-- Sempre que um perfil for criado, vinculamos o usuário à organização.
DROP TRIGGER IF EXISTS trg_auto_assign_promo_brindes ON public.profiles;
CREATE TRIGGER trg_auto_assign_promo_brindes
  AFTER INSERT ON public.profiles
  FOR EACH ROW
  EXECUTE FUNCTION public.auto_assign_user_to_promo_brindes();

-- 4. Sincronizar perfis existentes que possam estar órfãos de organização
-- Guard: a organização 'Promo Brindes' pode não existir em preview snapshots
-- (organization criada manualmente em produção); evitamos FK violation.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.organizations
    WHERE id = '35c6a2a6-5d6d-4ddb-8dbd-8e842a0118e5'
  ) THEN
    INSERT INTO public.organization_members (organization_id, user_id, role)
    SELECT '35c6a2a6-5d6d-4ddb-8dbd-8e842a0118e5', user_id, 'member'
    FROM public.profiles
    ON CONFLICT (organization_id, user_id) DO NOTHING;
  ELSE
    RAISE NOTICE 'Organização Promo Brindes não existe — sync de profiles pulado';
  END IF;
END $$;

-- <<< END 20260527143139_482b086d-660c-4025-91c5-619a87933d31.sql <<<

