  EXCEPTION WHEN undefined_function THEN NULL;
  END;

  BEGIN
    REVOKE EXECUTE ON FUNCTION public.fn_run_and_persist_smoke_tests() FROM authenticated, anon;
  EXCEPTION WHEN undefined_function THEN NULL;
  END;
END $$;

