-- >>> BEGIN 20260603215516_raw_landing_phase1_status_provenance.sql >>>

-- ════════════════════════════════════════════════════════════════
-- FASE 1 — Máquina de estados + proveniência + backfill (ADITIVO)
-- Landing bronze multi-fornecedor. Nada destrutivo aqui.
-- ════════════════════════════════════════════════════════════════

-- Estado de processamento como enum (substitui semanticamente o boolean)
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname='supplier_raw_status') THEN
    CREATE TYPE supplier_raw_status AS ENUM
      ('pending','processing','processed','failed','skipped','quarantined');
  END IF;
END $$;

-- Colunas novas. status/images_status já nascem NOT NULL DEFAULT 'pending'
-- (seguro: o DEFAULT preenche as linhas existentes; o backfill abaixo corrige).
-- source_channel nasce 'legacy' para as linhas históricas; depois vira 'n8n' para novos inserts.
ALTER TABLE public.supplier_products_raw
  ADD COLUMN IF NOT EXISTS source_channel  text    NOT NULL DEFAULT 'legacy',
  ADD COLUMN IF NOT EXISTS source_event_id text,
  ADD COLUMN IF NOT EXISTS source_endpoint text,
  ADD COLUMN IF NOT EXISTS attempts        integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS claimed_at      timestamptz,
  ADD COLUMN IF NOT EXISTS last_error      jsonb,
  ADD COLUMN IF NOT EXISTS status          supplier_raw_status NOT NULL DEFAULT 'pending',
  ADD COLUMN IF NOT EXISTS images_status   supplier_raw_status NOT NULL DEFAULT 'pending';

-- Backfill pela VERDADE OBSERVÁVEL: product_id materializado = processed.
-- Warnings (process_errors) de quem já materializou viram last_error informativo, sem rebaixar o status.
UPDATE public.supplier_products_raw SET
  status = CASE
    WHEN product_id IS NOT NULL     THEN 'processed'
    WHEN process_errors IS NOT NULL THEN 'failed'
    WHEN processed                  THEN 'processed'
    ELSE 'pending' END::supplier_raw_status,
  images_status = CASE WHEN images_processed THEN 'processed' ELSE 'pending' END::supplier_raw_status,
  last_error = COALESCE(last_error, process_errors);

-- A partir de agora, novos inserts default = 'n8n' (histórico permanece 'legacy')
ALTER TABLE public.supplier_products_raw ALTER COLUMN source_channel SET DEFAULT 'n8n';

-- <<< END 20260603215516_raw_landing_phase1_status_provenance.sql <<<

-- >>> BEGIN 20260603215610_raw_landing_phase1b_status_coherence_trigger.sql >>>

-- ════════════════════════════════════════════════════════════════
-- Salvaguarda de transição: coerência status(enum) <-> processed(legado)
-- Garante zero divergência enquanto o modelo antigo e o novo coexistem.
-- status é a FONTE DA VERDADE; processed/images_processed são espelhos.
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_sync_raw_status()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.processed        := (NEW.status = 'processed');
    NEW.images_processed := (NEW.images_status = 'processed');
    IF NEW.process_errors IS NOT NULL AND NEW.last_error IS NULL THEN
      NEW.last_error := NEW.process_errors;
    END IF;

  ELSIF TG_OP = 'UPDATE' THEN
    -- Se o enum mudou, ele manda → espelha em processed.
    -- Senão, se o código legado mexeu em processed, reflete de volta no enum.
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.processed := (NEW.status = 'processed');
    ELSIF NEW.processed IS DISTINCT FROM OLD.processed THEN
      NEW.status := CASE
        WHEN NEW.processed                  THEN 'processed'
        WHEN NEW.process_errors IS NOT NULL THEN 'failed'
        ELSE 'pending' END::supplier_raw_status;
    END IF;

    IF NEW.images_status IS DISTINCT FROM OLD.images_status THEN
      NEW.images_processed := (NEW.images_status = 'processed');
    ELSIF NEW.images_processed IS DISTINCT FROM OLD.images_processed THEN
      NEW.images_status := CASE WHEN NEW.images_processed THEN 'processed' ELSE 'pending' END::supplier_raw_status;
    END IF;

    IF NEW.process_errors IS DISTINCT FROM OLD.process_errors AND NEW.process_errors IS NOT NULL THEN
      NEW.last_error := NEW.process_errors;
    END IF;

    IF NEW.status = 'processed' AND NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.processed_at := COALESCE(NEW.processed_at, now());
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_zz_sync_raw_status ON public.supplier_products_raw;
CREATE TRIGGER trg_zz_sync_raw_status
  BEFORE INSERT OR UPDATE ON public.supplier_products_raw
  FOR EACH ROW EXECUTE FUNCTION public.fn_sync_raw_status();

-- <<< END 20260603215610_raw_landing_phase1b_status_coherence_trigger.sql <<<

-- >>> BEGIN 20260603215622_raw_landing_phase2_content_hash_generated.sql >>>

-- ════════════════════════════════════════════════════════════════
-- FASE 2 — content_hash GERADO pelo banco (idempotência confiável)
-- jsonb::text é canônico no PG → hash determinístico, nunca nulo,
-- independe do n8n. Resolve os 92% de raw_hash nulos de forma estrutural.
-- ════════════════════════════════════════════════════════════════
ALTER TABLE public.supplier_products_raw
  ADD COLUMN IF NOT EXISTS content_hash text
  GENERATED ALWAYS AS (encode(extensions.digest(raw_data::text, 'sha256'), 'hex')) STORED;

-- <<< END 20260603215622_raw_landing_phase2_content_hash_generated.sql <<<

-- >>> BEGIN 20260603215700_raw_landing_phase3_queue_indexes.sql >>>

-- ════════════════════════════════════════════════════════════════
-- FASE 3 (parte segura) — índices da fila e da idempotência.
-- Índices PARCIAIS: indexam só o que está "quente" (pending/failed),
-- mantendo-se minúsculos mesmo com milhões de linhas processadas.
-- Nenhuma coluna é removida aqui (DROPs ficam gated em auditoria).
-- ════════════════════════════════════════════════════════════════

-- Fila de processamento: o worker pega o próximo pendente por ordem de chegada
CREATE INDEX IF NOT EXISTS idx_spr_queue
  ON public.supplier_products_raw (supplier_id, imported_at) WHERE status = 'pending';

-- Itens que falharam (para retry/monitoramento)
CREATE INDEX IF NOT EXISTS idx_spr_failed
  ON public.supplier_products_raw (supplier_id) WHERE status = 'failed';

-- Fila do pipeline de imagens (assíncrono, paralelo)
CREATE INDEX IF NOT EXISTS idx_spr_images_queue
  ON public.supplier_products_raw (supplier_id) WHERE images_status = 'pending';

-- Detecção de mudança / dedupe por conteúdo
CREATE INDEX IF NOT EXISTS idx_spr_content_hash
  ON public.supplier_products_raw (supplier_id, content_hash);

-- <<< END 20260603215700_raw_landing_phase3_queue_indexes.sql <<<

-- >>> BEGIN 20260603221755_silver_01_locked_fields_soberania.sql >>>

-- ════════════════════════════════════════════════════════════════
-- SOBERANIA DA INTERFACE — trava por-campo em products
-- "Edição na interface é absoluta": campo tocado à mão entra em
-- locked_fields e a promoção silver→products nunca o sobrescreve.
-- ════════════════════════════════════════════════════════════════

ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS locked_fields text[] NOT NULL DEFAULT '{}';

COMMENT ON COLUMN public.products.locked_fields IS
  'Campos editados manualmente na interface (soberanos). A promoção silver→products nunca sobrescreve um campo presente aqui. Populado pelo trigger trg_products_capture_manual_edits quor a escrita é humana.';

-- ── Função: captura edição manual e trava o campo ─────────────────
-- Distingue escrita HUMANA de escrita do PIPELINE pela presença de um GUC
-- de sessão: o pipeline seta app.write_source='pipeline'; o front (default)
-- não seta → é tratado como edição humana e trava os campos alterados.
CREATE OR REPLACE FUNCTION public.fn_products_capture_manual_edits()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_src text := current_setting('app.write_source', true);  -- 'pipeline' | NULL/'ui'
  v_campos text[] := ARRAY[
    'name','description','short_description','sku','cost_price','sale_price','suggested_price',
    'primary_image_url','images','ncm_code','weight_g','height_cm','width_cm','length_cm',
    'dimensions_display','brand','packing_type','min_quantity','stock_quantity','is_active',
    'warranty_months','ipi_rate','engraving_type','category_id','main_category_id'
  ];
  v_campo text;
  v_old jsonb := to_jsonb(OLD);
  v_new jsonb := to_jsonb(NEW);
BEGIN
  -- Só captura em UPDATE feito por humano (não-pipeline)
  IF TG_OP = 'UPDATE' AND COALESCE(v_src,'ui') <> 'pipeline' THEN
    FOREACH v_campo IN ARRAY v_campos LOOP
      IF (v_old -> v_campo) IS DISTINCT FROM (v_new -> v_campo) THEN
        IF NOT (v_campo = ANY(NEW.locked_fields)) THEN
          NEW.locked_fields := array_append(NEW.locked_fields, v_campo);
        END IF;
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;

-- roda cedo (before) para que locked_fields já vá gravado na mesma operação.
-- nome "trg_aa_" garante execução antes dos demais BEFORE UPDATE.
DROP TRIGGER IF EXISTS trg_aa_capture_manual_edits ON public.products;
CREATE TRIGGER trg_aa_capture_manual_edits
  BEFORE UPDATE ON public.products
  FOR EACH ROW EXECUTE FUNCTION public.fn_products_capture_manual_edits();

-- <<< END 20260603221755_silver_01_locked_fields_soberania.sql <<<

-- >>> BEGIN 20260603221821_silver_02_produtos_padronizacao.sql >>>

-- ════════════════════════════════════════════════════════════════
-- SILVER — produtos_padronizacao
-- Recebe o cru da supplier_products_raw, aplica equivalências
-- (cor, NCM, unidade…) e guarda o produto JÁ PADRONIZADO, pronto
-- para promover a products. Uma linha por (supplier_id, supplier_reference).
-- ════════════════════════════════════════════════════════════════

CREATE TYPE produtos_padronizacao_status AS ENUM
  ('pending','standardized','rejected','promoted');

CREATE TABLE public.produtos_padronizacao (
  -- Identidade / proveniência
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  raw_id              uuid REFERENCES public.supplier_products_raw(id) ON DELETE SET NULL,
  supplier_id         uuid NOT NULL REFERENCES public.suppliers(id),
  supplier_reference  text NOT NULL,
  product_id          uuid REFERENCES public.products(id) ON DELETE SET NULL,  -- vínculo após promoção

  -- ── NÚCLEO DE INGESTÃO (já padronizado; mesmos nomes/tipos de products) ──
  name                text,
  description         text,
  short_description   varchar,
  cost_price          numeric,
  suggested_price     numeric,
  stock_quantity      integer,
  primary_image_url   text,
  images              jsonb,
  ncm_code            varchar,          -- já normalizado (8 dígitos, sem ponto)
  weight_g            integer,
  height_cm           numeric,
  width_cm            numeric,
  length_cm           numeric,
  dimensions_display  varchar,
  box_length_cm       numeric,
  box_width_cm        numeric,
  box_height_cm       numeric,
  box_weight_kg       numeric,
  box_volume_cm3      numeric,
  box_quantity        integer,
  box_inner_quantity  integer,
  brand               varchar,
  packing_type        varchar,
  repacking_type      varchar,
  capacities          varchar,
  capacity_ml         integer,
  min_quantity        integer,
  warranty_months     integer,
  ipi_rate            numeric,
  engraving_type      text,
  is_active           boolean,

  -- ── Equivalências resolvidas (resultado da padronização de cor) ──
  colors              jsonb,            -- cores canônicas resolvidas via supplier_colors

  -- ── Controle do fluxo bronze→silver→gold ──
  status              produtos_padronizacao_status NOT NULL DEFAULT 'pending',
  validation_errors   jsonb,            -- por que foi 'rejected' (ex.: ncm inválido)
  standardized_at     timestamptz,
  promoted_at         timestamptz,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT uq_pad_supplier_reference UNIQUE (supplier_id, supplier_reference)
);

-- Índices de fila/promoção (parciais — só o que está quente)
CREATE INDEX idx_pad_to_standardize ON public.produtos_padronizacao (supplier_id) WHERE status='pending';
CREATE INDEX idx_pad_to_promote     ON public.produtos_padronizacao (supplier_id) WHERE status='standardized';
CREATE INDEX idx_pad_rejected       ON public.produtos_padronizacao (supplier_id) WHERE status='rejected';
CREATE INDEX idx_pad_product        ON public.produtos_padronizacao (product_id) WHERE product_id IS NOT NULL;

-- updated_at automático (reusa a função existente do projeto)
CREATE TRIGGER set_updated_at_trigger
  BEFORE UPDATE ON public.produtos_padronizacao
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

COMMENT ON TABLE public.produtos_padronizacao IS
  'SILVER: produtos padronizados (equivalências de cor/NCM/unidade resolvidas) prontos para promoção a products. Bronze=supplier_products_raw, Gold=products.';

-- <<< END 20260603221821_silver_02_produtos_padronizacao.sql <<<

-- >>> BEGIN 20260603221859_silver_03_funcao_promocao_soberana.sql >>>

-- ════════════════════════════════════════════════════════════════
-- PROMOÇÃO silver → gold (products) com MERGE SOBERANO
-- Para cada campo: se está em products.locked_fields (editado à mão),
-- mantém o valor de products; senão, recebe o valor padronizado.
-- Seta app.write_source='pipeline' para NÃO disparar a captura de edição.
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_promote_padronizacao(p_id uuid)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE
  s         public.produtos_padronizacao%ROWTYPE;
  v_pid     uuid;
  v_org     uuid;
  v_locked  text[];
  v_is_new  boolean := false;
BEGIN
  SELECT * INTO s FROM public.produtos_padronizacao WHERE id = p_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'padronizacao_nao_encontrada', 'id', p_id);
  END IF;
  IF s.status <> 'standardized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'status_invalido', 'status', s.status);
  END IF;

  -- Marca esta sessão como escrita do PIPELINE (não trava campos)
  PERFORM set_config('app.write_source', 'pipeline', true);

  -- Localiza produto existente por (supplier_id, supplier_reference)
  SELECT id, locked_fields INTO v_pid, v_locked
  FROM public.products
  WHERE supplier_id = s.supplier_id AND supplier_reference = s.supplier_reference;

  IF v_pid IS NULL THEN
    -- Produto novo: cria o esqueleto (triggers de products completam o resto)
    v_is_new := true;
    SELECT organization_id INTO v_org FROM public.suppliers WHERE id = s.supplier_id;
    INSERT INTO public.products (organization_id, supplier_id, supplier_reference, sku, name, active, is_active, product_type)
    VALUES (v_org, s.supplier_id, s.supplier_reference,
            COALESCE(s.supplier_reference, s.name), COALESCE(s.name,'Produto '||s.supplier_reference),
            COALESCE(s.is_active, true), COALESCE(s.is_active, true), 'product')
    RETURNING id, locked_fields INTO v_pid, v_locked;
  END IF;

  v_locked := COALESCE(v_locked, '{}');

  -- MERGE SOBERANO: cada campo só atualiza se NÃO estiver travado.
  -- (COALESCE evita apagar valor existente quando a silver vem NULL.)
  UPDATE public.products p SET
    name               = CASE WHEN 'name'               = ANY(v_locked) THEN p.name               ELSE COALESCE(s.name, p.name) END,
    description        = CASE WHEN 'description'        = ANY(v_locked) THEN p.description        ELSE COALESCE(s.description, p.description) END,
    short_description  = CASE WHEN 'short_description'  = ANY(v_locked) THEN p.short_description  ELSE COALESCE(s.short_description, p.short_description) END,
    cost_price         = CASE WHEN 'cost_price'         = ANY(v_locked) THEN p.cost_price         ELSE COALESCE(s.cost_price, p.cost_price) END,
    suggested_price    = CASE WHEN 'suggested_price'    = ANY(v_locked) THEN p.suggested_price    ELSE COALESCE(s.suggested_price, p.suggested_price) END,
    stock_quantity     = CASE WHEN 'stock_quantity'     = ANY(v_locked) THEN p.stock_quantity     ELSE COALESCE(s.stock_quantity, p.stock_quantity) END,
    primary_image_url  = CASE WHEN 'primary_image_url'  = ANY(v_locked) THEN p.primary_image_url  ELSE COALESCE(s.primary_image_url, p.primary_image_url) END,
    images             = CASE WHEN 'images'             = ANY(v_locked) THEN p.images             ELSE COALESCE(s.images, p.images) END,
    ncm_code           = CASE WHEN 'ncm_code'           = ANY(v_locked) THEN p.ncm_code           ELSE COALESCE(s.ncm_code, p.ncm_code) END,
    weight_g           = CASE WHEN 'weight_g'           = ANY(v_locked) THEN p.weight_g           ELSE COALESCE(s.weight_g, p.weight_g) END,
    height_cm          = CASE WHEN 'height_cm'          = ANY(v_locked) THEN p.height_cm          ELSE COALESCE(s.height_cm, p.height_cm) END,
    width_cm           = CASE WHEN 'width_cm'           = ANY(v_locked) THEN p.width_cm           ELSE COALESCE(s.width_cm, p.width_cm) END,
    length_cm          = CASE WHEN 'length_cm'          = ANY(v_locked) THEN p.length_cm          ELSE COALESCE(s.length_cm, p.length_cm) END,
    dimensions_display = CASE WHEN 'dimensions_display' = ANY(v_locked) THEN p.dimensions_display ELSE COALESCE(s.dimensions_display, p.dimensions_display) END,
    box_length_cm      = CASE WHEN 'box_length_cm'      = ANY(v_locked) THEN p.box_length_cm      ELSE COALESCE(s.box_length_cm, p.box_length_cm) END,
    box_width_cm       = CASE WHEN 'box_width_cm'       = ANY(v_locked) THEN p.box_width_cm       ELSE COALESCE(s.box_width_cm, p.box_width_cm) END,
    box_height_cm      = CASE WHEN 'box_height_cm'      = ANY(v_locked) THEN p.box_height_cm      ELSE COALESCE(s.box_height_cm, p.box_height_cm) END,
    box_weight_kg      = CASE WHEN 'box_weight_kg'      = ANY(v_locked) THEN p.box_weight_kg      ELSE COALESCE(s.box_weight_kg, p.box_weight_kg) END,
    box_volume_cm3     = CASE WHEN 'box_volume_cm3'     = ANY(v_locked) THEN p.box_volume_cm3     ELSE COALESCE(s.box_volume_cm3, p.box_volume_cm3) END,
    box_quantity       = CASE WHEN 'box_quantity'       = ANY(v_locked) THEN p.box_quantity       ELSE COALESCE(s.box_quantity, p.box_quantity) END,
    box_inner_quantity = CASE WHEN 'box_inner_quantity' = ANY(v_locked) THEN p.box_inner_quantity ELSE COALESCE(s.box_inner_quantity, p.box_inner_quantity) END,
    brand              = CASE WHEN 'brand'              = ANY(v_locked) THEN p.brand              ELSE COALESCE(s.brand, p.brand) END,
    packing_type       = CASE WHEN 'packing_type'       = ANY(v_locked) THEN p.packing_type       ELSE COALESCE(s.packing_type, p.packing_type) END,
    repacking_type     = CASE WHEN 'repacking_type'     = ANY(v_locked) THEN p.repacking_type     ELSE COALESCE(s.repacking_type, p.repacking_type) END,
    capacities         = CASE WHEN 'capacities'         = ANY(v_locked) THEN p.capacities         ELSE COALESCE(s.capacities, p.capacities) END,
    capacity_ml        = CASE WHEN 'capacity_ml'        = ANY(v_locked) THEN p.capacity_ml        ELSE COALESCE(s.capacity_ml, p.capacity_ml) END,
    min_quantity       = CASE WHEN 'min_quantity'       = ANY(v_locked) THEN p.min_quantity       ELSE COALESCE(s.min_quantity, p.min_quantity) END,
    warranty_months    = CASE WHEN 'warranty_months'    = ANY(v_locked) THEN p.warranty_months    ELSE COALESCE(s.warranty_months, p.warranty_months) END,
    ipi_rate           = CASE WHEN 'ipi_rate'           = ANY(v_locked) THEN p.ipi_rate           ELSE COALESCE(s.ipi_rate, p.ipi_rate) END,
    engraving_type     = CASE WHEN 'engraving_type'     = ANY(v_locked) THEN p.engraving_type     ELSE COALESCE(s.engraving_type, p.engraving_type) END,
    colors             = CASE WHEN 'colors'             = ANY(v_locked) THEN p.colors             ELSE COALESCE(s.colors, p.colors) END,
    is_active          = CASE WHEN 'is_active'          = ANY(v_locked) THEN p.is_active          ELSE COALESCE(s.is_active, p.is_active) END,
    last_sync_at          = now(),
    last_sync_supplier_id = s.supplier_id,
    supplier_updated_at   = now()
  WHERE p.id = v_pid;

  -- Fecha o ciclo na silver e na bronze
  UPDATE public.produtos_padronizacao
     SET status='promoted', promoted_at=now(), product_id=v_pid
   WHERE id = p_id;

  IF s.raw_id IS NOT NULL THEN
    UPDATE public.supplier_products_raw
       SET status='processed', processed_at=now(), product_id=v_pid
     WHERE id = s.raw_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'product_id', v_pid, 'created', v_is_new,
                            'locked_preserved', v_locked);
END;
$$;

COMMENT ON FUNCTION public.fn_promote_padronizacao(uuid) IS
  'Promove uma linha silver→products com merge soberano: campos em products.locked_fields nunca são sobrescritos pelo fornecedor.';

-- <<< END 20260603221859_silver_03_funcao_promocao_soberana.sql <<<

-- >>> BEGIN 20260603222002_silver_04_padronizador_bronze_to_silver.sql >>>

-- ════════════════════════════════════════════════════════════════
-- PADRONIZADOR bronze → silver
-- Lê supplier_products_raw, aplica o de-para (supplier_field_mappings)
-- + equivalências, e grava produtos_padronizacao JÁ PADRONIZADO.
-- Correções embutidas: NCM sempre via fn_normalize_ncm (resolve bug Asia).
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_standardize_raw(p_raw_id uuid)
RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE
  r          public.supplier_products_raw%ROWTYPE;
  m          RECORD;
  v_val      text;
  v_tx       text;
  v_assigns  jsonb := '{}'::jsonb;   -- coluna→valor acumulado (campos de products)
  v_errs     jsonb := '[]'::jsonb;
  v_ncm      text;
  v_ncm_raw  text;
  v_pad_id   uuid;
  v_cols     text[] := ARRAY[
    'name','description','short_description','cost_price','suggested_price','stock_quantity',
    'primary_image_url','images','ncm_code','weight_g','height_cm','width_cm','length_cm',
    'dimensions_display','box_length_cm','box_width_cm','box_height_cm','box_weight_kg',
    'box_volume_cm3','box_quantity','box_inner_quantity','brand','packing_type','repacking_type',
    'capacities','capacity_ml','min_quantity','warranty_months','ipi_rate','engraving_type','is_active'
  ];
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'raw_nao_encontrado', 'id', p_raw_id);
  END IF;

  -- Aplica o de-para do fornecedor, somente para alvos em products
  -- e somente para colunas que a silver carrega (núcleo de ingestão).
  FOR m IN
    SELECT source_field, source_path, target_field, transform_type, transform_config,
           source_unit, target_unit
    FROM public.supplier_field_mappings
    WHERE supplier_id = r.supplier_id AND target_table = 'products' AND is_active = TRUE
      AND target_field = ANY(v_cols)
    ORDER BY priority
  LOOP
    -- extrai valor cru (campo direto ou caminho aninhado)
    IF m.source_path IS NOT NULL THEN
      v_val := r.raw_data #>> string_to_array(m.source_path, '.');
    ELSE
      v_val := r.raw_data ->> m.source_field;
    END IF;
    CONTINUE WHEN v_val IS NULL OR TRIM(v_val) = '';

    -- transforma usando a engine existente
    BEGIN
      v_tx := public.fn_apply_transform(v_val, m.transform_type, m.transform_config,
                                        m.source_unit, m.target_unit, r.supplier_id);
    EXCEPTION WHEN OTHERS THEN
      v_tx := v_val;
      v_errs := v_errs || jsonb_build_object('field', m.target_field, 'stage', 'transform', 'msg', SQLERRM);
    END;

    IF v_tx IS NOT NULL THEN
      v_assigns := v_assigns || jsonb_build_object(m.target_field, v_tx);
    END IF;
  END LOOP;

  -- ── CORREÇÃO NCM (resolve o bug Asia: jsonpath gravava com pontos) ──
  v_ncm_raw := COALESCE(v_assigns->>'ncm_code', r.raw_data->>'ncm', r.raw_data->>'Ncm');
  v_ncm := public.fn_normalize_ncm(v_ncm_raw);   -- 8 dígitos, sem ponto, ou NULL se inválido
  IF v_ncm IS NOT NULL THEN
    v_assigns := v_assigns || jsonb_build_object('ncm_code', v_ncm);
  ELSIF v_ncm_raw IS NOT NULL THEN
    v_errs := v_errs || jsonb_build_object('field','ncm_code','stage','validate','msg','ncm_invalido','raw',v_ncm_raw);
    v_assigns := v_assigns - 'ncm_code';  -- não promove NCM inválido
  END IF;

  -- ── UPSERT na silver, materializando o jsonb acumulado em colunas tipadas ──
  INSERT INTO public.produtos_padronizacao AS pad (
    raw_id, supplier_id, supplier_reference,
    name, description, short_description, cost_price, suggested_price, stock_quantity,
    primary_image_url, images, ncm_code, weight_g, height_cm, width_cm, length_cm,
    dimensions_display, box_length_cm, box_width_cm, box_height_cm, box_weight_kg,
    box_volume_cm3, box_quantity, box_inner_quantity, brand, packing_type, repacking_type,
    capacities, capacity_ml, min_quantity, warranty_months, ipi_rate, engraving_type, is_active,
    status, validation_errors, standardized_at
  ) VALUES (
    r.id, r.supplier_id, r.supplier_reference,
    v_assigns->>'name', v_assigns->>'description', v_assigns->>'short_description',
    (v_assigns->>'cost_price')::numeric, (v_assigns->>'suggested_price')::numeric, (v_assigns->>'stock_quantity')::integer,
    v_assigns->>'primary_image_url',
    CASE WHEN v_assigns ? 'images' THEN (v_assigns->'images') ELSE NULL END,
    v_assigns->>'ncm_code', (v_assigns->>'weight_g')::integer,
    (v_assigns->>'height_cm')::numeric, (v_assigns->>'width_cm')::numeric, (v_assigns->>'length_cm')::numeric,
    v_assigns->>'dimensions_display',
    (v_assigns->>'box_length_cm')::numeric, (v_assigns->>'box_width_cm')::numeric, (v_assigns->>'box_height_cm')::numeric,
    (v_assigns->>'box_weight_kg')::numeric, (v_assigns->>'box_volume_cm3')::numeric,
    (v_assigns->>'box_quantity')::integer, (v_assigns->>'box_inner_quantity')::integer,
    v_assigns->>'brand', v_assigns->>'packing_type', v_assigns->>'repacking_type',
    v_assigns->>'capacities', (v_assigns->>'capacity_ml')::integer, (v_assigns->>'min_quantity')::integer,
    (v_assigns->>'warranty_months')::integer, (v_assigns->>'ipi_rate')::numeric, v_assigns->>'engraving_type',
    COALESCE((v_assigns->>'is_active')::boolean, true),
    CASE WHEN jsonb_array_length(v_errs) > 0 AND v_assigns->>'name' IS NULL THEN 'rejected' ELSE 'standardized' END,
    CASE WHEN jsonb_array_length(v_errs) > 0 THEN v_errs ELSE NULL END,
    now()
  )
  ON CONFLICT (supplier_id, supplier_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, name=EXCLUDED.name, description=EXCLUDED.description,
    short_description=EXCLUDED.short_description, cost_price=EXCLUDED.cost_price,
    suggested_price=EXCLUDED.suggested_price, stock_quantity=EXCLUDED.stock_quantity,
    primary_image_url=EXCLUDED.primary_image_url, images=EXCLUDED.images, ncm_code=EXCLUDED.ncm_code,
    weight_g=EXCLUDED.weight_g, height_cm=EXCLUDED.height_cm, width_cm=EXCLUDED.width_cm, length_cm=EXCLUDED.length_cm,
    dimensions_display=EXCLUDED.dimensions_display, box_length_cm=EXCLUDED.box_length_cm, box_width_cm=EXCLUDED.box_width_cm,
    box_height_cm=EXCLUDED.box_height_cm, box_weight_kg=EXCLUDED.box_weight_kg, box_volume_cm3=EXCLUDED.box_volume_cm3,
    box_quantity=EXCLUDED.box_quantity, box_inner_quantity=EXCLUDED.box_inner_quantity, brand=EXCLUDED.brand,
    packing_type=EXCLUDED.packing_type, repacking_type=EXCLUDED.repacking_type, capacities=EXCLUDED.capacities,
    capacity_ml=EXCLUDED.capacity_ml, min_quantity=EXCLUDED.min_quantity, warranty_months=EXCLUDED.warranty_months,
    ipi_rate=EXCLUDED.ipi_rate, engraving_type=EXCLUDED.engraving_type, is_active=EXCLUDED.is_active,
    status=EXCLUDED.status, validation_errors=EXCLUDED.validation_errors, standardized_at=now(), updated_at=now()
  RETURNING pad.id INTO v_pad_id;

  RETURN jsonb_build_object('success', true, 'padronizacao_id', v_pad_id,
                            'campos', (SELECT count(*) FROM jsonb_object_keys(v_assigns)),
                            'erros', v_errs);
END;
$$;

COMMENT ON FUNCTION public.fn_standardize_raw(uuid) IS
  'Padronizador bronze→silver: aplica de-para + equivalências, normaliza NCM, grava produtos_padronizacao.';

