-- >>> BEGIN 20260604184447_spot_v2_fix_products_depara_and_cost.sql >>>
-- ============================================================
-- Paridade Spot → fn_process_raw_v2 : correções CRÍTICAS (config-only)
-- Projeto pqpdolkaeqlyzpdpbizo · Spot supplier_id bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0
-- ============================================================

-- G1) De-para de products morto: os 7 mappings ativos guardavam source_path em
--     JSONPath ('$.Name'), mas a v2 (e o motor genérico) resolvem source_path
--     como caminho separado por ponto via #>> → '$.Name' = {'$','Name'} → NULL,
--     então name/description/brand/origin/box_* nunca eram gravados.
--     source_field já está correto ('Name', ...). Zerando source_path, a v2 passa
--     a usar ->> source_field. (Cobertura no raw: 100%, origin 97,5%.)
UPDATE supplier_field_mappings
   SET source_path = NULL, updated_at = now()
 WHERE supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'
   AND target_table = 'products'
   AND source_path LIKE '$.%';

-- G2) Custo nunca gravado: a v2 só grava variant_supplier_sources se houver
--     mapping para essa tabela, e não havia nenhum. Recria o vínculo da legada
--     (cost_price = Price1). O trigger AFTER INSERT trg_supplier_source_price
--     propaga o custo para products.sale_price (markup do fornecedor).
INSERT INTO supplier_field_mappings
   (supplier_id, source_field, source_path, target_table, target_field,
    transform_type, is_active, priority, created_at, updated_at)
VALUES
   ('bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0', 'Price1', NULL,
    'variant_supplier_sources', 'cost_price', 'direct', true, 10, now(), now());

-- ============================================================
-- ROLLBACK (manual):
--   UPDATE supplier_field_mappings SET source_path = '$.' || source_field
--    WHERE supplier_id='bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0' AND target_table='products'
--      AND source_path IS NULL
--      AND source_field IN ('Name','Description','Brand','BoxWeightKG','BoxQuantity','CountryOfOrigin','ProdReference');
--   DELETE FROM supplier_field_mappings
--    WHERE supplier_id='bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'
--      AND target_table='variant_supplier_sources' AND target_field='cost_price' AND source_field='Price1';
-- ============================================================
-- <<< END 20260604184447_spot_v2_fix_products_depara_and_cost.sql <<<

-- >>> BEGIN 20260604184459_spot_v2_align_sku_prefix_to_catalog.sql >>>
-- ============================================================
-- Decisão de arquitetura — sku_prefix do Spot
-- Os 1.200 produtos Spot existentes usam sku = ProdReference PURO (0 com 'SPOT-').
-- supplier_settings.sku_prefix estava 'SPOT-', logo PRODUTOS NOVOS via v2 sairiam
-- com formato divergente do catálogo. products.sku é UNIQUE e chave natural
-- amplamente referenciada (contrato v_products_public, pedidos, URLs); reescrever
-- 1.200 skus seria arriscado. Alinhamos os NOVOS ao padrão vigente (sem prefixo),
-- mantendo o catálogo uniforme sem tocar nas chaves existentes.
-- (Alternativa futura: padronizar tudo em 'SPOT-' via migração dedicada que
--  atualize os 1.200 + todas as linhas que referenciam esses skus.)
UPDATE supplier_settings
   SET sku_prefix = '', updated_at = now()
 WHERE supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';

-- ROLLBACK: UPDATE supplier_settings SET sku_prefix='SPOT-' WHERE supplier_id='bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
-- ============================================================
-- <<< END 20260604184459_spot_v2_align_sku_prefix_to_catalog.sql <<<

-- >>> BEGIN 20260604184644_fn_process_raw_v2_parity_upgrade.sql >>>
CREATE OR REPLACE FUNCTION public.fn_process_raw_v2(p_supplier_id uuid, p_batch_size integer DEFAULT 100, p_bulk_mode boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_org_id            uuid;
    v_parent_key_source text;
    v_name_template     text;
    v_sku_prefix        text;
    v_prep              jsonb;
    v_parent            record;
    v_row               record;
    v_map               record;
    v_product_id        uuid;
    v_variant_id        uuid;
    v_vss_id            uuid;
    v_locked            text[];
    v_val               text;
    v_tv                text;
    v_parts             text[];
    v_vfields           jsonb;
    v_ssfields          jsonb;
    v_name              text;
    v_attrs             jsonb;
    v_sku               text;
    v_sup_sku           text;
    v_k                 text;
    v_v                 text;
    v_parents           integer := 0;
    v_variants          integer := 0;
    v_errors            jsonb := '[]'::jsonb;
    -- paridade: telemetria de batch + contadores de erro
    v_batch_id          uuid := gen_random_uuid();
    v_started           timestamptz := now();
    v_perr              integer := 0;
    v_verr              integer := 0;
BEGIN
    IF auth.uid() IS NOT NULL AND NOT is_admin_or_above((SELECT auth.uid())) THEN
        RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
    END IF;

    -- Escrita identificada como pipeline (evita auto-lock no trg_aa_capture_manual_edits)
    PERFORM set_config('app.write_source', 'pipeline', true);
    -- Suprime triggers pesados de enriquecimento durante processamento em massa
    PERFORM set_config('app.bulk_import_mode', p_bulk_mode::text, true);

    SELECT organization_id INTO v_org_id FROM suppliers WHERE id = p_supplier_id;

    SELECT parent_key_source, variant_name_template, sku_prefix
      INTO v_parent_key_source, v_name_template, v_sku_prefix
      FROM supplier_settings WHERE supplier_id = p_supplier_id;

    IF v_parent_key_source IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error', 'supplier_settings.parent_key_source ausente para o fornecedor '||p_supplier_id);
    END IF;
    v_name_template := COALESCE(v_name_template, '{product_name}');

    FOR v_parent IN
        SELECT DISTINCT raw_data->>v_parent_key_source AS pkey
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id AND processed = false
           AND NULLIF(raw_data->>v_parent_key_source,'') IS NOT NULL
         LIMIT p_batch_size
    LOOP
      BEGIN
        -- 1) Produto: achar ou criar por (supplier_id, supplier_reference = chave do pai)
        SELECT id INTO v_product_id
          FROM products
         WHERE supplier_id = p_supplier_id AND supplier_reference = v_parent.pkey;

        IF v_product_id IS NULL THEN
            INSERT INTO products (organization_id, supplier_id, supplier_reference, sku, name,
                                  active, is_active, sync_status, created_at, updated_at)
            VALUES (v_org_id, p_supplier_id, v_parent.pkey,
                    COALESCE(v_sku_prefix,'')||v_parent.pkey,
                    'Produto '||v_parent.pkey, true, true, 'processing', now(), now())
            RETURNING id INTO v_product_id;
        END IF;

        -- Campos travados pela curadoria humana (não sobrescrever)
        SELECT COALESCE(locked_fields, '{}'::text[]) INTO v_locked
          FROM products WHERE id = v_product_id;

        -- paridade: usa a linha MAIS RECENTE do pai (legada usava imported_at DESC)
        SELECT raw_data INTO v_prep
          FROM supplier_products_raw
         WHERE supplier_id=p_supplier_id AND processed=false
           AND raw_data->>v_parent_key_source = v_parent.pkey
         ORDER BY imported_at DESC NULLS LAST LIMIT 1;

        -- 2) Campos de produto (pulando os travados)
        v_parts := ARRAY[]::text[];
        FOR v_map IN
            SELECT * FROM supplier_field_mappings
             WHERE supplier_id=p_supplier_id AND target_table='products' AND is_active=true
             ORDER BY priority
        LOOP
            CONTINUE WHEN v_map.target_field = ANY(v_locked);
            v_val := CASE WHEN v_map.source_path IS NOT NULL
                          THEN v_prep #>> string_to_array(v_map.source_path,'.')
                          ELSE v_prep ->> v_map.source_field END;
            CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
            v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                       v_map.source_unit, v_map.target_unit, p_supplier_id);
            IF v_tv IS NOT NULL THEN
                v_parts := array_append(v_parts, format('%I = %L', v_map.target_field, v_tv));
            END IF;
        END LOOP;

        IF array_length(v_parts,1) > 0 THEN
            EXECUTE format(
              'UPDATE products SET %s, updated_at=now(), sync_status=''synced'', last_sync_at=now(), last_sync_supplier_id=%L WHERE id=%L',
              array_to_string(v_parts,', '), p_supplier_id, v_product_id);
        END IF;

        UPDATE products
           SET dimensions_display = fn_format_dimensions_display(length_cm, width_cm, height_cm)
         WHERE id = v_product_id AND length_cm IS NOT NULL
           AND NOT ('dimensions_display' = ANY(v_locked));

        -- 3) Variantes
        FOR v_row IN
            SELECT * FROM supplier_products_raw
             WHERE supplier_id=p_supplier_id AND processed=false
               AND raw_data->>v_parent_key_source = v_parent.pkey
        LOOP
          BEGIN
            v_vfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id=p_supplier_id AND target_table='product_variants' AND is_active=true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path,'.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_vfields := v_vfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            v_name := replace(v_name_template, '{product_name}',
                              COALESCE((SELECT name FROM products WHERE id=v_product_id),''));
            v_name := replace(v_name, '{color_name}', COALESCE(v_vfields->>'color_name',''));
            v_name := btrim(regexp_replace(v_name, '\s*[|-]\s*$', ''));
            v_attrs := jsonb_build_object('codigo_cor', COALESCE(v_vfields->>'color_code',''),
                                          'cor',        COALESCE(v_vfields->>'color_name',''));

            v_sup_sku := NULLIF(v_row.supplier_sku, '');
            v_variant_id := NULL;
            IF v_sup_sku IS NOT NULL THEN
                SELECT id INTO v_variant_id FROM product_variants
                 WHERE product_id = v_product_id AND supplier_sku = v_sup_sku;
            END IF;

            IF v_variant_id IS NULL THEN
                v_sku := COALESCE(v_vfields->>'sku', v_sup_sku, v_row.supplier_reference);
                INSERT INTO product_variants (product_id, sku, supplier_sku, name,
                                              color_code, color_name, color_hex, attributes, is_active, created_at, updated_at)
                VALUES (v_product_id, v_sku, v_sup_sku, v_name,
                        v_vfields->>'color_code', v_vfields->>'color_name', v_vfields->>'color_hex',
                        v_attrs, true, now(), now())
                ON CONFLICT (sku) DO UPDATE SET
                    supplier_sku=EXCLUDED.supplier_sku, name=EXCLUDED.name, color_code=EXCLUDED.color_code,
                    color_name=EXCLUDED.color_name, color_hex=EXCLUDED.color_hex, attributes=EXCLUDED.attributes,
                    updated_at=now()
                RETURNING id INTO v_variant_id;
            ELSE
                UPDATE product_variants SET
                    name=v_name, color_code=v_vfields->>'color_code', color_name=v_vfields->>'color_name',
                    color_hex=v_vfields->>'color_hex', attributes=v_attrs, updated_at=now()
                WHERE id=v_variant_id;
            END IF;

            v_parts := ARRAY[]::text[];
            FOR v_k, v_v IN
                SELECT key, value FROM jsonb_each_text(
                    v_vfields - 'sku' - 'supplier_sku' - 'color_code' - 'color_name' - 'color_hex')
            LOOP
                v_parts := array_append(v_parts, format('%I = %L', v_k, v_v));
            END LOOP;
            IF array_length(v_parts,1) > 0 THEN
                EXECUTE format('UPDATE product_variants SET %s, updated_at=now() WHERE id=%L',
                               array_to_string(v_parts,', '), v_variant_id);
            END IF;

            v_ssfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id=p_supplier_id AND target_table='variant_supplier_sources' AND is_active=true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path,'.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_ssfields := v_ssfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            IF v_ssfields <> '{}'::jsonb THEN
                SELECT id INTO v_vss_id FROM variant_supplier_sources
                 WHERE variant_id=v_variant_id AND supplier_id=p_supplier_id;
                IF v_vss_id IS NULL THEN
                    INSERT INTO variant_supplier_sources (organization_id, variant_id, supplier_id, supplier_sku,
                                                          cost_price, quantity, source, is_preferred, is_active, updated_at)
                    VALUES (v_org_id, v_variant_id, p_supplier_id, v_sup_sku,
                            NULLIF(v_ssfields->>'cost_price','')::numeric,
                            COALESCE(NULLIF(v_ssfields->>'quantity','')::integer, 0),
                            'raw_v2', true, true, now());
                ELSE
                    UPDATE variant_supplier_sources SET
                        cost_price = COALESCE(NULLIF(v_ssfields->>'cost_price','')::numeric, cost_price),
                        quantity   = COALESCE(NULLIF(v_ssfields->>'quantity','')::integer, quantity),
                        updated_at = now()
                    WHERE id=v_vss_id;
                END IF;
            END IF;

            -- paridade: carimba import_batch_id e limpa erro anterior em caso de sucesso
            UPDATE supplier_products_raw
               SET processed=true, processed_at=now(), product_id=v_product_id, variant_id=v_variant_id,
                   import_batch_id=v_batch_id, process_errors=NULL
             WHERE id=v_row.id;
            v_variants := v_variants + 1;

          EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors || jsonb_build_object('raw_id', v_row.id, 'stage','variant', 'error', SQLERRM);
            v_verr := v_verr + 1;
            -- paridade: persiste o erro na própria linha raw (como a legada)
            UPDATE supplier_products_raw
               SET process_errors = jsonb_build_object('error', SQLERRM, 'stage','variant', 'timestamp', now())
             WHERE id = v_row.id;
          END;
        END LOOP;

        v_parents := v_parents + 1;
      EXCEPTION WHEN OTHERS THEN
        v_errors := v_errors || jsonb_build_object('parent_key', v_parent.pkey, 'stage','parent', 'error', SQLERRM);
        v_perr := v_perr + 1;
        UPDATE supplier_products_raw
           SET process_errors = jsonb_build_object('error', SQLERRM, 'stage','parent', 'timestamp', now())
         WHERE supplier_id=p_supplier_id AND processed=false
           AND raw_data->>v_parent_key_source = v_parent.pkey;
      END;
    END LOOP;

    -- paridade (telemetria) SEM batches-zumbi: só registra o batch se houve trabalho ou erro
    IF v_parents > 0 OR v_variants > 0 OR v_errors <> '[]'::jsonb THEN
        INSERT INTO supplier_import_batches
            (id, supplier_id, started_at, finished_at, status,
             products_imported, variants_imported, products_errors, variants_errors, error_log)
        VALUES
            (v_batch_id, p_supplier_id, v_started, now(), 'completed',
             v_parents, v_variants, v_perr, v_verr, v_errors);
    END IF;

    RETURN jsonb_build_object(
        'success', true, 'supplier_id', p_supplier_id, 'bulk_mode', p_bulk_mode,
        'batch_id', CASE WHEN (v_parents>0 OR v_variants>0 OR v_errors <> '[]'::jsonb) THEN v_batch_id ELSE NULL END,
        'parents_processed', v_parents, 'variants_processed', v_variants,
        'products_errors', v_perr, 'variants_errors', v_verr, 'errors', v_errors);
END;
$function$;
-- <<< END 20260604184644_fn_process_raw_v2_parity_upgrade.sql <<<

-- >>> BEGIN 20260604185153_fix_search_path_unaccent_functions.sql >>>
-- ============================================================
-- Corrige search_path das ÚNICAS 2 funções que usam unaccent() sem 'extensions'
-- no caminho de busca. unaccent vive no schema 'extensions'; ~50 funções irmãs já
-- têm search_path='public, extensions'. Estas duas foram esquecidas.
--
-- products_search_vector_update: trigger trg_products_search_vector em products.
--   Sem search_path, ao ser disparada sob fn_process_raw_v2 (search_path=public),
--   não resolve unaccent() e ABORTA todo INSERT/UPDATE de products vindo do pipeline.
--   (Bug latente: derrubaria qualquer importação Spot real, não só o dry-run.)
-- fn_safe_bool: protegida por EXCEPTION, mas cai no fallback sem acento toda vez;
--   alinhada por consistência.
-- ============================================================
ALTER FUNCTION public.products_search_vector_update() SET search_path = public, extensions;
ALTER FUNCTION public.fn_safe_bool(text)            SET search_path = public, extensions;

-- ROLLBACK:
--   ALTER FUNCTION public.products_search_vector_update() RESET search_path;
--   ALTER FUNCTION public.fn_safe_bool(text) RESET search_path;
-- ============================================================
-- <<< END 20260604185153_fix_search_path_unaccent_functions.sql <<<

-- >>> BEGIN 20260604185419_fn_process_raw_v2_fix_batch_fk_order.sql >>>
CREATE OR REPLACE FUNCTION public.fn_process_raw_v2(p_supplier_id uuid, p_batch_size integer DEFAULT 100, p_bulk_mode boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_org_id            uuid;
    v_parent_key_source text;
    v_name_template     text;
    v_sku_prefix        text;
    v_prep              jsonb;
    v_parent            record;
    v_row               record;
    v_map               record;
    v_product_id        uuid;
    v_variant_id        uuid;
    v_vss_id            uuid;
    v_locked            text[];
    v_val               text;
    v_tv                text;
    v_parts             text[];
    v_vfields           jsonb;
    v_ssfields          jsonb;
    v_name              text;
    v_attrs             jsonb;
    v_sku               text;
    v_sup_sku           text;
    v_k                 text;
    v_v                 text;
    v_parents           integer := 0;
    v_variants          integer := 0;
    v_errors            jsonb := '[]'::jsonb;
    -- paridade: telemetria de batch + contadores de erro
    v_batch_id          uuid := gen_random_uuid();
    v_started           timestamptz := now();
    v_perr              integer := 0;
    v_verr              integer := 0;
    v_batch_open        boolean := false;
BEGIN
    IF auth.uid() IS NOT NULL AND NOT is_admin_or_above((SELECT auth.uid())) THEN
        RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
    END IF;

    -- Escrita identificada como pipeline (evita auto-lock no trg_aa_capture_manual_edits)
    PERFORM set_config('app.write_source', 'pipeline', true);
    -- Suprime triggers pesados de enriquecimento durante processamento em massa
    PERFORM set_config('app.bulk_import_mode', p_bulk_mode::text, true);

    SELECT organization_id INTO v_org_id FROM suppliers WHERE id = p_supplier_id;

    SELECT parent_key_source, variant_name_template, sku_prefix
      INTO v_parent_key_source, v_name_template, v_sku_prefix
      FROM supplier_settings WHERE supplier_id = p_supplier_id;

    IF v_parent_key_source IS NULL THEN
        RETURN jsonb_build_object('success', false,
            'error', 'supplier_settings.parent_key_source ausente para o fornecedor '||p_supplier_id);
    END IF;
    v_name_template := COALESCE(v_name_template, '{product_name}');

    -- paridade (telemetria) SEM batches-zumbi: abre o batch ANTES do loop, mas só se
    -- houver linhas pendentes (necessário para satisfazer a FK raw.import_batch_id).
    IF EXISTS (SELECT 1 FROM supplier_products_raw
                WHERE supplier_id=p_supplier_id AND processed=false
                  AND NULLIF(raw_data->>v_parent_key_source,'') IS NOT NULL) THEN
        INSERT INTO supplier_import_batches (id, supplier_id, started_at, status)
        VALUES (v_batch_id, p_supplier_id, v_started, 'processing');
        v_batch_open := true;
    END IF;

    FOR v_parent IN
        SELECT DISTINCT raw_data->>v_parent_key_source AS pkey
          FROM supplier_products_raw
         WHERE supplier_id = p_supplier_id AND processed = false
           AND NULLIF(raw_data->>v_parent_key_source,'') IS NOT NULL
         LIMIT p_batch_size
    LOOP
      BEGIN
        -- 1) Produto: achar ou criar por (supplier_id, supplier_reference = chave do pai)
        SELECT id INTO v_product_id
          FROM products
         WHERE supplier_id = p_supplier_id AND supplier_reference = v_parent.pkey;

        IF v_product_id IS NULL THEN
            INSERT INTO products (organization_id, supplier_id, supplier_reference, sku, name,
                                  active, is_active, sync_status, created_at, updated_at)
            VALUES (v_org_id, p_supplier_id, v_parent.pkey,
                    COALESCE(v_sku_prefix,'')||v_parent.pkey,
                    'Produto '||v_parent.pkey, true, true, 'processing', now(), now())
            RETURNING id INTO v_product_id;
        END IF;

        -- Campos travados pela curadoria humana (não sobrescrever)
        SELECT COALESCE(locked_fields, '{}'::text[]) INTO v_locked
          FROM products WHERE id = v_product_id;

        -- paridade: usa a linha MAIS RECENTE do pai (legada usava imported_at DESC)
        SELECT raw_data INTO v_prep
          FROM supplier_products_raw
         WHERE supplier_id=p_supplier_id AND processed=false
           AND raw_data->>v_parent_key_source = v_parent.pkey
         ORDER BY imported_at DESC NULLS LAST LIMIT 1;

        -- 2) Campos de produto (pulando os travados)
        v_parts := ARRAY[]::text[];
        FOR v_map IN
            SELECT * FROM supplier_field_mappings
             WHERE supplier_id=p_supplier_id AND target_table='products' AND is_active=true
             ORDER BY priority
        LOOP
            CONTINUE WHEN v_map.target_field = ANY(v_locked);
            v_val := CASE WHEN v_map.source_path IS NOT NULL
                          THEN v_prep #>> string_to_array(v_map.source_path,'.')
                          ELSE v_prep ->> v_map.source_field END;
            CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
            v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                       v_map.source_unit, v_map.target_unit, p_supplier_id);
            IF v_tv IS NOT NULL THEN
                v_parts := array_append(v_parts, format('%I = %L', v_map.target_field, v_tv));
            END IF;
        END LOOP;

        IF array_length(v_parts,1) > 0 THEN
            EXECUTE format(
              'UPDATE products SET %s, updated_at=now(), sync_status=''synced'', last_sync_at=now(), last_sync_supplier_id=%L WHERE id=%L',
              array_to_string(v_parts,', '), p_supplier_id, v_product_id);
        END IF;

        UPDATE products
           SET dimensions_display = fn_format_dimensions_display(length_cm, width_cm, height_cm)
         WHERE id = v_product_id AND length_cm IS NOT NULL
           AND NOT ('dimensions_display' = ANY(v_locked));

        -- 3) Variantes
        FOR v_row IN
            SELECT * FROM supplier_products_raw
             WHERE supplier_id=p_supplier_id AND processed=false
               AND raw_data->>v_parent_key_source = v_parent.pkey
        LOOP
          BEGIN
            v_vfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id=p_supplier_id AND target_table='product_variants' AND is_active=true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path,'.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_vfields := v_vfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            v_name := replace(v_name_template, '{product_name}',
                              COALESCE((SELECT name FROM products WHERE id=v_product_id),''));
            v_name := replace(v_name, '{color_name}', COALESCE(v_vfields->>'color_name',''));
            v_name := btrim(regexp_replace(v_name, '\s*[|-]\s*$', ''));
            v_attrs := jsonb_build_object('codigo_cor', COALESCE(v_vfields->>'color_code',''),
                                          'cor',        COALESCE(v_vfields->>'color_name',''));

            v_sup_sku := NULLIF(v_row.supplier_sku, '');
            v_variant_id := NULL;
            IF v_sup_sku IS NOT NULL THEN
                SELECT id INTO v_variant_id FROM product_variants
                 WHERE product_id = v_product_id AND supplier_sku = v_sup_sku;
            END IF;

            IF v_variant_id IS NULL THEN
                v_sku := COALESCE(v_vfields->>'sku', v_sup_sku, v_row.supplier_reference);
                INSERT INTO product_variants (product_id, sku, supplier_sku, name,
                                              color_code, color_name, color_hex, attributes, is_active, created_at, updated_at)
                VALUES (v_product_id, v_sku, v_sup_sku, v_name,
                        v_vfields->>'color_code', v_vfields->>'color_name', v_vfields->>'color_hex',
                        v_attrs, true, now(), now())
                ON CONFLICT (sku) DO UPDATE SET
                    supplier_sku=EXCLUDED.supplier_sku, name=EXCLUDED.name, color_code=EXCLUDED.color_code,
                    color_name=EXCLUDED.color_name, color_hex=EXCLUDED.color_hex, attributes=EXCLUDED.attributes,
                    updated_at=now()
                RETURNING id INTO v_variant_id;
            ELSE
                UPDATE product_variants SET
                    name=v_name, color_code=v_vfields->>'color_code', color_name=v_vfields->>'color_name',
                    color_hex=v_vfields->>'color_hex', attributes=v_attrs, updated_at=now()
                WHERE id=v_variant_id;
            END IF;

            v_parts := ARRAY[]::text[];
            FOR v_k, v_v IN
                SELECT key, value FROM jsonb_each_text(
                    v_vfields - 'sku' - 'supplier_sku' - 'color_code' - 'color_name' - 'color_hex')
            LOOP
                v_parts := array_append(v_parts, format('%I = %L', v_k, v_v));
            END LOOP;
            IF array_length(v_parts,1) > 0 THEN
                EXECUTE format('UPDATE product_variants SET %s, updated_at=now() WHERE id=%L',
                               array_to_string(v_parts,', '), v_variant_id);
            END IF;

            v_ssfields := '{}'::jsonb;
            FOR v_map IN
                SELECT * FROM supplier_field_mappings
                 WHERE supplier_id=p_supplier_id AND target_table='variant_supplier_sources' AND is_active=true
                 ORDER BY priority
            LOOP
                v_val := CASE WHEN v_map.source_path IS NOT NULL
                              THEN v_row.raw_data #>> string_to_array(v_map.source_path,'.')
                              ELSE v_row.raw_data ->> v_map.source_field END;
                CONTINUE WHEN v_val IS NULL OR btrim(v_val)='';
                v_tv := fn_apply_transform(v_val, v_map.transform_type, v_map.transform_config,
                                           v_map.source_unit, v_map.target_unit, p_supplier_id);
                IF v_tv IS NOT NULL THEN
                    v_ssfields := v_ssfields || jsonb_build_object(v_map.target_field, v_tv);
                END IF;
            END LOOP;

            IF v_ssfields <> '{}'::jsonb THEN
                SELECT id INTO v_vss_id FROM variant_supplier_sources
                 WHERE variant_id=v_variant_id AND supplier_id=p_supplier_id;
                IF v_vss_id IS NULL THEN
                    INSERT INTO variant_supplier_sources (organization_id, variant_id, supplier_id, supplier_sku,
                                                          cost_price, quantity, source, is_preferred, is_active, updated_at)
                    VALUES (v_org_id, v_variant_id, p_supplier_id, v_sup_sku,
                            NULLIF(v_ssfields->>'cost_price','')::numeric,
                            COALESCE(NULLIF(v_ssfields->>'quantity','')::integer, 0),
                            'raw_v2', true, true, now());
                ELSE
                    UPDATE variant_supplier_sources SET
                        cost_price = COALESCE(NULLIF(v_ssfields->>'cost_price','')::numeric, cost_price),
                        quantity   = COALESCE(NULLIF(v_ssfields->>'quantity','')::integer, quantity),
                        updated_at = now()
                    WHERE id=v_vss_id;
                END IF;
            END IF;

            -- paridade: carimba import_batch_id (FK satisfeita: batch já aberto) e limpa erro anterior
            UPDATE supplier_products_raw
               SET processed=true, processed_at=now(), product_id=v_product_id, variant_id=v_variant_id,
                   import_batch_id = CASE WHEN v_batch_open THEN v_batch_id ELSE NULL END,
                   process_errors=NULL
             WHERE id=v_row.id;
            v_variants := v_variants + 1;

          EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors || jsonb_build_object('raw_id', v_row.id, 'stage','variant', 'error', SQLERRM);
            v_verr := v_verr + 1;
            -- paridade: persiste o erro na própria linha raw (como a legada)
            UPDATE supplier_products_raw
               SET process_errors = jsonb_build_object('error', SQLERRM, 'stage','variant', 'timestamp', now())
             WHERE id = v_row.id;
          END;
        END LOOP;

        v_parents := v_parents + 1;
      EXCEPTION WHEN OTHERS THEN
        v_errors := v_errors || jsonb_build_object('parent_key', v_parent.pkey, 'stage','parent', 'error', SQLERRM);
        v_perr := v_perr + 1;
        UPDATE supplier_products_raw
           SET process_errors = jsonb_build_object('error', SQLERRM, 'stage','parent', 'timestamp', now())
         WHERE supplier_id=p_supplier_id AND processed=false
           AND raw_data->>v_parent_key_source = v_parent.pkey;
      END;
    END LOOP;

    -- finaliza o batch (se aberto): conta resultados, marca concluído
    IF v_batch_open THEN
        UPDATE supplier_import_batches
           SET finished_at=now(), status='completed',
               products_imported=v_parents, variants_imported=v_variants,
               products_errors=v_perr, variants_errors=v_verr, error_log=v_errors
         WHERE id=v_batch_id;
    END IF;

    RETURN jsonb_build_object(
        'success', true, 'supplier_id', p_supplier_id, 'bulk_mode', p_bulk_mode,
        'batch_id', CASE WHEN v_batch_open THEN v_batch_id ELSE NULL END,
        'parents_processed', v_parents, 'variants_processed', v_variants,
        'products_errors', v_perr, 'variants_errors', v_verr, 'errors', v_errors);
END;
$function$;
-- <<< END 20260604185419_fn_process_raw_v2_fix_batch_fk_order.sql <<<

-- >>> BEGIN 20260604185737_spot_v2_map_products_cost_price.sql >>>
-- ============================================================
-- Preço de venda dos produtos NOVOS: o trigger BEFORE trg_calculate_sale_price
-- (products) calcula sale_price = products.cost_price * (1 + default_markup_percent/100).
-- Os 1.200 produtos Spot existentes têm products.cost_price preenchido (1200/1200);
-- a v2 não preenchia → produtos novos ficariam sem cost_price e sem sale_price,
-- divergindo do catálogo. Mapeamos products.cost_price = Price1 (mesma origem do
-- custo de VSS), restaurando a consistência e habilitando o cálculo automático do
-- preço (markup 115% do fornecedor). Price1 cobre 100% do raw.
INSERT INTO supplier_field_mappings
   (supplier_id, source_field, source_path, target_table, target_field,
    transform_type, is_active, priority, created_at, updated_at)
VALUES
   ('bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0', 'Price1', NULL,
    'products', 'cost_price', 'direct', true, 10, now(), now());

-- ROLLBACK:
