-- >>> BEGIN 20260605011613_fix_purge_history_security_and_history_indexes.sql >>>
-- Correções detectadas na auditoria exaustiva pós-refactor:
--
-- 1) fn_purge_spr_history: criada com SECURITY DEFINER mas sem REVOKE do grant
--    padrão PUBLIC/anon → qualquer usuário anônimo podia chamar via REST API
--    (GET /rest/v1/rpc/fn_purge_spr_history?p_keep_days=1) e apagar todo o
--    histórico. Restrita a service_role + postgres.
--
-- 2) supplier_products_raw_history: FK supplier_id sem índice (advisor
--    unindexed_foreign_keys) e captured_at sem índice (penaliza fn_purge_spr_history
--    que filtra WHERE captured_at < ...).

-- 1) Revoga execução pública de fn_purge_spr_history
REVOKE EXECUTE ON FUNCTION public.fn_purge_spr_history(integer) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_purge_spr_history(integer) FROM anon;
REVOKE EXECUTE ON FUNCTION public.fn_purge_spr_history(integer) FROM authenticated;
GRANT  EXECUTE ON FUNCTION public.fn_purge_spr_history(integer) TO service_role;

-- 2) Índice no FK supplier_id (JOIN frequente com suppliers)
CREATE INDEX IF NOT EXISTS idx_spr_hist_supplier
  ON public.supplier_products_raw_history (supplier_id);

-- 3) Índice em captured_at para que fn_purge_spr_history e queries de auditoria
--    não façam seq scan em tabela de crescimento ilimitado
CREATE INDEX IF NOT EXISTS idx_spr_hist_captured_at
  ON public.supplier_products_raw_history (captured_at);
-- <<< END 20260605011613_fix_purge_history_security_and_history_indexes.sql <<<

-- >>> BEGIN 20260605011638_pad_silver_p0_indexes_checks_rls.sql >>>
-- (3) FK raw_id sem índice -> cria índice
CREATE INDEX IF NOT EXISTS idx_pad_raw ON public.produtos_padronizacao(raw_id);

-- (2) Invariante do fluxo medallion: promoted exige product_id
ALTER TABLE public.produtos_padronizacao
  ADD CONSTRAINT chk_promoted_requires_gold
  CHECK (status <> 'promoted' OR product_id IS NOT NULL);

-- (6) supplier_reference nunca em branco (parte da chave natural)
ALTER TABLE public.produtos_padronizacao
  ADD CONSTRAINT chk_supplier_reference_not_blank
  CHECK (btrim(supplier_reference) <> '');

-- (6) is_active deixa de aceitar NULL
ALTER TABLE public.produtos_padronizacao ALTER COLUMN is_active SET DEFAULT true;
UPDATE public.produtos_padronizacao SET is_active = true WHERE is_active IS NULL;
ALTER TABLE public.produtos_padronizacao ALTER COLUMN is_active SET NOT NULL;

-- (1) RLS + fechar anon (escrita destrutiva pública)
ALTER TABLE public.produtos_padronizacao ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.produtos_padronizacao FROM anon;
DROP POLICY IF EXISTS pad_authenticated_all ON public.produtos_padronizacao;
CREATE POLICY pad_authenticated_all ON public.produtos_padronizacao
  FOR ALL TO authenticated USING (true) WITH CHECK (true);
-- service_role ignora RLS (pipeline N8N permanece intacto)
-- <<< END 20260605011638_pad_silver_p0_indexes_checks_rls.sql <<<

