-- >>> BEGIN 20260605011700_pad_silver_comments_documentation.sql >>>
COMMENT ON TABLE public.produtos_padronizacao IS
'Camada SILVER (medallion). Conforma produtos do BRONZE (supplier_products_raw via raw_id) e os equivale ao GOLD (products via product_id). Fluxo: pending -> standardized -> promoted | rejected. Escrita via service_role (pipeline N8N); leitura via authenticated (RLS habilitado).';

COMMENT ON COLUMN public.produtos_padronizacao.raw_id IS 'FK -> supplier_products_raw (BRONZE). NULL se a origem raw foi removida.';
COMMENT ON COLUMN public.produtos_padronizacao.product_id IS 'FK -> products (GOLD). Equivalencia silver->gold. Preenchido quando status=promoted.';
COMMENT ON COLUMN public.produtos_padronizacao.status IS 'Estado no pipeline: pending|standardized|rejected|promoted. promoted exige product_id (chk_promoted_requires_gold).';
COMMENT ON COLUMN public.produtos_padronizacao.cost_price IS 'STAGING. Custo de entrada do fornecedor. Fonte canonica de custo por faixa: supplier_price_tiers. ~80% NULL por design.';
COMMENT ON COLUMN public.produtos_padronizacao.colors IS 'STAGING jsonb. Cores cruas do fornecedor. Normalizacao canonica: color_equivalences / supplier_colors.';
COMMENT ON COLUMN public.produtos_padronizacao.images IS 'STAGING jsonb. URLs cruas. Normalizacao canonica: product_images.';
COMMENT ON COLUMN public.produtos_padronizacao.validation_errors IS 'jsonb. Erros de validacao acumulados (preenchido quando status=rejected).';
COMMENT ON COLUMN public.produtos_padronizacao.supplier_reference IS 'Referencia do produto no fornecedor. Parte da chave natural (supplier_id, supplier_reference).';
-- <<< END 20260605011700_pad_silver_comments_documentation.sql <<<

-- >>> BEGIN 20260605011952_fix_fn_apply_transform_multiply_null_config_guard.sql >>>

-- Fix: multiply/divide com config NULL → retorna original em vez de NULL
CREATE OR REPLACE FUNCTION public.fn_apply_transform(
    p_value text,
    p_transform_type character varying,
    p_transform_config jsonb,
    p_source_unit character varying,
    p_target_unit character varying,
    p_supplier_id uuid
)
RETURNS text
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $function$
DECLARE
    v_result     TEXT;
    v_numeric    DECIMAL;
    v_multiplier DECIMAL;
    v_fn         VARCHAR;
    v_pattern    TEXT;
    v_group      INTEGER;
    v_matches    TEXT[];
BEGIN
    IF p_value IS NULL OR TRIM(p_value) = '' THEN
        RETURN NULL;
    END IF;

    CASE p_transform_type

        WHEN 'direct' THEN
            v_result := p_value;

        WHEN 'multiply' THEN
            BEGIN
                v_multiplier := COALESCE(
                    (p_transform_config->>'multiplier')::DECIMAL,
                    (p_transform_config->>'factor')::DECIMAL
                );
                -- Guard: sem config ou multiplier NULL → retorna original
                IF v_multiplier IS NULL THEN
                    RETURN p_value;
                END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM
                              TRIM(TRAILING '0' FROM
                                ROUND(v_numeric * v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'divide' THEN
            BEGIN
                v_multiplier := COALESCE(
                    (p_transform_config->>'divisor')::DECIMAL,
                    (p_transform_config->>'factor')::DECIMAL
                );
                -- Guard: sem config ou divisor NULL/zero → retorna original
                IF v_multiplier IS NULL OR v_multiplier = 0 THEN
                    RETURN p_value;
                END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM
                              TRIM(TRAILING '0' FROM
                                ROUND(v_numeric / v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'convert_unit' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_result := fn_convert_unit(v_numeric, p_source_unit, p_target_unit, p_supplier_id)::TEXT;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'lookup' THEN
            v_result := fn_map_value(p_supplier_id, p_transform_config->>'lookup_type', p_value);

        WHEN 'custom' THEN
            BEGIN
                v_fn := p_transform_config->>'function';
                CASE v_fn
                    WHEN 'fn_parse_capacity_ml' THEN
                        v_result := fn_parse_capacity_ml(p_value)::TEXT;
                    WHEN 'fn_convert_box_dimension_to_cm' THEN
                        v_result := fn_convert_box_dimension_to_cm(p_value)::TEXT;
                    ELSE
                        v_result := p_value;
                END CASE;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'prefix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'prefix' IS NOT NULL THEN
                v_result := (p_transform_config->>'prefix') || p_value;
            ELSE
                v_result := p_value;
            END IF;

        WHEN 'suffix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'suffix' IS NOT NULL THEN
                v_result := p_value || (p_transform_config->>'suffix');
            ELSE
                v_result := p_value;
            END IF;

        WHEN 'uppercase'    THEN v_result := UPPER(p_value);
        WHEN 'lowercase'    THEN v_result := LOWER(p_value);
        WHEN 'trim'         THEN v_result := BTRIM(p_value);

        WHEN 'replace' THEN
            IF p_transform_config IS NOT NULL THEN
                v_result := REPLACE(p_value,
                    COALESCE(p_transform_config->>'find', ''),
                    COALESCE(p_transform_config->>'replace', ''));
            ELSE
                v_result := p_value;
            END IF;

        WHEN 'regex_extract' THEN
            BEGIN
                v_pattern := p_transform_config->>'pattern';
                v_group   := COALESCE((p_transform_config->>'group')::INTEGER, 1);
                IF v_pattern IS NULL THEN RETURN p_value; END IF;
                v_matches := regexp_matches(p_value, v_pattern);
                IF array_length(v_matches, 1) >= v_group THEN
                    v_result := v_matches[v_group];
                ELSE
                    v_result := NULL;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        ELSE
            v_result := p_value;

    END CASE;

    RETURN v_result;
END;
$function$;

COMMENT ON FUNCTION public.fn_apply_transform(text, varchar, jsonb, varchar, varchar, uuid)
IS 'Transform pipeline v2.2 — Fix: multiply/divide com config NULL retorna original. Guards completos para todos os casos.';

-- <<< END 20260605011952_fix_fn_apply_transform_multiply_null_config_guard.sql <<<

-- >>> BEGIN 20260605012110_spr_p0_fix_content_hash_sha256.sql >>>
CREATE OR REPLACE FUNCTION public.fn_spr_before_write()
RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $$
DECLARE v_clean jsonb;
BEGIN
  IF NEW.raw_data ? '_source' AND COALESCE(NEW.source_channel,'') IN ('','n8n','legacy') THEN
    NEW.source_channel := NEW.raw_data->>'_source';
  END IF;
  IF NEW.raw_data ? '_imported_at' AND NEW.imported_at IS NULL THEN
    BEGIN NEW.imported_at := (NEW.raw_data->>'_imported_at')::timestamptz;
    EXCEPTION WHEN others THEN NULL; END;
  END IF;

  v_clean := NEW.raw_data - '_source' - '_api_fields_count' - '_imported_at';
  NEW.raw_data     := v_clean;
  NEW.content_hash := encode(digest(v_clean::text,'sha256'),'hex');  -- era md5(): alinhado ao default e aos 16.508 registros existentes

  IF TG_OP = 'INSERT' THEN
    NEW.imported_at := COALESCE(NEW.imported_at, now());
    IF NEW.process_errors IS NOT NULL AND NEW.last_error IS NULL THEN
      NEW.last_error := NEW.process_errors;
    END IF;
  ELSE
    NEW.updated_at := now();
    IF NEW.process_errors IS DISTINCT FROM OLD.process_errors AND NEW.process_errors IS NOT NULL THEN
      NEW.last_error := NEW.process_errors;
      NEW.attempts   := COALESCE(OLD.attempts,0) + 1;
      IF NEW.status <> 'processed'::supplier_raw_status THEN
        NEW.status := CASE WHEN NEW.attempts >= 5 THEN 'quarantined'::supplier_raw_status
                           ELSE 'failed'::supplier_raw_status END;
      END IF;
    END IF;
    IF NEW.status = 'processed'::supplier_raw_status AND NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.processed_at := COALESCE(NEW.processed_at, now());
    END IF;
  END IF;
  RETURN NEW;
END $$;

COMMENT ON COLUMN public.supplier_products_raw.content_hash IS
  'sha256(raw_data limpo, hex) — SSOT de dedup/deteccao de mudanca. Mantido por fn_spr_before_write (trigger trg_spr_before_write).';

COMMENT ON COLUMN public.supplier_products_raw.raw_data IS
  'Payload original do fornecedor (imutavel). NAO gravar metadados de controle aqui — use source_channel/source_endpoint/imported_at. fn_spr_before_write remove chaves _* legadas e recalcula content_hash.';
-- <<< END 20260605012110_spr_p0_fix_content_hash_sha256.sql <<<

