-- >>> BEGIN 20260605014545_revoke_fn_process_raw_v2_execute_from_anon_authenticated.sql >>>
-- Segurança (auditoria PR #659): fn_process_raw_v2 é SECURITY DEFINER e seu
-- guard interno `IF auth.uid() IS NOT NULL AND NOT is_admin_or_above(...)` NÃO
-- protege chamadas anônimas (auth.uid() IS NULL pula o RAISE). Como anon e
-- authenticated têm EXECUTE por padrão (CREATE FUNCTION concede a PUBLIC),
-- qualquer requisição anônima ao endpoint PostgREST /rpc/fn_process_raw_v2
-- dispararia a importação com privilégios de definidor (escalação/integridade).
-- O motor é chamado apenas por service_role (edge functions / cron) e por
-- admins via outras rotas, então remover EXECUTE de PUBLIC/anon/authenticated
-- fecha o vetor sem afetar o pipeline.
REVOKE EXECUTE ON FUNCTION public.fn_process_raw_v2(uuid, integer, boolean) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_process_raw_v2(uuid, integer, boolean) FROM anon;
REVOKE EXECUTE ON FUNCTION public.fn_process_raw_v2(uuid, integer, boolean) FROM authenticated;
-- <<< END 20260605014545_revoke_fn_process_raw_v2_execute_from_anon_authenticated.sql <<<

-- >>> BEGIN 20260605014600_fix_vacuum_analyze_weekly_cron_no_vacuum_in_txn.sql >>>
-- Correção (auditoria PR #659): a migration 20260604231642 reintroduziu
-- `VACUUM ANALYZE` no job de cron 'vacuum-analyze-weekly'. pg_cron executa o
-- comando multi-statement dentro de um bloco de transação, e VACUUM não pode
-- rodar em transaction block -> o job falharia toda semana (sáb 02:00), como
-- já havia sido corrigido em 20260602_002_fix_cron_jobs_never_ran.sql.
-- Recriamos o job com ANALYZE-only (atualiza estatísticas dentro da transação).
-- O VACUUM real é coberto por autovacuum (tuning em 20260604231642 /
-- 20260605001917) e pode ser feito manualmente via Dashboard quando necessário.
DO $$
BEGIN
  PERFORM cron.unschedule('vacuum-analyze-weekly');
EXCEPTION WHEN OTHERS THEN
  NULL; -- job pode não existir em replay limpo; será (re)criado abaixo
END $$;

SELECT cron.schedule('vacuum-analyze-weekly', '0 2 * * 6', $job$
    ANALYZE public.product_images;
    ANALYZE public.product_relationships;
    ANALYZE public.products;
    ANALYZE public.product_variants;
    ANALYZE public.supplier_import_batches;
    ANALYZE public.product_category_assignments;
    ANALYZE public.admin_audit_log;
    ANALYZE public.frontend_telemetry;
    ANALYZE public.supplier_products_raw;
    ANALYZE public.supplier_products_raw_history;
$job$);
-- <<< END 20260605014600_fix_vacuum_analyze_weekly_cron_no_vacuum_in_txn.sql <<<

-- >>> BEGIN 20260605020240_restore_spot_name_clean_and_maxlength_in_fn_apply_transform.sql >>>
-- Regressao (auditoria PR #659, achado Codex): a migration
-- 20260605011952_fix_fn_apply_transform_multiply_null_config_guard fez
-- CREATE OR REPLACE de fn_apply_transform e, ao restaurar o corpo, PERDEU dois
-- branches que 20260604234647 / 20260605000347 haviam adicionado:
--   (1) custom -> fn_clean_spot_name (limpeza do nome SPOT)
--   (2) cap de max_length (SPOT ncm_code=10, short_description=500)
-- Resultado vivo: nomes SPOT deixaram de ser limpos (caem no ELSE -> valor cru)
-- e os campos longos voltaram a poder estourar. Os mappings SPOT ativos usam
-- ambos. Este forward fix parte do corpo ATUAL (preserva os guards de
-- multiply/divide/regex null) e readiciona os dois branches.
CREATE OR REPLACE FUNCTION public.fn_apply_transform(p_value text, p_transform_type character varying, p_transform_config jsonb, p_source_unit character varying, p_target_unit character varying, p_supplier_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
    v_result     TEXT;
    v_numeric    DECIMAL;
    v_multiplier DECIMAL;
    v_fn         VARCHAR;
    v_pattern    TEXT;
    v_group      INTEGER;
    v_matches    TEXT[];
    v_max_length INTEGER;
BEGIN
    IF p_value IS NULL OR TRIM(p_value) = '' THEN
        RETURN NULL;
    END IF;

    CASE p_transform_type

        WHEN 'direct' THEN
            v_result := p_value;

        WHEN 'multiply' THEN
            BEGIN
                v_multiplier := COALESCE(
                    (p_transform_config->>'multiplier')::DECIMAL,
                    (p_transform_config->>'factor')::DECIMAL
                );
                -- Guard: sem config ou multiplier NULL → retorna original
                IF v_multiplier IS NULL THEN
                    RETURN p_value;
                END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM
                              TRIM(TRAILING '0' FROM
                                ROUND(v_numeric * v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'divide' THEN
            BEGIN
                v_multiplier := COALESCE(
                    (p_transform_config->>'divisor')::DECIMAL,
                    (p_transform_config->>'factor')::DECIMAL
                );
                -- Guard: sem config ou divisor NULL/zero → retorna original
                IF v_multiplier IS NULL OR v_multiplier = 0 THEN
                    RETURN p_value;
                END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM
                              TRIM(TRAILING '0' FROM
                                ROUND(v_numeric / v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'convert_unit' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_result := fn_convert_unit(v_numeric, p_source_unit, p_target_unit, p_supplier_id)::TEXT;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'lookup' THEN
            v_result := fn_map_value(p_supplier_id, p_transform_config->>'lookup_type', p_value);

        WHEN 'custom' THEN
            BEGIN
                v_fn := p_transform_config->>'function';
                CASE v_fn
                    WHEN 'fn_parse_capacity_ml' THEN
                        v_result := fn_parse_capacity_ml(p_value)::TEXT;
                    WHEN 'fn_convert_box_dimension_to_cm' THEN
                        v_result := fn_convert_box_dimension_to_cm(p_value)::TEXT;
                    WHEN 'fn_clean_spot_name' THEN
                        v_result := fn_clean_spot_name(p_value);
                    ELSE
                        v_result := p_value;
                END CASE;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        WHEN 'prefix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'prefix' IS NOT NULL THEN
                v_result := (p_transform_config->>'prefix') || p_value;
            ELSE
                v_result := p_value;
            END IF;

        WHEN 'suffix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'suffix' IS NOT NULL THEN
                v_result := p_value || (p_transform_config->>'suffix');
            ELSE
                v_result := p_value;
            END IF;

        WHEN 'uppercase'    THEN v_result := UPPER(p_value);
        WHEN 'lowercase'    THEN v_result := LOWER(p_value);
        WHEN 'trim'         THEN v_result := BTRIM(p_value);

        WHEN 'replace' THEN
            IF p_transform_config IS NOT NULL THEN
                v_result := REPLACE(p_value,
                    COALESCE(p_transform_config->>'find', ''),
                    COALESCE(p_transform_config->>'replace', ''));
            ELSE
                v_result := p_value;
            END IF;

        WHEN 'regex_extract' THEN
            BEGIN
                v_pattern := p_transform_config->>'pattern';
                v_group   := COALESCE((p_transform_config->>'group')::INTEGER, 1);
                IF v_pattern IS NULL THEN RETURN p_value; END IF;
                v_matches := regexp_matches(p_value, v_pattern);
                IF array_length(v_matches, 1) >= v_group THEN
                    v_result := v_matches[v_group];
                ELSE
                    v_result := NULL;
                END IF;
            EXCEPTION WHEN OTHERS THEN
                v_result := p_value;
            END;

        ELSE
            v_result := p_value;

    END CASE;

    -- Aditivo: trunca para caber na coluna de destino quando configurado.
    IF v_result IS NOT NULL AND p_transform_config IS NOT NULL
       AND (p_transform_config->>'max_length') IS NOT NULL THEN
        v_max_length := (p_transform_config->>'max_length')::INTEGER;
        IF v_max_length > 0 AND length(v_result) > v_max_length THEN
            v_result := left(v_result, v_max_length);
        END IF;
    END IF;

    RETURN v_result;
END;
$function$;
-- <<< END 20260605020240_restore_spot_name_clean_and_maxlength_in_fn_apply_transform.sql <<<

-- >>> BEGIN 20260605024400_fix_material_percentage_rounding_residual.sql >>>
CREATE OR REPLACE FUNCTION public.fn_extract_materials_from_name(p_product_id uuid, p_replace_existing boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_product RECORD;
    v_material RECORD;
    v_count INTEGER := 0;
    v_search_text TEXT;
    v_org_id UUID := '5db5aee1-064b-4ef4-9193-345dcd8274ea';
    v_found_materials UUID[] := '{}';
    v_material_id UUID;
    v_percentage NUMERIC;
    v_n INTEGER;
    v_idx INTEGER;
    v_accumulated NUMERIC := 0;
BEGIN
    SELECT id, name, description, short_description, organization_id
    INTO v_product FROM products WHERE id = p_product_id;

    IF v_product.id IS NULL THEN RETURN 0; END IF;
    IF v_product.organization_id IS NOT NULL THEN v_org_id := v_product.organization_id; END IF;

    v_search_text := LOWER(COALESCE(v_product.name, '') || ' ' ||
                          COALESCE(v_product.description, '') || ' ' ||
                          COALESCE(v_product.short_description, ''));

    IF p_replace_existing THEN
        DELETE FROM product_materials WHERE product_id = p_product_id;
    ELSE
        IF EXISTS (SELECT 1 FROM product_materials WHERE product_id = p_product_id) THEN
            RETURN 0;
        END IF;
    END IF;

    FOR v_material IN SELECT mt.id, mt.name FROM material_types mt WHERE mt.is_active = true
    LOOP
        IF (
            (v_material.name = 'Alumínio' AND (v_search_text ILIKE '%alumínio%' OR v_search_text ILIKE '%aluminio%'))
            OR (v_material.name = 'Aço Inox' AND (v_search_text ILIKE '%aço inox%' OR v_search_text ILIKE '%inox%'))
            OR (v_material.name = 'Metal Genérico' AND (v_search_text ILIKE '%em metal%' OR v_search_text ILIKE '%e metal%' OR v_search_text ILIKE '% metal %'))
            OR (v_material.name = 'Zinco' AND v_search_text ILIKE '%zinco%')
            OR (v_material.name = 'Cobre' AND v_search_text ILIKE '%cobre%')
            OR (v_material.name = 'Bronze' AND v_search_text ILIKE '%bronze%')
            OR (v_material.name ILIKE '%ABS%' AND (v_search_text ILIKE '% abs %' OR v_search_text ILIKE '%e abs%' OR v_search_text ILIKE '%em abs%' OR v_search_text ILIKE '%rabs%'))
            OR (v_material.name ILIKE '%PVC%' AND (v_search_text ILIKE '%pvc%' OR v_search_text ILIKE '% pu %' OR v_search_text ILIKE '%em pu%'))
            OR (v_material.name = 'Policarbonato' AND (v_search_text ILIKE '%policarbonato%' OR v_search_text ILIKE '% pc %' OR v_search_text ILIKE '%em pc%'))
            OR (v_material.name = 'Polipropileno (PP)' AND (v_search_text ILIKE '%polipropileno%' OR v_search_text ILIKE '% pp %' OR v_search_text ILIKE '%em pp%'))
            OR (v_material.name = 'Poliestireno - PS' AND (v_search_text ILIKE '%poliestireno%' OR v_search_text ILIKE '% ps %' OR v_search_text ILIKE '%e ps%'))
            OR (v_material.name = 'Plástico - PET' AND (v_search_text ILIKE '% pet %' OR v_search_text ILIKE '%em pet%' OR v_search_text ILIKE '%rpet%'))
            OR (v_material.name = 'Plástico - rPET' AND v_search_text ILIKE '%rpet%')
            OR (v_material.name = 'Acrílico' AND (v_search_text ILIKE '%acrílico%' OR v_search_text ILIKE '%acrilico%'))
            OR (v_material.name = 'Silicone' AND v_search_text ILIKE '%silicone%')
            OR (v_material.name = 'Tritan' AND v_search_text ILIKE '%tritan%')
            OR (v_material.name = 'EVA (Acetato de Vinila)' AND v_search_text ILIKE '%eva%')
            OR (v_material.name = 'POE (Poliolefina Elastomérica)' AND (v_search_text ILIKE '% poe %' OR v_search_text ILIKE '%em poe%'))
            OR (v_material.name = 'Poliéster' AND (v_search_text ILIKE '%poliéster%' OR v_search_text ILIKE '%poliester%' OR v_search_text ILIKE '%300d%' OR v_search_text ILIKE '%600d%' OR v_search_text ILIKE '%1680d%'))
            OR (v_material.name = 'Algodão' AND (v_search_text ILIKE '%algodão%' OR v_search_text ILIKE '%algodao%' OR v_search_text ILIKE '%canvas%' OR v_search_text ILIKE '%camiseta%'))
            OR (v_material.name = 'Nylon' AND v_search_text ILIKE '%nylon%')
            OR (v_material.name = 'Pongee' AND v_search_text ILIKE '%pongee%')
            OR (v_material.name = 'Oxford' AND v_search_text ILIKE '%oxford%')
            OR (v_material.name = 'Ripstop' AND (v_search_text ILIKE '%ripstop%' OR v_search_text ILIKE '%210d%'))
            OR (v_material.name = 'Jacquard' AND (v_search_text ILIKE '%jacquard%' OR v_search_text ILIKE '%840d%'))
            OR (v_material.name = 'Polar' AND v_search_text ILIKE '%polar%')
            OR (v_material.name = 'Microfibra' AND v_search_text ILIKE '%microfibra%')
            OR (v_material.name = 'Feltro' AND v_search_text ILIKE '%feltro%')
            OR (v_material.name = 'TNT (Nowen)' AND (v_search_text ILIKE '%tnt%' OR v_search_text ILIKE '%non-woven%' OR v_search_text ILIKE '%nonwoven%'))
            OR (v_material.name = 'Neoprene' AND v_search_text ILIKE '%neoprene%')
            OR (v_material.name = 'Fibras Naturais' AND (v_search_text ILIKE '%palha%' OR v_search_text ILIKE '%juta%' OR v_search_text ILIKE '%fibras naturais%'))
            OR (v_material.name = 'Bambu' AND v_search_text ILIKE '%bambu%')
            OR (v_material.name = 'Madeira' AND v_search_text ILIKE '%madeira%')
            OR (v_material.name = 'MDF' AND v_search_text ILIKE '%mdf%')
            OR (v_material.name = 'Cortiça' AND (v_search_text ILIKE '%cortiça%' OR v_search_text ILIKE '%cortica%'))
            OR (v_material.name = 'Vidro Borossilicado' AND v_search_text ILIKE '%borossilicato%')
            OR (v_material.name = 'Vidro' AND v_search_text ILIKE '%vidro%' AND NOT v_search_text ILIKE '%borossilicato%')
            OR (v_material.name = 'Cerâmica' AND (v_search_text ILIKE '%cerâmica%' OR v_search_text ILIKE '%ceramica%'))
            OR (v_material.name = 'Porcelana' AND v_search_text ILIKE '%porcelana%')
            OR (v_material.name ILIKE '%Couro%' AND (v_search_text ILIKE '%couro%' OR v_search_text ILIKE '%pele%' OR v_search_text ILIKE '%c.sintético%'))
            OR (v_material.name = 'Cartão' AND (v_search_text ILIKE '%cartão%' OR v_search_text ILIKE '%cartao%' OR v_search_text ILIKE '%papel pedra%' OR v_search_text ILIKE '%em papel%'))
            OR (v_material.name = 'Kraft' AND v_search_text ILIKE '%kraft%')
            OR (v_material.name = 'Borracha' AND v_search_text ILIKE '%borracha%')
            OR (v_material.name = 'Espuma' AND v_search_text ILIKE '%espuma%')
        )
        THEN
            v_found_materials := array_append(v_found_materials, v_material.id);
        END IF;
    END LOOP;

    v_n := COALESCE(array_length(v_found_materials, 1), 0);
    IF v_n > 0 THEN
        -- Distribuição com resíduo: os (n-1) primeiros recebem ROUND(100/n,2);
        -- o último recebe (100 - soma acumulada) garantindo total exato = 100.
        v_percentage := ROUND(100.0 / v_n, 2);
        v_idx := 0;
        FOREACH v_material_id IN ARRAY v_found_materials LOOP
            v_idx := v_idx + 1;
            IF v_idx < v_n THEN
                INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, sort_order, is_active)
                VALUES (v_org_id, p_product_id, v_material_id, 'corpo', v_percentage, v_idx, true);
                v_accumulated := v_accumulated + v_percentage;
            ELSE
                INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, sort_order, is_active)
                VALUES (v_org_id, p_product_id, v_material_id, 'corpo', ROUND(100 - v_accumulated, 2), v_idx, true);
            END IF;
            v_count := v_count + 1;
        END LOOP;
    END IF;

    RETURN v_count;
END;
$function$;
-- <<< END 20260605024400_fix_material_percentage_rounding_residual.sql <<<

-- >>> BEGIN 20260605025212_add_bronze_versioning_on_content_hash_change.sql >>>
-- P2.8 — Versionamento real da Bronze: arquiva versão anterior quando content_hash muda
CREATE OR REPLACE FUNCTION public.fn_version_supplier_raw_on_hash_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Só versiona quando o conteúdo realmente mudou (hash diferente e não-nulo)
  IF NEW.content_hash IS DISTINCT FROM OLD.content_hash THEN
    INSERT INTO public.supplier_products_raw_history
      (raw_id, supplier_id, supplier_reference, content_hash, raw_data, captured_at)
    VALUES
      (OLD.id, OLD.supplier_id, OLD.supplier_reference, OLD.content_hash, OLD.raw_data, OLD.updated_at);
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS trg_version_supplier_raw ON public.supplier_products_raw;
CREATE TRIGGER trg_version_supplier_raw
  BEFORE UPDATE OF content_hash ON public.supplier_products_raw
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_version_supplier_raw_on_hash_change();
-- <<< END 20260605025212_add_bronze_versioning_on_content_hash_change.sql <<<

-- >>> BEGIN 20260605025232_fix_bronze_versioning_trigger_on_raw_data.sql >>>
-- content_hash é generated column → versionar com base em raw_data (a fonte real)
DROP TRIGGER IF EXISTS trg_version_supplier_raw ON public.supplier_products_raw;

CREATE OR REPLACE FUNCTION public.fn_version_supplier_raw_on_hash_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Versiona quando o conteúdo cru muda (content_hash deriva de raw_data).
  IF NEW.content_hash IS DISTINCT FROM OLD.content_hash THEN
    INSERT INTO public.supplier_products_raw_history
      (raw_id, supplier_id, supplier_reference, content_hash, raw_data, captured_at)
    VALUES
      (OLD.id, OLD.supplier_id, OLD.supplier_reference, OLD.content_hash, OLD.raw_data, OLD.updated_at);
  END IF;
  RETURN NEW;
END;
$function$;

CREATE TRIGGER trg_version_supplier_raw
  BEFORE UPDATE OF raw_data ON public.supplier_products_raw
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_version_supplier_raw_on_hash_change();
-- <<< END 20260605025232_fix_bronze_versioning_trigger_on_raw_data.sql <<<

-- >>> BEGIN 20260605025255_fix_bronze_versioning_compare_raw_data.sql >>>
-- Em BEFORE UPDATE, generated columns (content_hash) ainda não recalcularam.
-- Comparar raw_data diretamente (fonte do hash).
CREATE OR REPLACE FUNCTION public.fn_version_supplier_raw_on_hash_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.raw_data IS DISTINCT FROM OLD.raw_data THEN
    INSERT INTO public.supplier_products_raw_history
      (raw_id, supplier_id, supplier_reference, content_hash, raw_data, captured_at)
    VALUES
      (OLD.id, OLD.supplier_id, OLD.supplier_reference, OLD.content_hash, OLD.raw_data, OLD.updated_at);
  END IF;
  RETURN NEW;
END;
$function$;
-- <<< END 20260605025255_fix_bronze_versioning_compare_raw_data.sql <<<

-- >>> BEGIN 20260605025338_drop_redundant_bronze_versioning_trigger.sql >>>
-- P2.8 JÁ EXISTIA via trg_spr_history/fn_spr_history. Remover minha duplicação para evitar
-- versionamento em dobro (dois INSERTs em history por mudança).
DROP TRIGGER IF EXISTS trg_version_supplier_raw ON public.supplier_products_raw;
DROP FUNCTION IF EXISTS public.fn_version_supplier_raw_on_hash_change();
-- <<< END 20260605025338_drop_redundant_bronze_versioning_trigger.sql <<<

-- >>> BEGIN 20260605100708_harden_rls_mcp_sessions_silver_pricetiers_physical_and_dryrun_acl.sql >>>
-- Hardening de segurança (auditoria PR #659, achados CodeRabbit/Codex/cubic).
-- service_role tem BYPASSRLS no Supabase, então o pipeline (edge/cron/SECURITY
-- DEFINER) continua escrevendo normalmente após estas restrições.

-- (P0) mcp_sessions guarda cookies de sessão: hoje anon tem policy FOR ALL
-- USING(true) + GRANT total. Fecha para service_role apenas.
DROP POLICY IF EXISTS mcp_sessions_anon_all ON public.mcp_sessions;
REVOKE ALL ON TABLE public.mcp_sessions FROM anon, authenticated;
DROP POLICY IF EXISTS mcp_sessions_service_all ON public.mcp_sessions;
CREATE POLICY mcp_sessions_service_all ON public.mcp_sessions
  FOR ALL TO service_role USING (true) WITH CHECK (true);

-- produtos_padronizacao (camada silver): contrato = service_role escreve,
-- authenticated só lê. Hoje a policy é FOR ALL USING/CHECK(true).
DROP POLICY IF EXISTS pad_authenticated_all ON public.produtos_padronizacao;
DROP POLICY IF EXISTS pad_authenticated_read ON public.produtos_padronizacao;
CREATE POLICY pad_authenticated_read ON public.produtos_padronizacao
  FOR SELECT TO authenticated USING (true);
REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER
  ON TABLE public.produtos_padronizacao FROM authenticated;

-- product_physical: remove escrita ampla de authenticated (mantém leitura e o
-- product_physical_service); revoga grants de anon.
DROP POLICY IF EXISTS product_physical_ins ON public.product_physical;
DROP POLICY IF EXISTS product_physical_upd ON public.product_physical;
DROP POLICY IF EXISTS product_physical_del ON public.product_physical;
REVOKE ALL ON TABLE public.product_physical FROM anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER
  ON TABLE public.product_physical FROM authenticated;

-- supplier_price_tiers: contém cost_price (custo de fornecedor). Remove escrita
-- de authenticated e grants de anon; mantém leitura por authenticated e o
-- supplier_price_tiers_service.
DROP POLICY IF EXISTS supplier_price_tiers_ins ON public.supplier_price_tiers;
DROP POLICY IF EXISTS supplier_price_tiers_upd ON public.supplier_price_tiers;
DROP POLICY IF EXISTS supplier_price_tiers_del ON public.supplier_price_tiers;
REVOKE ALL ON TABLE public.supplier_price_tiers FROM anon;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER
  ON TABLE public.supplier_price_tiers FROM authenticated;

-- fn_dryrun_raw_v2 é SECURITY DEFINER e hoje executável por anon/authenticated
-- (enumera supplier_settings/products/variants com privilégio elevado).
REVOKE EXECUTE ON FUNCTION public.fn_dryrun_raw_v2(uuid, integer) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_dryrun_raw_v2(uuid, integer) FROM anon;
REVOKE EXECUTE ON FUNCTION public.fn_dryrun_raw_v2(uuid, integer) FROM authenticated;
-- <<< END 20260605100708_harden_rls_mcp_sessions_silver_pricetiers_physical_and_dryrun_acl.sql <<<

-- >>> BEGIN 20260605101258_fix_silver_promotion_cost_isactive_locks_and_races.sql >>>
-- Fixes do pipeline Silver (auditoria PR #659, achados CodeRabbit/cubic).
-- Todas as funções recriadas a partir do corpo atual com edições mínimas + search_path.

-- 1) fn_standardize_variant: restaura captura de custo XBZ (PrecoVenda) e ASIA
--    (preco) que a silver_08g regrediu; e inclui is_active no ON CONFLICT.
CREATE OR REPLACE FUNCTION public.fn_standardize_variant(p_raw_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r public.supplier_products_raw%ROWTYPE;
  v_parent text; v_code text; v_apiid text; v_cname text; v_chex text;
  v_col RECORD; v_sku text; v_supplier_sku text; v_stock integer; v_cost numeric; v_var_id uuid;
  v_fname text; v_fcode text; v_fhex text; v_canonical_id uuid;
  v_SPOT uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_XBZ  uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
  v_ASIA uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_SM   uuid := '841cd690-210a-422a-908c-7676828db272';
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id=p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','raw_nao_encontrado'); END IF;
  v_parent := public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data);

  IF r.supplier_id=v_SPOT THEN
    v_code:=r.raw_data->>'ColorCode'; v_cname:=r.raw_data->>'ColorName'; v_chex:=r.raw_data->>'ColorHex';
    v_supplier_sku:=r.raw_data->>'Sku'; v_stock:=public.fn_safe_int(r.raw_data->>'StockQuantity');
    v_cost:=public.fn_safe_num(r.raw_data->>'Price1'); v_sku:=r.supplier_reference;
  ELSIF r.supplier_id=v_XBZ THEN
    v_apiid:=r.raw_data->>'CorWebPrincipalId'; v_cname:=r.raw_data->>'CorWebPrincipal';
    v_supplier_sku:=r.raw_data->>'CodigoComposto'; v_stock:=public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel');
    v_cost:=public.fn_safe_num(r.raw_data->>'PrecoVenda');   -- PrecoVenda do XBZ = CUSTO (silver_08e)
    v_sku:='XBZ-'||r.supplier_reference;
  ELSIF r.supplier_id=v_ASIA THEN
    v_cname:=r.raw_data->>'var_cor_nome'; v_chex:=r.raw_data->>'var_cor_hex';
    v_supplier_sku:=COALESCE(r.raw_data->>'var_referencia', r.supplier_reference);
    v_stock:=public.fn_safe_int(r.raw_data->>'var_estoque');
    v_cost:=public.fn_safe_num(r.raw_data->>'preco');        -- preco da Asia = CUSTO (silver_08e)
    v_sku:='ASIA-'||r.supplier_reference;
  ELSIF r.supplier_id=v_SM THEN
    -- Só Marcas: sem campo de cor. Extrai do título; hex da rede de produtos_similares.
    v_cname:=public.fn_extract_color_from_title(r.raw_data->>'titulo');
    v_chex := (SELECT split_part(item,'|',2)
               FROM unnest(string_to_array(r.raw_data->>'produtos_similares', ';')) item
               WHERE split_part(item,'|',1)=r.supplier_reference
                 AND split_part(item,'|',2) ~* '^#[0-9a-f]{6}$' LIMIT 1);
    v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque');
    v_cost:=public.fn_safe_num(r.raw_data->>'preco_sem_gravacao_sem_impostos');
    v_sku:=r.supplier_reference;
  ELSE
    v_cname:=r.raw_data->>'cor'; v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque'); v_cost:=public.fn_safe_num(r.raw_data->>'preco_base');
    v_sku:=r.supplier_reference;
  END IF;

  -- resolução do fornecedor (descritivos). Para SM não há catálogo, usa o extraído.
  SELECT * INTO v_col FROM public.fn_match_supplier_color(r.supplier_id, v_code, v_apiid, v_cname, v_chex);
  v_fname := COALESCE(v_col.color_name, v_cname);
  v_fcode := COALESCE(v_col.color_code, v_code);
  v_fhex  := COALESCE(v_col.color_hex,  v_chex);
  v_canonical_id := public.fn_match_canonical_color(v_fname, v_fhex);

  INSERT INTO public.produtos_padronizacao_variantes AS pv (
    raw_id, supplier_id, parent_reference, variant_reference,
    sku, supplier_sku, color_name, color_code, color_hex, color_id,
    stock_quantity, cost_price, is_active, status
  ) VALUES (
    r.id, r.supplier_id, v_parent, r.supplier_reference, v_sku, v_supplier_sku,
    v_fname, v_fcode, v_fhex, v_canonical_id,
    v_stock, v_cost, true, 'standardized'::public.produtos_padronizacao_status
  )
  ON CONFLICT (supplier_id, variant_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, parent_reference=EXCLUDED.parent_reference, sku=EXCLUDED.sku, supplier_sku=EXCLUDED.supplier_sku,
    color_name=EXCLUDED.color_name, color_code=EXCLUDED.color_code, color_hex=EXCLUDED.color_hex, color_id=EXCLUDED.color_id,
    stock_quantity=EXCLUDED.stock_quantity, cost_price=EXCLUDED.cost_price, is_active=EXCLUDED.is_active,
    status=EXCLUDED.status, updated_at=now()
  RETURNING pv.id INTO v_var_id;

  RETURN jsonb_build_object('success',true,'variante_id',v_var_id,'parent',v_parent,
                            'cor',v_fname,'hex',v_fhex,'color_id_canonico',v_canonical_id);
END;
$function$;

-- 2) fn_promote_variants_of_parent: VSS faz upsert (custo nao fica stale) e o
--    INSERT da variante e race-safe via ON CONFLICT (sku).
CREATE OR REPLACE FUNCTION public.fn_promote_variants_of_parent(p_supplier_id uuid, p_parent_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_pid uuid; v_org uuid; pv RECORD; v_vid uuid; v_count int := 0; v_attrs jsonb;
  v_existing_pid uuid;
BEGIN
  PERFORM set_config('app.write_source','pipeline',true);
  SELECT id, organization_id INTO v_pid, v_org FROM public.products
  WHERE supplier_id=p_supplier_id AND supplier_reference=p_parent_reference;
  IF v_pid IS NULL THEN RETURN jsonb_build_object('success',false,'error','produto_pai_nao_promovido','parent',p_parent_reference); END IF;

  FOR pv IN
    SELECT * FROM public.produtos_padronizacao_variantes
    WHERE supplier_id=p_supplier_id AND parent_reference=p_parent_reference AND status='standardized'
  LOOP
    v_attrs := jsonb_strip_nulls(jsonb_build_object('cor', pv.color_name, 'codigo_cor', pv.color_code, 'hex', pv.color_hex));

    -- idempotência por sku GLOBAL (sku é UNIQUE em product_variants); fallback (product_id, supplier_sku)
    SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants WHERE sku = pv.sku;
    IF v_vid IS NULL THEN
      SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants
      WHERE product_id=v_pid AND supplier_sku=pv.supplier_sku;
    END IF;

    IF v_vid IS NULL THEN
      -- race-safe: se outra sessao inserir o mesmo sku entre o SELECT e o INSERT,
      -- ON CONFLICT (sku) converte em UPDATE em vez de unique_violation.
      INSERT INTO public.product_variants (product_id, sku, supplier_sku, name, attributes, color_name, color_code, color_hex, color_id, stock_quantity, is_active, last_sync_at, last_sync_supplier_id)
      VALUES (v_pid, pv.sku, pv.supplier_sku, COALESCE(pv.color_name, pv.sku), v_attrs,
              pv.color_name, pv.color_code, pv.color_hex, pv.color_id,
              COALESCE(pv.stock_quantity,0), COALESCE(pv.is_active,true), now(), p_supplier_id)
      ON CONFLICT (sku) DO UPDATE SET
        supplier_sku = EXCLUDED.supplier_sku,
        attributes   = COALESCE(public.product_variants.attributes,'{}'::jsonb) || EXCLUDED.attributes,
        color_name   = COALESCE(EXCLUDED.color_name, public.product_variants.color_name),
        color_code   = COALESCE(EXCLUDED.color_code, public.product_variants.color_code),
        color_hex    = COALESCE(EXCLUDED.color_hex, public.product_variants.color_hex),
        color_id     = COALESCE(EXCLUDED.color_id, public.product_variants.color_id),
        stock_quantity = COALESCE(EXCLUDED.stock_quantity, public.product_variants.stock_quantity),
        last_sync_at = now(), last_sync_supplier_id = EXCLUDED.last_sync_supplier_id
      RETURNING id INTO v_vid;
    ELSE
      -- atualiza a variante existente (NÃO remapeia product_id para não mover variante entre produtos)
      UPDATE public.product_variants SET
        attributes = COALESCE(attributes,'{}'::jsonb) || v_attrs,
        color_name=COALESCE(pv.color_name,color_name), color_code=COALESCE(pv.color_code,color_code),
        color_hex=COALESCE(pv.color_hex,color_hex), color_id=COALESCE(pv.color_id,color_id),
        stock_quantity=COALESCE(pv.stock_quantity,stock_quantity), last_sync_at=now(), last_sync_supplier_id=p_supplier_id
      WHERE id=v_vid;
    END IF;

    IF pv.cost_price IS NOT NULL THEN
      INSERT INTO public.variant_supplier_sources (organization_id, variant_id, supplier_id, cost_price, supplier_sku, supplier_color_code, supplier_color_name, is_active, source, last_synced_at)
      VALUES (v_org, v_vid, p_supplier_id, pv.cost_price, pv.supplier_sku, pv.color_code, pv.color_name, true, 'silver', now())
      ON CONFLICT (variant_id, supplier_id) DO UPDATE SET
        cost_price          = EXCLUDED.cost_price,
        supplier_sku        = EXCLUDED.supplier_sku,
        supplier_color_code = EXCLUDED.supplier_color_code,
        supplier_color_name = EXCLUDED.supplier_color_name,
        is_active           = EXCLUDED.is_active,
        source              = EXCLUDED.source,
        last_synced_at      = EXCLUDED.last_synced_at;
    END IF;

    UPDATE public.produtos_padronizacao_variantes SET status='promoted', variant_id=v_vid, updated_at=now() WHERE id=pv.id;
    v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('success',true,'product_id',v_pid,'variantes_promovidas',v_count);
END;
$function$;

-- 3) fn_promote_padronizacao: lock pessimista (FOR UPDATE) evita promocao
--    concorrente duplicada do mesmo registro silver.
CREATE OR REPLACE FUNCTION public.fn_promote_padronizacao(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  s         public.produtos_padronizacao%ROWTYPE;
  v_pid     uuid;
  v_org     uuid;
  v_locked  text[];
  v_is_new  boolean := false;
BEGIN
  SELECT * INTO s FROM public.produtos_padronizacao WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'padronizacao_nao_encontrada', 'id', p_id);
  END IF;
  IF s.status <> 'standardized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'status_invalido', 'status', s.status);
  END IF;

  PERFORM set_config('app.write_source', 'pipeline', true);

  SELECT id, locked_fields INTO v_pid, v_locked
  FROM public.products
  WHERE supplier_id = s.supplier_id AND supplier_reference = s.supplier_reference;

  IF v_pid IS NULL THEN
    v_is_new := true;
    SELECT organization_id INTO v_org FROM public.suppliers WHERE id = s.supplier_id;
    INSERT INTO public.products (organization_id, supplier_id, supplier_reference, sku, name, active, is_active, product_type)
    VALUES (v_org, s.supplier_id, s.supplier_reference,
            COALESCE(s.supplier_reference, s.name), COALESCE(s.name,'Produto '||s.supplier_reference),
            COALESCE(s.is_active, true), COALESCE(s.is_active, true), 'product')
    RETURNING id, locked_fields INTO v_pid, v_locked;
  END IF;

  v_locked := COALESCE(v_locked, '{}');

  UPDATE public.products p SET
    name               = CASE WHEN 'name'               = ANY(v_locked) THEN p.name               ELSE COALESCE(s.name, p.name) END,
    description        = CASE WHEN 'description'        = ANY(v_locked) THEN p.description        ELSE COALESCE(s.description, p.description) END,
    short_description  = CASE WHEN 'short_description'  = ANY(v_locked) THEN p.short_description  ELSE COALESCE(s.short_description, p.short_description) END,
