-- >>> BEGIN 20260605154029_asia_bronze_fix_referencia_pai.sql >>>

-- ============================================================
-- CORREÇÃO: raw_data Asia — adicionar referencia (pai) correta
-- Todos os 1.245 registros: referencia == var_referencia (errado).
-- Fonte do mapeamento: silver (pad_id, 100% resolvido).
-- ============================================================

-- BACKUP primeiro
DROP TABLE IF EXISTS public._bkp_asia_raw_pre_fix_referencia;
CREATE TABLE public._bkp_asia_raw_pre_fix_referencia AS
  SELECT * FROM public.supplier_products_raw
  WHERE supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118';

-- Mapeamento pré-computado: raw_id → supplier_reference do pai
WITH mapa AS (
  SELECT
    pv.raw_id,
    pp.supplier_reference AS referencia_pai,
    br.supplier_reference  AS var_referencia_variante
  FROM produtos_padronizacao_variantes pv
  JOIN produtos_padronizacao pp ON pp.id = pv.pad_id
  JOIN supplier_products_raw br ON br.id = pv.raw_id
  WHERE pv.supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'
    AND pv.raw_id IS NOT NULL
    AND pv.pad_id IS NOT NULL
)
UPDATE public.supplier_products_raw br
SET raw_data = br.raw_data
  || jsonb_build_object('referencia',    mapa.referencia_pai)
  || jsonb_build_object('var_referencia', mapa.var_referencia_variante)
FROM mapa
WHERE br.id = mapa.raw_id
  AND br.supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'
  AND br.raw_data->>'referencia' = br.raw_data->>'var_referencia';
;

-- <<< END 20260605154029_asia_bronze_fix_referencia_pai.sql <<<

-- >>> BEGIN 20260605154127_asia_fn_derive_parent_usa_referencia.sql >>>

CREATE OR REPLACE FUNCTION public.fn_derive_parent_ref(
  p_supplier_id  uuid,
  p_variant_ref  text,
  p_raw          jsonb
) RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$
BEGIN
  IF p_variant_ref IS NULL OR TRIM(p_variant_ref) = '' THEN
    RETURN NULL;
  END IF;

  -- Spot | Stricker
  IF p_supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0' THEN
    RETURN COALESCE(NULLIF(TRIM(p_raw->>'ProdReference'), ''), p_variant_ref);
  END IF;

  -- XBZ Brindes
  IF p_supplier_id = 'd6718a29-e954-4c1b-bd84-03ea24884900' THEN
    RETURN COALESCE(NULLIF(TRIM(p_raw->>'CodigoAmigavel'), ''),
                   regexp_replace(p_variant_ref, '-[^-]*$', ''));
  END IF;

  -- Asia Import: usa raw_data->>'referencia' quando está presente E é diferente da variante.
  -- Esse campo foi corrigido na migration asia_bronze_fix_referencia_pai (antes era == var).
  -- Fallback: heurística sufixo-P para registros legados/descontinuados sem o campo.
  IF p_supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118' THEN
    IF p_raw IS NOT NULL
       AND NULLIF(TRIM(p_raw->>'referencia'), '') IS NOT NULL
       AND (p_raw->>'referencia') IS DISTINCT FROM p_variant_ref THEN
      RETURN TRIM(p_raw->>'referencia');
    END IF;
    -- fallback heurístico
    IF position('-' IN p_variant_ref) > 0 THEN
      RETURN regexp_replace(p_variant_ref, '-[^-]*$', '');
    ELSE
      RETURN p_variant_ref || 'P';
    END IF;
  END IF;

  -- Só Marcas: 1:1
  IF p_supplier_id = '841cd690-210a-422a-908c-7676828db272' THEN
    RETURN p_variant_ref;
  END IF;

  -- Demais: corte no último hífen
  IF position('-' IN p_variant_ref) > 0 THEN
    RETURN regexp_replace(p_variant_ref, '-[^-]*$', '');
  END IF;
  RETURN p_variant_ref;
END;
$$;

COMMENT ON FUNCTION public.fn_derive_parent_ref(uuid, text, jsonb) IS
  'Deriva referência do produto-pai. Asia: usa raw_data->>''referencia'' (corrigido em
   asia_bronze_fix_referencia_pai) com fallback heurístico sufixo-P. XBZ: CodigoAmigavel.
   Spot: ProdReference. Só Marcas: 1:1. Demais: corte-hífen.';
;

-- <<< END 20260605154127_asia_fn_derive_parent_usa_referencia.sql <<<

-- >>> BEGIN 20260605154154_asia_silver_rederive_parent_reference.sql >>>

-- Re-derivar parent_reference na silver Asia usando fn_derive_parent_ref atualizada
-- (que agora lê raw_data->>'referencia' diretamente)
-- Atualiza variantes que têm raw_id ligado ao bronze corrigido

UPDATE public.produtos_padronizacao_variantes pv
SET parent_reference = fn_derive_parent_ref(
  pv.supplier_id,
  pv.variant_reference,
  br.raw_data
)
FROM public.supplier_products_raw br
WHERE br.id = pv.raw_id
  AND pv.supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'
  AND br.supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'
  -- só atualiza se mudou (evita writes desnecessários e protege content_hash)
  AND pv.parent_reference IS DISTINCT FROM fn_derive_parent_ref(
    pv.supplier_id, pv.variant_reference, br.raw_data
  );

-- Re-derivar parent_reference também nos pais (supplier_reference já está correto,
-- mas garantir que standardized_at e pad_id nas variantes estejam consistentes)
-- O trigger trg_aa_padvar_sync re-resolverá pad_id automaticamente
UPDATE public.produtos_padronizacao_variantes SET pad_id = NULL
WHERE supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'
  AND raw_id IS NOT NULL;
-- Trigger trg_aa_padvar_sync vai re-resolver pad_id no próximo UPDATE
UPDATE public.produtos_padronizacao_variantes pv
SET pad_id = NULL
WHERE supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118';
-- Agora forçar re-resolução (UPDATE trivial que dispara trigger)
UPDATE public.produtos_padronizacao_variantes
SET updated_at = now()
WHERE supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118';
;

-- <<< END 20260605154154_asia_silver_rederive_parent_reference.sql <<<

-- >>> BEGIN 20260605155900_fix_images_status_consistency.sql >>>

-- ════════════════════════════════════════════════════════════════
-- Fix: images_status consistency — raw rows that point to products
-- which already have images in product_images should be marked as
-- images_status='processed'. The image pipeline ran but forgot to
-- update the flag. Safe backfill: only touches rows where
-- status='processed' AND images_status='pending' AND product has images.
-- ════════════════════════════════════════════════════════════════

UPDATE public.supplier_products_raw spr
SET images_status = 'processed'
WHERE spr.status = 'processed'
  AND spr.images_status = 'pending'
  AND spr.product_id IS NOT NULL
  AND EXISTS (
    SELECT 1 FROM public.product_images pi
    WHERE pi.product_id = spr.product_id
  );

-- <<< END 20260605155900_fix_images_status_consistency.sql <<<

-- >>> BEGIN 20260605160000_silver_unify_01_fn_standardize_supplier.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 1/4
-- Orquestrador Bronze → Silver (de-para) em lote, por fornecedor.
-- ════════════════════════════════════════════════════════════════
-- Espelha fn_promote_supplier (Silver → Gold), fechando o par simétrico
-- do pipeline de 3 fases:
--   Bronze  : supplier_products_raw (status='pending')
--   Silver  : produtos_padronizacao(+_variantes)  ← ESTA função
--   Gold    : products / product_variants / variant_supplier_sources
--
-- Ordem obrigatória: variantes ANTES do pai. fn_standardize_parent escolhe
-- a raw representante a partir de produtos_padronizacao_variantes, logo as
-- variantes precisam já existir no staging quando o pai é padronizado.
--
-- Idempotente: as funções-folha (fn_standardize_variant / _raw) usam UPSERT.
-- Concorrência: advisory xact lock por fornecedor evita execuções sobrepostas
-- do cron processarem o mesmo fornecedor duas vezes.
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_standardize_supplier(
    p_supplier_id uuid,
    p_limit       integer DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_raw         RECORD;
  v_par         RECORD;
  v_vres        jsonb;
  v_pres        jsonb;
  v_variants    integer := 0;
  v_parents     integer := 0;
  v_erros       integer := 0;
  v_err_amostra jsonb   := '[]'::jsonb;
  v_touched     text[]  := ARRAY[]::text[];
  v_t0          timestamptz := clock_timestamp();
BEGIN
  -- Segurança: bloqueia chamada direta por não-admin (cron roda sem auth.uid()).
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
  END IF;

  -- Evita execuções concorrentes para o mesmo fornecedor (cron sobreposto).
  IF NOT pg_try_advisory_xact_lock(hashtext('fn_standardize_supplier:'||p_supplier_id::text)::bigint) THEN
    RETURN jsonb_build_object('success', true, 'skipped', 'lock_ocupado',
                              'supplier_id', p_supplier_id);
  END IF;

  PERFORM set_config('app.write_source', 'pipeline', true);

  -- ── 1) Bronze → Silver (variantes): cada raw pendente do fornecedor ──
  FOR v_raw IN
      SELECT id, supplier_reference
      FROM public.supplier_products_raw
      WHERE supplier_id = p_supplier_id
        AND status = 'pending'
      ORDER BY imported_at NULLS LAST
      LIMIT p_limit
      FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      v_vres := public.fn_standardize_variant(v_raw.id);
      IF NOT COALESCE((v_vres->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'variante_falhou:%', COALESCE(v_vres->>'error', 'desconhecido');
      END IF;
      v_variants := v_variants + 1;
      v_touched  := array_append(v_touched, COALESCE(v_vres->>'parent', ''));
    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra
          || jsonb_build_object('raw_id', v_raw.id, 'stage', 'variant', 'erro', SQLERRM);
      END IF;
    END;
  END LOOP;

  -- ── 2) Bronze → Silver (produto pai): cada parent distinto tocado ──
  FOR v_par IN
      SELECT DISTINCT parent_reference
      FROM public.produtos_padronizacao_variantes
      WHERE supplier_id = p_supplier_id
        AND parent_reference = ANY(v_touched)
        AND NULLIF(parent_reference, '') IS NOT NULL
  LOOP
    BEGIN
      v_pres := public.fn_standardize_parent(p_supplier_id, v_par.parent_reference);
      IF NOT COALESCE((v_pres->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'pai_falhou:%', COALESCE(v_pres->>'error', 'desconhecido');
      END IF;
      v_parents := v_parents + 1;
    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra
          || jsonb_build_object('parent', v_par.parent_reference, 'stage', 'parent', 'erro', SQLERRM);
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true, 'supplier_id', p_supplier_id,
    'variantes_padronizadas', v_variants,
    'pais_padronizados', v_parents,
    'erros', v_erros, 'amostra_erros', v_err_amostra,
    'segundos', round(extract(epoch FROM clock_timestamp() - v_t0)::numeric, 1));
END;
$function$;

COMMENT ON FUNCTION public.fn_standardize_supplier(uuid, integer) IS
  'Pipeline Medallion (Fase 1→2): Bronze→Silver de-para em lote por fornecedor. '
  'Padroniza variantes (fn_standardize_variant) e depois os pais (fn_standardize_parent). '
  'Par simétrico de fn_promote_supplier (Fase 2→3). Idempotente; advisory lock por fornecedor.';

-- <<< END 20260605160000_silver_unify_01_fn_standardize_supplier.sql <<<

-- >>> BEGIN 20260605160100_silver_unify_02_rewire_process_pending_batches.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 2/4
-- Religa o cron de ingestão para o pipeline de 3 fases.
-- ════════════════════════════════════════════════════════════════
-- ANTES (atalho que VIOLAVA as 3 fases — Bronze→Gold direto, só SPOT):
--   process_pending_batches() → fn_process_raw_v2(SPOT, 1000, true)
--
-- DEPOIS (Medallion completo, todos os fornecedores auto_sync):
--   process_pending_batches()
--     └─ por fornecedor com raw 'pending':
--          fn_standardize_supplier(...)  -- Fase 1→2  Bronze → Silver (de-para)
--          fn_promote_supplier(...)      -- Fase 2→3  Silver → Gold
--
-- O cron 'process-pending-products' (*/5 * * * *) chama esta função;
-- a assinatura e o tipo de retorno são preservados (sem mudança no job).
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.process_pending_batches()
RETURNS TABLE(batch_id uuid, products_processed integer, status text)
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_sup  RECORD;
  v_std  jsonb;
  v_prom jsonb;
BEGIN
  FOR v_sup IN
      SELECT ss.supplier_id
      FROM public.supplier_settings ss
      WHERE COALESCE(ss.auto_sync_enabled, false) = true
        AND EXISTS (
          SELECT 1 FROM public.supplier_products_raw r
          WHERE r.supplier_id = ss.supplier_id AND r.status = 'pending'
        )
  LOOP
      -- Fase 1→2: Bronze → Silver (de-para)
      v_std  := public.fn_standardize_supplier(v_sup.supplier_id, 1000);
      -- Fase 2→3: Silver → Gold (promoção soberana: produto + variantes + sources)
      v_prom := public.fn_promote_supplier(v_sup.supplier_id, NULL);

      batch_id           := NULL::uuid;
      products_processed := COALESCE((v_prom->>'pais_promovidos')::integer, 0);
      status := CASE
                  WHEN COALESCE((v_std->>'erros')::int, 0) = 0
                   AND COALESCE((v_prom->>'erros')::int, 0) = 0 THEN 'SUCCESS'
                  ELSE 'PARTIAL'
                END;
      RETURN NEXT;
  END LOOP;
  RETURN;
END;
$function$;

COMMENT ON FUNCTION public.process_pending_batches() IS
  'Cron de ingestão (*/5). Pipeline Medallion 3 fases por fornecedor auto_sync: '
  'fn_standardize_supplier (Bronze→Silver) + fn_promote_supplier (Silver→Gold). '
  'Substitui o atalho fn_process_raw_v2 (Bronze→Gold direto). 2026-06-05.';

-- <<< END 20260605160100_silver_unify_02_rewire_process_pending_batches.sql <<<

-- >>> BEGIN 20260605160200_silver_unify_03_redirect_direct_to_gold.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 3/4
-- Neutraliza os atalhos Bronze→Gold (violavam as 3 fases).
-- ════════════════════════════════════════════════════════════════
-- Chamadores verificados ao vivo:
--   fn_process_raw_v2            ← só fn_dryrun_raw_v2 (ferramenta dry-run)
--   process_supplier_product     ← só process_supplier_products_batch
--   process_supplier_products_batch ← nenhum chamador externo
-- Assinaturas preservadas (CREATE OR REPLACE) para não quebrar nada.
-- ════════════════════════════════════════════════════════════════

-- (1) Motor v2: redireciona para o pipeline de 3 fases (deixa de gravar Gold direto)
CREATE OR REPLACE FUNCTION public.fn_process_raw_v2(
    p_supplier_id uuid,
    p_batch_size  integer DEFAULT 100,
    p_bulk_mode   boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE v_std jsonb; v_prom jsonb;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
  END IF;
  -- REDIRECIONADO 2026-06-05: não grava mais Bronze→Gold direto.
  v_std  := public.fn_standardize_supplier(p_supplier_id, p_batch_size);  -- Bronze→Silver
  v_prom := public.fn_promote_supplier(p_supplier_id, NULL);              -- Silver→Gold
  RETURN jsonb_build_object(
    'success', true, 'redirected', true,
    'pipeline', 'fn_standardize_supplier + fn_promote_supplier',
    'supplier_id', p_supplier_id,
    'parents_processed',  COALESCE((v_prom->>'pais_promovidos')::int, 0),
    'variants_processed', COALESCE((v_prom->>'variantes_promovidas')::int, 0),
    'standardize', v_std, 'promote', v_prom);
END;
$function$;

COMMENT ON FUNCTION public.fn_process_raw_v2(uuid, integer, boolean) IS
  'DEPRECATED/REDIRECIONADA 2026-06-05: delega ao pipeline Medallion de 3 fases '
  '(fn_standardize_supplier + fn_promote_supplier). Não grava mais Bronze->Gold direto.';

-- (2) Writer ad-hoc Bronze→Gold: neutralizado (sem escrita no Gold)
CREATE OR REPLACE FUNCTION public.process_supplier_product(
    p_supplier_id uuid,
    p_raw_data jsonb,
    p_supplier_reference text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  -- DEPRECATED 2026-06-05: gravava Bronze->Gold direto (pulava a Silver). Neutralizada.
  RETURN jsonb_build_object(
    'success', false, 'deprecated', true,
    'error', 'process_supplier_product descontinuada: use o pipeline Medallion '
             '(supplier_products_raw -> fn_standardize_supplier -> fn_promote_supplier)',
    'supplier_id', p_supplier_id, 'supplier_reference', p_supplier_reference);
END;
$function$;

COMMENT ON FUNCTION public.process_supplier_product(uuid, jsonb, text) IS
  'DEPRECATED 2026-06-05: writer Bronze->Gold direto neutralizado. Candidata a DROP em follow-up.';

-- (3) Batch legado: redireciona para o pipeline de 3 fases (preserva o shape de retorno)
CREATE OR REPLACE FUNCTION public.process_supplier_products_batch(
    p_supplier_id uuid,
    p_limit integer DEFAULT 100
)
RETURNS TABLE(staging_id uuid, supplier_reference text, success boolean,
              product_id uuid, variants_created integer, error_message text,
              processed_at timestamp with time zone)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE v_std jsonb; v_prom jsonb;
BEGIN
  -- REDIRECIONADO 2026-06-05: não usa mais process_supplier_product (Bronze->Gold direto).
  v_std  := public.fn_standardize_supplier(p_supplier_id, p_limit);  -- Bronze→Silver
  v_prom := public.fn_promote_supplier(p_supplier_id, NULL);         -- Silver→Gold

  staging_id         := NULL::uuid;
  supplier_reference := NULL::text;
  success            := COALESCE((v_prom->>'success')::boolean, false)
                        AND COALESCE((v_std->>'erros')::int, 0) = 0;
  product_id         := NULL::uuid;
  variants_created   := COALESCE((v_prom->>'variantes_promovidas')::integer, 0);
  error_message      := CASE WHEN success THEN NULL
                             ELSE 'erros no pipeline; ver fn_standardize_supplier/fn_promote_supplier' END;
  processed_at       := now();
  RETURN NEXT;
END;
$function$;

COMMENT ON FUNCTION public.process_supplier_products_batch(uuid, integer) IS
  'DEPRECATED/REDIRECIONADA 2026-06-05: delega ao pipeline Medallion 3 fases. Candidata a DROP em follow-up.';

