-- >>> BEGIN 20260605160400_silver_unify_05_promote_marks_raw_processed.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 5 (correção de integridade 3-fases)
-- fn_promote_variants_of_parent passa a marcar a RAW como 'processed'
-- quando a variante chega ao Gold.
-- ════════════════════════════════════════════════════════════════
-- PORQUÊ: no modelo de 3 fases, cada raw (1 SKU = 1 raw nos fornecedores
-- atuais) só está "concluída" quando sua variante é promovida ao Gold.
-- fn_promote_padronizacao só marca a raw REPRESENTANTE do grupo-pai; as
-- demais raws (uma por variante) ficavam 'pending' e seriam reprocessadas
-- indefinidamente pelo cron (a fila nunca drenava). O motor antigo
-- (fn_process_raw_v2) marcava cada raw individualmente — esta função
-- restaura essa garantia dentro do pipeline Silver.
--
-- Mudança cirúrgica: + UPDATE supplier_products_raw no laço de promoção.
-- ════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_promote_variants_of_parent(
    p_supplier_id uuid,
    p_parent_reference text
)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_pid uuid; v_org uuid; pv RECORD; v_vid uuid; v_count int := 0; v_attrs jsonb;
  v_existing_pid uuid;
BEGIN
  PERFORM set_config('app.write_source','pipeline',true);
  SELECT id, organization_id INTO v_pid, v_org FROM public.products
  WHERE supplier_id=p_supplier_id AND supplier_reference=p_parent_reference;
  IF v_pid IS NULL THEN RETURN jsonb_build_object('success',false,'error','produto_pai_nao_promovido','parent',p_parent_reference); END IF;

  FOR pv IN
    SELECT * FROM public.produtos_padronizacao_variantes
    WHERE supplier_id=p_supplier_id AND parent_reference=p_parent_reference AND status='standardized'
  LOOP
    v_attrs := jsonb_strip_nulls(jsonb_build_object('cor', pv.color_name, 'codigo_cor', pv.color_code, 'hex', pv.color_hex));

    -- idempotência por sku GLOBAL (sku é UNIQUE em product_variants); fallback (product_id, supplier_sku)
    SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants WHERE sku = pv.sku;
    IF v_vid IS NULL THEN
      SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants
      WHERE product_id=v_pid AND supplier_sku=pv.supplier_sku;
    END IF;

    IF v_vid IS NULL THEN
      INSERT INTO public.product_variants (product_id, sku, supplier_sku, name, attributes, color_name, color_code, color_hex, color_id, stock_quantity, is_active, last_sync_at, last_sync_supplier_id)
      VALUES (v_pid, pv.sku, pv.supplier_sku, COALESCE(pv.color_name, pv.sku), v_attrs,
              pv.color_name, pv.color_code, pv.color_hex, pv.color_id,
              COALESCE(pv.stock_quantity,0), COALESCE(pv.is_active,true), now(), p_supplier_id)
      ON CONFLICT (sku) DO UPDATE SET
        supplier_sku = EXCLUDED.supplier_sku,
        attributes   = COALESCE(public.product_variants.attributes,'{}'::jsonb) || EXCLUDED.attributes,
        color_name   = COALESCE(EXCLUDED.color_name, public.product_variants.color_name),
        color_code   = COALESCE(EXCLUDED.color_code, public.product_variants.color_code),
        color_hex    = COALESCE(EXCLUDED.color_hex, public.product_variants.color_hex),
        color_id     = COALESCE(EXCLUDED.color_id, public.product_variants.color_id),
        stock_quantity = COALESCE(EXCLUDED.stock_quantity, public.product_variants.stock_quantity),
        last_sync_at = now(), last_sync_supplier_id = EXCLUDED.last_sync_supplier_id
      RETURNING id INTO v_vid;
    ELSE
      UPDATE public.product_variants SET
        attributes = COALESCE(attributes,'{}'::jsonb) || v_attrs,
        color_name=COALESCE(pv.color_name,color_name), color_code=COALESCE(pv.color_code,color_code),
        color_hex=COALESCE(pv.color_hex,color_hex), color_id=COALESCE(pv.color_id,color_id),
        stock_quantity=COALESCE(pv.stock_quantity,stock_quantity), last_sync_at=now(), last_sync_supplier_id=p_supplier_id
      WHERE id=v_vid;
    END IF;

    IF pv.cost_price IS NOT NULL THEN
      INSERT INTO public.variant_supplier_sources (organization_id, variant_id, supplier_id, cost_price, supplier_sku, supplier_color_code, supplier_color_name, is_active, source, last_synced_at)
      VALUES (v_org, v_vid, p_supplier_id, pv.cost_price, pv.supplier_sku, pv.color_code, pv.color_name, true, 'silver', now())
      ON CONFLICT (variant_id, supplier_id) DO UPDATE SET
        cost_price          = EXCLUDED.cost_price,
        supplier_sku        = EXCLUDED.supplier_sku,
        supplier_color_code = EXCLUDED.supplier_color_code,
        supplier_color_name = EXCLUDED.supplier_color_name,
        is_active           = EXCLUDED.is_active,
        source              = EXCLUDED.source,
        last_synced_at      = EXCLUDED.last_synced_at;
    END IF;

    UPDATE public.produtos_padronizacao_variantes SET status='promoted', variant_id=v_vid, updated_at=now() WHERE id=pv.id;

    -- 3-fases: a raw desta variante está concluída ao chegar no Gold.
    IF pv.raw_id IS NOT NULL THEN
      UPDATE public.supplier_products_raw
         SET status='processed', processed_at=now(), product_id=v_pid, variant_id=v_vid
       WHERE id=pv.raw_id AND status <> 'processed';
    END IF;

    v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('success',true,'product_id',v_pid,'variantes_promovidas',v_count);
END;
$function$;

-- <<< END 20260605160400_silver_unify_05_promote_marks_raw_processed.sql <<<

-- >>> BEGIN 20260605160500_silver_unify_06_lockdown_standardize_supplier_grants.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 6 (segurança)
-- Tranca a execução de fn_standardize_supplier (SECURITY DEFINER).
-- ════════════════════════════════════════════════════════════════
-- Advisor: anon_/authenticated_security_definer_function_executable.
-- fn_standardize_supplier é SECURITY DEFINER (bypassa RLS) e nasceu com
-- EXECUTE para PUBLIC. O guard interno usa auth.uid() IS NOT NULL, que NÃO
-- barra o papel `anon` (uid NULL). Replicamos a ACL do motor fn_process_raw_v2:
-- somente postgres + service_role (o cron roda como service_role/postgres).
-- ════════════════════════════════════════════════════════════════

REVOKE ALL ON FUNCTION public.fn_standardize_supplier(uuid, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_standardize_supplier(uuid, integer) FROM anon;
REVOKE ALL ON FUNCTION public.fn_standardize_supplier(uuid, integer) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.fn_standardize_supplier(uuid, integer) TO postgres;
GRANT EXECUTE ON FUNCTION public.fn_standardize_supplier(uuid, integer) TO service_role;

-- <<< END 20260605160500_silver_unify_06_lockdown_standardize_supplier_grants.sql <<<

-- >>> BEGIN 20260605161000_fix_security_rls_and_search_paths.sql >>>

-- ════════════════════════════════════════════════════════════════
-- Security fixes — resolves 4 ERROR + 5 WARN advisors:
--   ERROR: RLS disabled on produtos_padronizacao_variantes
--   ERROR: RLS disabled on _backup_produtos_padronizacao_20260604
--   WARN (×5): mutable search_path on utility functions
-- ════════════════════════════════════════════════════════════════

-- ── 1. RLS on produtos_padronizacao_variantes ────────────────
ALTER TABLE public.produtos_padronizacao_variantes ENABLE ROW LEVEL SECURITY;

CREATE POLICY pad_var_authenticated_read
  ON public.produtos_padronizacao_variantes
  FOR SELECT TO authenticated
  USING (true);

CREATE POLICY pad_var_service_all
  ON public.produtos_padronizacao_variantes
  FOR ALL TO service_role
  USING (true) WITH CHECK (true);

-- ── 2. RLS on backup table (admin/service only) ──────────────
ALTER TABLE public._backup_produtos_padronizacao_20260604 ENABLE ROW LEVEL SECURITY;

CREATE POLICY backup_pad_service_only
  ON public._backup_produtos_padronizacao_20260604
  FOR ALL TO service_role
  USING (true) WITH CHECK (true);

-- ── 3. Fix mutable search_path — fn_log_price_change ────────
CREATE OR REPLACE FUNCTION public.fn_log_price_change()
RETURNS trigger LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
BEGIN
  RETURN NEW;
END;
$function$;

-- ── 4. Fix mutable search_path — fn_safe_int ────────────────
CREATE OR REPLACE FUNCTION public.fn_safe_int(p text)
RETURNS integer LANGUAGE plpgsql IMMUTABLE
SET search_path TO 'public'
AS $function$
DECLARE v numeric;
BEGIN
  IF p IS NULL OR TRIM(p)='' THEN RETURN NULL; END IF;
  v := replace(TRIM(p), ',', '.')::numeric;
  RETURN trunc(v)::integer;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END;
$function$;

-- ── 5. Fix mutable search_path — fn_safe_num ────────────────
CREATE OR REPLACE FUNCTION public.fn_safe_num(p text)
RETURNS numeric LANGUAGE plpgsql IMMUTABLE
SET search_path TO 'public'
AS $function$
BEGIN
  IF p IS NULL OR TRIM(p)='' THEN RETURN NULL; END IF;
  RETURN replace(TRIM(p), ',', '.')::numeric;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END;
$function$;

-- ── 6. Fix mutable search_path — fn_derive_parent_ref ───────
CREATE OR REPLACE FUNCTION public.fn_derive_parent_ref(
  p_supplier_id uuid, p_variant_ref text, p_raw jsonb
)
RETURNS text LANGUAGE plpgsql IMMUTABLE
SET search_path TO 'public'
AS $function$
BEGIN
  IF p_variant_ref IS NULL OR TRIM(p_variant_ref) = '' THEN
    RETURN NULL;
  END IF;

  -- Spot: referência-pai explícita no raw
  IF p_supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0' THEN
    RETURN COALESCE(NULLIF(TRIM(p_raw->>'ProdReference'), ''), p_variant_ref);
  END IF;

  -- XBZ: família explícita (CodigoAmigavel) — autoritativa da API
  IF p_supplier_id = 'd6718a29-e954-4c1b-bd84-03ea24884900' THEN
    RETURN COALESCE(NULLIF(TRIM(p_raw->>'CodigoAmigavel'), ''), regexp_replace(p_variant_ref, '-[^-]*$', ''));
  END IF;

  -- Asia: reconstrução heurística do pai (referencia do pai perdida na ingestão)
  IF p_supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118' THEN
    IF position('-' IN p_variant_ref) > 0 THEN
      RETURN regexp_replace(p_variant_ref, '-[^-]*$', '');
    ELSE
      RETURN p_variant_ref || 'P';
    END IF;
  END IF;

  -- Só Marcas: 1:1 — o código é o produto inteiro (hífen NÃO separa cor)
  IF p_supplier_id = '841cd690-210a-422a-908c-7676828db272' THEN
    RETURN p_variant_ref;
  END IF;

  -- demais: parte antes do ÚLTIMO hífen; sem hífen = é o próprio pai
  IF position('-' IN p_variant_ref) > 0 THEN
    RETURN regexp_replace(p_variant_ref, '-[^-]*$', '');
  END IF;
  RETURN p_variant_ref;
END;
$function$;

-- ── 7. Fix mutable search_path — fn_extract_color_from_title
CREATE OR REPLACE FUNCTION public.fn_extract_color_from_title(p_titulo text)
RETURNS text LANGUAGE plpgsql IMMUTABLE
SET search_path TO 'public'
AS $function$
DECLARE
  v_tok text;
  v_up  text;
BEGIN
  IF p_titulo IS NULL OR TRIM(p_titulo)='' THEN RETURN NULL; END IF;
  v_up := UPPER(p_titulo);

  SELECT m[1] INTO v_tok FROM regexp_matches(v_up,
    '\y(PRET[AO]|BRANC[AO]|AZUL|VERMELH[AO]|VERDE|CINZA|AMAREL[AO]|ROSA|ROX[AO]|LARANJA|BEGE|MARROM|DOURAD[AO]|PRATEAD[AO]|PRATA|NATURAL|BAMBU|MADEIRA|INOX|VINHO|CAQUI|NUDE|TURQUESA|LIL[AÁ]S|FUM[EÊ]|TRANSPARENTE|GRAFITE|CHUMBO|CORAL|MOSTARDA)\y'
  ) m LIMIT 1;

  IF v_tok IS NULL THEN RETURN NULL; END IF;

  RETURN CASE
    WHEN v_tok LIKE 'PRET%'    THEN 'Preto'
    WHEN v_tok LIKE 'BRANC%'   THEN 'Branco'
    WHEN v_tok LIKE 'VERMELH%' THEN 'Vermelho'
    WHEN v_tok LIKE 'AMAREL%'  THEN 'Amarelo'
    WHEN v_tok LIKE 'ROX%'     THEN 'Roxo'
    WHEN v_tok LIKE 'DOURAD%'  THEN 'Dourado'
    WHEN v_tok LIKE 'PRATEAD%' THEN 'Prata'
    WHEN v_tok='AZUL'          THEN 'Azul'
    WHEN v_tok='VERDE'         THEN 'Verde'
    WHEN v_tok='CINZA'         THEN 'Cinza'
    WHEN v_tok='ROSA'          THEN 'Rosa'
    WHEN v_tok='LARANJA'       THEN 'Laranja'
    WHEN v_tok='BEGE'          THEN 'Bege'
    WHEN v_tok='MARROM'        THEN 'Marrom'
    WHEN v_tok='PRATA'         THEN 'Prata'
    WHEN v_tok='NATURAL'       THEN 'Natural'
    WHEN v_tok='BAMBU'         THEN 'Bambu'
    WHEN v_tok='MADEIRA'       THEN 'Madeira'
    WHEN v_tok='INOX'          THEN 'Inox'
    WHEN v_tok='VINHO'         THEN 'Vinho'
    WHEN v_tok='CAQUI'         THEN 'Caqui'
    WHEN v_tok='NUDE'          THEN 'Nude'
    WHEN v_tok='TURQUESA'      THEN 'Turquesa'
    WHEN v_tok LIKE 'LIL%'     THEN 'Lilás'
    WHEN v_tok LIKE 'FUM%'     THEN 'Fumê'
    WHEN v_tok='TRANSPARENTE'  THEN 'Transparente'
    WHEN v_tok='GRAFITE'       THEN 'Grafite'
    WHEN v_tok='CHUMBO'        THEN 'Chumbo'
    WHEN v_tok='CORAL'         THEN 'Coral'
    WHEN v_tok='MOSTARDA'      THEN 'Mostarda'
    ELSE initcap(v_tok)
  END;
END;
$function$;

-- <<< END 20260605161000_fix_security_rls_and_search_paths.sql <<<

-- >>> BEGIN 20260605162000_fix_auth_rls_initplan.sql >>>

-- ════════════════════════════════════════════════════════════════
-- Performance fix: auth_rls_initplan — replace bare auth.uid()
-- with (SELECT auth.uid()) so PostgreSQL caches it per-statement
-- instead of re-evaluating per row. Affects 8 hot tables.
-- ════════════════════════════════════════════════════════════════

-- ── access_blocked_log ───────────────────────────────────────
DROP POLICY IF EXISTS access_blocked_log_admin_read   ON public.access_blocked_log;
DROP POLICY IF EXISTS access_blocked_log_admin_insert ON public.access_blocked_log;
CREATE POLICY access_blocked_log_admin_read   ON public.access_blocked_log
  FOR SELECT TO authenticated USING (is_admin_or_above((SELECT auth.uid())));
CREATE POLICY access_blocked_log_admin_insert ON public.access_blocked_log
  FOR INSERT TO authenticated WITH CHECK (is_admin_or_above((SELECT auth.uid())));

-- ── catalog_analytics ────────────────────────────────────────
DROP POLICY IF EXISTS users_read_own_analytics   ON public.catalog_analytics;
DROP POLICY IF EXISTS users_insert_own_analytics ON public.catalog_analytics;
CREATE POLICY users_read_own_analytics   ON public.catalog_analytics
  FOR SELECT TO authenticated USING ((SELECT auth.uid()) = user_id);
CREATE POLICY users_insert_own_analytics ON public.catalog_analytics
  FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid()) = user_id);

-- ── navigation_analytics ─────────────────────────────────────
DROP POLICY IF EXISTS users_read_own_nav_analytics   ON public.navigation_analytics;
DROP POLICY IF EXISTS users_insert_own_nav_analytics ON public.navigation_analytics;
CREATE POLICY users_read_own_nav_analytics   ON public.navigation_analytics
  FOR SELECT TO authenticated USING ((SELECT auth.uid()) = user_id);
CREATE POLICY users_insert_own_nav_analytics ON public.navigation_analytics
  FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid()) = user_id);

-- ── personalization_simulations ──────────────────────────────
DROP POLICY IF EXISTS "Sellers can manage own simulations" ON public.personalization_simulations;
DROP POLICY IF EXISTS persim_delete_own_or_admin           ON public.personalization_simulations;
DROP POLICY IF EXISTS persim_insert_own                    ON public.personalization_simulations;
DROP POLICY IF EXISTS persim_select_own_or_supervisor      ON public.personalization_simulations;
