-- >>> BEGIN 20260605191823_spot_bronze_multifeed_stock_and_customization_raw.sql >>>
-- ════════ SPOT BRONZE — landing multi-feed (produto + estoque + gravação) ════════
-- Produto continua em supplier_products_raw.raw_data (OptionalsComplete) via insert_supplier_product_raw.
-- Estoque: mesmo grão do SKU -> colunas dedicadas (trilha independente do produto).
-- Gravação: catálogo-wide -> companheira supplier_customization_raw (grão = table_code_option).

-- 1) ESTOQUE no bronze (metadata-only: defaults constantes/nullable, sem rewrite)
ALTER TABLE public.supplier_products_raw
  ADD COLUMN IF NOT EXISTS stock_data         jsonb,
  ADD COLUMN IF NOT EXISTS stock_hash         text,
  ADD COLUMN IF NOT EXISTS stock_status       supplier_raw_status NOT NULL DEFAULT 'pending',
  ADD COLUMN IF NOT EXISTS stock_synced_at    timestamptz,
  ADD COLUMN IF NOT EXISTS stock_processed_at timestamptz;

COMMENT ON COLUMN public.supplier_products_raw.stock_data IS
  'Feed Stocks cru deste SKU (Quantity, NextQuantity1..6/NextDate1..6, Country). Mesmo grao da variante; trilha independente: NAO polui raw_data nem content_hash do produto.';
COMMENT ON COLUMN public.supplier_products_raw.stock_status IS
  'Trilha Bronze->Gold do estoque (independente de status). RPC reseta p/ pending quando stock_hash muda.';
COMMENT ON COLUMN public.supplier_products_raw.stock_hash IS
  'sha256(stock_data) mantido pela RPC upsert_supplier_stock_raw (coluna plana de proposito p/ evitar rewrite da tabela).';

CREATE INDEX IF NOT EXISTS idx_spr_stock_pending
  ON public.supplier_products_raw (supplier_id, stock_synced_at)
  WHERE stock_status <> 'processed';

-- 2) GRAVAÇÃO catálogo-wide -> companheira no Bronze
CREATE TABLE IF NOT EXISTS public.supplier_customization_raw (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  supplier_id        uuid NOT NULL REFERENCES public.suppliers(id) ON DELETE RESTRICT,
  table_code         text NOT NULL,
  table_code_option  text NOT NULL,
  customization_type text,
  raw_data           jsonb NOT NULL CHECK (jsonb_typeof(raw_data) = 'object'),
  content_hash       text NOT NULL
                       GENERATED ALWAYS AS (encode(digest(raw_data::text,'sha256'),'hex')) STORED,
  status             supplier_raw_status NOT NULL DEFAULT 'pending',
  source_channel     text NOT NULL DEFAULT 'n8n',
  import_batch_id    uuid REFERENCES public.supplier_import_batches(id) ON DELETE SET NULL,
  imported_at        timestamptz NOT NULL DEFAULT now(),
  processed_at       timestamptz,
  process_errors     jsonb,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_scr_supplier_option UNIQUE (supplier_id, table_code_option)
);
COMMENT ON TABLE public.supplier_customization_raw IS
  'Bronze (layer) das tabelas de preco de gravacao por fornecedor. Grao = table_code_option (catalogo-wide, ~289 p/ SPOT). Aplicabilidade por SKU ja vive em supplier_products_raw.raw_data (CustomizationTables/Area1/TableCodes1...).';

CREATE INDEX IF NOT EXISTS idx_scr_unprocessed
  ON public.supplier_customization_raw (supplier_id, imported_at)
  WHERE status <> 'processed';

-- 3) RPCs de gravação (idempotentes; reset p/ 'pending' só quando o hash muda)
CREATE OR REPLACE FUNCTION public.upsert_supplier_stock_raw(
  p_supplier_id uuid, p_supplier_reference text, p_stock_data jsonb,
  p_import_batch_id uuid DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SET search_path TO 'public','extensions' AS $$
DECLARE v_id uuid; v_hash text;
BEGIN
  v_hash := encode(digest(p_stock_data::text,'sha256'),'hex');
  INSERT INTO supplier_products_raw
    (supplier_id, supplier_reference, supplier_sku, raw_data,
     stock_data, stock_hash, stock_synced_at, status, import_batch_id)
  VALUES
    (p_supplier_id, p_supplier_reference, p_supplier_reference, '{}'::jsonb,
     p_stock_data, v_hash, now(), 'skipped'::supplier_raw_status, p_import_batch_id)
  ON CONFLICT (supplier_id, supplier_reference) DO UPDATE SET
     stock_data      = EXCLUDED.stock_data,
     stock_hash      = v_hash,
     stock_synced_at = now(),
     import_batch_id = COALESCE(EXCLUDED.import_batch_id, supplier_products_raw.import_batch_id),
     stock_status    = CASE WHEN supplier_products_raw.stock_hash IS DISTINCT FROM v_hash
                            THEN 'pending'::supplier_raw_status ELSE supplier_products_raw.stock_status END,
     updated_at      = now()
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;
COMMENT ON FUNCTION public.upsert_supplier_stock_raw(uuid,text,jsonb,uuid) IS
  'Grava feed Stocks na linha do SKU (trilha stock_*). Stub status=skipped se o produto ainda nao existir; reset stock_status->pending so quando o estoque muda.';

CREATE OR REPLACE FUNCTION public.upsert_supplier_customization_raw(
  p_supplier_id uuid, p_table_code_option text, p_raw_data jsonb,
  p_table_code text DEFAULT NULL, p_customization_type text DEFAULT NULL,
  p_import_batch_id uuid DEFAULT NULL)
RETURNS uuid LANGUAGE plpgsql SET search_path TO 'public','extensions' AS $$
DECLARE v_id uuid; v_hash text;
BEGIN
  v_hash := encode(digest(p_raw_data::text,'sha256'),'hex');
  INSERT INTO supplier_customization_raw
    (supplier_id, table_code, table_code_option, customization_type, raw_data, import_batch_id)
  VALUES (p_supplier_id,
          COALESCE(p_table_code, regexp_replace(p_table_code_option, '-[^-]+$', '')),
          p_table_code_option, p_customization_type, p_raw_data, p_import_batch_id)
  ON CONFLICT (supplier_id, table_code_option) DO UPDATE SET
     raw_data           = EXCLUDED.raw_data,
     customization_type = COALESCE(EXCLUDED.customization_type, supplier_customization_raw.customization_type),
     import_batch_id    = COALESCE(EXCLUDED.import_batch_id, supplier_customization_raw.import_batch_id),
     status             = CASE WHEN supplier_customization_raw.content_hash IS DISTINCT FROM v_hash
                               THEN 'pending'::supplier_raw_status ELSE supplier_customization_raw.status END,
     updated_at         = now()
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;
COMMENT ON FUNCTION public.upsert_supplier_customization_raw(uuid,text,jsonb,text,text,uuid) IS
  'Grava feed CustomizationTables (grao = table_code_option). Idempotente por content_hash.';

-- 4) Hardening (espelha o padrão do bronze)
ALTER TABLE public.supplier_customization_raw ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.supplier_customization_raw FROM anon, authenticated;
GRANT  ALL ON public.supplier_customization_raw TO service_role;
REVOKE EXECUTE ON FUNCTION public.upsert_supplier_stock_raw(uuid,text,jsonb,uuid)                   FROM anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.upsert_supplier_customization_raw(uuid,text,jsonb,text,text,uuid) FROM anon, authenticated;;

-- <<< END 20260605191823_spot_bronze_multifeed_stock_and_customization_raw.sql <<<

-- >>> BEGIN 20260605205536_spot_variant_stock_from_stock_data.sql >>>
CREATE OR REPLACE FUNCTION public.fn_standardize_variant(p_raw_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r public.supplier_products_raw%ROWTYPE;
  v_parent text; v_code text; v_apiid text; v_cname text; v_chex text;
  v_col RECORD; v_sku text; v_supplier_sku text; v_stock integer; v_cost numeric; v_var_id uuid;
  v_fname text; v_fcode text; v_fhex text; v_canonical_id uuid;
  v_SPOT uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_XBZ  uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
  v_ASIA uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_SM   uuid := '841cd690-210a-422a-908c-7676828db272';
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id=p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','raw_nao_encontrado'); END IF;
  v_parent := public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data);

  IF r.supplier_id=v_SPOT THEN
    -- SPOT: cor por ColorCode (lookup); ColorDesc1/ColorHex1 como descritivos reais do feed.
    -- Estoque vem do feed Stocks (coluna stock_data), NAO do raw_data (OptionalsComplete nao traz estoque).
    v_code  := r.raw_data->>'ColorCode';
    v_cname := COALESCE(NULLIF(TRIM(r.raw_data->>'ColorName'),''), r.raw_data->>'ColorDesc1');
    v_chex  := COALESCE(NULLIF(TRIM(r.raw_data->>'ColorHex'),''),  r.raw_data->>'ColorHex1');
    v_supplier_sku := r.raw_data->>'Sku';
    v_stock := public.fn_safe_int(COALESCE(r.stock_data->>'Quantity', r.raw_data->>'StockQuantity'));
    v_cost  := public.fn_safe_num(r.raw_data->>'Price1');
    v_sku   := r.supplier_reference;
  ELSIF r.supplier_id=v_XBZ THEN
    v_apiid:=r.raw_data->>'CorWebPrincipalId'; v_cname:=r.raw_data->>'CorWebPrincipal';
    v_supplier_sku:=r.raw_data->>'CodigoComposto'; v_stock:=public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel');
    v_cost:=public.fn_safe_num(r.raw_data->>'PrecoVenda');   -- PrecoVenda do XBZ = CUSTO (silver_08e)
    v_sku:='XBZ-'||r.supplier_reference;
  ELSIF r.supplier_id=v_ASIA THEN
    v_cname:=r.raw_data->>'var_cor_nome'; v_chex:=r.raw_data->>'var_cor_hex';
    v_supplier_sku:=COALESCE(r.raw_data->>'var_referencia', r.supplier_reference);
    v_stock:=public.fn_safe_int(r.raw_data->>'var_estoque');
    v_cost:=public.fn_safe_num(r.raw_data->>'preco');        -- preco da Asia = CUSTO (silver_08e)
    v_sku:='ASIA-'||r.supplier_reference;
  ELSIF r.supplier_id=v_SM THEN
    -- Só Marcas: sem campo de cor. Extrai do título; hex da rede de produtos_similares.
    v_cname:=public.fn_extract_color_from_title(r.raw_data->>'titulo');
    v_chex := (SELECT split_part(item,'|',2)
               FROM unnest(string_to_array(r.raw_data->>'produtos_similares', ';')) item
               WHERE split_part(item,'|',1)=r.supplier_reference
                 AND split_part(item,'|',2) ~* '^#[0-9a-f]{6}$' LIMIT 1);
    v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque');
    v_cost:=public.fn_safe_num(r.raw_data->>'preco_sem_gravacao_sem_impostos');
    v_sku:=r.supplier_reference;
  ELSE
    v_cname:=r.raw_data->>'cor'; v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque'); v_cost:=public.fn_safe_num(r.raw_data->>'preco_base');
    v_sku:=r.supplier_reference;
  END IF;

  -- resolução do fornecedor (descritivos). Para SM não há catálogo, usa o extraído.
  SELECT * INTO v_col FROM public.fn_match_supplier_color(r.supplier_id, v_code, v_apiid, v_cname, v_chex);
  v_fname := COALESCE(v_col.color_name, v_cname);
  v_fcode := COALESCE(v_col.color_code, v_code);
  v_fhex  := COALESCE(v_col.color_hex,  v_chex);
  v_canonical_id := public.fn_match_canonical_color(v_fname, v_fhex);

  INSERT INTO public.produtos_padronizacao_variantes AS pv (
    raw_id, supplier_id, parent_reference, variant_reference,
    sku, supplier_sku, color_name, color_code, color_hex, color_id,
    stock_quantity, cost_price, is_active, status
  ) VALUES (
    r.id, r.supplier_id, v_parent, r.supplier_reference, v_sku, v_supplier_sku,
    v_fname, v_fcode, v_fhex, v_canonical_id,
    v_stock, v_cost, true, 'standardized'::public.produtos_padronizacao_status
  )
  ON CONFLICT (supplier_id, variant_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, parent_reference=EXCLUDED.parent_reference, sku=EXCLUDED.sku, supplier_sku=EXCLUDED.supplier_sku,
    color_name=EXCLUDED.color_name, color_code=EXCLUDED.color_code, color_hex=EXCLUDED.color_hex, color_id=EXCLUDED.color_id,
    stock_quantity=EXCLUDED.stock_quantity, cost_price=EXCLUDED.cost_price, is_active=EXCLUDED.is_active,
    status=EXCLUDED.status, updated_at=now()
  RETURNING pv.id INTO v_var_id;

  RETURN jsonb_build_object('success',true,'variante_id',v_var_id,'parent',v_parent,
                            'cor',v_fname,'hex',v_fhex,'color_id_canonico',v_canonical_id);
END;
$function$;;

-- <<< END 20260605205536_spot_variant_stock_from_stock_data.sql <<<

-- >>> BEGIN 20260605205624_deprecate_fn_spot_to_silver_redirect_canonical.sql >>>
CREATE OR REPLACE FUNCTION public.fn_spot_to_silver(p_bronze_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r public.supplier_products_raw%ROWTYPE;
  v_parent text; v_p jsonb; v_v jsonb;
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id=p_bronze_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','raw_nao_encontrado'); END IF;

  -- DEPRECATED 2026-06: antes gravava nas tabelas silver_* (legadas/abandonadas).
  -- Agora DELEGA para o pipeline canonico dirigido pelo de-para (supplier_field_mappings):
  --   fn_standardize_raw (parent) + fn_standardize_variant (variante) -> produtos_padronizacao(_variantes).
  v_parent := public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data);
  v_p := public.fn_standardize_raw(p_bronze_id, v_parent);
  v_v := public.fn_standardize_variant(p_bronze_id);

  RETURN jsonb_build_object(
    'success',    true,
    'deprecated', true,
    'note', 'fn_spot_to_silver redirecionada para fn_standardize_raw + fn_standardize_variant (Silver canonico produtos_padronizacao).',
    'parent',  v_p,
    'variant', v_v
  );
END;
$function$;;

-- <<< END 20260605205624_deprecate_fn_spot_to_silver_redirect_canonical.sql <<<

-- >>> BEGIN 20260605210000_silver_unify_07_adapt_staging_chain_to_silver.sql >>>
-- ════════════════════════════════════════════════════════════════
-- UNIFICAÇÃO MEDALLION — Fase 7
-- Adapta a cadeia legada "staging" para Bronze → Silver (de-para).
-- ════════════════════════════════════════════════════════════════
-- Descoberto em auditoria exaustiva do pg_proc (2026-06-05): havia uma
-- cadeia legada de ingestão que gravava Bronze → Gold DIRETO (pulava a Silver)
-- e NÃO estava deprecada nem adaptada:
--   fn_process_staging_batch → fn_process_all_staged_products → fn_process_staged_product → products
-- Estava DORMENTE (raiz órfã: 0 chamadores; ramo de variantes referenciava
-- fn_process_all_staged_variants, que NÃO EXISTE; fila de raws vazia), mas era
-- uma mina latente que violava a regra das 3 fases.
--
-- Decisão (usuário): ADAPTAR para a nova arquitetura Bronze → Prata, não dropar.
-- As 3 funções viram wrappers finos sobre o pipeline canônico (produtos_padronizacao*).
-- Promoção Silver → Gold continua a cargo do cron oficial (process_pending_batches
-- → fn_promote_supplier). Idempotente; sem escrita Gold direta.
-- ════════════════════════════════════════════════════════════════

-- 1) Folha: 1 raw → Silver (variante + pai)
CREATE OR REPLACE FUNCTION public.fn_process_staged_product(p_staging_id uuid)
RETURNS jsonb LANGUAGE plpgsql SET search_path TO 'public','extensions'
AS $function$
DECLARE r record; v_vres jsonb; v_pres jsonb; v_parent text;
BEGIN
  SELECT supplier_id, supplier_reference, raw_data INTO r
  FROM public.supplier_products_raw WHERE id = p_staging_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'raw_nao_encontrado', 'id', p_staging_id);
  END IF;
  -- ADAPTADO 2026-06-05: Bronze→Silver (de-para), não mais Bronze→Gold direto.
  v_vres   := public.fn_standardize_variant(p_staging_id);
  v_parent := COALESCE(NULLIF(v_vres->>'parent',''),
                       public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data));
  v_pres   := public.fn_standardize_parent(r.supplier_id, v_parent);
  RETURN jsonb_build_object('success', COALESCE((v_pres->>'success')::boolean, false),
    'adapted', 'bronze->silver', 'staging_id', p_staging_id, 'variant', v_vres, 'parent', v_pres);
END;
$function$;
COMMENT ON FUNCTION public.fn_process_staged_product(uuid) IS
  'ADAPTADO 2026-06-05: Bronze->Silver via fn_standardize_variant + fn_standardize_parent. Nao grava mais Bronze->Gold direto.';

-- 2) Batch por fornecedor → Silver
CREATE OR REPLACE FUNCTION public.fn_process_all_staged_products(p_supplier_id uuid DEFAULT NULL, p_limit integer DEFAULT 100)
RETURNS jsonb LANGUAGE plpgsql SET search_path TO 'public','extensions'
AS $function$
DECLARE v jsonb;
BEGIN
  IF p_supplier_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'supplier_id_obrigatorio');
  END IF;
  v := public.fn_standardize_supplier(p_supplier_id, p_limit);   -- Bronze→Silver
  RETURN jsonb_build_object('success', true, 'adapted', 'bronze->silver', 'standardize', v);
END;
$function$;
COMMENT ON FUNCTION public.fn_process_all_staged_products(uuid, integer) IS
  'ADAPTADO 2026-06-05: delega a fn_standardize_supplier (Bronze->Silver de-para).';

-- 3) Raiz da cadeia → Silver (promoção a Gold = cron oficial)
CREATE OR REPLACE FUNCTION public.fn_process_staging_batch(p_batch_id uuid DEFAULT NULL, p_supplier_id uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SET search_path TO 'public','extensions'
AS $function$
DECLARE v_std jsonb;
BEGIN
  IF p_supplier_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'supplier_id_obrigatorio');
  END IF;
  -- ADAPTADO 2026-06-05: Bronze→Silver via pipeline canônico (antes: staging→Gold direto +
  -- ramo de variantes inexistente). Promoção Silver→Gold = cron oficial (process_pending_batches).
  v_std := public.fn_standardize_supplier(p_supplier_id, NULL);
  RETURN jsonb_build_object('success', true, 'adapted', 'bronze->silver',
    'batch_id', p_batch_id, 'supplier_id', p_supplier_id, 'standardize', v_std);
END;
$function$;
COMMENT ON FUNCTION public.fn_process_staging_batch(uuid, uuid) IS
  'ADAPTADO 2026-06-05: delega a fn_standardize_supplier (Bronze->Silver). Promocao a Gold pelo cron oficial.';

-- <<< END 20260605210000_silver_unify_07_adapt_staging_chain_to_silver.sql <<<

-- >>> BEGIN 20260605223326_silver_widen_padronizacao_optionb.sql >>>
-- Opção B: alargar o Silver para carregar campos ricos até o Gold.
-- PARENT: flags, taxonomia, imagem de caixa, arrays.
ALTER TABLE public.produtos_padronizacao
  ADD COLUMN IF NOT EXISTS product_type           text,
  ADD COLUMN IF NOT EXISTS origin_country          varchar,
  ADD COLUMN IF NOT EXISTS combined_sizes          varchar,
  ADD COLUMN IF NOT EXISTS box_image               text,
  ADD COLUMN IF NOT EXISTS is_textil               boolean,
  ADD COLUMN IF NOT EXISTS is_stockout             boolean,
  ADD COLUMN IF NOT EXISTS is_online_exclusive     boolean,
  ADD COLUMN IF NOT EXISTS is_new                  boolean,
  ADD COLUMN IF NOT EXISTS has_colors              boolean,
  ADD COLUMN IF NOT EXISTS has_sizes               boolean,
  ADD COLUMN IF NOT EXISTS allows_personalization  boolean,
  ADD COLUMN IF NOT EXISTS tags                    jsonb,
  ADD COLUMN IF NOT EXISTS materials               jsonb,
  ADD COLUMN IF NOT EXISTS meta_keywords           text[];

-- VARIANTE: 5 faixas, reposição (1..3), multiplicador, imagens/vídeo do fornecedor.
ALTER TABLE public.produtos_padronizacao_variantes
  ADD COLUMN IF NOT EXISTS cost_price_1       numeric,
  ADD COLUMN IF NOT EXISTS cost_price_2       numeric,
  ADD COLUMN IF NOT EXISTS cost_price_3       numeric,
  ADD COLUMN IF NOT EXISTS cost_price_4       numeric,
  ADD COLUMN IF NOT EXISTS cost_price_5       numeric,
  ADD COLUMN IF NOT EXISTS min_qty_1          integer,
  ADD COLUMN IF NOT EXISTS min_qty_2          integer,
  ADD COLUMN IF NOT EXISTS min_qty_3          integer,
  ADD COLUMN IF NOT EXISTS min_qty_4          integer,
  ADD COLUMN IF NOT EXISTS min_qty_5          integer,
  ADD COLUMN IF NOT EXISTS next_quantity_1    integer,
  ADD COLUMN IF NOT EXISTS next_quantity_2    integer,
  ADD COLUMN IF NOT EXISTS next_quantity_3    integer,
  ADD COLUMN IF NOT EXISTS next_date_1        date,
  ADD COLUMN IF NOT EXISTS next_date_2        date,
  ADD COLUMN IF NOT EXISTS next_date_3        date,
  ADD COLUMN IF NOT EXISTS sale_multiplier    integer,
  ADD COLUMN IF NOT EXISTS supplier_thumbnail text,
  ADD COLUMN IF NOT EXISTS supplier_images    jsonb,
  ADD COLUMN IF NOT EXISTS supplier_videos    jsonb;;

