-- >>> BEGIN 20260605223411_standardize_raw_optionb_rich_products.sql >>>
CREATE OR REPLACE FUNCTION public.fn_standardize_raw(p_raw_id uuid, p_override_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r          public.supplier_products_raw%ROWTYPE;
  m          RECORD;
  v_val      text; v_tx text; v_path text;
  v_assigns  jsonb := '{}'::jsonb;
  v_errs     jsonb := '[]'::jsonb;
  v_ncm text; v_ncm_raw text;
  v_pad_id uuid; v_ref text;
  v_status public.produtos_padronizacao_status;
  v_tags jsonb; v_materials jsonb; v_meta text[]; v_arr jsonb;
  v_cols text[] := ARRAY[
    'name','description','short_description','cost_price','suggested_price','stock_quantity',
    'primary_image_url','images','ncm_code','weight_g','height_cm','width_cm','length_cm',
    'dimensions_display','box_length_cm','box_width_cm','box_height_cm','box_weight_kg',
    'box_volume_cm3','box_quantity','box_inner_quantity','brand','packing_type','repacking_type',
    'capacities','capacity_ml','min_quantity','warranty_months','ipi_rate','engraving_type','is_active',
    -- Opção B (campos ricos):
    'product_type','origin_country','combined_sizes','box_image',
    'is_textil','is_stockout','is_online_exclusive','is_new','has_colors','has_sizes','allows_personalization',
    'tags','materials','meta_keywords'];
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'raw_nao_encontrado'); END IF;
  v_ref := COALESCE(NULLIF(TRIM(p_override_reference),''), r.supplier_reference);

  FOR m IN
    SELECT source_field, source_path, target_field, transform_type, transform_config, source_unit, target_unit
    FROM public.supplier_field_mappings
    WHERE supplier_id=r.supplier_id AND target_table='products' AND is_active=TRUE AND target_field=ANY(v_cols)
    ORDER BY priority NULLS LAST
  LOOP
    v_path := NULLIF(regexp_replace(COALESCE(NULLIF(m.source_path,''), m.source_field, ''), '^\$\.?', ''), '');
    IF v_path IS NULL THEN v_val := NULL;
    ELSIF position('.' IN v_path) > 0 THEN v_val := r.raw_data #>> string_to_array(v_path, '.');
    ELSE v_val := r.raw_data ->> v_path; END IF;
    CONTINUE WHEN v_val IS NULL OR TRIM(v_val)='';

    -- Campos de array/jsonb: split respeitando o delimiter da config (default ',').
    IF m.target_field IN ('tags','materials') THEN
      v_arr := (SELECT to_jsonb(COALESCE(array_agg(btrim(e)) FILTER (WHERE btrim(e) <> ''), ARRAY[]::text[]))
                FROM unnest(string_to_array(v_val, COALESCE(m.transform_config->>'delimiter', ','))) e);
      IF m.target_field='tags' THEN v_tags := v_arr; ELSE v_materials := v_arr; END IF;
      CONTINUE;
    ELSIF m.target_field='meta_keywords' THEN
      v_meta := (SELECT COALESCE(array_agg(btrim(e)) FILTER (WHERE btrim(e) <> ''), ARRAY[]::text[])
                 FROM unnest(string_to_array(v_val, COALESCE(m.transform_config->>'delimiter', ','))) e);
      CONTINUE;
    END IF;

    BEGIN
      v_tx := public.fn_apply_transform(v_val, m.transform_type, m.transform_config, m.source_unit, m.target_unit, r.supplier_id);
    EXCEPTION WHEN OTHERS THEN v_tx := v_val;
      v_errs := v_errs || jsonb_build_object('field',m.target_field,'stage','transform','msg',SQLERRM);
    END;
    -- transforms órfãos (ex. bool_sim_nao) retornam o valor cru; a coerção final trata
    IF v_tx IS NOT NULL THEN v_assigns := v_assigns || jsonb_build_object(m.target_field, v_tx); END IF;
  END LOOP;

  -- NCM: inclui Taric (Spot usa código aduaneiro Taric em vez de Ncm)
  v_ncm_raw := COALESCE(v_assigns->>'ncm_code', r.raw_data->>'ncm', r.raw_data->>'Ncm', r.raw_data->>'Taric');
  v_ncm := public.fn_normalize_ncm(v_ncm_raw);
  IF v_ncm IS NOT NULL THEN v_assigns := v_assigns || jsonb_build_object('ncm_code', v_ncm);
  ELSIF v_ncm_raw IS NOT NULL THEN
    v_errs := v_errs || jsonb_build_object('field','ncm_code','stage','validate','msg','ncm_invalido','raw',v_ncm_raw);
    v_assigns := v_assigns - 'ncm_code';
  END IF;

  v_status := (CASE WHEN jsonb_array_length(v_errs)>0 AND v_assigns->>'name' IS NULL THEN 'rejected' ELSE 'standardized' END)::public.produtos_padronizacao_status;

  INSERT INTO public.produtos_padronizacao AS pad (
    raw_id, supplier_id, supplier_reference,
    name, description, short_description, cost_price, suggested_price, stock_quantity,
    primary_image_url, images, ncm_code, weight_g, height_cm, width_cm, length_cm,
    dimensions_display, box_length_cm, box_width_cm, box_height_cm, box_weight_kg,
    box_volume_cm3, box_quantity, box_inner_quantity, brand, packing_type, repacking_type,
    capacities, capacity_ml, min_quantity, warranty_months, ipi_rate, engraving_type, is_active,
    product_type, origin_country, combined_sizes, box_image,
    is_textil, is_stockout, is_online_exclusive, is_new, has_colors, has_sizes, allows_personalization,
    tags, materials, meta_keywords,
    status, validation_errors, standardized_at
  ) VALUES (
    r.id, r.supplier_id, v_ref,
    v_assigns->>'name', v_assigns->>'description', v_assigns->>'short_description',
    public.fn_safe_num(v_assigns->>'cost_price'), public.fn_safe_num(v_assigns->>'suggested_price'), public.fn_safe_int(v_assigns->>'stock_quantity'),
    v_assigns->>'primary_image_url',
    CASE WHEN v_assigns ? 'images' THEN (v_assigns->'images') ELSE NULL END,
    v_assigns->>'ncm_code', public.fn_safe_int(v_assigns->>'weight_g'),
    public.fn_safe_num(v_assigns->>'height_cm'), public.fn_safe_num(v_assigns->>'width_cm'), public.fn_safe_num(v_assigns->>'length_cm'),
    v_assigns->>'dimensions_display',
    public.fn_safe_num(v_assigns->>'box_length_cm'), public.fn_safe_num(v_assigns->>'box_width_cm'), public.fn_safe_num(v_assigns->>'box_height_cm'),
    public.fn_safe_num(v_assigns->>'box_weight_kg'), public.fn_safe_num(v_assigns->>'box_volume_cm3'),
    public.fn_safe_int(v_assigns->>'box_quantity'), public.fn_safe_int(v_assigns->>'box_inner_quantity'),
    v_assigns->>'brand', v_assigns->>'packing_type', v_assigns->>'repacking_type',
    v_assigns->>'capacities', public.fn_safe_int(v_assigns->>'capacity_ml'), public.fn_safe_int(v_assigns->>'min_quantity'),
    public.fn_safe_int(v_assigns->>'warranty_months'), public.fn_safe_num(v_assigns->>'ipi_rate'), v_assigns->>'engraving_type',
    COALESCE(public.fn_safe_bool(v_assigns->>'is_active'), true),
    v_assigns->>'product_type', v_assigns->>'origin_country', v_assigns->>'combined_sizes', v_assigns->>'box_image',
    public.fn_safe_bool(v_assigns->>'is_textil'), public.fn_safe_bool(v_assigns->>'is_stockout'),
    public.fn_safe_bool(v_assigns->>'is_online_exclusive'), public.fn_safe_bool(v_assigns->>'is_new'),
    public.fn_safe_bool(v_assigns->>'has_colors'), public.fn_safe_bool(v_assigns->>'has_sizes'),
    (v_assigns ? 'allows_personalization'),
    v_tags, v_materials, v_meta,
    v_status, CASE WHEN jsonb_array_length(v_errs)>0 THEN v_errs ELSE NULL END, now()
  )
  ON CONFLICT (supplier_id, supplier_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, name=EXCLUDED.name, description=EXCLUDED.description,
    short_description=EXCLUDED.short_description, cost_price=EXCLUDED.cost_price,
    suggested_price=EXCLUDED.suggested_price, stock_quantity=EXCLUDED.stock_quantity,
    primary_image_url=EXCLUDED.primary_image_url, images=EXCLUDED.images, ncm_code=EXCLUDED.ncm_code,
    weight_g=EXCLUDED.weight_g, height_cm=EXCLUDED.height_cm, width_cm=EXCLUDED.width_cm, length_cm=EXCLUDED.length_cm,
    dimensions_display=EXCLUDED.dimensions_display, box_length_cm=EXCLUDED.box_length_cm, box_width_cm=EXCLUDED.box_width_cm,
    box_height_cm=EXCLUDED.box_height_cm, box_weight_kg=EXCLUDED.box_weight_kg, box_volume_cm3=EXCLUDED.box_volume_cm3,
    box_quantity=EXCLUDED.box_quantity, box_inner_quantity=EXCLUDED.box_inner_quantity, brand=EXCLUDED.brand,
    packing_type=EXCLUDED.packing_type, repacking_type=EXCLUDED.repacking_type, capacities=EXCLUDED.capacities,
    capacity_ml=EXCLUDED.capacity_ml, min_quantity=EXCLUDED.min_quantity, warranty_months=EXCLUDED.warranty_months,
    ipi_rate=EXCLUDED.ipi_rate, engraving_type=EXCLUDED.engraving_type, is_active=EXCLUDED.is_active,
    product_type=EXCLUDED.product_type, origin_country=EXCLUDED.origin_country, combined_sizes=EXCLUDED.combined_sizes,
    box_image=EXCLUDED.box_image, is_textil=EXCLUDED.is_textil, is_stockout=EXCLUDED.is_stockout,
    is_online_exclusive=EXCLUDED.is_online_exclusive, is_new=EXCLUDED.is_new, has_colors=EXCLUDED.has_colors,
    has_sizes=EXCLUDED.has_sizes, allows_personalization=EXCLUDED.allows_personalization,
    tags=EXCLUDED.tags, materials=EXCLUDED.materials, meta_keywords=EXCLUDED.meta_keywords,
    status=EXCLUDED.status, validation_errors=EXCLUDED.validation_errors, standardized_at=now(), updated_at=now()
  RETURNING pad.id INTO v_pad_id;

  RETURN jsonb_build_object('success',true,'padronizacao_id',v_pad_id,'reference',v_ref,
                            'campos',(SELECT count(*) FROM jsonb_object_keys(v_assigns)),'erros',v_errs);
END;
$function$;;

-- <<< END 20260605223411_standardize_raw_optionb_rich_products.sql <<<

-- >>> BEGIN 20260605223503_standardize_variant_optionb_tiers_stock_images.sql >>>
CREATE OR REPLACE FUNCTION public.fn_standardize_variant(p_raw_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r public.supplier_products_raw%ROWTYPE;
  v_parent text; v_code text; v_apiid text; v_cname text; v_chex text;
  v_col RECORD; v_sku text; v_supplier_sku text; v_stock integer; v_cost numeric; v_var_id uuid;
  v_fname text; v_fcode text; v_fhex text; v_canonical_id uuid;
  -- Opção B (operacional/SPOT):
  v_cp1 numeric; v_cp2 numeric; v_cp3 numeric; v_cp4 numeric; v_cp5 numeric;
  v_mq1 int; v_mq2 int; v_mq3 int; v_mq4 int; v_mq5 int;
  v_nq1 int; v_nq2 int; v_nq3 int; v_nd1 date; v_nd2 date; v_nd3 date;
  v_mult int; v_thumb text; v_images jsonb; v_videos jsonb;
  v_base text := 'https://www.spotgifts.com.br/fotos/produtos/';
  v_SPOT uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_XBZ  uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
  v_ASIA uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_SM   uuid := '841cd690-210a-422a-908c-7676828db272';
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id=p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','raw_nao_encontrado'); END IF;
  v_parent := public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data);

  IF r.supplier_id=v_SPOT THEN
    -- SPOT: cor por ColorCode (lookup); ColorDesc1/ColorHex1 = descritivos reais do feed.
    -- Estoque do feed Stocks (stock_data). Faixas/reposição/multiplier/imagens = Opção B.
    v_code  := r.raw_data->>'ColorCode';
    v_cname := COALESCE(NULLIF(TRIM(r.raw_data->>'ColorName'),''), r.raw_data->>'ColorDesc1');
    v_chex  := COALESCE(NULLIF(TRIM(r.raw_data->>'ColorHex'),''),  r.raw_data->>'ColorHex1');
    v_supplier_sku := r.raw_data->>'Sku';
    v_stock := public.fn_safe_int(COALESCE(r.stock_data->>'Quantity', r.raw_data->>'StockQuantity'));
    v_cost  := public.fn_safe_num(r.raw_data->>'Price1');
    v_sku   := r.supplier_reference;
    -- 5 faixas
    v_cp1:=public.fn_safe_num(r.raw_data->>'Price1'); v_cp2:=public.fn_safe_num(r.raw_data->>'Price2');
    v_cp3:=public.fn_safe_num(r.raw_data->>'Price3'); v_cp4:=public.fn_safe_num(r.raw_data->>'Price4');
    v_cp5:=public.fn_safe_num(r.raw_data->>'Price5');
    v_mq1:=public.fn_safe_int(r.raw_data->>'MinQt1'); v_mq2:=public.fn_safe_int(r.raw_data->>'MinQt2');
    v_mq3:=public.fn_safe_int(r.raw_data->>'MinQt3'); v_mq4:=public.fn_safe_int(r.raw_data->>'MinQt4');
    v_mq5:=public.fn_safe_int(r.raw_data->>'MinQt5');
    -- reposição (do stock_data)
    v_nq1:=public.fn_safe_int(r.stock_data->>'NextQuantity1'); v_nq2:=public.fn_safe_int(r.stock_data->>'NextQuantity2'); v_nq3:=public.fn_safe_int(r.stock_data->>'NextQuantity3');
    v_nd1:=CASE WHEN r.stock_data->>'NextDate1' ~ '^\d{4}-\d{2}-\d{2}' THEN left(r.stock_data->>'NextDate1',10)::date END;
    v_nd2:=CASE WHEN r.stock_data->>'NextDate2' ~ '^\d{4}-\d{2}-\d{2}' THEN left(r.stock_data->>'NextDate2',10)::date END;
    v_nd3:=CASE WHEN r.stock_data->>'NextDate3' ~ '^\d{4}-\d{2}-\d{2}' THEN left(r.stock_data->>'NextDate3',10)::date END;
    v_mult:=public.fn_safe_int(r.raw_data->>'Multiplier');
    v_thumb:=CASE WHEN NULLIF(trim(r.raw_data->>'MainImage'),'') IS NOT NULL THEN v_base||trim(r.raw_data->>'MainImage') END;
    v_images:=(SELECT to_jsonb(COALESCE(array_agg(v_base||btrim(e)) FILTER (WHERE btrim(e) <> ''), ARRAY[]::text[]))
               FROM unnest(string_to_array(COALESCE(r.raw_data->>'AllImageList',''), ',')) e);
    v_videos:=CASE WHEN NULLIF(trim(r.raw_data->>'VideoLink'),'') IS NOT NULL THEN jsonb_build_array(trim(r.raw_data->>'VideoLink')) END;
  ELSIF r.supplier_id=v_XBZ THEN
    v_apiid:=r.raw_data->>'CorWebPrincipalId'; v_cname:=r.raw_data->>'CorWebPrincipal';
    v_supplier_sku:=r.raw_data->>'CodigoComposto'; v_stock:=public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel');
    v_cost:=public.fn_safe_num(r.raw_data->>'PrecoVenda');   -- PrecoVenda do XBZ = CUSTO (silver_08e)
    v_sku:='XBZ-'||r.supplier_reference;
  ELSIF r.supplier_id=v_ASIA THEN
    v_cname:=r.raw_data->>'var_cor_nome'; v_chex:=r.raw_data->>'var_cor_hex';
    v_supplier_sku:=COALESCE(r.raw_data->>'var_referencia', r.supplier_reference);
    v_stock:=public.fn_safe_int(r.raw_data->>'var_estoque');
    v_cost:=public.fn_safe_num(r.raw_data->>'preco');        -- preco da Asia = CUSTO (silver_08e)
    v_sku:='ASIA-'||r.supplier_reference;
  ELSIF r.supplier_id=v_SM THEN
    -- Só Marcas: sem campo de cor. Extrai do título; hex da rede de produtos_similares.
    v_cname:=public.fn_extract_color_from_title(r.raw_data->>'titulo');
    v_chex := (SELECT split_part(item,'|',2)
               FROM unnest(string_to_array(r.raw_data->>'produtos_similares', ';')) item
               WHERE split_part(item,'|',1)=r.supplier_reference
                 AND split_part(item,'|',2) ~* '^#[0-9a-f]{6}$' LIMIT 1);
    v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque');
    v_cost:=public.fn_safe_num(r.raw_data->>'preco_sem_gravacao_sem_impostos');
    v_sku:=r.supplier_reference;
  ELSE
    v_cname:=r.raw_data->>'cor'; v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque'); v_cost:=public.fn_safe_num(r.raw_data->>'preco_base');
    v_sku:=r.supplier_reference;
  END IF;

  -- resolução do fornecedor (descritivos). Para SM não há catálogo, usa o extraído.
  SELECT * INTO v_col FROM public.fn_match_supplier_color(r.supplier_id, v_code, v_apiid, v_cname, v_chex);
  v_fname := COALESCE(v_col.color_name, v_cname);
  v_fcode := COALESCE(v_col.color_code, v_code);
  v_fhex  := COALESCE(v_col.color_hex,  v_chex);
  v_canonical_id := public.fn_match_canonical_color(v_fname, v_fhex);

  INSERT INTO public.produtos_padronizacao_variantes AS pv (
    raw_id, supplier_id, parent_reference, variant_reference,
    sku, supplier_sku, color_name, color_code, color_hex, color_id,
    stock_quantity, cost_price, is_active, status,
    cost_price_1, cost_price_2, cost_price_3, cost_price_4, cost_price_5,
    min_qty_1, min_qty_2, min_qty_3, min_qty_4, min_qty_5,
    next_quantity_1, next_quantity_2, next_quantity_3, next_date_1, next_date_2, next_date_3,
    sale_multiplier, supplier_thumbnail, supplier_images, supplier_videos
  ) VALUES (
    r.id, r.supplier_id, v_parent, r.supplier_reference, v_sku, v_supplier_sku,
    v_fname, v_fcode, v_fhex, v_canonical_id,
    v_stock, v_cost, true, 'standardized'::public.produtos_padronizacao_status,
    v_cp1, v_cp2, v_cp3, v_cp4, v_cp5,
    v_mq1, v_mq2, v_mq3, v_mq4, v_mq5,
    v_nq1, v_nq2, v_nq3, v_nd1, v_nd2, v_nd3,
    v_mult, v_thumb, v_images, v_videos
  )
  ON CONFLICT (supplier_id, variant_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, parent_reference=EXCLUDED.parent_reference, sku=EXCLUDED.sku, supplier_sku=EXCLUDED.supplier_sku,
    color_name=EXCLUDED.color_name, color_code=EXCLUDED.color_code, color_hex=EXCLUDED.color_hex, color_id=EXCLUDED.color_id,
    stock_quantity=EXCLUDED.stock_quantity, cost_price=EXCLUDED.cost_price, is_active=EXCLUDED.is_active,
    status=EXCLUDED.status,
    cost_price_1=EXCLUDED.cost_price_1, cost_price_2=EXCLUDED.cost_price_2, cost_price_3=EXCLUDED.cost_price_3,
    cost_price_4=EXCLUDED.cost_price_4, cost_price_5=EXCLUDED.cost_price_5,
    min_qty_1=EXCLUDED.min_qty_1, min_qty_2=EXCLUDED.min_qty_2, min_qty_3=EXCLUDED.min_qty_3,
    min_qty_4=EXCLUDED.min_qty_4, min_qty_5=EXCLUDED.min_qty_5,
    next_quantity_1=EXCLUDED.next_quantity_1, next_quantity_2=EXCLUDED.next_quantity_2, next_quantity_3=EXCLUDED.next_quantity_3,
    next_date_1=EXCLUDED.next_date_1, next_date_2=EXCLUDED.next_date_2, next_date_3=EXCLUDED.next_date_3,
    sale_multiplier=EXCLUDED.sale_multiplier, supplier_thumbnail=EXCLUDED.supplier_thumbnail,
    supplier_images=EXCLUDED.supplier_images, supplier_videos=EXCLUDED.supplier_videos,
    updated_at=now()
  RETURNING pv.id INTO v_var_id;

  RETURN jsonb_build_object('success',true,'variante_id',v_var_id,'parent',v_parent,
                            'cor',v_fname,'hex',v_fhex,'color_id_canonico',v_canonical_id);
END;
$function$;;

-- <<< END 20260605223503_standardize_variant_optionb_tiers_stock_images.sql <<<

-- >>> BEGIN 20260605223615_promote_padronizacao_optionb_rich_fields.sql >>>
CREATE OR REPLACE FUNCTION public.fn_promote_padronizacao(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  s         public.produtos_padronizacao%ROWTYPE;
  v_pid     uuid;
  v_org     uuid;
  v_locked  text[];
  v_is_new  boolean := false;
BEGIN
  SELECT * INTO s FROM public.produtos_padronizacao WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'padronizacao_nao_encontrada', 'id', p_id);
  END IF;
  IF s.status <> 'standardized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'status_invalido', 'status', s.status);
  END IF;

  PERFORM set_config('app.write_source', 'pipeline', true);

  SELECT id, locked_fields INTO v_pid, v_locked
  FROM public.products
  WHERE supplier_id = s.supplier_id AND supplier_reference = s.supplier_reference;

  IF v_pid IS NULL THEN
    v_is_new := true;
    SELECT organization_id INTO v_org FROM public.suppliers WHERE id = s.supplier_id;
    INSERT INTO public.products (organization_id, supplier_id, supplier_reference, sku, name, active, is_active, product_type)
    VALUES (v_org, s.supplier_id, s.supplier_reference,
            COALESCE(s.supplier_reference, s.name), COALESCE(s.name,'Produto '||s.supplier_reference),
            COALESCE(s.is_active, true), COALESCE(s.is_active, true), 'product')
    RETURNING id, locked_fields INTO v_pid, v_locked;
  END IF;

  v_locked := COALESCE(v_locked, '{}');

  UPDATE public.products p SET
    name               = CASE WHEN 'name'               = ANY(v_locked) THEN p.name               ELSE COALESCE(s.name, p.name) END,
    description        = CASE WHEN 'description'        = ANY(v_locked) THEN p.description        ELSE COALESCE(s.description, p.description) END,
    short_description  = CASE WHEN 'short_description'  = ANY(v_locked) THEN p.short_description  ELSE COALESCE(s.short_description, p.short_description) END,
    cost_price         = CASE WHEN 'cost_price'         = ANY(v_locked) THEN p.cost_price         ELSE COALESCE(s.cost_price, p.cost_price) END,
    suggested_price    = CASE WHEN 'suggested_price'    = ANY(v_locked) THEN p.suggested_price    ELSE COALESCE(s.suggested_price, p.suggested_price) END,
    stock_quantity     = CASE WHEN 'stock_quantity'     = ANY(v_locked) THEN p.stock_quantity     ELSE COALESCE(s.stock_quantity, p.stock_quantity) END,
    primary_image_url  = CASE WHEN 'primary_image_url'  = ANY(v_locked) THEN p.primary_image_url  ELSE COALESCE(s.primary_image_url, p.primary_image_url) END,
    images             = CASE WHEN 'images'             = ANY(v_locked) THEN p.images             ELSE COALESCE(s.images, p.images) END,
    ncm_code           = CASE WHEN 'ncm_code'           = ANY(v_locked) THEN p.ncm_code           ELSE COALESCE(s.ncm_code, p.ncm_code) END,
    weight_g           = CASE WHEN 'weight_g'           = ANY(v_locked) THEN p.weight_g           ELSE COALESCE(s.weight_g, p.weight_g) END,
    height_cm          = CASE WHEN 'height_cm'          = ANY(v_locked) THEN p.height_cm          ELSE COALESCE(s.height_cm, p.height_cm) END,
    width_cm           = CASE WHEN 'width_cm'           = ANY(v_locked) THEN p.width_cm           ELSE COALESCE(s.width_cm, p.width_cm) END,
    length_cm          = CASE WHEN 'length_cm'          = ANY(v_locked) THEN p.length_cm          ELSE COALESCE(s.length_cm, p.length_cm) END,
    dimensions_display = CASE WHEN 'dimensions_display' = ANY(v_locked) THEN p.dimensions_display ELSE COALESCE(s.dimensions_display, p.dimensions_display) END,
    box_length_cm      = CASE WHEN 'box_length_cm'      = ANY(v_locked) THEN p.box_length_cm      ELSE COALESCE(s.box_length_cm, p.box_length_cm) END,
    box_width_cm       = CASE WHEN 'box_width_cm'       = ANY(v_locked) THEN p.box_width_cm       ELSE COALESCE(s.box_width_cm, p.box_width_cm) END,
    box_height_cm      = CASE WHEN 'box_height_cm'      = ANY(v_locked) THEN p.box_height_cm      ELSE COALESCE(s.box_height_cm, p.box_height_cm) END,
    box_weight_kg      = CASE WHEN 'box_weight_kg'      = ANY(v_locked) THEN p.box_weight_kg      ELSE COALESCE(s.box_weight_kg, p.box_weight_kg) END,
    box_volume_cm3     = CASE WHEN 'box_volume_cm3'     = ANY(v_locked) THEN p.box_volume_cm3     ELSE COALESCE(s.box_volume_cm3, p.box_volume_cm3) END,
    box_quantity       = CASE WHEN 'box_quantity'       = ANY(v_locked) THEN p.box_quantity       ELSE COALESCE(s.box_quantity, p.box_quantity) END,
    box_inner_quantity = CASE WHEN 'box_inner_quantity' = ANY(v_locked) THEN p.box_inner_quantity ELSE COALESCE(s.box_inner_quantity, p.box_inner_quantity) END,
    brand              = CASE WHEN 'brand'              = ANY(v_locked) THEN p.brand              ELSE COALESCE(s.brand, p.brand) END,
    packing_type       = CASE WHEN 'packing_type'       = ANY(v_locked) THEN p.packing_type       ELSE COALESCE(s.packing_type, p.packing_type) END,
    repacking_type     = CASE WHEN 'repacking_type'     = ANY(v_locked) THEN p.repacking_type     ELSE COALESCE(s.repacking_type, p.repacking_type) END,
    capacities         = CASE WHEN 'capacities'         = ANY(v_locked) THEN p.capacities         ELSE COALESCE(s.capacities, p.capacities) END,
    capacity_ml        = CASE WHEN 'capacity_ml'        = ANY(v_locked) THEN p.capacity_ml        ELSE COALESCE(s.capacity_ml, p.capacity_ml) END,
    min_quantity       = CASE WHEN 'min_quantity'       = ANY(v_locked) THEN p.min_quantity       ELSE COALESCE(s.min_quantity, p.min_quantity) END,
    warranty_months    = CASE WHEN 'warranty_months'    = ANY(v_locked) THEN p.warranty_months    ELSE COALESCE(s.warranty_months, p.warranty_months) END,
    ipi_rate           = CASE WHEN 'ipi_rate'           = ANY(v_locked) THEN p.ipi_rate           ELSE COALESCE(s.ipi_rate, p.ipi_rate) END,
    engraving_type     = CASE WHEN 'engraving_type'     = ANY(v_locked) THEN p.engraving_type     ELSE COALESCE(s.engraving_type, p.engraving_type) END,
    colors             = CASE WHEN 'colors'             = ANY(v_locked) THEN p.colors             ELSE COALESCE(s.colors, p.colors) END,
    -- Opção B: campos ricos
    origin_country         = CASE WHEN 'origin_country'         = ANY(v_locked) THEN p.origin_country         ELSE COALESCE(s.origin_country, p.origin_country) END,
    combined_sizes         = CASE WHEN 'combined_sizes'         = ANY(v_locked) THEN p.combined_sizes         ELSE COALESCE(s.combined_sizes, p.combined_sizes) END,
    box_image              = CASE WHEN 'box_image'              = ANY(v_locked) THEN p.box_image              ELSE COALESCE(s.box_image, p.box_image) END,
    is_textil              = CASE WHEN 'is_textil'              = ANY(v_locked) THEN p.is_textil              ELSE COALESCE(s.is_textil, p.is_textil) END,
    is_stockout            = CASE WHEN 'is_stockout'            = ANY(v_locked) THEN p.is_stockout            ELSE COALESCE(s.is_stockout, p.is_stockout) END,
    is_online_exclusive    = CASE WHEN 'is_online_exclusive'    = ANY(v_locked) THEN p.is_online_exclusive    ELSE COALESCE(s.is_online_exclusive, p.is_online_exclusive) END,
    is_new                 = CASE WHEN 'is_new'                 = ANY(v_locked) THEN p.is_new                 ELSE COALESCE(s.is_new, p.is_new) END,
    has_colors             = CASE WHEN 'has_colors'             = ANY(v_locked) THEN p.has_colors             ELSE COALESCE(s.has_colors, p.has_colors) END,
    has_sizes              = CASE WHEN 'has_sizes'              = ANY(v_locked) THEN p.has_sizes              ELSE COALESCE(s.has_sizes, p.has_sizes) END,
    allows_personalization = CASE WHEN 'allows_personalization' = ANY(v_locked) THEN p.allows_personalization ELSE COALESCE(s.allows_personalization, p.allows_personalization) END,
    tags                   = CASE WHEN 'tags'                   = ANY(v_locked) THEN p.tags                   ELSE COALESCE(s.tags, p.tags) END,
    materials              = CASE WHEN 'materials'              = ANY(v_locked) THEN p.materials              ELSE COALESCE(s.materials, p.materials) END,
    meta_keywords          = CASE WHEN 'meta_keywords'          = ANY(v_locked) THEN p.meta_keywords          ELSE COALESCE(s.meta_keywords, p.meta_keywords) END,
    last_sync_at          = now(),
    last_sync_supplier_id = s.supplier_id,
    supplier_updated_at   = now()
  WHERE p.id = v_pid;

  UPDATE public.produtos_padronizacao
     SET status='promoted', promoted_at=now(), product_id=v_pid
   WHERE id = p_id;

  IF s.raw_id IS NOT NULL THEN
    UPDATE public.supplier_products_raw
       SET status='processed', processed_at=now(), product_id=v_pid, process_errors=NULL
     WHERE id = s.raw_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'product_id', v_pid, 'created', v_is_new,
                            'locked_preserved', v_locked);
END;
$function$;;

