-- >>> BEGIN 20260606111639_spot_item2_print_positions_schema.sql >>>
-- Helper: repara dupla-codificação UTF-8 lido como CP1252 (ex.: 'Ã˜'->'Ø', 'Ã—'->'×').
-- Conservador: só atua se houver marcador de mojibake ('Ã'/'Â'); em erro, devolve original.
CREATE OR REPLACE FUNCTION public.fn_fix_mojibake(p text)
RETURNS text LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE v text;
BEGIN
  IF p IS NULL THEN RETURN NULL; END IF;
  IF p !~ '[ÃÂ]' THEN RETURN p; END IF;
  BEGIN
    v := convert_from(convert_to(p,'WIN1252'),'UTF8');
    RETURN v;
  EXCEPTION WHEN OTHERS THEN
    RETURN p;
  END;
END $$;

-- Posições de gravação por produto (até 8), extraídas do OptionalsComplete
CREATE TABLE IF NOT EXISTS public.product_print_positions (
  id                  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id          uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  position_index      smallint NOT NULL,
  component           text,
  location            text,
  composed_location   text,
  area_label          text,          -- tamanho da gravação (ex.: Ø70)
  technique_list      jsonb,         -- técnicas disponíveis nessa posição
  table_full_code     text,
  table_codes         text,
  table_codes_options jsonb,
  max_colors          jsonb,         -- máx. de cores por técnica
  handling_costs      jsonb,
  area_image          text,
  component_image     text,
  location_image      text,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  UNIQUE (product_id, position_index)
);
CREATE INDEX IF NOT EXISTS idx_ppp_product ON public.product_print_positions(product_id);;

-- <<< END 20260606111639_spot_item2_print_positions_schema.sql <<<

-- >>> BEGIN 20260606111735_spot_item2_print_positions_parser.sql >>>
CREATE OR REPLACE FUNCTION public.fn_spot_print_positions(p_supplier_id uuid, p_parent_ref text DEFAULT NULL)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','extensions' AS $$
DECLARE v_n integer;
BEGIN
  -- idempotente: limpa posições dos produtos-alvo e recria
  DELETE FROM public.product_print_positions ppp
   USING public.produtos_padronizacao pp
   WHERE ppp.product_id = pp.product_id AND pp.supplier_id = p_supplier_id
     AND (p_parent_ref IS NULL OR pp.supplier_reference = p_parent_ref);

  INSERT INTO public.product_print_positions
    (product_id, position_index, component, location, composed_location, area_label,
     technique_list, table_full_code, table_codes, table_codes_options, max_colors, handling_costs,
     area_image, component_image, location_image)
  SELECT p.id, g.n,
    public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>('Component'||g.n)),'')),
    public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>('Location'||g.n)),'')),
    public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>('ComposedLocation'||g.n)),'')),
    public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>('Area'||g.n)),'')),
    CASE WHEN nullif(btrim(spr.raw_data->>('CustomizationTypes'||g.n)),'') IS NOT NULL
         THEN to_jsonb(string_to_array(btrim(spr.raw_data->>('CustomizationTypes'||g.n)), ', ')) END,
    nullif(btrim(spr.raw_data->>('TableFullCode'||g.n)),''),
    nullif(btrim(spr.raw_data->>('TableCodes'||g.n)),''),
    CASE WHEN nullif(btrim(spr.raw_data->>('TableCodesOptions'||g.n)),'') IS NOT NULL
         THEN to_jsonb(string_to_array(btrim(spr.raw_data->>('TableCodesOptions'||g.n)), ', ')) END,
    CASE WHEN nullif(btrim(spr.raw_data->>('MaxColors'||g.n)),'') IS NOT NULL
         THEN to_jsonb(string_to_array(btrim(spr.raw_data->>('MaxColors'||g.n)), ', ')) END,
    CASE WHEN nullif(btrim(spr.raw_data->>('HandlingCosts'||g.n)),'') IS NOT NULL
         THEN to_jsonb(string_to_array(btrim(spr.raw_data->>('HandlingCosts'||g.n)), ', ')) END,
    nullif(btrim(spr.raw_data->>('Area'||g.n||'Image')),''),
    nullif(btrim(spr.raw_data->>('Component'||g.n||'Image')),''),
    nullif(btrim(spr.raw_data->>('Location'||g.n||'Image')),'')
  FROM public.products p
  JOIN public.produtos_padronizacao pp ON pp.product_id=p.id AND pp.supplier_id=p_supplier_id
  JOIN public.supplier_products_raw spr ON spr.id=pp.raw_id
  CROSS JOIN generate_series(1,8) g(n)
  WHERE (p_parent_ref IS NULL OR pp.supplier_reference=p_parent_ref)
    AND coalesce(nullif(btrim(spr.raw_data->>('Component'||g.n)),''),
                 nullif(btrim(spr.raw_data->>('Area'||g.n)),''),
                 nullif(btrim(spr.raw_data->>('Location'||g.n)),'')) IS NOT NULL;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;;

-- <<< END 20260606111735_spot_item2_print_positions_parser.sql <<<

-- >>> BEGIN 20260606112005_asia_standardize_variant_stockdata_first.sql >>>
CREATE OR REPLACE FUNCTION public.fn_standardize_variant(p_raw_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r public.supplier_products_raw%ROWTYPE;
  v_parent text; v_code text; v_apiid text; v_cname text; v_chex text;
  v_col RECORD; v_sku text; v_supplier_sku text; v_stock integer; v_cost numeric; v_var_id uuid;
  v_fname text; v_fcode text; v_fhex text; v_canonical_id uuid;
  v_cp1 numeric; v_cp2 numeric; v_cp3 numeric; v_cp4 numeric; v_cp5 numeric;
  v_mq1 int; v_mq2 int; v_mq3 int; v_mq4 int; v_mq5 int;
  v_nq1 int; v_nq2 int; v_nq3 int; v_nd1 date; v_nd2 date; v_nd3 date;
  v_mult int; v_thumb text; v_images jsonb; v_videos jsonb;
  v_base text := 'https://www.spotgifts.com.br/fotos/produtos/';
  v_SPOT uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_XBZ  uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
  v_ASIA uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_SM   uuid := '841cd690-210a-422a-908c-7676828db272';
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id=p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','raw_nao_encontrado'); END IF;
  v_parent := public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data);

  IF r.supplier_id=v_SPOT THEN
    v_code  := r.raw_data->>'ColorCode';
    v_cname := COALESCE(NULLIF(TRIM(r.raw_data->>'ColorName'),''), r.raw_data->>'ColorDesc1');
    v_chex  := COALESCE(NULLIF(TRIM(r.raw_data->>'ColorHex'),''),  r.raw_data->>'ColorHex1');
    v_supplier_sku := r.raw_data->>'Sku';
    v_stock := public.fn_safe_int(COALESCE(r.stock_data->>'Quantity', r.raw_data->>'StockQuantity'));
    v_cost  := public.fn_safe_num(r.raw_data->>'Price1');
    v_sku   := r.supplier_reference;
    v_cp1:=public.fn_safe_num(r.raw_data->>'Price1'); v_cp2:=public.fn_safe_num(r.raw_data->>'Price2');
    v_cp3:=public.fn_safe_num(r.raw_data->>'Price3'); v_cp4:=public.fn_safe_num(r.raw_data->>'Price4');
    v_cp5:=public.fn_safe_num(r.raw_data->>'Price5');
    v_mq1:=public.fn_safe_int(r.raw_data->>'MinQt1'); v_mq2:=public.fn_safe_int(r.raw_data->>'MinQt2');
    v_mq3:=public.fn_safe_int(r.raw_data->>'MinQt3'); v_mq4:=public.fn_safe_int(r.raw_data->>'MinQt4');
    v_mq5:=public.fn_safe_int(r.raw_data->>'MinQt5');
    v_nq1:=public.fn_safe_int(r.stock_data->>'NextQuantity1'); v_nq2:=public.fn_safe_int(r.stock_data->>'NextQuantity2'); v_nq3:=public.fn_safe_int(r.stock_data->>'NextQuantity3');
    v_nd1:=CASE WHEN r.stock_data->>'NextDate1' ~ '^\d{4}-\d{2}-\d{2}' THEN left(r.stock_data->>'NextDate1',10)::date END;
    v_nd2:=CASE WHEN r.stock_data->>'NextDate2' ~ '^\d{4}-\d{2}-\d{2}' THEN left(r.stock_data->>'NextDate2',10)::date END;
    v_nd3:=CASE WHEN r.stock_data->>'NextDate3' ~ '^\d{4}-\d{2}-\d{2}' THEN left(r.stock_data->>'NextDate3',10)::date END;
    v_mult:=public.fn_safe_int(r.raw_data->>'Multiplier');
    v_thumb:=CASE WHEN NULLIF(trim(r.raw_data->>'MainImage'),'') IS NOT NULL THEN v_base||trim(r.raw_data->>'MainImage') END;
    v_images:=(SELECT to_jsonb(COALESCE(array_agg(v_base||btrim(e)) FILTER (WHERE btrim(e) <> ''), ARRAY[]::text[]))
               FROM unnest(string_to_array(COALESCE(r.raw_data->>'AllImageList',''), ',')) e);
    v_videos:=CASE WHEN NULLIF(trim(r.raw_data->>'VideoLink'),'') IS NOT NULL THEN jsonb_build_array(trim(r.raw_data->>'VideoLink')) END;
  ELSIF r.supplier_id=v_XBZ THEN
    v_apiid:=r.raw_data->>'CorWebPrincipalId'; v_cname:=r.raw_data->>'CorWebPrincipal';
    v_supplier_sku:=r.raw_data->>'CodigoComposto'; v_stock:=public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel');
    v_cost:=public.fn_safe_num(r.raw_data->>'PrecoVenda');
    v_sku:='XBZ-'||r.supplier_reference;
  ELSIF r.supplier_id=v_ASIA THEN
    v_cname:=r.raw_data->>'var_cor_nome'; v_chex:=r.raw_data->>'var_cor_hex';
    v_supplier_sku:=COALESCE(r.raw_data->>'var_referencia', r.supplier_reference);
    -- estoque: trilha stock_data tem prioridade; fallback raw_data (linhas legadas)
    v_stock:=public.fn_safe_int(COALESCE(r.stock_data->>'qtd_estoque', r.raw_data->>'var_estoque'));
    v_cost:=public.fn_safe_num(r.raw_data->>'preco');
    v_sku:='ASIA-'||r.supplier_reference;
    -- reposicao (previsao_entrega): stock_data prioridade; fallback raw_data
    v_nd1 := CASE
      WHEN COALESCE(r.stock_data->'previsao_entrega'->0->>'data', r.raw_data->'previsao_entrega'->0->>'data') ~ '^\d{4}-\d{2}-\d{2}'
      THEN left(COALESCE(r.stock_data->'previsao_entrega'->0->>'data', r.raw_data->'previsao_entrega'->0->>'data'),10)::date END;
    v_nq1 := public.fn_safe_int(COALESCE(r.stock_data->'previsao_entrega'->0->>'quantidade', r.raw_data->'previsao_entrega'->0->>'quantidade'));
  ELSIF r.supplier_id=v_SM THEN
    v_cname:=public.fn_extract_color_from_title(r.raw_data->>'titulo');
    v_chex := (SELECT split_part(item,'|',2)
               FROM unnest(string_to_array(r.raw_data->>'produtos_similares', ';')) item
               WHERE split_part(item,'|',1)=r.supplier_reference
                 AND split_part(item,'|',2) ~* '^#[0-9a-f]{6}$' LIMIT 1);
    v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque');
    v_cost:=public.fn_safe_num(r.raw_data->>'preco_sem_gravacao_sem_impostos');
    v_sku:=r.supplier_reference;
  ELSE
    v_cname:=r.raw_data->>'cor'; v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque'); v_cost:=public.fn_safe_num(r.raw_data->>'preco_base');
    v_sku:=r.supplier_reference;
  END IF;

  SELECT * INTO v_col FROM public.fn_match_supplier_color(r.supplier_id, v_code, v_apiid, v_cname, v_chex);
  v_fname := COALESCE(v_col.color_name, v_cname);
  v_fcode := COALESCE(v_col.color_code, v_code);
  v_fhex  := COALESCE(v_col.color_hex,  v_chex);
  v_canonical_id := public.fn_match_canonical_color(v_fname, v_fhex);

  INSERT INTO public.produtos_padronizacao_variantes AS pv (
    raw_id, supplier_id, parent_reference, variant_reference,
    sku, supplier_sku, color_name, color_code, color_hex, color_id,
    stock_quantity, cost_price, is_active, status,
    cost_price_1, cost_price_2, cost_price_3, cost_price_4, cost_price_5,
    min_qty_1, min_qty_2, min_qty_3, min_qty_4, min_qty_5,
    next_quantity_1, next_quantity_2, next_quantity_3, next_date_1, next_date_2, next_date_3,
    sale_multiplier, supplier_thumbnail, supplier_images, supplier_videos
  ) VALUES (
    r.id, r.supplier_id, v_parent, r.supplier_reference, v_sku, v_supplier_sku,
    v_fname, v_fcode, v_fhex, v_canonical_id,
    v_stock, v_cost, true, 'standardized'::public.produtos_padronizacao_status,
    v_cp1, v_cp2, v_cp3, v_cp4, v_cp5,
    v_mq1, v_mq2, v_mq3, v_mq4, v_mq5,
    v_nq1, v_nq2, v_nq3, v_nd1, v_nd2, v_nd3,
    v_mult, v_thumb, v_images, v_videos
  )
  ON CONFLICT (supplier_id, variant_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, parent_reference=EXCLUDED.parent_reference, sku=EXCLUDED.sku, supplier_sku=EXCLUDED.supplier_sku,
    color_name=EXCLUDED.color_name, color_code=EXCLUDED.color_code, color_hex=EXCLUDED.color_hex, color_id=EXCLUDED.color_id,
    stock_quantity=EXCLUDED.stock_quantity, cost_price=EXCLUDED.cost_price, is_active=EXCLUDED.is_active,
    status=EXCLUDED.status,
    cost_price_1=EXCLUDED.cost_price_1, cost_price_2=EXCLUDED.cost_price_2, cost_price_3=EXCLUDED.cost_price_3,
    cost_price_4=EXCLUDED.cost_price_4, cost_price_5=EXCLUDED.cost_price_5,
    min_qty_1=EXCLUDED.min_qty_1, min_qty_2=EXCLUDED.min_qty_2, min_qty_3=EXCLUDED.min_qty_3,
    min_qty_4=EXCLUDED.min_qty_4, min_qty_5=EXCLUDED.min_qty_5,
    next_quantity_1=EXCLUDED.next_quantity_1, next_quantity_2=EXCLUDED.next_quantity_2, next_quantity_3=EXCLUDED.next_quantity_3,
    next_date_1=EXCLUDED.next_date_1, next_date_2=EXCLUDED.next_date_2, next_date_3=EXCLUDED.next_date_3,
    sale_multiplier=EXCLUDED.sale_multiplier, supplier_thumbnail=EXCLUDED.supplier_thumbnail,
    supplier_images=EXCLUDED.supplier_images, supplier_videos=EXCLUDED.supplier_videos,
    updated_at=now()
  RETURNING pv.id INTO v_var_id;

  RETURN jsonb_build_object('success',true,'variante_id',v_var_id,'parent',v_parent,
                            'cor',v_fname,'hex',v_fhex,'color_id_canonico',v_canonical_id);
END;
$function$;;

-- <<< END 20260606112005_asia_standardize_variant_stockdata_first.sql <<<

-- >>> BEGIN 20260606112521_spot_item2_customization_prices_schema.sql >>>
-- Bronze landing p/ o feed CustomizationOptions (preços por produto/posição/técnica)
CREATE TABLE IF NOT EXISTS public.supplier_customization_options_raw (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  supplier_id        uuid NOT NULL,
  product_reference  text NOT NULL,
  service_code       text,
  table_code         text,
  component          text,
  location           text,
  handling_cost      numeric,
  table_max_area_cm2 numeric,
  max_stitches       integer,
  hotspot            text,
  raw_data           jsonb NOT NULL,
  imported_at        timestamptz NOT NULL DEFAULT now(),
  UNIQUE (supplier_id, product_reference, service_code, table_code, component, location)
);
CREATE INDEX IF NOT EXISTS idx_scor_ref ON public.supplier_customization_options_raw(supplier_id, product_reference);

-- Gold: preços de personalização por produto (faixas 1..15 como arrays)
CREATE TABLE IF NOT EXISTS public.product_customization_prices (
  id                 uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id         uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  service_code       text,
  table_code         text,
  component          text,
  location           text,
  handling_cost      numeric,
  table_max_area_cm2 numeric,
  max_stitches       integer,
  hotspot            text,
  min_qty            integer[],
  price              numeric[],
  currency           text NOT NULL DEFAULT 'BRL',
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  UNIQUE (product_id, service_code, table_code, component, location)
);
CREATE INDEX IF NOT EXISTS idx_pcp_product ON public.product_customization_prices(product_id);

-- Transform landing -> Gold (idempotente). Pronto para quando o feed for ingerido.
CREATE OR REPLACE FUNCTION public.fn_spot_customization_prices_to_gold(p_supplier_id uuid, p_parent_ref text DEFAULT NULL)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','extensions' AS $$
DECLARE v_n integer;
BEGIN
  PERFORM set_config('app.bulk_import_mode','true', true);
  DELETE FROM public.product_customization_prices pcp
   USING public.produtos_padronizacao pp
   WHERE pcp.product_id = pp.product_id AND pp.supplier_id = p_supplier_id
     AND (p_parent_ref IS NULL OR pp.supplier_reference = p_parent_ref);

  INSERT INTO public.product_customization_prices
    (product_id, service_code, table_code, component, location, handling_cost, table_max_area_cm2, max_stitches, hotspot, min_qty, price)
  SELECT pp.product_id, r.service_code, r.table_code,
         public.fn_fix_mojibake(r.component), public.fn_fix_mojibake(r.location),
         r.handling_cost, r.table_max_area_cm2, r.max_stitches, r.hotspot,
         (SELECT array_agg((r.raw_data->>('MinQt'||i))::int ORDER BY i)
            FROM generate_series(1,15) i WHERE nullif(btrim(r.raw_data->>('MinQt'||i)),'') IS NOT NULL),
         (SELECT array_agg((r.raw_data->>('Price'||i))::numeric ORDER BY i)
            FROM generate_series(1,15) i WHERE nullif(btrim(r.raw_data->>('Price'||i)),'') IS NOT NULL)
  FROM public.supplier_customization_options_raw r
  JOIN public.produtos_padronizacao pp
    ON pp.supplier_id = r.supplier_id AND pp.supplier_reference = r.product_reference
  WHERE r.supplier_id = p_supplier_id AND pp.product_id IS NOT NULL
    AND (p_parent_ref IS NULL OR pp.supplier_reference = p_parent_ref);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;;

-- <<< END 20260606112521_spot_item2_customization_prices_schema.sql <<<

-- >>> BEGIN 20260606112800_asia_create_enrich_parent.sql >>>
CREATE OR REPLACE FUNCTION public.fn_asia_enrich_parent(p_supplier_id uuid, p_parent_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_raw jsonb; v_asia jsonb; v_n int;
BEGIN
  -- representante: a raw com maior payload do grupo (mesmo critério do fn_standardize_parent)
  SELECT (SELECT raw_data FROM public.supplier_products_raw WHERE id = pv.raw_id)
    INTO v_raw
  FROM public.produtos_padronizacao_variantes pv
  WHERE pv.supplier_id = p_supplier_id
    AND pv.parent_reference = p_parent_reference
    AND pv.raw_id IS NOT NULL
  ORDER BY length((SELECT raw_data::text FROM public.supplier_products_raw WHERE id = pv.raw_id)) DESC NULLS LAST, pv.raw_id
  LIMIT 1;

  IF v_raw IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'sem_representante', 'parent', p_parent_reference);
  END IF;

  v_asia := public.fn_parse_asia_properties(
    COALESCE(v_raw->'propriedades', '{}'::jsonb),
    COALESCE(public.fn_safe_num(v_raw->>'altura'), 0),
    COALESCE(public.fn_safe_num(v_raw->>'largura'), 0),
    COALESCE(public.fn_safe_num(v_raw->>'comprimento'), 0),
    COALESCE(public.fn_safe_num(v_raw->>'peso'), 0),
    v_raw->>'origem_faturamento');

  UPDATE public.produtos_padronizacao SET
    description        = COALESCE(NULLIF(v_raw->>'descricao', ''), description),
    images             = CASE WHEN jsonb_typeof(v_raw->'galeria') = 'array' AND jsonb_array_length(v_raw->'galeria') > 0
                              THEN v_raw->'galeria' ELSE images END,
    height_cm          = COALESCE((v_asia->>'height_cm')::numeric, height_cm),
    width_cm           = COALESCE((v_asia->>'width_cm')::numeric, width_cm),
    length_cm          = COALESCE((v_asia->>'length_cm')::numeric, length_cm),
    weight_g           = COALESCE((v_asia->>'weight_g')::int, weight_g),
    box_length_cm      = COALESCE((v_asia->>'box_length_cm')::numeric, box_length_cm),
    box_width_cm       = COALESCE((v_asia->>'box_width_cm')::numeric, box_width_cm),
    box_height_cm      = COALESCE((v_asia->>'box_height_cm')::numeric, box_height_cm),
    box_weight_kg      = COALESCE((v_asia->>'box_weight_kg')::numeric, box_weight_kg),
    box_quantity       = COALESCE((v_asia->>'box_quantity')::int, box_quantity),
    packing_type       = COALESCE(v_asia->>'packing_type', packing_type),
    capacity_ml        = COALESCE((v_asia->>'capacity_ml')::int, capacity_ml),
    dimensions_display = COALESCE(NULLIF(v_raw->'propriedades'->>'dimensao-do-produto', ''),
                                  NULLIF(v_raw->'propriedades'->>'dimensao-produto', ''), dimensions_display),
    updated_at = now()
  WHERE supplier_id = p_supplier_id AND supplier_reference = p_parent_reference;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('success', v_n > 0, 'parent', p_parent_reference, 'rows', v_n, 'parsed', v_asia);
END;
$function$;;

-- <<< END 20260606112800_asia_create_enrich_parent.sql <<<

