    );

    v_chash := encode(digest(v_content::text, 'sha256'), 'hex');
    v_shash := encode(digest(v_stock::text,   'sha256'), 'hex');

    INSERT INTO public.supplier_products_raw AS spr (
      supplier_id, supplier_reference, supplier_sku, raw_data,
      stock_data, stock_hash, stock_status, stock_synced_at,
      source_channel, source_endpoint, status, images_status
    ) VALUES (
      v_ASIA, v_var_ref, v_var_ref, v_content,
      v_stock, v_shash, 'pending'::supplier_raw_status, now(),
      'n8n', 'listarProdutos2', 'pending'::supplier_raw_status, 'pending'::supplier_raw_status
    )
    ON CONFLICT (supplier_id, supplier_sku) DO UPDATE SET
      raw_data           = EXCLUDED.raw_data,
      supplier_reference = EXCLUDED.supplier_reference,
      status             = CASE WHEN spr.content_hash IS DISTINCT FROM v_chash
                                THEN 'pending'::supplier_raw_status ELSE spr.status END,
      stock_data         = EXCLUDED.stock_data,
      stock_hash         = EXCLUDED.stock_hash,
      stock_status       = CASE WHEN spr.stock_hash IS DISTINCT FROM EXCLUDED.stock_hash
                                THEN 'pending'::supplier_raw_status ELSE spr.stock_status END,
      stock_synced_at    = now(),
      source_channel     = EXCLUDED.source_channel,
      source_endpoint    = EXCLUDED.source_endpoint;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'parent', v_parent, 'variacoes', v_vars);
END;
$function$;;

-- <<< END 20260606113554_asia_ingest_fix_source_channel.sql <<<

-- >>> BEGIN 20260606113906_spot_item6_silver_text_repair.sql >>>
CREATE OR REPLACE FUNCTION public.fn_spot_silver_enrich(p_supplier_id uuid, p_parent_ref text DEFAULT NULL)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','extensions' AS $$
DECLARE v_n integer;
BEGIN
  UPDATE public.produtos_padronizacao pp
  SET supplier_type        = nullif(btrim(spr.raw_data->>'Type'),''),
      supplier_type_code    = nullif(btrim(spr.raw_data->>'TypeCode'),''),
      supplier_subtype      = nullif(btrim(spr.raw_data->>'SubType'),''),
      supplier_subtype_code = nullif(btrim(spr.raw_data->>'SubTypeCode'),''),
      supplier_seo_name              = public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>'SEOName'),'')),
      supplier_seo_short_description = public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>'SEOShortDescription'),'')),
      certificates       = (SELECT to_jsonb(array_agg(btrim(e))) FROM unnest(string_to_array(spr.raw_data->>'Certificates', ',')) e WHERE btrim(e) <> ''),
      certificate_files  = (SELECT to_jsonb(array_agg(btrim(e))) FROM unnest(string_to_array(spr.raw_data->>'CertificateFiles', ',')) e WHERE btrim(e) <> ''),
      related_references = (SELECT to_jsonb(array_agg(btrim(e))) FROM unnest(string_to_array(spr.raw_data->>'RelatedReferences', ',')) e WHERE btrim(e) <> ''),
      weight_gr          = public.fn_fix_mojibake(nullif(btrim(spr.raw_data->>'WeightGr'),'')),
      is_seasonal        = public.fn_safe_bool(spr.raw_data->>'IsSeasonal'),
      pvc_free           = public.fn_safe_bool(spr.raw_data->>'PvcFree'),
      -- Item 6: reparo de encoding (Ø/×/acentos) nos textos já populados pelo standardize
      name               = public.fn_fix_mojibake(pp.name),
      short_description  = public.fn_fix_mojibake(pp.short_description),
      description        = public.fn_fix_mojibake(pp.description),
      combined_sizes     = public.fn_fix_mojibake(pp.combined_sizes),
      dimensions_display = public.fn_fix_mojibake(pp.dimensions_display),
      updated_at = now()
  FROM public.supplier_products_raw spr
  WHERE pp.raw_id = spr.id
    AND pp.supplier_id = p_supplier_id
    AND (p_parent_ref IS NULL OR pp.supplier_reference = p_parent_ref);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;;

-- <<< END 20260606113906_spot_item6_silver_text_repair.sql <<<

-- >>> BEGIN 20260606114108_fn_refresh_supplier_sync_telemetry_v1.sql >>>
create or replace function public.fn_refresh_supplier_sync_telemetry(p_supplier_id uuid default null)
returns table(supplier_code text, linhas bigint, novo_status text, novo_last_sync timestamptz)
language plpgsql
as $$
begin
  return query
  with agg as (
    select r.supplier_id,
           count(*)::bigint                                   as n,
           max(r.imported_at)                                  as max_imported,
           count(*) filter (where r.status = 'failed')         as n_failed
    from public.supplier_products_raw r
    where p_supplier_id is null or r.supplier_id = p_supplier_id
    group by r.supplier_id
  ),
  upd as (
    update public.suppliers s
       set last_full_sync_at = a.max_imported,
           last_sync_status  = case when a.n_failed > 0 then 'failed' else 'completed' end,
           last_sync_error   = case when a.n_failed > 0 then s.last_sync_error else null end,
           updated_at        = now()
      from agg a
     where s.id = a.supplier_id
    returning s.code, a.n, s.last_sync_status, s.last_full_sync_at
  )
  select u.code::text, u.n::bigint, u.last_sync_status::text, u.last_full_sync_at
  from upd u;
end;
$$;

comment on function public.fn_refresh_supplier_sync_telemetry(uuid)
  is 'Recalcula last_full_sync_at/last_sync_status de suppliers a partir do estado real de supplier_products_raw. Idempotente. Chamar ao fim de cada sync (n8n) ou com NULL para todos.';;

-- <<< END 20260606114108_fn_refresh_supplier_sync_telemetry_v1.sql <<<

-- >>> BEGIN 20260606114827_spr_normalize_keys_guard_v1.sql >>>
-- 1) Normalizador na entrada (preserva raw_data intacto; apara apenas as chaves)
create or replace function public.fn_spr_normalize_keys()
returns trigger
language plpgsql
as $$
begin
  if new.supplier_reference is not null then
    new.supplier_reference := btrim(new.supplier_reference);
  end if;
  if new.supplier_sku is not null then
    new.supplier_sku := btrim(new.supplier_sku);
  end if;
  return new;
end;
$$;

comment on function public.fn_spr_normalize_keys()
  is 'BEFORE INSERT/UPDATE em supplier_products_raw: apara espacos de supplier_reference/supplier_sku para evitar duplicatas por whitespace. Nao altera raw_data (payload fiel).';

drop trigger if exists trg_spr_normalize_keys on public.supplier_products_raw;
create trigger trg_spr_normalize_keys
  before insert or update on public.supplier_products_raw
  for each row
  execute function public.fn_spr_normalize_keys();

-- 2) Rede de seguranca: invariante garantida no schema (NOT VALID + VALIDATE = menos lock)
alter table public.supplier_products_raw
  add constraint chk_spr_reference_trimmed
  check (supplier_reference = btrim(supplier_reference)) not valid;
alter table public.supplier_products_raw
  validate constraint chk_spr_reference_trimmed;

alter table public.supplier_products_raw
  add constraint chk_spr_sku_trimmed
  check (supplier_sku is null or supplier_sku = btrim(supplier_sku)) not valid;
alter table public.supplier_products_raw
  validate constraint chk_spr_sku_trimmed;;

-- <<< END 20260606114827_spr_normalize_keys_guard_v1.sql <<<

-- >>> BEGIN 20260606115647_fn_ingest_supplier_raw_upsert_v1.sql >>>
-- Porta de ingestao canonica (UPSERT). Substitui o padrao DELETE+INSERT do SM.
-- Efeitos: (1) chave aparada pelo trigger; (2) ON CONFLICT atualiza em vez de duplicar;
-- (3) ao mudar raw_data, content_hash (generated) muda e trg_spr_history arquiva a versao anterior.
create or replace function public.fn_ingest_supplier_raw(
  p_supplier_id uuid,
  p_reference   text,
  p_raw         jsonb,
  p_sku         text default null,
  p_source      text default 'n8n'
)
returns table(acao text, raw_id uuid, content_hash text)
language plpgsql
as $$
declare
  v_ref     text := btrim(p_reference);
  v_existed boolean;
  v_id      uuid;
  v_hash    text;
begin
  if p_supplier_id is null or v_ref is null or v_ref = '' then
    raise exception 'fn_ingest_supplier_raw: supplier_id e reference sao obrigatorios';
  end if;
  if p_raw is null or jsonb_typeof(p_raw) <> 'object' then
    raise exception 'fn_ingest_supplier_raw: raw deve ser um objeto jsonb';
  end if;

  v_existed := exists (
    select 1 from public.supplier_products_raw
     where supplier_id = p_supplier_id and supplier_reference = v_ref
  );

  insert into public.supplier_products_raw
    (supplier_id, supplier_reference, supplier_sku, raw_data, source_channel)
  values
    (p_supplier_id, v_ref, coalesce(nullif(btrim(p_sku), ''), v_ref), p_raw, coalesce(p_source, 'n8n'))
  on conflict (supplier_id, supplier_reference) do update
     set raw_data       = excluded.raw_data,
         supplier_sku   = excluded.supplier_sku,
         source_channel = excluded.source_channel,
         status         = 'pending'::supplier_raw_status,
         updated_at     = now()
  returning id, supplier_products_raw.content_hash into v_id, v_hash;

  return query select case when v_existed then 'updated' else 'inserted' end, v_id, v_hash;
end;
$$;

comment on function public.fn_ingest_supplier_raw(uuid, text, jsonb, text, text)
  is 'Porta de ingestao idempotente (UPSERT) para supplier_products_raw. Recomendada para o n8n substituir DELETE+INSERT. Atualiza raw_data no conflito, disparando versionamento via trg_spr_history.';;

-- <<< END 20260606115647_fn_ingest_supplier_raw_upsert_v1.sql <<<

