-- >>> BEGIN 20260606121659_fn_refresh_product_satellites_v1.sql >>>
create or replace function public.fn_refresh_product_satellites(p_product_id uuid default null)
returns void
language plpgsql
as $$
begin
  insert into public.product_seo as t
    (product_id, meta_title, meta_description, meta_keywords, schema_json, canonical_url,
     robots_meta, seo_score, seo_last_audit_at, seo_issues, og_title, og_description, og_image_url)
  select p.id, p.meta_title, p.meta_description, p.meta_keywords, p.schema_json, p.canonical_url,
         p.robots_meta, p.seo_score, p.seo_last_audit_at, p.seo_issues, p.og_title, p.og_description, p.og_image_url
  from public.products p
  where p_product_id is null or p.id = p_product_id
  on conflict (product_id) do update set
    meta_title=excluded.meta_title, meta_description=excluded.meta_description, meta_keywords=excluded.meta_keywords,
    schema_json=excluded.schema_json, canonical_url=excluded.canonical_url, robots_meta=excluded.robots_meta,
    seo_score=excluded.seo_score, seo_last_audit_at=excluded.seo_last_audit_at, seo_issues=excluded.seo_issues,
    og_title=excluded.og_title, og_description=excluded.og_description, og_image_url=excluded.og_image_url;

  insert into public.product_ai as t
    (product_id, ai_summary, key_benefits, use_cases, target_audience, ai_title, ai_description,
     ai_version, ai_generated_at, ai_model)
  select p.id, p.ai_summary, p.key_benefits, p.use_cases, p.target_audience, p.ai_title, p.ai_description,
         p.ai_version, p.ai_generated_at, p.ai_model
  from public.products p
  where p_product_id is null or p.id = p_product_id
  on conflict (product_id) do update set
    ai_summary=excluded.ai_summary, key_benefits=excluded.key_benefits, use_cases=excluded.use_cases,
    target_audience=excluded.target_audience, ai_title=excluded.ai_title, ai_description=excluded.ai_description,
    ai_version=excluded.ai_version, ai_generated_at=excluded.ai_generated_at, ai_model=excluded.ai_model;

  insert into public.product_packaging as t
    (product_id, box_length_mm, box_width_mm, box_height_mm, box_weight_kg, box_length_cm, box_width_cm,
     box_height_cm, box_volume_cm3, box_quantity, box_inner_quantity, packing_type, repacking_type,
     packaging_material, packaging_color, packaging_finish, packaging_context, has_inner_cradle, cradle_material,
     packing_classification, repacking_classification, has_commercial_packaging, has_optional_packaging,
     optional_packaging_ref, description_packaging_info, box_image, has_gift_box)
  select p.id, p.box_length_mm, p.box_width_mm, p.box_height_mm, p.box_weight_kg, p.box_length_cm, p.box_width_cm,
         p.box_height_cm, p.box_volume_cm3, p.box_quantity, p.box_inner_quantity, p.packing_type, p.repacking_type,
         p.packaging_material, p.packaging_color, p.packaging_finish, p.packaging_context, p.has_inner_cradle, p.cradle_material,
         p.packing_classification, p.repacking_classification, p.has_commercial_packaging, p.has_optional_packaging,
         p.optional_packaging_ref, p.description_packaging_info, p.box_image, p.has_gift_box
  from public.products p
  where p_product_id is null or p.id = p_product_id
  on conflict (product_id) do update set
    box_length_mm=excluded.box_length_mm, box_width_mm=excluded.box_width_mm, box_height_mm=excluded.box_height_mm,
    box_weight_kg=excluded.box_weight_kg, box_length_cm=excluded.box_length_cm, box_width_cm=excluded.box_width_cm,
    box_height_cm=excluded.box_height_cm, box_volume_cm3=excluded.box_volume_cm3, box_quantity=excluded.box_quantity,
    box_inner_quantity=excluded.box_inner_quantity, packing_type=excluded.packing_type, repacking_type=excluded.repacking_type,
    packaging_material=excluded.packaging_material, packaging_color=excluded.packaging_color, packaging_finish=excluded.packaging_finish,
    packaging_context=excluded.packaging_context, has_inner_cradle=excluded.has_inner_cradle, cradle_material=excluded.cradle_material,
    packing_classification=excluded.packing_classification, repacking_classification=excluded.repacking_classification,
    has_commercial_packaging=excluded.has_commercial_packaging, has_optional_packaging=excluded.has_optional_packaging,
    optional_packaging_ref=excluded.optional_packaging_ref, description_packaging_info=excluded.description_packaging_info,
    box_image=excluded.box_image, has_gift_box=excluded.has_gift_box;
end;
$$;

comment on function public.fn_refresh_product_satellites(uuid)
  is 'Re-sincroniza os satelites (product_seo/ai/packaging) a partir de products. NULL = todos; ou um product_id. Chamar pos-promote/bulk.';;

-- <<< END 20260606121659_fn_refresh_product_satellites_v1.sql <<<

-- >>> BEGIN 20260606121907_spot_variant_reconcile_to_legacy.sql >>>
-- Reconciliação NÃO-DESTRUTIVA: leva o enrich de variante (do feed/Silver) para a
-- variante VIVA legada, casando por color_code (esquema de SKU legado != feed).
-- Para têxteis multi-tamanho por cor, mapeia a nível de cor (refinar com size_code depois).
CREATE OR REPLACE FUNCTION public.fn_spot_reconcile_variant_to_legacy(p_supplier_id uuid, p_parent_ref text DEFAULT NULL)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','extensions' AS $$
DECLARE v_n integer;
BEGIN
  PERFORM set_config('app.bulk_import_mode','true', true);
  UPDATE public.variant_supplier_sources vss
  SET your_price      = f.your_price,
      next_quantity_1 = f.next_quantity_1, next_quantity_2 = f.next_quantity_2, next_quantity_3 = f.next_quantity_3,
      next_quantity_4 = f.next_quantity_4, next_quantity_5 = f.next_quantity_5, next_quantity_6 = f.next_quantity_6,
      next_date_1 = f.next_date_1, next_date_2 = f.next_date_2, next_date_3 = f.next_date_3,
      next_date_4 = f.next_date_4, next_date_5 = f.next_date_5, next_date_6 = f.next_date_6
  FROM public.product_variants lv
  JOIN public.products p ON p.id = lv.product_id AND p.supplier_id = p_supplier_id
  JOIN LATERAL (
      SELECT ppv.*
      FROM public.produtos_padronizacao_variantes ppv
      WHERE ppv.supplier_id = p_supplier_id
        AND ppv.parent_reference = p.supplier_reference
        AND ppv.color_code = lv.color_code
      ORDER BY ppv.variant_reference
      LIMIT 1
  ) f ON TRUE
  WHERE vss.variant_id = lv.id AND vss.supplier_id = p_supplier_id
    AND lv.is_active AND lv.color_code IS NOT NULL
    AND (p_parent_ref IS NULL OR p.supplier_reference = p_parent_ref);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;;

-- <<< END 20260606121907_spot_variant_reconcile_to_legacy.sql <<<

-- >>> BEGIN 20260606122156_spot_seo_nondestructive_gapfill.sql >>>
CREATE OR REPLACE FUNCTION public.fn_spot_gold_enrich(p_supplier_id uuid, p_parent_ref text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','extensions' AS $$
DECLARE v_tax int; v_cat int; v_seo int; v_extra int;
BEGIN
  PERFORM set_config('app.bulk_import_mode','true', true);

  UPDATE public.products p
  SET supplier_type=pp.supplier_type, supplier_type_code=pp.supplier_type_code,
      supplier_subtype=pp.supplier_subtype, supplier_subtype_code=pp.supplier_subtype_code
  FROM public.produtos_padronizacao pp
  WHERE pp.product_id=p.id AND pp.supplier_id=p_supplier_id
    AND (p_parent_ref IS NULL OR pp.supplier_reference=p_parent_ref);
  GET DIAGNOSTICS v_tax = ROW_COUNT;

  UPDATE public.products p
  SET category_id = m.category_id
  FROM public.produtos_padronizacao pp
  JOIN public.supplier_subtype_category_map m
    ON m.supplier_id = pp.supplier_id
   AND lower(unaccent(m.subtype_desc)) = lower(unaccent(pp.supplier_subtype))
  WHERE pp.product_id=p.id AND pp.supplier_id=p_supplier_id
    AND p.category_id IS NULL AND m.category_id IS NOT NULL
    AND (p_parent_ref IS NULL OR pp.supplier_reference=p_parent_ref);
  GET DIAGNOSTICS v_cat = ROW_COUNT;

  -- SEO NÃO-DESTRUTIVO: apenas preenche vazios (nunca sobrescreve og/meta já geradas).
  -- ai_* (que o autofill não toca) recebem a cópia do fornecedor.
  UPDATE public.products p
  SET ai_title        = COALESCE(p.ai_title, nullif(pp.supplier_seo_name,'')),
      ai_description  = COALESCE(p.ai_description, nullif(pp.supplier_seo_short_description,'')),
      og_description  = COALESCE(p.og_description, nullif(pp.supplier_seo_short_description,'')),
      meta_description= COALESCE(p.meta_description,
                          CASE WHEN char_length(nullif(pp.supplier_seo_short_description,'')) BETWEEN 50 AND 170
                               THEN pp.supplier_seo_short_description END)
  FROM public.produtos_padronizacao pp
  WHERE pp.product_id=p.id AND pp.supplier_id=p_supplier_id
    AND (p_parent_ref IS NULL OR pp.supplier_reference=p_parent_ref)
    AND (pp.supplier_seo_name IS NOT NULL OR pp.supplier_seo_short_description IS NOT NULL);
  GET DIAGNOSTICS v_seo = ROW_COUNT;

  UPDATE public.products p
  SET certificates       = COALESCE(pp.certificates, p.certificates),
      certificate_files  = COALESCE(pp.certificate_files, p.certificate_files),
      related_references = COALESCE(pp.related_references, p.related_references),
      weight_gr          = COALESCE(pp.weight_gr, p.weight_gr),
      is_seasonal        = COALESCE(pp.is_seasonal, p.is_seasonal),
      pvc_free           = COALESCE(pp.pvc_free, p.pvc_free)
  FROM public.produtos_padronizacao pp
  WHERE pp.product_id=p.id AND pp.supplier_id=p_supplier_id
    AND (p_parent_ref IS NULL OR pp.supplier_reference=p_parent_ref);
  GET DIAGNOSTICS v_extra = ROW_COUNT;

  RETURN jsonb_build_object('taxonomia_gold',v_tax,'categorias_por_subtype',v_cat,'seo_atualizados',v_seo,'extras_atualizados',v_extra);
END $$;;

-- <<< END 20260606122156_spot_seo_nondestructive_gapfill.sql <<<

-- >>> BEGIN 20260606122428_asia_ingest_normalize_propriedades_shape.sql >>>
CREATE OR REPLACE FUNCTION public.fn_ingest_asia_product(p_prod jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ASIA   uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_parent text := p_prod->>'referencia';
  v_var    jsonb;
  v_var_ref text;
  v_content jsonb;
  v_stock   jsonb;
  v_props   jsonb;
  v_chash   text;
  v_shash   text;
  v_vars    int := 0;
BEGIN
  IF v_parent IS NULL OR jsonb_typeof(p_prod->'variacoes') <> 'array' THEN
    RETURN jsonb_build_object('success', false, 'error', 'payload_invalido', 'parent', v_parent);
  END IF;

  -- Normaliza propriedades: aceita OBJETO {slug:valor} OU ARRAY [{slug,nome,valor}].
  -- DISTINCT ON (slug) mantém a 1a ocorrência (resolve slug duplicado, ex. dimensao-do-produto fechado/aberto).
  IF jsonb_typeof(p_prod->'propriedades') = 'array' THEN
    SELECT COALESCE(jsonb_object_agg(slug, valor), '{}'::jsonb) INTO v_props
    FROM (
      SELECT DISTINCT ON (e->>'slug') e->>'slug' AS slug, COALESCE(e->>'valor', e->>'value') AS valor
      FROM jsonb_array_elements(p_prod->'propriedades') WITH ORDINALITY AS x(e, ord)
      WHERE NULLIF(e->>'slug','') IS NOT NULL
      ORDER BY e->>'slug', ord
    ) d;
  ELSIF jsonb_typeof(p_prod->'propriedades') = 'object' THEN
    v_props := p_prod->'propriedades';
  ELSE
    v_props := '{}'::jsonb;
  END IF;

  FOR v_var IN SELECT * FROM jsonb_array_elements(p_prod->'variacoes')
  LOOP
    v_var_ref := v_var->>'referencia';
    CONTINUE WHEN v_var_ref IS NULL OR TRIM(v_var_ref) = '';
    v_vars := v_vars + 1;

    v_content := jsonb_strip_nulls(jsonb_build_object(
      'referencia',         v_parent,
      'var_referencia',     v_var_ref,
      'nome',               p_prod->>'nome',
      'descricao',          p_prod->>'descricao',
      'preco',              v_var->>'preco',
      'imagem',             COALESCE(v_var->>'imagem', p_prod->>'imagem'),
      'galeria',            COALESCE(p_prod->'galeria', '[]'::jsonb),
      'video',              p_prod->>'video',
      'ncm',                COALESCE(v_var->>'ncm', v_props->>'ncm'),
      'altura',             p_prod->>'altura',
      'largura',            p_prod->>'largura',
      'comprimento',        p_prod->>'comprimento',
      'peso',               p_prod->>'peso',
      'status',             p_prod->>'status',
      'promocao',           p_prod->>'promocao',
      'origem_faturamento', p_prod->>'origem_faturamento',
      'propriedades',       v_props,
      'categorias',         COALESCE(p_prod->'categorias', '{}'::jsonb),
      'tags',               COALESCE(p_prod->'tags', '{}'::jsonb),
      'atributos',          COALESCE(v_var->'atributos', '{}'::jsonb),
      'var_cor_nome',       COALESCE(v_var->'atributos'->'cor'->>'value', v_var->'atributos'->'cor'->>'valor', v_var->>'cor'),
      'var_cor_hex',        COALESCE(v_var->'atributos'->'cor'->>'hexadecimal', v_var->'atributos'->'cor'->>'hex', v_var->>'cor_hex')
    ));

    v_stock := jsonb_build_object(
      'qtd_estoque',       COALESCE(public.fn_safe_int(v_var->>'qtd_estoque'), 0),
      'qtd_estoque_em_sp', COALESCE(public.fn_safe_int(v_var->>'qtd_estoque_em_sp'), 0),
      'previsao_entrega',  COALESCE(v_var->'previsao_entrega', '[]'::jsonb)
    );

    v_chash := encode(digest(v_content::text, 'sha256'), 'hex');
    v_shash := encode(digest(v_stock::text,   'sha256'), 'hex');

    INSERT INTO public.supplier_products_raw AS spr (
      supplier_id, supplier_reference, supplier_sku, raw_data,
      stock_data, stock_hash, stock_status, stock_synced_at,
      source_channel, source_endpoint, status, images_status
    ) VALUES (
      v_ASIA, v_var_ref, v_var_ref, v_content,
      v_stock, v_shash, 'pending'::supplier_raw_status, now(),
      'n8n', 'listarProdutos2', 'pending'::supplier_raw_status, 'pending'::supplier_raw_status
    )
    ON CONFLICT (supplier_id, supplier_sku) DO UPDATE SET
      raw_data           = EXCLUDED.raw_data,
      supplier_reference = EXCLUDED.supplier_reference,
      status             = CASE WHEN spr.content_hash IS DISTINCT FROM v_chash
                                THEN 'pending'::supplier_raw_status ELSE spr.status END,
      stock_data         = EXCLUDED.stock_data,
      stock_hash         = EXCLUDED.stock_hash,
      stock_status       = CASE WHEN spr.stock_hash IS DISTINCT FROM EXCLUDED.stock_hash
                                THEN 'pending'::supplier_raw_status ELSE spr.stock_status END,
      stock_synced_at    = now(),
      source_channel     = EXCLUDED.source_channel,
      source_endpoint    = EXCLUDED.source_endpoint;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'parent', v_parent, 'variacoes', v_vars);
END;
$function$;;

-- <<< END 20260606122428_asia_ingest_normalize_propriedades_shape.sql <<<

-- >>> BEGIN 20260606122455_asia_enrich_capacity_and_dims_priority.sql >>>
CREATE OR REPLACE FUNCTION public.fn_asia_enrich_parent(p_supplier_id uuid, p_parent_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_raw jsonb; v_asia jsonb; v_asia_prop jsonb; v_n int;
  v_h numeric; v_w numeric; v_l numeric;
  v_cap_raw text; v_cap_ml int;
BEGIN
  SELECT (SELECT raw_data FROM public.supplier_products_raw WHERE id = pv.raw_id)
    INTO v_raw
  FROM public.produtos_padronizacao_variantes pv
  WHERE pv.supplier_id = p_supplier_id
    AND pv.parent_reference = p_parent_reference
    AND pv.raw_id IS NOT NULL
  ORDER BY length((SELECT raw_data::text FROM public.supplier_products_raw WHERE id = pv.raw_id)) DESC NULLS LAST, pv.raw_id
  LIMIT 1;

  IF v_raw IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'sem_representante', 'parent', p_parent_reference);
  END IF;

  -- parser normal (peso/caixa/embalagem; dims com prioridade da raiz)
  v_asia := public.fn_parse_asia_properties(
    COALESCE(v_raw->'propriedades', '{}'::jsonb),
    COALESCE(public.fn_safe_num(v_raw->>'altura'), 0),
    COALESCE(public.fn_safe_num(v_raw->>'largura'), 0),
    COALESCE(public.fn_safe_num(v_raw->>'comprimento'), 0),
    COALESCE(public.fn_safe_num(v_raw->>'peso'), 0),
    v_raw->>'origem_faturamento');

  -- parser SO-propriedades (api dims = 0): dims do PRODUTO via propriedades tem PRIORIDADE sobre dimensoes_cm da raiz
  v_asia_prop := public.fn_parse_asia_properties(
    COALESCE(v_raw->'propriedades', '{}'::jsonb), 0, 0, 0, 0, v_raw->>'origem_faturamento');

  v_h := COALESCE((v_asia_prop->>'height_cm')::numeric, (v_asia->>'height_cm')::numeric);
  v_w := COALESCE((v_asia_prop->>'width_cm')::numeric,  (v_asia->>'width_cm')::numeric);
  v_l := COALESCE((v_asia_prop->>'length_cm')::numeric, (v_asia->>'length_cm')::numeric);

  -- capacidade: vem da VARIACAO (atributos.capacidade "780ml" | atributos.volume-litros "3,2L"),
  -- aceita value/valor; fallback propriedades.volume/capacidade. Converte L -> ml.
  v_cap_raw := lower(COALESCE(
     v_raw->'atributos'->'capacidade'->>'value',
     v_raw->'atributos'->'capacidade'->>'valor',
     v_raw->'atributos'->'volume-litros'->>'value',
     v_raw->'atributos'->'volume-litros'->>'valor',
     v_raw->'propriedades'->>'volume',
     v_raw->'propriedades'->>'capacidade',
     ''));
  v_cap_ml := CASE
     WHEN v_cap_raw ~ 'ml' THEN NULLIF(regexp_replace(v_cap_raw, '[^0-9]', '', 'g'), '')::int
     WHEN v_cap_raw ~ 'l'  THEN round(NULLIF(replace(regexp_replace(v_cap_raw, '[^0-9,\.]', '', 'g'), ',', '.'), '')::numeric * 1000)::int
     ELSE NULL END;

  UPDATE public.produtos_padronizacao SET
    description        = COALESCE(NULLIF(v_raw->>'descricao', ''), description),
    images             = CASE WHEN jsonb_typeof(v_raw->'galeria') = 'array' AND jsonb_array_length(v_raw->'galeria') > 0
                              THEN v_raw->'galeria' ELSE images END,
    height_cm          = COALESCE(v_h, height_cm),
    width_cm           = COALESCE(v_w, width_cm),
    length_cm          = COALESCE(v_l, length_cm),
    weight_g           = COALESCE((v_asia->>'weight_g')::int, weight_g),
    box_length_cm      = COALESCE((v_asia->>'box_length_cm')::numeric, box_length_cm),
    box_width_cm       = COALESCE((v_asia->>'box_width_cm')::numeric, box_width_cm),
    box_height_cm      = COALESCE((v_asia->>'box_height_cm')::numeric, box_height_cm),
    box_weight_kg      = COALESCE((v_asia->>'box_weight_kg')::numeric, box_weight_kg),
    box_quantity       = COALESCE((v_asia->>'box_quantity')::int, box_quantity),
    packing_type       = COALESCE(v_asia->>'packing_type', packing_type),
    capacity_ml        = COALESCE(v_cap_ml, (v_asia->>'capacity_ml')::int, capacity_ml),
    dimensions_display = COALESCE(NULLIF(v_raw->'propriedades'->>'dimensao-do-produto', ''),
                                  NULLIF(v_raw->'propriedades'->>'dimensao-produto', ''), dimensions_display),
    updated_at = now()
  WHERE supplier_id = p_supplier_id AND supplier_reference = p_parent_reference;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('success', v_n > 0, 'parent', p_parent_reference, 'rows', v_n,
                            'dims_cm', jsonb_build_object('h', v_h, 'w', v_w, 'l', v_l), 'capacity_ml', v_cap_ml);
END;
$function$;;

-- <<< END 20260606122455_asia_enrich_capacity_and_dims_priority.sql <<<

