-- >>> BEGIN 20260606124338_asia_create_stock_pending_processor.sql >>>
CREATE OR REPLACE FUNCTION public.fn_process_asia_stock_pending(p_limit integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_ASIA uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  r RECORD;
  v_stock int; v_nd1 date; v_nq1 int; v_up int;
  v_seen int := 0; v_applied int := 0; v_missing int := 0;
  v_t0 timestamptz := clock_timestamp();
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
  END IF;

  IF NOT pg_try_advisory_xact_lock(hashtext('fn_process_asia_stock_pending')::bigint) THEN
    RETURN jsonb_build_object('success', true, 'skipped', 'lock_ocupado');
  END IF;

  PERFORM set_config('app.write_source', 'pipeline_stock', true);

  FOR r IN
    SELECT id, supplier_reference, stock_data, raw_data
    FROM public.supplier_products_raw
    WHERE supplier_id = v_ASIA
      AND stock_status = 'pending'
    ORDER BY stock_synced_at NULLS FIRST, id
    LIMIT p_limit
    FOR UPDATE SKIP LOCKED
  LOOP
    v_seen := v_seen + 1;

    -- espelha EXATAMENTE o branch ASIA de fn_standardize_variant (fonte unica da verdade p/ estoque)
    v_stock := public.fn_safe_int(COALESCE(r.stock_data->>'qtd_estoque', r.raw_data->>'var_estoque'));
    v_nd1 := CASE
      WHEN COALESCE(r.stock_data->'previsao_entrega'->0->>'data', r.raw_data->'previsao_entrega'->0->>'data') ~ '^\d{4}-\d{2}-\d{2}'
      THEN left(COALESCE(r.stock_data->'previsao_entrega'->0->>'data', r.raw_data->'previsao_entrega'->0->>'data'), 10)::date END;
    v_nq1 := public.fn_safe_int(COALESCE(r.stock_data->'previsao_entrega'->0->>'quantidade', r.raw_data->'previsao_entrega'->0->>'quantidade'));

    UPDATE public.produtos_padronizacao_variantes
       SET stock_quantity = v_stock,
           next_date_1     = v_nd1,
           next_quantity_1 = v_nq1,
           updated_at      = now()
     WHERE supplier_id = v_ASIA
       AND variant_reference = r.supplier_reference;
    GET DIAGNOSTICS v_up = ROW_COUNT;

    IF v_up > 0 THEN v_applied := v_applied + 1; ELSE v_missing := v_missing + 1; END IF;

    -- fecha a trilha de estoque (independe do status de conteudo)
    UPDATE public.supplier_products_raw
       SET stock_status = 'processed'::supplier_raw_status,
           stock_synced_at = now()
     WHERE id = r.id;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true, 'supplier', 'ASIA',
    'vistos', v_seen, 'aplicados', v_applied, 'variante_inexistente', v_missing,
    'segundos', round(extract(epoch FROM clock_timestamp() - v_t0)::numeric, 1));
END;
$function$;

COMMENT ON FUNCTION public.fn_process_asia_stock_pending(integer) IS
'Lane de ESTOQUE ASIA: drena supplier_products_raw.stock_status=pending, aplica stock_quantity + reposicao (previsao_entrega[0]) em produtos_padronizacao_variantes e marca stock_status=processed. Espelha o branch ASIA de fn_standardize_variant. Agendada via pg_cron (asia-stock-sync).';;

-- <<< END 20260606124338_asia_create_stock_pending_processor.sql <<<

-- >>> BEGIN 20260606124341_spot_fix_batch_dedup_canonical.sql >>>
CREATE OR REPLACE FUNCTION public.fn_spot_batch_to_silver(p_batch_size integer DEFAULT 500)
RETURNS TABLE(processed integer, errors integer)
LANGUAGE plpgsql
AS $function$
DECLARE
  v_bronze_id UUID; v_processed INT := 0; v_errors INT := 0;
  v_supplier_id UUID := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';  -- SPOT/Stricker (fixo, robusto)
BEGIN
  FOR v_bronze_id IN (
    SELECT spr.id
    FROM public.supplier_products_raw spr
    WHERE spr.supplier_id = v_supplier_id
      AND spr.attempts < 5
      -- DEDUP CANÔNICO (BUG-2 fix): antes checava silver_variants (tabela legada/morta),
      -- o que reprocessava todo o catálogo. Agora checa a intermediária real.
      AND NOT EXISTS (
        SELECT 1 FROM public.produtos_padronizacao_variantes ppv
        WHERE ppv.supplier_id = v_supplier_id
          AND ppv.variant_reference = spr.supplier_reference
      )
    ORDER BY spr.imported_at
    LIMIT p_batch_size
  ) LOOP
    BEGIN
      PERFORM public.fn_spot_to_silver(v_bronze_id);  -- delega p/ standardize_raw + standardize_variant
      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      RAISE WARNING 'Erro bronze_id %: %', v_bronze_id, SQLERRM;
    END;
  END LOOP;
  RETURN QUERY SELECT v_processed, v_errors;
END;
$function$;;

-- <<< END 20260606124341_spot_fix_batch_dedup_canonical.sql <<<

-- >>> BEGIN 20260606124604_spot_fix_materials_split_regex.sql >>>
-- Helper: divide lista por regex [.,]\s+ (ponto OU vírgula + espaço), conserta mojibake, limpa vazios.
CREATE OR REPLACE FUNCTION public.fn_spot_split_list(p text)
RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path TO 'public','extensions' AS $$
  SELECT to_jsonb(COALESCE(array_agg(btrim(e)) FILTER (WHERE btrim(e) <> ''), ARRAY[]::text[]))
  FROM unnest(regexp_split_to_array(public.fn_fix_mojibake(COALESCE(p,'')), '[.,]\s+')) e;
$$;

-- Corretor SPOT-isolado: re-deriva produtos_padronizacao.materials a partir do Bronze (Materials),
-- usando o split por regex. NÃO toca outros fornecedores nem a função compartilhada.
CREATE OR REPLACE FUNCTION public.fn_spot_fix_materials(p_supplier_id uuid, p_parent_ref text DEFAULT NULL)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','extensions' AS $$
DECLARE v_n integer;
BEGIN
  PERFORM set_config('app.bulk_import_mode','true', true);
  UPDATE public.produtos_padronizacao pp
  SET materials = public.fn_spot_split_list(spr.raw_data->>'Materials'), updated_at = now()
  FROM public.supplier_products_raw spr
  WHERE pp.raw_id = spr.id
    AND pp.supplier_id = p_supplier_id
    AND nullif(btrim(spr.raw_data->>'Materials'),'') IS NOT NULL
    AND (p_parent_ref IS NULL OR pp.supplier_reference = p_parent_ref);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;;

-- <<< END 20260606124604_spot_fix_materials_split_regex.sql <<<

