-- >>> BEGIN 20260606124728_spot_pipeline_orchestrator.sql >>>
-- Orquestrador SPOT por REF: Bronze -> Silver -> Gold com TODAS as etapas, na ordem correta.
-- Idempotente. re-standardize re-arma status='standardized' (necessário p/ promote).
CREATE OR REPLACE FUNCTION public.fn_spot_process_ref(p_parent_ref text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','extensions' AS $$
DECLARE
  v_sup uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_rep uuid; v_pad uuid; r record; v_vars int := 0;
  v_promo jsonb; v_promv jsonb; v_repl int; v_pos int; v_gold jsonb; v_recon int;
BEGIN
  PERFORM set_config('app.write_source','pipeline', true);
  PERFORM set_config('app.bulk_import_mode','true', true);

  -- 1. representante (raw com mais conteúdo) + padroniza PARENT
  SELECT spr.id INTO v_rep FROM public.supplier_products_raw spr
   WHERE spr.supplier_id=v_sup AND spr.raw_data->>'ProdReference'=p_parent_ref
   ORDER BY length(spr.raw_data::text) DESC NULLS LAST, spr.id LIMIT 1;
  IF v_rep IS NULL THEN RETURN jsonb_build_object('success',false,'error','sem_raw','ref',p_parent_ref); END IF;
  PERFORM public.fn_standardize_raw(v_rep, p_parent_ref);

  -- 2. padroniza VARIANTES
  FOR r IN SELECT id FROM public.supplier_products_raw
            WHERE supplier_id=v_sup AND raw_data->>'ProdReference'=p_parent_ref LOOP
    PERFORM public.fn_standardize_variant(r.id); v_vars := v_vars + 1;
  END LOOP;

  -- 3. enrich Silver (taxonomia/SEO/extras/reparo texto) + 4. materials regex (BUG-1)
  PERFORM public.fn_spot_silver_enrich(v_sup, p_parent_ref);
  PERFORM public.fn_spot_fix_materials(v_sup, p_parent_ref);

  -- 5. promove PARENT (precisa status standardized) + VARIANTES
  SELECT id INTO v_pad FROM public.produtos_padronizacao
   WHERE supplier_id=v_sup AND supplier_reference=p_parent_ref
   ORDER BY standardized_at DESC NULLS LAST LIMIT 1;
  v_promo  := public.fn_promote_padronizacao(v_pad);
  v_promv  := public.fn_promote_variants_of_parent(v_sup, p_parent_ref);

  -- 6. enrich Gold (variante + produto) + reconciliação variante-viva
  v_repl   := public.fn_spot_variant_repl_enrich(v_sup, p_parent_ref);
  v_pos    := public.fn_spot_print_positions(v_sup, p_parent_ref);
  v_gold   := public.fn_spot_gold_enrich(v_sup, p_parent_ref);
  v_recon  := public.fn_spot_reconcile_variant_to_legacy(v_sup, p_parent_ref);

  RETURN jsonb_build_object('success',true,'ref',p_parent_ref,'variantes',v_vars,
    'promote_parent',v_promo->'success','promote_variants',v_promv->'variantes_promovidas',
    'repl',v_repl,'print_positions',v_pos,'gold',v_gold,'reconciliadas',v_recon);
END $$;

-- Batch por LOTE (ordenado, janela offset/limit). NÃO roda sozinho; chamada manual controla o rollout.
CREATE OR REPLACE FUNCTION public.fn_spot_process_batch(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public','extensions' AS $$
DECLARE
  v_sup uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_ref text; v_ok int := 0; v_err int := 0; v_errs jsonb := '[]'::jsonb;
BEGIN
  FOR v_ref IN
    SELECT DISTINCT raw_data->>'ProdReference' rr
    FROM public.supplier_products_raw
    WHERE supplier_id=v_sup AND raw_data->>'ProdReference' IS NOT NULL
    ORDER BY rr OFFSET p_offset LIMIT p_limit
  LOOP
    BEGIN
      PERFORM public.fn_spot_process_ref(v_ref); v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_err := v_err + 1; v_errs := v_errs || jsonb_build_object('ref',v_ref,'erro',SQLERRM);
    END;
  END LOOP;
  RETURN jsonb_build_object('processados',v_ok,'erros',v_err,'detalhe_erros',v_errs,'offset',p_offset,'limit',p_limit);
END $$;;

-- <<< END 20260606124728_spot_pipeline_orchestrator.sql <<<

-- >>> BEGIN 20260606124749_fn_silver_to_gold_locked_parity_v2.sql >>>
create or replace function public.fn_silver_to_gold(p_silver_id uuid)
 returns jsonb
 language plpgsql
as $function$
declare
  v_sp silver_products%rowtype;
  v_gold_id uuid; v_slug text;
  v_vars_ok int := 0; v_new_var_id uuid; sv record;
  v_var_name text;
  v_locked text[] := '{}';
begin
  select * into v_sp from silver_products where id = p_silver_id;
  if not found then raise exception 'Silver product % nao encontrado', p_silver_id; end if;
  if v_sp.norm_status = 'promoted' then
    return jsonb_build_object('gold_product_id',v_sp.gold_product_id,'status','already_promoted');
  end if;
  if v_sp.name is null then raise exception 'Silver product % sem nome', p_silver_id; end if;

  -- PARIDADE COM A V1: marca a escrita como pipeline (evita captura de "edicao manual"
  -- corromper locked_fields) e suprime automacoes pesadas de products.
  perform set_config('app.write_source','pipeline',true);
  perform set_config('app.bulk_import_mode','true',true);

  v_slug := lower(regexp_replace(regexp_replace(
    translate(left(v_sp.name,80),
      'áàãâäéèêëíìîïóòõôöúùûüçñÁÀÃÂÄÉÈÊËÍÌÎÏÓÒÕÔÖÚÙÛÜÇÑ',
      'aaaaaeeeeiiiiooooouuuucnAAAAEEEEIIIIOOOOOUUUUCN'),
    '[^a-z0-9\s]','','g'),'\s+','-','g'))
    || '-' || substr(p_silver_id::text,1,8);

  if v_sp.gold_product_id is not null then
    -- carrega os campos travados do produto Gold
    select coalesce(locked_fields,'{}') into v_locked from products where id = v_sp.gold_product_id;

    update products p set
      name               = case when 'name'        = any(v_locked) then p.name        else v_sp.name end,
      description        = case when 'description'  = any(v_locked) then p.description else coalesce(v_sp.description, p.description) end,
      category_id        = case when 'category_id' = any(v_locked) or 'main_category_id' = any(v_locked)
                                 then p.category_id else coalesce(v_sp.norm_category_id, p.category_id) end,
      supplier_id        = v_sp.supplier_id,
      brand              = case when 'brand'        = any(v_locked) then p.brand     else coalesce(v_sp.brand, p.brand) end,
      ncm_code           = case when 'ncm_code'     = any(v_locked) then p.ncm_code  else coalesce(v_sp.ncm_code, p.ncm_code) end,
      supply_mode        = coalesce(v_sp.supply_mode, p.supply_mode),
      min_order_quantity = case when 'min_quantity' = any(v_locked) then p.min_order_quantity else coalesce(v_sp.min_order_quantity, p.min_order_quantity) end,
      is_active          = case when 'is_active'    = any(v_locked) then p.is_active else v_sp.is_active end,
      updated_at         = now()
    where p.id = v_sp.gold_product_id;
    v_gold_id := v_sp.gold_product_id;
  else
    insert into products (
      organization_id, supplier_id, name, description, category_id, brand,
      ncm_code, supply_mode, min_order_quantity, is_active, slug
    ) values (
      v_sp.organization_id, v_sp.supplier_id, v_sp.name, v_sp.description,
      v_sp.norm_category_id, v_sp.brand, v_sp.ncm_code,
      coalesce(v_sp.supply_mode,'pronta_entrega_liso'),
      coalesce(v_sp.min_order_quantity,1), v_sp.is_active, v_slug
    ) returning id into v_gold_id;
  end if;

  for sv in select * from silver_variants where silver_product_id = p_silver_id loop
    v_var_name := v_sp.name || coalesce(' | ' || sv.color_name, '');

    if sv.gold_variant_id is not null then
      update product_variants set
        name=v_var_name, stock_quantity=coalesce(sv.stock_quantity,0),
        is_active=sv.is_active, color_code=sv.color_code, color_name=sv.color_name,
        color_hex=sv.color_hex, size_code=sv.size_code, supplier_sku=sv.supplier_sku,
        updated_at=now()
      where id=sv.gold_variant_id;
    else
      insert into product_variants (
        product_id, sku, name, supplier_sku, color_code, color_name, color_hex, size_code,
        stock_quantity, is_active, attributes, images
      ) values (
        v_gold_id, sv.supplier_sku, v_var_name, sv.supplier_sku,
        sv.color_code, sv.color_name, sv.color_hex, sv.size_code,
        coalesce(sv.stock_quantity,0), sv.is_active, '{}'::jsonb, '[]'::jsonb
      ) returning id into v_new_var_id;
      update silver_variants set gold_variant_id=v_new_var_id where id=sv.id;
    end if;
    v_vars_ok := v_vars_ok + 1;
  end loop;

  update silver_products set
    gold_product_id=v_gold_id, norm_status='promoted',
    promoted_at=now(), updated_at=now()
  where id=p_silver_id;

  return jsonb_build_object(
    'gold_product_id',v_gold_id,'silver_id',p_silver_id,
    'supplier_reference',v_sp.supplier_reference,
    'variants_promoted',v_vars_ok,'status','promoted');
exception when others then
  raise warning 'fn_silver_to_gold falhou %: %', p_silver_id, sqlerrm; raise;
end;
$function$;;

-- <<< END 20260606124749_fn_silver_to_gold_locked_parity_v2.sql <<<

-- >>> BEGIN 20260606124754_doc_supplier_category_mappings_global_decision.sql >>>
COMMENT ON TABLE public.supplier_category_mappings IS
'DE>PARA de categorias GLOBAL (compartilhado entre fornecedores). Decisao de modelagem registrada em 2026-06-06: esta tabela NAO possui coluna supplier_id — o mapeamento e chaveado por supplier_category_id -> category_id (canonica) e vale para todos os fornecedores (ASIA, SPOT, XBZ, SM). Difere de supplier_colors e supplier_field_mappings, que sao POR-FORNECEDOR (possuem supplier_id). O campo confidence indica a forca/qualidade do match.';

COMMENT ON COLUMN public.supplier_category_mappings.supplier_category_id IS
'Chave do de-para de categorias (escopo GLOBAL, sem supplier_id): identificador de categoria do fornecedor que mapeia para category_id canonica.';

COMMENT ON COLUMN public.supplier_category_mappings.category_id IS
'Categoria canonica (Gold) destino do de-para.';;

