-- >>> BEGIN 20260606134130_spot_import_stock_close_bronze_lifecycle.sql >>>
CREATE OR REPLACE FUNCTION public.fn_import_stock_from_spot(p_stocks jsonb)
 RETURNS TABLE(total_processed integer, total_updated integer, total_created integer, total_skipped integer, total_errors integer, details jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_stock JSONB;
    v_processed INTEGER := 0;
    v_updated INTEGER := 0;
    v_created INTEGER := 0;
    v_skipped INTEGER := 0;
    v_errors INTEGER := 0;
    v_bronze_closed INTEGER := 0;
    v_supplier_id UUID;
    v_variant_id UUID;
    v_sku TEXT;
    v_error_skus TEXT[] := '{}';
    v_skipped_skus TEXT[] := '{}';
BEGIN
    SELECT id INTO v_supplier_id
    FROM suppliers
    WHERE code = 'STRICKER' OR code = 'SPOT'
       OR name ILIKE '%spot%' OR name ILIKE '%stricker%'
    LIMIT 1;

    IF v_supplier_id IS NULL THEN
        RAISE EXCEPTION 'Fornecedor SPOT/Stricker não encontrado na tabela suppliers';
    END IF;

    FOR v_stock IN SELECT * FROM jsonb_array_elements(p_stocks)
    LOOP
        v_processed := v_processed + 1;
        v_sku := v_stock->>'Sku';

        BEGIN
            UPDATE variant_supplier_sources
            SET
                quantity = COALESCE((v_stock->>'Quantity')::INTEGER, 0),
                next_quantity_1 = NULLIF((v_stock->>'NextQuantity1')::INTEGER, 0),
                next_date_1 = NULLIF(v_stock->>'NextDate1', '')::DATE,
                next_quantity_2 = NULLIF((v_stock->>'NextQuantity2')::INTEGER, 0),
                next_date_2 = NULLIF(v_stock->>'NextDate2', '')::DATE,
                next_quantity_3 = NULLIF((v_stock->>'NextQuantity3')::INTEGER, 0),
                next_date_3 = NULLIF(v_stock->>'NextDate3', '')::DATE,
                last_synced_at = NOW(),
                sync_status = 'synced',
                sync_error = NULL,
                source = 'spot_api',
                raw_data = v_stock,
                updated_at = NOW()
            WHERE supplier_sku = v_sku
              AND supplier_id = v_supplier_id;

            IF FOUND THEN
                v_updated := v_updated + 1;
            ELSE
                SELECT id INTO v_variant_id
                FROM product_variants
                WHERE sku = v_sku OR supplier_sku = v_sku
                LIMIT 1;

                IF v_variant_id IS NOT NULL THEN
                    INSERT INTO variant_supplier_sources (
                        organization_id, variant_id, supplier_id, supplier_sku,
                        quantity, next_quantity_1, next_date_1,
                        next_quantity_2, next_date_2, next_quantity_3, next_date_3,
                        pack_quantity, min_qty_1, min_order_qty,
                        is_active, is_preferred, priority,
                        source, sync_status, last_synced_at, raw_data, sale_multiplier
                    ) VALUES (
                        '5db5aee1-064b-4ef4-9193-345dcd8274ea',
                        v_variant_id, v_supplier_id, v_sku,
                        COALESCE((v_stock->>'Quantity')::INTEGER, 0),
                        NULLIF((v_stock->>'NextQuantity1')::INTEGER, 0),
                        NULLIF(v_stock->>'NextDate1', '')::DATE,
                        NULLIF((v_stock->>'NextQuantity2')::INTEGER, 0),
                        NULLIF(v_stock->>'NextDate2', '')::DATE,
                        NULLIF((v_stock->>'NextQuantity3')::INTEGER, 0),
                        NULLIF(v_stock->>'NextDate3', '')::DATE,
                        1, 1, 1, true, true, 1,
                        'spot_api', 'synced', NOW(), v_stock, 1
                    )
                    ON CONFLICT (organization_id, variant_id, supplier_id)
                    DO UPDATE SET
                        quantity = EXCLUDED.quantity,
                        next_quantity_1 = EXCLUDED.next_quantity_1,
                        next_date_1 = EXCLUDED.next_date_1,
                        next_quantity_2 = EXCLUDED.next_quantity_2,
                        next_date_2 = EXCLUDED.next_date_2,
                        next_quantity_3 = EXCLUDED.next_quantity_3,
                        next_date_3 = EXCLUDED.next_date_3,
                        last_synced_at = NOW(),
                        sync_status = 'synced',
                        raw_data = EXCLUDED.raw_data,
                        updated_at = NOW();

                    v_created := v_created + 1;
                ELSE
                    v_skipped := v_skipped + 1;
                    v_skipped_skus := array_append(v_skipped_skus, v_sku);
                END IF;
            END IF;

        EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors + 1;
            v_error_skus := array_append(v_error_skus, v_sku || ': ' || SQLERRM);
            CONTINUE;
        END;
    END LOOP;

    -- Fechar ciclo de vida Bronze: SPOT stocks API = dump completo.
    -- Apos sync bem-sucedido, todos os rows STRICKER pendentes sao marcados processed.
    -- (stock_data=NULL e esperado para SPOT; o estoque flui API->VSS, nao via Bronze)
    UPDATE public.supplier_products_raw
    SET stock_status = 'processed'::supplier_raw_status,
        stock_synced_at = now()
    WHERE supplier_id = v_supplier_id
      AND stock_status IS DISTINCT FROM 'processed'::supplier_raw_status;
    GET DIAGNOSTICS v_bronze_closed = ROW_COUNT;

    RETURN QUERY SELECT
        v_processed, v_updated, v_created, v_skipped, v_errors,
        jsonb_build_object(
            'error_skus', to_jsonb(v_error_skus[1:10]),
            'skipped_skus_sample', to_jsonb(v_skipped_skus[1:10]),
            'supplier_id', v_supplier_id,
            'bronze_closed', v_bronze_closed
        );
END;
$function$;;

-- <<< END 20260606134130_spot_import_stock_close_bronze_lifecycle.sql <<<

-- >>> BEGIN 20260606135627_add_dim_to_cm_transform_sm_2026.sql >>>
-- Adiciona transform_type 'dim_to_cm' em fn_apply_transform (versão rica, 6 parâmetros)
-- Extrai a n-ésima dimensão de "AxBxC mm (AxLxP)" e converte para cm
CREATE OR REPLACE FUNCTION public.fn_apply_transform(
    p_value        text,
    p_transform_type character varying,
    p_transform_config jsonb,
    p_source_unit  character varying,
    p_target_unit  character varying,
    p_supplier_id  uuid
)
RETURNS text
LANGUAGE plpgsql STABLE
SET search_path TO 'public'
AS $fn$
DECLARE
    v_result     TEXT;
    v_numeric    DECIMAL;
    v_multiplier DECIMAL;
    v_fn         VARCHAR;
    v_pattern    TEXT;
    v_group      INTEGER;
    v_matches    TEXT[];
    v_max_length INTEGER;
BEGIN
    IF p_value IS NULL OR TRIM(p_value) = '' THEN RETURN NULL; END IF;

    CASE p_transform_type

        WHEN 'direct' THEN
            v_result := p_value;

        WHEN 'multiply' THEN
            BEGIN
                v_multiplier := COALESCE((p_transform_config->>'multiplier')::DECIMAL,
                                         (p_transform_config->>'factor')::DECIMAL);
                IF v_multiplier IS NULL THEN RETURN p_value; END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM
                              TRIM(TRAILING '0' FROM ROUND(v_numeric * v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN v_result := p_value;
            END;

        WHEN 'divide' THEN
            BEGIN
                v_multiplier := COALESCE((p_transform_config->>'divisor')::DECIMAL,
                                         (p_transform_config->>'factor')::DECIMAL);
                IF v_multiplier IS NULL OR v_multiplier = 0 THEN RETURN p_value; END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM
                              TRIM(TRAILING '0' FROM ROUND(v_numeric / v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN v_result := p_value;
            END;

        WHEN 'convert_unit' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_result  := fn_convert_unit(v_numeric, p_source_unit, p_target_unit,
                                             p_supplier_id)::TEXT;
            EXCEPTION WHEN OTHERS THEN v_result := p_value;
            END;

        WHEN 'lookup' THEN
            v_result := fn_map_value(p_supplier_id,
                                     p_transform_config->>'lookup_type', p_value);

        WHEN 'custom' THEN
            BEGIN
                v_fn := p_transform_config->>'function';
                CASE v_fn
                    WHEN 'fn_parse_capacity_ml'
                        THEN v_result := fn_parse_capacity_ml(p_value)::TEXT;
                    WHEN 'fn_convert_box_dimension_to_cm'
                        THEN v_result := fn_convert_box_dimension_to_cm(p_value)::TEXT;
                    WHEN 'fn_clean_spot_name'
                        THEN v_result := fn_clean_spot_name(p_value);
                    WHEN 'fn_normalize_ncm'
                        THEN v_result := fn_normalize_ncm(p_value)::TEXT;
                    ELSE v_result := p_value;
                END CASE;
            EXCEPTION WHEN OTHERS THEN v_result := p_value;
            END;

        WHEN 'prefix' THEN
            IF p_transform_config IS NOT NULL
               AND p_transform_config->>'prefix' IS NOT NULL THEN
                v_result := (p_transform_config->>'prefix') || p_value;
            ELSE v_result := p_value;
            END IF;

        WHEN 'suffix' THEN
            IF p_transform_config IS NOT NULL
               AND p_transform_config->>'suffix' IS NOT NULL THEN
                v_result := p_value || (p_transform_config->>'suffix');
            ELSE v_result := p_value;
            END IF;

        WHEN 'uppercase'  THEN v_result := UPPER(p_value);
        WHEN 'lowercase'  THEN v_result := LOWER(p_value);
        WHEN 'trim'       THEN v_result := BTRIM(p_value);

        WHEN 'replace' THEN
            IF p_transform_config IS NOT NULL THEN
                v_result := REPLACE(p_value,
                                    COALESCE(p_transform_config->>'find', ''),
                                    COALESCE(p_transform_config->>'replace', ''));
            ELSE v_result := p_value;
            END IF;

        WHEN 'regex_extract' THEN
            BEGIN
                v_pattern := p_transform_config->>'pattern';
                v_group   := COALESCE((p_transform_config->>'group')::INTEGER, 1);
                IF v_pattern IS NULL THEN RETURN p_value; END IF;
                v_matches := regexp_matches(p_value, v_pattern);
                IF array_length(v_matches, 1) >= v_group
                    THEN v_result := v_matches[v_group];
                    ELSE v_result := NULL;
                END IF;
            EXCEPTION WHEN OTHERS THEN v_result := p_value;
            END;

        -- ── NOVO: extrai n-ésima dimensão de "AxBxC mm" e converte para cm ──────
        WHEN 'dim_to_cm' THEN
            DECLARE
                v_pos   INTEGER;
                v_unit2 TEXT;
                v_dim   TEXT[];
            BEGIN
                v_pos   := COALESCE((p_transform_config->>'position')::INTEGER, 1);
                v_unit2 := lower(COALESCE(p_transform_config->>'unit', 'cm'));
                -- Normaliza vírgulas como decimais e extrai até 3 números separados por x/X
                v_dim   := regexp_matches(
                               replace(replace(p_value, ',', '.'), ' ', ''),
                               '(\d+(?:\.\d+)?)x(\d+(?:\.\d+)?)(?:x(\d+(?:\.\d+)?))?',
                               'i');
                IF v_dim IS NOT NULL
                   AND array_length(v_dim, 1) >= v_pos
                   AND v_dim[v_pos] IS NOT NULL
                   AND v_dim[v_pos] != '0' THEN
                    v_result := CASE v_unit2
                        WHEN 'mm' THEN round(v_dim[v_pos]::numeric / 10, 2)::text
                        ELSE v_dim[v_pos]
                    END;
                ELSE v_result := NULL;
                END IF;
            EXCEPTION WHEN OTHERS THEN v_result := NULL;
            END;
        -- ────────────────────────────────────────────────────────────────────────

        ELSE v_result := p_value;

    END CASE;

    -- Truncar ao max_length se configurado
    IF v_result IS NOT NULL
       AND p_transform_config IS NOT NULL
       AND (p_transform_config->>'max_length') IS NOT NULL THEN
        v_max_length := (p_transform_config->>'max_length')::INTEGER;
        IF v_max_length > 0 AND length(v_result) > v_max_length THEN
            v_result := left(v_result, v_max_length);
        END IF;
    END IF;

    RETURN v_result;
END;
$fn$;;

-- <<< END 20260606135627_add_dim_to_cm_transform_sm_2026.sql <<<

-- >>> BEGIN 20260606135705_fix_promote_variants_always_create_vss.sql >>>
CREATE OR REPLACE FUNCTION public.fn_promote_variants_of_parent(p_supplier_id uuid, p_parent_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_pid uuid; v_org uuid; pv RECORD; v_vid uuid; v_count int := 0; v_attrs jsonb;
  v_existing_pid uuid;
BEGIN
  PERFORM set_config('app.write_source','pipeline',true);
  PERFORM set_config('app.bulk_import_mode','true',true);
  SELECT id, organization_id INTO v_pid, v_org FROM public.products
  WHERE supplier_id=p_supplier_id AND supplier_reference=p_parent_reference;
  IF v_pid IS NULL THEN RETURN jsonb_build_object('success',false,'error','produto_pai_nao_promovido','parent',p_parent_reference); END IF;

  FOR pv IN
    SELECT * FROM public.produtos_padronizacao_variantes
    WHERE supplier_id=p_supplier_id AND parent_reference=p_parent_reference AND status='standardized'
  LOOP
    v_attrs := jsonb_strip_nulls(jsonb_build_object('cor', pv.color_name, 'codigo_cor', pv.color_code, 'hex', pv.color_hex));

    SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants WHERE sku = pv.sku;
    IF v_vid IS NULL THEN
      SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants
      WHERE product_id=v_pid AND supplier_sku=pv.supplier_sku;
    END IF;

    IF v_vid IS NULL THEN
      INSERT INTO public.product_variants (product_id, sku, supplier_sku, name, attributes, color_name, color_code, color_hex, color_id, capacity_ml, selected_thumbnail, stock_quantity, is_active, last_sync_at, last_sync_supplier_id)
      VALUES (v_pid, pv.sku, pv.supplier_sku, COALESCE(pv.color_name, pv.sku), v_attrs,
              pv.color_name, pv.color_code, pv.color_hex, pv.color_id, pv.capacity_ml, pv.supplier_thumbnail,
              COALESCE(pv.stock_quantity,0), COALESCE(pv.is_active,true), now(), p_supplier_id)
      ON CONFLICT (sku) DO UPDATE SET
        supplier_sku = EXCLUDED.supplier_sku,
        attributes   = COALESCE(public.product_variants.attributes,'{}'::jsonb) || EXCLUDED.attributes,
        color_name   = COALESCE(EXCLUDED.color_name, public.product_variants.color_name),
        color_code   = COALESCE(EXCLUDED.color_code, public.product_variants.color_code),
        color_hex    = COALESCE(EXCLUDED.color_hex, public.product_variants.color_hex),
        color_id     = COALESCE(EXCLUDED.color_id, public.product_variants.color_id),
        capacity_ml  = COALESCE(EXCLUDED.capacity_ml, public.product_variants.capacity_ml),
        selected_thumbnail = COALESCE(EXCLUDED.selected_thumbnail, public.product_variants.selected_thumbnail),
        stock_quantity = COALESCE(EXCLUDED.stock_quantity, public.product_variants.stock_quantity),
        last_sync_at = now(), last_sync_supplier_id = EXCLUDED.last_sync_supplier_id
      RETURNING id INTO v_vid;
    ELSE
      UPDATE public.product_variants SET
        attributes = COALESCE(attributes,'{}'::jsonb) || v_attrs,
        color_name=COALESCE(pv.color_name,color_name), color_code=COALESCE(pv.color_code,color_code),
        color_hex=COALESCE(pv.color_hex,color_hex), color_id=COALESCE(pv.color_id,color_id),
        capacity_ml=COALESCE(pv.capacity_ml,capacity_ml), selected_thumbnail=COALESCE(pv.supplier_thumbnail,selected_thumbnail),
        stock_quantity=COALESCE(pv.stock_quantity,stock_quantity), last_sync_at=now(), last_sync_supplier_id=p_supplier_id
      WHERE id=v_vid;
    END IF;

    -- FASE 9 (2026-06-06): VSS SEMPRE criado independente de cost_price.
    -- Antes: IF pv.cost_price IS NOT NULL bloqueava criação para variantes sem custo.
    -- Agora: VSS criado com cost_price=NULL quando não disponível; stock sync preenche depois.
    INSERT INTO public.variant_supplier_sources (
      organization_id, variant_id, supplier_id, cost_price, supplier_sku, supplier_color_code, supplier_color_name,
      is_active, source, last_synced_at,
      quantity, stock_main_warehouse,
      cost_price_1, cost_price_2, cost_price_3, cost_price_4, cost_price_5,
      min_qty_1, min_qty_2, min_qty_3, min_qty_4, min_qty_5,
      next_quantity_1, next_quantity_2, next_quantity_3, next_date_1, next_date_2, next_date_3,
      sale_multiplier, supplier_images, supplier_videos, supplier_thumbnail)
    VALUES (
      v_org, v_vid, p_supplier_id, pv.cost_price, pv.supplier_sku, pv.color_code, pv.color_name,
      true, 'silver', now(),
      COALESCE(pv.stock_quantity, 0), COALESCE(pv.stock_quantity, 0),
      pv.cost_price_1, pv.cost_price_2, pv.cost_price_3, pv.cost_price_4, pv.cost_price_5,
      pv.min_qty_1, pv.min_qty_2, pv.min_qty_3, pv.min_qty_4, pv.min_qty_5,
      pv.next_quantity_1, pv.next_quantity_2, pv.next_quantity_3, pv.next_date_1, pv.next_date_2, pv.next_date_3,
      pv.sale_multiplier, pv.supplier_images, pv.supplier_videos, pv.supplier_thumbnail)
    ON CONFLICT (variant_id, supplier_id) DO UPDATE SET
      cost_price          = COALESCE(EXCLUDED.cost_price, public.variant_supplier_sources.cost_price),
      supplier_sku        = EXCLUDED.supplier_sku,
      supplier_color_code = EXCLUDED.supplier_color_code,
      supplier_color_name = EXCLUDED.supplier_color_name,
      is_active           = EXCLUDED.is_active,
      source              = EXCLUDED.source,
      last_synced_at      = EXCLUDED.last_synced_at,
      quantity             = COALESCE(EXCLUDED.quantity, public.variant_supplier_sources.quantity),
      stock_main_warehouse = COALESCE(EXCLUDED.stock_main_warehouse, public.variant_supplier_sources.stock_main_warehouse),
      cost_price_1 = COALESCE(EXCLUDED.cost_price_1, public.variant_supplier_sources.cost_price_1),
      cost_price_2 = COALESCE(EXCLUDED.cost_price_2, public.variant_supplier_sources.cost_price_2),
      cost_price_3 = COALESCE(EXCLUDED.cost_price_3, public.variant_supplier_sources.cost_price_3),
      cost_price_4 = COALESCE(EXCLUDED.cost_price_4, public.variant_supplier_sources.cost_price_4),
      cost_price_5 = COALESCE(EXCLUDED.cost_price_5, public.variant_supplier_sources.cost_price_5),
      min_qty_1 = COALESCE(EXCLUDED.min_qty_1, public.variant_supplier_sources.min_qty_1),
      min_qty_2 = COALESCE(EXCLUDED.min_qty_2, public.variant_supplier_sources.min_qty_2),
      min_qty_3 = COALESCE(EXCLUDED.min_qty_3, public.variant_supplier_sources.min_qty_3),
      min_qty_4 = COALESCE(EXCLUDED.min_qty_4, public.variant_supplier_sources.min_qty_4),
      min_qty_5 = COALESCE(EXCLUDED.min_qty_5, public.variant_supplier_sources.min_qty_5),
      next_quantity_1 = COALESCE(EXCLUDED.next_quantity_1, public.variant_supplier_sources.next_quantity_1),
      next_quantity_2 = COALESCE(EXCLUDED.next_quantity_2, public.variant_supplier_sources.next_quantity_2),
      next_quantity_3 = COALESCE(EXCLUDED.next_quantity_3, public.variant_supplier_sources.next_quantity_3),
      next_date_1 = COALESCE(EXCLUDED.next_date_1, public.variant_supplier_sources.next_date_1),
      next_date_2 = COALESCE(EXCLUDED.next_date_2, public.variant_supplier_sources.next_date_2),
      next_date_3 = COALESCE(EXCLUDED.next_date_3, public.variant_supplier_sources.next_date_3),
      sale_multiplier    = COALESCE(EXCLUDED.sale_multiplier, public.variant_supplier_sources.sale_multiplier),
      supplier_images    = COALESCE(EXCLUDED.supplier_images, public.variant_supplier_sources.supplier_images),
      supplier_videos    = COALESCE(EXCLUDED.supplier_videos, public.variant_supplier_sources.supplier_videos),
      supplier_thumbnail = COALESCE(EXCLUDED.supplier_thumbnail, public.variant_supplier_sources.supplier_thumbnail);

    UPDATE public.produtos_padronizacao_variantes SET status='promoted', variant_id=v_vid, updated_at=now() WHERE id=pv.id;

    IF pv.raw_id IS NOT NULL THEN
      UPDATE public.supplier_products_raw
         SET status='processed', processed_at=now(), product_id=v_pid, variant_id=v_vid
       WHERE id=pv.raw_id AND status <> 'processed';
    END IF;

    v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('success',true,'product_id',v_pid,'variantes_promovidas',v_count);
END;
$function$;;

-- <<< END 20260606135705_fix_promote_variants_always_create_vss.sql <<<

-- >>> BEGIN 20260606135928_fix_promote_padronizacao_backfill_sku.sql >>>
CREATE OR REPLACE FUNCTION public.fn_promote_padronizacao(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  s         public.produtos_padronizacao%ROWTYPE;
  v_pid     uuid;
  v_org     uuid;
  v_locked  text[];
  v_is_new  boolean := false;
BEGIN
  SELECT * INTO s FROM public.produtos_padronizacao WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'padronizacao_nao_encontrada', 'id', p_id);
  END IF;
  IF s.status <> 'standardized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'status_invalido', 'status', s.status);
  END IF;

  PERFORM set_config('app.write_source', 'pipeline', true);
  PERFORM set_config('app.bulk_import_mode', 'true', true);

  SELECT id, locked_fields INTO v_pid, v_locked
  FROM public.products
  WHERE supplier_id = s.supplier_id AND supplier_reference = s.supplier_reference;

  IF v_pid IS NULL THEN
    v_is_new := true;
    SELECT organization_id INTO v_org FROM public.suppliers WHERE id = s.supplier_id;
    INSERT INTO public.products (organization_id, supplier_id, supplier_reference, sku, name, active, is_active, product_type)
    VALUES (v_org, s.supplier_id, s.supplier_reference,
            COALESCE(s.supplier_reference, s.name), COALESCE(s.name,'Produto '||s.supplier_reference),
            COALESCE(s.is_active, true), COALESCE(s.is_active, true), 'product')
    RETURNING id, locked_fields INTO v_pid, v_locked;
  END IF;

  v_locked := COALESCE(v_locked, '{}');

  UPDATE public.products p SET
    -- FASE 9 (2026-06-06): sku sempre sincronizado — preenche null sem sobrescrever valor existente
    sku                = COALESCE(p.sku, s.supplier_reference, s.name),
    name               = CASE WHEN 'name'               = ANY(v_locked) THEN p.name               ELSE COALESCE(s.name, p.name) END,
    description        = CASE WHEN 'description'        = ANY(v_locked) THEN p.description        ELSE COALESCE(s.description, p.description) END,
    short_description  = CASE WHEN 'short_description'  = ANY(v_locked) THEN p.short_description  ELSE COALESCE(s.short_description, p.short_description) END,
    cost_price         = CASE WHEN 'cost_price'         = ANY(v_locked) THEN p.cost_price         ELSE COALESCE(s.cost_price, p.cost_price) END,
    suggested_price    = CASE WHEN 'suggested_price'    = ANY(v_locked) THEN p.suggested_price    ELSE COALESCE(s.suggested_price, p.suggested_price) END,
    stock_quantity     = CASE WHEN 'stock_quantity'     = ANY(v_locked) THEN p.stock_quantity     ELSE COALESCE(s.stock_quantity, p.stock_quantity) END,
    primary_image_url  = CASE WHEN 'primary_image_url'  = ANY(v_locked) THEN p.primary_image_url  ELSE COALESCE(s.primary_image_url, p.primary_image_url) END,
    images             = CASE WHEN 'images'             = ANY(v_locked) THEN p.images             ELSE COALESCE(s.images, p.images) END,
    ncm_code           = CASE WHEN 'ncm_code'           = ANY(v_locked) THEN p.ncm_code           ELSE COALESCE(s.ncm_code, p.ncm_code) END,
    weight_g           = CASE WHEN 'weight_g'           = ANY(v_locked) THEN p.weight_g           ELSE COALESCE(s.weight_g, p.weight_g) END,
    height_cm          = CASE WHEN 'height_cm'          = ANY(v_locked) THEN p.height_cm          ELSE COALESCE(s.height_cm, p.height_cm) END,
    width_cm           = CASE WHEN 'width_cm'           = ANY(v_locked) THEN p.width_cm           ELSE COALESCE(s.width_cm, p.width_cm) END,
    length_cm          = CASE WHEN 'length_cm'          = ANY(v_locked) THEN p.length_cm          ELSE COALESCE(s.length_cm, p.length_cm) END,
    dimensions_display = CASE WHEN 'dimensions_display' = ANY(v_locked) THEN p.dimensions_display ELSE COALESCE(s.dimensions_display, p.dimensions_display) END,
    box_length_cm      = CASE WHEN 'box_length_cm'      = ANY(v_locked) THEN p.box_length_cm      ELSE COALESCE(s.box_length_cm, p.box_length_cm) END,
    box_width_cm       = CASE WHEN 'box_width_cm'       = ANY(v_locked) THEN p.box_width_cm       ELSE COALESCE(s.box_width_cm, p.box_width_cm) END,
    box_height_cm      = CASE WHEN 'box_height_cm'      = ANY(v_locked) THEN p.box_height_cm      ELSE COALESCE(s.box_height_cm, p.box_height_cm) END,
    box_weight_kg      = CASE WHEN 'box_weight_kg'      = ANY(v_locked) THEN p.box_weight_kg      ELSE COALESCE(s.box_weight_kg, p.box_weight_kg) END,
    box_volume_cm3     = CASE WHEN 'box_volume_cm3'     = ANY(v_locked) THEN p.box_volume_cm3     ELSE COALESCE(s.box_volume_cm3, p.box_volume_cm3) END,
    box_quantity       = CASE WHEN 'box_quantity'       = ANY(v_locked) THEN p.box_quantity       ELSE COALESCE(s.box_quantity, p.box_quantity) END,
    box_inner_quantity = CASE WHEN 'box_inner_quantity' = ANY(v_locked) THEN p.box_inner_quantity ELSE COALESCE(s.box_inner_quantity, p.box_inner_quantity) END,
    brand              = CASE WHEN 'brand'              = ANY(v_locked) THEN p.brand              ELSE COALESCE(s.brand, p.brand) END,
    packing_type       = CASE WHEN 'packing_type'       = ANY(v_locked) THEN p.packing_type       ELSE COALESCE(s.packing_type, p.packing_type) END,
    repacking_type     = CASE WHEN 'repacking_type'     = ANY(v_locked) THEN p.repacking_type     ELSE COALESCE(s.repacking_type, p.repacking_type) END,
    capacities         = CASE WHEN 'capacities'         = ANY(v_locked) THEN p.capacities         ELSE COALESCE(s.capacities, p.capacities) END,
    capacity_ml        = CASE WHEN 'capacity_ml'        = ANY(v_locked) THEN p.capacity_ml        ELSE COALESCE(s.capacity_ml, p.capacity_ml) END,
    min_quantity       = CASE WHEN 'min_quantity'       = ANY(v_locked) THEN p.min_quantity       ELSE COALESCE(s.min_quantity, p.min_quantity) END,
    warranty_months    = CASE WHEN 'warranty_months'    = ANY(v_locked) THEN p.warranty_months    ELSE COALESCE(s.warranty_months, p.warranty_months) END,
    ipi_rate           = CASE WHEN 'ipi_rate'           = ANY(v_locked) THEN p.ipi_rate           ELSE COALESCE(s.ipi_rate, p.ipi_rate) END,
    engraving_type     = CASE WHEN 'engraving_type'     = ANY(v_locked) THEN p.engraving_type     ELSE COALESCE(s.engraving_type, p.engraving_type) END,
    colors             = CASE WHEN 'colors'             = ANY(v_locked) THEN p.colors             ELSE COALESCE(s.colors, p.colors) END,
    origin_country         = CASE WHEN 'origin_country'         = ANY(v_locked) THEN p.origin_country         ELSE COALESCE(s.origin_country, p.origin_country) END,
    combined_sizes         = CASE WHEN 'combined_sizes'         = ANY(v_locked) THEN p.combined_sizes         ELSE COALESCE(s.combined_sizes, p.combined_sizes) END,
    box_image              = CASE WHEN 'box_image'              = ANY(v_locked) THEN p.box_image              ELSE COALESCE(s.box_image, p.box_image) END,
    is_textil              = CASE WHEN 'is_textil'              = ANY(v_locked) THEN p.is_textil              ELSE COALESCE(s.is_textil, p.is_textil) END,
    is_stockout            = CASE WHEN 'is_stockout'            = ANY(v_locked) THEN p.is_stockout            ELSE COALESCE(s.is_stockout, p.is_stockout) END,
    is_online_exclusive    = CASE WHEN 'is_online_exclusive'    = ANY(v_locked) THEN p.is_online_exclusive    ELSE COALESCE(s.is_online_exclusive, p.is_online_exclusive) END,
    is_new                 = CASE WHEN 'is_new'                 = ANY(v_locked) THEN p.is_new                 ELSE COALESCE(s.is_new, p.is_new) END,
    has_colors             = CASE WHEN 'has_colors'             = ANY(v_locked) THEN p.has_colors             ELSE COALESCE(s.has_colors, p.has_colors) END,
    has_sizes              = CASE WHEN 'has_sizes'              = ANY(v_locked) THEN p.has_sizes              ELSE COALESCE(s.has_sizes, p.has_sizes) END,
    allows_personalization = CASE WHEN 'allows_personalization' = ANY(v_locked) THEN p.allows_personalization ELSE COALESCE(s.allows_personalization, p.allows_personalization) END,
    tags                   = CASE WHEN 'tags'                   = ANY(v_locked) THEN p.tags                   ELSE COALESCE(s.tags, p.tags) END,
    materials              = CASE WHEN 'materials'              = ANY(v_locked) THEN p.materials              ELSE COALESCE(s.materials, p.materials) END,
    meta_keywords          = CASE WHEN 'meta_keywords'          = ANY(v_locked) THEN p.meta_keywords          ELSE COALESCE(s.meta_keywords, p.meta_keywords) END,
    last_sync_at          = now(),
    last_sync_supplier_id = s.supplier_id,
    supplier_updated_at   = now()
  WHERE p.id = v_pid;

  UPDATE public.produtos_padronizacao
     SET status='promoted', promoted_at=now(), product_id=v_pid
   WHERE id = p_id;

  IF s.raw_id IS NOT NULL THEN
    UPDATE public.supplier_products_raw
       SET status='processed', processed_at=now(), product_id=v_pid, process_errors=NULL
     WHERE id = s.raw_id;
    PERFORM public.fn_sync_single_product_dimensions(
              v_pid, (SELECT raw_data FROM public.supplier_products_raw WHERE id = s.raw_id));
  END IF;

  RETURN jsonb_build_object('success', true, 'product_id', v_pid, 'created', v_is_new,
                            'locked_preserved', v_locked);
END;
$function$;;

-- <<< END 20260606135928_fix_promote_padronizacao_backfill_sku.sql <<<

-- >>> BEGIN 20260606140351_fix_fn_sm_to_silver_v1_redirect_2026.sql >>>
-- Substitui a implementação v2 (que inseria em silver_products/silver_variants dropadas)
-- pelo redirecionamento ao pipeline v1 (fn_standardize_raw + fn_standardize_variant + promote).
-- Remove fn_clean_spot_name (SPOT-specific) e classify_xbz_category (fallback XBZ inapropriado).
CREATE OR REPLACE FUNCTION public.fn_sm_to_silver(p_bronze_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE
  v_spr         public.supplier_products_raw%ROWTYPE;
  v_result_std  jsonb;
  v_result_var  jsonb;
  v_pad_id      uuid;
  v_parent_ref  text;
BEGIN
  -- ── 1. Carregar bronze ────────────────────────────────────────────────────
  SELECT * INTO v_spr FROM public.supplier_products_raw WHERE id = p_bronze_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error',   'bronze_nao_encontrado',
      'id',      p_bronze_id
    );
  END IF;

  -- ── 2. v1 — padronizar produto (usa supplier_field_mappings SM) ───────────
  v_result_std := public.fn_standardize_raw(p_bronze_id);

  -- ── 3. v1 — padronizar variante (cor, estoque, faixas de preço) ──────────
  v_result_var := public.fn_standardize_variant(p_bronze_id);

  -- ── 4. Promover ao Gold se padronização OK ────────────────────────────────
  v_pad_id := (v_result_std->>'padronizacao_id')::uuid;

  IF v_pad_id IS NOT NULL
     AND COALESCE((v_result_std->>'success')::boolean, true) IS NOT FALSE
  THEN
    -- Promove produto
    PERFORM public.fn_promote_padronizacao(v_pad_id);

    -- Promove variante(s) — SM é 1:1, mas chama padrão
    v_parent_ref := public.fn_derive_parent_ref(
                      v_spr.supplier_id,
                      v_spr.supplier_reference,
                      v_spr.raw_data
                    );
    PERFORM public.fn_promote_variants_of_parent(v_spr.supplier_id, v_parent_ref);
  END IF;

  -- ── 5. Marcar bronze como processado ─────────────────────────────────────
  UPDATE public.supplier_products_raw
  SET    status       = 'processed',
         processed_at = now()
  WHERE  id = p_bronze_id;

  RETURN jsonb_build_object(
    'success',         true,
    'pipeline',        'v1',
    'bronze_id',       p_bronze_id,
    'reference',       v_spr.supplier_reference,
    'padronizacao_id', v_pad_id,
    'campos',          v_result_std->>'campos',
    'variante',        v_result_var->>'variante_id',
    'note',            'v2→v1: silver_products/silver_variants depreciados; fn_clean_spot_name e classify_xbz_category removidos'
  );

EXCEPTION WHEN OTHERS THEN
  -- Registrar erro sem crash
  UPDATE public.supplier_products_raw
  SET last_error = jsonb_build_object(
                     'fn',  'fn_sm_to_silver',
                     'msg', SQLERRM,
                     'ts',  now()
                   ),
      attempts   = COALESCE(attempts, 0) + 1
  WHERE id = p_bronze_id;

  RETURN jsonb_build_object(
    'success',   false,
    'error',     SQLERRM,
    'bronze_id', p_bronze_id
  );
END;
$fn$;;

-- <<< END 20260606140351_fix_fn_sm_to_silver_v1_redirect_2026.sql <<<

-- >>> BEGIN 20260606140407_fix_fn_sm_batch_to_silver_status_guard_2026.sql >>>
-- Substitui o WHERE NOT EXISTS (... FROM silver_variants ...) — que crashava imediatamente —
-- por um guard simples de status no próprio supplier_products_raw.
-- Redireciona chamadas para fn_sm_to_silver corrigida (que usa pipeline v1).
CREATE OR REPLACE FUNCTION public.fn_sm_batch_to_silver(p_batch_size integer DEFAULT 500)
RETURNS TABLE(processed integer, errors integer)
LANGUAGE plpgsql
SET search_path TO 'public'
AS $fn$
DECLARE
  v_bronze_id   uuid;
  v_processed   int := 0;
  v_errors      int := 0;
  v_supplier_id uuid;
BEGIN
  -- ── 1. Resolver supplier_id do SM de forma segura ─────────────────────────
  SELECT id INTO v_supplier_id
  FROM   public.suppliers
  WHERE  code = 'SOMARCAS'
  LIMIT  1;

  IF v_supplier_id IS NULL THEN
    RAISE WARNING 'fn_sm_batch_to_silver: supplier SOMARCAS não encontrado na tabela suppliers';
    RETURN QUERY SELECT 0, 0;
    RETURN;
  END IF;

  -- ── 2. Iterar sobre bronzes pendentes (guard por status — sem tabelas depreciadas) ──
  FOR v_bronze_id IN
    SELECT spr.id
    FROM   public.supplier_products_raw spr
    WHERE  spr.supplier_id = v_supplier_id
      AND  spr.status NOT IN ('processed', 'standardized')
      AND  COALESCE(spr.attempts, 0) < 5
    ORDER BY spr.imported_at
    LIMIT  p_batch_size
  LOOP
    BEGIN
      PERFORM public.fn_sm_to_silver(v_bronze_id);
      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      RAISE WARNING 'fn_sm_batch_to_silver: erro no bronze % — %', v_bronze_id, SQLERRM;
    END;
  END LOOP;

  RETURN QUERY SELECT v_processed, v_errors;
END;
$fn$;;

-- <<< END 20260606140407_fix_fn_sm_batch_to_silver_status_guard_2026.sql <<<

-- >>> BEGIN 20260606140520_fix_fn_sm_batch_status_guard_enum_2026.sql >>>
-- Corrige o status guard para usar apenas valores válidos do enum supplier_raw_status
-- (pending, processing, processed, failed, skipped, quarantined)
-- Processa: pending (novos) e failed (retry até 5 tentativas)
CREATE OR REPLACE FUNCTION public.fn_sm_batch_to_silver(p_batch_size integer DEFAULT 500)
RETURNS TABLE(processed integer, errors integer)
LANGUAGE plpgsql
SET search_path TO 'public'
AS $fn$
DECLARE
  v_bronze_id   uuid;
  v_processed   int := 0;
  v_errors      int := 0;
  v_supplier_id uuid;
BEGIN
  -- 1. Resolver supplier_id do SM de forma segura
  SELECT id INTO v_supplier_id
  FROM   public.suppliers
  WHERE  code = 'SOMARCAS'
  LIMIT  1;

  IF v_supplier_id IS NULL THEN
    RAISE WARNING 'fn_sm_batch_to_silver: supplier SOMARCAS não encontrado';
    RETURN QUERY SELECT 0, 0;
    RETURN;
  END IF;

  -- 2. Iterar sobre bronzes pendentes ou falhos (guard por enum — sem tabelas depreciadas)
  FOR v_bronze_id IN
    SELECT spr.id
    FROM   public.supplier_products_raw spr
    WHERE  spr.supplier_id = v_supplier_id
      AND  spr.status IN (
             'pending'::public.supplier_raw_status,
             'failed'::public.supplier_raw_status
           )
      AND  COALESCE(spr.attempts, 0) < 5
    ORDER BY spr.imported_at
    LIMIT  p_batch_size
  LOOP
    BEGIN
      PERFORM public.fn_sm_to_silver(v_bronze_id);
      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      RAISE WARNING 'fn_sm_batch_to_silver: erro bronze % — %', v_bronze_id, SQLERRM;
    END;
  END LOOP;

  RETURN QUERY SELECT v_processed, v_errors;
END;
$fn$;;

-- <<< END 20260606140520_fix_fn_sm_batch_status_guard_enum_2026.sql <<<

-- >>> BEGIN 20260606141141_fix_dim_to_cm_omega_symbol_support_2026.sql >>>
-- Corrige dim_to_cm para suportar formato "xØN" (símbolo de diâmetro)
-- Formatos SM afetados: "9,3xØ6,2 cm", "25,5xØ8,0 cm", "Garrafa: 21,4x7,2xØ7,2 cm"
CREATE OR REPLACE FUNCTION public.fn_apply_transform(
    p_value        text,
    p_transform_type character varying,
    p_transform_config jsonb,
    p_source_unit  character varying,
    p_target_unit  character varying,
    p_supplier_id  uuid
)
RETURNS text
LANGUAGE plpgsql STABLE
SET search_path TO 'public'
AS $fn$
DECLARE
    v_result     TEXT;
    v_numeric    DECIMAL;
    v_multiplier DECIMAL;
    v_fn         VARCHAR;
    v_pattern    TEXT;
    v_group      INTEGER;
    v_matches    TEXT[];
    v_max_length INTEGER;
BEGIN
    IF p_value IS NULL OR TRIM(p_value) = '' THEN RETURN NULL; END IF;

    CASE p_transform_type

        WHEN 'direct' THEN
            v_result := p_value;

        WHEN 'multiply' THEN
            BEGIN
                v_multiplier := COALESCE((p_transform_config->>'multiplier')::DECIMAL,
                                         (p_transform_config->>'factor')::DECIMAL);
                IF v_multiplier IS NULL THEN RETURN p_value; END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM
                              TRIM(TRAILING '0' FROM ROUND(v_numeric * v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN v_result := p_value;
            END;

        WHEN 'divide' THEN
            BEGIN
                v_multiplier := COALESCE((p_transform_config->>'divisor')::DECIMAL,
                                         (p_transform_config->>'factor')::DECIMAL);
                IF v_multiplier IS NULL OR v_multiplier = 0 THEN RETURN p_value; END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM
                              TRIM(TRAILING '0' FROM ROUND(v_numeric / v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN v_result := p_value;
            END;

        WHEN 'convert_unit' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_result  := fn_convert_unit(v_numeric, p_source_unit, p_target_unit,
                                             p_supplier_id)::TEXT;
            EXCEPTION WHEN OTHERS THEN v_result := p_value;
            END;

        WHEN 'lookup' THEN
            v_result := fn_map_value(p_supplier_id,
                                     p_transform_config->>'lookup_type', p_value);

        WHEN 'custom' THEN
            BEGIN
                v_fn := p_transform_config->>'function';
                CASE v_fn
                    WHEN 'fn_parse_capacity_ml'
                        THEN v_result := fn_parse_capacity_ml(p_value)::TEXT;
                    WHEN 'fn_convert_box_dimension_to_cm'
                        THEN v_result := fn_convert_box_dimension_to_cm(p_value)::TEXT;
                    WHEN 'fn_clean_spot_name'
                        THEN v_result := fn_clean_spot_name(p_value);
                    WHEN 'fn_normalize_ncm'
                        THEN v_result := fn_normalize_ncm(p_value)::TEXT;
                    ELSE v_result := p_value;
                END CASE;
            EXCEPTION WHEN OTHERS THEN v_result := p_value;
            END;

        WHEN 'prefix' THEN
            IF p_transform_config IS NOT NULL
               AND p_transform_config->>'prefix' IS NOT NULL THEN
                v_result := (p_transform_config->>'prefix') || p_value;
            ELSE v_result := p_value;
            END IF;

        WHEN 'suffix' THEN
            IF p_transform_config IS NOT NULL
               AND p_transform_config->>'suffix' IS NOT NULL THEN
                v_result := p_value || (p_transform_config->>'suffix');
            ELSE v_result := p_value;
            END IF;

        WHEN 'uppercase'  THEN v_result := UPPER(p_value);
        WHEN 'lowercase'  THEN v_result := LOWER(p_value);
        WHEN 'trim'       THEN v_result := BTRIM(p_value);

        WHEN 'replace' THEN
            IF p_transform_config IS NOT NULL THEN
                v_result := REPLACE(p_value,
                                    COALESCE(p_transform_config->>'find', ''),
                                    COALESCE(p_transform_config->>'replace', ''));
            ELSE v_result := p_value;
            END IF;

        WHEN 'regex_extract' THEN
            BEGIN
                v_pattern := p_transform_config->>'pattern';
                v_group   := COALESCE((p_transform_config->>'group')::INTEGER, 1);
                IF v_pattern IS NULL THEN RETURN p_value; END IF;
                v_matches := regexp_matches(p_value, v_pattern);
                IF array_length(v_matches, 1) >= v_group
                    THEN v_result := v_matches[v_group];
                    ELSE v_result := NULL;
                END IF;
            EXCEPTION WHEN OTHERS THEN v_result := p_value;
            END;

        -- ── dim_to_cm: extrai n-ésima dimensão e converte para cm ─────────────────
        -- Suporta formatos SM:
        --   "280x71x69 mm (AxLxP)"   → mm→cm com divisão por 10
        --   "24,5x7cm"               → já em cm
        --   "9,3xØ6,2 cm"            → suporta símbolo Ø (diâmetro) antes do número
        --   "Garrafa: 21,4x7,2xØ7,2" → suporta texto prefix e Ø
        -- Retorna NULL para zeros (0x0x0) e textos sem dimensão válida
        WHEN 'dim_to_cm' THEN
            DECLARE
                v_pos    INTEGER;
                v_unit2  TEXT;
                v_dim    TEXT[];
                v_clean  TEXT;
            BEGIN
                v_pos   := COALESCE((p_transform_config->>'position')::INTEGER, 1);
                v_unit2 := lower(COALESCE(p_transform_config->>'unit', 'cm'));
                -- Normaliza: vírgulas→pontos, remove espaços; Ø∅ entre x e dígito → apenas dígito
                v_clean := replace(replace(p_value, ',', '.'), ' ', '');
                -- Regex: aceita N[xX][Ø∅]?N[xX][Ø∅]?N (suporta símbolo diâmetro)
                v_dim   := regexp_matches(
                               v_clean,
                               '(\d+(?:\.\d+)?)[xX][Ø∅Oo]?(\d+(?:\.\d+)?)(?:[xX][Ø∅Oo]?(\d+(?:\.\d+)?))?',
                               'i');
                IF v_dim IS NOT NULL
                   AND array_length(v_dim, 1) >= v_pos
                   AND v_dim[v_pos] IS NOT NULL
                   AND v_dim[v_pos] != '0' THEN
                    v_result := CASE v_unit2
                        WHEN 'mm' THEN round(v_dim[v_pos]::numeric / 10, 2)::text
                        ELSE v_dim[v_pos]
                    END;
                ELSE v_result := NULL;
                END IF;
            EXCEPTION WHEN OTHERS THEN v_result := NULL;
            END;
        -- ────────────────────────────────────────────────────────────────────────────

        ELSE v_result := p_value;

    END CASE;

    -- Truncar ao max_length se configurado
    IF v_result IS NOT NULL
       AND p_transform_config IS NOT NULL
       AND (p_transform_config->>'max_length') IS NOT NULL THEN
        v_max_length := (p_transform_config->>'max_length')::INTEGER;
        IF v_max_length > 0 AND length(v_result) > v_max_length THEN
            v_result := left(v_result, v_max_length);
        END IF;
    END IF;

    RETURN v_result;
END;
$fn$;;

-- <<< END 20260606141141_fix_dim_to_cm_omega_symbol_support_2026.sql <<<

