-- >>> BEGIN 20260606141838_fn_apply_transform_v2_extended.sql >>>

CREATE OR REPLACE FUNCTION public.fn_apply_transform(
    p_value text,
    p_transform_type character varying,
    p_transform_config jsonb,
    p_source_unit character varying,
    p_target_unit character varying,
    p_supplier_id uuid
)
RETURNS text
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $function$
DECLARE
    v_result     TEXT;
    v_numeric    DECIMAL;
    v_multiplier DECIMAL;
    v_fn         VARCHAR;
    v_op         VARCHAR;
    v_pattern    TEXT;
    v_group      INTEGER;
    v_matches    TEXT[];
    v_max_length INTEGER;
BEGIN
    IF p_value IS NULL OR TRIM(p_value) = '' THEN RETURN NULL; END IF;

    CASE p_transform_type

        WHEN 'direct' THEN
            v_result := p_value;

        WHEN 'multiply' THEN
            BEGIN
                v_multiplier := COALESCE((p_transform_config->>'multiplier')::DECIMAL,(p_transform_config->>'factor')::DECIMAL);
                IF v_multiplier IS NULL THEN RETURN p_value; END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM ROUND(v_numeric * v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'divide' THEN
            BEGIN
                v_multiplier := COALESCE((p_transform_config->>'divisor')::DECIMAL,(p_transform_config->>'factor')::DECIMAL);
                IF v_multiplier IS NULL OR v_multiplier = 0 THEN RETURN p_value; END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM ROUND(v_numeric / v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'convert_unit' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_result := fn_convert_unit(v_numeric, p_source_unit, p_target_unit, p_supplier_id)::TEXT;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'lookup' THEN
            v_result := fn_map_value(p_supplier_id, p_transform_config->>'lookup_type', p_value);

        WHEN 'custom' THEN
            BEGIN
                v_fn := p_transform_config->>'function';
                v_op := p_transform_config->>'op';
                CASE
                    WHEN v_fn = 'fn_parse_capacity_ml'           THEN v_result := fn_parse_capacity_ml(p_value)::TEXT;
                    WHEN v_fn = 'fn_convert_box_dimension_to_cm' THEN v_result := fn_convert_box_dimension_to_cm(p_value)::TEXT;
                    WHEN v_fn = 'fn_clean_spot_name'             THEN v_result := fn_clean_spot_name(p_value);
                    WHEN v_fn = 'fn_normalize_ncm'               THEN v_result := fn_normalize_ncm(p_value)::TEXT;
                    WHEN v_fn = 'fn_spot_split_list'             THEN v_result := fn_spot_split_list(p_value)::TEXT;
                    WHEN v_fn = 'fn_spot_image_list'             THEN v_result := fn_spot_image_list(
                                                                          p_value,
                                                                          COALESCE(p_transform_config->>'base',
                                                                                   'https://www.spotgifts.com.br/fotos/produtos/')
                                                                        )::TEXT;
                    WHEN v_op = 'array_url'  THEN v_result := jsonb_build_array(p_value)::TEXT;
                    WHEN v_op = 'is_present' THEN v_result := CASE WHEN NULLIF(TRIM(p_value),'') IS NOT NULL
                                                                    THEN 'true' ELSE 'false' END;
                    ELSE v_result := p_value;
                END CASE;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        -- Tipos de cast explícito (antes caíam no ELSE → retornavam p_value bruto)
        WHEN 'cast_integer' THEN
            v_result := fn_safe_int(p_value)::TEXT;

        WHEN 'cast_decimal' THEN
            v_result := fn_safe_num(p_value)::TEXT;

        WHEN 'cast_datetime' THEN
            BEGIN
                v_result := CASE WHEN p_value ~ '^\d{4}-\d{2}-\d{2}'
                                 THEN LEFT(p_value, 10)
                                 ELSE NULL END;
            EXCEPTION WHEN OTHERS THEN v_result := NULL; END;

        WHEN 'cast_boolean' THEN
            v_result := fn_safe_bool(p_value)::TEXT;

        WHEN 'cast' THEN
            BEGIN
                v_result := CASE COALESCE(p_transform_config->>'to', 'text')
                    WHEN 'boolean' THEN fn_safe_bool(p_value)::TEXT
                    WHEN 'integer' THEN fn_safe_int(p_value)::TEXT
                    WHEN 'decimal' THEN fn_safe_num(p_value)::TEXT
                    ELSE p_value
                END;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        -- Split de arrays (antes fn_standardize_raw tratava inline; agora delega aqui também)
        WHEN 'split_pipe' THEN
            v_result := (
                SELECT to_jsonb(
                    COALESCE(
                        array_agg(BTRIM(e)) FILTER (WHERE BTRIM(e) <> ''),
                        ARRAY[]::text[]
                    )
                )::TEXT
                FROM unnest(string_to_array(p_value,
                     COALESCE(p_transform_config->>'delimiter', ','))) AS e
            );

        WHEN 'prefix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'prefix' IS NOT NULL THEN
                v_result := (p_transform_config->>'prefix') || p_value;
            ELSE v_result := p_value; END IF;

        WHEN 'suffix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'suffix' IS NOT NULL THEN
                v_result := p_value || (p_transform_config->>'suffix');
            ELSE v_result := p_value; END IF;

        WHEN 'uppercase' THEN v_result := UPPER(p_value);
        WHEN 'lowercase' THEN v_result := LOWER(p_value);
        WHEN 'trim'      THEN v_result := BTRIM(p_value);

        WHEN 'replace' THEN
            IF p_transform_config IS NOT NULL THEN
                v_result := REPLACE(p_value,
                    COALESCE(p_transform_config->>'find',''),
                    COALESCE(p_transform_config->>'replace',''));
            ELSE v_result := p_value; END IF;

        WHEN 'regex_extract' THEN
            BEGIN
                v_pattern := p_transform_config->>'pattern';
                v_group   := COALESCE((p_transform_config->>'group')::INTEGER, 1);
                IF v_pattern IS NULL THEN RETURN p_value; END IF;
                v_matches := regexp_matches(p_value, v_pattern);
                IF array_length(v_matches, 1) >= v_group THEN v_result := v_matches[v_group];
                ELSE v_result := NULL; END IF;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        ELSE v_result := p_value;
    END CASE;

    -- Truncar ao max_length configurado
    IF v_result IS NOT NULL AND p_transform_config IS NOT NULL
       AND (p_transform_config->>'max_length') IS NOT NULL THEN
        v_max_length := (p_transform_config->>'max_length')::INTEGER;
        IF v_max_length > 0 AND length(v_result) > v_max_length THEN
            v_result := LEFT(v_result, v_max_length);
        END IF;
    END IF;

    RETURN v_result;
END;
$function$;

COMMENT ON FUNCTION public.fn_apply_transform(text, character varying, jsonb, character varying, character varying, uuid) IS
'Motor de transformações do DE>PARA (supplier_field_mappings). v2 (2026-06-06):
 + custom: fn_spot_split_list, fn_spot_image_list, op=array_url, op=is_present
 + cast_integer, cast_decimal, cast_datetime, cast_boolean, cast (genérico com config.to)
 + split_pipe (jsonb array via delimiter)';
;

-- <<< END 20260606141838_fn_apply_transform_v2_extended.sql <<<

-- >>> BEGIN 20260606142001_standardize_raw_custom_array_v2.sql >>>

CREATE OR REPLACE FUNCTION public.fn_standardize_raw(p_raw_id uuid, p_override_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r          public.supplier_products_raw%ROWTYPE;
  m          RECORD;
  v_val      text; v_tx text; v_path text;
  v_assigns  jsonb := '{}'::jsonb;
  v_errs     jsonb := '[]'::jsonb;
  v_ncm text; v_ncm_raw text;
  v_pad_id uuid; v_ref text;
  v_status public.produtos_padronizacao_status;
  v_tags jsonb; v_materials jsonb; v_meta text[]; v_arr jsonb;
  v_cols text[] := ARRAY[
    'name','description','short_description','cost_price','suggested_price','stock_quantity',
    'primary_image_url','images','ncm_code','weight_g','height_cm','width_cm','length_cm',
    'dimensions_display','box_length_cm','box_width_cm','box_height_cm','box_weight_kg',
    'box_volume_cm3','box_quantity','box_inner_quantity','brand','packing_type','repacking_type',
    'capacities','capacity_ml','min_quantity','warranty_months','ipi_rate','engraving_type','is_active',
    -- Opção B (campos ricos):
    'product_type','origin_country','combined_sizes','box_image',
    'is_textil','is_stockout','is_online_exclusive','is_new','has_colors','has_sizes','allows_personalization',
    'tags','materials','meta_keywords'];
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'raw_nao_encontrado'); END IF;
  v_ref := COALESCE(NULLIF(TRIM(p_override_reference),''), r.supplier_reference);

  FOR m IN
    SELECT source_field, source_path, target_field, transform_type, transform_config, source_unit, target_unit
    FROM public.supplier_field_mappings
    WHERE supplier_id=r.supplier_id AND target_table='products' AND is_active=TRUE AND target_field=ANY(v_cols)
    ORDER BY priority NULLS LAST
  LOOP
    v_path := NULLIF(regexp_replace(COALESCE(NULLIF(m.source_path,''), m.source_field, ''), '^\$\.?', ''), '');
    IF v_path IS NULL THEN v_val := NULL;
    ELSIF position('.' IN v_path) > 0 THEN v_val := r.raw_data #>> string_to_array(v_path, '.');
    ELSE v_val := r.raw_data ->> v_path; END IF;
    CONTINUE WHEN v_val IS NULL OR TRIM(v_val)='';

    -- ─── Campos de array/jsonb ───────────────────────────────────────────────
    -- v2 (2026-06-06): detecta transform_type='custom' e delega para fn_apply_transform,
    -- permitindo que fn_spot_split_list (e outros) sejam usados via DE>PARA.
    IF m.target_field IN ('tags','materials') THEN
      IF m.transform_type = 'custom' AND (m.transform_config->>'function') IS NOT NULL THEN
        BEGIN
          v_tx  := public.fn_apply_transform(v_val, m.transform_type, m.transform_config,
                                             m.source_unit, m.target_unit, r.supplier_id);
          v_arr := CASE WHEN v_tx IS NOT NULL THEN v_tx::jsonb ELSE '[]'::jsonb END;
        EXCEPTION WHEN OTHERS THEN
          v_arr := '[]'::jsonb;
          v_errs := v_errs || jsonb_build_object('field',m.target_field,'stage','custom_array','msg',SQLERRM);
        END;
      ELSE
        -- Fallback: split por delimiter da config (default ',')
        v_arr := (SELECT to_jsonb(COALESCE(array_agg(btrim(e)) FILTER (WHERE btrim(e) <> ''), ARRAY[]::text[]))
                  FROM unnest(string_to_array(v_val, COALESCE(m.transform_config->>'delimiter', ','))) e);
      END IF;
      IF m.target_field='tags' THEN v_tags := v_arr; ELSE v_materials := v_arr; END IF;
      CONTINUE;
    ELSIF m.target_field='meta_keywords' THEN
      v_meta := (SELECT COALESCE(array_agg(btrim(e)) FILTER (WHERE btrim(e) <> ''), ARRAY[]::text[])
                 FROM unnest(string_to_array(v_val, COALESCE(m.transform_config->>'delimiter', ','))) e);
      CONTINUE;
    END IF;
    -- ────────────────────────────────────────────────────────────────────────

    BEGIN
      v_tx := public.fn_apply_transform(v_val, m.transform_type, m.transform_config, m.source_unit, m.target_unit, r.supplier_id);
    EXCEPTION WHEN OTHERS THEN v_tx := v_val;
      v_errs := v_errs || jsonb_build_object('field',m.target_field,'stage','transform','msg',SQLERRM);
    END;
    IF v_tx IS NOT NULL THEN v_assigns := v_assigns || jsonb_build_object(m.target_field, v_tx); END IF;
  END LOOP;

  -- NCM: inclui Taric (Spot usa código aduaneiro Taric em vez de Ncm)
  v_ncm_raw := COALESCE(v_assigns->>'ncm_code', r.raw_data->>'ncm', r.raw_data->>'Ncm', r.raw_data->>'Taric');
  v_ncm := public.fn_normalize_ncm(v_ncm_raw);
  IF v_ncm IS NOT NULL THEN v_assigns := v_assigns || jsonb_build_object('ncm_code', v_ncm);
  ELSIF v_ncm_raw IS NOT NULL THEN
    v_errs := v_errs || jsonb_build_object('field','ncm_code','stage','validate','msg','ncm_invalido','raw',v_ncm_raw);
    v_assigns := v_assigns - 'ncm_code';
  END IF;

  v_status := (CASE WHEN jsonb_array_length(v_errs)>0 AND v_assigns->>'name' IS NULL THEN 'rejected' ELSE 'standardized' END)::public.produtos_padronizacao_status;

  INSERT INTO public.produtos_padronizacao AS pad (
    raw_id, supplier_id, supplier_reference,
    name, description, short_description, cost_price, suggested_price, stock_quantity,
    primary_image_url, images, ncm_code, weight_g, height_cm, width_cm, length_cm,
    dimensions_display, box_length_cm, box_width_cm, box_height_cm, box_weight_kg,
    box_volume_cm3, box_quantity, box_inner_quantity, brand, packing_type, repacking_type,
    capacities, capacity_ml, min_quantity, warranty_months, ipi_rate, engraving_type, is_active,
    product_type, origin_country, combined_sizes, box_image,
    is_textil, is_stockout, is_online_exclusive, is_new, has_colors, has_sizes, allows_personalization,
    tags, materials, meta_keywords,
    status, validation_errors, standardized_at
  ) VALUES (
    r.id, r.supplier_id, v_ref,
    v_assigns->>'name', v_assigns->>'description', v_assigns->>'short_description',
    public.fn_safe_num(v_assigns->>'cost_price'), public.fn_safe_num(v_assigns->>'suggested_price'), public.fn_safe_int(v_assigns->>'stock_quantity'),
    v_assigns->>'primary_image_url',
    CASE WHEN v_assigns ? 'images' THEN (v_assigns->'images') ELSE NULL END,
    v_assigns->>'ncm_code', public.fn_safe_int(v_assigns->>'weight_g'),
    public.fn_safe_num(v_assigns->>'height_cm'), public.fn_safe_num(v_assigns->>'width_cm'), public.fn_safe_num(v_assigns->>'length_cm'),
    v_assigns->>'dimensions_display',
    public.fn_safe_num(v_assigns->>'box_length_cm'), public.fn_safe_num(v_assigns->>'box_width_cm'), public.fn_safe_num(v_assigns->>'box_height_cm'),
    public.fn_safe_num(v_assigns->>'box_weight_kg'), public.fn_safe_num(v_assigns->>'box_volume_cm3'),
    public.fn_safe_int(v_assigns->>'box_quantity'), public.fn_safe_int(v_assigns->>'box_inner_quantity'),
    v_assigns->>'brand', v_assigns->>'packing_type', v_assigns->>'repacking_type',
    v_assigns->>'capacities', public.fn_safe_int(v_assigns->>'capacity_ml'), public.fn_safe_int(v_assigns->>'min_quantity'),
    public.fn_safe_int(v_assigns->>'warranty_months'), public.fn_safe_num(v_assigns->>'ipi_rate'), v_assigns->>'engraving_type',
    COALESCE(public.fn_safe_bool(v_assigns->>'is_active'), true),
    v_assigns->>'product_type', v_assigns->>'origin_country', v_assigns->>'combined_sizes', v_assigns->>'box_image',
    public.fn_safe_bool(v_assigns->>'is_textil'), public.fn_safe_bool(v_assigns->>'is_stockout'),
    public.fn_safe_bool(v_assigns->>'is_online_exclusive'), public.fn_safe_bool(v_assigns->>'is_new'),
    public.fn_safe_bool(v_assigns->>'has_colors'), public.fn_safe_bool(v_assigns->>'has_sizes'),
    (v_assigns ? 'allows_personalization'),
    v_tags, v_materials, v_meta,
    v_status, CASE WHEN jsonb_array_length(v_errs)>0 THEN v_errs ELSE NULL END, now()
  )
  ON CONFLICT (supplier_id, supplier_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, name=EXCLUDED.name, description=EXCLUDED.description,
    short_description=EXCLUDED.short_description, cost_price=EXCLUDED.cost_price,
    suggested_price=EXCLUDED.suggested_price, stock_quantity=EXCLUDED.stock_quantity,
    primary_image_url=EXCLUDED.primary_image_url, images=EXCLUDED.images, ncm_code=EXCLUDED.ncm_code,
    weight_g=EXCLUDED.weight_g, height_cm=EXCLUDED.height_cm, width_cm=EXCLUDED.width_cm, length_cm=EXCLUDED.length_cm,
    dimensions_display=EXCLUDED.dimensions_display, box_length_cm=EXCLUDED.box_length_cm, box_width_cm=EXCLUDED.box_width_cm,
    box_height_cm=EXCLUDED.box_height_cm, box_weight_kg=EXCLUDED.box_weight_kg, box_volume_cm3=EXCLUDED.box_volume_cm3,
    box_quantity=EXCLUDED.box_quantity, box_inner_quantity=EXCLUDED.box_inner_quantity, brand=EXCLUDED.brand,
    packing_type=EXCLUDED.packing_type, repacking_type=EXCLUDED.repacking_type, capacities=EXCLUDED.capacities,
    capacity_ml=EXCLUDED.capacity_ml, min_quantity=EXCLUDED.min_quantity, warranty_months=EXCLUDED.warranty_months,
    ipi_rate=EXCLUDED.ipi_rate, engraving_type=EXCLUDED.engraving_type, is_active=EXCLUDED.is_active,
    product_type=EXCLUDED.product_type, origin_country=EXCLUDED.origin_country, combined_sizes=EXCLUDED.combined_sizes,
    box_image=EXCLUDED.box_image, is_textil=EXCLUDED.is_textil, is_stockout=EXCLUDED.is_stockout,
    is_online_exclusive=EXCLUDED.is_online_exclusive, is_new=EXCLUDED.is_new, has_colors=EXCLUDED.has_colors,
    has_sizes=EXCLUDED.has_sizes, allows_personalization=EXCLUDED.allows_personalization,
    tags=COALESCE(EXCLUDED.tags, pad.tags), materials=COALESCE(EXCLUDED.materials, pad.materials),
    meta_keywords=COALESCE(EXCLUDED.meta_keywords, pad.meta_keywords),
    status=EXCLUDED.status, validation_errors=EXCLUDED.validation_errors, standardized_at=now(), updated_at=now()
  RETURNING pad.id INTO v_pad_id;

  RETURN jsonb_build_object('success',true,'padronizacao_id',v_pad_id,'reference',v_ref,
                            'campos',(SELECT count(*) FROM jsonb_object_keys(v_assigns)),'erros',v_errs);
END;
$function$;
;

-- <<< END 20260606142001_standardize_raw_custom_array_v2.sql <<<

-- >>> BEGIN 20260606142100_remove_fix_materials_from_orchestrator.sql >>>

CREATE OR REPLACE FUNCTION public.fn_spot_process_ref(p_parent_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_sup uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_rep uuid; v_pad uuid; r record; v_vars int := 0;
  v_promo jsonb; v_promv jsonb; v_repl int; v_pos int; v_gold jsonb; v_recon int;
BEGIN
  PERFORM set_config('app.write_source','pipeline', true);
  PERFORM set_config('app.bulk_import_mode','true', true);

  -- 1. representante (raw com mais conteúdo) + padroniza PARENT via DE>PARA
  SELECT spr.id INTO v_rep FROM public.supplier_products_raw spr
   WHERE spr.supplier_id=v_sup AND spr.raw_data->>'ProdReference'=p_parent_ref
   ORDER BY length(spr.raw_data::text) DESC NULLS LAST, spr.id LIMIT 1;
  IF v_rep IS NULL THEN RETURN jsonb_build_object('success',false,'error','sem_raw','ref',p_parent_ref); END IF;
  PERFORM public.fn_standardize_raw(v_rep, p_parent_ref);
  -- NOTA: fn_standardize_raw (v2) usa fn_spot_split_list via DE>PARA para Materials.
  --       fn_spot_fix_materials removida desta etapa em 2026-06-06 (não mais necessária).

  -- 2. padroniza VARIANTES
  FOR r IN SELECT id FROM public.supplier_products_raw
            WHERE supplier_id=v_sup AND raw_data->>'ProdReference'=p_parent_ref LOOP
    PERFORM public.fn_standardize_variant(r.id); v_vars := v_vars + 1;
  END LOOP;

  -- 3. enrich Silver (taxonomia/SEO/extras/reparo encoding)
  --    Materials já correto pelo DE>PARA — fn_spot_fix_materials não é mais chamada.
  PERFORM public.fn_spot_silver_enrich(v_sup, p_parent_ref);

  -- 4. promove PARENT + VARIANTES (Silver → Gold)
  SELECT id INTO v_pad FROM public.produtos_padronizacao
   WHERE supplier_id=v_sup AND supplier_reference=p_parent_ref
   ORDER BY standardized_at DESC NULLS LAST LIMIT 1;
  v_promo  := public.fn_promote_padronizacao(v_pad);
  v_promv  := public.fn_promote_variants_of_parent(v_sup, p_parent_ref);

  -- 5. enrich Gold (variante + produto) + posições de impressão + reconciliação
  v_repl   := public.fn_spot_variant_repl_enrich(v_sup, p_parent_ref);
  v_pos    := public.fn_spot_print_positions(v_sup, p_parent_ref);
  v_gold   := public.fn_spot_gold_enrich(v_sup, p_parent_ref);
  v_recon  := public.fn_spot_reconcile_variant_to_legacy(v_sup, p_parent_ref);

  RETURN jsonb_build_object('success',true,'ref',p_parent_ref,'variantes',v_vars,
    'promote_parent',v_promo->'success','promote_variants',v_promv->'variantes_promovidas',
    'repl',v_repl,'print_positions',v_pos,'gold',v_gold,'reconciliadas',v_recon);
END $function$;
;

-- <<< END 20260606142100_remove_fix_materials_from_orchestrator.sql <<<

-- >>> BEGIN 20260606142300_standardize_variant_depara_spot.sql >>>

CREATE OR REPLACE FUNCTION public.fn_standardize_variant(p_raw_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r public.supplier_products_raw%ROWTYPE;
  v_parent text; v_code text; v_apiid text; v_cname text; v_chex text;
  v_col RECORD; v_sku text; v_supplier_sku text; v_stock integer; v_cost numeric; v_var_id uuid;
  v_fname text; v_fcode text; v_fhex text; v_canonical_id uuid;
  v_cp1 numeric; v_cp2 numeric; v_cp3 numeric; v_cp4 numeric; v_cp5 numeric;
  v_mq1 int; v_mq2 int; v_mq3 int; v_mq4 int; v_mq5 int;
  v_nq1 int; v_nq2 int; v_nq3 int; v_nd1 date; v_nd2 date; v_nd3 date;
  v_mult int; v_thumb text; v_images jsonb; v_videos jsonb;
  v_base text := 'https://www.spotgifts.com.br/fotos/produtos/';
  v_SPOT uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_XBZ  uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
  v_ASIA uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_SM   uuid := '841cd690-210a-422a-908c-7676828db272';
  -- Variáveis para o loop DE>PARA (SPOT)
  m            RECORD;
  v_val        text;
  v_tx         text;
  v_pv_assigns  jsonb := '{}'::jsonb;   -- acumulador product_variants
  v_vss_assigns jsonb := '{}'::jsonb;  -- acumulador variant_supplier_sources
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id=p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','raw_nao_encontrado'); END IF;
  v_parent := public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data);

  -- ═══════════════════════════════════════════════════════════════════════════
  -- SPOT: DE>PARA-driven (supplier_field_mappings) — 2026-06-06
  -- Substitui branch hardcoded por loop sobre 39 regras de variants/vss.
  -- Color matching e INSERT permanecem inalterados.
  -- ═══════════════════════════════════════════════════════════════════════════
  IF r.supplier_id=v_SPOT THEN
    v_pv_assigns  := '{}'::jsonb;
    v_vss_assigns := '{}'::jsonb;

    FOR m IN
      SELECT sfm.source_field, sfm.target_field, sfm.target_table,
             sfm.transform_type, sfm.transform_config, sfm.source_unit, sfm.target_unit
      FROM public.supplier_field_mappings sfm
      WHERE sfm.supplier_id = v_SPOT
        AND sfm.target_table IN ('product_variants','variant_supplier_sources')
        AND sfm.is_active = TRUE
        -- color_id e size_id: resolvidos por fn_match_canonical_color / lookup separado
        AND sfm.target_field NOT IN ('color_id','size_id','web_sku','length_cm','width_cm')
      ORDER BY sfm.target_table, sfm.priority NULLS LAST
    LOOP
      -- Fonte: raw_data ou stock_data (marcado em transform_config->>'source_blob')
      v_val := CASE WHEN m.transform_config->>'source_blob' = 'stock_data'
                    THEN r.stock_data ->> m.source_field
                    ELSE r.raw_data   ->> m.source_field
               END;
      CONTINUE WHEN v_val IS NULL OR TRIM(v_val) = '';

      BEGIN
        v_tx := public.fn_apply_transform(
          v_val, m.transform_type, m.transform_config,
          m.source_unit, m.target_unit, v_SPOT
        );
      EXCEPTION WHEN OTHERS THEN v_tx := v_val; END;
      CONTINUE WHEN v_tx IS NULL;

      IF m.target_table = 'product_variants' THEN
        v_pv_assigns := v_pv_assigns || jsonb_build_object(m.target_field, v_tx);
      ELSE
        v_vss_assigns := v_vss_assigns || jsonb_build_object(m.target_field, v_tx);
      END IF;
    END LOOP;

    -- Extrai valores tipados dos acumuladores
    v_supplier_sku := v_pv_assigns->>'supplier_sku';
    v_code  := v_pv_assigns->>'color_code';
    v_cname := COALESCE(NULLIF(TRIM(v_pv_assigns->>'color_name'),''), r.raw_data->>'ColorDesc1');
    v_chex  := COALESCE(NULLIF(TRIM(v_pv_assigns->>'color_hex'),''),  r.raw_data->>'ColorHex1');
    v_thumb := COALESCE(v_pv_assigns->>'selected_thumbnail', v_vss_assigns->>'supplier_thumbnail');
    v_sku   := r.supplier_reference;  -- SKU local SPOT = supplier_reference

    -- Imagens: fn_spot_image_list retorna jsonb serializada como text
    BEGIN
      v_images := COALESCE(
        CASE WHEN v_pv_assigns ? 'images'
             THEN (v_pv_assigns->>'images')::jsonb END,
        CASE WHEN v_vss_assigns ? 'supplier_images'
             THEN (v_vss_assigns->>'supplier_images')::jsonb END,
        '[]'::jsonb
      );
    EXCEPTION WHEN OTHERS THEN v_images := '[]'::jsonb; END;

    -- Vídeos (array_url op → jsonb serializada)
    BEGIN
      v_videos := CASE WHEN v_vss_assigns ? 'supplier_videos'
                       THEN (v_vss_assigns->>'supplier_videos')::jsonb END;
    EXCEPTION WHEN OTHERS THEN v_videos := NULL; END;

    -- Estoque (com fallback para campos legados)
    v_stock := public.fn_safe_int(COALESCE(
      v_vss_assigns->>'quantity',
      v_vss_assigns->>'stock_main_warehouse',
      r.stock_data->>'Quantity',
      r.raw_data->>'StockQuantity'
    ));

    -- Custo e preços (5 faixas)
    v_cost := public.fn_safe_num(COALESCE(v_vss_assigns->>'cost_price', r.raw_data->>'Price1'));
    v_cp1  := public.fn_safe_num(COALESCE(v_vss_assigns->>'cost_price_1', r.raw_data->>'Price1'));
    v_cp2  := public.fn_safe_num(v_vss_assigns->>'cost_price_2');
    v_cp3  := public.fn_safe_num(v_vss_assigns->>'cost_price_3');
    v_cp4  := public.fn_safe_num(v_vss_assigns->>'cost_price_4');
    v_cp5  := public.fn_safe_num(v_vss_assigns->>'cost_price_5');

    -- MOQ (quantidades mínimas por faixa)
    v_mq1 := public.fn_safe_int(v_vss_assigns->>'min_qty_1');
    v_mq2 := public.fn_safe_int(v_vss_assigns->>'min_qty_2');
    v_mq3 := public.fn_safe_int(v_vss_assigns->>'min_qty_3');
    v_mq4 := public.fn_safe_int(v_vss_assigns->>'min_qty_4');
    v_mq5 := public.fn_safe_int(v_vss_assigns->>'min_qty_5');

    -- Multiplicador de venda
    v_mult := public.fn_safe_int(COALESCE(v_vss_assigns->>'sale_multiplier', r.raw_data->>'Multiplier'));

    -- Reposição (lotes 1-3 via DE>PARA; lotes 4-6 via fn_spot_variant_repl_enrich)
    v_nq1 := public.fn_safe_int(v_vss_assigns->>'next_quantity_1');
    v_nq2 := public.fn_safe_int(v_vss_assigns->>'next_quantity_2');
    v_nq3 := public.fn_safe_int(v_vss_assigns->>'next_quantity_3');
    v_nd1 := CASE WHEN v_vss_assigns->>'next_date_1' ~ '^\d{4}-\d{2}-\d{2}'
                  THEN LEFT(v_vss_assigns->>'next_date_1', 10)::date ELSE NULL END;
    v_nd2 := CASE WHEN v_vss_assigns->>'next_date_2' ~ '^\d{4}-\d{2}-\d{2}'
                  THEN LEFT(v_vss_assigns->>'next_date_2', 10)::date ELSE NULL END;
    v_nd3 := CASE WHEN v_vss_assigns->>'next_date_3' ~ '^\d{4}-\d{2}-\d{2}'
                  THEN LEFT(v_vss_assigns->>'next_date_3', 10)::date ELSE NULL END;

  -- ═══════════════════════════════════════════════════════════════════════════
  -- XBZ, ASIA, SM: branches hardcoded (DE>PARA a implementar futuramente)
  -- ═══════════════════════════════════════════════════════════════════════════
  ELSIF r.supplier_id=v_XBZ THEN
    v_apiid:=r.raw_data->>'CorWebPrincipalId'; v_cname:=r.raw_data->>'CorWebPrincipal';
    v_supplier_sku:=r.raw_data->>'CodigoComposto'; v_stock:=public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel');
    v_cost:=public.fn_safe_num(r.raw_data->>'PrecoVenda');
    v_sku:='XBZ-'||r.supplier_reference;
  ELSIF r.supplier_id=v_ASIA THEN
    v_cname:=r.raw_data->>'var_cor_nome'; v_chex:=r.raw_data->>'var_cor_hex';
    v_supplier_sku:=COALESCE(r.raw_data->>'var_referencia', r.supplier_reference);
    v_stock:=public.fn_safe_int(COALESCE(r.stock_data->>'qtd_estoque', r.raw_data->>'var_estoque'));
    v_cost:=public.fn_safe_num(r.raw_data->>'preco');
    v_sku:='ASIA-'||r.supplier_reference;
    v_nd1 := CASE
      WHEN COALESCE(r.stock_data->'previsao_entrega'->0->>'data', r.raw_data->'previsao_entrega'->0->>'data') ~ '^\d{4}-\d{2}-\d{2}'
      THEN LEFT(COALESCE(r.stock_data->'previsao_entrega'->0->>'data', r.raw_data->'previsao_entrega'->0->>'data'),10)::date END;
    v_nq1 := public.fn_safe_int(COALESCE(r.stock_data->'previsao_entrega'->0->>'quantidade', r.raw_data->'previsao_entrega'->0->>'quantidade'));
  ELSIF r.supplier_id=v_SM THEN
    v_cname:=public.fn_extract_color_from_title(r.raw_data->>'titulo');
    v_chex := (SELECT split_part(item,'|',2)
               FROM unnest(string_to_array(r.raw_data->>'produtos_similares', ';')) item
               WHERE split_part(item,'|',1)=r.supplier_reference
                 AND split_part(item,'|',2) ~* '^#[0-9a-f]{6}$' LIMIT 1);
    v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque');
    v_cost:=public.fn_safe_num(r.raw_data->>'preco_sem_gravacao_sem_impostos');
    v_sku:=r.supplier_reference;
  ELSE
    v_cname:=r.raw_data->>'cor'; v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque'); v_cost:=public.fn_safe_num(r.raw_data->>'preco_base');
    v_sku:=r.supplier_reference;
  END IF;

  -- ═══════════════════════════════════════════════════════════════════════════
  -- Color matching (comum a todos os fornecedores — inalterado)
  -- ═══════════════════════════════════════════════════════════════════════════
  SELECT * INTO v_col FROM public.fn_match_supplier_color(r.supplier_id, v_code, v_apiid, v_cname, v_chex);
  v_fname := COALESCE(v_col.color_name, v_cname);
  v_fcode := COALESCE(v_col.color_code, v_code);
  v_fhex  := COALESCE(v_col.color_hex,  v_chex);
  v_canonical_id := public.fn_match_canonical_color(v_fname, v_fhex);

  -- ═══════════════════════════════════════════════════════════════════════════
  -- INSERT/UPSERT em produtos_padronizacao_variantes (inalterado)
  -- ═══════════════════════════════════════════════════════════════════════════
  INSERT INTO public.produtos_padronizacao_variantes AS pv (
    raw_id, supplier_id, parent_reference, variant_reference,
    sku, supplier_sku, color_name, color_code, color_hex, color_id,
    stock_quantity, cost_price, is_active, status,
    cost_price_1, cost_price_2, cost_price_3, cost_price_4, cost_price_5,
    min_qty_1, min_qty_2, min_qty_3, min_qty_4, min_qty_5,
    next_quantity_1, next_quantity_2, next_quantity_3, next_date_1, next_date_2, next_date_3,
    sale_multiplier, supplier_thumbnail, supplier_images, supplier_videos
  ) VALUES (
    r.id, r.supplier_id, v_parent, r.supplier_reference, v_sku, v_supplier_sku,
    v_fname, v_fcode, v_fhex, v_canonical_id,
    v_stock, v_cost, true, 'standardized'::public.produtos_padronizacao_status,
    v_cp1, v_cp2, v_cp3, v_cp4, v_cp5,
    v_mq1, v_mq2, v_mq3, v_mq4, v_mq5,
    v_nq1, v_nq2, v_nq3, v_nd1, v_nd2, v_nd3,
    v_mult, v_thumb, v_images, v_videos
  )
  ON CONFLICT (supplier_id, variant_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, parent_reference=EXCLUDED.parent_reference, sku=EXCLUDED.sku, supplier_sku=EXCLUDED.supplier_sku,
    color_name=EXCLUDED.color_name, color_code=EXCLUDED.color_code, color_hex=EXCLUDED.color_hex, color_id=EXCLUDED.color_id,
    stock_quantity=EXCLUDED.stock_quantity, cost_price=EXCLUDED.cost_price, is_active=EXCLUDED.is_active,
    status=EXCLUDED.status,
    cost_price_1=EXCLUDED.cost_price_1, cost_price_2=EXCLUDED.cost_price_2, cost_price_3=EXCLUDED.cost_price_3,
    cost_price_4=EXCLUDED.cost_price_4, cost_price_5=EXCLUDED.cost_price_5,
    min_qty_1=EXCLUDED.min_qty_1, min_qty_2=EXCLUDED.min_qty_2, min_qty_3=EXCLUDED.min_qty_3,
    min_qty_4=EXCLUDED.min_qty_4, min_qty_5=EXCLUDED.min_qty_5,
    next_quantity_1=EXCLUDED.next_quantity_1, next_quantity_2=EXCLUDED.next_quantity_2, next_quantity_3=EXCLUDED.next_quantity_3,
    next_date_1=EXCLUDED.next_date_1, next_date_2=EXCLUDED.next_date_2, next_date_3=EXCLUDED.next_date_3,
    sale_multiplier=EXCLUDED.sale_multiplier, supplier_thumbnail=EXCLUDED.supplier_thumbnail,
    supplier_images=EXCLUDED.supplier_images, supplier_videos=EXCLUDED.supplier_videos,
    updated_at=now()
  RETURNING pv.id INTO v_var_id;

  RETURN jsonb_build_object('success',true,'variante_id',v_var_id,'parent',v_parent,
                            'cor',v_fname,'hex',v_fhex,'color_id_canonico',v_canonical_id,
                            'de_para_driven', (r.supplier_id=v_SPOT));
END;
$function$;
;

-- <<< END 20260606142300_standardize_variant_depara_spot.sql <<<

-- >>> BEGIN 20260606142744_fase0_ingestao_bronze_foundation.sql >>>
-- ============================================================================
-- FASE 0 — Fundação da ingestão Bronze (AGNÓSTICA de executor: vale n8n ou Edge)
-- Princípio: só escreve no Bronze, via RPC idempotente. Transform fica no Postgres.
-- ============================================================================

-- 1) Log de corridas de ingestão (espelha pipeline_run_log da camada transform)
create table if not exists public.ingestion_run_log (
  id            bigint generated always as identity primary key,
  run_id        uuid not null,
  supplier_code text not null,
  feed          text not null check (feed in ('products','stock','customization')),
  started_at    timestamptz not null default now(),
  finished_at   timestamptz,
  duration_s    numeric,
  fetched       integer not null default 0,
  upserted      integer not null default 0,
  skipped       integer not null default 0,
  errors        integer not null default 0,
  status        text not null default 'running'
                check (status in ('running','ok','ok_com_erros','failed','aborted_rate_limit')),
  error_samples jsonb,
  created_at    timestamptz not null default now()
);
create index if not exists ix_ingestion_run_log_started  on public.ingestion_run_log (started_at desc);
create index if not exists ix_ingestion_run_log_sup_feed on public.ingestion_run_log (supplier_code, feed, started_at desc);
alter table public.ingestion_run_log enable row level security;  -- sem policy: só definer/superuser

-- helper: resolve supplier_id por code (fallback nome); erro se inativo/inexistente
create or replace function public.fn_resolve_supplier(p_code text)
returns uuid language plpgsql stable security definer set search_path=public as $$
declare v_id uuid; v_active boolean;
begin
  select id, active into v_id, v_active from suppliers
   where upper(code)=upper(p_code) or upper(name)=upper(p_code)
   order by (upper(code)=upper(p_code)) desc limit 1;
  if v_id is null   then raise exception 'Fornecedor % nao encontrado', p_code; end if;
  if v_active is false then raise exception 'Fornecedor % inativo', p_code; end if;
  return v_id;
end $$;

-- 2) ENTRYPOINT de ingestão — roteia p/ os RPCs idempotentes existentes
create or replace function public.fn_ingest_bronze_batch(
  p_supplier_code text, p_feed text, p_run_id uuid, p_items jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_sid uuid := public.fn_resolve_supplier(p_supplier_code);
  v_item jsonb; v_ref text; v_tco text;
  v_fetched int := 0; v_upserted int := 0; v_skipped int := 0; v_errors int := 0;
  v_errsamples jsonb := '[]'::jsonb;
begin
  if p_feed not in ('products','stock','customization') then raise exception 'feed invalido: %', p_feed; end if;
  if jsonb_typeof(p_items) <> 'array' then raise exception 'p_items deve ser array jsonb'; end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_fetched := v_fetched + 1;
    begin
      if p_feed in ('products','stock') then
        v_ref := coalesce(nullif(v_item->>'Sku',''), nullif(v_item->>'sku',''),
                          nullif(v_item->>'supplier_reference',''), nullif(v_item->>'referencia',''),
                          nullif(v_item->>'ProdReference',''), nullif(v_item->>'codigo',''));
        if v_ref is null then
          v_skipped := v_skipped + 1;
          if jsonb_array_length(v_errsamples) < 20 then
            v_errsamples := v_errsamples || jsonb_build_object('motivo','sem_chave_natural','item',v_item);
          end if;
          continue;
        end if;
        if p_feed = 'products'
          then perform public.insert_supplier_product_raw(v_sid, v_ref, v_item, p_run_id);
          else perform public.upsert_supplier_stock_raw  (v_sid, v_ref, v_item, p_run_id);
        end if;
        v_upserted := v_upserted + 1;
      else  -- customization
        v_tco := coalesce(nullif(v_item->>'TableCodeOption',''), nullif(v_item->>'table_code_option',''));
        if v_tco is null then
          v_skipped := v_skipped + 1;
          if jsonb_array_length(v_errsamples) < 20 then
            v_errsamples := v_errsamples || jsonb_build_object('motivo','sem_table_code_option','item',v_item);
          end if;
          continue;
        end if;
        perform public.upsert_supplier_customization_raw(
          v_sid, v_tco, v_item,
          nullif(v_item->>'TableCode',''),
          coalesce(nullif(v_item->>'CustomizationTypeName',''), nullif(v_item->>'customization_type','')),
          p_run_id);
        v_upserted := v_upserted + 1;
      end if;
    exception when others then
      v_errors := v_errors + 1;
      if jsonb_array_length(v_errsamples) < 20 then
        v_errsamples := v_errsamples || jsonb_build_object('erro',SQLERRM,'sqlstate',SQLSTATE,'ref',coalesce(v_ref,v_tco));
      end if;
    end;
  end loop;

  return jsonb_build_object('supplier_code',p_supplier_code,'feed',p_feed,'run_id',p_run_id,
    'fetched',v_fetched,'upserted',v_upserted,'skipped',v_skipped,'errors',v_errors,
    'error_samples',v_errsamples);
end $$;

-- 3) SWEEP de descontinuados (chamar SÓ após full-pull de produtos 100% OK)
create or replace function public.fn_bronze_mark_absent(p_supplier_code text, p_run_id uuid)
returns integer language plpgsql security definer set search_path=public as $$
declare v_sid uuid := public.fn_resolve_supplier(p_supplier_code); v_n int;
begin
  update supplier_products_raw
     set status = 'skipped'::supplier_raw_status, updated_at = now()
   where supplier_id = v_sid
     and status::text in ('pending','processing','processed')
     and coalesce(import_batch_id,'00000000-0000-0000-0000-000000000000'::uuid) <> p_run_id;
  get diagnostics v_n = row_count;
  return v_n;
end $$;

-- 4) Abre/fecha corrida no log
create or replace function public.fn_ingestion_run_open(p_supplier_code text, p_feed text)
returns uuid language plpgsql security definer set search_path=public as $$
declare v_run uuid := gen_random_uuid();
begin
  if p_feed not in ('products','stock','customization') then raise exception 'feed invalido: %', p_feed; end if;
  insert into ingestion_run_log(run_id, supplier_code, feed, status)
  values (v_run, p_supplier_code, p_feed, 'running');
  return v_run;
end $$;

create or replace function public.fn_ingestion_run_close(
  p_run_id uuid, p_status text, p_fetched int, p_upserted int, p_skipped int, p_errors int,
  p_error_samples jsonb default null)
returns void language plpgsql security definer set search_path=public as $$
begin
  update ingestion_run_log
     set finished_at = now(),
         duration_s  = extract(epoch from (now()-started_at)),
         status = p_status, fetched = p_fetched, upserted = p_upserted,
         skipped = p_skipped, errors = p_errors,
         error_samples = coalesce(p_error_samples, error_samples)
   where run_id = p_run_id;
end $$;

-- 5) Health da ingestão (standalone; será unido ao fn_pipeline_health quando ligarmos os extractors)
create or replace function public.fn_ingestion_health()
returns jsonb language sql stable security definer set search_path=public as $$
  select jsonb_build_object(
    'checked_at', now(),
    'por_fornecedor_feed', (
      select coalesce(jsonb_agg(jsonb_build_object(
               'supplier_code', supplier_code, 'feed', feed, 'ultimo_status', status,
               'ultimo_run', started_at,
               'idade_horas', round((extract(epoch from (now()-started_at))/3600)::numeric,2),
               'fetched', fetched, 'upserted', upserted, 'errors', errors) order by supplier_code, feed), '[]'::jsonb)
      from (select distinct on (supplier_code,feed) supplier_code,feed,status,started_at,fetched,upserted,errors
            from ingestion_run_log order by supplier_code,feed,started_at desc) ult),
    'corridas_24h', (select count(*) from ingestion_run_log where started_at > now()-interval '24 hours'),
    'falhas_24h',   (select count(*) from ingestion_run_log where started_at > now()-interval '24 hours'
                                                                and status in ('failed','aborted_rate_limit')))
$$;

-- Grants: tudo restrito a service_role (Edge/n8n usam service_role)
revoke all on function public.fn_resolve_supplier(text)                          from public, anon, authenticated;
revoke all on function public.fn_ingest_bronze_batch(text,text,uuid,jsonb)       from public, anon, authenticated;
revoke all on function public.fn_bronze_mark_absent(text,uuid)                   from public, anon, authenticated;
revoke all on function public.fn_ingestion_run_open(text,text)                   from public, anon, authenticated;
revoke all on function public.fn_ingestion_run_close(uuid,text,int,int,int,int,jsonb) from public, anon, authenticated;
revoke all on function public.fn_ingestion_health()                              from public, anon, authenticated;
grant execute on function public.fn_ingest_bronze_batch(text,text,uuid,jsonb)       to service_role;
grant execute on function public.fn_bronze_mark_absent(text,uuid)                   to service_role;
grant execute on function public.fn_ingestion_run_open(text,text)                   to service_role;
grant execute on function public.fn_ingestion_run_close(uuid,text,int,int,int,int,jsonb) to service_role;
grant execute on function public.fn_ingestion_health()                              to service_role;;

-- <<< END 20260606142744_fase0_ingestao_bronze_foundation.sql <<<

-- >>> BEGIN 20260606142945_fase0_run_open_close_batch_fk.sql >>>
-- run_open agora cunha um lote real em supplier_import_batches (satisfaz a FK import_batch_id)
-- e usa o id do lote como run_id (unifica correlação: run_id == import_batch_id).
create or replace function public.fn_ingestion_run_open(p_supplier_code text, p_feed text)
returns uuid language plpgsql security definer set search_path=public as $$
declare v_sid uuid := public.fn_resolve_supplier(p_supplier_code); v_run uuid;
begin
  if p_feed not in ('products','stock','customization') then raise exception 'feed invalido: %', p_feed; end if;
  insert into supplier_import_batches(supplier_id, status, notes)
    values (v_sid, 'running', 'ingestao '||p_feed||' ('||p_supplier_code||')')
    returning id into v_run;
  insert into ingestion_run_log(run_id, supplier_code, feed, status)
    values (v_run, p_supplier_code, p_feed, 'running');
  return v_run;
end $$;

-- run_close fecha o log E o lote (mapeia contadores p/ o batch)
create or replace function public.fn_ingestion_run_close(
  p_run_id uuid, p_status text, p_fetched int, p_upserted int, p_skipped int, p_errors int,
  p_error_samples jsonb default null)
returns void language plpgsql security definer set search_path=public as $$
begin
  update ingestion_run_log
     set finished_at=now(), duration_s=extract(epoch from (now()-started_at)),
         status=p_status, fetched=p_fetched, upserted=p_upserted, skipped=p_skipped, errors=p_errors,
         error_samples=coalesce(p_error_samples, error_samples)
   where run_id=p_run_id;
  update supplier_import_batches
     set finished_at=now(), status=p_status,
         products_imported=p_upserted, products_errors=p_errors,
         error_log=coalesce(p_error_samples, error_log)
   where id=p_run_id;
end $$;;

-- <<< END 20260606142945_fase0_run_open_close_batch_fk.sql <<<

-- >>> BEGIN 20260606143731_fn_standardize_variant_sm_depara_loop_2026.sql >>>
-- Migra o branch SM de hardcoded para loop De→Para (mesmo padrão do SPOT).
-- Cor permanece heurística pois API SM não tem campo de cor dedicado.
-- Agora popula: cost_price_1-4, min_qty_1, supplier_thumbnail, supplier_images.
CREATE OR REPLACE FUNCTION public.fn_standardize_variant(p_raw_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $fn$
DECLARE
  r             public.supplier_products_raw%ROWTYPE;
  v_parent      text; v_code text; v_apiid text; v_cname text; v_chex text;
  v_col         RECORD;
  v_sku         text; v_supplier_sku text; v_stock integer; v_cost numeric; v_var_id uuid;
  v_fname       text; v_fcode text; v_fhex text; v_canonical_id uuid;
  v_cp1 numeric; v_cp2 numeric; v_cp3 numeric; v_cp4 numeric; v_cp5 numeric;
  v_mq1 int;    v_mq2 int;    v_mq3 int;    v_mq4 int;    v_mq5 int;
  v_nq1 int;    v_nq2 int;    v_nq3 int;
  v_nd1 date;   v_nd2 date;   v_nd3 date;
  v_mult        int;
  v_thumb       text;
  v_images      jsonb;
  v_videos      jsonb;
  v_base        text := 'https://www.spotgifts.com.br/fotos/produtos/';
  v_SPOT        uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_XBZ         uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
  v_ASIA        uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_SM          uuid := '841cd690-210a-422a-908c-7676828db272';
  -- Loop De→Para
  m             RECORD;
  v_val         text;
  v_tx          text;
  v_pv_assigns  jsonb := '{}'::jsonb;
  v_vss_assigns jsonb := '{}'::jsonb;
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'raw_nao_encontrado');
  END IF;
  v_parent := public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data);

  -- ═══════════════════════════════════════════════════════════════════════════
  -- SPOT: De→Para-driven via supplier_field_mappings
  -- ═══════════════════════════════════════════════════════════════════════════
  IF r.supplier_id = v_SPOT THEN
    v_pv_assigns  := '{}'::jsonb;
    v_vss_assigns := '{}'::jsonb;

    FOR m IN
      SELECT sfm.source_field, sfm.target_field, sfm.target_table,
             sfm.transform_type, sfm.transform_config, sfm.source_unit, sfm.target_unit
      FROM public.supplier_field_mappings sfm
      WHERE sfm.supplier_id = v_SPOT
        AND sfm.target_table IN ('product_variants','variant_supplier_sources')
        AND sfm.is_active = TRUE
        AND sfm.target_field NOT IN ('color_id','size_id','web_sku','length_cm','width_cm')
      ORDER BY sfm.target_table, sfm.priority NULLS LAST
    LOOP
      v_val := CASE WHEN m.transform_config->>'source_blob' = 'stock_data'
                    THEN r.stock_data ->> m.source_field
                    ELSE r.raw_data   ->> m.source_field
               END;
      CONTINUE WHEN v_val IS NULL OR TRIM(v_val) = '';
      BEGIN
        v_tx := public.fn_apply_transform(v_val, m.transform_type, m.transform_config,
                                          m.source_unit, m.target_unit, v_SPOT);
      EXCEPTION WHEN OTHERS THEN v_tx := v_val; END;
      CONTINUE WHEN v_tx IS NULL;
      IF m.target_table = 'product_variants' THEN
        v_pv_assigns := v_pv_assigns || jsonb_build_object(m.target_field, v_tx);
      ELSE
        v_vss_assigns := v_vss_assigns || jsonb_build_object(m.target_field, v_tx);
      END IF;
    END LOOP;

    v_supplier_sku := v_pv_assigns->>'supplier_sku';
    v_code   := v_pv_assigns->>'color_code';
    v_cname  := COALESCE(NULLIF(TRIM(v_pv_assigns->>'color_name'),''), r.raw_data->>'ColorDesc1');
    v_chex   := COALESCE(NULLIF(TRIM(v_pv_assigns->>'color_hex'),''),  r.raw_data->>'ColorHex1');
    v_thumb  := COALESCE(v_pv_assigns->>'selected_thumbnail', v_vss_assigns->>'supplier_thumbnail');
    v_sku    := r.supplier_reference;
    BEGIN
      v_images := COALESCE(
        CASE WHEN v_pv_assigns  ? 'images'          THEN (v_pv_assigns ->>'images')::jsonb END,
        CASE WHEN v_vss_assigns ? 'supplier_images'  THEN (v_vss_assigns->>'supplier_images')::jsonb END,
        '[]'::jsonb);
    EXCEPTION WHEN OTHERS THEN v_images := '[]'::jsonb; END;
    BEGIN
      v_videos := CASE WHEN v_vss_assigns ? 'supplier_videos'
                       THEN (v_vss_assigns->>'supplier_videos')::jsonb END;
    EXCEPTION WHEN OTHERS THEN v_videos := NULL; END;
    v_stock := public.fn_safe_int(COALESCE(
      v_vss_assigns->>'quantity', v_vss_assigns->>'stock_main_warehouse',
      r.stock_data->>'Quantity',  r.raw_data->>'StockQuantity'));
    v_cost := public.fn_safe_num(COALESCE(v_vss_assigns->>'cost_price', r.raw_data->>'Price1'));
    v_cp1  := public.fn_safe_num(COALESCE(v_vss_assigns->>'cost_price_1', r.raw_data->>'Price1'));
    v_cp2  := public.fn_safe_num(v_vss_assigns->>'cost_price_2');
    v_cp3  := public.fn_safe_num(v_vss_assigns->>'cost_price_3');
    v_cp4  := public.fn_safe_num(v_vss_assigns->>'cost_price_4');
    v_cp5  := public.fn_safe_num(v_vss_assigns->>'cost_price_5');
    v_mq1  := public.fn_safe_int(v_vss_assigns->>'min_qty_1');
    v_mq2  := public.fn_safe_int(v_vss_assigns->>'min_qty_2');
    v_mq3  := public.fn_safe_int(v_vss_assigns->>'min_qty_3');
    v_mq4  := public.fn_safe_int(v_vss_assigns->>'min_qty_4');
    v_mq5  := public.fn_safe_int(v_vss_assigns->>'min_qty_5');
    v_mult := public.fn_safe_int(COALESCE(v_vss_assigns->>'sale_multiplier', r.raw_data->>'Multiplier'));
    v_nq1  := public.fn_safe_int(v_vss_assigns->>'next_quantity_1');
    v_nq2  := public.fn_safe_int(v_vss_assigns->>'next_quantity_2');
    v_nq3  := public.fn_safe_int(v_vss_assigns->>'next_quantity_3');
    v_nd1  := CASE WHEN v_vss_assigns->>'next_date_1' ~ '^\d{4}-\d{2}-\d{2}'
                   THEN LEFT(v_vss_assigns->>'next_date_1',10)::date END;
    v_nd2  := CASE WHEN v_vss_assigns->>'next_date_2' ~ '^\d{4}-\d{2}-\d{2}'
                   THEN LEFT(v_vss_assigns->>'next_date_2',10)::date END;
    v_nd3  := CASE WHEN v_vss_assigns->>'next_date_3' ~ '^\d{4}-\d{2}-\d{2}'
                   THEN LEFT(v_vss_assigns->>'next_date_3',10)::date END;

  -- ═══════════════════════════════════════════════════════════════════════════
  -- SM: De→Para-driven — migrado de hardcoded em 2026-06-06
  -- Cor permanece heurística: API SM não tem campo de cor dedicado.
  -- ═══════════════════════════════════════════════════════════════════════════
  ELSIF r.supplier_id = v_SM THEN
    v_pv_assigns  := '{}'::jsonb;
    v_vss_assigns := '{}'::jsonb;

    FOR m IN
      SELECT sfm.source_field, sfm.target_field, sfm.target_table,
             sfm.transform_type, sfm.transform_config, sfm.source_unit, sfm.target_unit
      FROM public.supplier_field_mappings sfm
      WHERE sfm.supplier_id = v_SM
        AND sfm.target_table IN ('product_variants','variant_supplier_sources')
        AND sfm.is_active = TRUE
      ORDER BY sfm.target_table, sfm.priority NULLS LAST
    LOOP
      v_val := CASE
        WHEN m.transform_config->>'source_blob' = 'stock_data'
          THEN r.stock_data ->> m.source_field
          ELSE r.raw_data   ->> m.source_field
      END;
      CONTINUE WHEN v_val IS NULL OR TRIM(v_val) = '';
      BEGIN
        v_tx := public.fn_apply_transform(v_val, m.transform_type, m.transform_config,
                                          m.source_unit, m.target_unit, v_SM);
      EXCEPTION WHEN OTHERS THEN v_tx := v_val; END;
      CONTINUE WHEN v_tx IS NULL;
      IF m.target_table = 'product_variants' THEN
        v_pv_assigns := v_pv_assigns || jsonb_build_object(m.target_field, v_tx);
      ELSE
        v_vss_assigns := v_vss_assigns || jsonb_build_object(m.target_field, v_tx);
      END IF;
    END LOOP;

    -- Cor: heurística de título (sem campo de cor na API SM)
    v_cname := public.fn_extract_color_from_title(r.raw_data->>'titulo');
    v_chex  := (SELECT split_part(item,'|',2)
                FROM unnest(string_to_array(r.raw_data->>'produtos_similares', ';')) item
                WHERE split_part(item,'|',1) = r.supplier_reference
                  AND split_part(item,'|',2) ~* '^#[0-9a-f]{6}$' LIMIT 1);

    -- Extrair valores tipados com fallback para raw_data
    v_supplier_sku := COALESCE(NULLIF(TRIM(v_pv_assigns->>'supplier_sku'),''), r.supplier_reference);
    v_sku          := r.supplier_reference;
    v_stock        := public.fn_safe_int(COALESCE(v_pv_assigns->>'stock_quantity',
                                                   r.raw_data->>'estoque'));
    v_cost         := public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price',
                                                   r.raw_data->>'preco_sem_gravacao_sem_impostos'));
    v_cp1          := public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_1',
                                                   r.raw_data->>'preco_sem_gravacao_sem_impostos'));
    v_cp2          := public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_2',
                                                   r.raw_data->>'preco_com_gravacao_sem_impostos'));
    v_cp3          := public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_3',
                                                   r.raw_data->>'preco_sem_gravacao_com_impostos'));
    v_cp4          := public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_4',
                                                   r.raw_data->>'preco_com_gravacao_com_impostos'));
    v_mq1          := public.fn_safe_int(COALESCE(v_pv_assigns->>'min_qty_1',
                                                   r.raw_data->>'quantidade_minima_sugerida'));
    v_thumb        := NULLIF(TRIM(COALESCE(v_pv_assigns->>'supplier_thumbnail',
                                           r.raw_data->>'url_foto')), '');
    BEGIN
      v_images := CASE WHEN v_pv_assigns ? 'supplier_images'
                       THEN (v_pv_assigns->>'supplier_images')::jsonb
                       ELSE NULL END;
    EXCEPTION WHEN OTHERS THEN v_images := NULL; END;

  -- ═══════════════════════════════════════════════════════════════════════════
  -- XBZ: hardcoded (De→Para a implementar futuramente)
  -- ═══════════════════════════════════════════════════════════════════════════
  ELSIF r.supplier_id = v_XBZ THEN
    v_apiid        := r.raw_data->>'CorWebPrincipalId';
    v_cname        := r.raw_data->>'CorWebPrincipal';
    v_supplier_sku := r.raw_data->>'CodigoComposto';
    v_stock        := public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel');
    v_cost         := public.fn_safe_num(r.raw_data->>'PrecoVenda');
    v_sku          := 'XBZ-' || r.supplier_reference;

  -- ═══════════════════════════════════════════════════════════════════════════
  -- ASIA: hardcoded (De→Para a implementar futuramente)
  -- ═══════════════════════════════════════════════════════════════════════════
  ELSIF r.supplier_id = v_ASIA THEN
    v_cname        := r.raw_data->>'var_cor_nome';
    v_chex         := r.raw_data->>'var_cor_hex';
    v_supplier_sku := COALESCE(r.raw_data->>'var_referencia', r.supplier_reference);
    v_stock        := public.fn_safe_int(COALESCE(r.stock_data->>'qtd_estoque',
                                                   r.raw_data->>'var_estoque'));
    v_cost         := public.fn_safe_num(r.raw_data->>'preco');
    v_sku          := 'ASIA-' || r.supplier_reference;
    v_nd1 := CASE
      WHEN COALESCE(r.stock_data->'previsao_entrega'->0->>'data',
                    r.raw_data  ->'previsao_entrega'->0->>'data') ~ '^\d{4}-\d{2}-\d{2}'
      THEN LEFT(COALESCE(r.stock_data->'previsao_entrega'->0->>'data',
                         r.raw_data  ->'previsao_entrega'->0->>'data'), 10)::date END;
    v_nq1 := public.fn_safe_int(COALESCE(
      r.stock_data->'previsao_entrega'->0->>'quantidade',
      r.raw_data  ->'previsao_entrega'->0->>'quantidade'));

  -- Fallback genérico
  ELSE
    v_cname        := r.raw_data->>'cor';
    v_supplier_sku := r.supplier_reference;
    v_stock        := public.fn_safe_int(r.raw_data->>'estoque');
    v_cost         := public.fn_safe_num(r.raw_data->>'preco_base');
    v_sku          := r.supplier_reference;
  END IF;

  -- ═══════════════════════════════════════════════════════════════════════════
  -- Color matching (comum a todos os fornecedores)
  -- ═══════════════════════════════════════════════════════════════════════════
  SELECT * INTO v_col FROM public.fn_match_supplier_color(r.supplier_id, v_code, v_apiid, v_cname, v_chex);
  v_fname        := COALESCE(v_col.color_name, v_cname);
  v_fcode        := COALESCE(v_col.color_code, v_code);
  v_fhex         := COALESCE(v_col.color_hex,  v_chex);
  v_canonical_id := public.fn_match_canonical_color(v_fname, v_fhex);

  -- ═══════════════════════════════════════════════════════════════════════════
  -- UPSERT em produtos_padronizacao_variantes
  -- ═══════════════════════════════════════════════════════════════════════════
  INSERT INTO public.produtos_padronizacao_variantes AS pv (
    raw_id, supplier_id, parent_reference, variant_reference,
    sku, supplier_sku, color_name, color_code, color_hex, color_id,
    stock_quantity, cost_price, is_active, status,
    cost_price_1, cost_price_2, cost_price_3, cost_price_4, cost_price_5,
    min_qty_1, min_qty_2, min_qty_3, min_qty_4, min_qty_5,
    next_quantity_1, next_quantity_2, next_quantity_3,
    next_date_1, next_date_2, next_date_3,
    sale_multiplier, supplier_thumbnail, supplier_images, supplier_videos
  ) VALUES (
    r.id, r.supplier_id, v_parent, r.supplier_reference,
    v_sku, v_supplier_sku, v_fname, v_fcode, v_fhex, v_canonical_id,
    v_stock, v_cost, true, 'standardized'::public.produtos_padronizacao_status,
    v_cp1, v_cp2, v_cp3, v_cp4, v_cp5,
    v_mq1, v_mq2, v_mq3, v_mq4, v_mq5,
    v_nq1, v_nq2, v_nq3, v_nd1, v_nd2, v_nd3,
    v_mult, v_thumb, v_images, v_videos
  )
  ON CONFLICT (supplier_id, variant_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, parent_reference=EXCLUDED.parent_reference,
    sku=EXCLUDED.sku, supplier_sku=EXCLUDED.supplier_sku,
    color_name=EXCLUDED.color_name, color_code=EXCLUDED.color_code,
    color_hex=EXCLUDED.color_hex, color_id=EXCLUDED.color_id,
    stock_quantity=EXCLUDED.stock_quantity, cost_price=EXCLUDED.cost_price,
    is_active=EXCLUDED.is_active, status=EXCLUDED.status,
    cost_price_1=EXCLUDED.cost_price_1, cost_price_2=EXCLUDED.cost_price_2,
    cost_price_3=EXCLUDED.cost_price_3, cost_price_4=EXCLUDED.cost_price_4,
    cost_price_5=EXCLUDED.cost_price_5,
    min_qty_1=EXCLUDED.min_qty_1, min_qty_2=EXCLUDED.min_qty_2,
    min_qty_3=EXCLUDED.min_qty_3, min_qty_4=EXCLUDED.min_qty_4,
    min_qty_5=EXCLUDED.min_qty_5,
    next_quantity_1=EXCLUDED.next_quantity_1, next_quantity_2=EXCLUDED.next_quantity_2,
    next_quantity_3=EXCLUDED.next_quantity_3,
    next_date_1=EXCLUDED.next_date_1, next_date_2=EXCLUDED.next_date_2,
    next_date_3=EXCLUDED.next_date_3,
    sale_multiplier=EXCLUDED.sale_multiplier,
    supplier_thumbnail=EXCLUDED.supplier_thumbnail,
    supplier_images=EXCLUDED.supplier_images,
    supplier_videos=EXCLUDED.supplier_videos,
    updated_at=now()
  RETURNING pv.id INTO v_var_id;

  RETURN jsonb_build_object(
    'success',         true,
    'variante_id',     v_var_id,
    'parent',          v_parent,
    'cor',             v_fname,
    'hex',             v_fhex,
    'color_id_canonico', v_canonical_id,
    'de_para_driven',  (r.supplier_id IN (v_SPOT, v_SM))
  );
END;
$fn$;;

-- <<< END 20260606143731_fn_standardize_variant_sm_depara_loop_2026.sql <<<

-- >>> BEGIN 20260606144346_fn_promote_padronizacao_depara_category_2026.sql >>>
-- Adiciona lookup De→Para de categoria via supplier_category_mappings.
-- Prioridade: (1) locked_fields preserva, (2) De→Para atribui, (3) fallback trigger por keywords.
CREATE OR REPLACE FUNCTION public.fn_promote_padronizacao(p_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $fn$
DECLARE
  s        public.produtos_padronizacao%ROWTYPE;
  v_pid    uuid;
  v_org    uuid;
  v_locked text[];
  v_is_new boolean := false;
  -- ── Categoria De→Para ──────────────────────────────────────────────────────
  v_cat_id   uuid    := NULL;
  v_cat_src  text;
  v_cat_l1   text;
BEGIN
  SELECT * INTO s FROM public.produtos_padronizacao WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'padronizacao_nao_encontrada', 'id', p_id);
  END IF;
  IF s.status <> 'standardized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'status_invalido', 'status', s.status);
  END IF;

  PERFORM set_config('app.write_source',     'pipeline', true);
  PERFORM set_config('app.bulk_import_mode', 'true',     true);

  -- ── Produto Gold (INSERT se novo) ──────────────────────────────────────────
  SELECT id, locked_fields INTO v_pid, v_locked
  FROM public.products
  WHERE supplier_id = s.supplier_id AND supplier_reference = s.supplier_reference;

  IF v_pid IS NULL THEN
    v_is_new := true;
    SELECT organization_id INTO v_org FROM public.suppliers WHERE id = s.supplier_id;
    INSERT INTO public.products (organization_id, supplier_id, supplier_reference, sku, name, active, is_active, product_type)
    VALUES (v_org, s.supplier_id, s.supplier_reference,
            COALESCE(s.supplier_reference, s.name),
            COALESCE(s.name, 'Produto ' || s.supplier_reference),
            COALESCE(s.is_active, true), COALESCE(s.is_active, true), 'product')
    RETURNING id, locked_fields INTO v_pid, v_locked;
  END IF;

  v_locked := COALESCE(v_locked, '{}');

  -- ── Categoria via De→Para (supplier_categories → supplier_category_mappings) ──
  -- Se o fornecedor tem supplier_category_mappings configurado, usa-os.
  -- Só executa se 'category_id' não estiver em locked_fields.
  IF s.raw_id IS NOT NULL AND NOT ('category_id' = ANY(v_locked)) THEN
    BEGIN
      -- 1. Qual campo do raw_data contém a categoria para este fornecedor?
      SELECT sfm.source_field INTO v_cat_src
      FROM public.supplier_field_mappings sfm
      WHERE sfm.supplier_id = s.supplier_id
        AND sfm.target_field = 'categories'
      LIMIT 1;

      -- 2. Extrair o nível L1 (antes do primeiro '|')
      IF v_cat_src IS NOT NULL THEN
        SELECT split_part(COALESCE(spr.raw_data ->> v_cat_src, ''), '|', 1)
        INTO v_cat_l1
        FROM public.supplier_products_raw spr
        WHERE spr.id = s.raw_id;

        -- 3. Lookup De→Para
        IF v_cat_l1 IS NOT NULL AND TRIM(v_cat_l1) <> '' THEN
          SELECT scm.category_id INTO v_cat_id
          FROM public.supplier_categories sc
          JOIN public.supplier_category_mappings scm ON scm.supplier_category_id = sc.id
          WHERE sc.supplier_id = s.supplier_id
            AND TRIM(sc.supplier_code) = TRIM(v_cat_l1)
          LIMIT 1;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      NULL; -- falha silenciosa: trigger por keywords fará fallback
    END;
  END IF;

  -- ── UPDATE Gold ────────────────────────────────────────────────────────────
  UPDATE public.products p SET
    sku                = COALESCE(p.sku, s.supplier_reference, s.name),
    name               = CASE WHEN 'name'               = ANY(v_locked) THEN p.name               ELSE COALESCE(s.name,               p.name)               END,
    description        = CASE WHEN 'description'        = ANY(v_locked) THEN p.description        ELSE COALESCE(s.description,        p.description)        END,
    short_description  = CASE WHEN 'short_description'  = ANY(v_locked) THEN p.short_description  ELSE COALESCE(s.short_description,  p.short_description)  END,
    cost_price         = CASE WHEN 'cost_price'         = ANY(v_locked) THEN p.cost_price         ELSE COALESCE(s.cost_price,         p.cost_price)         END,
    suggested_price    = CASE WHEN 'suggested_price'    = ANY(v_locked) THEN p.suggested_price    ELSE COALESCE(s.suggested_price,    p.suggested_price)    END,
    stock_quantity     = CASE WHEN 'stock_quantity'     = ANY(v_locked) THEN p.stock_quantity     ELSE COALESCE(s.stock_quantity,     p.stock_quantity)     END,
    primary_image_url  = CASE WHEN 'primary_image_url'  = ANY(v_locked) THEN p.primary_image_url  ELSE COALESCE(s.primary_image_url,  p.primary_image_url)  END,
    images             = CASE WHEN 'images'             = ANY(v_locked) THEN p.images             ELSE COALESCE(s.images,             p.images)             END,
    ncm_code           = CASE WHEN 'ncm_code'           = ANY(v_locked) THEN p.ncm_code           ELSE COALESCE(s.ncm_code,           p.ncm_code)           END,
    weight_g           = CASE WHEN 'weight_g'           = ANY(v_locked) THEN p.weight_g           ELSE COALESCE(s.weight_g,           p.weight_g)           END,
    height_cm          = CASE WHEN 'height_cm'          = ANY(v_locked) THEN p.height_cm          ELSE COALESCE(s.height_cm,          p.height_cm)          END,
    width_cm           = CASE WHEN 'width_cm'           = ANY(v_locked) THEN p.width_cm           ELSE COALESCE(s.width_cm,           p.width_cm)           END,
    length_cm          = CASE WHEN 'length_cm'          = ANY(v_locked) THEN p.length_cm          ELSE COALESCE(s.length_cm,          p.length_cm)          END,
    dimensions_display = CASE WHEN 'dimensions_display' = ANY(v_locked) THEN p.dimensions_display ELSE COALESCE(s.dimensions_display, p.dimensions_display) END,
    box_length_cm      = CASE WHEN 'box_length_cm'      = ANY(v_locked) THEN p.box_length_cm      ELSE COALESCE(s.box_length_cm,      p.box_length_cm)      END,
    box_width_cm       = CASE WHEN 'box_width_cm'       = ANY(v_locked) THEN p.box_width_cm       ELSE COALESCE(s.box_width_cm,       p.box_width_cm)       END,
    box_height_cm      = CASE WHEN 'box_height_cm'      = ANY(v_locked) THEN p.box_height_cm      ELSE COALESCE(s.box_height_cm,      p.box_height_cm)      END,
    box_weight_kg      = CASE WHEN 'box_weight_kg'      = ANY(v_locked) THEN p.box_weight_kg      ELSE COALESCE(s.box_weight_kg,      p.box_weight_kg)      END,
    box_volume_cm3     = CASE WHEN 'box_volume_cm3'     = ANY(v_locked) THEN p.box_volume_cm3     ELSE COALESCE(s.box_volume_cm3,     p.box_volume_cm3)     END,
    box_quantity       = CASE WHEN 'box_quantity'       = ANY(v_locked) THEN p.box_quantity       ELSE COALESCE(s.box_quantity,       p.box_quantity)       END,
    box_inner_quantity = CASE WHEN 'box_inner_quantity' = ANY(v_locked) THEN p.box_inner_quantity ELSE COALESCE(s.box_inner_quantity, p.box_inner_quantity) END,
    brand              = CASE WHEN 'brand'              = ANY(v_locked) THEN p.brand              ELSE COALESCE(s.brand,              p.brand)              END,
    packing_type       = CASE WHEN 'packing_type'       = ANY(v_locked) THEN p.packing_type       ELSE COALESCE(s.packing_type,       p.packing_type)       END,
    repacking_type     = CASE WHEN 'repacking_type'     = ANY(v_locked) THEN p.repacking_type     ELSE COALESCE(s.repacking_type,     p.repacking_type)     END,
    capacities         = CASE WHEN 'capacities'         = ANY(v_locked) THEN p.capacities         ELSE COALESCE(s.capacities,         p.capacities)         END,
    capacity_ml        = CASE WHEN 'capacity_ml'        = ANY(v_locked) THEN p.capacity_ml        ELSE COALESCE(s.capacity_ml,        p.capacity_ml)        END,
    min_quantity       = CASE WHEN 'min_quantity'       = ANY(v_locked) THEN p.min_quantity       ELSE COALESCE(s.min_quantity,       p.min_quantity)       END,
    warranty_months    = CASE WHEN 'warranty_months'    = ANY(v_locked) THEN p.warranty_months    ELSE COALESCE(s.warranty_months,    p.warranty_months)    END,
    ipi_rate           = CASE WHEN 'ipi_rate'           = ANY(v_locked) THEN p.ipi_rate           ELSE COALESCE(s.ipi_rate,           p.ipi_rate)           END,
    engraving_type     = CASE WHEN 'engraving_type'     = ANY(v_locked) THEN p.engraving_type     ELSE COALESCE(s.engraving_type,     p.engraving_type)     END,
    colors             = CASE WHEN 'colors'             = ANY(v_locked) THEN p.colors             ELSE COALESCE(s.colors,             p.colors)             END,
    origin_country         = CASE WHEN 'origin_country'         = ANY(v_locked) THEN p.origin_country         ELSE COALESCE(s.origin_country,         p.origin_country)         END,
    combined_sizes         = CASE WHEN 'combined_sizes'         = ANY(v_locked) THEN p.combined_sizes         ELSE COALESCE(s.combined_sizes,         p.combined_sizes)         END,
    box_image              = CASE WHEN 'box_image'              = ANY(v_locked) THEN p.box_image              ELSE COALESCE(s.box_image,              p.box_image)              END,
    is_textil              = CASE WHEN 'is_textil'              = ANY(v_locked) THEN p.is_textil              ELSE COALESCE(s.is_textil,              p.is_textil)              END,
    is_stockout            = CASE WHEN 'is_stockout'            = ANY(v_locked) THEN p.is_stockout            ELSE COALESCE(s.is_stockout,            p.is_stockout)            END,
    is_online_exclusive    = CASE WHEN 'is_online_exclusive'    = ANY(v_locked) THEN p.is_online_exclusive    ELSE COALESCE(s.is_online_exclusive,    p.is_online_exclusive)    END,
    is_new                 = CASE WHEN 'is_new'                 = ANY(v_locked) THEN p.is_new                 ELSE COALESCE(s.is_new,                 p.is_new)                 END,
    has_colors             = CASE WHEN 'has_colors'             = ANY(v_locked) THEN p.has_colors             ELSE COALESCE(s.has_colors,             p.has_colors)             END,
    has_sizes              = CASE WHEN 'has_sizes'              = ANY(v_locked) THEN p.has_sizes              ELSE COALESCE(s.has_sizes,              p.has_sizes)              END,
    allows_personalization = CASE WHEN 'allows_personalization' = ANY(v_locked) THEN p.allows_personalization ELSE COALESCE(s.allows_personalization, p.allows_personalization) END,
    tags                   = CASE WHEN 'tags'                   = ANY(v_locked) THEN p.tags                   ELSE COALESCE(s.tags,                   p.tags)                   END,
    materials              = CASE WHEN 'materials'              = ANY(v_locked) THEN p.materials              ELSE COALESCE(s.materials,              p.materials)              END,
    meta_keywords          = CASE WHEN 'meta_keywords'          = ANY(v_locked) THEN p.meta_keywords          ELSE COALESCE(s.meta_keywords,          p.meta_keywords)          END,
    -- ── NOVO: categoria via De→Para ────────────────────────────────────────
    -- Se De→Para retornou um category_id → usa-o (mais confiável que keywords).
    -- Se não encontrou → preserva o existente (trigger de keywords mantém).
    -- locked_fields sempre tem precedência absoluta.
    category_id            = CASE
      WHEN 'category_id' = ANY(v_locked) THEN p.category_id
      WHEN v_cat_id IS NOT NULL           THEN v_cat_id
      ELSE                                     p.category_id
    END,
    last_sync_at          = now(),
    last_sync_supplier_id = s.supplier_id,
    supplier_updated_at   = now()
  WHERE p.id = v_pid;

  -- ── Atualizar Silver e Bronze ──────────────────────────────────────────────
  UPDATE public.produtos_padronizacao
     SET status='promoted', promoted_at=now(), product_id=v_pid
   WHERE id = p_id;

  IF s.raw_id IS NOT NULL THEN
    UPDATE public.supplier_products_raw
       SET status='processed', processed_at=now(), product_id=v_pid, process_errors=NULL
     WHERE id = s.raw_id;
    PERFORM public.fn_sync_single_product_dimensions(
              v_pid, (SELECT raw_data FROM public.supplier_products_raw WHERE id = s.raw_id));
  END IF;

  RETURN jsonb_build_object(
    'success',          true,
    'product_id',       v_pid,
    'created',          v_is_new,
    'locked_preserved', v_locked,
    'category_depara',  CASE WHEN v_cat_id IS NOT NULL
                             THEN jsonb_build_object('category_id', v_cat_id, 'l1_raw', v_cat_l1)
                             ELSE 'null'::jsonb END
  );
END;
$fn$;;

-- <<< END 20260606144346_fn_promote_padronizacao_depara_category_2026.sql <<<

-- >>> BEGIN 20260606144549_widen_supplier_value_mappings_source_value_2026.sql >>>
-- Aumentar limite de source_value para suportar textos longos de técnicas
-- (limite atual de VARCHAR(100) é insuficiente para frases completas de técnica SM)
ALTER TABLE public.supplier_value_mappings
  ALTER COLUMN source_value TYPE varchar(512),
  ALTER COLUMN target_value TYPE varchar(256);;

-- <<< END 20260606144549_widen_supplier_value_mappings_source_value_2026.sql <<<

-- >>> BEGIN 20260606144922_fn_apply_transform_extract_keywords_lookup_2026.sql >>>
-- Adiciona case 'extract_keywords_lookup' ao fn_apply_transform custom section.
-- Varre supplier_value_mappings[field_type] buscando source_values como keywords no p_value (título).
-- Retorna jsonb TEXT[] de todos os matches — conecta supplier_value_mappings ao pipeline.
CREATE OR REPLACE FUNCTION public.fn_apply_transform(
  p_value          text,
  p_transform_type character varying,
  p_transform_config jsonb,
  p_source_unit    character varying,
  p_target_unit    character varying,
  p_supplier_id    uuid
)
RETURNS text
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $fn$
DECLARE
    v_result     TEXT;
    v_numeric    DECIMAL;
    v_multiplier DECIMAL;
    v_fn         VARCHAR;
    v_op         VARCHAR;
    v_pattern    TEXT;
    v_group      INTEGER;
    v_matches    TEXT[];
    v_max_length INTEGER;
    v_ftype      TEXT;
BEGIN
    IF p_value IS NULL OR TRIM(p_value) = '' THEN RETURN NULL; END IF;

    CASE p_transform_type

        WHEN 'direct' THEN
            v_result := p_value;

        WHEN 'multiply' THEN
            BEGIN
                v_multiplier := COALESCE((p_transform_config->>'multiplier')::DECIMAL,
                                         (p_transform_config->>'factor')::DECIMAL);
                IF v_multiplier IS NULL THEN RETURN p_value; END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM
                              TRIM(TRAILING '0' FROM
                                ROUND(v_numeric * v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'divide' THEN
            BEGIN
                v_multiplier := COALESCE((p_transform_config->>'divisor')::DECIMAL,
                                         (p_transform_config->>'factor')::DECIMAL);
                IF v_multiplier IS NULL OR v_multiplier = 0 THEN RETURN p_value; END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM
                              TRIM(TRAILING '0' FROM
                                ROUND(v_numeric / v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'convert_unit' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_result  := public.fn_convert_unit(v_numeric, p_source_unit, p_target_unit,
                                                    p_supplier_id)::TEXT;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        -- ── Lookup simples: supplier_value_mappings ─────────────────────────
        WHEN 'lookup' THEN
            v_result := public.fn_map_value(p_supplier_id,
                                            p_transform_config->>'lookup_type', p_value);

        -- ── Keyword scan: extrai todos os source_values que aparecem em p_value ──
        -- Ex: titulo "GARRAFA EM ALUMÍNIO BRANCO" → ["Alumínio"]
        -- Usa supplier_value_mappings[field_type='material' (ou outro)] como dicionário.
        WHEN 'extract_keywords_lookup' THEN
            BEGIN
                v_ftype := COALESCE(p_transform_config->>'field_type', 'material');
                SELECT to_jsonb(
                    COALESCE(
                        array_agg(DISTINCT svm.source_value ORDER BY svm.source_value)
                        FILTER (WHERE svm.source_value IS NOT NULL),
                        ARRAY[]::text[]
                    )
                )::TEXT
                INTO v_result
                FROM public.supplier_value_mappings svm
                WHERE svm.supplier_id = p_supplier_id
                  AND svm.field_type  = v_ftype
                  AND svm.is_active   = TRUE
                  AND UPPER(p_value)  LIKE '%' || UPPER(svm.source_value) || '%';

                -- Se não encontrou nenhum → null (não sobrescreve)
                IF v_result = '[]' OR v_result = 'null' THEN v_result := NULL; END IF;
            EXCEPTION WHEN OTHERS THEN v_result := NULL; END;

        WHEN 'custom' THEN
            BEGIN
                v_fn := p_transform_config->>'function';
                v_op := p_transform_config->>'op';
                CASE
                    WHEN v_fn = 'fn_parse_capacity_ml'           THEN v_result := public.fn_parse_capacity_ml(p_value)::TEXT;
                    WHEN v_fn = 'fn_convert_box_dimension_to_cm' THEN v_result := public.fn_convert_box_dimension_to_cm(p_value)::TEXT;
                    WHEN v_fn = 'fn_clean_spot_name'             THEN v_result := public.fn_clean_spot_name(p_value);
                    WHEN v_fn = 'fn_normalize_ncm'               THEN v_result := public.fn_normalize_ncm(p_value)::TEXT;
                    WHEN v_fn = 'fn_spot_split_list'             THEN v_result := public.fn_spot_split_list(p_value)::TEXT;
                    WHEN v_fn = 'fn_spot_image_list'             THEN v_result := public.fn_spot_image_list(
                                                                          p_value,
                                                                          COALESCE(p_transform_config->>'base',
                                                                                   'https://www.spotgifts.com.br/fotos/produtos/')
                                                                        )::TEXT;
                    WHEN v_op = 'array_url'  THEN v_result := jsonb_build_array(p_value)::TEXT;
                    WHEN v_op = 'is_present' THEN v_result := CASE WHEN NULLIF(TRIM(p_value),'') IS NOT NULL
                                                                    THEN 'true' ELSE 'false' END;
                    ELSE v_result := p_value;
                END CASE;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'cast_integer' THEN
            v_result := public.fn_safe_int(p_value)::TEXT;

        WHEN 'cast_decimal' THEN
            v_result := public.fn_safe_num(p_value)::TEXT;

        WHEN 'cast_datetime' THEN
            BEGIN
                v_result := CASE WHEN p_value ~ '^\d{4}-\d{2}-\d{2}'
                                 THEN LEFT(p_value, 10)
                                 ELSE NULL END;
            EXCEPTION WHEN OTHERS THEN v_result := NULL; END;

        WHEN 'cast_boolean' THEN
            v_result := public.fn_safe_bool(p_value)::TEXT;

        WHEN 'cast' THEN
            BEGIN
                v_result := CASE COALESCE(p_transform_config->>'to', 'text')
                    WHEN 'boolean' THEN public.fn_safe_bool(p_value)::TEXT
                    WHEN 'integer' THEN public.fn_safe_int(p_value)::TEXT
                    WHEN 'decimal' THEN public.fn_safe_num(p_value)::TEXT
                    ELSE p_value
                END;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'split_pipe' THEN
            v_result := (
                SELECT to_jsonb(
                    COALESCE(
                        array_agg(BTRIM(e)) FILTER (WHERE BTRIM(e) <> ''),
                        ARRAY[]::text[]
                    )
                )::TEXT
                FROM unnest(string_to_array(p_value,
                     COALESCE(p_transform_config->>'delimiter', ','))) AS e
            );

        WHEN 'prefix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'prefix' IS NOT NULL THEN
                v_result := (p_transform_config->>'prefix') || p_value;
            ELSE v_result := p_value; END IF;

        WHEN 'suffix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'suffix' IS NOT NULL THEN
                v_result := p_value || (p_transform_config->>'suffix');
            ELSE v_result := p_value; END IF;

        WHEN 'uppercase' THEN v_result := UPPER(p_value);
        WHEN 'lowercase' THEN v_result := LOWER(p_value);
        WHEN 'trim'      THEN v_result := BTRIM(p_value);

        WHEN 'replace' THEN
            IF p_transform_config IS NOT NULL THEN
                v_result := REPLACE(p_value,
                    COALESCE(p_transform_config->>'find',''),
                    COALESCE(p_transform_config->>'replace',''));
            ELSE v_result := p_value; END IF;

        WHEN 'regex_extract' THEN
            BEGIN
                v_pattern := p_transform_config->>'pattern';
                v_group   := COALESCE((p_transform_config->>'group')::INTEGER, 1);
                IF v_pattern IS NULL THEN RETURN p_value; END IF;
                v_matches := regexp_matches(p_value, v_pattern);
                IF array_length(v_matches, 1) >= v_group THEN v_result := v_matches[v_group];
                ELSE v_result := NULL; END IF;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        -- Transformações dimensionais (dim_to_cm) — com suporte a símbolo Ø
        WHEN 'dim_to_cm' THEN
            BEGIN
                DECLARE
                    v_dim_str TEXT := TRIM(p_value);
                    v_src_unit TEXT := LOWER(COALESCE(p_source_unit, 'cm'));
                    v_divisor DECIMAL := CASE v_src_unit WHEN 'mm' THEN 10 WHEN 'm' THEN 0.01 ELSE 1 END;
                    v_parts TEXT[];
                    v_h DECIMAL; v_w DECIMAL; v_l DECIMAL;
                    v_rx TEXT := '[Ø∅Oo]?(\d+(?:[.,]\d+)?)';
                BEGIN
                    v_dim_str := REGEXP_REPLACE(v_dim_str, '\s*(mm|cm|m)\s*(?:\(.*?\))?$', '', 'i');
                    v_dim_str := TRIM(v_dim_str);
                    IF v_dim_str ~ '(?i)^[Ø∅Oo]?\d' THEN
                        v_matches := REGEXP_MATCHES(v_dim_str,
                          '(?i)' || v_rx || '(?:\s*[xX]\s*' || v_rx || ')?(?:\s*[xX]\s*' || v_rx || ')?');
                        IF v_matches IS NOT NULL THEN
                            v_h := REPLACE(v_matches[1], ',', '.')::DECIMAL / v_divisor;
                            v_w := CASE WHEN v_matches[2] IS NOT NULL
                                        THEN REPLACE(v_matches[2], ',', '.')::DECIMAL / v_divisor END;
                            v_l := CASE WHEN v_matches[3] IS NOT NULL
                                        THEN REPLACE(v_matches[3], ',', '.')::DECIMAL / v_divisor END;
                            IF v_h = 0 AND (v_w IS NULL OR v_w = 0) THEN
                                v_result := NULL;
                            ELSE
                                v_result := jsonb_build_object(
                                    'h', ROUND(v_h, 2),
                                    'w', CASE WHEN v_w IS NOT NULL THEN ROUND(v_w, 2) END,
                                    'l', CASE WHEN v_l IS NOT NULL THEN ROUND(v_l, 2) END
                                )::TEXT;
                            END IF;
                        END IF;
                    END IF;
                EXCEPTION WHEN OTHERS THEN v_result := NULL; END;
            END;

        ELSE v_result := p_value;
    END CASE;

    -- Truncar ao max_length configurado
    IF v_result IS NOT NULL AND p_transform_config IS NOT NULL
       AND (p_transform_config->>'max_length') IS NOT NULL THEN
        v_max_length := (p_transform_config->>'max_length')::INTEGER;
        IF v_max_length > 0 AND length(v_result) > v_max_length THEN
            v_result := LEFT(v_result, v_max_length);
        END IF;
    END IF;

    RETURN v_result;
END;
$fn$;;

-- <<< END 20260606144922_fn_apply_transform_extract_keywords_lookup_2026.sql <<<

-- >>> BEGIN 20260606155230_fix_promote_variants_stock_coalesce_zero.sql >>>

-- ============================================================
-- FIX: fn_promote_variants_of_parent
-- Problema: COALESCE(pv.stock_quantity, 0) nos INSERTs
-- converte NULL do Silver em 0, que o ON CONFLICT COALESCE
-- não consegue distinguir de "zero real" → destrói estoque Gold.
--
-- Regra correta:
--   Silver NULL  → passa NULL → ON CONFLICT preserva Gold existente
--   Silver 0     → passa 0   → ON CONFLICT escreve 0 (zero genuíno)
--   Silver 1862  → passa 1862→ ON CONFLICT escreve 1862
-- ============================================================
DO $$
DECLARE
  v_body text;
  v_body_after text;
BEGIN
  SELECT pg_get_functiondef(p.oid) INTO v_body
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'fn_promote_variants_of_parent'
    AND pg_get_function_arguments(p.oid) = 'p_supplier_id uuid, p_parent_reference text';

  IF v_body IS NULL THEN
    RAISE EXCEPTION 'fn_promote_variants_of_parent não encontrada';
  END IF;

  -- ── Bug 1 (pos ~1786): INSERT product_variants ──────────────────
  -- "COALESCE(pv.stock_quantity,0), COALESCE(pv.is_active,true)"
  v_body_after := replace(v_body,
    'COALESCE(pv.stock_quantity,0), COALESCE(pv.is_active,true)',
    'pv.stock_quantity, COALESCE(pv.is_active,true)'
  );

  IF v_body_after = v_body THEN
    RAISE EXCEPTION 'Bug 1 (product_variants stock) NÃO encontrado — string não coincide';
  END IF;

  -- ── Bug 2 (pos ~4385): INSERT variant_supplier_sources ──────────
  -- "COALESCE(pv.stock_quantity, 0), COALESCE(pv.stock_quantity, 0),"
  v_body_after := replace(v_body_after,
    'COALESCE(pv.stock_quantity, 0), COALESCE(pv.stock_quantity, 0),',
    'pv.stock_quantity, pv.stock_quantity,'
  );

  IF v_body_after = replace(v_body,
      'COALESCE(pv.stock_quantity,0), COALESCE(pv.is_active,true)',
      'pv.stock_quantity, COALESCE(pv.is_active,true)') THEN
    RAISE EXCEPTION 'Bug 2 (VSS stock) NÃO encontrado — string não coincide';
  END IF;

  -- Substitui CREATE OR REPLACE FUNCTION por só o corpo para re-executar
  EXECUTE v_body_after;

  RAISE NOTICE 'fn_promote_variants_of_parent corrigida: 2 COALESCE(stock,0) removidos';
END;
$$;
;

-- <<< END 20260606155230_fix_promote_variants_stock_coalesce_zero.sql <<<

-- >>> BEGIN 20260606155345_widen_transform_type_drop_recreate_view_2026.sql >>>
-- Salvar definição da view, alterar coluna, recriar view
DO $$
DECLARE v_def text;
BEGIN
  SELECT pg_get_viewdef('vw_supplier_field_mappings_summary'::regclass, true)
  INTO v_def;
  EXECUTE 'DROP VIEW IF EXISTS vw_supplier_field_mappings_summary CASCADE';
  EXECUTE 'ALTER TABLE public.supplier_field_mappings ALTER COLUMN transform_type TYPE varchar(50)';
  EXECUTE 'CREATE OR REPLACE VIEW vw_supplier_field_mappings_summary AS ' || v_def;
END $$;;

