-- >>> BEGIN 20260606155425_fn_upsert_stock_to_bronze_and_sync.sql >>>

-- ============================================================
-- FN 1: fn_upsert_stock_to_bronze
-- Recebe array de itens de estoque do feed SPOT (spot_ws_stocks)
-- e grava em supplier_products_raw.stock_data (Bronze).
-- NUNCA escreve em Silver ou Gold — só Bronze.
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_upsert_stock_to_bronze(
  p_supplier_id uuid,
  p_items       jsonb   -- array [{Sku, Quantity, NextQuantity1..6, NextDate1..6, ...}]
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_item       jsonb;
  v_sku        text;
  v_updated    int := 0;
  v_not_found  int := 0;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_sku := v_item->>'Sku';
    IF v_sku IS NULL OR v_sku = '' THEN CONTINUE; END IF;

    UPDATE public.supplier_products_raw
    SET
      stock_data = v_item,
      updated_at = now()
    WHERE supplier_id  = p_supplier_id
      AND supplier_sku = v_sku;

    IF FOUND THEN
      v_updated := v_updated + 1;
    ELSE
      v_not_found := v_not_found + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'updated',    v_updated,
    'not_found',  v_not_found,
    'total',      jsonb_array_length(p_items)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_upsert_stock_to_bronze(uuid, jsonb) FROM public, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.fn_upsert_stock_to_bronze(uuid, jsonb) TO service_role;


-- ============================================================
-- FN 2: fn_sync_stock_bronze_to_gold
-- Lê stock_data do Bronze → atualiza stock fields no Silver
-- → propaga stock fields para o Gold.
-- É o caminho CANÔNICO de estoque: Bronze → Silver → Gold.
-- NÃO recalcula preços, dimensões nem outros campos.
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_sync_stock_bronze_to_gold(
  p_supplier_id uuid,
  p_parent_ref  text DEFAULT NULL  -- NULL = todos os refs deste fornecedor
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_silver_updated int;
  v_gold_updated   int;
BEGIN
  -- ── PASSO 1: Bronze stock_data → Silver ──────────────────────────────────
  -- Atualiza SOMENTE os campos de estoque no Silver
  -- Fonte: supplier_products_raw.stock_data (Bronze)
  UPDATE public.produtos_padronizacao_variantes ppv
  SET
    stock_quantity  = public.fn_safe_int(spr.stock_data->>'Quantity'),
    next_quantity_1 = NULLIF(public.fn_safe_int(spr.stock_data->>'NextQuantity1'), 0),
    next_quantity_2 = NULLIF(public.fn_safe_int(spr.stock_data->>'NextQuantity2'), 0),
    next_quantity_3 = NULLIF(public.fn_safe_int(spr.stock_data->>'NextQuantity3'), 0),
    next_date_1     = NULLIF(spr.stock_data->>'NextDate1', '')::date,
    next_date_2     = NULLIF(spr.stock_data->>'NextDate2', '')::date,
    next_date_3     = NULLIF(spr.stock_data->>'NextDate3', '')::date,
    updated_at      = now()
  FROM public.supplier_products_raw spr
  WHERE ppv.raw_id      = spr.id
    AND ppv.supplier_id = p_supplier_id
    AND spr.supplier_id = p_supplier_id
    AND spr.stock_data  IS NOT NULL
    AND (p_parent_ref IS NULL OR ppv.parent_reference = p_parent_ref);

  GET DIAGNOSTICS v_silver_updated = ROW_COUNT;

  -- ── PASSO 2: Silver → Gold (VSS) ─────────────────────────────────────────
  -- Propaga stock_quantity e lotes 1-3 do Silver para o Gold
  -- COALESCE garante que VSS sem Silver ainda preserva valor existente
  UPDATE public.variant_supplier_sources vss
  SET
    quantity             = COALESCE(ppv.stock_quantity, vss.quantity),
    stock_main_warehouse = COALESCE(ppv.stock_quantity, vss.stock_main_warehouse),
    next_quantity_1      = COALESCE(ppv.next_quantity_1, vss.next_quantity_1),
    next_quantity_2      = COALESCE(ppv.next_quantity_2, vss.next_quantity_2),
    next_quantity_3      = COALESCE(ppv.next_quantity_3, vss.next_quantity_3),
    next_date_1          = COALESCE(ppv.next_date_1, vss.next_date_1),
    next_date_2          = COALESCE(ppv.next_date_2, vss.next_date_2),
    next_date_3          = COALESCE(ppv.next_date_3, vss.next_date_3),
    last_synced_at       = now(),
    source               = 'silver',
    updated_at           = now()
  FROM public.produtos_padronizacao_variantes ppv
  WHERE vss.variant_id  = ppv.variant_id
    AND vss.supplier_id = ppv.supplier_id
    AND ppv.supplier_id = p_supplier_id
    AND ppv.stock_quantity IS NOT NULL
    AND (p_parent_ref IS NULL OR ppv.parent_reference = p_parent_ref);

  GET DIAGNOSTICS v_gold_updated = ROW_COUNT;

  RETURN jsonb_build_object(
    'silver_updated', v_silver_updated,
    'gold_updated',   v_gold_updated,
    'supplier_id',    p_supplier_id,
    'parent_ref',     p_parent_ref
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_sync_stock_bronze_to_gold(uuid, text) FROM public, anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.fn_sync_stock_bronze_to_gold(uuid, text) TO service_role;
;

-- <<< END 20260606155425_fn_upsert_stock_to_bronze_and_sync.sql <<<

-- >>> BEGIN 20260606155547_fn_apply_transform_fix_keywords_distinct_target_2026.sql >>>
-- Corrigir extract_keywords_lookup: agregar target_value DISTINCT (nomes canônicos)
-- em vez de source_value (aliases). Assim "Inox", "Aço Inox", "Inoxidável" → ["Aço Inoxidável"]
CREATE OR REPLACE FUNCTION public.fn_apply_transform(
  p_value          text,
  p_transform_type character varying,
  p_transform_config jsonb,
  p_source_unit    character varying,
  p_target_unit    character varying,
  p_supplier_id    uuid
)
RETURNS text
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $fn$
DECLARE
    v_result     TEXT;
    v_numeric    DECIMAL;
    v_multiplier DECIMAL;
    v_fn         VARCHAR;
    v_op         VARCHAR;
    v_pattern    TEXT;
    v_group      INTEGER;
    v_matches    TEXT[];
    v_max_length INTEGER;
    v_ftype      TEXT;
BEGIN
    IF p_value IS NULL OR TRIM(p_value) = '' THEN RETURN NULL; END IF;

    CASE p_transform_type

        WHEN 'direct' THEN v_result := p_value;

        WHEN 'multiply' THEN
            BEGIN
                v_multiplier := COALESCE((p_transform_config->>'multiplier')::DECIMAL,
                                         (p_transform_config->>'factor')::DECIMAL);
                IF v_multiplier IS NULL THEN RETURN p_value; END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM
                              ROUND(v_numeric * v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'divide' THEN
            BEGIN
                v_multiplier := COALESCE((p_transform_config->>'divisor')::DECIMAL,
                                         (p_transform_config->>'factor')::DECIMAL);
                IF v_multiplier IS NULL OR v_multiplier = 0 THEN RETURN p_value; END IF;
                v_numeric := p_value::DECIMAL;
                v_result := TRIM(TRAILING '.' FROM TRIM(TRAILING '0' FROM
                              ROUND(v_numeric / v_multiplier, 4)::TEXT));
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'convert_unit' THEN
            BEGIN
                v_numeric := p_value::DECIMAL;
                v_result  := public.fn_convert_unit(v_numeric, p_source_unit, p_target_unit,
                                                    p_supplier_id)::TEXT;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'lookup' THEN
            v_result := public.fn_map_value(p_supplier_id,
                                            p_transform_config->>'lookup_type', p_value);

        -- ── Keyword scan: extrai nomes CANÔNICOS (target_value DISTINCT) ─────
        -- Varre supplier_value_mappings[field_type] buscando aliases no p_value.
        -- Ex: "GARRAFA INOX COM BAMBU" → ["Aço Inoxidável","Bambu"] (deduplicado por target_value)
        WHEN 'extract_keywords_lookup' THEN
            BEGIN
                v_ftype := COALESCE(p_transform_config->>'field_type', 'material');
                SELECT to_jsonb(
                    COALESCE(
                        array_agg(DISTINCT svm.target_value ORDER BY svm.target_value)
                        FILTER (WHERE svm.target_value IS NOT NULL),
                        ARRAY[]::text[]
                    )
                )::TEXT
                INTO v_result
                FROM public.supplier_value_mappings svm
                WHERE svm.supplier_id = p_supplier_id
                  AND svm.field_type  = v_ftype
                  AND svm.is_active   = TRUE
                  AND UPPER(p_value)  LIKE '%' || UPPER(svm.source_value) || '%';

                IF v_result IS NULL OR v_result = '[]' OR v_result = 'null' THEN
                  v_result := NULL;
                END IF;
            EXCEPTION WHEN OTHERS THEN v_result := NULL; END;

        WHEN 'custom' THEN
            BEGIN
                v_fn := p_transform_config->>'function';
                v_op := p_transform_config->>'op';
                CASE
                    WHEN v_fn = 'fn_parse_capacity_ml'           THEN v_result := public.fn_parse_capacity_ml(p_value)::TEXT;
                    WHEN v_fn = 'fn_convert_box_dimension_to_cm' THEN v_result := public.fn_convert_box_dimension_to_cm(p_value)::TEXT;
                    WHEN v_fn = 'fn_clean_spot_name'             THEN v_result := public.fn_clean_spot_name(p_value);
                    WHEN v_fn = 'fn_normalize_ncm'               THEN v_result := public.fn_normalize_ncm(p_value)::TEXT;
                    WHEN v_fn = 'fn_spot_split_list'             THEN v_result := public.fn_spot_split_list(p_value)::TEXT;
                    WHEN v_fn = 'fn_spot_image_list'             THEN v_result := public.fn_spot_image_list(
                                                                          p_value,
                                                                          COALESCE(p_transform_config->>'base',
                                                                                   'https://www.spotgifts.com.br/fotos/produtos/')
                                                                        )::TEXT;
                    WHEN v_op = 'array_url'  THEN v_result := jsonb_build_array(p_value)::TEXT;
                    WHEN v_op = 'is_present' THEN v_result := CASE WHEN NULLIF(TRIM(p_value),'') IS NOT NULL
                                                                    THEN 'true' ELSE 'false' END;
                    ELSE v_result := p_value;
                END CASE;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'cast_integer'  THEN v_result := public.fn_safe_int(p_value)::TEXT;
        WHEN 'cast_decimal'  THEN v_result := public.fn_safe_num(p_value)::TEXT;

        WHEN 'cast_datetime' THEN
            BEGIN
                v_result := CASE WHEN p_value ~ '^\d{4}-\d{2}-\d{2}'
                                 THEN LEFT(p_value, 10) ELSE NULL END;
            EXCEPTION WHEN OTHERS THEN v_result := NULL; END;

        WHEN 'cast_boolean'  THEN v_result := public.fn_safe_bool(p_value)::TEXT;

        WHEN 'cast' THEN
            BEGIN
                v_result := CASE COALESCE(p_transform_config->>'to', 'text')
                    WHEN 'boolean' THEN public.fn_safe_bool(p_value)::TEXT
                    WHEN 'integer' THEN public.fn_safe_int(p_value)::TEXT
                    WHEN 'decimal' THEN public.fn_safe_num(p_value)::TEXT
                    ELSE p_value
                END;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'split_pipe' THEN
            v_result := (
                SELECT to_jsonb(COALESCE(
                    array_agg(BTRIM(e)) FILTER (WHERE BTRIM(e) <> ''),
                    ARRAY[]::text[]))::TEXT
                FROM unnest(string_to_array(p_value,
                     COALESCE(p_transform_config->>'delimiter', ','))) AS e
            );

        WHEN 'prefix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'prefix' IS NOT NULL THEN
                v_result := (p_transform_config->>'prefix') || p_value;
            ELSE v_result := p_value; END IF;

        WHEN 'suffix' THEN
            IF p_transform_config IS NOT NULL AND p_transform_config->>'suffix' IS NOT NULL THEN
                v_result := p_value || (p_transform_config->>'suffix');
            ELSE v_result := p_value; END IF;

        WHEN 'uppercase' THEN v_result := UPPER(p_value);
        WHEN 'lowercase' THEN v_result := LOWER(p_value);
        WHEN 'trim'      THEN v_result := BTRIM(p_value);

        WHEN 'replace' THEN
            IF p_transform_config IS NOT NULL THEN
                v_result := REPLACE(p_value,
                    COALESCE(p_transform_config->>'find',''),
                    COALESCE(p_transform_config->>'replace',''));
            ELSE v_result := p_value; END IF;

        WHEN 'regex_extract' THEN
            BEGIN
                v_pattern := p_transform_config->>'pattern';
                v_group   := COALESCE((p_transform_config->>'group')::INTEGER, 1);
                IF v_pattern IS NULL THEN RETURN p_value; END IF;
                v_matches := regexp_matches(p_value, v_pattern);
                IF array_length(v_matches, 1) >= v_group THEN v_result := v_matches[v_group];
                ELSE v_result := NULL; END IF;
            EXCEPTION WHEN OTHERS THEN v_result := p_value; END;

        WHEN 'dim_to_cm' THEN
            BEGIN
                DECLARE
                    v_dim_str TEXT := TRIM(p_value);
                    v_src_unit TEXT := LOWER(COALESCE(p_source_unit, 'cm'));
                    v_divisor DECIMAL := CASE v_src_unit WHEN 'mm' THEN 10 WHEN 'm' THEN 0.01 ELSE 1 END;
                    v_h DECIMAL; v_w DECIMAL; v_l DECIMAL;
                    v_rx TEXT := '[Ø∅Oo]?(\d+(?:[.,]\d+)?)';
                BEGIN
                    v_dim_str := REGEXP_REPLACE(v_dim_str, '\s*(mm|cm|m)\s*(?:\(.*?\))?$', '', 'i');
                    v_dim_str := TRIM(v_dim_str);
                    IF v_dim_str ~ '(?i)^[Ø∅Oo]?\d' THEN
                        v_matches := REGEXP_MATCHES(v_dim_str,
                          '(?i)' || v_rx || '(?:\s*[xX]\s*' || v_rx || ')?(?:\s*[xX]\s*' || v_rx || ')?');
                        IF v_matches IS NOT NULL THEN
                            v_h := REPLACE(v_matches[1], ',', '.')::DECIMAL / v_divisor;
                            v_w := CASE WHEN v_matches[2] IS NOT NULL
                                        THEN REPLACE(v_matches[2], ',', '.')::DECIMAL / v_divisor END;
                            v_l := CASE WHEN v_matches[3] IS NOT NULL
                                        THEN REPLACE(v_matches[3], ',', '.')::DECIMAL / v_divisor END;
                            IF v_h = 0 AND (v_w IS NULL OR v_w = 0) THEN
                                v_result := NULL;
                            ELSE
                                v_result := jsonb_build_object(
                                    'h', ROUND(v_h, 2),
                                    'w', CASE WHEN v_w IS NOT NULL THEN ROUND(v_w, 2) END,
                                    'l', CASE WHEN v_l IS NOT NULL THEN ROUND(v_l, 2) END
                                )::TEXT;
                            END IF;
                        END IF;
                    END IF;
                EXCEPTION WHEN OTHERS THEN v_result := NULL; END;
            END;

        ELSE v_result := p_value;
    END CASE;

    IF v_result IS NOT NULL AND p_transform_config IS NOT NULL
       AND (p_transform_config->>'max_length') IS NOT NULL THEN
        v_max_length := (p_transform_config->>'max_length')::INTEGER;
        IF v_max_length > 0 AND length(v_result) > v_max_length THEN
            v_result := LEFT(v_result, v_max_length);
        END IF;
    END IF;

    RETURN v_result;
END;
$fn$;;

-- <<< END 20260606155547_fn_apply_transform_fix_keywords_distinct_target_2026.sql <<<

-- >>> BEGIN 20260606155703_fn_site_promote_to_gold_blocos_e_f_g_h.sql >>>
CREATE OR REPLACE FUNCTION public.fn_site_promote_to_gold(
  p_supplier uuid    DEFAULT 'd6718a29-e954-4c1b-bd84-03ea24884900'::uuid,
  p_limit    integer DEFAULT NULL::integer,
  p_only_new boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $func$
DECLARE
  v_org_id    uuid    := '5db5aee1-064b-4ef4-9193-345dcd8274ea';
  v_linked    integer := 0;
  v_phys_a    integer := 0;
  v_phys_e    integer := 0;
  v_props_b   integer := 0;
  v_props_f   integer := 0;
  v_rel       integer := 0;
  v_xcat      integer := 0;
  v_imgs      integer := 0;
  v_vids      integer := 0;
  v_promoted  integer := 0;
BEGIN

  -- 0. Vincular product_id para linhas sem link
  WITH lnk AS (
    SELECT s.id, p.product_id
    FROM public.produtos_site_padronizacao s
    JOIN public.produtos_padronizacao p
      ON p.supplier_id = s.supplier_id
     AND p.supplier_reference = s.supplier_reference
    WHERE s.supplier_id = p_supplier
      AND p.product_id IS NOT NULL
      AND s.product_id IS NULL
      AND s.status <> 'rejected'
  )
  UPDATE public.produtos_site_padronizacao t
     SET product_id = lnk.product_id, updated_at = now()
    FROM lnk WHERE t.id = lnk.id;
  GET DIAGNOSTICS v_linked = ROW_COUNT;

  -- Escopo de trabalho (SELECT s.* traz TODAS as colunas)
  CREATE TEMP TABLE _scope ON COMMIT DROP AS
    SELECT s.*
    FROM public.produtos_site_padronizacao s
    WHERE s.supplier_id = p_supplier
      AND s.product_id  IS NOT NULL
      AND s.status = CASE WHEN p_only_new
                          THEN 'standardized'::public.produtos_padronizacao_status
                          ELSE s.status END
      AND s.status <> 'rejected'
    LIMIT COALESCE(p_limit, 1000000000);

  IF NOT EXISTS (SELECT 1 FROM _scope) THEN
    RETURN jsonb_build_object('linked', v_linked, 'note', 'nada_novo');
  END IF;

  -- (a) product_physical: diameter gap-fill
  INSERT INTO public.product_physical (product_id, diameter_cm)
  SELECT product_id, diameter_cm FROM _scope WHERE diameter_cm IS NOT NULL
  ON CONFLICT (product_id) DO UPDATE
    SET diameter_cm = COALESCE(public.product_physical.diameter_cm, EXCLUDED.diameter_cm),
        updated_at  = now();
  GET DIAGNOSTICS v_phys_a = ROW_COUNT;

  -- (b) product_properties: atributos site + extratores
  INSERT INTO public.product_properties (product_id, property_code, property_value, source, raw_value)
  SELECT s.product_id, kv.code, kv.val, kv.src, kv.val
  FROM _scope s
  CROSS JOIN LATERAL (VALUES
    ('site_ficha_tecnica_pdf',
        s.datasheet_pdf_url,                                                     'xbz_site'),
    ('site_modo_de_uso',
        s.usage_instructions,                                                    'xbz_site'),
    ('site_disclaimer',
        s.disclaimer,                                                            'xbz_site'),
    ('circumference_cm',
        s.circumference_cm::text,                                                'xbz_site'),
    ('site_categoria_path',
        (SELECT string_agg(c->>'nome', ' > ' ORDER BY (c->>'nivel')::int)
           FROM jsonb_array_elements(COALESCE(s.categories, '[]'::jsonb)) c),   'xbz_site'),
    ('site_url',
        s.source_url,                                                            'xbz_site'),
    ('material_xbz_primary',
        NULLIF(public.extract_xbz_material_primary(
          upper(COALESCE(s.name,'')), upper(COALESCE(s.description,''))), ''),  'xbz_extractor')
  ) AS kv(code, val, src)
  WHERE kv.val IS NOT NULL AND btrim(kv.val) <> ''
  ON CONFLICT (product_id, property_code) DO UPDATE
    SET property_value = EXCLUDED.property_value,
        raw_value      = EXCLUDED.raw_value,
        source         = EXCLUDED.source,
        updated_at     = now();
  GET DIAGNOSTICS v_props_b = ROW_COUNT;

  -- (c) product_relationships
  INSERT INTO public.product_relationships
    (product_id, related_product_id, relationship_type, is_active)
  SELECT DISTINCT s.product_id, rp.product_id, 'related', true
  FROM _scope s
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(s.related_references, '[]'::jsonb)) rel
  JOIN public.produtos_padronizacao rp
    ON rp.supplier_id      = s.supplier_id
   AND rp.supplier_reference = rel->>'codigo'
   AND rp.product_id IS NOT NULL
  WHERE (rel->>'codigo') IS NOT NULL
    AND rp.product_id <> s.product_id
  ON CONFLICT (product_id, related_product_id, relationship_type) DO NOTHING;
  GET DIAGNOSTICS v_rel = ROW_COUNT;

  -- (d) product_category_assignments via classify_xbz_category
  INSERT INTO public.product_category_assignments
    (product_id, category_id, is_primary, display_order)
  SELECT DISTINCT s.product_id, xcat.category_id, false, 995
  FROM _scope s
  CROSS JOIN LATERAL public.classify_xbz_category(upper(COALESCE(s.name, ''))) xcat
  WHERE xcat.confidence IN ('high', 'medium')
    AND xcat.category_id IS NOT NULL
    AND xcat.category_name <> 'NÃO CLASSIFICADO'
    AND s.name IS NOT NULL
  ON CONFLICT (product_id, category_id) DO NOTHING;
  GET DIAGNOSTICS v_xcat = ROW_COUNT;

  -- (e) NOVO: product_physical — peso + dimensões (gap-fill, nunca sobrescreve API)
  INSERT INTO public.product_physical (product_id, weight_g, height_cm, width_cm, length_cm)
  SELECT product_id,
         weight_g::numeric,
         height_cm,
         width_cm,
         depth_cm
  FROM _scope
  WHERE weight_g IS NOT NULL
     OR height_cm IS NOT NULL
     OR width_cm  IS NOT NULL
     OR depth_cm  IS NOT NULL
  ON CONFLICT (product_id) DO UPDATE SET
    weight_g  = COALESCE(public.product_physical.weight_g,  EXCLUDED.weight_g),
    height_cm = COALESCE(public.product_physical.height_cm, EXCLUDED.height_cm),
    width_cm  = COALESCE(public.product_physical.width_cm,  EXCLUDED.width_cm),
    length_cm = COALESCE(public.product_physical.length_cm, EXCLUDED.length_cm),
    updated_at = now();
  GET DIAGNOSTICS v_phys_e = ROW_COUNT;

  -- (f) NOVO: product_properties — cores (swatches), gravação, vídeo
  INSERT INTO public.product_properties (product_id, property_code, property_value, source, raw_value)
  SELECT s.product_id, kv.code, kv.val, 'xbz_site', kv.val
  FROM _scope s
  CROSS JOIN LATERAL (VALUES
    ('site_cores_swatches',
        CASE WHEN jsonb_array_length(COALESCE(s.colors, '[]'::jsonb)) > 0
             THEN s.colors::text ELSE NULL END),
    ('gravacao_medida',          s.engraving_text),
    ('gravacao_comprimento_cm',  s.engraving_length_cm::text),
    ('gravacao_largura_cm',      s.engraving_width_cm::text),
    ('gravacao_local',           NULLIF(s.engraving_location, '')),
    ('site_video_youtube_id',
        CASE WHEN s.has_video AND s.video_embed_id IS NOT NULL
             THEN s.video_embed_id ELSE NULL END),
    ('site_video_watch_url',
        CASE WHEN s.has_video AND s.video_watch_url IS NOT NULL
             THEN s.video_watch_url ELSE NULL END)
  ) AS kv(code, val)
  WHERE kv.val IS NOT NULL AND btrim(kv.val) <> ''
  ON CONFLICT (product_id, property_code) DO UPDATE
    SET property_value = EXCLUDED.property_value,
        raw_value      = EXCLUDED.raw_value,
        updated_at     = now();
  GET DIAGNOSTICS v_props_f = ROW_COUNT;

  -- (g) NOVO: product_images — galeria completa do site
  INSERT INTO public.product_images (
    product_id, organization_id, url_original,
    is_primary, display_order, source_supplier, image_type, is_active
  )
  SELECT DISTINCT
    s.product_id,
    v_org_id,
    img->>'url_origem',
    (img->>'tipo' = 'principal'),
    (img->>'ordem')::integer,
    'xbz_site',
    CASE WHEN img->>'tipo' = 'principal' THEN 'product_primary' ELSE 'product_gallery' END,
    true
  FROM _scope s
  CROSS JOIN LATERAL jsonb_array_elements(COALESCE(s.images, '[]'::jsonb)) img
  WHERE (img->>'url_origem') IS NOT NULL
    AND btrim(img->>'url_origem') <> ''
    AND NOT EXISTS (
      SELECT 1 FROM public.product_images pi2
      WHERE pi2.product_id  = s.product_id
        AND pi2.url_original = img->>'url_origem'
    );
  GET DIAGNOSTICS v_imgs = ROW_COUNT;

  -- (h) NOVO: product_videos — YouTube via site
  INSERT INTO public.product_videos (
    product_id, organization_id, source_youtube_id,
    url_original, is_primary, source_supplier, is_active
  )
  SELECT
    s.product_id,
    v_org_id,
    s.video_embed_id,
    s.video_watch_url,
    true,
    'xbz_site',
    true
  FROM _scope s
  WHERE s.has_video = true
    AND s.video_embed_id IS NOT NULL
    AND btrim(s.video_embed_id) <> ''
    AND NOT EXISTS (
      SELECT 1 FROM public.product_videos pv2
      WHERE pv2.product_id        = s.product_id
        AND pv2.source_youtube_id = s.video_embed_id
    );
  GET DIAGNOSTICS v_vids = ROW_COUNT;

  -- Marcar promovidas
  UPDATE public.produtos_site_padronizacao t
     SET status      = 'promoted'::public.produtos_padronizacao_status,
         promoted_at = now(),
         updated_at  = now()
   WHERE t.id IN (SELECT id FROM _scope);
  GET DIAGNOSTICS v_promoted = ROW_COUNT;

  RETURN jsonb_build_object(
    'linked',        v_linked,
    'physical_diam', v_phys_a,
    'physical_dims', v_phys_e,
    'properties_b',  v_props_b,
    'properties_f',  v_props_f,
    'relationships', v_rel,
    'category_xbz',  v_xcat,
    'images',        v_imgs,
    'videos',        v_vids,
    'promoted',      v_promoted
  );
END $func$;;

-- <<< END 20260606155703_fn_site_promote_to_gold_blocos_e_f_g_h.sql <<<

-- >>> BEGIN 20260606155805_fn_standardize_raw_fix_materials_transform_dispatch_2026.sql >>>
-- Corrige dispatch de transform para tags/materials em fn_standardize_raw.
-- Antes: só chamava fn_apply_transform para transform_type='custom'.
-- Depois: chama fn_apply_transform para QUALQUER transform não-trivial (tudo exceto 'direct').
-- Isso suporta extract_keywords_lookup, lookup, split_pipe etc. em campos de array.
CREATE OR REPLACE FUNCTION public.fn_standardize_raw(p_raw_id uuid, p_override_reference text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r          public.supplier_products_raw%ROWTYPE;
  m          RECORD;
  v_val      text; v_tx text; v_path text;
  v_assigns  jsonb := '{}'::jsonb;
  v_errs     jsonb := '[]'::jsonb;
  v_ncm text; v_ncm_raw text;
  v_pad_id uuid; v_ref text;
  v_status public.produtos_padronizacao_status;
  v_tags jsonb; v_materials jsonb; v_meta text[]; v_arr jsonb;
  v_cols text[] := ARRAY[
    'name','description','short_description','cost_price','suggested_price','stock_quantity',
    'primary_image_url','images','ncm_code','weight_g','height_cm','width_cm','length_cm',
    'dimensions_display','box_length_cm','box_width_cm','box_height_cm','box_weight_kg',
    'box_volume_cm3','box_quantity','box_inner_quantity','brand','packing_type','repacking_type',
    'capacities','capacity_ml','min_quantity','warranty_months','ipi_rate','engraving_type','is_active',
    'product_type','origin_country','combined_sizes','box_image',
    'is_textil','is_stockout','is_online_exclusive','is_new','has_colors','has_sizes','allows_personalization',
    'tags','materials','meta_keywords'];
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'raw_nao_encontrado'); END IF;
  v_ref := COALESCE(NULLIF(TRIM(p_override_reference),''), r.supplier_reference);

  FOR m IN
    SELECT source_field, source_path, target_field, transform_type, transform_config, source_unit, target_unit
    FROM public.supplier_field_mappings
    WHERE supplier_id=r.supplier_id AND target_table='products' AND is_active=TRUE AND target_field=ANY(v_cols)
    ORDER BY priority NULLS LAST
  LOOP
    v_path := NULLIF(regexp_replace(COALESCE(NULLIF(m.source_path,''), m.source_field, ''), '^\\\$\\.?', ''), '');
    IF v_path IS NULL THEN v_val := NULL;
    ELSIF position('.' IN v_path) > 0 THEN v_val := r.raw_data #>> string_to_array(v_path, '.');
    ELSE v_val := r.raw_data ->> v_path; END IF;
    CONTINUE WHEN v_val IS NULL OR TRIM(v_val)='';

    -- ─── Campos de array/jsonb (tags, materials) ─────────────────────────────
    -- Delega para fn_apply_transform para qualquer transform não-trivial.
    -- 'direct' e NULL → split por delimiter (comportamento legado para CSV simples).
    IF m.target_field IN ('tags','materials') THEN
      IF m.transform_type IS NOT NULL AND m.transform_type NOT IN ('direct','') THEN
        -- Qualquer transform não-trivial: fn_apply_transform sabe como produzir jsonb TEXT
        BEGIN
          v_tx  := public.fn_apply_transform(v_val, m.transform_type, m.transform_config,
                                             m.source_unit, m.target_unit, r.supplier_id);
          v_arr := CASE WHEN v_tx IS NOT NULL THEN v_tx::jsonb ELSE '[]'::jsonb END;
        EXCEPTION WHEN OTHERS THEN
          v_arr := '[]'::jsonb;
          v_errs := v_errs || jsonb_build_object('field',m.target_field,'stage','array_transform','msg',SQLERRM);
        END;
      ELSE
        -- 'direct' ou NULL → split CSV simples (legado)
        v_arr := (SELECT to_jsonb(COALESCE(array_agg(btrim(e)) FILTER (WHERE btrim(e) <> ''), ARRAY[]::text[]))
                  FROM unnest(string_to_array(v_val, COALESCE(m.transform_config->>'delimiter', ','))) e);
      END IF;
      IF m.target_field='tags' THEN v_tags := v_arr; ELSE v_materials := v_arr; END IF;
      CONTINUE;
    ELSIF m.target_field='meta_keywords' THEN
      v_meta := (SELECT COALESCE(array_agg(btrim(e)) FILTER (WHERE btrim(e) <> ''), ARRAY[]::text[])
                 FROM unnest(string_to_array(v_val, COALESCE(m.transform_config->>'delimiter', ','))) e);
      CONTINUE;
    END IF;
    -- ─────────────────────────────────────────────────────────────────────────

    BEGIN
      v_tx := public.fn_apply_transform(v_val, m.transform_type, m.transform_config,
                                        m.source_unit, m.target_unit, r.supplier_id);
    EXCEPTION WHEN OTHERS THEN v_tx := v_val;
      v_errs := v_errs || jsonb_build_object('field',m.target_field,'stage','transform','msg',SQLERRM);
    END;
    IF v_tx IS NOT NULL THEN v_assigns := v_assigns || jsonb_build_object(m.target_field, v_tx); END IF;
  END LOOP;

  -- NCM: suporte a Taric (SPOT usa código aduaneiro Taric)
  v_ncm_raw := COALESCE(v_assigns->>'ncm_code', r.raw_data->>'ncm', r.raw_data->>'Ncm', r.raw_data->>'Taric');
  v_ncm := public.fn_normalize_ncm(v_ncm_raw);
  IF v_ncm IS NOT NULL THEN v_assigns := v_assigns || jsonb_build_object('ncm_code', v_ncm);
  ELSIF v_ncm_raw IS NOT NULL THEN
    v_errs := v_errs || jsonb_build_object('field','ncm_code','stage','validate','msg','ncm_invalido','raw',v_ncm_raw);
    v_assigns := v_assigns - 'ncm_code';
  END IF;

  v_status := (CASE WHEN jsonb_array_length(v_errs)>0 AND v_assigns->>'name' IS NULL
                    THEN 'rejected' ELSE 'standardized'
               END)::public.produtos_padronizacao_status;

  INSERT INTO public.produtos_padronizacao AS pad (
    raw_id, supplier_id, supplier_reference,
    name, description, short_description, cost_price, suggested_price, stock_quantity,
    primary_image_url, images, ncm_code, weight_g, height_cm, width_cm, length_cm,
    dimensions_display, box_length_cm, box_width_cm, box_height_cm, box_weight_kg,
    box_volume_cm3, box_quantity, box_inner_quantity, brand, packing_type, repacking_type,
    capacities, capacity_ml, min_quantity, warranty_months, ipi_rate, engraving_type, is_active,
    product_type, origin_country, combined_sizes, box_image,
    is_textil, is_stockout, is_online_exclusive, is_new, has_colors, has_sizes, allows_personalization,
    tags, materials, meta_keywords,
    status, validation_errors, standardized_at
  ) VALUES (
    r.id, r.supplier_id, v_ref,
    v_assigns->>'name', v_assigns->>'description', v_assigns->>'short_description',
    public.fn_safe_num(v_assigns->>'cost_price'),
    public.fn_safe_num(v_assigns->>'suggested_price'),
    public.fn_safe_int(v_assigns->>'stock_quantity'),
    v_assigns->>'primary_image_url',
    CASE WHEN v_assigns ? 'images' THEN (v_assigns->'images') ELSE NULL END,
    v_assigns->>'ncm_code', public.fn_safe_int(v_assigns->>'weight_g'),
    public.fn_safe_num(v_assigns->>'height_cm'), public.fn_safe_num(v_assigns->>'width_cm'),
    public.fn_safe_num(v_assigns->>'length_cm'),
    v_assigns->>'dimensions_display',
    public.fn_safe_num(v_assigns->>'box_length_cm'), public.fn_safe_num(v_assigns->>'box_width_cm'),
    public.fn_safe_num(v_assigns->>'box_height_cm'), public.fn_safe_num(v_assigns->>'box_weight_kg'),
    public.fn_safe_num(v_assigns->>'box_volume_cm3'),
    public.fn_safe_int(v_assigns->>'box_quantity'), public.fn_safe_int(v_assigns->>'box_inner_quantity'),
    v_assigns->>'brand', v_assigns->>'packing_type', v_assigns->>'repacking_type',
    v_assigns->>'capacities', public.fn_safe_int(v_assigns->>'capacity_ml'),
    public.fn_safe_int(v_assigns->>'min_quantity'),
    public.fn_safe_int(v_assigns->>'warranty_months'),
    public.fn_safe_num(v_assigns->>'ipi_rate'),
    v_assigns->>'engraving_type',
    COALESCE(public.fn_safe_bool(v_assigns->>'is_active'), true),
    v_assigns->>'product_type', v_assigns->>'origin_country', v_assigns->>'combined_sizes',
    v_assigns->>'box_image',
    public.fn_safe_bool(v_assigns->>'is_textil'), public.fn_safe_bool(v_assigns->>'is_stockout'),
    public.fn_safe_bool(v_assigns->>'is_online_exclusive'), public.fn_safe_bool(v_assigns->>'is_new'),
    public.fn_safe_bool(v_assigns->>'has_colors'), public.fn_safe_bool(v_assigns->>'has_sizes'),
    (v_assigns ? 'allows_personalization'),
    v_tags, v_materials, v_meta,
    v_status,
    CASE WHEN jsonb_array_length(v_errs)>0 THEN v_errs ELSE NULL END,
    now()
  )
  ON CONFLICT (supplier_id, supplier_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, name=EXCLUDED.name, description=EXCLUDED.description,
    short_description=EXCLUDED.short_description, cost_price=EXCLUDED.cost_price,
    suggested_price=EXCLUDED.suggested_price, stock_quantity=EXCLUDED.stock_quantity,
    primary_image_url=EXCLUDED.primary_image_url, images=EXCLUDED.images, ncm_code=EXCLUDED.ncm_code,
    weight_g=EXCLUDED.weight_g, height_cm=EXCLUDED.height_cm, width_cm=EXCLUDED.width_cm,
    length_cm=EXCLUDED.length_cm, dimensions_display=EXCLUDED.dimensions_display,
    box_length_cm=EXCLUDED.box_length_cm, box_width_cm=EXCLUDED.box_width_cm,
    box_height_cm=EXCLUDED.box_height_cm, box_weight_kg=EXCLUDED.box_weight_kg,
    box_volume_cm3=EXCLUDED.box_volume_cm3, box_quantity=EXCLUDED.box_quantity,
    box_inner_quantity=EXCLUDED.box_inner_quantity, brand=EXCLUDED.brand,
    packing_type=EXCLUDED.packing_type, repacking_type=EXCLUDED.repacking_type,
    capacities=EXCLUDED.capacities, capacity_ml=EXCLUDED.capacity_ml,
    min_quantity=EXCLUDED.min_quantity, warranty_months=EXCLUDED.warranty_months,
    ipi_rate=EXCLUDED.ipi_rate, engraving_type=EXCLUDED.engraving_type,
    is_active=EXCLUDED.is_active, product_type=EXCLUDED.product_type,
    origin_country=EXCLUDED.origin_country, combined_sizes=EXCLUDED.combined_sizes,
    box_image=EXCLUDED.box_image, is_textil=EXCLUDED.is_textil,
    is_stockout=EXCLUDED.is_stockout, is_online_exclusive=EXCLUDED.is_online_exclusive,
    is_new=EXCLUDED.is_new, has_colors=EXCLUDED.has_colors, has_sizes=EXCLUDED.has_sizes,
    allows_personalization=EXCLUDED.allows_personalization,
    tags=COALESCE(EXCLUDED.tags, pad.tags),
    materials=COALESCE(EXCLUDED.materials, pad.materials),
    meta_keywords=COALESCE(EXCLUDED.meta_keywords, pad.meta_keywords),
    status=EXCLUDED.status, validation_errors=EXCLUDED.validation_errors,
    standardized_at=now(), updated_at=now()
  RETURNING pad.id INTO v_pad_id;

  RETURN jsonb_build_object('success',true,'padronizacao_id',v_pad_id,'reference',v_ref,
                            'campos',(SELECT count(*) FROM jsonb_object_keys(v_assigns)),'erros',v_errs);
END;
$function$;;

