-- >>> BEGIN 20260607113114_asia_wp_canonical_site_data_v1.sql >>>
-- =====================================================================
-- ASIA F2 — Conforma o site_data WooCommerce ao contrato canônico do
-- subsistema genérico de site (lido por fn_site_to_silver_all).
-- 1) Helper puro WP->canônico (IMMUTABLE)
-- 2) Reescreve fn_upsert_asia_wp_batch para emitir o canônico + processed
-- =====================================================================

CREATE OR REPLACE FUNCTION public.fn_asia_wp_to_canonical(p_wp jsonb)
RETURNS jsonb
LANGUAGE sql
IMMUTABLE
AS $fn$
  SELECT jsonb_strip_nulls(jsonb_build_object(
    'codigo',               p_wp->>'sku',
    'id_interno_site',      p_wp->>'id',
    'url',                  p_wp->>'permalink',
    'nome',                 p_wp->>'name',
    'descricao',            p_wp->>'description',
    'disponibilidade_site', p_wp#>>'{stock_availability,text}',
    'peso_g',               CASE WHEN NULLIF(p_wp->>'weight','') IS NOT NULL
                                 THEN round((p_wp->>'weight')::numeric*1000)::int END,
    'dimensoes', jsonb_strip_nulls(jsonb_build_object(
        'altura_cm',       NULLIF(p_wp#>>'{dimensions,height}','')::numeric,
        'largura_cm',      NULLIF(p_wp#>>'{dimensions,width}','')::numeric,
        'profundidade_cm', NULLIF(p_wp#>>'{dimensions,length}','')::numeric)),
    'imagens', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                  'tipo', CASE WHEN ord=1 THEN 'principal' ELSE 'galeria' END,
                  'ordem', ord, 'url_origem', img->>'src',
                  'alt', NULLIF(img->>'alt','')) ORDER BY ord),'[]'::jsonb)
                FROM jsonb_array_elements(COALESCE(p_wp->'images','[]'::jsonb))
                     WITH ORDINALITY AS t(img,ord)),
    'cores', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'id',term->>'id','nome',term->>'name','slug',term->>'slug')),'[]'::jsonb)
              FROM jsonb_array_elements(COALESCE(p_wp->'attributes','[]'::jsonb)) attr
              CROSS JOIN jsonb_array_elements(COALESCE(attr->'terms','[]'::jsonb)) term
              WHERE attr->>'taxonomy'='pa_cor'),
    'categorias', (SELECT COALESCE(jsonb_agg(jsonb_build_object(
                     'id',cat->>'id','nome',cat->>'name','slug',cat->>'slug','link',cat->>'link')),'[]'::jsonb)
                   FROM jsonb_array_elements(COALESCE(p_wp->'categories','[]'::jsonb)) cat),
    -- extensões de valor (WP-only)
    'preco_normal', CASE WHEN NULLIF(p_wp#>>'{prices,regular_price}','') IS NOT NULL
        THEN round((p_wp#>>'{prices,regular_price}')::numeric
                   /power(10::numeric,COALESCE(NULLIF(p_wp#>>'{prices,currency_minor_unit}','')::int,2)::numeric),2) END,
    'preco_promo', CASE WHEN NULLIF(p_wp#>>'{prices,sale_price}','') IS NOT NULL
        THEN round((p_wp#>>'{prices,sale_price}')::numeric
                   /power(10::numeric,COALESCE(NULLIF(p_wp#>>'{prices,currency_minor_unit}','')::int,2)::numeric),2) END,
    'em_promocao',    (p_wp->>'on_sale')::boolean,
    'moq',            NULLIF(p_wp#>>'{add_to_cart,multiple_of}','')::int,
    'qtd_minima',     NULLIF(p_wp#>>'{add_to_cart,minimum}','')::int,
    'qtd_maxima',     NULLIF(p_wp#>>'{add_to_cart,maximum}','')::int,
    'marca',          (SELECT b->>'name' FROM jsonb_array_elements(COALESCE(p_wp->'brands','[]'::jsonb)) b LIMIT 1),
    'avaliacao',      NULLIF(p_wp->>'average_rating','0')::numeric,
    'num_avaliacoes', NULLIF(p_wp->>'review_count','0')::int,
    '_meta', jsonb_build_object('scraper_version','wc_store_v1','fonte','woocommerce_store_api')
  ));
$fn$;

COMMENT ON FUNCTION public.fn_asia_wp_to_canonical(jsonb) IS
  'Mapeia 1 produto da WooCommerce Store API (s.asiaimport.com.br) para o shape canonico de site_data lido por fn_site_to_silver_all. Puro/IMMUTABLE.';

-- ---------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.fn_upsert_asia_wp_batch(p_items jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE
  v_ASIA       uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_item       jsonb;
  v_parent_ref text;
  v_canon      jsonb;
  v_hash       text;
  v_rows       int;
  v_fetched    int := 0;
  v_updated    int := 0;
  v_parents    int := 0;
BEGIN
  IF jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'fn_upsert_asia_wp_batch: p_items deve ser array jsonb';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_fetched := v_fetched + 1;
    -- Store API: 'sku' = referencia do produto-pai (ex: "MC511P"),
    -- que casa com raw_data->>'referencia' em TODAS as variantes.
    v_parent_ref := NULLIF(TRIM(v_item->>'sku'), '');
    CONTINUE WHEN v_parent_ref IS NULL;

    v_canon := public.fn_asia_wp_to_canonical(v_item);   -- WP cru -> canonico (PT)
    v_hash  := encode(digest(v_canon::text, 'sha256'), 'hex');

    UPDATE public.supplier_products_raw r SET
      site_data       = v_canon,
      site_hash       = v_hash,
      site_source_url = v_canon->>'url',
      -- dado da Store API chega pronto: vai direto a 'processed' quando muda
      site_status     = CASE WHEN r.site_hash IS DISTINCT FROM v_hash
                             THEN 'processed'::supplier_raw_status
                             ELSE r.site_status END,
      site_scraped_at = now(),
      updated_at      = now()
    WHERE r.supplier_id = v_ASIA
      AND r.raw_data->>'referencia' = v_parent_ref;

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_updated := v_updated + v_rows;
    IF v_rows > 0 THEN v_parents := v_parents + 1; END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'fetched',         v_fetched,
    'matched_parents', v_parents,
    'updated_rows',    v_updated,
    'rodado_em',       now()
  );
END;
$fn$;

COMMENT ON FUNCTION public.fn_upsert_asia_wp_batch(jsonb) IS
  'F2 ASIA: recebe array de produtos da WooCommerce Store API, converte p/ canonico via fn_asia_wp_to_canonical e grava na trilha site_* de supplier_products_raw (propaga ao grao pai->variantes). site_status->processed on change.';

REVOKE ALL ON FUNCTION public.fn_asia_wp_to_canonical(jsonb) FROM public, anon, authenticated;
REVOKE ALL ON FUNCTION public.fn_upsert_asia_wp_batch(jsonb)  FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_asia_wp_to_canonical(jsonb) TO service_role;
GRANT EXECUTE ON FUNCTION public.fn_upsert_asia_wp_batch(jsonb)  TO service_role;;

-- <<< END 20260607113114_asia_wp_canonical_site_data_v1.sql <<<

-- >>> BEGIN 20260607113213_asia_wp_batch_v1b_md5_hash.sql >>>
-- Troca digest(sha256)/pgcrypto por md5() built-in no hash de change-detection.
-- site_hash so e comparado consigo mesmo (mesmo loader) -> md5 e suficiente.
CREATE OR REPLACE FUNCTION public.fn_upsert_asia_wp_batch(p_items jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE
  v_ASIA       uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_item       jsonb;
  v_parent_ref text;
  v_canon      jsonb;
  v_hash       text;
  v_rows       int;
  v_fetched    int := 0;
  v_updated    int := 0;
  v_parents    int := 0;
BEGIN
  IF jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'fn_upsert_asia_wp_batch: p_items deve ser array jsonb';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_fetched := v_fetched + 1;
    v_parent_ref := NULLIF(TRIM(v_item->>'sku'), '');
    CONTINUE WHEN v_parent_ref IS NULL;

    v_canon := public.fn_asia_wp_to_canonical(v_item);
    v_hash  := md5(v_canon::text);

    UPDATE public.supplier_products_raw r SET
      site_data       = v_canon,
      site_hash       = v_hash,
      site_source_url = v_canon->>'url',
      site_status     = CASE WHEN r.site_hash IS DISTINCT FROM v_hash
                             THEN 'processed'::supplier_raw_status
                             ELSE r.site_status END,
      site_scraped_at = now(),
      updated_at      = now()
    WHERE r.supplier_id = v_ASIA
      AND r.raw_data->>'referencia' = v_parent_ref;

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_updated := v_updated + v_rows;
    IF v_rows > 0 THEN v_parents := v_parents + 1; END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'fetched',         v_fetched,
    'matched_parents', v_parents,
    'updated_rows',    v_updated,
    'rodado_em',       now()
  );
END;
$fn$;;

-- <<< END 20260607113213_asia_wp_batch_v1b_md5_hash.sql <<<

-- >>> BEGIN 20260607114929_site_silver_extend_wp_fields_v1.sql >>>
-- Adiciona 6 colunas nullable (WP-only) a produtos_site_padronizacao.
-- XBZ: site_data nao tem essas chaves -> ficam null -> sem impacto.
ALTER TABLE public.produtos_site_padronizacao
  ADD COLUMN IF NOT EXISTS brand         text,
  ADD COLUMN IF NOT EXISTS moq           integer,
  ADD COLUMN IF NOT EXISTS min_quantity  integer,
  ADD COLUMN IF NOT EXISTS regular_price numeric(12,2),
  ADD COLUMN IF NOT EXISTS sale_price    numeric(12,2),
  ADD COLUMN IF NOT EXISTS is_on_sale    boolean;

COMMENT ON COLUMN public.produtos_site_padronizacao.brand         IS 'Marca do produto (WP brands taxonomy). XBZ: null.';
COMMENT ON COLUMN public.produtos_site_padronizacao.moq           IS 'Multiplo minimo de venda (WP add_to_cart.multiple_of). XBZ: null.';
COMMENT ON COLUMN public.produtos_site_padronizacao.min_quantity  IS 'Quantidade minima de pedido (WP add_to_cart.minimum). XBZ: null.';
COMMENT ON COLUMN public.produtos_site_padronizacao.regular_price IS 'Preco normal/lista sem promocao (WP prices.regular_price). XBZ: null.';
COMMENT ON COLUMN public.produtos_site_padronizacao.sale_price    IS 'Preco promocional (WP prices.sale_price). XBZ: null.';
COMMENT ON COLUMN public.produtos_site_padronizacao.is_on_sale    IS 'Produto em promocao (WP on_sale). XBZ: null.';

-- Estende fn_site_to_silver_all para popular os 6 novos campos do site_data canonico.
-- A logica de leitura e identica para qualquer fornecedor; XBZ retorna null nos 6.
CREATE OR REPLACE FUNCTION public.fn_site_to_silver_all(
  p_supplier uuid DEFAULT 'd6718a29-e954-4c1b-bd84-03ea24884900'::uuid,
  p_limit    integer DEFAULT NULL::integer
)
RETURNS jsonb LANGUAGE plpgsql
AS $function$
DECLARE v_affected int; v_total int;
BEGIN
  INSERT INTO public.produtos_site_padronizacao AS t (
    raw_id, supplier_id, supplier_reference, source_url, source_hash, scraper_version,
    name, description, usage_instructions, supplier_internal_id, availability, disclaimer,
    weight_g, height_cm, width_cm, depth_cm, diameter_cm, circumference_cm,
    engraving_text, engraving_length_cm, engraving_width_cm, engraving_location,
    datasheet_pdf_url, has_video, video_platform, video_embed_id, video_embed_url,
    video_watch_url, video_channel_url, has_view_360, view_360_icon_url,
    primary_image_url, images, colors, categories, related_references,
    brand, moq, min_quantity, regular_price, sale_price, is_on_sale,
    status, standardized_at, updated_at
  )
  SELECT
    s.raw_id, s.supplier_id, s.codigo,
    s.site_data->>'url', s.site_hash, s.site_data#>>'{_meta,scraper_version}',
    public.fn_sanitize_text(s.site_data->>'nome'),
    public.fn_sanitize_text(s.site_data->>'descricao'),
    public.fn_sanitize_text(s.site_data->>'modo_de_uso'),
    s.site_data->>'id_interno_site',
    public.fn_sanitize_text(s.site_data->>'disponibilidade_site'),
    public.fn_sanitize_text(s.site_data->>'disclaimer'),
    (s.site_data->>'peso_g')::int,
    (s.site_data#>>'{dimensoes,altura_cm}')::numeric,
    (s.site_data#>>'{dimensoes,largura_cm}')::numeric,
    (s.site_data#>>'{dimensoes,profundidade_cm}')::numeric,
    (s.site_data#>>'{dimensoes,diametro_cm}')::numeric,
    (s.site_data#>>'{dimensoes,circunferencia_cm}')::numeric,
    public.fn_sanitize_text(s.site_data#>>'{gravacao,medida_texto}'),
    (s.site_data#>>'{gravacao,comprimento_cm}')::numeric,
    (s.site_data#>>'{gravacao,largura_cm}')::numeric,
    public.fn_sanitize_text(s.site_data#>>'{gravacao,local}'),
    s.site_data->>'ficha_tecnica_pdf',
    (s.site_data#>>'{video,indicador}')::boolean,
    s.site_data#>>'{video,plataforma}',  s.site_data#>>'{video,embed_id}',
    s.site_data#>>'{video,embed_url}',   s.site_data#>>'{video,watch_url}',
    s.site_data#>>'{video,canal}',
    (s.site_data#>>'{view_360,indicador}')::boolean, s.site_data#>>'{view_360,icone}',
    (SELECT img->>'url_origem'
       FROM jsonb_array_elements(COALESCE(s.site_data->'imagens','[]'::jsonb)) img
      WHERE img->>'tipo'='principal' ORDER BY (img->>'ordem')::int LIMIT 1),
    s.site_data->'imagens', s.site_data->'cores',
    s.site_data->'categorias', s.site_data->'relacionados',
    -- Campos WP-exclusive: null para XBZ (chaves ausentes no site_data XBZ)
    NULLIF(s.site_data->>'marca', ''),
    NULLIF(s.site_data->>'moq', '')::integer,
    NULLIF(s.site_data->>'qtd_minima', '')::integer,
    NULLIF(s.site_data->>'preco_normal', '')::numeric,
    NULLIF(s.site_data->>'preco_promo', '')::numeric,
    (s.site_data->>'em_promocao')::boolean,
    'standardized'::public.produtos_padronizacao_status, now(), now()
  FROM (
    SELECT DISTINCT ON (r.supplier_id, r.site_data->>'codigo')
      r.id AS raw_id, r.supplier_id, r.site_data->>'codigo' AS codigo,
      r.site_data, r.site_hash
    FROM public.supplier_products_raw r
    WHERE r.supplier_id = p_supplier
      AND r.site_status = 'processed'
      AND r.site_data IS NOT NULL
      AND r.site_data->>'codigo' IS NOT NULL
    ORDER BY r.supplier_id, r.site_data->>'codigo', r.id
    LIMIT COALESCE(p_limit, 1000000000)
  ) s
  ON CONFLICT (supplier_id, supplier_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, source_url=EXCLUDED.source_url,
    source_hash=EXCLUDED.source_hash, scraper_version=EXCLUDED.scraper_version,
    name=EXCLUDED.name, description=EXCLUDED.description,
    usage_instructions=EXCLUDED.usage_instructions,
    supplier_internal_id=EXCLUDED.supplier_internal_id,
    availability=EXCLUDED.availability, disclaimer=EXCLUDED.disclaimer,
    weight_g=EXCLUDED.weight_g, height_cm=EXCLUDED.height_cm,
    width_cm=EXCLUDED.width_cm, depth_cm=EXCLUDED.depth_cm,
    diameter_cm=EXCLUDED.diameter_cm, circumference_cm=EXCLUDED.circumference_cm,
    engraving_text=EXCLUDED.engraving_text,
    engraving_length_cm=EXCLUDED.engraving_length_cm,
    engraving_width_cm=EXCLUDED.engraving_width_cm,
    engraving_location=EXCLUDED.engraving_location,
    datasheet_pdf_url=EXCLUDED.datasheet_pdf_url,
    has_video=EXCLUDED.has_video, video_platform=EXCLUDED.video_platform,
    video_embed_id=EXCLUDED.video_embed_id, video_embed_url=EXCLUDED.video_embed_url,
    video_watch_url=EXCLUDED.video_watch_url, video_channel_url=EXCLUDED.video_channel_url,
    has_view_360=EXCLUDED.has_view_360, view_360_icon_url=EXCLUDED.view_360_icon_url,
    primary_image_url=EXCLUDED.primary_image_url,
    images=EXCLUDED.images, colors=EXCLUDED.colors,
    categories=EXCLUDED.categories, related_references=EXCLUDED.related_references,
    -- Fill-only nos 6 novos: COALESCE preserva valor existente se novo for null
    brand=COALESCE(EXCLUDED.brand, t.brand),
    moq=COALESCE(EXCLUDED.moq, t.moq),
    min_quantity=COALESCE(EXCLUDED.min_quantity, t.min_quantity),
    regular_price=COALESCE(EXCLUDED.regular_price, t.regular_price),
    sale_price=COALESCE(EXCLUDED.sale_price, t.sale_price),
    is_on_sale=COALESCE(EXCLUDED.is_on_sale, t.is_on_sale),
    status='standardized'::public.produtos_padronizacao_status,
    standardized_at=now(), updated_at=now()
  WHERE t.source_hash IS DISTINCT FROM EXCLUDED.source_hash;

  GET DIAGNOSTICS v_affected = ROW_COUNT;
  SELECT count(DISTINCT r.site_data->>'codigo') INTO v_total
  FROM public.supplier_products_raw r
  WHERE r.supplier_id=p_supplier AND r.site_status='processed' AND r.site_data IS NOT NULL;

  RETURN jsonb_build_object('afetados', v_affected, 'total_candidatos', v_total,
                            'normalizacao', 'fn_sanitize_text', 'rodado_em', now());
END $function$;;

-- <<< END 20260607114929_site_silver_extend_wp_fields_v1.sql <<<

-- >>> BEGIN 20260607114959_asia_site_promote_to_gold_v1.sql >>>
-- Promote dedicado ASIA: trail site -> Gold.
-- Consistente com fn_xbz_enrich_gold_extractors (padrao supplier-especifico ja estabelecido).
-- fn_site_promote_to_gold (XBZ) nao e tocada.
CREATE OR REPLACE FUNCTION public.fn_asia_site_promote_to_gold(
  p_limit    integer DEFAULT NULL,
  p_only_new boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE
  v_ASIA     uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_linked   int  := 0;
  v_phys     int  := 0;
  v_scalars  int  := 0;
  v_promoted int  := 0;
BEGIN

  -- 0. Vincular product_id via Silver principal (mesmo padrao do fn_site_promote_to_gold)
  WITH lnk AS (
    SELECT s.id, p.product_id
    FROM public.produtos_site_padronizacao s
    JOIN public.produtos_padronizacao p
      ON p.supplier_id = s.supplier_id
     AND p.supplier_reference = s.supplier_reference
    WHERE s.supplier_id = v_ASIA
      AND p.product_id IS NOT NULL
      AND s.product_id IS NULL
      AND s.status <> 'rejected'
  )
  UPDATE public.produtos_site_padronizacao t
     SET product_id = lnk.product_id, updated_at = now()
    FROM lnk WHERE t.id = lnk.id;
  GET DIAGNOSTICS v_linked = ROW_COUNT;

  CREATE TEMP TABLE _asia_site_scope ON COMMIT DROP AS
    SELECT s.* FROM public.produtos_site_padronizacao s
    WHERE s.supplier_id = v_ASIA
      AND s.product_id IS NOT NULL
      AND s.status = CASE WHEN p_only_new
                          THEN 'standardized'::public.produtos_padronizacao_status
                          ELSE s.status END
      AND s.status <> 'rejected'
    LIMIT COALESCE(p_limit, 1000000000);

  IF NOT EXISTS (SELECT 1 FROM _asia_site_scope) THEN
    RETURN jsonb_build_object('linked', v_linked, 'note', 'nada_novo');
  END IF;

  -- (e) product_physical: peso + dimensoes (gap-fill COALESCE, nunca sobrescreve fonte melhor)
  INSERT INTO public.product_physical (product_id, weight_g, height_cm, width_cm, length_cm)
  SELECT product_id, weight_g::numeric, height_cm, width_cm, depth_cm
  FROM _asia_site_scope
  WHERE weight_g IS NOT NULL OR height_cm IS NOT NULL
     OR width_cm IS NOT NULL  OR depth_cm IS NOT NULL
  ON CONFLICT (product_id) DO UPDATE SET
    weight_g  = COALESCE(public.product_physical.weight_g,  EXCLUDED.weight_g),
    height_cm = COALESCE(public.product_physical.height_cm, EXCLUDED.height_cm),
    width_cm  = COALESCE(public.product_physical.width_cm,  EXCLUDED.width_cm),
    length_cm = COALESCE(public.product_physical.length_cm, EXCLUDED.length_cm),
    updated_at = now();
  GET DIAGNOSTICS v_phys = ROW_COUNT;

  -- (h) products: fill-only escalares WP-exclusive (brand, moq, precos).
  --     COALESCE: nunca sobrescreve dado ja gravado de fonte melhor (API, ERP).
  UPDATE public.products p SET
    brand                  = COALESCE(p.brand,                  s.brand),
    min_order_quantity     = COALESCE(p.min_order_quantity,     s.moq),
    min_quantity           = COALESCE(p.min_quantity,           s.min_quantity),
    requires_minimum_order = COALESCE(p.requires_minimum_order,
                               CASE WHEN s.moq IS NOT NULL THEN (s.moq > 1) ELSE NULL END),
    sale_price             = COALESCE(p.sale_price,             s.sale_price),
    is_on_sale             = COALESCE(p.is_on_sale,             s.is_on_sale),
    suggested_price        = COALESCE(p.suggested_price,        s.regular_price),
    updated_at             = now()
  FROM _asia_site_scope s
  WHERE p.id = s.product_id
    AND (s.brand IS NOT NULL OR s.moq IS NOT NULL
      OR s.sale_price IS NOT NULL OR s.regular_price IS NOT NULL
      OR s.is_on_sale IS NOT NULL);
  GET DIAGNOSTICS v_scalars = ROW_COUNT;

  -- Marcar promovidas (idempotencia: evita reprocessar nas proximas rodadas)
  UPDATE public.produtos_site_padronizacao t
     SET status      = 'promoted'::public.produtos_padronizacao_status,
         promoted_at = now(),
         updated_at  = now()
   WHERE t.id IN (SELECT id FROM _asia_site_scope);
  GET DIAGNOSTICS v_promoted = ROW_COUNT;

  RETURN jsonb_build_object(
    'linked',   v_linked,
    'physical', v_phys,
    'scalars',  v_scalars,
    'promoted', v_promoted
  );
END;
$fn$;

COMMENT ON FUNCTION public.fn_asia_site_promote_to_gold(integer,boolean) IS
  'Promote WP site_data -> Gold para ASIA. Pattern supplier-especifico (consistente com fn_xbz_enrich_gold_extractors). Nao toca fn_site_promote_to_gold (XBZ).';

REVOKE ALL ON FUNCTION public.fn_asia_site_promote_to_gold(integer,boolean) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_asia_site_promote_to_gold(integer,boolean) TO service_role;;

-- <<< END 20260607114959_asia_site_promote_to_gold_v1.sql <<<

-- >>> BEGIN 20260607120103_fn_spot_direct_stock_gold.sql >>>

-- ============================================================
-- fn_spot_direct_stock_gold
-- Hot-path: atualiza estoque direto no Gold (variant_supplier_sources
-- + product_variants) sem passar pelo Medallion.
-- Chamada pelo workflow SPOT - Sync Estoque a cada 15 min.
-- Reconciliação completa pela execução Medallion de madrugada.
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_spot_direct_stock_gold(
  p_items jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_sid       CONSTANT uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'; -- STRICKER
  v_item      jsonb;
  v_sku       text;
  v_vid       uuid;
  v_qty       int;
  v_vss_rows  int;
  v_updated   int := 0;
  v_skipped   int := 0;
  v_errors    int := 0;
  v_errs      jsonb := '[]'::jsonb;

  -- Helper: safe nullable int from jsonb field
  v_nq1 int; v_nq2 int; v_nq3 int;
  v_nq4 int; v_nq5 int; v_nq6 int;
  -- Helper: safe nullable date from jsonb field
  v_nd1 date; v_nd2 date; v_nd3 date;
  v_nd4 date; v_nd5 date; v_nd6 date;
BEGIN
  IF jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'fn_spot_direct_stock_gold: p_items deve ser array jsonb';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    BEGIN
      -- ── Extrair Sku ──────────────────────────────────────────
      v_sku := NULLIF(TRIM(COALESCE(
                 v_item->>'Sku', v_item->>'WebSku',
                 v_item->>'sku', v_item->>'webSku')), '');

      IF v_sku IS NULL THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

      -- ── Resolver variant via VSS (join supplier-específico) ──
      SELECT vss.variant_id INTO v_vid
      FROM public.variant_supplier_sources vss
      WHERE vss.supplier_sku = v_sku
        AND vss.supplier_id  = v_sid
      LIMIT 1;

      IF v_vid IS NULL THEN
        -- Fallback: tentar product_variants diretamente
        SELECT pv.id INTO v_vid
        FROM public.product_variants pv
        WHERE pv.supplier_sku = v_sku LIMIT 1;
      END IF;

      IF v_vid IS NULL THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

      -- ── Quantidade ───────────────────────────────────────────
      v_qty := COALESCE(NULLIF(v_item->>'Quantity', '')::int, 0);

      -- ── Reposições (nulls-safe, "" = NULL) ───────────────────
      v_nq1 := CASE WHEN NULLIF(v_item->>'NextQuantity1','') IS NOT NULL THEN (v_item->>'NextQuantity1')::int END;
      v_nq2 := CASE WHEN NULLIF(v_item->>'NextQuantity2','') IS NOT NULL THEN (v_item->>'NextQuantity2')::int END;
      v_nq3 := CASE WHEN NULLIF(v_item->>'NextQuantity3','') IS NOT NULL THEN (v_item->>'NextQuantity3')::int END;
      v_nq4 := CASE WHEN NULLIF(v_item->>'NextQuantity4','') IS NOT NULL THEN (v_item->>'NextQuantity4')::int END;
      v_nq5 := CASE WHEN NULLIF(v_item->>'NextQuantity5','') IS NOT NULL THEN (v_item->>'NextQuantity5')::int END;
      v_nq6 := CASE WHEN NULLIF(v_item->>'NextQuantity6','') IS NOT NULL THEN (v_item->>'NextQuantity6')::int END;

      v_nd1 := CASE WHEN NULLIF(v_item->>'NextDate1','') IS NOT NULL THEN (v_item->>'NextDate1')::date END;
      v_nd2 := CASE WHEN NULLIF(v_item->>'NextDate2','') IS NOT NULL THEN (v_item->>'NextDate2')::date END;
      v_nd3 := CASE WHEN NULLIF(v_item->>'NextDate3','') IS NOT NULL THEN (v_item->>'NextDate3')::date END;
      v_nd4 := CASE WHEN NULLIF(v_item->>'NextDate4','') IS NOT NULL THEN (v_item->>'NextDate4')::date END;
      v_nd5 := CASE WHEN NULLIF(v_item->>'NextDate5','') IS NOT NULL THEN (v_item->>'NextDate5')::date END;
      v_nd6 := CASE WHEN NULLIF(v_item->>'NextDate6','') IS NOT NULL THEN (v_item->>'NextDate6')::date END;

      -- ── Atualizar variant_supplier_sources ───────────────────
      UPDATE public.variant_supplier_sources
      SET quantity             = v_qty,
          stock_main_warehouse = v_qty,
          next_quantity_1      = v_nq1, next_date_1 = v_nd1,
          next_quantity_2      = v_nq2, next_date_2 = v_nd2,
          next_quantity_3      = v_nq3, next_date_3 = v_nd3,
          next_quantity_4      = v_nq4, next_date_4 = v_nd4,
          next_quantity_5      = v_nq5, next_date_5 = v_nd5,
          next_quantity_6      = v_nq6, next_date_6 = v_nd6,
          source               = 'hot_path_stock',
          last_synced_at       = now(),
          updated_at           = now()
      WHERE variant_id = v_vid
        AND supplier_id = v_sid;

      GET DIAGNOSTICS v_vss_rows = ROW_COUNT;

      -- ── Atualizar product_variants.stock_quantity ─────────────
      UPDATE public.product_variants
      SET stock_quantity = v_qty,
          last_sync_at  = now()
      WHERE id = v_vid;

      v_updated := v_updated + 1;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      IF jsonb_array_length(v_errs) < 15 THEN
        v_errs := v_errs || jsonb_build_object(
          'sku', v_sku, 'err', SQLERRM, 'state', SQLSTATE
        );
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'feed',       'hot_path_stock',
    'supplier',   'STRICKER',
    'updated',    v_updated,
    'skipped',    v_skipped,
    'errors',     v_errors,
    'error_samples', v_errs,
    'updated_at', now()
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_spot_direct_stock_gold(jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_spot_direct_stock_gold(jsonb) TO service_role;
COMMENT ON FUNCTION public.fn_spot_direct_stock_gold(jsonb) IS
  'Hot-path SPOT: atualiza estoque direto em variant_supplier_sources + product_variants. Sem Medallion. Reconciliado pelo Sync Full de madrugada.';
;

-- <<< END 20260607120103_fn_spot_direct_stock_gold.sql <<<

-- >>> BEGIN 20260607120216_fn_spot_direct_prices_gold.sql >>>

-- ============================================================
-- fn_spot_direct_prices_gold
-- Hot-path: atualiza faixas de preço direto no Gold
-- (variant_supplier_sources) sem passar pelo Medallion.
-- Chamada pelo workflow SPOT - Sync Preços a cada 1 hora.
-- Reconciliação completa pelo Sync Full de madrugada.
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_spot_direct_prices_gold(
  p_items jsonb
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_sid     CONSTANT uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0'; -- STRICKER
  v_item    jsonb;
  v_sku     text;
  v_vid     uuid;
  v_rows    int;
  v_updated int := 0;
  v_skipped int := 0;
  v_errors  int := 0;
  v_errs    jsonb := '[]'::jsonb;

  -- Preços das faixas
  v_p1 numeric; v_p2 numeric; v_p3 numeric; v_p4 numeric; v_p5 numeric;
  v_q1 int;     v_q2 int;     v_q3 int;     v_q4 int;     v_q5 int;
  v_your_price numeric;
BEGIN
  IF jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'fn_spot_direct_prices_gold: p_items deve ser array jsonb';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    BEGIN
      -- ── Extrair Sku ──────────────────────────────────────────
      v_sku := NULLIF(TRIM(COALESCE(
                 v_item->>'Sku', v_item->>'WebSku',
                 v_item->>'sku', v_item->>'webSku')), '');

      IF v_sku IS NULL THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

      -- ── Resolver variant via VSS ─────────────────────────────
      SELECT vss.variant_id INTO v_vid
      FROM public.variant_supplier_sources vss
      WHERE vss.supplier_sku = v_sku
        AND vss.supplier_id  = v_sid
      LIMIT 1;

      IF v_vid IS NULL THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

      -- ── Extrair faixas de preço (null-safe) ──────────────────
      v_p1 := NULLIF(v_item->>'Price1', '')::numeric;
      v_p2 := NULLIF(v_item->>'Price2', '')::numeric;
      v_p3 := NULLIF(v_item->>'Price3', '')::numeric;
      v_p4 := NULLIF(v_item->>'Price4', '')::numeric;
      v_p5 := NULLIF(v_item->>'Price5', '')::numeric;

      v_q1 := NULLIF(v_item->>'MinQt1', '')::int;
      v_q2 := NULLIF(v_item->>'MinQt2', '')::int;
      v_q3 := NULLIF(v_item->>'MinQt3', '')::int;
      v_q4 := NULLIF(v_item->>'MinQt4', '')::int;
      v_q5 := NULLIF(v_item->>'MinQt5', '')::int;

      v_your_price := NULLIF(v_item->>'YourPrice', '')::numeric;

      -- Validação mínima: ao menos Price1 deve existir e ser positivo
      IF v_p1 IS NULL THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

      -- ── Atualizar variant_supplier_sources ───────────────────
      -- COALESCE preserva valor existente quando o campo vier NULL no feed
      UPDATE public.variant_supplier_sources
      SET
        cost_price       = v_p1,
        cost_price_1     = COALESCE(v_p1,  cost_price_1),
        min_qty_1        = COALESCE(v_q1,  min_qty_1),
        cost_price_2     = COALESCE(v_p2,  cost_price_2),
        min_qty_2        = COALESCE(v_q2,  min_qty_2),
        cost_price_3     = COALESCE(v_p3,  cost_price_3),
        min_qty_3        = COALESCE(v_q3,  min_qty_3),
        cost_price_4     = COALESCE(v_p4,  cost_price_4),
        min_qty_4        = COALESCE(v_q4,  min_qty_4),
        cost_price_5     = COALESCE(v_p5,  cost_price_5),
        min_qty_5        = COALESCE(v_q5,  min_qty_5),
        your_price       = COALESCE(v_your_price, your_price),
        source           = 'hot_path_prices',
        price_updated_at = now(),
        last_synced_at   = now(),
        updated_at       = now()
      WHERE variant_id = v_vid
        AND supplier_id = v_sid;

      GET DIAGNOSTICS v_rows = ROW_COUNT;

      IF v_rows > 0 THEN
        v_updated := v_updated + 1;
      ELSE
        v_skipped := v_skipped + 1; -- VSS existe mas sem linha para STRICKER
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      IF jsonb_array_length(v_errs) < 15 THEN
        v_errs := v_errs || jsonb_build_object(
          'sku', v_sku, 'err', SQLERRM, 'state', SQLSTATE
        );
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'feed',          'hot_path_prices',
    'supplier',      'STRICKER',
    'updated',       v_updated,
    'skipped',       v_skipped,
    'errors',        v_errors,
    'error_samples', v_errs,
    'updated_at',    now()
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_spot_direct_prices_gold(jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_spot_direct_prices_gold(jsonb) TO service_role;
COMMENT ON FUNCTION public.fn_spot_direct_prices_gold(jsonb) IS
  'Hot-path SPOT: atualiza faixas de preço direto em variant_supplier_sources. Sem Medallion. Reconciliado pelo Sync Full de madrugada.';
;

-- <<< END 20260607120216_fn_spot_direct_prices_gold.sql <<<

-- >>> BEGIN 20260607123219_sm_site_url_map_patch_v2.sql >>>

-- ============================================================
--  SM JINA PIPELINE — FASE 0 PATCH v2
--  Corrige constraint e adiciona colunas faltantes
-- ============================================================

-- 1. Adicionar colunas faltantes (idempotente)
ALTER TABLE public.sm_site_url_map
    ADD COLUMN IF NOT EXISTS hex_color  text,
    ADD COLUMN IF NOT EXISTS nome_site  text,
    ADD COLUMN IF NOT EXISTS validated  boolean NOT NULL DEFAULT false,
    ADD COLUMN IF NOT EXISTS created_at timestamptz NOT NULL DEFAULT now(),
    ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();

-- 2. Preencher timestamps para linhas existentes
UPDATE public.sm_site_url_map
SET created_at = COALESCE(discovered_at, now()),
    updated_at = COALESCE(last_verified_at, discovered_at, now())
WHERE created_at = now();   -- só recém-adicionadas (default foi now())

-- 3. Constraint de source incluindo todos os valores existentes
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'sm_site_url_map_source_chk'
      AND conrelid = 'public.sm_site_url_map'::regclass
  ) THEN
    ALTER TABLE public.sm_site_url_map
      ADD CONSTRAINT sm_site_url_map_source_chk
        CHECK (source IN (
          'produtos_similares', 'category_scrape', 'jina_search',
          'manual', 'unknown', 'bronze_seed', 'related_products'
        ));
  END IF;
END $$;

-- 4. Índices
CREATE INDEX IF NOT EXISTS sm_site_url_map_validated_idx ON public.sm_site_url_map (validated);
CREATE INDEX IF NOT EXISTS sm_site_url_map_source_idx    ON public.sm_site_url_map (source);
CREATE INDEX IF NOT EXISTS sm_site_url_map_site_id_idx   ON public.sm_site_url_map (site_id)
    WHERE site_id IS NOT NULL;

-- 5. Trigger updated_at
CREATE OR REPLACE FUNCTION public.fn_sm_url_map_set_updated()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END;
$$;

DROP TRIGGER IF EXISTS trg_sm_site_url_map_updated ON public.sm_site_url_map;
CREATE TRIGGER trg_sm_site_url_map_updated
    BEFORE UPDATE ON public.sm_site_url_map
    FOR EACH ROW EXECUTE FUNCTION public.fn_sm_url_map_set_updated();

-- 6. Comentários
COMMENT ON TABLE  public.sm_site_url_map IS
    'Mapa codigo SM → URL canônica (site_id + slug). '
    '1230+ mapeamentos descobertos via bronze_seed, produtos_similares, '
    'related_products e category_scrape. Alimenta o SM Jina Scraping Pipeline.';
COMMENT ON COLUMN public.sm_site_url_map.validated IS
    'true após 1º scrape bem-sucedido retornar dados do produto correto.';
COMMENT ON COLUMN public.sm_site_url_map.hex_color IS
    'Cor hex do produto neste mapeamento (ex.: #FFFFFF). Extraída dos produtos_similares.';
COMMENT ON COLUMN public.sm_site_url_map.nome_site IS
    'Nome do produto como aparece no site SM. Extraído dos produtos_similares.';

-- 7. RLS
ALTER TABLE public.sm_site_url_map ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE policyname = 'sm_url_map_service_all'
      AND tablename  = 'sm_site_url_map'
  ) THEN
    EXECUTE 'CREATE POLICY sm_url_map_service_all ON public.sm_site_url_map
             FOR ALL TO service_role USING (true) WITH CHECK (true)';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE policyname = 'sm_url_map_auth_read'
      AND tablename  = 'sm_site_url_map'
  ) THEN
    EXECUTE 'CREATE POLICY sm_url_map_auth_read ON public.sm_site_url_map
             FOR SELECT TO authenticated USING (true)';
  END IF;
END $$;
;

