-- >>> BEGIN 20260607123859_fix_sm_url_discover_collect_site_url.sql >>>

-- ============================================================
--  BUG FIX 1: fn_sm_url_discover_collect
--  Problema: após descobrir site_id via Jina Search, a coluna
--  site_url não era atualizada → fn_sm_site_enqueue nunca
--  enfileirava esses produtos (filtro: m.site_url IS NOT NULL)
--  Fix: calcular e gravar site_url junto com site_id
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_sm_url_discover_collect(p_max integer DEFAULT 20)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, net
AS $$
DECLARE
  v_sup       uuid := '841cd690-210a-422a-908c-7676828db272';
  rec         record;
  v_body      text;
  v_sc        int;
  v_m         text[];
  v_site_id   int;
  v_slug      text;
  v_site_url  text;
  v_ok        int := 0;
  v_fail      int := 0;
  v_wait      int := 0;
BEGIN
  FOR rec IN
    SELECT id, codigo, slug, search_req_id
    FROM public.sm_site_url_map
    WHERE supplier_id    = v_sup
      AND search_status  = 'pending'
      AND search_req_id  IS NOT NULL
    LIMIT p_max
  LOOP
    SELECT status_code, content
    INTO   v_sc, v_body
    FROM   net._http_response
    WHERE  id = rec.search_req_id;

    IF NOT FOUND THEN
      v_wait := v_wait + 1;
      CONTINUE;
    END IF;

    v_site_id  := NULL;
    v_slug     := NULL;
    v_site_url := NULL;

    IF v_sc = 200 AND length(COALESCE(v_body,'')) > 100 THEN
      -- Extrai URL somarcas.com.br/{site_id}/produto/{slug}
      v_m := regexp_match(v_body,
        'somarcas\.com\.br/([0-9]+)/produto/([a-z0-9][a-z0-9-]+)');
      IF v_m IS NOT NULL THEN
        v_site_id  := v_m[1]::int;
        v_slug     := v_m[2];
        -- ── FIX: calcular site_url completa ──────────────────────────────
        v_site_url := 'https://www.somarcas.com.br/' || v_site_id || '/produto/' || v_slug;
      END IF;
    END IF;

    IF v_site_id IS NOT NULL THEN
      UPDATE public.sm_site_url_map
        SET site_id          = v_site_id,
            slug             = COALESCE(v_slug, slug),
            -- ── FIX: gravar site_url para que fn_sm_site_enqueue possa enfileirar ──
            site_url         = v_site_url,
            source           = 'jina_search',
            confidence       = 'medium',
            search_status    = 'done',
            last_verified_at = now()
      WHERE id = rec.id;
      v_ok := v_ok + 1;
    ELSE
      UPDATE public.sm_site_url_map
        SET search_status = 'failed',
            search_req_id = NULL
      WHERE id = rec.id;
      v_fail := v_fail + 1;
    END IF;

    DELETE FROM net._http_response WHERE id = rec.search_req_id;

  END LOOP;

  RETURN jsonb_build_object('ok',v_ok,'fail',v_fail,'wait',v_wait,'ts',now());
END;
$$;

REVOKE ALL ON FUNCTION public.fn_sm_url_discover_collect(integer)
    FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_sm_url_discover_collect(integer)
    TO service_role;

COMMENT ON FUNCTION public.fn_sm_url_discover_collect IS
    'Coleta resultados de buscas Jina para descoberta de URLs SM. '
    'FIX v2: agora grava site_url completa além do site_id, '
    'permitindo que fn_sm_site_enqueue enfileira os produtos descobertos.';
;

-- <<< END 20260607123859_fix_sm_url_discover_collect_site_url.sql <<<

-- >>> BEGIN 20260607123912_fix_sm_parser_immutable_to_stable.sql >>>

-- ============================================================
--  BUG FIX 2: fn_parse_sm_site_markdown
--  Problema: declarada como IMMUTABLE mas usa now() internamente.
--  IMMUTABLE significa que o Postgres pode cachear o resultado
--  por argumentos idênticos → scraped_at poderia ficar congelado
--  no primeiro valor e jamais atualizar.
--  Fix: mudar para STABLE (correto para funções que usam clock)
-- ============================================================
ALTER FUNCTION public.fn_parse_sm_site_markdown(text, text)
    VOLATILE;
-- Volatile é mais seguro aqui pois o parser grava scraped_at=now()
-- e pode ser chamado em contextos de trigger ou cron onde
-- STABLE também seria problemático (cada chamada deve ter o now() atual)

COMMENT ON FUNCTION public.fn_parse_sm_site_markdown IS
    'Parser SM site markdown → jsonb estruturado. '
    'FIX v2: mudado de IMMUTABLE para VOLATILE (usava now() internamente, '
    'o que violava o contrato de IMMUTABLE e causava scraped_at congelado).';
;

-- <<< END 20260607123912_fix_sm_parser_immutable_to_stable.sql <<<

-- >>> BEGIN 20260607124027_fix_sm_site_collect_promote_security.sql >>>

-- ============================================================
--  BUG FIX 3: SECURITY DEFINER + search_path correto em
--  fn_sm_site_collect, fn_sm_site_promote e fn_sm_site_tick
--  Sem isso, chamadas fora do contexto cron (ex.: Edge Function,
--  authenticated role) falham por falta de acesso a net.*, vault.*
-- ============================================================

-- ── fn_sm_site_tick (orquestrador) ──────────────────────────
CREATE OR REPLACE FUNCTION public.fn_sm_site_tick(
    p_enqueue   integer DEFAULT 5,
    p_collect   integer DEFAULT 20,
    p_stale_days integer DEFAULT 7,
    p_with_auth  boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, net, vault, extensions
AS $$
DECLARE
  v_enq  int;
  v_coll jsonb;
  v_prom jsonb;
BEGIN
  -- Ordem: collect primeiro (limpa responses pendentes) → enqueue → promote
  v_coll := public.fn_sm_site_collect(p_collect);
  v_enq  := public.fn_sm_site_enqueue(p_enqueue, p_stale_days, NULL, p_with_auth);
  v_prom := public.fn_sm_site_promote(50);
  RETURN jsonb_build_object(
    'collect',  v_coll,
    'enqueued', v_enq,
    'promote',  v_prom,
    'ts',       now()
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_sm_site_tick(integer,integer,integer,boolean)
    FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_sm_site_tick(integer,integer,integer,boolean)
    TO service_role;

COMMENT ON FUNCTION public.fn_sm_site_tick IS
    'Orquestrador SM Jina Pipeline. Chama collect → enqueue → promote. '
    'FIX v2: SECURITY DEFINER + search_path correto.';
;

-- <<< END 20260607124027_fix_sm_site_collect_promote_security.sql <<<

-- >>> BEGIN 20260607124223_fix_sm_url_map_revert_trigger_and_fix_collect.sql >>>

-- ============================================================
--  FIX CRÍTICO: site_url é GENERATED ALWAYS AS (site_id || slug)
--  → remover trigger desnecessário
--  → corrigir fn_sm_url_discover_collect que agora tem
--    "site_url = v_site_url" — isso causa erro em generated column
-- ============================================================

-- 1. Remover o trigger recém-criado (desnecessário — gerado automaticamente)
DROP TRIGGER IF EXISTS trg_sm_url_map_compute_site_url ON public.sm_site_url_map;
DROP FUNCTION IF EXISTS public.fn_sm_url_map_compute_site_url();

-- 2. Corrigir fn_sm_url_discover_collect:
--    Remover o "site_url = v_site_url" — GENERATED column não aceita SET explícito
CREATE OR REPLACE FUNCTION public.fn_sm_url_discover_collect(p_max integer DEFAULT 20)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, net
AS $$
DECLARE
  v_sup       uuid := '841cd690-210a-422a-908c-7676828db272';
  rec         record;
  v_body      text;
  v_sc        int;
  v_m         text[];
  v_site_id   int;
  v_slug      text;
  v_ok        int := 0;
  v_fail      int := 0;
  v_wait      int := 0;
BEGIN
  FOR rec IN
    SELECT id, codigo, slug, search_req_id
    FROM public.sm_site_url_map
    WHERE supplier_id    = v_sup
      AND search_status  = 'pending'
      AND search_req_id  IS NOT NULL
    LIMIT p_max
  LOOP
    SELECT status_code, content
    INTO   v_sc, v_body
    FROM   net._http_response
    WHERE  id = rec.search_req_id;

    IF NOT FOUND THEN
      v_wait := v_wait + 1;
      CONTINUE;
    END IF;

    v_site_id := NULL;
    v_slug    := NULL;

    IF v_sc = 200 AND length(COALESCE(v_body,'')) > 100 THEN
      v_m := regexp_match(v_body,
        'somarcas\.com\.br/([0-9]+)/produto/([a-z0-9][a-z0-9-]+)');
      IF v_m IS NOT NULL THEN
        v_site_id := v_m[1]::int;
        v_slug    := v_m[2];
        -- NOTA: site_url é GENERATED ALWAYS AS (site_id || slug)
        -- Não precisa ser setada explicitamente — o Postgres a computa.
      END IF;
    END IF;

    IF v_site_id IS NOT NULL THEN
      UPDATE public.sm_site_url_map
        SET site_id          = v_site_id,
            slug             = COALESCE(v_slug, slug),
            -- site_url NÃO É setada: é GENERATED column, auto-computada
            source           = 'jina_search',
            confidence       = 'medium',
            search_status    = 'done',
            last_verified_at = now()
      WHERE id = rec.id;
      v_ok := v_ok + 1;
    ELSE
      UPDATE public.sm_site_url_map
        SET search_status = 'failed',
            search_req_id = NULL
      WHERE id = rec.id;
      v_fail := v_fail + 1;
    END IF;

    DELETE FROM net._http_response WHERE id = rec.search_req_id;

  END LOOP;

  RETURN jsonb_build_object('ok',v_ok,'fail',v_fail,'wait',v_wait,'ts',now());
END;
$$;

REVOKE ALL ON FUNCTION public.fn_sm_url_discover_collect(integer)
    FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_sm_url_discover_collect(integer)
    TO service_role;

COMMENT ON FUNCTION public.fn_sm_url_discover_collect IS
    'Coleta resultados Jina Search para descoberta de URLs SM. '
    'SECURITY DEFINER + search_path correto. '
    'NOTE: site_url é GENERATED ALWAYS AS, não precisa de SET explícito.';
;

-- <<< END 20260607124223_fix_sm_url_map_revert_trigger_and_fix_collect.sql <<<

-- >>> BEGIN 20260607124931_fix_sm_parser_fotos_spec_related_v3.sql >>>

-- ============================================================
--  BUG FIX 5+6+7: fn_parse_sm_site_markdown v3
--
--  BUG 6 (CRÍTICO): fotos_cdn capturava ALL URLs CDN incluindo
--    thumbnails m/ de produtos RELACIONADOS.
--    Fix: excluir /m/ prefix; manter apenas /g/, /p/, hash-files
--         e imagens_site/ (sem v4 subfolder)
--
--  BUG 7: spec_tecnica regex apenas .png — arquivo real é .jpg
--    Fix: aceitar .jpg e .png na regex de hash-filename
--
--  BUG 5: relacionados sem codigo eram ignorados no collect.
--    Fix no PARSER: emitir relacionados sem codigo também
--    (fn_sm_site_collect os insere na URL map via fn_sm_url_map_from_site_urls)
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_parse_sm_site_markdown(
    p_md        text,
    p_source_url text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
VOLATILE
AS $$
DECLARE
  v_codigo      text;
  v_video_url   text;
  v_spec_url    text;
  v_photos      text[];
  v_related     jsonb    := '[]'::jsonb;
  v_price_tiers jsonb;
  v_master      jsonb;
  v_ncm         text;
  v_ipi         numeric;
  v_estoque     int;
  v_m           text[];
  v_m2          text[];
  v_tiers       jsonb    := '[]'::jsonb;
  v_qtds        text[];
  v_p_si        text[];
  v_p_ci        text[];
  v_i           int;
  v_rel_sid     int;
  v_rel_slug    text;
  v_rel_codigo  text;
  v_ctx_start   int;
  v_ctx         text;
BEGIN
  IF p_md IS NULL OR length(btrim(p_md)) < 200 THEN
    RETURN jsonb_build_object('error','conteudo_vazio','len',length(COALESCE(p_md,'')));
  END IF;

  -- 1. Código do produto (SM código: AS-00610, LE-31723, etc.)
  v_m := regexp_match(p_md, '\b([A-Z]{2,3}-[0-9]{4,6}(?:-[0-9]+)?)\b');
  IF v_m IS NOT NULL THEN v_codigo := v_m[1]; END IF;

  -- 2. Vídeo YouTube
  v_m := regexp_match(p_md, 'youtube\.com/watch\?v=([A-Za-z0-9_-]{6,15})');
  IF v_m IS NOT NULL THEN
    v_video_url := 'https://www.youtube.com/watch?v=' || v_m[1];
  ELSE
    v_m := regexp_match(p_md, 'youtube\.com/embed/([A-Za-z0-9_-]{6,15})');
    IF v_m IS NOT NULL THEN
      v_video_url := 'https://www.youtube.com/watch?v=' || v_m[1];
    END IF;
  END IF;

  -- 3. Spec técnica (BUG 7 FIX: aceitar .jpg E .png no hash-filename)
  v_m := regexp_match(p_md,
    'Especifica[cç][oõ]es? T[eé]cnicas\]\((https://[^)]+\.(?:png|jpg|jpeg))\)', 'i');
  IF v_m IS NOT NULL THEN
    v_spec_url := v_m[1];
  ELSE
    -- Hash-filename: 30+ hex chars + extensão (.png ou .jpg)
    v_m := regexp_match(p_md,
      '(https://somarcascdn\.azureedge\.net/upload/imagens_site_v4/[a-f0-9]{30,}\.(?:png|jpg|jpeg))');
    IF v_m IS NOT NULL THEN v_spec_url := v_m[1]; END IF;
  END IF;

  -- 4. Fotos CDN (BUG 6 FIX: excluir thumbnails m/ de produtos relacionados)
  --    Aceitar apenas:
  --    • /imagens_site_v4/g/  ← fotos grandes do produto
  --    • /imagens_site_v4/p/  ← thumbnails do produto
  --    • /imagens_site_v4/{hash}.{ext}  ← spec técnica / hero
  --    • /imagens_site/{filename}  ← imagens legado
  --    EXCLUIR: /imagens_site_v4/m/ (thumbnails de relacionados)
  SELECT array_agg(DISTINCT m[1])
  INTO   v_photos
  FROM   regexp_matches(p_md,
    '(https://somarcas(?:cdn)?\.azureedge\.net/upload/(?:'
      'imagens_site_v4/[gp]/[^"\)\s]+\.(?:webp|jpg|png|jpeg)'
      '|imagens_site_v4/[a-f0-9]{20,}\.[a-z]+'    -- hash-filename spec
      '|imagens_site/[^"\)\s]+\.(?:webp|jpg|png|jpeg)'  -- legado sem v4
    '))', 'g') m
  WHERE m[1] NOT ILIKE '%/m/%';   -- guaraná extra: excluir /m/ explicitamente

  -- 5. Produtos relacionados (BUG 5 FIX: emitir TODOS, com ou sem codigo)
  FOR v_m IN
    SELECT regexp_matches(p_md,
      'somarcas\.com\.br/([0-9]+)/produto/([a-z0-9][a-z0-9-]+[a-z0-9])', 'g')
  LOOP
    v_rel_sid  := v_m[1]::int;
    v_rel_slug := v_m[2];
    v_rel_codigo := NULL;

    -- Tenta extrair codigo do contexto próximo (janela de 250 chars antes/depois)
    v_ctx_start := strpos(p_md, v_m[1] || '/produto/' || v_m[2]);
    IF v_ctx_start > 0 THEN
      v_ctx := substring(p_md FROM GREATEST(1, v_ctx_start - 250) FOR 280);
      -- Formato bold: **AS-00610**
      v_m2 := regexp_match(v_ctx, '\*\*([A-Z]{2,3}-[0-9]{4,6}(?:-[0-9]+)?)\*\*');
      IF v_m2 IS NOT NULL THEN v_rel_codigo := v_m2[1]; END IF;
    END IF;

    -- BUG 5 FIX: emitir SEMPRE (mesmo sem codigo)
    -- fn_sm_site_collect vai decidir o que fazer com cada tipo
    v_related := v_related || jsonb_build_object(
      'site_id', v_rel_sid,
      'slug',    v_rel_slug,
      'codigo',  v_rel_codigo   -- NULL quando não detectado — OK
    );
  END LOOP;

  -- Desduplicar por site_id
  IF jsonb_array_length(v_related) > 0 THEN
    SELECT jsonb_agg(r) INTO v_related
    FROM (
      SELECT DISTINCT ON ((r->>'site_id')::int) r
      FROM jsonb_array_elements(v_related) r
      ORDER BY (r->>'site_id')::int,
               CASE WHEN r->>'codigo' IS NOT NULL THEN 0 ELSE 1 END  -- prioriza com codigo
    ) s;
  END IF;

  -- 6. Tabela de preços (requer auth)
  IF position('50 un' IN p_md) > 0 AND position('Sem impostos' IN p_md) > 0 THEN
    v_m := regexp_match(p_md, 'Qualquer un\.[^\n]*([0-9]+\s*un[^\n]+)\n');
    IF v_m IS NOT NULL THEN
      SELECT array_agg(trim(q.q)) INTO v_qtds
      FROM regexp_split_to_table(v_m[1], '\|') q(q)
      WHERE trim(q.q) ~ '[0-9]+\s*un';
    END IF;
    v_m := regexp_match(p_md, 'Sem impostos[^\n]*\n([^\n]+)');
    IF v_m IS NOT NULL THEN
      SELECT array_agg(replace(m[1],',','.')) INTO v_p_si
      FROM regexp_matches(v_m[1], 'R\$\s*([0-9]+[,\.][0-9]+)', 'g') m;
    END IF;
    v_m := regexp_match(p_md, 'Com IPI[^\n]*\n([^\n]+)');
    IF v_m IS NOT NULL THEN
      SELECT array_agg(replace(m[1],',','.')) INTO v_p_ci
      FROM regexp_matches(v_m[1], 'R\$\s*([0-9]+[,\.][0-9]+)', 'g') m;
    END IF;
    IF v_qtds IS NOT NULL AND v_p_si IS NOT NULL THEN
      FOR v_i IN 1..LEAST(array_length(v_qtds,1), array_length(v_p_si,1)) LOOP
        v_tiers := v_tiers || jsonb_build_object(
          'qtd_label',     v_qtds[v_i],
          'preco_sem_ipi', v_p_si[v_i]::numeric,
          'preco_com_ipi', CASE WHEN v_p_ci IS NOT NULL
                                AND v_i <= array_length(v_p_ci,1)
                                THEN v_p_ci[v_i]::numeric ELSE NULL END
        );
      END LOOP;
      IF jsonb_array_length(v_tiers) > 0 THEN v_price_tiers := v_tiers; END IF;
    END IF;
  END IF;

  -- 7. Caixa Master
  DECLARE v_mq text[]; v_mw text[]; BEGIN
    v_m  := regexp_match(p_md, 'DIMENS[OÕ]ES[^\n]*CAIXA[^\n]*\n[^\n]*?([0-9].{5,25}cm)', 'i');
    v_mq := regexp_match(p_md, '([0-9]+)\s+unidades?\s+por\s+caixa', 'i');
    v_mw := regexp_match(p_md, 'PESO\s+TOTAL[^\n]*\n[^\n]*?([0-9]+[,.]?[0-9]*)\s*kg', 'i');
    IF v_m IS NOT NULL OR v_mq IS NOT NULL OR v_mw IS NOT NULL THEN
      v_master := jsonb_strip_nulls(jsonb_build_object(
        'dims',    CASE WHEN v_m  IS NOT NULL THEN v_m[1]  ELSE NULL END,
        'qtd',     CASE WHEN v_mq IS NOT NULL THEN v_mq[1]::int ELSE NULL END,
        'peso_kg', CASE WHEN v_mw IS NOT NULL THEN replace(v_mw[1],',','.')::numeric ELSE NULL END
      ));
      IF v_master = '{}'::jsonb THEN v_master := NULL; END IF;
    END IF;
  END;

  -- 8. NCM / IPI / Estoque
  v_m := regexp_match(p_md, '\bNCM\b[^\n]*?([0-9]{8})', 'i');
  IF v_m IS NOT NULL THEN v_ncm := v_m[1]; END IF;

  v_m := regexp_match(p_md, 'IPI[^0-9]*([0-9]+[,.]?[0-9]*)\s*%', 'i');
  IF v_m IS NOT NULL THEN v_ipi := replace(v_m[1],',','.')::numeric; END IF;

  v_m := regexp_match(p_md, 'Estoque\s+de\s+([0-9.]+)\s+unidades', 'i');
  IF v_m IS NOT NULL THEN v_estoque := replace(v_m[1],'.','')::int; END IF;

  RETURN jsonb_strip_nulls(jsonb_build_object(
    'scraped_at',        now(),
    'source_url',        p_source_url,
    'codigo_detectado',  v_codigo,
    'video_url',         v_video_url,
    'spec_tecnica_url',  v_spec_url,
    'fotos_cdn',         CASE WHEN v_photos IS NOT NULL THEN to_jsonb(v_photos) ELSE NULL END,
    'relacionados',      CASE WHEN jsonb_array_length(v_related) > 0 THEN v_related ELSE NULL END,
    'price_tiers',       v_price_tiers,
    'caixa_master',      v_master,
    'ncm_site',          v_ncm,
    'ipi_site',          v_ipi,
    'estoque_site',      v_estoque,
    'is_authenticated',  (v_price_tiers IS NOT NULL OR v_master IS NOT NULL)
  ));
END;
$$;

COMMENT ON FUNCTION public.fn_parse_sm_site_markdown IS
    'v3 — Fixes: '
    '(6) fotos_cdn exclui thumbnails m/ de relacionados; '
    '(7) spec_tecnica aceita .jpg e .png; '
    '(5) relacionados emitidos mesmo sem codigo; '
    'VOLATILE (usa now()).';
;

-- <<< END 20260607124931_fix_sm_parser_fotos_spec_related_v3.sql <<<

-- >>> BEGIN 20260607125019_fix_sm_site_collect_related_no_codigo.sql >>>

-- ============================================================
--  BUG FIX 5 (parte 2): fn_sm_site_collect v2
--  Problema: relacionados sem 'codigo' eram ignorados
--  Fix: coleta TODOS (site_id, slug, codigo_ou_null)
--       → com codigo  → INSERT direto em sm_site_url_map
--       → sem codigo  → acumula e chama fn_sm_url_map_from_site_urls (slug match)
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_sm_site_collect(p_max integer DEFAULT 20)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, net, extensions
AS $$
DECLARE
  v_sup         uuid := '841cd690-210a-422a-908c-7676828db272';
  rec           record;
  v_sc          int;
  v_body        text;
  v_payload     jsonb;
  v_hash        text;
  v_err         text;
  v_ok          int  := 0;
  v_fail        int  := 0;
  v_wait        int  := 0;
  v_new_urls    int  := 0;
  v_rows        int  := 0;
  v_rel         jsonb;
  v_rel_item    jsonb;
  v_rel_codigo  text;
  v_rel_sid     int;
  v_rel_slug    text;
  -- Acumulador de (site_id, slug) sem codigo → slug-match batch
  v_no_codigo   jsonb := '[]'::jsonb;
  v_slug_result jsonb;
BEGIN

  FOR rec IN
    SELECT spr.id                   AS spr_id,
           spr.site_fetch_req_id    AS req_id,
           spr.site_source_url      AS source_url,
           spr.raw_data->>'codigo'  AS codigo
    FROM   supplier_products_raw spr
    WHERE  spr.supplier_id  = v_sup
      AND  spr.site_status  = 'processing'
      AND  spr.site_fetch_req_id IS NOT NULL
    LIMIT  p_max
  LOOP
    SELECT status_code, content
    INTO   v_sc, v_body
    FROM   net._http_response
    WHERE  id = rec.req_id;

    IF NOT FOUND THEN
      v_wait := v_wait + 1;
      CONTINUE;
    END IF;

    v_err := NULL;

    -- Validação de qualidade mínima
    IF v_sc <> 200 THEN
      v_err := 'HTTP ' || COALESCE(v_sc::text, '?');
    ELSIF length(COALESCE(v_body,'')) < 500 THEN
      v_err := 'resposta_curta len=' || length(COALESCE(v_body,''));
    ELSIF position('Just a moment' IN v_body) > 0
       OR position('Enable JavaScript' IN v_body) > 0 THEN
      v_err := 'cloudflare_challenge';
    ELSE
      v_payload := public.fn_parse_sm_site_markdown(v_body, rec.source_url);

      IF v_payload ? 'error' THEN
        v_err := 'parse_error:' || (v_payload->>'error');
      -- Aceitar se há pelo menos fotos CDN OU relacionados (sem exigir codigo)
      ELSIF (v_payload->'fotos_cdn') IS NULL
         AND (v_payload->'relacionados') IS NULL
         AND (v_payload->>'video_url') IS NULL THEN
        v_err := 'pagina_nao_produto';
      END IF;
    END IF;

    IF v_err IS NULL THEN
      v_hash := encode(extensions.digest(v_payload::text, 'sha256'), 'hex');

      UPDATE supplier_products_raw
        SET site_data         = v_payload,
            site_hash         = v_hash,
            site_status       = 'processed',
            site_scraped_at   = now(),
            site_processed_at = now(),
            site_last_error   = NULL,
            site_fetch_req_id = NULL
      WHERE id = rec.spr_id;

      v_ok := v_ok + 1;

      -- ── Expande URL map com relacionados ───────────────────────────────
      v_rel := v_payload->'relacionados';
      IF v_rel IS NOT NULL AND jsonb_array_length(v_rel) > 0 THEN
        FOR v_rel_item IN SELECT * FROM jsonb_array_elements(v_rel) LOOP
          v_rel_sid   := (v_rel_item->>'site_id')::int;
          v_rel_slug  := v_rel_item->>'slug';
          v_rel_codigo:= v_rel_item->>'codigo';  -- pode ser NULL

          CONTINUE WHEN v_rel_sid IS NULL OR v_rel_slug IS NULL;

          IF v_rel_codigo IS NOT NULL THEN
            -- Path A: codigo conhecido → INSERT direto
            INSERT INTO public.sm_site_url_map
              (supplier_id, codigo, site_id, slug, source, confidence, last_verified_at)
            VALUES
              (v_sup, v_rel_codigo, v_rel_sid, v_rel_slug,
               'related_products', 'high', now())
            ON CONFLICT (supplier_id, codigo) DO UPDATE
              SET site_id          = EXCLUDED.site_id,
                  slug             = EXCLUDED.slug,
                  source           = EXCLUDED.source,
                  confidence       = EXCLUDED.confidence,
                  last_verified_at = EXCLUDED.last_verified_at
              WHERE sm_site_url_map.site_id IS DISTINCT FROM EXCLUDED.site_id;

            GET DIAGNOSTICS v_rows = ROW_COUNT;
            v_new_urls := v_new_urls + v_rows;
          ELSE
            -- Path B: sem codigo → acumula para slug-match em batch
            v_no_codigo := v_no_codigo || jsonb_build_object(
              'site_id', v_rel_sid, 'slug', v_rel_slug
            );
          END IF;
        END LOOP;
      END IF;

    ELSE
      UPDATE supplier_products_raw
        SET site_status       = 'failed',
            site_attempts     = COALESCE(site_attempts, 0) + 1,
            site_last_error   = v_err,
            site_fetch_req_id = NULL
      WHERE id = rec.spr_id;

      v_fail := v_fail + 1;
    END IF;

    DELETE FROM net._http_response WHERE id = rec.req_id;

  END LOOP;

  -- ── Batch slug-match para relacionados sem codigo ──────────────────────
  IF jsonb_array_length(v_no_codigo) > 0 THEN
    v_slug_result := public.fn_sm_url_map_from_site_urls(v_no_codigo);
    v_new_urls := v_new_urls + COALESCE((v_slug_result->>'resolved')::int, 0);
  END IF;

  RETURN jsonb_build_object(
    'ok',              v_ok,
    'fail',            v_fail,
    'aguardando',      v_wait,
    'new_url_map',     v_new_urls,
    'slug_matched',    COALESCE((v_slug_result->>'resolved')::int, 0),
    'slug_unmatched',  COALESCE((v_slug_result->>'unmatched')::int, 0),
    'ts',              now()
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_sm_site_collect(integer)
    FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_sm_site_collect(integer)
    TO service_role;

COMMENT ON FUNCTION public.fn_sm_site_collect IS
    'v2 — Coleta respostas Jina, valida, parseia e grava site_data. '
    'SECURITY DEFINER + search_path. '
    'Fix 5: relacionados sem codigo → slug-match via fn_sm_url_map_from_site_urls. '
    'Fix: critério de página válida usa fotos_cdn OR relacionados (sem exigir codigo).';
;

-- <<< END 20260607125019_fix_sm_site_collect_related_no_codigo.sql <<<

-- >>> BEGIN 20260607125336_fn_sm_pipeline_health_v1.sql >>>

-- ============================================================
--  fn_sm_pipeline_health — Diagnóstico completo do pipeline SM
--  Retorna um JSON com todos os KPIs em uma chamada.
--  Útil para dashboards, alertas e validação pós-deploy.
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_sm_pipeline_health()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, vault
AS $$
DECLARE
  v_sup   uuid := '841cd690-210a-422a-908c-7676828db272';
  v_jina  text;
  v_cook  text;
  v_res   jsonb;
BEGIN
  -- Verificar Vault secrets (sem expor valores)
  BEGIN
    SELECT decrypted_secret INTO v_jina
    FROM vault.decrypted_secrets WHERE name='jina_api_key';
    SELECT decrypted_secret INTO v_cook
    FROM vault.decrypted_secrets WHERE name='sm_session_cookie';
  EXCEPTION WHEN OTHERS THEN NULL;
  END;

  SELECT jsonb_build_object(
    'ts', now(),
    'supplier', 'Só Marcas',
    'supplier_id', v_sup,

    -- ── Vault ─────────────────────────────────────────────────────────────
    'vault', jsonb_build_object(
      'jina_api_key',       CASE WHEN v_jina IS NULL OR v_jina LIKE '__PLACEHOLDER%'
                                 THEN 'placeholder/missing' ELSE 'ok' END,
      'sm_session_cookie',  CASE WHEN v_cook IS NULL OR v_cook LIKE '__PLACEHOLDER%'
                                 THEN 'placeholder/missing' ELSE 'ok' END
    ),

    -- ── Bronze ────────────────────────────────────────────────────────────
    'bronze', jsonb_build_object(
      'total',        (SELECT count(*) FROM supplier_products_raw WHERE supplier_id=v_sup),
      'site_pending', (SELECT count(*) FROM supplier_products_raw
                       WHERE supplier_id=v_sup AND site_status='pending'),
      'site_processing', (SELECT count(*) FROM supplier_products_raw
                          WHERE supplier_id=v_sup AND site_status='processing'),
      'site_processed',  (SELECT count(*) FROM supplier_products_raw
                          WHERE supplier_id=v_sup AND site_status='processed'),
      'site_failed',     (SELECT count(*) FROM supplier_products_raw
                          WHERE supplier_id=v_sup AND site_status='failed'),
      'site_promoted',   (SELECT count(*) FROM supplier_products_raw
                          WHERE supplier_id=v_sup AND site_promoted_at IS NOT NULL),
      'last_scraped_at', (SELECT max(site_scraped_at) FROM supplier_products_raw
                          WHERE supplier_id=v_sup),
      'pct_scraped', round(100.0 *
        (SELECT count(*) FROM supplier_products_raw
         WHERE supplier_id=v_sup AND site_status='processed') /
        NULLIF((SELECT count(*) FROM supplier_products_raw WHERE supplier_id=v_sup), 0), 1),
      'errors_sample', (SELECT jsonb_agg(jsonb_build_object('codigo', raw_data->>'codigo',
                          'err', site_last_error, 'att', site_attempts))
                        FROM (SELECT raw_data, site_last_error, site_attempts
                              FROM supplier_products_raw
                              WHERE supplier_id=v_sup AND site_status='failed'
                              LIMIT 5) e)
    ),

    -- ── URL Map ───────────────────────────────────────────────────────────
    'url_map', jsonb_build_object(
      'total',           (SELECT count(*) FROM sm_site_url_map WHERE supplier_id=v_sup),
      'with_url',        (SELECT count(*) FROM sm_site_url_map
                          WHERE supplier_id=v_sup AND site_url IS NOT NULL),
      'without_site_id', (SELECT count(*) FROM sm_site_url_map
                          WHERE supplier_id=v_sup AND site_id IS NULL),
      'coverage_pct',    round(100.0 *
        (SELECT count(*) FROM sm_site_url_map WHERE supplier_id=v_sup AND site_url IS NOT NULL) /
        NULLIF((SELECT count(*) FROM supplier_products_raw WHERE supplier_id=v_sup), 0), 1),
      'by_source', (SELECT jsonb_object_agg(source, cnt)
                    FROM (SELECT source, count(*) AS cnt FROM sm_site_url_map
                          WHERE supplier_id=v_sup AND site_id IS NOT NULL
                          GROUP BY source) s),
      'search_status', (SELECT jsonb_object_agg(COALESCE(ss,'null'), cnt)
                        FROM (SELECT search_status AS ss, count(*) AS cnt
                              FROM sm_site_url_map
                              WHERE supplier_id=v_sup AND site_id IS NULL
                              GROUP BY ss) s)
    ),

    -- ── Gold ──────────────────────────────────────────────────────────────
    'gold', jsonb_build_object(
      'total_products',    (SELECT count(*) FROM products WHERE supplier_id=v_sup),
      'with_site_url',     (SELECT count(*) FROM products
                            WHERE supplier_id=v_sup AND supplier_product_url IS NOT NULL),
      'with_ncm',          (SELECT count(*) FROM products
                            WHERE supplier_id=v_sup AND ncm_code IS NOT NULL),
      'site_properties',   (SELECT count(*) FROM product_properties pp
                            JOIN products p ON p.id=pp.product_id
                            WHERE p.supplier_id=v_sup AND pp.source LIKE 'sm_site%'),
      'by_property_code',  (SELECT jsonb_object_agg(property_code, cnt)
                            FROM (SELECT pp.property_code, count(*) AS cnt
                                  FROM product_properties pp
                                  JOIN products p ON p.id=pp.product_id
                                  WHERE p.supplier_id=v_sup AND pp.source LIKE 'sm_site%'
                                  GROUP BY pp.property_code) s)
    ),

    -- ── Cron jobs ─────────────────────────────────────────────────────────
    'cron_jobs', (SELECT jsonb_agg(jsonb_build_object(
      'id', j.jobid, 'name', j.jobname, 'schedule', j.schedule, 'active', j.active,
      'last_run', jr.start_time, 'last_status', jr.status
    ))
    FROM cron.job j
    LEFT JOIN LATERAL (
      SELECT start_time, status FROM cron.job_run_details
      WHERE jobid = j.jobid ORDER BY start_time DESC LIMIT 1
    ) jr ON true
    WHERE j.jobname ILIKE '%sm%' OR j.command ILIKE '%sm%')

  ) INTO v_res;

  RETURN v_res;
END;
$$;

GRANT EXECUTE ON FUNCTION public.fn_sm_pipeline_health() TO service_role, authenticated;

COMMENT ON FUNCTION public.fn_sm_pipeline_health IS
    'Health check completo do SM Jina Scraping Pipeline. '
    'Retorna KPIs de Vault, Bronze, URL Map, Gold e Cron Jobs em um JSON.';
;

-- <<< END 20260607125336_fn_sm_pipeline_health_v1.sql <<<

-- >>> BEGIN 20260607125523_sm_category_pages_and_scraping.sql >>>

-- ============================================================
--  SM CATEGORY SCRAPING PIPELINE
--  Fase: descoberta de site_ids via páginas de categoria
--
--  Estratégia:
--  1. sm_category_pages: tabela de categorias a scraper
--  2. Seed via matriz_de_categorias do Bronze
--  3. fn_sm_category_enqueue: Jina requests para cada categoria
--  4. fn_sm_category_collect: extrai (site_id, slug) → fn_sm_url_map_from_site_urls
-- ============================================================

-- ── 1. Tabela sm_category_pages ─────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.sm_category_pages (
    id              uuid        NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
    name            text        NOT NULL,     -- ex.: "Copos, Canecas, Squeezes e Garrafas"
    slug            text        NOT NULL,     -- ex.: "copos-canecas-squeezes-e-garrafas"
    category_id     integer,                  -- site_id da categoria (descoberto via scrape)
    site_url        text GENERATED ALWAYS AS (
                      CASE WHEN category_id IS NOT NULL
                           THEN 'https://www.somarcas.com.br/'
                                || category_id::text
                                || '/categorias/'
                                || slug
                           ELSE NULL
                      END
                    ) STORED,
    -- Status do scraping
    status          text        NOT NULL DEFAULT 'pending',
    fetch_req_id    bigint,
    attempts        integer     NOT NULL DEFAULT 0,
    last_error      text,
    last_scraped_at timestamptz,
    products_found  integer     DEFAULT 0,    -- quantos produtos encontrados nesta página
    -- Paginação (SM categorias podem ter várias páginas)
    current_page    integer     NOT NULL DEFAULT 1,
    has_more_pages  boolean     NOT NULL DEFAULT false,
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT sm_category_pages_slug_uq UNIQUE (slug),
    CONSTRAINT sm_category_pages_status_chk
        CHECK (status IN ('pending','processing','done','failed','partial'))
);

CREATE INDEX IF NOT EXISTS sm_category_pages_status_idx ON public.sm_category_pages (status);
CREATE INDEX IF NOT EXISTS sm_category_pages_cid_idx    ON public.sm_category_pages (category_id)
    WHERE category_id IS NOT NULL;

-- Trigger updated_at
CREATE OR REPLACE FUNCTION public.fn_sm_category_set_updated()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;

DROP TRIGGER IF EXISTS trg_sm_category_updated ON public.sm_category_pages;
CREATE TRIGGER trg_sm_category_updated
    BEFORE UPDATE ON public.sm_category_pages
    FOR EACH ROW EXECUTE FUNCTION public.fn_sm_category_set_updated();

-- RLS
ALTER TABLE public.sm_category_pages ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies
    WHERE tablename='sm_category_pages' AND policyname='sm_cat_service_all') THEN
    EXECUTE 'CREATE POLICY sm_cat_service_all ON public.sm_category_pages
             FOR ALL TO service_role USING (true) WITH CHECK (true)';
    EXECUTE 'CREATE POLICY sm_cat_auth_read ON public.sm_category_pages
             FOR SELECT TO authenticated USING (true)';
  END IF;
END $$;

COMMENT ON TABLE public.sm_category_pages IS
    'Páginas de categoria do site Só Marcas a serem scrapeadas para descoberta de site_ids. '
    'Cada categoria tem múltiplos produtos — scraping em batch via Jina Reader.';


-- ── 2. fn_sm_category_seed: popula sm_category_pages a partir do Bronze ─
CREATE OR REPLACE FUNCTION public.fn_sm_category_seed()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_sup    uuid := '841cd690-210a-422a-908c-7676828db272';
  v_ins    int  := 0;
  v_rows   int  := 0;
  v_name   text;
  v_slug   text;
BEGIN
  -- Explodir pipe-delimited, slugificar, desduplicar e inserir
  INSERT INTO public.sm_category_pages (name, slug)
  SELECT DISTINCT
    trim(cat)                      AS name,
    public.fn_slugify(trim(cat))   AS slug
  FROM supplier_products_raw,
       regexp_split_to_table(raw_data->>'matriz_de_categorias', '\|') cat
  WHERE supplier_id = v_sup
    AND raw_data->>'matriz_de_categorias' IS NOT NULL
    AND raw_data->>'matriz_de_categorias' != ''
    AND trim(cat) != ''
    AND public.fn_slugify(trim(cat)) IS NOT NULL
    AND length(public.fn_slugify(trim(cat))) > 3
  ON CONFLICT (slug) DO NOTHING;

  GET DIAGNOSTICS v_ins = ROW_COUNT;

  RETURN jsonb_build_object(
    'categories_seeded', v_ins,
    'total_in_table',    (SELECT count(*) FROM sm_category_pages),
    'ts', now()
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.fn_sm_category_seed() TO service_role;


-- ── 3. fn_sm_category_enqueue: dispara Jina Reader para cada categoria ──
CREATE OR REPLACE FUNCTION public.fn_sm_category_enqueue(
    p_limit     integer DEFAULT 3,
    p_jina_key  text    DEFAULT NULL
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, vault, net
AS $$
DECLARE
  v_jina_key  text := p_jina_key;
  v_headers   jsonb;
  rec         record;
  v_req       bigint;
  v_n         int := 0;
  v_url       text;
BEGIN
  -- Vault: Jina API key
  IF v_jina_key IS NULL THEN
    BEGIN
      SELECT decrypted_secret INTO v_jina_key
      FROM vault.decrypted_secrets WHERE name='jina_api_key' LIMIT 1;
      IF v_jina_key LIKE '__PLACEHOLDER%' THEN v_jina_key := NULL; END IF;
    EXCEPTION WHEN OTHERS THEN v_jina_key := NULL;
    END;
  END IF;

  -- Headers Jina (Return-Format: html para parsear produto listings)
  v_headers := jsonb_build_object('Accept', 'text/html');
  IF v_jina_key IS NOT NULL THEN
    v_headers := v_headers || jsonb_build_object('Authorization', 'Bearer ' || v_jina_key);
  END IF;

  -- Watchdog: liberta 'processing' travado > 60 min
  UPDATE sm_category_pages
    SET status = 'pending', fetch_req_id = NULL
  WHERE status = 'processing'
    AND updated_at < now() - interval '60 minutes';

  -- Categorias com category_id descoberto → podem ser scrapeadas
  -- Categorias sem category_id → tentar via Jina Search
  FOR rec IN
    SELECT id, name, slug, category_id, site_url, current_page
    FROM sm_category_pages
    WHERE status IN ('pending','partial')
      AND (status <> 'failed' OR attempts < 3)
    ORDER BY CASE WHEN category_id IS NOT NULL THEN 0 ELSE 1 END,  -- com URL primeiro
             attempts, created_at
    LIMIT p_limit
  LOOP
    IF rec.site_url IS NOT NULL THEN
      -- Categoria com URL conhecida: scrape direto
      v_url := rec.site_url;
      IF rec.current_page > 1 THEN
        v_url := v_url || '?page=' || rec.current_page;
      END IF;
      v_url := 'https://r.jina.ai/' || v_url;
    ELSE
      -- Categoria sem URL: Jina Search para encontrar a URL
      v_url := 'https://s.jina.ai/site%3Asomarcas.com.br%2Fcategorias%20'
               || replace(rec.slug, '-', '+');
    END IF;

    SELECT net.http_get(
      url                  := v_url,
      headers              := v_headers,
      timeout_milliseconds := 45000
    ) INTO v_req;

    UPDATE sm_category_pages
      SET status       = 'processing',
          fetch_req_id = v_req,
          attempts     = attempts + 1
    WHERE id = rec.id;

    v_n := v_n + 1;
  END LOOP;

  RETURN v_n;
END;
$$;

GRANT EXECUTE ON FUNCTION public.fn_sm_category_enqueue(integer, text) TO service_role;


-- ── 4. fn_sm_category_collect: processa respostas e extrai produtos ──────
CREATE OR REPLACE FUNCTION public.fn_sm_category_collect(p_max integer DEFAULT 10)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, net
AS $$
DECLARE
  rec          record;
  v_body       text;
  v_sc         int;
  v_m          text[];
  v_category_id int;
  v_urls       jsonb := '[]'::jsonb;
  v_url_item   jsonb;
  v_ok         int  := 0;
  v_fail       int  := 0;
  v_wait       int  := 0;
  v_total_urls int  := 0;
  v_matched    int  := 0;
  v_result     jsonb;
BEGIN
  FOR rec IN
    SELECT id, name, slug, category_id, fetch_req_id, site_url
    FROM sm_category_pages
    WHERE status = 'processing'
      AND fetch_req_id IS NOT NULL
    LIMIT p_max
  LOOP
    SELECT status_code, content INTO v_sc, v_body
    FROM net._http_response WHERE id = rec.fetch_req_id;

    IF NOT FOUND THEN
      v_wait := v_wait + 1;
      CONTINUE;
    END IF;

    IF v_sc <> 200 OR length(COALESCE(v_body,'')) < 200 THEN
      UPDATE sm_category_pages
        SET status='failed', last_error='HTTP '||COALESCE(v_sc::text,'?'),
            fetch_req_id=NULL
      WHERE id = rec.id;
      v_fail := v_fail + 1;
    ELSE
      -- 1. Se não tem category_id, tenta descobrir pela URL no markdown
      IF rec.category_id IS NULL THEN
        v_m := regexp_match(v_body,
          'somarcas\.com\.br/([0-9]+)/categorias/(' || rec.slug || ')');
        IF v_m IS NOT NULL THEN
          UPDATE sm_category_pages
            SET category_id = v_m[1]::int
          WHERE id = rec.id;
          -- Re-enqueue para scrape completo da categoria (agora com URL)
          UPDATE sm_category_pages
            SET status='pending', fetch_req_id=NULL
          WHERE id = rec.id;
          v_ok := v_ok + 1;
          DELETE FROM net._http_response WHERE id = rec.fetch_req_id;
          CONTINUE;
        END IF;
      END IF;

      -- 2. Extrai todos os (site_id, slug) de produtos na página
      v_urls := '[]'::jsonb;
      FOR v_m IN
        SELECT regexp_matches(v_body,
          'somarcas\.com\.br/([0-9]+)/produto/([a-z0-9][a-z0-9-]+)', 'g')
      LOOP
        v_urls := v_urls || jsonb_build_object(
          'site_id', v_m[1]::int,
          'slug',    v_m[2]
        );
      END LOOP;

      -- Desduplicar por site_id
      SELECT jsonb_agg(DISTINCT item) INTO v_urls
      FROM jsonb_array_elements(v_urls) item;

      v_total_urls := v_total_urls + COALESCE(jsonb_array_length(v_urls), 0);

      -- 3. Slug-match → sm_site_url_map
      IF jsonb_array_length(v_urls) > 0 THEN
        v_result := public.fn_sm_url_map_from_site_urls(v_urls);
        v_matched := v_matched + COALESCE((v_result->>'resolved')::int, 0);
      END IF;

      -- 4. Verificar paginação (simplificado — se encontrou produtos, marcar done)
      UPDATE sm_category_pages
        SET status          = 'done',
            products_found  = COALESCE(jsonb_array_length(v_urls), 0),
            last_scraped_at = now(),
            fetch_req_id    = NULL
      WHERE id = rec.id;

      v_ok := v_ok + 1;
    END IF;

    DELETE FROM net._http_response WHERE id = rec.fetch_req_id;
  END LOOP;

  RETURN jsonb_build_object(
    'ok',         v_ok,
    'fail',       v_fail,
    'wait',       v_wait,
    'urls_found', v_total_urls,
    'matched',    v_matched,
    'ts',         now()
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.fn_sm_category_collect(integer) TO service_role;

COMMENT ON FUNCTION public.fn_sm_category_enqueue IS
    'Enfileira Jina Reader para páginas de categoria SM. '
    'Categorias com URL conhecida: scrape direto. Sem URL: Jina Search.';
COMMENT ON FUNCTION public.fn_sm_category_collect IS
    'Coleta respostas de categorias, extrai (site_id, slug) dos produtos '
    'e chama fn_sm_url_map_from_site_urls para atualizar o mapa.';
;

