-- >>> BEGIN 20260607125626_fix_sm_url_map_from_site_urls_dedup.sql >>>

-- ============================================================
--  BUG FIX 8: fn_sm_url_map_from_site_urls
--  Problema: ON CONFLICT tenta atualizar o mesmo (supplier_id, codigo)
--  duas vezes quando o mesmo slug existe em múltiplos site_ids
--  (ex.: "kit-boas-vindas-5-pcs" → site_id 2943 e 2945)
--  Fix: DISTINCT ON (codigo) com ORDER para escolher o site_id
--       mais recente/maior (mais provável de ser o canonical)
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_sm_url_map_from_site_urls(p_urls jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_sup       uuid := '841cd690-210a-422a-908c-7676828db272';
  v_resolved  int  := 0;
  v_unmatched int  := 0;
  v_total     int  := 0;
BEGIN
  CREATE TEMP TABLE _inc ON COMMIT DROP AS
  SELECT DISTINCT ON (slug)
    (u->>'site_id')::int AS site_id,
    u->>'slug'           AS slug
  FROM jsonb_array_elements(p_urls) u
  WHERE (u->>'site_id')::int > 0
    AND u->>'slug' IS NOT NULL
  ORDER BY slug, (u->>'site_id')::int DESC;  -- maior site_id vence (mais recente)

  v_total := (SELECT count(*) FROM _inc);

  -- DISTINCT ON (codigo) garante que cada produto-Bronze aparece 1x no INSERT
  -- mesmo que seu slug-títyulo case com múltiplos slugs da _inc
  INSERT INTO public.sm_site_url_map
    (supplier_id, codigo, site_id, slug, source, confidence, last_verified_at)
  SELECT DISTINCT ON (spr.raw_data->>'codigo')
    v_sup,
    spr.raw_data->>'codigo',
    i.site_id,
    i.slug,
    'category_scrape',
    CASE WHEN count(spr.id) OVER (PARTITION BY i.slug) > 1
         THEN 'medium'
         ELSE 'high' END,
    now()
  FROM _inc i
  JOIN supplier_products_raw spr
    ON spr.supplier_id = v_sup
    AND public.fn_slugify(spr.raw_data->>'titulo') = i.slug
  ORDER BY spr.raw_data->>'codigo', i.site_id DESC   -- DISTINCT ON requer ORDER BY
  ON CONFLICT (supplier_id, codigo) DO UPDATE
    SET site_id          = EXCLUDED.site_id,
        slug             = EXCLUDED.slug,
        source           = EXCLUDED.source,
        confidence       = EXCLUDED.confidence,
        last_verified_at = EXCLUDED.last_verified_at
    WHERE sm_site_url_map.site_id IS DISTINCT FROM EXCLUDED.site_id
       OR sm_site_url_map.site_id IS NULL;

  GET DIAGNOSTICS v_resolved = ROW_COUNT;

  SELECT count(*) INTO v_unmatched
  FROM _inc i
  WHERE NOT EXISTS (
    SELECT 1 FROM supplier_products_raw spr
    WHERE spr.supplier_id = v_sup
      AND public.fn_slugify(spr.raw_data->>'titulo') = i.slug
  );

  RETURN jsonb_build_object(
    'input_total',  v_total,
    'resolved',     v_resolved,
    'unmatched',    v_unmatched,
    'coverage_pct', (SELECT round(100.0 *
      (SELECT count(*) FROM sm_site_url_map WHERE supplier_id=v_sup AND site_id IS NOT NULL) /
      NULLIF((SELECT count(*) FROM supplier_products_raw WHERE supplier_id=v_sup), 0), 1))
  );
END;
$$;

REVOKE ALL ON FUNCTION public.fn_sm_url_map_from_site_urls(jsonb)
    FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_sm_url_map_from_site_urls(jsonb)
    TO service_role;

COMMENT ON FUNCTION public.fn_sm_url_map_from_site_urls IS
    'v2 — BUG FIX 8: DISTINCT ON (slug) na _inc e DISTINCT ON (codigo) no INSERT '
    'para evitar ON CONFLICT duplicado quando mesmo slug tem múltiplos site_ids. '
    'SECURITY DEFINER.';
;

-- <<< END 20260607125626_fix_sm_url_map_from_site_urls_dedup.sql <<<

-- >>> BEGIN 20260607131647_fn_ingest_asia_api_batch_v1.sql >>>

CREATE OR REPLACE FUNCTION public.fn_ingest_asia_api_batch(
  p_produtos jsonb  -- array de produtos-pai da API oficial api.asiaimport.com.br
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_supplier_id  uuid    := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_batch_id     uuid    := gen_random_uuid();
  v_inseridos    int     := 0;
  v_atualizados  int     := 0;
  v_sem_mudanca  int     := 0;
  v_erros        int     := 0;
  v_produto      jsonb;
  v_referencia   text;
  v_hash         text;
  v_hash_atual   text;
BEGIN
  -- Cria batch de importação
  INSERT INTO supplier_import_batches (id, supplier_id, status, started_at, notes)
  VALUES (v_batch_id, v_supplier_id, 'running', now(), 'API oficial api.asiaimport.com.br — listarProdutos2');

  -- Itera sobre cada produto-pai
  FOR v_produto IN SELECT * FROM jsonb_array_elements(p_produtos)
  LOOP
    BEGIN
      v_referencia := v_produto->>'referencia';

      -- Valida referência
      IF v_referencia IS NULL OR v_referencia = '' THEN
        v_erros := v_erros + 1;
        CONTINUE;
      END IF;

      -- Calcula hash do conteúdo para detectar mudanças
      v_hash := md5(v_produto::text);

      -- Verifica se existe e se mudou
      SELECT content_hash INTO v_hash_atual
      FROM supplier_products_raw
      WHERE supplier_id = v_supplier_id
        AND supplier_sku = v_referencia;

      IF NOT FOUND THEN
        -- Novo produto
        INSERT INTO supplier_products_raw (
          supplier_id,
          supplier_sku,
          supplier_reference,
          raw_data,
          content_hash,
          status,
          source_channel,
          import_batch_id,
          imported_at,
          updated_at
        ) VALUES (
          v_supplier_id,
          v_referencia,
          v_referencia,
          v_produto,
          v_hash,
          'pending',
          'api_oficial',
          v_batch_id,
          now(),
          now()
        );
        v_inseridos := v_inseridos + 1;

      ELSIF v_hash_atual IS DISTINCT FROM v_hash THEN
        -- Produto mudou — atualiza e re-dispara pipeline
        UPDATE supplier_products_raw SET
          raw_data        = v_produto,
          content_hash    = v_hash,
          status          = 'pending',
          source_channel  = 'api_oficial',
          import_batch_id = v_batch_id,
          updated_at      = now()
        WHERE supplier_id = v_supplier_id
          AND supplier_sku = v_referencia;
        v_atualizados := v_atualizados + 1;

      ELSE
        -- Produto idêntico — sem alteração
        v_sem_mudanca := v_sem_mudanca + 1;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      -- Continua processando os demais
    END;
  END LOOP;

  -- Finaliza batch
  UPDATE supplier_import_batches SET
    status          = CASE WHEN v_erros = 0 THEN 'ok' ELSE 'ok_com_erros' END,
    finished_at     = now(),
    products_imported = v_inseridos,
    products_updated  = v_atualizados,
    notes           = notes || format(' | inseridos=%s atualizados=%s sem_mudanca=%s erros=%s',
                        v_inseridos, v_atualizados, v_sem_mudanca, v_erros)
  WHERE id = v_batch_id;

  RETURN jsonb_build_object(
    'batch_id',     v_batch_id,
    'inseridos',    v_inseridos,
    'atualizados',  v_atualizados,
    'sem_mudanca',  v_sem_mudanca,
    'erros',        v_erros,
    'total',        v_inseridos + v_atualizados + v_sem_mudanca + v_erros
  );
END;
$$;

-- Permissões: só service_role (chamada pelo n8n via Supabase API key)
REVOKE ALL ON FUNCTION public.fn_ingest_asia_api_batch(jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_ingest_asia_api_batch(jsonb) TO service_role;

COMMENT ON FUNCTION public.fn_ingest_asia_api_batch(jsonb) IS
  'UPSERT de produtos-pai da API oficial Asia Import (api.asiaimport.com.br / listarProdutos2).
   Grain: 1 linha por produto-pai (supplier_sku = referencia pai, ex: MC511P).
   Hash guard: só atualiza Bronze e re-dispara status=pending se conteúdo mudou.';
;

-- <<< END 20260607131647_fn_ingest_asia_api_batch_v1.sql <<<

