-- >>> BEGIN 20260610102331_add_url_sanitization_trigger_product_images.sql >>>
-- ═══════════════════════════════════════════════════════════
-- fn_sanitize_url: normaliza URLs malformadas antes de gravar
-- Corrige: https:/ → https://, http:/ → http://
--          trim de espaços, remoção de \r\n embutidos
-- ═══════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_sanitize_url(p_url TEXT)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
SET search_path TO 'public'
AS $$
DECLARE
  v_url TEXT := p_url;
BEGIN
  IF v_url IS NULL THEN RETURN NULL; END IF;

  -- Trim espaços externos
  v_url := TRIM(v_url);

  -- Remover caracteres de controle embutidos (CR, LF, TAB)
  v_url := REPLACE(v_url, CHR(13), '');
  v_url := REPLACE(v_url, CHR(10), '');
  v_url := REPLACE(v_url, CHR(9),  '');

  -- Corrigir https:/ (1 slash) → https://
  -- Usando REGEXP_REPLACE para precisão: ^https:/(?!/)
  v_url := REGEXP_REPLACE(v_url, '^https:/([^/])', 'https://\1');

  -- Corrigir http:/ (1 slash) → http://
  v_url := REGEXP_REPLACE(v_url, '^http:/([^/])', 'http://\1');

  -- Se ficou vazio após trim, retornar NULL
  IF v_url = '' THEN RETURN NULL; END IF;

  RETURN v_url;
END;
$$;

-- ═══════════════════════════════════════════════════════════
-- Trigger BEFORE INSERT/UPDATE em product_images
-- Sanitiza url_original e url_cdn antes de gravar
-- ═══════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_sanitize_product_image_urls()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- Sanitizar url_original (CDN do fornecedor)
  NEW.url_original := fn_sanitize_url(NEW.url_original);

  -- Sanitizar url_cdn (CF Images) — só aplicar trim e controles
  IF NEW.url_cdn IS NOT NULL THEN
    NEW.url_cdn := TRIM(NEW.url_cdn);
    NEW.url_cdn := REPLACE(NEW.url_cdn, CHR(13), '');
    NEW.url_cdn := REPLACE(NEW.url_cdn, CHR(10), '');
  END IF;

  RETURN NEW;
END;
$$;

-- Criar trigger BEFORE INSERT OR UPDATE (fires before row is written)
DROP TRIGGER IF EXISTS trg_sanitize_image_urls ON product_images;
CREATE TRIGGER trg_sanitize_image_urls
  BEFORE INSERT OR UPDATE OF url_original, url_cdn
  ON product_images
  FOR EACH ROW
  EXECUTE FUNCTION fn_sanitize_product_image_urls();

-- Comentário explicativo
COMMENT ON FUNCTION public.fn_sanitize_url(TEXT) IS
  'Normaliza URLs: corrige https:/(1slash), http:/(1slash), remove CR/LF/TAB embutidos, trim.';
COMMENT ON FUNCTION public.fn_sanitize_product_image_urls() IS
  'Trigger BEFORE INSERT/UPDATE: sanitiza url_original e url_cdn em product_images.';
COMMENT ON TRIGGER trg_sanitize_image_urls ON product_images IS
  'Previne gravação de URLs malformadas. Corrige https:/ → https://, trim, remove ctrl chars.';;

-- <<< END 20260610102331_add_url_sanitization_trigger_product_images.sql <<<

-- >>> BEGIN 20260610102919_add_cost_price_non_zero_constraint_and_xbz_guard.sql >>>
-- ═══════════════════════════════════════════════════════
-- 1. CHECK CONSTRAINT: cost_price nunca pode ser = 0
-- NULL é OK (preço desconhecido); > 0 é o valor real
-- ═══════════════════════════════════════════════════════
ALTER TABLE public.products
  ADD CONSTRAINT chk_cost_price_not_zero
  CHECK (cost_price IS NULL OR cost_price > 0);

-- ═══════════════════════════════════════════════════════
-- 2. Mesmo constraint em variant_supplier_sources
-- ═══════════════════════════════════════════════════════
ALTER TABLE public.variant_supplier_sources
  ADD CONSTRAINT chk_vss_cost_price_not_zero
  CHECK (cost_price IS NULL OR cost_price > 0);

-- ═══════════════════════════════════════════════════════
-- 3. Função auxiliar: parse de PrecoVendaFormatado XBZ
-- converte "2,46" → 2.46 com fallback seguro
-- ═══════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_xbz_parse_price(
  p_preco_venda      TEXT,
  p_preco_formatado  TEXT
) RETURNS NUMERIC
LANGUAGE plpgsql
IMMUTABLE
SET search_path TO 'public'
AS $$
DECLARE
  v_raw  NUMERIC := 0;
  v_fmt  NUMERIC := 0;
BEGIN
  -- Tentar PrecoVenda primeiro (já é numeric-string)
  BEGIN
    v_raw := p_preco_venda::NUMERIC;
  EXCEPTION WHEN OTHERS THEN
    v_raw := 0;
  END;

  -- Se PrecoVenda = 0, tentar PrecoVendaFormatado (pt-BR: vírgula decimal)
  IF v_raw = 0 AND p_preco_formatado IS NOT NULL THEN
    BEGIN
      v_fmt := REPLACE(p_preco_formatado, ',', '.')::NUMERIC;
    EXCEPTION WHEN OTHERS THEN
      v_fmt := 0;
    END;
    IF v_fmt > 0.05 THEN   -- ignora valores absurdamente baixos (R$0.01 = catálogo grátis)
      RETURN v_fmt;
    END IF;
  END IF;

  -- Se PrecoVenda > 0, usar diretamente
  IF v_raw > 0 THEN RETURN v_raw; END IF;

  -- Ambos zero ou inválidos → NULL (não temos preço)
  RETURN NULL;
END;
$$;

COMMENT ON FUNCTION public.fn_xbz_parse_price(TEXT, TEXT) IS
  'Parse preço XBZ: usa PrecoVenda se > 0; fallback para PrecoVendaFormatado (vírgula→ponto).
   Retorna NULL quando ambos são 0 ou inválidos. Previne cost_price=0 no Gold.';
COMMENT ON CONSTRAINT chk_cost_price_not_zero ON public.products IS
  'cost_price NUNCA pode ser 0: NULL=desconhecido, >0=valor real.';
COMMENT ON CONSTRAINT chk_vss_cost_price_not_zero ON public.variant_supplier_sources IS
  'cost_price nunca 0 em variant_supplier_sources. Usar NULL para preço desconhecido.';;

-- <<< END 20260610102919_add_cost_price_non_zero_constraint_and_xbz_guard.sql <<<

-- >>> BEGIN 20260610102947_fix_xbz_parse_price_null_handling.sql >>>
-- Fix: tratar PrecoVenda=NULL como 0 (usar Formatado como fallback)
CREATE OR REPLACE FUNCTION public.fn_xbz_parse_price(
  p_preco_venda      TEXT,
  p_preco_formatado  TEXT
) RETURNS NUMERIC
LANGUAGE plpgsql
IMMUTABLE
SET search_path TO 'public'
AS $$
DECLARE
  v_raw  NUMERIC := 0;
  v_fmt  NUMERIC := 0;
BEGIN
  -- Tentar PrecoVenda primeiro (já é numeric-string)
  -- NULL ou vazio → 0 (vai usar Formatado como fallback)
  IF p_preco_venda IS NOT NULL AND p_preco_venda != '' THEN
    BEGIN
      v_raw := p_preco_venda::NUMERIC;
    EXCEPTION WHEN OTHERS THEN
      v_raw := 0;
    END;
  END IF;

  -- Se PrecoVenda = 0 OU NULL, tentar PrecoVendaFormatado (pt-BR: vírgula decimal)
  IF COALESCE(v_raw, 0) = 0 AND p_preco_formatado IS NOT NULL THEN
    BEGIN
      v_fmt := REPLACE(p_preco_formatado, ',', '.')::NUMERIC;
    EXCEPTION WHEN OTHERS THEN
      v_fmt := 0;
    END;
    IF COALESCE(v_fmt, 0) > 0.05 THEN  -- ignora valores absurdamente baixos (R$0.01)
      RETURN v_fmt;
    END IF;
  END IF;

  -- Se PrecoVenda > 0, usar diretamente
  IF COALESCE(v_raw, 0) > 0 THEN RETURN v_raw; END IF;

  -- Ambos zero ou inválidos → NULL (não temos preço)
  RETURN NULL;
END;
$$;;

-- <<< END 20260610102947_fix_xbz_parse_price_null_handling.sql <<<

-- >>> BEGIN 20260610103932_create_asia_legacy_image_upload_pipeline_v2.sql >>>
-- Criar tabela e pipeline (versão corrigida com cf_custom_id único)

CREATE TABLE IF NOT EXISTS public.asia_legacy_upload_queue (
  id                UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  product_id        UUID NOT NULL REFERENCES products(id),
  source_url        TEXT NOT NULL,
  cf_custom_id      TEXT NOT NULL,
  supplier_code     TEXT NOT NULL DEFAULT 'asia',
  supplier_ref      TEXT,
  status            TEXT NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending','uploading','done','error','skip_404')),
  request_id        BIGINT,
  cf_image_id       TEXT,
  error_msg         TEXT,
  attempt_count     INT NOT NULL DEFAULT 0,
  created_at        TIMESTAMPTZ DEFAULT NOW(),
  updated_at        TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (product_id),
  UNIQUE (cf_custom_id)
);

CREATE INDEX IF NOT EXISTS idx_alq_status ON asia_legacy_upload_queue(status);
CREATE INDEX IF NOT EXISTS idx_alq_product ON asia_legacy_upload_queue(product_id);

-- Enfileirar — cf_custom_id = {supplier}-{product_id_8chars}-legacy-01 (garantidamente único)
INSERT INTO asia_legacy_upload_queue (product_id, source_url, cf_custom_id, supplier_code, supplier_ref)
SELECT
  p.id,
  p.primary_image_url,
  CONCAT(
    CASE WHEN p.primary_image_url ILIKE '%asiaimport%' THEN 'asia' ELSE 'xbz' END,
    '-',
    REPLACE(LEFT(p.id::text, 8), '-', ''),  -- primeiros 8 chars do UUID (único)
    '-legacy'
  ) AS cf_custom_id,
  CASE WHEN p.primary_image_url ILIKE '%asiaimport%' THEN 'asia' ELSE 'xbz' END,
  p.supplier_reference
FROM products p
WHERE p.is_active = true
  AND p.primary_image_url IS NOT NULL
  AND p.primary_image_url NOT LIKE 'https://imagedelivery.net%'
ON CONFLICT (product_id) DO NOTHING;

-- Verificar contagem
SELECT COUNT(*), COUNT(*) FILTER (WHERE status='pending') AS pending
FROM asia_legacy_upload_queue;;

-- <<< END 20260610103932_create_asia_legacy_image_upload_pipeline_v2.sql <<<

-- >>> BEGIN 20260610104018_create_asia_legacy_dispatch_harvest_functions.sql >>>
-- ═══════════════════════════════════════════════════════════════
-- Funções de dispatch e harvest para imagens ASIA/XBZ legadas
-- ═══════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_asia_legacy_dispatch_batch(p_limit INT DEFAULT 20)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'net'
AS $$
DECLARE
  v_count   INT := 0;
  v_item    RECORD;
  v_req_id  BIGINT;
  v_mcp_id  INT := 0;
BEGIN
  FOR v_item IN
    SELECT id, product_id, source_url, cf_custom_id, supplier_code
    FROM asia_legacy_upload_queue
    WHERE status = 'pending' AND attempt_count < 3
    ORDER BY created_at
    LIMIT p_limit
  LOOP
    v_mcp_id := v_mcp_id + 1;

    SELECT net.http_post(
      url := 'https://cloudflare-deploy-mcp.adm01.workers.dev/mcp',
      body := jsonb_build_object(
        'jsonrpc', '2.0',
        'id', v_mcp_id,
        'method', 'tools/call',
        'params', jsonb_build_object(
          'name', 'cf_images_upload_url',
          'arguments', jsonb_build_object(
            'source_url', v_item.source_url,
            'custom_id',  v_item.cf_custom_id,
            'metadata',   jsonb_build_object(
              'supplier',   v_item.supplier_code,
              'product_id', v_item.product_id::text,
              'pipeline',   'asia_legacy'
            )
          )
        )
      ),
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Accept', 'application/json, text/event-stream'
      ),
      timeout_milliseconds := 30000
    ) INTO v_req_id;

    UPDATE asia_legacy_upload_queue
    SET status = 'uploading',
        request_id = v_req_id,
        attempt_count = attempt_count + 1,
        updated_at = NOW()
    WHERE id = v_item.id;

    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('dispatched', v_count);
END;
$$;

-- ─────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fn_asia_legacy_harvest_batch()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'net'
AS $$
DECLARE
  v_done     INT := 0;
  v_fail     INT := 0;
  v_item     RECORD;
  v_resp     RECORD;
  v_body     TEXT;
  v_cf_id    TEXT;
  v_cf_url   TEXT;
  v_org      CONSTANT UUID := '5db5aee1-064b-4ef4-9193-345dcd8274ea';
  v_cdnbase  CONSTANT TEXT := 'https://imagedelivery.net/vKMs9Ow8bA_enuhLXZ2HAw';
BEGIN
  FOR v_item IN
    SELECT q.id, q.product_id, q.request_id, q.cf_custom_id,
           q.source_url, q.supplier_code
    FROM asia_legacy_upload_queue q
    WHERE q.status = 'uploading' AND q.request_id IS NOT NULL
  LOOP
    SELECT * INTO v_resp FROM net._http_response
    WHERE id = v_item.request_id LIMIT 1;

    IF NOT FOUND THEN CONTINUE; END IF;

    v_body := COALESCE(v_resp.content, '');

    -- Verificar se houve erro HTTP
    IF v_resp.status_code NOT IN (200, 201) THEN
      UPDATE asia_legacy_upload_queue
      SET status = 'error',
          error_msg = LEFT('HTTP ' || v_resp.status_code::text || ': ' || v_body, 300),
          updated_at = NOW()
      WHERE id = v_item.id;
      v_fail := v_fail + 1;
      CONTINUE;
    END IF;

    -- Extração do cf_image_id da resposta SSE/JSON
    -- O MCP Worker retorna SSE com "data: {...}" contendo o resultado
    BEGIN
      -- Tentar parsear como JSON direto
      v_cf_id := (v_body::jsonb->'result'->'content'->0->'text')::text;
      IF v_cf_id IS NOT NULL THEN
        -- É texto com o JSON da resposta CF dentro
        v_cf_id := ((v_cf_id::text)::jsonb->>'id');
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_cf_id := NULL;
    END;

    -- Fallback: regex para extrair "id":"..."
    IF v_cf_id IS NULL OR TRIM(REPLACE(v_cf_id, '"', '')) = '' THEN
      v_cf_id := (REGEXP_MATCH(v_body, '"id"\s*:\s*"([a-z0-9A-Z\-_]+)"'))[1];
    END IF;

    -- Se a resposta menciona "already exists", usar o custom_id
    IF v_cf_id IS NULL AND v_body ILIKE '%already exists%' THEN
      v_cf_id := v_item.cf_custom_id;
    END IF;

    IF v_cf_id IS NULL OR TRIM(v_cf_id) = '' THEN
      -- Fallback final: usar o cf_custom_id
      -- (CF aceita o custom_id como ID se o upload foi aceito)
      IF v_body ILIKE '%"success":true%' OR v_body ILIKE '%asia-%' THEN
        v_cf_id := v_item.cf_custom_id;
      ELSE
        UPDATE asia_legacy_upload_queue
        SET status = 'error',
            error_msg = LEFT('no_cf_id: ' || v_body, 300),
            updated_at = NOW()
        WHERE id = v_item.id;
        v_fail := v_fail + 1;
        CONTINUE;
      END IF;
    END IF;

    v_cf_id := TRIM(REPLACE(v_cf_id, '"', ''));
    v_cf_url := v_cdnbase || '/' || v_cf_id || '/public';

    -- Inserir product_images (trigger fn_sync_product_images_to_products
    -- atualiza products.primary_image_url automaticamente)
    BEGIN
      INSERT INTO product_images (
        product_id, cloudflare_image_id, url_cdn, url_original,
        image_type, is_primary, is_active, display_order,
        source_supplier, organization_id,
        filename, alt_text
      ) VALUES (
        v_item.product_id,
        v_cf_id,
        v_cf_url,
        v_item.source_url,
        'main', true, true, 1,
        v_item.supplier_code,
        v_org,
        SPLIT_PART(v_item.source_url, '/', -1),
        SPLIT_PART(v_item.source_url, '/', -1)
      )
      ON CONFLICT (cloudflare_image_id) DO NOTHING;

      UPDATE asia_legacy_upload_queue
      SET status = 'done',
          cf_image_id = v_cf_id,
          updated_at = NOW()
      WHERE id = v_item.id;

      v_done := v_done + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE asia_legacy_upload_queue
      SET status = 'error',
          error_msg = LEFT(SQLERRM, 300),
          updated_at = NOW()
      WHERE id = v_item.id;
      v_fail := v_fail + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('harvested_ok', v_done, 'harvested_fail', v_fail);
END;
$$;

-- ─────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fn_asia_legacy_run_cycle(p_limit INT DEFAULT 20)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'net'
AS $$
DECLARE
  v_lock     BOOLEAN;
  v_dispatch JSONB;
  v_harvest  JSONB;
  v_pending  INT; v_uploading INT; v_done INT; v_error INT;
BEGIN
  v_lock := pg_try_advisory_xact_lock(hashtext('fn_asia_legacy_run_cycle')::BIGINT);
  IF NOT v_lock THEN RETURN jsonb_build_object('status', 'skipped_lock'); END IF;

  v_harvest  := fn_asia_legacy_harvest_batch();
  v_dispatch := fn_asia_legacy_dispatch_batch(p_limit);

  SELECT COUNT(*) FILTER (WHERE status='pending')   INTO v_pending   FROM asia_legacy_upload_queue;
  SELECT COUNT(*) FILTER (WHERE status='uploading') INTO v_uploading FROM asia_legacy_upload_queue;
  SELECT COUNT(*) FILTER (WHERE status='done')      INTO v_done      FROM asia_legacy_upload_queue;
  SELECT COUNT(*) FILTER (WHERE status='error')     INTO v_error     FROM asia_legacy_upload_queue;

  RETURN jsonb_build_object(
    'status', 'ok',
    'dispatch', v_dispatch, 'harvest', v_harvest,
    'pending', v_pending, 'uploading', v_uploading,
    'done', v_done, 'error', v_error
  );
END;
$$;

COMMENT ON TABLE public.asia_legacy_upload_queue IS 'Upload CF Images para 382 produtos ASIA/XBZ com primary_image_url não-CF. Criado em 2026-06-10.';
COMMENT ON FUNCTION public.fn_asia_legacy_run_cycle IS 'Dispatch+harvest upload CF Images para produtos ASIA/XBZ legados. 20 itens/ciclo.';;

