-- ════════════════════════════════════════════════════════════════
-- SILVER DE-PARA — Fase 4/6: derivação do PAI via de-para
-- fn_derive_parent_ref deixa de ter regras hardcoded por UUID e passa a LER a
-- regra do de-para (supplier_field_mappings, target_table='product_variants',
-- target_field='parent_reference'), semeada na Fase 3:
--   • source_field  = chave autoritativa do pai no raw (ProdReference,
--                     CodigoAmigavel) ou o sentinela '_none' quando o
--                     fornecedor não tem (a coluna é NOT NULL);
--   • transform_config.fallback = estratégia quando a chave está ausente/vazia:
--       'identity'                 → o próprio variant_ref é o pai (Spot, Só Marcas)
--       'strip_hyphen_suffix'      → corta após o ÚLTIMO hífen; sem hífen = pai (XBZ, default)
--       'asia_hyphen_or_suffix_P'  → com hífen corta; sem hífen acrescenta 'P' (Asia)
--
-- Comportamento IDÊNTICO ao da versão hardcoded (20260605161000) por construção.
-- Passa de IMMUTABLE → STABLE (lê tabela). Sem uso em índice/coluna gerada
-- (verificado). Mantém search_path e o guard de variant_ref nulo/vazio.
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_derive_parent_ref(
  p_supplier_id uuid, p_variant_ref text, p_raw jsonb
)
RETURNS text LANGUAGE plpgsql STABLE
SET search_path TO 'public'
AS $function$
DECLARE
  v_src      text;
  v_cfg      jsonb;
  v_fallback text;
  v_explicit text;
BEGIN
  IF p_variant_ref IS NULL OR TRIM(p_variant_ref) = '' THEN
    RETURN NULL;
  END IF;

  SELECT source_field, transform_config
    INTO v_src, v_cfg
  FROM public.supplier_field_mappings
  WHERE supplier_id = p_supplier_id
    AND target_table = 'product_variants'
    AND target_field = 'parent_reference'
    AND is_active = TRUE
  ORDER BY priority
  LIMIT 1;

  v_fallback := COALESCE(v_cfg->>'fallback', 'strip_hyphen_suffix');

  -- 1) chave autoritativa do pai no raw, se configurada e preenchida
  -- ('_none' = sentinela "sem chave"; campos sintéticos '_*' não vêm do raw)
  IF v_src IS NOT NULL AND v_src NOT LIKE '\_%' THEN
    v_explicit := NULLIF(TRIM(p_raw->>v_src), '');
    IF v_explicit IS NOT NULL THEN
      RETURN v_explicit;
    END IF;
  END IF;

  -- 2) fallback por estratégia
  IF v_fallback = 'identity' THEN
    RETURN p_variant_ref;

  ELSIF v_fallback = 'asia_hyphen_or_suffix_P' THEN
    IF position('-' IN p_variant_ref) > 0 THEN
      RETURN regexp_replace(p_variant_ref, '-[^-]*$', '');
    ELSE
      RETURN p_variant_ref || 'P';
    END IF;

  ELSE  -- 'strip_hyphen_suffix' (default)
    IF position('-' IN p_variant_ref) > 0 THEN
      RETURN regexp_replace(p_variant_ref, '-[^-]*$', '');
    END IF;
    RETURN p_variant_ref;
  END IF;
END;
$function$;

COMMENT ON FUNCTION public.fn_derive_parent_ref(uuid, text, jsonb) IS
  'Deriva a referência do produto-pai a partir do de-para (parent_reference): chave autoritativa no raw + estratégia de fallback. Config-driven; substitui as regras hardcoded por fornecedor.';

-- <<< END 20260610120300_silver_depara_04_derive_parent_config_driven.sql <<<

-- >>> BEGIN 20260610120400_silver_depara_05_standardize_variant_depara.sql >>>
-- ════════════════════════════════════════════════════════════════
-- SILVER DE-PARA — Fase 5/6: fn_standardize_variant 100% data-driven
-- Remove os blocos IF/ELSIF por UUID de fornecedor. Toda a extração de campos
-- de variante passa a vir do de-para (supplier_field_mappings,
-- target_table='product_variants', semeado na Fase 3) aplicado pelo motor
-- fn_apply_transform — exatamente como fn_standardize_raw já faz para o pai.
--
-- Equivalência de cor (fn_match_supplier_color → fn_match_canonical_color),
-- derivação do pai (fn_derive_parent_ref, agora config-driven), coerções seguras
-- (fn_safe_int/num) e o UPSERT permanecem IDÊNTICOS. Comportamento preservado
-- por construção; a única mudança benigna é que strings vazias viram NULL
-- (o loop ignora valores em branco), em vez de '' como antes.
--
-- Campos sintéticos do documento (não vêm do raw):
--   _ref     = supplier_reference  (fonte de sku/supplier_sku)
--   _sm_hex  = hex resolvido na rede produtos_similares (Só Marcas)
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_standardize_variant(p_raw_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r public.supplier_products_raw%ROWTYPE;
  v_doc jsonb;
  m RECORD;
  v_val text; v_tx text;
  v_assigns jsonb := '{}'::jsonb;
  v_parent text;
  v_code text; v_apiid text; v_cname text; v_chex text;
  v_supplier_sku text; v_sku text; v_stock integer; v_cost numeric;
  v_col RECORD; v_fname text; v_fcode text; v_fhex text; v_canonical_id uuid;
  v_var_id uuid;
  v_cols text[] := ARRAY[
    'sku','supplier_sku','color_code','color_api_id','color_name','color_hex',
    'stock_quantity','cost_price'];
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'raw_nao_encontrado'); END IF;

  -- Documento de trabalho: raw + campos sintéticos supplier-agnostic.
  v_doc := COALESCE(r.raw_data, '{}'::jsonb)
           || jsonb_build_object('_ref', r.supplier_reference)
           || jsonb_build_object('_sm_hex',
                public.fn_sm_hex_from_similares(r.raw_data->>'produtos_similares', r.supplier_reference));

  -- Pai: config-driven (parent_reference no de-para).
  v_parent := public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data);

  -- De-para de variante (campos de variante; parent_reference é tratado acima).
  FOR m IN
    SELECT source_field, source_path, target_field, transform_type, transform_config, source_unit, target_unit
    FROM public.supplier_field_mappings
    WHERE supplier_id = r.supplier_id AND target_table = 'product_variants' AND is_active = TRUE
      AND target_field = ANY(v_cols)
    ORDER BY priority
  LOOP
    IF m.source_path IS NOT NULL THEN v_val := v_doc #>> string_to_array(m.source_path, '.');
    ELSE v_val := v_doc ->> m.source_field; END IF;
    CONTINUE WHEN v_val IS NULL OR TRIM(v_val) = '';
    BEGIN
      v_tx := public.fn_apply_transform(v_val, m.transform_type, m.transform_config, m.source_unit, m.target_unit, r.supplier_id);
    EXCEPTION WHEN OTHERS THEN v_tx := v_val;
    END;
    IF v_tx IS NOT NULL THEN v_assigns := v_assigns || jsonb_build_object(m.target_field, v_tx); END IF;
  END LOOP;

  -- Materializa com as coerções seguras herdadas da versão hardcoded.
  v_code         := v_assigns->>'color_code';
  v_apiid        := v_assigns->>'color_api_id';
  v_cname        := v_assigns->>'color_name';
  v_chex         := v_assigns->>'color_hex';
  v_supplier_sku := COALESCE(v_assigns->>'supplier_sku', r.supplier_reference);
  v_sku          := COALESCE(v_assigns->>'sku', r.supplier_reference);
  v_stock        := public.fn_safe_int(v_assigns->>'stock_quantity');
  v_cost         := public.fn_safe_num(v_assigns->>'cost_price');

  -- Resolução de cor (descritivos) + canônica — idêntico à versão anterior.
  SELECT * INTO v_col FROM public.fn_match_supplier_color(r.supplier_id, v_code, v_apiid, v_cname, v_chex);
  v_fname := COALESCE(v_col.color_name, v_cname);
  v_fcode := COALESCE(v_col.color_code, v_code);
  v_fhex  := COALESCE(v_col.color_hex,  v_chex);
  v_canonical_id := public.fn_match_canonical_color(v_fname, v_fhex);

  INSERT INTO public.produtos_padronizacao_variantes AS pv (
    raw_id, supplier_id, parent_reference, variant_reference,
    sku, supplier_sku, color_name, color_code, color_hex, color_id,
    stock_quantity, cost_price, is_active, status
  ) VALUES (
    r.id, r.supplier_id, v_parent, r.supplier_reference, v_sku, v_supplier_sku,
    v_fname, v_fcode, v_fhex, v_canonical_id,
    v_stock, v_cost, true, 'standardized'::public.produtos_padronizacao_status
  )
  ON CONFLICT (supplier_id, variant_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id, parent_reference=EXCLUDED.parent_reference, sku=EXCLUDED.sku, supplier_sku=EXCLUDED.supplier_sku,
    color_name=EXCLUDED.color_name, color_code=EXCLUDED.color_code, color_hex=EXCLUDED.color_hex, color_id=EXCLUDED.color_id,
    stock_quantity=EXCLUDED.stock_quantity, cost_price=EXCLUDED.cost_price, is_active=EXCLUDED.is_active,
    status=EXCLUDED.status, updated_at=now()
  RETURNING pv.id INTO v_var_id;

  RETURN jsonb_build_object('success', true, 'variante_id', v_var_id, 'parent', v_parent,
                            'cor', v_fname, 'hex', v_fhex, 'color_id_canonico', v_canonical_id);
END;
$function$;

COMMENT ON FUNCTION public.fn_standardize_variant(uuid) IS
  'Padronizador bronze→silver de variante, 100% data-driven via de-para (supplier_field_mappings target_table=product_variants). '
  'Sem branches por fornecedor; cor via fn_match_supplier_color/fn_match_canonical_color; pai via fn_derive_parent_ref.';

-- <<< END 20260610120400_silver_depara_05_standardize_variant_depara.sql <<<

-- >>> BEGIN 20260610120500_silver_depara_06_parity_check.sql >>>
-- ════════════════════════════════════════════════════════════════
-- SILVER DE-PARA — Fase 6/6: verificação de PARIDADE (read-only)
-- fn_parity_standardize_variant compara, SEM gravar, a extração de campos de
-- variante pela lógica ANTIGA (hardcoded por UUID, congelada aqui) vs. a NOVA
-- (de-para via supplier_field_mappings + fn_apply_transform), sobre uma amostra
-- de supplier_products_raw. Emite uma linha por campo divergente.
--
-- Uso (esperado: zero linhas):
--   SELECT * FROM public.fn_parity_standardize_variant(500);
--   SELECT field, count(*) FROM public.fn_parity_standardize_variant(5000) GROUP BY 1;
--
-- Observação: parent_reference e a resolução de cor (fn_match_supplier_color/
-- canônica) não mudaram de lógica — a regra do pai foi apenas movida para o
-- de-para (Fase 3/4), preservando o resultado. Esta checagem foca na EXTRAÇÃO
-- crua dos campos, que é onde os branches por fornecedor viviam.
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_parity_standardize_variant(p_limit integer DEFAULT 500)
RETURNS TABLE(raw_id uuid, supplier uuid, field text, old_val text, new_val text)
LANGUAGE plpgsql STABLE
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r public.supplier_products_raw%ROWTYPE;
  v_doc jsonb; m RECORD; v_val text; v_tx text; v_assigns jsonb;
  -- antigo (hardcoded)
  o_code text; o_apiid text; o_cname text; o_chex text; o_ssku text; o_sku text; o_stock text; o_cost text;
  -- novo (de-para)
  n_code text; n_apiid text; n_cname text; n_chex text; n_ssku text; n_sku text; n_stock text; n_cost text;
  v_SPOT uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_XBZ  uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
  v_ASIA uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_SM   uuid := '841cd690-210a-422a-908c-7676828db272';
BEGIN
  FOR r IN
    SELECT * FROM public.supplier_products_raw
    WHERE supplier_id IN (v_SPOT, v_XBZ, v_ASIA, v_SM)
    ORDER BY imported_at DESC NULLS LAST
    LIMIT p_limit
  LOOP
    -- ── ANTIGO (congelado de 20260605101258) ──
    o_code:=NULL; o_apiid:=NULL; o_cname:=NULL; o_chex:=NULL; o_ssku:=NULL; o_stock:=NULL; o_cost:=NULL;
    IF r.supplier_id=v_SPOT THEN
      o_code:=r.raw_data->>'ColorCode'; o_cname:=r.raw_data->>'ColorName'; o_chex:=r.raw_data->>'ColorHex';
      o_ssku:=r.raw_data->>'Sku'; o_stock:=public.fn_safe_int(r.raw_data->>'StockQuantity')::text;
      o_cost:=public.fn_safe_num(r.raw_data->>'Price1')::text; o_sku:=r.supplier_reference;
    ELSIF r.supplier_id=v_XBZ THEN
      o_apiid:=r.raw_data->>'CorWebPrincipalId'; o_cname:=r.raw_data->>'CorWebPrincipal';
      o_ssku:=r.raw_data->>'CodigoComposto'; o_stock:=public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel')::text;
      o_cost:=public.fn_safe_num(r.raw_data->>'PrecoVenda')::text; o_sku:='XBZ-'||r.supplier_reference;
    ELSIF r.supplier_id=v_ASIA THEN
      o_cname:=r.raw_data->>'var_cor_nome'; o_chex:=r.raw_data->>'var_cor_hex';
      o_ssku:=COALESCE(r.raw_data->>'var_referencia', r.supplier_reference);
      o_stock:=public.fn_safe_int(r.raw_data->>'var_estoque')::text;
      o_cost:=public.fn_safe_num(r.raw_data->>'preco')::text; o_sku:='ASIA-'||r.supplier_reference;
    ELSIF r.supplier_id=v_SM THEN
      o_cname:=public.fn_extract_color_from_title(r.raw_data->>'titulo');
      o_chex := public.fn_sm_hex_from_similares(r.raw_data->>'produtos_similares', r.supplier_reference);
      o_ssku:=r.supplier_reference; o_stock:=public.fn_safe_int(r.raw_data->>'estoque')::text;
      o_cost:=public.fn_safe_num(r.raw_data->>'preco_sem_gravacao_sem_impostos')::text; o_sku:=r.supplier_reference;
    END IF;

    -- ── NOVO (de-para, read-only: replica fn_standardize_variant sem gravar) ──
    v_doc := COALESCE(r.raw_data,'{}'::jsonb)
             || jsonb_build_object('_ref', r.supplier_reference)
             || jsonb_build_object('_sm_hex', public.fn_sm_hex_from_similares(r.raw_data->>'produtos_similares', r.supplier_reference));
    v_assigns := '{}'::jsonb;
    FOR m IN
      SELECT source_field, source_path, target_field, transform_type, transform_config, source_unit, target_unit
      FROM public.supplier_field_mappings
      WHERE supplier_id=r.supplier_id AND target_table='product_variants' AND is_active=TRUE
        AND target_field = ANY(ARRAY['sku','supplier_sku','color_code','color_api_id','color_name','color_hex','stock_quantity','cost_price'])
      ORDER BY priority
    LOOP
      IF m.source_path IS NOT NULL THEN v_val := v_doc #>> string_to_array(m.source_path,'.');
      ELSE v_val := v_doc ->> m.source_field; END IF;
      CONTINUE WHEN v_val IS NULL OR TRIM(v_val)='';
      BEGIN v_tx := public.fn_apply_transform(v_val, m.transform_type, m.transform_config, m.source_unit, m.target_unit, r.supplier_id);
      EXCEPTION WHEN OTHERS THEN v_tx := v_val; END;
      IF v_tx IS NOT NULL THEN v_assigns := v_assigns || jsonb_build_object(m.target_field, v_tx); END IF;
    END LOOP;
    n_code:=v_assigns->>'color_code'; n_apiid:=v_assigns->>'color_api_id';
    n_cname:=v_assigns->>'color_name'; n_chex:=v_assigns->>'color_hex';
    n_ssku:=COALESCE(v_assigns->>'supplier_sku', r.supplier_reference);
    n_sku:=COALESCE(v_assigns->>'sku', r.supplier_reference);
    n_stock:=public.fn_safe_int(v_assigns->>'stock_quantity')::text;
    n_cost:=public.fn_safe_num(v_assigns->>'cost_price')::text;

    -- ── DIFFS (NULLIF dos dois lados; '' antigo ≈ NULL novo é tolerado) ──
    IF NULLIF(o_sku,'')   IS DISTINCT FROM NULLIF(n_sku,'')   THEN raw_id:=r.id; supplier:=r.supplier_id; field:='sku';            old_val:=o_sku;   new_val:=n_sku;   RETURN NEXT; END IF;
    IF NULLIF(o_ssku,'')  IS DISTINCT FROM NULLIF(n_ssku,'')  THEN raw_id:=r.id; supplier:=r.supplier_id; field:='supplier_sku';   old_val:=o_ssku;  new_val:=n_ssku;  RETURN NEXT; END IF;
    IF NULLIF(o_code,'')  IS DISTINCT FROM NULLIF(n_code,'')  THEN raw_id:=r.id; supplier:=r.supplier_id; field:='color_code';     old_val:=o_code;  new_val:=n_code;  RETURN NEXT; END IF;
    IF NULLIF(o_apiid,'') IS DISTINCT FROM NULLIF(n_apiid,'') THEN raw_id:=r.id; supplier:=r.supplier_id; field:='color_api_id';   old_val:=o_apiid; new_val:=n_apiid; RETURN NEXT; END IF;
    IF NULLIF(o_cname,'') IS DISTINCT FROM NULLIF(n_cname,'') THEN raw_id:=r.id; supplier:=r.supplier_id; field:='color_name';     old_val:=o_cname; new_val:=n_cname; RETURN NEXT; END IF;
    IF NULLIF(o_chex,'')  IS DISTINCT FROM NULLIF(n_chex,'')  THEN raw_id:=r.id; supplier:=r.supplier_id; field:='color_hex';      old_val:=o_chex;  new_val:=n_chex;  RETURN NEXT; END IF;
    IF NULLIF(o_stock,'') IS DISTINCT FROM NULLIF(n_stock,'') THEN raw_id:=r.id; supplier:=r.supplier_id; field:='stock_quantity'; old_val:=o_stock; new_val:=n_stock; RETURN NEXT; END IF;
    IF NULLIF(o_cost,'')  IS DISTINCT FROM NULLIF(n_cost,'')  THEN raw_id:=r.id; supplier:=r.supplier_id; field:='cost_price';     old_val:=o_cost;  new_val:=n_cost;  RETURN NEXT; END IF;
  END LOOP;
END;
$function$;

COMMENT ON FUNCTION public.fn_parity_standardize_variant(integer) IS
  'Read-only: compara extração de variante ANTIGA (hardcoded) vs NOVA (de-para) sobre amostra de raws. Zero linhas = paridade. Usar antes de confiar no de-para em produção.';

REVOKE ALL ON FUNCTION public.fn_parity_standardize_variant(integer) FROM PUBLIC, anon, authenticated;

-- <<< END 20260610120500_silver_depara_06_parity_check.sql <<<

-- >>> BEGIN 20260610120511_p0_carrossel_01_hash_canonico_e_enrich_tipado.sql >>>
-- ============================================================================
-- P0-1: Mata o carrossel de reprocessamento + histórico-bomba (auditoria 2026-06-10)
-- Evidência: 100% das versões de histórico XBZ diferem só em '_ruiz_sync_at';
-- flip diário de tipos (string<->number) em PrecoVenda/IdProduto/VendaMinima/
-- Multiplos/IpiTaxa causado por enrich gravar via ->> (texto).
-- NOTA: o corpo de fn_spr_before_write desta migração foi corrigido em
-- 20260610120708 (digest -> extensions.digest). Mantido aqui como aplicado.
-- ============================================================================

ALTER TABLE public.supplier_settings
  ADD COLUMN IF NOT EXISTS hash_excluded_fields text[] NOT NULL DEFAULT '{}';

COMMENT ON COLUMN public.supplier_settings.hash_excluded_fields IS
  'Chaves de raw_data ignoradas no cálculo de content_hash (estado volátil de estoque). Chaves iniciadas em "_" são sempre ignoradas. Mudança nesses campos NÃO deve redisparar padronização de produto.';

UPDATE public.supplier_settings ss
   SET hash_excluded_fields = ARRAY['Disponivel','QuantidadeDisponivel',
        'QuantidadeDisponivelEstoquePrincipal','ReposicaoDataPrevista','StatusConfiabilidade']
  FROM public.suppliers s
 WHERE s.id = ss.supplier_id AND s.code = 'XBZ';

-- fn_xbz_enrich_stock_batch v2: preserva tipos JSON, espelha em stock_data,
-- sem '_ruiz_sync_at' (usa stock_synced_at), e pula linhas sem mudança real
CREATE OR REPLACE FUNCTION public.fn_xbz_enrich_stock_batch(p_supplier_id uuid, p_items jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_updated int := 0;
BEGIN
  UPDATE supplier_products_raw spr
  SET
    raw_data = spr.raw_data || jsonb_strip_nulls(jsonb_build_object(
      'QuantidadeDisponivel',                 item->'QuantidadeDisponivel',
      'QuantidadeDisponivelEstoquePrincipal', item->'QuantidadeDisponivelEstoquePrincipal',
      'ReposicaoDataPrevista',                item->'ReposicaoDataPrevista',
      'Multiplos',                            item->'Multiplos',
      'VendaMinima',                          item->'VendaMinima',
      'Disponivel',                           item->'Disponivel',
      'IpiTaxa',                              item->'IpiTaxa',
      'PrecoVenda',                           item->'PrecoVenda',
      'IdProduto',                            item->'IdProduto',
      'CodigoXbz',                            item->'CodigoXbz',
      'StatusConfiabilidade',                 item->'StatusConfiabilidade'
    )),
    stock_data = COALESCE(spr.stock_data, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
      'QuantidadeDisponivel',                 item->'QuantidadeDisponivel',
      'QuantidadeDisponivelEstoquePrincipal', item->'QuantidadeDisponivelEstoquePrincipal',
      'ReposicaoDataPrevista',                item->'ReposicaoDataPrevista',
      'Disponivel',                           item->'Disponivel'
    )),
    stock_synced_at = now(),
    updated_at = now()
  FROM jsonb_array_elements(p_items) AS item
  WHERE spr.supplier_id = p_supplier_id
    AND spr.supplier_sku = item->>'CodigoComposto'
    AND spr.raw_data IS NOT NULL
    AND (
      spr.raw_data->'QuantidadeDisponivel'                 IS DISTINCT FROM item->'QuantidadeDisponivel' OR
      spr.raw_data->'QuantidadeDisponivelEstoquePrincipal' IS DISTINCT FROM item->'QuantidadeDisponivelEstoquePrincipal' OR
      spr.raw_data->'ReposicaoDataPrevista'                IS DISTINCT FROM item->'ReposicaoDataPrevista' OR
      spr.raw_data->'Multiplos'                            IS DISTINCT FROM item->'Multiplos' OR
      spr.raw_data->'VendaMinima'                          IS DISTINCT FROM item->'VendaMinima' OR
      spr.raw_data->'Disponivel'                           IS DISTINCT FROM item->'Disponivel' OR
      spr.raw_data->'IpiTaxa'                              IS DISTINCT FROM item->'IpiTaxa' OR
      spr.raw_data->'PrecoVenda'                           IS DISTINCT FROM item->'PrecoVenda' OR
      spr.raw_data->'IdProduto'                            IS DISTINCT FROM item->'IdProduto' OR
      spr.raw_data->'CodigoXbz'                            IS DISTINCT FROM item->'CodigoXbz' OR
      spr.raw_data->'StatusConfiabilidade'                 IS DISTINCT FROM item->'StatusConfiabilidade'
    );

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  RETURN jsonb_build_object(
    'updated',     v_updated,
    'total_input', jsonb_array_length(p_items),
    'skipped_noop', jsonb_array_length(p_items) - v_updated,
    'campos',      'tipos JSON preservados; estoque espelhado em stock_data; sem _ruiz_sync_at',
    'ts',          now()
  );
END $$;

-- <<< END 20260610120511_p0_carrossel_01_hash_canonico_e_enrich_tipado.sql <<<

-- >>> BEGIN 20260610120708_p0_carrossel_02_fix_digest_schema.sql >>>
-- Hotfix: digest() vive em extensions.* no Supabase; referência explícita.
-- Versão final e vigente de fn_spr_before_write (hash canônico):
--   • remove TODAS as chaves de metadado '_%' do raw_data persistido
--   • content_hash = sha256(raw_data sem chaves '_%' e sem
--     supplier_settings.hash_excluded_fields do fornecedor)
--   • mantém máquina de estados: attempts++/failed/quarantined via process_errors
CREATE OR REPLACE FUNCTION public.fn_spr_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
DECLARE
  v_clean    jsonb;
  v_hashbase jsonb;
  v_excl     text[];
  v_k        text;
BEGIN
  IF NEW.raw_data ? '_source' AND COALESCE(NEW.source_channel,'') IN ('','n8n','legacy') THEN
    NEW.source_channel := NEW.raw_data->>'_source';
  END IF;
  IF NEW.raw_data ? '_imported_at' AND NEW.imported_at IS NULL THEN
    BEGIN NEW.imported_at := (NEW.raw_data->>'_imported_at')::timestamptz;
    EXCEPTION WHEN others THEN NULL; END;
  END IF;

  v_clean := NEW.raw_data;
  FOR v_k IN SELECT k FROM jsonb_object_keys(NEW.raw_data) k WHERE k LIKE E'\\_%' LOOP
    v_clean := v_clean - v_k;
  END LOOP;
  NEW.raw_data := v_clean;

  SELECT ss.hash_excluded_fields INTO v_excl
    FROM public.supplier_settings ss
   WHERE ss.supplier_id = NEW.supplier_id;
  v_hashbase := CASE WHEN v_excl IS NOT NULL AND array_length(v_excl,1) > 0
                     THEN v_clean - v_excl ELSE v_clean END;
  NEW.content_hash := encode(extensions.digest(v_hashbase::text, 'sha256'), 'hex');

  IF TG_OP = 'INSERT' THEN
    NEW.imported_at := COALESCE(NEW.imported_at, now());
    IF NEW.process_errors IS NOT NULL AND NEW.last_error IS NULL THEN
      NEW.last_error := NEW.process_errors;
    END IF;
  ELSE
    NEW.updated_at := now();

    IF NEW.process_errors IS DISTINCT FROM OLD.process_errors
       AND NEW.process_errors IS NOT NULL THEN
      NEW.last_error := NEW.process_errors;
      NEW.attempts   := COALESCE(OLD.attempts, 0) + 1;
      IF NEW.status <> 'processed'::supplier_raw_status THEN
        NEW.status := CASE WHEN NEW.attempts >= 5
                           THEN 'quarantined'::supplier_raw_status
                           ELSE 'failed'::supplier_raw_status END;
      END IF;
    END IF;

    IF NEW.status = 'processed'::supplier_raw_status
       AND NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.processed_at := COALESCE(NEW.processed_at, now());
    END IF;
  END IF;

  RETURN NEW;
END $$;

-- <<< END 20260610120708_p0_carrossel_02_fix_digest_schema.sql <<<

-- >>> BEGIN 20260610121302_p0_carrossel_03_content_hash_drop_expression.sql >>>
-- content_hash era GENERATED ALWAYS (hash cheio de raw_data) — impossibilitava
-- hash canônico com exclusão de campos voláteis (expressão gerada não pode ler
-- supplier_settings) e tornava a atribuição do trigger CÓDIGO MORTO desde sempre.
-- Converte para coluna comum mantida por fn_spr_before_write.
ALTER TABLE public.supplier_products_raw
  ALTER COLUMN content_hash DROP EXPRESSION;

COMMENT ON COLUMN public.supplier_products_raw.content_hash IS
  'sha256 canônico do payload: raw_data sem chaves de metadado (prefixo _) e sem supplier_settings.hash_excluded_fields. Mantido por fn_spr_before_write (BEFORE INSERT/UPDATE). NÃO é mais coluna gerada.';

-- Pós-migração executado em lotes (one-shot, fora da migração):
