-- >>> BEGIN 20260610122350_p0_seguranca_02_products_grants_por_coluna_anon.sql >>>
-- O REVOKE de coluna não vence grant de TABELA: anon tinha SELECT na tabela
-- products inteira. Corrige: remove o grant de tabela e concede lista explícita
-- de colunas (todas exceto cost_price e ipi_rate).
-- Verificado pós-aplicação via REST com a chave anon:
--   products?select=cost_price -> 42501 permission denied
--   products?select=id,name,sale_price -> 200
--   v_products_public (SECDEF, campos sensíveis já anulados) -> 200
--   GraphQL: campo cost_price deixa de existir no tipo products p/ anon
DO $$
DECLARE v_cols text;
BEGIN
  SELECT string_agg(quote_ident(column_name), ', ' ORDER BY ordinal_position)
    INTO v_cols
  FROM information_schema.columns
  WHERE table_schema='public' AND table_name='products'
    AND column_name NOT IN ('cost_price','ipi_rate');

  REVOKE SELECT ON public.products FROM anon;
  EXECUTE format('GRANT SELECT (%s) ON public.products TO anon', v_cols);
END $$;

-- <<< END 20260610122350_p0_seguranca_02_products_grants_por_coluna_anon.sql <<<

-- >>> BEGIN 20260610122504_p0_estoque_01_fn_reconcile_stock_gold.sql >>>
-- P0: Reconciliação de estoque na Gold. Fonte de verdade: variant_supplier_sources.
-- Auditoria 2026-06-10: 3.931 variantes ativas (21%) com cache divergente da soma
-- das fontes; 515 products idem (dois escritores concorrentes: triggers + jobs).
-- Execução inicial: 3.797 variantes + 182 products corrigidos; divergência pós = 0.
CREATE OR REPLACE FUNCTION public.fn_reconcile_stock_gold(p_dry_run boolean DEFAULT false)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_var int := 0; v_prod int := 0;
  v_var_div int; v_prod_div int;
  v_t0 timestamptz := clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('fn_reconcile_stock_gold')::bigint) THEN
    RETURN jsonb_build_object('skipped','lock_ocupado');
  END IF;

  PERFORM set_config('app.bulk_import_mode','true', true);
  PERFORM set_config('app.write_source','reconcile', true);

  SELECT count(*) INTO v_var_div FROM (
    SELECT v.id FROM product_variants v
    LEFT JOIN variant_supplier_sources s ON s.variant_id=v.id AND s.is_active
    WHERE v.is_active
    GROUP BY v.id, v.stock_quantity
    HAVING COALESCE(v.stock_quantity,0) IS DISTINCT FROM COALESCE(sum(s.quantity),0)) z;
  SELECT count(*) INTO v_prod_div FROM (
    SELECT p.id FROM products p
    LEFT JOIN product_variants v ON v.product_id=p.id AND v.is_active
    WHERE p.is_active
    GROUP BY p.id, p.stock_quantity
    HAVING COALESCE(p.stock_quantity,0) IS DISTINCT FROM COALESCE(sum(v.stock_quantity),0)) z;

  IF p_dry_run THEN
    RETURN jsonb_build_object('dry_run', true,
      'variantes_divergentes', v_var_div, 'products_divergentes', v_prod_div);
  END IF;

  WITH agg AS (
    SELECT v.id, COALESCE(sum(s.quantity) FILTER (WHERE s.is_active),0) AS q
    FROM product_variants v
    LEFT JOIN variant_supplier_sources s ON s.variant_id=v.id
    WHERE v.is_active
    GROUP BY v.id),
  upd AS (
    UPDATE product_variants v SET stock_quantity = agg.q
    FROM agg WHERE v.id=agg.id AND COALESCE(v.stock_quantity,0) IS DISTINCT FROM agg.q
    RETURNING v.id)
  SELECT count(*) INTO v_var FROM upd;

  WITH agg AS (
    SELECT p.id, COALESCE(sum(v.stock_quantity) FILTER (WHERE v.is_active),0) AS q
    FROM products p
    LEFT JOIN product_variants v ON v.product_id=p.id
    WHERE p.is_active
    GROUP BY p.id),
  upd AS (
    UPDATE products p
       SET stock_quantity = agg.q,
           is_stockout = (agg.q <= 0),
           last_stock_update_at = now()
    FROM agg WHERE p.id=agg.id
      AND (COALESCE(p.stock_quantity,0) IS DISTINCT FROM agg.q
           OR p.is_stockout IS DISTINCT FROM (agg.q <= 0))
    RETURNING p.id)
  SELECT count(*) INTO v_prod FROM upd;

  RETURN jsonb_build_object(
    'variantes_divergentes_antes', v_var_div,
    'products_divergentes_antes', v_prod_div,
    'variantes_corrigidas', v_var,
    'products_corrigidos', v_prod,
    'segundos', round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,1),
    'ts', now());
END $$;

REVOKE ALL ON FUNCTION public.fn_reconcile_stock_gold(boolean) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.fn_reconcile_stock_gold(boolean) TO service_role;

SELECT cron.schedule('reconcile-stock-gold-daily', '10 5 * * *',
  'SELECT public.fn_reconcile_stock_gold(false);')
WHERE NOT EXISTS (SELECT 1 FROM cron.job WHERE jobname='reconcile-stock-gold-daily');

-- <<< END 20260610122504_p0_estoque_01_fn_reconcile_stock_gold.sql <<<

-- >>> BEGIN 20260610122909_p1_historico_01_particionamento_mensal.sql >>>
-- P1: Particionamento do histórico do Bronze (5 GB / 3,18M linhas; purga via
-- DELETE em tabela única = bloat permanente). Estratégia de corte por rename:
--   • tabela atual -> supplier_products_raw_history_legacy (purgável por DELETE
--     até esvaziar; depois DROP manual)
--   • novo supplier_products_raw_history PARTITION BY RANGE(captured_at),
--     partições mensais, purga por DROP PARTITION (instantânea, sem bloat)
-- O trigger trg_spr_history insere pelo nome — passa a alimentar a particionada.
-- Sem FKs no histórico novo: trilha de auditoria deve sobreviver à origem.

ALTER TABLE public.supplier_products_raw_history
  RENAME TO supplier_products_raw_history_legacy;

CREATE TABLE public.supplier_products_raw_history (
  id                 uuid        NOT NULL DEFAULT gen_random_uuid(),
  raw_id             uuid,
  supplier_id        uuid,
  supplier_reference varchar,
  content_hash       text,
  raw_data           jsonb,
  captured_at        timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (id, captured_at)
) PARTITION BY RANGE (captured_at);

COMMENT ON TABLE public.supplier_products_raw_history IS
  'Versões anteriores de raw_data quando content_hash canônico muda (trg_spr_history). Particionada por mês; retenção via DROP PARTITION em fn_purge_spr_history. Legado pré-2026-06-10 em supplier_products_raw_history_legacy.';

CREATE INDEX idx_sprh_raw_captured ON public.supplier_products_raw_history (raw_id, captured_at DESC);

CREATE TABLE public.supplier_products_raw_history_p2026_06 PARTITION OF public.supplier_products_raw_history
  FOR VALUES FROM ('2026-06-01') TO ('2026-07-01');
CREATE TABLE public.supplier_products_raw_history_p2026_07 PARTITION OF public.supplier_products_raw_history
  FOR VALUES FROM ('2026-07-01') TO ('2026-08-01');
CREATE TABLE public.supplier_products_raw_history_p2026_08 PARTITION OF public.supplier_products_raw_history
  FOR VALUES FROM ('2026-08-01') TO ('2026-09-01');
CREATE TABLE public.supplier_products_raw_history_p2026_09 PARTITION OF public.supplier_products_raw_history
  FOR VALUES FROM ('2026-09-01') TO ('2026-10-01');
CREATE TABLE public.supplier_products_raw_history_p2026_10 PARTITION OF public.supplier_products_raw_history
  FOR VALUES FROM ('2026-10-01') TO ('2026-11-01');

ALTER TABLE public.supplier_products_raw_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY hist_all_service ON public.supplier_products_raw_history
  FOR ALL TO service_role USING (true) WITH CHECK (true);
CREATE POLICY hist_select_admin ON public.supplier_products_raw_history
  FOR SELECT TO authenticated USING (is_admin_or_above((SELECT auth.uid())));

REVOKE ALL ON public.supplier_products_raw_history FROM anon;
GRANT SELECT ON public.supplier_products_raw_history TO authenticated;
GRANT ALL    ON public.supplier_products_raw_history TO service_role;
REVOKE ALL ON public.supplier_products_raw_history_legacy FROM anon;

DROP FUNCTION IF EXISTS public.fn_purge_spr_history(integer);

CREATE FUNCTION public.fn_purge_spr_history(p_keep_days integer DEFAULT 90)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_cutoff   timestamptz := now() - make_interval(days => p_keep_days);
  v_deleted  integer := 0;
  v_n        integer;
  r          RECORD;
  v_m        date;
  v_nome     text;
BEGIN
  FOR r IN
    SELECT c.oid::regclass::text AS part,
           (regexp_match(pg_get_expr(c.relpartbound, c.oid),
                         'TO \(''([^'']+)''\)'))[1]::timestamptz AS ub
    FROM pg_inherits i
    JOIN pg_class c ON c.oid = i.inhrelid
    WHERE i.inhparent = 'public.supplier_products_raw_history'::regclass
  LOOP
    IF r.ub IS NOT NULL AND r.ub <= v_cutoff THEN
      EXECUTE format('DROP TABLE %s', r.part);
    END IF;
  END LOOP;

  IF to_regclass('public.supplier_products_raw_history_legacy') IS NOT NULL THEN
    DELETE FROM public.supplier_products_raw_history_legacy
     WHERE captured_at < v_cutoff;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_deleted := v_deleted + v_n;
  END IF;

  FOR i IN 0..3 LOOP
    v_m := (date_trunc('month', now()) + (i || ' months')::interval)::date;
    v_nome := 'supplier_products_raw_history_p' || to_char(v_m, 'YYYY_MM');
    IF to_regclass('public.'||v_nome) IS NULL THEN
      EXECUTE format(
        'CREATE TABLE public.%I PARTITION OF public.supplier_products_raw_history FOR VALUES FROM (%L) TO (%L)',
        v_nome, v_m, (v_m + interval '1 month')::date);
    END IF;
  END LOOP;

  RETURN v_deleted;
END $$;

REVOKE ALL ON FUNCTION public.fn_purge_spr_history(integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_purge_spr_history(integer) TO service_role;

-- <<< END 20260610122909_p1_historico_01_particionamento_mensal.sql <<<

-- >>> BEGIN 20260610122930_grant_anon_video_function_family_v2.sql >>>
-- G11: funções da família de vídeo sem GRANT EXECUTE p/ anon (processor do VPS roda como anon).
-- fn_spot_link_video sem grant = próximo download SPOT ok falharia no link.
-- Varredura idempotente: concede a TODAS as funções de vídeo que estejam sem o grant.
DO $$
DECLARE r record; n int := 0;
BEGIN
  FOR r IN
    SELECT p.oid::regprocedure AS sig
    FROM pg_proc p JOIN pg_namespace ns ON ns.oid = p.pronamespace
    WHERE ns.nspname = 'public'
      AND (p.proname LIKE 'fn_video%'
           OR p.proname LIKE 'fn_spot%video%'
           OR p.proname IN ('fn_spot_vimeo_daily_sync','fn_spot_enqueue_vimeo_eu',
                            'fn_spot_enqueue_new_videos','fn_xbz_link_video',
                            'fn_asia_link_video','fn_sm_link_video'))
      AND NOT has_function_privilege('anon', p.oid, 'EXECUTE')
  LOOP
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO anon', r.sig);
    n := n + 1;
  END LOOP;
  RAISE NOTICE 'GRANTs anon aplicados: %', n;
END $$;;

-- <<< END 20260610122930_grant_anon_video_function_family_v2.sql <<<

