-- >>> BEGIN 20260611011713_fix_standardize_variant_fcode_fhex_swallowed_by_comment.sql >>>
-- FIX CRÍTICO: fn_standardize_variant — v_fcode/v_fhex engolidos por comentário.
-- Patch 2026-06-09 deixou v_fcode:=/v_fhex:= após `--` na mesma linha (nunca executavam).
-- Impacto: color_code NULL em 9.892 vars XBZ, 1.588 Asia, 753 SM; hex NULL em 9.902 XBZ.
-- Correção mínima: mesmas lógicas, atribuições em linhas próprias.

CREATE OR REPLACE FUNCTION public.fn_standardize_variant(p_raw_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r             public.supplier_products_raw%ROWTYPE;
  v_parent      text; v_code text; v_apiid text; v_cname text; v_chex text;
  v_col         RECORD;
  v_sku         text; v_supplier_sku text; v_stock integer; v_cost numeric; v_var_id uuid;
  v_fname       text; v_fcode text; v_fhex text; v_canonical_id uuid;
  v_cp1 numeric; v_cp2 numeric; v_cp3 numeric; v_cp4 numeric; v_cp5 numeric;
  v_mq1 int;    v_mq2 int;    v_mq3 int;    v_mq4 int;    v_mq5 int;
  v_nq1 int;    v_nq2 int;    v_nq3 int;
  v_nd1 date;   v_nd2 date;   v_nd3 date;
  v_mult        int;
  v_thumb       text;
  v_images      jsonb;
  v_videos      jsonb;
  v_cap_ml      int;
  v_SPOT        uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
  v_XBZ         uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
  v_ASIA        uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_SM          uuid := '841cd690-210a-422a-908c-7676828db272';
  m             RECORD; v_val text; v_tx text;
  v_pv_assigns  jsonb := '{}'::jsonb;
  v_vss_assigns jsonb := '{}'::jsonb;
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','raw_nao_encontrado'); END IF;
  v_parent := public.fn_derive_parent_ref(r.supplier_id, r.supplier_reference, r.raw_data);

  IF r.supplier_id = v_SPOT THEN
    FOR m IN SELECT sfm.source_field,sfm.target_field,sfm.target_table,sfm.transform_type,sfm.transform_config,sfm.source_unit,sfm.target_unit
             FROM public.supplier_field_mappings sfm
             WHERE sfm.supplier_id=v_SPOT AND sfm.target_table IN('product_variants','variant_supplier_sources')
               AND sfm.is_active=TRUE AND sfm.target_field NOT IN('color_id','size_id','web_sku','length_cm','width_cm')
             ORDER BY sfm.target_table,sfm.priority NULLS LAST LOOP
      v_val:=CASE WHEN m.transform_config->>'source_blob'='stock_data' THEN r.stock_data->>m.source_field ELSE r.raw_data->>m.source_field END;
      CONTINUE WHEN v_val IS NULL OR TRIM(v_val)='';
      BEGIN v_tx:=public.fn_apply_transform(v_val,m.transform_type,m.transform_config,m.source_unit,m.target_unit,v_SPOT);
      EXCEPTION WHEN OTHERS THEN v_tx:=v_val; END;
      CONTINUE WHEN v_tx IS NULL;
      IF m.target_table='product_variants' THEN v_pv_assigns:=v_pv_assigns||jsonb_build_object(m.target_field,v_tx);
      ELSE v_vss_assigns:=v_vss_assigns||jsonb_build_object(m.target_field,v_tx); END IF;
    END LOOP;
    v_supplier_sku:=v_pv_assigns->>'supplier_sku'; v_code:=v_pv_assigns->>'color_code';
    v_cname:=COALESCE(NULLIF(TRIM(v_pv_assigns->>'color_name'),''),r.raw_data->>'ColorDesc1');
    v_chex:=COALESCE(NULLIF(TRIM(v_pv_assigns->>'color_hex'),''),r.raw_data->>'ColorHex1');
    v_thumb:=COALESCE(v_pv_assigns->>'selected_thumbnail',v_vss_assigns->>'supplier_thumbnail');
    v_sku:=r.supplier_reference;
    BEGIN v_images:=COALESCE(CASE WHEN v_pv_assigns?'images' THEN(v_pv_assigns->>'images')::jsonb END,CASE WHEN v_vss_assigns?'supplier_images' THEN(v_vss_assigns->>'supplier_images')::jsonb END,'[]'::jsonb); EXCEPTION WHEN OTHERS THEN v_images:='[]'::jsonb; END;
    BEGIN v_videos:=CASE WHEN v_vss_assigns?'supplier_videos' THEN(v_vss_assigns->>'supplier_videos')::jsonb END; EXCEPTION WHEN OTHERS THEN v_videos:=NULL; END;
    v_stock:=public.fn_safe_int(COALESCE(v_vss_assigns->>'quantity',v_vss_assigns->>'stock_main_warehouse',r.stock_data->>'Quantity',r.raw_data->>'StockQuantity'));
    v_cost:=public.fn_safe_num(COALESCE(v_vss_assigns->>'cost_price',r.raw_data->>'Price1'));
    v_cp1:=public.fn_safe_num(COALESCE(v_vss_assigns->>'cost_price_1',r.raw_data->>'Price1'));
    v_cp2:=public.fn_safe_num(v_vss_assigns->>'cost_price_2'); v_cp3:=public.fn_safe_num(v_vss_assigns->>'cost_price_3');
    v_cp4:=public.fn_safe_num(v_vss_assigns->>'cost_price_4'); v_cp5:=public.fn_safe_num(v_vss_assigns->>'cost_price_5');
    v_mq1:=public.fn_safe_int(v_vss_assigns->>'min_qty_1'); v_mq2:=public.fn_safe_int(v_vss_assigns->>'min_qty_2');
    v_mq3:=public.fn_safe_int(v_vss_assigns->>'min_qty_3'); v_mq4:=public.fn_safe_int(v_vss_assigns->>'min_qty_4'); v_mq5:=public.fn_safe_int(v_vss_assigns->>'min_qty_5');
    v_mult:=public.fn_safe_int(COALESCE(v_vss_assigns->>'sale_multiplier',r.raw_data->>'Multiplier'));
    v_nq1:=public.fn_safe_int(v_vss_assigns->>'next_quantity_1'); v_nq2:=public.fn_safe_int(v_vss_assigns->>'next_quantity_2'); v_nq3:=public.fn_safe_int(v_vss_assigns->>'next_quantity_3');
    v_nd1:=CASE WHEN v_vss_assigns->>'next_date_1'~'^\d{4}-\d{2}-\d{2}' THEN LEFT(v_vss_assigns->>'next_date_1',10)::date END;
    v_nd2:=CASE WHEN v_vss_assigns->>'next_date_2'~'^\d{4}-\d{2}-\d{2}' THEN LEFT(v_vss_assigns->>'next_date_2',10)::date END;
    v_nd3:=CASE WHEN v_vss_assigns->>'next_date_3'~'^\d{4}-\d{2}-\d{2}' THEN LEFT(v_vss_assigns->>'next_date_3',10)::date END;

  ELSIF r.supplier_id = v_SM THEN
    FOR m IN SELECT sfm.source_field,sfm.target_field,sfm.target_table,sfm.transform_type,sfm.transform_config,sfm.source_unit,sfm.target_unit
             FROM public.supplier_field_mappings sfm
             WHERE sfm.supplier_id=v_SM AND sfm.target_table IN('product_variants','variant_supplier_sources') AND sfm.is_active=TRUE
             ORDER BY sfm.target_table,sfm.priority NULLS LAST LOOP
      v_val:=CASE WHEN m.transform_config->>'source_blob'='stock_data' THEN r.stock_data->>m.source_field ELSE r.raw_data->>m.source_field END;
      CONTINUE WHEN v_val IS NULL OR TRIM(v_val)='';
      BEGIN v_tx:=public.fn_apply_transform(v_val,m.transform_type,m.transform_config,m.source_unit,m.target_unit,v_SM); EXCEPTION WHEN OTHERS THEN v_tx:=v_val; END;
      CONTINUE WHEN v_tx IS NULL;
      IF m.target_table='product_variants' THEN v_pv_assigns:=v_pv_assigns||jsonb_build_object(m.target_field,v_tx);
      ELSE v_vss_assigns:=v_vss_assigns||jsonb_build_object(m.target_field,v_tx); END IF;
    END LOOP;
    v_cname:=public.fn_extract_color_from_title(r.raw_data->>'titulo');
    v_chex:=(SELECT split_part(item,'|',2) FROM unnest(string_to_array(r.raw_data->>'produtos_similares',';')) item WHERE split_part(item,'|',1)=r.supplier_reference AND split_part(item,'|',2)~*'^#[0-9a-f]{6}$' LIMIT 1);
    v_supplier_sku:=COALESCE(NULLIF(TRIM(v_pv_assigns->>'supplier_sku'),''),r.supplier_reference);
    v_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(COALESCE(v_pv_assigns->>'stock_quantity',r.raw_data->>'estoque'));
    v_cost:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price',r.raw_data->>'preco_sem_gravacao_sem_impostos'));
    v_cp1:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_1',r.raw_data->>'preco_sem_gravacao_sem_impostos'));
    v_cp2:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_2',r.raw_data->>'preco_com_gravacao_sem_impostos'));
    v_cp3:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_3',r.raw_data->>'preco_sem_gravacao_com_impostos'));
    v_cp4:=public.fn_safe_num(COALESCE(v_pv_assigns->>'cost_price_4',r.raw_data->>'preco_com_gravacao_com_impostos'));
    v_mq1:=public.fn_safe_int(COALESCE(v_pv_assigns->>'min_qty_1',r.raw_data->>'quantidade_minima_sugerida'));
    v_thumb:=NULLIF(TRIM(COALESCE(v_pv_assigns->>'supplier_thumbnail',r.raw_data->>'url_foto')),'');
    BEGIN v_images:=CASE WHEN v_pv_assigns?'supplier_images' THEN(v_pv_assigns->>'supplier_images')::jsonb ELSE NULL END; EXCEPTION WHEN OTHERS THEN v_images:=NULL; END;

  ELSIF r.supplier_id = v_XBZ THEN
    v_apiid        := r.raw_data->>'CorWebPrincipalId';
    v_cname        := r.raw_data->>'CorWebPrincipal';
    v_supplier_sku := r.raw_data->>'CodigoComposto';
    v_stock        := GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel'),0));
    v_cost         := public.fn_safe_num(r.raw_data->>'PrecoVenda');
    v_sku          := 'XBZ-'||r.supplier_reference;
    v_mult         := CASE WHEN public.fn_safe_int(r.raw_data->>'Multiplos')>0 THEN public.fn_safe_int(r.raw_data->>'Multiplos') ELSE NULL END;
    v_mq1          := CASE WHEN public.fn_safe_int(r.raw_data->>'VendaMinima')>0 THEN public.fn_safe_int(r.raw_data->>'VendaMinima') ELSE NULL END;
    v_cap_ml := CASE
        WHEN r.raw_data->>'Nome' IS NOT NULL
         AND r.raw_data->>'Nome' !~* '(127v|220v|led|lampada|lâmpada|pisca)'
        THEN public.extract_capacity_ml(r.raw_data->>'Nome')
        ELSE NULL
    END;
    v_thumb := CASE
        WHEN r.raw_data->>'ImageLink' LIKE 'https://%' OR r.raw_data->>'ImageLink' LIKE 'http://%' THEN r.raw_data->>'ImageLink'
        WHEN r.raw_data->>'ImageLink' LIKE 'hhttps://%' THEN SUBSTRING(r.raw_data->>'ImageLink' FROM 2)
        WHEN r.raw_data->>'ImageLink' LIKE 'htt%brindes.com.br%' THEN 'https://cdn.xbzbrindes.com.br'||SUBSTRING(r.raw_data->>'ImageLink' FROM POSITION('brindes.com.br' IN r.raw_data->>'ImageLink')+14)
        ELSE NULL END;
    BEGIN v_images:=CASE WHEN r.site_data->'imagens' IS NOT NULL AND jsonb_array_length(r.site_data->'imagens')>0 THEN r.site_data->'imagens' ELSE NULL END; EXCEPTION WHEN OTHERS THEN v_images:=NULL; END;
    BEGIN v_videos:=CASE WHEN (r.site_data->'video'->>'indicador')::boolean=true AND r.site_data->'video'->>'embed_id' IS NOT NULL
        THEN jsonb_build_array(jsonb_build_object('embed_id',r.site_data->'video'->>'embed_id','embed_url',r.site_data->'video'->>'embed_url','watch_url',r.site_data->'video'->>'watch_url','plataforma','youtube','indicador',true))
        ELSE NULL END; EXCEPTION WHEN OTHERS THEN v_videos:=NULL; END;
    v_nd1:=CASE WHEN r.raw_data->>'ReposicaoDataPrevista' IS NOT NULL AND LEFT(r.raw_data->>'ReposicaoDataPrevista',4)!='0001' THEN LEFT(r.raw_data->>'ReposicaoDataPrevista',10)::date ELSE NULL END;
    v_nq1:=CASE WHEN r.raw_data->>'QuantidadeDisponivelEstoquePrincipal' IS NOT NULL AND GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel'),0))>GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivelEstoquePrincipal'),0)) THEN GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivel'),0)-GREATEST(0,COALESCE(public.fn_safe_int(r.raw_data->>'QuantidadeDisponivelEstoquePrincipal'),0))) ELSE NULL END;

  ELSIF r.supplier_id = v_ASIA THEN
    v_cname:=r.raw_data->>'var_cor_nome'; v_chex:=r.raw_data->>'var_cor_hex';
    v_supplier_sku:=COALESCE(r.raw_data->>'var_referencia',r.supplier_reference);
    v_stock:=public.fn_safe_int(COALESCE(r.stock_data->>'qtd_estoque',r.raw_data->>'var_estoque'));
    v_cost:=public.fn_safe_num(r.raw_data->>'preco'); v_sku:='ASIA-'||r.supplier_reference;
    v_nd1:=CASE WHEN COALESCE(r.stock_data->'previsao_entrega'->0->>'data',r.raw_data->'previsao_entrega'->0->>'data')~'^\d{4}-\d{2}-\d{2}' THEN LEFT(COALESCE(r.stock_data->'previsao_entrega'->0->>'data',r.raw_data->'previsao_entrega'->0->>'data'),10)::date END;
    v_nq1:=public.fn_safe_int(COALESCE(r.stock_data->'previsao_entrega'->0->>'quantidade',r.raw_data->'previsao_entrega'->0->>'quantidade'));
  ELSE
    v_cname:=r.raw_data->>'cor'; v_supplier_sku:=r.supplier_reference;
    v_stock:=public.fn_safe_int(r.raw_data->>'estoque'); v_cost:=public.fn_safe_num(r.raw_data->>'preco_base'); v_sku:=r.supplier_reference;
  END IF;

  SELECT * INTO v_col FROM public.fn_match_supplier_color(r.supplier_id,v_code,v_apiid,v_cname,v_chex);
  -- FIX 2026-06-11: as 3 atribuições abaixo estavam na MESMA linha de um
  -- comentário `--` (patch 2026-06-09) e nunca executavam; color_code e
  -- color_hex saíam NULL. Agora em linhas próprias.
  v_fname:=public.fn_normalize_product_name(COALESCE(v_col.color_name,v_cname));
  v_fcode:=COALESCE(v_col.color_code,v_code);
  v_fhex:=COALESCE(v_col.color_hex,v_chex);
  -- SPOT CANONICAL CODE GUARD (pipeline-proof 2026-06-09):
  -- Preserva código 3-dígitos da API quando fn_match_supplier_color
  -- retorna código legado 2-dígitos via fallback de nome.
  IF r.supplier_id = v_SPOT AND v_code IS NOT NULL
     AND length(v_code) = 3 AND COALESCE(length(v_fcode), 0) < 3 THEN
    v_fcode := v_code;
  END IF;
  v_canonical_id:=public.fn_match_canonical_color(v_fname,v_fhex);

  INSERT INTO public.produtos_padronizacao_variantes AS pv (
    raw_id,supplier_id,parent_reference,variant_reference,sku,supplier_sku,color_name,color_code,color_hex,color_id,
    stock_quantity,cost_price,is_active,status,capacity_ml,
    cost_price_1,cost_price_2,cost_price_3,cost_price_4,cost_price_5,
    min_qty_1,min_qty_2,min_qty_3,min_qty_4,min_qty_5,
    next_quantity_1,next_quantity_2,next_quantity_3,next_date_1,next_date_2,next_date_3,
    sale_multiplier,supplier_thumbnail,supplier_images,supplier_videos
  ) VALUES (
    r.id,r.supplier_id,v_parent,r.supplier_reference,v_sku,v_supplier_sku,v_fname,v_fcode,v_fhex,v_canonical_id,
    v_stock,v_cost,true,'standardized'::public.produtos_padronizacao_status,v_cap_ml,
    v_cp1,v_cp2,v_cp3,v_cp4,v_cp5,
    v_mq1,v_mq2,v_mq3,v_mq4,v_mq5,
    v_nq1,v_nq2,v_nq3,v_nd1,v_nd2,v_nd3,
    v_mult,v_thumb,v_images,v_videos
  )
  ON CONFLICT (supplier_id,variant_reference) DO UPDATE SET
    raw_id=EXCLUDED.raw_id,parent_reference=EXCLUDED.parent_reference,sku=EXCLUDED.sku,supplier_sku=EXCLUDED.supplier_sku,
    color_name=EXCLUDED.color_name,color_code=EXCLUDED.color_code,color_hex=EXCLUDED.color_hex,
    color_id=COALESCE(EXCLUDED.color_id,pv.color_id),
    stock_quantity=EXCLUDED.stock_quantity,cost_price=EXCLUDED.cost_price,is_active=EXCLUDED.is_active,status=EXCLUDED.status,
    capacity_ml=COALESCE(EXCLUDED.capacity_ml, pv.capacity_ml),
    cost_price_1=EXCLUDED.cost_price_1,cost_price_2=EXCLUDED.cost_price_2,cost_price_3=EXCLUDED.cost_price_3,
    cost_price_4=EXCLUDED.cost_price_4,cost_price_5=EXCLUDED.cost_price_5,
    min_qty_1=EXCLUDED.min_qty_1,min_qty_2=EXCLUDED.min_qty_2,min_qty_3=EXCLUDED.min_qty_3,
    min_qty_4=EXCLUDED.min_qty_4,min_qty_5=EXCLUDED.min_qty_5,
    next_quantity_1=EXCLUDED.next_quantity_1,next_quantity_2=EXCLUDED.next_quantity_2,next_quantity_3=EXCLUDED.next_quantity_3,
    next_date_1=EXCLUDED.next_date_1,next_date_2=EXCLUDED.next_date_2,next_date_3=EXCLUDED.next_date_3,
    sale_multiplier=EXCLUDED.sale_multiplier,
    supplier_thumbnail=EXCLUDED.supplier_thumbnail,supplier_images=EXCLUDED.supplier_images,supplier_videos=EXCLUDED.supplier_videos,
    updated_at=now()
  RETURNING pv.id INTO v_var_id;

  RETURN jsonb_build_object(
    'success',true,'variante_id',v_var_id,'parent',v_parent,'cor',v_fname,
    'capacity_ml',v_cap_ml,'thumbnail',v_thumb IS NOT NULL,
    'images_count',CASE WHEN v_images IS NOT NULL THEN jsonb_array_length(v_images) ELSE 0 END,
    'has_video',v_videos IS NOT NULL,'cost_price',v_cost,'sale_multiplier',v_mult,'min_qty_1',v_mq1,
    'next_date_1',v_nd1,'next_quantity_1',v_nq1
  );
END;
$function$;

COMMENT ON FUNCTION public.fn_standardize_variant(uuid) IS
  'Bronze->Silver (variante). De-para supplier_field_mappings p/ SPOT e SM; hardcoded XBZ/Asia; fallback generico. FIX 2026-06-11: v_fcode/v_fhex estavam comentados desde 2026-06-09 (color_code/hex saiam NULL).';;

-- <<< END 20260611011713_fix_standardize_variant_fcode_fhex_swallowed_by_comment.sql <<<

-- >>> BEGIN 20260611011808_fase9_01_cron_promotes_orphan_standardized.sql >>>
-- ITEM A — Robustez: process_pending_batches também promove staging órfão.
-- Caso raro (race) visto em validação: pad/padvar 'standardized' com raw já 'processed'
-- → não havia raw pendente, o cron pulava o fornecedor e o staging ficava preso até o
-- próximo import. Agora: além do fluxo normal, um segundo passo promove fornecedores
-- com staging standardized SEM raw pendente. Idempotente; advisory locks preservados.
CREATE OR REPLACE FUNCTION public.process_pending_batches()
RETURNS TABLE(batch_id uuid, products_processed integer, status text)
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_sup  RECORD;
  v_std  jsonb;
  v_prom jsonb;
BEGIN
  -- Fluxo principal: fornecedores auto_sync com raw pendente (Bronze→Silver→Gold)
  FOR v_sup IN
      SELECT ss.supplier_id
      FROM public.supplier_settings ss
      WHERE COALESCE(ss.auto_sync_enabled, false) = true
        AND EXISTS (
          SELECT 1 FROM public.supplier_products_raw r
          WHERE r.supplier_id = ss.supplier_id AND r.status = 'pending'
        )
  LOOP
      v_std  := public.fn_standardize_supplier(v_sup.supplier_id, 1000);
      v_prom := public.fn_promote_supplier(v_sup.supplier_id, NULL);

      batch_id           := NULL::uuid;
      products_processed := COALESCE((v_prom->>'pais_promovidos')::integer, 0);
      status := CASE
                  WHEN COALESCE((v_std->>'erros')::int, 0) = 0
                   AND COALESCE((v_prom->>'erros')::int, 0) = 0 THEN 'SUCCESS'
                  ELSE 'PARTIAL'
                END;
      RETURN NEXT;
  END LOOP;

  -- Robustez (Fase 9): staging órfão — pad/padvar standardized SEM raw pendente.
  FOR v_sup IN
      SELECT DISTINCT x.supplier_id
      FROM (
        SELECT supplier_id FROM public.produtos_padronizacao WHERE status='standardized'
        UNION
        SELECT supplier_id FROM public.produtos_padronizacao_variantes WHERE status='standardized'
      ) x
      WHERE NOT EXISTS (
        SELECT 1 FROM public.supplier_products_raw r
        WHERE r.supplier_id = x.supplier_id AND r.status = 'pending'
      )
  LOOP
      v_prom := public.fn_promote_supplier(v_sup.supplier_id, NULL);
      batch_id           := NULL::uuid;
      products_processed := COALESCE((v_prom->>'pais_promovidos')::integer, 0);
      status := CASE WHEN COALESCE((v_prom->>'erros')::int,0)=0 THEN 'SUCCESS' ELSE 'PARTIAL' END;
      RETURN NEXT;
  END LOOP;

  RETURN;
END;
$function$;

COMMENT ON FUNCTION public.process_pending_batches() IS
  'Cron de ingestao (*/5). Pipeline Medallion 3 fases por fornecedor auto_sync (standardize+promote) + passo de robustez (Fase 9): promove staging standardized orfao (sem raw pendente). Substitui o atalho fn_process_raw_v2.';;

-- <<< END 20260611011808_fase9_01_cron_promotes_orphan_standardized.sql <<<

-- >>> BEGIN 20260611011855_fase9_01b_fix_ambiguous_status_qualify_columns.sql >>>
-- HOTFIX imediato: qualifica colunas 'status' (colidiam com o OUT-param da função).
CREATE OR REPLACE FUNCTION public.process_pending_batches()
RETURNS TABLE(batch_id uuid, products_processed integer, status text)
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_sup  RECORD;
  v_std  jsonb;
  v_prom jsonb;
BEGIN
  FOR v_sup IN
      SELECT ss.supplier_id
      FROM public.supplier_settings ss
      WHERE COALESCE(ss.auto_sync_enabled, false) = true
        AND EXISTS (
          SELECT 1 FROM public.supplier_products_raw r
          WHERE r.supplier_id = ss.supplier_id AND r.status = 'pending'
        )
  LOOP
      v_std  := public.fn_standardize_supplier(v_sup.supplier_id, 1000);
      v_prom := public.fn_promote_supplier(v_sup.supplier_id, NULL);

      batch_id           := NULL::uuid;
      products_processed := COALESCE((v_prom->>'pais_promovidos')::integer, 0);
      status := CASE
                  WHEN COALESCE((v_std->>'erros')::int, 0) = 0
                   AND COALESCE((v_prom->>'erros')::int, 0) = 0 THEN 'SUCCESS'
                  ELSE 'PARTIAL'
                END;
      RETURN NEXT;
  END LOOP;

  -- Robustez (Fase 9): staging standardized órfão (sem raw pendente) — colunas qualificadas.
  FOR v_sup IN
      SELECT DISTINCT x.supplier_id
      FROM (
        SELECT pp.supplier_id FROM public.produtos_padronizacao pp WHERE pp.status='standardized'
        UNION
        SELECT pv.supplier_id FROM public.produtos_padronizacao_variantes pv WHERE pv.status='standardized'
      ) x
      WHERE NOT EXISTS (
        SELECT 1 FROM public.supplier_products_raw r
        WHERE r.supplier_id = x.supplier_id AND r.status = 'pending'
      )
  LOOP
      v_prom := public.fn_promote_supplier(v_sup.supplier_id, NULL);
      batch_id           := NULL::uuid;
      products_processed := COALESCE((v_prom->>'pais_promovidos')::integer, 0);
      status := CASE WHEN COALESCE((v_prom->>'erros')::int,0)=0 THEN 'SUCCESS' ELSE 'PARTIAL' END;
      RETURN NEXT;
  END LOOP;

  RETURN;
END;
$function$;;

-- <<< END 20260611011855_fase9_01b_fix_ambiguous_status_qualify_columns.sql <<<

-- >>> BEGIN 20260611012037_fase9_02_fix_promote_variants_checks_and_orphan_variants.sql >>>
-- Fase 9 / fixes expostos pelo passo de robustez (erros reais presos em silêncio):
-- (1) fn_promote_variants_of_parent: limpa process_errors ao marcar raw processed
--     (respeita chk_spr_no_processed_with_errors) e só grava VSS com cost_price > 0
--     (respeita chk_vss_cost_price_not_zero; custo 0 do fornecedor = sem source de custo).
-- (2) process_pending_batches: no passo de robustez, também promove VARIANTES órfãs
--     standardized cujo pai já está promoted (fn_promote_supplier não as cobre).

CREATE OR REPLACE FUNCTION public.fn_promote_variants_of_parent(
    p_supplier_id uuid,
    p_parent_reference text
)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_pid uuid; v_org uuid; pv RECORD; v_vid uuid; v_count int := 0; v_attrs jsonb;
  v_existing_pid uuid;
BEGIN
  PERFORM set_config('app.write_source','pipeline',true);
  SELECT id, organization_id INTO v_pid, v_org FROM public.products
  WHERE supplier_id=p_supplier_id AND supplier_reference=p_parent_reference;
  IF v_pid IS NULL THEN RETURN jsonb_build_object('success',false,'error','produto_pai_nao_promovido','parent',p_parent_reference); END IF;

  FOR pv IN
    SELECT * FROM public.produtos_padronizacao_variantes
    WHERE supplier_id=p_supplier_id AND parent_reference=p_parent_reference AND status='standardized'
  LOOP
    v_attrs := jsonb_strip_nulls(jsonb_build_object('cor', pv.color_name, 'codigo_cor', pv.color_code, 'hex', pv.color_hex));

    SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants WHERE sku = pv.sku;
    IF v_vid IS NULL THEN
      SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants
      WHERE product_id=v_pid AND supplier_sku=pv.supplier_sku;
    END IF;

    IF v_vid IS NULL THEN
      INSERT INTO public.product_variants (product_id, sku, supplier_sku, name, attributes, color_name, color_code, color_hex, color_id, stock_quantity, is_active, last_sync_at, last_sync_supplier_id)
      VALUES (v_pid, pv.sku, pv.supplier_sku, COALESCE(pv.color_name, pv.sku), v_attrs,
              pv.color_name, pv.color_code, pv.color_hex, pv.color_id,
              COALESCE(pv.stock_quantity,0), COALESCE(pv.is_active,true), now(), p_supplier_id)
      ON CONFLICT (sku) DO UPDATE SET
        supplier_sku = EXCLUDED.supplier_sku,
        attributes   = COALESCE(public.product_variants.attributes,'{}'::jsonb) || EXCLUDED.attributes,
        color_name   = COALESCE(EXCLUDED.color_name, public.product_variants.color_name),
        color_code   = COALESCE(EXCLUDED.color_code, public.product_variants.color_code),
        color_hex    = COALESCE(EXCLUDED.color_hex, public.product_variants.color_hex),
        color_id     = COALESCE(EXCLUDED.color_id, public.product_variants.color_id),
        stock_quantity = COALESCE(EXCLUDED.stock_quantity, public.product_variants.stock_quantity),
        last_sync_at = now(), last_sync_supplier_id = EXCLUDED.last_sync_supplier_id
      RETURNING id INTO v_vid;
    ELSE
      UPDATE public.product_variants SET
        attributes = COALESCE(attributes,'{}'::jsonb) || v_attrs,
        color_name=COALESCE(pv.color_name,color_name), color_code=COALESCE(pv.color_code,color_code),
        color_hex=COALESCE(pv.color_hex,color_hex), color_id=COALESCE(pv.color_id,color_id),
        stock_quantity=COALESCE(pv.stock_quantity,stock_quantity), last_sync_at=now(), last_sync_supplier_id=p_supplier_id
      WHERE id=v_vid;
    END IF;

    -- FIX (chk_vss_cost_price_not_zero): só grava source de custo quando custo > 0.
    IF pv.cost_price IS NOT NULL AND pv.cost_price > 0 THEN
      INSERT INTO public.variant_supplier_sources (organization_id, variant_id, supplier_id, cost_price, supplier_sku, supplier_color_code, supplier_color_name, is_active, source, last_synced_at)
      VALUES (v_org, v_vid, p_supplier_id, pv.cost_price, pv.supplier_sku, pv.color_code, pv.color_name, true, 'silver', now())
      ON CONFLICT (variant_id, supplier_id) DO UPDATE SET
        cost_price          = EXCLUDED.cost_price,
        supplier_sku        = EXCLUDED.supplier_sku,
        supplier_color_code = EXCLUDED.supplier_color_code,
        supplier_color_name = EXCLUDED.supplier_color_name,
        is_active           = EXCLUDED.is_active,
        source              = EXCLUDED.source,
        last_synced_at      = EXCLUDED.last_synced_at;
    END IF;

    UPDATE public.produtos_padronizacao_variantes SET status='promoted', variant_id=v_vid, updated_at=now() WHERE id=pv.id;

    -- 3-fases: raw concluída ao chegar no Gold. FIX: limpa process_errors
    -- (promoção bem-sucedida supera erro anterior; respeita chk_spr_no_processed_with_errors).
    IF pv.raw_id IS NOT NULL THEN
      UPDATE public.supplier_products_raw
         SET status='processed', processed_at=now(), product_id=v_pid, variant_id=v_vid,
             process_errors=NULL
       WHERE id=pv.raw_id AND status <> 'processed';
    END IF;

    v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('success',true,'product_id',v_pid,'variantes_promovidas',v_count);
END;
$function$;

-- (2) cron: robustez também para variantes órfãs (pai já promoted)
CREATE OR REPLACE FUNCTION public.process_pending_batches()
RETURNS TABLE(batch_id uuid, products_processed integer, status text)
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_sup  RECORD;
  v_par  RECORD;
  v_std  jsonb;
  v_prom jsonb;
  v_vp   jsonb;
  v_cnt  integer;
BEGIN
  FOR v_sup IN
      SELECT ss.supplier_id
      FROM public.supplier_settings ss
      WHERE COALESCE(ss.auto_sync_enabled, false) = true
        AND EXISTS (
          SELECT 1 FROM public.supplier_products_raw r
          WHERE r.supplier_id = ss.supplier_id AND r.status = 'pending'
        )
  LOOP
      v_std  := public.fn_standardize_supplier(v_sup.supplier_id, 1000);
      v_prom := public.fn_promote_supplier(v_sup.supplier_id, NULL);

      batch_id           := NULL::uuid;
      products_processed := COALESCE((v_prom->>'pais_promovidos')::integer, 0);
      status := CASE
                  WHEN COALESCE((v_std->>'erros')::int, 0) = 0
                   AND COALESCE((v_prom->>'erros')::int, 0) = 0 THEN 'SUCCESS'
                  ELSE 'PARTIAL'
                END;
      RETURN NEXT;
  END LOOP;

  -- Robustez (Fase 9): staging standardized órfão (sem raw pendente).
  FOR v_sup IN
      SELECT DISTINCT x.supplier_id
      FROM (
        SELECT pp.supplier_id FROM public.produtos_padronizacao pp WHERE pp.status='standardized'
        UNION
        SELECT pv2.supplier_id FROM public.produtos_padronizacao_variantes pv2 WHERE pv2.status='standardized'
      ) x
      WHERE NOT EXISTS (
        SELECT 1 FROM public.supplier_products_raw r
        WHERE r.supplier_id = x.supplier_id AND r.status = 'pending'
      )
  LOOP
      -- pads órfãos (promove pai + variantes)
      v_prom := public.fn_promote_supplier(v_sup.supplier_id, NULL);
      v_cnt  := COALESCE((v_prom->>'pais_promovidos')::integer, 0);

      -- variantes órfãs cujo pai JÁ está promoted (fn_promote_supplier não cobre)
      FOR v_par IN
          SELECT DISTINCT pv3.parent_reference
          FROM public.produtos_padronizacao_variantes pv3
          WHERE pv3.supplier_id = v_sup.supplier_id AND pv3.status='standardized'
            AND NULLIF(pv3.parent_reference,'') IS NOT NULL
      LOOP
          v_vp := public.fn_promote_variants_of_parent(v_sup.supplier_id, v_par.parent_reference);
      END LOOP;

      batch_id           := NULL::uuid;
      products_processed := v_cnt;
      status := CASE WHEN COALESCE((v_prom->>'erros')::int,0)=0 THEN 'SUCCESS' ELSE 'PARTIAL' END;
      RETURN NEXT;
  END LOOP;

  RETURN;
END;
$function$;

COMMENT ON FUNCTION public.process_pending_batches() IS
  'Cron de ingestao (*/5). Pipeline Medallion 3 fases (standardize+promote) + robustez (Fase 9): promove staging standardized orfao, incluindo variantes cujo pai ja esta promoted.';;

-- <<< END 20260611012037_fase9_02_fix_promote_variants_checks_and_orphan_variants.sql <<<

-- >>> BEGIN 20260611012148_fn_promote_supplier_sweep_orphan_variants.sql >>>
-- fn_promote_supplier: sweep de variantes órfãs no Silver.
-- GAP: iterava somente pais 'standardized'; variantes re-padronizadas com pai
-- 'promoted' ficavam presas. Sweep promove variantes standardized cujo pai já
-- está no Gold. Retorno ganha 'variantes_orfas_promovidas'.

CREATE OR REPLACE FUNCTION public.fn_promote_supplier(
    p_supplier_id uuid,
    p_limit       integer DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_par RECORD;
  v_prom jsonb; v_vres jsonb;
  v_pais int := 0; v_novos int := 0; v_var int := 0; v_erros int := 0;
  v_orfas int := 0;
  v_t0 timestamptz := clock_timestamp();
  v_err_amostra jsonb := '[]'::jsonb;
  v_created boolean; v_vcount int;
BEGIN
  PERFORM set_config('app.write_source','pipeline', true);

  FOR v_par IN
    SELECT id, supplier_reference
    FROM public.produtos_padronizacao
    WHERE supplier_id = p_supplier_id AND status = 'standardized'
    ORDER BY supplier_reference
    LIMIT p_limit
  LOOP
    BEGIN
      v_prom := public.fn_promote_padronizacao(v_par.id);
      IF NOT COALESCE((v_prom->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'pai_falhou:%', COALESCE(v_prom->>'error','desconhecido');
      END IF;
      v_created := COALESCE((v_prom->>'created')::boolean, false);

      v_vres := public.fn_promote_variants_of_parent(p_supplier_id, v_par.supplier_reference);
      IF NOT COALESCE((v_vres->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'variantes_falharam:%', COALESCE(v_vres->>'error','desconhecido');
      END IF;
      v_vcount := COALESCE((v_vres->>'variantes_promovidas')::int, 0);

      v_pais := v_pais + 1;
      IF v_created THEN v_novos := v_novos + 1; END IF;
      v_var := v_var + v_vcount;

    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra || jsonb_build_object('ref', v_par.supplier_reference, 'erro', SQLERRM);
      END IF;
      BEGIN
        UPDATE public.supplier_products_raw r
           SET process_errors = jsonb_build_object(
                 'stage','promote','parent', v_par.supplier_reference,
                 'erro', SQLERRM, 'at', now())
         WHERE r.supplier_id = p_supplier_id
           AND r.status IN ('pending','failed')
           AND r.id IN (
             SELECT pv.raw_id FROM public.produtos_padronizacao_variantes pv
              WHERE pv.supplier_id = p_supplier_id
                AND pv.parent_reference = v_par.supplier_reference
                AND pv.raw_id IS NOT NULL
             UNION
             SELECT pp.raw_id FROM public.produtos_padronizacao pp
              WHERE pp.id = v_par.id AND pp.raw_id IS NOT NULL);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END;
  END LOOP;

  -- SWEEP 2026-06-11: variantes 'standardized' órfãs (pai já no Gold).
  FOR v_par IN
    SELECT DISTINCT pv.parent_reference AS supplier_reference
    FROM public.produtos_padronizacao_variantes pv
    JOIN public.products p
      ON p.supplier_id = pv.supplier_id
     AND p.supplier_reference = pv.parent_reference
    WHERE pv.supplier_id = p_supplier_id
      AND pv.status = 'standardized'
      AND NULLIF(pv.parent_reference, '') IS NOT NULL
  LOOP
    BEGIN
      v_vres := public.fn_promote_variants_of_parent(p_supplier_id, v_par.supplier_reference);
      IF NOT COALESCE((v_vres->>'success')::boolean, false) THEN
        RAISE EXCEPTION 'sweep_falhou:%', COALESCE(v_vres->>'error','desconhecido');
      END IF;
      v_orfas := v_orfas + COALESCE((v_vres->>'variantes_promovidas')::int, 0);
    EXCEPTION WHEN OTHERS THEN
      v_erros := v_erros + 1;
      IF jsonb_array_length(v_err_amostra) < 10 THEN
        v_err_amostra := v_err_amostra
          || jsonb_build_object('ref', v_par.supplier_reference, 'stage', 'sweep', 'erro', SQLERRM);
      END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'supplier_id', p_supplier_id,
    'pais_promovidos', v_pais, 'pais_novos', v_novos, 'variantes_promovidas', v_var,
    'variantes_orfas_promovidas', v_orfas,
    'erros', v_erros, 'amostra_erros', v_err_amostra,
    'segundos', round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,1));
END $function$;

COMMENT ON FUNCTION public.fn_promote_supplier(uuid, integer) IS
  'Orquestrador Silver->Gold por fornecedor. Promove pais standardized (atomico pai+variantes) e, desde 2026-06-11, faz sweep de variantes standardized orfas cujo pai ja esta no Gold (backfills/re-padronizacoes). NULL-safe, idempotente.';;

-- <<< END 20260611012148_fn_promote_supplier_sweep_orphan_variants.sql <<<

-- >>> BEGIN 20260611012351_fase9_03_fn_apply_print_profiles.sql >>>
-- ITEM B — Áreas de gravação por PERFIL DE CATEGORIA (Fase 9).
-- Contexto: print_area_techniques alimenta a calculadora de preço (v12). As áreas
-- existentes (13k, de abril) seguem perfis consistentes por categoria. Simulação massiva
-- (1.848 cenários reais): o perfil modal da categoria reproduz EXATAMENTE 91,8% dos
-- produtos. Gate de confiança: só aplica quando a categoria tem >=3 exemplares E o
-- fingerprint modal tem dominância >=60%. Fill-only (nunca toca produto com área).
-- Auditável: notes='profile_inference v1 ...' (rollback: DELETE WHERE notes LIKE 'profile_inference%').
CREATE OR REPLACE FUNCTION public.fn_apply_print_profiles(
    p_limit   integer DEFAULT 200,
    p_dry_run boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_applied  integer := 0;
  v_areas    integer := 0;
  v_skipped  integer := 0;
  v_prod     RECORD;
  v_template uuid;
  v_conf     numeric;
  v_n        integer;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
  END IF;

  FOR v_prod IN
    SELECT p.id, p.category_id
    FROM public.products p
    WHERE p.is_active
      AND p.category_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM public.print_area_techniques pat WHERE pat.product_id = p.id)
    ORDER BY p.created_at DESC
    LIMIT p_limit
  LOOP
    -- perfil da categoria: fingerprint modal + produto exemplar (template) + confiança
    WITH fp AS (
      SELECT pat.product_id,
             string_agg(DISTINCT pat.location_code||'|'||pat.tabela_preco_id::text, ';'
                        ORDER BY pat.location_code||'|'||pat.tabela_preco_id::text) AS f
      FROM public.print_area_techniques pat
      JOIN public.products px ON px.id = pat.product_id
      WHERE px.category_id = v_prod.category_id AND pat.is_active
      GROUP BY pat.product_id
    ),
    modal AS (
      SELECT f, count(*) AS n_modal, sum(count(*)) OVER () AS n_total
      FROM fp GROUP BY f ORDER BY count(*) DESC LIMIT 1
    )
    SELECT (SELECT fp.product_id FROM fp JOIN modal m ON fp.f = m.f LIMIT 1),
           m.n_modal::numeric / NULLIF(m.n_total,0), m.n_total::integer
      INTO v_template, v_conf, v_n
    FROM modal m;

    IF v_template IS NULL OR v_n IS NULL OR v_n < 3 OR v_conf IS NULL OR v_conf < 0.60 THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    IF NOT p_dry_run THEN
      INSERT INTO public.print_area_techniques
        (product_id, tabela_preco_id, location_code, location_name, location_order,
         max_width, max_height, is_curved, shape, technique_order, is_active, notes)
      SELECT v_prod.id, t.tabela_preco_id, t.location_code, t.location_name, t.location_order,
             t.max_width, t.max_height, t.is_curved, t.shape, t.technique_order, true,
             'profile_inference v1 (cat='||v_prod.category_id||', conf='||round(v_conf*100)||'%, n='||v_n||')'
      FROM public.print_area_techniques t
      WHERE t.product_id = v_template AND t.is_active;
      GET DIAGNOSTICS v_areas = ROW_COUNT;
    ELSE
      SELECT count(*) INTO v_areas FROM public.print_area_techniques t
      WHERE t.product_id = v_template AND t.is_active;
    END IF;

    v_applied := v_applied + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'dry_run', p_dry_run,
    'produtos_processados', v_applied + v_skipped,
    'produtos_aplicados', v_applied, 'produtos_sem_perfil_confiavel', v_skipped);
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_apply_print_profiles(integer, boolean) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_apply_print_profiles(integer, boolean) FROM anon;
REVOKE ALL ON FUNCTION public.fn_apply_print_profiles(integer, boolean) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.fn_apply_print_profiles(integer, boolean) TO postgres;
GRANT EXECUTE ON FUNCTION public.fn_apply_print_profiles(integer, boolean) TO service_role;

COMMENT ON FUNCTION public.fn_apply_print_profiles(integer, boolean) IS
  'Fase 9: aplica areas de gravacao (print_area_techniques) por PERFIL MODAL da categoria. Gate: >=3 exemplares + dominancia >=60% (paridade simulada 91,8% em 1.848 cenarios). Fill-only, auditavel via notes, dry_run default true.';;

-- <<< END 20260611012351_fase9_03_fn_apply_print_profiles.sql <<<

-- >>> BEGIN 20260611012422_p2_xbz_01_enrich_guard_simetrico_e_stock_synced_at_honesto.sql >>>
-- ════════════════════════════════════════════════════════════════
-- P2-XBZ-01 — fn_xbz_enrich_stock_batch v3
--
-- Diagnóstico (provado em produção, 2026-06-11):
-- 1. O payload real do VPS (/api/ruiz/consultaEstoque) NÃO carrega
--    QuantidadeDisponivel / QuantidadeDisponivelEstoquePrincipal /
--    ReposicaoDataPrevista / StatusConfiabilidade. O guard antigo
--    comparava campo-a-campo com IS DISTINCT FROM: campo presente no
--    raw_data e ausente no item => "diferente" para sempre => o UPDATE
--    re-escrevia ~10,6k linhas (91% da tabela XBZ) a CADA ciclo, sem
--    mudar um byte de raw_data (timestamp único 23:45:13.710604 em
--    10.636 linhas; raw_data->QuantidadeDisponivel não acompanhou
--    stock_data->Quantity).
-- 2. O carimbo stock_synced_at=now() nessas escritas vazias mascarava
--    o fato de que NENHUM escritor grava stock_data (canal inglês:
--    Quantity/QuantityMainWarehouse/...) desde <= 2026-06-08
--    (pg_stat_statements desde o reset não contém escritor algum).
--
-- Fix:
-- a) Guard SIMÉTRICO com a escrita: o patch é jsonb_strip_nulls(...)
--    dos campos que o item realmente carrega; só atualiza quando
--    NOT (raw_data @> patch) — merge que não muda nada é pulado de
--    verdade. Igualdade jsonb numérica é por valor (1.050 == 1.05).
-- b) Não carimba mais stock_synced_at: este enrich não escreve
--    quantidade. stock_synced_at volta a significar "última escrita
--    real de stock_data" (dead-man switch do worker de estoque).
-- c) updated_at fica por conta do trigger fn_spr_before_write.
--
-- Contrato preservado: assinatura, SECURITY DEFINER, search_path,
-- chaves do retorno (updated/total_input/skipped_noop/ts) e o espelho
-- dos campos de estoque em stock_data quando presentes no item.
-- ════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_xbz_enrich_stock_batch(p_supplier_id uuid, p_items jsonb)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_updated int := 0;
BEGIN
  UPDATE supplier_products_raw spr
  SET
    raw_data   = spr.raw_data || patch.p,
    stock_data = COALESCE(spr.stock_data, '{}'::jsonb) || jsonb_strip_nulls(jsonb_build_object(
      'QuantidadeDisponivel',                 item->'QuantidadeDisponivel',
      'QuantidadeDisponivelEstoquePrincipal', item->'QuantidadeDisponivelEstoquePrincipal',
      'ReposicaoDataPrevista',                item->'ReposicaoDataPrevista',
      'Disponivel',                           item->'Disponivel'
    ))
  FROM jsonb_array_elements(p_items) AS item
  CROSS JOIN LATERAL (
    SELECT jsonb_strip_nulls(jsonb_build_object(
      'QuantidadeDisponivel',                 item->'QuantidadeDisponivel',
      'QuantidadeDisponivelEstoquePrincipal', item->'QuantidadeDisponivelEstoquePrincipal',
      'ReposicaoDataPrevista',                item->'ReposicaoDataPrevista',
      'Multiplos',                            item->'Multiplos',
      'VendaMinima',                          item->'VendaMinima',
      'Disponivel',                           item->'Disponivel',
      'IpiTaxa',                              item->'IpiTaxa',
      'PrecoVenda',                           item->'PrecoVenda',
      'IdProduto',                            item->'IdProduto',
      'CodigoXbz',                            item->'CodigoXbz',
      'StatusConfiabilidade',                 item->'StatusConfiabilidade'
    )) AS p
  ) patch
  WHERE spr.supplier_id = p_supplier_id
    AND spr.supplier_sku = item->>'CodigoComposto'
    AND spr.raw_data IS NOT NULL
    AND NOT (spr.raw_data @> patch.p);

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  RETURN jsonb_build_object(
    'updated',      v_updated,
    'total_input',  jsonb_array_length(p_items),
    'skipped_noop', jsonb_array_length(p_items) - v_updated,
    'campos',       'guard simetrico raw_data @> patch; sem carimbo de stock_synced_at; tipos JSON preservados',
    'ts',           now()
  );
END;
$$;

COMMENT ON FUNCTION public.fn_xbz_enrich_stock_batch(uuid, jsonb) IS
  'Enriquece raw_data XBZ com campos do consultaEstoque (preco/disponibilidade/IPI; quantidades quando o item as trouxer). '
