-- >>> BEGIN 20260611012548_m11a_helpers_display_name_tokenize_2026.sql >>>
-- M11a — Funções base do programa Rumo ao 10/10 (V2)
-- fn_safe_bool já existia (reutilizada). Novas: display name, tokenize, parsers jsonb/text[].

CREATE OR REPLACE FUNCTION public.fn_display_product_name(p_name text)
RETURNS text
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
SET search_path TO 'public'
AS $function$
DECLARE
  s text;
  pairs text[][] := ARRAY[
    ARRAY['(\d)l\M','\1L'], ARRAY['(\d)d\M','\1D'], ARRAY['(\d)t\M','\1T'],
    ARRAY['(\d)w\M','\1W'], ARRAY['(\d)v\M','\1V'], ARRAY['(\d)gb\M','\1GB'],
    ARRAY['(\d)mah\M','\1mAh'],
    ARRAY['\ma([3-6])\M','A\1'], ARRAY['\mb([5-6])\M','B\1'],
    ARRAY['\musb\M','USB'], ARRAY['\mled\M','LED'], ARRAY['\mabs\M','ABS'],
    ARRAY['\mpvc\M','PVC'], ARRAY['\mpu\M','PU'],   ARRAY['\mpp\M','PP'],
    ARRAY['\mrpet\M','RPET'], ARRAY['\mpet\M','PET'], ARRAY['\meva\M','EVA'],
    ARRAY['\mmdf\M','MDF'], ARRAY['\mtnt\M','TNT'], ARRAY['\muv\M','UV'],
    ARRAY['\mgps\M','GPS'], ARRAY['\mnfc\M','NFC'], ARRAY['\mlcd\M','LCD'],
    ARRAY['\mrgb\M','RGB'], ARRAY['\mcob\M','COB'], ARRAY['\mtv\M','TV'],
    ARRAY['\mfm\M','FM'], ARRAY['\mgg\M','GG'], ARRAY['\mxg\M','XG']
  ];
  pr text[];
BEGIN
  IF p_name IS NULL THEN RETURN NULL; END IF;
  s := btrim(regexp_replace(
         translate(
           replace(replace(replace(replace(p_name, chr(8203),''), chr(8204),''), chr(8205),''), chr(65279),''),
           chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288),
           repeat(' ', 18)),
         '\s+', ' ', 'g'));
  IF s = '' THEN RETURN NULL; END IF;
  s := upper(left(s,1)) || lower(substr(s,2));
  FOREACH pr SLICE 1 IN ARRAY pairs LOOP
    s := regexp_replace(s, pr[1], pr[2], 'gi');
  END LOOP;
  s := upper(left(s,1)) || substr(s,2);
  RETURN s;
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_tokenize_product_tags(p_name text)
RETURNS jsonb
LANGUAGE sql IMMUTABLE PARALLEL SAFE
SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(tok ORDER BY first_ord), '[]'::jsonb)
  FROM (
    SELECT tok, MIN(ord) AS first_ord
    FROM (
      SELECT t.tok, t.ord
      FROM regexp_split_to_table(lower(COALESCE(p_name,'')), '[^a-z0-9áàâãäéèêëíìîïóòôõöúùûüçñ]+')
           WITH ORDINALITY AS t(tok, ord)
    ) x
    WHERE length(tok) >= 4
      AND tok !~ '^[0-9]+$'
      AND tok NOT IN ('para','pelo','pela','pelos','pelas','sobre','entre','cada','como','mais','menos',
                      'este','esta','isso','aquele','aquela','seus','suas','com','tipo','modelo',
                      'unidade','unidades','aprox','aproximadamente')
    GROUP BY tok
    ORDER BY MIN(ord)
    LIMIT 12
  ) y;
$function$;

CREATE OR REPLACE FUNCTION public.fn_safe_jsonb_arr(p_value text)
RETURNS jsonb
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
SET search_path TO 'public'
AS $function$
DECLARE
  j jsonb;
BEGIN
  IF p_value IS NULL OR btrim(p_value) = '' THEN RETURN NULL; END IF;
  BEGIN
    j := p_value::jsonb;
    IF jsonb_typeof(j) = 'array' THEN
      RETURN CASE WHEN jsonb_array_length(j) > 0 THEN j ELSE NULL END;
    ELSIF jsonb_typeof(j) = 'object' THEN
      SELECT NULLIF(jsonb_agg(v), '[]'::jsonb) INTO j FROM jsonb_each_text(j) e(k, v) WHERE NULLIF(btrim(v),'') IS NOT NULL;
      RETURN j;
    ELSIF jsonb_typeof(j) = 'string' THEN
      RETURN jsonb_build_array(j #>> '{}');
    END IF;
    RETURN NULL;
  EXCEPTION WHEN OTHERS THEN
    RETURN (
      SELECT NULLIF(COALESCE(jsonb_agg(btrim(e)), '[]'::jsonb), '[]'::jsonb)
      FROM unnest(string_to_array(p_value, CASE WHEN position('|' in p_value) > 0 THEN '|' ELSE ',' END)) e
      WHERE btrim(e) <> ''
    );
  END;
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_safe_text_arr(p_value text)
RETURNS text[]
LANGUAGE sql IMMUTABLE PARALLEL SAFE
SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN public.fn_safe_jsonb_arr(p_value) IS NULL THEN NULL
    ELSE (SELECT array_agg(e #>> '{}') FROM jsonb_array_elements(public.fn_safe_jsonb_arr(p_value)) e)
  END;
$function$;;

-- <<< END 20260611012548_m11a_helpers_display_name_tokenize_2026.sql <<<

-- >>> BEGIN 20260611012702_m11a2_display_name_sentence_segments_tags_min3_2026.sql >>>
-- Refinamentos pós-simulação full-corpus:
-- 1) fn_display_product_name: capitaliza primeira letra após '. ' (padrão "MARCA. descrição")
-- 2) fn_tokenize_product_tags: tokens >= 3 chars com stopwords ampliadas (kit/chá/gin/bar entram)

CREATE OR REPLACE FUNCTION public.fn_display_product_name(p_name text)
RETURNS text
LANGUAGE plpgsql IMMUTABLE PARALLEL SAFE
SET search_path TO 'public'
AS $function$
DECLARE
  s text;
  seg text;
  parts text[];
  i int;
  pairs text[][] := ARRAY[
    ARRAY['(\d)l\M','\1L'], ARRAY['(\d)d\M','\1D'], ARRAY['(\d)t\M','\1T'],
    ARRAY['(\d)w\M','\1W'], ARRAY['(\d)v\M','\1V'], ARRAY['(\d)gb\M','\1GB'],
    ARRAY['(\d)mah\M','\1mAh'],
    ARRAY['\ma([3-6])\M','A\1'], ARRAY['\mb([5-6])\M','B\1'],
    ARRAY['\musb\M','USB'], ARRAY['\mled\M','LED'], ARRAY['\mabs\M','ABS'],
    ARRAY['\mpvc\M','PVC'], ARRAY['\mpu\M','PU'],   ARRAY['\mpp\M','PP'],
    ARRAY['\mrpet\M','RPET'], ARRAY['\mpet\M','PET'], ARRAY['\meva\M','EVA'],
    ARRAY['\mmdf\M','MDF'], ARRAY['\mtnt\M','TNT'], ARRAY['\muv\M','UV'],
    ARRAY['\mgps\M','GPS'], ARRAY['\mnfc\M','NFC'], ARRAY['\mlcd\M','LCD'],
    ARRAY['\mrgb\M','RGB'], ARRAY['\mcob\M','COB'], ARRAY['\mtv\M','TV'],
    ARRAY['\mfm\M','FM'], ARRAY['\mgg\M','GG'], ARRAY['\mxg\M','XG']
  ];
  pr text[];
BEGIN
  IF p_name IS NULL THEN RETURN NULL; END IF;
  s := btrim(regexp_replace(
         translate(
           replace(replace(replace(replace(p_name, chr(8203),''), chr(8204),''), chr(8205),''), chr(65279),''),
           chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288),
           repeat(' ', 18)),
         '\s+', ' ', 'g'));
  IF s = '' THEN RETURN NULL; END IF;
  s := lower(s);
  -- sentence-case por segmento: capitaliza início e após '. '
  parts := string_to_array(s, '. ');
  FOR i IN 1..COALESCE(array_length(parts,1),0) LOOP
    seg := parts[i];
    IF seg <> '' THEN
      parts[i] := upper(left(seg,1)) || substr(seg,2);
    END IF;
  END LOOP;
  s := array_to_string(parts, '. ');
  FOREACH pr SLICE 1 IN ARRAY pairs LOOP
    s := regexp_replace(s, pr[1], pr[2], 'gi');
  END LOOP;
  s := upper(left(s,1)) || substr(s,2);
  RETURN s;
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_tokenize_product_tags(p_name text)
RETURNS jsonb
LANGUAGE sql IMMUTABLE PARALLEL SAFE
SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(tok ORDER BY first_ord), '[]'::jsonb)
  FROM (
    SELECT tok, MIN(ord) AS first_ord
    FROM (
      SELECT t.tok, t.ord
      FROM regexp_split_to_table(lower(COALESCE(p_name,'')), '[^a-z0-9áàâãäéèêëíìîïóòôõöúùûüçñ]+')
           WITH ORDINALITY AS t(tok, ord)
    ) x
    WHERE length(tok) >= 3
      AND tok !~ '^[0-9]+$'
      AND tok NOT IN ('para','pelo','pela','pelos','pelas','sobre','entre','cada','como','mais','menos',
                      'este','esta','isso','aquele','aquela','seus','suas','com','por','dos','das','uma',
                      'uns','umas','até','ate','the','and','pçs','pcs','und','unid','tipo','modelo',
                      'unidade','unidades','aprox','aproximadamente')
    GROUP BY tok
    ORDER BY MIN(ord)
    LIMIT 12
  ) y;
$function$;;

-- <<< END 20260611012702_m11a2_display_name_sentence_segments_tags_min3_2026.sql <<<

-- >>> BEGIN 20260611012811_m11b_fn_enrich_padronizacao_2026.sql >>>
-- M11b — fn_enrich_padronizacao: enriquecimento canônico da Silver.
-- Semântica: SÓ preenche o que está NULL/vazio. Nunca sobrescreve dado do fornecedor.
-- Chamada pelo fn_standardize_raw (fim) e pelos retroativos.

CREATE OR REPLACE FUNCTION public.fn_enrich_padronizacao(p_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  pp     public.produtos_padronizacao%ROWTYPE;
  v_raw  jsonb;
  v_filled jsonb := '{}'::jsonb;
  v_tags jsonb;
  v_raw_tags jsonb;
  v_mats jsonb;
  v_mat_txt text;
  v_ipi  numeric;
  v_ncm  text;
  v_desc text;
  v_prefix text;
BEGIN
  SELECT * INTO pp FROM public.produtos_padronizacao WHERE id = p_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'pad_nao_encontrado');
  END IF;

  SELECT raw_data INTO v_raw FROM public.supplier_products_raw WHERE id = pp.raw_id;

  -- 1) description ← raw (quando mapping não populou)
  IF NULLIF(TRIM(COALESCE(pp.description,'')),'') IS NULL AND v_raw IS NOT NULL THEN
    v_desc := NULLIF(TRIM(COALESCE(
      v_raw->>'descricao', v_raw->>'Descricao', v_raw->>'Description', v_raw->>'DESCRICAO')), '');
    IF v_desc IS NOT NULL THEN
      v_filled := v_filled || jsonb_build_object('description', true);
    END IF;
  END IF;

  -- 2) materials ← raw material direto OU extração por nome/descrição
  IF jsonb_array_length(COALESCE(pp.materials, '[]'::jsonb)) = 0 THEN
    v_mats := public.fn_safe_jsonb_arr(COALESCE(
      v_raw->>'material', v_raw->>'materiais', v_raw->>'Materials', v_raw->>'MATERIAL'));
    IF v_mats IS NULL THEN
      v_mat_txt := public.extract_xbz_material_primary(pp.name, pp.description);
      IF v_mat_txt IS NOT NULL THEN
        v_mats := jsonb_build_array(v_mat_txt);
      END IF;
    END IF;
    IF v_mats IS NOT NULL THEN
      v_filled := v_filled || jsonb_build_object('materials', true);
    END IF;
  END IF;

  -- 3) tags ← raw tags (objeto/array/pipe) ∪ tokenização do nome (dedup, máx 16)
  IF jsonb_array_length(COALESCE(pp.tags, '[]'::jsonb)) = 0 THEN
    v_raw_tags := public.fn_safe_jsonb_arr(v_raw->>'tags');
    SELECT COALESCE(jsonb_agg(tok ORDER BY first_ord), '[]'::jsonb) INTO v_tags
    FROM (
      SELECT tok, MIN(ord) AS first_ord FROM (
        SELECT e.value #>> '{}' AS tok, e.ordinality AS ord
        FROM jsonb_array_elements(COALESCE(v_raw_tags,'[]'::jsonb)) WITH ORDINALITY e
        UNION ALL
        SELECT e2.value #>> '{}', 100 + e2.ordinality
        FROM jsonb_array_elements(public.fn_tokenize_product_tags(pp.name)) WITH ORDINALITY e2
      ) u
      WHERE NULLIF(TRIM(tok),'') IS NOT NULL
      GROUP BY tok ORDER BY MIN(ord) LIMIT 16
    ) t;
    IF jsonb_array_length(v_tags) > 0 THEN
      v_filled := v_filled || jsonb_build_object('tags', true);
    ELSE
      v_tags := NULL;
    END IF;
  END IF;

  -- 4) ipi_rate ← ncm_codes OU moda dos irmãos de mesmo NCM (inequívoca)
  IF pp.ipi_rate IS NULL AND NULLIF(TRIM(COALESCE(pp.ncm_code,'')),'') IS NOT NULL THEN
    v_ipi := public.fn_get_ncm_ipi_rate(pp.ncm_code);
    IF v_ipi IS NULL THEN
      SELECT MIN(x.ipi_rate) INTO v_ipi
      FROM public.produtos_padronizacao x
      WHERE x.ncm_code = pp.ncm_code AND x.ipi_rate IS NOT NULL
      HAVING COUNT(DISTINCT x.ipi_rate) = 1;
    END IF;
    IF v_ipi IS NOT NULL THEN
      v_filled := v_filled || jsonb_build_object('ipi_rate', v_ipi);
    END IF;
  END IF;

  -- 5) ncm_code ← prefixo de nome (2 primeiras palavras, mesmo fornecedor, inequívoco)
  IF NULLIF(TRIM(COALESCE(pp.ncm_code,'')),'') IS NULL AND pp.name IS NOT NULL THEN
    v_prefix := (SELECT string_agg(w, ' ') FROM (
      SELECT w FROM regexp_split_to_table(UPPER(pp.name), '\s+') WITH ORDINALITY t(w, o)
      WHERE o <= 2 ORDER BY o) z);
    IF v_prefix IS NOT NULL AND LENGTH(v_prefix) >= 5 THEN
      SELECT MIN(x.ncm_code) INTO v_ncm
      FROM public.produtos_padronizacao x
      WHERE x.supplier_id = pp.supplier_id
        AND x.id <> pp.id
        AND x.ncm_code IS NOT NULL
        AND UPPER(x.name) LIKE v_prefix || '%'
      HAVING COUNT(DISTINCT x.ncm_code) = 1;
      IF v_ncm IS NOT NULL THEN
        v_filled := v_filled || jsonb_build_object('ncm_code', v_ncm);
      END IF;
    END IF;
  END IF;

  -- 6) meta_keywords ← tags finais
  -- (aplicado no UPDATE abaixo quando vazio)

  UPDATE public.produtos_padronizacao SET
    description   = CASE WHEN v_desc IS NOT NULL THEN v_desc ELSE description END,
    materials     = CASE WHEN v_mats IS NOT NULL THEN v_mats ELSE materials END,
    tags          = CASE WHEN v_tags IS NOT NULL THEN v_tags ELSE tags END,
    ipi_rate      = COALESCE(ipi_rate, v_ipi),
    ncm_code      = COALESCE(ncm_code, v_ncm),
    meta_keywords = CASE
                      WHEN COALESCE(array_length(meta_keywords,1),0) = 0 THEN
                        COALESCE(
                          (SELECT array_agg(e #>> '{}') FROM jsonb_array_elements(
                             COALESCE(v_tags, NULLIF(tags,'[]'::jsonb))) e),
                          meta_keywords)
                      ELSE meta_keywords
                    END,
    updated_at    = now()
  WHERE id = p_id
    AND (v_desc IS NOT NULL OR v_mats IS NOT NULL OR v_tags IS NOT NULL
         OR v_ipi IS NOT NULL OR v_ncm IS NOT NULL
         OR COALESCE(array_length(meta_keywords,1),0) = 0);

  RETURN jsonb_build_object('success', true, 'pad_id', p_id, 'filled', v_filled);
END;
$function$;;

-- <<< END 20260611012811_m11b_fn_enrich_padronizacao_2026.sql <<<

