-- >>> BEGIN 20260611012938_m11c_fn_standardize_raw_v3_full_columns_enrich_2026.sql >>>
-- M11c — fn_standardize_raw v3:
-- (a) Persiste TODAS as colunas de v_cols (antes ~20 eram calculadas e descartadas:
--     tags, materials, meta_keywords, engraving_type, images, box_*, flags, etc.)
-- (b) Remove bloco IPI morto (lookup no branch ELSE com v_ncm NULL — nunca executava)
-- (c) Chama fn_enrich_padronizacao ao final — ingestão converge, sem decay retroativo
-- Mantém: nome MAIÚSCULO na Silver (fn_normalize_product_name), brand permanente,
--         clamp de estoque, fn_safe_num/int, semântica COALESCE(novo, antigo).

CREATE OR REPLACE FUNCTION public.fn_standardize_raw(p_raw_id uuid, p_override_reference text DEFAULT NULL::text)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r          public.supplier_products_raw%ROWTYPE;
  m          RECORD;
  v_val      text; v_tx text; v_path text;
  v_assigns  jsonb := '{}'::jsonb;
  v_errs     jsonb := '[]'::jsonb;
  v_ncm text; v_ncm_raw text;
  v_pad_id uuid; v_ref text;
  v_status public.produtos_padronizacao_status;
  v_cols text[] := ARRAY[
    'name','description','short_description','cost_price','suggested_price','stock_quantity',
    'primary_image_url','images','ncm_code','weight_g','height_cm','width_cm','length_cm',
    'dimensions_display','box_length_cm','box_width_cm','box_height_cm','box_weight_kg',
    'box_volume_cm3','box_quantity','box_inner_quantity','brand','packing_type','repacking_type',
    'capacities','capacity_ml','min_quantity','ipi_rate','engraving_type','is_active',
    'product_type','origin_country','combined_sizes','box_image',
    'is_textil','is_stockout','is_online_exclusive','is_new','has_colors','has_sizes',
    'allows_personalization','tags','materials','meta_keywords'
  ];
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'raw_nao_encontrado'); END IF;
  v_ref := COALESCE(NULLIF(TRIM(p_override_reference),''), r.supplier_reference);

  FOR m IN
    SELECT source_field, source_path, target_field, transform_type, transform_config, source_unit, target_unit
    FROM public.supplier_field_mappings
    WHERE supplier_id=r.supplier_id AND target_table='products' AND is_active=TRUE AND target_field=ANY(v_cols)
    ORDER BY priority NULLS LAST
  LOOP
    BEGIN
      IF m.source_path IS NOT NULL AND m.source_path <> '' THEN
        v_path := regexp_replace(m.source_path, E'^\\$\\.?', '');
        v_val  := r.raw_data #>> string_to_array(v_path, '.');
      ELSE
        v_val := r.raw_data ->> m.source_field;
      END IF;

      IF v_val IS NULL THEN CONTINUE; END IF;

      v_tx := public.fn_apply_transform(
        v_val, m.transform_type, m.transform_config,
        m.source_unit, m.target_unit,
        r.supplier_id
      );

      v_assigns := v_assigns || jsonb_build_object(m.target_field, v_tx);
    EXCEPTION WHEN OTHERS THEN
      v_errs := v_errs || jsonb_build_object('field', m.target_field, 'error', SQLERRM);
    END;
  END LOOP;

  -- NCM: normaliza; inválido (placeholder/formatos quebrados) é removido
  v_ncm_raw := COALESCE(v_assigns->>'ncm_code', r.raw_data->>'Ncm', r.raw_data->>'ncm');
  IF v_ncm_raw IS NOT NULL THEN
    v_ncm := public.fn_normalize_ncm(v_ncm_raw);
    IF v_ncm IS NOT NULL THEN
      v_assigns := v_assigns || jsonb_build_object('ncm_code', v_ncm);
    ELSE
      v_assigns := v_assigns - 'ncm_code';
    END IF;
  END IF;

  SELECT id INTO v_pad_id FROM public.produtos_padronizacao
  WHERE supplier_id = r.supplier_id AND supplier_reference = v_ref;

  IF v_pad_id IS NULL THEN
    INSERT INTO public.produtos_padronizacao
      (supplier_id, supplier_reference, raw_id, status)
    VALUES (r.supplier_id, v_ref, r.id, 'pending')
    RETURNING id INTO v_pad_id;
  END IF;

  IF jsonb_typeof(v_assigns) = 'object' AND v_assigns <> '{}'::jsonb THEN
    v_status := 'standardized';
  ELSE
    v_status := 'pending';
  END IF;

  -- BRAND PERMANENTE: sempre nome do supplier na Silver
  v_assigns := v_assigns || jsonb_build_object(
    'brand', public.fn_brand_from_supplier(r.supplier_id)
  );

  -- Clamp: stock negativo → 0
  IF (v_assigns->>'stock_quantity') IS NOT NULL
    AND (v_assigns->>'stock_quantity')::numeric < 0 THEN
    v_assigns := v_assigns || jsonb_build_object('stock_quantity', 0);
  END IF;

  UPDATE public.produtos_padronizacao
  SET
    -- nome entra sempre em MAIÚSCULO na Silver (display-case acontece na promoção)
    name               = COALESCE(public.fn_normalize_product_name(v_assigns->>'name'), name),
    description        = COALESCE((v_assigns->>'description')::text,                                   description),
    short_description  = COALESCE((v_assigns->>'short_description')::text,                             short_description),
    cost_price         = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'cost_price'),      0),        cost_price),
    suggested_price    = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'suggested_price'), 0),        suggested_price),
    stock_quantity     = COALESCE(public.fn_safe_int(v_assigns->>'stock_quantity'),                     stock_quantity),
    primary_image_url  = COALESCE((v_assigns->>'primary_image_url')::text,                             primary_image_url),
    images             = COALESCE(public.fn_safe_jsonb_arr(v_assigns->>'images'),                       images),
    ncm_code           = COALESCE((v_assigns->>'ncm_code')::text,                                      ncm_code),
    weight_g           = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'weight_g'),  0),              weight_g),
    height_cm          = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'height_cm'), 0),              height_cm),
    width_cm           = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'width_cm'),  0),              width_cm),
    length_cm          = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'length_cm'), 0),              length_cm),
    dimensions_display = COALESCE((v_assigns->>'dimensions_display')::text,                            dimensions_display),
    box_length_cm      = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_length_cm'), 0),          box_length_cm),
    box_width_cm       = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_width_cm'),  0),          box_width_cm),
    box_height_cm      = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_height_cm'), 0),          box_height_cm),
    box_weight_kg      = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_weight_kg'), 0),          box_weight_kg),
    box_volume_cm3     = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_volume_cm3'),0),          box_volume_cm3),
    box_quantity       = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'box_quantity'), 0),           box_quantity),
    box_inner_quantity = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'box_inner_quantity'), 0),     box_inner_quantity),
    brand              = COALESCE((v_assigns->>'brand')::text,                                          brand),
    packing_type       = COALESCE((v_assigns->>'packing_type')::text,                                   packing_type),
    repacking_type     = COALESCE((v_assigns->>'repacking_type')::text,                                 repacking_type),
    capacities         = COALESCE((v_assigns->>'capacities')::text,                                     capacities),
    capacity_ml        = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'capacity_ml'), 0),            capacity_ml),
    min_quantity       = COALESCE(public.fn_safe_int(v_assigns->>'min_quantity'),                       min_quantity),
    ipi_rate           = COALESCE(public.fn_safe_num(v_assigns->>'ipi_rate'),                           ipi_rate),
    engraving_type     = COALESCE((v_assigns->>'engraving_type')::text,                                 engraving_type),
    is_active          = COALESCE(public.fn_safe_bool(v_assigns->>'is_active'),                         is_active),
    product_type       = COALESCE((v_assigns->>'product_type')::text,                                   product_type),
    origin_country     = COALESCE((v_assigns->>'origin_country')::text,                                 origin_country),
    combined_sizes     = COALESCE((v_assigns->>'combined_sizes')::text,                                 combined_sizes),
    box_image          = COALESCE((v_assigns->>'box_image')::text,                                      box_image),
    is_textil              = COALESCE(public.fn_safe_bool(v_assigns->>'is_textil'),              is_textil),
    is_stockout            = COALESCE(public.fn_safe_bool(v_assigns->>'is_stockout'),            is_stockout),
    is_online_exclusive    = COALESCE(public.fn_safe_bool(v_assigns->>'is_online_exclusive'),    is_online_exclusive),
    is_new                 = COALESCE(public.fn_safe_bool(v_assigns->>'is_new'),                 is_new),
    has_colors             = COALESCE(public.fn_safe_bool(v_assigns->>'has_colors'),             has_colors),
    has_sizes              = COALESCE(public.fn_safe_bool(v_assigns->>'has_sizes'),              has_sizes),
    allows_personalization = COALESCE(public.fn_safe_bool(v_assigns->>'allows_personalization'), allows_personalization),
    tags               = COALESCE(public.fn_safe_jsonb_arr(v_assigns->>'tags'),                         tags),
    materials          = COALESCE(public.fn_safe_jsonb_arr(v_assigns->>'materials'),                    materials),
    meta_keywords      = COALESCE(public.fn_safe_text_arr(v_assigns->>'meta_keywords'),                 meta_keywords),
    raw_id             = r.id,
    status             = v_status,
    standardized_at    = CASE WHEN v_status = 'standardized' THEN now() ELSE standardized_at END,
    validation_errors  = CASE WHEN jsonb_array_length(v_errs) > 0 THEN v_errs ELSE NULL END,
    updated_at         = now()
  WHERE id = v_pad_id;

  -- Enriquecimento canônico (só preenche NULLs): ipi/ncm/materials/tags/meta/description
  PERFORM public.fn_enrich_padronizacao(v_pad_id);

  RETURN jsonb_build_object(
    'success', true, 'pad_id', v_pad_id,
    'status', v_status, 'fields_set', v_assigns,
    'errors', v_errs
  );
END;
$function$;;

-- <<< END 20260611012938_m11c_fn_standardize_raw_v3_full_columns_enrich_2026.sql <<<

-- >>> BEGIN 20260611013114_m12_fn_promote_padronizacao_display_name_cat_fallback_2026.sql >>>
-- M12 — fn_promote_padronizacao v2:
-- (a) Gold name recebe display-case (fn_display_product_name) — Silver permanece MAIÚSCULA
-- (b) Categoria: De→Para (precedência) → classify alta-confiança (fill-only, só quando Gold sem categoria)
-- Tudo o mais idêntico à versão anterior (locked_fields, NULLIF guards, CF image preservada).

CREATE OR REPLACE FUNCTION public.fn_promote_padronizacao(p_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  s        public.produtos_padronizacao%ROWTYPE;
  v_pid    uuid;
  v_org    uuid;
  v_locked text[];
  v_is_new boolean := false;
  v_cat_id   uuid    := NULL;
  v_cat_src  text;
  v_cat_l1   text;
  v_existing_cat uuid := NULL;
  v_min_qty  integer := NULL;
  v_display_name text;
BEGIN
  SELECT * INTO s FROM public.produtos_padronizacao WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'padronizacao_nao_encontrada', 'id', p_id);
  END IF;
  IF s.status <> 'standardized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'status_invalido', 'status', s.status);
  END IF;

  PERFORM set_config('app.write_source',     'pipeline', true);
  PERFORM set_config('app.bulk_import_mode', 'true',     true);

  v_display_name := public.fn_display_product_name(s.name);

  SELECT id, locked_fields, category_id INTO v_pid, v_locked, v_existing_cat
  FROM public.products
  WHERE supplier_id = s.supplier_id AND supplier_reference = s.supplier_reference;

  IF v_pid IS NULL THEN
    v_is_new := true;
    SELECT organization_id INTO v_org FROM public.suppliers WHERE id = s.supplier_id;
    INSERT INTO public.products (organization_id, supplier_id, supplier_reference, sku, name, active, is_active, product_type)
    VALUES (v_org, s.supplier_id, s.supplier_reference,
            COALESCE(s.supplier_reference, s.name),
            COALESCE(v_display_name, s.name, 'Produto ' || s.supplier_reference),
            true, true, 'product')  -- REGRA: produto SEMPRE nasce ativo; desativação requer aprovação
    RETURNING id, locked_fields INTO v_pid, v_locked;
  END IF;

  v_locked := COALESCE(v_locked, '{}');

  -- Categoria nível 1: De→Para
  IF s.raw_id IS NOT NULL AND NOT ('category_id' = ANY(v_locked)) THEN
    BEGIN
      SELECT sfm.source_field INTO v_cat_src
      FROM public.supplier_field_mappings sfm
      WHERE sfm.supplier_id = s.supplier_id AND sfm.target_field = 'categories'
      LIMIT 1;
      IF v_cat_src IS NOT NULL THEN
        SELECT split_part(COALESCE(spr.raw_data ->> v_cat_src, ''), '|', 1)
        INTO v_cat_l1
        FROM public.supplier_products_raw spr WHERE spr.id = s.raw_id;
        IF v_cat_l1 IS NOT NULL AND TRIM(v_cat_l1) <> '' THEN
          SELECT scm.category_id INTO v_cat_id
          FROM public.supplier_categories sc
          JOIN public.supplier_category_mappings scm ON scm.supplier_category_id = sc.id
          WHERE sc.supplier_id = s.supplier_id AND TRIM(sc.supplier_code) = TRIM(v_cat_l1)
          LIMIT 1;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  -- Categoria nível 2: classify alta-confiança (fill-only — só quando Gold ainda sem categoria)
  IF v_cat_id IS NULL AND v_existing_cat IS NULL AND NOT ('category_id' = ANY(v_locked)) THEN
    BEGIN
      SELECT c.category_id INTO v_cat_id
      FROM public.classify_xbz_category(s.name) c
      WHERE c.confidence = 'alta'
      LIMIT 1;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  -- min_quantity: GREATEST(supplier, categoria)
  IF s.min_quantity IS NOT NULL THEN
    SELECT GREATEST(
        s.min_quantity,
        COALESCE(c.min_order_quantity, 1)
    )
    INTO v_min_qty
    FROM public.categories c
    WHERE c.id = COALESCE(v_cat_id,
        (SELECT category_id FROM public.products WHERE id = v_pid));
    v_min_qty := COALESCE(v_min_qty, s.min_quantity);
  END IF;

  -- ── UPDATE Gold ─────────────────────────────────────────────────────
  UPDATE public.products p SET
    sku                = COALESCE(p.sku, s.supplier_reference, s.name),
    name               = CASE WHEN 'name'               = ANY(v_locked) THEN p.name               ELSE COALESCE(v_display_name, s.name, p.name)           END,
    description        = CASE WHEN 'description'        = ANY(v_locked) THEN p.description        ELSE COALESCE(s.description,        p.description)        END,
    short_description  = CASE WHEN 'short_description'  = ANY(v_locked) THEN p.short_description  ELSE COALESCE(s.short_description,  p.short_description)  END,
    cost_price         = CASE WHEN 'cost_price'         = ANY(v_locked) THEN p.cost_price         ELSE COALESCE(NULLIF(s.cost_price,      0), p.cost_price)      END,
    suggested_price    = CASE WHEN 'suggested_price'    = ANY(v_locked) THEN p.suggested_price    ELSE COALESCE(NULLIF(s.suggested_price, 0), p.suggested_price) END,
    stock_quantity     = CASE WHEN 'stock_quantity'     = ANY(v_locked) THEN p.stock_quantity     ELSE COALESCE(s.stock_quantity,     p.stock_quantity)     END,
    min_quantity       = CASE WHEN 'min_quantity'       = ANY(v_locked) THEN p.min_quantity
                              WHEN v_min_qty IS NOT NULL                THEN v_min_qty
                              ELSE COALESCE(s.min_quantity, p.min_quantity)              END,
    primary_image_url  = CASE
      WHEN 'primary_image_url' = ANY(v_locked)              THEN p.primary_image_url
      WHEN p.primary_image_url LIKE '%imagedelivery%'       THEN p.primary_image_url
      ELSE COALESCE(s.primary_image_url, p.primary_image_url)
    END,
    images             = CASE WHEN 'images'             = ANY(v_locked) THEN p.images             ELSE COALESCE(s.images,             p.images)             END,
    ncm_code           = CASE WHEN 'ncm_code'           = ANY(v_locked) THEN p.ncm_code           ELSE COALESCE(NULLIF(s.ncm_code,'00000000'), p.ncm_code)           END,
    weight_g           = CASE WHEN 'weight_g'           = ANY(v_locked) THEN p.weight_g           ELSE COALESCE(NULLIF(s.weight_g,   0), p.weight_g)   END,
    height_cm          = CASE WHEN 'height_cm'          = ANY(v_locked) THEN p.height_cm          ELSE COALESCE(NULLIF(s.height_cm,  0), p.height_cm)  END,
    width_cm           = CASE WHEN 'width_cm'           = ANY(v_locked) THEN p.width_cm           ELSE COALESCE(NULLIF(s.width_cm,   0), p.width_cm)   END,
    length_cm          = CASE WHEN 'length_cm'          = ANY(v_locked) THEN p.length_cm          ELSE COALESCE(NULLIF(s.length_cm,  0), p.length_cm)  END,
    dimensions_display = CASE WHEN 'dimensions_display' = ANY(v_locked) THEN p.dimensions_display ELSE COALESCE(s.dimensions_display, p.dimensions_display) END,
    box_length_cm      = CASE WHEN 'box_length_cm'      = ANY(v_locked) THEN p.box_length_cm      ELSE COALESCE(s.box_length_cm,      p.box_length_cm)      END,
    box_width_cm       = CASE WHEN 'box_width_cm'       = ANY(v_locked) THEN p.box_width_cm       ELSE COALESCE(s.box_width_cm,       p.box_width_cm)       END,
    box_height_cm      = CASE WHEN 'box_height_cm'      = ANY(v_locked) THEN p.box_height_cm      ELSE COALESCE(s.box_height_cm,      p.box_height_cm)      END,
    box_weight_kg      = CASE WHEN 'box_weight_kg'      = ANY(v_locked) THEN p.box_weight_kg      ELSE COALESCE(s.box_weight_kg,      p.box_weight_kg)      END,
    box_volume_cm3     = CASE WHEN 'box_volume_cm3'     = ANY(v_locked) THEN p.box_volume_cm3     ELSE COALESCE(s.box_volume_cm3,     p.box_volume_cm3)     END,
    box_quantity       = CASE WHEN 'box_quantity'       = ANY(v_locked) THEN p.box_quantity       ELSE COALESCE(s.box_quantity,       p.box_quantity)       END,
    box_inner_quantity = CASE WHEN 'box_inner_quantity' = ANY(v_locked) THEN p.box_inner_quantity ELSE COALESCE(s.box_inner_quantity, p.box_inner_quantity) END,
    brand              = CASE WHEN 'brand'              = ANY(v_locked) THEN p.brand              ELSE COALESCE(s.brand,              p.brand)              END,
    packing_type       = CASE WHEN 'packing_type'       = ANY(v_locked) THEN p.packing_type       ELSE COALESCE(s.packing_type,       p.packing_type)       END,
    repacking_type     = CASE WHEN 'repacking_type'     = ANY(v_locked) THEN p.repacking_type     ELSE COALESCE(s.repacking_type,     p.repacking_type)     END,
    capacities         = CASE WHEN 'capacities'         = ANY(v_locked) THEN p.capacities         ELSE COALESCE(s.capacities,         p.capacities)         END,
    capacity_ml        = CASE WHEN 'capacity_ml'        = ANY(v_locked) THEN p.capacity_ml        ELSE COALESCE(NULLIF(s.capacity_ml, 0), p.capacity_ml) END,
    ipi_rate           = CASE WHEN 'ipi_rate'           = ANY(v_locked) THEN p.ipi_rate           ELSE COALESCE(s.ipi_rate,           p.ipi_rate)           END,
    engraving_type     = CASE WHEN 'engraving_type'     = ANY(v_locked) THEN p.engraving_type     ELSE COALESCE(s.engraving_type,     p.engraving_type)     END,
    colors             = CASE WHEN 'colors'             = ANY(v_locked) THEN p.colors             ELSE COALESCE(s.colors,             p.colors)             END,
    combined_sizes         = CASE WHEN 'combined_sizes'         = ANY(v_locked) THEN p.combined_sizes         ELSE COALESCE(s.combined_sizes,         p.combined_sizes)         END,
    box_image              = CASE WHEN 'box_image'              = ANY(v_locked) THEN p.box_image              ELSE COALESCE(s.box_image,              p.box_image)              END,
    is_textil              = CASE WHEN 'is_textil'              = ANY(v_locked) THEN p.is_textil              ELSE COALESCE(s.is_textil,              p.is_textil)              END,
    is_stockout            = CASE WHEN 'is_stockout'            = ANY(v_locked) THEN p.is_stockout            ELSE COALESCE(s.is_stockout,            p.is_stockout)            END,
    is_online_exclusive    = CASE WHEN 'is_online_exclusive'    = ANY(v_locked) THEN p.is_online_exclusive    ELSE COALESCE(s.is_online_exclusive,    p.is_online_exclusive)    END,
    is_new                 = CASE WHEN 'is_new'                 = ANY(v_locked) THEN p.is_new                 ELSE COALESCE(s.is_new,                 p.is_new)                 END,
    has_colors             = CASE WHEN 'has_colors'             = ANY(v_locked) THEN p.has_colors             ELSE COALESCE(s.has_colors,             p.has_colors)             END,
    has_sizes              = CASE WHEN 'has_sizes'              = ANY(v_locked) THEN p.has_sizes              ELSE COALESCE(s.has_sizes,              p.has_sizes)              END,
    allows_personalization = CASE WHEN 'allows_personalization' = ANY(v_locked) THEN p.allows_personalization ELSE COALESCE(s.allows_personalization, p.allows_personalization) END,
    tags                   = CASE WHEN 'tags'                   = ANY(v_locked) THEN p.tags                   ELSE COALESCE(NULLIF(s.tags,'[]'::jsonb),      p.tags)      END,
    materials              = CASE WHEN 'materials'              = ANY(v_locked) THEN p.materials              ELSE COALESCE(NULLIF(s.materials,'[]'::jsonb), p.materials) END,
    meta_keywords          = CASE WHEN 'meta_keywords'          = ANY(v_locked) THEN p.meta_keywords          ELSE COALESCE(s.meta_keywords,          p.meta_keywords)          END,
    category_id            = CASE
      WHEN 'category_id' = ANY(v_locked) THEN p.category_id
      WHEN v_cat_id IS NOT NULL           THEN v_cat_id
      ELSE                                     p.category_id
    END,
    origin_country        = CASE WHEN 'origin_country'        = ANY(v_locked) THEN p.origin_country        ELSE COALESCE(s.origin_country,        p.origin_country)        END,
    supplier_type         = CASE WHEN 'supplier_type'         = ANY(v_locked) THEN p.supplier_type         ELSE COALESCE(s.supplier_type,         p.supplier_type)         END,
    supplier_type_code    = CASE WHEN 'supplier_type_code'    = ANY(v_locked) THEN p.supplier_type_code    ELSE COALESCE(s.supplier_type_code,    p.supplier_type_code)    END,
    supplier_subtype      = CASE WHEN 'supplier_subtype'      = ANY(v_locked) THEN p.supplier_subtype      ELSE COALESCE(s.supplier_subtype,      p.supplier_subtype)      END,
    supplier_subtype_code = CASE WHEN 'supplier_subtype_code' = ANY(v_locked) THEN p.supplier_subtype_code ELSE COALESCE(s.supplier_subtype_code, p.supplier_subtype_code) END,
    is_seasonal           = CASE WHEN 'is_seasonal'           = ANY(v_locked) THEN p.is_seasonal           ELSE COALESCE(s.is_seasonal,           p.is_seasonal)           END,
    pvc_free              = CASE WHEN 'pvc_free'              = ANY(v_locked) THEN p.pvc_free              ELSE COALESCE(s.pvc_free,              p.pvc_free)              END,
    last_sync_at          = now(),
    last_sync_supplier_id = s.supplier_id,
    supplier_updated_at   = now()
  WHERE p.id = v_pid;

  UPDATE public.produtos_padronizacao
     SET status='promoted', promoted_at=now(), product_id=v_pid
   WHERE id = p_id;

  IF s.raw_id IS NOT NULL THEN
    UPDATE public.supplier_products_raw
       SET status='processed', processed_at=now(), product_id=v_pid, process_errors=NULL
     WHERE id = s.raw_id;
    PERFORM public.fn_sync_single_product_dimensions(
              v_pid, (SELECT raw_data FROM public.supplier_products_raw WHERE id = s.raw_id));
  END IF;

  RETURN jsonb_build_object(
    'success',          true,
    'product_id',       v_pid,
    'created',          v_is_new,
    'locked_preserved', v_locked,
    'min_quantity_final', v_min_qty,
    'display_name',     v_display_name,
    'category_depara',  CASE WHEN v_cat_id IS NOT NULL
                             THEN jsonb_build_object('category_id', v_cat_id, 'l1_raw', v_cat_l1)
                             ELSE 'null'::jsonb END
  );
END;
$function$;;

-- <<< END 20260611013114_m12_fn_promote_padronizacao_display_name_cat_fallback_2026.sql <<<

-- >>> BEGIN 20260611013302_m12b_trigger_limpar_nome_gold_display_case_2026.sql >>>
-- M12b — trigger_limpar_nome_produto v3:
-- Gold é camada de exibição: nome SPOT recebe display-case (sentence-case com
-- preservação de siglas/unidades) em vez de UPPERCASE completo.
-- Silver permanece MAIÚSCULA (contrato de matching/dedup do pipeline).

CREATE OR REPLACE FUNCTION public.trigger_limpar_nome_produto()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
    v_spot_supplier_id UUID := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
    v_result text;
BEGIN
    IF NEW.supplier_id = v_spot_supplier_id THEN
        -- higiene (invisíveis/espaços) + display-case com preservação de siglas
        v_result := public.fn_display_product_name(NEW.name);
        IF v_result IS NOT NULL AND v_result <> '' THEN
            NEW.name := v_result;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;;

-- <<< END 20260611013302_m12b_trigger_limpar_nome_gold_display_case_2026.sql <<<

-- >>> BEGIN 20260611013908_pipeline_hardening_p1_standardize_raw_rejected_clamps.sql >>>
-- HARDENING P1 — fn_standardize_raw: fallback name + clamp money + rejected explícito
-- (achados #4/#5 da simulação massiva 2026-06-11)
CREATE OR REPLACE FUNCTION public.fn_standardize_raw(p_raw_id uuid, p_override_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  r          public.supplier_products_raw%ROWTYPE;
  m          RECORD;
  v_val      text; v_tx text; v_path text;
  v_assigns  jsonb := '{}'::jsonb;
  v_errs     jsonb := '[]'::jsonb;
  v_ncm text; v_ncm_raw text;
  v_pad_id uuid; v_ref text;
  v_status public.produtos_padronizacao_status;
  v_final_name text;
  v_money numeric;
  v_cols text[] := ARRAY[
    'name','description','short_description','cost_price','suggested_price','stock_quantity',
    'primary_image_url','images','ncm_code','weight_g','height_cm','width_cm','length_cm',
    'dimensions_display','box_length_cm','box_width_cm','box_height_cm','box_weight_kg',
    'box_volume_cm3','box_quantity','box_inner_quantity','brand','packing_type','repacking_type',
    'capacities','capacity_ml','min_quantity','ipi_rate','engraving_type','is_active',
    'product_type','origin_country','combined_sizes','box_image',
    'is_textil','is_stockout','is_online_exclusive','is_new','has_colors','has_sizes',
    'allows_personalization','tags','materials','meta_keywords'
  ];
BEGIN
  SELECT * INTO r FROM public.supplier_products_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'raw_nao_encontrado'); END IF;
  v_ref := COALESCE(NULLIF(TRIM(p_override_reference),''), r.supplier_reference);

  FOR m IN
    SELECT source_field, source_path, target_field, transform_type, transform_config, source_unit, target_unit
    FROM public.supplier_field_mappings
    WHERE supplier_id=r.supplier_id AND target_table='products' AND is_active=TRUE AND target_field=ANY(v_cols)
    ORDER BY priority NULLS LAST
  LOOP
    BEGIN
      IF m.source_path IS NOT NULL AND m.source_path <> '' THEN
        v_path := regexp_replace(m.source_path, E'^\\$\\.?', '');
        v_val  := r.raw_data #>> string_to_array(v_path, '.');
      ELSE
        v_val := r.raw_data ->> m.source_field;
      END IF;

      IF v_val IS NULL THEN CONTINUE; END IF;

      v_tx := public.fn_apply_transform(
        v_val, m.transform_type, m.transform_config,
        m.source_unit, m.target_unit,
        r.supplier_id
      );

      v_assigns := v_assigns || jsonb_build_object(m.target_field, v_tx);
    EXCEPTION WHEN OTHERS THEN
      v_errs := v_errs || jsonb_build_object('field', m.target_field, 'error', SQLERRM);
    END;
  END LOOP;

  -- FALLBACK genérico de name (2026-06-11)
  IF NULLIF(TRIM(v_assigns->>'name'),'') IS NULL THEN
    v_val := COALESCE(
      NULLIF(TRIM(r.raw_data->>'nome'),''),
      NULLIF(TRIM(r.raw_data->>'Nome'),''),
      NULLIF(TRIM(r.raw_data->>'name'),''),
      NULLIF(TRIM(r.raw_data->>'Name'),''),
      NULLIF(TRIM(r.raw_data->>'titulo'),''),
      NULLIF(TRIM(r.raw_data->>'Titulo'),''));
    IF v_val IS NOT NULL THEN
      v_assigns := v_assigns || jsonb_build_object('name', v_val);
    END IF;
  END IF;

  -- CLAMP money (2026-06-11): fora de (0, 99999999.99] não entra na Silver
  FOREACH v_val IN ARRAY ARRAY['cost_price','suggested_price'] LOOP
    IF v_assigns ? v_val THEN
      v_money := public.fn_safe_num(v_assigns->>v_val);
      IF v_money IS NOT NULL AND (v_money < 0 OR v_money > 99999999.99) THEN
        v_assigns := v_assigns - v_val;
        v_errs := v_errs || jsonb_build_object('field', v_val, 'error',
          'valor_fora_do_dominio: '||v_money::text);
      END IF;
    END IF;
  END LOOP;

  -- NCM: normaliza; inválido é removido
  v_ncm_raw := COALESCE(v_assigns->>'ncm_code', r.raw_data->>'Ncm', r.raw_data->>'ncm');
  IF v_ncm_raw IS NOT NULL THEN
    v_ncm := public.fn_normalize_ncm(v_ncm_raw);
    IF v_ncm IS NOT NULL THEN
      v_assigns := v_assigns || jsonb_build_object('ncm_code', v_ncm);
    ELSE
      v_assigns := v_assigns - 'ncm_code';
    END IF;
  END IF;

  SELECT id INTO v_pad_id FROM public.produtos_padronizacao
  WHERE supplier_id = r.supplier_id AND supplier_reference = v_ref;

  IF v_pad_id IS NULL THEN
    INSERT INTO public.produtos_padronizacao
      (supplier_id, supplier_reference, raw_id, status)
    VALUES (r.supplier_id, v_ref, r.id, 'pending')
    RETURNING id INTO v_pad_id;
  END IF;

  -- BRAND PERMANENTE
  v_assigns := v_assigns || jsonb_build_object(
    'brand', public.fn_brand_from_supplier(r.supplier_id)
  );

  -- Clamp: stock negativo → 0
  IF (v_assigns->>'stock_quantity') IS NOT NULL
    AND public.fn_safe_num(v_assigns->>'stock_quantity') IS NOT NULL
    AND public.fn_safe_num(v_assigns->>'stock_quantity') < 0 THEN
    v_assigns := v_assigns || jsonb_build_object('stock_quantity', 0);
  END IF;

  UPDATE public.produtos_padronizacao
  SET
    name               = COALESCE(public.fn_normalize_product_name(v_assigns->>'name'), name),
    description        = COALESCE((v_assigns->>'description')::text,                                   description),
    short_description  = COALESCE((v_assigns->>'short_description')::text,                             short_description),
    cost_price         = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'cost_price'),      0),        cost_price),
    suggested_price    = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'suggested_price'), 0),        suggested_price),
    stock_quantity     = COALESCE(public.fn_safe_int(v_assigns->>'stock_quantity'),                     stock_quantity),
    primary_image_url  = COALESCE((v_assigns->>'primary_image_url')::text,                             primary_image_url),
    images             = COALESCE(public.fn_safe_jsonb_arr(v_assigns->>'images'),                       images),
    ncm_code           = COALESCE((v_assigns->>'ncm_code')::text,                                      ncm_code),
    weight_g           = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'weight_g'),  0),              weight_g),
    height_cm          = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'height_cm'), 0),              height_cm),
    width_cm           = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'width_cm'),  0),              width_cm),
    length_cm          = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'length_cm'), 0),              length_cm),
    dimensions_display = COALESCE((v_assigns->>'dimensions_display')::text,                            dimensions_display),
    box_length_cm      = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_length_cm'), 0),          box_length_cm),
    box_width_cm       = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_width_cm'),  0),          box_width_cm),
    box_height_cm      = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_height_cm'), 0),          box_height_cm),
    box_weight_kg      = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_weight_kg'), 0),          box_weight_kg),
    box_volume_cm3     = COALESCE(NULLIF(public.fn_safe_num(v_assigns->>'box_volume_cm3'),0),          box_volume_cm3),
    box_quantity       = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'box_quantity'), 0),           box_quantity),
    box_inner_quantity = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'box_inner_quantity'), 0),     box_inner_quantity),
    brand              = COALESCE((v_assigns->>'brand')::text,                                          brand),
    packing_type       = COALESCE((v_assigns->>'packing_type')::text,                                   packing_type),
    repacking_type     = COALESCE((v_assigns->>'repacking_type')::text,                                 repacking_type),
    capacities         = COALESCE((v_assigns->>'capacities')::text,                                     capacities),
    capacity_ml        = COALESCE(NULLIF(public.fn_safe_int(v_assigns->>'capacity_ml'), 0),            capacity_ml),
    min_quantity       = COALESCE(public.fn_safe_int(v_assigns->>'min_quantity'),                       min_quantity),
    ipi_rate           = COALESCE(public.fn_safe_num(v_assigns->>'ipi_rate'),                           ipi_rate),
    engraving_type     = COALESCE((v_assigns->>'engraving_type')::text,                                 engraving_type),
    is_active          = COALESCE(public.fn_safe_bool(v_assigns->>'is_active'),                         is_active),
    product_type       = COALESCE((v_assigns->>'product_type')::text,                                   product_type),
    origin_country     = COALESCE((v_assigns->>'origin_country')::text,                                 origin_country),
    combined_sizes     = COALESCE((v_assigns->>'combined_sizes')::text,                                 combined_sizes),
    box_image          = COALESCE((v_assigns->>'box_image')::text,                                      box_image),
    is_textil              = COALESCE(public.fn_safe_bool(v_assigns->>'is_textil'),              is_textil),
    is_stockout            = COALESCE(public.fn_safe_bool(v_assigns->>'is_stockout'),            is_stockout),
    is_online_exclusive    = COALESCE(public.fn_safe_bool(v_assigns->>'is_online_exclusive'),    is_online_exclusive),
    is_new                 = COALESCE(public.fn_safe_bool(v_assigns->>'is_new'),                 is_new),
    has_colors             = COALESCE(public.fn_safe_bool(v_assigns->>'has_colors'),             has_colors),
    has_sizes              = COALESCE(public.fn_safe_bool(v_assigns->>'has_sizes'),              has_sizes),
    allows_personalization = COALESCE(public.fn_safe_bool(v_assigns->>'allows_personalization'), allows_personalization),
    tags               = COALESCE(public.fn_safe_jsonb_arr(v_assigns->>'tags'),                         tags),
    materials          = COALESCE(public.fn_safe_jsonb_arr(v_assigns->>'materials'),                    materials),
    meta_keywords      = COALESCE(public.fn_safe_text_arr(v_assigns->>'meta_keywords'),                 meta_keywords),
    raw_id             = r.id,
    updated_at         = now()
  WHERE id = v_pad_id
  RETURNING name INTO v_final_name;

  -- STATUS EXPLÍCITO (2026-06-11): name ⇒ standardized; sem name ⇒ rejected.
  IF v_final_name IS NOT NULL AND TRIM(v_final_name) <> '' THEN
    v_status := 'standardized';
  ELSE
    v_status := 'rejected';
    v_errs := v_errs || jsonb_build_object('field','name','error',
      'name_ausente: nenhum mapping/fallback produziu nome');
  END IF;

  UPDATE public.produtos_padronizacao
  SET status            = v_status,
      standardized_at   = CASE WHEN v_status='standardized' THEN now() ELSE standardized_at END,
      validation_errors = CASE WHEN jsonb_array_length(v_errs) > 0 THEN v_errs ELSE NULL END
  WHERE id = v_pad_id;

  PERFORM public.fn_enrich_padronizacao(v_pad_id);

  RETURN jsonb_build_object(
    'success', v_status = 'standardized', 'pad_id', v_pad_id,
    'status', v_status, 'fields_set', v_assigns,
    'errors', v_errs
  );
END;
$function$;

COMMENT ON FUNCTION public.fn_standardize_raw(uuid, text) IS
  'Bronze->Silver (produto/pai) via de-para supplier_field_mappings + fallback generico de name. 2026-06-11: clamp money (0,1e8]; sem name => rejected + validation_errors + success=false (antes ficava pending invisivel com success=true).';;

-- <<< END 20260611013908_pipeline_hardening_p1_standardize_raw_rejected_clamps.sql <<<

-- >>> BEGIN 20260611013958_m16_fn_classify_residual_promote_chain_2026.sql >>>
-- M16 — Categoria residual por dicionário ILIKE (alta precisão, derivado da análise
-- dos 388 produtos sem categoria) + cadeia completa na promoção:
-- De→Para → classify (melhor confiança) → residual. Sempre fill-only e nunca em campo lockado.

CREATE OR REPLACE FUNCTION public.fn_classify_category_residual(p_name text)
RETURNS uuid
LANGUAGE plpgsql STABLE
SET search_path TO 'public'
AS $function$
DECLARE
  n text := lower(COALESCE(p_name,''));
  v_id uuid;
BEGIN
  IF n = '' THEN RETURN NULL; END IF;

  -- chapéus (específico → genérico)
  IF n ~ 'chap[ée]u' THEN
    IF n ~ 'ecoflex' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu_ecoflex' LIMIT 1;
    ELSIF n ~ 'juta' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu_juta' LIMIT 1;
    ELSIF n ~ 'palha' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu_palha' LIMIT 1;
    ELSIF n ~ 'bucket' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu-bucket' LIMIT 1;
    END IF;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='chapeus' OR name='Chapéus' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- cadernos / cadernetas / blocos
  IF n ~ 'caderno|caderneta|bloco de anota' THEN
    SELECT id INTO v_id FROM categories WHERE slug='cadernetas-cadernos' LIMIT 1;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE name ILIKE 'caderno%' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- marmitas
  IF n ~ 'marmita' THEN
    SELECT id INTO v_id FROM categories WHERE name ILIKE 'marmit%' OR slug ILIKE 'marmit%' LIMIT 1;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='bar_e_cozinha' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- malas e bolsas
  IF n ~ '\mmala\M' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bolsas_de_viagem' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'bolsa t[ée]rmica' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bolsa_termica' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ '\mbolsa\M' AND n ~ 'esport|viagem|mochila' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bolsas_de_viagem' LIMIT 1; RETURN v_id;
  END IF;

  -- brinquedos / antiestresse
  IF n ~ 'brinquedo' AND n ~ '\mpet\M|cachorro|gato' THEN
    SELECT id INTO v_id FROM categories WHERE slug='brinquedos_pet' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'antiestresse|anti-estresse|anti estresse|apert[áa]vel|brinquedo' THEN
    SELECT id INTO v_id FROM categories WHERE slug='jogos_e_brinquedos' LIMIT 1; RETURN v_id;
  END IF;

  -- escritório / pastas
  IF n ~ 'pasta|escrit[óo]rio|porta document' THEN
    SELECT id INTO v_id FROM categories WHERE slug ILIKE 'escritorio%' OR name ILIKE 'escritório%' LIMIT 1;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='acessorios' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  RETURN NULL;
END;
$function$;

-- Promoção: cadeia de categoria completa (De→Para → classify melhor confiança → residual)
CREATE OR REPLACE FUNCTION public.fn_promote_category_fallback(p_name text)
RETURNS uuid
LANGUAGE plpgsql STABLE
SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  BEGIN
    SELECT c.category_id INTO v_id
    FROM public.classify_xbz_category(p_name) c
    ORDER BY CASE c.confidence WHEN 'alta' THEN 1 WHEN 'média' THEN 2 ELSE 3 END
    LIMIT 1;
  EXCEPTION WHEN OTHERS THEN v_id := NULL;
  END;
  IF v_id IS NULL THEN
    v_id := public.fn_classify_category_residual(p_name);
  END IF;
  RETURN v_id;
END;
$function$;;

-- <<< END 20260611013958_m16_fn_classify_residual_promote_chain_2026.sql <<<

-- >>> BEGIN 20260611014138_m16b_fn_classify_residual_wave2_2026.sql >>>
-- M16b — Onda 2 do dicionário residual (caixa de som, mouse pad, churrasco,
-- kit drink/executivo/talheres, umidificador, frasqueira, pet, marmita...)

CREATE OR REPLACE FUNCTION public.fn_classify_category_residual(p_name text)
RETURNS uuid
LANGUAGE plpgsql STABLE
SET search_path TO 'public'
AS $function$
DECLARE
  n text := lower(COALESCE(p_name,''));
  v_id uuid;
BEGIN
  IF n = '' THEN RETURN NULL; END IF;

  -- som / áudio
  IF n ~ 'caixa de som|caixa som|speaker' THEN
    SELECT id INTO v_id FROM categories WHERE slug='caixa-de-som' LIMIT 1; RETURN v_id;
  END IF;

  -- mouse pad
  IF n ~ 'mouse ?pad' THEN
    IF n ~ 'ergon[ôo]mico' THEN SELECT id INTO v_id FROM categories WHERE slug='mouse_pad_espuma_ergonomico' LIMIT 1; END IF;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='mouse_pad' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- churrasco
  IF n ~ 'churrasqueira|churrasco' THEN
    IF n ~ '\mkit\M' THEN SELECT id INTO v_id FROM categories WHERE slug='kit_churrasco' LIMIT 1; END IF;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='churrasco' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- kits específicos
  IF n ~ '\mkit\M' AND n ~ 'drink|coquetel' THEN
    SELECT id INTO v_id FROM categories WHERE slug='kit-drink' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ '\mkit\M' AND n ~ 'executivo' THEN
    SELECT id INTO v_id FROM categories WHERE slug='kit_executivo' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'talher' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bar_e_cozinha' LIMIT 1; RETURN v_id;
  END IF;

  -- utilidades / casa
  IF n ~ 'umidificador|aromatizador' THEN
    SELECT id INTO v_id FROM categories WHERE slug='ferramentas-utilidades' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'frasqueira' THEN
    SELECT id INTO v_id FROM categories WHERE slug='frasqueiras' LIMIT 1; RETURN v_id;
  END IF;

  -- pet
  IF n ~ 'bebedouro|comedouro' AND n ~ '\mpet|cachorro|gato' THEN
    SELECT id INTO v_id FROM categories WHERE slug='brinquedos_pet' LIMIT 1; RETURN v_id;
  END IF;

  -- chapéus
  IF n ~ 'chap[ée]u' THEN
    IF n ~ 'ecoflex' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu_ecoflex' LIMIT 1;
    ELSIF n ~ 'juta' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu_juta' LIMIT 1;
    ELSIF n ~ 'palha' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu_palha' LIMIT 1;
    ELSIF n ~ 'bucket' THEN SELECT id INTO v_id FROM categories WHERE slug='chapeu-bucket' LIMIT 1;
    END IF;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='chapeus' OR name='Chapéus' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- cadernos / cadernetas / blocos
  IF n ~ 'caderno|caderneta|bloco de anota' THEN
    SELECT id INTO v_id FROM categories WHERE slug='cadernetas-cadernos' LIMIT 1;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE name ILIKE 'caderno%' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- marmitas
  IF n ~ 'marmita' THEN
    SELECT id INTO v_id FROM categories WHERE name ILIKE 'marmit%' OR slug ILIKE 'marmit%' LIMIT 1;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='bar_e_cozinha' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  -- malas e bolsas
  IF n ~ '\mmala\M' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bolsas_de_viagem' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'bolsa t[ée]rmica' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bolsa_termica' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ '\mbolsa\M' AND n ~ 'esport|viagem|mochila' THEN
    SELECT id INTO v_id FROM categories WHERE slug='bolsas_de_viagem' LIMIT 1; RETURN v_id;
  END IF;

  -- brinquedos / antiestresse
  IF n ~ 'brinquedo' AND n ~ '\mpet\M|cachorro|gato' THEN
    SELECT id INTO v_id FROM categories WHERE slug='brinquedos_pet' LIMIT 1; RETURN v_id;
  END IF;
  IF n ~ 'antiestresse|anti-estresse|anti estresse|apert[áa]vel|brinquedo' THEN
    SELECT id INTO v_id FROM categories WHERE slug='jogos_e_brinquedos' LIMIT 1; RETURN v_id;
  END IF;

  -- escritório / pastas
  IF n ~ 'pasta|escrit[óo]rio|porta document' THEN
    SELECT id INTO v_id FROM categories WHERE slug ILIKE 'escritorio%' OR name ILIKE 'escritório%' LIMIT 1;
    IF v_id IS NULL THEN SELECT id INTO v_id FROM categories WHERE slug='acessorios' LIMIT 1; END IF;
    RETURN v_id;
  END IF;

  RETURN NULL;
END;
$function$;;

-- <<< END 20260611014138_m16b_fn_classify_residual_wave2_2026.sql <<<

-- >>> BEGIN 20260611014254_m18_medallion_coverage_monitoring_2026.sql >>>
-- M18 — Monitoramento de cobertura do pipeline (anti-decay):
-- view ao vivo + snapshots diários + função de detecção de regressão.
-- Motivação: as melhorias V1 decaíram silenciosamente porque eram UPDATEs
-- retroativos sem guarda. Agora: funções corrigem na FONTE + este monitor detecta drift.

CREATE OR REPLACE VIEW public.vw_medallion_coverage AS
SELECT
  s.name AS fornecedor,
  'silver' AS camada,
  COUNT(*) AS produtos,
  ROUND(100.0*SUM(CASE WHEN NULLIF(TRIM(pp.ncm_code),'') IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS ncm_pct,
  ROUND(100.0*SUM(CASE WHEN jsonb_array_length(COALESCE(pp.materials,'[]'::jsonb))>0 THEN 1 ELSE 0 END)/COUNT(*),1) AS materials_pct,
  ROUND(100.0*SUM(CASE WHEN jsonb_array_length(COALESCE(pp.tags,'[]'::jsonb))>0 THEN 1 ELSE 0 END)/COUNT(*),1) AS tags_pct,
  ROUND(100.0*SUM(CASE WHEN COALESCE(array_length(pp.meta_keywords,1),0)>0 THEN 1 ELSE 0 END)/COUNT(*),1) AS meta_pct,
  ROUND(100.0*SUM(CASE WHEN pp.ipi_rate IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS ipi_pct,
  ROUND(100.0*SUM(CASE WHEN NULLIF(TRIM(pp.description),'') IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS description_pct,
  NULL::numeric AS category_pct,
  NULL::numeric AS display_name_pct
FROM public.produtos_padronizacao pp JOIN public.suppliers s ON s.id=pp.supplier_id
GROUP BY s.name
UNION ALL
SELECT
  s.name, 'gold', COUNT(*),
  ROUND(100.0*SUM(CASE WHEN NULLIF(TRIM(p.ncm_code),'') IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN jsonb_array_length(COALESCE(p.tags,'[]'::jsonb))>0 THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN jsonb_array_length(COALESCE(p.tags,'[]'::jsonb))>0 THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN COALESCE(array_length(p.meta_keywords,1),0)>0 THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN p.ipi_rate IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN NULLIF(TRIM(p.description),'') IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN p.category_id IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN p.name IS NULL OR p.name <> public.fn_normalize_product_name(p.name) OR p.name !~ '[A-Za-zÀ-ú]{4,}' THEN 1 ELSE 0 END)/COUNT(*),1)
FROM public.products p JOIN public.suppliers s ON s.id=p.supplier_id
GROUP BY s.name;

CREATE TABLE IF NOT EXISTS public.medallion_coverage_snapshots (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  captured_at timestamptz NOT NULL DEFAULT now(),
  fornecedor text NOT NULL,
  camada text NOT NULL,
  produtos int NOT NULL,
  ncm_pct numeric, materials_pct numeric, tags_pct numeric, meta_pct numeric,
  ipi_pct numeric, description_pct numeric, category_pct numeric, display_name_pct numeric
);
CREATE INDEX IF NOT EXISTS idx_mcs_captured ON public.medallion_coverage_snapshots (captured_at);

ALTER TABLE public.medallion_coverage_snapshots ENABLE ROW LEVEL SECURITY;
DO $$ BEGIN
  CREATE POLICY mcs_admin_read ON public.medallion_coverage_snapshots
    FOR SELECT TO authenticated USING (true);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE OR REPLACE FUNCTION public.fn_snapshot_medallion_coverage()
RETURNS integer
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE n int;
BEGIN
  INSERT INTO public.medallion_coverage_snapshots
    (fornecedor, camada, produtos, ncm_pct, materials_pct, tags_pct, meta_pct, ipi_pct, description_pct, category_pct, display_name_pct)
  SELECT fornecedor, camada, produtos, ncm_pct, materials_pct, tags_pct, meta_pct, ipi_pct, description_pct, category_pct, display_name_pct
  FROM public.vw_medallion_coverage;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$function$;

-- Regressão: queda > 2pp em qualquer métrica vs máximo dos últimos 7 dias
CREATE OR REPLACE FUNCTION public.fn_check_coverage_regression()
RETURNS TABLE (fornecedor text, camada text, metrica text, maximo_7d numeric, atual numeric, queda_pp numeric)
LANGUAGE sql STABLE
SET search_path TO 'public'
AS $function$
  WITH hist AS (
    SELECT fornecedor, camada,
           MAX(ncm_pct) ncm, MAX(materials_pct) mat, MAX(tags_pct) tags, MAX(meta_pct) meta,
           MAX(ipi_pct) ipi, MAX(description_pct) descr, MAX(category_pct) cat, MAX(display_name_pct) disp
    FROM public.medallion_coverage_snapshots
    WHERE captured_at > now() - interval '7 days'
    GROUP BY fornecedor, camada
  ), atual AS (
    SELECT * FROM public.vw_medallion_coverage
  ), unioned AS (
    SELECT a.fornecedor, a.camada, m.metrica, m.maximo, m.val
    FROM atual a JOIN hist h ON h.fornecedor=a.fornecedor AND h.camada=a.camada
    CROSS JOIN LATERAL (VALUES
      ('ncm', h.ncm, a.ncm_pct), ('materials', h.mat, a.materials_pct),
      ('tags', h.tags, a.tags_pct), ('meta', h.meta, a.meta_pct),
      ('ipi', h.ipi, a.ipi_pct), ('description', h.descr, a.description_pct),
      ('category', h.cat, a.category_pct), ('display_name', h.disp, a.display_name_pct)
    ) m(metrica, maximo, val)
  )
  SELECT fornecedor, camada, metrica, maximo, val, ROUND(maximo - val, 1)
  FROM unioned
  WHERE maximo IS NOT NULL AND val IS NOT NULL AND maximo - val > 2.0
  ORDER BY (maximo - val) DESC;
$function$;

-- Snapshot diário 03:37 UTC
DO $$ BEGIN
  PERFORM cron.schedule('medallion-coverage-daily', '37 3 * * *',
    'SELECT public.fn_snapshot_medallion_coverage()');
EXCEPTION WHEN OTHERS THEN NULL; END $$;

-- Snapshot inicial (baseline pós-melhorias)
SELECT public.fn_snapshot_medallion_coverage();;

-- <<< END 20260611014254_m18_medallion_coverage_monitoring_2026.sql <<<

-- >>> BEGIN 20260611014320_m18b_fix_view_gold_materials_col_2026.sql >>>
-- Fix: branch gold da view usava p.tags na coluna materials_pct
CREATE OR REPLACE VIEW public.vw_medallion_coverage AS
SELECT
  s.name AS fornecedor,
  'silver' AS camada,
  COUNT(*) AS produtos,
  ROUND(100.0*SUM(CASE WHEN NULLIF(TRIM(pp.ncm_code),'') IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS ncm_pct,
  ROUND(100.0*SUM(CASE WHEN jsonb_array_length(COALESCE(pp.materials,'[]'::jsonb))>0 THEN 1 ELSE 0 END)/COUNT(*),1) AS materials_pct,
  ROUND(100.0*SUM(CASE WHEN jsonb_array_length(COALESCE(pp.tags,'[]'::jsonb))>0 THEN 1 ELSE 0 END)/COUNT(*),1) AS tags_pct,
  ROUND(100.0*SUM(CASE WHEN COALESCE(array_length(pp.meta_keywords,1),0)>0 THEN 1 ELSE 0 END)/COUNT(*),1) AS meta_pct,
  ROUND(100.0*SUM(CASE WHEN pp.ipi_rate IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS ipi_pct,
  ROUND(100.0*SUM(CASE WHEN NULLIF(TRIM(pp.description),'') IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1) AS description_pct,
  NULL::numeric AS category_pct,
  NULL::numeric AS display_name_pct
FROM public.produtos_padronizacao pp JOIN public.suppliers s ON s.id=pp.supplier_id
GROUP BY s.name
UNION ALL
SELECT
  s.name, 'gold', COUNT(*),
  ROUND(100.0*SUM(CASE WHEN NULLIF(TRIM(p.ncm_code),'') IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN jsonb_array_length(COALESCE(p.materials,'[]'::jsonb))>0
                        OR EXISTS (SELECT 1 FROM public.product_materials pm WHERE pm.product_id=p.id) THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN jsonb_array_length(COALESCE(p.tags,'[]'::jsonb))>0 THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN COALESCE(array_length(p.meta_keywords,1),0)>0 THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN p.ipi_rate IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN NULLIF(TRIM(p.description),'') IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN p.category_id IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),1),
  ROUND(100.0*SUM(CASE WHEN p.name IS NULL OR p.name <> public.fn_normalize_product_name(p.name) OR p.name !~ '[A-Za-zÀ-ú]{4,}' THEN 1 ELSE 0 END)/COUNT(*),1)
FROM public.products p JOIN public.suppliers s ON s.id=p.supplier_id
GROUP BY s.name;

-- refaz o snapshot baseline com a view corrigida
DELETE FROM public.medallion_coverage_snapshots WHERE captured_at > now() - interval '1 hour';
SELECT public.fn_snapshot_medallion_coverage();;

-- <<< END 20260611014320_m18b_fix_view_gold_materials_col_2026.sql <<<

-- >>> BEGIN 20260611014515_fn_dryrun_standardize_supplier_real_rollback.sql >>>
-- fn_dryrun_standardize_supplier: dry-run DE VERDADE (rollback via subtransação).
-- Antes escrevia no Silver apesar do nome (sem filtro de status, sem revert).
CREATE OR REPLACE FUNCTION public.fn_dryrun_standardize_supplier(
    p_supplier_id uuid,
    p_limit       integer DEFAULT 50
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_preview jsonb;
  v_detail  text;
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin_or_above((SELECT auth.uid())) THEN
    RAISE EXCEPTION 'Acesso negado: requer perfil admin ou superior';
  END IF;

  BEGIN
    PERFORM set_config('app.write_source', 'pipeline', true);

    v_preview := jsonb_build_object(
      'standardize', public.fn_standardize_supplier(p_supplier_id, p_limit));

    v_preview := v_preview || jsonb_build_object(
      'silver_depois', jsonb_build_object(
        'pais_standardized', (SELECT COUNT(*) FROM public.produtos_padronizacao
           WHERE supplier_id=p_supplier_id AND status='standardized'),
        'pais_rejected', (SELECT COUNT(*) FROM public.produtos_padronizacao
           WHERE supplier_id=p_supplier_id AND status='rejected'),
        'variantes_standardized', (SELECT COUNT(*) FROM public.produtos_padronizacao_variantes
           WHERE supplier_id=p_supplier_id AND status='standardized'),
        'amostra_rejeitados', (SELECT jsonb_agg(jsonb_build_object(
             'ref', p.supplier_reference, 'erros', p.validation_errors))
           FROM (SELECT supplier_reference, validation_errors
                 FROM public.produtos_padronizacao
                 WHERE supplier_id=p_supplier_id AND status='rejected'
                 ORDER BY updated_at DESC LIMIT 5) p)));

    RAISE EXCEPTION 'DRYRUN_ROLLBACK' USING DETAIL = v_preview::text;

  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM = 'DRYRUN_ROLLBACK' THEN
      GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
      RETURN jsonb_build_object(
        'success', true, 'dry_run', true, 'reverted', true,
        'supplier_id', p_supplier_id, 'preview', v_detail::jsonb);
    END IF;
    RETURN jsonb_build_object(
      'success', false, 'dry_run', true, 'reverted', true,
      'supplier_id', p_supplier_id, 'error', SQLERRM);
  END;
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_dryrun_standardize_supplier(uuid, integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_dryrun_standardize_supplier(uuid, integer) FROM anon;
REVOKE ALL ON FUNCTION public.fn_dryrun_standardize_supplier(uuid, integer) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.fn_dryrun_standardize_supplier(uuid, integer) TO postgres;
GRANT EXECUTE ON FUNCTION public.fn_dryrun_standardize_supplier(uuid, integer) TO service_role;

COMMENT ON FUNCTION public.fn_dryrun_standardize_supplier(uuid, integer) IS
  'Dry-run REAL do Bronze->Silver: executa fn_standardize_supplier numa subtransação, coleta preview (contagens + amostra de rejeitados) e REVERTE tudo via exceção sentinela. 2026-06-11: antes escrevia no Silver apesar do nome.';;

-- <<< END 20260611014515_fn_dryrun_standardize_supplier_real_rollback.sql <<<

-- >>> BEGIN 20260611014803_lockdown_pipeline_function_acls.sql >>>
-- LOCKDOWN de ACLs das funções do pipeline (achado #7, advisors 2026-06-11).
-- kit_component executável por PUBLIC/anon; fn_standardize_supplier regrediu.
-- Contrato: pipeline executável APENAS por postgres + service_role.
DO $$
DECLARE
  fn record;
BEGIN
  FOR fn IN
    SELECT format('%I.%I(%s)', n.nspname, p.proname,
                  pg_get_function_identity_arguments(p.oid)) AS sig
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname IN (
        'fn_standardize_supplier',
        'fn_pipeline_promote_tick',
        'fn_dryrun_raw_v2',
        'fn_dryrun_standardize_supplier',
        'fn_standardize_kit_component',
        'fn_promote_kit_component_padronizacao',
        'fn_sm_site_promote')
  LOOP
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC', fn.sig);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM anon', fn.sig);
    EXECUTE format('REVOKE ALL ON FUNCTION %s FROM authenticated', fn.sig);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO postgres', fn.sig);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role', fn.sig);
  END LOOP;
END $$;

ALTER FUNCTION public.fn_sm_site_promote(integer) SET search_path TO 'public', 'extensions';;

-- <<< END 20260611014803_lockdown_pipeline_function_acls.sql <<<

