-- >>> BEGIN 20260611124504_fix_classify_pen_v2_slugs_novos_materiais.sql >>>

-- ============================================================================
-- classify_pen v2.0 — Correção de slugs + novas categorias + volatilidade correta
-- GAPs corrigidos:
--   1. 'canetas-roller' → 'canetas-metal-roller' (slug real no banco)
--   2. Adicionados: canetas-cortica, canetas-madeira, canetas_semi_metal,
--      canetas-fibra-eco, canetas-aluminio-reciclado
--   3. Volatilidade IMMUTABLE → STABLE (função faz SELECT em tabela)
--   4. Adicionado campo 'is_pen' no retorno para classificação segura
-- ============================================================================

CREATE OR REPLACE FUNCTION public.classify_pen(product_name text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE                          -- lê categories; STABLE é o correto (não IMMUTABLE)
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_name          TEXT;
    v_is_pen        BOOLEAN := FALSE;
    v_material      TEXT;
    v_category_id   UUID;
    v_category_slug TEXT;
    v_attributes    JSONB;
BEGIN
    -- ========================================================================
    -- 1. NORMALIZAÇÃO
    -- ========================================================================
    v_name := UPPER(unaccent(COALESCE(product_name, '')));

    -- ========================================================================
    -- 2. VALIDAÇÃO: É CANETA OU LAPISEIRA?
    --    Padrões: CANETA, ESFEROGRAF*, ROLLER, LAPISEIRA, STYLUS, MARCA-TEXTO
    -- ========================================================================
    IF v_name ~ 'CANETA|ESFEROGRAF|ROLLER|LAPISEIRA|STYLUS|MARCA.?TEXTO' THEN
        v_is_pen := TRUE;
    END IF;

    -- Se NÃO é caneta/lapiseira, retorna imediatamente (sem custo)
    IF NOT v_is_pen THEN
        RETURN jsonb_build_object(
            'is_pen',        FALSE,
            'category_id',   NULL,
            'category_slug', NULL,
            'material',      NULL,
            'attributes',    NULL
        );
    END IF;

    -- ========================================================================
    -- 3. IDENTIFICAÇÃO DO MATERIAL (hierarquia: mais específico primeiro)
    --    Ordem: Bambu > Cortiça > Madeira > Fibra Eco > Alumínio Reciclado >
    --           Reciclado/Eco > Roller > Metal > Semi-Metal > Plástico > Fallback
    -- ========================================================================

    IF v_name ~ 'BAMBU|BAMBOO' THEN
        v_material      := 'BAMBU';
        v_category_slug := 'canetas-bambu';

    ELSIF v_name ~ 'CORTIC[AÇ]' THEN
        v_material      := 'CORTIÇA';
        v_category_slug := 'canetas-cortica';          -- FIX v2: categoria específica

    ELSIF v_name ~ 'MADEIRA|WOOD' THEN
        v_material      := 'MADEIRA';
        v_category_slug := 'canetas-madeira';          -- NOVO v2

    ELSIF v_name ~ 'FIBRA.?ECO|WHEAT.?STRAW|PALHA.?TRIGO|FIBRA.?TRIGO' THEN
        v_material      := 'FIBRA ECO';
        v_category_slug := 'canetas-fibra-eco';        -- NOVO v2

    ELSIF v_name ~ 'ALUMIN.*RECICLAD|RECICLAD.*ALUMIN' THEN
        v_material      := 'ALUMÍNIO RECICLADO';
        v_category_slug := 'canetas-aluminio-reciclado'; -- NOVO v2

    ELSIF v_name ~ 'RECICLAD|RECICLAV|ECOLOGIC|ECO\.|ECO[^A-Z]|PAPEL|KRAFT' THEN
        v_material      := 'ECOLÓGICA';
        v_category_slug := 'canetas-ecologicas';

    ELSIF v_name ~ 'ROLLER|ROLLERBALL' THEN
        v_material      := 'METAL';
        v_category_slug := 'canetas-metal-roller';     -- FIX v2: slug correto

    ELSIF v_name ~ 'METAL|METALIC|INOX|ALUMIN' THEN
        v_material      := 'METAL';
        v_category_slug := 'canetas_metal';

    ELSIF v_name ~ 'SEMI.?METAL' THEN
        v_material      := 'SEMI-METAL';
        v_category_slug := 'canetas_semi_metal';       -- NOVO v2

    ELSIF v_name ~ 'PLASTIC|ACRILIC|ABS|EMBORRACHAD|SILICONE|TRANSPARENTE|TRANSLUCID' THEN
        v_material      := 'PLÁSTICO';
        v_category_slug := 'canetas_plastico';

    ELSE
        v_material      := 'INDEFINIDO';
        v_category_slug := 'canetas';
    END IF;

    -- ========================================================================
    -- 4. BUSCAR UUID DA CATEGORIA (dinâmico — nunca hardcoded)
    -- ========================================================================
    SELECT id INTO v_category_id
    FROM categories
    WHERE slug = v_category_slug AND is_active = true
    LIMIT 1;

    -- Fallback em cascata: subcategoria → pai → raiz canetas
    IF v_category_id IS NULL AND v_category_slug NOT IN ('canetas', 'canetas-ecologicas', 'canetas_metal', 'canetas_plastico') THEN
        -- Tenta a categoria-pai mais próxima
        CASE
            WHEN v_category_slug IN ('canetas-cortica', 'canetas-madeira', 'canetas-fibra-eco',
                                      'canetas-aluminio-reciclado', 'canetas-papel-reciclado',
                                      'canetas-plastico-reciclado') THEN
                SELECT id INTO v_category_id FROM categories WHERE slug = 'canetas-ecologicas' AND is_active = true LIMIT 1;
            WHEN v_category_slug IN ('canetas-metal-roller', 'canetas-premium-griffs') THEN
                SELECT id INTO v_category_id FROM categories WHERE slug = 'canetas_metal' AND is_active = true LIMIT 1;
            WHEN v_category_slug = 'canetas_semi_metal' THEN
                SELECT id INTO v_category_id FROM categories WHERE slug = 'canetas_metal' AND is_active = true LIMIT 1;
            ELSE NULL;
        END CASE;
        v_category_slug := COALESCE(
            (SELECT slug FROM categories WHERE id = v_category_id LIMIT 1),
            v_category_slug
        );
    END IF;

    -- Fallback final: categoria raiz de canetas
    IF v_category_id IS NULL THEN
        SELECT id INTO v_category_id FROM categories WHERE slug = 'canetas' AND is_active = true LIMIT 1;
        v_category_slug := 'canetas';
    END IF;

    -- ========================================================================
    -- 5. ATRIBUTOS FUNCIONAIS (independente do material)
    -- ========================================================================
    v_attributes := jsonb_build_object(
        'has_touch',         v_name ~ 'TOUCH|STYLUS',
        'has_roller',        v_name ~ 'ROLLER|ROLLERBALL',
        'has_marca_texto',   v_name ~ 'MARCA.?TEXTO|MARCADOR|DESTAQUE',
        'has_multifuncao',   v_name ~ 'MULTIFUNC|[234].?EM.?1',
        'has_laser',         v_name ~ 'LASER|APONTADOR',
        'has_lanterna',      v_name ~ 'LANTERNA|LED|LUZ',
        'has_pen_drive',     v_name ~ 'PEN.?DRIVE|USB|PENDRIVE',
        'has_porta_celular', v_name ~ 'PORTA.?CELULAR|SUPORTE|BASE',
        'has_lapiseira',     v_name ~ 'LAPISEIRA|LAPISC'
    );

    -- ========================================================================
    -- 6. RETORNO
    -- ========================================================================
    RETURN jsonb_build_object(
        'is_pen',        TRUE,
        'category_id',   v_category_id,
        'category_slug', v_category_slug,
        'material',      v_material,
        'attributes',    v_attributes
    );
END;
$function$;

COMMENT ON FUNCTION public.classify_pen(TEXT) IS
'classify_pen v2.0 (jun/2026) — Classifica canetas de qualquer fornecedor.
Mudanças v2: slug roller corrigido (canetas-metal-roller), 
novas categorias (cortica, madeira, fibra-eco, aluminio-reciclado, semi-metal),
volatilidade IMMUTABLE→STABLE, fallback em cascata, has_lapiseira adicionado.
Taxa de cobertura esperada: >92% (era 88.5% na v1.1).';
;

-- <<< END 20260611124504_fix_classify_pen_v2_slugs_novos_materiais.sql <<<

-- >>> BEGIN 20260611124554_fix_classify_pen_v2_1_semi_metal_order.sql >>>

-- Patch cirúrgico: mover SEMI.?METAL ANTES de METAL na cadeia ELSIF
-- + excluir SEMI do padrão METAL para evitar ambiguidade futura

CREATE OR REPLACE FUNCTION public.classify_pen(product_name text)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_name          TEXT;
    v_is_pen        BOOLEAN := FALSE;
    v_material      TEXT;
    v_category_id   UUID;
    v_category_slug TEXT;
    v_attributes    JSONB;
BEGIN
    v_name := UPPER(unaccent(COALESCE(product_name, '')));

    IF v_name ~ 'CANETA|ESFEROGRAF|ROLLER|LAPISEIRA|STYLUS|MARCA.?TEXTO' THEN
        v_is_pen := TRUE;
    END IF;

    IF NOT v_is_pen THEN
        RETURN jsonb_build_object('is_pen', FALSE, 'category_id', NULL,
                                  'category_slug', NULL, 'material', NULL, 'attributes', NULL);
    END IF;

    -- Hierarquia: mais específico PRIMEIRO
    IF v_name ~ 'BAMBU|BAMBOO' THEN
        v_material := 'BAMBU'; v_category_slug := 'canetas-bambu';

    ELSIF v_name ~ 'CORTIC[AÇ]' THEN
        v_material := 'CORTIÇA'; v_category_slug := 'canetas-cortica';

    ELSIF v_name ~ 'MADEIRA|WOOD' THEN
        v_material := 'MADEIRA'; v_category_slug := 'canetas-madeira';

    ELSIF v_name ~ 'FIBRA.?ECO|WHEAT.?STRAW|PALHA.?TRIGO|FIBRA.?TRIGO' THEN
        v_material := 'FIBRA ECO'; v_category_slug := 'canetas-fibra-eco';

    ELSIF v_name ~ 'ALUMIN.*RECICLAD|RECICLAD.*ALUMIN' THEN
        v_material := 'ALUMÍNIO RECICLADO'; v_category_slug := 'canetas-aluminio-reciclado';

    ELSIF v_name ~ 'RECICLAD|RECICLAV|ECOLOGIC|ECO\.|ECO[^A-Z]|PAPEL|KRAFT' THEN
        v_material := 'ECOLÓGICA'; v_category_slug := 'canetas-ecologicas';

    ELSIF v_name ~ 'ROLLER|ROLLERBALL' THEN
        v_material := 'METAL'; v_category_slug := 'canetas-metal-roller';

    ELSIF v_name ~ 'SEMI.?METAL' THEN
        -- DEVE vir ANTES do padrão METAL genérico
        v_material := 'SEMI-METAL'; v_category_slug := 'canetas_semi_metal';

    ELSIF v_name ~ '(^|[^A-Z])METAL([^A-Z]|$)|METALIC|INOX|ALUMIN' THEN
        -- Padrão METAL com word-boundary para não capturar SEMI METAL
        v_material := 'METAL'; v_category_slug := 'canetas_metal';

    ELSIF v_name ~ 'PLASTIC|ACRILIC|ABS|EMBORRACHAD|SILICONE|TRANSPARENTE|TRANSLUCID' THEN
        v_material := 'PLÁSTICO'; v_category_slug := 'canetas_plastico';

    ELSE
        v_material := 'INDEFINIDO'; v_category_slug := 'canetas';
    END IF;

    -- Busca UUID dinâmico
    SELECT id INTO v_category_id FROM categories
    WHERE slug = v_category_slug AND is_active = true LIMIT 1;

    -- Fallback em cascata
    IF v_category_id IS NULL AND v_category_slug NOT IN ('canetas','canetas-ecologicas','canetas_metal','canetas_plastico') THEN
        CASE
            WHEN v_category_slug IN ('canetas-cortica','canetas-madeira','canetas-fibra-eco',
                                     'canetas-aluminio-reciclado','canetas-papel-reciclado',
                                     'canetas-plastico-reciclado') THEN
                SELECT id INTO v_category_id FROM categories WHERE slug='canetas-ecologicas' AND is_active=true LIMIT 1;
                v_category_slug := 'canetas-ecologicas';
            WHEN v_category_slug IN ('canetas-metal-roller','canetas-premium-griffs',
                                     'canetas_semi_metal') THEN
                SELECT id INTO v_category_id FROM categories WHERE slug='canetas_metal' AND is_active=true LIMIT 1;
                v_category_slug := 'canetas_metal';
            ELSE NULL;
        END CASE;
    END IF;

    IF v_category_id IS NULL THEN
        SELECT id INTO v_category_id FROM categories WHERE slug='canetas' AND is_active=true LIMIT 1;
        v_category_slug := 'canetas';
    END IF;

    v_attributes := jsonb_build_object(
        'has_touch',         v_name ~ 'TOUCH|STYLUS',
        'has_roller',        v_name ~ 'ROLLER|ROLLERBALL',
        'has_marca_texto',   v_name ~ 'MARCA.?TEXTO|MARCADOR|DESTAQUE',
        'has_multifuncao',   v_name ~ 'MULTIFUNC|[234].?EM.?1',
        'has_laser',         v_name ~ 'LASER|APONTADOR',
        'has_lanterna',      v_name ~ 'LANTERNA|LED|LUZ',
        'has_pen_drive',     v_name ~ 'PEN.?DRIVE|USB|PENDRIVE',
        'has_porta_celular', v_name ~ 'PORTA.?CELULAR|SUPORTE|BASE',
        'has_lapiseira',     v_name ~ 'LAPISEIRA|LAPISC'
    );

    RETURN jsonb_build_object(
        'is_pen',        TRUE,
        'category_id',   v_category_id,
        'category_slug', v_category_slug,
        'material',      v_material,
        'attributes',    v_attributes
    );
END;
$function$;

COMMENT ON FUNCTION public.classify_pen(TEXT) IS
'classify_pen v2.1 (jun/2026) — Fix ordem SEMI_METAL antes de METAL. 
Cobre: bambu, cortiça, madeira, fibra-eco, alumínio-reciclado, ecológica, 
roller, semi-metal, metal, plástico, indefinido. Fallback em cascata.';
;

-- <<< END 20260611124554_fix_classify_pen_v2_1_semi_metal_order.sql <<<

-- >>> BEGIN 20260611124637_create_fn_enrich_pen_categories.sql >>>

-- ============================================================================
-- fn_enrich_pen_categories(p_supplier_id, p_batch_size, p_force_reclassify)
-- 
-- Propósito: Classificar canetas no Gold usando classify_pen v2.1
--            → grava em product_category_assignments
--            → grava atributos no products.properties_data (se existir)
--
-- Modo de uso:
--   SELECT fn_enrich_pen_categories();                  -- todos os fornecedores, só não-classificadas
--   SELECT fn_enrich_pen_categories(NULL, 500, TRUE);   -- reclassifica tudo (força)
--   SELECT fn_enrich_pen_categories('uuid-spot', 200);  -- só SPOT, 200 por vez
--
-- Regras de segurança:
--   - Nunca remove categorias existentes NÃO-canetas do produto
--   - ON CONFLICT DO NOTHING → idempotente
--   - Não modifica produtos que não são canetas (classify_pen.is_pen = false)
--   - p_force_reclassify = FALSE (default): só processa sem categoria de caneta
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_enrich_pen_categories(
    p_supplier_id       uuid    DEFAULT NULL,    -- NULL = todos os fornecedores
    p_batch_size        integer DEFAULT 300,
    p_force_reclassify  boolean DEFAULT FALSE    -- TRUE = reclassifica mesmo quem já tem
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_processed     integer := 0;
    v_classified    integer := 0;
    v_skipped       integer := 0;
    v_errors        integer := 0;
    v_rec           RECORD;
    v_pen_result    jsonb;
    v_category_id   uuid;
    v_pen_category_ids uuid[];
BEGIN
    -- Pré-carregar UUIDs das categorias de canetas para filtro eficiente
    SELECT ARRAY_AGG(id) INTO v_pen_category_ids
    FROM categories
    WHERE (slug ILIKE 'caneta%' OR slug = 'lapiseiras')
    AND is_active = true;

    -- Loop sobre produtos candidatos
    FOR v_rec IN
        SELECT DISTINCT ON (p.id)
            p.id,
            p.name,
            p.supplier_id
        FROM products p
        WHERE p.is_active = true
        AND (
            p.name ILIKE '%caneta%'
            OR p.name ILIKE '%esferograf%'
            OR p.name ILIKE '%lapiseira%'
            OR p.name ILIKE '%roller%'
            OR p.name ILIKE '%stylus%'
        )
        AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
        AND (
            p_force_reclassify = TRUE
            OR NOT EXISTS (
                SELECT 1 FROM product_category_assignments pca
                WHERE pca.product_id = p.id
                AND pca.category_id = ANY(v_pen_category_ids)
            )
        )
        ORDER BY p.id
        LIMIT p_batch_size
    LOOP
        v_processed := v_processed + 1;

        BEGIN
            -- Classificar
            v_pen_result := classify_pen(v_rec.name);

            -- Só processa se for caneta e tiver category_id
            IF (v_pen_result->>'is_pen')::boolean = TRUE
               AND (v_pen_result->>'category_id') IS NOT NULL THEN

                v_category_id := (v_pen_result->>'category_id')::uuid;

                -- Gravar em product_category_assignments (idempotente)
                INSERT INTO product_category_assignments (
                    product_id,
                    category_id,
                    is_primary,
                    source,
                    created_at,
                    updated_at
                )
                VALUES (
                    v_rec.id,
                    v_category_id,
                    FALSE,          -- não sobrescreve primary existente
                    'classify_pen_v2',
                    now(),
                    now()
                )
                ON CONFLICT (product_id, category_id) DO UPDATE
                    SET updated_at = now(),
                        source = 'classify_pen_v2';

                v_classified := v_classified + 1;

            ELSE
                v_skipped := v_skipped + 1;
            END IF;

        EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors + 1;
            -- Continua sem parar o batch inteiro
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'status',      'ok',
        'processed',   v_processed,
        'classified',  v_classified,
        'skipped',     v_skipped,
        'errors',      v_errors,
        'timestamp',   now()
    );
END;
$$;

COMMENT ON FUNCTION public.fn_enrich_pen_categories(uuid, integer, boolean) IS
'Classifica canetas no Gold usando classify_pen v2.1 → product_category_assignments.
Idempotente (ON CONFLICT DO UPDATE). Seguro: não remove categorias existentes.
Parâmetros: supplier_id (NULL=todos), batch_size (default 300), force_reclassify (default FALSE).';

-- Garantir permissão de execução
GRANT EXECUTE ON FUNCTION public.fn_enrich_pen_categories(uuid, integer, boolean) TO service_role;
;

-- <<< END 20260611124637_create_fn_enrich_pen_categories.sql <<<

-- >>> BEGIN 20260611124715_fix_fn_enrich_pen_categories_schema_correto.sql >>>

-- Fix: remover colunas inexistentes (source, updated_at)
-- Usar schema real: id, product_id, category_id, is_primary, display_order, created_at

CREATE OR REPLACE FUNCTION public.fn_enrich_pen_categories(
    p_supplier_id       uuid    DEFAULT NULL,
    p_batch_size        integer DEFAULT 300,
    p_force_reclassify  boolean DEFAULT FALSE
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_processed     integer := 0;
    v_classified    integer := 0;
    v_skipped       integer := 0;
    v_errors        integer := 0;
    v_rec           RECORD;
    v_pen_result    jsonb;
    v_category_id   uuid;
    v_pen_category_ids uuid[];
BEGIN
    -- Pré-carregar IDs das categorias de canetas
    SELECT ARRAY_AGG(id) INTO v_pen_category_ids
    FROM categories
    WHERE (slug ILIKE 'caneta%' OR slug = 'lapiseiras')
    AND is_active = true;

    FOR v_rec IN
        SELECT p.id, p.name, p.supplier_id
        FROM products p
        WHERE p.is_active = true
        AND (
            p.name ILIKE '%caneta%'
            OR p.name ILIKE '%esferograf%'
            OR p.name ILIKE '%lapiseira%'
            OR p.name ILIKE '%roller%'
            OR p.name ILIKE '%stylus%'
        )
        AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
        AND (
            p_force_reclassify = TRUE
            OR NOT EXISTS (
                SELECT 1 FROM product_category_assignments pca
                WHERE pca.product_id = p.id
                AND pca.category_id = ANY(v_pen_category_ids)
            )
        )
        ORDER BY p.id
        LIMIT p_batch_size
    LOOP
        v_processed := v_processed + 1;

        BEGIN
            v_pen_result := classify_pen(v_rec.name);

            IF (v_pen_result->>'is_pen')::boolean = TRUE
               AND (v_pen_result->>'category_id') IS NOT NULL THEN

                v_category_id := (v_pen_result->>'category_id')::uuid;

                INSERT INTO product_category_assignments (
                    product_id,
                    category_id,
                    is_primary,
                    display_order,
                    created_at
                )
                VALUES (
                    v_rec.id,
                    v_category_id,
                    FALSE,
                    0,
                    now()
                )
                ON CONFLICT (product_id, category_id) DO NOTHING;

                v_classified := v_classified + 1;
            ELSE
                v_skipped := v_skipped + 1;
            END IF;

        EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors + 1;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'status',      'ok',
        'processed',   v_processed,
        'classified',  v_classified,
        'skipped',     v_skipped,
        'errors',      v_errors,
        'timestamp',   now()
    );
END;
$$;

COMMENT ON FUNCTION public.fn_enrich_pen_categories(uuid, integer, boolean) IS
'v2 fix (jun/2026): schema correto sem updated_at/source. Classifica canetas Gold → product_category_assignments.';

GRANT EXECUTE ON FUNCTION public.fn_enrich_pen_categories(uuid, integer, boolean) TO service_role;
;

