-- >>> BEGIN 20260611125247_update_fn_enrich_properties_batch_xbz_support.sql >>>

-- Atualizar fn_enrich_properties_batch para suportar XBZ:
-- XBZ não tem campo 'Properties'; usa concatenação Nome + Descricao
-- Também adiciona suporte a 'xbz' no lookup de supplier_id

CREATE OR REPLACE FUNCTION public.fn_enrich_properties_batch(
    p_supplier_code text    DEFAULT 'spot',
    p_batch_size    integer DEFAULT 200,
    p_force         boolean DEFAULT FALSE
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
    v_processed         integer := 0;
    v_enriched          integer := 0;
    v_skipped           integer := 0;
    v_errors            integer := 0;
    v_rec               RECORD;
    v_raw_props         text;
    v_result            jsonb;
    v_supplier_id       uuid;
    v_props_field       text;
    v_props_field2      text;   -- campo secundário (concatenado)
    v_mapping_code      text;
    v_supplier_db_code  text;
    v_use_concat        boolean := FALSE;
BEGIN
    -- Normalizar alias: spot/stricker → STRICKER
    v_supplier_db_code := CASE LOWER(p_supplier_code)
        WHEN 'spot'     THEN 'STRICKER'
        WHEN 'stricker' THEN 'STRICKER'
        WHEN 'xbz'      THEN 'XBZ'
        WHEN 'asia'     THEN 'ASIA'
        WHEN 'somarcas' THEN 'SOMARCAS'
        ELSE UPPER(p_supplier_code)
    END;

    v_mapping_code := CASE LOWER(p_supplier_code)
        WHEN 'spot'     THEN 'spot'
        WHEN 'stricker' THEN 'spot'
        ELSE LOWER(p_supplier_code)
    END;

    -- Estratégia por fornecedor:
    -- STRICKER: campo 'Properties' (texto normalizado do WS)
    -- XBZ: concatenar 'Nome' + ' ' + 'Descricao' (não tem Properties)
    CASE v_supplier_db_code
        WHEN 'STRICKER' THEN
            v_props_field  := 'Properties';
            v_props_field2 := NULL;
            v_use_concat   := FALSE;
        WHEN 'XBZ' THEN
            v_props_field  := 'Nome';
            v_props_field2 := 'Descricao';
            v_use_concat   := TRUE;
        ELSE
            v_props_field  := 'properties';
            v_props_field2 := NULL;
            v_use_concat   := FALSE;
    END CASE;

    SELECT id INTO v_supplier_id FROM suppliers WHERE code = v_supplier_db_code LIMIT 1;

    IF v_supplier_id IS NULL THEN
        RETURN jsonb_build_object('status', 'error',
            'message', 'Supplier não encontrado: ' || p_supplier_code);
    END IF;

    FOR v_rec IN
        SELECT DISTINCT ON (p.id)
            p.id        AS product_id,
            p.name      AS product_name,
            spr.raw_data AS bronze_raw
        FROM products p
        JOIN supplier_products_raw spr ON spr.product_id = p.id
        WHERE p.supplier_id = v_supplier_id
        AND p.is_active = true
        AND (
            CASE WHEN v_use_concat THEN
                (spr.raw_data ? v_props_field AND spr.raw_data->>v_props_field IS NOT NULL)
            ELSE
                (spr.raw_data ? v_props_field
                 AND spr.raw_data->>v_props_field IS NOT NULL
                 AND spr.raw_data->>v_props_field <> '')
            END
        )
        AND (
            p_force = TRUE
            OR NOT EXISTS (
                SELECT 1 FROM product_properties pp WHERE pp.product_id = p.id
                AND pp.property_code NOT LIKE 'OTHER_%'
                AND pp.property_code NOT IN ('material_xbz_primary','site_url','site_imagens_urls',
                    'gravacao_comprimento_cm','gravacao_medida','gravacao_largura_cm',
                    'site_cores_swatches','site_categoria_path','site_ficha_tecnica_pdf',
                    'circumference_cm','gravacao_local','site_video_youtube_id',
                    'site_video_watch_url','site_modo_de_uso')
            )
        )
        ORDER BY p.id
        LIMIT p_batch_size
    LOOP
        v_processed := v_processed + 1;

        BEGIN
            -- Montar texto fonte para matching
            IF v_use_concat THEN
                v_raw_props := COALESCE(v_rec.bronze_raw->>v_props_field, '')
                               || ' ' ||
                               COALESCE(v_rec.bronze_raw->>v_props_field2, '');
                v_raw_props := LOWER(TRIM(v_raw_props));
            ELSE
                v_raw_props := v_rec.bronze_raw->>v_props_field;
            END IF;

            IF LENGTH(TRIM(v_raw_props)) < 3 THEN
                v_skipped := v_skipped + 1;
                CONTINUE;
            END IF;

            v_result := fn_import_product_properties(
                p_product_id     := v_rec.product_id,
                p_raw_properties := v_raw_props,
                p_source         := 'bronze_batch_' || v_mapping_code,
                p_supplier_code  := v_mapping_code
            );

            IF (v_result->>'success')::boolean = TRUE THEN
                v_enriched := v_enriched + 1;
            ELSE
                v_skipped := v_skipped + 1;
            END IF;

        EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors + 1;
        END;
    END LOOP;

    RETURN jsonb_build_object(
        'status',        'ok',
        'supplier_code', v_mapping_code,
        'supplier_id',   v_supplier_id,
        'processed',     v_processed,
        'enriched',      v_enriched,
        'skipped',       v_skipped,
        'errors',        v_errors,
        'timestamp',     now()
    );
END;
$$;

COMMENT ON FUNCTION public.fn_enrich_properties_batch(text, integer, boolean) IS
'v3 (jun/2026): suporte XBZ via Nome+Descricao concat. 
STRICKER usa Properties. XBZ usa Nome+Descricao. Filtra propriedades custom XBZ no check de existência.';

GRANT EXECUTE ON FUNCTION public.fn_enrich_properties_batch(text, integer, boolean) TO service_role;
;

-- <<< END 20260611125247_update_fn_enrich_properties_batch_xbz_support.sql <<<

-- >>> BEGIN 20260611130544_seo_create_product_specifications.sql >>>

-- ============================================================
-- ETAPA 1: Criar tabela product_specifications
-- Necessária para: calculate_seo_score, Schema.org, SEO técnico
-- ============================================================

CREATE TABLE IF NOT EXISTS public.product_specifications (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    product_id  UUID NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
    spec_key    TEXT NOT NULL,           -- ex: 'Material', 'Capacidade', 'Dimensões'
    spec_value  TEXT NOT NULL,           -- ex: 'Aço inox 304', '500ml', '10x5x5 cm'
    spec_unit   TEXT,                    -- ex: 'ml', 'cm', 'g'
    spec_group  TEXT DEFAULT 'geral',    -- ex: 'técnica', 'embalagem', 'personalização'
    display_order INTEGER DEFAULT 0,
    is_active   BOOLEAN DEFAULT true,
    organization_id UUID DEFAULT '5db5aee1-064b-4ef4-9193-345dcd8274ea'::uuid,
    created_at  TIMESTAMPTZ DEFAULT now(),
    updated_at  TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_product_specifications_product_id
    ON public.product_specifications (product_id);

CREATE INDEX IF NOT EXISTS idx_product_specifications_group
    ON public.product_specifications (spec_group)
    WHERE is_active = true;

COMMENT ON TABLE public.product_specifications IS
    'Especificações técnicas estruturadas por produto — alimenta Schema.org e SEO técnico';
COMMENT ON COLUMN public.product_specifications.spec_key IS
    'Nome do atributo (ex: Material, Capacidade)';
COMMENT ON COLUMN public.product_specifications.spec_value IS
    'Valor do atributo (ex: Aço inox 304)';
COMMENT ON COLUMN public.product_specifications.spec_group IS
    'Grupo lógico: geral, tecnica, embalagem, personalizacao, sustentabilidade';
;

-- <<< END 20260611130544_seo_create_product_specifications.sql <<<

-- >>> BEGIN 20260611130612_seo_fix_calculate_seo_score.sql >>>

-- ============================================================
-- ETAPA 2: Corrigir calculate_seo_score
-- Fix: product_specifications agora existe (criada na etapa 1)
-- Fix: melhorar critérios de score para 7.521 produtos reais
-- ============================================================

CREATE OR REPLACE FUNCTION public.calculate_seo_score(p_product_id UUID)
RETURNS TABLE(score INTEGER, issues JSONB)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product     RECORD;
  v_score       INTEGER := 0;
  v_issues      JSONB   := '[]'::jsonb;
  v_image_count INTEGER;
  v_faq_count   INTEGER;
  v_spec_count  INTEGER;
  v_alt_count   INTEGER;
BEGIN
  -- Buscar produto
  SELECT * INTO v_product FROM products WHERE id = p_product_id;

  IF NOT FOUND THEN
    RETURN QUERY SELECT 0, '["Produto não encontrado"]'::jsonb;
    RETURN;
  END IF;

  -- === CRITÉRIO 1: NOME (10 pts) ===
  IF v_product.name IS NOT NULL AND LENGTH(TRIM(v_product.name)) >= 10 THEN
    v_score := v_score + 10;
  ELSE
    v_issues := v_issues || '["Nome muito curto (mínimo 10 caracteres)"]'::jsonb;
  END IF;

  -- === CRITÉRIO 2: SLUG (10 pts) ===
  IF v_product.slug IS NOT NULL AND LENGTH(TRIM(v_product.slug)) >= 5 THEN
    v_score := v_score + 10;
  ELSE
    v_issues := v_issues || '["Slug não definido ou muito curto"]'::jsonb;
  END IF;

  -- === CRITÉRIO 3: META TITLE (15 pts) ===
  IF v_product.meta_title IS NOT NULL AND LENGTH(TRIM(v_product.meta_title)) > 0 THEN
    v_score := v_score + 10;
    IF LENGTH(v_product.meta_title) BETWEEN 30 AND 70 THEN
      v_score := v_score + 5;
    ELSE
      v_issues := v_issues || '["Meta title fora do tamanho ideal (30-70 chars)"]'::jsonb;
    END IF;
  ELSE
    v_issues := v_issues || '["Meta title não definido"]'::jsonb;
  END IF;

  -- === CRITÉRIO 4: META DESCRIPTION (15 pts) ===
  IF v_product.meta_description IS NOT NULL AND LENGTH(TRIM(v_product.meta_description)) > 0 THEN
    v_score := v_score + 10;
    IF LENGTH(v_product.meta_description) BETWEEN 100 AND 170 THEN
      v_score := v_score + 5;
    ELSE
      v_issues := v_issues || '["Meta description fora do tamanho ideal (100-170 chars)"]'::jsonb;
    END IF;
  ELSE
    v_issues := v_issues || '["Meta description não definida"]'::jsonb;
  END IF;

  -- === CRITÉRIO 5: DESCRIPTION (15 pts) ===
  IF v_product.description IS NOT NULL AND LENGTH(TRIM(v_product.description)) > 0 THEN
    IF LENGTH(v_product.description) >= 300 THEN
      v_score := v_score + 15;
    ELSIF LENGTH(v_product.description) >= 100 THEN
      v_score := v_score + 10;
      v_issues := v_issues || '["Descrição poderia ser mais detalhada (ideal 300+ chars)"]'::jsonb;
    ELSE
      v_score := v_score + 5;
      v_issues := v_issues || '["Descrição muito curta (ideal 300+ chars)"]'::jsonb;
    END IF;
  ELSE
    v_issues := v_issues || '["Descrição não definida"]'::jsonb;
  END IF;

  -- === CRITÉRIO 6: SHORT DESCRIPTION (5 pts) ===
  IF v_product.short_description IS NOT NULL
     AND LENGTH(TRIM(v_product.short_description)) >= 30 THEN
    v_score := v_score + 5;
  ELSE
    v_issues := v_issues || '["Descrição curta não definida ou muito breve (ideal 30+ chars)"]'::jsonb;
  END IF;

  -- === CRITÉRIO 7: AI SUMMARY — GEO/LLM SEO (5 pts) ===
  IF v_product.ai_summary IS NOT NULL AND LENGTH(TRIM(v_product.ai_summary)) >= 100 THEN
    v_score := v_score + 5;
  END IF;

  -- === CRITÉRIO 8: IMAGENS (15 pts) ===
  SELECT COUNT(*) INTO v_image_count
  FROM product_images
  WHERE product_id = p_product_id AND is_active = true;

  IF v_image_count >= 5 THEN
    v_score := v_score + 15;
  ELSIF v_image_count >= 3 THEN
    v_score := v_score + 10;
    v_issues := v_issues || '["Adicionar mais imagens (ideal 5+)"]'::jsonb;
  ELSIF v_image_count >= 1 THEN
    v_score := v_score + 5;
    v_issues := v_issues || '["Poucas imagens (ideal 5+)"]'::jsonb;
  ELSE
    v_issues := v_issues || '["Sem imagens cadastradas"]'::jsonb;
  END IF;

  -- === CRITÉRIO 9: ALT TEXT NAS IMAGENS (3 pts bônus) ===
  IF v_image_count > 0 THEN
    SELECT COUNT(*) INTO v_alt_count
    FROM product_images
    WHERE product_id = p_product_id AND is_active = true AND alt_text IS NOT NULL;
    IF v_alt_count = v_image_count THEN
      v_score := v_score + 3;
    END IF;
  END IF;

  -- === CRITÉRIO 10: FAQs (5 pts) ===
  SELECT COUNT(*) INTO v_faq_count
  FROM product_faqs
  WHERE product_id = p_product_id AND is_active = true;

  IF v_faq_count >= 3 THEN
    v_score := v_score + 5;
  ELSIF v_faq_count >= 1 THEN
    v_score := v_score + 3;
  END IF;

  -- === CRITÉRIO 11: ESPECIFICAÇÕES TÉCNICAS (5 pts) ===
  SELECT COUNT(*) INTO v_spec_count
  FROM product_specifications
  WHERE product_id = p_product_id AND is_active = true;

  IF v_spec_count >= 5 THEN
    v_score := v_score + 5;
  ELSIF v_spec_count >= 1 THEN
    v_score := v_score + 3;
  END IF;

  -- === CRITÉRIO 12: SCHEMA JSON (2 pts bônus) ===
  IF v_product.schema_json IS NOT NULL THEN
    v_score := v_score + 2;
  END IF;

  -- Garantir limites 0-100
  v_score := LEAST(GREATEST(v_score, 0), 100);

  RETURN QUERY SELECT v_score, v_issues;
END;
$$;

COMMENT ON FUNCTION public.calculate_seo_score(UUID) IS
    'Calcula score SEO 0-100 de um produto. Critérios: nome, slug, meta_title, meta_description, description, short_description, ai_summary, imagens, alt_text, FAQs, specs, schema_json';
;

-- <<< END 20260611130612_seo_fix_calculate_seo_score.sql <<<

-- >>> BEGIN 20260611130631_seo_fix_fn_update_all_seo_scores.sql >>>

-- ============================================================
-- ETAPA 3: Corrigir fn_update_all_seo_scores
-- Bug: acessava v_score_result.result->>'score' (field inexistente)
-- Fix: v_score_result.score e v_score_result.issues (tipos corretos)
-- Melhoria: batch UPDATE em vez de loop individual (performance)
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_update_all_seo_scores(
    p_only_stale BOOLEAN DEFAULT false,  -- true = só recalcula quem não foi auditado nas últimas 24h
    p_supplier_id UUID DEFAULT NULL      -- NULL = todos os fornecedores
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_updated   INTEGER := 0;
  v_errors    INTEGER := 0;
  v_start     TIMESTAMPTZ := clock_timestamp();
  r           RECORD;
  v_score     INTEGER;
  v_issues    JSONB;
BEGIN
  FOR r IN
    SELECT id FROM products
    WHERE is_deleted = false
      AND is_active  = true
      AND (p_supplier_id IS NULL OR supplier_id = p_supplier_id)
      AND (
        NOT p_only_stale
        OR seo_last_audit_at IS NULL
        OR seo_last_audit_at < now() - INTERVAL '24 hours'
      )
    ORDER BY seo_last_audit_at ASC NULLS FIRST  -- prioriza nunca auditados
  LOOP
    BEGIN
      -- ⚡ FIX PRINCIPAL: usar .score e .issues diretamente (não .result)
      SELECT s.score, s.issues
        INTO v_score, v_issues
        FROM calculate_seo_score(r.id) s;

      UPDATE products
         SET seo_score        = v_score,
             seo_issues       = v_issues,
             seo_last_audit_at = now()
       WHERE id = r.id;

      v_updated := v_updated + 1;

    EXCEPTION WHEN OTHERS THEN
      -- Produto individual falhou — não aborta o lote
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success',          (v_errors = 0),
    'products_scored',  v_updated,
    'errors',           v_errors,
    'duration_ms',      EXTRACT(MILLISECONDS FROM (clock_timestamp() - v_start))::INTEGER
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error',   SQLERRM,
    'state',   SQLSTATE
  );
END;
$$;

COMMENT ON FUNCTION public.fn_update_all_seo_scores(BOOLEAN, UUID) IS
    'Recalcula seo_score de todos os produtos Gold. p_only_stale=true recalcula só quem não foi auditado nas últimas 24h. p_supplier_id filtra por fornecedor.';
;

-- <<< END 20260611130631_seo_fix_fn_update_all_seo_scores.sql <<<

-- >>> BEGIN 20260611130645_create_product_novelties_table.sql >>>

-- ══════════════════════════════════════════════════════════════════
-- MIGRATION: product_novelties — tabela de controle do selo "NOVO"
-- Arquitetura Medallion — camada Gold (referencia products.id)
-- ══════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS public.product_novelties (
    id                      uuid        NOT NULL DEFAULT gen_random_uuid(),
    product_id              uuid        NOT NULL,
    supplier_id             uuid,
    supplier_code           text,
    supplier_product_code   text,

    -- Origem da detecção (G-10: enum expandido via CHECK)
    source                  text        NOT NULL
        CONSTRAINT chk_pn_source CHECK (source IN (
            'manual',               -- marcado manualmente pelo usuário
            'import',               -- importação em lote
            'pipeline_auto',        -- detecção genérica pelo pipeline (qualquer fornecedor)
            'spot_new_product',     -- flag NewProduct=true da Stricker (OptionalsComplete)
            'spot_catalogo_novidades', -- Catalogs contém "Novidades" (catálogo ID=5)
            'xbz_recently_promoted',  -- produto XBZ promovido nos últimos N dias
            'asia_recently_promoted', -- produto ASIA promovido nos últimos N dias
            'sm_recently_promoted',   -- produto SOMARCAS promovido nos últimos N dias
            '88brindes_recently_promoted' -- produto 88BRINDES promovido recentemente
        )),

    -- Ciclo de vida do selo
    detected_at             timestamptz NOT NULL DEFAULT now(),
    expires_at              timestamptz,          -- NULL = não expira automaticamente
    is_active               boolean     NOT NULL DEFAULT true,
    is_highlighted          boolean     NOT NULL DEFAULT false, -- destaque home (só curadoria manual)

    -- Auditoria
    notes                   text,
    created_by              uuid,                 -- FK para profiles (nullable = criado pelo sistema)
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),  -- G-06: campo que faltava no doc

    CONSTRAINT pk_product_novelties PRIMARY KEY (id),
    CONSTRAINT fk_pn_product   FOREIGN KEY (product_id)  REFERENCES public.products(id)  ON DELETE CASCADE,
    CONSTRAINT fk_pn_supplier  FOREIGN KEY (supplier_id) REFERENCES public.suppliers(id) ON DELETE SET NULL,
    CONSTRAINT fk_pn_created_by FOREIGN KEY (created_by) REFERENCES public.profiles(id)  ON DELETE SET NULL,

    -- Expiração não pode ser anterior à detecção
    CONSTRAINT chk_pn_expires_after_detected
        CHECK (expires_at IS NULL OR expires_at > detected_at)
);

-- ── Índices de performance ────────────────────────────────────────
-- Busca principal: novidades ativas
CREATE INDEX IF NOT EXISTS idx_pn_product_active
    ON public.product_novelties(product_id)
    WHERE is_active = true;

-- Busca por expiração (CRON de cleanup)
CREATE INDEX IF NOT EXISTS idx_pn_expires
    ON public.product_novelties(expires_at)
    WHERE is_active = true AND expires_at IS NOT NULL;

-- Busca por fornecedor
CREATE INDEX IF NOT EXISTS idx_pn_supplier
    ON public.product_novelties(supplier_id)
    WHERE is_active = true;

-- Busca por fonte (métricas)
CREATE INDEX IF NOT EXISTS idx_pn_source
    ON public.product_novelties(source, is_active);

-- Destaques para home
CREATE INDEX IF NOT EXISTS idx_pn_highlighted
    ON public.product_novelties(is_highlighted, detected_at DESC)
    WHERE is_active = true AND is_highlighted = true;

-- G-07: PARTIAL UNIQUE — garante no máximo 1 registro ATIVO por produto
-- (permite histórico: produto pode ter múltiplos registros, mas só 1 ativo)
CREATE UNIQUE INDEX IF NOT EXISTS uq_pn_product_one_active
    ON public.product_novelties(product_id)
    WHERE is_active = true;

-- ── Comentários de documentação ──────────────────────────────────
COMMENT ON TABLE public.product_novelties IS
    'Controla o ciclo de vida do selo "NOVO" nos produtos. '
    'Camada Gold — referencia products.id. '
    'Pipeline popula via fn_sync_product_novelties(); curadoria manual via is_highlighted. '
    'Máx. 1 registro ATIVO por produto (partial unique index). Histórico preservado.';

COMMENT ON COLUMN public.product_novelties.is_highlighted IS
    'TRUE = produto aparece em destaque na home. APENAS curadoria manual — nunca automático pelo pipeline.';
COMMENT ON COLUMN public.product_novelties.source IS
    'Origem da detecção. pipeline_auto/spot_*/xbz_*/asia_*/sm_* = automático. manual/import = humano.';
COMMENT ON COLUMN public.product_novelties.expires_at IS
    'NULL = não expira automaticamente. fn_expire_novelties() atualiza is_active=false quando vencido.';

-- ── G-11: RLS + GRANTs ──────────────────────────────────────────
ALTER TABLE public.product_novelties ENABLE ROW LEVEL SECURITY;

-- service_role: acesso total (pipeline, funções internas)
CREATE POLICY pn_service_role_all
    ON public.product_novelties
    FOR ALL
    TO service_role
    USING (true)
    WITH CHECK (true);

-- authenticated: leitura de registros ativos (catálogo front-end)
CREATE POLICY pn_authenticated_select_active
    ON public.product_novelties
    FOR SELECT
    TO authenticated
    USING (is_active = true);

-- anon: leitura pública de registros ativos (SSR / API pública)
CREATE POLICY pn_anon_select_active
    ON public.product_novelties
    FOR SELECT
    TO anon
    USING (is_active = true);

GRANT SELECT               ON public.product_novelties TO anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.product_novelties TO service_role;
;

-- <<< END 20260611130645_create_product_novelties_table.sql <<<

-- >>> BEGIN 20260611130705_seo_fix_fn_populate_all_products_seo.sql >>>

-- ============================================================
-- ETAPA 4: Corrigir fn_populate_all_products_seo
-- Bug B3: LENGTH(TRIM(COALESCE(meta_keywords,''))) em TEXT[] → inválido
-- Fix: array_length(meta_keywords, 1) IS NULL
-- Melhoria: popular og_image_url, canonical_url, schema_json stub
-- Melhoria: parâmetro p_supplier_id para processar por fornecedor
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_populate_all_products_seo(
    p_supplier_id UUID DEFAULT NULL,   -- NULL = todos; uuid = só este fornecedor
    p_force       BOOLEAN DEFAULT false -- true = reprocessa mesmo quem já tem slug
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_products_updated   INTEGER := 0;
  v_images_updated     INTEGER := 0;
  v_categories_updated INTEGER := 0;
  v_start_time         TIMESTAMPTZ := clock_timestamp();
BEGIN

  -- ===========================================================
  -- 1. SLUG — gerar apenas onde NULL (ou forçar)
  -- ===========================================================
  UPDATE products p
     SET slug = generate_product_slug(p.name, p.id)
   WHERE (p_force OR p.slug IS NULL OR LENGTH(TRIM(COALESCE(p.slug, ''))) = 0)
     AND p.name IS NOT NULL
     AND p.is_deleted = false
     AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
     AND 'slug' != ALL(COALESCE(p.locked_fields, '{}'::text[]));  -- respeita locked_fields

  -- ===========================================================
  -- 2. META TITLE
  -- ===========================================================
  UPDATE products p
     SET meta_title = generate_product_meta_title(
           p.name,
           (SELECT c.name FROM categories c
            WHERE c.id = COALESCE(p.main_category_id, p.category_id) LIMIT 1)
         )
   WHERE (p_force OR p.meta_title IS NULL OR LENGTH(TRIM(COALESCE(p.meta_title, ''))) = 0)
     AND p.name IS NOT NULL
     AND p.is_deleted = false
     AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
     AND 'meta_title' != ALL(COALESCE(p.locked_fields, '{}'::text[]));

  -- ===========================================================
  -- 3. META DESCRIPTION
  -- ===========================================================
  UPDATE products p
     SET meta_description = generate_product_meta_description(
           p.name, p.short_description, p.description,
           COALESCE(p.allows_personalization, false)
         )
   WHERE (p_force OR p.meta_description IS NULL OR LENGTH(TRIM(COALESCE(p.meta_description, ''))) = 0)
     AND p.name IS NOT NULL
     AND p.is_deleted = false
     AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
     AND 'meta_description' != ALL(COALESCE(p.locked_fields, '{}'::text[]));

  -- ===========================================================
  -- 4. META KEYWORDS — FIX: usar array_length em TEXT[], não LENGTH()
  -- ===========================================================
  UPDATE products p
     SET meta_keywords = extract_keywords(
           COALESCE(p.name, '') || ' ' ||
           COALESCE(p.short_description, '') || ' ' ||
           COALESCE(p.description, '') || ' ' ||
           'brinde promocional brinde corporativo brinde personalizado',
           15
         )
   WHERE (p_force OR p.meta_keywords IS NULL
         OR array_length(p.meta_keywords, 1) IS NULL
         OR array_length(p.meta_keywords, 1) = 0)
     AND p.name IS NOT NULL
     AND p.is_deleted = false
     AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id);

  -- ===========================================================
  -- 5. CANONICAL_URL
  -- ===========================================================
  UPDATE products p
     SET canonical_url = '/produto/' || p.slug
   WHERE (p_force OR p.canonical_url IS NULL)
     AND p.slug IS NOT NULL
     AND p.is_deleted = false
     AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id);

  -- ===========================================================
  -- 6. OG_TITLE (herda meta_title se NULL)
  -- ===========================================================
  UPDATE products p
     SET og_title = p.meta_title
   WHERE (p_force OR p.og_title IS NULL)
     AND p.meta_title IS NOT NULL
     AND p.is_deleted = false
     AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id);

  -- ===========================================================
  -- 7. OG_DESCRIPTION (herda meta_description se NULL)
  -- ===========================================================
  UPDATE products p
     SET og_description = p.meta_description
   WHERE (p_force OR p.og_description IS NULL)
     AND p.meta_description IS NOT NULL
     AND p.is_deleted = false
     AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id);

  -- ===========================================================
  -- 8. OG_IMAGE_URL (herda primary_image_url se NULL)
  -- ===========================================================
  UPDATE products p
     SET og_image_url = p.primary_image_url
   WHERE (p_force OR p.og_image_url IS NULL)
     AND p.primary_image_url IS NOT NULL
     AND p.is_deleted = false
     AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id);

  -- ===========================================================
  -- 9. CONTAR produtos com SEO preenchido
  -- ===========================================================
  SELECT COUNT(*) INTO v_products_updated
  FROM products
  WHERE slug IS NOT NULL AND is_deleted = false
    AND (p_supplier_id IS NULL OR supplier_id = p_supplier_id);

  -- ===========================================================
  -- 10. ALT_TEXT EM product_images (apenas imagens sem alt_text)
  -- ===========================================================
  UPDATE product_images pi
     SET
       alt_text   = generate_image_alt_text(
                      (SELECT p.name FROM products p WHERE p.id = pi.product_id),
                      COALESCE(pi.image_type, 'gallery'),
                      (SELECT cv.name FROM color_variations cv WHERE cv.id = pi.color_id),
                      COALESCE(pi.display_order, 1)
                    ),
       title_text = (SELECT p.name FROM products p WHERE p.id = pi.product_id) ||
                    COALESCE(' - ' || (SELECT cv.name FROM color_variations cv WHERE cv.id = pi.color_id), '')
   WHERE (p_force OR pi.alt_text IS NULL OR LENGTH(TRIM(COALESCE(pi.alt_text, ''))) = 0)
     AND pi.product_id IS NOT NULL
     AND (p_supplier_id IS NULL OR EXISTS (
       SELECT 1 FROM products p2
       WHERE p2.id = pi.product_id AND p2.supplier_id = p_supplier_id
     ));

  GET DIAGNOSTICS v_images_updated = ROW_COUNT;

  -- ===========================================================
  -- 11. CATEGORIES SEO
  -- ===========================================================
  UPDATE categories c
     SET
       meta_title = COALESCE(c.meta_title,
                      c.name || ' - Brindes Promocionais | Promo Brindes'),
       meta_description = COALESCE(c.meta_description,
                      'Encontre os melhores ' || LOWER(c.name) ||
                      ' para brindes corporativos e eventos. ' ||
                      'Personalização com sua marca. Solicite orçamento!')
   WHERE (c.meta_title IS NULL OR c.meta_description IS NULL)
     AND c.is_active = true;

  GET DIAGNOSTICS v_categories_updated = ROW_COUNT;

  -- ===========================================================
  -- RETORNO
  -- ===========================================================
  RETURN jsonb_build_object(
    'success',            true,
    'products_with_seo',  v_products_updated,
    'images_updated',     v_images_updated,
    'categories_updated', v_categories_updated,
    'supplier_filter',    p_supplier_id,
    'forced',             p_force,
    'duration_ms',        EXTRACT(MILLISECONDS FROM (clock_timestamp() - v_start_time))::INTEGER
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'success', false,
    'error',   SQLERRM,
    'state',   SQLSTATE
  );
END;
$$;

COMMENT ON FUNCTION public.fn_populate_all_products_seo(UUID, BOOLEAN) IS
    'Popula campos SEO em products, product_images e categories. p_supplier_id filtra fornecedor. p_force=true reprocessa mesmo quem já tem slug. Respeita locked_fields.';
;

-- <<< END 20260611130705_seo_fix_fn_populate_all_products_seo.sql <<<

-- >>> BEGIN 20260611130708_create_product_novelties_triggers.sql >>>

-- ══════════════════════════════════════════════════════════════════
-- TRIGGER 1: updated_at automático em product_novelties (G-06)
-- ══════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_pn_set_updated_at()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_pn_updated_at ON public.product_novelties;
CREATE TRIGGER trg_pn_updated_at
    BEFORE UPDATE ON public.product_novelties
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_pn_set_updated_at();

-- ══════════════════════════════════════════════════════════════════
-- TRIGGER 2: sincroniza products.is_new / novelty_* (G-04)
-- Dispara em INSERT, UPDATE e DELETE na product_novelties.
-- Mantém products como reflexo fiel do estado de novelties.
-- ══════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_pn_sync_products_is_new()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_product_id uuid;
    v_active     boolean;
    v_detected   timestamptz;
    v_expires    timestamptz;
BEGIN
    -- Determina o product_id afetado em qualquer operação
    v_product_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.product_id ELSE NEW.product_id END;

    -- Busca o estado ATIVO mais recente para este produto
    -- (pode vir de qualquer fonte — respeita a hierarquia: is_active=true prevalece)
    SELECT
        pn.is_active,
        pn.detected_at,
        pn.expires_at
    INTO v_active, v_detected, v_expires
    FROM public.product_novelties pn
    WHERE pn.product_id = v_product_id
      AND pn.is_active  = true
    ORDER BY pn.detected_at DESC
    LIMIT 1;

    -- Se nenhum registro ativo encontrado → limpar flag no Gold
    IF NOT FOUND THEN
        UPDATE public.products
        SET
            is_new              = false,
            novelty_detected_at = NULL,
            novelty_expires_at  = NULL,
            updated_at          = now()
        WHERE id = v_product_id;
    ELSE
        -- Sincroniza Gold com o estado ativo da novelty
        UPDATE public.products
        SET
            is_new              = v_active,
            novelty_detected_at = v_detected,
            novelty_expires_at  = v_expires,
            updated_at          = now()
        WHERE id = v_product_id;
    END IF;

    -- Retorno padrão para triggers AFTER
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.fn_pn_sync_products_is_new() IS
    'Trigger: sincroniza products.is_new / novelty_detected_at / novelty_expires_at '
    'sempre que product_novelties muda (INSERT/UPDATE/DELETE). '
    'Garante que o Gold reflete o estado real do módulo de novidades.';

DROP TRIGGER IF EXISTS trg_pn_sync_products ON public.product_novelties;
CREATE TRIGGER trg_pn_sync_products
    AFTER INSERT OR UPDATE OR DELETE ON public.product_novelties
    FOR EACH ROW
    EXECUTE FUNCTION public.fn_pn_sync_products_is_new();
;

-- <<< END 20260611130708_create_product_novelties_triggers.sql <<<

-- >>> BEGIN 20260611130729_create_fn_expire_novelties.sql >>>

-- ══════════════════════════════════════════════════════════════════
-- fn_expire_novelties(): expira novidades vencidas (G-03)
-- Atua em DUAS frentes:
--   1. product_novelties: is_active=false quando expires_at < now()
--   2. products: is_new=false quando novelty_expires_at < now()
--      (cobre produtos com flags diretos mas sem registro em product_novelties)
-- Advisory lock: 74108912 (evita corrida com outras chamadas)
-- ══════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_expire_novelties()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_novelties_expired   int := 0;
    v_products_fixed      int := 0;
    v_result              jsonb;
BEGIN
    -- Advisory lock: só uma instância roda por vez
    IF NOT pg_try_advisory_xact_lock(74108912) THEN
        RETURN jsonb_build_object(
            'status',  'skipped',
            'reason',  'advisory_lock_busy',
            'ts',      now()
        );
    END IF;

    -- ── Frente 1: product_novelties com expires_at vencido ──────
    WITH expired AS (
        UPDATE public.product_novelties
        SET    is_active  = false,
               updated_at = now()
        WHERE  is_active   = true
          AND  expires_at  IS NOT NULL
          AND  expires_at  < now()
        RETURNING product_id
    )
    SELECT COUNT(*) INTO v_novelties_expired FROM expired;

    -- ── Frente 2: products.is_new orphans (sem product_novelties) ─
    -- Cobre o legado: produtos que tinham is_new=true direto no Gold
    -- mas novelty_expires_at já passou (os 127 stale da STRICKER)
    WITH stale_products AS (
        UPDATE public.products
        SET    is_new              = false,
               novelty_detected_at = NULL,
               novelty_expires_at  = NULL,
               updated_at          = now()
        WHERE  is_new            = true
          AND  novelty_expires_at IS NOT NULL
          AND  novelty_expires_at < now()
          -- Não tem registro ativo em product_novelties
          AND  NOT EXISTS (
                SELECT 1 FROM public.product_novelties pn
                WHERE  pn.product_id = products.id
                  AND  pn.is_active  = true
          )
        RETURNING id
    )
    SELECT COUNT(*) INTO v_products_fixed FROM stale_products;

    v_result := jsonb_build_object(
        'status',                 'ok',
        'novelties_expired',      v_novelties_expired,
        'products_stale_fixed',   v_products_fixed,
        'total_actions',          v_novelties_expired + v_products_fixed,
        'ran_at',                 now()
    );

    RETURN v_result;
END;
$$;

COMMENT ON FUNCTION public.fn_expire_novelties() IS
    'Expira novidades vencidas em DUAS frentes: product_novelties e products.is_new orphans. '
    'Complementa a Edge Function cleanup-novelties. Advisory lock 74108912. '
    'Retorna JSON com contagens de ações realizadas.';

REVOKE ALL ON FUNCTION public.fn_expire_novelties() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_expire_novelties() TO service_role;
;

-- <<< END 20260611130729_create_fn_expire_novelties.sql <<<

