-- ============================================================
-- ETAPA 5: Recriar views SEO (v3 — correções + melhorias)
-- Fix B4: adicionar is_deleted = false em vw_sitemap_products
-- Melhoria: supplier_reference, ai_title, schema_json coverage
-- ============================================================

-- Drop em ordem de dependência
DROP VIEW IF EXISTS public.vw_seo_dashboard          CASCADE;
DROP VIEW IF EXISTS public.vw_products_seo_status    CASCADE;
DROP VIEW IF EXISTS public.vw_sitemap_all            CASCADE;
DROP VIEW IF EXISTS public.vw_sitemap_categories     CASCADE;
DROP VIEW IF EXISTS public.vw_sitemap_products       CASCADE;

-- ============================================================
-- VIEW 1: vw_sitemap_products  (FIX: + is_deleted = false)
-- ============================================================
CREATE VIEW public.vw_sitemap_products AS
SELECT
    'product'::text AS url_type,
    '/produto/' || COALESCE(slug, id::text) AS url_path,
    COALESCE(slug, id::text)               AS identifier,
    name                                   AS title,
    supplier_reference,
    updated_at                             AS lastmod,
    CASE
        WHEN is_featured     = true THEN 1.0
        WHEN is_bestseller   = true THEN 0.9
        WHEN is_new          = true THEN 0.8
        ELSE 0.7
    END AS priority,
    CASE
        WHEN is_featured = true OR is_bestseller = true THEN 'daily'
        ELSE 'weekly'
    END AS changefreq,
    COALESCE(primary_image_url, og_image_url) AS image_url,
    COALESCE(meta_title, name)             AS image_title,
    COALESCE(seo_score, 0)                 AS seo_score
FROM products
WHERE is_active  = true
  AND is_deleted = false
  AND (robots_meta IS NULL OR robots_meta NOT LIKE '%noindex%')
ORDER BY priority DESC, updated_at DESC;

COMMENT ON VIEW public.vw_sitemap_products IS
    'v3 — Dados para sitemap XML de produtos. Corrigido: is_deleted=false';

-- ============================================================
-- VIEW 2: vw_sitemap_categories
-- ============================================================
CREATE VIEW public.vw_sitemap_categories AS
SELECT
    'category'::text AS url_type,
    '/categoria/' || slug AS url_path,
    slug               AS identifier,
    name               AS title,
    updated_at         AS lastmod,
    COALESCE(seo_priority,
        CASE
            WHEN level = 1 THEN 0.9
            WHEN level = 2 THEN 0.8
            ELSE 0.7
        END
    ) AS priority,
    'weekly'::text AS changefreq,
    image_url,
    COALESCE(meta_title, name) AS title_seo,
    products_count
FROM categories
WHERE is_active  = true
  AND is_visible = true
  AND slug IS NOT NULL
ORDER BY level ASC, priority DESC, name ASC;

COMMENT ON VIEW public.vw_sitemap_categories IS
    'v3 — Dados para sitemap XML de categorias';

-- ============================================================
-- VIEW 3: vw_sitemap_all
-- ============================================================
CREATE VIEW public.vw_sitemap_all AS
SELECT url_type, url_path, identifier, title, lastmod, priority, changefreq, image_url
FROM public.vw_sitemap_products
UNION ALL
SELECT url_type, url_path, identifier, title, lastmod, priority, changefreq, image_url
FROM public.vw_sitemap_categories
ORDER BY priority DESC, lastmod DESC;

COMMENT ON VIEW public.vw_sitemap_all IS
    'v3 — União produtos + categorias para sitemap XML completo';

-- ============================================================
-- VIEW 4: vw_products_seo_status  (melhorada: ai_title, schema_json)
-- ============================================================
CREATE VIEW public.vw_products_seo_status AS
SELECT
    p.id,
    p.name,
    p.sku,
    p.supplier_reference,
    p.slug,
    s.name AS supplier_name,

    -- Indicadores binários
    CASE WHEN p.slug IS NOT NULL AND LENGTH(TRIM(p.slug)) > 0       THEN '✅' ELSE '❌' END AS has_slug,
    CASE WHEN p.meta_title IS NOT NULL AND LENGTH(TRIM(p.meta_title)) > 0 THEN '✅' ELSE '❌' END AS has_meta_title,
    CASE WHEN p.meta_description IS NOT NULL AND LENGTH(TRIM(p.meta_description)) > 0 THEN '✅' ELSE '❌' END AS has_meta_description,
    CASE
        WHEN LENGTH(COALESCE(p.description, '')) >= 300 THEN '✅'
        WHEN LENGTH(COALESCE(p.description, '')) >= 100 THEN '🟡'
        ELSE '❌'
    END AS has_good_description,
    CASE WHEN p.ai_title IS NOT NULL AND LENGTH(TRIM(p.ai_title)) > 0 THEN '✅' ELSE '❌' END AS has_ai_title,
    CASE WHEN p.ai_summary IS NOT NULL AND LENGTH(TRIM(p.ai_summary)) > 0 THEN '✅' ELSE '❌' END AS has_ai_summary,
    CASE WHEN p.schema_json IS NOT NULL THEN '✅' ELSE '❌' END AS has_schema_json,

    -- Tamanhos
    LENGTH(COALESCE(p.meta_title, ''))       AS meta_title_length,
    LENGTH(COALESCE(p.meta_description, '')) AS meta_description_length,
    LENGTH(COALESCE(p.description, ''))      AS description_length,

    -- Imagens
    (SELECT COUNT(*)
     FROM product_images
     WHERE product_id = p.id AND is_active = true)              AS image_count,
    (SELECT COUNT(*)
     FROM product_images
     WHERE product_id = p.id AND is_active = true AND alt_text IS NOT NULL) AS images_with_alt,

    -- Score
    COALESCE(p.seo_score, 0) AS seo_score,
    CASE
        WHEN COALESCE(p.seo_score, 0) >= 80 THEN '🟢 Ótimo'
        WHEN COALESCE(p.seo_score, 0) >= 60 THEN '🟡 Bom'
        WHEN COALESCE(p.seo_score, 0) >= 40 THEN '🟠 Regular'
        ELSE '🔴 Ruim'
    END AS seo_status,

    p.updated_at,
    p.seo_last_audit_at
FROM products p
LEFT JOIN suppliers s ON s.id = p.supplier_id
WHERE p.is_active  = true
  AND p.is_deleted = false
ORDER BY COALESCE(p.seo_score, 0) ASC, p.name;

COMMENT ON VIEW public.vw_products_seo_status IS
    'v3 — Dashboard visual SEO por produto. Inclui ai_title, ai_summary, schema_json, supplier_reference';

-- ============================================================
-- VIEW 5: vw_seo_dashboard  (melhorada: ai_title, schema_json)
-- ============================================================
CREATE VIEW public.vw_seo_dashboard AS
WITH product_stats AS (
    SELECT
        COUNT(*)                                                           AS total_products,
        COUNT(*) FILTER (WHERE slug IS NOT NULL AND LENGTH(TRIM(slug)) > 0) AS with_slug,
        COUNT(*) FILTER (WHERE meta_title IS NOT NULL AND LENGTH(TRIM(meta_title)) > 0) AS with_meta_title,
        COUNT(*) FILTER (WHERE meta_description IS NOT NULL AND LENGTH(TRIM(meta_description)) > 0) AS with_meta_description,
        COUNT(*) FILTER (WHERE LENGTH(COALESCE(description,'')) >= 300)     AS with_good_description,
        COUNT(*) FILTER (WHERE ai_summary IS NOT NULL AND LENGTH(TRIM(ai_summary)) > 0) AS with_ai_summary,
        COUNT(*) FILTER (WHERE ai_title IS NOT NULL AND LENGTH(TRIM(ai_title)) > 0) AS with_ai_title,
        COUNT(*) FILTER (WHERE schema_json IS NOT NULL)                     AS with_schema_json,
        ROUND(AVG(COALESCE(seo_score, 0)), 1)                              AS avg_seo_score,
        COUNT(*) FILTER (WHERE COALESCE(seo_score, 0) >= 80)               AS excellent_seo,
        COUNT(*) FILTER (WHERE COALESCE(seo_score, 0) >= 60 AND COALESCE(seo_score, 0) < 80) AS good_seo,
        COUNT(*) FILTER (WHERE COALESCE(seo_score, 0) >= 40 AND COALESCE(seo_score, 0) < 60) AS fair_seo,
        COUNT(*) FILTER (WHERE COALESCE(seo_score, 0) < 40)                AS poor_seo
    FROM products
    WHERE is_active = true AND is_deleted = false
),
category_stats AS (
    SELECT
        COUNT(*) AS total_categories,
        COUNT(*) FILTER (WHERE meta_title IS NOT NULL)       AS with_meta_title,
        COUNT(*) FILTER (WHERE meta_description IS NOT NULL) AS with_meta_description,
        COUNT(*) FILTER (WHERE ai_summary IS NOT NULL)       AS with_ai_summary
    FROM categories
    WHERE is_active = true
),
image_stats AS (
    SELECT
        COUNT(*) AS total_images,
        COUNT(*) FILTER (WHERE alt_text IS NOT NULL AND LENGTH(TRIM(alt_text)) > 0) AS with_alt_text
    FROM product_images
    WHERE is_active = true
)
SELECT
    'produtos'::text AS entidade,
    p.total_products AS total,
    ROUND(p.with_slug          * 100.0 / NULLIF(p.total_products, 0), 1) AS pct_com_slug,
    ROUND(p.with_meta_title    * 100.0 / NULLIF(p.total_products, 0), 1) AS pct_com_meta_title,
    ROUND(p.with_meta_description * 100.0 / NULLIF(p.total_products, 0), 1) AS pct_com_meta_description,
    ROUND(p.with_ai_title      * 100.0 / NULLIF(p.total_products, 0), 1) AS pct_com_ai_title,
    ROUND(p.with_ai_summary    * 100.0 / NULLIF(p.total_products, 0), 1) AS pct_com_ai_summary,
    ROUND(p.with_schema_json   * 100.0 / NULLIF(p.total_products, 0), 1) AS pct_com_schema_json,
    p.avg_seo_score                                                        AS score_medio,
    p.excellent_seo || ' 🟢 | ' || p.good_seo || ' 🟡 | ' || p.fair_seo || ' 🟠 | ' || p.poor_seo || ' 🔴' AS distribuicao_scores
FROM product_stats p

UNION ALL

SELECT
    'categorias'::text, c.total_categories,
    NULL, -- pct_com_slug
    ROUND(c.with_meta_title       * 100.0 / NULLIF(c.total_categories, 0), 1),
    ROUND(c.with_meta_description * 100.0 / NULLIF(c.total_categories, 0), 1),
    NULL, -- pct_com_ai_title
    ROUND(c.with_ai_summary       * 100.0 / NULLIF(c.total_categories, 0), 1),
    NULL, NULL, NULL
FROM category_stats c

UNION ALL

SELECT
    'imagens'::text, i.total_images,
    NULL, NULL, NULL, NULL,
    ROUND(i.with_alt_text * 100.0 / NULLIF(i.total_images, 0), 1),
    NULL, NULL,
    i.with_alt_text || ' de ' || i.total_images || ' com alt text'
FROM image_stats i;

COMMENT ON VIEW public.vw_seo_dashboard IS
    'v3 — Dashboard executivo: produtos, categorias, imagens. Inclui ai_title, ai_summary, schema_json coverage';
;

-- <<< END 20260611130808_seo_recreate_views_v3.sql <<<

-- >>> BEGIN 20260611130830_create_fn_sync_product_novelties.sql >>>

-- ══════════════════════════════════════════════════════════════════
-- fn_sync_product_novelties(): detecta novidades no Bronze/Gold
-- e popula product_novelties mantendo o invariante Medallion.
--
-- ESTRATÉGIAS POR FORNECEDOR:
--   STRICKER  → Bronze raw_data.NewProduct='true' OU Catalogs ILIKE '%Novidades%'
--   XBZ       → products.created_at nas últimas p_recent_days_xbz
--   ASIA      → products.created_at nas últimas p_recent_days_asia
--   SOMARCAS  → products.created_at nas últimas p_recent_days_sm
--   88BRINDES → products.created_at nas últimas p_recent_days_88
--
-- Advisory lock: 74108913 (slot exclusivo)
-- Idempotente: ON CONFLICT (product_id) WHERE is_active=true → DO NOTHING
-- Não sobrescreve registros manuais (source='manual')
-- ══════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_sync_product_novelties(
    p_recent_days_xbz   int  DEFAULT 60,   -- janela de "novo" para XBZ
    p_recent_days_asia  int  DEFAULT 60,   -- janela de "novo" para ASIA
    p_recent_days_sm    int  DEFAULT 60,   -- janela de "novo" para SOMARCAS
    p_recent_days_88    int  DEFAULT 60,   -- janela de "novo" para 88BRINDES
    p_expires_days      int  DEFAULT 60,   -- duração do selo em dias
    p_dry_run           boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_stricker_id  uuid := 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0';
    v_xbz_id       uuid := 'd6718a29-e954-4c1b-bd84-03ea24884900';
    v_asia_id      uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
    v_sm_id        uuid := '841cd690-210a-422a-908c-7676828db272';
    -- 88BRINDES: busca dinâmica para não hardcodar
    v_88_id        uuid;

    v_ins_stricker_new   int := 0;
    v_ins_stricker_cat   int := 0;
    v_ins_xbz            int := 0;
    v_ins_asia           int := 0;
    v_ins_sm             int := 0;
    v_ins_88             int := 0;
    v_total              int := 0;
BEGIN
    -- Advisory lock: só uma instância roda por vez
    IF NOT pg_try_advisory_xact_lock(74108913) THEN
        RETURN jsonb_build_object(
            'status', 'skipped',
            'reason', 'advisory_lock_busy',
            'ts',     now()
        );
    END IF;

    -- Busca dinâmica do supplier_id do 88BRINDES
    SELECT id INTO v_88_id FROM public.suppliers WHERE code = '88BRINDES' LIMIT 1;

    IF p_dry_run THEN
        -- Modo dry_run: apenas conta sem inserir
        SELECT COUNT(*) INTO v_ins_stricker_new
        FROM public.products p
        JOIN public.supplier_products_raw spr
            ON  spr.supplier_id = p.supplier_id
            AND SPLIT_PART(spr.supplier_sku, '-', 1) = p.supplier_reference
        WHERE p.supplier_id  = v_stricker_id
          AND p.is_active     = true
          AND spr.raw_data->>'NewProduct' = 'true'
          AND COALESCE(spr.raw_data->>'IsStockOut', 'false') <> 'true'
          AND NOT EXISTS (
            SELECT 1 FROM public.product_novelties pn
            WHERE pn.product_id = p.id AND pn.is_active = true
          );

        RETURN jsonb_build_object(
            'status', 'dry_run',
            'would_insert_stricker_new_product', v_ins_stricker_new,
            'ts', now()
        );
    END IF;

    -- ─────────────────────────────────────────────────────────────
    -- STRICKER: flag NewProduct=true no Bronze
    -- ─────────────────────────────────────────────────────────────
    WITH to_insert AS (
        SELECT DISTINCT p.id AS product_id
        FROM public.products p
        JOIN public.supplier_products_raw spr
            ON  spr.supplier_id = p.supplier_id
            AND SPLIT_PART(spr.supplier_sku, '-', 1) = p.supplier_reference
        WHERE p.supplier_id  = v_stricker_id
          AND p.is_active     = true
          AND spr.raw_data->>'NewProduct' = 'true'
          AND COALESCE(spr.raw_data->>'IsStockOut', 'false') <> 'true'
          AND NOT EXISTS (
            SELECT 1 FROM public.product_novelties pn
            WHERE pn.product_id = p.id AND pn.is_active = true
          )
    ),
    inserted AS (
        INSERT INTO public.product_novelties
            (product_id, supplier_id, supplier_code, source, detected_at, expires_at, is_active, is_highlighted, notes)
        SELECT
            ti.product_id,
            v_stricker_id,
            'STRICKER',
            'spot_new_product',
            now(),
            now() + (p_expires_days || ' days')::interval,
            true,
            false,
            'Detectado automaticamente via Bronze raw_data.NewProduct=true'
        FROM to_insert ti
        ON CONFLICT DO NOTHING
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_ins_stricker_new FROM inserted;

    -- ─────────────────────────────────────────────────────────────
    -- STRICKER: Catalogs contém "Novidades" (catálogo ID=5)
    -- ─────────────────────────────────────────────────────────────
    WITH to_insert AS (
        SELECT DISTINCT p.id AS product_id
        FROM public.products p
        JOIN public.supplier_products_raw spr
            ON  spr.supplier_id = p.supplier_id
            AND SPLIT_PART(spr.supplier_sku, '-', 1) = p.supplier_reference
        WHERE p.supplier_id = v_stricker_id
          AND p.is_active    = true
          AND spr.raw_data->>'Catalogs' ILIKE '%Novidades%'
          AND COALESCE(spr.raw_data->>'NewProduct', 'false') <> 'true'  -- evitar duplo
          AND COALESCE(spr.raw_data->>'IsStockOut', 'false') <> 'true'
          AND NOT EXISTS (
            SELECT 1 FROM public.product_novelties pn
            WHERE pn.product_id = p.id AND pn.is_active = true
          )
    ),
    inserted AS (
        INSERT INTO public.product_novelties
            (product_id, supplier_id, supplier_code, source, detected_at, expires_at, is_active, is_highlighted, notes)
        SELECT
            ti.product_id,
            v_stricker_id,
            'STRICKER',
            'spot_catalogo_novidades',
            now(),
            now() + (p_expires_days || ' days')::interval,
            true,
            false,
            'Detectado automaticamente via Bronze Catalogs contém Novidades'
        FROM to_insert ti
        ON CONFLICT DO NOTHING
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_ins_stricker_cat FROM inserted;

    -- ─────────────────────────────────────────────────────────────
    -- XBZ: produtos recentemente promovidos ao Gold
    -- ─────────────────────────────────────────────────────────────
    WITH to_insert AS (
        SELECT p.id AS product_id
        FROM public.products p
        WHERE p.supplier_id = v_xbz_id
          AND p.is_active    = true
          AND p.created_at  >= now() - (p_recent_days_xbz || ' days')::interval
          AND NOT EXISTS (
            SELECT 1 FROM public.product_novelties pn
            WHERE pn.product_id = p.id AND pn.is_active = true
          )
    ),
    inserted AS (
        INSERT INTO public.product_novelties
            (product_id, supplier_id, supplier_code, source, detected_at, expires_at, is_active, is_highlighted, notes)
        SELECT
            ti.product_id,
            v_xbz_id,
            'XBZ',
            'xbz_recently_promoted',
            p.created_at,
            p.created_at + (p_expires_days || ' days')::interval,
            true,
            false,
            'Detectado automaticamente: produto XBZ promovido nos últimos ' || p_recent_days_xbz || ' dias'
        FROM to_insert ti
        JOIN public.products p ON p.id = ti.product_id
        ON CONFLICT DO NOTHING
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_ins_xbz FROM inserted;

    -- ─────────────────────────────────────────────────────────────
    -- ASIA: produtos recentemente promovidos ao Gold
    -- ─────────────────────────────────────────────────────────────
    WITH to_insert AS (
        SELECT p.id AS product_id
        FROM public.products p
        WHERE p.supplier_id = v_asia_id
          AND p.is_active    = true
          AND p.created_at  >= now() - (p_recent_days_asia || ' days')::interval
          AND NOT EXISTS (
            SELECT 1 FROM public.product_novelties pn
            WHERE pn.product_id = p.id AND pn.is_active = true
          )
    ),
    inserted AS (
        INSERT INTO public.product_novelties
            (product_id, supplier_id, supplier_code, source, detected_at, expires_at, is_active, is_highlighted, notes)
        SELECT
            ti.product_id,
            v_asia_id,
            'ASIA',
            'asia_recently_promoted',
            p.created_at,
            p.created_at + (p_expires_days || ' days')::interval,
            true,
            false,
            'Detectado automaticamente: produto ASIA promovido nos últimos ' || p_recent_days_asia || ' dias'
        FROM to_insert ti
        JOIN public.products p ON p.id = ti.product_id
        ON CONFLICT DO NOTHING
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_ins_asia FROM inserted;

    -- ─────────────────────────────────────────────────────────────
    -- SOMARCAS: produtos recentemente promovidos ao Gold
    -- ─────────────────────────────────────────────────────────────
    WITH to_insert AS (
        SELECT p.id AS product_id
        FROM public.products p
        WHERE p.supplier_id = v_sm_id
          AND p.is_active    = true
          AND p.created_at  >= now() - (p_recent_days_sm || ' days')::interval
          AND NOT EXISTS (
            SELECT 1 FROM public.product_novelties pn
            WHERE pn.product_id = p.id AND pn.is_active = true
          )
    ),
    inserted AS (
        INSERT INTO public.product_novelties
            (product_id, supplier_id, supplier_code, source, detected_at, expires_at, is_active, is_highlighted, notes)
        SELECT
            ti.product_id,
            v_sm_id,
            'SOMARCAS',
            'sm_recently_promoted',
            p.created_at,
            p.created_at + (p_expires_days || ' days')::interval,
            true,
            false,
            'Detectado automaticamente: produto SOMARCAS promovido nos últimos ' || p_recent_days_sm || ' dias'
        FROM to_insert ti
        JOIN public.products p ON p.id = ti.product_id
        ON CONFLICT DO NOTHING
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_ins_sm FROM inserted;

    -- ─────────────────────────────────────────────────────────────
    -- 88BRINDES: produtos recentemente promovidos ao Gold
    -- ─────────────────────────────────────────────────────────────
    IF v_88_id IS NOT NULL THEN
        WITH to_insert AS (
            SELECT p.id AS product_id
            FROM public.products p
            WHERE p.supplier_id = v_88_id
              AND p.is_active    = true
              AND p.created_at  >= now() - (p_recent_days_88 || ' days')::interval
              AND NOT EXISTS (
                SELECT 1 FROM public.product_novelties pn
                WHERE pn.product_id = p.id AND pn.is_active = true
              )
        ),
        inserted AS (
            INSERT INTO public.product_novelties
                (product_id, supplier_id, supplier_code, source, detected_at, expires_at, is_active, is_highlighted, notes)
            SELECT
                ti.product_id,
                v_88_id,
                '88BRINDES',
                '88brindes_recently_promoted',
                p.created_at,
                p.created_at + (p_expires_days || ' days')::interval,
                true,
                false,
                'Detectado automaticamente: produto 88BRINDES promovido nos últimos ' || p_recent_days_88 || ' dias'
            FROM to_insert ti
            JOIN public.products p ON p.id = ti.product_id
            ON CONFLICT DO NOTHING
            RETURNING 1
        )
        SELECT COUNT(*) INTO v_ins_88 FROM inserted;
    END IF;

    v_total := v_ins_stricker_new + v_ins_stricker_cat + v_ins_xbz + v_ins_asia + v_ins_sm + v_ins_88;

    RETURN jsonb_build_object(
        'status',                  'ok',
        'total_inserted',          v_total,
        'stricker_new_product',    v_ins_stricker_new,
        'stricker_catalogo',       v_ins_stricker_cat,
        'xbz',                     v_ins_xbz,
        'asia',                    v_ins_asia,
        'somarcas',                v_ins_sm,
        '88brindes',               v_ins_88,
        'params', jsonb_build_object(
            'expires_days',         p_expires_days,
            'recent_days_xbz',      p_recent_days_xbz,
            'recent_days_asia',     p_recent_days_asia,
            'recent_days_sm',       p_recent_days_sm,
            'recent_days_88',       p_recent_days_88
        ),
        'ran_at', now()
    );
END;
$$;

COMMENT ON FUNCTION public.fn_sync_product_novelties(int,int,int,int,int,boolean) IS
    'Detecta novidades por fornecedor e popula product_novelties. '
    'STRICKER: Bronze NewProduct=true e Catalogs=Novidades. '
    'XBZ/ASIA/SOMARCAS/88BRINDES: produtos promovidos recentemente. '
    'Idempotente, advisory lock 74108913. Retorna JSON com contagens.';

REVOKE ALL ON FUNCTION public.fn_sync_product_novelties(int,int,int,int,int,boolean) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_sync_product_novelties(int,int,int,int,int,boolean) TO service_role;
;

-- <<< END 20260611130830_create_fn_sync_product_novelties.sql <<<

-- >>> BEGIN 20260611130919_seo_fix_generate_meta_description_min_length.sql >>>

-- ============================================================
-- FIX intermediário: generate_product_meta_description
-- Garantir mínimo de 50 chars (constraint chk_products_meta_desc_length)
-- Problema: strip_html() em short_description HTML-pesado retornava < 50 chars
-- ============================================================

CREATE OR REPLACE FUNCTION public.generate_product_meta_description(
    p_name                 TEXT,
    p_short_description    TEXT    DEFAULT NULL,
    p_description          TEXT    DEFAULT NULL,
    p_allows_personalization BOOLEAN DEFAULT false
)
RETURNS TEXT
LANGUAGE plpgsql
IMMUTABLE
SET search_path = public
AS $$
DECLARE
  v_description        TEXT;
  v_base               TEXT;
  v_personalization    TEXT := '';
  v_cta                TEXT := ' Solicite orçamento!';
  v_fallback_suffix    TEXT := ' para brindes corporativos e eventos promocionais.';
BEGIN
  IF p_name IS NULL THEN RETURN NULL; END IF;

  -- === BASE: prioridade short_desc > desc > fallback ===
  IF p_short_description IS NOT NULL
     AND LENGTH(TRIM(strip_html(p_short_description))) >= 20 THEN
    v_base := TRIM(REGEXP_REPLACE(strip_html(p_short_description), '\s+', ' ', 'g'));

  ELSIF p_description IS NOT NULL
        AND LENGTH(TRIM(strip_html(p_description))) >= 20 THEN
    v_base := truncate_text(
                TRIM(REGEXP_REPLACE(strip_html(p_description), '\s+', ' ', 'g')),
                110, ''
              );
  ELSE
    -- Fallback: nome + sufixo padrão (sempre ≥ 50 chars)
    v_base := p_name || v_fallback_suffix;
  END IF;

  -- === GARANTIR BASE MÍNIMA DE 30 CHARS ===
  -- Se strip_html gerou texto muito curto, expande com sufixo
  IF LENGTH(v_base) < 30 THEN
    v_base := v_base || v_fallback_suffix;
  END IF;

  -- === PERSONALIZAÇÃO ===
  IF p_allows_personalization THEN
    v_personalization := ' Personalização disponível.';
  END IF;

  -- === MONTAR ===
  v_description := v_base;

  IF LENGTH(v_description || v_personalization) <= 140 THEN
    v_description := v_description || v_personalization;
  END IF;

  IF LENGTH(v_description || v_cta) <= 165 THEN
    v_description := v_description || v_cta;
  END IF;

  -- === GARANTIR MÍNIMO 50 CHARS (constraint) ===
  -- Se ainda for curto demais, completa com contexto de brindes
  IF LENGTH(v_description) < 50 THEN
    v_description := v_description || ' Brinde corporativo personalizado. Solicite orçamento!';
  END IF;

  -- === GARANTIR MÁXIMO 170 CHARS (constraint) ===
  v_description := LEFT(v_description, 169);

  RETURN v_description;
END;
$$;

COMMENT ON FUNCTION public.generate_product_meta_description(TEXT, TEXT, TEXT, BOOLEAN) IS
    'Gera meta description SEO otimizada. Garante 50-169 chars (compatível com constraint chk_products_meta_desc_length). Prioridade: short_description > description > fallback.';
;

-- <<< END 20260611130919_seo_fix_generate_meta_description_min_length.sql <<<

-- >>> BEGIN 20260611130957_create_vw_product_novelties_active.sql >>>

-- ══════════════════════════════════════════════════════════════════
-- VIEW: vw_product_novelties_active
-- Novidades ativas com dados do produto (Gold join) — G-09
-- Substitui o filtro repetitivo em todas as queries do sistema
-- ══════════════════════════════════════════════════════════════════
CREATE OR REPLACE VIEW public.vw_product_novelties_active AS
SELECT
    -- Colunas de product_novelties
    pn.id                   AS novelty_id,
    pn.product_id,
    pn.supplier_id,
    pn.supplier_code,
    pn.supplier_product_code,
    pn.source,
    pn.detected_at,
    pn.expires_at,
    pn.is_active,
    pn.is_highlighted,
    pn.notes,
    pn.created_at           AS novelty_created_at,
    pn.updated_at           AS novelty_updated_at,

    -- Dados essenciais do produto (Gold)
    p.name                  AS product_name,
    p.sku                   AS product_sku,
    p.supplier_reference,
    p.primary_image_url,
    p.sale_price,
    p.cost_price,
    p.stock_quantity,
    p.is_active             AS product_active,
    p.is_stockout,
    p.created_at            AS product_created_at,

    -- Dias restantes até expirar (NULL = não expira)
    CASE
        WHEN pn.expires_at IS NULL THEN NULL
        ELSE EXTRACT(DAY FROM (pn.expires_at - now()))::int
    END AS days_remaining,

    -- Flag de urgência para dashboard (< 7 dias para expirar)
    CASE
        WHEN pn.expires_at IS NOT NULL
             AND pn.expires_at - now() < INTERVAL '7 days'
        THEN true
        ELSE false
    END AS expiring_soon

FROM public.product_novelties pn
JOIN public.products p ON p.id = pn.product_id
WHERE pn.is_active = true
  AND (pn.expires_at IS NULL OR pn.expires_at > now())
  AND p.is_active = true;

COMMENT ON VIEW public.vw_product_novelties_active IS
    'Novidades ativas com JOIN em products (Gold). '
    'Filtros já aplicados: is_active=true, expires_at não vencido, produto ativo. '
    'Ordenar por is_highlighted DESC, detected_at DESC para home. '
    'Campo days_remaining: NULL = permanente. expiring_soon = TRUE quando < 7 dias.';

-- GRANTs na view
GRANT SELECT ON public.vw_product_novelties_active TO anon, authenticated, service_role;

-- ── View auxiliar: destaques para a home (máx. 4) ───────────────
CREATE OR REPLACE VIEW public.vw_novelties_home_highlights AS
SELECT
    novelty_id, product_id, product_name, product_sku,
    primary_image_url, sale_price, detected_at,
    days_remaining, supplier_code, source
FROM public.vw_product_novelties_active
WHERE is_highlighted = true
ORDER BY detected_at DESC
LIMIT 4;

COMMENT ON VIEW public.vw_novelties_home_highlights IS
    'Top 4 novidades destacadas para o banner da home (is_highlighted=true). '
    'Curadoria manual: definir is_highlighted=true em product_novelties.';

GRANT SELECT ON public.vw_novelties_home_highlights TO anon, authenticated, service_role;
;

