-- >>> BEGIN 20260611132314_fn_trigger_product_automation_bulk_mode_guard.sql >>>

-- ============================================================
-- CORREÇÃO: fn_trigger_product_automation
-- Adiciona guarda de bulk_import_mode + write_source='pipeline'
-- Evita timeout em updates em lote (is_thermal, backfill, etc.)
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_trigger_product_automation()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_classify_result JSONB;
    v_materials_linked INTEGER;
    v_bulk_mode BOOLEAN;
    v_write_source TEXT;
BEGIN
    -- ── GUARDA DE MODO BULK ──────────────────────────────────
    -- Quando pipeline ou bulk import está ativo, pula automações
    -- pesadas (tags, datas, ECO, feminino) — serão rodadas em lote
    v_bulk_mode    := current_setting('app.bulk_import_mode', true) = 'true';
    v_write_source := current_setting('app.write_source',     true);

    IF v_bulk_mode OR v_write_source = 'pipeline' THEN
        RETURN NEW;
    END IF;
    -- ────────────────────────────────────────────────────────

    -- 1. CLASSIFICAR CATEGORIA (se ainda não tem)
    IF NEW.category_id IS NULL THEN
        v_classify_result := fn_master_classify_product(NEW.name, NEW.id);
        RAISE NOTICE 'Produto [%] classificado: tipo=%, categoria=%',
            LEFT(NEW.name, 30),
            v_classify_result->>'detected_type',
            v_classify_result->>'category_id';
    END IF;

    -- 2. VINCULAR MATERIAIS
    v_materials_linked := fn_link_product_materials(NEW.id, NEW.supplier_id);
    IF v_materials_linked > 0 THEN
        RAISE NOTICE 'Produto [%]: % materiais vinculados', LEFT(NEW.name, 30), v_materials_linked;
    END IF;

    -- 3. AUTOMAÇÕES SECUNDÁRIAS (com tratamento de erro individual)
    BEGIN PERFORM fn_auto_link_tags(NEW.id);
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Aviso: fn_auto_link_tags falhou: %', SQLERRM;
    END;

    BEGIN PERFORM fn_auto_link_properties(NEW.id);
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Aviso: fn_auto_link_properties falhou: %', SQLERRM;
    END;

    BEGIN PERFORM fn_auto_link_eco(NEW.id);
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Aviso: fn_auto_link_eco falhou: %', SQLERRM;
    END;

    BEGIN PERFORM fn_auto_link_feminino(NEW.id);
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Aviso: fn_auto_link_feminino falhou: %', SQLERRM;
    END;

    BEGIN PERFORM fn_auto_link_commemorative_dates(NEW.id);
    EXCEPTION WHEN OTHERS THEN
        RAISE NOTICE 'Aviso: fn_auto_link_commemorative_dates falhou: %', SQLERRM;
    END;

    RETURN NEW;
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Erro no trigger de automação para produto %: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.fn_trigger_product_automation() IS
'Trigger de automação de produtos. Guarda bulk_import_mode e write_source=pipeline para operações em lote. v2.0 2026-06-11';
;

-- <<< END 20260611132314_fn_trigger_product_automation_bulk_mode_guard.sql <<<

-- >>> BEGIN 20260611132442_fn_backfill_is_thermal_v1.sql >>>

-- ============================================================
-- fn_backfill_is_thermal() — função permanente de manutenção
-- Pode ser chamada a qualquer momento para re-sincronizar o flag
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_backfill_is_thermal()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_via_props integer := 0;
  v_via_name  integer := 0;
  v_cleared   integer := 0;
BEGIN
  PERFORM set_config('app.bulk_import_mode', 'true', true);
  PERFORM set_config('app.write_source', 'pipeline', true);

  -- PASSO 1: true via product_properties
  UPDATE products p SET is_thermal = true
  WHERE p.is_active = true
    AND (p.is_thermal IS NULL OR p.is_thermal = false)
    AND EXISTS (
      SELECT 1 FROM product_properties pp
      WHERE pp.product_id = p.id
        AND pp.property_code IN (
          'DOUBLE_WALL','THERMAL_COLD_HOT_HOURS','THERMAL_COLD_24_HOT_12',
          'THERMAL_COLD_24_HOT_6','THERMAL_COLD','THERMAL_HOT','THERMAL_PROTECTION'
        )
    );
  GET DIAGNOSTICS v_via_props = ROW_COUNT;

  -- PASSO 2: true via nome/descrição
  UPDATE products p SET is_thermal = true
  WHERE p.is_active = true
    AND (p.is_thermal IS NULL OR p.is_thermal = false)
    AND (
      p.name ~* '\y(t[eé]rmic|garrafa\s+t[eé]rm|bolsa\s+t[eé]rm|lancheira|caneca\s+t[eé]rm|copo\s+t[eé]rm|squeeze\s+t[eé]rm|cooler|isotérm|isot[eé]rm)\y'
      OR p.name ~* 'parede\s+dupla'
      OR (p.name ~* 'inox' AND p.name ~* '(garrafa|copo|caneca|squeeze|bolsa|cuia)')
      OR p.description ~* '(parede\s+dupla|isolad[ao]\s+a\s+v[aá]cuo|mant[eé]m\s+(fria|quente|temperatura)|horas\s+(fria|quente)|frias\s+e\s+quentes)'
    );
  GET DIAGNOSTICS v_via_name = ROW_COUNT;

  -- PASSO 3: false para produtos que não têm evidência de thermal (seguro = só NULLs)
  UPDATE products p SET is_thermal = false
  WHERE p.is_active = true
    AND p.is_thermal IS NULL;
  GET DIAGNOSTICS v_cleared = ROW_COUNT;

  RETURN jsonb_build_object(
    'marcados_via_properties', v_via_props,
    'marcados_via_nome',       v_via_name,
    'default_false',           v_cleared,
    'total_ativados',          v_via_props + v_via_name
  );
END;
$$;

COMMENT ON FUNCTION public.fn_backfill_is_thermal() IS
'Sincroniza is_thermal em products via product_properties + nome/descrição. Safe para bulk. v1.0 2026-06-11';

-- Executar para limpar os NULLs restantes
SELECT public.fn_backfill_is_thermal();
;

