-- >>> BEGIN 20260611133929_add_frente4_stockout_orphan_to_fn_expire.sql >>>

-- FIX: Frente 4 — stockout orphans sem novelty ativa
-- Cobre o caso: pipeline set is_new=true diretamente em products (sem passar por product_novelties)
-- para produtos que são is_stockout=true — esses nunca devem ter badge NOVO
CREATE OR REPLACE FUNCTION public.fn_expire_novelties()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_novelties_expired    int := 0;
    v_products_fixed       int := 0;
    v_stockout_deactivated int := 0;
    v_stockout_orphans     int := 0;
    v_result               jsonb;
BEGIN
    IF NOT pg_try_advisory_xact_lock(74108912) THEN
        RETURN jsonb_build_object('status','skipped','reason','advisory_lock_busy','ts',now());
    END IF;

    -- ── Frente 1: product_novelties com expires_at vencido ──────────
    WITH expired AS (
        UPDATE public.product_novelties
        SET is_active=false, updated_at=clock_timestamp()
        WHERE is_active=true AND expires_at IS NOT NULL AND expires_at < now()
        RETURNING product_id
    ) SELECT COUNT(*) INTO v_novelties_expired FROM expired;

    -- ── Frente 2: orphans stale em products (expires passado, sem novelty ativa) ──
    WITH stale AS (
        UPDATE public.products
        SET is_new=false, novelty_detected_at=NULL, novelty_expires_at=NULL, updated_at=now()
        WHERE is_new=true
          AND novelty_expires_at IS NOT NULL AND novelty_expires_at < now()
          AND NOT EXISTS(
              SELECT 1 FROM public.product_novelties pn
              WHERE pn.product_id=products.id AND pn.is_active=true)
        RETURNING id
    ) SELECT COUNT(*) INTO v_products_fixed FROM stale;

    -- ── Frente 3: novelties ativas de produtos is_stockout=true ─────
    WITH stockout AS (
        UPDATE public.product_novelties pn
        SET is_active=false, updated_at=clock_timestamp(),
            notes=COALESCE(notes||' | ','')|| 'Desativado: produto is_stockout=true'
        FROM public.products p
        WHERE pn.product_id=p.id AND pn.is_active=true AND p.is_stockout=true
        RETURNING pn.product_id
    ) SELECT COUNT(*) INTO v_stockout_deactivated FROM stockout;

    -- ── Frente 4 (NEW): orphans stockout em products sem novelty ativa ──
    -- Pipeline pode setar is_new=true diretamente em products mesmo para
    -- produtos is_stockout=true. Essa frente corrige os orphans resultantes.
    WITH stockout_orphans AS (
        UPDATE public.products
        SET is_new=false, novelty_detected_at=NULL, novelty_expires_at=NULL, updated_at=now()
        WHERE is_stockout=true
          AND is_new=true
          AND NOT EXISTS(
              SELECT 1 FROM public.product_novelties pn
              WHERE pn.product_id=products.id AND pn.is_active=true)
        RETURNING id
    ) SELECT COUNT(*) INTO v_stockout_orphans FROM stockout_orphans;

    v_result := jsonb_build_object(
        'status',                 'ok',
        'novelties_expired',      v_novelties_expired,
        'products_stale_fixed',   v_products_fixed,
        'stockout_deactivated',   v_stockout_deactivated,
        'stockout_orphans_fixed', v_stockout_orphans,
        'total_actions',          v_novelties_expired + v_products_fixed + v_stockout_deactivated + v_stockout_orphans,
        'ran_at',                 now()
    );
    RETURN v_result;
END;
$$;

COMMENT ON FUNCTION public.fn_expire_novelties() IS
    'Expira novidades em 4 frentes: '
    '(1) product_novelties com expires_at vencido; '
    '(2) products.is_new orphans stale (expires passado, sem novelty ativa); '
    '(3) novelties ativas de produtos is_stockout=true; '
    '(4) products.is_new orphans stockout (pipeline setou diretamente, sem novelty ativa). '
    'Advisory lock 74108912. clock_timestamp() para updated_at preciso.';
;

-- <<< END 20260611133929_add_frente4_stockout_orphan_to_fn_expire.sql <<<

-- >>> BEGIN 20260611135038_p2_realtime_01_device_login_notifications_e_publication.sql >>>
-- p2_realtime_01: cria device_login_notifications e completa a publication realtime
--
-- Contexto (auditoria integração frontend↔medallion 2026-06-11):
--   1. A edge function detect-new-device INSERE em public.device_login_notifications
--      e o hook usePushNotifications ASSINA INSERTs dessa tabela — mas a tabela
--      nunca existiu no SSOT doufsxqlfjyuvxuezpln (escrita e subscription mortas).
--   2. useWorkspaceNotifications/notificationService assinam postgres_changes de
--      workspace_notifications e usePushNotifications assina login_attempts, mas
--      nenhuma das duas estava na publication supabase_realtime (eventos nunca
--      entregues; UI dependia só de refetch).
--
-- Segurança:
--   - RLS select-own para authenticated (realtime respeita RLS: cada usuário só
--     recebe eventos das próprias linhas; login_attempts mantém a policy
--     existente can_view_audit_logs — eventos só chegam a admin/dev).
--   - Escrita exclusiva da service_role (edge function); nenhuma policy de
--     INSERT/UPDATE/DELETE para clientes.
--   - Não toca nas tabelas sensíveis verificadas por check_hardening_status
--     (discount_approval_requests, kit_variants, kit_comments ficam fora da
--     publication — invariante realtime_isolation_ok preservada).

CREATE TABLE IF NOT EXISTS public.device_login_notifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES auth.users (id) ON DELETE CASCADE,
  device_id text,
  ip_address text,
  user_agent text,
  location text,
  email_sent boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.device_login_notifications IS
  'Notificações de login em novo dispositivo/IP. Escrita: edge detect-new-device (service_role). Leitura: dono via RLS. Consumida em realtime por usePushNotifications.';

CREATE INDEX IF NOT EXISTS idx_device_login_notifications_user_created
  ON public.device_login_notifications (user_id, created_at DESC);

ALTER TABLE public.device_login_notifications ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Users can read own device login notifications"
  ON public.device_login_notifications;
CREATE POLICY "Users can read own device login notifications"
  ON public.device_login_notifications
  FOR SELECT TO authenticated
  USING (user_id = (SELECT auth.uid()));

REVOKE ALL ON public.device_login_notifications FROM PUBLIC;
REVOKE ALL ON public.device_login_notifications FROM anon;
GRANT SELECT ON public.device_login_notifications TO authenticated;
GRANT ALL ON public.device_login_notifications TO service_role;

-- Publication realtime (idempotente — ALTER PUBLICATION falha se a tabela já estiver lá)
DO $$
DECLARE
  _tbl text;
BEGIN
  FOREACH _tbl IN ARRAY ARRAY['device_login_notifications', 'workspace_notifications', 'login_attempts']
  LOOP
    IF NOT EXISTS (
      SELECT 1
      FROM pg_publication_rel pr
      JOIN pg_class c ON c.oid = pr.prrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE pr.prpubid = (SELECT oid FROM pg_publication WHERE pubname = 'supabase_realtime')
        AND n.nspname = 'public'
        AND c.relname = _tbl
    ) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', _tbl);
    END IF;
  END LOOP;
END;
$$;;

-- <<< END 20260611135038_p2_realtime_01_device_login_notifications_e_publication.sql <<<

-- >>> BEGIN 20260611135102_p2_acl_01_restore_admin_rpcs_frontend.sql >>>
-- p2_acl_01: restaura EXECUTE de RPCs admin consumidas diretamente pelo frontend
--
-- Contexto (auditoria integração frontend↔medallion 2026-06-11): os lockdowns de
-- ACL deixaram 4 RPCs chamadas pela UI admin sem EXECUTE para authenticated,
-- quebrando silenciosamente (42501):
--
--   - check_hardening_status()        → HardeningHealthCard
--   - check_telemetry_regression()    → useRegressionGuardrail / useOptimizationQueue
--   - lookup_request_id(text)         → useAppHealth (drill-down de request_id)
--   - execute_role_migration_batch()  → useRoleMigration
--
-- Todas têm checagem de autorização INTERNA (admin/dev via user_roles/has_role),
-- portanto reexpor a authenticated é seguro: não-admins recebem exceção da
-- própria função, não acesso.
--
-- NÃO reexpostas (decisão deliberada):
--   - repair_ownership_orphans: o teste de segurança do frontend
--     (src/utils/security-audit.ts) EXIGE permission denied para authenticated;
--     a execução real é via edge function ownership-repair (service_role).
--   - sync_external_connections_from_credentials: SECURITY DEFINER sem checagem
--     de chamador — ganha wrapper admin-gated em migration própria.

-- check_hardening_status lê storage.buckets e cron.job; como SECURITY INVOKER,
-- authenticated falharia ao tocar cron.* mesmo sendo admin. Vira DEFINER com a
-- checagem interna de admin já existente + search_path travado (todas as
-- referências do corpo são schema-qualificadas; verificado em 2026-06-11).
ALTER FUNCTION public.check_hardening_status() SECURITY DEFINER;
ALTER FUNCTION public.check_hardening_status() SET search_path = '';
REVOKE ALL ON FUNCTION public.check_hardening_status() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.check_hardening_status() FROM anon;
GRANT EXECUTE ON FUNCTION public.check_hardening_status() TO authenticated;
GRANT EXECUTE ON FUNCTION public.check_hardening_status() TO service_role;

REVOKE ALL ON FUNCTION public.check_telemetry_regression() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.check_telemetry_regression() FROM anon;
GRANT EXECUTE ON FUNCTION public.check_telemetry_regression() TO authenticated;
GRANT EXECUTE ON FUNCTION public.check_telemetry_regression() TO service_role;

REVOKE ALL ON FUNCTION public.lookup_request_id(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.lookup_request_id(text) FROM anon;
GRANT EXECUTE ON FUNCTION public.lookup_request_id(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.lookup_request_id(text) TO service_role;

REVOKE ALL ON FUNCTION public.execute_role_migration_batch(text, text, jsonb, boolean) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.execute_role_migration_batch(text, text, jsonb, boolean) FROM anon;
GRANT EXECUTE ON FUNCTION public.execute_role_migration_batch(text, text, jsonb, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.execute_role_migration_batch(text, text, jsonb, boolean) TO service_role;;

-- <<< END 20260611135102_p2_acl_01_restore_admin_rpcs_frontend.sql <<<

-- >>> BEGIN 20260611135118_p2_acl_02_fn_admin_sync_external_connections.sql >>>
-- p2_acl_02: wrapper admin-gated para o sync manual de external_connections
--
-- Contexto: LastSyncRunPanel (UI admin) chamava
-- sync_external_connections_from_credentials() direto. Essa função é
-- SECURITY DEFINER SEM checagem de chamador (escolhe um admin arbitrário como
-- system actor) e teve EXECUTE corretamente revogado de anon/authenticated no
-- hardening — o botão "Executar sync" quebrou (42501).
--
-- Correção: wrapper SECURITY DEFINER que (1) exige papel admin do CHAMADOR e
-- (2) delega à função original, que permanece trancada para clientes.
-- O frontend passa a chamar fn_admin_sync_external_connections()
-- (src/integrations/supabase/gold.ts → rpcAdminSyncExternalConnections).

CREATE OR REPLACE FUNCTION public.fn_admin_sync_external_connections()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF NOT public.has_role((SELECT auth.uid()), 'admin'::public.app_role) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN public.sync_external_connections_from_credentials();
END;
$$;

COMMENT ON FUNCTION public.fn_admin_sync_external_connections() IS
  'Wrapper admin-gated do sync manual de external_connections. Chamado pela UI admin (LastSyncRunPanel). A função interna permanece sem EXECUTE para clientes.';

REVOKE ALL ON FUNCTION public.fn_admin_sync_external_connections() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_admin_sync_external_connections() FROM anon;
GRANT EXECUTE ON FUNCTION public.fn_admin_sync_external_connections() TO authenticated;
GRANT EXECUTE ON FUNCTION public.fn_admin_sync_external_connections() TO service_role;;

-- <<< END 20260611135118_p2_acl_02_fn_admin_sync_external_connections.sql <<<

