-- >>> BEGIN 20260611162730_ai_enrich_m2_dequeue_fix_varchar_cast.sql >>>

-- Fix: cast explícito TEXT em todas as colunas VARCHAR para eliminar type mismatch
DROP FUNCTION IF EXISTS public.fn_dequeue_ai_enrichment(INTEGER, TEXT, TEXT);

CREATE OR REPLACE FUNCTION public.fn_dequeue_ai_enrichment(
    p_batch_size        INTEGER DEFAULT 5,
    p_locked_by         TEXT    DEFAULT 'n8n',
    p_enrichment_type   TEXT    DEFAULT 'all'
)
RETURNS TABLE (
    queue_id              UUID,
    product_id            UUID,
    product_name          TEXT,
    sku                   TEXT,
    supplier_ref          TEXT,
    description           TEXT,
    short_desc            TEXT,
    brand                 TEXT,
    materials             JSONB,
    dimensions_display    TEXT,
    capacity_ml           INTEGER,
    weight_g              INTEGER,
    allows_person         BOOLEAN,
    category_id           UUID,
    category_name         TEXT,
    category_path         TEXT,
    ai_version_current    INTEGER,
    ai_title_exists       BOOLEAN,
    ai_description_exists BOOLEAN,
    ai_summary_exists     BOOLEAN,
    schema_exists         BOOLEAN,
    enrichment_type       TEXT,
    copywriting_config    JSONB,
    raw_data_snapshot     JSONB
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    RETURN QUERY
    WITH dequeued AS (
        UPDATE ai_enrichment_queue q
        SET
            status          = 'processing',
            locked_at       = now(),
            locked_by       = p_locked_by,
            last_attempt_at = now(),
            attempts        = q.attempts + 1,
            updated_at      = now()
        WHERE q.id IN (
            SELECT iq.id FROM ai_enrichment_queue iq
            WHERE iq.status = 'pending'
              AND iq.attempts < iq.max_attempts
              AND (p_enrichment_type = 'all' OR iq.enrichment_type = p_enrichment_type)
            ORDER BY iq.priority ASC, iq.created_at ASC
            LIMIT p_batch_size
            FOR UPDATE SKIP LOCKED
        )
        RETURNING q.id, q.product_id, q.enrichment_type AS q_enrichment_type
    )
    SELECT
        d.id,
        p.id,
        p.name::TEXT,
        p.sku::TEXT,
        p.supplier_reference::TEXT,      -- VARCHAR(50) → TEXT
        p.description::TEXT,
        p.short_description::TEXT,
        p.brand::TEXT,
        p.materials,
        p.dimensions_display::TEXT,
        p.capacity_ml,
        p.weight_g,
        COALESCE(p.allows_personalization, false),
        COALESCE(p.main_category_id, p.category_id),
        c.name::TEXT,
        c.full_path_readable::TEXT,
        COALESCE(p.ai_version, 0),
        (p.ai_title IS NOT NULL AND LENGTH(TRIM(COALESCE(p.ai_title,''))) > 0),
        (p.ai_description IS NOT NULL AND LENGTH(TRIM(COALESCE(p.ai_description,''))) > 0),
        (p.ai_summary IS NOT NULL AND LENGTH(TRIM(COALESCE(p.ai_summary,''))) > 0),
        (p.schema_json IS NOT NULL),
        d.q_enrichment_type::TEXT,
        public.get_copywriting_config(COALESCE(p.main_category_id, p.category_id)),
        (
            SELECT jsonb_build_object(
                'Area1',                    spr.raw_data->>'Area1',
                'Area2',                    spr.raw_data->>'Area2',
                'CustomizationTypes',       spr.raw_data->>'CustomizationTypes',
                'CustomizationDefaultType', spr.raw_data->>'CustomizationDefaultType',
                'DefaultCustomization',     spr.raw_data->>'DefaultCustomization',
                'ProductComponents',        spr.raw_data->>'ProductComponents',
                'ProductCertifications',    spr.raw_data->>'ProductCertifications',
                'Certificates',             spr.raw_data->>'Certificates',
                'Materials',                spr.raw_data->>'Materials',
                'Capacity',                 spr.raw_data->>'Capacity',
                'WeightGr',                 spr.raw_data->>'WeightGr',
                'KeyWords',                 spr.raw_data->>'KeyWords',
                'Properties',               spr.raw_data->>'Properties',
                'Type',                     spr.raw_data->>'Type',
                'SubType',                  spr.raw_data->>'SubType',
                'CountryOfOrigin',          spr.raw_data->>'CountryOfOrigin',
                'Brand',                    spr.raw_data->>'Brand',
                'CombinedSizes',            spr.raw_data->>'CombinedSizes'
            )
            FROM supplier_products_raw spr
            WHERE spr.product_id = p.id
            ORDER BY spr.updated_at DESC NULLS LAST
            LIMIT 1
        )
    FROM dequeued d
    JOIN products p ON p.id = d.product_id
    LEFT JOIN categories c ON c.id = COALESCE(p.main_category_id, p.category_id);
END;
$$;

GRANT EXECUTE ON FUNCTION public.fn_dequeue_ai_enrichment(INTEGER, TEXT, TEXT)
    TO anon, service_role;

-- Recarregar schema cache do PostgREST
NOTIFY pgrst, 'reload schema';
;

-- <<< END 20260611162730_ai_enrich_m2_dequeue_fix_varchar_cast.sql <<<

-- >>> BEGIN 20260611163709_ai_queue_auto_cleanup_trigger.sql >>>

-- MELHORIA PREVENTIVA: trigger para limpar fila quando produto é desativado/deletado
CREATE OR REPLACE FUNCTION public.fn_cleanup_ai_queue_on_product_deactivate()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
    -- Se produto foi desativado ou deletado, remover da fila pending/error
    IF (NEW.is_active = false OR NEW.is_deleted = true)
       AND (OLD.is_active = true AND OLD.is_deleted = false) THEN
        DELETE FROM ai_enrichment_queue
        WHERE product_id = NEW.id
          AND status IN ('pending', 'error');
    END IF;
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_cleanup_ai_queue ON products;
CREATE TRIGGER trg_cleanup_ai_queue
    AFTER UPDATE OF is_active, is_deleted ON products
    FOR EACH ROW
    EXECUTE FUNCTION fn_cleanup_ai_queue_on_product_deactivate();

COMMENT ON TRIGGER trg_cleanup_ai_queue ON products IS
    'Remove automaticamente da ai_enrichment_queue itens pending/error quando produto é desativado ou deletado.';
;

-- <<< END 20260611163709_ai_queue_auto_cleanup_trigger.sql <<<

-- >>> BEGIN 20260611163721_fix_circumference_cm_backfill_and_pipeline.sql >>>
-- ══════════════════════════════════════════════════════════════════════
-- CORREÇÃO COMPLETA: circumference_cm na cadeia Medallion Gold
-- Gaps encontrados nos testes exaustivos:
--   1. product_physical não tinha a coluna
--   2. fn_promote_padronizacao não propagava circumference_cm para products
--   3. 464 produtos Gold com circumference_cm no Silver mas NULL no Gold
-- ══════════════════════════════════════════════════════════════════════

-- ── 1. Adicionar circumference_cm a product_physical ──────────────────
ALTER TABLE public.product_physical
  ADD COLUMN IF NOT EXISTS circumference_cm numeric NULL;

COMMENT ON COLUMN public.product_physical.circumference_cm IS
  'Circunferência em centímetros. Espelho de products.circumference_cm.';

-- ── 2. Backfill: Gold ← Silver (via product_id) ──────────────────────
-- Apenas onde Gold ainda é NULL e Silver tem valor
UPDATE public.products p
SET circumference_cm = psp.circumference_cm
FROM public.produtos_site_padronizacao psp
WHERE psp.product_id = p.id
  AND psp.circumference_cm IS NOT NULL
  AND p.circumference_cm IS NULL;

-- Backfill complementar via produtos_padronizacao (outros fornecedores)
UPDATE public.products p
SET circumference_cm = pp.circumference_cm
FROM public.produtos_padronizacao pp
WHERE pp.product_id = p.id
  AND pp.circumference_cm IS NOT NULL
  AND p.circumference_cm IS NULL;

-- ── 3. Backfill product_physical ← products ──────────────────────────
UPDATE public.product_physical ph
SET circumference_cm = p.circumference_cm
FROM public.products p
WHERE ph.product_id = p.id
  AND p.circumference_cm IS NOT NULL
  AND ph.circumference_cm IS NULL;

-- ── 4. Atualizar fn_promote_padronizacao ─────────────────────────────
-- Adiciona circumference_cm após length_cm no UPDATE Gold e no INSERT product_physical
CREATE OR REPLACE FUNCTION public.fn_promote_padronizacao(p_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
AS $func$
DECLARE
  s        public.produtos_padronizacao%ROWTYPE;
  v_pid    uuid;
  v_org    uuid;
  v_locked text[];
  v_is_new boolean := false;
  v_cat_id   uuid    := NULL;
  v_cat_src  text;
  v_cat_l1   text;
  v_existing_cat uuid := NULL;
  v_min_qty  integer := NULL;
  v_display_name text;
BEGIN
  SELECT * INTO s FROM public.produtos_padronizacao WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'padronizacao_nao_encontrada', 'id', p_id);
  END IF;
  IF s.status <> 'standardized' THEN
    RETURN jsonb_build_object('success', false, 'error', 'status_invalido', 'status', s.status);
  END IF;

  PERFORM set_config('app.write_source',     'pipeline', true);
  PERFORM set_config('app.bulk_import_mode', 'true',     true);

  v_display_name := public.fn_display_product_name(s.name);

  SELECT id, locked_fields, category_id INTO v_pid, v_locked, v_existing_cat
  FROM public.products
  WHERE supplier_id = s.supplier_id AND supplier_reference = s.supplier_reference;

  IF v_pid IS NULL THEN
    v_is_new := true;
    SELECT organization_id INTO v_org FROM public.suppliers WHERE id = s.supplier_id;
    INSERT INTO public.products (organization_id, supplier_id, supplier_reference, sku, name, active, is_active, product_type)
    VALUES (v_org, s.supplier_id, s.supplier_reference,
            COALESCE(s.supplier_reference, s.name),
            COALESCE(v_display_name, s.name, 'Produto ' || s.supplier_reference),
            true, true, 'product')
    RETURNING id, locked_fields INTO v_pid, v_locked;
  END IF;

  v_locked := COALESCE(v_locked, '{}');

  -- Categoria nível 1: De→Para
  IF s.raw_id IS NOT NULL AND NOT ('category_id' = ANY(v_locked)) THEN
    BEGIN
      SELECT sfm.source_field INTO v_cat_src
      FROM public.supplier_field_mappings sfm
      WHERE sfm.supplier_id = s.supplier_id AND sfm.target_field = 'categories'
      LIMIT 1;
      IF v_cat_src IS NOT NULL THEN
        SELECT split_part(COALESCE(spr.raw_data ->> v_cat_src, ''), '|', 1)
        INTO v_cat_l1
        FROM public.supplier_products_raw spr WHERE spr.id = s.raw_id;
        IF v_cat_l1 IS NOT NULL AND TRIM(v_cat_l1) <> '' THEN
          SELECT scm.category_id INTO v_cat_id
          FROM public.supplier_categories sc
          JOIN public.supplier_category_mappings scm ON scm.supplier_category_id = sc.id
          WHERE sc.supplier_id = s.supplier_id AND TRIM(sc.supplier_code) = TRIM(v_cat_l1)
          LIMIT 1;
        END IF;
      END IF;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END IF;

  -- Categoria nível 2: classify alta-confiança (fill-only)
  IF v_cat_id IS NULL AND v_existing_cat IS NULL AND NOT ('category_id' = ANY(v_locked)) THEN
    v_cat_id := public.fn_promote_category_fallback(s.name);
  END IF;

  -- min_quantity: GREATEST(supplier, categoria)
  IF s.min_quantity IS NOT NULL THEN
    SELECT GREATEST(
        s.min_quantity,
        COALESCE(c.min_order_quantity, 1)
    )
    INTO v_min_qty
    FROM public.categories c
    WHERE c.id = COALESCE(v_cat_id,
        (SELECT category_id FROM public.products WHERE id = v_pid));
    v_min_qty := COALESCE(v_min_qty, s.min_quantity);
  END IF;

  -- ── UPDATE Gold ─────────────────────────────────────────────────────
  UPDATE public.products p SET
    sku                = COALESCE(p.sku, s.supplier_reference, s.name),
    name               = CASE WHEN 'name'               = ANY(v_locked) THEN p.name               ELSE COALESCE(v_display_name, s.name, p.name)           END,
    description        = CASE WHEN 'description'        = ANY(v_locked) THEN p.description        ELSE COALESCE(s.description,        p.description)        END,
    short_description  = CASE WHEN 'short_description'  = ANY(v_locked) THEN p.short_description  ELSE COALESCE(s.short_description,  p.short_description)  END,
    cost_price         = CASE WHEN 'cost_price'         = ANY(v_locked) THEN p.cost_price         ELSE COALESCE(NULLIF(s.cost_price,      0), p.cost_price)      END,
    suggested_price    = CASE WHEN 'suggested_price'    = ANY(v_locked) THEN p.suggested_price    ELSE COALESCE(NULLIF(s.suggested_price, 0), p.suggested_price) END,
    stock_quantity     = CASE WHEN 'stock_quantity'     = ANY(v_locked) THEN p.stock_quantity     ELSE COALESCE(s.stock_quantity,     p.stock_quantity)     END,
    min_quantity       = CASE WHEN 'min_quantity'       = ANY(v_locked) THEN p.min_quantity
                              WHEN v_min_qty IS NOT NULL                THEN v_min_qty
                              ELSE COALESCE(s.min_quantity, p.min_quantity)              END,
    primary_image_url  = CASE
      WHEN 'primary_image_url' = ANY(v_locked)              THEN p.primary_image_url
      WHEN p.primary_image_url LIKE '%imagedelivery%'       THEN p.primary_image_url
      ELSE COALESCE(s.primary_image_url, p.primary_image_url)
    END,
    images             = CASE WHEN 'images'             = ANY(v_locked) THEN p.images             ELSE COALESCE(s.images,             p.images)             END,
    ncm_code           = CASE WHEN 'ncm_code'           = ANY(v_locked) THEN p.ncm_code           ELSE COALESCE(NULLIF(s.ncm_code,'00000000'), p.ncm_code)           END,
    weight_g           = CASE WHEN 'weight_g'           = ANY(v_locked) THEN p.weight_g           ELSE COALESCE(NULLIF(s.weight_g,   0), p.weight_g)   END,
    height_cm          = CASE WHEN 'height_cm'          = ANY(v_locked) THEN p.height_cm          ELSE COALESCE(NULLIF(s.height_cm,  0), p.height_cm)  END,
    width_cm           = CASE WHEN 'width_cm'           = ANY(v_locked) THEN p.width_cm           ELSE COALESCE(NULLIF(s.width_cm,   0), p.width_cm)   END,
    length_cm          = CASE WHEN 'length_cm'          = ANY(v_locked) THEN p.length_cm          ELSE COALESCE(NULLIF(s.length_cm,  0), p.length_cm)  END,
    circumference_cm   = CASE WHEN 'circumference_cm'   = ANY(v_locked) THEN p.circumference_cm   ELSE COALESCE(NULLIF(s.circumference_cm, 0), p.circumference_cm) END,
    diameter_cm        = CASE WHEN 'diameter_cm'        = ANY(v_locked) THEN p.diameter_cm        ELSE COALESCE(NULLIF(s.diameter_cm, 0), p.diameter_cm) END,
    dimensions_display = CASE WHEN 'dimensions_display' = ANY(v_locked) THEN p.dimensions_display ELSE COALESCE(s.dimensions_display, p.dimensions_display) END,
    box_length_cm      = CASE WHEN 'box_length_cm'      = ANY(v_locked) THEN p.box_length_cm      ELSE COALESCE(s.box_length_cm,      p.box_length_cm)      END,
    box_width_cm       = CASE WHEN 'box_width_cm'       = ANY(v_locked) THEN p.box_width_cm       ELSE COALESCE(s.box_width_cm,       p.box_width_cm)       END,
    box_height_cm      = CASE WHEN 'box_height_cm'      = ANY(v_locked) THEN p.box_height_cm      ELSE COALESCE(s.box_height_cm,      p.box_height_cm)      END,
    box_weight_kg      = CASE WHEN 'box_weight_kg'      = ANY(v_locked) THEN p.box_weight_kg      ELSE COALESCE(s.box_weight_kg,      p.box_weight_kg)      END,
    box_volume_cm3     = CASE WHEN 'box_volume_cm3'     = ANY(v_locked) THEN p.box_volume_cm3     ELSE COALESCE(s.box_volume_cm3,     p.box_volume_cm3)     END,
    box_quantity       = CASE WHEN 'box_quantity'       = ANY(v_locked) THEN p.box_quantity       ELSE COALESCE(s.box_quantity,       p.box_quantity)       END,
    box_inner_quantity = CASE WHEN 'box_inner_quantity' = ANY(v_locked) THEN p.box_inner_quantity ELSE COALESCE(s.box_inner_quantity, p.box_inner_quantity) END,
    brand              = CASE WHEN 'brand'              = ANY(v_locked) THEN p.brand              ELSE COALESCE(s.brand,              p.brand)              END,
    packing_type       = CASE WHEN 'packing_type'       = ANY(v_locked) THEN p.packing_type       ELSE COALESCE(s.packing_type,       p.packing_type)       END,
    repacking_type     = CASE WHEN 'repacking_type'     = ANY(v_locked) THEN p.repacking_type     ELSE COALESCE(s.repacking_type,     p.repacking_type)     END,
    capacities         = CASE WHEN 'capacities'         = ANY(v_locked) THEN p.capacities         ELSE COALESCE(s.capacities,         p.capacities)         END,
    capacity_ml        = CASE WHEN 'capacity_ml'        = ANY(v_locked) THEN p.capacity_ml        ELSE COALESCE(NULLIF(s.capacity_ml, 0), p.capacity_ml) END,
    ipi_rate           = CASE WHEN 'ipi_rate'           = ANY(v_locked) THEN p.ipi_rate           ELSE COALESCE(s.ipi_rate,           p.ipi_rate)           END,
    engraving_type     = CASE WHEN 'engraving_type'     = ANY(v_locked) THEN p.engraving_type     ELSE COALESCE(s.engraving_type,     p.engraving_type)     END,
    colors             = CASE WHEN 'colors'             = ANY(v_locked) THEN p.colors             ELSE COALESCE(s.colors,             p.colors)             END,
    combined_sizes     = CASE WHEN 'combined_sizes'     = ANY(v_locked) THEN p.combined_sizes     ELSE COALESCE(s.combined_sizes,     p.combined_sizes)     END,
    box_image          = CASE WHEN 'box_image'          = ANY(v_locked) THEN p.box_image          ELSE COALESCE(s.box_image,          p.box_image)          END,
    is_textil          = CASE WHEN 'is_textil'          = ANY(v_locked) THEN p.is_textil          ELSE COALESCE(s.is_textil,          p.is_textil)          END,
    category_id        = CASE WHEN 'category_id'        = ANY(v_locked) THEN p.category_id        ELSE COALESCE(v_cat_id, v_existing_cat, p.category_id)     END,
    updated_at         = now()
  WHERE p.id = v_pid;

  -- Sincronizar product_physical (inclui circumference_cm)
  INSERT INTO public.product_physical (product_id, weight_g, height_cm, width_cm, length_cm, diameter_cm, circumference_cm, capacity_ml)
  VALUES (v_pid, NULLIF(s.weight_g,0), NULLIF(s.height_cm,0), NULLIF(s.width_cm,0), NULLIF(s.length_cm,0), NULLIF(s.diameter_cm,0), NULLIF(s.circumference_cm,0), NULLIF(s.capacity_ml,0))
  ON CONFLICT (product_id) DO UPDATE SET
    weight_g         = COALESCE(public.product_physical.weight_g,         EXCLUDED.weight_g),
    height_cm        = COALESCE(public.product_physical.height_cm,        EXCLUDED.height_cm),
    width_cm         = COALESCE(public.product_physical.width_cm,         EXCLUDED.width_cm),
    length_cm        = COALESCE(public.product_physical.length_cm,        EXCLUDED.length_cm),
    diameter_cm      = COALESCE(public.product_physical.diameter_cm,      EXCLUDED.diameter_cm),
    circumference_cm = COALESCE(public.product_physical.circumference_cm, EXCLUDED.circumference_cm),
    capacity_ml      = COALESCE(public.product_physical.capacity_ml,      EXCLUDED.capacity_ml),
    updated_at       = now();

  UPDATE public.produtos_padronizacao SET status = 'promoted', product_id = v_pid, updated_at = now()
  WHERE id = p_id;

  RETURN jsonb_build_object('success', true, 'created', v_is_new, 'product_id', v_pid);
END;
$func$;

-- <<< END 20260611163721_fix_circumference_cm_backfill_and_pipeline.sql <<<

-- >>> BEGIN 20260611163809_create_missing_analytics_and_approval_tables.sql >>>
-- Migration: create missing analytics and approval tables
-- Tables referenced in code but absent from DB:
--   navigation_analytics, product_views, discount_approval_requests
--
-- navigation_analytics: schema matches what useNavigationAnalytics.ts inserts
-- (event_type + event_data jsonb — NOT the older button_name/source_path columns)

-- 1. navigation_analytics
CREATE TABLE IF NOT EXISTS public.navigation_analytics (
  id          UUID        NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  user_id     UUID        REFERENCES auth.users(id) ON DELETE SET NULL,
  event_type  TEXT        NOT NULL,
  event_data  JSONB,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.navigation_analytics ENABLE ROW LEVEL SECURITY;

GRANT INSERT ON public.navigation_analytics TO authenticated;
GRANT ALL   ON public.navigation_analytics TO service_role;

DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'navigation_analytics'
      AND policyname = 'Users can insert own navigation events'
  ) THEN
    CREATE POLICY "Users can insert own navigation events"
      ON public.navigation_analytics FOR INSERT TO authenticated
      WITH CHECK (auth.uid() = user_id);
  END IF;
END $$;

-- 2. product_views
CREATE TABLE IF NOT EXISTS public.product_views (
  id           UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id   TEXT,
  product_sku  TEXT,
  product_name TEXT,
  seller_id    UUID        REFERENCES auth.users(id) ON DELETE SET NULL,
  view_type    TEXT        NOT NULL DEFAULT 'detail',
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.product_views ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'product_views'
      AND policyname = 'Users can insert own views'
  ) THEN
    CREATE POLICY "Users can insert own views"
      ON public.product_views FOR INSERT TO authenticated
      WITH CHECK (seller_id = auth.uid());
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'product_views'
      AND policyname = 'Users can read own views'
  ) THEN
    CREATE POLICY "Users can read own views"
      ON public.product_views FOR SELECT TO authenticated
      USING (seller_id = auth.uid());
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'product_views'
      AND policyname = 'Admins can read all views'
  ) THEN
    CREATE POLICY "Admins can read all views"
      ON public.product_views FOR SELECT TO authenticated
      USING (public.has_role(auth.uid(), 'admin'));
  END IF;
END $$;

-- 3. discount_approval_requests
CREATE TABLE IF NOT EXISTS public.discount_approval_requests (
  id                          UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
  quote_id                    UUID        NOT NULL REFERENCES public.quotes(id) ON DELETE CASCADE,
  seller_id                   UUID        NOT NULL,
  requested_discount_percent  NUMERIC     NOT NULL,
  max_allowed_percent         NUMERIC     NOT NULL,
  status                      TEXT        NOT NULL DEFAULT 'pending',
  admin_id                    UUID,
  admin_notes                 TEXT,
  seller_notes                TEXT,
  responded_at                TIMESTAMPTZ,
  created_at                  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at                  TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.discount_approval_requests ENABLE ROW LEVEL SECURITY;

DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'discount_approval_requests'
      AND policyname = 'Admins can manage all approval requests'
  ) THEN
    CREATE POLICY "Admins can manage all approval requests"
      ON public.discount_approval_requests FOR ALL TO authenticated
      USING     (public.has_role(auth.uid(), 'admin'::app_role))
      WITH CHECK (public.has_role(auth.uid(), 'admin'::app_role));
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'discount_approval_requests'
      AND policyname = 'Sellers can read own approval requests'
  ) THEN
    CREATE POLICY "Sellers can read own approval requests"
      ON public.discount_approval_requests FOR SELECT TO authenticated
      USING (seller_id = auth.uid());
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'discount_approval_requests'
      AND policyname = 'Sellers can insert own approval requests'
  ) THEN
    CREATE POLICY "Sellers can insert own approval requests"
      ON public.discount_approval_requests FOR INSERT TO authenticated
      WITH CHECK (seller_id = auth.uid());
  END IF;
END $$;

-- Auto-update updated_at on discount_approval_requests
CREATE OR REPLACE FUNCTION public.update_discount_approval_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_discount_approval_updated_at'
      AND tgrelid = 'public.discount_approval_requests'::regclass
  ) THEN
    CREATE TRIGGER trg_discount_approval_updated_at
      BEFORE UPDATE ON public.discount_approval_requests
      FOR EACH ROW EXECUTE FUNCTION public.update_discount_approval_updated_at();
  END IF;
END $$;

-- <<< END 20260611163809_create_missing_analytics_and_approval_tables.sql <<<

-- >>> BEGIN 20260611164038_fix_asia_promote_circumference_cm.sql >>>
-- Corrige fn_asia_site_promote_to_gold para propagar circumference_cm
-- tanto para product_physical quanto para products.circumference_cm.
CREATE OR REPLACE FUNCTION public.fn_asia_site_promote_to_gold(
  p_limit    integer DEFAULT NULL::integer,
  p_only_new boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_ASIA     uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_linked   int  := 0;
  v_phys     int  := 0;
  v_scalars  int  := 0;
  v_promoted int  := 0;
  v_zombies  int  := 0;
BEGIN

  -- ── STEP -1: Limpar produtos-zombie com supplier_reference IS NULL
  WITH zombie_candidates AS (
    SELECT p.id AS zombie_id
    FROM products p
    WHERE p.supplier_id = v_ASIA
      AND (p.supplier_reference IS NULL OR p.supplier_reference = '')
      AND p.is_active = false
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.is_active=true)
      AND NOT EXISTS (SELECT 1 FROM product_videos pv WHERE pv.product_id=p.id AND pv.is_active=true)
      AND EXISTS (
        SELECT 1 FROM products p2
        WHERE p2.supplier_id = v_ASIA
          AND p2.is_active = true
          AND p2.supplier_reference IS NOT NULL
          AND lower(trim(p2.name)) = lower(trim(p.name))
      )
  )
  DELETE FROM product_variants pv2
  USING zombie_candidates zc
  WHERE pv2.product_id = zc.zombie_id;

  WITH zombie_products AS (
    SELECT p.id AS zombie_id
    FROM products p
    WHERE p.supplier_id = v_ASIA
      AND (p.supplier_reference IS NULL OR p.supplier_reference = '')
      AND p.is_active = false
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.is_active=true)
      AND NOT EXISTS (SELECT 1 FROM product_videos pv WHERE pv.product_id=p.id AND pv.is_active=true)
      AND EXISTS (
        SELECT 1 FROM products p2
        WHERE p2.supplier_id = v_ASIA AND p2.is_active = true
          AND p2.supplier_reference IS NOT NULL
          AND lower(trim(p2.name)) = lower(trim(p.name))
      )
  )
  DELETE FROM products p3 USING zombie_products zp WHERE p3.id = zp.zombie_id;
  GET DIAGNOSTICS v_zombies = ROW_COUNT;

  -- ── STEP 0: Vincular product_id via Silver principal
  WITH lnk AS (
    SELECT s.id, p.product_id
    FROM public.produtos_site_padronizacao s
    JOIN public.produtos_padronizacao p
      ON p.supplier_id = s.supplier_id
     AND p.supplier_reference = s.supplier_reference
    WHERE s.supplier_id = v_ASIA
      AND p.product_id IS NOT NULL
      AND s.product_id IS NULL
      AND s.status <> 'rejected'
  )
  UPDATE public.produtos_site_padronizacao t
     SET product_id = lnk.product_id, updated_at = now()
    FROM lnk WHERE t.id = lnk.id;
  GET DIAGNOSTICS v_linked = ROW_COUNT;

  CREATE TEMP TABLE _asia_site_scope ON COMMIT DROP AS
    SELECT s.* FROM public.produtos_site_padronizacao s
    WHERE s.supplier_id = v_ASIA
      AND s.product_id IS NOT NULL
      AND s.status = CASE WHEN p_only_new
                          THEN 'standardized'::public.produtos_padronizacao_status
                          ELSE s.status END
      AND s.status <> 'rejected'
    LIMIT COALESCE(p_limit, 1000000000);

  IF NOT EXISTS (SELECT 1 FROM _asia_site_scope) THEN
    RETURN jsonb_build_object(
      'linked', v_linked, 'note', 'nada_novo', 'zombies_removidos', v_zombies
    );
  END IF;

  -- (e) product_physical: peso + dimensoes (incluindo circumference_cm)
  INSERT INTO public.product_physical (
    product_id, weight_g, height_cm, width_cm, length_cm, circumference_cm
  )
  SELECT
    product_id,
    weight_g::numeric,
    height_cm,
    width_cm,
    depth_cm,
    circumference_cm
  FROM _asia_site_scope
  WHERE weight_g IS NOT NULL OR height_cm IS NOT NULL
     OR width_cm IS NOT NULL  OR depth_cm IS NOT NULL
     OR circumference_cm IS NOT NULL
  ON CONFLICT (product_id) DO UPDATE SET
    weight_g         = COALESCE(public.product_physical.weight_g,         EXCLUDED.weight_g),
    height_cm        = COALESCE(public.product_physical.height_cm,        EXCLUDED.height_cm),
    width_cm         = COALESCE(public.product_physical.width_cm,         EXCLUDED.width_cm),
    length_cm        = COALESCE(public.product_physical.length_cm,        EXCLUDED.length_cm),
    circumference_cm = COALESCE(public.product_physical.circumference_cm, EXCLUDED.circumference_cm),
    updated_at = now();
  GET DIAGNOSTICS v_phys = ROW_COUNT;

  -- (f) products: propagar circumference_cm diretamente na tabela Gold
  -- (fill-only — não sobrescreve valor já preenchido manualmente)
  UPDATE public.products p SET
    circumference_cm = COALESCE(p.circumference_cm, s.circumference_cm),
    updated_at       = now()
  FROM _asia_site_scope s
  WHERE p.id = s.product_id
    AND s.circumference_cm IS NOT NULL
    AND p.circumference_cm IS NULL;

  -- (h) products: fill-only escalares WP-exclusive
  UPDATE public.products p SET
    brand                  = COALESCE(p.brand,                  s.brand),
    min_order_quantity     = COALESCE(p.min_order_quantity,     s.moq),
    min_quantity           = COALESCE(p.min_quantity,           s.min_quantity),
    requires_minimum_order = COALESCE(p.requires_minimum_order,
                               CASE WHEN s.moq IS NOT NULL THEN (s.moq > 1) ELSE NULL END),
    sale_price             = COALESCE(p.sale_price,             s.sale_price),
    is_on_sale             = COALESCE(p.is_on_sale,             s.is_on_sale),
    suggested_price        = COALESCE(p.suggested_price,        s.regular_price),
    updated_at             = now()
  FROM _asia_site_scope s
  WHERE p.id = s.product_id
    AND (s.brand IS NOT NULL OR s.moq IS NOT NULL
      OR s.sale_price IS NOT NULL OR s.regular_price IS NOT NULL
      OR s.is_on_sale IS NOT NULL);
  GET DIAGNOSTICS v_scalars = ROW_COUNT;

  -- Marcar promovidas
  UPDATE public.produtos_site_padronizacao t
     SET status      = 'promoted'::public.produtos_padronizacao_status,
         promoted_at = now(),
         updated_at  = now()
   WHERE t.id IN (SELECT id FROM _asia_site_scope);
  GET DIAGNOSTICS v_promoted = ROW_COUNT;

  RETURN jsonb_build_object(
    'linked',            v_linked,
    'physical',          v_phys,
    'scalars',           v_scalars,
    'promoted',          v_promoted,
    'zombies_removidos', v_zombies
  );
END;
$function$;

-- <<< END 20260611164038_fix_asia_promote_circumference_cm.sql <<<

