-- >>> BEGIN 20260611175537_xbz_fix_remaining_products_and_assignments.sql >>>

-- Passo 5 final: mapear os 3 XBZ restantes + criar assignments para todos os 104 mapeados

-- 1. Mapear os 3 que ainda não têm categoria
UPDATE products
SET category_id = 'd9fbf215-1841-4f2b-9a7c-e5b0238fbcda',
    updated_at = now()
WHERE sku IN ('19141','19141A','P$CX7146')
  AND supplier_id = 'd6718a29-e954-4c1b-bd84-03ea24884900'
  AND is_active = true;

-- 2. Criar assignments primários para TODOS os XBZ que agora têm category_id mas sem primário
-- (inclui os 48 do UPDATE anterior + os 3 recém-mapeados = 51 produtos)
INSERT INTO product_category_assignments (product_id, category_id, is_primary, display_order, created_at)
SELECT 
  p.id,
  p.category_id,
  true,
  1,
  now()
FROM products p
WHERE p.supplier_id = 'd6718a29-e954-4c1b-bd84-03ea24884900'
  AND p.is_active = true
  AND p.category_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM product_category_assignments pca 
    WHERE pca.product_id = p.id AND pca.is_primary = true
  )
  AND NOT EXISTS (
    SELECT 1 FROM product_category_assignments pca2
    WHERE pca2.product_id = p.id AND pca2.category_id = p.category_id
  )
ON CONFLICT (product_id, category_id) DO NOTHING;

-- 3. Para os que já tinham o category_id na pivot mas não como primário
INSERT INTO product_category_assignments (product_id, category_id, is_primary, display_order, created_at)
SELECT 
  p.id,
  p.category_id,
  true,
  1,
  now()
FROM products p
WHERE p.supplier_id = 'd6718a29-e954-4c1b-bd84-03ea24884900'
  AND p.is_active = true
  AND p.category_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM product_category_assignments pca 
    WHERE pca.product_id = p.id AND pca.is_primary = true
  )
ON CONFLICT (product_id, category_id) DO UPDATE SET is_primary = true;
;

-- <<< END 20260611175537_xbz_fix_remaining_products_and_assignments.sql <<<

-- >>> BEGIN 20260611175639_asia_fix_13_products_without_category_v2.sql >>>

-- Passo 6 v2: Asia Import — mapear 13 produtos sem category_id + criar assignments (com cast)

UPDATE products
SET category_id = CASE
    WHEN sku = 'SVT010P' THEN '6f595c2f-907d-4b0b-9f62-13eef959aa0c'::uuid
    WHEN sku = 'LC210P'  THEN '402679eb-bb0e-48d2-bea2-4da27239b995'::uuid
    WHEN sku IN ('PL01PP','PL02PP','PL05PP','PL04','PL05') 
                         THEN 'd9fbf215-1841-4f2b-9a7c-e5b0238fbcda'::uuid
    WHEN sku = 'PCA100P' THEN 'd9fbf215-1841-4f2b-9a7c-e5b0238fbcda'::uuid
    WHEN sku IN ('PA150P','PA140P') 
                         THEN '1f004c4e-0d01-47b9-9b97-0fc4d8bca2d1'::uuid
    WHEN sku IN ('PCL100P','PCL120PP') 
                         THEN 'd9fbf215-1841-4f2b-9a7c-e5b0238fbcda'::uuid
    WHEN sku = 'PT1050P' THEN 'e6134500-5231-4de4-b69b-fbf3970572fa'::uuid
  END,
  updated_at = now()
WHERE supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'
  AND is_active = true
  AND sku IN ('SVT010P','LC210P','PL01PP','PL02PP','PL05PP','PL04','PL05',
              'PCA100P','PA150P','PA140P','PCL100P','PCL120PP','PT1050P');

-- Criar assignments primários para os 13 recém-mapeados
INSERT INTO product_category_assignments (product_id, category_id, is_primary, display_order, created_at)
SELECT 
  p.id,
  p.category_id,
  true,
  1,
  now()
FROM products p
WHERE p.supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118'
  AND p.is_active = true
  AND p.sku IN ('SVT010P','LC210P','PL01PP','PL02PP','PL05PP','PL04','PL05',
                'PCA100P','PA150P','PA140P','PCL100P','PCL120PP','PT1050P')
  AND p.category_id IS NOT NULL
ON CONFLICT (product_id, category_id) DO UPDATE SET is_primary = true;
;

