-- >>> BEGIN 20260611181802_create_attribute_equivalences_table.sql >>>

-- Passo 9: Criar tabela attribute_equivalences
-- Bridge entre atributos de fornecedores e atributos padronizados do Promo Brindes
-- Mesma lógica do supplier_category_mappings mas para VALORES de atributos

CREATE TABLE IF NOT EXISTS public.attribute_equivalences (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  -- Fornecedor de origem
  supplier_id           uuid NOT NULL REFERENCES public.suppliers(id),
  source                text NOT NULL,       -- 'SPOT' | 'XBZ' | 'ASIA' | 'SOMARCAS'

  -- Atributo no fornecedor (texto livre — chave e valor originais)
  supplier_attr_key     text NOT NULL,       -- ex: 'Properties', 'Certificates', 'Material'
  supplier_attr_value   text NOT NULL,       -- ex: 'BPA free', 'Food Safety', 'Aço Inoxidável'

  -- Atributo padronizado no Promo Brindes
  promo_attr_key        text NOT NULL,       -- ex: 'livre_bpa', 'material_corpo', 'certificacao'
  promo_attr_value      text NOT NULL,       -- ex: 'true', 'Inox', 'BPA Free'
  promo_attr_type       text NOT NULL DEFAULT 'text',  -- 'text' | 'boolean' | 'number' | 'select'
  promo_attr_unit       text,               -- ex: 'ml', 'g', 'cm'

  -- Qualidade do mapeamento
  confidence            numeric(4,2) NOT NULL DEFAULT 1.00 CHECK (confidence BETWEEN 0 AND 1),
  match_quality         text NOT NULL DEFAULT 'manual'
                          CHECK (match_quality IN ('exact','partial','manual','ai_suggested')),
  verified              boolean NOT NULL DEFAULT false,
  verified_by           uuid REFERENCES auth.users(id),
  verified_at           timestamptz,

  -- Metadados
  notes                 text,
  is_active             boolean NOT NULL DEFAULT true,
  organization_id       uuid,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),

  -- Unicidade: mesmo fornecedor + mesma chave + mesmo valor origem = 1 mapeamento
  UNIQUE (supplier_id, supplier_attr_key, supplier_attr_value, promo_attr_key)
);

-- Índices para performance no pipeline de promoção Silver→Gold
CREATE INDEX IF NOT EXISTS idx_aeq_supplier_key_value
  ON public.attribute_equivalences (supplier_id, supplier_attr_key, supplier_attr_value)
  WHERE is_active = true;

CREATE INDEX IF NOT EXISTS idx_aeq_promo_key
  ON public.attribute_equivalences (promo_attr_key)
  WHERE is_active = true;

CREATE INDEX IF NOT EXISTS idx_aeq_pending_review
  ON public.attribute_equivalences (confidence, verified)
  WHERE is_active = true AND confidence < 0.80;

-- Trigger de updated_at
CREATE OR REPLACE FUNCTION public.fn_set_updated_at_aeq()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;

DROP TRIGGER IF EXISTS trg_aeq_updated_at ON public.attribute_equivalences;
CREATE TRIGGER trg_aeq_updated_at
  BEFORE UPDATE ON public.attribute_equivalences
  FOR EACH ROW EXECUTE FUNCTION public.fn_set_updated_at_aeq();

-- RLS: somente roles autorizados leem/escrevem
ALTER TABLE public.attribute_equivalences ENABLE ROW LEVEL SECURITY;

CREATE POLICY "aeq_select_authenticated"
  ON public.attribute_equivalences FOR SELECT
  TO authenticated USING (true);

CREATE POLICY "aeq_write_service_role"
  ON public.attribute_equivalences FOR ALL
  TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE public.attribute_equivalences IS
  'De-para entre valores de atributos de fornecedores e atributos padronizados do catálogo Promo Brindes. '
  'Alimenta fn_promote_padronizacao ao promover Silver→Gold para normalizar Properties/Certificates/Materials.';
;

-- <<< END 20260611181802_create_attribute_equivalences_table.sql <<<

-- >>> BEGIN 20260611181838_create_product_attributes_table.sql >>>

-- Passo 10-A: Criar tabela product_attributes
-- Armazena atributos estruturados por produto no Gold (material, capacidade, BPA free, etc.)
-- Alimentada pela fn_promote_padronizacao via attribute_equivalences

CREATE TABLE IF NOT EXISTS public.product_attributes (
  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),

  -- Produto Gold ao qual o atributo pertence
  product_id        uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,

  -- Atributo (chave snake_case, valor sempre como text + tipo para conversão)
  attribute_key     text NOT NULL,       -- ex: 'material_corpo', 'capacidade', 'livre_bpa'
  attribute_value   text NOT NULL,       -- ex: 'Inox', '500', 'true'
  attribute_type    text NOT NULL DEFAULT 'text'
                      CHECK (attribute_type IN ('text','number','boolean','select','multiselect')),
  attribute_unit    text,               -- ex: 'ml', 'g', 'cm', 'horas'

  -- Fonte do atributo (rastreabilidade)
  source_supplier   text,              -- 'SPOT' | 'XBZ' | 'ASIA' | 'SOMARCAS'
  source_field      text,              -- campo original: 'Properties', 'Certificates', 'Materials'
  source_raw_value  text,              -- valor original antes da normalização

  -- Exibição
  display_order     integer DEFAULT 0,
  is_visible        boolean NOT NULL DEFAULT true,   -- aparece na ficha do produto
  is_filterable     boolean NOT NULL DEFAULT false,  -- aparece nos filtros de busca
  is_comparable     boolean NOT NULL DEFAULT true,   -- aparece na comparação de produtos

  -- Auditoria
  is_active         boolean NOT NULL DEFAULT true,
  created_at        timestamptz NOT NULL DEFAULT now(),
  updated_at        timestamptz NOT NULL DEFAULT now(),

  -- Unicidade: mesmo produto + mesma chave = 1 valor (upsert-safe)
  UNIQUE (product_id, attribute_key)
);

-- Índices para performance de filtros de catálogo
CREATE INDEX IF NOT EXISTS idx_pa_product_id
  ON public.product_attributes (product_id)
  WHERE is_active = true;

CREATE INDEX IF NOT EXISTS idx_pa_filterable_key_value
  ON public.product_attributes (attribute_key, attribute_value)
  WHERE is_active = true AND is_filterable = true;

CREATE INDEX IF NOT EXISTS idx_pa_supplier
  ON public.product_attributes (source_supplier, attribute_key)
  WHERE is_active = true;

-- Índice para busca por atributos booleanos (BPA free, etc.)
CREATE INDEX IF NOT EXISTS idx_pa_boolean_attrs
  ON public.product_attributes (attribute_key)
  WHERE is_active = true AND attribute_type = 'boolean' AND attribute_value = 'true';

-- Trigger updated_at
CREATE OR REPLACE FUNCTION public.fn_set_updated_at_pa()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;

DROP TRIGGER IF EXISTS trg_pa_updated_at ON public.product_attributes;
CREATE TRIGGER trg_pa_updated_at
  BEFORE UPDATE ON public.product_attributes
  FOR EACH ROW EXECUTE FUNCTION public.fn_set_updated_at_pa();

-- RLS
ALTER TABLE public.product_attributes ENABLE ROW LEVEL SECURITY;

CREATE POLICY "pa_select_public"
  ON public.product_attributes FOR SELECT
  USING (is_active = true AND is_visible = true);

CREATE POLICY "pa_select_authenticated_all"
  ON public.product_attributes FOR SELECT
  TO authenticated USING (true);

CREATE POLICY "pa_write_service_role"
  ON public.product_attributes FOR ALL
  TO service_role USING (true) WITH CHECK (true);

COMMENT ON TABLE public.product_attributes IS
  'Atributos estruturados por produto Gold — material, capacidade, BPA free, etc. '
  'Populada via fn_promote_padronizacao usando attribute_equivalences como de-para. '
  'Fonte primária para filtros de catálogo e comparação de produtos.';
;

