-- >>> BEGIN 20260611214640_create_fn_promote_notebook_specs_v1.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- fn_promote_notebook_specs — Função mestre que:
-- 1. Identifica produtos Gold que são material gráfico
-- 2. Extrai todos os atributos via parsers
-- 3. Faz UPSERT em product_notebook_specs
-- 4. Sincroniza product_notebook_features
--
-- Modo de uso:
-- fn_promote_notebook_specs()            — processa todos pending
-- fn_promote_notebook_specs(p_product_id) — processa 1 produto
-- fn_promote_notebook_specs(p_limit := N) — processa até N produtos
-- ═══════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_promote_notebook_specs(
  p_product_id uuid    DEFAULT NULL,  -- NULL = processa todos
  p_limit      int     DEFAULT 500,   -- max por execução
  p_force      boolean DEFAULT false  -- re-processa mesmo se já existe
)
RETURNS jsonb  -- {processed, inserted, updated, features_added, errors, skipped}
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_processed   int := 0;
  v_inserted    int := 0;
  v_updated     int := 0;
  v_feat_added  int := 0;
  v_skipped     int := 0;
  v_errors      int := 0;
  v_error_sample text[] := ARRAY[]::text[];

  -- Cursor de produtos
  r RECORD;

  -- Valores extraídos
  v_format_code   text;
  v_ruling_code   text;
  v_weight_gsm    int;
  v_color_code    text;
  v_binding_code  text;
  v_binding_color text;
  v_cover_type    text;
  v_cover_mat     text;
  v_cover_finish  text;
  v_sheets        int;
  v_feature_codes text[];
  v_confidence    numeric;

  -- IDs das lookup tables
  v_format_id    uuid; v_ruling_id   uuid; v_weight_id   uuid;
  v_color_id     uuid; v_binding_id  uuid; v_bcolor_id   uuid;
  v_ctype_id     uuid; v_cmat_id     uuid; v_cfinish_id  uuid;
  v_feat_id      uuid;
  v_spec_id      uuid;

  v_lock_key     bigint := 88675432;  -- advisory lock para evitar runs paralelos
BEGIN
  -- ── Advisory lock (não-blocking) ─────────────────────────────
  IF NOT pg_try_advisory_xact_lock(v_lock_key) THEN
    RETURN jsonb_build_object('skipped','already_running');
  END IF;

  -- ── Cursor de produtos a processar ───────────────────────────
  FOR r IN (
    SELECT DISTINCT
      p.id                         AS product_id,
      p.supplier_id,
      s.name                       AS supplier_name,
      pp.supplier_reference,
      pp.supplier_subtype,
      pp.supplier_subtype_code,
      pp.name,
      pp.description,
      pp.combined_sizes,
      pp.materials,
      pp.tags,
      pp.meta_keywords,
      pp.is_textil
    FROM products p
    JOIN suppliers s ON s.id = p.supplier_id
    -- Pegar dados do Silver (último promoted para este product_id)
    JOIN LATERAL (
      SELECT pp2.*
      FROM produtos_padronizacao pp2
      WHERE pp2.product_id = p.id
        AND pp2.status = 'promoted'
      ORDER BY pp2.promoted_at DESC NULLS LAST
      LIMIT 1
    ) pp ON true
    -- Filtrar por produto específico OU todos sem spec (ou force=true)
    WHERE (p_product_id IS NULL OR p.id = p_product_id)
      AND p.is_active = true
      AND fn_is_graphic_material(
            pp.supplier_subtype, pp.supplier_subtype_code,
            pp.name, pp.meta_keywords, pp.tags, pp.is_textil
          ) = true
      AND (
        p_force = true
        OR NOT EXISTS (
          SELECT 1 FROM product_notebook_specs pns WHERE pns.product_id = p.id
        )
      )
    ORDER BY p.id
    LIMIT p_limit
  ) LOOP

    BEGIN  -- Per-product exception block
      v_processed := v_processed + 1;

      -- ── Extrair todos os atributos ──────────────────────────
      v_format_code  := fn_parse_paper_format(r.tags, r.name, r.description, r.combined_sizes);
      v_ruling_code  := fn_parse_paper_ruling(r.tags, r.name, r.description);
      v_weight_gsm   := fn_parse_paper_weight(r.description);
      v_color_code   := fn_parse_paper_color_code(r.tags, r.description);
      v_binding_code := fn_parse_binding_type_code(r.name, r.description);
      v_cover_type   := fn_parse_cover_type_code(r.name, r.description);
      v_cover_mat    := fn_parse_cover_material_code(r.materials, r.name, r.description);
      v_cover_finish := NULL;  -- extraído via COVER_FINISHES na v2
      v_sheets       := fn_parse_sheet_count(r.description);
      v_feature_codes := fn_extract_notebook_feature_codes(r.tags, r.description, r.name);

      -- ── Resolver binding color ──────────────────────────────
      v_binding_color := fn_parse_binding_color_code(r.description);

      -- ── Calcular confidence score ───────────────────────────
      v_confidence := (
        (CASE WHEN v_format_code  IS NOT NULL THEN 0.20 ELSE 0 END) +
        (CASE WHEN v_cover_mat    IS NOT NULL THEN 0.20 ELSE 0 END) +
        (CASE WHEN v_ruling_code  IS NOT NULL THEN 0.15 ELSE 0 END) +
        (CASE WHEN v_cover_type   IS NOT NULL THEN 0.15 ELSE 0 END) +
        (CASE WHEN v_sheets       IS NOT NULL THEN 0.15 ELSE 0 END) +
        (CASE WHEN v_weight_gsm   IS NOT NULL THEN 0.10 ELSE 0 END) +
        (CASE WHEN v_binding_code IS NOT NULL THEN 0.05 ELSE 0 END)
      )::numeric(3,2);

      -- ── Resolver IDs das lookup tables ─────────────────────
      SELECT id INTO v_format_id   FROM paper_formats   WHERE code = v_format_code;
      SELECT id INTO v_ruling_id   FROM paper_rulings   WHERE code = v_ruling_code;
      SELECT id INTO v_weight_id   FROM paper_weights   WHERE weight_gsm = v_weight_gsm;
      SELECT id INTO v_color_id    FROM paper_colors    WHERE code = v_color_code;
      SELECT id INTO v_binding_id  FROM binding_types   WHERE code = v_binding_code;
      SELECT id INTO v_bcolor_id   FROM binding_colors  WHERE code = v_binding_color;
      SELECT id INTO v_ctype_id    FROM cover_types     WHERE code = v_cover_type;
      SELECT id INTO v_cmat_id     FROM cover_materials WHERE code = v_cover_mat;
      -- cover_finish: detectar MATTE/SOFT_TOUCH/GLOSSY via nome/descrição
      SELECT id INTO v_cfinish_id FROM cover_finishes WHERE code = (
        CASE 
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%soft touch%' THEN 'SOFT_TOUCH'
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%fosco%' THEN 'MATTE'
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%brilhante%' THEN 'GLOSSY'
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%metalizado%' THEN 'METALLIC'
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%alto relevo%' OR
               lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%emboss%' THEN 'EMBOSSED'
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%baixo relevo%' OR
               lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%deboss%' THEN 'DEBOSSED'
          WHEN lower(coalesce(r.name,'') || ' ' || coalesce(r.description,'')) ILIKE '%uv%' THEN 'UV_SPOT'
          ELSE NULL
        END
      );

      -- ── UPSERT em product_notebook_specs ───────────────────
      INSERT INTO product_notebook_specs (
        product_id, paper_format_id, paper_ruling_id, paper_weight_id,
        paper_color_id, binding_type_id, binding_color_id,
        cover_type_id, cover_material_id, cover_finish_id,
        sheet_count, source_supplier, confidence_score
      ) VALUES (
        r.product_id, v_format_id, v_ruling_id, v_weight_id,
        v_color_id, v_binding_id, v_bcolor_id,
        v_ctype_id, v_cmat_id, v_cfinish_id,
        v_sheets, r.supplier_name, v_confidence
      )
      ON CONFLICT (product_id) DO UPDATE SET
        paper_format_id   = EXCLUDED.paper_format_id,
        paper_ruling_id   = EXCLUDED.paper_ruling_id,
        paper_weight_id   = EXCLUDED.paper_weight_id,
        paper_color_id    = EXCLUDED.paper_color_id,
        binding_type_id   = EXCLUDED.binding_type_id,
        binding_color_id  = EXCLUDED.binding_color_id,
        cover_type_id     = EXCLUDED.cover_type_id,
        cover_material_id = EXCLUDED.cover_material_id,
        cover_finish_id   = EXCLUDED.cover_finish_id,
        sheet_count       = EXCLUDED.sheet_count,
        source_supplier   = EXCLUDED.source_supplier,
        confidence_score  = EXCLUDED.confidence_score,
        updated_at        = now()
      WHERE product_notebook_specs.manually_reviewed = false
      RETURNING id INTO v_spec_id;

      IF v_spec_id IS NOT NULL THEN
        v_inserted := v_inserted + 1;
      ELSE
        -- updated (ON CONFLICT hit mas NOT RETURNING = manually reviewed, skip)
        v_updated := v_updated + 1;
      END IF;

      -- ── Sincronizar product_notebook_features ───────────────
      -- Remove features antigas não-manuais e reinsere
      DELETE FROM product_notebook_features
      WHERE product_id = r.product_id;

      FOREACH v_format_code IN ARRAY coalesce(v_feature_codes, ARRAY[]::text[]) LOOP
        SELECT id INTO v_feat_id FROM notebook_features WHERE code = v_format_code;
        IF v_feat_id IS NOT NULL THEN
          INSERT INTO product_notebook_features (product_id, feature_id)
          VALUES (r.product_id, v_feat_id)
          ON CONFLICT (product_id, feature_id) DO NOTHING;
          v_feat_added := v_feat_added + 1;
        END IF;
      END LOOP;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      v_error_sample := array_append(v_error_sample,
        format('%s: %s', r.supplier_reference, SQLERRM)
      );
      IF array_length(v_error_sample, 1) > 5 THEN EXIT; END IF;
    END;

  END LOOP;

  v_skipped := p_limit - v_processed;
  IF v_skipped < 0 THEN v_skipped := 0; END IF;

  RETURN jsonb_build_object(
    'processed',      v_processed,
    'inserted',       v_inserted,
    'updated',        v_updated,
    'features_added', v_feat_added,
    'errors',         v_errors,
    'error_samples',  v_error_sample,
    'confidence_avg', (
      SELECT round(avg(confidence_score)::numeric, 2)
      FROM product_notebook_specs
      WHERE updated_at > now() - interval '5 minutes'
    )
  );
END;
$$;

COMMENT ON FUNCTION public.fn_promote_notebook_specs IS
  'Promove specs de material gráfico do Silver → Gold. 
   Usa advisory lock. Idempotente. Respeita manually_reviewed=true.
   Retorna jsonb com métricas de execução.';
;

-- <<< END 20260611214640_create_fn_promote_notebook_specs_v1.sql <<<

-- >>> BEGIN 20260611214701_create_vw_product_notebook_complete_v1.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- VIEW CONSOLIDADA — Produto + todas as specs em uma única consulta
-- ═══════════════════════════════════════════════════════════════════

CREATE OR REPLACE VIEW public.vw_product_notebook_complete AS
SELECT
  -- ── Produto (Gold) ─────────────────────────────────────────
  p.id                    AS product_id,
  p.name                  AS product_name,
  p.sku                   AS sku,
  p.cost_price,
  p.is_active,
  s.name                  AS supplier_name,

  -- ── Formato ────────────────────────────────────────────────
  pf.code                 AS format_code,
  pf.name                 AS format_name,
  pf.width_cm,
  pf.height_cm,

  -- ── Papel ──────────────────────────────────────────────────
  pr.code                 AS ruling_code,
  pr.name                 AS ruling_name,
  pw.weight_gsm,
  pw.description          AS weight_description,
  pc.code                 AS paper_color_code,
  pc.name                 AS paper_color_name,
  pns.sheet_count,

  -- ── Encadernação ───────────────────────────────────────────
  bt.code                 AS binding_code,
  bt.name_pt              AS binding_name,
  bc.code                 AS binding_color_code,
  bc.name                 AS binding_color_name,

  -- ── Capa ───────────────────────────────────────────────────
  ct.code                 AS cover_type_code,
  ct.name                 AS cover_type_name,
  cm.code                 AS cover_material_code,
  cm.name                 AS cover_material_name,
  cm.is_eco_friendly,
  cf.code                 AS cover_finish_code,
  cf.name                 AS cover_finish_name,

  -- ── Meta ───────────────────────────────────────────────────
  pns.source_supplier,
  pns.confidence_score,
  pns.manually_reviewed,
  pns.created_at          AS spec_created_at,
  pns.updated_at          AS spec_updated_at,

  -- ── Features (array agregado) ──────────────────────────────
  COALESCE(
    array_agg(nf.code ORDER BY nf.display_order) 
    FILTER (WHERE nf.code IS NOT NULL),
    ARRAY[]::text[]
  )                       AS feature_codes,
  COALESCE(
    array_agg(nf.name ORDER BY nf.display_order)
    FILTER (WHERE nf.name IS NOT NULL),
    ARRAY[]::text[]
  )                       AS feature_names

FROM products p
JOIN suppliers s ON s.id = p.supplier_id
JOIN product_notebook_specs pns ON pns.product_id = p.id
LEFT JOIN paper_formats   pf ON pf.id = pns.paper_format_id
LEFT JOIN paper_rulings   pr ON pr.id = pns.paper_ruling_id
LEFT JOIN paper_weights   pw ON pw.id = pns.paper_weight_id
LEFT JOIN paper_colors    pc ON pc.id = pns.paper_color_id
LEFT JOIN binding_types   bt ON bt.id = pns.binding_type_id
LEFT JOIN binding_colors  bc ON bc.id = pns.binding_color_id
LEFT JOIN cover_types     ct ON ct.id = pns.cover_type_id
LEFT JOIN cover_materials cm ON cm.id = pns.cover_material_id
LEFT JOIN cover_finishes  cf ON cf.id = pns.cover_finish_id
LEFT JOIN product_notebook_features pnf ON pnf.product_id = p.id
LEFT JOIN notebook_features nf ON nf.id = pnf.feature_id
GROUP BY
  p.id, p.name, p.sku, p.cost_price, p.is_active, s.name,
  pf.code, pf.name, pf.width_cm, pf.height_cm,
  pr.code, pr.name, pw.weight_gsm, pw.description,
  pc.code, pc.name, pns.sheet_count,
  bt.code, bt.name_pt, bc.code, bc.name,
  ct.code, ct.name, cm.code, cm.name, cm.is_eco_friendly,
  cf.code, cf.name,
  pns.source_supplier, pns.confidence_score,
  pns.manually_reviewed, pns.created_at, pns.updated_at;

COMMENT ON VIEW public.vw_product_notebook_complete IS
  'View consolidada de produtos de material gráfico com todas as specs, 
   features agregadas e metadados de confiança.';
;

-- <<< END 20260611214701_create_vw_product_notebook_complete_v1.sql <<<

-- >>> BEGIN 20260611214834_fix_fn_parse_cover_material_priority_v2.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- FIX: fn_parse_cover_material_code v2
-- 
-- Bug: "lápis com borracha na ponta" estava matchando RUBBER
-- Fix: Campo materials (jsonb estruturado) tem prioridade ABSOLUTA.
--      Descrição só é usada como fallback se materials = NULL ou [].
-- ═══════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_parse_cover_material_code(
  p_materials jsonb, p_name text, p_description text
) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_mats_arr  text[];
  v_mat_lower text;
  v_desc      text := lower(coalesce(p_description,'') || ' ' || coalesce(p_name,''));
  i           int;
BEGIN
  -- ── PRIORIDADE 1: Campo materials estruturado (jsonb array) ──
  -- Extrair como array de texto e checar cada item
  IF p_materials IS NOT NULL AND jsonb_array_length(p_materials) > 0 THEN
    SELECT array_agg(lower(elem::text ->> 0)) INTO v_mats_arr
    FROM jsonb_array_elements(p_materials) elem;
    -- Se array processing falhar, tentar como texto
    IF v_mats_arr IS NULL THEN
      SELECT array_agg(lower(trim(elem #>> '{}'))) INTO v_mats_arr
      FROM jsonb_array_elements_text(p_materials) elem;
    END IF;
    
    FOR i IN 1..coalesce(array_length(v_mats_arr,1),0) LOOP
      v_mat_lower := v_mats_arr[i];
      IF v_mat_lower IS NULL THEN CONTINUE; END IF;
      
      -- Match exato ou parcial no campo materials (fonte mais confiável)
      IF v_mat_lower ILIKE '%pele reciclada%' OR v_mat_lower ILIKE '%couro reciclado%' THEN RETURN 'RECYCLED_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%pu à base de água%' OR v_mat_lower ILIKE '%pu a base de agua%' THEN RETURN 'PU_WATER'; END IF;
      IF v_mat_lower ILIKE '%genuine leather%' OR v_mat_lower ILIKE '%couro legítimo%' OR v_mat_lower ILIKE '%couro natural%' THEN RETURN 'GENUINE_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%couro sintético%' OR v_mat_lower ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%polipele%' THEN RETURN 'POLYLEATHER'; END IF;
      IF v_mat_lower = 'pu' OR v_mat_lower ILIKE '% pu' OR v_mat_lower ILIKE 'pu %' THEN RETURN 'PU'; END IF;
      IF v_mat_lower ILIKE '%rpet%' OR v_mat_lower ILIKE '%pet reciclado%' THEN RETURN 'RPET'; END IF;
      IF v_mat_lower ILIKE '%cortiça%' OR v_mat_lower ILIKE '%cork%' THEN RETURN 'CORK'; END IF;
      IF v_mat_lower ILIKE '%bambu%' OR v_mat_lower ILIKE '%bamboo%' THEN RETURN 'BAMBOO'; END IF;
      IF v_mat_lower ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
      -- Borracha/emborrachado APENAS quando é o material principal da capa
      -- (não quando é "borracha na ponta do lápis")
      IF (v_mat_lower = 'borracha' OR v_mat_lower ILIKE 'emborrachad%')
         AND v_mat_lower NOT ILIKE '%ponta%' THEN RETURN 'RUBBER'; END IF;
      IF v_mat_lower ILIKE '%linho%' OR v_mat_lower ILIKE '%linen%' THEN RETURN 'LINEN'; END IF;
      IF v_mat_lower ILIKE '%tecido%' OR v_mat_lower ILIKE '%poliéster%' OR v_mat_lower ILIKE '%algodão%' THEN RETURN 'FABRIC'; END IF;
      IF v_mat_lower ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;
      IF v_mat_lower ILIKE '%couchê%' OR v_mat_lower ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
      IF v_mat_lower ILIKE '%plástico%' OR v_mat_lower ILIKE '%plastic%' THEN RETURN 'PLASTIC'; END IF;
      -- Papel → Cartão (inclui variações)
      IF v_mat_lower ILIKE '%papel%' OR v_mat_lower ILIKE '%cartão%' OR v_mat_lower ILIKE '%cardboard%' THEN RETURN 'CARDBOARD'; END IF;
    END LOOP;
  END IF;

  -- ── PRIORIDADE 2: Nome do produto (mais restrito) ────────────
  -- Só checar no nome se é claramente um material de capa
  IF p_name ILIKE '%couro sintético%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
  IF p_name ILIKE '%cortiça%' THEN RETURN 'CORK'; END IF;
  IF p_name ILIKE '%bambu%' THEN RETURN 'BAMBOO'; END IF;
  IF p_name ILIKE '%rpet%' THEN RETURN 'RPET'; END IF;
  IF p_name ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
  IF p_name ILIKE '%emborrachad%' THEN RETURN 'RUBBER'; END IF;
  IF p_name ILIKE '%linho%' THEN RETURN 'LINEN'; END IF;
  IF p_name ILIKE '%couchê%' OR p_name ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
  -- PU no nome da capa: "CADERNETA EM PU", "CADERNETA PU A5"
  IF p_name ILIKE '% em pu%' OR p_name ILIKE '% pu %' OR p_name ILIKE '% pu$' THEN RETURN 'PU'; END IF;

  -- ── PRIORIDADE 3: Descrição (com cuidado — fonte menos confiável)
  -- Só checar expressões que claramente descrevem a CAPA, não o conteúdo
  IF v_desc ILIKE '%capa%couro sintético%' OR v_desc ILIKE '%couro sintético%capa%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
  IF v_desc ILIKE '%capa%em pu%' OR v_desc ILIKE '%em pu%capa%' THEN RETURN 'PU'; END IF;
  IF v_desc ILIKE '%capa%cortiça%' THEN RETURN 'CORK'; END IF;
  IF v_desc ILIKE '%capa%bambu%' THEN RETURN 'BAMBOO'; END IF;
  IF v_desc ILIKE '%capa%rpet%' THEN RETURN 'RPET'; END IF;
  IF v_desc ILIKE '%capa%percalux%' THEN RETURN 'PERCALUX'; END IF;
  -- Borracha na descrição APENAS se não há contexto de lápis/borracha de apagar
  IF v_desc ILIKE '%capa%borracha%' AND v_desc NOT ILIKE '%borracha na ponta%' AND v_desc NOT ILIKE '%lápis%borracha%' THEN
    RETURN 'RUBBER';
  END IF;
  IF v_desc ILIKE '%capa%linho%' THEN RETURN 'LINEN'; END IF;
  IF v_desc ILIKE '%capa%kraft%' THEN RETURN 'KRAFT'; END IF;
  IF v_desc ILIKE '%capa%plástico%' THEN RETURN 'PLASTIC'; END IF;
  IF v_desc ILIKE '%capa%papel%' OR v_desc ILIKE '%capa%cartão%' THEN RETURN 'CARDBOARD'; END IF;

  RETURN NULL;
END;
$$;
;

-- <<< END 20260611214834_fix_fn_parse_cover_material_priority_v2.sql <<<

-- >>> BEGIN 20260611214912_fix_fn_parse_cover_material_jsonb_v3.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- FIX v3: jsonb array extraction usando jsonb_array_elements_text
-- (elimina erro "operator does not exist: text ->> integer")
-- ═══════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_parse_cover_material_code(
  p_materials jsonb, p_name text, p_description text
) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_mat_lower text;
  v_pname     text := lower(coalesce(p_name,''));
  v_desc      text := lower(coalesce(p_description,''));
BEGIN
  -- ── PRIORIDADE 1: materials jsonb (array de strings) ─────────
  IF p_materials IS NOT NULL AND jsonb_array_length(p_materials) > 0 THEN
    FOR v_mat_lower IN
      SELECT lower(elem) FROM jsonb_array_elements_text(p_materials) AS t(elem)
    LOOP
      IF v_mat_lower IS NULL OR v_mat_lower = '' THEN CONTINUE; END IF;
      IF v_mat_lower ILIKE '%pele reciclada%' OR v_mat_lower ILIKE '%couro reciclado%' THEN RETURN 'RECYCLED_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%pu à base de água%' OR v_mat_lower ILIKE '%pu a base de agua%' THEN RETURN 'PU_WATER'; END IF;
      IF v_mat_lower ILIKE '%couro legítimo%' OR v_mat_lower ILIKE '%couro natural%' OR v_mat_lower ILIKE '%genuine leather%' THEN RETURN 'GENUINE_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%couro sintético%' OR v_mat_lower ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%polipele%' THEN RETURN 'POLYLEATHER'; END IF;
      -- PU: exato ou como prefixo/sufixo semântico
      IF v_mat_lower = 'pu' OR v_mat_lower ILIKE 'pu %' OR v_mat_lower ILIKE '% pu' OR v_mat_lower ILIKE '% pu %' THEN RETURN 'PU'; END IF;
      IF v_mat_lower ILIKE '%rpet%' OR v_mat_lower ILIKE '%pet reciclado%' THEN RETURN 'RPET'; END IF;
      IF v_mat_lower ILIKE '%cortiça%' OR v_mat_lower ILIKE '%cork%' THEN RETURN 'CORK'; END IF;
      IF v_mat_lower ILIKE '%bambu%' OR v_mat_lower ILIKE '%bamboo%' THEN RETURN 'BAMBOO'; END IF;
      IF v_mat_lower ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
      -- Borracha: só quando é o material da capa (não "borracha na ponta do lápis")
      IF (v_mat_lower = 'borracha' OR v_mat_lower ILIKE 'emborrachad%') THEN RETURN 'RUBBER'; END IF;
      IF v_mat_lower ILIKE '%linho%' OR v_mat_lower ILIKE '%linen%' THEN RETURN 'LINEN'; END IF;
      IF v_mat_lower ILIKE '%tecido%' OR v_mat_lower ILIKE '%poliéster%' OR v_mat_lower ILIKE '%algodão%' THEN RETURN 'FABRIC'; END IF;
      IF v_mat_lower ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;
      IF v_mat_lower ILIKE '%couchê%' OR v_mat_lower ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
      IF v_mat_lower ILIKE '%plástico%' OR v_mat_lower ILIKE '%plastic%' THEN RETURN 'PLASTIC'; END IF;
      IF v_mat_lower ILIKE '%papel%' OR v_mat_lower ILIKE '%cartão%' OR v_mat_lower ILIKE '%cardboard%' THEN RETURN 'CARDBOARD'; END IF;
    END LOOP;
  END IF;

  -- ── PRIORIDADE 2: Nome do produto ─────────────────────────────
  IF v_pname ILIKE '%couro sintético%' OR v_pname ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
  IF v_pname ILIKE '%em cortiça%' OR v_pname ILIKE '%cortiça%' THEN RETURN 'CORK'; END IF;
  IF v_pname ILIKE '%bambu%' THEN RETURN 'BAMBOO'; END IF;
  IF v_pname ILIKE '%rpet%' THEN RETURN 'RPET'; END IF;
  IF v_pname ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
  IF v_pname ILIKE '%emborrachad%' THEN RETURN 'RUBBER'; END IF;
  IF v_pname ILIKE '%linho%' THEN RETURN 'LINEN'; END IF;
  IF v_pname ILIKE '%couchê%' OR v_pname ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
  IF v_pname ILIKE '% em pu %' OR v_pname ILIKE '% em pu$' OR v_pname ILIKE '% pu %' OR v_pname ILIKE '% pu$' THEN RETURN 'PU'; END IF;
  IF v_pname ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;

  -- ── PRIORIDADE 3: Descrição (contexto de capa) ────────────────
  -- Só casar quando a palavra aparece junto com "capa" para evitar falsos positivos
  IF v_desc ILIKE '%capa%couro sintético%' OR v_desc ILIKE '%couro sintético%capa%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
  IF v_desc ILIKE '%capa%em pu%' OR v_desc ILIKE '%em pu%capa%' THEN RETURN 'PU'; END IF;
  IF v_desc ILIKE '%capa%cortiça%' THEN RETURN 'CORK'; END IF;
  IF v_desc ILIKE '%capa%bambu%' THEN RETURN 'BAMBOO'; END IF;
  IF v_desc ILIKE '%capa%rpet%' THEN RETURN 'RPET'; END IF;
  IF v_desc ILIKE '%capa%percalux%' THEN RETURN 'PERCALUX'; END IF;
  -- Borracha no contexto da capa — excluindo contexto de lápis/borracha de apagar
  IF v_desc ILIKE '%capa%borracha%' 
     AND v_desc NOT ILIKE '%borracha na ponta%'
     AND v_desc NOT ILIKE '%lápis%borracha%' THEN RETURN 'RUBBER'; END IF;
  IF v_desc ILIKE '%capa%linho%' THEN RETURN 'LINEN'; END IF;
  IF v_desc ILIKE '%capa%kraft%' THEN RETURN 'KRAFT'; END IF;
  IF v_desc ILIKE '%capa%plástico%' THEN RETURN 'PLASTIC'; END IF;
  IF v_desc ILIKE '%capa%papel%' OR v_desc ILIKE '%capa%cartão%' OR v_desc ILIKE '%cartonada%' THEN RETURN 'CARDBOARD'; END IF;

  RETURN NULL;
END;
$$;
;

-- <<< END 20260611214912_fix_fn_parse_cover_material_jsonb_v3.sql <<<

-- >>> BEGIN 20260611215000_create_fn_notebook_health_monitor_v1.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- fn_notebook_specs_health — Relatório de saúde do módulo notebooks
-- Retorna cobertura por fornecedor, fill-rate por campo e alertas
-- ═══════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_notebook_specs_health()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_total        int;
  v_by_supplier  jsonb;
  v_field_fills  jsonb;
  v_top_features jsonb;
  v_orphans      int;
  v_low_conf     int;
  v_no_spec      int;
  v_last_cron    text;
BEGIN
  SELECT COUNT(*) INTO v_total FROM product_notebook_specs;

  -- Coverage por fornecedor
  SELECT jsonb_agg(row_to_json(t)) INTO v_by_supplier FROM (
    SELECT 
      s.name AS supplier,
      COUNT(*) AS com_spec,
      round(100.0 * COUNT(*) / NULLIF(v_total,0), 1) AS pct_total,
      round(avg(pns.confidence_score)::numeric, 2) AS avg_confidence
    FROM product_notebook_specs pns
    JOIN products p ON p.id = pns.product_id
    JOIN suppliers s ON s.id = p.supplier_id
    GROUP BY s.name ORDER BY com_spec DESC
  ) t;

  -- Fill-rate por campo
  SELECT jsonb_build_object(
    'format_pct',   round(100.0 * COUNT(paper_format_id)::numeric / NULLIF(v_total,0), 1),
    'ruling_pct',   round(100.0 * COUNT(paper_ruling_id)::numeric / NULLIF(v_total,0), 1),
    'weight_pct',   round(100.0 * COUNT(paper_weight_id)::numeric / NULLIF(v_total,0), 1),
    'cover_mat_pct',round(100.0 * COUNT(cover_material_id)::numeric / NULLIF(v_total,0), 1),
    'cover_type_pct',round(100.0*COUNT(cover_type_id)::numeric / NULLIF(v_total,0), 1),
    'binding_pct',  round(100.0 * COUNT(binding_type_id)::numeric / NULLIF(v_total,0), 1),
    'sheets_pct',   round(100.0 * COUNT(sheet_count)::numeric / NULLIF(v_total,0), 1),
    'features_pct', round(100.0 * (SELECT COUNT(DISTINCT product_id) FROM product_notebook_features)::numeric / NULLIF(v_total,0), 1)
  ) INTO v_field_fills
  FROM product_notebook_specs;

  -- Top features
  SELECT jsonb_agg(row_to_json(t)) INTO v_top_features FROM (
    SELECT nf.code, nf.name, COUNT(*) AS n_products
    FROM product_notebook_features pnf
    JOIN notebook_features nf ON nf.id = pnf.feature_id
    GROUP BY nf.code, nf.name ORDER BY n_products DESC LIMIT 8
  ) t;

  -- Alertas
  SELECT COUNT(*) INTO v_orphans FROM product_notebook_specs
  WHERE paper_format_id IS NULL AND cover_material_id IS NULL 
    AND paper_ruling_id IS NULL AND sheet_count IS NULL;

  SELECT COUNT(*) INTO v_low_conf FROM product_notebook_specs
  WHERE confidence_score < 0.3;

  -- Produtos gráficos sem spec (classificados mas não processados)
  SELECT COUNT(*) INTO v_no_spec FROM products p
  JOIN LATERAL (
    SELECT pp2.* FROM produtos_padronizacao pp2
    WHERE pp2.product_id = p.id AND pp2.status = 'promoted'
    ORDER BY pp2.promoted_at DESC NULLS LAST LIMIT 1
  ) pp ON true
  JOIN suppliers s ON s.id = p.supplier_id
  WHERE p.is_active = true
    AND fn_is_graphic_material(pp.supplier_subtype, pp.supplier_subtype_code,
          pp.name, pp.meta_keywords, pp.tags, pp.is_textil) = true
    AND NOT EXISTS (SELECT 1 FROM product_notebook_specs pns WHERE pns.product_id = p.id);

  -- Último run do cron
  SELECT to_char(MAX(end_time), 'YYYY-MM-DD HH24:MI:SS') INTO v_last_cron
  FROM cron.job_run_details WHERE jobid = (
    SELECT jobid FROM cron.job WHERE jobname = 'notebook-specs-daily' LIMIT 1
  ) AND status = 'succeeded';

  RETURN jsonb_build_object(
    'status',          CASE WHEN v_orphans > 20 OR v_low_conf > 100 THEN 'warning' ELSE 'ok' END,
    'total_specs',     v_total,
    'by_supplier',     v_by_supplier,
    'field_fill_rates',v_field_fills,
    'top_features',    v_top_features,
    'alerts', jsonb_build_object(
      'orphan_specs_no_attrs', v_orphans,
      'low_confidence_lt30',   v_low_conf,
      'graphic_products_no_spec', v_no_spec
    ),
    'last_cron_run',   coalesce(v_last_cron, 'never')
  );
END;
$$;

COMMENT ON FUNCTION public.fn_notebook_specs_health IS
  'Relatório de saúde do módulo material gráfico. Retorna cobertura, fill-rates, alertas e stats de features.';
;

-- <<< END 20260611215000_create_fn_notebook_health_monitor_v1.sql <<<

-- >>> BEGIN 20260611215114_improve_notebook_parsers_sm_patterns_v4.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- REFINAMENTO v4: Melhorias para padrões SM e XBZ
-- 1. fn_parse_cover_type_code: detecta "capa dura" disperso na desc
-- 2. fn_parse_paper_ruling: padrão "para anotações" → RULED
-- 3. fn_parse_sheet_count: padrão SM "N folhas" sem "aproximadamente"
-- 4. fn_parse_binding_type_code: detecta Wire-o como "wiire" (typo XBZ)
-- ═══════════════════════════════════════════════════════════════════

-- Override fn_parse_cover_type_code — mais tolerante para SM
CREATE OR REPLACE FUNCTION public.fn_parse_cover_type_code(
  p_name text, p_description text
) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_all text := lower(coalesce(p_name,'') || ' ' || coalesce(p_description,''));
BEGIN
  -- Semi-rígida (antes de HARD para não pegar "dura" de semi-rígida)
  IF v_all ILIKE '%semi%rígida%' OR v_all ILIKE '%semi rígida%' THEN RETURN 'SEMI'; END IF;
  -- HARD
  IF v_all ILIKE ANY(ARRAY[
    '%capa dura%','%capa rígida%','%hard cover%','%hardcover%',
    '%cartonada%','%capa dura%'
  ]) THEN RETURN 'HARD'; END IF;
  -- SOFT
  IF v_all ILIKE ANY(ARRAY[
    '%capa flexível%','%capa mole%','%soft cover%','%softcover%',
    '%capa flex%'
  ]) THEN RETURN 'SOFT'; END IF;
  RETURN NULL;
END;
$$;

-- Override fn_parse_paper_ruling — "para anotações" implica pautado
CREATE OR REPLACE FUNCTION public.fn_parse_paper_ruling(
  p_tags jsonb, p_name text, p_description text
) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_tags text := lower(coalesce(p_tags::text,''));
  v_desc text := lower(coalesce(p_description,''));
  v_name text := lower(coalesce(p_name,''));
  v_all  text := v_tags || ' ' || v_desc || ' ' || v_name;
BEGIN
  -- Planner
  IF v_all ILIKE '%planner%' AND (v_all ILIKE '%planejamento%' OR v_all ILIKE '%agenda%' OR v_all ILIKE '%metas%') THEN
    RETURN 'PLANNER';
  END IF;
  -- Pontilhado / bullet journal
  IF v_all ILIKE ANY(ARRAY['%pontilhado%','%dotted%','%bullet journal%']) THEN RETURN 'DOTTED'; END IF;
  -- Quadriculado
  IF v_all ILIKE '%quadriculado%' THEN RETURN 'GRID'; END IF;
  -- Pautado explícito
  IF v_all ILIKE ANY(ARRAY[
    '%pautado%','%pauta%','%folhas pautadas%','%com pauta%',
    '%linhas%','%pautadas%'
  ]) THEN RETURN 'RULED'; END IF;
  -- Liso explícito
  IF v_all ILIKE ANY(ARRAY[
    '%liso%','%lisas%','%sem pauta%','%folhas lisas%','%sem linhas%',
    '%em branco%'
  ]) THEN RETURN 'BLANK'; END IF;
  -- Agenda → ruled (agendas têm layout de planejamento)
  IF v_all ILIKE ANY(ARRAY['%diária%','%semanal%','%plano diário%','%plano semanal%','%agenda%']) THEN
    RETURN 'RULED';
  END IF;
  -- "para anotações" → ruled (padrão SM — cadernos de anotações têm pauta)
  IF v_all ILIKE '%para anotações%' OR v_all ILIKE '%anotações%' THEN
    RETURN 'RULED';
  END IF;
  RETURN NULL;
END;
$$;

-- Melhorar fn_parse_sheet_count para padrões SM sem "aproximadamente"
CREATE OR REPLACE FUNCTION public.fn_parse_sheet_count(p_description text)
RETURNS int LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_desc    text := lower(coalesce(p_description,''));
  v_match   text[];
  v_n       int;
BEGIN
  -- "N folhas" — com ou sem "aproximadamente"
  SELECT m INTO v_match
  FROM regexp_matches(v_desc, '(?:(?:aproximadamente|com|possui|contém)\s+)?(\d+)\s*folhas?', 'g') AS t(m)
  LIMIT 1;
  IF v_match IS NOT NULL THEN
    v_n := v_match[1]::int;
    IF v_n BETWEEN 10 AND 1000 THEN RETURN v_n; END IF;
  END IF;
  -- "N páginas" → divide por 2
  SELECT m INTO v_match
  FROM regexp_matches(v_desc, '(?:(?:aproximadamente|com|possui|contém)\s+)?(\d+)\s*páginas?', 'g') AS t(m)
  LIMIT 1;
  IF v_match IS NOT NULL THEN
    v_n := v_match[1]::int;
    IF v_n BETWEEN 20 AND 2000 THEN RETURN v_n / 2; END IF;
  END IF;
  -- "N ff" ou "Nff" (abreviatura de folhas)
  SELECT m INTO v_match
  FROM regexp_matches(v_desc, '(\d+)\s*ff\b', 'g') AS t(m)
  LIMIT 1;
  IF v_match IS NOT NULL THEN
    v_n := v_match[1]::int;
    IF v_n BETWEEN 10 AND 500 THEN RETURN v_n; END IF;
  END IF;
  RETURN NULL;
END;
$$;
;

-- <<< END 20260611215114_improve_notebook_parsers_sm_patterns_v4.sql <<<

-- >>> BEGIN 20260611215711_fix_fn_is_graphic_material_calendario_v2.sql >>>

-- FIX: Calendário de mesa não é caderno
-- + Ampliar lista de exclusões por nome

CREATE OR REPLACE FUNCTION public.fn_is_graphic_material(
  p_supplier_subtype      text,
  p_supplier_subtype_code text,
  p_name                  text,
  p_meta_keywords         text[],
  p_tags                  jsonb,
  p_is_textil             boolean
)
RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_subtype_lower text := lower(coalesce(p_supplier_subtype,''));
  v_name_lower    text := lower(coalesce(p_name,''));
  v_kw_text       text := lower(array_to_string(coalesce(p_meta_keywords, ARRAY[]::text[]), ' '));
  v_tags_text     text := lower(coalesce(p_tags::text,''));
BEGIN
  -- ── 1. Excluir têxteis ────────────────────────────────────
  IF p_is_textil = true THEN RETURN false; END IF;

  -- ── 2. Excluir subtipos LAPTOP/MOCHILA/PASTA ─────────────
  IF v_subtype_lower ILIKE ANY(ARRAY[
    '%para notebook%','%bolso para notebook%','%notebook e tablet%',
    '%pastas para notebook%','%suporte para notebook%',
    '%para pc%','%p/ notebook%'
  ]) THEN RETURN false; END IF;

  -- ── 3. Excluir nomes claramente não-papelaria ─────────────
  IF v_name_lower ILIKE ANY(ARRAY[
    '%mochila%','%trolley%','%bolsa%',
    '% pasta %','%pasta executiva%','%pasta convenção%','%pasta notebook%',
    '%calendário de mesa%','%calendar de mesa%',
    '%porta-cartão%','%porta cartao%','%porta-caneta%',
    '%squeeze%','%caneca%','%garrafa%','%copo%',
    '%chaveiro%','%camiseta%'
  ]) THEN RETURN false; END IF;

  -- ── 4. Subtipo explícito de papelaria ────────────────────
  IF v_subtype_lower ILIKE ANY(ARRAY[
    '%agenda%','%bloco%','%caderno%','%caderneta%',
    '%planner%','%autoadesivos%','%notas adesivas%',
    '%papelaria%','%diário%','%com pauta%','%com caneta%',
    '%algodao%','%percalux%','%couro%'
  ]) THEN
    IF v_subtype_lower ILIKE '%notebook%' THEN RETURN false; END IF;
    RETURN true;
  END IF;

  -- ── 5. Nome claramente papelaria ─────────────────────────
  IF v_name_lower ILIKE ANY(ARRAY[
    '%caderno%','%caderneta%','%agenda%','%bloco%','%bloco de nota%',
    '%planner%','%diário%','%moleskine%','%sketchbook%'
  ]) THEN RETURN true; END IF;

  -- ── 6. Keywords ──────────────────────────────────────────
  IF v_kw_text ILIKE ANY(ARRAY[
    '%caderno%','%caderneta%','%bloco%','%agenda%','%planner%'
  ]) THEN RETURN true; END IF;

  -- ── 7. Tags — apenas se o NOME também não é de produto não-papelaria
  -- Requer que o nome não seja de produto ambíguo (calendário, etc.)
  IF v_tags_text ILIKE ANY(ARRAY[
    '%caderno%','%caderneta%','%agenda%','%bloco%','%planner%',
    '%folhas pautadas%','%folhas lisas%'
  ]) THEN
    IF v_name_lower ILIKE ANY(ARRAY['%mochila%','%bolsa%','%pasta%','%calendário%','%calendar%']) THEN
      RETURN false;
    END IF;
    RETURN true;
  END IF;
  -- Tags de formato (A4, A5, etc.) SÓ classificam como papelaria
  -- se o NOME também indica papelaria (evita calendários de mesa)
  IF v_tags_text ILIKE ANY(ARRAY[
    '%tamanho a3%','%tamanho a4%','%tamanho b5%','%tamanho a5%','%tamanho a6%','%tamanho a7%'
  ]) THEN
    IF v_name_lower ILIKE ANY(ARRAY[
      '%caderno%','%caderneta%','%agenda%','%bloco%','%planner%','%diário%','%sketchbook%'
    ]) THEN RETURN true; END IF;
    RETURN false;  -- tag de formato sem nome papelaria = não classificar
  END IF;

  RETURN false;
END;
$$;
;

-- <<< END 20260611215711_fix_fn_is_graphic_material_calendario_v2.sql <<<

-- >>> BEGIN 20260611215834_fix_fn_parse_paper_format_dimensions_v2.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- FIX v2: Dimensões — bug regexp_matches retornava text[][] não text[]
-- Também corrige: swap landscape, detecção cm vs mm
-- ═══════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_parse_paper_format(
  p_tags          jsonb,
  p_name          text,
  p_description   text,
  p_combined_sizes text
)
RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_tags  text := lower(coalesce(p_tags::text,''));
  v_name  text := upper(coalesce(p_name,''));
  v_desc  text := lower(coalesce(p_description,''));
  v_sizes text := lower(coalesce(p_combined_sizes,''));
  v_dim   text;
  v_nums  text[];
  v_w_mm  numeric;
  v_h_mm  numeric;
  v_tmp   numeric;
BEGIN
  -- ── Prioridade 1: tags estruturadas ───────────────────────
  IF v_tags ILIKE '%tamanho a3%' THEN RETURN 'A3'; END IF;
  IF v_tags ILIKE '%tamanho a4%' THEN RETURN 'A4'; END IF;
  IF v_tags ILIKE '%tamanho b5%' THEN RETURN 'B5'; END IF;
  IF v_tags ILIKE '%tamanho a5%' THEN RETURN 'A5'; END IF;
  IF v_tags ILIKE '%tamanho a6%' THEN RETURN 'A6'; END IF;
  IF v_tags ILIKE '%tamanho a7%' THEN RETURN 'A7'; END IF;

  -- ── Prioridade 2: nome (word boundary \m...\M) ────────────
  IF v_name ~ '\mA3\M' THEN RETURN 'A3'; END IF;
  IF v_name ~ '\mA4\M' THEN RETURN 'A4'; END IF;
  IF v_name ~ '\mB5\M' THEN RETURN 'B5'; END IF;
  IF v_name ~ '\mA5\M' THEN RETURN 'A5'; END IF;
  IF v_name ~ '\mA6\M' THEN RETURN 'A6'; END IF;
  IF v_name ~ '\mA7\M' THEN RETURN 'A7'; END IF;

  -- ── Prioridade 3: descrição ───────────────────────────────
  IF v_desc ~ '\ma3\M' THEN RETURN 'A3'; END IF;
  IF v_desc ~ '\ma4\M' THEN RETURN 'A4'; END IF;
  IF v_desc ~ '\mb5\M' THEN RETURN 'B5'; END IF;
  IF v_desc ~ '\ma5\M' THEN RETURN 'A5'; END IF;
  IF v_desc ~ '\ma6\M' THEN RETURN 'A6'; END IF;
  IF v_desc ~ '\ma7\M' THEN RETURN 'A7'; END IF;

  -- ── Prioridade 4: combined_sizes por dimensão ─────────────
  -- Pegar primeira parte (antes de '|')
  v_dim := trim(split_part(v_sizes, '|', 1));
  IF length(v_dim) < 3 THEN RETURN NULL; END IF;

  -- Extrair números usando regexp_matches corretamente (m[1] não m)
  SELECT array_agg(m[1]) INTO v_nums
  FROM regexp_matches(v_dim, '(\d+(?:[,\.]\d+)?)', 'g') AS t(m);

  IF v_nums IS NULL OR array_length(v_nums, 1) < 2 THEN RETURN NULL; END IF;

  -- Converter para numérico (tratar vírgula como separador decimal)
  v_w_mm := replace(v_nums[1], ',', '.')::numeric;
  v_h_mm := replace(v_nums[2], ',', '.')::numeric;

  -- Detectar cm vs mm: valores < 50 são provavelmente cm
  IF v_w_mm < 50 THEN v_w_mm := v_w_mm * 10; END IF;
  IF v_h_mm < 50 THEN v_h_mm := v_h_mm * 10; END IF;

  -- Normalizar para portrait (width ≤ height)
  IF v_w_mm > v_h_mm THEN
    v_tmp  := v_w_mm;
    v_w_mm := v_h_mm;
    v_h_mm := v_tmp;
  END IF;

  -- Comparar com dimensões ISO (tolerância ±8mm)
  IF abs(v_w_mm - 297) <= 8 AND abs(v_h_mm - 420) <= 8 THEN RETURN 'A3'; END IF;
  IF abs(v_w_mm - 210) <= 8 AND abs(v_h_mm - 297) <= 8 THEN RETURN 'A4'; END IF;
  IF abs(v_w_mm - 176) <= 8 AND abs(v_h_mm - 250) <= 8 THEN RETURN 'B5'; END IF;
  IF abs(v_w_mm - 148) <= 8 AND abs(v_h_mm - 210) <= 8 THEN RETURN 'A5'; END IF;
  IF abs(v_w_mm - 105) <= 8 AND abs(v_h_mm - 148) <= 8 THEN RETURN 'A6'; END IF;
  IF abs(v_w_mm - 74)  <= 8 AND abs(v_h_mm - 105) <= 8 THEN RETURN 'A7'; END IF;

  RETURN NULL;
END;
$$;
;

-- <<< END 20260611215834_fix_fn_parse_paper_format_dimensions_v2.sql <<<

-- >>> BEGIN 20260611215958_fix_fn_parse_paper_ruling_v3.sql >>>

-- FIX: Remove padrão %pauta% muito amplo, adiciona exclusão "sem pauta"

CREATE OR REPLACE FUNCTION public.fn_parse_paper_ruling(
  p_tags jsonb, p_name text, p_description text
) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_tags text := lower(coalesce(p_tags::text,''));
  v_desc text := lower(coalesce(p_description,''));
  v_name text := lower(coalesce(p_name,''));
  v_all  text := v_tags || ' ' || v_desc || ' ' || v_name;
BEGIN
  -- ── Prioridade: BLANK antes de RULED para "sem pauta" ────────
  -- (sem pauta / sem linhas são detectados ANTES dos positivos)
  IF v_all ILIKE ANY(ARRAY[
    '%sem pauta%','%sem linhas%','%folhas lisas%','%páginas lisas%',
    '%liso%','%lisas%','%em branco%','%plain%','%without lines%'
  ]) THEN RETURN 'BLANK'; END IF;

  -- PLANNER
  IF v_all ILIKE '%planner%' AND v_all ILIKE ANY(ARRAY['%planejamento%','%agenda%','%metas%','%anual%']) THEN
    RETURN 'PLANNER';
  END IF;
  -- Pontilhado
  IF v_all ILIKE ANY(ARRAY['%pontilhado%','%dotted%','%bullet journal%']) THEN RETURN 'DOTTED'; END IF;
  -- Quadriculado
  IF v_all ILIKE '%quadriculado%' THEN RETURN 'GRID'; END IF;
  -- Pautado — padrões explícitos (evitar "sem pauta")
  IF v_all ILIKE ANY(ARRAY[
    '%pautado%','%folhas pautadas%','%com pauta%','%pautadas%','%papel pautado%',
    '%linhas%','%lines for%','%pages with lines%','%lined%'
  ]) THEN RETURN 'RULED'; END IF;
  -- Agenda/diário implica ruled
  IF v_all ILIKE ANY(ARRAY[
    '%diária%','%semanal%','%plano diário%','%plano semanal%'
  ]) THEN RETURN 'RULED'; END IF;
  -- Para anotações → ruled (padrão SM)
  IF v_all ILIKE '%para anotações%' THEN RETURN 'RULED'; END IF;
  -- Agenda no nome/tags → ruled
  IF v_all ILIKE '%agenda%' AND v_name ILIKE '%agenda%' THEN RETURN 'RULED'; END IF;
  RETURN NULL;
END;
$$;
;

-- <<< END 20260611215958_fix_fn_parse_paper_ruling_v3.sql <<<

-- >>> BEGIN 20260611220101_fix_fn_parse_paper_weight_regex_v2.sql >>>

-- FIX: Regex mais robusta — captura 80g, 80g., 80g/m², 80 gsm
CREATE OR REPLACE FUNCTION public.fn_parse_paper_weight(p_description text)
RETURNS int LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_desc  text := lower(coalesce(p_description,''));
  v_match text[];
  v_n     int;
BEGIN
  -- Tentar capturar gramatura em diversas formas:
  -- "75 g/m²", "75g/m2", "75 gsm", "80g", "80g.", "80g,"
  -- Padrão: número + opcional espaço + g + (/ ou espaço ou pontuação não-alfa ou fim)
  SELECT m INTO v_match
  FROM regexp_matches(
    v_desc,
    '(\d+)\s*(?:g/m[²2]|gsm|g(?![a-z]))',
    'ig'  -- case insensitive, multiline
  ) AS t(m)
  LIMIT 1;

  IF v_match IS NOT NULL THEN
    v_n := v_match[1]::int;
    -- Faixa válida para papel de caderno (50–250 g/m²)
    IF v_n BETWEEN 50 AND 250 THEN RETURN v_n; END IF;
  END IF;
  RETURN NULL;
END;
$$;
;

-- <<< END 20260611220101_fix_fn_parse_paper_weight_regex_v2.sql <<<

-- >>> BEGIN 20260611220211_fix_fn_parse_cover_material_null_defense_v4.sql >>>

-- FIX: Defender contra JSON null ('null'::jsonb) e jsonb não-array
CREATE OR REPLACE FUNCTION public.fn_parse_cover_material_code(
  p_materials jsonb, p_name text, p_description text
) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_mat_lower text;
  v_pname     text := lower(coalesce(p_name,''));
  v_desc      text := lower(coalesce(p_description,''));
BEGIN
  -- ── PRIORIDADE 1: materials jsonb (array de strings) ─────────
  -- Defender contra SQL NULL, JSON null, e tipos não-array
  IF p_materials IS NOT NULL
     AND jsonb_typeof(p_materials) = 'array'
     AND jsonb_array_length(p_materials) > 0
  THEN
    FOR v_mat_lower IN
      SELECT lower(elem) FROM jsonb_array_elements_text(p_materials) AS t(elem)
    LOOP
      IF v_mat_lower IS NULL OR v_mat_lower = '' THEN CONTINUE; END IF;
      IF v_mat_lower ILIKE '%pele reciclada%' OR v_mat_lower ILIKE '%couro reciclado%' THEN RETURN 'RECYCLED_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%pu à base de água%' OR v_mat_lower ILIKE '%pu a base de agua%' THEN RETURN 'PU_WATER'; END IF;
      IF v_mat_lower ILIKE '%couro legítimo%' OR v_mat_lower ILIKE '%couro natural%' OR v_mat_lower ILIKE '%genuine leather%' THEN RETURN 'GENUINE_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%couro sintético%' OR v_mat_lower ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%polipele%' THEN RETURN 'POLYLEATHER'; END IF;
      IF v_mat_lower = 'pu' OR v_mat_lower ILIKE 'pu %' OR v_mat_lower ILIKE '% pu' THEN RETURN 'PU'; END IF;
      IF v_mat_lower ILIKE '%rpet%' OR v_mat_lower ILIKE '%pet reciclado%' THEN RETURN 'RPET'; END IF;
      IF v_mat_lower ILIKE '%cortiça%' OR v_mat_lower ILIKE '%cork%' THEN RETURN 'CORK'; END IF;
      IF v_mat_lower ILIKE '%bambu%' OR v_mat_lower ILIKE '%bamboo%' THEN RETURN 'BAMBOO'; END IF;
      IF v_mat_lower ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
      IF v_mat_lower = 'borracha' OR v_mat_lower ILIKE 'emborrachad%' THEN RETURN 'RUBBER'; END IF;
      IF v_mat_lower ILIKE '%linho%' OR v_mat_lower ILIKE '%linen%' THEN RETURN 'LINEN'; END IF;
      IF v_mat_lower ILIKE '%tecido%' OR v_mat_lower ILIKE '%poliéster%' OR v_mat_lower ILIKE '%algodão%' THEN RETURN 'FABRIC'; END IF;
      IF v_mat_lower ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;
      IF v_mat_lower ILIKE '%couchê%' OR v_mat_lower ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
      IF v_mat_lower ILIKE '%plástico%' OR v_mat_lower ILIKE '%plastic%' THEN RETURN 'PLASTIC'; END IF;
      IF v_mat_lower ILIKE '%papel%' OR v_mat_lower ILIKE '%cartão%' OR v_mat_lower ILIKE '%cardboard%' THEN RETURN 'CARDBOARD'; END IF;
    END LOOP;
  END IF;

  -- ── PRIORIDADE 2: Nome do produto ─────────────────────────────
  IF v_pname ILIKE '%couro sintético%' OR v_pname ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
  IF v_pname ILIKE '%em cortiça%' OR v_pname ILIKE '%cortiça%' THEN RETURN 'CORK'; END IF;
  IF v_pname ILIKE '%bambu%' THEN RETURN 'BAMBOO'; END IF;
  IF v_pname ILIKE '%rpet%' THEN RETURN 'RPET'; END IF;
  IF v_pname ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
  IF v_pname ILIKE '%emborrachad%' THEN RETURN 'RUBBER'; END IF;
  IF v_pname ILIKE '%linho%' THEN RETURN 'LINEN'; END IF;
  IF v_pname ILIKE '%couchê%' OR v_pname ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
  IF v_pname ILIKE '% em pu %' OR v_pname ILIKE '% em pu$' OR v_pname ILIKE '% pu %' OR v_pname ILIKE '% pu$' THEN RETURN 'PU'; END IF;
  IF v_pname ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;

  -- ── PRIORIDADE 3: Descrição (somente contexto de capa) ────────
  IF v_desc ILIKE '%capa%couro sintético%' OR v_desc ILIKE '%couro sintético%capa%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
  IF v_desc ILIKE '%capa%em pu%' OR v_desc ILIKE '%em pu%capa%' THEN RETURN 'PU'; END IF;
  IF v_desc ILIKE '%capa%cortiça%' THEN RETURN 'CORK'; END IF;
  IF v_desc ILIKE '%capa%bambu%' THEN RETURN 'BAMBOO'; END IF;
  IF v_desc ILIKE '%capa%rpet%' THEN RETURN 'RPET'; END IF;
  IF v_desc ILIKE '%capa%percalux%' THEN RETURN 'PERCALUX'; END IF;
  IF v_desc ILIKE '%capa%borracha%'
     AND v_desc NOT ILIKE '%borracha na ponta%'
     AND v_desc NOT ILIKE '%lápis%borracha%' THEN RETURN 'RUBBER'; END IF;
  IF v_desc ILIKE '%capa%linho%' THEN RETURN 'LINEN'; END IF;
  IF v_desc ILIKE '%capa%kraft%' THEN RETURN 'KRAFT'; END IF;
  IF v_desc ILIKE '%capa%plástico%' THEN RETURN 'PLASTIC'; END IF;
  IF v_desc ILIKE '%capa%papel%' OR v_desc ILIKE '%capa%cartão%' OR v_desc ILIKE '%cartonada%' THEN RETURN 'CARDBOARD'; END IF;

  RETURN NULL;
END;
$$;
;

-- <<< END 20260611220211_fix_fn_parse_cover_material_null_defense_v4.sql <<<

-- >>> BEGIN 20260611220329_fix_fn_parse_cover_material_ilike_anchors_v5.sql >>>

-- FIX: Remover $ de ILIKE (não é âncora em ILIKE!) + PU detection melhorada
CREATE OR REPLACE FUNCTION public.fn_parse_cover_material_code(
  p_materials jsonb, p_name text, p_description text
) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_mat_lower text;
  v_pname     text := lower(coalesce(p_name,''));
  v_desc      text := lower(coalesce(p_description,''));
BEGIN
  -- ── PRIORIDADE 1: materials jsonb (array de strings) ─────────
  IF p_materials IS NOT NULL
     AND jsonb_typeof(p_materials) = 'array'
     AND jsonb_array_length(p_materials) > 0
  THEN
    FOR v_mat_lower IN
      SELECT lower(elem) FROM jsonb_array_elements_text(p_materials) AS t(elem)
    LOOP
      IF v_mat_lower IS NULL OR v_mat_lower = '' THEN CONTINUE; END IF;
      IF v_mat_lower ILIKE '%pele reciclada%' OR v_mat_lower ILIKE '%couro reciclado%' THEN RETURN 'RECYCLED_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%pu à base de água%' OR v_mat_lower ILIKE '%pu a base de agua%' THEN RETURN 'PU_WATER'; END IF;
      IF v_mat_lower ILIKE '%couro legítimo%' OR v_mat_lower ILIKE '%couro natural%' THEN RETURN 'GENUINE_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%couro sintético%' OR v_mat_lower ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%polipele%' THEN RETURN 'POLYLEATHER'; END IF;
      -- PU: exato ou dentro de texto (não derivado de "superior", "output", etc.)
      IF v_mat_lower ~ '(?i)\bpu\b' THEN RETURN 'PU'; END IF;
      IF v_mat_lower ILIKE '%rpet%' OR v_mat_lower ILIKE '%pet reciclado%' THEN RETURN 'RPET'; END IF;
      IF v_mat_lower ILIKE '%cortiça%' OR v_mat_lower ILIKE '%cork%' THEN RETURN 'CORK'; END IF;
      IF v_mat_lower ILIKE '%bambu%' OR v_mat_lower ILIKE '%bamboo%' THEN RETURN 'BAMBOO'; END IF;
      IF v_mat_lower ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
      IF v_mat_lower = 'borracha' OR v_mat_lower ILIKE 'emborrachad%' THEN RETURN 'RUBBER'; END IF;
      IF v_mat_lower ILIKE '%linho%' OR v_mat_lower ILIKE '%linen%' THEN RETURN 'LINEN'; END IF;
      IF v_mat_lower ILIKE '%tecido%' OR v_mat_lower ILIKE '%poliéster%' OR v_mat_lower ILIKE '%algodão%' THEN RETURN 'FABRIC'; END IF;
      IF v_mat_lower ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;
      IF v_mat_lower ILIKE '%couchê%' OR v_mat_lower ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
      IF v_mat_lower ILIKE '%plástico%' OR v_mat_lower ILIKE '%plastic%' THEN RETURN 'PLASTIC'; END IF;
      IF v_mat_lower ILIKE '%papel%' OR v_mat_lower ILIKE '%cartão%' OR v_mat_lower ILIKE '%cardboard%' THEN RETURN 'CARDBOARD'; END IF;
    END LOOP;
  END IF;

  -- ── PRIORIDADE 2: Nome do produto ─────────────────────────────
  IF v_pname ILIKE '%couro sintético%' OR v_pname ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
  IF v_pname ILIKE '%cortiça%' THEN RETURN 'CORK'; END IF;
  IF v_pname ILIKE '%bambu%' THEN RETURN 'BAMBOO'; END IF;
  IF v_pname ILIKE '%rpet%' THEN RETURN 'RPET'; END IF;
  IF v_pname ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
  IF v_pname ILIKE '%emborrachad%' THEN RETURN 'RUBBER'; END IF;
  IF v_pname ILIKE '%linho%' THEN RETURN 'LINEN'; END IF;
  IF v_pname ILIKE '%couchê%' OR v_pname ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
  -- PU: regex word boundary para evitar falsos (superior, compute, etc.)
  IF v_pname ~ '(?i)\bpu\b' OR v_pname ILIKE '% em pu' OR v_pname ILIKE '%caderneta pu%' THEN RETURN 'PU'; END IF;
  IF v_pname ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;

  -- ── PRIORIDADE 3: Descrição com contexto de capa ─────────────
  IF v_desc ILIKE '%capa%couro sintético%' OR v_desc ILIKE '%couro sintético%capa%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
  IF v_desc ILIKE '%capa%em pu%' OR v_desc ILIKE '%em pu%capa%' THEN RETURN 'PU'; END IF;
  IF v_desc ILIKE '%capa%cortiça%' THEN RETURN 'CORK'; END IF;
  IF v_desc ILIKE '%capa%bambu%' THEN RETURN 'BAMBOO'; END IF;
  IF v_desc ILIKE '%capa%rpet%' THEN RETURN 'RPET'; END IF;
  IF v_desc ILIKE '%capa%percalux%' THEN RETURN 'PERCALUX'; END IF;
  IF v_desc ILIKE '%capa%borracha%'
     AND v_desc NOT ILIKE '%borracha na ponta%'
     AND v_desc NOT ILIKE '%lápis%borracha%' THEN RETURN 'RUBBER'; END IF;
  IF v_desc ILIKE '%capa%linho%' THEN RETURN 'LINEN'; END IF;
  IF v_desc ILIKE '%capa%kraft%' THEN RETURN 'KRAFT'; END IF;
  IF v_desc ILIKE '%capa%plástico%' THEN RETURN 'PLASTIC'; END IF;
  IF v_desc ILIKE '%capa%papel%' OR v_desc ILIKE '%capa%cartão%' OR v_desc ILIKE '%cartonada%' THEN RETURN 'CARDBOARD'; END IF;

  RETURN NULL;
END;
$$;
;

