-- >>> BEGIN 20260611220649_fix_fn_is_graphic_material_kit_regression_v3.sql >>>

-- FIX v3: Reordenar — verificação positiva de notebook nome ANTES das exclusões
-- agressivas. Kits "garrafa + caderneta" são legítimos.

CREATE OR REPLACE FUNCTION public.fn_is_graphic_material(
  p_supplier_subtype      text,
  p_supplier_subtype_code text,
  p_name                  text,
  p_meta_keywords         text[],
  p_tags                  jsonb,
  p_is_textil             boolean
)
RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_subtype_lower text := lower(coalesce(p_supplier_subtype,''));
  v_name_lower    text := lower(coalesce(p_name,''));
  v_kw_text       text := lower(array_to_string(coalesce(p_meta_keywords, ARRAY[]::text[]), ' '));
  v_tags_text     text := lower(coalesce(p_tags::text,''));
BEGIN
  -- ── 1. Excluir têxteis ────────────────────────────────────
  IF p_is_textil = true THEN RETURN false; END IF;

  -- ── 2. Excluir subtipos LAPTOP/MOCHILA ───────────────────
  IF v_subtype_lower ILIKE ANY(ARRAY[
    '%para notebook%','%bolso para notebook%','%notebook e tablet%',
    '%pastas para notebook%','%suporte para notebook%',
    '%para pc%','%p/ notebook%'
  ]) THEN RETURN false; END IF;

  -- ── 3a. POSITIVOS: nome explicitamente contém produto de papelaria
  -- Kits com "garrafa + caderneta" são legítimos → checa PRIMEIRO
  IF v_name_lower ILIKE ANY(ARRAY[
    '%caderno%','%caderneta%','%agenda%','%bloco%','%bloco de nota%',
    '%planner%','%diário%','%moleskine%','%sketchbook%'
  ]) THEN
    -- Excluir apenas se o nome é PURAMENTE de não-papelaria sem notebook
    -- (ex: "mochila com bolso para notebook" - já eliminado pelo passo 2)
    -- Para kits tipo "garrafa + caderneta" → RETORNAR true
    RETURN true;
  END IF;

  -- ── 3b. NEGATIVOS: nomes claramente não-papelaria (sem notebook no nome)
  IF v_name_lower ILIKE ANY(ARRAY[
    '%mochila%','%trolley%','%bolsa%',
    '% pasta %','%pasta executiva%','%pasta convenção%',
    '%calendário de mesa%','%calendar de mesa%',
    '%porta-cartão%','%porta cartao%','%porta-caneta%'
  ]) THEN RETURN false; END IF;

  -- ── 4. Subtipo explícito de papelaria ────────────────────
  IF v_subtype_lower ILIKE ANY(ARRAY[
    '%agenda%','%bloco%','%caderno%','%caderneta%',
    '%planner%','%autoadesivos%','%notas adesivas%',
    '%papelaria%','%diário%','%com pauta%','%com caneta%',
    '%algodao%','%percalux%','%couro%'
  ]) THEN
    IF v_subtype_lower ILIKE '%notebook%' THEN RETURN false; END IF;
    RETURN true;
  END IF;

  -- ── 5. Keywords ──────────────────────────────────────────
  IF v_kw_text ILIKE ANY(ARRAY[
    '%caderno%','%caderneta%','%bloco%','%agenda%','%planner%'
  ]) THEN RETURN true; END IF;

  -- ── 6. Tags com palavras-notebook ────────────────────────
  IF v_tags_text ILIKE ANY(ARRAY[
    '%caderno%','%caderneta%','%agenda%','%bloco%','%planner%',
    '%folhas pautadas%','%folhas lisas%'
  ]) THEN RETURN true; END IF;

  -- Tags de formato SÓ classificam se nome também é papelaria
  IF v_tags_text ILIKE ANY(ARRAY[
    '%tamanho a3%','%tamanho a4%','%tamanho b5%',
    '%tamanho a5%','%tamanho a6%','%tamanho a7%'
  ]) THEN
    IF v_name_lower ILIKE ANY(ARRAY[
      '%caderno%','%caderneta%','%agenda%','%bloco%','%planner%','%diário%','%sketchbook%'
    ]) THEN RETURN true; END IF;
    RETURN false;
  END IF;

  RETURN false;
END;
$$;
;

-- <<< END 20260611220649_fix_fn_is_graphic_material_kit_regression_v3.sql <<<

-- >>> BEGIN 20260611220751_fix_fn_calculate_packaging_fit_cylindrical_bug.sql >>>

CREATE OR REPLACE FUNCTION public.fn_calculate_packaging_fit(
    p_product_id   uuid,
    p_packaging_id uuid,
    p_config_type  text DEFAULT 'default'
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $function$
DECLARE
    v_product   RECORD;
    v_packaging RECORD;
    v_gap_h     DECIMAL; v_gap_w DECIMAL; v_gap_l DECIMAL; v_gap_d DECIMAL;
    v_gap_min   DECIMAL; v_gap_avg DECIMAL;
    v_rating    VARCHAR(20);
    v_prefix    TEXT;
    v_min       DECIMAL := 2;
    v_tight     DECIMAL := 5;
    v_good      DECIMAL := 15;
    v_max       DECIMAL := 50;
    -- Para cilíndrico × retangular: orientação ótima
    v_pkg_dims  DECIMAL[];
    v_pkg_long  DECIMAL;  -- maior dim interna (para a altura do cilindro)
    v_pkg_short DECIMAL;  -- menor dim interna (para o diâmetro do cilindro)
    v_pkg_mid   DECIMAL;  -- dim do meio (também para diâmetro)
BEGIN
    -- Determinar prefixo de configuração
    v_prefix := lower(trim(COALESCE(p_config_type, 'default')));
    IF v_prefix NOT IN ('fragile','precision','bottles') THEN v_prefix := ''; END IF;
    IF v_prefix <> '' THEN v_prefix := v_prefix || '_'; END IF;

    -- Carregar limites (com fallback para default)
    SELECT COALESCE(
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'min_gap_mm'),
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'min_gap_mm'), 2
    ) INTO v_min;
    SELECT COALESCE(
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'tight_max_mm'),
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'tight_gap_max_mm'), 5
    ) INTO v_tight;
    SELECT COALESCE(
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'good_max_mm'),
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'good_gap_max_mm'), 15
    ) INTO v_good;
    SELECT COALESCE(
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'max_gap_mm'),
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'max_gap_mm'), 50
    ) INTO v_max;

    -- Buscar produto
    SELECT height_cm, width_cm, length_cm, diameter_cm, shape_type
    INTO v_product FROM products WHERE id = p_product_id;
    IF v_product IS NULL THEN
        RETURN jsonb_build_object('error','Produto não encontrado','compatible',false);
    END IF;

    -- Buscar embalagem
    SELECT internal_height_cm, internal_width_cm, internal_length_cm, internal_diameter_cm, product_type
    INTO v_packaging FROM products WHERE id = p_packaging_id;
    IF v_packaging IS NULL OR v_packaging.product_type <> 'packaging' THEN
        RETURN jsonb_build_object('error','Embalagem não encontrada ou inválida','compatible',false);
    END IF;

    -- Calcular folgas
    IF v_product.shape_type = 'cylindrical' THEN
        -- Produto cilíndrico: pode ser orientado na maior dimensão da caixa
        IF v_packaging.internal_diameter_cm IS NOT NULL THEN
            -- Embalagem também cilíndrica: comparação direta
            v_gap_d := (v_packaging.internal_diameter_cm - COALESCE(v_product.diameter_cm, v_product.width_cm)) * 10;
            v_gap_h := (v_packaging.internal_height_cm  - v_product.height_cm) * 10;
        ELSE
            -- Embalagem retangular: orientar cilindro na maior dimensão disponível
            -- Ordenar dimensões internas: menor para diâmetro, maior para comprimento
            v_pkg_dims := ARRAY[
                COALESCE(v_packaging.internal_height_cm, 0),
                COALESCE(v_packaging.internal_width_cm,  0),
                COALESCE(v_packaging.internal_length_cm, 0)
            ];
            -- v_pkg_long = maior dimensão (comporta a altura do cilindro)
            v_pkg_long  := GREATEST(v_pkg_dims[1], v_pkg_dims[2], v_pkg_dims[3]);
            -- v_pkg_short = menor dimensão (limita o diâmetro)
            v_pkg_short := LEAST(v_pkg_dims[1], v_pkg_dims[2], v_pkg_dims[3]);
            -- v_pkg_mid = dimensão do meio (também limita o diâmetro)
            v_pkg_mid   := v_pkg_dims[1] + v_pkg_dims[2] + v_pkg_dims[3]
                           - v_pkg_long - v_pkg_short;

            v_gap_h := (v_pkg_long  - v_product.height_cm) * 10;
            v_gap_d := (v_pkg_short - COALESCE(v_product.diameter_cm, v_product.width_cm)) * 10;
            -- Verificar se também cabe na dimensão do meio
            IF v_pkg_mid < COALESCE(v_product.diameter_cm, v_product.width_cm) THEN
                v_gap_d := LEAST(v_gap_d, (v_pkg_mid - COALESCE(v_product.diameter_cm, v_product.width_cm)) * 10);
            END IF;
        END IF;
        v_gap_min := LEAST(COALESCE(v_gap_d, 999), COALESCE(v_gap_h, 999));
        v_gap_avg := (COALESCE(v_gap_d, 0) + COALESCE(v_gap_h, 0)) / 2.0;
    ELSE
        -- Produto retangular: alinhamento direto por dimensão
        v_gap_h   := (v_packaging.internal_height_cm - v_product.height_cm) * 10;
        v_gap_w   := (v_packaging.internal_width_cm  - v_product.width_cm ) * 10;
        v_gap_l   := (v_packaging.internal_length_cm - v_product.length_cm) * 10;
        v_gap_min := LEAST(COALESCE(v_gap_h, 999), COALESCE(v_gap_w, 999), COALESCE(v_gap_l, 999));
        v_gap_avg := (COALESCE(v_gap_h, 0) + COALESCE(v_gap_w, 0) + COALESCE(v_gap_l, 0)) / 3.0;
    END IF;

    -- Classificar encaixe
    IF v_gap_min IS NULL OR v_gap_min >= 900 THEN
        v_rating := 'incompatible';
    ELSIF v_gap_min < 0 THEN
        v_rating := 'too_tight';
    ELSIF v_gap_min < v_min  THEN
        v_rating := 'too_tight';
    ELSIF v_gap_min <= v_tight THEN
        v_rating := 'tight';
    ELSIF v_gap_min <= v_good  THEN
        v_rating := 'good';
    ELSIF v_gap_min <= v_max   THEN
        v_rating := 'loose';
    ELSE
        v_rating := 'too_large';
    END IF;

    RETURN jsonb_build_object(
        'compatible',      v_rating IN ('tight','good','loose'),
        'fit_rating',      v_rating,
        'config_type',     COALESCE(NULLIF(p_config_type,'default'), 'default'),
        'gap_height_mm',   ROUND(COALESCE(v_gap_h, 0)::numeric, 2),
        'gap_width_mm',    ROUND(COALESCE(v_gap_w, 0)::numeric, 2),
        'gap_length_mm',   ROUND(COALESCE(v_gap_l, 0)::numeric, 2),
        'gap_diameter_mm', ROUND(COALESCE(v_gap_d, 0)::numeric, 2),
        'gap_min_mm',      CASE WHEN v_gap_min < 900 THEN ROUND(v_gap_min::numeric, 2) ELSE NULL END,
        'gap_avg_mm',      ROUND(v_gap_avg::numeric, 2),
        'shape',           v_product.shape_type,
        'limits_mm',       jsonb_build_object('min',v_min,'tight',v_tight,'good',v_good,'max',v_max)
    );
END;
$function$;

COMMENT ON FUNCTION public.fn_calculate_packaging_fit(uuid, uuid, text) IS
'Calcula compatibilidade dimensional produto×embalagem com suporte a orientação ótima.
Cilíndrico×retangular: produto é orientado na maior dimensão da caixa (fix v2).
p_config_type: default | fragile | precision | bottles.
fit_rating: tight|good|loose|too_tight|too_large|incompatible.';
;

-- <<< END 20260611220751_fix_fn_calculate_packaging_fit_cylindrical_bug.sql <<<

-- >>> BEGIN 20260611220954_fix_fn_is_graphic_material_papelaria_v4.sql >>>

-- FIX v4: Remover "papelaria" dos subtipos positivos (inclui estojos e borrachas)
-- Adicionar exclusões de nome para produtos claramente não-notebook

CREATE OR REPLACE FUNCTION public.fn_is_graphic_material(
  p_supplier_subtype      text,
  p_supplier_subtype_code text,
  p_name                  text,
  p_meta_keywords         text[],
  p_tags                  jsonb,
  p_is_textil             boolean
)
RETURNS boolean
LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_subtype_lower text := lower(coalesce(p_supplier_subtype,''));
  v_name_lower    text := lower(coalesce(p_name,''));
  v_kw_text       text := lower(array_to_string(coalesce(p_meta_keywords, ARRAY[]::text[]), ' '));
  v_tags_text     text := lower(coalesce(p_tags::text,''));
BEGIN
  -- ── 1. Excluir têxteis ────────────────────────────────────
  IF p_is_textil = true THEN RETURN false; END IF;

  -- ── 2. Excluir subtipos LAPTOP ───────────────────────────
  IF v_subtype_lower ILIKE ANY(ARRAY[
    '%para notebook%','%bolso para notebook%','%notebook e tablet%',
    '%pastas para notebook%','%suporte para notebook%',
    '%para pc%','%p/ notebook%'
  ]) THEN RETURN false; END IF;

  -- ── 3a. POSITIVOS: nome contém produto de papelaria
  -- Verificar ANTES das exclusões para capturar kits como "kit garrafa + caderneta"
  IF v_name_lower ILIKE ANY(ARRAY[
    '%caderno%','%caderneta%','%agenda%','%bloco%','%bloco de nota%',
    '%planner%','%diário%','%moleskine%','%sketchbook%'
  ]) THEN
    -- Excluir apenas nomes claramente de NOT-notebooks mesmo com palavra notebook
    IF v_name_lower ILIKE '%mochila%' THEN RETURN false; END IF;
    RETURN true;
  END IF;

  -- ── 3b. NEGATIVOS por nome: estojos e acessórios não-notebook
  IF v_name_lower ILIKE ANY(ARRAY[
    '%mochila%','%trolley%','%bolsa%',
    '% pasta %','%pasta executiva%','%pasta convenção%',
    '%calendário de mesa%',
    '%porta-cartão%','%porta cartao%',
    '%estojo%','%kit de escrita%','%conjunto%borrachas%',
    '%conjunto%canetas%','%conjunto%esferográfica%'
  ]) THEN RETURN false; END IF;

  -- ── 4. Subtipo explícito de papelaria (REMOVIDO: papelaria)
  IF v_subtype_lower ILIKE ANY(ARRAY[
    '%agenda%','%bloco%','%caderno%','%caderneta%',
    '%planner%','%autoadesivos%','%notas adesivas%',
    '%diário%','%com pauta%','%com caneta%',
    '%algodao%','%percalux%','%couro%'
  ]) THEN
    IF v_subtype_lower ILIKE '%notebook%' THEN RETURN false; END IF;
    RETURN true;
  END IF;

  -- ── 5. Keywords ──────────────────────────────────────────
  IF v_kw_text ILIKE ANY(ARRAY[
    '%caderno%','%caderneta%','%bloco%','%agenda%','%planner%'
  ]) THEN RETURN true; END IF;

  -- ── 6. Tags com palavras-notebook ────────────────────────
  IF v_tags_text ILIKE ANY(ARRAY[
    '%caderno%','%caderneta%','%agenda%','%bloco%','%planner%',
    '%folhas pautadas%','%folhas lisas%'
  ]) THEN RETURN true; END IF;

  -- Tags de formato SÓ classificam se nome é papelaria
  IF v_tags_text ILIKE ANY(ARRAY[
    '%tamanho a3%','%tamanho a4%','%tamanho b5%',
    '%tamanho a5%','%tamanho a6%','%tamanho a7%'
  ]) THEN
    IF v_name_lower ILIKE ANY(ARRAY[
      '%caderno%','%caderneta%','%agenda%','%bloco%','%planner%','%sketchbook%'
    ]) THEN RETURN true; END IF;
    RETURN false;
  END IF;

  RETURN false;
END;
$$;
;

-- <<< END 20260611220954_fix_fn_is_graphic_material_papelaria_v4.sql <<<

-- >>> BEGIN 20260611232926_create_fn_auto_discover_all_compatible_packagings.sql >>>

CREATE OR REPLACE FUNCTION public.fn_auto_discover_all_compatible_packagings(
    p_min_fit_rating text DEFAULT 'good',
    p_config_type    text DEFAULT 'default',
    p_only_missing   boolean DEFAULT true  -- true = só produtos sem compat; false = todos
)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
    v_prefix      TEXT;
    v_min         DECIMAL; v_tight DECIMAL; v_good DECIMAL; v_max DECIMAL;
    v_inserted    INT := 0;
    v_skipped     INT := 0;
    v_incompat    INT := 0;
BEGIN
    -- Determinar prefixo de config
    v_prefix := lower(trim(COALESCE(p_config_type,'default')));
    IF v_prefix NOT IN ('fragile','precision','bottles') THEN v_prefix := ''; END IF;
    IF v_prefix <> '' THEN v_prefix := v_prefix || '_'; END IF;

    SELECT COALESCE(
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'min_gap_mm'),
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'min_gap_mm'), 2
    ) INTO v_min;
    SELECT COALESCE(
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'tight_max_mm'),
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'tight_gap_max_mm'), 5
    ) INTO v_tight;
    SELECT COALESCE(
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'good_max_mm'),
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'good_gap_max_mm'), 15
    ) INTO v_good;
    SELECT COALESCE(
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'max_gap_mm'),
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'max_gap_mm'), 50
    ) INTO v_max;

    -- ─────────────────────────────────────────────────────────────────────────
    -- CTE: Produto × Embalagem — cálculo em bloco (sem cursor)
    -- ─────────────────────────────────────────────────────────────────────────
    WITH
    -- Produtos candidatos (com dimensões)
    prods AS (
        SELECT p.id, p.height_cm, p.width_cm, p.length_cm, p.diameter_cm, p.shape_type, p.supplier_id
        FROM products p
        WHERE p.is_active = true
          AND p.product_type IN ('product','kit')
          AND p.height_cm IS NOT NULL
          AND p.width_cm  IS NOT NULL
          AND (
              NOT p_only_missing
              OR NOT EXISTS (
                  SELECT 1 FROM product_packaging_compatibility x
                  WHERE x.product_id = p.id AND x.active = true
              )
          )
    ),
    -- Embalagens disponíveis com dimensões internas
    pkgs AS (
        SELECT pk.id, pk.internal_height_cm, pk.internal_width_cm, pk.internal_length_cm,
               pk.internal_diameter_cm, pk.supplier_id
        FROM products pk
        WHERE pk.product_type = 'packaging'
          AND pk.is_active = true
          AND pk.internal_height_cm IS NOT NULL
    ),
    -- Cross product: calcular folgas
    pairs AS (
        SELECT
            pr.id AS product_id,
            pk.id AS packaging_id,
            pr.supplier_id AS prod_supplier,
            pk.supplier_id AS pkg_supplier,
            pr.shape_type,
            -- Para produtos cilíndricos em caixas retangulares: orientação ótima
            CASE WHEN pr.shape_type = 'cylindrical' THEN
                -- gap diâmetro vs. menor dimensão da caixa
                (LEAST(pk.internal_height_cm, pk.internal_width_cm, pk.internal_length_cm)
                 - COALESCE(pr.diameter_cm, pr.width_cm)) * 10
            ELSE
                (pk.internal_height_cm - pr.height_cm) * 10
            END AS gap_h_raw,

            CASE WHEN pr.shape_type = 'cylindrical' THEN
                -- gap altura vs. maior dimensão da caixa
                (GREATEST(pk.internal_height_cm, pk.internal_width_cm, pk.internal_length_cm)
                 - pr.height_cm) * 10
            ELSE
                (pk.internal_width_cm - pr.width_cm) * 10
            END AS gap_w_raw,

            CASE WHEN pr.shape_type = 'cylindrical' THEN NULL
            ELSE (pk.internal_length_cm - pr.length_cm) * 10
            END AS gap_l_raw
        FROM prods pr
        CROSS JOIN pkgs pk
    ),
    -- Folga mínima e classificação
    classified AS (
        SELECT
            product_id, packaging_id, prod_supplier, pkg_supplier, shape_type,
            gap_h_raw, gap_w_raw, gap_l_raw,
            CASE WHEN shape_type = 'cylindrical'
                 THEN LEAST(COALESCE(gap_h_raw, 999), COALESCE(gap_w_raw, 999))
                 ELSE LEAST(COALESCE(gap_h_raw, 999), COALESCE(gap_w_raw, 999), COALESCE(gap_l_raw, 999))
            END AS gap_min,
            CASE WHEN shape_type = 'cylindrical'
                 THEN (COALESCE(gap_h_raw, 0) + COALESCE(gap_w_raw, 0)) / 2.0
                 ELSE (COALESCE(gap_h_raw, 0) + COALESCE(gap_w_raw, 0) + COALESCE(gap_l_raw, 0)) / 3.0
            END AS gap_avg
        FROM pairs
    ),
    rated AS (
        SELECT
            product_id, packaging_id, prod_supplier, pkg_supplier, shape_type,
            gap_h_raw, gap_w_raw, gap_l_raw, gap_min, gap_avg,
            CASE
                WHEN gap_min IS NULL OR gap_min >= 900 THEN 'incompatible'
                WHEN gap_min < 0          THEN 'too_tight'
                WHEN gap_min < v_min      THEN 'too_tight'
                WHEN gap_min <= v_tight   THEN 'tight'
                WHEN gap_min <= v_good    THEN 'good'
                WHEN gap_min <= v_max     THEN 'loose'
                ELSE 'too_large'
            END AS fit_rating
        FROM classified
    ),
    -- Filtrar por min_fit_rating solicitado
    compatibles AS (
        SELECT * FROM rated
        WHERE fit_rating = ANY(
            CASE p_min_fit_rating
                WHEN 'tight'  THEN ARRAY['tight']
                WHEN 'good'   THEN ARRAY['tight','good']
                WHEN 'loose'  THEN ARRAY['tight','good','loose']
                ELSE               ARRAY['tight','good','loose']
            END
        )
    ),
    -- Inserir novos pares (ignorar existentes)
    ins AS (
        INSERT INTO product_packaging_compatibility (
            product_id, packaging_id, compatibility_source,
            fit_rating, fit_gap_height_mm, fit_gap_width_mm, fit_gap_length_mm,
            fit_gap_min_mm, fit_gap_avg_mm,
            is_same_supplier, auto_discovered_at, config_type_used, active
        )
        SELECT
            product_id, packaging_id, 'dimension_calculated',
            fit_rating,
            ROUND(COALESCE(gap_h_raw, 0)::numeric, 2),
            ROUND(COALESCE(gap_w_raw, 0)::numeric, 2),
            ROUND(COALESCE(gap_l_raw, 0)::numeric, 2),
            ROUND(gap_min::numeric, 2),
            ROUND(gap_avg::numeric, 2),
            (prod_supplier = pkg_supplier),
            now(),
            COALESCE(NULLIF(p_config_type,'default'),'default'),
            true
        FROM compatibles
        ON CONFLICT (product_id, packaging_id) DO NOTHING
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_inserted FROM ins;

    -- Contar incompatíveis (estimativa)
    SELECT COUNT(*)
    INTO v_incompat
    FROM (
        SELECT pr.id
        FROM products pr
        WHERE pr.is_active = true AND pr.product_type IN ('product','kit')
          AND pr.height_cm IS NOT NULL
    ) prs
    CROSS JOIN (SELECT id FROM products WHERE product_type = 'packaging' AND is_active = true AND internal_height_cm IS NOT NULL) pkk
    WHERE NOT EXISTS (
        SELECT 1 FROM product_packaging_compatibility x
        WHERE x.product_id = prs.id AND x.packaging_id = pkk.id
    );

    RETURN jsonb_build_object(
        'success',         true,
        'inserted',        v_inserted,
        'config_type',     p_config_type,
        'min_fit_rating',  p_min_fit_rating,
        'only_missing',    p_only_missing,
        'limits_mm',       jsonb_build_object('min',v_min,'tight',v_tight,'good',v_good,'max',v_max)
    );
END;
$function$;

COMMENT ON FUNCTION public.fn_auto_discover_all_compatible_packagings IS
'Versão batch de fn_auto_discover_compatible_packagings.
Processa TODOS os produtos de uma vez (set-based, sem cursor).
Suporta config_type: default | fragile | precision | bottles.';
;

