-- >>> BEGIN 20260611233140_fix_fn_parse_sheet_count_ff_regex_v3.sql >>>

-- FIX: \b → (?!\w) para pattern "ff" + robustez geral
CREATE OR REPLACE FUNCTION public.fn_parse_sheet_count(p_description text)
RETURNS int LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_desc  text := lower(coalesce(p_description,''));
  v_match text[];
  v_n     int;
BEGIN
  -- "N folhas" (com ou sem aproximadamente/possui/contém)
  SELECT m INTO v_match
  FROM regexp_matches(
    v_desc,
    '(?:(?:aproximadamente|com|possui|contém|tem)\s+)?(\d+)\s*folhas?',
    'g'
  ) AS t(m)
  LIMIT 1;
  IF v_match IS NOT NULL THEN
    v_n := v_match[1]::int;
    IF v_n BETWEEN 10 AND 1000 THEN RETURN v_n; END IF;
  END IF;

  -- "N páginas" → divir por 2
  SELECT m INTO v_match
  FROM regexp_matches(
    v_desc,
    '(?:(?:aproximadamente|com|possui|contém|tem)\s+)?(\d+)\s*páginas?',
    'g'
  ) AS t(m)
  LIMIT 1;
  IF v_match IS NOT NULL THEN
    v_n := v_match[1]::int;
    IF v_n BETWEEN 20 AND 2000 THEN RETURN v_n / 2; END IF;
  END IF;

  -- "Nff" (abreviatura pt-br de folhas) — usa (?!\w) em vez de \b
  SELECT m INTO v_match
  FROM regexp_matches(v_desc, '(\d+)\s*ff(?!\w)', 'g') AS t(m)
  LIMIT 1;
  IF v_match IS NOT NULL THEN
    v_n := v_match[1]::int;
    IF v_n BETWEEN 10 AND 500 THEN RETURN v_n; END IF;
  END IF;

  RETURN NULL;
END;
$$;
;

-- <<< END 20260611233140_fix_fn_parse_sheet_count_ff_regex_v3.sql <<<

-- >>> BEGIN 20260611233222_fix_fn_parse_binding_type_feminino_v2.sql >>>

CREATE OR REPLACE FUNCTION public.fn_parse_binding_type_code(
  p_name text, p_description text
) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_all text := lower(coalesce(p_name,'') || ' ' || coalesce(p_description,''));
BEGIN
  IF v_all ILIKE ANY(ARRAY['%wire-o%','%wire o%','%wire_o%','%wiire%']) THEN RETURN 'WIRE_O'; END IF;
  IF v_all ILIKE '%espiral%' OR v_all ILIKE '%spiral%' THEN RETURN 'SPIRAL'; END IF;
  IF v_all ILIKE ANY(ARRAY['%argolas%','%fichário%','%ring bound%','%ring-bound%']) THEN RETURN 'RING'; END IF;
  -- costurado/costurada
  IF v_all ILIKE '%costurad%' OR v_all ILIKE '%sewn%' OR v_all ILIKE '%stitched%' THEN RETURN 'SEWN'; END IF;
  -- grampo/grampeado/grampeada
  IF v_all ILIKE ANY(ARRAY['%gramp%','%canoa%','%saddle%']) THEN RETURN 'SADDLE'; END IF;
  IF v_all ILIKE '%brochura%' OR v_all ILIKE '%lombada quadrada%' OR v_all ILIKE '%perfect bound%' THEN RETURN 'PERFECT'; END IF;
  IF v_all ILIKE '%disco%' OR v_all ILIKE '%disc bound%' THEN RETURN 'DISC'; END IF;
  -- Capa dura sem argolas → CASE
  IF v_all ILIKE '%capa dura%' AND v_all NOT ILIKE '%espiral%' AND v_all NOT ILIKE '%wire%' THEN
    RETURN 'CASE';
  END IF;
  RETURN NULL;
END;
$$;
;

-- <<< END 20260611233222_fix_fn_parse_binding_type_feminino_v2.sql <<<

-- >>> BEGIN 20260611233238_create_packaging_health_view_and_promote_function.sql >>>

-- ══════════════════════════════════════════════════════════════════
-- 16A: VIEW vw_packaging_health — painel de saúde do módulo
-- ══════════════════════════════════════════════════════════════════
CREATE OR REPLACE VIEW public.vw_packaging_health AS
WITH stats AS (
    SELECT
        -- Embalagens inclusas
        (SELECT COUNT(*) FROM product_included_packagings WHERE active = true)                      AS pip_total,
        (SELECT COUNT(*) FROM product_included_packagings WHERE active = true AND material IS NOT NULL) AS pip_com_material,
        (SELECT COUNT(*) FROM product_included_packagings WHERE active = true AND internal_height_cm IS NOT NULL) AS pip_com_dims_internas,
        (SELECT COUNT(*) FROM product_included_packagings WHERE active = true AND can_be_customized = true) AS pip_personalizaveis,
        -- Print areas e técnicas
        (SELECT COUNT(*) FROM included_packaging_print_areas WHERE active = true)                    AS areas_total,
        (SELECT COUNT(*) FROM included_packaging_techniques  WHERE active = true)                    AS tecnicas_total,
        -- Compatibilidades
        (SELECT COUNT(*) FROM product_packaging_compatibility WHERE active = true)                   AS compat_total,
        (SELECT COUNT(*) FROM product_packaging_compatibility WHERE active = true AND fit_rating = 'tight') AS compat_tight,
        (SELECT COUNT(*) FROM product_packaging_compatibility WHERE active = true AND fit_rating = 'good')  AS compat_good,
        (SELECT COUNT(*) FROM product_packaging_compatibility WHERE active = true AND fit_rating = 'loose') AS compat_loose,
        (SELECT COUNT(*) FROM product_packaging_compatibility WHERE active = true AND is_recommended = true) AS compat_recomendados,
        (SELECT COUNT(*) FROM product_packaging_compatibility WHERE compatibility_source = 'supplier_indicated' AND active = true) AS compat_supplier,
        -- Produtos
        (SELECT COUNT(*) FROM products WHERE product_type = 'packaging' AND is_active = true)        AS pkgs_catalogados,
        (SELECT COUNT(*) FROM products WHERE product_type = 'packaging' AND is_active = true AND internal_height_cm IS NOT NULL) AS pkgs_com_dims,
        (SELECT COUNT(DISTINCT product_id) FROM product_packaging_compatibility WHERE active = true) AS produtos_com_compat,
        (SELECT COUNT(*) FROM products WHERE is_active = true AND product_type IN ('product','kit'))  AS produtos_total,
        -- Catálogo
        (SELECT COUNT(*) FROM packagings WHERE active = true)    AS packagings_catalog,
        (SELECT COUNT(*) FROM supplier_packagings WHERE active = true) AS supplier_packagings,
        -- Config
        (SELECT config_value FROM packaging_compatibility_config WHERE config_key = 'min_gap_mm')    AS cfg_min_gap,
        (SELECT config_value FROM packaging_compatibility_config WHERE config_key = 'tight_gap_max_mm') AS cfg_tight_max,
        (SELECT config_value FROM packaging_compatibility_config WHERE config_key = 'good_gap_max_mm')  AS cfg_good_max,
        (SELECT config_value FROM packaging_compatibility_config WHERE config_key = 'max_gap_mm')    AS cfg_max_gap
)
SELECT
    -- Embalagens inclusas
    pip_total               AS "pip_total",
    pip_com_material        AS "pip_com_material",
    ROUND(pip_com_material::numeric  / NULLIF(pip_total,0) * 100, 1) AS "pip_material_pct",
    pip_com_dims_internas   AS "pip_dims_internas",
    pip_personalizaveis     AS "pip_personalizaveis",
    -- Personalização
    areas_total             AS "areas_gravacao_total",
    tecnicas_total          AS "tecnicas_total",
    -- Compatibilidades
    compat_total            AS "compat_total",
    compat_tight            AS "compat_tight",
    compat_good             AS "compat_good",
    compat_loose            AS "compat_loose",
    compat_recomendados     AS "compat_recomendados",
    compat_supplier         AS "compat_supplier_indicated",
    ROUND(compat_recomendados::numeric / NULLIF(compat_total,0) * 100, 1) AS "compat_recom_pct",
    -- Cobertura de produtos
    produtos_total          AS "produtos_ativos_total",
    produtos_com_compat     AS "produtos_com_compat",
    (produtos_total - produtos_com_compat) AS "produtos_sem_compat",
    ROUND(produtos_com_compat::numeric / NULLIF(produtos_total,0) * 100, 1) AS "cobertura_compat_pct",
    -- Catálogo de embalagens
    pkgs_catalogados        AS "pkgs_catalogados",
    pkgs_com_dims           AS "pkgs_com_dims_internas",
    packagings_catalog      AS "packagings_catalog_entries",
    supplier_packagings     AS "supplier_packagings_entries",
    -- Config atual
    cfg_min_gap  || 'mm'  AS "config_min_gap",
    cfg_tight_max|| 'mm'  AS "config_tight_max",
    cfg_good_max || 'mm'  AS "config_good_max",
    cfg_max_gap  || 'mm'  AS "config_max_gap",
    now()                   AS "snapshot_at"
FROM stats;

COMMENT ON VIEW public.vw_packaging_health IS
'Painel de saúde do módulo de embalagens. Mostra cobertura, qualidade e configuração atual.';

-- ══════════════════════════════════════════════════════════════════
-- 16B: fn_get_product_packaging_summary — versão melhorada
-- ══════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_get_product_packaging_summary(p_product_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $function$
DECLARE
    v_included  JSONB;
    v_compat    JSONB;
    v_product   RECORD;
BEGIN
    SELECT sku, name, product_type, shape_type, height_cm, width_cm, length_cm, diameter_cm
    INTO v_product FROM products WHERE id = p_product_id;

    IF v_product IS NULL THEN
        RETURN jsonb_build_object('error','Produto não encontrado');
    END IF;

    -- Embalagens inclusas
    SELECT jsonb_agg(jsonb_build_object(
        'id',            pip.id,
        'name',          pip.name,
        'material',      pip.material,
        'color',         pip.color,
        'can_customize', pip.can_be_customized,
        'can_disable',   pip.can_be_disabled,
        'has_cradle',    pip.has_inner_cradle,
        'dims_internal', CASE WHEN pip.internal_height_cm IS NOT NULL
            THEN jsonb_build_object('h',pip.internal_height_cm,'w',pip.internal_width_cm,'l',pip.internal_length_cm)
            ELSE NULL END,
        'areas_count',   (SELECT COUNT(*) FROM included_packaging_print_areas WHERE packaging_id = pip.id AND active = true),
        'techniques',    (SELECT jsonb_agg(technique_name ORDER BY display_order) FROM included_packaging_techniques WHERE packaging_id = pip.id AND active = true)
    ) ORDER BY pip.is_default DESC)
    INTO v_included
    FROM product_included_packagings pip
    WHERE pip.product_id = p_product_id AND pip.active = true;

    -- Embalagens compatíveis (opcionais recomendadas)
    SELECT jsonb_agg(jsonb_build_object(
        'packaging_id',  ppc.packaging_id,
        'sku',           pkg.sku,
        'name',          pkg.name,
        'fit_rating',    ppc.fit_rating,
        'gap_min_mm',    ppc.fit_gap_min_mm,
        'source',        ppc.compatibility_source,
        'recommended',   ppc.is_recommended,
        'same_supplier', ppc.is_same_supplier,
        'supplier',      (SELECT name FROM suppliers WHERE id = pkg.supplier_id),
        'price',         (SELECT unit_price FROM supplier_packagings WHERE packaging_id = ppc.packaging_id AND is_available = true ORDER BY unit_price LIMIT 1)
    ) ORDER BY ppc.is_recommended DESC, ppc.fit_gap_min_mm NULLS LAST)
    INTO v_compat
    FROM product_packaging_compatibility ppc
    JOIN products pkg ON pkg.id = ppc.packaging_id
    WHERE ppc.product_id = p_product_id AND ppc.active = true
      AND ppc.fit_rating IN ('tight','good','loose');

    RETURN jsonb_build_object(
        'product',       jsonb_build_object('sku',v_product.sku,'name',v_product.name,'shape',v_product.shape_type,
                            'dims',jsonb_build_object('h',v_product.height_cm,'w',v_product.width_cm,'l',v_product.length_cm,'d',v_product.diameter_cm)),
        'included',      COALESCE(v_included, '[]'::jsonb),
        'compatible',    COALESCE(v_compat, '[]'::jsonb),
        'has_packaging', (v_included IS NOT NULL AND jsonb_array_length(COALESCE(v_included,'[]'::jsonb)) > 0),
        'has_options',   (v_compat IS NOT NULL AND jsonb_array_length(COALESCE(v_compat,'[]'::jsonb)) > 0),
        'generated_at',  now()
    );
END;
$function$;

COMMENT ON FUNCTION public.fn_get_product_packaging_summary IS
'Retorna sumário completo de embalagens de um produto:
- included: embalagens inclusas com áreas e técnicas de personalização
- compatible: embalagens opcionais compatíveis com fit_rating e preços';
;

-- <<< END 20260611233238_create_packaging_health_view_and_promote_function.sql <<<

-- >>> BEGIN 20260611233311_create_fn_promote_packaging_to_gold.sql >>>

-- ══════════════════════════════════════════════════════════════════
-- 16C: fn_promote_packaging_to_gold — pipeline Silver → Gold
-- ══════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_promote_packaging_to_gold(
    p_supplier_id  uuid DEFAULT NULL,  -- NULL = todos os fornecedores
    p_batch_size   int  DEFAULT 500
)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
    v_promoted_included  INT := 0;
    v_promoted_compat    INT := 0;
    v_promoted_type      INT := 0;
    v_errors             INT := 0;
BEGIN
    -- ─────────────────────────────────────────────────────────
    -- PASSO 1: Atualizar product_type='packaging' para produtos
    --          que têm is_packaging_product=true no Silver
    --          (via product_packaging.has_optional_packaging e packing_classification)
    -- ─────────────────────────────────────────────────────────
    WITH candidates AS (
        SELECT DISTINCT pp.product_id
        FROM product_packaging pp
        JOIN products p ON p.id = pp.product_id
        WHERE p.product_type <> 'packaging'
          AND pp.packing_classification = 'packaging_product'
          AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
        LIMIT p_batch_size
    )
    UPDATE products p
    SET product_type = 'packaging', updated_at = now()
    FROM candidates c
    WHERE p.id = c.product_id;
    GET DIAGNOSTICS v_promoted_type = ROW_COUNT;

    -- ─────────────────────────────────────────────────────────
    -- PASSO 2: Criar/atualizar product_included_packagings
    --          a partir de product_packaging (Silver) onde
    --          has_commercial_packaging = true e sem registo existente
    -- ─────────────────────────────────────────────────────────
    WITH silver AS (
        SELECT 
            pp.product_id,
            pp.packing_type       AS pip_name,
            pp.packaging_material AS pip_material,
            pp.packaging_color    AS pip_color,
            pp.packaging_finish   AS pip_finish,
            pp.has_inner_cradle   AS pip_cradle,
            pp.cradle_material    AS pip_cradle_mat,
            p.supplier_id
        FROM product_packaging pp
        JOIN products p ON p.id = pp.product_id
        WHERE pp.packing_classification = 'commercial'
          AND pp.packing_type IS NOT NULL
          AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
          AND NOT EXISTS (
              SELECT 1 FROM product_included_packagings pip
              WHERE pip.product_id = pp.product_id AND pip.active = true
          )
        LIMIT p_batch_size
    )
    INSERT INTO product_included_packagings (
        product_id, name, material, color, finish,
        has_inner_cradle, cradle_material,
        can_be_customized, can_be_disabled, is_default,
        supplier_id, ingest_source, active
    )
    SELECT 
        product_id,
        COALESCE(NULLIF(trim(pip_name),''), 'Embalagem'),
        pip_material,
        pip_color,
        pip_finish,
        COALESCE(pip_cradle, false),
        pip_cradle_mat,
        -- Determinar can_be_customized por material
        CASE WHEN pip_material ILIKE ANY(ARRAY['%polybag%','%plástico bolha%','%película%'])
             THEN false ELSE true END,
        true,   -- can_be_disabled
        true,   -- is_default
        supplier_id,
        CASE 
            WHEN supplier_id = 'bcfc0d02-44c6-48ae-8472-12b1a3f3d8e0' THEN 'spot_properties'
            WHEN supplier_id = 'd2734e23-d633-4819-bb15-e51aa44e2118' THEN 'asia_manual'
            WHEN supplier_id = '841cd690-210a-422a-908c-7676828db272' THEN 'sm_scraping'
            WHEN supplier_id = 'd6718a29-e954-4c1b-bd84-03ea24884900' THEN 'xbz_manual'
            ELSE 'pipeline_auto'
        END,
        true
    FROM silver
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_promoted_included = ROW_COUNT;

    -- ─────────────────────────────────────────────────────────
    -- PASSO 3: Criar compatibilidades supplier_indicated
    --          a partir de optional_packaging_ref em products
    -- ─────────────────────────────────────────────────────────
    WITH refs AS (
        SELECT DISTINCT
            p.id AS product_id,
            p.optional_packaging_ref AS ref_sku
        FROM products p
        WHERE p.optional_packaging_ref IS NOT NULL
          AND p.is_active = true
          AND (p_supplier_id IS NULL OR p.supplier_id = p_supplier_id)
    ),
    resolved AS (
        SELECT r.product_id, pkg.id AS packaging_id
        FROM refs r
        JOIN products pkg ON pkg.sku = r.ref_sku AND pkg.product_type = 'packaging' AND pkg.is_active = true
        WHERE NOT EXISTS (
            SELECT 1 FROM product_packaging_compatibility ppc
            WHERE ppc.product_id = r.product_id AND ppc.packaging_id = pkg.id
        )
        LIMIT p_batch_size
    )
    INSERT INTO product_packaging_compatibility (
        product_id, packaging_id, compatibility_source,
        is_recommended, is_same_supplier, active
    )
    SELECT 
        product_id, packaging_id, 'supplier_indicated',
        true,
        (SELECT supplier_id FROM products WHERE id = product_id) = 
        (SELECT supplier_id FROM products WHERE id = packaging_id),
        true
    FROM resolved
    ON CONFLICT (product_id, packaging_id) DO NOTHING;
    GET DIAGNOSTICS v_promoted_compat = ROW_COUNT;

    RETURN jsonb_build_object(
        'success',           true,
        'promoted_type',     v_promoted_type,
        'promoted_included', v_promoted_included,
        'promoted_compat',   v_promoted_compat,
        'errors',            v_errors,
        'supplier_id',       p_supplier_id,
        'batch_size',        p_batch_size,
        'executed_at',       now()
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error',   SQLERRM,
        'sqlstate', SQLSTATE
    );
END;
$function$;

COMMENT ON FUNCTION public.fn_promote_packaging_to_gold IS
'Pipeline Silver → Gold para módulo de embalagens.
- Passo 1: Classifica products como product_type=packaging
- Passo 2: Cria product_included_packagings a partir de product_packaging (Silver)
- Passo 3: Cria product_packaging_compatibility supplier_indicated via optional_packaging_ref
p_supplier_id: NULL = todos | UUID = fornecedor específico
p_batch_size: limite por execução (default 500)';
;

-- <<< END 20260611233311_create_fn_promote_packaging_to_gold.sql <<<

-- >>> BEGIN 20260611233459_fix_fn_parse_cover_material_papel_fallback_v6.sql >>>

-- FIX v6: "Papel" em materials é FALLBACK (material interno)
-- Se a descrição contém um material de capa mais específico, usa ele

CREATE OR REPLACE FUNCTION public.fn_parse_cover_material_code(
  p_materials jsonb, p_name text, p_description text
) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_mat_lower   text;
  v_pname       text := lower(coalesce(p_name,''));
  v_desc        text := lower(coalesce(p_description,''));
  v_has_papel   boolean := false;
  v_desc_result text;
BEGIN
  -- ── PRIORIDADE 1: materials jsonb (exceto "Papel" que é fallback) ─
  IF p_materials IS NOT NULL
     AND jsonb_typeof(p_materials) = 'array'
     AND jsonb_array_length(p_materials) > 0
  THEN
    FOR v_mat_lower IN
      SELECT lower(elem) FROM jsonb_array_elements_text(p_materials) AS t(elem)
    LOOP
      IF v_mat_lower IS NULL OR v_mat_lower = '' THEN CONTINUE; END IF;
      -- "Papel" / "Cartão" são materiais internos — tratar como fallback
      IF v_mat_lower ILIKE '%papel%' OR v_mat_lower ILIKE '%cartão%' OR v_mat_lower ILIKE '%cardboard%' THEN
        v_has_papel := true; CONTINUE;  -- não retornar ainda — checar desc primeiro
      END IF;
      IF v_mat_lower ILIKE '%pele reciclada%' OR v_mat_lower ILIKE '%couro reciclado%' THEN RETURN 'RECYCLED_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%pu à base de água%' THEN RETURN 'PU_WATER'; END IF;
      IF v_mat_lower ILIKE '%couro legítimo%' OR v_mat_lower ILIKE '%couro natural%' THEN RETURN 'GENUINE_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%couro sintético%' OR v_mat_lower ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%polipele%' THEN RETURN 'POLYLEATHER'; END IF;
      IF v_mat_lower ~ '(?i)\bpu\b' THEN RETURN 'PU'; END IF;
      IF v_mat_lower ILIKE '%rpet%' OR v_mat_lower ILIKE '%pet reciclado%' THEN RETURN 'RPET'; END IF;
      IF v_mat_lower ILIKE '%cortiça%' OR v_mat_lower ILIKE '%cork%' THEN RETURN 'CORK'; END IF;
      IF v_mat_lower ILIKE '%bambu%' OR v_mat_lower ILIKE '%bamboo%' THEN RETURN 'BAMBOO'; END IF;
      IF v_mat_lower ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
      IF v_mat_lower = 'borracha' OR v_mat_lower ILIKE 'emborrachad%' THEN RETURN 'RUBBER'; END IF;
      IF v_mat_lower ILIKE '%linho%' OR v_mat_lower ILIKE '%linen%' THEN RETURN 'LINEN'; END IF;
      IF v_mat_lower ILIKE '%tecido%' OR v_mat_lower ILIKE '%poliéster%' OR v_mat_lower ILIKE '%algodão%' THEN RETURN 'FABRIC'; END IF;
      IF v_mat_lower ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;
      IF v_mat_lower ILIKE '%couchê%' OR v_mat_lower ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
      IF v_mat_lower ILIKE '%plástico%' OR v_mat_lower ILIKE '%plastic%' THEN RETURN 'PLASTIC'; END IF;
    END LOOP;
  END IF;

  -- ── PRIORIDADE 2: Nome do produto ─────────────────────────────
  IF v_pname ILIKE '%couro sintético%' OR v_pname ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
  IF v_pname ILIKE '%cortiça%' THEN RETURN 'CORK'; END IF;
  IF v_pname ILIKE '%bambu%' THEN RETURN 'BAMBOO'; END IF;
  IF v_pname ILIKE '%rpet%' THEN RETURN 'RPET'; END IF;
  IF v_pname ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
  IF v_pname ILIKE '%emborrachad%' THEN RETURN 'RUBBER'; END IF;
  IF v_pname ILIKE '%linho%' THEN RETURN 'LINEN'; END IF;
  IF v_pname ILIKE '%couchê%' OR v_pname ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
  IF v_pname ~ '(?i)\bpu\b' OR v_pname ILIKE '% em pu' OR v_pname ILIKE '%caderneta pu%' THEN RETURN 'PU'; END IF;
  IF v_pname ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;
  IF v_pname ILIKE '%feltro%' THEN RETURN 'FABRIC'; END IF;

  -- ── PRIORIDADE 3: Descrição (contexto de capa) ────────────────
  -- Checada ANTES de retornar CARDBOARD do "Papel"
  v_desc_result := NULL;
  IF v_desc ILIKE '%capa%couro sintético%' OR v_desc ILIKE '%couro sintético%capa%' THEN v_desc_result := 'SYNTHETIC_LEATHER';
  ELSIF v_desc ILIKE '%capa%em pu%' OR v_desc ILIKE '%em pu%capa%' OR v_desc ILIKE '%capa dura em pu%' THEN v_desc_result := 'PU';
  ELSIF v_desc ILIKE '%capa%cortiça%' THEN v_desc_result := 'CORK';
  ELSIF v_desc ILIKE '%capa%bambu%' THEN v_desc_result := 'BAMBOO';
  ELSIF v_desc ILIKE '%capa%rpet%' THEN v_desc_result := 'RPET';
  ELSIF v_desc ILIKE '%capa%percalux%' THEN v_desc_result := 'PERCALUX';
  ELSIF v_desc ILIKE '%capa%borracha%'
     AND v_desc NOT ILIKE '%borracha na ponta%'
     AND v_desc NOT ILIKE '%lápis%borracha%' THEN v_desc_result := 'RUBBER';
  ELSIF v_desc ILIKE '%capa%linho%' OR v_desc ILIKE '%feltro%' THEN v_desc_result := 'FABRIC';
  ELSIF v_desc ILIKE '%capa%kraft%' THEN v_desc_result := 'KRAFT';
  ELSIF v_desc ILIKE '%capa%plástico%' THEN v_desc_result := 'PLASTIC';
  ELSIF v_desc ILIKE '%couro reciclado%' OR v_desc ILIKE '%pele reciclada%' THEN v_desc_result := 'RECYCLED_LEATHER';
  END IF;

  IF v_desc_result IS NOT NULL THEN RETURN v_desc_result; END IF;

  -- ── FALLBACK: "Papel" do materials (material interno / capa de cartão) ─
  IF v_has_papel THEN RETURN 'CARDBOARD'; END IF;

  RETURN NULL;
END;
$$;
;

-- <<< END 20260611233459_fix_fn_parse_cover_material_papel_fallback_v6.sql <<<

-- >>> BEGIN 20260611233745_fix_fn_calculate_packaging_fit_error_schema.sql >>>

CREATE OR REPLACE FUNCTION public.fn_calculate_packaging_fit(
    p_product_id   uuid,
    p_packaging_id uuid,
    p_config_type  text DEFAULT 'default'
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $function$
DECLARE
    v_product   RECORD;
    v_packaging RECORD;
    v_gap_h     DECIMAL; v_gap_w DECIMAL; v_gap_l DECIMAL; v_gap_d DECIMAL;
    v_gap_min   DECIMAL; v_gap_avg DECIMAL;
    v_rating    VARCHAR(20);
    v_prefix    TEXT;
    v_min       DECIMAL := 2;
    v_tight     DECIMAL := 5;
    v_good      DECIMAL := 15;
    v_max       DECIMAL := 50;
    v_pkg_dims  DECIMAL[];
    v_pkg_long  DECIMAL;
    v_pkg_short DECIMAL;
    v_pkg_mid   DECIMAL;
BEGIN
    v_prefix := lower(trim(COALESCE(p_config_type,'default')));
    IF v_prefix NOT IN ('fragile','precision','bottles') THEN v_prefix := ''; END IF;
    IF v_prefix <> '' THEN v_prefix := v_prefix || '_'; END IF;

    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'min_gap_mm'),
                    (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'min_gap_mm'), 2) INTO v_min;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'tight_max_mm'),
                    (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'tight_gap_max_mm'), 5) INTO v_tight;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'good_max_mm'),
                    (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'good_gap_max_mm'), 15) INTO v_good;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'max_gap_mm'),
                    (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'max_gap_mm'), 50) INTO v_max;

    SELECT height_cm, width_cm, length_cm, diameter_cm, shape_type
    INTO v_product FROM products WHERE id = p_product_id;

    -- ⚡ FIX: UUID inválido retorna fit_rating='error' em vez de NULL
    IF v_product IS NULL THEN
        RETURN jsonb_build_object(
            'error',       'Produto não encontrado: ' || p_product_id,
            'compatible',  false,
            'fit_rating',  'error'
        );
    END IF;

    SELECT internal_height_cm, internal_width_cm, internal_length_cm, internal_diameter_cm, product_type
    INTO v_packaging FROM products WHERE id = p_packaging_id;

    IF v_packaging IS NULL OR v_packaging.product_type <> 'packaging' THEN
        RETURN jsonb_build_object(
            'error',      CASE WHEN v_packaging IS NULL
                               THEN 'Embalagem não encontrada: ' || p_packaging_id
                               ELSE 'Produto ' || p_packaging_id || ' não é do tipo packaging (tipo=' || v_packaging.product_type || ')'
                          END,
            'compatible', false,
            'fit_rating', 'error'
        );
    END IF;

    IF v_product.shape_type = 'cylindrical' THEN
        IF v_packaging.internal_diameter_cm IS NOT NULL THEN
            v_gap_d := (v_packaging.internal_diameter_cm - COALESCE(v_product.diameter_cm, v_product.width_cm)) * 10;
            v_gap_h := (v_packaging.internal_height_cm  - v_product.height_cm) * 10;
        ELSE
            v_pkg_dims := ARRAY[
                COALESCE(v_packaging.internal_height_cm, 0),
                COALESCE(v_packaging.internal_width_cm,  0),
                COALESCE(v_packaging.internal_length_cm, 0)
            ];
            v_pkg_long  := GREATEST(v_pkg_dims[1], v_pkg_dims[2], v_pkg_dims[3]);
            v_pkg_short := LEAST   (v_pkg_dims[1], v_pkg_dims[2], v_pkg_dims[3]);
            v_pkg_mid   := v_pkg_dims[1] + v_pkg_dims[2] + v_pkg_dims[3] - v_pkg_long - v_pkg_short;
            v_gap_h     := (v_pkg_long  - v_product.height_cm) * 10;
            v_gap_d     := (v_pkg_short - COALESCE(v_product.diameter_cm, v_product.width_cm)) * 10;
            IF v_pkg_mid < COALESCE(v_product.diameter_cm, v_product.width_cm) THEN
                v_gap_d := LEAST(v_gap_d, (v_pkg_mid - COALESCE(v_product.diameter_cm, v_product.width_cm)) * 10);
            END IF;
        END IF;
        v_gap_min := LEAST(COALESCE(v_gap_d, 999), COALESCE(v_gap_h, 999));
        v_gap_avg := (COALESCE(v_gap_d, 0) + COALESCE(v_gap_h, 0)) / 2.0;
    ELSE
        v_gap_h   := (v_packaging.internal_height_cm  - v_product.height_cm) * 10;
        v_gap_w   := (v_packaging.internal_width_cm   - v_product.width_cm ) * 10;
        v_gap_l   := (v_packaging.internal_length_cm  - v_product.length_cm) * 10;
        v_gap_min := LEAST(COALESCE(v_gap_h, 999), COALESCE(v_gap_w, 999), COALESCE(v_gap_l, 999));
        v_gap_avg := (COALESCE(v_gap_h, 0) + COALESCE(v_gap_w, 0) + COALESCE(v_gap_l, 0)) / 3.0;
    END IF;

    IF v_gap_min IS NULL OR v_gap_min >= 900 THEN
        v_rating := 'incompatible';
    ELSIF v_gap_min < 0    THEN v_rating := 'too_tight';
    ELSIF v_gap_min < v_min THEN v_rating := 'too_tight';
    ELSIF v_gap_min <= v_tight THEN v_rating := 'tight';
    ELSIF v_gap_min <= v_good  THEN v_rating := 'good';
    ELSIF v_gap_min <= v_max   THEN v_rating := 'loose';
    ELSE v_rating := 'too_large';
    END IF;

    RETURN jsonb_build_object(
        'compatible',      v_rating IN ('tight','good','loose'),
        'fit_rating',      v_rating,
        'config_type',     COALESCE(NULLIF(p_config_type,'default'),'default'),
        'gap_height_mm',   ROUND(COALESCE(v_gap_h, 0)::numeric, 2),
        'gap_width_mm',    ROUND(COALESCE(v_gap_w, 0)::numeric, 2),
        'gap_length_mm',   ROUND(COALESCE(v_gap_l, 0)::numeric, 2),
        'gap_diameter_mm', ROUND(COALESCE(v_gap_d, 0)::numeric, 2),
        'gap_min_mm',      CASE WHEN v_gap_min < 900 THEN ROUND(v_gap_min::numeric, 2) ELSE NULL END,
        'gap_avg_mm',      ROUND(v_gap_avg::numeric, 2),
        'shape',           v_product.shape_type,
        'limits_mm',       jsonb_build_object('min',v_min,'tight',v_tight,'good',v_good,'max',v_max)
    );
END;
$function$;

COMMENT ON FUNCTION public.fn_calculate_packaging_fit(uuid, uuid, text) IS
'v3 — Schema consistente: erro retorna fit_rating=''error'', não NULL.
Cilíndrico×retangular: orientação ótima (produto na maior dim da caixa).
Suporta config_type: default|fragile|precision|bottles.';
;

-- <<< END 20260611233745_fix_fn_calculate_packaging_fit_error_schema.sql <<<

-- >>> BEGIN 20260611234121_fix_fn_parse_cover_material_plastic_fallback_v7.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- v7: Fix definitivo — Plástico/Papel tratados como FALLBACK
-- rPET detectado por padrão composto "Plástico - rPET"
-- Descrição sempre checada ANTES de retornar material genérico
-- ═══════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_parse_cover_material_code(
  p_materials jsonb, p_name text, p_description text
) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_mat_lower   text;
  v_pname       text := lower(coalesce(p_name,''));
  v_desc        text := lower(coalesce(p_description,''));
  v_has_papel   boolean := false;   -- "Papel", "Papelão", "Cartão"
  v_has_plastic boolean := false;   -- "Plástico" genérico
  v_has_rpet    boolean := false;   -- "Plástico - rPET" ou similar
  v_desc_result text;
BEGIN
  -- ── PRIORIDADE 1: materials jsonb ─────────────────────────────
  IF p_materials IS NOT NULL
     AND jsonb_typeof(p_materials) = 'array'
     AND jsonb_array_length(p_materials) > 0
  THEN
    FOR v_mat_lower IN
      SELECT lower(elem) FROM jsonb_array_elements_text(p_materials) AS t(elem)
    LOOP
      IF v_mat_lower IS NULL OR v_mat_lower = '' THEN CONTINUE; END IF;
      -- Específicos — retornar imediatamente
      IF v_mat_lower ILIKE '%pele reciclada%' OR v_mat_lower ILIKE '%couro reciclado%' THEN RETURN 'RECYCLED_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%pu à base de água%' THEN RETURN 'PU_WATER'; END IF;
      IF v_mat_lower ILIKE '%couro legítimo%' OR v_mat_lower ILIKE '%couro natural%' THEN RETURN 'GENUINE_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%couro sintético%' OR v_mat_lower ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
      IF v_mat_lower ILIKE '%polipele%' THEN RETURN 'POLYLEATHER'; END IF;
      IF v_mat_lower ~ '(?i)\bpu\b' AND v_mat_lower NOT ILIKE '%plástico%' THEN RETURN 'PU'; END IF;
      -- rPET: detectar ANTES de retornar PLASTIC genérico
      IF v_mat_lower ILIKE '%rpet%' OR v_mat_lower ILIKE '%r-pet%' OR v_mat_lower ILIKE '%pet reciclado%' THEN
        v_has_rpet := true; CONTINUE;
      END IF;
      IF v_mat_lower ILIKE '%cortiça%' OR v_mat_lower ILIKE '%cork%' THEN RETURN 'CORK'; END IF;
      IF v_mat_lower ILIKE '%bambu%' OR v_mat_lower ILIKE '%bamboo%' THEN RETURN 'BAMBOO'; END IF;
      IF v_mat_lower ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
      IF v_mat_lower = 'borracha' OR v_mat_lower ILIKE 'emborrachad%' THEN RETURN 'RUBBER'; END IF;
      IF v_mat_lower ILIKE '%linho%' OR v_mat_lower ILIKE '%linen%' THEN RETURN 'LINEN'; END IF;
      -- Tecido/fabric: verificar que não é plástico ecológico
      IF v_mat_lower ILIKE '%tecido%' OR v_mat_lower ILIKE '%poliéster%' OR v_mat_lower ILIKE '%algodão%' OR v_mat_lower ILIKE '%feltro%' THEN RETURN 'FABRIC'; END IF;
      IF v_mat_lower ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;
      IF v_mat_lower ILIKE '%couchê%' OR v_mat_lower ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
      -- Polipropileno e plásticos específicos (PP, PVC) = PLASTIC direto
      IF v_mat_lower ILIKE '%polipropileno%' OR v_mat_lower ILIKE '%(pp)%' OR v_mat_lower ILIKE '%pvc%' THEN RETURN 'PLASTIC'; END IF;
      -- Papel/Papelão/Cartão = fallback (material interno, não capa específica)
      IF v_mat_lower ILIKE '%papel%' OR v_mat_lower ILIKE '%papelão%' OR v_mat_lower ILIKE '%cartão%' OR v_mat_lower ILIKE '%cardboard%' THEN
        v_has_papel := true; CONTINUE;
      END IF;
      -- Plástico genérico = fallback também (Asia usa "Plástico" para materiais mistos)
      IF v_mat_lower ILIKE '%plástico%' OR v_mat_lower ILIKE '%plastic%' THEN
        v_has_plastic := true; CONTINUE;
      END IF;
    END LOOP;
    -- rPET foi encontrado (sem outro material específico mais prioritário)
    IF v_has_rpet THEN RETURN 'RPET'; END IF;
  END IF;

  -- ── PRIORIDADE 2: Nome do produto ─────────────────────────────
  IF v_pname ILIKE '%couro sintético%' OR v_pname ILIKE '%courvin%' THEN RETURN 'SYNTHETIC_LEATHER'; END IF;
  IF v_pname ILIKE '%cortiça%' THEN RETURN 'CORK'; END IF;
  IF v_pname ILIKE '%bambu%' THEN RETURN 'BAMBOO'; END IF;
  IF v_pname ILIKE '%rpet%' THEN RETURN 'RPET'; END IF;
  IF v_pname ILIKE '%percalux%' THEN RETURN 'PERCALUX'; END IF;
  IF v_pname ILIKE '%emborrachad%' THEN RETURN 'RUBBER'; END IF;
  IF v_pname ILIKE '%linho%' THEN RETURN 'LINEN'; END IF;
  IF v_pname ILIKE '%couchê%' OR v_pname ILIKE '%couche%' THEN RETURN 'COUCHE'; END IF;
  IF v_pname ~ '(?i)\bpu\b' OR v_pname ILIKE '% em pu' OR v_pname ILIKE '%caderneta pu%' THEN RETURN 'PU'; END IF;
  IF v_pname ILIKE '%kraft%' THEN RETURN 'KRAFT'; END IF;
  IF v_pname ILIKE '%feltro%' THEN RETURN 'FABRIC'; END IF;

  -- ── PRIORIDADE 3: Descrição (contexto de capa) — sempre antes dos fallbacks ─
  v_desc_result := NULL;
  IF    v_desc ILIKE '%capa%couro sintético%' OR v_desc ILIKE '%couro sintético%capa%' THEN v_desc_result := 'SYNTHETIC_LEATHER';
  ELSIF v_desc ILIKE '%capa dura em pu%' OR v_desc ILIKE '%capa em pu%' OR v_desc ILIKE '%em pu%capa%' THEN v_desc_result := 'PU';
  ELSIF v_desc ILIKE '%capa%cortiça%' THEN v_desc_result := 'CORK';
  ELSIF v_desc ILIKE '%capa%bambu%' THEN v_desc_result := 'BAMBOO';
  ELSIF v_desc ILIKE '%capa%rpet%' OR v_desc ILIKE '%rpet%capa%' OR v_desc ILIKE '%tecido rpet%' THEN v_desc_result := 'RPET';
  ELSIF v_desc ILIKE '%capa%percalux%' THEN v_desc_result := 'PERCALUX';
  ELSIF v_desc ILIKE '%capa%borracha%' AND v_desc NOT ILIKE '%borracha na ponta%' AND v_desc NOT ILIKE '%lápis%borracha%' THEN v_desc_result := 'RUBBER';
  ELSIF v_desc ILIKE '%capa%linho%' OR v_desc ILIKE '%capa%feltro%' THEN v_desc_result := 'FABRIC';
  ELSIF v_desc ILIKE '%capa%kraft%' THEN v_desc_result := 'KRAFT';
  ELSIF v_desc ILIKE '%capa%plástico%' OR v_desc ILIKE '%capa dura cartonada%' OR v_desc ILIKE '%cartonada%' THEN v_desc_result := 'CARDBOARD';
  ELSIF v_desc ILIKE '%capa%papelão%' OR v_desc ILIKE '%papelão reciclado%' THEN v_desc_result := 'CARDBOARD';
  ELSIF v_desc ILIKE '%couro reciclado%' OR v_desc ILIKE '%pele reciclada%' THEN v_desc_result := 'RECYCLED_LEATHER';
  END IF;
  IF v_desc_result IS NOT NULL THEN RETURN v_desc_result; END IF;

  -- ── FALLBACK 1: Papel/Papelão/Cartão ──────────────────────────
  IF v_has_papel THEN RETURN 'CARDBOARD'; END IF;
  -- ── FALLBACK 2: Plástico genérico ─────────────────────────────
  IF v_has_plastic THEN RETURN 'PLASTIC'; END IF;

  RETURN NULL;
END;
$$;
;

-- <<< END 20260611234121_fix_fn_parse_cover_material_plastic_fallback_v7.sql <<<

-- >>> BEGIN 20260611234549_fix_fn_parse_binding_color_context_v2.sql >>>

-- FIX: binding_color só detectado quando cor aparece com contexto de espiral/wire-o
-- "espiral preto", "wire-o prata", "encadernação espiral branca"
-- NÃO: "capa preta", "caderneta branca"

CREATE OR REPLACE FUNCTION public.fn_parse_binding_color_code(
  p_description text
) RETURNS text LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_desc text := lower(coalesce(p_description,''));
BEGIN
  -- Só detectar cor de espiral quando há CONTEXTO explícito de encadernação
  -- Padrões: "espiral preto", "wire-o prata", "encadernação espiral branca", 
  --           "espiral em prata", "wire-o em preto"
  IF v_desc ~ '(?i)(espiral|wire.?o|encadernação).{0,30}(pret[ao]|negr[ao])'
     OR v_desc ~ '(?i)(pret[ao]|negr[ao]).{0,30}(espiral|wire.?o)' THEN RETURN 'BLACK'; END IF;

  IF v_desc ~ '(?i)(espiral|wire.?o|encadernação).{0,30}(prat[ao]|prateado|inox|cinza metálico|alumín)'
     OR v_desc ~ '(?i)(prat[ao]|prateado|inox).{0,30}(espiral|wire.?o)' THEN RETURN 'SILVER'; END IF;

  IF v_desc ~ '(?i)(espiral|wire.?o|encadernação).{0,30}(dourad[ao]|gold|golden)'
     OR v_desc ~ '(?i)(dourad[ao]|gold).{0,30}(espiral|wire.?o)' THEN RETURN 'GOLD'; END IF;

  IF v_desc ~ '(?i)(espiral|wire.?o|encadernação).{0,30}(branc[ao]|white)'
     OR v_desc ~ '(?i)(branc[ao]|white).{0,30}(espiral|wire.?o)' THEN RETURN 'WHITE'; END IF;

  RETURN NULL;
END;
$$;
;

-- <<< END 20260611234549_fix_fn_parse_binding_color_context_v2.sql <<<

-- >>> BEGIN 20260611235441_fix_fn_auto_discover_col_mapping_and_ranking.sql >>>

CREATE OR REPLACE FUNCTION public.fn_auto_discover_all_compatible_packagings(
    p_min_fit_rating text    DEFAULT 'good',
    p_config_type    text    DEFAULT 'default',
    p_only_missing   boolean DEFAULT true
)
RETURNS jsonb
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
    v_prefix      TEXT;
    v_min         DECIMAL; v_tight DECIMAL; v_good DECIMAL; v_max DECIMAL;
    v_inserted    INT := 0;
    v_ranked      INT := 0;
BEGIN
    v_prefix := lower(trim(COALESCE(p_config_type,'default')));
    IF v_prefix NOT IN ('fragile','precision','bottles') THEN v_prefix := ''; END IF;
    IF v_prefix <> '' THEN v_prefix := v_prefix || '_'; END IF;

    SELECT COALESCE(
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'min_gap_mm'),
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'min_gap_mm'), 2
    ) INTO v_min;
    SELECT COALESCE(
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'tight_max_mm'),
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'tight_gap_max_mm'), 5
    ) INTO v_tight;
    SELECT COALESCE(
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'good_max_mm'),
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'good_gap_max_mm'), 15
    ) INTO v_good;
    SELECT COALESCE(
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'max_gap_mm'),
        (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'max_gap_mm'), 50
    ) INTO v_max;

    -- ─────────────────────────────────────────────────────────────────────────
    -- INSERT: cálculo em bloco (set-based, sem cursor)
    -- ─────────────────────────────────────────────────────────────────────────
    WITH
    prods AS (
        SELECT p.id, p.height_cm, p.width_cm, p.length_cm, p.diameter_cm, p.shape_type, p.supplier_id
        FROM products p
        WHERE p.is_active = true
          AND p.product_type IN ('product','kit')
          AND p.height_cm IS NOT NULL
          AND p.width_cm  IS NOT NULL
          AND (
              NOT p_only_missing
              OR NOT EXISTS (
                  SELECT 1 FROM product_packaging_compatibility x
                  WHERE x.product_id = p.id AND x.active = true
              )
          )
    ),
    pkgs AS (
        SELECT pk.id, pk.internal_height_cm, pk.internal_width_cm, pk.internal_length_cm,
               pk.internal_diameter_cm, pk.supplier_id
        FROM products pk
        WHERE pk.product_type = 'packaging'
          AND pk.is_active = true
          AND pk.internal_height_cm IS NOT NULL
    ),
    pairs AS (
        SELECT
            pr.id AS product_id,
            pk.id AS packaging_id,
            pr.supplier_id AS prod_supplier,
            pk.supplier_id AS pkg_supplier,
            pr.shape_type,
            -- ── CILÍNDRICO: gap_d = menor dim da caixa - diâmetro ──
            -- ──             gap_h = maior dim da caixa - altura do produto
            CASE WHEN pr.shape_type = 'cylindrical' THEN
                (GREATEST(pk.internal_height_cm, pk.internal_width_cm, pk.internal_length_cm)
                 - pr.height_cm) * 10                              -- gap ALTURA (vs. maior dim)
            ELSE
                (pk.internal_height_cm - pr.height_cm) * 10
            END AS gap_h_mm,    -- ← sempre gap vertical (altura)

            CASE WHEN pr.shape_type = 'cylindrical' THEN
                NULL                                               -- não se aplica
            ELSE
                (pk.internal_width_cm - pr.width_cm) * 10
            END AS gap_w_mm,

            CASE WHEN pr.shape_type = 'cylindrical' THEN
                NULL                                               -- não se aplica
            ELSE
                (pk.internal_length_cm - pr.length_cm) * 10
            END AS gap_l_mm,

            CASE WHEN pr.shape_type = 'cylindrical' THEN
                (LEAST(pk.internal_height_cm, pk.internal_width_cm, pk.internal_length_cm)
                 - COALESCE(pr.diameter_cm, pr.width_cm)) * 10    -- gap DIÂMETRO (vs. menor dim)
            ELSE
                NULL
            END AS gap_d_mm
        FROM prods pr
        CROSS JOIN pkgs pk
    ),
    classified AS (
        SELECT
            product_id, packaging_id, prod_supplier, pkg_supplier, shape_type,
            gap_h_mm, gap_w_mm, gap_l_mm, gap_d_mm,
            -- gap_min: limitante real do encaixe
            CASE WHEN shape_type = 'cylindrical'
                 THEN LEAST(COALESCE(gap_h_mm, 999), COALESCE(gap_d_mm, 999))
                 ELSE LEAST(COALESCE(gap_h_mm, 999), COALESCE(gap_w_mm, 999), COALESCE(gap_l_mm, 999))
            END AS gap_min,
            CASE WHEN shape_type = 'cylindrical'
                 THEN (COALESCE(gap_h_mm, 0) + COALESCE(gap_d_mm, 0)) / 2.0
                 ELSE (COALESCE(gap_h_mm, 0) + COALESCE(gap_w_mm, 0) + COALESCE(gap_l_mm, 0)) / 3.0
            END AS gap_avg
        FROM pairs
    ),
    rated AS (
        SELECT *,
            CASE
                WHEN gap_min IS NULL OR gap_min >= 900 THEN 'incompatible'
                WHEN gap_min < 0          THEN 'too_tight'
                WHEN gap_min < v_min      THEN 'too_tight'
                WHEN gap_min <= v_tight   THEN 'tight'
                WHEN gap_min <= v_good    THEN 'good'
                WHEN gap_min <= v_max     THEN 'loose'
                ELSE 'too_large'
            END AS fit_rating
        FROM classified
    ),
    compatibles AS (
        SELECT * FROM rated
        WHERE fit_rating = ANY(
            CASE p_min_fit_rating
                WHEN 'tight'  THEN ARRAY['tight']
                WHEN 'good'   THEN ARRAY['tight','good']
                WHEN 'loose'  THEN ARRAY['tight','good','loose']
                ELSE               ARRAY['tight','good','loose']
            END
        )
    ),
    ins AS (
        INSERT INTO product_packaging_compatibility (
            product_id, packaging_id, compatibility_source,
            fit_rating,
            fit_gap_height_mm,    -- ← altura produto vs. maior dim da caixa
            fit_gap_width_mm,     -- ← largura (só retangular)
            fit_gap_length_mm,    -- ← comprimento (só retangular)
            fit_gap_diameter_mm,  -- ← diâmetro (só cilíndrico)
            fit_gap_min_mm,
            fit_gap_avg_mm,
            is_same_supplier, auto_discovered_at, config_type_used, active
        )
        SELECT
            product_id, packaging_id, 'dimension_calculated',
            fit_rating,
            ROUND(COALESCE(gap_h_mm, 0)::numeric, 2),   -- altura
            ROUND(COALESCE(gap_w_mm, 0)::numeric, 2),   -- largura (0 para cilíndrico)
            ROUND(COALESCE(gap_l_mm, 0)::numeric, 2),   -- comprimento (0 para cilíndrico)
            ROUND(COALESCE(gap_d_mm, 0)::numeric, 2),   -- diâmetro (0 para retangular)
            ROUND(gap_min::numeric, 2),
            ROUND(gap_avg::numeric, 2),
            (prod_supplier = pkg_supplier),
            now(),
            COALESCE(NULLIF(p_config_type,'default'),'default'),
            true
        FROM compatibles
        ON CONFLICT (product_id, packaging_id) DO NOTHING
        RETURNING 1
    )
    SELECT COUNT(*) INTO v_inserted FROM ins;

    -- ─────────────────────────────────────────────────────────────────────────
    -- FIX BUG 2: Executar ranking is_recommended para produtos afetados
    -- Apenas para produtos que ainda não têm nenhum is_recommended=true
    -- ─────────────────────────────────────────────────────────────────────────
    IF v_inserted > 0 THEN
        WITH ranking AS (
            SELECT id,
                ROW_NUMBER() OVER (
                    PARTITION BY product_id
                    ORDER BY
                        CASE compatibility_source
                            WHEN 'supplier_indicated' THEN 1
                            WHEN 'dimension_matching'  THEN 2
                            WHEN 'dimension_calculated' THEN 3
                            ELSE 4 END,
                        CASE fit_rating
                            WHEN 'tight' THEN 1
                            WHEN 'good'  THEN 2
                            WHEN 'loose' THEN 3
                            ELSE 4 END,
                        COALESCE(fit_gap_min_mm, 99999) ASC
                ) rn
            FROM product_packaging_compatibility
            WHERE active = true
              AND fit_rating IN ('tight','good','loose')
              AND product_id IN (
                  -- Apenas produtos sem is_recommended ainda
                  SELECT DISTINCT product_id FROM product_packaging_compatibility
                  WHERE active = true
                  GROUP BY product_id
                  HAVING BOOL_OR(is_recommended) = false
              )
        )
        UPDATE product_packaging_compatibility ppc
        SET is_recommended = true, updated_at = now()
        FROM ranking r
        WHERE ppc.id = r.id AND r.rn = 1;

        GET DIAGNOSTICS v_ranked = ROW_COUNT;
    END IF;

    RETURN jsonb_build_object(
        'success',         true,
        'inserted',        v_inserted,
        'ranked',          v_ranked,
        'config_type',     p_config_type,
        'min_fit_rating',  p_min_fit_rating,
        'only_missing',    p_only_missing,
        'limits_mm',       jsonb_build_object('min',v_min,'tight',v_tight,'good',v_good,'max',v_max)
    );
END;
$function$;

COMMENT ON FUNCTION public.fn_auto_discover_all_compatible_packagings(text,text,boolean) IS
'v2 — FIX: mapeamento correto gap_h/gap_d para cilíndrico.
FIX: ranking is_recommended auto-executado após insert.
Cilíndrico: gap_h_mm=altura vs maior dim, gap_d_mm=diâmetro vs menor dim.
Retangular: gap_h/w/l_mm conforme dimensões da caixa.';
;

-- <<< END 20260611235441_fix_fn_auto_discover_col_mapping_and_ranking.sql <<<

-- >>> BEGIN 20260612000237_fn_calculate_packaging_fit_v4_flat_disk_rule.sql >>>

CREATE OR REPLACE FUNCTION public.fn_calculate_packaging_fit(
    p_product_id   uuid,
    p_packaging_id uuid,
    p_config_type  text DEFAULT 'default'
)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $function$
DECLARE
    v_product   RECORD;
    v_packaging RECORD;
    v_gap_h     DECIMAL; v_gap_w DECIMAL; v_gap_l DECIMAL; v_gap_d DECIMAL;
    v_gap_min   DECIMAL; v_gap_avg DECIMAL;
    v_rating    VARCHAR(20);
    v_prefix    TEXT;
    v_min       DECIMAL := 2;
    v_tight     DECIMAL := 5;
    v_good      DECIMAL := 15;
    v_max       DECIMAL := 50;
    v_pkg_dims  DECIMAL[];
    v_pkg_long  DECIMAL;
    v_pkg_short DECIMAL;
    v_pkg_mid   DECIMAL;
    v_needs_padding BOOLEAN := false;
BEGIN
    -- ── config type ──────────────────────────────────────────────────────────
    v_prefix := lower(trim(COALESCE(p_config_type,'default')));
    IF v_prefix NOT IN ('fragile','precision','bottles') THEN v_prefix := ''; END IF;
    IF v_prefix <> '' THEN v_prefix := v_prefix || '_'; END IF;

    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'min_gap_mm'),
                    (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'min_gap_mm'), 2) INTO v_min;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'tight_max_mm'),
                    (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'tight_gap_max_mm'), 5) INTO v_tight;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'good_max_mm'),
                    (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'good_gap_max_mm'), 15) INTO v_good;
    SELECT COALESCE((SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = v_prefix || 'max_gap_mm'),
                    (SELECT config_value::DECIMAL FROM packaging_compatibility_config WHERE config_key = 'max_gap_mm'), 50) INTO v_max;

    -- ── load product ─────────────────────────────────────────────────────────
    SELECT height_cm, width_cm, length_cm, diameter_cm, shape_type
    INTO v_product FROM products WHERE id = p_product_id;

    IF v_product IS NULL THEN
        RETURN jsonb_build_object(
            'error',       'Produto não encontrado: ' || p_product_id,
            'compatible',  false,
            'fit_rating',  'error'
        );
    END IF;

    -- ── load packaging ───────────────────────────────────────────────────────
    SELECT internal_height_cm, internal_width_cm, internal_length_cm, internal_diameter_cm, product_type
    INTO v_packaging FROM products WHERE id = p_packaging_id;

    IF v_packaging IS NULL OR v_packaging.product_type <> 'packaging' THEN
        RETURN jsonb_build_object(
            'error',      CASE WHEN v_packaging IS NULL
                               THEN 'Embalagem não encontrada: ' || p_packaging_id
                               ELSE 'Produto ' || p_packaging_id || ' não é do tipo packaging'
                          END,
            'compatible', false,
            'fit_rating', 'error'
        );
    END IF;

    -- ── gap calculation ──────────────────────────────────────────────────────
    IF v_product.shape_type = 'cylindrical' THEN
        IF v_packaging.internal_diameter_cm IS NOT NULL THEN
            -- Embalagem cilíndrica → cálculo direto
            v_gap_d := (v_packaging.internal_diameter_cm - COALESCE(v_product.diameter_cm, v_product.width_cm)) * 10;
            v_gap_h := (v_packaging.internal_height_cm  - v_product.height_cm) * 10;
        ELSE
            -- Embalagem retangular → orientação ótima (produto na maior dim da caixa)
            v_pkg_dims := ARRAY[
                COALESCE(v_packaging.internal_height_cm, 0),
                COALESCE(v_packaging.internal_width_cm,  0),
                COALESCE(v_packaging.internal_length_cm, 0)
            ];
            v_pkg_long  := GREATEST(v_pkg_dims[1], v_pkg_dims[2], v_pkg_dims[3]);
            v_pkg_short := LEAST   (v_pkg_dims[1], v_pkg_dims[2], v_pkg_dims[3]);
            v_pkg_mid   := v_pkg_dims[1] + v_pkg_dims[2] + v_pkg_dims[3] - v_pkg_long - v_pkg_short;
            v_gap_h     := (v_pkg_long  - v_product.height_cm) * 10;
            v_gap_d     := (v_pkg_short - COALESCE(v_product.diameter_cm, v_product.width_cm)) * 10;
            -- Se a dim. média também for menor que o diâmetro, usar o gap menor
            IF v_pkg_mid < COALESCE(v_product.diameter_cm, v_product.width_cm) THEN
                v_gap_d := LEAST(v_gap_d, (v_pkg_mid - COALESCE(v_product.diameter_cm, v_product.width_cm)) * 10);
            END IF;
        END IF;
        v_gap_min := LEAST(COALESCE(v_gap_d, 999), COALESCE(v_gap_h, 999));
        v_gap_avg := (COALESCE(v_gap_d, 0) + COALESCE(v_gap_h, 0)) / 2.0;

        -- ⚡ REGRA DISCO PLANO (B11): produto muito plano em caixa alta
        -- Se gap_h > 200mm, o produto ficará solto verticalmente → needs_padding, cap em 'loose'
        IF COALESCE(v_gap_h, 0) > 200 THEN
            v_needs_padding := true;
        END IF;

    ELSE
        v_gap_h   := (v_packaging.internal_height_cm  - v_product.height_cm) * 10;
        v_gap_w   := (v_packaging.internal_width_cm   - v_product.width_cm ) * 10;
        v_gap_l   := (v_packaging.internal_length_cm  - v_product.length_cm) * 10;
        v_gap_min := LEAST(COALESCE(v_gap_h, 999), COALESCE(v_gap_w, 999), COALESCE(v_gap_l, 999));
        v_gap_avg := (COALESCE(v_gap_h, 0) + COALESCE(v_gap_w, 0) + COALESCE(v_gap_l, 0)) / 3.0;
    END IF;

    -- ── rating classification ─────────────────────────────────────────────────
    IF v_gap_min IS NULL OR v_gap_min >= 900 THEN
        v_rating := 'incompatible';
    ELSIF v_gap_min < 0     THEN v_rating := 'too_tight';
    ELSIF v_gap_min < v_min THEN v_rating := 'too_tight';
    ELSIF v_gap_min <= v_tight THEN v_rating := 'tight';
    ELSIF v_gap_min <= v_good  THEN v_rating := 'good';
    ELSIF v_gap_min <= v_max   THEN v_rating := 'loose';
    ELSE v_rating := 'too_large';
    END IF;

    -- ⚡ CAP disco plano: se needs_padding, máximo é 'loose'
    IF v_needs_padding AND v_rating IN ('tight','good') THEN
        v_rating := 'loose';
    END IF;

    RETURN jsonb_build_object(
        'compatible',      v_rating IN ('tight','good','loose'),
        'fit_rating',      v_rating,
        'config_type',     COALESCE(NULLIF(p_config_type,'default'),'default'),
        'gap_height_mm',   ROUND(COALESCE(v_gap_h, 0)::numeric, 2),
        'gap_width_mm',    ROUND(COALESCE(v_gap_w, 0)::numeric, 2),
        'gap_length_mm',   ROUND(COALESCE(v_gap_l, 0)::numeric, 2),
        'gap_diameter_mm', ROUND(COALESCE(v_gap_d, 0)::numeric, 2),
        'gap_min_mm',      CASE WHEN v_gap_min < 900 THEN ROUND(v_gap_min::numeric, 2) ELSE NULL END,
        'gap_avg_mm',      ROUND(v_gap_avg::numeric, 2),
        'shape',           v_product.shape_type,
        'needs_padding',   v_needs_padding,
        'limits_mm',       jsonb_build_object('min',v_min,'tight',v_tight,'good',v_good,'max',v_max)
    );
END;
$function$;

COMMENT ON FUNCTION public.fn_calculate_packaging_fit(uuid, uuid, text) IS
'v4 — Inclui regra B11 (disco plano): se gap_height > 200mm → needs_padding=true, fit_rating cap=loose.
Schema consistente: erro retorna fit_rating=''error''.
Cilíndrico×retangular: orientação ótima (produto na maior dim da caixa).
Suporta config_type: default|fragile|precision|bottles.';
;

