-- >>> BEGIN 20260612134405_fix_v_products_public_add_circumference_cm_at_end.sql >>>

-- FIX: Adicionar circumference_cm ao FINAL da v_products_public
-- CREATE OR REPLACE VIEW só permite adicionar colunas no final (sem deslocar existentes)

DO $$
DECLARE
  v_def text;
  v_new text;
BEGIN
  SELECT pg_get_viewdef('public.v_products_public'::regclass, true) INTO v_def;
  
  -- Adicionar circumference_cm no final, antes do FROM products
  v_new := replace(v_def,
    chr(10) || '   FROM products',
    ',' || chr(10) || '    circumference_cm' || chr(10) || '   FROM products'
  );
  
  IF v_new = v_def THEN
    RAISE EXCEPTION 'Pattern FROM products não encontrado';
  END IF;
  
  EXECUTE 'CREATE OR REPLACE VIEW public.v_products_public AS ' || v_new;
  RAISE NOTICE 'circumference_cm adicionado ao final de v_products_public';
END $$;
;

-- <<< END 20260612134405_fix_v_products_public_add_circumference_cm_at_end.sql <<<

-- >>> BEGIN 20260612141612_fix_sync_main_category_trigger_always_update.sql >>>

-- FIX ESTRUTURAL: fn_sync_main_category_from_pca agora SEMPRE atualiza
-- Antes: só atualizava quando main_category_id IS NULL (causava divergências)
-- Depois: atualiza SEMPRE que is_primary=true é inserido/alterado
CREATE OR REPLACE FUNCTION public.fn_sync_main_category_from_pca()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  -- Atualiza quando is_primary=true É INSERIDO ou MUDADO para true
  -- Remove restrição "AND main_category_id IS NULL" — agora SEMPRE sincroniza
  IF NEW.is_primary = true THEN
    UPDATE products 
    SET main_category_id = NEW.category_id,
        updated_at = now()
    WHERE id = NEW.product_id;
  END IF;
  RETURN NEW;
END;
$function$;

COMMENT ON FUNCTION public.fn_sync_main_category_from_pca() IS 
'Trigger: sincroniza products.main_category_id com PCA is_primary=true. 
Corrigido em 2026-06-12: remove restrição "IS NULL" — agora sempre sobrescreve para manter coerência.';
;

-- <<< END 20260612141612_fix_sync_main_category_trigger_always_update.sql <<<

-- >>> BEGIN 20260612141819_add_smoke_tests_category_governance_t21_t26.sql >>>

-- PASSO 5: Adicionar testes T21-T26 à fn_smoke_tests_categorization
-- Cobre os 4 blind spots identificados + 2 testes extras de governança
CREATE OR REPLACE FUNCTION public.fn_smoke_tests_categorization()
 RETURNS TABLE(test_id text, test_name text, expected text, actual text, passed boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org uuid := '5db5aee1-064b-4ef4-9193-345dcd8274ea';
  v_active_total bigint;
  v_active_no_tags bigint;
  v_pct_no_tags numeric;
BEGIN

  SELECT COUNT(*) INTO v_active_total FROM products WHERE is_active=true;
  SELECT COUNT(*) INTO v_active_no_tags FROM products p WHERE p.is_active=true
    AND NOT EXISTS(SELECT 1 FROM product_tags pt WHERE pt.product_id=p.id);
  v_pct_no_tags := ROUND(100.0*v_active_no_tags/NULLIF(v_active_total,0),2);

  -- ── TESTES ORIGINAIS T01-T20 ─────────────────────────────────────────────
  RETURN QUERY SELECT 'T01','COR variation_type existe e ativo','true',
    EXISTS(SELECT 1 FROM variation_types WHERE code='COR' AND organization_id=v_org AND is_active=true)::text,
    EXISTS(SELECT 1 FROM variation_types WHERE code='COR' AND organization_id=v_org AND is_active=true);

  RETURN QUERY SELECT 'T02','variation_values COR >= 90','true',
    (COUNT(*)>=90)::text, COUNT(*)>=90
    FROM variation_values vv JOIN variation_types vt ON vv.variation_type_id=vt.id
    WHERE vt.code='COR' AND vt.organization_id=v_org;

  RETURN QUERY SELECT 'T03','supplier_colors 100% linked a color_variations','true',
    (COUNT(*)=0)::text, COUNT(*)=0
    FROM supplier_colors WHERE color_variation_id IS NULL AND organization_id=v_org;

  RETURN QUERY SELECT 'T04','product_novelties sem duplicatas (product+supplier)','true',
    (COUNT(*)=0)::text, COUNT(*)=0
    FROM (SELECT product_id,COALESCE(supplier_id::text,'__null__') k,COUNT(*)n
          FROM product_novelties GROUP BY 1,2 HAVING COUNT(*)>1) x;

  RETURN QUERY SELECT 'T05','product_novelties: 0 expiradas ainda ativas','true',
    (COUNT(*)=0)::text, COUNT(*)=0
    FROM product_novelties
    WHERE is_active=true AND expires_at IS NOT NULL AND expires_at < NOW();

  RETURN QUERY SELECT 'T06','product_novelties: partial UNIQUE index supplier NOT NULL','true',
    EXISTS(SELECT 1 FROM pg_indexes WHERE tablename='product_novelties'
      AND indexdef ILIKE '%supplier_id IS NOT NULL%')::text,
    EXISTS(SELECT 1 FROM pg_indexes WHERE tablename='product_novelties'
      AND indexdef ILIKE '%supplier_id IS NOT NULL%');

  -- T07 ATUALIZADO: hierarquia entre 3 e 4 níveis (antes só >= 3, passava com L6)
  RETURN QUERY SELECT 'T07','categories: hierarquia ativa entre 3 e 4 níveis (max=4)','true',
    (COUNT(DISTINCT level) BETWEEN 3 AND 4)::text,
    COUNT(DISTINCT level) BETWEEN 3 AND 4
    FROM categories
    WHERE is_active=true AND deleted_at IS NULL;

  -- T08 ATUALIZADO: >= 300 registros ATIVOS não deletados (antes era 400 total)
  RETURN QUERY SELECT 'T08','categories ativas (não deletadas) >= 300','true',
    (COUNT(*)>=300)::text, COUNT(*)>=300
    FROM categories WHERE is_active=true AND deleted_at IS NULL;

  RETURN QUERY SELECT 'T09','color_variations: >= 80 registros','true',
    (COUNT(*)>=80)::text, COUNT(*)>=80
    FROM color_variations;

  RETURN QUERY SELECT 'T10','supplier_category_mappings: >= 100 registros','true',
    (COUNT(*)>=100)::text, COUNT(*)>=100
    FROM supplier_category_mappings;

  RETURN QUERY SELECT 'T11','variant_supplier_sources: 6 colunas next_date','true',
    (COUNT(*)=6)::text, COUNT(*)=6
    FROM information_schema.columns
    WHERE table_schema='public' AND table_name='variant_supplier_sources'
      AND column_name ILIKE 'next_date_%';

  RETURN QUERY SELECT 'T12','products ativos com category_id >= 99.9%','true',
    (ROUND(100.0*SUM(CASE WHEN category_id IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),2)>=99.9)::text,
    ROUND(100.0*SUM(CASE WHEN category_id IS NOT NULL THEN 1 ELSE 0 END)/COUNT(*),2)>=99.9
    FROM products WHERE is_active=true;

  RETURN QUERY SELECT 'T13','tags: UNIQUE (org_id, slug) existe','true',
    EXISTS(SELECT 1 FROM pg_indexes WHERE tablename='tags'
      AND indexdef ILIKE '%organization_id%slug%')::text,
    EXISTS(SELECT 1 FROM pg_indexes WHERE tablename='tags'
      AND indexdef ILIKE '%organization_id%slug%');

  RETURN QUERY SELECT 'T14','product_tags: UNIQUE (product_id, tag_id) existe','true',
    EXISTS(SELECT 1 FROM pg_indexes WHERE tablename='product_tags'
      AND indexdef ILIKE '%product_id%tag_id%' AND indexdef ILIKE '%unique%')::text,
    EXISTS(SELECT 1 FROM pg_indexes WHERE tablename='product_tags'
      AND indexdef ILIKE '%product_id%tag_id%' AND indexdef ILIKE '%unique%');

  RETURN QUERY SELECT 'T15','product_relationships: 0 duplicatas','true',
    (COUNT(*)=0)::text, COUNT(*)=0
    FROM (SELECT product_id,related_product_id,relationship_type,COUNT(*)n
          FROM product_relationships GROUP BY 1,2,3 HAVING COUNT(*)>1) x;

  RETURN QUERY SELECT 'T16',
    'product_tags: produtos sem tag <= 0.5% (Gold-only orphans aceitos)',
    '<= 0.5%',
    v_pct_no_tags::text || '%  (' || v_active_no_tags || ' de ' || v_active_total || ' ativos)',
    v_pct_no_tags <= 0.5;

  RETURN QUERY SELECT 'T17','variation_values: UNIQUE (org, type, value) existe','true',
    EXISTS(SELECT 1 FROM pg_indexes WHERE tablename='variation_values'
      AND indexdef ILIKE '%organization_id%variation_type_id%value%')::text,
    EXISTS(SELECT 1 FROM pg_indexes WHERE tablename='variation_values'
      AND indexdef ILIKE '%organization_id%variation_type_id%value%');

  RETURN QUERY SELECT 'T18','supplier_colors: index (supplier_id, code) existe','true',
    EXISTS(SELECT 1 FROM pg_indexes WHERE tablename='supplier_colors'
      AND indexdef ILIKE '%supplier_id%code%')::text,
    EXISTS(SELECT 1 FROM pg_indexes WHERE tablename='supplier_colors'
      AND indexdef ILIKE '%supplier_id%code%');

  RETURN QUERY SELECT 'T19','fn_expire_novelties() executável','true',
    EXISTS(SELECT 1 FROM pg_proc WHERE proname='fn_expire_novelties')::text,
    EXISTS(SELECT 1 FROM pg_proc WHERE proname='fn_expire_novelties');

  RETURN QUERY SELECT 'T20',
    'products ativos >= 7100',
    '>= 7100',
    v_active_total::text,
    v_active_total >= 7100;

  -- ── NOVOS TESTES T21-T26: GOVERNANÇA DE CATEGORIAS ──────────────────────

  -- T21 [BLIND SPOT 1]: Nenhum produto ativo com category_id em nível > 4
  -- Detecta regressão de categorias L5/L6 voltando ao pipeline
  RETURN QUERY SELECT 'T21',
    'Produtos ativos: category_id nivel máximo = 4 (nenhum em L5+)',
    '0',
    (SELECT COUNT(*)::text
     FROM products p
     JOIN categories c ON c.id = p.category_id
     WHERE p.is_active = true AND c.level > 4),
    (SELECT COUNT(*) = 0
     FROM products p
     JOIN categories c ON c.id = p.category_id
     WHERE p.is_active = true AND c.level > 4);

  -- T22 [BLIND SPOT 2]: Coerência Gold — category_id = main_category_id (0 divergências)
  -- Detecta regressão do trigger fn_sync_main_category_from_pca
  RETURN QUERY SELECT 'T22',
    'Gold coerência: category_id = main_category_id (0 divergências)',
    '0',
    (SELECT COUNT(*)::text
     FROM products
     WHERE is_active = true
       AND category_id IS NOT NULL
       AND main_category_id IS NOT NULL
       AND category_id != main_category_id),
    (SELECT COUNT(*) = 0
     FROM products
     WHERE is_active = true
       AND category_id IS NOT NULL
       AND main_category_id IS NOT NULL
       AND category_id != main_category_id);

  -- T23 [BLIND SPOT 3]: Todas as categorias L1-L3 ativas têm slug
  -- Sem slug = sem URL válida no site
  RETURN QUERY SELECT 'T23',
    'Categorias L1-L3 ativas: todas têm slug (0 sem slug)',
    '0',
    (SELECT COUNT(*)::text
     FROM categories
     WHERE level BETWEEN 1 AND 3
       AND is_active = true
       AND deleted_at IS NULL
       AND (slug IS NULL OR TRIM(slug) = '')),
    (SELECT COUNT(*) = 0
     FROM categories
     WHERE level BETWEEN 1 AND 3
       AND is_active = true
       AND deleted_at IS NULL
       AND (slug IS NULL OR TRIM(slug) = ''));

  -- T24 [BLIND SPOT 4]: supplier_subtype_category_map aponta só para cats ativas/não-deletadas
  -- Detecta contaminação por categorias órfãs no pipeline
  RETURN QUERY SELECT 'T24',
    'supplier_subtype_category_map: 0 entradas apontando para cats deletadas/inativas',
    '0',
    (SELECT COUNT(*)::text
     FROM supplier_subtype_category_map sscm
     LEFT JOIN categories c ON c.id = sscm.category_id
     WHERE c.id IS NULL 
       OR c.is_active = false 
       OR c.deleted_at IS NOT NULL),
    (SELECT COUNT(*) = 0
     FROM supplier_subtype_category_map sscm
     LEFT JOIN categories c ON c.id = sscm.category_id
     WHERE c.id IS NULL 
       OR c.is_active = false 
       OR c.deleted_at IS NOT NULL);

  -- T25 [EXTRA]: Produtos ativos têm PCA is_primary=true (0 órfãos)
  -- Garante integridade da atribuição primária de categoria
  RETURN QUERY SELECT 'T25',
    'Produtos ativos: todos têm PCA is_primary=true (0 órfãos)',
    '0',
    (SELECT COUNT(*)::text
     FROM products p
     WHERE p.is_active = true
       AND NOT EXISTS (
         SELECT 1 FROM product_category_assignments pca
         WHERE pca.product_id = p.id AND pca.is_primary = true
       )),
    (SELECT COUNT(*) = 0
     FROM products p
     WHERE p.is_active = true
       AND NOT EXISTS (
         SELECT 1 FROM product_category_assignments pca
         WHERE pca.product_id = p.id AND pca.is_primary = true
       ));

  -- T26 [EXTRA]: Nenhum produto ativo com category_id apontando para categoria deletada
  -- Detecta vazamentos de FK para categorias soft-deleted
  RETURN QUERY SELECT 'T26',
    'Produtos ativos: category_id aponta para categoria ativa (0 FK órfãs)',
    '0',
    (SELECT COUNT(*)::text
     FROM products p
     LEFT JOIN categories c ON c.id = p.category_id
     WHERE p.is_active = true
       AND p.category_id IS NOT NULL
       AND (c.id IS NULL OR c.is_active = false OR c.deleted_at IS NOT NULL)),
    (SELECT COUNT(*) = 0
     FROM products p
     LEFT JOIN categories c ON c.id = p.category_id
     WHERE p.is_active = true
       AND p.category_id IS NOT NULL
       AND (c.id IS NULL OR c.is_active = false OR c.deleted_at IS NOT NULL));

END;
$function$;

COMMENT ON FUNCTION public.fn_smoke_tests_categorization() IS
'Suite de smoke tests para categorização. 
T01-T20: testes originais.
T21: nível máximo L4 (detecta regressão L5).
T22: coerência category_id = main_category_id.
T23: slugs obrigatórios em L1-L3.
T24: pipeline SSCM sem categorias deletadas.
T25: PCA is_primary cobertura total.
T26: FK integrity category_id.
Atualizado: 2026-06-12 — adicionados T21-T26, T07/T08 corrigidos.';
;

-- <<< END 20260612141819_add_smoke_tests_category_governance_t21_t26.sql <<<

-- >>> BEGIN 20260612144301_fix_p0a_trends_top_products_numeric_sort.sql >>>

CREATE OR REPLACE FUNCTION public.fn_generate_trends_insights(p_user_id uuid, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cache_key  text;
  v_cached     jsonb;
  v_insights   jsonb;
  v_since      timestamptz;
  v_total_views    bigint;
  v_total_searches bigint;
  v_unique_terms   bigint;
  v_unique_prods   bigint;
BEGIN
  p_days := GREATEST(1, LEAST(COALESCE(p_days, 30), 999));
  v_since     := NOW() - (p_days || ' days')::interval;
  v_cache_key := 'trends_' || p_days || '_' || TO_CHAR(NOW(), 'YYYY-MM-DD');

  IF p_user_id IS NOT NULL THEN
    SELECT payload INTO v_cached
    FROM public.ai_insights_cache
    WHERE user_id      = p_user_id
      AND function_name = 'fn_generate_trends_insights'
      AND cache_key     = v_cache_key
      AND expires_at    > NOW()
    LIMIT 1;
    IF FOUND AND v_cached IS NOT NULL THEN RETURN v_cached; END IF;
  END IF;

  SELECT COUNT(*)::bigint, COUNT(DISTINCT product_id)::bigint
  INTO v_total_views, v_unique_prods
  FROM public.product_views
  WHERE created_at >= v_since
    AND (p_user_id IS NULL OR seller_id = p_user_id);

  SELECT COUNT(*)::bigint, COUNT(DISTINCT search_term)::bigint
  INTO v_total_searches, v_unique_terms
  FROM public.search_analytics
  WHERE created_at >= v_since;

  SELECT jsonb_build_object(
    'totals', jsonb_build_object(
      'views', v_total_views, 'searches', v_total_searches,
      'unique_terms', v_unique_terms, 'unique_products', v_unique_prods
    ),
    'top_products', COALESCE((
      SELECT jsonb_agg(sub ORDER BY (sub->>'view_count')::bigint DESC)
      FROM (
        SELECT jsonb_build_object(
          'product_id',   pv.product_id,
          'view_count',   COUNT(*),
          'product_name', MAX(p.name)
        ) AS sub
        FROM public.product_views pv
        LEFT JOIN public.products p ON p.id = pv.product_id
        WHERE pv.created_at >= v_since
          AND (p_user_id IS NULL OR pv.seller_id = p_user_id)
        GROUP BY pv.product_id
        ORDER BY COUNT(*) DESC
        LIMIT 10
      ) x
    ), '[]'::jsonb),
    'top_searches', COALESCE((
      SELECT jsonb_agg(sub ORDER BY (sub->>'count')::int DESC)
      FROM (
        SELECT jsonb_build_object(
          'term', search_term, 'count', COUNT(*),
          'zero_pct', ROUND(100.0 * SUM(CASE WHEN results_count=0 THEN 1 ELSE 0 END)
                      / NULLIF(COUNT(*),0), 1),
          'zero_results', SUM(CASE WHEN results_count=0 THEN 1 ELSE 0 END)
        ) AS sub
        FROM public.search_analytics
        WHERE created_at >= v_since
        GROUP BY search_term
        ORDER BY COUNT(*) DESC
        LIMIT 10
      ) x
    ), '[]'::jsonb),
    'repressed_demand', COALESCE((
      SELECT jsonb_agg(sub ORDER BY (sub->>'zero_result_searches')::int DESC)
      FROM (
        SELECT jsonb_build_object(
          'term', search_term, 'searches', COUNT(*),
          'zero_result_searches', SUM(CASE WHEN results_count=0 THEN 1 ELSE 0 END)
        ) AS sub
        FROM public.search_analytics
        WHERE created_at >= v_since
        GROUP BY search_term
        HAVING SUM(CASE WHEN results_count=0 THEN 1 ELSE 0 END) > 0
        ORDER BY SUM(CASE WHEN results_count=0 THEN 1 ELSE 0 END) DESC
        LIMIT 10
      ) x
    ), '[]'::jsonb),
    'period_days',  p_days,
    'generated_at', NOW()
  ) INTO v_insights;

  IF p_user_id IS NOT NULL THEN
    INSERT INTO public.ai_insights_cache (
      user_id, function_name, cache_key, payload,
      model, tokens_input, tokens_output, duration_ms,
      created_at, expires_at
    ) VALUES (
      p_user_id, 'fn_generate_trends_insights', v_cache_key, v_insights,
      'postgres_aggregation', 0, 0, 0,
      NOW(), NOW() + INTERVAL '23 hours'
    )
    ON CONFLICT (user_id, function_name, cache_key)
    DO UPDATE SET payload = EXCLUDED.payload, created_at = NOW(),
      expires_at = NOW() + INTERVAL '23 hours';
  END IF;

  RETURN v_insights;

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'error', SQLERRM,
    'totals', jsonb_build_object('views',0,'searches',0,'unique_terms',0,'unique_products',0),
    'top_products','[]'::jsonb,'top_searches','[]'::jsonb,
    'repressed_demand','[]'::jsonb,'period_days',p_days,'generated_at',NOW()
  );
END;
$function$;
;

-- <<< END 20260612144301_fix_p0a_trends_top_products_numeric_sort.sql <<<

-- >>> BEGIN 20260612144459_fix_p0b_search_analytics_results_count_sanitize.sql >>>

-- 1) Sanitizar histórico: resultados > 2000 = lixo do frontend → sentinel -1
UPDATE public.search_analytics
SET results_count = -1
WHERE results_count > 2000;

-- 2) Fix fn_log_search_analytics: sanitizar results_count na entrada
--    Valores > 2000 quase certamente são totais de catálogo, não contagens reais
--    Sentinel -1 indica "valor não confiável / enviado pelo frontend incorretamente"
CREATE OR REPLACE FUNCTION public.fn_log_search_analytics(
  p_search_term text,
  p_results_count integer DEFAULT 0,
  p_search_context text DEFAULT NULL::text,
  p_debounce_seconds integer DEFAULT 2
)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_last_logged timestamptz;
  v_clean_term  text;
  v_safe_count  integer;
BEGIN
  v_clean_term := LOWER(TRIM(LEFT(p_search_term, 200)));

  IF LENGTH(v_clean_term) < 2 THEN
    RETURN false;
  END IF;

  -- Sanitizar results_count:
  --   -1  = sentinel "valor suspeito/não-confiável" (frontend enviou total do catálogo)
  --    0  = zero genuíno (nenhum resultado encontrado)
  --   >0  = contagem real (plausível: entre 1 e 5000)
  v_safe_count := CASE
    WHEN p_results_count IS NULL        THEN 0
    WHEN p_results_count < 0            THEN 0      -- negativos → zero
    WHEN p_results_count > 2000         THEN -1     -- suspeito → sentinel
    ELSE GREATEST(0, p_results_count)
  END;

  -- Debounce: mesmo termo + mesmo usuário na janela de tempo
  SELECT MAX(created_at) INTO v_last_logged
  FROM public.search_analytics sa
  WHERE sa.search_term = v_clean_term
    AND sa.user_id IS NOT DISTINCT FROM auth.uid()
    AND sa.created_at >= NOW() - (p_debounce_seconds || ' seconds')::interval;

  IF v_last_logged IS NOT NULL THEN
    RETURN false;
  END IF;

  INSERT INTO public.search_analytics (
    search_term, results_count, search_context, user_id, created_at
  ) VALUES (
    v_clean_term, v_safe_count, p_search_context, auth.uid(), NOW()
  );

  RETURN true;

EXCEPTION
  WHEN OTHERS THEN
    RETURN false;
END;
$function$;

-- 3) Invalidar cache stale gerado com dados incorretos
DELETE FROM public.ai_insights_cache
WHERE function_name = 'fn_generate_trends_insights';
;

