  END IF;

  RETURN v_insights;

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'error', SQLERRM,
    'totals', jsonb_build_object(
      'views',0,'searches',0,'unique_terms',0,'unique_products',0,
