-- >>> BEGIN 20260612145216_create_stock_movements_table.sql >>>

-- =============================================================
-- Tabela de movimentações manuais de estoque
-- Auditoria completa de entradas, saídas e ajustes operacionais
-- =============================================================

CREATE TABLE public.stock_movements (
    id              uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
    variant_id      uuid        NOT NULL REFERENCES product_variants(id) ON DELETE RESTRICT,
    movement_type   text        NOT NULL,
    quantity        integer     NOT NULL,
    stock_before    integer,
    stock_after     integer,
    unit_cost       numeric(12,4),
    reference_type  text,
    reference_number text,
    notes           text,
    created_by      uuid,
    created_at      timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT chk_stock_movements_type
        CHECK (movement_type IN ('ENTRADA','SAIDA','AJUSTE','PERDA','RESERVA','DEVOLUCAO')),
    CONSTRAINT chk_stock_movements_qty_nonzero
        CHECK (quantity != 0)
);

-- Índices para queries frequentes
CREATE INDEX idx_stock_movements_variant_id  ON public.stock_movements (variant_id);
CREATE INDEX idx_stock_movements_created_at  ON public.stock_movements (created_at DESC);
CREATE INDEX idx_stock_movements_type        ON public.stock_movements (movement_type);
CREATE INDEX idx_stock_movements_reference   ON public.stock_movements (reference_number) WHERE reference_number IS NOT NULL;

-- Comentários descritivos
COMMENT ON TABLE  public.stock_movements IS 'Histórico auditável de movimentações manuais de estoque (entradas, saídas, ajustes). Não substituído pelo sync automático de fornecedores.';
COMMENT ON COLUMN public.stock_movements.movement_type    IS 'ENTRADA=recebimento, SAIDA=despacho/venda, AJUSTE=correção inventário, PERDA=quebra/avaria, RESERVA=reserva prévia, DEVOLUCAO=retorno de cliente';
COMMENT ON COLUMN public.stock_movements.quantity         IS 'Positivo para ENTRADA, negativo para SAIDA/PERDA/RESERVA';
COMMENT ON COLUMN public.stock_movements.reference_type   IS 'Tipo do documento de referência (NF, PEDIDO, RESERVA_ID, etc.)';
COMMENT ON COLUMN public.stock_movements.reference_number IS 'Número do documento de referência';

-- RLS: habilitar (alinhado com padrão das demais tabelas do schema)
ALTER TABLE public.stock_movements ENABLE ROW LEVEL SECURITY;

-- Policy: leitura para usuários autenticados da organização
CREATE POLICY "stock_movements_select" ON public.stock_movements
    FOR SELECT TO authenticated USING (true);

-- Policy: insert/update para authenticated (as funções rodam com SECURITY INVOKER)
CREATE POLICY "stock_movements_insert" ON public.stock_movements
    FOR INSERT TO authenticated WITH CHECK (true);
;

-- <<< END 20260612145216_create_stock_movements_table.sql <<<

-- >>> BEGIN 20260612161032_fix_p2a_conversion_funnel_function.sql >>>

-- Função dedicada para o Funil de Conversão real do módulo de Tendências
-- Retorna cada etapa do funil com volume e taxa de conversão entre etapas

CREATE OR REPLACE FUNCTION public.fn_get_conversion_funnel(
  p_user_id uuid DEFAULT NULL,
  p_days    integer DEFAULT 30
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_since          timestamptz;
  v_since_prev     timestamptz;
  v_buscas         bigint := 0;
  v_views          bigint := 0;
  v_prods_vistos   bigint := 0;
  v_orcamentos     bigint := 0;
  v_pedidos        bigint := 0;
  -- Período anterior
  v_buscas_prev    bigint := 0;
  v_views_prev     bigint := 0;
  v_orcamentos_prev bigint := 0;
BEGIN
  -- Validação de acesso: igual à fn_generate_trends_insights
  IF p_user_id IS NOT NULL
     AND p_user_id != auth.uid()
     AND NOT is_manager_or_admin()
  THEN
    RETURN jsonb_build_object('error','Acesso negado');
  END IF;

  p_days      := GREATEST(1, LEAST(COALESCE(p_days, 30), 999));
  v_since     := NOW() - (p_days || ' days')::interval;
  v_since_prev:= NOW() - (p_days * 2 || ' days')::interval;

  -- Etapa 1: Buscas (excluindo sentinels -1)
  SELECT COUNT(*)::bigint INTO v_buscas
  FROM search_analytics
  WHERE created_at >= v_since AND results_count != -1;

  SELECT COUNT(*)::bigint INTO v_buscas_prev
  FROM search_analytics
  WHERE created_at >= v_since_prev AND created_at < v_since AND results_count != -1;

  -- Etapa 2: Visualizações de produto
  SELECT COUNT(*)::bigint, COUNT(DISTINCT product_id)::bigint
  INTO v_views, v_prods_vistos
  FROM product_views
  WHERE created_at >= v_since
    AND (p_user_id IS NULL OR seller_id = p_user_id);

  SELECT COUNT(*)::bigint INTO v_views_prev
  FROM product_views
  WHERE created_at >= v_since_prev AND created_at < v_since
    AND (p_user_id IS NULL OR seller_id = p_user_id);

  -- Etapa 3: Orçamentos criados no período
  SELECT COUNT(DISTINCT q.id)::bigint INTO v_orcamentos
  FROM quotes q
  WHERE q.created_at >= v_since
    AND (p_user_id IS NULL OR q.created_by = p_user_id OR q.assigned_to = p_user_id);

  SELECT COUNT(DISTINCT q.id)::bigint INTO v_orcamentos_prev
  FROM quotes q
  WHERE q.created_at >= v_since_prev AND q.created_at < v_since
    AND (p_user_id IS NULL OR q.created_by = p_user_id OR q.assigned_to = p_user_id);

  -- Etapa 4: Pedidos
  SELECT COUNT(*)::bigint INTO v_pedidos
  FROM orders
  WHERE created_at >= v_since
    AND (p_user_id IS NULL OR created_by = p_user_id);

  RETURN jsonb_build_object(
    'period_days', p_days,
    'generated_at', NOW(),
    'funnel', jsonb_build_array(
      jsonb_build_object(
        'step', 1, 'label', 'Buscas',
        'value', v_buscas,
        'prev_value', v_buscas_prev,
        'growth_pct', CASE WHEN v_buscas_prev=0 THEN NULL
          ELSE ROUND(100.0*(v_buscas-v_buscas_prev)::numeric/v_buscas_prev,1) END,
        'conversion_from_prev', NULL
      ),
      jsonb_build_object(
        'step', 2, 'label', 'Visualizações',
        'value', v_views,
        'prev_value', v_views_prev,
        'growth_pct', CASE WHEN v_views_prev=0 THEN NULL
          ELSE ROUND(100.0*(v_views-v_views_prev)::numeric/v_views_prev,1) END,
        -- Taxa de conversão: views por busca (views/buscas × 100)
        'conversion_from_prev', CASE WHEN v_buscas=0 THEN NULL
          ELSE ROUND(100.0*v_views/v_buscas,1) END,
        'unique_products', v_prods_vistos
      ),
      jsonb_build_object(
        'step', 3, 'label', 'Orçamentos',
        'value', v_orcamentos,
        'prev_value', v_orcamentos_prev,
        'growth_pct', CASE WHEN v_orcamentos_prev=0 THEN NULL
          ELSE ROUND(100.0*(v_orcamentos-v_orcamentos_prev)::numeric/v_orcamentos_prev,1) END,
        'conversion_from_prev', CASE WHEN v_prods_vistos=0 THEN NULL
          ELSE ROUND(100.0*v_orcamentos/v_prods_vistos,1) END
      ),
      jsonb_build_object(
        'step', 4, 'label', 'Pedidos',
        'value', v_pedidos,
        'prev_value', NULL,
        'growth_pct', NULL,
        'conversion_from_prev', CASE WHEN v_orcamentos=0 THEN NULL
          ELSE ROUND(100.0*v_pedidos/v_orcamentos,1) END
      )
    )
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM, 'funnel', '[]'::jsonb);
END;
$function$;

GRANT EXECUTE ON FUNCTION public.fn_get_conversion_funnel(uuid, integer)
  TO authenticated, service_role;
;

-- <<< END 20260612161032_fix_p2a_conversion_funnel_function.sql <<<

-- >>> BEGIN 20260612161137_fix_p2d_enriched_repressed_demand_with_catalog_diagnosis.sql >>>

-- Criar função dedicada de Demanda Reprimida com diagnóstico de falso-zero
-- Classifica cada termo: FALSO-ZERO (produto existe, bug de busca) vs REAL (produto ausente)

CREATE OR REPLACE FUNCTION public.fn_get_repressed_demand(
  p_user_id uuid DEFAULT NULL,
  p_days    integer DEFAULT 30,
  p_limit   integer DEFAULT 20
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_since   timestamptz;
  v_result  jsonb;
BEGIN
  IF p_user_id IS NOT NULL
     AND p_user_id != auth.uid()
     AND NOT is_manager_or_admin()
  THEN
    RETURN jsonb_build_object('error','Acesso negado');
  END IF;

  p_days  := GREATEST(1, LEAST(COALESCE(p_days, 30), 999));
  p_limit := GREATEST(1, LEAST(COALESCE(p_limit, 20), 100));
  v_since := NOW() - (p_days || ' days')::interval;

  WITH zero_terms AS (
    SELECT
      search_term,
      COUNT(*) FILTER (WHERE results_count != -1)          AS total_buscas,
      SUM(CASE WHEN results_count = 0 THEN 1 ELSE 0 END)   AS zeros,
      ROUND(
        100.0 * SUM(CASE WHEN results_count = 0 THEN 1 ELSE 0 END)
        / NULLIF(COUNT(*) FILTER (WHERE results_count != -1), 0),
        1
      ) AS pct_zero
    FROM public.search_analytics
    WHERE created_at >= v_since
    GROUP BY search_term
    HAVING SUM(CASE WHEN results_count = 0 THEN 1 ELSE 0 END) > 0
    ORDER BY SUM(CASE WHEN results_count = 0 THEN 1 ELSE 0 END) DESC
    LIMIT p_limit
  ),
  enriched AS (
    SELECT
      zt.search_term,
      zt.total_buscas,
      zt.zeros                           AS zero_result_searches,
      zt.pct_zero,
      -- Verificar via fulltext search (mesma lógica do search_products_fulltext)
      (SELECT COUNT(*)::int FROM public.products p
       WHERE p.is_active = true
         AND (p.is_deleted IS NULL OR p.is_deleted = false)
         AND p.sale_price IS NOT NULL
         AND p.search_vector @@ websearch_to_tsquery('portuguese', unaccent(zt.search_term))
      ) AS db_fulltext_count,
      -- Verificar via SKU exato
      (SELECT COUNT(*)::int FROM public.products p
       WHERE p.is_active = true
         AND (p.is_deleted IS NULL OR p.is_deleted = false)
         AND (p.sku ILIKE zt.search_term OR p.sku_promo ILIKE zt.search_term)
      ) AS db_sku_exact_count
    FROM zero_terms zt
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'term',                  e.search_term,
      'searches',              e.total_buscas,
      'zero_result_searches',  e.zero_result_searches,
      'pct_zero',              e.pct_zero,
      'db_fulltext_results',   e.db_fulltext_count,
      'db_sku_results',        e.db_sku_exact_count,
      -- Diagnóstico: FALSO (produto existe mas busca não achou) vs REAL (ausência genuína)
      'diagnosis', CASE
        WHEN e.db_fulltext_count > 0 OR e.db_sku_exact_count > 0
          THEN 'false_zero'    -- Produto existe: bug de busca no frontend
        ELSE
          'true_gap'           -- Produto genuinamente ausente: oportunidade de catálogo
        END,
      'diagnosis_label', CASE
        WHEN e.db_fulltext_count > 0 OR e.db_sku_exact_count > 0
          THEN 'Produto existe no catálogo — verificar busca do frontend'
        ELSE
          'Produto ausente — oportunidade de cadastro'
        END
    )
    ORDER BY e.zero_result_searches DESC
  ) INTO v_result
  FROM enriched e;

  RETURN jsonb_build_object(
    'period_days',  p_days,
    'generated_at', NOW(),
    'items',        COALESCE(v_result, '[]'::jsonb)
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM, 'items', '[]'::jsonb);
END;
$function$;

GRANT EXECUTE ON FUNCTION public.fn_get_repressed_demand(uuid, integer, integer)
  TO authenticated, service_role;

-- Criar índice parcial para zero-results (acelera a query de demanda reprimida)
CREATE INDEX IF NOT EXISTS idx_search_analytics_zero_results_v2
  ON public.search_analytics(search_term, created_at DESC)
  WHERE results_count = 0 AND results_count != -1;
;

-- <<< END 20260612161137_fix_p2d_enriched_repressed_demand_with_catalog_diagnosis.sql <<<

-- >>> BEGIN 20260612161221_fix_p2d_repressed_demand_search_path_fix.sql >>>

-- Corrigir search_path para incluir extensions (onde unaccent está instalado)
CREATE OR REPLACE FUNCTION public.fn_get_repressed_demand(
  p_user_id uuid DEFAULT NULL,
  p_days    integer DEFAULT 30,
  p_limit   integer DEFAULT 20
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_since   timestamptz;
  v_result  jsonb;
BEGIN
  IF p_user_id IS NOT NULL
     AND p_user_id != auth.uid()
     AND NOT is_manager_or_admin()
  THEN
    RETURN jsonb_build_object('error','Acesso negado');
  END IF;

  p_days  := GREATEST(1, LEAST(COALESCE(p_days, 30), 999));
  p_limit := GREATEST(1, LEAST(COALESCE(p_limit, 20), 100));
  v_since := NOW() - (p_days || ' days')::interval;

  WITH zero_terms AS (
    SELECT
      search_term,
      COUNT(*) FILTER (WHERE results_count != -1)          AS total_buscas,
      SUM(CASE WHEN results_count = 0 THEN 1 ELSE 0 END)   AS zeros,
      ROUND(
        100.0 * SUM(CASE WHEN results_count = 0 THEN 1 ELSE 0 END)
        / NULLIF(COUNT(*) FILTER (WHERE results_count != -1), 0), 1
      ) AS pct_zero
    FROM public.search_analytics
    WHERE created_at >= v_since
    GROUP BY search_term
    HAVING SUM(CASE WHEN results_count = 0 THEN 1 ELSE 0 END) > 0
    ORDER BY SUM(CASE WHEN results_count = 0 THEN 1 ELSE 0 END) DESC
    LIMIT p_limit
  ),
  enriched AS (
    SELECT
      zt.search_term, zt.total_buscas,
      zt.zeros AS zero_result_searches, zt.pct_zero,
      (SELECT COUNT(*)::int FROM public.products p
       WHERE p.is_active = true
         AND (p.is_deleted IS NULL OR p.is_deleted = false)
         AND p.sale_price IS NOT NULL
         AND p.search_vector @@ websearch_to_tsquery('portuguese', unaccent(zt.search_term))
      ) AS db_fulltext_count,
      (SELECT COUNT(*)::int FROM public.products p
       WHERE p.is_active = true
         AND (p.is_deleted IS NULL OR p.is_deleted = false)
         AND (p.sku ILIKE zt.search_term OR p.sku_promo ILIKE zt.search_term)
      ) AS db_sku_exact_count
    FROM zero_terms zt
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'term',                 e.search_term,
      'searches',             e.total_buscas,
      'zero_result_searches', e.zero_result_searches,
      'pct_zero',             e.pct_zero,
      'db_fulltext_results',  e.db_fulltext_count,
      'db_sku_results',       e.db_sku_exact_count,
      'diagnosis', CASE
        WHEN e.db_fulltext_count > 0 OR e.db_sku_exact_count > 0 THEN 'false_zero'
        ELSE 'true_gap' END,
      'diagnosis_label', CASE
        WHEN e.db_fulltext_count > 0 OR e.db_sku_exact_count > 0
          THEN 'Produto existe no catálogo — verificar busca no frontend'
        ELSE 'Produto ausente — oportunidade de cadastro' END
    )
    ORDER BY e.zero_result_searches DESC
  ) INTO v_result
  FROM enriched e;

  RETURN jsonb_build_object(
    'period_days', p_days, 'generated_at', NOW(),
    'items', COALESCE(v_result, '[]'::jsonb)
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM, 'items', '[]'::jsonb);
END;
$function$;
;

