-- >>> BEGIN 20260613115945_fix_xbz_manual_reactivate_and_block_bypass.sql >>>

-- ═══════════════════════════════════════════════════════════════
-- PARTE 1: Reativar XBZ-MANUAL (produtos + variantes + VSS)
-- ═══════════════════════════════════════════════════════════════

-- 1a. Reativar VSS
UPDATE variant_supplier_sources vss
SET is_active = true, is_preferred = true, quantity = COALESCE(quantity, 0), updated_at = NOW()
FROM product_variants pv
JOIN products p ON p.id = pv.product_id
WHERE vss.variant_id = pv.id
  AND p.sku LIKE 'XBZ-MANUAL-%';

-- 1b. Reativar variantes
UPDATE product_variants pv
SET is_active = true, updated_at = NOW()
FROM products p
WHERE pv.product_id = p.id
  AND p.sku LIKE 'XBZ-MANUAL-%';

-- 1c. Reativar produtos (usando SET LOCAL para bypassar o block trigger)
-- SECURITY DEFINER + approved GUC para passar pelo trigger de bloqueio
DO $$
BEGIN
  -- Aprovar a reativação (é a operação inversa — ativar, não desativar)
  -- O trigger de bloqueio só é ativo para is_active TRUE → FALSE
  -- Reativação (FALSE → TRUE) não é bloqueada, mas active precisa acompanhar
  UPDATE products
  SET active = true, is_active = true, updated_at = NOW()
  WHERE sku LIKE 'XBZ-MANUAL-%'
    AND (active = false OR is_active = false);
END $$;

-- ═══════════════════════════════════════════════════════════════
-- PARTE 2: Corrigir fn_block_unauthorized_product_deactivation
-- para também bloquear active=false (o bypass vector)
-- ═══════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_block_unauthorized_product_deactivation()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_approved   text := COALESCE(current_setting('app.deactivation_approved', true), 'false');
  v_src        text := COALESCE(current_setting('app.write_source', true), 'ui');
  v_auth_row   _deactivation_auth%ROWTYPE;
BEGIN
  -- ── Proteção para INSERT: produto não pode nascer inativo
  IF TG_OP = 'INSERT' AND (NEW.is_active = false OR NEW.active = false) THEN
    IF v_approved <> 'true' THEN
      NEW.is_active := true;
      NEW.active    := true;
      RAISE NOTICE '[DEACTIVATION BLOCKED INSERT] Produto % criado como ativo.',
        COALESCE(NEW.supplier_reference, NEW.sku, 'sem-ref');
    END IF;
    RETURN NEW;
  END IF;

  -- ── Proteção para UPDATE: ativo → inativo via is_active OU via active
  IF TG_OP = 'UPDATE' AND (
    (OLD.is_active = true AND NEW.is_active = false) OR
    (OLD.active    = true AND NEW.active    = false)
  ) THEN
    -- Verificar via GUC
    IF v_approved = 'true' THEN
      PERFORM set_config('app.deactivation_approved', 'false', false);
      RAISE NOTICE '[DEACTIVATION ALLOWED] Produto % desativado (src=%)',
        COALESCE(NEW.supplier_reference, NEW.sku), v_src;
      RETURN NEW;
    END IF;

    -- Verificar via tabela _deactivation_auth
    SELECT * INTO v_auth_row
    FROM _deactivation_auth
    WHERE product_id = OLD.id
      AND used = false
      AND expires_at > now()
    LIMIT 1;

    IF v_auth_row.id IS NOT NULL THEN
      UPDATE _deactivation_auth SET used=true WHERE id=v_auth_row.id;
      RAISE NOTICE '[DEACTIVATION ALLOWED via AUTH TABLE] Produto % (request=%)',
        COALESCE(NEW.supplier_reference, NEW.sku), v_auth_row.request_id;
      RETURN NEW;
    END IF;

    -- BLOQUEAR — reverter AMBOS os campos
    NEW.is_active := OLD.is_active;
    NEW.active    := OLD.active;
    RAISE NOTICE '[DEACTIVATION BLOCKED] Produto % requer aprovação (campo: %)',
      COALESCE(NEW.supplier_reference, 'sem-ref'),
      CASE WHEN OLD.is_active = true AND NEW.is_active = false THEN 'is_active'
           ELSE 'active' END;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;

-- ═══════════════════════════════════════════════════════════════
-- PARTE 3: Adicionar reativação automática ao fantasmas-deactivate-guard
-- (proteção de emergência periódica)
-- ═══════════════════════════════════════════════════════════════

SELECT cron.alter_job(
  job_id := (SELECT jobid FROM cron.job WHERE jobname = 'fantasmas-deactivate-guard'),
  command := $cmd$
  -- Guard 1: fantasmas (sem supplier_reference e sku)
  UPDATE products
  SET is_active = false, updated_at = now()
  WHERE is_active = true
    AND supplier_reference IS NULL
    AND sku IS NULL
    AND supplier_id IS NOT NULL;

  -- Guard 2: produtos com 'active' em locked_fields devem ter active=false E is_active=false
  UPDATE products
  SET active = false, is_active = false, updated_at = now()
  WHERE 'active' = ANY(COALESCE(locked_fields, '{}'))
    AND (active = true OR is_active = true);

  -- Guard 3 (NOVO): reativar XBZ-MANUAL que foram incorretamente desativados por bypass do trigger
  UPDATE products SET active = true, is_active = true, updated_at = now()
  WHERE sku LIKE 'XBZ-MANUAL-%' AND (active = false OR is_active = false);
  $cmd$
);
;

-- <<< END 20260613115945_fix_xbz_manual_reactivate_and_block_bypass.sql <<<

-- >>> BEGIN 20260613122207_bug3_revoke_public_anon_novelty_functions_2026_06_13.sql >>>

-- BUG 3 FIX: REVOKE acesso anon/PUBLIC das 4 funções novas de novelties
-- Auditoria detectou: anon pode chamar funções de modificação de dados → RISCO CRÍTICO
-- Essas funções são chamadas APENAS por pg_cron (service_role) ou triggers internos

-- 1. fn_reactivate_valid_novelties — modifica product_novelties + products
--    Tinha: {postgres=X, anon=X, authenticated=X, service_role=X}
--    Deve:  {postgres=X, service_role=X}
REVOKE EXECUTE ON FUNCTION public.fn_reactivate_valid_novelties()
  FROM PUBLIC, anon, authenticated;

-- 2. fn_expire_novelties — modifica product_novelties + products (is_active=false)
--    Tinha: {=X (PUBLIC), postgres=X, anon=X, authenticated=X, service_role=X}
--    Deve:  {postgres=X, service_role=X}
REVOKE EXECUTE ON FUNCTION public.fn_expire_novelties()
  FROM PUBLIC, anon, authenticated;

-- 3. fn_pn_sync_products_is_new — trigger SECURITY DEFINER, nunca chamada por usuário
--    Tinha: {=X (PUBLIC), ...}
--    Deve:  {postgres=X, service_role=X}
REVOKE EXECUTE ON FUNCTION public.fn_pn_sync_products_is_new()
  FROM PUBLIC, anon, authenticated;

-- 4. fn_sync_is_new_expires_at — sincroniza campo is_new_expires_at nos products
--    Tinha: {=X (PUBLIC), ...}
--    Deve:  {postgres=X, service_role=X}
REVOKE EXECUTE ON FUNCTION public.fn_sync_is_new_expires_at()
  FROM PUBLIC, anon, authenticated;

-- Guard: garantir service_role mantém acesso em todos
GRANT EXECUTE ON FUNCTION public.fn_reactivate_valid_novelties() TO service_role;
GRANT EXECUTE ON FUNCTION public.fn_expire_novelties() TO service_role;
GRANT EXECUTE ON FUNCTION public.fn_pn_sync_products_is_new() TO service_role;
GRANT EXECUTE ON FUNCTION public.fn_sync_is_new_expires_at() TO service_role;
;

-- <<< END 20260613122207_bug3_revoke_public_anon_novelty_functions_2026_06_13.sql <<<

-- >>> BEGIN 20260613123219_fn_reactivate_valid_novelties_v6_frente5_is_new_expires_at_cleanup.sql >>>

CREATE OR REPLACE FUNCTION public.fn_reactivate_valid_novelties()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
/*
  v6_2026-06-13 — Quadrupla proteção:
  1. DISTINCT ON + NOT EXISTS active (v4)
  2. Hard block: migration_from_supplier NUNCA reativa (source denylist)
  3. Sincroniza is_new_expires_at ao setar is_new=true (M3)
  4. [NOVO] Frente 5: limpa is_new_expires_at/novelty_expires_at órfão
     quando is_new=false mas is_new_expires_at ainda preenchido (gap detectado em 2026-06-13)
*/
DECLARE
  v_novelties_fixed      int := 0;
  v_products_fixed       int := 0;
  v_orphans_fixed        int := 0;
  v_expires_at_cleaned   int := 0;
BEGIN
  -- Frente 1: reativar APENAS produtos SEM novelty ativa, 1 por produto (DISTINCT ON)
  -- v6: quadrupla proteção
  WITH candidates AS (
    SELECT DISTINCT ON (pn.product_id) pn.id
    FROM product_novelties pn
    JOIN products p ON pn.product_id = p.id
    WHERE p.is_active    = true
      AND p.is_stockout  = false
      AND pn.is_active   = false
      AND pn.expires_at  IS NOT NULL
      AND pn.expires_at  > now()
      -- BLOQUEIO ABSOLUTO: migration_from_supplier nunca volta a ativo
      AND pn.source      != 'migration_from_supplier'
      -- CRÍTICO v4: só produtos SEM nenhuma novelty ativa
      AND NOT EXISTS (
        SELECT 1 FROM product_novelties pn_active
        WHERE pn_active.product_id = pn.product_id
          AND pn_active.is_active  = true
      )
    ORDER BY pn.product_id, pn.expires_at DESC
  ),
  fixed AS (
    UPDATE product_novelties pn
    SET is_active = true, updated_at = clock_timestamp()
    WHERE pn.id IN (SELECT id FROM candidates)
    RETURNING pn.product_id
  )
  SELECT COUNT(*) INTO v_novelties_fixed FROM fixed;

  -- Frente 2: desativar novelties de produtos INATIVOS
  WITH deact AS (
    UPDATE product_novelties pn
    SET is_active = false, updated_at = clock_timestamp()
    FROM products p
    WHERE pn.product_id = p.id AND p.is_active = false AND pn.is_active = true
    RETURNING pn.product_id
  ) SELECT COUNT(*) INTO v_orphans_fixed FROM deact;

  -- Frente 2b: desativar novelties de produtos STOCKOUT
  UPDATE product_novelties pn
  SET is_active = false, updated_at = clock_timestamp()
  FROM products p
  WHERE pn.product_id = p.id AND p.is_active = true
    AND p.is_stockout = true AND pn.is_active = true;

  -- Frente 3: sincronizar products.is_new + is_new_expires_at (M3)
  UPDATE products p
  SET is_new = true,
      novelty_detected_at = pn.detected_at,
      novelty_expires_at  = pn.expires_at,
      is_new_expires_at   = pn.expires_at,
      updated_at = now()
  FROM product_novelties pn
  WHERE pn.product_id = p.id AND pn.is_active = true
    AND p.is_active = true AND p.is_stockout = false AND p.is_new = false;
  GET DIAGNOSTICS v_products_fixed = ROW_COUNT;

  -- Frente 4: limpar is_new=true órfão + todos os campos de novelty
  UPDATE products SET
    is_new              = false,
    novelty_detected_at = NULL,
    novelty_expires_at  = NULL,
    is_new_expires_at   = NULL,
    updated_at          = now()
  WHERE is_new = true
    AND NOT EXISTS (SELECT 1 FROM product_novelties pn
      WHERE pn.product_id = products.id AND pn.is_active = true);

  -- Frente 5 [v6 — gap fix 2026-06-13]:
  -- Limpar is_new_expires_at/novelty_expires_at residuais quando:
  -- is_new = false (já limpo) mas is_new_expires_at ainda preenchido
  -- Cenário: produto foi novo → foi para stockout (Frente 2b desativou novelty)
  -- → algo externo setou is_new=false (trigger, gold promote) mas não limpou expires_at
  UPDATE products SET
    is_new_expires_at   = NULL,
    novelty_expires_at  = NULL,
    updated_at          = now()
  WHERE is_new = false
    AND is_new_expires_at IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM product_novelties pn
      WHERE pn.product_id = products.id AND pn.is_active = true);
  GET DIAGNOSTICS v_expires_at_cleaned = ROW_COUNT;

  RETURN jsonb_build_object(
    'novelties_reactivated',         v_novelties_fixed,
    'inactive_products_deactivated', v_orphans_fixed,
    'products_synced',               v_products_fixed,
    'expires_at_residuals_cleaned',  v_expires_at_cleaned,
    'version',                       'v6_2026-06-13_frente5_gap_fix',
    'ran_at',                        now()
  );
END;
$function$;

REVOKE ALL ON FUNCTION public.fn_reactivate_valid_novelties() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_reactivate_valid_novelties() TO service_role;
;

-- <<< END 20260613123219_fn_reactivate_valid_novelties_v6_frente5_is_new_expires_at_cleanup.sql <<<

-- >>> BEGIN 20260613180000_reconcile_ai_enrichment_queue_drift.sql >>>
-- ============================================================================
-- Reconciliacao de drift de schema (audit 200-commits, P0-2) — 2026-06-13
-- ----------------------------------------------------------------------------
-- A tabela public.ai_enrichment_queue (fila ATIVA de enriquecimento por IA, com
-- ~7,1k linhas em prod) e a view public.vw_ai_enrichment_status EXISTEM no banco
-- canonico (doufsxqlfjyuvxuezpln) porem NAO possuiam migration correspondente no
-- repositorio — drift detectado na auditoria dos ultimos 200 commits.
--
-- Esta migration RECONCILIA o repo com o estado vivo. E 100% IDEMPOTENTE
-- (IF NOT EXISTS / DO-guard / CREATE OR REPLACE / DROP POLICY IF EXISTS):
-- aplicar em producao e NO-OP; o objetivo e que um rebuild limpo a partir das
-- migrations recrie estes objetos IDENTICOS ao que ja roda em prod.
--
-- DDL extraido do catalogo vivo (pg_get_constraintdef / pg_indexes / pg_policies
-- / pg_get_viewdef) em 2026-06-13. Sem alteracao de seguranca: reproduz a unica
-- policy (SELECT org-scoped p/ authenticated) e o acesso de escrita via
-- service_role (que bypassa RLS) exatamente como estao no banco.
-- ============================================================================

-- 1) Tabela --------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.ai_enrichment_queue (
  id               uuid        NOT NULL DEFAULT gen_random_uuid(),
  product_id       uuid        NOT NULL,
  enrichment_type  text        NOT NULL,
  status           text        NOT NULL DEFAULT 'pending'::text,
  priority         integer              DEFAULT 5,
  attempts         integer              DEFAULT 0,
  max_attempts     integer              DEFAULT 3,
  last_error       text,
  last_attempt_at  timestamptz,
  created_at       timestamptz          DEFAULT now(),
  updated_at       timestamptz          DEFAULT now(),
  completed_at     timestamptz,
  locked_at        timestamptz,
  locked_by        text,
  organization_id  uuid                 DEFAULT '5db5aee1-064b-4ef4-9193-345dcd8274ea'::uuid
);

-- 2) Constraints (idempotentes) ------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ai_enrichment_queue_pkey' AND conrelid='public.ai_enrichment_queue'::regclass) THEN
    ALTER TABLE public.ai_enrichment_queue ADD CONSTRAINT ai_enrichment_queue_pkey PRIMARY KEY (id);
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ai_enrichment_queue_product_id_fkey' AND conrelid='public.ai_enrichment_queue'::regclass) THEN
    ALTER TABLE public.ai_enrichment_queue ADD CONSTRAINT ai_enrichment_queue_product_id_fkey
      FOREIGN KEY (product_id) REFERENCES public.products(id) ON DELETE CASCADE;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='chk_enrichment_type' AND conrelid='public.ai_enrichment_queue'::regclass) THEN
    ALTER TABLE public.ai_enrichment_queue ADD CONSTRAINT chk_enrichment_type
      CHECK (enrichment_type = ANY (ARRAY['ai_title'::text,'ai_summary'::text,'schema_json'::text,'all'::text]));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='chk_status' AND conrelid='public.ai_enrichment_queue'::regclass) THEN
    ALTER TABLE public.ai_enrichment_queue ADD CONSTRAINT chk_status
      CHECK (status = ANY (ARRAY['pending'::text,'processing'::text,'done'::text,'error'::text,'skipped'::text]));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='uq_product_enrichment_type' AND conrelid='public.ai_enrichment_queue'::regclass) THEN
    ALTER TABLE public.ai_enrichment_queue ADD CONSTRAINT uq_product_enrichment_type UNIQUE (product_id, enrichment_type);
  END IF;
END $$;

-- 3) Indexes (os 2 unique acima ja criam seus indices; aqui so os demais) ------
CREATE INDEX IF NOT EXISTS idx_ai_queue_pending    ON public.ai_enrichment_queue USING btree (priority, created_at) WHERE (status = 'pending'::text);
CREATE INDEX IF NOT EXISTS idx_ai_queue_product_id ON public.ai_enrichment_queue USING btree (product_id);
CREATE INDEX IF NOT EXISTS idx_ai_queue_status     ON public.ai_enrichment_queue USING btree (status, updated_at);

-- 4) RLS + policy (reproduz exatamente o estado vivo) --------------------------
ALTER TABLE public.ai_enrichment_queue ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS authenticated_read_own_org_queue ON public.ai_enrichment_queue;
CREATE POLICY authenticated_read_own_org_queue
  ON public.ai_enrichment_queue
  FOR SELECT
  TO authenticated
  USING (organization_id = '5db5aee1-064b-4ef4-9193-345dcd8274ea'::uuid);

-- 5) Grants (writer = service_role, bypassa RLS) -------------------------------
GRANT ALL ON public.ai_enrichment_queue TO service_role;

-- 6) View de monitoramento (depende de ai_enrichment_queue + products.ai_*) ----
CREATE OR REPLACE VIEW public.vw_ai_enrichment_status AS
 WITH queue_stats AS (
         SELECT ai_enrichment_queue.enrichment_type,
            count(*) FILTER (WHERE ai_enrichment_queue.status = 'pending'::text) AS pending,
            count(*) FILTER (WHERE ai_enrichment_queue.status = 'processing'::text) AS processing,
            count(*) FILTER (WHERE ai_enrichment_queue.status = 'done'::text) AS done,
            count(*) FILTER (WHERE ai_enrichment_queue.status = 'error'::text) AS errors,
            count(*) FILTER (WHERE ai_enrichment_queue.status = 'skipped'::text) AS skipped,
            count(*) AS total,
            max(ai_enrichment_queue.completed_at) AS last_completed_at
           FROM ai_enrichment_queue
          GROUP BY ai_enrichment_queue.enrichment_type
        ), product_coverage AS (
         SELECT count(*) FILTER (WHERE products.ai_title IS NOT NULL AND length(TRIM(BOTH FROM products.ai_title)) > 0) AS has_ai_title,
            count(*) FILTER (WHERE products.ai_summary IS NOT NULL AND length(TRIM(BOTH FROM products.ai_summary)) > 0) AS has_ai_summary,
            count(*) FILTER (WHERE products.schema_json IS NOT NULL) AS has_schema_json,
            count(*) AS total
           FROM products
          WHERE products.is_active = true AND products.is_deleted = false
        )
 SELECT q.enrichment_type,
    q.pending,
    q.processing,
    q.done,
    q.errors,
    q.total AS total_queued,
    q.last_completed_at,
        CASE q.enrichment_type
            WHEN 'ai_title'::text THEN pc.has_ai_title
            WHEN 'ai_summary'::text THEN pc.has_ai_summary
            WHEN 'schema_json'::text THEN pc.has_schema_json
            ELSE NULL::bigint
        END AS products_with_field,
    pc.total AS total_products,
    round(
        CASE q.enrichment_type
            WHEN 'ai_title'::text THEN pc.has_ai_title::numeric * 100.0 / NULLIF(pc.total, 0)::numeric
            WHEN 'ai_summary'::text THEN pc.has_ai_summary::numeric * 100.0 / NULLIF(pc.total, 0)::numeric
            WHEN 'schema_json'::text THEN pc.has_schema_json::numeric * 100.0 / NULLIF(pc.total, 0)::numeric
            ELSE NULL::numeric
        END, 1) AS pct_coverage
   FROM queue_stats q
     CROSS JOIN product_coverage pc
  ORDER BY q.enrichment_type;

-- <<< END 20260613180000_reconcile_ai_enrichment_queue_drift.sql <<<

-- >>> BEGIN 20260613181344_doc_public_mv_exposure_views_and_refresh_fns.sql >>>

-- G1/G2 residue (SAFE, metadata-only): document that public.mv_* are EXPOSURE VIEWS
-- over real materialized views living in schema analytics, refreshed hourly by cron job 47.
-- Goal: remove the "naming trap" (prefix mv_ on a plain public VIEW) for future maintainers.

COMMENT ON VIEW public.mv_product_cards IS
  'VIEW pública de exposição (PostgREST só enxerga public). Dados materializados em analytics.mv_product_cards (matview real, índice único, refresh CONCURRENTLY). Atualizada de hora em hora pelo cron job 47 "refresh-all-materialized-views" (30 * * * *). Apesar do prefixo mv_, ESTE objeto em public é uma VIEW comum — NUNCA rode REFRESH MATERIALIZED VIEW aqui (rode em analytics.*). Defasagem máx vs products ~1h.';

COMMENT ON VIEW public.mv_product_compositions IS
  'VIEW pública de exposição sobre a matview analytics.mv_product_compositions (refresh CONCURRENTLY via cron 47, hourly). public.mv_* é VIEW, não matview — não rode REFRESH aqui.';

COMMENT ON VIEW public.mv_product_intelligence IS
  'VIEW pública de exposição sobre a matview analytics.mv_product_intelligence (depende de mv_stock_velocity; refresh via cron 47, hourly). public.mv_* é VIEW, não matview.';

COMMENT ON VIEW public.mv_stock_velocity IS
  'VIEW pública de exposição sobre a matview analytics.mv_stock_velocity (refresh CONCURRENTLY via cron 47, hourly). public.mv_* é VIEW, não matview.';

COMMENT ON VIEW public.mv_material_group_stats IS
  'VIEW pública de exposição sobre a matview analytics.mv_material_group_stats (refresh CONCURRENTLY via cron 47, hourly). public.mv_* é VIEW, não matview.';

COMMENT ON VIEW public.mv_media_health IS
  'VIEW pública de exposição sobre a matview analytics.mv_media_health (refresh CONCURRENTLY via cron 47, hourly). public.mv_* é VIEW, não matview.';

COMMENT ON FUNCTION public.refresh_all_materialized_views() IS
  'CORRETA E EM USO (cron job 47, 30 * * * *). Atualiza as 7 matviews REAIS em analytics: CONCURRENTLY nas 6 com índice único; REFRESH plain em analytics.categories_tree_visual (sem índice único). NÃO é bug — os objetos analytics.mv_* são matviews de fato.';

COMMENT ON FUNCTION public.refresh_materialized_views() IS
  'Atualiza analytics.mv_material_group_stats e analytics.mv_product_compositions (CONCURRENTLY). Alvos são matviews REAIS no schema analytics — função correta.';

COMMENT ON FUNCTION public.fn_refresh_media_health() IS
  'Atualiza analytics.mv_media_health (CONCURRENTLY). Alvo é matview REAL no schema analytics — função correta.';
;

-- <<< END 20260613181344_doc_public_mv_exposure_views_and_refresh_fns.sql <<<

-- >>> BEGIN 20260613181545_add_fn_assert_public_contract_guard.sql >>>

-- Guarda permanente do contrato público Gold↔front (somente-leitura, additiva, idempotente).
-- Re-executável a qualquer momento; ideal para smoke test / cron de saúde.
CREATE OR REPLACE FUNCTION public.fn_assert_public_contract()
RETURNS TABLE(check_name text, status text, detail text)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, analytics
AS $$
  WITH base AS (
    SELECT
      (SELECT count(*) FROM products WHERE is_active AND is_deleted IS NOT TRUE)                                   AS prod_visible,
      (SELECT count(*) FROM v_products_public)                                                                     AS vpp,
      (SELECT count(*) FROM mv_product_cards)                                                                      AS cards,
      (SELECT count(*) FROM v_products_public WHERE cost_price IS NOT NULL)                                        AS cost_leak,
      (SELECT count(*) FROM v_products_public WHERE suggested_price IS NOT NULL)                                   AS sugg_leak,
      (SELECT count(*) FROM products p WHERE p.is_active AND p.is_deleted IS NOT TRUE
         AND NOT EXISTS (SELECT 1 FROM v_products_min_price m WHERE m.product_id=p.id))                            AS no_minprice,
      (SELECT count(*) FROM product_variants pv WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.id=pv.product_id)) AS orphan_var,
      (SELECT count(*) FROM product_images pi WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.id=pi.product_id))   AS orphan_img,
      (SELECT count(*) FROM pg_matviews WHERE schemaname='analytics' AND NOT ispopulated)                          AS mv_unpop,
      has_column_privilege('anon','public.products','cost_price','SELECT')                                         AS anon_cost,
      has_table_privilege('anon','public.v_products_public','SELECT')                                              AS anon_vpp
  )
  SELECT 'P0_cost_price_nao_vaza',        CASE WHEN cost_leak=0 THEN 'PASS' ELSE 'FAIL' END, 'linhas_com_custo='||cost_leak FROM base
  UNION ALL SELECT 'P0_suggested_nao_vaza', CASE WHEN sugg_leak=0 THEN 'PASS' ELSE 'FAIL' END, 'linhas='||sugg_leak FROM base
  UNION ALL SELECT 'paridade_vpp_vs_ativos', CASE WHEN vpp=prod_visible THEN 'PASS' ELSE 'FAIL' END, vpp||' vs '||prod_visible FROM base
  UNION ALL SELECT 'paridade_cards_vs_vpp',  CASE WHEN cards=vpp THEN 'PASS' ELSE 'WARN' END, cards||' vs '||vpp||' (cards=matview refresh horario, ate ~1h)' FROM base
  UNION ALL SELECT 'todo_visivel_tem_preco',  CASE WHEN no_minprice=0 THEN 'PASS' ELSE 'WARN' END, 'sem_preco='||no_minprice FROM base
  UNION ALL SELECT 'zero_variantes_orfas',    CASE WHEN orphan_var=0 THEN 'PASS' ELSE 'FAIL' END, 'orfas='||orphan_var FROM base
  UNION ALL SELECT 'zero_imagens_orfas',      CASE WHEN orphan_img=0 THEN 'PASS' ELSE 'FAIL' END, 'orfas='||orphan_img FROM base
  UNION ALL SELECT 'matviews_populadas',      CASE WHEN mv_unpop=0 THEN 'PASS' ELSE 'FAIL' END, 'nao_populadas='||mv_unpop FROM base
  UNION ALL SELECT 'anon_SEM_grant_custo',    CASE WHEN anon_cost=false THEN 'PASS' ELSE 'FAIL' END, 'anon_grant_cost='||anon_cost FROM base
  UNION ALL SELECT 'anon_LE_view_publica',    CASE WHEN anon_vpp THEN 'PASS' ELSE 'FAIL' END, 'anon_grant_vpp='||anon_vpp FROM base;
$$;

REVOKE ALL ON FUNCTION public.fn_assert_public_contract() FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_assert_public_contract() TO service_role;
COMMENT ON FUNCTION public.fn_assert_public_contract() IS
  'Guarda do contrato público Gold↔front (somente-leitura). Re-execute para validar: 0 vazamento de custo, paridade products↔v_products_public↔mv_product_cards, todo produto visível com preço, 0 órfãos, matviews populadas, anon sem grant de custo. Criada na auditoria 2026-06-13.';
;

-- <<< END 20260613181545_add_fn_assert_public_contract_guard.sql <<<

-- >>> BEGIN 20260613190000_medallion_front_v3_public_views_goldhygiene2.sql >>>
-- ============================================================================
-- Migration: 20260611170000_medallion_front_v3_tags_techniques_nuances_kitprintareas_goldhygiene2
-- Contexto : Integração FRONT ↔ Medallion (Bronze→Prata→Ouro), rodada v3.
--            Continuação de 20260611160000 (v2). SSOT doufsxqlfjyuvxuezpln.
-- Idempotente: CREATE OR REPLACE / REVOKE / loop to_regclass.
--
-- O que esta migração versiona (já aplicada ao vivo — suíte anon 31/31):
--   F6  CORREÇÃO DE BUG: v_tags_public + v_product_tags_public.
--       A policy de SELECT de tags/product_tags chama user_belongs_to_org(),
--       função SEM grant EXECUTE p/ anon → QUALQUER página que carregasse tags
--       quebrava com erro 42501 (não degradava vazio: estourava exceção).
--       49.442 vínculos tag↔produto destravados.
--   F7  3 views p/ tabelas RLS-vazio que a UI consome:
--       v_personalization_techniques_public (11 técnicas de gravação),
--       v_color_nuances_public (7 acabamentos),
--       v_kit_component_print_areas_public (1.018 áreas de impressão de kit).
--   F8  Higiene Gold round 2: revoga escrita anon órfã em +10 tabelas de
--       referência/catálogo (bases das views novas). RLS já bloqueava.
--
-- Projeções omitem deliberadamente campos internos:
--   tags/color_nuances → organization_id, bitrix_id
--   personalization_techniques → prompt_suffix (IA), base_cost_multiplier (custo)
--   kit_component_print_areas → tabela_preco_id (liga a custo de gravação)
-- ============================================================================

BEGIN;

-- ----------------------------------------------------------------------------
-- F6.a — v_tags_public (labels de vitrine: "Mais Vendido", "Biodegradável"…)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_tags_public AS
SELECT t.id,
       t.name,
       t.slug,
       t.color_hex,
       t.description,
       t.usage_count
FROM public.tags t
WHERE t.is_active = true;
ALTER VIEW public.v_tags_public SET (security_invoker = false);
GRANT SELECT ON public.v_tags_public TO anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- F6.b — v_product_tags_public (ponte produto↔tag; só produto ativo + tag ativa)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_product_tags_public AS
SELECT pt.id,
       pt.product_id,
       pt.tag_id
FROM public.product_tags pt
JOIN public.products p ON p.id = pt.product_id
   AND p.is_active = true AND p.is_deleted IS NOT TRUE
JOIN public.tags t ON t.id = pt.tag_id AND t.is_active = true;
ALTER VIEW public.v_product_tags_public SET (security_invoker = false);
GRANT SELECT ON public.v_product_tags_public TO anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- F7.a — v_personalization_techniques_public (Bordado, Silk, Laser, DTF…)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_personalization_techniques_public AS
SELECT pt.id,
       pt.name,
       pt.code,
       pt.description,
       pt.requires_color_count
FROM public.personalization_techniques pt
WHERE pt.is_active = true;
ALTER VIEW public.v_personalization_techniques_public SET (security_invoker = false);
GRANT SELECT ON public.v_personalization_techniques_public TO anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- F7.b — v_color_nuances_public (Fosco, Metalizado, Perolizado, Neon…)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_color_nuances_public AS
SELECT cn.id,
       cn.name,
       cn.slug,
       cn.description,
       cn.sort_order
FROM public.color_nuances cn
WHERE cn.is_active = true;
ALTER VIEW public.v_color_nuances_public SET (security_invoker = false);
GRANT SELECT ON public.v_color_nuances_public TO anon, authenticated, service_role;

-- ----------------------------------------------------------------------------
-- F7.c — v_kit_component_print_areas_public (áreas de impressão de kits ativos)
-- ----------------------------------------------------------------------------
CREATE OR REPLACE VIEW public.v_kit_component_print_areas_public AS
SELECT kpa.id,
       kpa.kit_component_id,
       kpa.location_code,
       kpa.location_name,
       kpa.location_order,
       kpa.max_width,
       kpa.max_height,
       kpa.shape,
       kpa.is_curved,
       kpa.technique_order
FROM public.kit_component_print_areas kpa
JOIN public.product_kit_components pkc ON pkc.id = kpa.kit_component_id
JOIN public.products p ON p.id = pkc.kit_product_id
   AND p.is_active = true AND p.is_deleted IS NOT TRUE
WHERE kpa.is_active = true;
ALTER VIEW public.v_kit_component_print_areas_public SET (security_invoker = false);
GRANT SELECT ON public.v_kit_component_print_areas_public TO anon, authenticated, service_role;

COMMIT;

-- ----------------------------------------------------------------------------
-- F8 — Higiene Gold round 2 (FORA de transação). Remove escrita anon órfã em
-- +10 tabelas de referência/catálogo. RLS já bloqueia (condições auth.uid()/
-- is_admin_or_above, falsas p/ anon). SELECT preservado.
-- ----------------------------------------------------------------------------
DO $$
DECLARE
  t text;
  alvos text[] := ARRAY[
    'tags','product_tags','personalization_techniques','color_nuances','kit_component_print_areas',
    'kit_component_types','kit_variants','supplier_colors','supplier_branches','supplier_property_mappings',
    'product_groups','product_group_members'
  ];
BEGIN
  FOREACH t IN ARRAY alvos LOOP
    IF to_regclass('public.'||t) IS NOT NULL THEN
      EXECUTE format(
        'REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.%I FROM anon', t);
    END IF;
  END LOOP;
END $$;

