-- >>> BEGIN 20260614121400_fix_fn_sync_derived_product_flags_v2_auto_reset.sql >>>

-- ============================================================
-- FIX P0-B: fn_sync_derived_product_flags v2
-- MUDANÇAS vs v1:
--   1. Adicionado bloco de AUTO-RESET: is_on_sale=FALSE quando estoque volta
--   2. O reset respeita is_on_sale_expires_at (promoções manuais protegidas)
--   3. Inclui produtos inativos no reset (limpeza geral)
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_sync_derived_product_flags()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_on_sale_set      integer := 0;
  v_on_sale_cleared  integer := 0;   -- reset quando estoque volta
  v_on_sale_expired  integer := 0;   -- limpeza por expires_at
  v_new_expired      integer := 0;
  v_featured_exp     integer := 0;
  v_bestseller_exp   integer := 0;
BEGIN

  -- ── AUTO-RESET is_on_sale quando estoque voltou ───────────────────
  -- Limpa produtos que tinham is_on_sale=TRUE por stockout mas agora
  -- têm estoque (is_stockout=FALSE). Não toca produtos com expires_at
  -- manual (promoções legítimas definidas pelo time).
  UPDATE products
  SET is_on_sale = false, updated_at = now()
  WHERE is_on_sale  = true
    AND is_stockout = false
    AND is_on_sale_expires_at IS NULL;
  GET DIAGNOSTICS v_on_sale_cleared = ROW_COUNT;

  -- ── ATIVAR is_on_sale por stockout ───────────────────────────────
  -- Ativa SOMENTE para produtos ativos sem estoque que ainda não estão
  -- marcados como on_sale (e sem expires_at manual).
  UPDATE products
  SET is_on_sale = true, updated_at = now()
  WHERE is_active   = true
    AND is_stockout = true
    AND is_on_sale  = false
    AND is_on_sale_expires_at IS NULL;
  GET DIAGNOSTICS v_on_sale_set = ROW_COUNT;

  -- ── EXPIRAR is_on_sale por expires_at ────────────────────────────
  UPDATE products
  SET is_on_sale = false, updated_at = now()
  WHERE is_on_sale = true
    AND is_on_sale_expires_at IS NOT NULL
    AND is_on_sale_expires_at < now();
  GET DIAGNOSTICS v_on_sale_expired = ROW_COUNT;

  -- ── EXPIRAR is_new ────────────────────────────────────────────────
  UPDATE products
  SET is_new = false, updated_at = now()
  WHERE is_new = true
    AND is_new_expires_at IS NOT NULL
    AND is_new_expires_at < now();
  GET DIAGNOSTICS v_new_expired = ROW_COUNT;

  -- ── EXPIRAR is_featured ───────────────────────────────────────────
  UPDATE products
  SET is_featured = false, updated_at = now()
  WHERE is_featured = true
    AND is_featured_expires_at IS NOT NULL
    AND is_featured_expires_at < now();
  GET DIAGNOSTICS v_featured_exp = ROW_COUNT;

  -- ── EXPIRAR is_bestseller ─────────────────────────────────────────
  UPDATE products
  SET is_bestseller = false, updated_at = now()
  WHERE is_bestseller = true
    AND is_bestseller_expires_at IS NOT NULL
    AND is_bestseller_expires_at < now();
  GET DIAGNOSTICS v_bestseller_exp = ROW_COUNT;

  RETURN jsonb_build_object(
    'version',            'v2_2026-06-14_auto_reset',
    'is_on_sale_cleared', v_on_sale_cleared,
    'is_on_sale_set',     v_on_sale_set,
    'is_on_sale_expired', v_on_sale_expired,
    'is_new_expired',     v_new_expired,
    'is_featured_expired',   v_featured_exp,
    'is_bestseller_expired', v_bestseller_exp
  );
END;
$$;
;

-- <<< END 20260614121400_fix_fn_sync_derived_product_flags_v2_auto_reset.sql <<<

-- >>> BEGIN 20260614121444_fix_fn_trigger_set_has_gift_box_v2_repacking_coverage.sql >>>

-- ============================================================
-- FIX P1-A: fn_trigger_set_has_gift_box v2
-- MUDANÇA vs v1: cobre repacking_classification='commercial'
-- (os 8 produtos Spot tinham repacking='commercial' mas
--  packing_classification=NULL → gift_box ficava FALSE)
-- Nova regra: has_gift_box=TRUE se QUALQUER classificação=commercial
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_trigger_set_has_gift_box()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.packing_classification = 'commercial'
     OR NEW.repacking_classification = 'commercial'
  THEN
    NEW.has_gift_box             := TRUE;
    NEW.has_commercial_packaging := TRUE;
  ELSE
    NEW.has_gift_box             := FALSE;
    NEW.has_commercial_packaging := FALSE;
  END IF;
  RETURN NEW;
END;
$$;
;

-- <<< END 20260614121444_fix_fn_trigger_set_has_gift_box_v2_repacking_coverage.sql <<<

-- >>> BEGIN 20260614121516_create_view_v_product_active_badge.sql >>>

-- ============================================================
-- FIX P1-B: VIEW v_product_active_badge
-- Hierarquia canônica de badge por produto:
--   1. stockout   — produto indisponível (prioridade máxima)
--   2. new        — novidade (30 dias)
--   3. bestseller — mais vendido
--   4. featured   — destaque curado
--   5. on_sale    — promoção
--   6. gift_box   — embalagem comercial
--   7. none       — sem badge
-- Uso: SELECT * FROM v_product_active_badge WHERE product_id = $1
-- ============================================================
DROP VIEW IF EXISTS public.v_product_active_badge;

CREATE VIEW public.v_product_active_badge AS
SELECT
  p.id                AS product_id,
  p.sku,
  p.name,
  p.is_active,
  p.is_stockout,
  p.is_new,
  p.is_bestseller,
  p.is_featured,
  p.is_on_sale,
  p.has_gift_box,
  -- Badge canônica (prioridade definida aqui, não no frontend)
  CASE
    WHEN p.is_stockout   THEN 'stockout'
    WHEN p.is_new        THEN 'new'
    WHEN p.is_bestseller THEN 'bestseller'
    WHEN p.is_featured   THEN 'featured'
    WHEN p.is_on_sale    THEN 'on_sale'
    WHEN p.has_gift_box  THEN 'gift_box'
    ELSE                      'none'
  END                 AS active_badge,
  -- Label de exibição em PT-BR (pronto para o frontend)
  CASE
    WHEN p.is_stockout   THEN 'Fora de estoque'
    WHEN p.is_new        THEN 'Novidade'
    WHEN p.is_bestseller THEN 'Mais vendido'
    WHEN p.is_featured   THEN 'Destaque'
    WHEN p.is_on_sale    THEN 'Promoção'
    WHEN p.has_gift_box  THEN 'Embalagem especial'
    ELSE                      NULL
  END                 AS active_badge_label,
  -- Cor CSS para o badge (tailwind class ou hex)
  CASE
    WHEN p.is_stockout   THEN 'red'
    WHEN p.is_new        THEN 'blue'
    WHEN p.is_bestseller THEN 'amber'
    WHEN p.is_featured   THEN 'purple'
    WHEN p.is_on_sale    THEN 'green'
    WHEN p.has_gift_box  THEN 'teal'
    ELSE                      NULL
  END                 AS active_badge_color,
  -- Quantos badges secundários existem (para debug/analytics)
  (
    (p.is_stockout::int)   +
    (p.is_new::int)        +
    (p.is_bestseller::int) +
    (p.is_featured::int)   +
    (p.is_on_sale::int)    +
    (p.has_gift_box::int)
  )                   AS total_badges_ativos,
  -- Expiração da novidade (útil para cache-busting no frontend)
  p.novelty_expires_at,
  p.supplier_id,
  p.updated_at
FROM public.products p;

-- Garantir que a view é visível para o role anon/authenticated
GRANT SELECT ON public.v_product_active_badge TO anon, authenticated;

COMMENT ON VIEW public.v_product_active_badge IS
'Hierarquia canônica de badges por produto. Prioridade: stockout > new > bestseller > featured > on_sale > gift_box. Use active_badge para exibição no catálogo — nunca calcule a prioridade no frontend.';
;

-- <<< END 20260614121516_create_view_v_product_active_badge.sql <<<

-- >>> BEGIN 20260614121641_fix_fn_sync_derived_v3_remove_stockout_onsale_logic.sql >>>

-- ============================================================
-- FIX P2-A: fn_sync_derived_product_flags v3
-- MUDANÇA: Remove lógica "stockout → is_on_sale" completamente.
-- is_on_sale agora deve ser setado APENAS por:
--   (a) Pipeline do fornecedor com dado real de promoção
--   (b) Admin manual com is_on_sale_expires_at obrigatório
-- O badge "Fora de estoque" já é tratado por is_stockout.
-- Manter: auto-reset (limpa is_on_sale residual quando estoque volta)
-- Manter: expiração por expires_at (para promoções futuras)
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_sync_derived_product_flags()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_on_sale_cleared  integer := 0;
  v_on_sale_expired  integer := 0;
  v_new_expired      integer := 0;
  v_featured_exp     integer := 0;
  v_bestseller_exp   integer := 0;
BEGIN

  -- ── AUTO-RESET is_on_sale residual ───────────────────────────────
  -- Remove is_on_sale=TRUE de produtos que NÃO têm expires_at definido
  -- (limpeza de resíduos de lógica antiga stockout→onsale)
  -- Promoções manuais legítimas TÊM expires_at → ficam protegidas.
  UPDATE products
  SET is_on_sale = false, updated_at = now()
  WHERE is_on_sale  = true
    AND is_on_sale_expires_at IS NULL;
  GET DIAGNOSTICS v_on_sale_cleared = ROW_COUNT;

  -- ── EXPIRAR is_on_sale por expires_at ────────────────────────────
  UPDATE products
  SET is_on_sale = false, updated_at = now()
  WHERE is_on_sale = true
    AND is_on_sale_expires_at IS NOT NULL
    AND is_on_sale_expires_at < now();
  GET DIAGNOSTICS v_on_sale_expired = ROW_COUNT;

  -- ── EXPIRAR is_new ────────────────────────────────────────────────
  UPDATE products
  SET is_new = false, updated_at = now()
  WHERE is_new = true
    AND is_new_expires_at IS NOT NULL
    AND is_new_expires_at < now();
  GET DIAGNOSTICS v_new_expired = ROW_COUNT;

  -- ── EXPIRAR is_featured ───────────────────────────────────────────
  UPDATE products
  SET is_featured = false, updated_at = now()
  WHERE is_featured = true
    AND is_featured_expires_at IS NOT NULL
    AND is_featured_expires_at < now();
  GET DIAGNOSTICS v_featured_exp = ROW_COUNT;

  -- ── EXPIRAR is_bestseller ─────────────────────────────────────────
  UPDATE products
  SET is_bestseller = false, updated_at = now()
  WHERE is_bestseller = true
    AND is_bestseller_expires_at IS NOT NULL
    AND is_bestseller_expires_at < now();
  GET DIAGNOSTICS v_bestseller_exp = ROW_COUNT;

  RETURN jsonb_build_object(
    'version',               'v3_2026-06-14_remove_stockout_onsale',
    'is_on_sale_cleared',    v_on_sale_cleared,
    'is_on_sale_expired',    v_on_sale_expired,
    'is_new_expired',        v_new_expired,
    'is_featured_expired',   v_featured_exp,
    'is_bestseller_expired', v_bestseller_exp
  );
END;
$$;
;

-- <<< END 20260614121641_fix_fn_sync_derived_v3_remove_stockout_onsale_logic.sql <<<

-- >>> BEGIN 20260614121711_fix_sync_is_new_expires_at_trigger_canonical_novelty.sql >>>

-- ============================================================
-- FIX P2-B: Trigger para manter is_new_expires_at em sync com
-- novelty_expires_at (canonical) — eliminar divergências futuras
-- novelty_expires_at = coluna canônica
-- is_new_expires_at = cópia de compatibilidade (sync automático)
-- ============================================================

-- 1) Função de trigger de sincronização
CREATE OR REPLACE FUNCTION public.fn_sync_novelty_expires_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- Se novelty_expires_at foi alterado, propaga para is_new_expires_at
  IF NEW.novelty_expires_at IS DISTINCT FROM OLD.novelty_expires_at THEN
    NEW.is_new_expires_at := NEW.novelty_expires_at;
  END IF;
  -- Se is_new_expires_at foi alterado E novelty_expires_at não mudou,
  -- propaga is_new_expires_at → novelty_expires_at (bidirecional)
  IF NEW.is_new_expires_at IS DISTINCT FROM OLD.is_new_expires_at
     AND NEW.novelty_expires_at IS NOT DISTINCT FROM OLD.novelty_expires_at THEN
    NEW.novelty_expires_at := NEW.is_new_expires_at;
  END IF;
  RETURN NEW;
END;
$$;

-- 2) Registrar trigger BEFORE UPDATE na tabela products
DROP TRIGGER IF EXISTS trg_sync_novelty_expires_at ON public.products;

CREATE TRIGGER trg_sync_novelty_expires_at
  BEFORE UPDATE OF novelty_expires_at, is_new_expires_at
  ON public.products
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_sync_novelty_expires_at();

-- 3) Comentário documentando a relação canônica
COMMENT ON COLUMN public.products.novelty_expires_at IS
'CANÔNICA: data de expiração da novidade. Sincronizada bidirecional com is_new_expires_at via trigger trg_sync_novelty_expires_at. Alterar qualquer uma propaga para a outra.';

COMMENT ON COLUMN public.products.is_new_expires_at IS
'CÓPIA de compatibilidade de novelty_expires_at. Mantida em sync por trigger. Prefira usar novelty_expires_at para novos desenvolvimentos.';
;

-- <<< END 20260614121711_fix_sync_is_new_expires_at_trigger_canonical_novelty.sql <<<

-- >>> BEGIN 20260614123055_fix_trg_sync_novelty_expires_also_on_insert.sql >>>

-- ============================================================
-- FIX GAP T5.06: Trigger trg_sync_novelty_expires_at
-- Expandir para também cobrir INSERT (não só UPDATE)
-- Problema: INSERT com novelty_expires_at definido não propagava
-- para is_new_expires_at (trigger era apenas BEFORE UPDATE)
-- ============================================================

-- Atualizar função para lidar com INSERT e UPDATE
CREATE OR REPLACE FUNCTION public.fn_sync_novelty_expires_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- INSERT: se novelty_expires_at foi fornecido, propagar para is_new_expires_at
  IF TG_OP = 'INSERT' THEN
    IF NEW.novelty_expires_at IS NOT NULL AND NEW.is_new_expires_at IS NULL THEN
      NEW.is_new_expires_at := NEW.novelty_expires_at;
    ELSIF NEW.is_new_expires_at IS NOT NULL AND NEW.novelty_expires_at IS NULL THEN
      NEW.novelty_expires_at := NEW.is_new_expires_at;
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE: sincronização bidirecional
  IF TG_OP = 'UPDATE' THEN
    -- Se novelty_expires_at mudou, propaga para is_new_expires_at
    IF NEW.novelty_expires_at IS DISTINCT FROM OLD.novelty_expires_at THEN
      NEW.is_new_expires_at := NEW.novelty_expires_at;
    END IF;
    -- Se is_new_expires_at mudou E novelty não mudou → propaga inverso
    IF NEW.is_new_expires_at IS DISTINCT FROM OLD.is_new_expires_at
       AND NEW.novelty_expires_at IS NOT DISTINCT FROM OLD.novelty_expires_at THEN
      NEW.novelty_expires_at := NEW.is_new_expires_at;
    END IF;
    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;

-- Recriar trigger cobrindo INSERT E UPDATE
DROP TRIGGER IF EXISTS trg_sync_novelty_expires_at ON public.products;

CREATE TRIGGER trg_sync_novelty_expires_at
  BEFORE INSERT OR UPDATE OF novelty_expires_at, is_new_expires_at
  ON public.products
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_sync_novelty_expires_at();

COMMENT ON FUNCTION public.fn_sync_novelty_expires_at() IS
'Sincroniza novelty_expires_at ↔ is_new_expires_at em INSERT e UPDATE. novelty_expires_at é a coluna canônica.';
;

-- <<< END 20260614123055_fix_trg_sync_novelty_expires_also_on_insert.sql <<<

-- >>> BEGIN 20260614124543_fix_view_v_product_active_badge_v2_catalog_badge.sql >>>

-- Drop e recrear com nova estrutura de colunas
DROP VIEW IF EXISTS public.v_product_active_badge CASCADE;

CREATE VIEW public.v_product_active_badge AS
SELECT
  p.id                AS product_id,
  p.sku,
  p.name,
  p.is_active,
  p.is_stockout,
  p.is_new,
  p.is_bestseller,
  p.is_featured,
  p.is_on_sale,
  p.has_gift_box,
  -- Badge técnico (admin/debug — sempre calculado independente de is_active)
  CASE
    WHEN p.is_stockout   THEN 'stockout'
    WHEN p.is_new        THEN 'new'
    WHEN p.is_bestseller THEN 'bestseller'
    WHEN p.is_featured   THEN 'featured'
    WHEN p.is_on_sale    THEN 'on_sale'
    WHEN p.has_gift_box  THEN 'gift_box'
    ELSE                      'none'
  END                 AS active_badge,
  -- Badge do catálogo (USAR NO FRONTEND — NULL quando produto inativo)
  CASE
    WHEN NOT p.is_active THEN NULL
    WHEN p.is_stockout   THEN 'stockout'
    WHEN p.is_new        THEN 'new'
    WHEN p.is_bestseller THEN 'bestseller'
    WHEN p.is_featured   THEN 'featured'
    WHEN p.is_on_sale    THEN 'on_sale'
    WHEN p.has_gift_box  THEN 'gift_box'
    ELSE                      'none'
  END                 AS catalog_badge,
  -- Label PT-BR (NULL se inativo)
  CASE
    WHEN NOT p.is_active THEN NULL
    WHEN p.is_stockout   THEN 'Fora de estoque'
    WHEN p.is_new        THEN 'Novidade'
    WHEN p.is_bestseller THEN 'Mais vendido'
    WHEN p.is_featured   THEN 'Destaque'
    WHEN p.is_on_sale    THEN 'Promoção'
    WHEN p.has_gift_box  THEN 'Embalagem especial'
    ELSE                      NULL
  END                 AS active_badge_label,
  -- Cor CSS (NULL se inativo)
  CASE
    WHEN NOT p.is_active THEN NULL
    WHEN p.is_stockout   THEN 'red'
    WHEN p.is_new        THEN 'blue'
    WHEN p.is_bestseller THEN 'amber'
    WHEN p.is_featured   THEN 'purple'
    WHEN p.is_on_sale    THEN 'green'
    WHEN p.has_gift_box  THEN 'teal'
    ELSE                      NULL
  END                 AS active_badge_color,
  (
    (p.is_stockout::int)   +
    (p.is_new::int)        +
    (p.is_bestseller::int) +
    (p.is_featured::int)   +
    (p.is_on_sale::int)    +
    (p.has_gift_box::int)
  )                   AS total_badges_ativos,
  p.novelty_expires_at,
  p.supplier_id,
  p.updated_at
FROM public.products p;

GRANT SELECT ON public.v_product_active_badge TO anon, authenticated;
;

