-- >>> BEGIN 20260614131754_fix_on_sale_constraint_and_helper_functions.sql >>>

-- ============================================================
-- FIX #5A: CHECK CONSTRAINT — is_on_sale obriga expires_at
-- Impede is_on_sale=TRUE sem data de expiração (promoção sem prazo)
-- ============================================================
ALTER TABLE public.products
  ADD CONSTRAINT chk_on_sale_requires_expires
  CHECK (NOT (is_on_sale = TRUE AND is_on_sale_expires_at IS NULL));

COMMENT ON CONSTRAINT chk_on_sale_requires_expires ON public.products IS
'Garante que toda promoção tenha data de expiração. is_on_sale=TRUE sem is_on_sale_expires_at é proibido. Use fn_set_product_on_sale() para ativar promoções.';

-- ============================================================
-- FIX #5B: FUNÇÃO HELPER — ativar promoção com prazo obrigatório
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_set_product_on_sale(
  p_product_id    uuid,
  p_expires_at    timestamptz,
  p_discount_pct  numeric DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_sku    text;
  v_name   text;
BEGIN
  -- Validações
  IF p_expires_at IS NULL THEN
    RAISE EXCEPTION 'p_expires_at é obrigatório para promoções (constraint chk_on_sale_requires_expires)';
  END IF;
  IF p_expires_at <= NOW() THEN
    RAISE EXCEPTION 'p_expires_at deve ser uma data futura (recebido: %)', p_expires_at;
  END IF;
  IF p_discount_pct IS NOT NULL AND (p_discount_pct <= 0 OR p_discount_pct >= 100) THEN
    RAISE EXCEPTION 'p_discount_pct deve estar entre 0 e 100 (recebido: %)', p_discount_pct;
  END IF;

  SELECT sku, name INTO v_sku, v_name FROM products WHERE id=p_product_id;
  IF v_sku IS NULL THEN
    RAISE EXCEPTION 'Produto % não encontrado', p_product_id;
  END IF;

  -- Ativar promoção
  UPDATE products
  SET
    is_on_sale            = TRUE,
    is_on_sale_expires_at = p_expires_at,
    updated_at            = NOW()
  WHERE id = p_product_id;

  RETURN jsonb_build_object(
    'status',           'on_sale_ativado',
    'product_id',       p_product_id,
    'sku',              v_sku,
    'name',             v_name,
    'expires_at',       p_expires_at,
    'discount_pct',     p_discount_pct,
    'dias_restantes',   EXTRACT(DAY FROM p_expires_at - NOW())::integer
  );
END;
$$;

-- ============================================================
-- FIX #5C: FUNÇÃO HELPER — remover promoção
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_remove_product_on_sale(
  p_product_id uuid
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE v_sku text;
BEGIN
  SELECT sku INTO v_sku FROM products WHERE id=p_product_id;
  UPDATE products
  SET is_on_sale=FALSE, is_on_sale_expires_at=NULL, updated_at=NOW()
  WHERE id=p_product_id;
  RETURN jsonb_build_object('status','on_sale_removido','sku',v_sku);
END;
$$;

COMMENT ON FUNCTION public.fn_set_product_on_sale IS
'Ativa promoção em um produto com data de expiração obrigatória. Parâmetros: product_id, expires_at (futuro), discount_pct (opcional, 0-100). Respeita constraint chk_on_sale_requires_expires.';
COMMENT ON FUNCTION public.fn_remove_product_on_sale IS
'Remove promoção de um produto (is_on_sale=FALSE, is_on_sale_expires_at=NULL).';
;

-- <<< END 20260614131754_fix_on_sale_constraint_and_helper_functions.sql <<<

-- >>> BEGIN 20260614131816_add_price_last_verified_at_to_products.sql >>>

-- ============================================================
-- FIX #19A: Nova coluna price_last_verified_at
-- Distingue "preço verificado" (check) de "preço alterado" (price_updated_at)
-- XBZ: preços raramente mudam mas são verificados a cada sync
-- ============================================================
ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS price_last_verified_at TIMESTAMPTZ;

COMMENT ON COLUMN public.products.price_last_verified_at IS
'Última vez que o preço foi VERIFICADO (independente de ter mudado). Diferente de price_updated_at que só muda quando o preço muda. Usado para o badge #19 Freshness de Preço: stale = NOW()-price_last_verified_at > price_freshness_threshold_days. Atualizado pelo pipeline de sync de cada fornecedor.';
;

-- <<< END 20260614131816_add_price_last_verified_at_to_products.sql <<<

-- >>> BEGIN 20260614131847_add_price_verified_trigger_and_update_view.sql >>>

-- FIX #19C: Trigger para atualizar price_last_verified_at quando last_sync_at muda
CREATE OR REPLACE FUNCTION public.fn_trigger_update_price_last_verified()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- Quando last_sync_at é atualizado, registrar verificação de preço
  IF NEW.last_sync_at IS DISTINCT FROM OLD.last_sync_at
     AND NEW.last_sync_at IS NOT NULL THEN
    NEW.price_last_verified_at := GREATEST(
      COALESCE(NEW.price_last_verified_at, '2000-01-01'::timestamptz),
      NEW.last_sync_at
    );
  END IF;
  -- Quando price_updated_at muda (preço realmente mudou), também atualiza verified
  IF NEW.price_updated_at IS DISTINCT FROM OLD.price_updated_at
     AND NEW.price_updated_at IS NOT NULL THEN
    NEW.price_last_verified_at := GREATEST(
      COALESCE(NEW.price_last_verified_at, '2000-01-01'::timestamptz),
      NEW.price_updated_at
    );
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_update_price_last_verified ON public.products;
CREATE TRIGGER trg_update_price_last_verified
  BEFORE UPDATE OF last_sync_at, price_updated_at
  ON public.products
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_trigger_update_price_last_verified();

COMMENT ON FUNCTION public.fn_trigger_update_price_last_verified IS
'Mantém price_last_verified_at em sync com last_sync_at e price_updated_at. Dispara em BEFORE UPDATE OF last_sync_at, price_updated_at.';
;

-- <<< END 20260614131847_add_price_verified_trigger_and_update_view.sql <<<

-- >>> BEGIN 20260614183000_catalog_search_unaccent_fts.sql >>>
-- Catalogo: busca acento-insensivel (unaccent + FTS) - search_vector em products
-- Data: 2026-06-14 | Autoria: catalog-search-audit (Promo Gifts v4)
-- PROBLEMA: name ILIKE '%ecologico%' -> 3 produtos; com acento -> 41 (38 invisiveis).
-- SOLUCAO: search_vector sem acento + indice GIN. Aditivo + idempotente.
-- METODO: dry-run (BEGIN/ROLLBACK) recomendado; exige service role.

create extension if not exists unaccent;

create or replace function public.immutable_unaccent(txt text)
returns text language sql immutable parallel safe
set search_path = extensions, public, pg_catalog
as $$ select unaccent('unaccent'::regdictionary, coalesce(txt, '')) $$;

alter table public.products
  add column if not exists search_vector tsvector
  generated always as (
    setweight(to_tsvector('portuguese'::regconfig, public.immutable_unaccent(coalesce(name, ''))), 'A') ||
    setweight(to_tsvector('portuguese'::regconfig, public.immutable_unaccent(coalesce(sku, ''))), 'B') ||
    setweight(to_tsvector('portuguese'::regconfig, public.immutable_unaccent(coalesce(supplier_reference, ''))), 'B') ||
    setweight(to_tsvector('portuguese'::regconfig, public.immutable_unaccent(coalesce(short_description, ''))), 'C')
  ) stored;

create index if not exists idx_products_search_vector on public.products using gin (search_vector);

do $$
declare v_def text; v_from int; v_new text;
begin
  select pg_get_viewdef('public.v_products_public'::regclass, true) into v_def;
  if v_def is null then raise notice 'view inexistente';
  elsif position('search_vector' in v_def) > 0 then raise notice 'ja exposto';
  elsif v_def ~* '\*\s+from' or v_def ~ '\.\*' then raise notice 'SELECT * - flui automaticamente';
  else
    v_from := position(' FROM ' in upper(v_def));
    if v_from = 0 then raise exception 'FROM nao localizado'; end if;
    v_new := left(v_def, v_from - 1) || ', search_vector' || substr(v_def, v_from);
    execute 'create or replace view public.v_products_public as ' || v_new;
    raise notice 'view recriada com search_vector';
  end if;
end $$;

grant select on public.v_products_public to anon, authenticated;

-- VERIFICACAO pos-apply (esperado AMBOS ~41):
-- select count(*) from v_products_public where search_vector @@ websearch_to_tsquery('portuguese','ecologico') and active;

-- <<< END 20260614183000_catalog_search_unaccent_fts.sql <<<

-- >>> BEGIN 20260614210000_fix_convert_cart_to_quote_organization_id.sql >>>
-- fix(cart): fn_convert_cart_to_quote grava organization_id + backfill de rascunhos orfaos
--
-- Bug: a RPC criava quotes sem organization_id. O RLS quotes_select_scope exige
-- user_is_org_member(organization_id); com org NULL nem o proprio dono le o rascunho
-- -> /orcamentos/:id/editar recebia 0 linhas -> 406 (Not Acceptable) em loop.
-- O INSERT passava por ser SECURITY DEFINER; o SELECT do navegador (RLS), nao.
--
-- Ja aplicado em producao; este arquivo registra a migration para o repo nao divergir do DB.
-- Idempotente: CREATE OR REPLACE + backfill com WHERE organization_id IS NULL.

CREATE TABLE IF NOT EXISTS public._backup_quotes_orgid_null_20260614 AS
  SELECT id, organization_id, created_by, seller_id, created_at
  FROM public.quotes WHERE organization_id IS NULL;

CREATE OR REPLACE FUNCTION public.fn_convert_cart_to_quote(p_cart_id uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid(); v_org uuid;
  v_cart public.seller_carts%ROWTYPE; v_quote_id uuid; v_it public.seller_cart_items%ROWTYPE;
  v_pid uuid; v_min int; v_eff int; v_oos boolean; v_count int;
  v_warnings jsonb := '[]'::jsonb; v_bumped jsonb := '[]'::jsonb;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Nao autenticado.' USING ERRCODE='28000'; END IF;
  SELECT * INTO v_cart FROM public.seller_carts WHERE id = p_cart_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Carrinho nao encontrado.' USING ERRCODE='P0002'; END IF;
  IF v_cart.seller_id <> v_uid THEN RAISE EXCEPTION 'Este carrinho nao pertence ao usuario atual.' USING ERRCODE='42501'; END IF;
  SELECT count(*) INTO v_count FROM public.seller_cart_items WHERE cart_id = p_cart_id;
  IF v_count = 0 THEN RAISE EXCEPTION 'Carrinho vazio - adicione itens antes de gerar o orcamento.' USING ERRCODE='23514'; END IF;
  SELECT organization_id INTO v_org FROM public.user_organizations WHERE user_id = v_uid
    ORDER BY (role::text='owner') DESC, (role::text='admin') DESC, created_at ASC LIMIT 1;
  IF v_org IS NULL THEN RAISE EXCEPTION 'Vendedor sem organizacao vinculada - nao e possivel gerar o orcamento.' USING ERRCODE='23514'; END IF;
  INSERT INTO public.quotes (organization_id, created_by, seller_id, status, client_name, client_company, notes)
  VALUES (v_org, v_uid, v_uid, 'draft', COALESCE(NULLIF(v_cart.company_name,''),'Cliente'), v_cart.company_name, v_cart.notes)
  RETURNING id INTO v_quote_id;
  FOR v_it IN SELECT * FROM public.seller_cart_items WHERE cart_id = p_cart_id ORDER BY sort_order NULLS LAST, created_at LOOP
    BEGIN v_pid := v_it.product_id::uuid; EXCEPTION WHEN others THEN v_pid := NULL; END;
    v_min := 1; v_oos := false;
    IF v_pid IS NOT NULL THEN
      SELECT COALESCE(min_order_quantity, min_quantity, 1), (is_stockout IS TRUE OR COALESCE(stock_quantity,0) <= 0) INTO v_min, v_oos FROM public.products WHERE id = v_pid;
      IF NOT FOUND THEN v_pid := NULL; v_min := 1; v_oos := false; END IF;
    END IF;
    v_eff := GREATEST(COALESCE(v_it.quantity,1), 1);
    IF v_eff < v_min THEN v_bumped := v_bumped || jsonb_build_object('produto', v_it.product_name, 'de', v_eff, 'para', v_min); v_eff := v_min; END IF;
    IF v_oos THEN v_warnings := v_warnings || jsonb_build_object('produto', v_it.product_name, 'aviso', 'sem estoque no momento'); END IF;
    INSERT INTO public.quote_items (quote_id, product_id, product_sku, product_name, product_image_url, unit_price, quantity, color_name, color_hex, notes, sort_order)
    VALUES (v_quote_id, v_pid, v_it.product_sku, v_it.product_name, v_it.product_image_url, COALESCE(v_it.product_price,0), v_eff, v_it.color_name, v_it.color_hex, v_it.notes, v_it.sort_order);
  END LOOP;
  DELETE FROM public.seller_carts WHERE id = p_cart_id;
  RETURN jsonb_build_object('quote_id', v_quote_id, 'items', v_count, 'bumped', v_bumped, 'warnings', v_warnings);
END $function$;

UPDATE public.quotes q
SET organization_id = (
  SELECT uo.organization_id FROM public.user_organizations uo
  WHERE uo.user_id = COALESCE(q.created_by, q.seller_id)
  ORDER BY (uo.role::text='owner') DESC, (uo.role::text='admin') DESC, uo.created_at ASC
  LIMIT 1)
WHERE q.organization_id IS NULL
  AND EXISTS (SELECT 1 FROM public.user_organizations uo2 WHERE uo2.user_id = COALESCE(q.created_by, q.seller_id));

-- <<< END 20260614210000_fix_convert_cart_to_quote_organization_id.sql <<<

