-- >>> BEGIN 20260615110226_fix_asia_stock_fast_sync_nq1_date_guard.sql >>>
CREATE OR REPLACE FUNCTION public.fn_asia_stock_fast_sync(p_skus jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_asia   uuid := 'd2734e23-d633-4819-bb15-e51aa44e2118';
  v_org    uuid := '5db5aee1-064b-4ef4-9193-345dcd8274ea';
  r        jsonb;
  v_sku    text; v_stock int; v_price numeric; v_vid uuid; v_pid uuid;
  v_seen   int := 0; v_ok int := 0; v_nao int := 0; v_erros int := 0;
  v_nq_propagados int := 0; v_vss_nq_updated int := 0;
  v_prods  uuid[] := '{}';
  v_skus_processados text[] := '{}';
  v_t0     timestamptz := clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('fn_asia_stock_fast_sync')::bigint) THEN
    RETURN jsonb_build_object('success', true, 'skipped', 'lock_ocupado');
  END IF;

  FOR r IN SELECT * FROM jsonb_array_elements(p_skus)
  LOOP
    BEGIN
      v_seen  := v_seen + 1;
      v_sku   := r->>'sku';
      v_stock := GREATEST(0, COALESCE(fn_safe_int(r->>'qtd_estoque'), 0));
      v_price := fn_safe_num(r->>'preco');

      IF v_sku IS NULL OR v_sku = '' THEN CONTINUE; END IF;

      SELECT pv.id, pv.product_id INTO v_vid, v_pid
      FROM product_variants pv
      JOIN products p ON p.id = pv.product_id
      WHERE p.supplier_id = v_asia
        AND (pv.supplier_sku = v_sku OR pv.sku = 'ASIA-' || v_sku)
        AND pv.is_active = true
      LIMIT 1;

      IF v_vid IS NULL THEN v_nao := v_nao + 1; CONTINUE; END IF;

      UPDATE product_variants
      SET stock_quantity = v_stock, updated_at = now()
      WHERE id = v_vid;

      INSERT INTO variant_supplier_sources (
        variant_id, supplier_id, quantity, cost_price,
        last_synced_at, sync_status, updated_at, organization_id
      ) VALUES (
        v_vid, v_asia, v_stock, v_price, now(), 'synced', now(), v_org
      )
      ON CONFLICT (variant_id, supplier_id) DO UPDATE SET
        quantity       = EXCLUDED.quantity,
        cost_price     = CASE WHEN EXCLUDED.cost_price > 0 THEN EXCLUDED.cost_price ELSE variant_supplier_sources.cost_price END,
        last_synced_at = now(), sync_status = 'synced', updated_at = now();

      v_ok := v_ok + 1;
      IF NOT (v_pid = ANY(v_prods)) THEN v_prods := array_append(v_prods, v_pid); END IF;
      v_skus_processados := array_append(v_skus_processados, v_sku);

    EXCEPTION WHEN OTHERS THEN v_erros := v_erros + 1;
    END;
  END LOOP;

  UPDATE products p
  SET stock_quantity = (SELECT COALESCE(SUM(pv.stock_quantity),0) FROM product_variants pv WHERE pv.product_id=p.id AND pv.is_active=true),
      last_sync_at=now(), updated_at=now()
  WHERE p.id = ANY(v_prods);

  -- PASSO 4: Bronze -> VSS (sem guard -- auditavel)
  UPDATE variant_supplier_sources vss
  SET
    next_quantity_1 = fn_safe_int(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'quantidade'),
    next_date_1     = CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                      THEN LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data',10)::date ELSE NULL END,
    next_quantity_2 = fn_safe_int(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'quantidade'),
    next_date_2     = CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                      THEN LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data',10)::date ELSE NULL END,
    next_quantity_3 = fn_safe_int(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'quantidade'),
    next_date_3     = CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                      THEN LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data',10)::date ELSE NULL END,
    updated_at      = now()
  FROM supplier_products_raw spr
  WHERE vss.supplier_id=v_asia AND spr.supplier_id=v_asia
    AND (vss.supplier_sku=spr.supplier_sku OR vss.supplier_sku='ASIA-'||spr.supplier_sku)
    AND spr.supplier_sku=ANY(v_skus_processados);
  GET DIAGNOSTICS v_vss_nq_updated = ROW_COUNT;

  -- PASSO 5: Bronze -> PV GOLD com GUARD > CURRENT_DATE
  -- FIX FINAL-02: nq1/nq2/nq3 agora usam o MESMO guard de regex dos ndX.
  -- Antes, nq1 fazia LEFT(COALESCE(...,''),10)::date sem regex -> ''::date -> erro 22007 (data NULL/vazia).
  PERFORM set_config('app.bulk_import_mode','true',true);
  WITH bronze_data AS (
    SELECT spr.supplier_sku AS sku,
           -- Guard: so datas futuras e ISO-validas chegam ao Gold
           CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                 AND LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data',10)::date > CURRENT_DATE
                THEN fn_safe_int(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'quantidade') ELSE NULL END AS nq1,
           CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                 AND LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data',10)::date > CURRENT_DATE
                THEN LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->0->>'data',10)::date ELSE NULL END AS nd1,
           CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                 AND LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data',10)::date > CURRENT_DATE
                THEN fn_safe_int(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'quantidade') ELSE NULL END AS nq2,
           CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                 AND LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data',10)::date > CURRENT_DATE
                THEN LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->1->>'data',10)::date ELSE NULL END AS nd2,
           CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                 AND LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data',10)::date > CURRENT_DATE
                THEN fn_safe_int(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'quantidade') ELSE NULL END AS nq3,
           CASE WHEN COALESCE(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data','') ~ '^\d{4}-\d{2}-\d{2}'
                 AND LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data',10)::date > CURRENT_DATE
                THEN LEFT(COALESCE(spr.stock_data,spr.raw_data)->'previsao_entrega'->2->>'data',10)::date ELSE NULL END AS nd3
    FROM supplier_products_raw spr
    WHERE spr.supplier_id=v_asia AND spr.supplier_sku=ANY(v_skus_processados)
  )
  UPDATE product_variants pv
  SET next_quantity_1=b.nq1, next_date_1=b.nd1,
      next_quantity_2=b.nq2, next_date_2=b.nd2,
      next_quantity_3=b.nq3, next_date_3=b.nd3,
      updated_at=now()
  FROM bronze_data b
  WHERE (pv.supplier_sku=b.sku OR pv.supplier_sku='ASIA-'||b.sku) AND pv.is_active=true
    AND (pv.next_quantity_1 IS DISTINCT FROM b.nq1 OR pv.next_date_1 IS DISTINCT FROM b.nd1
      OR pv.next_quantity_2 IS DISTINCT FROM b.nq2 OR pv.next_date_2 IS DISTINCT FROM b.nd2
      OR pv.next_quantity_3 IS DISTINCT FROM b.nq3 OR pv.next_date_3 IS DISTINCT FROM b.nd3);
  GET DIAGNOSTICS v_nq_propagados = ROW_COUNT;

  RETURN jsonb_build_object(
    'success',true,'vistos',v_seen,'aplicados',v_ok,'nao_encontrados',v_nao,
    'produtos_recalc',array_length(v_prods,1),'erros',v_erros,
    'vss_nq_updated',v_vss_nq_updated,'pv_nq_propagados',v_nq_propagados,
    'guard_pv','datas_passadas_NAO_chegam_ao_gold_ASIA',
    'fixes',jsonb_build_array('B01a','B01b','B01c','B01d','FINAL-01-GUARD-ASIA','FINAL-02-NQ-REGEX-GUARD'),
    'segundos',round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,1)
  );
END;
$function$;;

-- <<< END 20260615110226_fix_asia_stock_fast_sync_nq1_date_guard.sql <<<

-- >>> BEGIN 20260615120000_stock_notifications_date_filter.sql >>>
-- ============================================================================
-- Notificações de Estoque: filtro de data (p_since) + eventDate por item
-- ----------------------------------------------------------------------------
-- Adiciona parâmetro p_since DATE DEFAULT NULL em todas as 5 RPCs, permitindo
-- filtrar notificações por período (Hoje / 7d / 30d / Tudo) na UI.
-- fn_get_low_stock_alerts: expõe last_stock_update_at no RETURNS.
-- Já aplicado em produção via execute_sql; este arquivo existe para supabase db push.
--
-- Comportamento de cada função com p_since:
--   fn_get_stockout_alerts  → filtra last_stock_update_at >= p_since
--   fn_get_low_stock_alerts → filtra last_stock_update_at >= p_since
--   fn_get_novelty_alerts   → filtra detected_at >= p_since
--   fn_get_recent_restocks  → restringe janela 30d: GREATEST(p_since, 30d atrás)
--   fn_get_stock_notification_counts → aplica filtro em todos os 4 sub-counts
-- ============================================================================

-- Drop das assinaturas antigas (single-param)
DROP FUNCTION IF EXISTS public.fn_get_recent_restocks(integer);
DROP FUNCTION IF EXISTS public.fn_get_stockout_alerts(integer);
DROP FUNCTION IF EXISTS public.fn_get_low_stock_alerts(integer);
DROP FUNCTION IF EXISTS public.fn_get_novelty_alerts(integer);
DROP FUNCTION IF EXISTS public.fn_get_stock_notification_counts();

-- 1) CHEGOU: p_since restringe janela máxima de 30 dias
CREATE OR REPLACE FUNCTION public.fn_get_recent_restocks(
  p_limit int DEFAULT 30,
  p_since date DEFAULT NULL
)
RETURNS TABLE(product_id uuid, product_name text, product_sku text, image_url text,
              stock_quantity int, supplier_id uuid, supplier_name text, last_restock_date date)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  WITH cenario_a AS (
    SELECT sds.product_id, max(sds.summary_date) AS last_restock_date
    FROM stock_daily_summary sds
    WHERE COALESCE(sds.stock_open,0)=0 AND COALESCE(sds.stock_close,0)>0
      AND sds.restock_detected=true
      AND sds.summary_date >= GREATEST(
        COALESCE(p_since, (CURRENT_DATE - INTERVAL '30 days')::date),
        (CURRENT_DATE - INTERVAL '30 days')::date
      )
    GROUP BY sds.product_id
  )
  SELECT p.id, p.name::text, p.sku::text, p.primary_image_url::text, p.stock_quantity,
         p.supplier_id, s.name::text, ca.last_restock_date
  FROM cenario_a ca
  JOIN products p ON p.id=ca.product_id
  LEFT JOIN suppliers s ON s.id=p.supplier_id
  WHERE p.is_active=true AND p.stock_quantity>0
  ORDER BY ca.last_restock_date DESC, p.stock_quantity DESC, p.id
  LIMIT GREATEST(p_limit,0);
$$;

-- 2) ZEROU: filtra por last_stock_update_at
CREATE OR REPLACE FUNCTION public.fn_get_stockout_alerts(
  p_limit int DEFAULT 50,
  p_since date DEFAULT NULL
)
RETURNS TABLE(product_id uuid, product_name text, product_sku text, image_url text,
              stock_quantity int, supplier_id uuid, supplier_name text, last_stock_update_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT p.id, p.name::text, p.sku::text, p.primary_image_url::text, p.stock_quantity,
         p.supplier_id, s.name::text, p.last_stock_update_at
  FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
  WHERE p.is_active=true AND p.is_stockout=true
    AND (p_since IS NULL OR p.last_stock_update_at >= p_since::timestamptz)
  ORDER BY p.last_stock_update_at DESC NULLS LAST, p.id
  LIMIT GREATEST(p_limit,0);
$$;

-- 3) BAIXO: filtra por last_stock_update_at + expõe coluna no RETURNS
CREATE OR REPLACE FUNCTION public.fn_get_low_stock_alerts(
  p_limit int DEFAULT 50,
  p_since date DEFAULT NULL
)
RETURNS TABLE(product_id uuid, product_name text, product_sku text, image_url text,
              stock_quantity int, supplier_id uuid, supplier_name text,
              low_stock_threshold int, last_stock_update_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT p.id, p.name::text, p.sku::text, p.primary_image_url::text, p.stock_quantity,
         p.supplier_id, s.name::text, COALESCE(s.low_stock_threshold,10), p.last_stock_update_at
  FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
  WHERE p.is_active=true AND p.is_stockout=false
    AND p.stock_quantity>0 AND p.stock_quantity <= COALESCE(s.low_stock_threshold,10)
    AND (p_since IS NULL OR p.last_stock_update_at >= p_since::timestamptz)
  ORDER BY p.stock_quantity ASC, p.id
  LIMIT GREATEST(p_limit,0);
$$;

-- 4) NOVIDADE: filtra por detected_at
CREATE OR REPLACE FUNCTION public.fn_get_novelty_alerts(
  p_limit int DEFAULT 30,
  p_since date DEFAULT NULL
)
RETURNS TABLE(product_id uuid, product_name text, product_sku text, image_url text,
              stock_quantity int, supplier_id uuid, supplier_name text,
              detected_at timestamptz, days_remaining int, is_highlighted boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  WITH dedup AS (
    SELECT DISTINCT ON (pn.product_id)
           pn.product_id, p.name::text, p.sku::text, p.primary_image_url::text, p.stock_quantity,
           p.supplier_id, s.name::text, pn.detected_at,
           EXTRACT(DAY FROM (pn.expires_at - now()))::int, pn.is_highlighted
    FROM product_novelties pn
    JOIN products p ON p.id=pn.product_id
    LEFT JOIN suppliers s ON s.id=p.supplier_id
    WHERE pn.is_active=true AND (pn.expires_at IS NULL OR pn.expires_at>now())
      AND p.is_active=true AND p.is_stockout=false
      AND p.sale_price IS NOT NULL AND p.sale_price>0
      AND p.primary_image_url IS NOT NULL AND p.primary_image_url<>''
      AND (p_since IS NULL OR pn.detected_at >= p_since::timestamptz)
    ORDER BY pn.product_id, pn.detected_at DESC
  )
  SELECT * FROM dedup ORDER BY detected_at DESC, product_id
  LIMIT GREATEST(p_limit,0);
$$;

-- 5) CONTADORES: filtra todos os 4 sub-counts por período
CREATE OR REPLACE FUNCTION public.fn_get_stock_notification_counts(p_since date DEFAULT NULL)
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$
  SELECT jsonb_build_object(
    'stockout', (
      SELECT count(*) FROM products
      WHERE is_active AND is_stockout
        AND (p_since IS NULL OR last_stock_update_at >= p_since::timestamptz)
    ),
    'low_stock', (
      SELECT count(*) FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
      WHERE p.is_active AND p.is_stockout=false AND p.stock_quantity>0
        AND p.stock_quantity <= COALESCE(s.low_stock_threshold,10)
        AND (p_since IS NULL OR p.last_stock_update_at >= p_since::timestamptz)
    ),
    'novelties', (
      SELECT count(DISTINCT pn.product_id)
      FROM product_novelties pn JOIN products p ON p.id=pn.product_id
      WHERE pn.is_active AND (pn.expires_at IS NULL OR pn.expires_at>now())
        AND p.is_active AND p.is_stockout=false AND p.sale_price>0
        AND p.primary_image_url IS NOT NULL AND p.primary_image_url<>''
        AND (p_since IS NULL OR pn.detected_at >= p_since::timestamptz)
    ),
    'restocks', (
      SELECT count(*) FROM (
        SELECT sds.product_id
        FROM stock_daily_summary sds JOIN products p ON p.id=sds.product_id
        WHERE COALESCE(sds.stock_open,0)=0 AND COALESCE(sds.stock_close,0)>0
          AND sds.restock_detected=true
          AND sds.summary_date >= GREATEST(
            COALESCE(p_since, (CURRENT_DATE - INTERVAL '30 days')::date),
            (CURRENT_DATE - INTERVAL '30 days')::date
          )
          AND p.is_active AND p.stock_quantity>0
        GROUP BY sds.product_id
      ) r
    )
  );
$$;

-- Hardening ACL: REVOKE PUBLIC/anon, GRANT authenticated
DO $$ DECLARE fn text;
BEGIN
  FOREACH fn IN ARRAY ARRAY[
    'public.fn_get_recent_restocks(integer,date)',
    'public.fn_get_stockout_alerts(integer,date)',
    'public.fn_get_low_stock_alerts(integer,date)',
    'public.fn_get_novelty_alerts(integer,date)',
    'public.fn_get_stock_notification_counts(date)'
  ] LOOP
    EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM PUBLIC', fn);
    EXECUTE format('REVOKE EXECUTE ON FUNCTION %s FROM anon', fn);
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated', fn);
  END LOOP;
END $$;

-- <<< END 20260615120000_stock_notifications_date_filter.sql <<<

-- >>> BEGIN 20260615140556_fix_asia_product_names_cleanup.sql >>>

DO $$
DECLARE
  v_rows  integer;
  v_t0    timestamptz := clock_timestamp();
BEGIN
  PERFORM set_config('app.write_source',     'pipeline', true);
  PERFORM set_config('app.bulk_import_mode', 'true',     true);

  UPDATE public.products p
  SET
    name          = public.fn_display_product_name(pp.name),
    locked_fields = array_remove(p.locked_fields, 'name'),
    updated_at    = now()
  FROM public.produtos_padronizacao pp
  WHERE pp.supplier_id          = p.supplier_id
    AND pp.supplier_reference   = p.supplier_reference
    AND p.supplier_id           = 'd2734e23-d633-4819-bb15-e51aa44e2118'
    AND p.is_active             = true
    AND p.name LIKE '% – %'
    AND p.name ~ '\d+[,.]?\d*\s*[xXøØ]'
    AND NULLIF(TRIM(pp.name), '') IS NOT NULL;

  GET DIAGNOSTICS v_rows = ROW_COUNT;

  IF v_rows < 280 OR v_rows > 310 THEN
    RAISE EXCEPTION 'Contagem fora do esperado (280-310): % linhas. Abortando.', v_rows;
  END IF;
END;
$$;
;

