    v_rows, ROUND(EXTRACT(EPOCH FROM clock_timestamp()-v_t0)*1000)::int;

  IF v_rows < 300 OR v_rows > 340 THEN
    RAISE EXCEPTION 'Contagem fora do esperado (300-340): % linhas. Abortando.', v_rows;
  END IF;
END;
$$;
;

