-- ============================================================
-- PEÇA 2: Migrar as 3 funções que usam auth_login_attempts
-- para usar login_attempts (canônica, 1.240 linhas ativas)
-- e depois arquivar auth_login_attempts
-- ============================================================

-- 2A: record_auth_attempt → delega para log_login_attempt (já canônica)
CREATE OR REPLACE FUNCTION public.record_auth_attempt(
  _email    text,
  _ip       text,
  _success  boolean,
  _reason   text DEFAULT NULL,
  _ua       text DEFAULT NULL
)
RETURNS void
LANGUAGE sql
SET search_path TO 'public'
AS $$
  -- MIGRADO em 2026-06-15: era INSERT em auth_login_attempts (vazia).
  -- Agora delega para log_login_attempt → login_attempts (canônica, ativa).
  SELECT public.log_login_attempt(
    _email        := _email,
    _success      := _success,
    _user_id      := NULL,
    _ip           := _ip,
    _user_agent   := _ua,
    _failure_reason := _reason
  );
$$;

-- 2B: check_auth_throttling → lê de login_attempts em vez de auth_login_attempts
-- Mantém assinatura idêntica para não quebrar callers
CREATE OR REPLACE FUNCTION public.check_auth_throttling(
  _email text,
  _ip    text
)
RETURNS TABLE(allowed boolean, remaining_seconds integer)
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  recent_failures     INT;
  last_failure_at     TIMESTAMP WITH TIME ZONE;
  lockout_duration    INT;
  elapsed_since_last  INT;
BEGIN
  -- MIGRADO em 2026-06-15: era auth_login_attempts (0 linhas).
  -- Agora lê de login_attempts (canônica). Lógica de throttling idêntica.
  SELECT COUNT(*), MAX(created_at)
    INTO recent_failures, last_failure_at
  FROM public.login_attempts
  WHERE (email = _email OR ip_address = _ip)
    AND success = false
    AND created_at > now() - INTERVAL '15 minutes';

  IF recent_failures < 5 THEN
    RETURN QUERY SELECT true, 0;
    RETURN;
  END IF;

  IF    recent_failures < 10 THEN lockout_duration := 300;
  ELSIF recent_failures < 15 THEN lockout_duration := 900;
  ELSE                             lockout_duration := 3600;
  END IF;

  elapsed_since_last := EXTRACT(EPOCH FROM (now() - last_failure_at))::INT;

  IF elapsed_since_last >= lockout_duration THEN
    RETURN QUERY SELECT true, 0;
  ELSE
    RETURN QUERY SELECT false, (lockout_duration - elapsed_since_last);
  END IF;
END;
$function$;

-- 2C: clear_auth_attempts → deleta de login_attempts por email
CREATE OR REPLACE FUNCTION public.clear_auth_attempts(_email text)
RETURNS void
LANGUAGE sql
SET search_path TO 'public'
AS $$
  -- MIGRADO em 2026-06-15: era DELETE em auth_login_attempts (vazia).
  -- Agora limpa login_attempts (canônica).
  DELETE FROM public.login_attempts WHERE email = _email;
$$;

-- 2D: Arquivar auth_login_attempts (0 linhas, agora sem callers)
ALTER TABLE public.auth_login_attempts SET SCHEMA archive;

-- Comentário pós-arquivo
COMMENT ON TABLE archive.auth_login_attempts IS
'[ARQUIVADA → schema archive em 2026-06-15]
Tabela duplicata de public.login_attempts — criada para um
sistema de seguranca paralelo (check_auth_throttling +
record_auth_attempt + clear_auth_attempts) que nunca recebeu
dados (0 linhas em producao).

As 3 funcoes callers foram migradas para login_attempts
(canonica, 1.240 linhas ativas) em 2026-06-15.
Schema: email, ip_address, success, failure_reason, user_agent.
login_attempts e superset: adiciona user_id e metadata.

Candidata a DROP apos confirmar estabilidade das 3 funcoes migradas.';
;

-- <<< END 20260615153253_peca2_unify_auth_login_attempts_to_login_attempts.sql <<<

-- >>> BEGIN 20260615153354_peca3_fn_check_login_allowed.sql >>>

-- ============================================================
-- PEÇA 3: fn_check_login_allowed — orquestrador de enforcement
-- Lê access_security_settings e aplica todos os controles:
--   1. IP whitelist
--   2. City whitelist
--   3. Lockout por tentativas falhas (usa login_attempts)
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_check_login_allowed(
  p_email       TEXT,
  p_ip_address  TEXT       DEFAULT NULL,
  p_city        TEXT       DEFAULT NULL,
  p_user_agent  TEXT       DEFAULT NULL
)
RETURNS TABLE (
  allowed       BOOLEAN,
  reason        TEXT,
  blocked_until TIMESTAMPTZ,
  check_details JSONB
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  _s              RECORD;   -- linha singleton de access_security_settings
  _failed_count   INT   := 0;
  _last_failure   TIMESTAMPTZ;
  _last_success   TIMESTAMPTZ;
  _lockout_until  TIMESTAMPTZ;
  _details        JSONB := '{}'::JSONB;
BEGIN
  -- ── GUARD: email obrigatório ───────────────────────────────
  IF p_email IS NULL OR length(trim(p_email)) = 0 THEN
    RETURN QUERY SELECT false, 'invalid_email'::TEXT,
      NULL::TIMESTAMPTZ, '{}'::JSONB;
    RETURN;
  END IF;
  p_email := lower(trim(p_email));

  -- ── 1. Ler configurações (com fallback seguro se singleton vazio) ──
  SELECT * INTO _s FROM public.access_security_settings LIMIT 1;

  IF NOT FOUND THEN
    _s.ip_whitelist_enabled     := false;
    _s.city_whitelist_enabled   := false;
    _s.block_unknown_locations  := false;
    _s.max_failed_attempts      := 5;
    _s.lockout_duration_minutes := 30;
    _s.strict_access_mode       := false;
    _details := _details || '{"settings_source":"defaults"}'::JSONB;
  ELSE
    _details := _details || '{"settings_source":"db"}'::JSONB;
  END IF;

  -- Sanitizar valores mínimos (evita divisão por zero / lockout eterno)
  _s.max_failed_attempts      := GREATEST(COALESCE(_s.max_failed_attempts, 5), 1);
  _s.lockout_duration_minutes := GREATEST(COALESCE(_s.lockout_duration_minutes, 30), 1);

  -- ── 2. IP Whitelist ───────────────────────────────────────
  IF _s.ip_whitelist_enabled AND p_ip_address IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.ip_whitelist WHERE is_active = true LIMIT 1) THEN
      -- Lista populada: checar IP
      IF NOT EXISTS (
        SELECT 1 FROM public.ip_whitelist
        WHERE ip_address = p_ip_address AND is_active = true
      ) THEN
        _details := _details
          || jsonb_build_object('ip_check','blocked','ip',p_ip_address);
        BEGIN
          INSERT INTO public.access_blocked_log
            (email, ip_address, city, block_reason, user_agent)
          VALUES (p_email, p_ip_address, p_city, 'ip_not_whitelisted', p_user_agent);
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
        RETURN QUERY SELECT false, 'ip_not_whitelisted'::TEXT,
          NULL::TIMESTAMPTZ, _details;
        RETURN;
      END IF;
      _details := _details || '{"ip_check":"allowed"}'::JSONB;
    ELSE
      -- Whitelist vazia → FAIL OPEN (não bloqueia ninguém)
      _details := _details || '{"ip_check":"skipped_empty_whitelist"}'::JSONB;
    END IF;
  ELSE
    _details := _details || '{"ip_check":"disabled"}'::JSONB;
  END IF;

  -- ── 3. City Whitelist ─────────────────────────────────────
  IF _s.city_whitelist_enabled AND p_city IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM public.city_whitelist WHERE is_active = true LIMIT 1) THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.city_whitelist
        WHERE upper(city_name) = upper(p_city) AND is_active = true
      ) THEN
        _details := _details
          || jsonb_build_object('city_check','blocked','city',p_city);
        BEGIN
          INSERT INTO public.access_blocked_log
            (email, ip_address, city, block_reason, user_agent)
          VALUES (p_email, p_ip_address, p_city, 'city_not_whitelisted', p_user_agent);
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
        RETURN QUERY SELECT false, 'city_not_whitelisted'::TEXT,
          NULL::TIMESTAMPTZ, _details;
        RETURN;
      END IF;
      _details := _details || '{"city_check":"allowed"}'::JSONB;
    ELSE
      _details := _details || '{"city_check":"skipped_empty_whitelist"}'::JSONB;
    END IF;
  ELSE
    _details := _details || '{"city_check":"disabled"}'::JSONB;
  END IF;

  -- ── 4. Lockout por tentativas falhas ──────────────────────
  -- Âncora: último sucesso (ignora falhas anteriores a ele)
  SELECT max(created_at) INTO _last_success
  FROM public.login_attempts
  WHERE email = p_email AND success = true;

  SELECT count(*), max(created_at)
    INTO _failed_count, _last_failure
  FROM public.login_attempts
  WHERE email = p_email
    AND success = false
    AND created_at > now()
        - (_s.lockout_duration_minutes || ' minutes')::interval
    AND (_last_success IS NULL OR created_at > _last_success);

  _details := _details || jsonb_build_object(
    'failed_attempts',   _failed_count,
    'max_allowed',       _s.max_failed_attempts,
    'window_minutes',    _s.lockout_duration_minutes
  );

  IF _failed_count >= _s.max_failed_attempts AND _last_failure IS NOT NULL THEN
    _lockout_until := _last_failure
      + (_s.lockout_duration_minutes || ' minutes')::interval;

    IF _lockout_until > now() THEN
      _details := _details
        || jsonb_build_object('lockout_until', _lockout_until);
      BEGIN
        INSERT INTO public.access_blocked_log
          (email, ip_address, city, block_reason, user_agent)
        VALUES (p_email, p_ip_address, p_city,
                'too_many_failed_attempts', p_user_agent);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
      RETURN QUERY SELECT false, 'too_many_failed_attempts'::TEXT,
        _lockout_until, _details;
      RETURN;
    END IF;
  END IF;

  -- ── 5. Passou tudo → ALLOWED ──────────────────────────────
  _details := _details || '{"result":"all_checks_passed"}'::JSONB;
  RETURN QUERY SELECT true, 'allowed'::TEXT, NULL::TIMESTAMPTZ, _details;

EXCEPTION WHEN OTHERS THEN
  -- Fail-OPEN: erro inesperado não bloqueia o login
  RETURN QUERY SELECT true, 'security_check_error_fail_open'::TEXT,
    NULL::TIMESTAMPTZ,
    jsonb_build_object('error', SQLERRM, 'sqlstate', SQLSTATE);
END;
$function$;

-- Grants: authenticated pode chamar (pré-login), service_role também
REVOKE ALL ON FUNCTION public.fn_check_login_allowed(TEXT,TEXT,TEXT,TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_check_login_allowed(TEXT,TEXT,TEXT,TEXT)
  TO authenticated, service_role;
;

-- <<< END 20260615153354_peca3_fn_check_login_allowed.sql <<<

-- >>> BEGIN 20260615153540_perf_01_fn_purge_spr_history_nova_arquitetura.sql >>>

-- ══════════════════════════════════════════════════════════════════════
-- MIGRATION 01: fn_purge_spr_history → nova arquitetura
-- Adapta Job 2 para usar DROP TABLE em archive.* (vs DELETE row-a-row)
-- Razão: legacy em archive não recebe novos dados (snapshot fixo de 5.1GB)
-- DROP é instantâneo e zero-bloat; DELETE em 3.18M rows geraria WAL massivo
-- Drop ocorrerá em ~2026-09-08 quando max(captured_at) ultrapassar 90 dias
-- Guard: p_keep_days >= 30 previne DROP acidental com janela mínima
-- ══════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_purge_spr_history(p_keep_days integer DEFAULT 90)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_cutoff   timestamptz := now() - make_interval(days => GREATEST(p_keep_days, 30));
  v_deleted  integer := 0;
  v_n        integer;
  r          RECORD;
  v_m        date;
  v_nome     text;
BEGIN
  -- ── JOB 1: DROP partições antigas de supplier_products_raw_history ──
  FOR r IN
    SELECT c.oid::regclass::text AS part,
           (regexp_match(pg_get_expr(c.relpartbound, c.oid),
                         'TO \(''([^'']+)''\)'))[1]::timestamptz AS ub
    FROM pg_inherits i
    JOIN pg_class c ON c.oid = i.inhrelid
    WHERE i.inhparent = 'public.supplier_products_raw_history'::regclass
  LOOP
    IF r.ub IS NOT NULL AND r.ub <= v_cutoff THEN
      EXECUTE format('DROP TABLE %s', r.part);
    END IF;
  END LOOP;

  -- ── JOB 2 (nova arquitetura): DROP legacy quando todos os dados expirarem ──
  -- A tabela foi movida para archive em 2026-06-15 e não recebe novos dados.
  -- DROP TABLE é zero-bloat e instantâneo; DELETE em 3.18M rows geraria WAL massivo.
  -- A tabela só é dropada quando MAX(captured_at) < cutoff (todos os dados expiraram).
  IF to_regclass('archive.supplier_products_raw_history_legacy') IS NOT NULL THEN
    IF (SELECT max(captured_at)
        FROM archive.supplier_products_raw_history_legacy) < v_cutoff THEN
      EXECUTE 'DROP TABLE archive.supplier_products_raw_history_legacy';
      v_deleted := -1;  -- sinal de DROP executado (distingue de 0 rows deletados)
    END IF;
  END IF;

  -- ── JOB 3: garantir partições futuras (próximos 4 meses) ──
  FOR i IN 0..3 LOOP
    v_m := (date_trunc('month', now()) + (i || ' months')::interval)::date;
    v_nome := 'supplier_products_raw_history_p' || to_char(v_m, 'YYYY_MM');
    IF to_regclass('public.' || v_nome) IS NULL THEN
      EXECUTE format(
        'CREATE TABLE public.%I PARTITION OF public.supplier_products_raw_history'
        ' FOR VALUES FROM (%L) TO (%L)',
        v_nome, v_m, (v_m + interval '1 month')::date);
    END IF;
  END LOOP;

  RETURN v_deleted;
END
$function$;

COMMENT ON FUNCTION public.fn_purge_spr_history(integer) IS
'Housekeeping do histórico Bronze.
Job1: DROP de partições de supplier_products_raw_history com data_fim < cutoff.
Job2: DROP de archive.supplier_products_raw_history_legacy quando max(captured_at) < cutoff
      (snapshot fixo — não recebe novos dados desde 2026-06-15). Retorna -1 se executou DROP.
Job3: CREATE de partições futuras (próximos 4 meses).
Guard: p_keep_days é flooreado em 30 para prevenir DROP acidental.
Cron: purge-spr-history-daily 03:30 daily com p_keep_days=90.';
;

-- <<< END 20260615153540_perf_01_fn_purge_spr_history_nova_arquitetura.sql <<<

-- >>> BEGIN 20260615153907_perf_03_tags_indexes_lower_name_and_slug_active.sql >>>

-- ══════════════════════════════════════════════════════════════════
-- MIGRATION 03: tags — índices para padrões de busca reais
--
-- Gap 1: LOWER(name) usado por fn_auto_link_eco, fn_auto_link_feminino,
--         fn_auto_link_tags → seq scan (nenhum índice funcional)
-- Gap 2: (slug) WHERE is_active=true → cobre o padrão mais frequente
--         (fn_apply_auto_tag_rules, fn_apply_supplier_flag_tags × 9 slugs)
--         com índice ainda menor que o compound existente
-- ══════════════════════════════════════════════════════════════════

-- Índice funcional em LOWER(name) — para lookups case-insensitive por nome
CREATE INDEX IF NOT EXISTS idx_tags_lower_name
  ON public.tags (lower(name))
  WHERE is_active = true;

-- Índice parcial em slug para tags ativas — padrão mais frequente nas funções
-- Complementa o compound (slug, org_id) existente: este é menor e
-- elimina o step de Filter: is_active no plan
CREATE INDEX IF NOT EXISTS idx_tags_slug_active
  ON public.tags (slug)
  WHERE is_active = true;

COMMENT ON INDEX public.idx_tags_lower_name IS
'Suporte para fn_auto_link_eco, fn_auto_link_feminino, fn_auto_link_tags:
WHERE LOWER(name) IN (...) OR LOWER(slug) IN (...)';

COMMENT ON INDEX public.idx_tags_slug_active IS
'Suporte para fn_apply_auto_tag_rules e fn_apply_supplier_flag_tags:
WHERE slug = $1 AND is_active = true (padrão mais frequente — 9 slugs hardcoded)';
;

