    THEN ROUND((v_total_orders::numeric / v_total_quotes) * 100, 0) ELSE 0 END;

  SELECT
    COUNT(CASE WHEN is_hot_product THEN 1 END)::integer,
    COUNT(CASE WHEN is_stockout_risk THEN 1 END)::integer,
    COUNT(CASE WHEN is_stagnant THEN 1 END)::integer,
    COALESCE(SUM(total_current_stock), 0),
    COALESCE(ROUND(AVG(avg_depletion_30d) FILTER (WHERE avg_depletion_30d > 0), 1), 0)
  INTO v_products_hot, v_products_risk, v_products_stagnant, v_total_stock, v_avg_velocity
  FROM analytics.mv_product_intelligence;

  v_demand_label := CASE
    WHEN v_avg_velocity >= 100 THEN 'Muito Alta'
    WHEN v_avg_velocity >= 50  THEN 'Alta'
    WHEN v_avg_velocity >= 10  THEN 'Normal'
    WHEN v_avg_velocity >  0   THEN 'Baixa'
    ELSE 'Em análise'
  END;

  v_changed := 'Faturamento de R$ ' || to_char(v_revenue, 'FM999,999,990.00') ||
    ' nos últimos ' || p_days || ' dias com ' || v_total_orders ||
    ' pedidos (ticket médio R$ ' || to_char(v_ticket_avg, 'FM999,999,990.00') ||
    '). Conversão orçamento→pedido: ' || v_conversion || '%.';

  v_reason := 'Demanda de mercado classificada como "' || v_demand_label ||
    '" com velocidade média de ' || ROUND(v_avg_velocity, 1)::text ||
    ' unidades/dia. ' || v_products_risk || ' produtos em risco de ruptura e ' ||
    v_products_stagnant || ' estagnados identificados.';

  v_action := CASE
    WHEN v_conversion = 0 AND v_total_quotes > 0 THEN
      'Conversão 0% — ' || v_total_quotes ||
      ' orçamentos abertos. Ative follow-up nos orçamentos pendentes para destravar pedidos.'
    WHEN v_conversion < 30 AND v_total_quotes > 0 THEN
      'Conversão de ' || v_conversion ||
      '% abaixo da meta. Priorize os orçamentos com maior valor para acelerar fechamentos.'
    WHEN v_products_risk > 50 THEN
      v_products_risk ||
      ' produtos com risco de ruptura. Acione reposição prioritária na curva A.'
    WHEN v_products_stagnant > 200 THEN
      v_products_stagnant ||
      ' produtos estagnados. Avalie ações promocionais ou renegociação com fornecedores.'
    ELSE
      'Pipeline saudável. Expanda prospecção de novos clientes e aumente o ticket médio.'
  END;

  v_insights := jsonb_build_object(
    'gerado_em',   now(),
    'periodo_dias', p_days,
    'dados_base', jsonb_build_object(
      'pedidos',             v_total_orders,
      'orcamentos',          v_total_quotes,
      'faturamento',         v_revenue,
      'ticket_medio',        v_ticket_avg,
      'conversao_pct',       v_conversion,
      'produtos_hot',        v_products_hot,
      'produtos_risco',      v_products_risk,
      'produtos_estagnados', v_products_stagnant,
      'estoque_total',       v_total_stock,
      'velocidade_media',    v_avg_velocity
    ),
    'insights', jsonb_build_object(
      'o_que_mudou',  v_changed,
      'por_que',      v_reason,
      'proxima_acao', v_action,
      'demanda',      v_demand_label
    ),
    'fonte', 'fn_generate_market_insights_cache_v1'
  );

  -- UPSERT com clock_timestamp(): TTL correto mesmo em multi-call intra-transação
  INSERT INTO ai_insights_cache (
    user_id, function_name, cache_key, payload,
    model, duration_ms, expires_at
  ) VALUES (
    p_user_id, 'fn_generate_market_insights_cache',
    v_cache_key, v_insights,
    'db_computed_v1', 0,
    clock_timestamp() + INTERVAL '6 hours'
  )
  ON CONFLICT (user_id, function_name, cache_key)
  DO UPDATE SET
    payload    = EXCLUDED.payload,
    created_at = clock_timestamp(),
    expires_at = clock_timestamp() + INTERVAL '6 hours';

  RETURN v_insights;
END;
$function$;

-- ─── A2: fn_generate_trends_insights ─────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.fn_generate_trends_insights(p_user_id uuid, p_days integer DEFAULT 30)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_caller_id  uuid;
  v_cache_key  text;
  v_cached     jsonb;
  v_insights   jsonb;
  v_since      timestamptz;
  v_since_prev timestamptz;
  v_views_now    bigint; v_prods_now    bigint;
  v_searches_now bigint; v_terms_now    bigint;
  v_views_prev   bigint; v_prods_prev   bigint;
  v_searches_prev bigint; v_terms_prev  bigint;
BEGIN
  v_caller_id := auth.uid();

  IF p_user_id IS NOT NULL
     AND p_user_id != v_caller_id
     AND NOT is_manager_or_admin()
  THEN
    RETURN jsonb_build_object(
      'error', 'Acesso negado: apenas managers e admins podem visualizar dados de outros usuários',
      'totals', jsonb_build_object('views',0,'searches',0,'unique_terms',0,'unique_products',0,
                                   'views_growth_pct',null,'searches_growth_pct',null),
      'top_products','[]'::jsonb,'top_searches','[]'::jsonb,
      'repressed_demand','[]'::jsonb,'period_days',p_days,'generated_at',NOW()
    );
  END IF;

  p_days      := GREATEST(1, LEAST(COALESCE(p_days, 30), 999));
  -- now() para ranges de data (transação-scoped é correto para consistência de query)
  v_since     := NOW() - (p_days || ' days')::interval;
  v_since_prev:= NOW() - (p_days * 2 || ' days')::interval;
  -- cache_key baseado na hora atual (now() correto — granularidade de 1h é intencional)
  v_cache_key := 'trends_' || p_days || '_' || TO_CHAR(NOW(), 'YYYY-MM-DD-HH24');

  IF p_user_id IS NOT NULL THEN
    SELECT payload INTO v_cached
    FROM public.ai_insights_cache
    WHERE user_id = p_user_id AND function_name = 'fn_generate_trends_insights'
      AND cache_key = v_cache_key AND expires_at > NOW()
    LIMIT 1;
    IF FOUND AND v_cached IS NOT NULL THEN RETURN v_cached; END IF;
  END IF;

  SELECT COUNT(*)::bigint, COUNT(DISTINCT product_id)::bigint
  INTO v_views_now, v_prods_now
  FROM public.product_views
  WHERE created_at >= v_since
    AND (p_user_id IS NULL OR seller_id = p_user_id);

  SELECT COUNT(*)::bigint, COUNT(DISTINCT search_term)::bigint
  INTO v_searches_now, v_terms_now
  FROM public.search_analytics WHERE created_at >= v_since;

  SELECT COUNT(*)::bigint, COUNT(DISTINCT product_id)::bigint
  INTO v_views_prev, v_prods_prev
  FROM public.product_views
  WHERE created_at >= v_since_prev AND created_at < v_since
    AND (p_user_id IS NULL OR seller_id = p_user_id);

  SELECT COUNT(*)::bigint, COUNT(DISTINCT search_term)::bigint
  INTO v_searches_prev, v_terms_prev
  FROM public.search_analytics
  WHERE created_at >= v_since_prev AND created_at < v_since;

  SELECT jsonb_build_object(
    'totals', jsonb_build_object(
      'views', v_views_now, 'searches', v_searches_now,
      'unique_terms', v_terms_now, 'unique_products', v_prods_now,
      'views_growth_pct', CASE WHEN v_views_prev=0 THEN NULL
        ELSE ROUND(100.0*(v_views_now-v_views_prev)::numeric/v_views_prev,1) END,
      'searches_growth_pct', CASE WHEN v_searches_prev=0 THEN NULL
        ELSE ROUND(100.0*(v_searches_now-v_searches_prev)::numeric/v_searches_prev,1) END,
      'unique_products_growth_pct', CASE WHEN v_prods_prev=0 THEN NULL
        ELSE ROUND(100.0*(v_prods_now-v_prods_prev)::numeric/v_prods_prev,1) END,
      'unique_terms_growth_pct', CASE WHEN v_terms_prev=0 THEN NULL
        ELSE ROUND(100.0*(v_terms_now-v_terms_prev)::numeric/v_terms_prev,1) END,
      'prev_period_views', v_views_prev,
      'prev_period_searches', v_searches_prev
    ),
    'top_products', COALESCE((
      SELECT jsonb_agg(sub ORDER BY (sub->>'view_count')::bigint DESC)
      FROM (
        SELECT jsonb_build_object(
          'product_id', pv.product_id,'view_count', COUNT(*),'product_name', MAX(p.name)
        ) AS sub
        FROM public.product_views pv
        LEFT JOIN public.products p ON p.id = pv.product_id
        WHERE pv.created_at >= v_since
          AND (p_user_id IS NULL OR pv.seller_id = p_user_id)
        GROUP BY pv.product_id ORDER BY COUNT(*) DESC LIMIT 10
      ) x
    ), '[]'::jsonb),
    'top_searches', COALESCE((
      SELECT jsonb_agg(sub ORDER BY (sub->>'count')::int DESC)
      FROM (
        SELECT jsonb_build_object(
          'term', search_term, 'count', COUNT(*),
          'zero_pct', ROUND(100.0*SUM(CASE WHEN results_count=0 THEN 1 ELSE 0 END)
                      /NULLIF(COUNT(*) FILTER (WHERE results_count != -1),0),1),
          'zero_results', SUM(CASE WHEN results_count=0 THEN 1 ELSE 0 END)
        ) AS sub
        FROM public.search_analytics
        WHERE created_at >= v_since AND results_count != -1
        GROUP BY search_term ORDER BY COUNT(*) DESC LIMIT 10
      ) x
    ), '[]'::jsonb),
    'repressed_demand', COALESCE((
      SELECT jsonb_agg(sub ORDER BY (sub->>'zero_result_searches')::int DESC)
      FROM (
        SELECT jsonb_build_object(
          'term', search_term,
          'searches', COUNT(*) FILTER (WHERE results_count != -1),
          'zero_result_searches', SUM(CASE WHEN results_count=0 THEN 1 ELSE 0 END)
        ) AS sub
        FROM public.search_analytics
        WHERE created_at >= v_since
        GROUP BY search_term
        HAVING SUM(CASE WHEN results_count=0 THEN 1 ELSE 0 END) > 0
        ORDER BY SUM(CASE WHEN results_count=0 THEN 1 ELSE 0 END) DESC LIMIT 10
      ) x
    ), '[]'::jsonb),
    'period_days', p_days, 'generated_at', NOW()
  ) INTO v_insights;

  IF p_user_id IS NOT NULL THEN
    -- clock_timestamp() garante TTL preciso mesmo em chamadas múltiplas intra-transação
    INSERT INTO public.ai_insights_cache (
      user_id, function_name, cache_key, payload,
      model, duration_ms, created_at, expires_at
    ) VALUES (
      p_user_id, 'fn_generate_trends_insights', v_cache_key, v_insights,
      'postgres_aggregation', 0, clock_timestamp(), clock_timestamp() + INTERVAL '6 hours'
    )
    ON CONFLICT (user_id, function_name, cache_key)
    DO UPDATE SET payload=EXCLUDED.payload,
      created_at=clock_timestamp(), expires_at=clock_timestamp()+INTERVAL '6 hours';
  END IF;

  RETURN v_insights;

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'error', SQLERRM,
    'totals', jsonb_build_object(
      'views',0,'searches',0,'unique_terms',0,'unique_products',0,
      'views_growth_pct',null,'searches_growth_pct',null
    ),
    'top_products','[]'::jsonb,'top_searches','[]'::jsonb,
    'repressed_demand','[]'::jsonb,'period_days',p_days,'generated_at',NOW()
  );
END;
$function$;
;

-- <<< END 20260615184657_fix_ai_cache_clock_timestamp_precise_ttl.sql <<<

-- >>> BEGIN 20260615184745_fix_search_analytics_results_count_check_constraint.sql >>>

-- FIX B2: Adiciona CHECK CONSTRAINT que impede inserção de results_count
-- fora do range válido [-1, 2000].
--
-- Valores válidos:
--   -1   = marcador "too many results" (> 2000 sanitizado pela fn_log_search_analytics)
--    0   = busca sem resultados
--  1-2000 = count real de resultados
--
-- Qualquer valor > 2000 ou < -1 viola o contrato e é bloqueado na raiz.
-- fn_log_search_analytics já sanitiza p_results_count > 2000 → -1, portanto
-- inserções via RPC continuam funcionando sem mudança.
-- Inserções diretas via PostgREST com count bruto do catálogo (bug original) → BLOQUEADAS.
--
-- NULL é permitido (PostgreSQL: NULL satisfaz CHECK constraints por omissão).

ALTER TABLE public.search_analytics
  ADD CONSTRAINT chk_results_count_range
  CHECK (results_count IS NULL OR results_count BETWEEN -1 AND 2000);

COMMENT ON CONSTRAINT chk_results_count_range ON public.search_analytics IS
  'Garante que results_count seja NULL, -1 (anomalia), ou 0-2000 (count real). '
  'Valores > 2000 devem ser sanitizados para -1 pela fn_log_search_analytics antes da inserção.';
;

-- <<< END 20260615184745_fix_search_analytics_results_count_check_constraint.sql <<<

-- >>> BEGIN 20260615185337_fix_dashboard_insights_cache_drop_tokens_rebuild_view.sql >>>

-- FIX C2: Limpar schema dashboard_insights_cache + reconstruir view ai_insights_cache
--
-- Contexto: ai_insights_cache é uma VIEW sobre dashboard_insights_cache (tabela base).
-- A tabela base ainda tem tokens_input/tokens_output (colunas mortas sempre NULL).
-- A VIEW precisa ser dropada antes de alterar a tabela base; depois recriada sem as colunas.
-- Ordem: DROP VIEW → ALTER TABLE → CREATE VIEW (operação atômica dentro de 1 transação DDL).

-- Passo 1: remover a VIEW para liberar a dependência
DROP VIEW IF EXISTS public.ai_insights_cache;

-- Passo 2: dropar colunas mortas da tabela base
ALTER TABLE public.dashboard_insights_cache
  DROP COLUMN IF EXISTS tokens_input,
  DROP COLUMN IF EXISTS tokens_output;

-- Passo 3: recriar VIEW sem as colunas descontinuadas
-- Mantém ai_insights_cache como alias de backward-compatibility.
-- INSERT/UPDATE/ON CONFLICT funcionam através de VIEW simples no PostgreSQL 17.
CREATE VIEW public.ai_insights_cache AS
SELECT
  id,
  user_id,
  function_name,
  cache_key,
  payload,
  model,
  duration_ms,
  created_at,
  expires_at
FROM public.dashboard_insights_cache;

COMMENT ON VIEW public.ai_insights_cache IS
  'View de compatibilidade sobre dashboard_insights_cache. '
  'Mantém o nome original para que funções existentes não precisem ser alteradas. '
  'INSERT/ON CONFLICT roteados automaticamente para a tabela base pelo PostgreSQL.';
;

-- <<< END 20260615185337_fix_dashboard_insights_cache_drop_tokens_rebuild_view.sql <<<

-- >>> BEGIN 20260615190630_move_staging_tables_to_archive_schema.sql >>>

-- ============================================================
-- MIGRATION: move_staging_tables_to_archive_schema
-- ============================================================
-- Strategy : physical move to archive + forwarding auto-updatable
--            views in public (zero breaking change for 15+ fns)
-- Tables   : 5 (all staging)
-- Views    : 2 analytics (drop public → recreate in archive)
--            5 forwarding  (new in public, transparent aliases)
-- RLS      : policies move automatically with ALTER TABLE ... SET SCHEMA
-- PG17 note: FOR UPDATE SKIP LOCKED works through simple auto-updatable views
-- ============================================================

-- ── STEP 1: archive schema ────────────────────────────────────
CREATE SCHEMA IF NOT EXISTS archive;

GRANT USAGE ON SCHEMA archive
    TO postgres, anon, authenticated, service_role;

-- ── STEP 2: drop views that block ALTER TABLE ─────────────────
DROP VIEW IF EXISTS public.v_import_staging_by_product;
DROP VIEW IF EXISTS public.v_import_staging_progress;

-- ── STEP 3: physical move ─────────────────────────────────────
-- (RLS policies, indexes, sequences, constraints migrate with the table)
ALTER TABLE public.color_analysis_staging  SET SCHEMA archive;
ALTER TABLE public.import_staging_images   SET SCHEMA archive;
ALTER TABLE public.scraper_images_staging  SET SCHEMA archive;
ALTER TABLE public.sm_images_staging       SET SCHEMA archive;
ALTER TABLE public.xbz_gallery_staging     SET SCHEMA archive;

-- ── STEP 4: permissions on archive tables ────────────────────
GRANT ALL ON archive.color_analysis_staging  TO service_role;
GRANT ALL ON archive.import_staging_images   TO service_role;
GRANT ALL ON archive.scraper_images_staging  TO service_role;
GRANT ALL ON archive.sm_images_staging       TO service_role;
GRANT ALL ON archive.xbz_gallery_staging     TO service_role;

GRANT SELECT ON archive.color_analysis_staging  TO authenticated, anon;
GRANT SELECT ON archive.import_staging_images   TO authenticated, anon;
GRANT SELECT ON archive.scraper_images_staging  TO authenticated, anon;
GRANT SELECT ON archive.sm_images_staging       TO authenticated, anon;
GRANT SELECT ON archive.xbz_gallery_staging     TO authenticated, anon;

-- ── STEP 5: auto-updatable forwarding views in public ─────────
-- Simple SELECT * → qualifies as auto-updatable in PG:
-- supports INSERT / UPDATE / DELETE / ON CONFLICT / FOR UPDATE SKIP LOCKED
CREATE VIEW public.color_analysis_staging AS
    SELECT * FROM archive.color_analysis_staging;

CREATE VIEW public.import_staging_images AS
    SELECT * FROM archive.import_staging_images;

CREATE VIEW public.scraper_images_staging AS
    SELECT * FROM archive.scraper_images_staging;

CREATE VIEW public.sm_images_staging AS
    SELECT * FROM archive.sm_images_staging;

CREATE VIEW public.xbz_gallery_staging AS
    SELECT * FROM archive.xbz_gallery_staging;

-- Audit comments
COMMENT ON VIEW public.color_analysis_staging IS
    '[ARCHIVED] forwarding view → archive.color_analysis_staging — do not add columns here';
COMMENT ON VIEW public.import_staging_images IS
    '[ARCHIVED] forwarding view → archive.import_staging_images — do not add columns here';
COMMENT ON VIEW public.scraper_images_staging IS
    '[ARCHIVED] forwarding view → archive.scraper_images_staging — do not add columns here';
COMMENT ON VIEW public.sm_images_staging IS
    '[ARCHIVED] forwarding view → archive.sm_images_staging — do not add columns here';
COMMENT ON VIEW public.xbz_gallery_staging IS
    '[ARCHIVED] forwarding view → archive.xbz_gallery_staging — do not add columns here';

-- ── STEP 6: permissions on forwarding views ───────────────────
GRANT SELECT ON public.color_analysis_staging  TO authenticated, anon;
GRANT SELECT ON public.import_staging_images   TO authenticated, anon;
GRANT SELECT ON public.scraper_images_staging  TO authenticated, anon;
GRANT SELECT ON public.sm_images_staging       TO authenticated, anon;
GRANT SELECT ON public.xbz_gallery_staging     TO authenticated, anon;

-- ── STEP 7: analytics views recreated in archive ─────────────
-- (reference archive.import_staging_images now)
CREATE VIEW archive.v_import_staging_by_product AS
    SELECT
        s.parsed_sku,
        p.name AS product_name,
        count(*)                                                    AS total_images,
        count(*) FILTER (WHERE s.status::text = 'completed')       AS completed,
        count(*) FILTER (WHERE s.status::text = 'pending')         AS pending,
        count(*) FILTER (WHERE s.status::text = ANY (
            ARRAY['upload_error'::varchar,'insert_error'::varchar]::text[]
        ))                                                          AS errors,
        count(*) FILTER (WHERE s.status::text = 'already_exists')  AS already_exists
    FROM archive.import_staging_images s
    LEFT JOIN public.products p ON s.product_id = p.id
    GROUP BY s.parsed_sku, p.name
    ORDER BY count(*) DESC;

CREATE VIEW archive.v_import_staging_progress AS
    SELECT
        status,
        count(*) AS total,
        round((count(*)::numeric * 100.0) / sum(count(*)) OVER (), 2) AS percentual
    FROM archive.import_staging_images
    GROUP BY status
    ORDER BY
        CASE status
            WHEN 'completed'     THEN 1
            WHEN 'uploaded'      THEN 2
            WHEN 'extracted'     THEN 3
            WHEN 'pending'       THEN 4
            WHEN 'already_exists'THEN 5
            WHEN 'no_product'    THEN 6
            WHEN 'no_color'      THEN 7
            WHEN 'upload_error'  THEN 8
            WHEN 'insert_error'  THEN 9
            WHEN 'skipped'       THEN 10
            ELSE NULL::integer
        END;

GRANT SELECT ON archive.v_import_staging_by_product TO authenticated, anon, service_role;
GRANT SELECT ON archive.v_import_staging_progress   TO authenticated, anon, service_role;

-- ── STEP 8: PostgREST schema reload ──────────────────────────
NOTIFY pgrst, 'reload schema';
;

-- <<< END 20260615190630_move_staging_tables_to_archive_schema.sql <<<

-- >>> BEGIN 20260615191757_drop_dead_staging_forwarding_views_public.sql >>>

-- Remove forwarding views de public para as 3 tabelas mortas do Grupo 1.
-- As tabelas continuam intactas em archive.* — só limpamos a "janela" pública desnecessária.
DROP VIEW IF EXISTS public.color_analysis_staging;
DROP VIEW IF EXISTS public.import_staging_images;
DROP VIEW IF EXISTS public.scraper_images_staging;
;

-- <<< END 20260615191757_drop_dead_staging_forwarding_views_public.sql <<<

-- >>> BEGIN 20260615191907_restore_grupo2_staging_to_public.sql >>>

-- Remove forwarding views e devolve as tabelas físicas para public
DROP VIEW IF EXISTS public.sm_images_staging;
DROP VIEW IF EXISTS public.xbz_gallery_staging;

ALTER TABLE archive.sm_images_staging  SET SCHEMA public;
ALTER TABLE archive.xbz_gallery_staging SET SCHEMA public;

NOTIFY pgrst, 'reload schema';
;

-- <<< END 20260615191907_restore_grupo2_staging_to_public.sql <<<

-- >>> BEGIN 20260615200001_doc_admin_settings_comment_on_table_and_columns.sql >>>
-- ============================================================
-- MIGRATION: doc_admin_settings_comment_on_table_and_columns
-- Objetivo : Documentar propósito, estado, chaves conhecidas
--            e descrição de cada coluna de admin_settings.
-- Data     : 2026-06-15
-- Branch   : chore/admin-settings-hardening
-- Melhoria : #1 de 4 — COMMENT ON TABLE + COMMENT ON COLUMNS
-- ============================================================

-- ----------------------------------------------------------
-- 1. COMENTÁRIO NA TABELA
-- ----------------------------------------------------------
COMMENT ON TABLE public.admin_settings IS
'Key-value store de configurações globais do painel admin.
Padrão: 1 linha por configuração, chave única, valor em JSONB livre.
Criada em 20260514 (migration t39_create_missing_tables_part3).

PROPÓSITO:
  Persistir preferências e parâmetros configuráveis pelo admin
  que precisam ser compartilhados entre máquinas sem necessidade
  de deploy. Todos os admins leem/escrevem o mesmo valor.

CONSUMIDORES (frontend — src/hooks/admin/):
  useRetestCooldownSetting.ts
    chave: retest_cooldown | valor: { ms: number }
    uso  : cooldown em ms do botão Testar novamente nos cards de
           conexão de fornecedores. Default: 3000. Presets: [3000,10000,30000,60000].

  useIntelligenceBadgeSettings.ts
    chave: intelligence_badges
    valor: { hotItem:{enabled:bool}, bestSeller:{enabled:bool, minAvgDailyDepletion7d:number} }
    uso  : liga/desliga badges Hot Item e Best-seller no ProductCard.
           Default: hotItem enabled=true, bestSeller enabled=true threshold=15.

PADRÃO DE ACESSO (ambos os hooks):
  Leitura : supabase.from(admin_settings).select(value).eq(key,KEY).maybeSingle()
  Gravação: supabase.from(admin_settings).upsert({key,value},{onConflict:key})
  Cache module-level + broadcast pattern — fetch único por sessão por chave.

RLS:
  SELECT/INSERT/UPDATE → authenticated com has_role(uid, admin)
  DELETE               → sem policy (bloqueado implicitamente pelo RLS)
  anon                 → sem GRANT

INFRAESTRUTURA:
  Trigger: update_admin_settings_updated_at → BEFORE UPDATE → update_updated_at_column()
  FK em updated_by: pendente (melhoria #3)
  Nenhuma função Postgres acessa esta tabela — só frontend.
  Nenhuma view depende desta tabela.

ESTADO: 0 linhas (2026-06-15) — admins usando defaults do frontend.
NÃO ARQUIVAR / NÃO DROPAR — tabela ativa com consumidores no frontend.';

-- ----------------------------------------------------------
-- 2. COMENTÁRIOS NAS COLUNAS
-- ----------------------------------------------------------
COMMENT ON COLUMN public.admin_settings.id IS
'PK UUID. Gerado automaticamente (gen_random_uuid()). Chave técnica — não exposta no frontend.';

COMMENT ON COLUMN public.admin_settings.key IS
'Chave identificadora única da configuração (NOT NULL UNIQUE).
Convenção: snake_case, descritivo do domínio.
Chaves registradas (2026-06-15):
  retest_cooldown    → useRetestCooldownSetting.ts
  intelligence_badges → useIntelligenceBadgeSettings.ts
Ao criar nova chave: documentar aqui e no hook correspondente.';

COMMENT ON COLUMN public.admin_settings.value IS
'Payload JSONB da configuração (NOT NULL, default {}).
Schema livre — cada chave define o próprio shape.
Shapes conhecidos:
  retest_cooldown    → { ms: number }
  intelligence_badges → { hotItem:{enabled:bool}, bestSeller:{enabled:bool, minAvgDailyDepletion7d:number} }
Sempre sanitizar/validar no frontend antes de usar (hooks têm função sanitize()).';

COMMENT ON COLUMN public.admin_settings.updated_by IS
'UUID do admin que realizou a última alteração. Nullable.
NULL quando criado pelo sistema ou quando o frontend não envia o campo.
Sem FK formal para auth.users — a adicionar em melhoria #3.
Hooks atuais (useRetestCooldownSetting, useIntelligenceBadgeSettings) não setam este campo.';

COMMENT ON COLUMN public.admin_settings.created_at IS
'Timestamp de criação da linha. Auto-preenchido (DEFAULT now()). Imutável após INSERT.';

COMMENT ON COLUMN public.admin_settings.updated_at IS
'Timestamp da última atualização. Auto-atualizado pelo trigger
update_admin_settings_updated_at (BEFORE UPDATE → update_updated_at_column()).
Igual a created_at enquanto a linha não for alterada após INSERT.';

-- <<< END 20260615200001_doc_admin_settings_comment_on_table_and_columns.sql <<<

-- >>> BEGIN 20260615200002_sec_admin_settings_revoke_delete_authenticated.sql >>>
-- ============================================================
-- MIGRATION: sec_admin_settings_revoke_delete_authenticated
-- Objetivo : Revogar GRANT DELETE de authenticated em admin_settings.
-- Data     : 2026-06-15
-- Branch   : chore/admin-settings-hardening
-- Melhoria : #2 de 4 — Higiene de grants (princípio menor privilégio)
--
-- CONTEXTO:
--   A tabela admin_settings tem GRANT DELETE para authenticated
--   mas NÃO tem policy RLS para DELETE. Isso significa que:
--   (a) Nenhum usuário consegue deletar linhas (RLS bloqueia — correto)
--   (b) O GRANT existe porém é inútil e enganoso
--   Violação do princípio do menor privilégio: não deve existir
--   GRANT sem a intenção real de permitir a operação.
--
-- IMPACTO:
--   Frontend : 0 impacto — nenhum hook chama DELETE nesta tabela.
--   Backend  : 0 impacto — nenhuma função Postgres usa DELETE aqui.
--   service_role: 0 impacto — bypassa RLS e não precisa do GRANT.
--   Segurança: melhora a postura — grant fantasma removido.
--
-- REVERSÃO (se necessário):
--   GRANT DELETE ON public.admin_settings TO authenticated;
-- ============================================================

-- Remover o GRANT DELETE do role authenticated
REVOKE DELETE ON public.admin_settings FROM authenticated;

-- <<< END 20260615200002_sec_admin_settings_revoke_delete_authenticated.sql <<<

-- >>> BEGIN 20260615200003_fk_admin_settings_updated_by_auth_users.sql >>>
-- ============================================================
-- MIGRATION: fk_admin_settings_updated_by_auth_users
-- Objetivo : Adicionar FK updated_by → auth.users(id) ON DELETE SET NULL
-- Data     : 2026-06-15
-- Branch   : chore/admin-settings-hardening
-- Melhoria : #3 de 4 — Integridade referencial do campo updated_by
--
-- CONTEXTO:
--   admin_settings.updated_by é uuid nullable sem FK.
--   Qualquer UUID (mesmo inválido) pode ser gravado, sem validação.
--   Ao adicionar FK: banco garante que updated_by referencia um
--   usuário real em auth.users.
--
-- ON DELETE SET NULL:
--   Se o usuário admin for deletado do sistema, updated_by vira NULL
--   automaticamente — a linha de configuração sobrevive intacta.
--   Sem ON DELETE SET NULL, a deleção do usuário falharia por FK
--   violação (comportamento indesejável para um campo de auditoria).
--
-- PRÉ-CONDIÇÕES VERIFICADAS:
--   rows_in_table = 0  (sem risco de violação retroativa)
--   auth.users existe (schema auth, relname users)
--   Nenhuma FK existente com este nome
--
-- IMPACTO:
--   Frontend: 0 — hooks não setam updated_by (campo fica NULL)
--   Backend : 0 — nenhuma função grafa nesta coluna
--   Futuro  : se alguém setar updated_by, precisa ser UUID válido
--
-- REVERSÃO (se necessário):
--   ALTER TABLE public.admin_settings DROP CONSTRAINT fk_admin_settings_updated_by;
-- ============================================================

ALTER TABLE public.admin_settings
    ADD CONSTRAINT fk_admin_settings_updated_by
    FOREIGN KEY (updated_by)
    REFERENCES auth.users(id)
    ON DELETE SET NULL;

-- <<< END 20260615200003_fk_admin_settings_updated_by_auth_users.sql <<<

-- >>> BEGIN 20260615200004_fix_admin_settings_trigger_canonical_set_updated_at.sql >>>
-- ============================================================
-- MIGRATION: fix_admin_settings_trigger_canonical_set_updated_at
-- Objetivo : Padronizar trigger updated_at de admin_settings para
--            usar set_updated_at() — função canônica do projeto
--            (usada por 66 tabelas vs 29 que ainda usam o legado).
-- Data     : 2026-06-15
-- Branch   : chore/admin-settings-hardening
-- Melhoria : #4 de 4 — Consistência arquitetural de triggers
--
-- CONTEXTO:
--   O projeto tem 2 funções trigger semanticamente idênticas:
--     set_updated_at()           → canônica (66 tabelas)
--     update_updated_at_column() → legada   (29 tabelas, inclui admin_settings)
--   Ambas executam exatamente: NEW.updated_at = NOW(); RETURN NEW;
--   Nenhuma diferença funcional — apenas histórica.
--   admin_settings usa a legada. Esta migration corrige isso.
--
-- IMPACTO:
--   Comportamento de updated_at: IDÊNTICO (mesma lógica)
--   Frontend: 0 impacto
--   Backend : 0 impacto
--   Trigger antigo é descartado e substituído — sem sobreposição.
--
-- REVERSÃO (se necessário):
--   DROP TRIGGER IF EXISTS trg_admin_settings_set_updated_at ON public.admin_settings;
--   CREATE TRIGGER update_admin_settings_updated_at
--     BEFORE UPDATE ON public.admin_settings
--     FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
-- ============================================================

-- 1. Remover o trigger legado
DROP TRIGGER IF EXISTS update_admin_settings_updated_at ON public.admin_settings;

-- 2. Criar o trigger canônico com nomenclatura padronizada
CREATE TRIGGER trg_admin_settings_set_updated_at
    BEFORE UPDATE ON public.admin_settings
    FOR EACH ROW
    EXECUTE FUNCTION public.set_updated_at();

-- <<< END 20260615200004_fix_admin_settings_trigger_canonical_set_updated_at.sql <<<

-- >>> BEGIN 20260615200005_fix_admin_settings_check_key_not_empty.sql >>>
-- ============================================================
-- MIGRATION: fix_admin_settings_check_key_not_empty
-- Objetivo : Adicionar CHECK CONSTRAINT que impede key vazia ou
--            com apenas espaços em branco.
-- Data     : 2026-06-15
-- Branch   : chore/admin-settings-hardening
-- Origem   : Gap detectado em bateria de testes exaustiva (7.01/7.06)
--
-- PROBLEMA:
--   Coluna key é text NOT NULL mas sem CHECK CONSTRAINT.
--   key = '' ou key = '   ' seriam aceitas pelo banco.
--   Um hook que gravasse key='' criaria uma linha inacessível
--   pelos hooks reais (que usam key nomeado como 'retest_cooldown').
--
-- SOLUÇÃO:
--   CHECK (trim(key) <> '') — bloqueia vazio, só-espaços e NULL
--   (NULL já é bloqueado pelo NOT NULL, mas o CHECK é defensivo)
--
-- IMPACTO:
--   Frontend: 0 — hooks usam chaves nomeadas tipo 'retest_cooldown'
--   Backend : 0 — nenhuma função grava key vazia
--   Tabela  : 0 rows — sem violação retroativa
--
-- REVERSÃO (se necessário):
--   ALTER TABLE public.admin_settings DROP CONSTRAINT chk_admin_settings_key_not_empty;
-- ============================================================

ALTER TABLE public.admin_settings
    ADD CONSTRAINT chk_admin_settings_key_not_empty
    CHECK (trim(key) <> '');

-- <<< END 20260615200005_fix_admin_settings_check_key_not_empty.sql <<<

-- >>> BEGIN 20260615201651_align_xbz_staging_schema_part1_ddl_data.sql >>>

-- ═══════════════════════════════════════════════════════════════
-- PARTE 1: DDL + DADOS + CONSTRAINTS
-- ═══════════════════════════════════════════════════════════════

-- STEP 1: deduplicar antes de adicionar unique constraint
-- mantém: cf_id preenchido > updated_at mais recente
DELETE FROM public.xbz_gallery_staging
WHERE id IN (
    SELECT id FROM (
        SELECT id,
            ROW_NUMBER() OVER (
                PARTITION BY codigo_amigavel, url_original
                ORDER BY cloudflare_image_id NULLS LAST, updated_at DESC
            ) AS rn
        FROM public.xbz_gallery_staging
    ) t WHERE rn > 1
);

-- STEP 2: adicionar colunas SM (nullable primeiro)
ALTER TABLE public.xbz_gallery_staging
    ADD COLUMN IF NOT EXISTS variant_id       uuid,
    ADD COLUMN IF NOT EXISTS supplier_id      uuid,
    ADD COLUMN IF NOT EXISTS image_slug       text,
    ADD COLUMN IF NOT EXISTS image_id_site    integer,
    ADD COLUMN IF NOT EXISTS image_type       text,
    ADD COLUMN IF NOT EXISTS is_primary       boolean,
    ADD COLUMN IF NOT EXISTS display_order    integer,
    ADD COLUMN IF NOT EXISTS source           text,
    ADD COLUMN IF NOT EXISTS uploaded_at      timestamptz,
    ADD COLUMN IF NOT EXISTS product_image_id uuid,
    ADD COLUMN IF NOT EXISTS populated_at     timestamptz,
    ADD COLUMN IF NOT EXISTS partition_id     integer,
    ADD COLUMN IF NOT EXISTS retry_count      integer,
    ADD COLUMN IF NOT EXISTS cf_custom_id     text,
    ADD COLUMN IF NOT EXISTS cf_filename      text;

-- STEP 3: popular colunas novas a partir dos dados existentes
UPDATE public.xbz_gallery_staging SET
    supplier_id      = 'd6718a29-e954-4c1b-bd84-03ea24884900'::uuid,
    image_type       = CASE WHEN d_number = 1 THEN 'main' ELSE 'gallery' END,
    is_primary       = (d_number = 1),
    display_order    = d_number - 1,
    source           = 'site',
    cf_custom_id     = cloudflare_image_id,
    cf_filename      = cloudflare_image_id || '.jpg',
    populated_at     = created_at,
    retry_count      = 0,
    uploaded_at      = CASE WHEN status = 'uploaded' THEN updated_at ELSE NULL END,
    image_slug       = lower(regexp_replace(
                           regexp_replace(coalesce(cloudflare_image_id,''), '^xbz-', ''),
                           '-\d{2}$', ''));

-- product_image_id: link via cloudflare_image_id → product_images
UPDATE public.xbz_gallery_staging xgs
SET    product_image_id = pi.id
FROM   public.product_images pi
WHERE  pi.cloudflare_image_id = xgs.cloudflare_image_id
  AND  xgs.product_image_id IS NULL;

-- STEP 4: migrar status para nomenclatura SM
UPDATE public.xbz_gallery_staging SET status = 'pending'   WHERE status = 'discovered';
UPDATE public.xbz_gallery_staging SET status = 'uploading' WHERE status = 'downloaded';

-- STEP 5: renomear colunas operacionais
ALTER TABLE public.xbz_gallery_staging RENAME COLUMN codigo_amigavel TO sku;
ALTER TABLE public.xbz_gallery_staging RENAME COLUMN url_original    TO source_url;
ALTER TABLE public.xbz_gallery_staging RENAME COLUMN url_cdn         TO cloudflare_url;

-- STEP 6: NOT NULL + defaults nas novas colunas
ALTER TABLE public.xbz_gallery_staging
    ALTER COLUMN supplier_id   SET NOT NULL,
    ALTER COLUMN supplier_id   SET DEFAULT 'd6718a29-e954-4c1b-bd84-03ea24884900'::uuid,
    ALTER COLUMN image_type    SET NOT NULL,
    ALTER COLUMN image_type    SET DEFAULT 'gallery',
    ALTER COLUMN is_primary    SET NOT NULL,
    ALTER COLUMN is_primary    SET DEFAULT false,
    ALTER COLUMN display_order SET NOT NULL,
    ALTER COLUMN display_order SET DEFAULT 0,
    ALTER COLUMN source        SET NOT NULL,
    ALTER COLUMN source        SET DEFAULT 'site',
    ALTER COLUMN retry_count   SET NOT NULL,
    ALTER COLUMN retry_count   SET DEFAULT 0,
    ALTER COLUMN status        SET DEFAULT 'pending';

-- STEP 7: constraints
ALTER TABLE public.xbz_gallery_staging
    DROP CONSTRAINT IF EXISTS uq_staging_codigo_d;

ALTER TABLE public.xbz_gallery_staging
    ADD CONSTRAINT uq_xbz_staging_sku_source_url UNIQUE (sku, source_url);

ALTER TABLE public.xbz_gallery_staging
    ADD CONSTRAINT uq_xbz_staging_cf_id UNIQUE (cf_custom_id);

CREATE INDEX IF NOT EXISTS idx_xbz_staging_status
    ON public.xbz_gallery_staging (status, created_at);
;

