-- >>> BEGIN 20260615230004_image_type_deprecation_guardrails_and_tracker.sql >>>
-- (1) Comentário com o RAIO DE IMPACTO explícito — para impedir DROP cego (inclusive futuro)
COMMENT ON COLUMN public.product_images.image_type IS
  'DEPRECADO 19/01/2026 — Use image_type_id (FK image_types). NÃO DROPAR ainda: '
  'coluna referenciada por dezenas de funções (pipeline de ingestão dos 5 fornecedores) '
  'e views/matviews (inclui mv_product_cards). Dados 100% consistentes com image_type_id. '
  'Drop seguro só após zerar vw_image_type_dropblockers.';

-- (2) Artefato rastreável: lista viva de tudo que ainda trava o DROP, classificado por risco.
--     Views/matviews = bloqueadores de DDL (CASCADE/RESTRICT). Funções = risco de runtime (plpgsql late-bound).
CREATE OR REPLACE VIEW public.vw_image_type_dropblockers AS
SELECT 'view_ddl_blocker'::text AS risco,
       dependent.relkind::text   AS kind,
       dependent.relname         AS objeto
FROM pg_class dependent
JOIN pg_namespace dn ON dn.oid = dependent.relnamespace
WHERE dependent.relkind IN ('v','m')
  AND dn.nspname = 'public'
  AND pg_get_viewdef(dependent.oid) ~ '\mimage_type\M'
UNION ALL
SELECT 'function_runtime_risk', 'f', p.proname
FROM pg_proc p
JOIN pg_namespace n ON n.oid = p.pronamespace
WHERE n.nspname = 'public'
  AND pg_get_functiondef(p.oid) ~ '\mimage_type\M';

COMMENT ON VIEW public.vw_image_type_dropblockers IS
  'Rastreador da migração image_type→image_type_id. Quando retornar 0 linhas, a coluna image_type pode ser dropada com segurança.';;

-- <<< END 20260615230004_image_type_deprecation_guardrails_and_tracker.sql <<<

-- >>> BEGIN 20260615230501_product_images_format_canonical_guard.sql >>>
-- ============================================================================
-- product_images :: blindagem do campo `format`  (Migration 1/5)
-- ----------------------------------------------------------------------------
-- Contexto: o campo `format` convivia com casing inconsistente (JPEG/jpg/PNG).
-- Um job de ingestão autoritativo já normaliza valores em runtime; esta migration
-- adiciona a GUARDA de escrita + o INVARIANTE de minúsculo, sem enumerar formatos
-- (não quebra avif/jxl futuros nem o job vivo).
-- Idempotente.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_normalize_image_format()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  IF NEW.format IS NOT NULL THEN
    NEW.format := lower(btrim(NEW.format));
    -- canonicaliza a variação mais comum
    IF NEW.format = 'jpg'  THEN NEW.format := 'jpeg'; END IF;
    -- remove eventual prefixo mime ("image/png" -> "png")
    IF position('/' in NEW.format) > 0 THEN
      NEW.format := split_part(NEW.format, '/', 2);
    END IF;
    IF NEW.format = '' THEN NEW.format := NULL; END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_normalize_image_format ON public.product_images;
CREATE TRIGGER trg_normalize_image_format
  BEFORE INSERT OR UPDATE OF format ON public.product_images
  FOR EACH ROW EXECUTE FUNCTION public.fn_normalize_image_format();

-- CHECK do invariante (lowercase alfanumérico). NOT VALID + VALIDATE = online.
ALTER TABLE public.product_images
  DROP CONSTRAINT IF EXISTS chk_product_images_format_lc;
ALTER TABLE public.product_images
  ADD CONSTRAINT chk_product_images_format_lc
  CHECK (format IS NULL OR format ~ '^[a-z0-9]+$') NOT VALID;
ALTER TABLE public.product_images
  VALIDATE CONSTRAINT chk_product_images_format_lc;

-- <<< END 20260615230501_product_images_format_canonical_guard.sql <<<

-- >>> BEGIN 20260615230502_product_images_assert_secure_select_rls.sql >>>
-- ============================================================================
-- product_images :: re-afirmar baseline seguro de leitura (RLS)  (Migration 2/5)
-- ----------------------------------------------------------------------------
-- O ambiente (Lovable/jobs) já removeu a policy permissiva `*_anon_select USING(true)`
-- que permitia ao papel anônimo ler imagens inativas. Esta migration é DEFENSIVA e
-- idempotente: neutraliza a policy permissiva caso ela ressurja e fixa
-- `product_images_select` na forma canônica segura.
--   - anônimo: vê apenas is_active = true
--   - autenticado: vê tudo
--   - escrita (INSERT/UPDATE/DELETE): restrita a org owner/admin (policies já existentes)
-- ============================================================================

DROP POLICY IF EXISTS product_images_anon_select ON public.product_images;

DROP POLICY IF EXISTS product_images_select ON public.product_images;
CREATE POLICY product_images_select ON public.product_images
  FOR SELECT
  TO public
  USING ((is_active = true) OR ((SELECT auth.uid()) IS NOT NULL));

-- <<< END 20260615230502_product_images_assert_secure_select_rls.sql <<<

-- >>> BEGIN 20260615230503_product_images_sync_image_type_code.sql >>>
-- ============================================================================
-- product_images :: coerência image_type (texto) <-> image_type_id (FK)  (Migration 3/5)
-- ----------------------------------------------------------------------------
-- O classificador (fn_auto_classify_product_image) define ambos no INSERT, mas um
-- UPDATE que altere SOMENTE image_type_id deixaria o texto defasado (drift).
-- Este guard mantém image_type derivado da FK (fonte da verdade), alinhado ao
-- COALESCE(it.code, pi.image_type) usado pela view v_product_images_cdn.
-- Drift medido na introdução = 0; guard é preventivo. Dispara só em UPDATE OF image_type_id.
-- Idempotente.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_sync_image_type_code()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
DECLARE
  v_code text;
BEGIN
  IF NEW.image_type_id IS NOT NULL THEN
    SELECT code INTO v_code FROM image_types WHERE id = NEW.image_type_id;
    IF v_code IS NOT NULL THEN
      NEW.image_type := v_code;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_image_type_code ON public.product_images;
CREATE TRIGGER trg_sync_image_type_code
  BEFORE UPDATE OF image_type_id ON public.product_images
  FOR EACH ROW EXECUTE FUNCTION public.fn_sync_image_type_code();

-- <<< END 20260615230503_product_images_sync_image_type_code.sql <<<

-- >>> BEGIN 20260615230504_product_images_observability_and_resync.sql >>>
-- ============================================================================
-- product_images :: observabilidade de qualidade + resync set-based  (Migration 4/5)
-- ----------------------------------------------------------------------------
-- (1) View de monitoramento dos gaps de metadados por fornecedor.
-- (2) fn_resync_product_media(): recomputa, em UMA passada set-based, os campos
--     desnormalizados de `products` (images, og_image_url, primary_image_url,
--     primary_image_fallback_url, set_image_url). Replica a lógica de
--     fn_sync_product_images_to_products + fn_sync_set_image_url. Uso: cargas em
--     massa podem desabilitar os triggers AFTER por-linha e chamar isto 1x no fim,
--     eliminando a amplificação de escrita (N updates em products -> 1).
-- NOTA: a versão DETERMINÍSTICA final está na migration 20260615230505.
-- ============================================================================

-- (1) Observabilidade -------------------------------------------------------
CREATE OR REPLACE VIEW public.v_product_images_quality_gap
WITH (security_invoker = true) AS
SELECT
  source_supplier,
  count(*)                                                         AS total,
  count(*) FILTER (WHERE is_active)                                AS ativas,
  count(*) FILTER (WHERE width_px IS NULL OR height_px IS NULL)    AS sem_dimensoes,
  count(*) FILTER (WHERE format IS NULL)                           AS sem_format,
  count(*) FILTER (WHERE file_size_bytes IS NULL)                  AS sem_file_size,
  count(*) FILTER (WHERE alt_text IS NULL)                         AS sem_alt,
  round(100.0 * count(*) FILTER (WHERE width_px IS NULL)
        / nullif(count(*), 0), 2)                                  AS pct_sem_dimensoes
FROM public.product_images
GROUP BY source_supplier;

-- (2) Resync set-based (versão inicial; substituída pela determinística) -----
CREATE OR REPLACE FUNCTION public.fn_resync_product_media(p_product_ids uuid[] DEFAULT NULL)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_count integer;
BEGIN
  WITH targets AS (
    SELECT p.id FROM products p
    WHERE p_product_ids IS NULL OR p.id = ANY(p_product_ids)
  ),
  agg AS (
    SELECT t.id AS product_id,
      COALESCE((
        SELECT jsonb_agg(url_cdn ORDER BY
          CASE WHEN image_type='main' AND is_primary THEN 0
               WHEN image_type='main' THEN 1
               WHEN image_type IN ('gallery','product') THEN 2
               WHEN image_type='ambient' THEN 3
               WHEN image_type='set' THEN 4
               WHEN image_type='logo' THEN 5 ELSE 9 END,
          is_primary DESC, display_order ASC NULLS LAST)
          FILTER (WHERE image_type NOT IN ('box','pouch','location','area','component'))
        FROM product_images WHERE product_id=t.id AND is_active), '[]'::jsonb) AS images,
      ( SELECT url_cdn FROM product_images
        WHERE product_id=t.id AND is_active
          AND image_type NOT IN ('box','pouch','location','area','component')
        ORDER BY CASE WHEN is_og_image THEN 0
                      WHEN image_type='main' AND is_primary THEN 1
                      WHEN image_type='main' THEN 2
                      WHEN image_type IN ('gallery','product') THEN 3
                      WHEN image_type='ambient' THEN 4
                      WHEN image_type='set' THEN 5 ELSE 9 END,
                 is_primary DESC, display_order ASC NULLS LAST LIMIT 1) AS og_url,
      ( SELECT url_cdn FROM product_images
        WHERE product_id=t.id AND is_active
          AND image_type NOT IN ('box','pouch','location','area','component')
        ORDER BY CASE WHEN image_type='main' AND is_primary THEN 0
                      WHEN image_type='main' THEN 1
                      WHEN image_type IN ('gallery','product') AND is_primary THEN 2
                      WHEN image_type IN ('gallery','product') THEN 3
                      WHEN image_type='ambient' THEN 4
                      WHEN image_type='set' AND is_primary THEN 5
                      WHEN image_type='set' THEN 6
                      WHEN image_type='logo' THEN 7 ELSE 9 END,
                 is_primary DESC, display_order ASC NULLS LAST LIMIT 1) AS primary_url,
      ( SELECT url_original FROM product_images
        WHERE product_id=t.id AND is_active AND url_original IS NOT NULL AND url_original<>''
        ORDER BY CASE WHEN image_type='main' AND is_primary THEN 0
                      WHEN image_type='main' THEN 1
                      WHEN image_type IN ('gallery','product') AND is_primary THEN 2
                      WHEN image_type IN ('gallery','product') THEN 3
                      WHEN image_type='ambient' THEN 4
                      WHEN image_type='set' AND is_primary THEN 5
                      WHEN image_type='set' THEN 6
                      WHEN image_type='logo' THEN 7 ELSE 9 END,
                 is_primary DESC, display_order ASC NULLS LAST LIMIT 1) AS fallback_url,
      ( SELECT url_cdn FROM product_images
        WHERE product_id=t.id AND is_active AND image_type='set'
        ORDER BY display_order ASC, created_at ASC LIMIT 1) AS set_url
    FROM targets t
  )
  UPDATE products p SET
    images                     = agg.images,
    og_image_url               = agg.og_url,
    primary_image_url          = agg.primary_url,
    primary_image_fallback_url = agg.fallback_url,
    set_image_url              = agg.set_url
  FROM agg WHERE p.id = agg.product_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

