-- >>> BEGIN 20260615232612_create_fn_resync_product_image_urls.sql >>>

-- ============================================================
-- FIX 9: Função para re-sincronizar manualmente os campos de imagem
-- em products a partir de product_images.
-- Útil quando o trigger falha, produto é importado sem imagens e depois
-- recebe imagens sem disparar o trigger correto, ou para correção em lote.
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_resync_product_image_urls(
  p_product_ids UUID[] DEFAULT NULL,   -- NULL = todos os produtos
  p_force       BOOLEAN DEFAULT FALSE  -- FALSE = só atualiza se URL está desatualizada
)
RETURNS TABLE (
  product_id      UUID,
  action          TEXT,
  primary_url_set TEXT,
  og_url_set      TEXT,
  images_count    INTEGER
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_product_id UUID;
  v_new_primary_url TEXT;
  v_new_og_url TEXT;
  v_new_fallback_url TEXT;
  v_new_set_url TEXT;
  v_new_images JSONB;
  v_images_count INTEGER;
  v_old_primary_url TEXT;
BEGIN
  -- Iterar sobre os produtos selecionados (ou todos)
  FOR v_product_id IN
    SELECT p.id
    FROM public.products p
    WHERE (p_product_ids IS NULL OR p.id = ANY(p_product_ids))
      AND p.is_active = true
    ORDER BY p.id
  LOOP
    -- Buscar primary_url atual para comparação
    SELECT primary_image_url INTO v_old_primary_url
    FROM public.products WHERE id = v_product_id;

    -- Calcular nova primary_image_url
    SELECT url_cdn INTO v_new_primary_url
    FROM public.product_images
    WHERE product_id = v_product_id AND is_active = true
      AND image_type NOT IN ('box','pouch','location','area','component')
    ORDER BY
      CASE
        WHEN image_type = 'main'    AND is_primary = true  THEN 0
        WHEN image_type = 'main'                           THEN 1
        WHEN image_type IN ('gallery','product') AND is_primary = true THEN 2
        WHEN image_type IN ('gallery','product')           THEN 3
        WHEN image_type = 'ambient'                        THEN 4
        WHEN image_type = 'set'    AND is_primary = true  THEN 5
        WHEN image_type = 'set'                            THEN 6
        WHEN image_type = 'logo'                           THEN 7
        ELSE 9
      END,
      is_primary DESC, display_order ASC NULLS LAST
    LIMIT 1;

    -- Pular se não forçado e URL não mudou
    IF NOT p_force AND v_new_primary_url IS NOT DISTINCT FROM v_old_primary_url THEN
      CONTINUE;
    END IF;

    -- Calcular og_image_url
    SELECT url_cdn INTO v_new_og_url
    FROM public.product_images
    WHERE product_id = v_product_id AND is_active = true
      AND image_type NOT IN ('box','pouch','location','area','component')
    ORDER BY
      CASE WHEN is_og_image = true                       THEN 0
           WHEN image_type = 'main' AND is_primary = true THEN 1
           WHEN image_type = 'main'                       THEN 2
           WHEN image_type IN ('gallery','product')       THEN 3
           WHEN image_type = 'ambient'                    THEN 4
           WHEN image_type = 'set'                        THEN 5
           ELSE 9 END,
      is_primary DESC, display_order ASC NULLS LAST
    LIMIT 1;

    -- Calcular fallback URL (url_original do mesmo produto)
    SELECT url_original INTO v_new_fallback_url
    FROM public.product_images
    WHERE product_id = v_product_id AND is_active = true
      AND url_original IS NOT NULL AND url_original != ''
      AND image_type NOT IN ('box','pouch','location','area','component')
    ORDER BY
      CASE
        WHEN image_type = 'main' AND is_primary = true THEN 0
        WHEN image_type = 'main'                       THEN 1
        ELSE 9
      END,
      is_primary DESC, display_order ASC NULLS LAST
    LIMIT 1;

    -- Calcular set_image_url
    SELECT url_cdn INTO v_new_set_url
    FROM public.product_images
    WHERE product_id = v_product_id AND is_active = true AND image_type = 'set'
    ORDER BY display_order ASC, created_at ASC
    LIMIT 1;

    -- Calcular array de imagens (jsonb)
    SELECT
      COALESCE(jsonb_agg(url_cdn ORDER BY
        CASE
          WHEN image_type = 'main'    AND is_primary = true THEN 0
          WHEN image_type = 'main'                          THEN 1
          WHEN image_type IN ('gallery','product')          THEN 2
          WHEN image_type = 'ambient'                       THEN 3
          WHEN image_type = 'set'                           THEN 4
          WHEN image_type = 'logo'                          THEN 5
          ELSE 9
        END,
        is_primary DESC, display_order ASC NULLS LAST
      ) FILTER (WHERE image_type NOT IN ('box','pouch','location','area','component')),
      '[]'::jsonb
    ),
    COUNT(*)::INTEGER
    INTO v_new_images, v_images_count
    FROM public.product_images
    WHERE product_id = v_product_id AND is_active = true;

    -- Aplicar atualização
    UPDATE public.products SET
      primary_image_url         = v_new_primary_url,
      og_image_url              = v_new_og_url,
      primary_image_fallback_url = v_new_fallback_url,
      set_image_url             = v_new_set_url,
      images                    = v_new_images,
      updated_at                = NOW()
    WHERE id = v_product_id;

    -- Retornar resultado
    RETURN QUERY
      SELECT
        v_product_id,
        CASE
          WHEN v_old_primary_url IS NULL AND v_new_primary_url IS NOT NULL THEN 'SET'
          WHEN v_old_primary_url IS NOT NULL AND v_new_primary_url IS NULL THEN 'CLEARED'
          ELSE 'UPDATED'
        END,
        COALESCE(v_new_primary_url, '(null)'),
        COALESCE(v_new_og_url, '(null)'),
        v_images_count;
  END LOOP;
END;
$$;

COMMENT ON FUNCTION public.fn_resync_product_image_urls(UUID[], BOOLEAN) IS
  'Re-sincroniza manualmente os campos de imagem em products a partir de product_images.
   Útil quando o trigger falhou ou produto recebeu imagens sem disparar sync.
   
   Uso:
     -- Resync de produtos específicos:
     SELECT * FROM fn_resync_product_image_urls(ARRAY[''uuid1'', ''uuid2'']::UUID[]);
     
     -- Resync de TODOS (só onde URL mudou):
     SELECT * FROM fn_resync_product_image_urls();
     
     -- Forçar resync de todos mesmo sem mudança:
     SELECT * FROM fn_resync_product_image_urls(NULL, TRUE);
   
   Adicionada 2026-06-15.';
;

-- <<< END 20260615232612_create_fn_resync_product_image_urls.sql <<<

-- >>> BEGIN 20260615232809_product_images_format_normalize_robust.sql >>>
-- ============================================================================
-- product_images :: fn_normalize_image_format ROBUSTA (fail-open)
-- GAP descoberto em teste: btrim() só remove espaços; format com tab/newline/CR/
-- ';'/espaço interno (ex.: "image/jpeg; charset=utf-8") sobrevivia à normalização
-- e era REJEITADO pelo CHECK chk_product_images_format_lc -> a LINHA INTEIRA falhava
-- (regressão capaz de quebrar a ingestão por um campo meramente cosmético).
-- Correção: normaliza extraindo a 1a sequência [a-z0-9] (após remover prefixo mime),
-- garantindo que a saída SEMPRE satisfaz o CHECK. Nunca derruba a linha por format.
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_normalize_image_format()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
DECLARE
  v text;
BEGIN
  IF NEW.format IS NOT NULL THEN
    v := lower(NEW.format);
    v := regexp_replace(v, '^.*/', '');     -- remove prefixo mime (até a última '/')
    v := substring(v from '[a-z0-9]+');     -- 1a sequência alfanumérica (ou NULL)
    IF v = 'jpg' THEN v := 'jpeg'; END IF;  -- canonicaliza
    NEW.format := v;                        -- NULL se nada alfanumérico (fail-open)
  END IF;
  RETURN NEW;
END;
$$;;

-- <<< END 20260615232809_product_images_format_normalize_robust.sql <<<

-- >>> BEGIN 20260615233030_backfill_alt_text_newly_mapped_image_types.sql >>>

-- FIX 10: Backfill alt_text for image types now properly mapped in generate_image_alt_text
WITH candidates AS (
  SELECT
    pi.id,
    p.name          AS product_name,
    cv.name         AS color_name,
    pi.image_type,
    pi.display_order
  FROM public.product_images pi
  JOIN public.products p ON p.id = pi.product_id
  LEFT JOIN public.color_variations cv ON cv.id = pi.color_id
  WHERE pi.image_type IN ('product','location','set','component','area','ambient','detail','bag','mockup','thumbnail','vitrine_pessoa','vitrine_ambiente')
    AND (pi.alt_text ILIKE 'Imagem %' OR pi.alt_text ILIKE '%- Imagem %')
)
UPDATE public.product_images
SET
  alt_text   = generate_image_alt_text(
                  candidates.product_name,
                  candidates.image_type,
                  candidates.color_name,
                  COALESCE(candidates.display_order, 1)
               ),
  updated_at = NOW()
FROM candidates
WHERE product_images.id = candidates.id;
;

-- <<< END 20260615233030_backfill_alt_text_newly_mapped_image_types.sql <<<

-- >>> BEGIN 20260615233218_add_unique_constraint_one_primary_per_product.sql >>>

-- FIX 12: Enforce at DB level that each product has at most one active primary image.
-- Currently this is maintained by application code and triggers, but has no DB guard.
-- A partial UNIQUE index is the cleanest approach — allows NULL/false without restriction.
CREATE UNIQUE INDEX IF NOT EXISTS uq_product_images_one_primary_per_product
  ON public.product_images (product_id)
  WHERE is_primary = true AND is_active = true;

COMMENT ON INDEX uq_product_images_one_primary_per_product IS
  'Garante que cada produto tenha no máximo uma imagem primária ativa. Partial index: aplica-se apenas quando is_primary=true e is_active=true.';
;

-- <<< END 20260615233218_add_unique_constraint_one_primary_per_product.sql <<<

-- >>> BEGIN 20260615233247_grant_anon_execute_is_org_owner_or_admin.sql >>>
-- ============================================================================
-- FIX SEV-1 (descoberto em teste): a policy de SELECT de product_images foi
-- alterada pelo ambiente para `is_active OR is_org_owner_or_admin(organization_id)`,
-- mas o papel `anon` NÃO tinha EXECUTE nessa função. Resultado: ao avaliar a RLS
-- sobre qualquer linha inativa, o anônimo recebia `permission denied for function
-- is_org_owner_or_admin` e a query inteira falhava -> imagens quebravam no site público.
--
-- A função é SECURITY DEFINER e usa auth.uid(); para anon (uid nulo) retorna false
-- (sem vazamento). Conceder EXECUTE ao anon corrige o erro e mantém a intenção:
-- anônimo vê apenas imagens ativas; inativas só para owner/admin da organização.
-- Fix estável: independe da expressão exata da policy (resiste à churn do ambiente).
-- ============================================================================

GRANT EXECUTE ON FUNCTION public.is_org_owner_or_admin(uuid) TO anon;;

-- <<< END 20260615233247_grant_anon_execute_is_org_owner_or_admin.sql <<<

-- >>> BEGIN 20260615233432_product_images_sync_image_type_code_close_drift.sql >>>
-- ============================================================================
-- FIX (gap M3 descoberto em teste): o guard trg_sync_image_type_code disparava só
-- em UPDATE OF image_type_id, então um UPDATE direto da coluna texto `image_type`
-- (sem mexer no id) criava DRIFT (texto != image_types.code do id). Isso afeta a
-- ordenação em fn_sync_product_images_to_products e fn_resync_product_media, que
-- ordenam por image_type (texto).
-- Como image_type_id é NOT NULL + FK (fonte da verdade), o invariante é "texto
-- espelha a FK". Passamos o trigger a disparar também em UPDATE OF image_type,
-- re-derivando o texto a partir do id em qualquer um dos dois caminhos.
-- ============================================================================

DROP TRIGGER IF EXISTS trg_sync_image_type_code ON public.product_images;
CREATE TRIGGER trg_sync_image_type_code
  BEFORE UPDATE OF image_type_id, image_type ON public.product_images
  FOR EACH ROW EXECUTE FUNCTION public.fn_sync_image_type_code();;

-- <<< END 20260615233432_product_images_sync_image_type_code_close_drift.sql <<<

-- >>> BEGIN 20260615233542_fix_sync_image_type_bidirectional_on_insert.sql >>>

-- FIX 14: Make image_type ↔ image_type_id sync bidirectional and cover INSERT.
-- Current bug: trigger only runs on UPDATE, so INSERT rows get image_type_id='other'
-- even when image_type='main'. On the first UPDATE the SEO trigger overwrites image_type to 'other'.

-- Priority rule:
--   image_type_id explicitly set (non-'other') → trusted, update text
--   image_type text explicitly set (non-'gallery' default) → lookup UUID
--   both at defaults → still sync text→UUID so 'gallery' gets the correct UUID

CREATE OR REPLACE FUNCTION public.fn_sync_image_type_code()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = 'public'
AS $function$
DECLARE
  OTHER_UUID CONSTANT uuid := '953d054a-3bbc-4954-a319-b3c806ac596f';
  v_code text;
  v_id   uuid;
BEGIN
  -- Branch A: image_type_id is explicitly non-'other' → it is authoritative
  IF NEW.image_type_id IS NOT NULL AND NEW.image_type_id <> OTHER_UUID THEN
    SELECT code INTO v_code FROM image_types WHERE id = NEW.image_type_id;
    IF v_code IS NOT NULL THEN
      NEW.image_type := v_code;
    END IF;

  -- Branch B: image_type_id is missing or 'other' → use text to look up UUID
  ELSE
    SELECT id INTO v_id FROM image_types WHERE code = LOWER(COALESCE(NEW.image_type, 'gallery'));
    IF v_id IS NOT NULL THEN
      NEW.image_type_id := v_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

-- Drop existing trigger (UPDATE only) and recreate for INSERT + UPDATE
DROP TRIGGER IF EXISTS trg_sync_image_type_code ON public.product_images;

CREATE TRIGGER trg_sync_image_type_code
  BEFORE INSERT OR UPDATE OF image_type, image_type_id
  ON public.product_images
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_sync_image_type_code();

-- Backfill: fix the ~432 rows where image_type='gallery' but image_type_id='other'
-- (rows inserted before this fix where the column defaults collided)
UPDATE public.product_images
SET image_type_id = (SELECT id FROM public.image_types WHERE code = LOWER(image_type) LIMIT 1)
WHERE image_type_id = '953d054a-3bbc-4954-a319-b3c806ac596f'
  AND image_type != 'other'
  AND EXISTS (SELECT 1 FROM public.image_types WHERE code = LOWER(product_images.image_type));
;

-- <<< END 20260615233542_fix_sync_image_type_bidirectional_on_insert.sql <<<

