-- >>> BEGIN 20260616180001_product_images_m1_og_canonical_one_per_product.sql >>>
-- ============================================================================
-- MELHORIA 1 — OG canonico: exatamente 1 og_image por produto ATIVO (= a primaria)
-- Aplicado em prod (doufsxqlfjyuvxuezpln) via MCP em 2026-06-16; este arquivo espelha o estado.
-- Idempotente e reversivel (apenas flags booleanas).
-- Corrige: 1.660 produtos sem OG, 1 produto com 2 OG, 161 OG em nao-primaria, 140 OG em inativa.
-- Triggers de sync mantem products.og_image_url (volume ~2,1k linhas).
-- https://claude.ai/code/session_01JWqwBkgRNk8v6ejLd18Hv9
-- ============================================================================

-- 1) Remove o flag OG de qualquer linha que NAO seja a primaria ativa
UPDATE public.product_images
   SET is_og_image = false
 WHERE is_og_image IS TRUE
   AND (is_primary IS NOT TRUE OR is_active IS NOT TRUE);

-- 2) Garante o flag OG na primaria ativa de todo produto que estava sem
UPDATE public.product_images
   SET is_og_image = true
 WHERE is_active IS TRUE
   AND is_primary IS TRUE
   AND is_og_image IS NOT TRUE;

-- <<< END 20260616180001_product_images_m1_og_canonical_one_per_product.sql <<<

-- >>> BEGIN 20260616180002_product_images_m2_display_order_deterministic.sql >>>
-- ============================================================================
-- MELHORIA 2 — display_order deterministico por (product_id, color_id, image_type)
-- Aplicado em prod via MCP em 2026-06-16; este arquivo espelha o estado.
-- Primaria sempre 1a; desempate por (display_order, created_at, id). Elimina 18.484 colisoes -> 0.
-- Reversivel (snapshot backup.product_images_display_order_20260616). ~55.764 linhas reordenadas.
-- Suprime amplificacao de triggers (session_replication_role=replica) + resync determinístico.
-- https://claude.ai/code/session_01JWqwBkgRNk8v6ejLd18Hv9
-- ============================================================================

CREATE SCHEMA IF NOT EXISTS backup;
DROP TABLE IF EXISTS backup.product_images_display_order_20260616;
CREATE TABLE backup.product_images_display_order_20260616 AS
  SELECT id, display_order, now() AS snapshot_at
  FROM public.product_images WHERE is_active;

SET LOCAL session_replication_role = replica;

WITH reseq AS (
  SELECT id,
         row_number() OVER (PARTITION BY product_id, color_id, image_type
                            ORDER BY (NOT is_primary), display_order, created_at, id) AS new_order
  FROM public.product_images
  WHERE is_active
)
UPDATE public.product_images p
   SET display_order = r.new_order,
       updated_at    = now()
  FROM reseq r
 WHERE p.id = r.id
   AND p.display_order IS DISTINCT FROM r.new_order;

SET LOCAL session_replication_role = origin;
SELECT public.fn_resync_product_media(
  ARRAY(SELECT DISTINCT product_id FROM public.product_images WHERE is_active)
);

-- <<< END 20260616180002_product_images_m2_display_order_deterministic.sql <<<

-- >>> BEGIN 20260616180003_product_images_m3_colorid_backfill_monovariant.sql >>>
-- ============================================================================
-- MELHORIA 3 — color_id backfill INEQUIVOCO (produtos mono-variante)
-- Aplicado em prod via MCP em 2026-06-16; este arquivo espelha o estado.
-- Atribui a unica cor do produto as imagens color-specific sem color_id (1.706 linhas).
-- Multi-variante (14.155) NAO e tocado (ambiguo - requer re-importacao com mapa de cor).
-- https://claude.ai/code/session_01JWqwBkgRNk8v6ejLd18Hv9
-- ============================================================================
UPDATE public.product_images pi
   SET color_id   = mv.cid,
       updated_at = now()
  FROM (
    SELECT product_id, (array_agg(DISTINCT color_id))[1] AS cid
    FROM public.product_variants
    WHERE color_id IS NOT NULL
    GROUP BY product_id
    HAVING count(DISTINCT color_id) = 1
  ) mv
 WHERE pi.product_id = mv.product_id
   AND pi.color_id IS NULL
   AND pi.is_active IS TRUE
   AND EXISTS (SELECT 1 FROM public.image_types it
                WHERE it.id = pi.image_type_id AND it.is_color_specific IS TRUE);

-- <<< END 20260616180003_product_images_m3_colorid_backfill_monovariant.sql <<<

-- >>> BEGIN 20260616180004_product_images_m4_projection_repair_and_hashlegacy_softpurge.sql >>>
-- ============================================================================
-- MELHORIA 4 — Reparo defensivo de projecoes + expurgo SOFT hash_legacy
-- Aplicado em prod via MCP em 2026-06-16; este arquivo espelha o estado (condicao corrigida).
--
-- NOTA FORENSE: a simulacao apontou 196 produtos com primary_image_url "apontando p/ hash_legacy",
-- MAS a investigacao mostrou que url_cdn das 519 hash_legacy e CANONICALIZADO p/ imagens validas
-- (hl_urlcdn_self=0, hl_urlcdn_canonicalized=519, truly_broken_primary=0). Logo a projecao NAO
-- estava quebrada — era falso-positivo por compartilhamento de url_cdn. O repoint abaixo usa a
-- condicao CORRETA (primaria que NAO resolve p/ nenhuma imagem ativa) — no-op idempotente hoje,
-- defensivo p/ o futuro. O soft-delete das hash_legacy (inativas, cloudflare_image_id 100% ausente
-- no CF) permanece como limpeza de governanca (reversivel via deleted_at).
-- https://claude.ai/code/session_01JWqwBkgRNk8v6ejLd18Hv9
-- ============================================================================

CREATE SCHEMA IF NOT EXISTS backup;
CREATE TABLE IF NOT EXISTS backup.products_imageproj_20260616 AS
  SELECT id, primary_image_url, og_image_url, primary_image_fallback_url, now() AS snapshot_at
  FROM public.products
  WHERE primary_image_url IS NOT NULL
    AND NOT EXISTS (SELECT 1 FROM public.product_images v
                     WHERE v.url_cdn = products.primary_image_url AND v.is_active);

SET LOCAL session_replication_role = replica;

-- M4a: repoint primary_image_url SOMENTE quando nao resolve p/ nenhuma imagem ativa -> primaria ativa
WITH ap AS (
  SELECT DISTINCT ON (product_id) product_id, url_cdn
  FROM public.product_images WHERE is_active AND is_primary
  ORDER BY product_id, display_order
)
UPDATE public.products p
   SET primary_image_url = ap.url_cdn, updated_at = now()
  FROM ap
 WHERE p.id = ap.product_id
   AND p.primary_image_url IS DISTINCT FROM ap.url_cdn
   AND NOT EXISTS (SELECT 1 FROM public.product_images v
                    WHERE v.url_cdn = p.primary_image_url AND v.is_active);

-- M4a': mesma logica p/ og_image_url
WITH ap AS (
  SELECT DISTINCT ON (product_id) product_id, url_cdn
  FROM public.product_images WHERE is_active AND is_primary
  ORDER BY product_id, display_order
)
UPDATE public.products p
   SET og_image_url = ap.url_cdn, updated_at = now()
  FROM ap
 WHERE p.id = ap.product_id
   AND p.og_image_url IS DISTINCT FROM ap.url_cdn
   AND NOT EXISTS (SELECT 1 FROM public.product_images v
                    WHERE v.url_cdn = p.og_image_url AND v.is_active);

-- M4b: expurgo SOFT das hash_legacy (inativas, cloudflare_image_id 100% ausente no CF) — reversivel
UPDATE public.product_images
   SET deleted_at = now(),
       deleted_reason = 'hash_legacy xbz_site_* 100% ausente no Cloudflare (auditoria 2026-06-16); inativa, sem impacto UX',
       last_modified_source = 'claude'
 WHERE cf_id_scheme = 'hash_legacy'
   AND deleted_at IS NULL;

SET LOCAL session_replication_role = origin;

-- <<< END 20260616180004_product_images_m4_projection_repair_and_hashlegacy_softpurge.sql <<<

-- >>> BEGIN 20260616180005_product_images_m5_reclassify_xbz_product_to_gallery.sql >>>
-- ============================================================================
-- MELHORIA 5 — Reclassifica XBZ image_type 'product' (generico) -> 'gallery'
-- Aplicado em prod via MCP em 2026-06-16; este arquivo espelha o estado.
-- 7.779 ativas, todas NAO-primarias (Vista Alternativa). Reversivel (snapshot).
-- Atualiza texto + FK explicitamente (replica mode) e resync escopado aos produtos afetados.
-- Resultado: balde generico 'product' zerado; drift texto<->FK = 0.
-- https://claude.ai/code/session_01JWqwBkgRNk8v6ejLd18Hv9
-- ============================================================================
CREATE SCHEMA IF NOT EXISTS backup;
CREATE TABLE IF NOT EXISTS backup.product_images_type_xbz_20260616 AS
  SELECT id, product_id, image_type, image_type_id, now() AS snapshot_at
  FROM public.product_images
  WHERE source_supplier='XBZ' AND image_type='product' AND is_active;

SET LOCAL session_replication_role = replica;

UPDATE public.product_images
   SET image_type    = 'gallery',
       image_type_id = '1590e144-e3f8-41e6-98f9-f4a25bae496d',  -- code='gallery' (Vista Alternativa)
       updated_at    = now()
 WHERE source_supplier='XBZ' AND image_type='product' AND is_active;

SET LOCAL session_replication_role = origin;

SELECT public.fn_resync_product_media(
  ARRAY(SELECT DISTINCT product_id FROM backup.product_images_type_xbz_20260616)
);

-- <<< END 20260616180005_product_images_m5_reclassify_xbz_product_to_gallery.sql <<<

-- >>> BEGIN 20260616180006_product_images_m6_cf_remediation_worklist_view.sql >>>
-- ============================================================================
-- MELHORIA 6 — View de remediacao: produtos ATIVOS com primaria realmente quebrada
-- Aplicado em prod via MCP em 2026-06-16; este arquivo espelha o estado.
-- (primaria nao resolve p/ nenhuma imagem ativa verified/pending/uploaded). Worklist de re-upload.
-- Aditiva, sem mutacao de dados. Revogada de anon/authenticated (padrao v_cf_recon_progress).
-- https://claude.ai/code/session_01JWqwBkgRNk8v6ejLd18Hv9
-- ============================================================================
CREATE OR REPLACE VIEW public.v_cf_image_remediation AS
SELECT
  p.id AS product_id,
  p.primary_image_url,
  (SELECT count(*) FROM public.product_images pi WHERE pi.product_id=p.id AND pi.is_active) AS active_imgs,
  (SELECT count(*) FROM public.product_images pi WHERE pi.product_id=p.id AND pi.is_active AND pi.cf_sync_status='verified') AS verified_active_imgs
FROM public.products p
WHERE p.is_active
  AND p.primary_image_url IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM public.product_images v
    WHERE v.url_cdn = p.primary_image_url AND v.is_active
      AND v.cf_sync_status IN ('verified','pending','uploaded')
  );

REVOKE ALL ON public.v_cf_image_remediation FROM anon, authenticated;
COMMENT ON VIEW public.v_cf_image_remediation IS
  'Produtos ATIVOS cuja primaria nao resolve p/ imagem ativa verified/pending/uploaded no Cloudflare. Worklist de re-upload (auditoria 2026-06-16); converge conforme a recon completa.';

-- <<< END 20260616180006_product_images_m6_cf_remediation_worklist_view.sql <<<

-- >>> BEGIN 20260616180007_product_images_m7_display_order_resequence_post_reclassify.sql >>>
-- ============================================================================
-- MELHORIA 7 — Re-sequencia display_order APOS a reclassificacao M5
-- Aplicado em prod via MCP em 2026-06-16; este arquivo espelha o estado.
-- A M5 alterou image_type (particao de ordenacao) de 7.779 linhas, reintroduzindo 10.484 colisoes.
-- Esta passada restaura a invariante determinística (colisoes estritas -> 0). Idempotente.
-- Reversibilidade: snapshot original em backup.product_images_display_order_20260616 (M2).
-- https://claude.ai/code/session_01JWqwBkgRNk8v6ejLd18Hv9
-- ============================================================================
SET LOCAL session_replication_role = replica;

WITH reseq AS (
  SELECT id,
         row_number() OVER (PARTITION BY product_id, color_id, image_type
                            ORDER BY (NOT is_primary), display_order, created_at, id) AS new_order
  FROM public.product_images
  WHERE is_active
)
UPDATE public.product_images p
   SET display_order = r.new_order,
       updated_at    = now()
  FROM reseq r
 WHERE p.id = r.id
   AND p.display_order IS DISTINCT FROM r.new_order;

SET LOCAL session_replication_role = origin;
SELECT public.fn_resync_product_media(
  ARRAY(SELECT DISTINCT product_id FROM public.product_images WHERE is_active)
);

-- <<< END 20260616180007_product_images_m7_display_order_resequence_post_reclassify.sql <<<

-- >>> BEGIN 20260616181001_cf_recon_foundation.sql >>>
-- ============================================================================
-- CF-RECON 0 — Fundacao de Reconciliacao Cloudflare x product_images
-- Aplicado em prod via MCP em 2026-06-16; este arquivo espelha o estado.
-- Schema isolado `cf_recon`, aditivo e idempotente. Nada em public e mutado.
-- Nao exposto via PostgREST (schema fora do search_path da API).
-- https://claude.ai/code/session_01MAV1SvJ69G694NWUzo2XeG
-- ============================================================================
create schema if not exists cf_recon;
comment on schema cf_recon is 'Reconciliacao product_images x Cloudflare Images. Mantido por Claude/pipeline. Nao exposto via PostgREST.';

-- Inventario do crawl do Cloudflare (espelho do estado do CF)
create table if not exists cf_recon.cf_image (
  image_id      text primary key,
  uploaded_at   timestamptz,
  filename      text,
  meta          jsonb,
  crawl_run_id  uuid,
  first_seen_at timestamptz not null default now(),
  last_seen_at  timestamptz not null default now()
);
comment on table cf_recon.cf_image is 'Inventario de imagens existentes no Cloudflare (preenchido por crawl paginado).';

-- Execucoes de crawl (resumivel/auditavel)
create table if not exists cf_recon.crawl_run (
  id            uuid primary key default gen_random_uuid(),
  started_at    timestamptz not null default now(),
  finished_at   timestamptz,
  pages_scanned int not null default 0,
  images_seen   int not null default 0,
  cf_total_reported int,
  status        text not null default 'running' check (status in ('running','completed','failed','partial')),
  notes         text
);

-- Trilha de auditoria: TODA alteracao feita pela reconciliacao
create table if not exists cf_recon.action_log (
  id            bigserial primary key,
  acted_at      timestamptz not null default now(),
  actor         text not null default 'claude',
  action        text not null,
  image_db_id   uuid,
  cf_image_id   text,
  old_status    text,
  new_status    text,
  evidence      jsonb,
  reversible    boolean not null default true
);
comment on table cf_recon.action_log is 'Auditoria imutavel de cada reclassificacao/quarentena aplicada.';

-- Snapshots de metricas ao longo do tempo
create table if not exists cf_recon.metric_snapshot (
  id        bigserial primary key,
  taken_at  timestamptz not null default now(),
  metrics   jsonb not null
);

-- View: fila canonica de verificacao (exclui deletados/hash_legacy = ruido)
create or replace view cf_recon.v_verification_queue as
select pi.id, pi.cloudflare_image_id, pi.cf_sync_status, pi.cf_id_scheme,
       pi.source_supplier, pi.cf_check_attempts, pi.is_active, pi.created_at
from public.product_images pi
where pi.cf_sync_status <> 'verified'
  and pi.deleted_at is null
  and coalesce(pi.cf_id_scheme,'') <> 'hash_legacy';
comment on view cf_recon.v_verification_queue is 'Fila real de verificacao CF: pendentes vivos, sem deletados/hash_legacy.';

-- View: divergencias DB x CF (util apos crawl popular cf_image)
create or replace view cf_recon.v_divergence as
select
  pi.id              as db_id,
  pi.cloudflare_image_id,
  pi.cf_sync_status,
  pi.cf_id_scheme,
  pi.source_supplier,
  pi.is_active,
  pi.deleted_at is not null as is_deleted,
  (ci.image_id is not null) as exists_in_cf,
  case
    when ci.image_id is not null and pi.cf_sync_status <> 'verified' then 'cf_present_db_unverified'
    when ci.image_id is null and pi.deleted_at is not null then 'deleted_noise'
    when ci.image_id is null and pi.is_active then 'broken_reference_active'
    when ci.image_id is null and not pi.is_active then 'broken_reference_inactive'
    else 'ok'
  end as divergence_class
from public.product_images pi
left join cf_recon.cf_image ci on ci.image_id = pi.cloudflare_image_id;
comment on view cf_recon.v_divergence is 'Classificacao de divergencia por linha (requer cf_image populado via crawl).';

-- View: orfas do lado Cloudflare (imagens no CF sem dono no DB)
create or replace view cf_recon.v_cf_orphans as
select ci.image_id, ci.uploaded_at, ci.filename
from cf_recon.cf_image ci
left join public.product_images pi on pi.cloudflare_image_id = ci.image_id
where pi.id is null;
comment on view cf_recon.v_cf_orphans is 'Imagens existentes no Cloudflare sem referencia em product_images (candidatas a custo recuperavel).';

-- <<< END 20260616181001_cf_recon_foundation.sql <<<

