-- >>> BEGIN 20260616211558_mcp_kv_refresh_lock.sql >>>
-- Lock distribuido p/ evitar race de refresh cross-isolate no higgsfield-mcp
alter table public.mcp_kv add column if not exists lock_until timestamptz;

-- Tenta adquirir o lock de refresh atomicamente. Retorna true se ESTE chamador ganhou.
create or replace function public.mcp_kv_try_lock(p_secret text, p_key text, p_ttl_seconds int)
returns boolean
language plpgsql
security definer
set search_path = public
as $$
declare
  v_now timestamptz := now();
  v_rows int;
begin
  if p_secret <> '9f2c7a1e6b40d83f5c1908a4e7d62b3f8c05a91e4d7b620c' then
    raise exception 'unauthorized';
  end if;
  -- adquire se nao existe lock vigente (lock_until nulo ou expirado)
  update public.mcp_kv
     set lock_until = v_now + make_interval(secs => p_ttl_seconds)
   where k = p_key
     and (lock_until is null or lock_until < v_now);
  get diagnostics v_rows = row_count;
  return v_rows > 0;
end;
$$;

revoke all on function public.mcp_kv_try_lock(text,text,int) from public, anon;
grant execute on function public.mcp_kv_try_lock(text,text,int) to anon;;

-- <<< END 20260616211558_mcp_kv_refresh_lock.sql <<<

-- >>> BEGIN 20260616211957_product_images_m1_og_canonical_one_per_product.sql >>>
-- ============================================================================
-- MELHORIA 1 — OG canônico: exatamente 1 og_image por produto ATIVO (= a primária)
-- Idempotente e reversível (apenas flags booleanas).
-- Corrige: 1.660 produtos sem OG, 1 produto com 2 OG, 161 OG em não-primária, 140 OG em inativa.
-- Triggers de sync mantêm products.og_image_url (volume ~2,1k — sem risco de amplificação).
-- ============================================================================

-- 1) Remove o flag OG de qualquer linha que NÃO seja a primária ativa
UPDATE public.product_images
   SET is_og_image = false
 WHERE is_og_image IS TRUE
   AND (is_primary IS NOT TRUE OR is_active IS NOT TRUE);

-- 2) Garante o flag OG na primária ativa de todo produto que estava sem
UPDATE public.product_images
   SET is_og_image = true
 WHERE is_active IS TRUE
   AND is_primary IS TRUE
   AND is_og_image IS NOT TRUE;;

-- <<< END 20260616211957_product_images_m1_og_canonical_one_per_product.sql <<<

-- >>> BEGIN 20260616212114_product_images_m2_display_order_deterministic.sql >>>
-- ============================================================================
-- MELHORIA 2 — display_order determinístico por (product_id, color_id, image_type)
-- Primária sempre 1ª; desempate por (display_order, created_at, id). Elimina 18.484 colisões → 0.
-- Reversível (snapshot em backup). Suprime amplificação de triggers + resync determinístico final.
-- ============================================================================

-- Snapshot reversível do estado atual (ativas)
CREATE SCHEMA IF NOT EXISTS backup;
DROP TABLE IF EXISTS backup.product_images_display_order_20260616;
CREATE TABLE backup.product_images_display_order_20260616 AS
  SELECT id, display_order, now() AS snapshot_at
  FROM public.product_images WHERE is_active;

-- Suprime triggers nesta transação (sem ALTER global, sem lock exclusivo prolongado)
SET LOCAL session_replication_role = replica;

WITH reseq AS (
  SELECT id,
         row_number() OVER (PARTITION BY product_id, color_id, image_type
                            ORDER BY (NOT is_primary), display_order, created_at, id) AS new_order
  FROM public.product_images
  WHERE is_active
)
UPDATE public.product_images p
   SET display_order = r.new_order,
       updated_at    = now()
  FROM reseq r
 WHERE p.id = r.id
   AND p.display_order IS DISTINCT FROM r.new_order;

-- Restaura modo normal e reconstrói projeções (images/og/primary/fallback) determinísticamente
SET LOCAL session_replication_role = origin;
SELECT public.fn_resync_product_media(
  ARRAY(SELECT DISTINCT product_id FROM public.product_images WHERE is_active)
);;

-- <<< END 20260616212114_product_images_m2_display_order_deterministic.sql <<<

-- >>> BEGIN 20260616212505_product_images_m3_colorid_backfill_monovariant.sql >>>
-- ============================================================================
-- MELHORIA 3 — color_id backfill INEQUÍVOCO (produtos mono-variante)
-- color_id é uuid → agrega com array_agg(DISTINCT ...). Multi-variante NÃO é tocado.
-- ============================================================================
UPDATE public.product_images pi
   SET color_id   = mv.cid,
       updated_at = now()
  FROM (
    SELECT product_id, (array_agg(DISTINCT color_id))[1] AS cid
    FROM public.product_variants
    WHERE color_id IS NOT NULL
    GROUP BY product_id
    HAVING count(DISTINCT color_id) = 1
  ) mv
 WHERE pi.product_id = mv.product_id
   AND pi.color_id IS NULL
   AND pi.is_active IS TRUE
   AND EXISTS (SELECT 1 FROM public.image_types it
                WHERE it.id = pi.image_type_id AND it.is_color_specific IS TRUE);;

-- <<< END 20260616212505_product_images_m3_colorid_backfill_monovariant.sql <<<

-- >>> BEGIN 20260616212622_product_images_m4_projection_repair_and_hashlegacy_softpurge.sql >>>
-- ============================================================================
-- MELHORIA 4 — Reparo de projeções obsoletas (UX) + expurgo SOFT hash_legacy
-- Repoint cirúrgico em products (replica mode = 0 efeitos colaterais dos 33 triggers).
-- Reversível: snapshot em backup.products_imageproj_20260616.
-- Os 16 produtos SEM imagem ativa NÃO são tocados (serão sinalizados p/ re-importação).
-- ============================================================================

CREATE SCHEMA IF NOT EXISTS backup;
CREATE TABLE IF NOT EXISTS backup.products_imageproj_20260616 AS
  SELECT id, primary_image_url, og_image_url, primary_image_fallback_url, now() AS snapshot_at
  FROM public.products
  WHERE primary_image_url IN (SELECT url_cdn FROM public.product_images WHERE is_active IS NOT TRUE)
     OR og_image_url      IN (SELECT url_cdn FROM public.product_images WHERE is_active IS NOT TRUE);

SET LOCAL session_replication_role = replica;

-- M4a: primary_image_url obsoleto (-> inativa) repointado p/ a primária ATIVA
WITH ap AS (
  SELECT DISTINCT ON (product_id) product_id, url_cdn
  FROM public.product_images WHERE is_active AND is_primary
  ORDER BY product_id, display_order
)
UPDATE public.products p
   SET primary_image_url = ap.url_cdn, updated_at = now()
  FROM ap
 WHERE p.id = ap.product_id
   AND p.primary_image_url IS DISTINCT FROM ap.url_cdn
   AND p.primary_image_url IN (SELECT url_cdn FROM public.product_images WHERE is_active IS NOT TRUE);

-- M4a': og_image_url obsoleto repointado p/ a primária ATIVA (OG = primária após M1)
WITH ap AS (
  SELECT DISTINCT ON (product_id) product_id, url_cdn
  FROM public.product_images WHERE is_active AND is_primary
  ORDER BY product_id, display_order
)
UPDATE public.products p
   SET og_image_url = ap.url_cdn, updated_at = now()
  FROM ap
 WHERE p.id = ap.product_id
   AND p.og_image_url IS DISTINCT FROM ap.url_cdn
   AND p.og_image_url IN (SELECT url_cdn FROM public.product_images WHERE is_active IS NOT TRUE);

-- M4b: expurgo SOFT das hash_legacy (inativas, 100% ausentes no CF) — reversível
UPDATE public.product_images
   SET deleted_at = now(),
       deleted_reason = 'hash_legacy xbz_site_* 100% ausente no Cloudflare (auditoria 2026-06-16); inativa, sem impacto UX',
       last_modified_source = 'claude'
 WHERE cf_id_scheme = 'hash_legacy'
   AND deleted_at IS NULL;

SET LOCAL session_replication_role = origin;;

-- <<< END 20260616212622_product_images_m4_projection_repair_and_hashlegacy_softpurge.sql <<<

-- >>> BEGIN 20260616213208_product_images_m5_reclassify_xbz_product_to_gallery.sql >>>
-- ============================================================================
-- MELHORIA 5 — Reclassifica XBZ image_type 'product' (genérico/sem-semântica) -> 'gallery'
-- 7.779 ativas, todas NÃO-primárias (Vista Alternativa). Reversível (snapshot).
-- Atualiza texto + FK explicitamente (replica mode), depois resync escopado aos produtos afetados.
-- ============================================================================
CREATE SCHEMA IF NOT EXISTS backup;
CREATE TABLE IF NOT EXISTS backup.product_images_type_xbz_20260616 AS
  SELECT id, product_id, image_type, image_type_id, now() AS snapshot_at
  FROM public.product_images
  WHERE source_supplier='XBZ' AND image_type='product' AND is_active;

SET LOCAL session_replication_role = replica;

UPDATE public.product_images
   SET image_type    = 'gallery',
       image_type_id = '1590e144-e3f8-41e6-98f9-f4a25bae496d',  -- code='gallery' (Vista Alternativa)
       updated_at    = now()
 WHERE source_supplier='XBZ' AND image_type='product' AND is_active;

SET LOCAL session_replication_role = origin;

SELECT public.fn_resync_product_media(
  ARRAY(SELECT DISTINCT product_id FROM backup.product_images_type_xbz_20260616)
);;

