-- >>> BEGIN 20260616234054_cf_recon_remediate_broken_active.sql >>>
-- Melhoria 3: tratar imagens ATIVAS quebradas (missing).
-- 24 com irma 'verified' -> desativa (autopromote troca a primaria). 56 sem -> fila de remediacao.
create table if not exists cf_recon.remediation (
  id           bigserial primary key,
  created_at   timestamptz not null default now(),
  kind         text not null,
  product_id   uuid,
  image_db_id  uuid,
  cf_image_id  text,
  detail       jsonb,
  status       text not null default 'open' check (status in ('open','in_progress','done','wontfix'))
);
comment on table cf_recon.remediation is 'Fila de remediacao manual: re-upload, produtos sem imagem, inativas a revisar.';
create index if not exists idx_remediation_kind_status on cf_recon.remediation(kind, status);

with broken_active as (
  select b.id, b.product_id, b.cloudflare_image_id, b.is_primary
  from public.product_images b
  where b.cf_sync_status='missing' and b.is_active
),
classified as (
  select ba.*,
    exists(select 1 from public.product_images s
           where s.product_id=ba.product_id and s.id<>ba.id
             and s.is_active and s.cf_sync_status='verified') as healthy
  from broken_active ba
),
ins_review as (
  insert into cf_recon.remediation(kind, product_id, image_db_id, cf_image_id, detail)
  select 'broken_active_no_replacement', product_id, id, cloudflare_image_id,
         jsonb_build_object('is_primary', is_primary, 'reason','active+missing+sem_irma_verified')
  from classified where not healthy
  returning 1
),
log_deact as (
  insert into cf_recon.action_log(actor,action,image_db_id,cf_image_id,old_status,new_status,evidence,reversible)
  select 'claude','deactivate_broken_active', id, cloudflare_image_id, 'is_active=true','is_active=false',
         jsonb_build_object('reason','active+missing com irma verified; autopromote assume primaria'), true
  from classified where healthy
  returning 1
)
update public.product_images pi
set is_active = false,
    last_modified_source = 'claude'
from classified c
where pi.id = c.id and c.healthy;;

-- <<< END 20260616234054_cf_recon_remediate_broken_active.sql <<<

-- >>> BEGIN 20260616234201_cf_recon_products_without_image.sql >>>
-- Melhoria 4 (D6): produtos sem imagem ativa.
-- View de cobertura + enfileira os ATIVOS (gap real de vitrine) para sourcing.
create or replace view cf_recon.v_products_without_active_image as
select p.id as product_id, p.name, p.is_active as product_active,
       (select count(*) from public.product_images pi where pi.product_id=p.id) as total_images,
       (select count(*) from public.product_images pi where pi.product_id=p.id and pi.cf_sync_status='missing') as broken_images
from public.products p
where not exists (select 1 from public.product_images pi where pi.product_id=p.id and pi.is_active);
comment on view cf_recon.v_products_without_active_image is 'Produtos sem nenhuma imagem ativa (D6). product_active=true = gap de vitrine prioritario.';

insert into cf_recon.remediation(kind, product_id, image_db_id, cf_image_id, detail)
select 'product_no_active_image', product_id, null, null,
       jsonb_build_object('product_name', name, 'total_images', total_images, 'broken_images', broken_images)
from cf_recon.v_products_without_active_image
where product_active is true
  and not exists (
    select 1 from cf_recon.remediation r
    where r.kind='product_no_active_image' and r.product_id = cf_recon.v_products_without_active_image.product_id
  );;

-- <<< END 20260616234201_cf_recon_products_without_image.sql <<<

-- >>> BEGIN 20260616234220_cf_recon_inactive_alive_views.sql >>>
-- Melhoria 5 (D5): imagens inativas porem nao-deletadas (potencial custo no CF).
create or replace view cf_recon.v_inactive_alive as
select pi.id, pi.product_id, pi.cloudflare_image_id, pi.cf_sync_status,
       pi.source_supplier, pi.cf_id_scheme, pi.updated_at
from public.product_images pi
where pi.is_active is false and pi.deleted_at is null;
comment on view cf_recon.v_inactive_alive is 'Imagens fora do catalogo (inativas) mas nao soft-deletadas. Candidatas a arquivamento.';

-- Custo recuperavel: inativas vivas cujo asset AINDA existe no Cloudflare (requer crawl).
create or replace view cf_recon.v_inactive_alive_cf_cost as
select ia.id, ia.product_id, ia.cloudflare_image_id, ia.cf_sync_status, ia.source_supplier
from cf_recon.v_inactive_alive ia
join cf_recon.cf_image ci on ci.image_id = ia.cloudflare_image_id;
comment on view cf_recon.v_inactive_alive_cf_cost is 'Inativas vivas que ocupam storage no CF (custo recuperavel apos revisao). Requer crawl populado.';

-- Painel consolidado de saude da reconciliacao
create or replace view cf_recon.v_health_dashboard as
select
  (select count(*) from public.product_images) as db_total,
  (select count(*) from public.product_images where is_active) as db_active,
  (select count(*) from public.product_images where cf_sync_status='verified') as verified,
  (select count(*) from public.product_images where cf_sync_status='pending') as pending,
  (select count(*) from public.product_images where cf_sync_status='missing') as missing,
  (select count(*) from public.product_images where cf_sync_status='missing' and is_active) as missing_active,
  (select count(*) from cf_recon.v_verification_queue) as queue_real,
  (select count(*) from cf_recon.remediation where status='open') as remediation_open,
  (select count(*) from cf_recon.cf_image) as cf_crawled,
  (select count(*) from cf_recon.action_log) as actions_logged;
comment on view cf_recon.v_health_dashboard is 'KPI unico da reconciliacao CF x product_images.';;

-- <<< END 20260616234220_cf_recon_inactive_alive_views.sql <<<

