-- >>> BEGIN 20260617000002_hash_product_images_cron.sql >>>
-- Migration: P2.7 — content_hash population via Edge Function cron
-- Applied: 2026-06-17
-- Session: https://claude.ai/code/session_015AMvYV8EoNtNpvL7jrUm83
--
-- Registers a pg_cron job that calls the `hash-product-images` Edge Function
-- every 5 minutes. The function downloads each verified image and computes
-- a SHA-256 hex digest stored in product_images.content_hash.
--
-- Prerequisite: vault secret 'HASH_PRODUCT_IMAGES_CRON_SECRET' must be set.
-- Set it via: Supabase dashboard → Settings → Vault → New Secret
-- Match the value to HASH_PRODUCT_IMAGES_CRON_SECRET in Edge Function env.
--
-- Throughput: ~960 hashes/hour (80 images × 12 invocations).
-- ETA to full coverage: ~75 hours from first run (72,047 verified images).
--
-- To monitor progress:
--   SELECT COUNT(*) FROM product_images
--   WHERE content_hash IS NULL AND cf_sync_status = 'verified' AND deleted_at IS NULL;

-- ─── Index for efficient next-batch selection ─────────────────────────────────

CREATE INDEX IF NOT EXISTS idx_product_images_content_hash_null
  ON product_images (id)
  WHERE content_hash IS NULL
    AND cf_sync_status = 'verified'
    AND deleted_at IS NULL;

-- ─── pg_cron job ──────────────────────────────────────────────────────────────

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'hash-product-images') THEN
    PERFORM cron.unschedule('hash-product-images');
  END IF;
END $$;

SELECT cron.schedule(
  'hash-product-images',
  '*/5 * * * *',
  $cron$
  SELECT net.http_post(
    url := public.get_edge_functions_base_url() || '/functions/v1/hash-product-images',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', public.get_edge_function_secret('HASH_PRODUCT_IMAGES_CRON_SECRET')
    ),
    body := '{"trigger":"cron"}'::jsonb,
    timeout_milliseconds := 55000
  ) AS request_id;
  $cron$
);

-- ─── Duplicate detection view (available once hashes start populating) ────────
-- Finds images with identical pixel content stored under different CF IDs.
-- Useful for deduplication audits after content_hash is fully populated.

CREATE OR REPLACE VIEW public.v_product_image_hash_duplicates AS
SELECT
  content_hash,
  COUNT(*)                                              AS duplicate_count,
  array_agg(cloudflare_image_id ORDER BY cloudflare_image_id) AS cf_ids,
  array_agg(id ORDER BY cloudflare_image_id)           AS image_ids,
  MIN(created_at)                                      AS oldest_upload
FROM product_images
WHERE content_hash IS NOT NULL
  AND deleted_at IS NULL
GROUP BY content_hash
HAVING COUNT(*) > 1
ORDER BY duplicate_count DESC, content_hash;

COMMENT ON VIEW public.v_product_image_hash_duplicates IS
  'Images with identical SHA-256 content_hash stored under different cloudflare_image_ids. '
  'Populated once hash-product-images cron has run. Use for deduplication audits.';

-- <<< END 20260617000002_hash_product_images_cron.sql <<<

-- >>> BEGIN 20260617000003_generate_blurhashes_cron.sql >>>
-- Migration: P2.8 — blurhash population via Edge Function cron
-- Applied: 2026-06-17
-- Session: https://claude.ai/code/session_015AMvYV8EoNtNpvL7jrUm83
--
-- Registers a pg_cron job that calls the `generate-blurhashes` Edge Function
-- every 5 minutes. The function downloads each verified JPEG/PNG image, decodes
-- pixels, resizes to 32×32, and encodes a blurhash string stored in
-- product_images.blurhash. Skips WebP/GIF (unsupported pure-JS decoders).
--
-- Prerequisite: vault secret 'GENERATE_BLURHASHES_CRON_SECRET' must be set.
-- Coverage: ~67,344 images (JPEG 54,866 + PNG 12,478 = 93.4% of verified).
-- Throughput: ~480 hashes/hour (40 images × 12 invocations).
-- ETA to full JPEG+PNG coverage: ~140 hours from first run.
--
-- To monitor progress:
--   SELECT COUNT(*) FROM product_images
--   WHERE blurhash IS NULL AND cf_sync_status = 'verified'
--     AND deleted_at IS NULL AND format IN ('jpeg', 'png');

-- ─── Index for efficient next-batch selection ─────────────────────────────────

CREATE INDEX IF NOT EXISTS idx_product_images_blurhash_null
  ON product_images (is_primary DESC, id)
  WHERE blurhash IS NULL
    AND cf_sync_status = 'verified'
    AND deleted_at IS NULL
    AND format IN ('jpeg', 'png');

-- ─── pg_cron job ──────────────────────────────────────────────────────────────

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'generate-blurhashes') THEN
    PERFORM cron.unschedule('generate-blurhashes');
  END IF;
END $$;

SELECT cron.schedule(
  'generate-blurhashes',
  '*/5 * * * *',
  $cron$
  SELECT net.http_post(
    url := public.get_edge_functions_base_url() || '/functions/v1/generate-blurhashes',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', public.get_edge_function_secret('GENERATE_BLURHASHES_CRON_SECRET')
    ),
    body := '{"trigger":"cron"}'::jsonb,
    timeout_milliseconds := 55000
  ) AS request_id;
  $cron$
);

-- <<< END 20260617000003_generate_blurhashes_cron.sql <<<

-- >>> BEGIN 20260617000004_extend_get_edge_function_secret_allowlist.sql >>>
-- Migration: P2.9 — extend get_edge_function_secret allowlist
-- Applied: 2026-06-17
--
-- Adds the three new cron secret names to the get_edge_function_secret
-- whitelist so authorizeCron can read them from vault at runtime.
--
-- Without this, the RPC raises 'insufficient_privilege' for any name not
-- in the list, getVaultSecret() catches it and returns "", and authorizeCron
-- fail-closes with 503 instead of 401 — breaking the live test suite.
--
-- Secrets added:
--   HASH_PRODUCT_IMAGES_CRON_SECRET   (P2.7 — hash-product-images cron)
--   GENERATE_BLURHASHES_CRON_SECRET   (P2.8 — generate-blurhashes cron)
--   BACKFILL_DIM_CRON_SECRET          (P2.9 — backfill-image-dimensions cron)

CREATE OR REPLACE FUNCTION public.get_edge_function_secret(_name text)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = vault, public, pg_temp
AS $function$
DECLARE
  _secret text;
BEGIN
  IF _name NOT IN (
    'WEBHOOK_DISPATCHER_SECRET',
    'CONNECTIONS_AUTO_TEST_SECRET',
    'CRON_SECRET',
    'HASH_PRODUCT_IMAGES_CRON_SECRET',
    'GENERATE_BLURHASHES_CRON_SECRET',
    'BACKFILL_DIM_CRON_SECRET'
  ) THEN
    RAISE EXCEPTION 'Nome de secret nao autorizado: %', _name USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT decrypted_secret INTO _secret
  FROM vault.decrypted_secrets
  WHERE name = _name
  LIMIT 1;

  IF _secret IS NULL THEN
    RAISE EXCEPTION 'Secret % nao encontrado no vault', _name USING ERRCODE = 'no_data_found';
  END IF;

  RETURN _secret;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_edge_function_secret(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_edge_function_secret(text) FROM anon;
REVOKE ALL ON FUNCTION public.get_edge_function_secret(text) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.get_edge_function_secret(text) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_edge_function_secret(text) TO postgres;

COMMENT ON FUNCTION public.get_edge_function_secret(text) IS
  'Le secret de vault.decrypted_secrets. SECURITY DEFINER. Restrito a nomes whitelisted. Usado por triggers/cron/RPCs que chamam edge functions com auth via header. P2.9: adicionados HASH_PRODUCT_IMAGES_CRON_SECRET, GENERATE_BLURHASHES_CRON_SECRET, BACKFILL_DIM_CRON_SECRET.';

