-- >>> BEGIN 20260617000005_fix_backfill_dim_cron_add_auth_header.sql >>>
-- Migration: P2.9b — fix backfill-image-dimensions cron to include x-cron-secret
-- Applied: 2026-06-17
--
-- The original cron registration (migration 20260616003458) sent no auth header:
--   headers := '{"Content-Type":"application/json"}'::jsonb
--
-- Since authorizeCron requires x-cron-secret to be present (fail-closed SEC-003),
-- every invocation returned 401 — the cron was effectively a no-op.
--
-- This migration re-registers the cron with:
--   1. Dynamic URL via get_edge_functions_base_url() (avoids hardcoded project ID)
--   2. x-cron-secret header read from vault via get_edge_function_secret()
--   3. 55s timeout (same as hash-product-images / generate-blurhashes)

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'backfill-image-dimensions') THEN
    PERFORM cron.unschedule('backfill-image-dimensions');
  END IF;
END $$;

SELECT cron.schedule(
  'backfill-image-dimensions',
  '*/5 * * * *',
  $cron$
  SELECT net.http_post(
    url := public.get_edge_functions_base_url() || '/functions/v1/backfill-image-dimensions',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', public.get_edge_function_secret('BACKFILL_DIM_CRON_SECRET')
    ),
    body := '{"trigger":"cron"}'::jsonb,
    timeout_milliseconds := 55000
  ) AS request_id;
  $cron$
);

-- <<< END 20260617000005_fix_backfill_dim_cron_add_auth_header.sql <<<

-- >>> BEGIN 20260617001236_add_cf_last_checked_at_to_product_images.sql >>>

-- P1.5: Fix cf_verified_at semantic ambiguity
-- cf_verified_at   = timestamp when image was last CONFIRMED PRESENT in Cloudflare
-- cf_last_checked_at = timestamp when CF API was last called (any result: present OR absent)

ALTER TABLE product_images
  ADD COLUMN IF NOT EXISTS cf_last_checked_at TIMESTAMPTZ;

COMMENT ON COLUMN product_images.cf_verified_at IS
  'Timestamp when this image was last confirmed PRESENT in Cloudflare Images API. NULL if never verified or if currently missing.';

COMMENT ON COLUMN product_images.cf_last_checked_at IS
  'Timestamp of the most recent Cloudflare Images API check, regardless of result (verified or missing). Used to track check freshness.';

-- Backfill: for verified records, cf_last_checked_at = cf_verified_at (check confirmed presence)
-- For missing records, cf_last_checked_at = cf_verified_at (check confirmed absence — semantic fix)
UPDATE product_images
SET cf_last_checked_at = cf_verified_at
WHERE cf_verified_at IS NOT NULL
  AND cf_last_checked_at IS NULL;

-- For missing records: cf_verified_at should be NULL (not present = not verified)
-- We preserve the timestamp in cf_last_checked_at then clear cf_verified_at for missing records
UPDATE product_images
SET
  cf_last_checked_at = COALESCE(cf_last_checked_at, cf_verified_at),
  cf_verified_at = NULL
WHERE cf_sync_status = 'missing'
  AND cf_verified_at IS NOT NULL;

-- Index for query performance (checking stale records)
CREATE INDEX IF NOT EXISTS idx_product_images_cf_last_checked_at
  ON product_images (cf_last_checked_at)
  WHERE cf_last_checked_at IS NOT NULL;
;

-- <<< END 20260617001236_add_cf_last_checked_at_to_product_images.sql <<<

-- >>> BEGIN 20260617010114_generate_blurhashes_cron.sql >>>
-- Migration: P2.8 — blurhash population via Edge Function cron
-- Applied: 2026-06-17
--
-- Registers a pg_cron job that calls the `generate-blurhashes` Edge Function
-- every 5 minutes. The function downloads each verified JPEG/PNG image, decodes
-- pixels, resizes to 32x32, and encodes a blurhash string stored in
-- product_images.blurhash. Skips WebP/GIF (unsupported pure-JS decoders).
--
-- Coverage: ~67,344 images (JPEG 54,866 + PNG 12,478 = 93.4% of verified).
-- Throughput: ~480 hashes/hour (40 images x 12 invocations).

-- Index for efficient next-batch selection
CREATE INDEX IF NOT EXISTS idx_product_images_blurhash_null
  ON product_images (is_primary DESC, id)
  WHERE blurhash IS NULL
    AND cf_sync_status = 'verified'
    AND deleted_at IS NULL
    AND format IN ('jpeg', 'png');

-- pg_cron job
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'generate-blurhashes') THEN
    PERFORM cron.unschedule('generate-blurhashes');
  END IF;
END $$;

SELECT cron.schedule(
  'generate-blurhashes',
  '*/5 * * * *',
  $cron$
  SELECT net.http_post(
    url := public.get_edge_functions_base_url() || '/functions/v1/generate-blurhashes',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-cron-secret', public.get_edge_function_secret('GENERATE_BLURHASHES_CRON_SECRET')
    ),
    body := '{"trigger":"cron"}'::jsonb,
    timeout_milliseconds := 55000
  ) AS request_id;
  $cron$
);;

-- <<< END 20260617010114_generate_blurhashes_cron.sql <<<

-- >>> BEGIN 20260617011033_extend_get_edge_function_secret_allowlist.sql >>>
CREATE OR REPLACE FUNCTION public.get_edge_function_secret(_name text)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = vault, public, pg_temp
AS $function$
DECLARE
  _secret text;
BEGIN
  IF _name NOT IN (
    'WEBHOOK_DISPATCHER_SECRET',
    'CONNECTIONS_AUTO_TEST_SECRET',
    'CRON_SECRET',
    'HASH_PRODUCT_IMAGES_CRON_SECRET',
    'GENERATE_BLURHASHES_CRON_SECRET',
    'BACKFILL_DIM_CRON_SECRET'
  ) THEN
    RAISE EXCEPTION 'Nome de secret nao autorizado: %', _name USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT decrypted_secret INTO _secret
  FROM vault.decrypted_secrets
  WHERE name = _name
  LIMIT 1;

  IF _secret IS NULL THEN
    RAISE EXCEPTION 'Secret % nao encontrado no vault', _name USING ERRCODE = 'no_data_found';
  END IF;

  RETURN _secret;
END;
$function$;

REVOKE ALL ON FUNCTION public.get_edge_function_secret(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_edge_function_secret(text) FROM anon;
REVOKE ALL ON FUNCTION public.get_edge_function_secret(text) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.get_edge_function_secret(text) TO service_role;
GRANT EXECUTE ON FUNCTION public.get_edge_function_secret(text) TO postgres;

COMMENT ON FUNCTION public.get_edge_function_secret(text) IS
  'Le secret de vault.decrypted_secrets. SECURITY DEFINER. Restrito a nomes whitelisted. Usado por triggers/cron/RPCs que chamam edge functions com auth via header. P2.9: adicionados HASH_PRODUCT_IMAGES_CRON_SECRET, GENERATE_BLURHASHES_CRON_SECRET, BACKFILL_DIM_CRON_SECRET.';;

-- <<< END 20260617011033_extend_get_edge_function_secret_allowlist.sql <<<

