-- >>> BEGIN 20260617131553_relink_duplicates_remainder_20260617.sql >>>
WITH ranked AS (SELECT id, content_hash, ROW_NUMBER() OVER (PARTITION BY content_hash ORDER BY is_primary DESC NULLS LAST, created_at ASC, id ASC) AS rn, FIRST_VALUE(id) OVER (PARTITION BY content_hash ORDER BY is_primary DESC NULLS LAST, created_at ASC, id ASC) AS canonical_id FROM public.product_images WHERE content_hash IS NOT NULL AND deleted_at IS NULL AND canonical_image_id IS NULL AND content_hash IN (SELECT content_hash FROM public.product_images WHERE content_hash IS NOT NULL AND deleted_at IS NULL GROUP BY content_hash HAVING COUNT(*) > 1)) UPDATE public.product_images pi SET canonical_image_id = r.canonical_id, is_shared = true, last_modified_source = 'claude', updated_at = now() FROM ranked r WHERE pi.id = r.id AND r.rn > 1 AND r.canonical_id <> pi.id; WITH ranked AS (SELECT id, ROW_NUMBER() OVER (PARTITION BY content_hash ORDER BY is_primary DESC NULLS LAST, created_at ASC, id ASC) AS rn FROM public.product_images WHERE content_hash IS NOT NULL AND deleted_at IS NULL AND content_hash IN (SELECT content_hash FROM public.product_images WHERE content_hash IS NOT NULL AND deleted_at IS NULL GROUP BY content_hash HAVING COUNT(*) > 1)) UPDATE public.product_images pi SET is_shared = true, last_modified_source = 'claude', updated_at = now() FROM ranked r WHERE pi.id = r.id AND r.rn = 1 AND pi.is_shared = false;;

-- <<< END 20260617131553_relink_duplicates_remainder_20260617.sql <<<

-- >>> BEGIN 20260617131816_link_synthetic_legacy_dupes_20260617.sql >>>
WITH synthetic AS (SELECT id, cloudflare_image_id, regexp_replace(cloudflare_image_id, '-(leg|dup)-[0-9a-f]+$', '') AS true_cf_id FROM public.product_images WHERE deleted_at IS NULL AND cloudflare_image_id ~ '-(leg|dup)-[0-9a-f]+$'), with_canonical AS (SELECT s.id AS synth_id, c.id AS canonical_id FROM synthetic s JOIN public.product_images c ON c.cloudflare_image_id = s.true_cf_id AND c.deleted_at IS NULL AND c.id <> s.id) UPDATE public.product_images pi SET is_shared = true, canonical_image_id = w.canonical_id, last_modified_source = 'claude', updated_at = now() FROM with_canonical w WHERE pi.id = w.synth_id;;

-- <<< END 20260617131816_link_synthetic_legacy_dupes_20260617.sql <<<

-- >>> BEGIN 20260617132021_fix_canonical_chains_shared_20260617.sql >>>
UPDATE public.product_images SET is_shared = true, last_modified_source = 'claude', updated_at = now() WHERE canonical_image_id IS NOT NULL AND is_shared = false; WITH chains AS (SELECT pi1.id AS child_id, COALESCE(pi3.id, pi2.id) AS root_id FROM public.product_images pi1 JOIN public.product_images pi2 ON pi2.id = pi1.canonical_image_id LEFT JOIN public.product_images pi3 ON pi3.id = pi2.canonical_image_id WHERE pi1.canonical_image_id IS NOT NULL AND pi2.canonical_image_id IS NOT NULL) UPDATE public.product_images pi SET canonical_image_id = c.root_id, last_modified_source = 'claude', updated_at = now() FROM chains c WHERE pi.id = c.child_id AND pi.id <> c.root_id;;

-- <<< END 20260617132021_fix_canonical_chains_shared_20260617.sql <<<

-- >>> BEGIN 20260617132045_resolve_canonical_chains_recursive_20260617.sql >>>
WITH RECURSIVE walk AS (SELECT id AS leaf_id, id AS current_id, canonical_image_id AS next_id, 0 AS depth FROM public.product_images WHERE canonical_image_id IS NOT NULL UNION ALL SELECT w.leaf_id, w.next_id, pi.canonical_image_id, w.depth + 1 FROM walk w JOIN public.product_images pi ON pi.id = w.next_id WHERE pi.canonical_image_id IS NOT NULL AND w.depth < 10), roots AS (SELECT leaf_id, current_id AS root_id, MAX(depth) AS max_depth FROM walk WHERE next_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.product_images p WHERE p.id = walk.next_id AND p.canonical_image_id IS NOT NULL) GROUP BY leaf_id, current_id) UPDATE public.product_images pi SET canonical_image_id = r.root_id, last_modified_source = 'claude', updated_at = now() FROM roots r WHERE pi.id = r.leaf_id AND pi.id <> r.root_id AND r.max_depth > 0;;

-- <<< END 20260617132045_resolve_canonical_chains_recursive_20260617.sql <<<

-- >>> BEGIN 20260617132121_resolve_canonical_cycles_20260617.sql >>>
WITH cycles AS (SELECT pi1.id AS id_a, pi2.id AS id_b FROM public.product_images pi1 JOIN public.product_images pi2 ON pi2.id = pi1.canonical_image_id AND pi2.canonical_image_id = pi1.id WHERE pi1.canonical_image_id IS NOT NULL AND pi2.canonical_image_id IS NOT NULL), root_per_cycle AS (SELECT LEAST(id_a, id_b) AS root_id, GREATEST(id_a, id_b) AS dep_id FROM cycles) UPDATE public.product_images pi SET canonical_image_id = NULL, last_modified_source = 'claude', updated_at = now() FROM root_per_cycle r WHERE pi.id = r.root_id; WITH RECURSIVE walk AS (SELECT id AS leaf_id, canonical_image_id AS next_id, 0 AS depth FROM public.product_images WHERE canonical_image_id IS NOT NULL UNION ALL SELECT w.leaf_id, pi.canonical_image_id, w.depth + 1 FROM walk w JOIN public.product_images pi ON pi.id = w.next_id WHERE pi.canonical_image_id IS NOT NULL AND w.depth < 5), roots AS (SELECT leaf_id, MAX(depth) FILTER (WHERE next_id IS NULL) AS max_d FROM walk GROUP BY leaf_id) SELECT NULL; UPDATE public.product_images SET canonical_image_id = NULL WHERE id IN (SELECT pi1.id FROM public.product_images pi1 JOIN public.product_images pi2 ON pi2.id = pi1.canonical_image_id WHERE pi2.canonical_image_id IS NOT NULL AND pi1.canonical_image_id IS NOT NULL);;

-- <<< END 20260617132121_resolve_canonical_cycles_20260617.sql <<<

-- >>> BEGIN 20260617132321_cleanup_backfill_queue_stale_20260617.sql >>>
UPDATE public.image_backfill_queue q SET status = 'skipped', last_error = 'cleanup: target image no longer eligible (verified status changed, format changed, or attribute already set)', finished_at = now() WHERE q.status = 'pending' AND ((q.task = 'blurhash' AND NOT EXISTS (SELECT 1 FROM public.product_images p WHERE p.id = q.product_image_id AND p.blurhash IS NULL AND p.deleted_at IS NULL AND p.cf_sync_status = 'verified' AND p.format IN ('jpeg','png','webp'))) OR (q.task = 'content_hash' AND NOT EXISTS (SELECT 1 FROM public.product_images p WHERE p.id = q.product_image_id AND p.content_hash IS NULL AND p.deleted_at IS NULL AND p.cf_sync_status = 'verified')) OR (q.task = 'file_size' AND NOT EXISTS (SELECT 1 FROM public.product_images p WHERE p.id = q.product_image_id AND p.file_size_bytes IS NULL AND p.deleted_at IS NULL AND p.cf_sync_status = 'verified')) OR (q.task = 'reupload' AND NOT EXISTS (SELECT 1 FROM public.product_images p WHERE p.id = q.product_image_id AND p.cf_sync_status = 'orphaned' AND p.deleted_at IS NULL)));;

-- <<< END 20260617132321_cleanup_backfill_queue_stale_20260617.sql <<<

-- >>> BEGIN 20260617190154_gap4_fix_rls_audit_tables_security_hardening.sql >>>

-- ============================================================================
-- GAP-4: Security hardening das tabelas de auditoria CF
-- Remove grants indevidos a anon/authenticated + documenta intent via policy
-- Autor: Claude (PhD DB forensics) · 2026-06-17
-- Impacto: ZERO — grants eram inacessíveis por RLS desde criação
-- ============================================================================

-- ── 1. REVOGAR grants enganosos de anon/authenticated ──────────────────────
REVOKE ALL PRIVILEGES ON public._cf_images_audit      FROM anon, authenticated;
REVOKE ALL PRIVILEGES ON public._img_divergence_audit FROM anon, authenticated;

-- ── 2. Garantir acesso correto ao service_role (explícito) ─────────────────
GRANT SELECT, INSERT, UPDATE, DELETE ON public._cf_images_audit      TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public._img_divergence_audit TO service_role;

-- ── 3. Policy RESTRICTIVE explícita: documenta intent de acesso negado ─────
-- service_role e postgres têm BYPASSRLS = nunca afetados por policies
-- anon/authenticated: bloqueados por esta policy + ausência de grant
DROP POLICY IF EXISTS "audit_internal_deny_public" ON public._cf_images_audit;
CREATE POLICY "audit_internal_deny_public"
  ON public._cf_images_audit
  AS RESTRICTIVE
  TO anon, authenticated
  USING (false)
  WITH CHECK (false);

DROP POLICY IF EXISTS "audit_internal_deny_public" ON public._img_divergence_audit;
CREATE POLICY "audit_internal_deny_public"
  ON public._img_divergence_audit
  AS RESTRICTIVE
  TO anon, authenticated
  USING (false)
  WITH CHECK (false);

-- ── 4. COMMENTs que documentam propósito + acesso ──────────────────────────
COMMENT ON TABLE public._cf_images_audit IS
'Mirror local do Cloudflare Images (conta cd0f4eee). 72k+ rows. PK=cf_id.
Populada via fn_cf_audit_ingest(p_rows jsonb) com dados da API CF paginada.
Bidirecionalmente sincronizada com cf_recon.cf_image.
ACESSO: service_role + postgres apenas (BYPASSRLS). anon/authenticated: BLOQUEADO por design.
Criada: 2026-06-16. Última sincronização: 2026-06-17.';

COMMENT ON TABLE public._img_divergence_audit IS
'Log de decisões de remediação durante auditoria CF×DB de 2026-06-16.
Classes: D1_ASIA_COR2 (1.025 rows), D2_KEY (607 rows). Todos executed=true.
Referenciada por fn_asia_reactivate_done_colors e fn_img_remediation_rollback.
ACESSO: service_role + postgres apenas. anon/authenticated: BLOQUEADO por design.';

COMMENT ON FUNCTION public.fn_cf_audit_ingest(jsonb) IS
'Ingest paginado da API Cloudflare Images → _cf_images_audit.
Recebe array JSONB (response CF /images/v1), faz UPSERT por cf_id.
Retorna INTEGER = nº de rows afetadas.
SECURITY DEFINER (roda como postgres, bypassa RLS).
VOLATILE (correto — escreve no DB a cada chamada).
Chamada por: n8n workflow de crawl CF ou script VPS xbz_video_import.js.';
;

-- <<< END 20260617190154_gap4_fix_rls_audit_tables_security_hardening.sql <<<

-- >>> BEGIN 20260617190306_gap3_extend_ghost_queue_status_add_false_positive.sql >>>

-- ============================================================================
-- GAP-3: Adicionar status 'false_positive' ao CHECK constraint
-- Semântica: imagem marcada como morta mas confirmada viva (timing artifact)
-- Distinção importante de 'checked_alive' (verificação genuína de vitalidade)
-- ============================================================================

-- Drop e recria constraint com novo valor
ALTER TABLE cf_recon.cf_ghost_check_queue
  DROP CONSTRAINT cf_ghost_check_queue_status_check;

ALTER TABLE cf_recon.cf_ghost_check_queue
  ADD CONSTRAINT cf_ghost_check_queue_status_check
  CHECK (status = ANY (ARRAY[
    'pending'::text,
    'checked_alive'::text,
    'checked_dead'::text,
    'error'::text,
    'false_positive'::text  -- imagem ghost check prematuro: existia mas não havia sido uploadada ainda
  ]));

-- COMMENT no constraint para documentar o novo valor
COMMENT ON TABLE cf_recon.cf_ghost_check_queue IS
'Fila de verificação de imagens "fantasma" — CF IDs registrados que podem não existir mais.
status: pending=aguardando check | checked_alive=confirmado vivo | checked_dead=confirmado morto
        error=falha no check | false_positive=marcado morto mas imagem uploadada DEPOIS do check.
17.834 rows: 17.827 checked_dead (sem product_images), 7 false_positive (xbz-15465p-*).';
;

