-- >>> BEGIN 20260617214500_audit_estoque_stock_quantity_outliers_view.sql >>>
-- Auditoria Estoque (follow-up revisão P1): garante os slots 4-6 mesmo em DB recriado do zero
-- (idempotente; em produção as colunas já existem). Necessário antes da view/trigger que os usa.
ALTER TABLE public.variant_supplier_sources ADD COLUMN IF NOT EXISTS next_quantity_4 integer;
ALTER TABLE public.variant_supplier_sources ADD COLUMN IF NOT EXISTS next_date_4 date;
ALTER TABLE public.variant_supplier_sources ADD COLUMN IF NOT EXISTS next_quantity_5 integer;
ALTER TABLE public.variant_supplier_sources ADD COLUMN IF NOT EXISTS next_date_5 date;
ALTER TABLE public.variant_supplier_sources ADD COLUMN IF NOT EXISTS next_quantity_6 integer;
ALTER TABLE public.variant_supplier_sources ADD COLUMN IF NOT EXISTS next_date_6 date;

-- Auditoria do módulo Estoque (2026-06-17) — observabilidade NÃO destrutiva.
--
-- Contexto: a auditoria identificou que o "Estoque Futuro" e o total de unidades
-- do dashboard são dominados por outliers de quantidade vindos de feeds de
-- fornecedor (ex.: uma única variação com 2.234.529 un.). Em vez de sobrescrever
-- dados de fornecedor (que podem ser legítimos para itens a granel), expomos uma
-- VIEW de revisão manual. Read-only, security_invoker (sem novo lint
-- security_definer_view), sem grant para anon (somente authenticated/admin).
create or replace view public.vw_stock_quantity_outliers
with (security_invoker = true) as
select
  vss.id          as source_id,
  vss.variant_id,
  pv.product_id,
  p.sku           as product_sku,
  p.name          as product_name,
  vss.supplier_id,
  vsp.name        as supplier_name,
  vss.quantity    as current_quantity,
  greatest(
    coalesce(vss.next_quantity_1,0), coalesce(vss.next_quantity_2,0), coalesce(vss.next_quantity_3,0),
    coalesce(vss.next_quantity_4,0), coalesce(vss.next_quantity_5,0), coalesce(vss.next_quantity_6,0)
  )               as max_future_quantity,
  vss.updated_at,
  case
    when vss.quantity >= 1000000 then 'extreme'
    when vss.quantity >= 100000  then 'high'
    else 'elevated'
  end             as severity
from public.variant_supplier_sources vss
join public.product_variants pv on pv.id = vss.variant_id
join public.products p          on p.id  = pv.product_id
left join public.v_suppliers_public vsp on vsp.id = vss.supplier_id
where vss.is_active
  and (
    vss.quantity >= 50000
    or greatest(
        coalesce(vss.next_quantity_1,0), coalesce(vss.next_quantity_2,0), coalesce(vss.next_quantity_3,0),
        coalesce(vss.next_quantity_4,0), coalesce(vss.next_quantity_5,0), coalesce(vss.next_quantity_6,0)
       ) >= 50000
  );

comment on view public.vw_stock_quantity_outliers is
  'Observabilidade (read-only): linhas de variant_supplier_sources com quantidade atual/futura implausivel (>=50k un.) para revisao manual de erros de feed de fornecedor. Nao altera dados. Criada na auditoria do modulo Estoque 2026-06-17.';

grant select on public.vw_stock_quantity_outliers to authenticated;

-- <<< END 20260617214500_audit_estoque_stock_quantity_outliers_view.sql <<<

-- >>> BEGIN 20260617215342_repair_mockup_assets_bucket_drift.sql >>>

-- AUDIT 2026-06-17: the `mockup-assets` bucket is declared by migration
-- 20260215185444 but is ABSENT in production (drift). The generate-mockup edge
-- function, mockup-storage.uploadLogoToStorage and approval/OffscreenLayoutCapture
-- all upload to it and call getPublicUrl -> every upload was failing with
-- "Bucket not found". Re-create it (public) + per-user-folder RLS, idempotently.

INSERT INTO storage.buckets (id, name, public)
VALUES ('mockup-assets', 'mockup-assets', true)
ON CONFLICT (id) DO UPDATE SET public = true;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='Anyone can view mockup assets') THEN
    CREATE POLICY "Anyone can view mockup assets"
      ON storage.objects FOR SELECT
      USING (bucket_id = 'mockup-assets');
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='Users can upload their own mockup assets') THEN
    CREATE POLICY "Users can upload their own mockup assets"
      ON storage.objects FOR INSERT
      WITH CHECK (bucket_id = 'mockup-assets' AND auth.uid()::text = (storage.foldername(name))[1]);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='Users can update their own mockup assets') THEN
    CREATE POLICY "Users can update their own mockup assets"
      ON storage.objects FOR UPDATE
      USING (bucket_id = 'mockup-assets' AND auth.uid()::text = (storage.foldername(name))[1]);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='Users can delete their own mockup assets') THEN
    CREATE POLICY "Users can delete their own mockup assets"
      ON storage.objects FOR DELETE
      USING (bucket_id = 'mockup-assets' AND auth.uid()::text = (storage.foldername(name))[1]);
  END IF;
END $$;
;

-- <<< END 20260617215342_repair_mockup_assets_bucket_drift.sql <<<

