-- >>> BEGIN 20260617215816_harden_generate_quote_number_advisory_lock.sql >>>
-- BUG P1: generate_quote_number usava MAX(...)+1 sem serialização. Sob concorrência
-- (2 vendedores criando orçamento no mesmo instante), ambos liam o mesmo MAX e geravam
-- o MESMO quote_number → violação da UNIQUE quotes_quote_number_key (SQLSTATE 23505),
-- sem retry. Correção: pg_advisory_xact_lock por ANO. O lock é liberado no commit/rollback;
-- a segunda transação espera, relê o MAX já atualizado e gera o próximo número.
CREATE OR REPLACE FUNCTION public.generate_quote_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE year_short text; max_num integer; new_number text;
BEGIN
  -- Só calcula/gera se o número ainda não foi informado.
  IF NEW.quote_number IS NOT NULL AND NEW.quote_number <> '' THEN
    RETURN NEW;
  END IF;

  year_short := to_char(now(), 'YY');

  -- Serializa a geração por ano (transaction-scoped: liberado no commit/rollback).
  PERFORM pg_advisory_xact_lock(hashtext('quote_number:' || year_short)::bigint);

  SELECT COALESCE(MAX(
    CASE WHEN split_part(quote_number, '/', 1) ~ '^\d+$'
         THEN split_part(quote_number, '/', 1)::integer ELSE 0 END
  ), 10000) INTO max_num
  FROM public.quotes WHERE quote_number LIKE '%/' || year_short;

  new_number := (max_num + 1)::text || '/' || year_short;
  NEW.quote_number := new_number;
  RETURN NEW;
END;
$function$;;

-- <<< END 20260617215816_harden_generate_quote_number_advisory_lock.sql <<<

-- >>> BEGIN 20260617215830_fix_quote_items_delete_rls_allow_quote_access.sql >>>
-- BUG P1: a policy quote_items_delete exigia is_org_owner_or_admin(), mas o RPC
-- update_quote_transactional (SECURITY INVOKER) faz DELETE dos itens antigos antes
-- de reinserir. Resultado: vendedor comum editando o PRÓPRIO orçamento recebia
-- "permission denied" no DELETE → toda a edição falhava. INSERT/SELECT/UPDATE já
-- usavam can_access_quote; o DELETE estava fora de padrão.
-- Segurança preservada: o trigger trg_quote_items_parent_immutable (BEFORE INS/UPD/DEL)
-- continua bloqueando qualquer alteração em itens de orçamentos approved/converted.
DROP POLICY IF EXISTS quote_items_delete ON public.quote_items;
CREATE POLICY quote_items_delete ON public.quote_items
  FOR DELETE
  USING (can_access_quote(quote_id));;

-- <<< END 20260617215830_fix_quote_items_delete_rls_allow_quote_access.sql <<<

-- >>> BEGIN 20260617215841_fix_qip_insert_rls_allow_coordinator.sql >>>
-- BUG P3 (hardening de consistência): qip_insert_own_quote só permitia o seller_id,
-- enquanto qip_select/update/delete já incluem is_coord_or_above(). Isso bloqueava um
-- coordenador (ou acima) de inserir personalizações ao editar o orçamento de um vendedor,
-- gerando falha assimétrica no update transacional. Alinhamos a regra de INSERT às demais.
DROP POLICY IF EXISTS qip_insert_own_quote ON public.quote_item_personalizations;
CREATE POLICY qip_insert_own_quote ON public.quote_item_personalizations
  FOR INSERT
  WITH CHECK (EXISTS (
    SELECT 1
    FROM public.quote_items qi
    JOIN public.quotes q ON q.id = qi.quote_id
    WHERE qi.id = quote_item_personalizations.quote_item_id
      AND (q.seller_id = (SELECT auth.uid()) OR is_coord_or_above((SELECT auth.uid())))
  ));;

-- <<< END 20260617215841_fix_qip_insert_rls_allow_coordinator.sql <<<

-- >>> BEGIN 20260617215920_fix_update_quote_transactional_persist_price_fields.sql >>>
-- BUG P2: ao reinserir os itens, update_quote_transactional NÃO copiava
-- price_confirmed_at → toda edição do orçamento zerava a confirmação de preço do item.
-- Também ignorava price_updated_at, price_freshness_threshold_days e bitrix_product_id,
-- campos coletados pelo builder (addProductWithColor/confirmItemPrice) e necessários para
-- o indicador de frescor de preço e para a sincronização com o Bitrix.
-- Leitura defensiva (nullif/coalesce) mantém retrocompatibilidade com payloads sem esses campos.
CREATE OR REPLACE FUNCTION public.update_quote_transactional(_quote_id uuid, _quote_patch jsonb, _items jsonb)
 RETURNS quotes
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  _updated_quote public.quotes;
  _item          jsonb;
  _pers          jsonb;
  _new_item_id   uuid;
begin
  -- ── 1. Atualiza o orçamento ────────────────────────────────────────────────
  update public.quotes
  set
    client_id                = coalesce(nullif(_quote_patch->>'client_id', ''), client_id::text)::uuid,
    client_name              = coalesce(nullif(_quote_patch->>'client_name', ''), client_name),
    client_email             = coalesce(_quote_patch->>'client_email',     client_email),
    client_phone             = coalesce(_quote_patch->>'client_phone',     client_phone),
    client_company           = coalesce(_quote_patch->>'client_company',   client_company),
    status                   = coalesce(_quote_patch->>'status',           status),
    shipping_type            = coalesce(_quote_patch->>'shipping_type',    shipping_type),
    shipping_cost            = coalesce((_quote_patch->>'shipping_cost')::numeric,            shipping_cost),
    payment_method           = coalesce(_quote_patch->>'payment_method',   payment_method),
    payment_terms            = coalesce(_quote_patch->>'payment_terms',    payment_terms),
    delivery_time            = coalesce(_quote_patch->>'delivery_time',    delivery_time),
    notes                    = coalesce(_quote_patch->>'notes',            notes),
    internal_notes           = coalesce(_quote_patch->>'internal_notes',   internal_notes),
    discount_percent         = coalesce((_quote_patch->>'discount_percent')::numeric,         discount_percent),
    discount_amount          = coalesce((_quote_patch->>'discount_amount')::numeric,          discount_amount),
    subtotal                 = coalesce((_quote_patch->>'subtotal')::numeric,                 subtotal),
    total                    = coalesce((_quote_patch->>'total')::numeric,                    total),
    negotiation_markup_percent = coalesce((_quote_patch->>'negotiation_markup_percent')::numeric, negotiation_markup_percent),
    valid_until              = coalesce((_quote_patch->>'valid_until')::date,                 valid_until),
    updated_at               = now()
  where id = _quote_id
  returning * into _updated_quote;

  if _updated_quote is null then
    raise exception 'Orçamento não encontrado: %', _quote_id
      using errcode = 'no_data_found';
  end if;

  -- ── 2. Remove itens/personalizações existentes ────────────────────────────
  delete from public.quote_item_personalizations
  where quote_item_id in (
    select id from public.quote_items where quote_id = _quote_id
  );
  delete from public.quote_items where quote_id = _quote_id;

  -- ── 3. Reinsere itens ─────────────────────────────────────────────────────
  for _item in select value from jsonb_array_elements(coalesce(_items, '[]'::jsonb)) loop
    insert into public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days, bitrix_product_id
    )
    values (
      _quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', '')
    )
    returning id into _new_item_id;

    -- ── 4. Reinsere personalizações ─────────────────────────────────────────
    for _pers in select value from jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb)) loop
      insert into public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      values (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    end loop;
  end loop;

  return _updated_quote;
end;
$function$;;

-- <<< END 20260617215920_fix_update_quote_transactional_persist_price_fields.sql <<<

-- >>> BEGIN 20260617215943_fix_recalc_freight_only_fob_pre.sql >>>
-- BUG P2 (split-brain de frete): o recálculo no banco somava shipping_cost ao total
-- para shipping_type IN ('fob','fob_pre'), mas o frontend (calculateQuoteTotals) e a
-- semântica de negócio somam apenas 'fob_pre' (cif = cortesia; fob = cliente paga direto
-- à transportadora; fob_pre = pré-negociado, com custo embutido). Hoje converge porque
-- 'fob' sempre chega com custo 0, mas é um bug latente: bastaria um 'fob' com custo > 0
-- para o total do banco divergir do total exibido. Alinhamos o gatilho ao SSOT do frontend.
CREATE OR REPLACE FUNCTION public.fn_quotes_recalc_subtotal_from_items()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _quote_id uuid;
  _quote_status text;
  _markup numeric;
  _disc_amount_db numeric;
  _disc_pct numeric;
  _ship_type text;
  _ship_cost numeric;
  _real_subtotal numeric(12,2);
  _new_subtotal numeric(12,2);
  _ship_value numeric(12,2);
  _disc_value numeric(12,2);
  _new_total numeric(12,2);
BEGIN
  _quote_id := COALESCE(NEW.quote_id, OLD.quote_id);
  IF _quote_id IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;

  SELECT
    status,
    LEAST(50, GREATEST(0, COALESCE(negotiation_markup_percent, 0))),
    COALESCE(discount_amount, 0),
    COALESCE(discount_percent, 0),
    shipping_type,
    COALESCE(shipping_cost, 0)
  INTO _quote_status, _markup, _disc_amount_db, _disc_pct, _ship_type, _ship_cost
  FROM public.quotes WHERE id = _quote_id;

  -- Nao mexer em quotes aprovados/convertidos (imutaveis)
  IF _quote_status IN ('approved', 'converted') THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  -- REAL: soma pura dos itens (sem markup)
  SELECT COALESCE(SUM(quantity * unit_price + COALESCE(personalization_cost, 0)), 0)
  INTO _real_subtotal
  FROM public.quote_items
  WHERE quote_id = _quote_id;

  -- APRESENTADO ao cliente: aplica markup
  _new_subtotal := ROUND(_real_subtotal * (1 + _markup / 100.0), 2);

  -- DESCONTO: discount_percent tem prioridade (espelha logica do frontend)
  IF _disc_pct > 0 THEN
    _disc_value := ROUND(_new_subtotal * (_disc_pct / 100.0), 2);
  ELSE
    _disc_value := _disc_amount_db;
  END IF;

  -- FRETE: somente 'fob_pre' (pré-negociado com custo) entra no total.
  -- Alinhado ao frontend (calculateQuoteTotals): cif/fob/null não somam.
  _ship_value := CASE WHEN _ship_type = 'fob_pre' THEN _ship_cost ELSE 0 END;

  -- TOTAL final
  _new_total := _new_subtotal - _disc_value + _ship_value;

  -- UPDATE apenas se mudou (evita loop com trigger BEFORE em quotes)
  UPDATE public.quotes
  SET subtotal = _new_subtotal,
      total = _new_total,
      discount_amount = _disc_value,
      updated_at = now()
  WHERE id = _quote_id
    AND (subtotal IS DISTINCT FROM _new_subtotal
      OR total IS DISTINCT FROM _new_total
      OR discount_amount IS DISTINCT FROM _disc_value);

  RETURN COALESCE(NEW, OLD);
END;
$function$;;

