-- >>> BEGIN 20260618000007_enhance_drift_dashboard_v2.sql >>>
-- Migration: enhance_drift_dashboard_v2_20260618
-- Purpose: Rebuild v_cf_drift_dashboard with 21 metrics including canonical dedup stats
-- Adds: pi_canonical_deps, pi_canonical_roots, pi_has_blurhash, pi_has_content_hash,
--       pi_null_format, pi_shared_no_canonical, pct_deduplicated, pct_blurhash, pct_content_hash

BEGIN;

DROP VIEW IF EXISTS public.v_cf_drift_dashboard;

CREATE VIEW public.v_cf_drift_dashboard
WITH (security_invoker = true)
AS
WITH stats AS (
  SELECT
    (SELECT COUNT(*) FROM cf_recon.cf_image)                                                   AS recon_total,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL)                       AS pi_active_total,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND cf_sync_status='verified')   AS pi_verified,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND cf_sync_status='orphaned')   AS pi_orphaned,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND cf_sync_status='missing')    AS pi_missing,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NOT NULL)                   AS pi_soft_deleted,
    (SELECT COUNT(*) FROM cf_recon.cf_image c
     WHERE NOT EXISTS (SELECT 1 FROM public.product_images p
       WHERE p.cloudflare_image_id = c.image_id AND p.deleted_at IS NULL))                     AS cf_orphans_not_in_pi,
    (SELECT COUNT(*) FROM public.product_images p
     WHERE p.deleted_at IS NULL AND p.cf_sync_status='verified'
       AND NOT EXISTS (SELECT 1 FROM cf_recon.cf_image c WHERE c.image_id = p.cloudflare_image_id)) AS pi_verified_no_recon,
    (SELECT COUNT(*) FROM public.image_backfill_queue WHERE status='pending')                  AS backfill_queue_pending,
    (SELECT COUNT(*) FROM public.image_backfill_queue WHERE status='skipped')                  AS backfill_queue_skipped,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND canonical_image_id IS NOT NULL) AS pi_canonical_deps,
    (SELECT COUNT(DISTINCT canonical_image_id) FROM public.product_images WHERE deleted_at IS NULL AND canonical_image_id IS NOT NULL) AS pi_canonical_roots,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND blurhash IS NOT NULL)         AS pi_has_blurhash,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND content_hash IS NOT NULL)     AS pi_has_content_hash,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND format IS NULL)               AS pi_null_format,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND is_shared = true AND canonical_image_id IS NULL) AS pi_shared_no_canonical
), computed AS (
  SELECT
    *,
    ROUND(pi_verified::numeric / NULLIF(pi_active_total, 0) * 100, 2)      AS pct_verified_active,
    ROUND(cf_orphans_not_in_pi::numeric / NULLIF(recon_total, 0) * 100, 2) AS pct_cf_orphans,
    ROUND(pi_has_blurhash::numeric / NULLIF(pi_active_total, 0) * 100, 2)  AS pct_blurhash,
    ROUND(pi_has_content_hash::numeric / NULLIF(pi_active_total, 0) * 100, 2) AS pct_content_hash,
    ROUND(pi_canonical_deps::numeric / NULLIF(pi_active_total, 0) * 100, 2) AS pct_deduplicated
  FROM stats
)
SELECT * FROM computed;

REVOKE SELECT ON public.v_cf_drift_dashboard FROM anon, authenticated;
GRANT SELECT ON public.v_cf_drift_dashboard TO service_role;

COMMIT;

-- <<< END 20260618000007_enhance_drift_dashboard_v2.sql <<<

-- >>> BEGIN 20260618000008_autolink_trigger_and_reconcile_fn.sql >>>
-- Migration: link_residual_groups_and_autolink_trigger_20260618
-- Purpose: Auto-link trigger for future canonical dedup + reconcile_cf_image_status function
-- Creates:
--   fn_autolink_canonical_on_content_hash() — BEFORE UPDATE trigger function
--   trg_autolink_canonical_on_content_hash — fires on UPDATE OF content_hash
--   reconcile_cf_image_status(p_cf_id, p_exists) — edge function callable reconciler

BEGIN;

-- Auto-link trigger function: links image to canonical group when content_hash is first populated
CREATE OR REPLACE FUNCTION public.fn_autolink_canonical_on_content_hash()
RETURNS TRIGGER LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
DECLARE
  v_root_id uuid;
BEGIN
  -- Only act when content_hash is being set for the first time
  IF NEW.content_hash IS NULL OR (OLD.content_hash IS NOT NULL AND OLD.content_hash = NEW.content_hash) THEN
    RETURN NEW;
  END IF;
  -- Do not override an existing canonical assignment
  IF NEW.canonical_image_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  -- Find the oldest root in the group (is_shared=false, canonical_image_id=NULL)
  SELECT id INTO v_root_id
  FROM public.product_images
  WHERE content_hash = NEW.content_hash
    AND deleted_at IS NULL
    AND canonical_image_id IS NULL
    AND id <> NEW.id
    AND is_shared = false
  ORDER BY created_at ASC, id ASC
  LIMIT 1;

  IF v_root_id IS NOT NULL THEN
    NEW.canonical_image_id := v_root_id;
    NEW.is_shared := true;
  ELSE
    -- Fallback: inherit root from existing dependent in same group
    SELECT pi2.canonical_image_id INTO v_root_id
    FROM public.product_images pi2
    WHERE pi2.content_hash = NEW.content_hash
      AND pi2.deleted_at IS NULL
      AND pi2.canonical_image_id IS NOT NULL
      AND pi2.id <> NEW.id
    LIMIT 1;

    IF v_root_id IS NOT NULL THEN
      NEW.canonical_image_id := v_root_id;
      NEW.is_shared := true;
    END IF;
    -- If only member → remain as root
  END IF;

  RETURN NEW;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_autolink_canonical_on_content_hash() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_autolink_canonical_on_content_hash() TO service_role;

DROP TRIGGER IF EXISTS trg_autolink_canonical_on_content_hash ON public.product_images;
CREATE TRIGGER trg_autolink_canonical_on_content_hash
  BEFORE UPDATE OF content_hash
  ON public.product_images
  FOR EACH ROW
  WHEN (NEW.content_hash IS NOT NULL AND (OLD.content_hash IS NULL OR OLD.content_hash <> NEW.content_hash))
  EXECUTE FUNCTION public.fn_autolink_canonical_on_content_hash();

-- Reconcile function: called by edge function after CF verification check
CREATE OR REPLACE FUNCTION public.reconcile_cf_image_status(p_cf_id text, p_exists boolean)
RETURNS TABLE(action text, rows_affected integer)
LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
DECLARE
  v_now timestamptz := now();
  v_rows int := 0;
BEGIN
  IF p_exists THEN
    UPDATE public.product_images
    SET
      cf_sync_status      = 'verified',
      cf_verified_at      = COALESCE(cf_verified_at, v_now),
      cf_last_checked_at  = v_now,
      cf_last_error       = NULL,
      last_modified_source = 'edge_function',
      updated_at          = v_now
    WHERE cloudflare_image_id = p_cf_id
      AND deleted_at IS NULL
      AND cf_sync_status <> 'verified';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    RETURN QUERY SELECT 'mark_verified'::text, v_rows;
  ELSE
    UPDATE public.product_images
    SET
      cf_sync_status      = 'missing',
      cf_check_attempts   = cf_check_attempts + 1,
      cf_last_checked_at  = v_now,
      cf_last_error       = COALESCE(cf_last_error, '') || ' | ' || v_now::text || ' recon: not_found_in_cloudflare',
      last_modified_source = 'edge_function',
      updated_at          = v_now
    WHERE cloudflare_image_id = p_cf_id
      AND deleted_at IS NULL
      AND cf_sync_status = 'verified';
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    RETURN QUERY SELECT 'mark_missing'::text, v_rows;
  END IF;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.reconcile_cf_image_status(text, boolean) FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.reconcile_cf_image_status(text, boolean) TO service_role;

COMMIT;

-- <<< END 20260618000008_autolink_trigger_and_reconcile_fn.sql <<<

-- >>> BEGIN 20260618000009_health_check_function.sql >>>
-- Migration: create_health_check_function_20260618
-- Purpose: 15-invariant health check for product_images integrity
-- Function: public.fn_product_images_health_check()
-- Checks: C01–C15 covering CF equivalence, canonical dedup, soft-delete, CDN URLs, sync

BEGIN;

CREATE OR REPLACE FUNCTION public.fn_product_images_health_check()
RETURNS TABLE(check_name text, status text, value bigint, threshold bigint, details text)
LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
BEGIN
  -- C01: All active images verified in CF
  RETURN QUERY SELECT
    'c01_all_active_verified'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images not verified in CF'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND cf_sync_status <> 'verified';

  -- C02: Zero CF orphans (CF has image not in product_images)
  RETURN QUERY SELECT
    'c02_zero_cf_orphans'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'CF images not in product_images'::text
  FROM cf_recon.cf_image c
  WHERE NOT EXISTS (SELECT 1 FROM public.product_images p
    WHERE p.cloudflare_image_id = c.image_id AND p.deleted_at IS NULL);

  -- C03: cf_recon count matches active product_images count (±5 tolerance)
  RETURN QUERY SELECT
    'c03_recon_pi_sync'::text,
    CASE WHEN ABS(c.recon_total - c.pi_total) <= 5 THEN 'OK' ELSE 'WARN' END,
    ABS(c.recon_total - c.pi_total), 5::bigint,
    'Difference between cf_recon.cf_image and active product_images'::text
  FROM (SELECT
    (SELECT COUNT(*) FROM cf_recon.cf_image) AS recon_total,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL) AS pi_total
  ) c;

  -- C04: No duplicate cloudflare_image_id among active images
  RETURN QUERY SELECT
    'c04_no_duplicate_cf_id'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Duplicate cloudflare_image_id in active images'::text
  FROM (SELECT cloudflare_image_id
    FROM public.product_images WHERE deleted_at IS NULL
    GROUP BY cloudflare_image_id HAVING COUNT(*) > 1) dup;

  -- C05: Soft-deleted images always have a reason
  RETURN QUERY SELECT
    'c05_soft_delete_has_reason'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Soft-deleted images without deleted_reason'::text
  FROM public.product_images
  WHERE deleted_at IS NOT NULL AND (deleted_reason IS NULL OR deleted_reason = '');

  -- C06: No is_active=true on soft-deleted rows
  RETURN QUERY SELECT
    'c06_no_active_deleted'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active=true but soft-deleted images'::text
  FROM public.product_images
  WHERE deleted_at IS NOT NULL AND is_active = true;

  -- C07: Canonical chains are flat (no A→B→C, only A→B)
  RETURN QUERY SELECT
    'c07_canonical_chains_flat'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical pointing to non-root (chain detected)'::text
  FROM public.product_images pi_child
  JOIN public.product_images pi_root ON pi_root.id = pi_child.canonical_image_id
  WHERE pi_child.canonical_image_id IS NOT NULL AND pi_root.canonical_image_id IS NOT NULL;

  -- C08: No canonical cycles (A→B, B→A)
  RETURN QUERY SELECT
    'c08_no_canonical_cycles'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical cycles detected (A→B, B→A)'::text
  FROM public.product_images a
  JOIN public.product_images b ON b.id = a.canonical_image_id AND b.canonical_image_id = a.id;

  -- C09: is_shared=true always has canonical_image_id
  RETURN QUERY SELECT
    'c09_shared_has_canonical'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'is_shared=true without canonical_image_id'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND is_shared = true AND canonical_image_id IS NULL;

  -- C10: All active images have valid CDN URLs
  RETURN QUERY SELECT
    'c10_valid_cdn_urls'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with invalid url_cdn'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND (url_cdn IS NULL OR url_cdn NOT LIKE 'https://imagedelivery.net/%');

  -- C11: No NULL format on active images
  RETURN QUERY SELECT
    'c11_no_null_format'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with NULL format'::text
  FROM public.product_images WHERE deleted_at IS NULL AND format IS NULL;

  -- C12: Alt-text coverage (all active images have meaningful alt text ≥10 chars)
  RETURN QUERY SELECT
    'c12_alt_text_coverage'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with missing/short alt_text'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND (alt_text IS NULL OR LENGTH(alt_text) < 10);

  -- C13: Canonical pointers do not target soft-deleted images
  RETURN QUERY SELECT
    'c13_canonical_not_deleted'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical pointing to soft-deleted image'::text
  FROM public.product_images pi
  WHERE pi.canonical_image_id IS NOT NULL
    AND EXISTS (SELECT 1 FROM public.product_images root
      WHERE root.id = pi.canonical_image_id AND root.deleted_at IS NOT NULL);

  -- C14: No NULL display_order on active images
  RETURN QUERY SELECT
    'c14_display_order_not_null'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with NULL display_order'::text
  FROM public.product_images WHERE deleted_at IS NULL AND display_order IS NULL;

  -- C15: products.primary_image_url in sync with product_images (±5 tolerance)
  RETURN QUERY SELECT
    'c15_primary_image_url_sync'::text,
    CASE WHEN COUNT(*) <= 5 THEN 'OK' ELSE 'WARN' END,
    COUNT(*), 5::bigint,
    'Products where primary_image_url diverges from product_images primary'::text
  FROM public.products p
  JOIN public.product_images pi ON pi.product_id = p.id
    AND pi.is_primary = true AND pi.is_active = true AND pi.deleted_at IS NULL
  WHERE p.is_active = true AND (p.is_deleted IS NULL OR p.is_deleted = false)
    AND p.primary_image_url IS NOT NULL AND p.primary_image_url <> pi.url_cdn;

END;
$$;

REVOKE ALL ON FUNCTION public.fn_product_images_health_check() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_product_images_health_check() TO service_role;

COMMIT;

-- <<< END 20260618000009_health_check_function.sql <<<

-- >>> BEGIN 20260618000010_flatten_canonical_chains.sql >>>
-- Migration: flatten_canonical_chains_20260618 + fix_shared_null_after_flatten_20260618
-- Purpose: Flatten any A→B→C canonical chains to A→C (all deps point directly to root)
-- Then fix CTE artefact where final_root_id resolved to NULL for true roots
-- Result: 65 chains flattened; 65 CTE artefacts corrected via 3-step fix

BEGIN;

-- Step 1: Flatten chains — update deps that point to a non-root to point to the true root
UPDATE public.product_images pi_dep
SET
  canonical_image_id  = pi_root.id,
  last_modified_source = 'migration',
  updated_at          = now()
FROM public.product_images pi_mid
JOIN public.product_images pi_root ON pi_root.id = pi_mid.canonical_image_id
WHERE pi_dep.canonical_image_id = pi_mid.id
  AND pi_mid.canonical_image_id IS NOT NULL  -- pi_mid is itself a dep, not a root
  AND pi_root.canonical_image_id IS NULL     -- pi_root is a true root
  AND pi_dep.deleted_at IS NULL;

-- Step 2 (CTE artefact fix — 3 sub-steps):

-- 2a: Relink is_shared=true / canonical=NULL to root via content_hash (where root exists)
WITH fixable AS (
  SELECT pi.id, g.root_id
  FROM public.product_images pi
  JOIN (
    SELECT content_hash, MIN(id ORDER BY created_at ASC, id ASC) AS root_id
    FROM public.product_images
    WHERE content_hash IS NOT NULL
      AND deleted_at IS NULL
      AND is_shared = false
      AND canonical_image_id IS NULL
    GROUP BY content_hash
  ) g ON g.content_hash = pi.content_hash
  WHERE pi.deleted_at IS NULL
    AND pi.is_shared = true
    AND pi.canonical_image_id IS NULL
    AND pi.id <> g.root_id
)
UPDATE public.product_images pi
SET
  canonical_image_id  = f.root_id,
  last_modified_source = 'migration',
  updated_at          = now()
FROM fixable f
WHERE pi.id = f.id;

-- 2b: For content_hash groups where ALL members lost their canonical (all zeroed by CTE bug),
--     elect the oldest as root and relink the rest
WITH orphan_groups AS (
  SELECT content_hash
  FROM public.product_images
  WHERE deleted_at IS NULL
    AND is_shared = true
    AND canonical_image_id IS NULL
    AND content_hash IS NOT NULL
  GROUP BY content_hash
),
roots AS (
  SELECT DISTINCT ON (og.content_hash) pi.id AS root_id, og.content_hash
  FROM orphan_groups og
  JOIN public.product_images pi ON pi.content_hash = og.content_hash AND pi.deleted_at IS NULL
  ORDER BY og.content_hash, pi.created_at ASC, pi.id ASC
)
-- Promote oldest member to non-shared root
UPDATE public.product_images pi
SET
  is_shared           = false,
  canonical_image_id  = NULL,
  last_modified_source = 'migration',
  updated_at          = now()
FROM roots r
WHERE pi.id = r.root_id;

-- 2c: Relink remaining is_shared=true / canonical=NULL to the newly elected roots
WITH newly_fixed AS (
  SELECT pi.id, g.root_id
  FROM public.product_images pi
  JOIN (
    SELECT content_hash, id AS root_id
    FROM public.product_images
    WHERE deleted_at IS NULL
      AND is_shared = false
      AND canonical_image_id IS NULL
      AND content_hash IS NOT NULL
  ) g ON g.content_hash = pi.content_hash
  WHERE pi.deleted_at IS NULL
    AND pi.is_shared = true
    AND pi.canonical_image_id IS NULL
    AND pi.id <> g.root_id
)
UPDATE public.product_images pi
SET
  canonical_image_id  = f.root_id,
  last_modified_source = 'migration',
  updated_at          = now()
FROM newly_fixed f
WHERE pi.id = f.id;

COMMIT;

-- <<< END 20260618000010_flatten_canonical_chains.sql <<<

-- >>> BEGIN 20260618000215_estoque_outlier_view_severity_fix.sql >>>

-- Auditoria Estoque (follow-up de revisão): a severidade considerava só
-- vss.quantity, mas o WHERE admite linhas também por estoque FUTURO. Agora a
-- severidade usa GREATEST(quantity, max_future) — classifica corretamente
-- linhas que entram pela janela de futuro. (CodeRabbit/Cubic P2)
create or replace view public.vw_stock_quantity_outliers
with (security_invoker = true) as
select
  vss.id            as source_id,
  vss.variant_id,
  pv.product_id,
  p.sku             as product_sku,
  p.name            as product_name,
  vss.supplier_id,
  vsp.name          as supplier_name,
  vss.quantity      as current_quantity,
  greatest(coalesce(vss.next_quantity_1,0), coalesce(vss.next_quantity_2,0), coalesce(vss.next_quantity_3,0),
           coalesce(vss.next_quantity_4,0), coalesce(vss.next_quantity_5,0), coalesce(vss.next_quantity_6,0)) as max_future_quantity,
  vss.updated_at,
  case
    when greatest(coalesce(vss.quantity,0),
                  coalesce(vss.next_quantity_1,0), coalesce(vss.next_quantity_2,0), coalesce(vss.next_quantity_3,0),
                  coalesce(vss.next_quantity_4,0), coalesce(vss.next_quantity_5,0), coalesce(vss.next_quantity_6,0)) >= 1000000 then 'extreme'
    when greatest(coalesce(vss.quantity,0),
                  coalesce(vss.next_quantity_1,0), coalesce(vss.next_quantity_2,0), coalesce(vss.next_quantity_3,0),
                  coalesce(vss.next_quantity_4,0), coalesce(vss.next_quantity_5,0), coalesce(vss.next_quantity_6,0)) >= 100000 then 'high'
    else 'elevated'
  end as severity
from variant_supplier_sources vss
join product_variants pv on pv.id = vss.variant_id
join products p on p.id = pv.product_id
left join v_suppliers_public vsp on vsp.id = vss.supplier_id
where vss.is_active and (
  vss.quantity >= 50000
  or greatest(coalesce(vss.next_quantity_1,0), coalesce(vss.next_quantity_2,0), coalesce(vss.next_quantity_3,0),
              coalesce(vss.next_quantity_4,0), coalesce(vss.next_quantity_5,0), coalesce(vss.next_quantity_6,0)) >= 50000
);

comment on view public.vw_stock_quantity_outliers is
  'Observabilidade (read-only): linhas de vss com quantidade atual OU futura implausivelmente alta (>=50k) p/ revisão manual. Severidade = GREATEST(atual, futuro). NÃO altera dados; os valores são, em sua maioria, granel legítimo de grandes distribuidores. Auditoria Estoque 2026-06-17.';
;

-- <<< END 20260618000215_estoque_outlier_view_severity_fix.sql <<<

-- >>> BEGIN 20260618000747_quotes_calc_real_values_markup_fail_loud.sql >>>
-- Melhoria #1: markup fail-loud.
-- Antes: o trigger sobrescrevia NEW.negotiation_markup_percent com o valor clampado em
-- [0,50], mascarando o CHECK valid_negotiation_markup_range e tornando markup fora de faixa
-- um clamp SILENCIOSO (inconsistente com o frontend, que lança erro acima de 50).
-- Agora: o valor cru chega ao CHECK e é REJEITADO se fora de [0,50]. Para dados válidos o
-- comportamento é idêntico (a cópia local clampada continua sendo usada só como divisor
-- defensivo do real_subtotal; para markup em [0,50] equivale ao próprio valor).
CREATE OR REPLACE FUNCTION public.fn_quotes_calc_real_values()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_markup numeric;
BEGIN
  -- Cópia local clampada usada APENAS como divisor defensivo (não regrava a coluna).
  -- A faixa válida é garantida pelo CHECK valid_negotiation_markup_range ([0,50]):
  -- valores fora de faixa são rejeitados pelo constraint (fail-loud), não silenciados.
  v_markup := LEAST(50, GREATEST(0, COALESCE(NEW.negotiation_markup_percent, 0)));

  IF v_markup > 0 THEN
    NEW.real_subtotal := ROUND(NEW.subtotal / (1 + v_markup / 100.0), 2);
  ELSE
    NEW.real_subtotal := NEW.subtotal;
  END IF;

  IF NEW.real_subtotal > 0 THEN
    NEW.real_discount_percent := ROUND(
      ((NEW.real_subtotal - (NEW.subtotal - COALESCE(NEW.discount_amount, 0))) / NEW.real_subtotal) * 100,
      2
    );
  ELSE
    NEW.real_discount_percent := 0;
  END IF;

  RETURN NEW;
END
$function$;;

-- <<< END 20260618000747_quotes_calc_real_values_markup_fail_loud.sql <<<

-- >>> BEGIN 20260618001640_quotes_version_no_inflation.sql >>>
-- Melhoria #2: elimina a inflação de `version` em quotes.
-- Problema: increment_row_version (compartilhada com `orders`) incrementa version a CADA
-- UPDATE. Na criação, a cascata de recálculo dispara vários UPDATEs (um por item/personalização),
-- inflando version para ~3-4 num orçamento recém-criado.
-- Correção: função ESPECÍFICA de quotes que só incrementa quando muda alguma coluna NÃO-derivada.
-- Comparo OLD vs NEW via jsonb removendo as colunas automáticas/derivadas (escritas pelos
-- triggers de recálculo e de updated_at). Assim a cascata de recálculo (que só mexe em
-- subtotal/total/discount_amount/real_subtotal/real_discount_percent/updated_at) NÃO infla a versão,
-- mas qualquer edição real de campo do orçamento incrementa +1.
-- `orders` e increment_row_version permanecem INTOCADOS.
CREATE OR REPLACE FUNCTION public.increment_quote_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  _old jsonb := to_jsonb(OLD)
                 - 'subtotal' - 'total' - 'discount_amount'
                 - 'real_subtotal' - 'real_discount_percent'
                 - 'updated_at' - 'version';
  _new jsonb := to_jsonb(NEW)
                 - 'subtotal' - 'total' - 'discount_amount'
                 - 'real_subtotal' - 'real_discount_percent'
                 - 'updated_at' - 'version';
BEGIN
  IF _old IS DISTINCT FROM _new THEN
    NEW.version := COALESCE(OLD.version, 0) + 1;
  ELSE
    -- Update derivado-apenas (cascata de recálculo): preserva a versão atual.
    NEW.version := COALESCE(OLD.version, 1);
  END IF;
  RETURN NEW;
END
$function$;

DROP TRIGGER IF EXISTS trg_quotes_version ON public.quotes;
CREATE TRIGGER trg_quotes_version
  BEFORE UPDATE ON public.quotes
  FOR EACH ROW
  EXECUTE FUNCTION public.increment_quote_version();;

-- <<< END 20260618001640_quotes_version_no_inflation.sql <<<

-- >>> BEGIN 20260618001925_quotes_insert_bind_seller_id.sql >>>
-- Melhoria #3: hardening do INSERT de quotes.
-- Antes: with_check = user_is_org_member(organization_id) — qualquer membro da org podia
-- inserir um orçamento com seller_id de OUTRO vendedor (via API direta).
-- Agora: além de ser membro da org, o criador precisa ser coord+ OU estar gravando o
-- orçamento em seu próprio nome (seller_id/created_by = auth.uid()). Espelha exatamente o
-- padrão já usado (e testado em produção) nas policies de SELECT/UPDATE de quotes.
-- Coordenadores+ continuam podendo criar em nome de terceiros (sem regressão no fluxo real).
ALTER POLICY org_members_create_quotes ON public.quotes
  WITH CHECK (
    user_is_org_member(organization_id)
    AND (
      is_coord_or_above((SELECT auth.uid()))
      OR seller_id = (SELECT auth.uid())
      OR created_by = (SELECT auth.uid())
    )
  );;

-- <<< END 20260618001925_quotes_insert_bind_seller_id.sql <<<

-- >>> BEGIN 20260618002120_quotes_insert_bind_seller_id_strict.sql >>>
-- Melhoria #3 (refino): binding estrito de seller_id no INSERT.
-- Remove o ramo created_by=auth.uid() para não permitir criar com seller_id de terceiro
-- apenas marcando-se como criador. O app sempre grava seller_id=auth.uid(); coords+ seguem
-- podendo criar em nome de outro vendedor.
ALTER POLICY org_members_create_quotes ON public.quotes
  WITH CHECK (
    user_is_org_member(organization_id)
    AND (
      is_coord_or_above((SELECT auth.uid()))
      OR seller_id = (SELECT auth.uid())
    )
  );;

-- <<< END 20260618002120_quotes_insert_bind_seller_id_strict.sql <<<

-- >>> BEGIN 20260618100230_estoque_warehouse_qty_coherence_20260618.sql >>>

-- ============================================================================
-- FIX SISTÊMICO: coerência stock_main_warehouse(+other) <-> quantity (canônico)
-- Causa-raiz: Asia/SM atualizam apenas `quantity`; `stock_main_warehouse` ficava
-- congelado na ingestão. A camada de inteligência (snapshot, sumário diário,
-- market intelligence, MVs) lê main+other -> ficava cega/errada p/ Asia e SM.
-- Solução write-path-independent: trigger BEFORE que espelha quantity->main
-- quando o writer não tocou o split de armazém (Asia/SM/manual), sem interferir
-- em XBZ/Spot (que setam main explicitamente).
-- ============================================================================

-- 1) Guard de sessão no trigger de snapshot (permite supressão controlada em
--    correções em massa, sem DISABLE TRIGGER / sem lock ACCESS EXCLUSIVE).
CREATE OR REPLACE FUNCTION public.fn_capture_stock_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_product_id    uuid;
  v_stock_changed boolean;
  v_price_changed boolean;
  v_date_changed  boolean;
  v_change_type   varchar(20);
BEGIN
  -- Supressão controlada (correções em massa): SET LOCAL app.skip_stock_snapshot='true'
  IF current_setting('app.skip_stock_snapshot', true) = 'true' THEN
    RETURN NEW;
  END IF;

  v_stock_changed := (
    OLD.stock_main_warehouse  IS DISTINCT FROM NEW.stock_main_warehouse
    OR OLD.stock_other_warehouses IS DISTINCT FROM NEW.stock_other_warehouses
  );
  v_price_changed := (OLD.cost_price IS DISTINCT FROM NEW.cost_price);
  v_date_changed  := (OLD.next_date_1 IS DISTINCT FROM NEW.next_date_1);

  IF NOT v_stock_changed AND NOT v_price_changed AND NOT v_date_changed THEN
    RETURN NEW;
  END IF;

  IF v_stock_changed AND v_price_changed THEN
    v_change_type := 'both';
  ELSIF v_price_changed THEN
    v_change_type := 'price';
  ELSIF v_date_changed AND NOT v_stock_changed THEN
    v_change_type := 'restock_date';
  ELSE
    v_change_type := 'stock';
  END IF;

  SELECT pv.product_id INTO v_product_id
  FROM product_variants pv WHERE pv.id = NEW.variant_id;

  IF v_product_id IS NULL THEN RETURN NEW; END IF;

  INSERT INTO stock_snapshots (
    variant_supplier_source_id, supplier_id, supplier_branch_id,
    variant_id, product_id,
    stock_main_old, stock_main_new,
    stock_other_old, stock_other_new,
    cost_price_old, cost_price_new,
    change_type, captured_at, sync_source
  ) VALUES (
    NEW.id, NEW.supplier_id, NEW.supplier_branch_id,
    NEW.variant_id, v_product_id,
    CASE WHEN v_stock_changed THEN OLD.stock_main_warehouse  ELSE NULL END,
    CASE WHEN v_stock_changed THEN NEW.stock_main_warehouse  ELSE NULL END,
    CASE WHEN v_stock_changed THEN OLD.stock_other_warehouses ELSE NULL END,
    CASE WHEN v_stock_changed THEN NEW.stock_other_warehouses ELSE NULL END,
    CASE WHEN v_price_changed THEN OLD.cost_price ELSE NULL END,
    CASE WHEN v_price_changed THEN NEW.cost_price ELSE NULL END,
    v_change_type, now(), NEW.source
  );

  RETURN NEW;
END;
$function$;

-- 2) Trigger-espelho: mantém stock_main_warehouse(+other) coerente com `quantity`
CREATE OR REPLACE FUNCTION public.fn_vss_sync_warehouse_from_qty()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- split não informado (ambos 0) mas há quantity -> espelha
    IF COALESCE(NEW.stock_main_warehouse,0) = 0
       AND COALESCE(NEW.stock_other_warehouses,0) = 0
       AND COALESCE(NEW.quantity,0) <> 0 THEN
      NEW.stock_main_warehouse  := COALESCE(NEW.quantity,0);
      NEW.stock_other_warehouses := 0;
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    -- quantity mudou E o split NÃO foi tocado neste UPDATE (Asia/SM/manual)
    IF NEW.quantity IS DISTINCT FROM OLD.quantity
       AND NEW.stock_main_warehouse  IS NOT DISTINCT FROM OLD.stock_main_warehouse
       AND NEW.stock_other_warehouses IS NOT DISTINCT FROM OLD.stock_other_warehouses THEN
      NEW.stock_main_warehouse  := COALESCE(NEW.quantity,0);
      NEW.stock_other_warehouses := 0;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS trg_vss_sync_warehouse_from_qty ON public.variant_supplier_sources;
CREATE TRIGGER trg_vss_sync_warehouse_from_qty
  BEFORE INSERT OR UPDATE OF quantity ON public.variant_supplier_sources
  FOR EACH ROW EXECUTE FUNCTION public.fn_vss_sync_warehouse_from_qty();
;

-- <<< END 20260618100230_estoque_warehouse_qty_coherence_20260618.sql <<<

-- >>> BEGIN 20260618100311_add_idx_products_tags_gin_super_filtro.sql >>>
-- Super Filtro health gate: idx_tags_gin estava 🔴 (índice ausente).
-- products.tags é jsonb (array de atributos do produto). Índice GIN parcial
-- (somente ativos/não-deletados), mesmo padrão de idx_products_target_audience_gin
-- e idx_products_surface_finish_gin. Aditivo, sem impacto em leitura existente.
CREATE INDEX IF NOT EXISTS idx_products_tags_gin
  ON public.products USING gin (tags)
  WHERE (is_active = true AND is_deleted IS NOT TRUE);;

-- <<< END 20260618100311_add_idx_products_tags_gin_super_filtro.sql <<<

-- >>> BEGIN 20260618100701_estoque_inventory_health_active_filter_and_deactivate_zero_20260618.sql >>>

-- FIX 1: get_inventory_health contava variantes INATIVAS com estoque obsoleto
-- nos KPIs with_stock / low_stock. Adiciona filtro pv.is_active = true
-- (a parte total_value/total_units já filtrava). 
CREATE OR REPLACE FUNCTION public.get_inventory_health()
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total_products  INTEGER;
  v_with_stock      INTEGER;
  v_low_stock       INTEGER;
  v_no_stock        INTEGER;
  v_total_value     NUMERIC;
  v_total_units     BIGINT;
BEGIN
  SELECT COUNT(*) INTO v_total_products
  FROM products WHERE is_active = true AND deleted_at IS NULL;

  SELECT COUNT(DISTINCT p.id) INTO v_with_stock
  FROM products p
  JOIN product_variants pv ON pv.product_id = p.id
  WHERE p.is_active = true AND p.deleted_at IS NULL
    AND pv.is_active = true          -- FIX: ignora variantes inativas
    AND pv.stock_quantity > 0;

  SELECT COUNT(DISTINCT p.id) INTO v_low_stock
  FROM products p
  JOIN product_variants pv ON pv.product_id = p.id
  WHERE p.is_active = true AND p.deleted_at IS NULL
    AND pv.is_active = true          -- FIX: ignora variantes inativas
    AND pv.stock_quantity > 0 AND pv.stock_quantity < 10;

  v_no_stock := v_total_products - v_with_stock;

  SELECT
    COALESCE(SUM(vss.quantity::bigint * COALESCE(vss.cost_price, 0)), 0),
    COALESCE(SUM(vss.quantity::bigint), 0)
  INTO v_total_value, v_total_units
  FROM product_variants pv
  JOIN products p          ON p.id = pv.product_id
  JOIN variant_supplier_sources vss ON vss.variant_id = pv.id AND vss.is_active = true
  WHERE p.is_active = true AND p.deleted_at IS NULL AND pv.is_active = true;

  RETURN json_build_object(
    'summary', json_build_object(
      'total_products',    v_total_products,
      'with_stock',        v_with_stock,
      'with_stock_pct',    ROUND((v_with_stock::NUMERIC / NULLIF(v_total_products,0) * 100), 1),
      'low_stock',         v_low_stock,
      'no_stock',          v_no_stock,
      'no_stock_pct',      ROUND((v_no_stock::NUMERIC / NULLIF(v_total_products,0) * 100), 1)
    ),
    'inventory', json_build_object(
      'total_units',  v_total_units,
      'total_value',  ROUND(v_total_value, 2),
      'currency',     'BRL',
      'note',         'Valor calculado via VSS cost_price (custo líquido fornecedor)'
    ),
    'alerts', json_build_object(
      'critical_low_stock', v_low_stock,
      'out_of_stock',       v_no_stock
    ),
    'generated_at', NOW()
  );
END;
$function$;

-- FIX 2 (durável): ao DESATIVAR uma variante, zera seu cache stock_quantity
-- (variante inativa = 0 vendável). Fecha o leak D na origem, sem UPDATE extra.
CREATE OR REPLACE FUNCTION public.fn_zero_stock_on_variant_deactivate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.is_active = true AND NEW.is_active = false THEN
    NEW.stock_quantity := 0;
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS trg_zero_stock_on_variant_deactivate ON public.product_variants;
CREATE TRIGGER trg_zero_stock_on_variant_deactivate
  BEFORE UPDATE OF is_active ON public.product_variants
  FOR EACH ROW EXECUTE FUNCTION public.fn_zero_stock_on_variant_deactivate();
;

-- <<< END 20260618100701_estoque_inventory_health_active_filter_and_deactivate_zero_20260618.sql <<<

-- >>> BEGIN 20260618101311_estoque_reconcile_add_vss_F_coherence_20260618.sql >>>

-- Enriquecimento do reconciliador diário: NÍVEL 0 — coerência interna da VSS
-- (stock_main_warehouse + stock_other_warehouses == quantity canônico).
-- Auto-cura nightly de qualquer F-violation (ex.: main derivado com quantity
-- estável, que o trigger-espelho não cobre por só disparar em mudança de qty).
-- Snapshots suprimidos (correção != movimento real).
CREATE OR REPLACE FUNCTION public.fn_reconcile_stock_gold(p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_var int := 0; v_prod int := 0; v_vss int := 0;
  v_var_div int; v_prod_div int; v_vss_div int;
  v_t0 timestamptz := clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('fn_reconcile_stock_gold')::bigint) THEN
    RETURN jsonb_build_object('skipped','lock_ocupado');
  END IF;

  PERFORM set_config('app.bulk_import_mode','true', true);
  PERFORM set_config('app.write_source','reconcile', true);
  PERFORM set_config('app.skip_stock_snapshot','true', true);  -- correções não geram movimento

  -- diagnóstico (antes)
  SELECT count(*) INTO v_vss_div FROM variant_supplier_sources v
    WHERE v.is_active AND NOT COALESCE(v.removed_from_api,false)
      AND v.quantity IS DISTINCT FROM (COALESCE(v.stock_main_warehouse,0)+COALESCE(v.stock_other_warehouses,0));
  SELECT count(*) INTO v_var_div FROM (
    SELECT v.id FROM product_variants v
    LEFT JOIN variant_supplier_sources s ON s.variant_id=v.id AND s.is_active
    WHERE v.is_active
    GROUP BY v.id, v.stock_quantity
    HAVING COALESCE(v.stock_quantity,0) IS DISTINCT FROM COALESCE(sum(s.quantity),0)) z;
  SELECT count(*) INTO v_prod_div FROM (
    SELECT p.id FROM products p
    LEFT JOIN product_variants v ON v.product_id=p.id AND v.is_active
    WHERE p.is_active
    GROUP BY p.id, p.stock_quantity
    HAVING COALESCE(p.stock_quantity,0) IS DISTINCT FROM COALESCE(sum(v.stock_quantity),0)) z;

  IF p_dry_run THEN
    RETURN jsonb_build_object('dry_run', true,
      'vss_incoerentes', v_vss_div,
      'variantes_divergentes', v_var_div, 'products_divergentes', v_prod_div);
  END IF;

  -- nível 0: coerência interna VSS (main+other == quantity)
  WITH upd AS (
    UPDATE variant_supplier_sources v
       SET stock_main_warehouse = v.quantity,
           stock_other_warehouses = 0,
           updated_at = now()
    WHERE v.is_active AND NOT COALESCE(v.removed_from_api,false)
      AND v.quantity IS DISTINCT FROM (COALESCE(v.stock_main_warehouse,0)+COALESCE(v.stock_other_warehouses,0))
    RETURNING v.id)
  SELECT count(*) INTO v_vss FROM upd;

  -- nível 1: VSS → product_variants
  WITH agg AS (
    SELECT v.id, COALESCE(sum(s.quantity) FILTER (WHERE s.is_active),0) AS q
    FROM product_variants v
    LEFT JOIN variant_supplier_sources s ON s.variant_id=v.id
    WHERE v.is_active
    GROUP BY v.id),
  upd AS (
    UPDATE product_variants v SET stock_quantity = agg.q
    FROM agg WHERE v.id=agg.id AND COALESCE(v.stock_quantity,0) IS DISTINCT FROM agg.q
    RETURNING v.id)
  SELECT count(*) INTO v_var FROM upd;

  -- nível 2: product_variants → products (cache + is_stockout)
  WITH agg AS (
    SELECT p.id, COALESCE(sum(v.stock_quantity) FILTER (WHERE v.is_active),0) AS q
    FROM products p
    LEFT JOIN product_variants v ON v.product_id=p.id
    WHERE p.is_active
    GROUP BY p.id),
  upd AS (
    UPDATE products p
       SET stock_quantity = agg.q,
           is_stockout = (agg.q <= 0),
           last_stock_update_at = now()
    FROM agg WHERE p.id=agg.id
      AND (COALESCE(p.stock_quantity,0) IS DISTINCT FROM agg.q
           OR p.is_stockout IS DISTINCT FROM (agg.q <= 0))
    RETURNING p.id)
  SELECT count(*) INTO v_prod FROM upd;

  RETURN jsonb_build_object(
    'vss_incoerentes_antes', v_vss_div,
    'variantes_divergentes_antes', v_var_div,
    'products_divergentes_antes', v_prod_div,
    'vss_coerencia_corrigidas', v_vss,
    'variantes_corrigidas', v_var,
    'products_corrigidos', v_prod,
    'segundos', round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,1),
    'ts', now());
END $function$;
;

-- <<< END 20260618101311_estoque_reconcile_add_vss_F_coherence_20260618.sql <<<

-- >>> BEGIN 20260618101453_fix_validate_discount_valid_until_null.sql >>>

-- Bug fix: valid_until IS NULL was treated as expired (NULL > now() = NULL = false).
-- Semantics change: NULL valid_until means "no expiry" (backward compat for old approvals).
-- Forward path: respondToApproval in useDiscountApproval.ts now always sets valid_until = now() + 30 days.
CREATE OR REPLACE FUNCTION public.fn_quotes_validate_discount()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  _max_allowed numeric;
  _real_discount_pct numeric;
  _has_valid_approval boolean;
  _current_hash text;
  _seller_id uuid;
  _msg text;
BEGIN
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN NEW;
  END IF;

  _seller_id := COALESCE(NEW.seller_id, NEW.created_by);

  IF _seller_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF public.is_coord_or_above(_seller_id) THEN
    RETURN NEW;
  END IF;

  _real_discount_pct := COALESCE(NEW.real_discount_percent, 0);

  IF _real_discount_pct <= 0 THEN
    RETURN NEW;
  END IF;

  SELECT max_discount_percent INTO _max_allowed
  FROM public.seller_discount_limits
  WHERE user_id = _seller_id;

  IF _max_allowed IS NULL THEN
    RAISE EXCEPTION 'Vendedor sem limite de desconto cadastrado. Solicite ao admin que configure seu limite antes de salvar orcamentos.'
      USING ERRCODE = '23514';
  END IF;

  IF _real_discount_pct <= _max_allowed THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
            ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
            ' por cento. Salve o orcamento com desconto dentro do limite primeiro, depois solicite aprovacao ao coordenador.';
    RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
  END IF;

  _current_hash := public.compute_quote_snapshot_hash(NEW.id);

  -- NULL valid_until = sem vencimento (retrocompat). Aprovações com valid_until definido
  -- precisam estar dentro do prazo.
  SELECT EXISTS (
    SELECT 1 FROM public.discount_approval_requests
    WHERE quote_id = NEW.id
      AND status = 'approved'
      AND (valid_until IS NULL OR valid_until > now())
      AND requested_discount_percent >= _real_discount_pct
      AND quote_snapshot_hash = _current_hash
  ) INTO _has_valid_approval;

  IF _has_valid_approval THEN
    RETURN NEW;
  END IF;

  -- Aprovação existe mas expirou (valid_until definido e já passou) OU snapshot mudou.
  IF EXISTS (
    SELECT 1 FROM public.discount_approval_requests
    WHERE quote_id = NEW.id AND status = 'approved'
      AND (
        (valid_until IS NOT NULL AND valid_until <= now())
        OR quote_snapshot_hash <> _current_hash
      )
  ) THEN
    RAISE EXCEPTION 'Aprovacao anterior nao vale mais (orcamento foi alterado ou aprovacao expirou). Solicite nova aprovacao ao coordenador.'
      USING ERRCODE = '23514';
  END IF;

  _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
          ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
          ' por cento. Solicite aprovacao ao coordenador antes de salvar.';
  RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
END;
$$;
;

-- <<< END 20260618101453_fix_validate_discount_valid_until_null.sql <<<

-- >>> BEGIN 20260618102326_fix_validate_discount_valid_until_v2.sql >>>

-- Refinamento: o check constraint dar_valid_until_required_when_approved já garante
-- que status='approved' implica valid_until IS NOT NULL. Portanto a retrocompat
-- "NULL = sem vencimento" é desnecessária para novos registros.
-- Mantemos (valid_until IS NULL OR valid_until > now()) para registros legados
-- (criados antes do constraint existir) e como defesa em profundidade.
-- A lógica do trigger permanece correta como está após a migration anterior.
-- Esta migration documenta o constraint descoberto e não altera código.
COMMENT ON CONSTRAINT dar_valid_until_required_when_approved
  ON public.discount_approval_requests
  IS 'Garante que aprovações sempre têm vencimento explícito. '
     'O trigger fn_quotes_validate_discount verifica valid_until > now() '
     '(ou IS NULL como retrocompat para registros legados). '
     'O hook respondToApproval define valid_until = now() + 30 days ao aprovar.';
;

-- <<< END 20260618102326_fix_validate_discount_valid_until_v2.sql <<<

-- >>> BEGIN 20260618102416_quotes_add_cancelled_status.sql >>>
-- Melhoria #1: adiciona status 'cancelled' ao CHECK valid_quote_status e corrige soft_delete_quote.
--
-- Problema: soft_delete_quote fazia UPDATE quotes SET status='cancelled', mas 'cancelled' não
-- existia no CHECK valid_quote_status → função SEMPRE falhava para usuários autenticados com
-- check_violation (funciona só como service_role, que ignora a condição auth.uid() e faz no-op).
--
-- Solução: adicionar 'cancelled' ao enum de statuses válidos.
-- Semântica diferente de 'rejected' (rejeição pelo cliente) — 'cancelled' = cancelamento interno.
-- Nenhum dado existente é afetado (ADD CHECK é imediato: existentes estão em [0,50]).

ALTER TABLE public.quotes
  DROP CONSTRAINT IF EXISTS valid_quote_status;

ALTER TABLE public.quotes
  ADD CONSTRAINT valid_quote_status
    CHECK (status = ANY (ARRAY[
      'draft','pending','pending_approval','sent','viewed',
      'approved','converted','rejected','expired','cancelled'
    ]));

-- Corrigir soft_delete_quote para usar a mesma proteção de imutabilidade já existente.
-- Adicionamos também proteção contra cancelamento de quotes já convertidos/aprovados
-- (status terminal de negócio). Coord+ pode cancelar qualquer status não-terminal.
CREATE OR REPLACE FUNCTION public.soft_delete_quote(_quote_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY INVOKER
 SET search_path TO 'public'
AS $function$
DECLARE
  _current_status text;
BEGIN
  -- Lê o status atual respeitando RLS (só acessa quotes visíveis ao caller)
  SELECT status INTO _current_status FROM public.quotes WHERE id = _quote_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Orçamento não encontrado ou sem permissão de acesso'
      USING ERRCODE = 'no_data_found';
  END IF;

  -- Proteção: não cancelar estados terminais de negócio
  IF _current_status IN ('converted', 'cancelled') THEN
    RAISE EXCEPTION 'Não é possível cancelar um orçamento com status "%". Apenas orçamentos ativos podem ser cancelados.',
      _current_status
      USING ERRCODE = '23514';
  END IF;

  -- Permite cancelar se o caller é dono ou coordenador+
  UPDATE public.quotes
  SET    status     = 'cancelled',
         updated_at = now()
  WHERE  id         = _quote_id
    AND  (seller_id = auth.uid()
          OR created_by  = auth.uid()
          OR public.is_coord_or_above(auth.uid()));

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sem permissão para cancelar este orçamento'
      USING ERRCODE = '42501';
  END IF;
END;
$function$;;

-- <<< END 20260618102416_quotes_add_cancelled_status.sql <<<

-- >>> BEGIN 20260618102515_create_quote_transactional_add_history.sql >>>
-- Melhoria #2: audit trail em create_quote_transactional.
-- Problema: a criação do orçamento via RPC principal não registrava nada em quote_history,
-- tornando o audit trail dependente apenas do legado fn_create_quote_v3.
-- Solução: INSERT em quote_history após a criação, usando auth.uid() ou seller_id como fallback
-- (service_role tem auth.uid()=NULL; usamos seller_id do payload como fallback).
CREATE OR REPLACE FUNCTION public.create_quote_transactional(_quote jsonb, _items jsonb)
 RETURNS quotes
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  _new_quote    public.quotes;
  _new_quote_id uuid;
  _item         jsonb;
  _pers         jsonb;
  _new_item_id  uuid;
  _actor_id     uuid;
begin
  -- ── 1. Cria o orçamento (quote_number é preenchido pelo trigger generate_quote_number) ──
  insert into public.quotes (
    quote_number, client_id, client_name, client_email, client_phone, client_company,
    seller_id, organization_id, status,
    subtotal, discount_percent, discount_amount, total, negotiation_markup_percent,
    payment_method, payment_terms, delivery_time, shipping_type, shipping_cost,
    notes, internal_notes, valid_until
  )
  values (
    coalesce(_quote->>'quote_number', ''),
    nullif(_quote->>'client_id', '')::uuid,
    coalesce(_quote->>'client_name', ''),
    _quote->>'client_email',
    _quote->>'client_phone',
    _quote->>'client_company',
    nullif(_quote->>'seller_id', '')::uuid,
    nullif(_quote->>'organization_id', '')::uuid,
    coalesce(_quote->>'status', 'draft'),
    coalesce((_quote->>'subtotal')::numeric, 0),
    coalesce((_quote->>'discount_percent')::numeric, 0),
    coalesce((_quote->>'discount_amount')::numeric, 0),
    coalesce((_quote->>'total')::numeric, 0),
    coalesce((_quote->>'negotiation_markup_percent')::numeric, 0),
    _quote->>'payment_method',
    _quote->>'payment_terms',
    _quote->>'delivery_time',
    _quote->>'shipping_type',
    coalesce((_quote->>'shipping_cost')::numeric, 0),
    _quote->>'notes',
    _quote->>'internal_notes',
    nullif(_quote->>'valid_until', '')::date
  )
  returning * into _new_quote;

  _new_quote_id := _new_quote.id;

  -- ── 2. Insere itens ───────────────────────────────────────────────────────
  for _item in select value from jsonb_array_elements(coalesce(_items, '[]'::jsonb)) loop
    insert into public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days, bitrix_product_id
    )
    values (
      _new_quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', '')
    )
    returning id into _new_item_id;

    -- ── 3. Insere personalizações do item ────────────────────────────────────
    for _pers in select value from jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb)) loop
      insert into public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      values (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    end loop;
  end loop;

  -- ── 4. Relê a linha final (quote_number gerado + totais recalculados pelos triggers) ──
  select * into _new_quote from public.quotes where id = _new_quote_id;

  -- ── 5. Audit trail ───────────────────────────────────────────────────────
  -- auth.uid() é NULL em contexto service_role; usa seller_id do payload como fallback.
  _actor_id := coalesce(auth.uid(), nullif(_quote->>'seller_id','')::uuid);
  if _actor_id is not null then
    insert into public.quote_history (quote_id, user_id, action, description, metadata)
    values (
      _new_quote_id,
      _actor_id,
      'created',
      format('Orçamento %s criado com %s item(s) via RPC',
             _new_quote.quote_number,
             (select count(*) from public.quote_items where quote_id = _new_quote_id)),
      jsonb_build_object(
        'status',    _new_quote.status,
        'subtotal',  _new_quote.subtotal,
        'total',     _new_quote.total,
        'markup',    _new_quote.negotiation_markup_percent,
        'n_items',   (select count(*) from public.quote_items where quote_id = _new_quote_id)
      )
    );
  end if;

  return _new_quote;
end;
$function$;;

-- <<< END 20260618102515_create_quote_transactional_add_history.sql <<<

-- >>> BEGIN 20260618102605_update_quote_transactional_add_history.sql >>>
-- Melhoria #3: audit trail em update_quote_transactional.
-- Problema: nenhum registro de edição era salvo em quote_history — impossível rastrear
-- quem editou o quê e quando. Campos de status, desconto e markup são especialmente críticos.
-- Solução: INSERT em quote_history ao final, com ação diferenciada por tipo de mudança:
--   - 'status_changed' quando o status muda
--   - 'updated' nos demais casos
-- Inclui snapshot de campos-chave no metadata para diff futuro.
CREATE OR REPLACE FUNCTION public.update_quote_transactional(
  _quote_id    uuid,
  _quote_patch jsonb,
  _items       jsonb
)
 RETURNS quotes
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  _updated_quote  public.quotes;
  _prev_status    text;
  _prev_total     numeric;
  _item           jsonb;
  _pers           jsonb;
  _new_item_id    uuid;
  _actor_id       uuid;
  _action         text;
  _desc           text;
begin
  -- ── 0. Captura estado anterior para o diff do audit trail ─────────────────
  select status, total into _prev_status, _prev_total
  from public.quotes where id = _quote_id;

  -- ── 1. Atualiza o orçamento ────────────────────────────────────────────────
  update public.quotes
  set
    client_id                = coalesce(nullif(_quote_patch->>'client_id', ''), client_id::text)::uuid,
    client_name              = coalesce(nullif(_quote_patch->>'client_name', ''), client_name),
    client_email             = coalesce(_quote_patch->>'client_email',     client_email),
    client_phone             = coalesce(_quote_patch->>'client_phone',     client_phone),
    client_company           = coalesce(_quote_patch->>'client_company',   client_company),
    status                   = coalesce(_quote_patch->>'status',           status),
    shipping_type            = coalesce(_quote_patch->>'shipping_type',    shipping_type),
    shipping_cost            = coalesce((_quote_patch->>'shipping_cost')::numeric,            shipping_cost),
    payment_method           = coalesce(_quote_patch->>'payment_method',   payment_method),
    payment_terms            = coalesce(_quote_patch->>'payment_terms',    payment_terms),
    delivery_time            = coalesce(_quote_patch->>'delivery_time',    delivery_time),
    notes                    = coalesce(_quote_patch->>'notes',            notes),
    internal_notes           = coalesce(_quote_patch->>'internal_notes',   internal_notes),
    discount_percent         = coalesce((_quote_patch->>'discount_percent')::numeric,         discount_percent),
    discount_amount          = coalesce((_quote_patch->>'discount_amount')::numeric,          discount_amount),
    subtotal                 = coalesce((_quote_patch->>'subtotal')::numeric,                 subtotal),
    total                    = coalesce((_quote_patch->>'total')::numeric,                    total),
    negotiation_markup_percent = coalesce((_quote_patch->>'negotiation_markup_percent')::numeric, negotiation_markup_percent),
    valid_until              = coalesce((_quote_patch->>'valid_until')::date,                 valid_until),
    updated_at               = now()
  where id = _quote_id
  returning * into _updated_quote;

  if _updated_quote is null then
    raise exception 'Orçamento não encontrado: %', _quote_id
      using errcode = 'no_data_found';
  end if;

  -- ── 2. Remove itens/personalizações existentes ────────────────────────────
  delete from public.quote_item_personalizations
  where quote_item_id in (
    select id from public.quote_items where quote_id = _quote_id
  );
  delete from public.quote_items where quote_id = _quote_id;

  -- ── 3. Reinsere itens ─────────────────────────────────────────────────────
  for _item in select value from jsonb_array_elements(coalesce(_items, '[]'::jsonb)) loop
    insert into public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days, bitrix_product_id
    )
    values (
      _quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', '')
    )
    returning id into _new_item_id;

    -- ── 4. Reinsere personalizações ─────────────────────────────────────────
    for _pers in select value from jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb)) loop
      insert into public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      values (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    end loop;
  end loop;

  -- ── 5. Audit trail ───────────────────────────────────────────────────────
  _actor_id := coalesce(auth.uid(), _updated_quote.seller_id);
  if _actor_id is not null then
    -- Ação diferenciada: status_changed é evento mais crítico de rastrear
    if _prev_status is distinct from _updated_quote.status then
      _action := 'status_changed';
      _desc   := format('Status alterado de "%s" para "%s" no %s',
                        _prev_status, _updated_quote.status, _updated_quote.quote_number);
    else
      _action := 'updated';
      _desc   := format('Orçamento %s editado (total: R$ %s)',
                        _updated_quote.quote_number,
                        _updated_quote.total);
    end if;

    insert into public.quote_history (quote_id, user_id, action, description, metadata)
    values (
      _quote_id,
      _actor_id,
      _action,
      _desc,
      jsonb_build_object(
        'prev_status', _prev_status,
        'new_status',  _updated_quote.status,
        'prev_total',  _prev_total,
        'new_total',   _updated_quote.total,
        'markup',      _updated_quote.negotiation_markup_percent,
        'n_items',     (select count(*) from public.quote_items where quote_id = _quote_id)
      )
    );
  end if;

  return _updated_quote;
end;
$function$;;

-- <<< END 20260618102605_update_quote_transactional_add_history.sql <<<

-- >>> BEGIN 20260618102650_convert_quote_to_order_auth_and_history.sql >>>
-- Melhoria #4: convert_quote_to_order com check explícito de autorização + audit trail.
--
-- Problemas:
-- (a) A função dependia EXCLUSIVAMENTE do RLS implícito (SELECT falha se caller não vê o quote)
--     para barrar acesso não autorizado. Falta check explícito: o caller deve ser o dono do
--     orçamento ou coord+; o p_seller_id passado deve ser auth.uid() ou um usuario permitido.
-- (b) Nenhum registro era criado em quote_history ao converter — ação crítica sem trilha.
--
-- Solução:
-- (a) Verifica: se não é service_role, exige que auth.uid() = p_seller_id OU coord+.
--     Nota: RLS já bloqueia SELECT do quote se caller não tiver acesso; o check explícito
--     adiciona defesa em profundidade para garantir que p_seller_id não seja "forjado".
-- (b) Insere em quote_history com action='converted' e referência ao pedido gerado.
CREATE OR REPLACE FUNCTION public.convert_quote_to_order(
  p_quote_id       uuid,
  p_seller_id      uuid,
  p_organization_id uuid DEFAULT NULL::uuid
)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_quote       RECORD;
  v_order_id    UUID;
  v_order_number TEXT;
  v_item        RECORD;
  v_new_item_id UUID;
  v_actor_id    UUID;
BEGIN
  -- ── 0. Auth check explícito (além do RLS implícito via SELECT abaixo) ────
  -- Em contexto service_role (automações internas) a checagem é dispensada.
  IF current_setting('request.jwt.claim.role', true) <> 'service_role' AND auth.uid() IS NOT NULL THEN
    IF auth.uid() <> p_seller_id AND NOT public.is_coord_or_above(auth.uid()) THEN
      RAISE EXCEPTION
        'Sem permissão: apenas o vendedor responsável ou um coordenador pode converter este orçamento'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- ── 1. Carrega o orçamento (RLS aplicado — SECURITY INVOKER) ─────────────
  SELECT * INTO v_quote FROM public.quotes WHERE id = p_quote_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Orçamento não encontrado'; END IF;
  IF v_quote.status != 'approved' THEN
    RAISE EXCEPTION 'Apenas orçamentos aprovados podem ser convertidos';
  END IF;
  IF EXISTS (SELECT 1 FROM public.orders WHERE quote_id = p_quote_id) THEN
    RAISE EXCEPTION 'Este orçamento já foi convertido em pedido';
  END IF;

  -- ── 2. Cria o pedido ──────────────────────────────────────────────────────
  INSERT INTO public.orders (
    seller_id, organization_id, quote_id, client_id, client_name, client_email,
    client_phone, client_company, subtotal, discount_amount, shipping_cost,
    shipping_type, total, payment_terms, delivery_time, notes, internal_notes,
    status, fulfillment_status
  ) VALUES (
    p_seller_id,
    COALESCE(p_organization_id, v_quote.organization_id),
    p_quote_id,
    v_quote.client_id, v_quote.client_name, v_quote.client_email,
    v_quote.client_phone, v_quote.client_company,
    v_quote.subtotal, v_quote.discount_amount, v_quote.shipping_cost,
    v_quote.shipping_type, v_quote.total, v_quote.payment_terms,
    v_quote.delivery_time, v_quote.notes, v_quote.internal_notes,
    'confirmed', 'pending'
  ) RETURNING id, order_number INTO v_order_id, v_order_number;

  -- ── 3. Copia itens ────────────────────────────────────────────────────────
  FOR v_item IN SELECT * FROM public.quote_items WHERE quote_id = p_quote_id LOOP
    INSERT INTO public.order_items (
      order_id, quote_item_id, product_id, product_sku, product_name,
      product_image_url, quantity, unit_price, subtotal,
      discount_amount, personalization_cost
    ) VALUES (
      v_order_id, v_item.id, v_item.product_id, v_item.product_sku, v_item.product_name,
      v_item.product_image_url, v_item.quantity, v_item.unit_price, v_item.subtotal,
      COALESCE(v_item.discount_amount, 0), COALESCE(v_item.personalization_cost, 0)
    ) RETURNING id INTO v_new_item_id;
  END LOOP;

  -- ── 4. Atualiza status do orçamento ───────────────────────────────────────
  UPDATE public.quotes
  SET    status = 'converted',
         converted_to_order_id = v_order_id,
         converted_at = now()
  WHERE  id = p_quote_id;

  -- ── 5. Audit trail ────────────────────────────────────────────────────────
  v_actor_id := COALESCE(auth.uid(), p_seller_id);
  IF v_actor_id IS NOT NULL THEN
    INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
    VALUES (
      p_quote_id,
      v_actor_id,
      'converted',
      format('Orçamento %s convertido em pedido %s',
             v_quote.quote_number, v_order_number),
      jsonb_build_object(
        'order_id',     v_order_id,
        'order_number', v_order_number,
        'total',        v_quote.total,
        'n_items',      (SELECT count(*) FROM public.order_items WHERE order_id = v_order_id)
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'id',           v_order_id,
    'order_number', v_order_number,
    'status',       'confirmed',
    'total',        v_quote.total
  );
END;
$function$;;

-- <<< END 20260618102650_convert_quote_to_order_auth_and_history.sql <<<

-- >>> BEGIN 20260618102923_create_fn_super_filtro_product_ids.sql >>>
-- Super Filtro: resolver server-side de IDs para filtros de metadados
-- (Datas Comemorativas, Tags, Ramos/Segmentos de Atividade, Público-Alvo).
-- Retorna product_ids ATIVOS que satisfazem TODOS os grupos de filtro ativos
-- (AND entre grupos), com OR dentro de cada grupo. cardinality()=0 => grupo
-- inativo (sem restrição). Espelha o padrão de useProductsByColor/Category:
-- o frontend intersecta o Set client-side com a grade já carregada.
CREATE OR REPLACE FUNCTION public.fn_super_filtro_product_ids(
  _datas text[] DEFAULT '{}',
  _tags text[] DEFAULT '{}',
  _ramos text[] DEFAULT '{}',
  _segmentos text[] DEFAULT '{}',
  _publico text[] DEFAULT '{}'
) RETURNS TABLE(product_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $func$
  SELECT b.id
  FROM products b
  WHERE b.is_active = true AND b.is_deleted IS NOT TRUE
    AND ( cardinality(_datas)=0 OR EXISTS (
        SELECT 1 FROM product_commemorative_dates pcd
        JOIN commemorative_dates cd ON cd.id = pcd.commemorative_date_id AND cd.is_active
        WHERE pcd.product_id = b.id AND pcd.is_active AND cd.slug = ANY(_datas) ) )
    AND ( cardinality(_tags)=0 OR EXISTS (
        SELECT 1 FROM product_tags pt
        JOIN tags t ON t.id = pt.tag_id AND t.is_active
        WHERE pt.product_id = b.id AND pt.tag_id = ANY(_tags::uuid[]) ) )
    AND ( cardinality(_ramos)=0 OR EXISTS (
        SELECT 1 FROM produto_ramo_atividade pra
        JOIN ramo_atividade_filho raf ON raf.id = pra.ramo_atividade_filho_id
        JOIN ramo_atividade ra ON ra.id = raf.ramo_atividade_id
        WHERE pra.produto_id = b.id AND ra.slug = ANY(_ramos) ) )
    AND ( cardinality(_segmentos)=0 OR EXISTS (
        SELECT 1 FROM produto_ramo_atividade pra
        JOIN ramo_atividade_filho raf ON raf.id = pra.ramo_atividade_filho_id
        WHERE pra.produto_id = b.id AND raf.slug = ANY(_segmentos) ) )
    AND ( cardinality(_publico)=0 OR b.target_audience && _publico );
$func$;

COMMENT ON FUNCTION public.fn_super_filtro_product_ids(text[],text[],text[],text[],text[])
  IS 'Super Filtro: product_ids ativos por metadados (datas/tags/ramos/segmentos/publico). AND entre grupos, OR dentro. Consumido por useProductsByMetadata.';

GRANT EXECUTE ON FUNCTION public.fn_super_filtro_product_ids(text[],text[],text[],text[],text[])
  TO anon, authenticated, service_role;

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260618102923_create_fn_super_filtro_product_ids.sql <<<

-- >>> BEGIN 20260618103302_create_rpc_get_catalog_bestseller_ids.sql >>>

-- Ranking server-side de "+ Vendidos" sobre TODOS os ativos (corrige janela parcial client-side).
-- best-seller-supplier: turnover_score (mv_product_intelligence)
-- best-seller-promo:    soma de quantity em quote_items
-- Tie-break name ASC, id ASC ESPELHA byNameThenId() do front (consistência cliente/servidor).
CREATE OR REPLACE FUNCTION public.get_catalog_bestseller_ids(
  p_sort text DEFAULT 'best-seller-supplier',
  p_limit int DEFAULT 500,
  p_offset int DEFAULT 0
)
RETURNS TABLE(product_id uuid)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public
AS $fn$
  SELECT p.id
  FROM products p
  LEFT JOIN mv_product_intelligence mi ON mi.product_id = p.id
  LEFT JOIN (
    SELECT qi.product_id AS pid, sum(COALESCE(qi.quantity,1)) AS promo_qty
    FROM quote_items qi WHERE qi.product_id IS NOT NULL GROUP BY qi.product_id
  ) qs ON qs.pid = p.id
  WHERE p.active = true
  ORDER BY
    CASE WHEN p_sort = 'best-seller-promo'    THEN COALESCE(qs.promo_qty, 0) END DESC NULLS LAST,
    CASE WHEN p_sort = 'best-seller-supplier' THEN COALESCE(mi.turnover_score, 0) END DESC NULLS LAST,
    p.name ASC, p.id ASC
  LIMIT GREATEST(p_limit, 0) OFFSET GREATEST(p_offset, 0);
$fn$;

COMMENT ON FUNCTION public.get_catalog_bestseller_ids(text,int,int) IS
  'Auditoria catálogo 2026-06-18: ordem server-side para sorts best-seller-* (turnover/promo) sobre todos os ativos, com paginação. Consumida por fetchCatalogPage com fallback gracioso.';

GRANT EXECUTE ON FUNCTION public.get_catalog_bestseller_ids(text,int,int) TO anon, authenticated;
;

-- <<< END 20260618103302_create_rpc_get_catalog_bestseller_ids.sql <<<

-- >>> BEGIN 20260618103619_replace_bestseller_rpc_with_setof_page.sql >>>

-- Substitui get_catalog_bestseller_ids (retornava ids -> .in() gerava URL gigante no front)
-- por get_catalog_bestseller_page que retorna as próprias linhas da view (1 chamada, sem .in()).
DROP FUNCTION IF EXISTS public.get_catalog_bestseller_ids(text,int,int);

CREATE OR REPLACE FUNCTION public.get_catalog_bestseller_page(
  p_sort text DEFAULT 'best-seller-supplier',
  p_limit int DEFAULT 500,
  p_offset int DEFAULT 0
)
RETURNS SETOF public.v_products_public
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public
AS $fn$
  SELECT v.*
  FROM public.v_products_public v
  LEFT JOIN mv_product_intelligence mi ON mi.product_id = v.id
  LEFT JOIN (
    SELECT qi.product_id AS pid, sum(COALESCE(qi.quantity,1)) AS promo_qty
    FROM quote_items qi WHERE qi.product_id IS NOT NULL GROUP BY qi.product_id
  ) qs ON qs.pid = v.id
  WHERE v.active = true
  ORDER BY
    CASE WHEN p_sort = 'best-seller-promo'    THEN COALESCE(qs.promo_qty, 0) END DESC NULLS LAST,
    CASE WHEN p_sort = 'best-seller-supplier' THEN COALESCE(mi.turnover_score, 0) END DESC NULLS LAST,
    v.name ASC, v.id ASC
  LIMIT GREATEST(p_limit,0) OFFSET GREATEST(p_offset,0);
$fn$;

COMMENT ON FUNCTION public.get_catalog_bestseller_page(text,int,int) IS
  'Auditoria catálogo 2026-06-18: página ordenada server-side para sorts best-seller-* (turnover/promo) sobre TODOS os ativos. Retorna linhas de v_products_public. Tie-break name,id espelha byNameThenId() do front. Consumida por fetchCatalogPage com fallback gracioso.';

GRANT EXECUTE ON FUNCTION public.get_catalog_bestseller_page(text,int,int) TO anon, authenticated;
;

-- <<< END 20260618103619_replace_bestseller_rpc_with_setof_page.sql <<<

-- >>> BEGIN 20260618103654_quote_history_rls_add_seller_id.sql >>>
-- Melhoria #1: quote_history RLS — adicionar seller_id às policies SELECT e INSERT.
--
-- Problema: as policies verificavam apenas created_by e assigned_to, ignorando seller_id.
-- Cenário quebrado: coord cria quote com seller_id=sellerA e created_by=coordId.
-- SellerA pode SELECT/UPDATE o quote (via quotes_select_scope/quotes_update_scope),
-- mas NÃO consegue ler nem inserir no seu próprio quote_history. Isso faz com que
-- nosso novo audit trail (create/update_quote_transactional) silenciosamente falhe
-- ao tentar INSERT quando chamado como authenticated sellerA.
--
-- Solução: adicionar q.seller_id = auth.uid() às condições de EXISTS em ambas as policies.

-- SELECT policy
DROP POLICY IF EXISTS "Sellers and coord view quote_history" ON public.quote_history;
CREATE POLICY "Sellers and coord view quote_history"
  ON public.quote_history
  FOR SELECT
  USING (
    is_coord_or_above(auth.uid())
    OR EXISTS (
      SELECT 1 FROM public.quotes q
      WHERE q.id = quote_history.quote_id
        AND (
          q.seller_id   = auth.uid()
          OR q.created_by  = auth.uid()
          OR q.assigned_to = auth.uid()
        )
    )
  );

-- INSERT policy
DROP POLICY IF EXISTS "Sellers and coord create quote_history" ON public.quote_history;
CREATE POLICY "Sellers and coord create quote_history"
  ON public.quote_history
  FOR INSERT
  WITH CHECK (
    user_id = auth.uid()
    AND (
      is_coord_or_above(auth.uid())
      OR EXISTS (
        SELECT 1 FROM public.quotes q
        WHERE q.id = quote_history.quote_id
          AND (
            q.seller_id   = auth.uid()
            OR q.created_by  = auth.uid()
            OR q.assigned_to = auth.uid()
          )
      )
    )
  );;

-- <<< END 20260618103654_quote_history_rls_add_seller_id.sql <<<

-- >>> BEGIN 20260618103742_drop_orphaned_validate_quote_real_discount.sql >>>
-- Melhoria #2: remover função órfã validate_quote_real_discount.
--
-- Problema: a função exists mas nenhum trigger a referencia (trigger_refs=0).
-- Ela duplica a lógica de fn_quotes_calc_real_values (cálculo de real_subtotal) e
-- fn_quotes_validate_discount (validação de limites). Seu nome genérico cria confusão
-- com a função ativa fn_quotes_validate_discount, dificultando manutenção.
--
-- Verificação prévia: nenhum trigger ou outra função a chama.
-- É seguro dropar.
DROP FUNCTION IF EXISTS public.validate_quote_real_discount();;

-- <<< END 20260618103742_drop_orphaned_validate_quote_real_discount.sql <<<

-- >>> BEGIN 20260618103812_fn_create_quote_v3_redirect_to_transactional.sql >>>
-- Melhoria #3: fn_create_quote_v3 vira thin-wrapper sobre create_quote_transactional.
--
-- Problema: a função legada ainda era chamável como RPC, gravava action='created_v3' no history
-- (inconsistente com 'created' da nova RPC), não aplicava as validações da nova stack e
-- usava padrões antigos (markup sem clamp, valid_until como TIMESTAMPTZ vs date).
--
-- Solução: redirecionar para create_quote_transactional internamente, preservando a assinatura
-- original para retrocompatibilidade de callers existentes (retorna o mesmo jsonb {id, quote_number}).
-- client_cnpj é descartado na conversão (campo não existe no novo schema de criação).
-- A nova função escreve action='created' com metadata completo (não mais 'created_v3').
CREATE OR REPLACE FUNCTION public.fn_create_quote_v3(p_quote_data jsonb, p_items_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  _result public.quotes;
  _quote_payload  jsonb;
  _items_payload  jsonb;
  _item           jsonb;
  _item_converted jsonb;
BEGIN
  -- Verifica autenticação (mantém comportamento original)
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  -- Converte o payload do formato v3 para o formato esperado por create_quote_transactional
  -- seller_id é sempre auth.uid() (mesma semântica da v3 original)
  _quote_payload := jsonb_build_object(
    'quote_number',               '',
    'client_id',                  p_quote_data->>'client_id',
    'client_name',                COALESCE(p_quote_data->>'client_name', ''),
    'client_email',               p_quote_data->>'client_email',
    'client_phone',               p_quote_data->>'client_phone',
    'client_company',             p_quote_data->>'client_company',
    'seller_id',                  auth.uid()::text,
    'organization_id',            p_quote_data->>'organization_id',
    'status',                     COALESCE(p_quote_data->>'status', 'draft'),
    'subtotal',                   COALESCE(p_quote_data->>'subtotal', '0'),
    'discount_percent',           COALESCE(p_quote_data->>'discount_percent', '0'),
    'discount_amount',            COALESCE(p_quote_data->>'discount_amount', '0'),
    'total',                      COALESCE(p_quote_data->>'total', '0'),
    'negotiation_markup_percent', COALESCE(p_quote_data->>'negotiation_markup_percent', '0'),
    'notes',                      p_quote_data->>'notes',
    'internal_notes',             p_quote_data->>'internal_notes',
    'valid_until',                p_quote_data->>'valid_until',
    'payment_terms',              p_quote_data->>'payment_terms',
    'delivery_time',              p_quote_data->>'delivery_time',
    'shipping_type',              p_quote_data->>'shipping_type',
    'shipping_cost',              COALESCE(p_quote_data->>'shipping_cost', '0')
  );

  -- Garante que os itens tenham 'personalizations' (v3 não exigia o campo)
  SELECT jsonb_agg(
    item || CASE WHEN item ? 'personalizations' THEN '{}'::jsonb
                 ELSE jsonb_build_object('personalizations','[]'::jsonb)
            END)
  INTO _items_payload
  FROM jsonb_array_elements(COALESCE(p_items_data,'[]'::jsonb)) AS item;

  _items_payload := COALESCE(_items_payload, '[]'::jsonb);

  -- Delega para a RPC canônica (inclui audit trail, validações, atomic)
  _result := public.create_quote_transactional(_quote_payload, _items_payload);

  -- Retorna no mesmo formato da v3 original para retrocompatibilidade
  RETURN jsonb_build_object('id', _result.id, 'quote_number', _result.quote_number);
END;
$function$;;

-- <<< END 20260618103812_fn_create_quote_v3_redirect_to_transactional.sql <<<

-- >>> BEGIN 20260618103837_quotes_add_created_at_created_by_indexes.sql >>>
-- Melhoria #4: índices de performance em quotes.created_at e quotes.created_by.
--
-- Padrão de query mais comum da UI: list de orçamentos ordenados por data decrescente.
-- O índice composto existente (seller_id, organization_id, status) não cobre ORDER BY created_at,
-- causando sort em memória para listas grandes. Corretores de orçamentos alheios (coord+) e
-- buscas por criador também carecem de índice.
--
-- idx_quotes_created_at: para listagens por data (ORDER BY created_at DESC)
-- idx_quotes_created_by: para queries de coord que filtram por quem criou o orçamento

CREATE INDEX IF NOT EXISTS idx_quotes_created_at
  ON public.quotes (created_at DESC);

CREATE INDEX IF NOT EXISTS idx_quotes_created_by
  ON public.quotes (created_by)
  WHERE created_by IS NOT NULL;

-- Complementar: índice em converted_at para relatórios de conversão
CREATE INDEX IF NOT EXISTS idx_quotes_converted_at
  ON public.quotes (converted_at DESC)
  WHERE converted_at IS NOT NULL;;

-- <<< END 20260618103837_quotes_add_created_at_created_by_indexes.sql <<<

-- >>> BEGIN 20260618103923_update_quote_transactional_optimistic_lock.sql >>>
-- Melhoria #5: optimistic locking opcional em update_quote_transactional.
--
-- Problema: sem verificação de versão, dois callers que leram o mesmo quote em paralelo
-- e chamam update_quote_transactional com patches diferentes vão causar lost-update silencioso
-- (a última chamada vence, sobrescrevendo as mudanças da primeira sem qualquer erro).
--
-- Solução: parâmetro _expected_version optional (default NULL = comportamento atual sem lock).
-- Quando fornecido, a função verifica se a versão atual ainda é a esperada ANTES de fazer o UPDATE.
-- Qualquer divergência lança exceção SERIALIZATION_FAILURE (código 40001), que o frontend
-- pode tratar pedindo ao usuário para recarregar e resubmeter.
--
-- Retrocompatibilidade: callers que não passam _expected_version continuam funcionando.
CREATE OR REPLACE FUNCTION public.update_quote_transactional(
  _quote_id         uuid,
  _quote_patch      jsonb,
  _items            jsonb,
  _expected_version integer DEFAULT NULL   -- NULL = sem lock; >0 = verifica versão antes de gravar
)
 RETURNS quotes
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  _updated_quote  public.quotes;
  _current_version integer;
  _prev_status    text;
  _prev_total     numeric;
  _item           jsonb;
  _pers           jsonb;
  _new_item_id    uuid;
  _actor_id       uuid;
  _action         text;
  _desc           text;
begin
  -- ── 0. Captura estado anterior (para diff do audit trail e validação de versão) ──
  select version, status, total
  into _current_version, _prev_status, _prev_total
  from public.quotes where id = _quote_id;

  -- ── Optimistic locking: só aplica quando _expected_version é fornecido ──────────
  if _expected_version is not null then
    if _current_version is null then
      raise exception 'Orçamento não encontrado: %', _quote_id
        using errcode = 'no_data_found';
    end if;
    if _current_version <> _expected_version then
      raise exception
        'Conflito de versão: orçamento foi modificado por outro usuário (versão atual: %, versão esperada: %). Recarregue e tente novamente.',
        _current_version, _expected_version
        using errcode = '40001';  -- SQLSTATE serialization_failure — retryable
    end if;
  end if;

  -- ── 1. Atualiza o orçamento ────────────────────────────────────────────────
  update public.quotes
  set
    client_id                  = coalesce(nullif(_quote_patch->>'client_id', ''), client_id::text)::uuid,
    client_name                = coalesce(nullif(_quote_patch->>'client_name', ''), client_name),
    client_email               = coalesce(_quote_patch->>'client_email',     client_email),
    client_phone               = coalesce(_quote_patch->>'client_phone',     client_phone),
    client_company             = coalesce(_quote_patch->>'client_company',   client_company),
    status                     = coalesce(_quote_patch->>'status',           status),
    shipping_type              = coalesce(_quote_patch->>'shipping_type',    shipping_type),
    shipping_cost              = coalesce((_quote_patch->>'shipping_cost')::numeric,            shipping_cost),
    payment_method             = coalesce(_quote_patch->>'payment_method',   payment_method),
    payment_terms              = coalesce(_quote_patch->>'payment_terms',    payment_terms),
    delivery_time              = coalesce(_quote_patch->>'delivery_time',    delivery_time),
    notes                      = coalesce(_quote_patch->>'notes',            notes),
    internal_notes             = coalesce(_quote_patch->>'internal_notes',   internal_notes),
    discount_percent           = coalesce((_quote_patch->>'discount_percent')::numeric,         discount_percent),
    discount_amount            = coalesce((_quote_patch->>'discount_amount')::numeric,          discount_amount),
    subtotal                   = coalesce((_quote_patch->>'subtotal')::numeric,                 subtotal),
    total                      = coalesce((_quote_patch->>'total')::numeric,                    total),
    negotiation_markup_percent = coalesce((_quote_patch->>'negotiation_markup_percent')::numeric, negotiation_markup_percent),
    valid_until                = coalesce((_quote_patch->>'valid_until')::date,                 valid_until),
    updated_at                 = now()
  where id = _quote_id
  returning * into _updated_quote;

  if _updated_quote is null then
    raise exception 'Orçamento não encontrado: %', _quote_id
      using errcode = 'no_data_found';
  end if;

  -- ── 2. Remove itens/personalizações existentes ────────────────────────────
  delete from public.quote_item_personalizations
  where quote_item_id in (
    select id from public.quote_items where quote_id = _quote_id
  );
  delete from public.quote_items where quote_id = _quote_id;

  -- ── 3. Reinsere itens ─────────────────────────────────────────────────────
  for _item in select value from jsonb_array_elements(coalesce(_items, '[]'::jsonb)) loop
    insert into public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days, bitrix_product_id
    )
    values (
      _quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', '')
    )
    returning id into _new_item_id;

    -- ── 4. Reinsere personalizações ─────────────────────────────────────────
    for _pers in select value from jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb)) loop
      insert into public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      values (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    end loop;
  end loop;

  -- ── 5. Audit trail ───────────────────────────────────────────────────────
  _actor_id := coalesce(auth.uid(), _updated_quote.seller_id);
  if _actor_id is not null then
    if _prev_status is distinct from _updated_quote.status then
      _action := 'status_changed';
      _desc   := format('Status alterado de "%s" para "%s" no %s',
                        _prev_status, _updated_quote.status, _updated_quote.quote_number);
    else
      _action := 'updated';
      _desc   := format('Orçamento %s editado (total: R$ %s)',
                        _updated_quote.quote_number,
                        _updated_quote.total);
    end if;

    insert into public.quote_history (quote_id, user_id, action, description, metadata)
    values (
      _quote_id,
      _actor_id,
      _action,
      _desc,
      jsonb_build_object(
        'prev_status',         _prev_status,
        'new_status',          _updated_quote.status,
        'prev_total',          _prev_total,
        'new_total',           _updated_quote.total,
        'markup',              _updated_quote.negotiation_markup_percent,
        'n_items',             (select count(*) from public.quote_items where quote_id = _quote_id),
        'optimistic_lock_used', (_expected_version is not null)
      )
    );
  end if;

  return _updated_quote;
end;
$function$;;

-- <<< END 20260618103923_update_quote_transactional_optimistic_lock.sql <<<

