-- >>> BEGIN 20260618113750_estoque_vw_product_availability_filter_active_product_20260618.sql >>>

-- vw_product_availability reportava disponibilidade de variantes sob produtos
-- DESPUBLICADOS (is_active=false). Disponibilidade só faz sentido para produto
-- ativo. Adiciona JOIN+filtro de produto ativo. (Os 103 componentes/refis
-- despublicados permanecem ATIVOS — inventário legítimo — apenas deixam de
-- aparecer como "disponíveis".)
CREATE OR REPLACE VIEW public.vw_product_availability AS
SELECT pv.id AS variant_id,
    pv.product_id,
    pv.sku,
    pv.stock_quantity,
    pv.next_quantity_1,
    pv.next_date_1,
    pv.next_quantity_2,
    pv.next_date_2,
    pv.next_quantity_3,
    pv.next_date_3,
    CASE
        WHEN pv.stock_quantity > 0 THEN 'in_stock'::text
        WHEN pv.stock_quantity = 0 AND pv.next_date_1 IS NOT NULL AND pv.next_date_1 > CURRENT_DATE THEN 'out_of_stock_with_restock'::text
        ELSE 'out_of_stock'::text
    END AS availability_status,
    pv.stock_quantity = 0 AND pv.next_date_1 IS NOT NULL AND pv.next_date_1 > CURRENT_DATE AS has_incoming_stock,
    pv.next_date_1 IS NOT NULL AND pv.next_date_1 > CURRENT_DATE AS has_upcoming_restock,
    pv.last_sync_at
FROM product_variants pv
JOIN products p ON p.id = pv.product_id
WHERE pv.is_active = true
  AND p.is_active = true;

NOTIFY pgrst, 'reload schema';
;

-- <<< END 20260618113750_estoque_vw_product_availability_filter_active_product_20260618.sql <<<

-- >>> BEGIN 20260618114202_estoque_enforce_inactive_variant_zero_stock_20260618.sql >>>

-- Invariante robusto: variante INATIVA sempre tem stock_quantity=0, independente
-- do writer. Substitui o trigger estreito (que só cobria a transição is_active)
-- por enforcement em TODO INSERT/UPDATE — fecha o caminho do sync Silver→Gold
-- que reescrevia stock em variantes já inativas.
DROP TRIGGER IF EXISTS trg_zero_stock_on_variant_deactivate ON public.product_variants;
DROP FUNCTION IF EXISTS public.fn_zero_stock_on_variant_deactivate();

CREATE OR REPLACE FUNCTION public.fn_enforce_inactive_variant_zero_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Variante não-ativa não pode carregar estoque vendável.
  IF NEW.is_active IS NOT TRUE AND COALESCE(NEW.stock_quantity,0) <> 0 THEN
    NEW.stock_quantity := 0;
  END IF;
  RETURN NEW;
END;
$function$;

DROP TRIGGER IF EXISTS trg_enforce_inactive_variant_zero_stock ON public.product_variants;
CREATE TRIGGER trg_enforce_inactive_variant_zero_stock
  BEFORE INSERT OR UPDATE ON public.product_variants
  FOR EACH ROW EXECUTE FUNCTION public.fn_enforce_inactive_variant_zero_stock();
;

-- <<< END 20260618114202_estoque_enforce_inactive_variant_zero_stock_20260618.sql <<<

-- >>> BEGIN 20260618114413_harden_calc_real_values_derive_discount.sql >>>

-- DEFESA EM PROFUNDIDADE: fn_quotes_calc_real_values deriva o desconto efetivo de
-- AMBOS discount_percent e discount_amount, em vez de confiar que o cliente já
-- computou discount_amount consistente com discount_percent.
--
-- Gap fechado: se qualquer caminho (SQL bruto, migração, novo código) gravar
-- discount_percent sem discount_amount, a fórmula antiga computava
-- real_discount_percent=0, BURLANDO silenciosamente a validação de alçada
-- (trg_quotes_validate_discount). Agora o desconto efetivo é derivado de forma
-- robusta no servidor.
--
-- Retrocompatibilidade PROVADA: 3608 combos de inputs consistentes do app
-- (percent e amount mode × markup 0-50 × desconto 0-100) → 100% idênticos à
-- fórmula anterior (max_diff=0.00). Só difere no caso de inconsistência (gap).
CREATE OR REPLACE FUNCTION public.fn_quotes_calc_real_values()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_markup numeric;
  v_effective_discount numeric;
BEGIN
  -- Cópia local clampada usada APENAS como divisor defensivo (não regrava a coluna).
  -- A faixa válida é garantida pelo CHECK valid_negotiation_markup_range ([0,50]):
  -- valores fora de faixa são rejeitados pelo constraint (fail-loud), não silenciados.
  v_markup := LEAST(50, GREATEST(0, COALESCE(NEW.negotiation_markup_percent, 0)));

  IF v_markup > 0 THEN
    NEW.real_subtotal := ROUND(NEW.subtotal / (1 + v_markup / 100.0), 2);
  ELSE
    NEW.real_subtotal := NEW.subtotal;
  END IF;

  -- Desconto efetivo derivado no servidor (não confia no cliente):
  -- se há percentual, ele tem precedência e é convertido sobre o subtotal apresentado;
  -- caso contrário usa o valor absoluto. Fecha o gap onde discount_percent setado
  -- com discount_amount=0 zerava o real_discount_percent e burlava a alçada.
  IF COALESCE(NEW.discount_percent, 0) > 0 THEN
    v_effective_discount := ROUND(NEW.subtotal * NEW.discount_percent / 100.0, 2);
  ELSE
    v_effective_discount := COALESCE(NEW.discount_amount, 0);
  END IF;

  IF NEW.real_subtotal > 0 THEN
    NEW.real_discount_percent := ROUND(
      ((NEW.real_subtotal - (NEW.subtotal - v_effective_discount)) / NEW.real_subtotal) * 100,
      2
    );
  ELSE
    NEW.real_discount_percent := 0;
  END IF;

  RETURN NEW;
END
$function$;
;

-- <<< END 20260618114413_harden_calc_real_values_derive_discount.sql <<<

-- >>> BEGIN 20260618115637_harden_fn_super_filtro_product_ids_tags_uuid_safe.sql >>>
-- Endurecimento backward-compatible: tags nao-UUID sao ignoradas (igual a datas/ramos),
-- em vez de lancar 22P02. Comportamento identico em todo input valido (provado em 305 casos
-- diferenciais v1 vs v2). Demais clausulas inalteradas.
CREATE OR REPLACE FUNCTION public.fn_super_filtro_product_ids(
  _datas text[] DEFAULT '{}', _tags text[] DEFAULT '{}', _ramos text[] DEFAULT '{}',
  _segmentos text[] DEFAULT '{}', _publico text[] DEFAULT '{}')
RETURNS TABLE(product_id uuid) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $fn$
  SELECT b.id
  FROM products b
  WHERE b.is_active = true AND b.is_deleted IS NOT TRUE
    AND ( cardinality(_datas)=0 OR EXISTS (
        SELECT 1 FROM product_commemorative_dates pcd
        JOIN commemorative_dates cd ON cd.id = pcd.commemorative_date_id AND cd.is_active
        WHERE pcd.product_id = b.id AND pcd.is_active AND cd.slug = ANY(_datas) ) )
    AND ( cardinality(_tags)=0 OR EXISTS (
        SELECT 1 FROM product_tags pt
        JOIN tags t ON t.id = pt.tag_id AND t.is_active
        WHERE pt.product_id = b.id AND pt.tag_id = ANY( ARRAY(
            SELECT x::uuid FROM unnest(_tags) AS x
            WHERE x ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        ) ) ) )
    AND ( cardinality(_ramos)=0 OR EXISTS (
        SELECT 1 FROM produto_ramo_atividade pra
        JOIN ramo_atividade_filho raf ON raf.id = pra.ramo_atividade_filho_id
        JOIN ramo_atividade ra ON ra.id = raf.ramo_atividade_id
        WHERE pra.produto_id = b.id AND ra.slug = ANY(_ramos) ) )
    AND ( cardinality(_segmentos)=0 OR EXISTS (
        SELECT 1 FROM produto_ramo_atividade pra
        JOIN ramo_atividade_filho raf ON raf.id = pra.ramo_atividade_filho_id
        WHERE pra.produto_id = b.id AND raf.slug = ANY(_segmentos) ) )
    AND ( cardinality(_publico)=0 OR b.target_audience && _publico );
$fn$;

DROP FUNCTION IF EXISTS public._sf_v2(text[],text[],text[],text[],text[]);

GRANT EXECUTE ON FUNCTION public.fn_super_filtro_product_ids(text[],text[],text[],text[],text[]) TO anon, authenticated, service_role;
NOTIFY pgrst, 'reload schema';;

-- <<< END 20260618115637_harden_fn_super_filtro_product_ids_tags_uuid_safe.sql <<<

-- >>> BEGIN 20260618120000_cart_items_quantity_upper_bound_check.sql >>>
-- Integridade do módulo Carrinhos: completa o invariante de quantidade em
-- seller_cart_items para 1 <= quantity <= 999999.
--
-- Contexto: a migration 20260618000000 adicionou o piso (quantity >= 1), mas
-- não havia TETO no banco. O hook useSellerCarts clampa a edição direta em
-- 999999, porém os caminhos de MESCLAGEM (add/move/duplicate) somavam
-- `existing + qty`. Sem teto no banco, somas repetidas poderiam crescer sem
-- limite e, no extremo, estourar o range de int4 — produzindo subtotais
-- absurdos no carrinho e no orçamento gerado. O cliente passou a clampar o
-- teto; este CHECK é a última linha de defesa para qualquer caminho que escape
-- à UI (RPC futura, importação em massa, restore, regressão).
--
-- Idempotente: clampa linhas legadas > 999999 antes de aplicar e só adiciona o
-- CHECK se ele ainda não existir. Mantido como constraint separada do piso para
-- não precisar derrubar/recriar a constraint já existente.

-- 1) Sanea linhas legadas eventualmente acima do teto (clamp para 999999)
--    LOCK elimina a janela de corrida: sem ele um INSERT/UPDATE concorrente
--    poderia escrever quantity > 999999 entre o UPDATE abaixo e o ADD CONSTRAINT.
LOCK TABLE public.seller_cart_items IN SHARE ROW EXCLUSIVE MODE;

UPDATE public.seller_cart_items
SET quantity = 999999
WHERE quantity > 999999;

-- 2) Adiciona o CHECK de teto apenas se ainda não existir
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conrelid = 'public.seller_cart_items'::regclass
      AND conname = 'seller_cart_items_quantity_max'
  ) THEN
    ALTER TABLE public.seller_cart_items
      ADD CONSTRAINT seller_cart_items_quantity_max CHECK (quantity <= 999999);
  END IF;
END $$;

-- <<< END 20260618120000_cart_items_quantity_upper_bound_check.sql <<<

-- >>> BEGIN 20260618120504_fn_color_link_all_suppliers_v2_asia_prefix.sql >>>

CREATE OR REPLACE FUNCTION public.fn_color_link_all_suppliers(
  p_dry_run boolean DEFAULT true
)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_xbz_mono    int := 0;
  v_spot_sm_mono int := 0;
  v_asia_varcor  int := 0;
  v_asia_prefix  int := 0;
  v_xbz_cross    int := 0;
  v_t04          int := 0;
BEGIN

  -- 1. XBZ Mono-cor
  IF NOT p_dry_run THEN
    WITH m AS (
      SELECT DISTINCT ON (pi.id)
        pi.id iid, pv.id vid, pv.color_id cid
      FROM product_images pi
      JOIN LATERAL (
        SELECT pv2.id, pv2.color_id
        FROM product_variants pv2
        WHERE pv2.product_id=pi.product_id AND pv2.is_active=true AND pv2.color_id IS NOT NULL
        ORDER BY pv2.id LIMIT 1
      ) pv ON true
      WHERE pi.supplier_code='XBZ' AND pi.is_active=true
        AND pi.color_id IS NULL AND pi.variant_id IS NULL
        AND (SELECT COUNT(DISTINCT pv3.color_id) FROM product_variants pv3
             WHERE pv3.product_id=pi.product_id AND pv3.is_active=true AND pv3.color_id IS NOT NULL)=1
      ORDER BY pi.id
    )
    UPDATE product_images SET color_id=m.cid, variant_id=m.vid, updated_at=NOW()
    FROM m WHERE id=m.iid;
    GET DIAGNOSTICS v_xbz_mono = ROW_COUNT;
  ELSE
    SELECT COUNT(DISTINCT pi.id) INTO v_xbz_mono
    FROM product_images pi
    WHERE pi.supplier_code='XBZ' AND pi.is_active=true
      AND pi.color_id IS NULL AND pi.variant_id IS NULL
      AND (SELECT COUNT(DISTINCT pv3.color_id) FROM product_variants pv3
           WHERE pv3.product_id=pi.product_id AND pv3.is_active=true AND pv3.color_id IS NOT NULL)=1;
  END IF;

  -- 2. SPOT+SOMARCAS Mono-cor
  IF NOT p_dry_run THEN
    WITH m AS (
      SELECT DISTINCT ON (pi.id)
        pi.id iid, pv.id vid, pv.color_id cid
      FROM product_images pi
      JOIN LATERAL (
        SELECT pv2.id, pv2.color_id
        FROM product_variants pv2
        WHERE pv2.product_id=pi.product_id AND pv2.is_active=true AND pv2.color_id IS NOT NULL
        ORDER BY pv2.id LIMIT 1
      ) pv ON true
      WHERE pi.supplier_code IN ('SPOT','SOMARCAS') AND pi.is_active=true
        AND pi.color_id IS NULL AND pi.variant_id IS NULL
        AND (SELECT COUNT(DISTINCT pv3.color_id) FROM product_variants pv3
             WHERE pv3.product_id=pi.product_id AND pv3.is_active=true AND pv3.color_id IS NOT NULL)=1
      ORDER BY pi.id
    )
    UPDATE product_images SET color_id=m.cid, variant_id=m.vid, updated_at=NOW()
    FROM m WHERE id=m.iid;
    GET DIAGNOSTICS v_spot_sm_mono = ROW_COUNT;
  ELSE
    SELECT COUNT(DISTINCT pi.id) INTO v_spot_sm_mono
    FROM product_images pi
    WHERE pi.supplier_code IN ('SPOT','SOMARCAS') AND pi.is_active=true
      AND pi.color_id IS NULL AND pi.variant_id IS NULL
      AND (SELECT COUNT(DISTINCT pv3.color_id) FROM product_variants pv3
           WHERE pv3.product_id=pi.product_id AND pv3.is_active=true AND pv3.color_id IS NOT NULL)=1;
  END IF;

  -- 3. ASIA via var_cor_nome (raw_data)
  IF NOT p_dry_run THEN
    WITH af AS (
      SELECT DISTINCT ON (pi.id)
        pi.id iid, pv.id vid, pv.color_id cid
      FROM supplier_products_raw spr
      JOIN product_variants pv ON pv.product_id=spr.product_id
        AND pv.is_active=true AND pv.color_id IS NOT NULL
        AND (UPPER(TRIM(spr.raw_data->>'var_cor_nome'))=UPPER(TRIM(pv.color_name))
          OR UPPER(TRIM(spr.raw_data->>'var_cor_nome'))=UPPER(TRIM(
             (SELECT cv.name FROM color_variations cv WHERE cv.id=pv.color_id LIMIT 1))))
        AND NOT EXISTS (SELECT 1 FROM product_images pi2
                        WHERE pi2.product_id=pv.product_id AND pi2.color_id=pv.color_id AND pi2.is_active=true)
      JOIN product_images pi ON pi.product_id=spr.product_id
        AND REGEXP_REPLACE(pi.url_original,'.*/(.+)$','\1')=REGEXP_REPLACE(spr.raw_data->>'imagem','.*/(.+)$','\1')
        AND pi.is_active=true AND pi.color_id IS NULL
      WHERE spr.supplier_id='d2734e23-d633-4819-bb15-e51aa44e2118'::uuid
        AND spr.raw_data->>'var_cor_nome' IS NOT NULL AND spr.raw_data->>'imagem' IS NOT NULL
      ORDER BY pi.id, pv.color_id
    ),
    unamb AS (
      SELECT iid, vid, cid FROM af
      WHERE iid IN (SELECT iid FROM af GROUP BY iid HAVING COUNT(DISTINCT cid)=1)
    )
    UPDATE product_images SET color_id=u.cid, variant_id=u.vid, updated_at=NOW()
    FROM unamb u WHERE id=u.iid;
    GET DIAGNOSTICS v_asia_varcor = ROW_COUNT;
  ELSE
    SELECT COUNT(DISTINCT pi.id) INTO v_asia_varcor
    FROM product_images pi
    JOIN supplier_products_raw spr ON spr.product_id=pi.product_id
    JOIN product_variants pv ON pv.product_id=spr.product_id
      AND pv.is_active=true AND pv.color_id IS NOT NULL
      AND (UPPER(TRIM(spr.raw_data->>'var_cor_nome'))=UPPER(TRIM(pv.color_name))
        OR UPPER(TRIM(spr.raw_data->>'var_cor_nome'))=UPPER(TRIM(
           (SELECT cv.name FROM color_variations cv WHERE cv.id=pv.color_id LIMIT 1))))
      AND NOT EXISTS (SELECT 1 FROM product_images pi2
                      WHERE pi2.product_id=pv.product_id AND pi2.color_id=pv.color_id AND pi2.is_active=true)
    WHERE spr.supplier_id='d2734e23-d633-4819-bb15-e51aa44e2118'::uuid
      AND spr.raw_data->>'var_cor_nome' IS NOT NULL AND spr.raw_data->>'imagem' IS NOT NULL
      AND REGEXP_REPLACE(pi.url_original,'.*/(.+)$','\1')=REGEXP_REPLACE(spr.raw_data->>'imagem','.*/(.+)$','\1')
      AND pi.is_active=true AND pi.color_id IS NULL;
  END IF;

  -- 4. ASIA via prefixo de cor no filename (VD-PERSONALIZACAO, PT-CANETA...)
  IF NOT p_dry_run THEN
    WITH af AS (
      SELECT DISTINCT ON (pi.id)
        pi.id iid, pv.id vid, pv.color_id cid
      FROM product_images pi
      JOIN product_variants pv ON pv.product_id=pi.product_id
        AND pv.is_active=true AND pv.color_id IS NOT NULL
      WHERE pi.supplier_code='ASIA' AND pi.is_active=true
        AND pi.color_id IS NULL AND pi.variant_id IS NULL
        AND (
          UPPER(REGEXP_REPLACE(pi.url_original,'^.*[/-]([A-Z]{2,3})[-_][A-Z].*\.(?:jpg|png|jpeg)$','\1'))
            = UPPER(TRIM(pv.color_code))
          OR UPPER(REGEXP_REPLACE(pi.url_original,'^.+[-_]([A-Z]{2,4})[-_]?\d*\.(?:jpg|png|jpeg)$','\1'))
            = UPPER(TRIM(pv.color_code))
          OR pi.url_original ILIKE '%-' || REPLACE(UPPER(pv.color_name),' ','-') || '-%'
          OR pi.url_original ILIKE '%-' || REPLACE(UPPER(pv.color_name),' ','-') || '.'
          OR pi.url_original ILIKE '%-' || REPLACE(UPPER(pv.color_name),' ','-') || '_'
        )
        AND NOT EXISTS (SELECT 1 FROM product_images pi2
                        WHERE pi2.product_id=pv.product_id AND pi2.color_id=pv.color_id AND pi2.is_active=true)
      ORDER BY pi.id, pv.color_id
    ),
    unamb AS (
      SELECT iid, vid, cid FROM af
      WHERE iid IN (SELECT iid FROM af GROUP BY iid HAVING COUNT(DISTINCT cid)=1)
    )
    UPDATE product_images SET color_id=u.cid, variant_id=u.vid, updated_at=NOW()
    FROM unamb u WHERE id=u.iid;
    GET DIAGNOSTICS v_asia_prefix = ROW_COUNT;
  ELSE
    SELECT COUNT(DISTINCT pi.id) INTO v_asia_prefix
    FROM product_images pi
    JOIN product_variants pv ON pv.product_id=pi.product_id
      AND pv.is_active=true AND pv.color_id IS NOT NULL
    WHERE pi.supplier_code='ASIA' AND pi.is_active=true
      AND pi.color_id IS NULL AND pi.variant_id IS NULL
      AND (
        UPPER(REGEXP_REPLACE(pi.url_original,'^.*[/-]([A-Z]{2,3})[-_][A-Z].*\.(?:jpg|png|jpeg)$','\1'))
          = UPPER(TRIM(pv.color_code))
        OR UPPER(REGEXP_REPLACE(pi.url_original,'^.+[-_]([A-Z]{2,4})[-_]?\d*\.(?:jpg|png|jpeg)$','\1'))
          = UPPER(TRIM(pv.color_code))
        OR pi.url_original ILIKE '%-' || REPLACE(UPPER(pv.color_name),' ','-') || '-%'
        OR pi.url_original ILIKE '%-' || REPLACE(UPPER(pv.color_name),' ','-') || '.'
        OR pi.url_original ILIKE '%-' || REPLACE(UPPER(pv.color_name),' ','-') || '_'
      )
      AND NOT EXISTS (SELECT 1 FROM product_images pi2
                      WHERE pi2.product_id=pv.product_id AND pi2.color_id=pv.color_id AND pi2.is_active=true);
  END IF;

  -- 5. XBZ cross-product color fix (mono-cor com cor errada)
  IF NOT p_dry_run THEN
    WITH fix AS (
      SELECT DISTINCT ON (pi.id)
        pi.id iid, pv.color_id cid, pv.id vid
      FROM product_images pi
      JOIN product_variants pv ON pv.product_id=pi.product_id
        AND pv.is_active=true AND pv.color_id IS NOT NULL
      WHERE pi.is_active=true AND pi.color_id IS NOT NULL AND pi.color_id != pv.color_id
        AND (SELECT COUNT(DISTINCT pv2.color_id) FROM product_variants pv2
             WHERE pv2.product_id=pi.product_id AND pv2.is_active=true AND pv2.color_id IS NOT NULL)=1
        AND NOT EXISTS (SELECT 1 FROM product_images pi3
                        WHERE pi3.product_id=pi.product_id AND pi3.color_id=pv.color_id AND pi3.is_active=true)
        AND NOT EXISTS (SELECT 1 FROM product_variants pv4
                        WHERE pv4.product_id=pi.product_id AND pv4.color_id=pi.color_id AND pv4.is_active=true)
        AND EXISTS (SELECT 1 FROM product_images pi5
                    WHERE pi5.product_id=pi.product_id AND pi5.supplier_code='XBZ' AND pi5.is_active=true)
      ORDER BY pi.id
    )
    UPDATE product_images SET color_id=f.cid, variant_id=f.vid, updated_at=NOW()
    FROM fix f WHERE id=f.iid;
    GET DIAGNOSTICS v_xbz_cross = ROW_COUNT;
  ELSE
    SELECT COUNT(DISTINCT pi.id) INTO v_xbz_cross
    FROM product_images pi
    JOIN product_variants pv ON pv.product_id=pi.product_id AND pv.is_active=true AND pv.color_id IS NOT NULL
    WHERE pi.is_active=true AND pi.color_id IS NOT NULL AND pi.color_id != pv.color_id
      AND (SELECT COUNT(DISTINCT pv2.color_id) FROM product_variants pv2
           WHERE pv2.product_id=pi.product_id AND pv2.is_active=true AND pv2.color_id IS NOT NULL)=1
      AND NOT EXISTS (SELECT 1 FROM product_images pi3
                      WHERE pi3.product_id=pi.product_id AND pi3.color_id=pv.color_id AND pi3.is_active=true)
      AND NOT EXISTS (SELECT 1 FROM product_variants pv4
                      WHERE pv4.product_id=pi.product_id AND pv4.color_id=pi.color_id AND pv4.is_active=true)
      AND EXISTS (SELECT 1 FROM product_images pi5
                  WHERE pi5.product_id=pi.product_id AND pi5.supplier_code='XBZ' AND pi5.is_active=true);
  END IF;

  -- 6. T04 fix: color_id ← variant.color_id quando divergem (nuance vs canonical)
  IF NOT p_dry_run THEN
    WITH div AS (
      SELECT pi.id, pv.color_id cid
      FROM product_images pi
      JOIN product_variants pv ON pv.id=pi.variant_id
      WHERE pi.is_active=true AND pi.color_id IS DISTINCT FROM pv.color_id
        AND pi.variant_id IS NOT NULL AND pv.color_id IS NOT NULL
    )
    UPDATE product_images SET color_id=d.cid, updated_at=NOW()
    FROM div d WHERE product_images.id=d.id;
    GET DIAGNOSTICS v_t04 = ROW_COUNT;
  ELSE
    SELECT COUNT(*) INTO v_t04
    FROM product_images pi JOIN product_variants pv ON pv.id=pi.variant_id
    WHERE pi.is_active=true AND pi.color_id IS DISTINCT FROM pv.color_id
      AND pi.variant_id IS NOT NULL AND pv.color_id IS NOT NULL;
  END IF;

  RETURN jsonb_build_object(
    'dry_run', p_dry_run,
    'xbz_mono', v_xbz_mono,
    'spot_sm_mono', v_spot_sm_mono,
    'asia_varcor', v_asia_varcor,
    'asia_prefix', v_asia_prefix,
    'xbz_cross', v_xbz_cross,
    't04_fix', v_t04,
    'total', v_xbz_mono+v_spot_sm_mono+v_asia_varcor+v_asia_prefix+v_xbz_cross+v_t04,
    'run_at', NOW()
  );
END;
$$;
;

-- <<< END 20260618120504_fn_color_link_all_suppliers_v2_asia_prefix.sql <<<

-- >>> BEGIN 20260618120525_trigger_product_images_deactivate_on_product_inactive.sql >>>

-- Trigger para auto-desativar imagens quando produto é desativado
-- Resolve T095 estruturalmente (não apenas one-shot)
CREATE OR REPLACE FUNCTION fn_sync_product_images_on_product_deactivate()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  -- Quando produto passa de ativo para inativo: desativar todas as suas imagens
  IF OLD.is_active = true AND NEW.is_active = false THEN
    UPDATE product_images
    SET is_active  = false,
        updated_at = NOW()
    WHERE product_id = NEW.id
      AND is_active  = true;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_product_images_on_product_deactivate ON products;
CREATE TRIGGER trg_sync_product_images_on_product_deactivate
  AFTER UPDATE OF is_active ON products
  FOR EACH ROW
  WHEN (OLD.is_active IS DISTINCT FROM NEW.is_active)
  EXECUTE FUNCTION fn_sync_product_images_on_product_deactivate();

COMMENT ON TRIGGER trg_sync_product_images_on_product_deactivate ON products
  IS 'Auto-desativa imagens quando produto é desativado. Resolve T095 estruturalmente.';
;

-- <<< END 20260618120525_trigger_product_images_deactivate_on_product_inactive.sql <<<

-- >>> BEGIN 20260618120559_trigger_sync_primary_image_url_on_is_primary.sql >>>

-- Resolver T086 estruturalmente: quando is_primary muda em product_images,
-- sincronizar products.primary_image_url automaticamente
CREATE OR REPLACE FUNCTION fn_sync_primary_image_url()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  -- Caso 1: imagem passou a is_primary=true → setar no produto
  IF NEW.is_primary = true AND NEW.is_active = true THEN
    UPDATE products
    SET primary_image_url = NEW.url_cdn,
        updated_at        = NOW()
    WHERE id = NEW.product_id
      AND is_active = true
      AND (primary_image_url IS NULL OR primary_image_url != NEW.url_cdn);
  END IF;

  -- Caso 2: imagem era primary e foi desativada → limpar se não há outra primary
  IF (OLD.is_primary = true OR OLD.is_active = true)
    AND (NEW.is_primary = false OR NEW.is_active = false) THEN
    -- Verifica se ainda existe outra primary ativa
    IF NOT EXISTS (
      SELECT 1 FROM product_images
      WHERE product_id = NEW.product_id
        AND is_primary  = true
        AND is_active   = true
        AND id         != NEW.id
    ) THEN
      UPDATE products
      SET primary_image_url = (
            SELECT url_cdn FROM product_images
            WHERE product_id = NEW.product_id AND is_active = true
            ORDER BY is_primary DESC, display_order ASC, id ASC
            LIMIT 1
          ),
          updated_at = NOW()
      WHERE id = NEW.product_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_primary_image_url ON product_images;
CREATE TRIGGER trg_sync_primary_image_url
  AFTER INSERT OR UPDATE OF is_primary, is_active, url_cdn ON product_images
  FOR EACH ROW
  EXECUTE FUNCTION fn_sync_primary_image_url();

COMMENT ON TRIGGER trg_sync_primary_image_url ON product_images
  IS 'Mantém products.primary_image_url sincronizado automaticamente. Resolve T086 estruturalmente.';
;

-- <<< END 20260618120559_trigger_sync_primary_image_url_on_is_primary.sql <<<

-- >>> BEGIN 20260618121622_estoque_promote_variants_respect_is_active_20260618.sql >>>

-- ROOT-CAUSE FIX: fn_promote_variants_of_parent (cron medallion-promote-tick)
-- reescrevia stock_quantity do silver em variantes GOLD inativas (ramo ELSE e
-- ON CONFLICT, sem checar is_active). Agora respeita is_active: variante inativa
-- recebe 0 (coerente com o invariante). Defesa-em-profundidade junto ao trigger.
CREATE OR REPLACE FUNCTION public.fn_promote_variants_of_parent(p_supplier_id uuid, p_parent_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_pid uuid; v_org uuid; pv RECORD; v_vid uuid; v_count int := 0; v_attrs jsonb;
  v_existing_pid uuid;
BEGIN
  PERFORM set_config('app.write_source','pipeline',true);
  SELECT id, organization_id INTO v_pid, v_org FROM public.products
  WHERE supplier_id=p_supplier_id AND supplier_reference=p_parent_reference;
  IF v_pid IS NULL THEN RETURN jsonb_build_object('success',false,'error','produto_pai_nao_promovido','parent',p_parent_reference); END IF;

  FOR pv IN
    SELECT * FROM public.produtos_padronizacao_variantes
    WHERE supplier_id=p_supplier_id AND parent_reference=p_parent_reference AND status='standardized'
  LOOP
    -- M2 2026-06-11: tamanho entra nos attributes (jsonb_strip_nulls ignora NULL)
    v_attrs := jsonb_strip_nulls(jsonb_build_object('cor', pv.color_name, 'codigo_cor', pv.color_code, 'hex', pv.color_hex, 'tamanho', pv.size_code));

    SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants WHERE sku = pv.sku;
    IF v_vid IS NULL THEN
      SELECT id, product_id INTO v_vid, v_existing_pid FROM public.product_variants
      WHERE product_id=v_pid AND supplier_sku=pv.supplier_sku;
    END IF;

    IF v_vid IS NULL THEN
      INSERT INTO public.product_variants (product_id, sku, supplier_sku, name, attributes, color_name, color_code, color_hex, color_id, stock_quantity, is_active, last_sync_at, last_sync_supplier_id,
                                           size_code, size_length_cm, size_width_cm, capacity_ml)
      VALUES (v_pid, pv.sku, pv.supplier_sku, COALESCE(pv.color_name, pv.sku), v_attrs,
              pv.color_name, pv.color_code, pv.color_hex, pv.color_id,
              COALESCE(pv.stock_quantity,0), COALESCE(pv.is_active,true), now(), p_supplier_id,
              pv.size_code, pv.size_length_cm, pv.size_width_cm, pv.capacity_ml)
      ON CONFLICT (sku) DO UPDATE SET
        supplier_sku = EXCLUDED.supplier_sku,
        attributes   = COALESCE(public.product_variants.attributes,'{}'::jsonb) || EXCLUDED.attributes,
        color_name   = COALESCE(EXCLUDED.color_name, public.product_variants.color_name),
        color_code   = COALESCE(EXCLUDED.color_code, public.product_variants.color_code),
        color_hex    = COALESCE(EXCLUDED.color_hex, public.product_variants.color_hex),
        color_id     = COALESCE(EXCLUDED.color_id, public.product_variants.color_id),
        stock_quantity = CASE WHEN public.product_variants.is_active
                              THEN COALESCE(EXCLUDED.stock_quantity, public.product_variants.stock_quantity)
                              ELSE 0 END,
        size_code      = COALESCE(EXCLUDED.size_code, public.product_variants.size_code),
        size_length_cm = COALESCE(EXCLUDED.size_length_cm, public.product_variants.size_length_cm),
        size_width_cm  = COALESCE(EXCLUDED.size_width_cm, public.product_variants.size_width_cm),
        capacity_ml    = COALESCE(EXCLUDED.capacity_ml, public.product_variants.capacity_ml),
        last_sync_at = now(), last_sync_supplier_id = EXCLUDED.last_sync_supplier_id
      RETURNING id INTO v_vid;
    ELSE
      UPDATE public.product_variants SET
        attributes = COALESCE(attributes,'{}'::jsonb) || v_attrs,
        color_name=COALESCE(pv.color_name,color_name), color_code=COALESCE(pv.color_code,color_code),
        color_hex=COALESCE(pv.color_hex,color_hex), color_id=COALESCE(pv.color_id,color_id),
        stock_quantity = CASE WHEN is_active THEN COALESCE(pv.stock_quantity, stock_quantity) ELSE 0 END,
        size_code=COALESCE(pv.size_code,size_code),
        size_length_cm=COALESCE(pv.size_length_cm,size_length_cm),
        size_width_cm=COALESCE(pv.size_width_cm,size_width_cm),
        capacity_ml=COALESCE(pv.capacity_ml,capacity_ml),
        last_sync_at=now(), last_sync_supplier_id=p_supplier_id
      WHERE id=v_vid;
    END IF;

    -- FIX (chk_vss_cost_price_not_zero): só grava source de custo quando custo > 0.
    IF pv.cost_price IS NOT NULL AND pv.cost_price > 0 THEN
      INSERT INTO public.variant_supplier_sources (organization_id, variant_id, supplier_id, cost_price, supplier_sku, supplier_color_code, supplier_color_name, is_active, source, last_synced_at)
      VALUES (v_org, v_vid, p_supplier_id, pv.cost_price, pv.supplier_sku, pv.color_code, pv.color_name, true, 'silver', now())
      ON CONFLICT (variant_id, supplier_id) DO UPDATE SET
        cost_price          = EXCLUDED.cost_price,
        supplier_sku        = EXCLUDED.supplier_sku,
        supplier_color_code = EXCLUDED.supplier_color_code,
        supplier_color_name = EXCLUDED.supplier_color_name,
        is_active           = EXCLUDED.is_active,
        source              = EXCLUDED.source,
        last_synced_at      = EXCLUDED.last_synced_at;
    END IF;

    UPDATE public.produtos_padronizacao_variantes SET status='promoted', variant_id=v_vid, updated_at=now() WHERE id=pv.id;

    -- 3-fases: raw concluída ao chegar no Gold. FIX: limpa process_errors
    -- (promoção bem-sucedida supera erro anterior; respeita chk_spr_no_processed_with_errors).
    IF pv.raw_id IS NOT NULL THEN
      UPDATE public.supplier_products_raw
         SET status='processed', processed_at=now(), product_id=v_pid, variant_id=v_vid,
             process_errors=NULL
       WHERE id=pv.raw_id AND status <> 'processed';
    END IF;

    v_count := v_count + 1;
  END LOOP;
  RETURN jsonb_build_object('success',true,'product_id',v_pid,'variantes_promovidas',v_count);
END;
$function$;
;

-- <<< END 20260618121622_estoque_promote_variants_respect_is_active_20260618.sql <<<

-- >>> BEGIN 20260618121811_estoque_reconcile_add_orphan_vss_selfheal_20260618.sql >>>

-- Reconciliador diário agora também auto-cura C06 (nível -1): desativa VSS ativa
-- sob variante inativa (invariante "VSS ativa ⟹ variante ativa"). Fecha a via de
-- recorrência via fn_promote_variants_of_parent (que reativa VSS com cost_price>0).
CREATE OR REPLACE FUNCTION public.fn_reconcile_stock_gold(p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_var int := 0; v_prod int := 0; v_vss int := 0; v_orphan int := 0;
  v_var_div int; v_prod_div int; v_vss_div int; v_orphan_div int;
  v_t0 timestamptz := clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtext('fn_reconcile_stock_gold')::bigint) THEN
    RETURN jsonb_build_object('skipped','lock_ocupado');
  END IF;

  PERFORM set_config('app.bulk_import_mode','true', true);
  PERFORM set_config('app.write_source','reconcile', true);
  PERFORM set_config('app.skip_stock_snapshot','true', true);

  -- diagnóstico (antes)
  SELECT count(*) INTO v_orphan_div FROM variant_supplier_sources v
    WHERE v.is_active AND v.variant_id IN (SELECT id FROM product_variants WHERE is_active=false);
  SELECT count(*) INTO v_vss_div FROM variant_supplier_sources v
    WHERE v.is_active AND NOT COALESCE(v.removed_from_api,false)
      AND v.quantity IS DISTINCT FROM (COALESCE(v.stock_main_warehouse,0)+COALESCE(v.stock_other_warehouses,0));
  SELECT count(*) INTO v_var_div FROM (
    SELECT v.id FROM product_variants v
    LEFT JOIN variant_supplier_sources s ON s.variant_id=v.id AND s.is_active
    WHERE v.is_active
    GROUP BY v.id, v.stock_quantity
    HAVING COALESCE(v.stock_quantity,0) IS DISTINCT FROM COALESCE(sum(s.quantity),0)) z;
  SELECT count(*) INTO v_prod_div FROM (
    SELECT p.id FROM products p
    LEFT JOIN product_variants v ON v.product_id=p.id AND v.is_active
    WHERE p.is_active
    GROUP BY p.id, p.stock_quantity
    HAVING COALESCE(p.stock_quantity,0) IS DISTINCT FROM COALESCE(sum(v.stock_quantity),0)) z;

  IF p_dry_run THEN
    RETURN jsonb_build_object('dry_run', true,
      'vss_orfas', v_orphan_div,
      'vss_incoerentes', v_vss_div,
      'variantes_divergentes', v_var_div, 'products_divergentes', v_prod_div);
  END IF;

  -- nível -1: invariante estrutural (VSS ativa só sob variante ativa)
  WITH orphan AS (
    UPDATE variant_supplier_sources v SET is_active=false, updated_at=now()
    WHERE v.is_active AND v.variant_id IN (SELECT id FROM product_variants WHERE is_active=false)
    RETURNING v.id)
  SELECT count(*) INTO v_orphan FROM orphan;

  -- nível 0: coerência interna VSS (main+other == quantity)
  WITH upd AS (
    UPDATE variant_supplier_sources v
       SET stock_main_warehouse = v.quantity, stock_other_warehouses = 0, updated_at = now()
    WHERE v.is_active AND NOT COALESCE(v.removed_from_api,false)
      AND v.quantity IS DISTINCT FROM (COALESCE(v.stock_main_warehouse,0)+COALESCE(v.stock_other_warehouses,0))
    RETURNING v.id)
  SELECT count(*) INTO v_vss FROM upd;

  -- nível 1: VSS → product_variants
  WITH agg AS (
    SELECT v.id, COALESCE(sum(s.quantity) FILTER (WHERE s.is_active),0) AS q
    FROM product_variants v
    LEFT JOIN variant_supplier_sources s ON s.variant_id=v.id
    WHERE v.is_active
    GROUP BY v.id),
  upd AS (
    UPDATE product_variants v SET stock_quantity = agg.q
    FROM agg WHERE v.id=agg.id AND COALESCE(v.stock_quantity,0) IS DISTINCT FROM agg.q
    RETURNING v.id)
  SELECT count(*) INTO v_var FROM upd;

  -- nível 2: product_variants → products (cache + is_stockout)
  WITH agg AS (
    SELECT p.id, COALESCE(sum(v.stock_quantity) FILTER (WHERE v.is_active),0) AS q
    FROM products p
    LEFT JOIN product_variants v ON v.product_id=p.id
    WHERE p.is_active
    GROUP BY p.id),
  upd AS (
    UPDATE products p
       SET stock_quantity = agg.q, is_stockout = (agg.q <= 0), last_stock_update_at = now()
    FROM agg WHERE p.id=agg.id
      AND (COALESCE(p.stock_quantity,0) IS DISTINCT FROM agg.q
           OR p.is_stockout IS DISTINCT FROM (agg.q <= 0))
    RETURNING p.id)
  SELECT count(*) INTO v_prod FROM upd;

  RETURN jsonb_build_object(
    'vss_orfas_antes', v_orphan_div,
    'vss_incoerentes_antes', v_vss_div,
    'variantes_divergentes_antes', v_var_div,
    'products_divergentes_antes', v_prod_div,
    'vss_orfas_desativadas', v_orphan,
    'vss_coerencia_corrigidas', v_vss,
    'variantes_corrigidas', v_var,
    'products_corrigidos', v_prod,
    'segundos', round(extract(epoch FROM clock_timestamp()-v_t0)::numeric,1),
    'ts', now());
END $function$;
;

-- <<< END 20260618121811_estoque_reconcile_add_orphan_vss_selfheal_20260618.sql <<<

-- >>> BEGIN 20260618130000_cart_concurrency_advisory_locks.sql >>>
-- Hardening de concorrencia nos triggers de carrinhos (seller_carts / seller_cart_items).
-- Auditoria exaustiva encontrou dois triggers fazendo read-modify-write SEM lock; sob
-- READ COMMITTED, dois INSERTs concorrentes liam o mesmo estado e violavam invariantes:
--   1) assign_cart_item_sort_order: dois itens recebiam o MESMO sort_order (empate de ordem;
--      nao ha unique em (cart_id, sort_order) que barre).
--   2) enforce_seller_cart_limit: o teto de 3 carrinhos por vendedor podia ser furado (4+),
--      pois o trigger e o UNICO gate (sem exclusion/check de cap).
-- Correcao: advisory lock TRANSACIONAL por chave (cart_id / seller_id), liberado no commit,
-- serializando apenas operacoes concorrentes do MESMO carrinho/vendedor (contencao minima).
-- Namespaces distintos: 415263 (sort_order) e 415264 (limite).

CREATE OR REPLACE FUNCTION public.assign_cart_item_sort_order()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
BEGIN
  IF (TG_OP = 'INSERT' AND NEW.sort_order IS NULL)
     OR (TG_OP = 'UPDATE' AND NEW.cart_id <> OLD.cart_id) THEN
    PERFORM pg_advisory_xact_lock(415263, hashtext(NEW.cart_id::text));
    SELECT COALESCE(MAX(sort_order), -1) + 1
      INTO NEW.sort_order
      FROM public.seller_cart_items
     WHERE cart_id = NEW.cart_id
       AND id <> NEW.id;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_seller_cart_limit()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock(415264, hashtext(NEW.seller_id::text));
  IF (SELECT count(*) FROM public.seller_carts WHERE seller_id = NEW.seller_id) >= 3 THEN
    RAISE EXCEPTION 'Limite de 3 carrinhos por vendedor atingido' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$;

