-- >>> BEGIN 20260618170025_fix_v_catalog_stats_revoke_write_grants.sql >>>

-- ================================================================
-- HYGIENE FIX: C3 — Revogar grants de escrita desnecessários em v_catalog_stats
-- ================================================================
-- Contexto: v_catalog_stats é uma aggregate view (GROUP-less COUNT — nunca updatable).
-- Supabase herdou INSERT/UPDATE/DELETE/REFERENCES/TRIGGER via ALTER DEFAULT PRIVILEGES.
-- Esses grants são dead-code perigoso (não funcionam, pois is_insertable_into='NO'),
-- mas causam HTTP 500 ao invés de 403/405 em tentativas de escrita — comportamento confuso.
-- Fix: manter apenas SELECT (necessário para o frontend) e revogar o resto.
REVOKE INSERT, UPDATE, DELETE, REFERENCES, TRIGGER
  ON public.v_catalog_stats
  FROM anon, authenticated;

-- Confirmar resultado esperado:
-- anon: SELECT only | authenticated: SELECT only
;

-- <<< END 20260618170025_fix_v_catalog_stats_revoke_write_grants.sql <<<

-- >>> BEGIN 20260618171421_add_event_trigger_revoke_view_write_grants.sql >>>

-- ================================================================
-- MELHORIA 4: Event Trigger automático — REVOKE write grants em views public
-- 2026-06-18 — elimina dead-code herdado do Supabase DEFAULT PRIVILEGES
-- ================================================================
CREATE OR REPLACE FUNCTION public.fn_revoke_view_write_grants_on_create()
RETURNS event_trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  obj record;
  view_name text;
BEGIN
  FOR obj IN
    SELECT object_type, schema_name, object_identity
    FROM pg_event_trigger_ddl_commands()
    WHERE object_type = 'view'
      AND schema_name = 'public'
  LOOP
    view_name := obj.object_identity;
    BEGIN
      EXECUTE format(
        'REVOKE INSERT, UPDATE, DELETE, REFERENCES, TRIGGER ON %s FROM anon, authenticated',
        view_name
      );
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'fn_revoke_view_write_grants_on_create: could not revoke on %: %',
        view_name, SQLERRM;
    END;
  END LOOP;
END;
$$;

COMMENT ON FUNCTION public.fn_revoke_view_write_grants_on_create()
  IS 'Event trigger: revoga automaticamente INSERT/UPDATE/DELETE/REFERENCES/TRIGGER '
     'de anon e authenticated em novas views public.*, mantendo apenas SELECT. '
     'Criado 2026-06-18 para eliminar dead-code do Supabase DEFAULT PRIVILEGES.';

DROP EVENT TRIGGER IF EXISTS evt_revoke_view_write_grants;

CREATE EVENT TRIGGER evt_revoke_view_write_grants
  ON ddl_command_end
  WHEN TAG IN ('CREATE VIEW')
  EXECUTE FUNCTION public.fn_revoke_view_write_grants_on_create();

COMMENT ON EVENT TRIGGER evt_revoke_view_write_grants
  IS 'Dispara fn_revoke_view_write_grants_on_create() após CREATE [OR REPLACE] VIEW '
     'em public.*, garantindo SELECT-only para anon e authenticated.';
;

-- <<< END 20260618171421_add_event_trigger_revoke_view_write_grants.sql <<<

-- >>> BEGIN 20260618172121_sec_revoke_public_grant_rpcs.sql >>>

-- MELHORIA 1 (2026-06-18): Revogar GRANT PUBLIC das RPCs de catálogo
-- Risco simulado: REVOKE PUBLIC não afeta anon/authenticated (grants explícitos mantidos)
-- No Supabase, requisições anon usam role 'anon', não 'PUBLIC' — safe to revoke

REVOKE EXECUTE ON FUNCTION public.fn_get_product_intelligence_all() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_get_all_leaf_categories() FROM PUBLIC;

-- Manter apenas anon + authenticated (já existem como grants explícitos)
-- Verificação inline
DO $$
DECLARE
  v_pub_intel int;
  v_pub_leaf  int;
BEGIN
  SELECT COUNT(*) INTO v_pub_intel
  FROM information_schema.routine_privileges
  WHERE routine_name = 'fn_get_product_intelligence_all' AND grantee = 'PUBLIC';

  SELECT COUNT(*) INTO v_pub_leaf
  FROM information_schema.routine_privileges
  WHERE routine_name = 'fn_get_all_leaf_categories' AND grantee = 'PUBLIC';

  IF v_pub_intel > 0 OR v_pub_leaf > 0 THEN
    RAISE EXCEPTION 'REVOKE falhou — PUBLIC grant ainda presente';
  END IF;

  RAISE NOTICE 'OK: PUBLIC grant revogado. anon+authenticated mantidos.';
END;
$$;
;

-- <<< END 20260618172121_sec_revoke_public_grant_rpcs.sql <<<

-- >>> BEGIN 20260618172232_fix_abc_classification_c_missing.sql >>>

-- MELHORIA 2 (2026-06-18): Corrigir abc_classification em analytics.mv_product_intelligence
-- Bug: percent_rank() com 3 926 empates em total_depleted_30d=0 recebe rank=0.458 ≤ 0.50
-- → todos classificados como B em vez de C
-- Fix: produtos com depletion=0 são SEMPRE C, independente do percent_rank

DROP MATERIALIZED VIEW IF EXISTS analytics.mv_product_intelligence CASCADE;

CREATE MATERIALIZED VIEW analytics.mv_product_intelligence AS
WITH product_metrics AS (
  SELECT
    sv.product_id,
    SUM(sv.total_depleted_30d)       AS total_depleted_30d,
    SUM(sv.total_depleted_90d)       AS total_depleted_90d,
    SUM(sv.current_stock)            AS total_current_stock,
    AVG(sv.avg_daily_depletion_7d)   AS avg_depletion_7d,
    AVG(sv.avg_daily_depletion_30d)  AS avg_depletion_30d,
    MIN(sv.days_to_stockout)         AS min_days_to_stockout,
    MAX(sv.velocity_trend)           AS max_velocity_trend,
    SUM(sv.total_restocked_30d)      AS total_restocked_30d,
    COUNT(*)                         AS supplier_count,
    AVG(sv.current_price)            AS avg_current_price
  FROM analytics.mv_stock_velocity sv
  GROUP BY sv.product_id
),
ranked AS (
  SELECT
    pm.*,
    percent_rank() OVER (ORDER BY pm.total_depleted_30d DESC) AS depletion_rank
  FROM product_metrics pm
)
SELECT
  product_id,
  total_depleted_30d,
  total_depleted_90d,
  total_current_stock,
  avg_depletion_7d,
  avg_depletion_30d,
  min_days_to_stockout,
  max_velocity_trend,
  total_restocked_30d,
  supplier_count,
  avg_current_price,
  -- FIX 2026-06-18: produtos sem depletion são SEMPRE C.
  -- Bug anterior: percent_rank() com 3 926 empates em 0 recebia rank=0.458 ≤ 0.50 → B.
  CASE
    WHEN (total_depleted_30d = 0 OR total_depleted_30d IS NULL) THEN 'C'::text
    WHEN (depletion_rank <= 0.20)                               THEN 'A'::text
    WHEN (depletion_rank <= 0.50)                               THEN 'B'::text
    ELSE                                                              'C'::text
  END AS abc_classification,
  LEAST(100::numeric,
    ROUND((
      COALESCE(avg_depletion_30d, 0) * 5 +
      CASE WHEN COALESCE(max_velocity_trend, 0) > 1 THEN max_velocity_trend * 10 ELSE 0 END +
      CASE WHEN COALESCE(total_restocked_30d, 0) > 0 THEN 15 ELSE 0 END::numeric
    ), 1)
  ) AS turnover_score,
  ((COALESCE(max_velocity_trend, 0) > 1.5) AND (COALESCE(min_days_to_stockout, 999) < 15))
    AS is_hot_product,
  ((COALESCE(total_depleted_30d, 0) < 5) AND (COALESCE(total_current_stock, 0) > 100))
    AS is_stagnant,
  ((COALESCE(total_depleted_30d, 0) < 5) AND (COALESCE(total_current_stock, 0) > 500))
    AS is_negotiation_opportunity,
  ((COALESCE(min_days_to_stockout, 999) < 7) AND (COALESCE(avg_depletion_30d, 0) > 1))
    AS is_stockout_risk,
  (COALESCE(total_restocked_30d, 0) > COALESCE(total_depleted_30d, 0) * 0.5)
    AS has_frequent_restock,
  NOW() AS refreshed_at
FROM ranked r;

-- Índices da MV
CREATE UNIQUE INDEX mv_product_intelligence_pk
  ON analytics.mv_product_intelligence (product_id);

CREATE INDEX mv_product_intelligence_abc_idx
  ON analytics.mv_product_intelligence (abc_classification);

CREATE INDEX mv_product_intelligence_turnover_idx
  ON analytics.mv_product_intelligence (turnover_score DESC);

-- Permissões
GRANT SELECT ON analytics.mv_product_intelligence TO authenticated, anon;

-- Recriar view pública (dropped by CASCADE)
CREATE OR REPLACE VIEW public.mv_product_intelligence AS
SELECT
  product_id,
  total_depleted_30d,
  total_depleted_90d,
  total_current_stock,
  avg_depletion_7d,
  avg_depletion_30d,
  min_days_to_stockout,
  max_velocity_trend,
  total_restocked_30d,
  supplier_count,
  avg_current_price,
  abc_classification,
  turnover_score,
  is_hot_product,
  is_stagnant,
  is_negotiation_opportunity,
  is_stockout_risk,
  has_frequent_restock,
  refreshed_at
FROM analytics.mv_product_intelligence;

GRANT SELECT ON public.mv_product_intelligence TO authenticated, anon;
;

-- <<< END 20260618172232_fix_abc_classification_c_missing.sql <<<

