-- >>> BEGIN 20260619000000_fix_favorites_module.sql >>>
-- ============================================================
-- MIGRATION: fix_favorites_module
-- Date: 2026-06-19
-- Author: Claude Code (audit + fix)
--
-- BUG #1 (CRITICAL): The unique index on favorite_items uses
--   COALESCE(variant_id, '00000000-0000-0000-0000-000000000000')
--   which is a functional expression. PostgREST's upsert with
--   onConflict:'list_id,product_id,variant_id' cannot resolve
--   against functional indexes → all add-to-favorites fail with
--   42P10 "there is no unique or exclusion constraint matching".
--   Fix: replace with NULLS NOT DISTINCT (PG15+/PG17 compatible).
--
-- BUG #2: ensure_default_favorite_list had a TOCTOU race condition
--   (SELECT then INSERT) that could cause duplicate default lists.
--   Fix: wrap INSERT in exception handler.
--
-- BUG #3: fn_favorite_items_soft_delete ran as INVOKER, so
--   coordinator-level deletes of other users' items would cause
--   the trigger INSERT into trash to fail RLS. Fix: SECURITY DEFINER.
--
-- BUG #4: No atomic restore-from-trash RPC; two-step client code
--   could leave items in both tables on partial failure.
--   Fix: add restore_favorite_from_trash() RPC.
-- ============================================================

-- ─── BUG #1: fix unique index ────────────────────────────────

DROP INDEX IF EXISTS public.uniq_fi_list_product_variant;

-- NULLS NOT DISTINCT: treats NULL as equal for uniqueness,
-- same semantics as the old COALESCE sentinel but works with
-- plain-column ON CONFLICT syntax required by PostgREST.
CREATE UNIQUE INDEX uniq_fi_list_product_variant
  ON public.favorite_items USING btree (list_id, product_id, variant_id)
  NULLS NOT DISTINCT;

-- ─── BUG #2: race-safe ensure_default_favorite_list ──────────

CREATE OR REPLACE FUNCTION public.ensure_default_favorite_list(_user_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
  v_list_id uuid;
BEGIN
  -- Fast path: list already exists
  SELECT id INTO v_list_id
  FROM public.favorite_lists
  WHERE user_id = _user_id AND is_default = true
  LIMIT 1;

  IF v_list_id IS NOT NULL THEN
    RETURN v_list_id;
  END IF;

  -- Slow path: create, handling concurrent creation via exception
  BEGIN
    INSERT INTO public.favorite_lists (
      user_id, name, description, color, icon, is_default, position
    ) VALUES (
      _user_id, 'Meus Favoritos', 'Lista padrão de favoritos', '#3B82F6', 'Heart', true, 0
    )
    RETURNING id INTO v_list_id;
  EXCEPTION WHEN unique_violation THEN
    -- Another concurrent call won the race; fetch the winner
    SELECT id INTO v_list_id
    FROM public.favorite_lists
    WHERE user_id = _user_id AND is_default = true
    LIMIT 1;
  END;

  RETURN v_list_id;
END;
$$;

-- ─── BUG #3: soft-delete trigger — SECURITY DEFINER ──────────

CREATE OR REPLACE FUNCTION public.fn_favorite_items_soft_delete()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  INSERT INTO public.favorite_items_trash (
    original_id, list_id, user_id, product_id, variant_id,
    variant_info, note, price_at_save, position, added_at, deleted_at
  ) VALUES (
    OLD.id, OLD.list_id, OLD.user_id, OLD.product_id, OLD.variant_id,
    OLD.variant_info, OLD.note, OLD.price_at_save, OLD.position, OLD.added_at, now()
  )
  ON CONFLICT DO NOTHING;  -- safeguard against duplicate trash entries
  RETURN OLD;
END;
$$;

-- ─── BUG #4: atomic restore-from-trash RPC ───────────────────

CREATE OR REPLACE FUNCTION public.restore_favorite_from_trash(
  _trash_id        uuid,
  _user_id         uuid,
  _fallback_list_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
  v_trash           public.favorite_items_trash%ROWTYPE;
  v_list_id         uuid;
  v_item_id         uuid;
  v_original_list   uuid;
BEGIN
  -- Load and validate ownership
  SELECT * INTO v_trash
  FROM public.favorite_items_trash
  WHERE id = _trash_id AND user_id = _user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not-found');
  END IF;

  v_original_list := v_trash.list_id;

  -- Resolve target list: original → fallback → default
  SELECT id INTO v_list_id
  FROM public.favorite_lists
  WHERE id = v_trash.list_id
    AND user_id = _user_id
    AND is_archived = false;

  IF v_list_id IS NULL AND _fallback_list_id IS NOT NULL THEN
    SELECT id INTO v_list_id
    FROM public.favorite_lists
    WHERE id = _fallback_list_id
      AND user_id = _user_id
      AND is_archived = false;
  END IF;

  IF v_list_id IS NULL THEN
    v_list_id := public.ensure_default_favorite_list(_user_id);
  END IF;

  -- Atomically restore (idempotent via ON CONFLICT DO NOTHING)
  INSERT INTO public.favorite_items (
    list_id, user_id, product_id, variant_id, variant_info,
    note, price_at_save
  ) VALUES (
    v_list_id, _user_id, v_trash.product_id, v_trash.variant_id, v_trash.variant_info,
    v_trash.note, v_trash.price_at_save
  )
  ON CONFLICT (list_id, product_id, variant_id) DO NOTHING
  RETURNING id INTO v_item_id;

  -- Remove from trash only if insert succeeded or item already in list
  DELETE FROM public.favorite_items_trash WHERE id = _trash_id;

  RETURN jsonb_build_object(
    'ok',                   true,
    'item_id',              v_item_id,
    'list_id',              v_list_id,
    'original_list_changed', (v_list_id IS DISTINCT FROM v_original_list)
  );
END;
$$;

-- Grant execute to authenticated users
GRANT EXECUTE ON FUNCTION public.restore_favorite_from_trash(uuid, uuid, uuid)
  TO authenticated;

-- <<< END 20260619000000_fix_favorites_module.sql <<<

-- >>> BEGIN 20260619000001_fix_fn_get_product_intelligence_all_gap2.sql >>>
-- GAP-2 FIX (2026-06-19 audit)
-- fn_get_product_intelligence_all: filtrar produtos inativos/deletados.
--
-- Problema: analytics.mv_product_intelligence incluía 72 registros de produtos
-- desativados (originados de analytics.mv_stock_velocity que não filtra por
-- is_active). A função retornava esses 72 inativos para o frontend, que os
-- incluía no supplierSalesMap, potencialmente distorcendo o sort best-seller.
--
-- Fix: JOIN com products para filtrar apenas ativos e não-deletados.
-- Não altera a MV de analytics (que pode ter outros usos).
-- --------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.fn_get_product_intelligence_all()
RETURNS TABLE(
  product_id          uuid,
  turnover_score      numeric,
  avg_depletion_7d    numeric,
  avg_depletion_30d   numeric,
  abc_classification  text,
  total_depleted_30d  numeric,
  total_depleted_90d  numeric
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = 'public'
AS $function$
  -- FIX GAP-2 (2026-06-19 audit): filtra produtos inativos/deletados.
  -- analytics.mv_product_intelligence incluía 72 registros de produtos desativados
  -- (originados de analytics.mv_stock_velocity que não filtra por is_active).
  -- JOIN com products garante que a API sempre retorna apenas produtos ativos.
  SELECT
    mi.product_id,
    mi.turnover_score,
    mi.avg_depletion_7d,
    mi.avg_depletion_30d,
    mi.abc_classification,
    mi.total_depleted_30d,
    mi.total_depleted_90d
  FROM mv_product_intelligence mi          -- public view → analytics.mv_product_intelligence
  JOIN products p ON p.id = mi.product_id  -- filter: apenas ativos e não deletados
  WHERE p.is_active = true
    AND (p.is_deleted IS NOT TRUE OR p.is_deleted IS NULL);
$function$;

COMMENT ON FUNCTION public.fn_get_product_intelligence_all() IS
  'Retorna TODAS as linhas de mv_product_intelligence para produtos ATIVOS sem limitação de max_rows.
   FIX BUG-A (2026-06-18): bypassa PostgREST max_rows=1000.
   FIX GAP-2 (2026-06-19 audit): filtra inativos/deletados via JOIN com products.
   Consumida por useSupplierSalesRanking para popular supplierSalesMap.';

-- UNIQUE INDEX em analytics.mv_product_intelligence para REFRESH CONCURRENTLY
-- (o índice normal existente não permite CONCURRENTLY)
CREATE UNIQUE INDEX IF NOT EXISTS idx_mv_product_intelligence_product_id_unique
  ON analytics.mv_product_intelligence (product_id);

-- Refresh com CONCURRENTLY para remover os 72 inativos sem bloquear leituras
REFRESH MATERIALIZED VIEW CONCURRENTLY analytics.mv_product_intelligence;

NOTIFY pgrst, 'reload schema';

-- <<< END 20260619000001_fix_fn_get_product_intelligence_all_gap2.sql <<<

-- >>> BEGIN 20260619000001_fix_is_shared_on_canonical_null.sql >>>
-- Migration: fix_is_shared_on_canonical_null_20260619
-- Purpose: Gap fix discovered during exhaustive testing — hard-delete of canonical root
-- triggers FK ON DELETE SET NULL on dependent rows' canonical_image_id, but leaves
-- is_shared=true. That state violates invariant C09 (is_shared=true must have canonical).
-- Fix: BEFORE UPDATE trigger that resets is_shared to false whenever
--      canonical_image_id transitions from NOT NULL to NULL.

BEGIN;

CREATE OR REPLACE FUNCTION public.fn_reset_is_shared_on_canonical_null()
RETURNS TRIGGER LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
BEGIN
  IF NEW.canonical_image_id IS NULL AND OLD.canonical_image_id IS NOT NULL THEN
    NEW.is_shared := false;
    NEW.last_modified_source := COALESCE(NULLIF(NEW.last_modified_source, ''), 'edge_function');
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_reset_is_shared_on_canonical_null() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_reset_is_shared_on_canonical_null() TO service_role;

DROP TRIGGER IF EXISTS trg_reset_is_shared_on_canonical_null ON public.product_images;
CREATE TRIGGER trg_reset_is_shared_on_canonical_null
  BEFORE UPDATE OF canonical_image_id
  ON public.product_images
  FOR EACH ROW
  WHEN (NEW.canonical_image_id IS NULL AND OLD.canonical_image_id IS NOT NULL)
  EXECUTE FUNCTION public.fn_reset_is_shared_on_canonical_null();

COMMIT;

-- <<< END 20260619000001_fix_is_shared_on_canonical_null.sql <<<

