        -- (Rows with different content_hash from elected_dep become orphaned standalones
        --  in this step; C16 will detect any residual cross-group violations.)
        UPDATE public.product_images
        SET canonical_image_id = v_elected_dep_root,
            is_shared           = true,
            updated_at          = now()
        WHERE canonical_image_id = NEW.id
          AND id <> NEW.id
          AND id <> v_elected_dep_root
          AND deleted_at IS NULL;
      END IF;
      -- If no former deps → nothing to do
    END IF;

  END IF;

  RETURN NEW;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_autolink_canonical_on_content_hash() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_autolink_canonical_on_content_hash() TO service_role;

COMMIT;

-- <<< END 20260619000008_fix_gap_c5_correct_relink.sql <<<

-- >>> BEGIN 20260619000009_fix_gap_c5b_new_group.sql >>>
-- Migration: fix_gap_c5b_new_group_20260619
-- Purpose: Extend GAP-C5 re-linking to cover the case where a root changes hash
--          to a BRAND NEW group (one with no existing members).
--
-- Problem discovered (GAP-C5b): Migration 008 only fired the former-dep re-link block
-- when v_root_id IS NOT NULL (i.e., the root joined an existing group and became a dep).
-- When a root changes hash to a new group with no existing members, v_root_id stays NULL,
-- the C5 block is skipped, and former deps remain pointing to the root with a mismatched
-- content_hash — creating C16 violations (dep.content_hash ≠ canonical.content_hash).
--
-- Example:
--   rootA(VFY2) + dep1(VFY2) + dep2(VFY2)
--   rootA changes hash → VFY9 (brand new group)
--   rootA stays standalone root of VFY9.
--   dep1 and dep2 still point to rootA but have VFY2 hash → C16 violations.
--
-- Fix: Change the C5 trigger condition from
--   OLD.canonical_image_id IS NULL AND v_root_id IS NOT NULL
-- to
--   OLD.canonical_image_id IS NULL AND OLD.content_hash IS NOT NULL
--
-- This fires whenever the row WAS a root in a previous hash group (OLD.content_hash IS NOT NULL),
-- regardless of whether it joins a new group (v_root_id IS NOT NULL) or remains standalone.
-- Using OLD.content_hash IS NOT NULL avoids edge cases where the hash was NULL (first-set),
-- where deps would have NULL hash and no C16 violation exists.

CREATE OR REPLACE FUNCTION public.fn_autolink_canonical_on_content_hash()
RETURNS TRIGGER LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
DECLARE
  v_root_id               uuid;
  v_existing_canonical_hash text;
  v_old_group_root        uuid;
  v_elected_dep_root      uuid;
BEGIN
  -- Only act when content_hash is being set or changed
  IF NEW.content_hash IS NULL OR (OLD.content_hash IS NOT NULL AND OLD.content_hash = NEW.content_hash) THEN
    RETURN NEW;
  END IF;

  -- If image already has a canonical assignment:
  IF NEW.canonical_image_id IS NOT NULL THEN
    IF OLD.content_hash IS NOT NULL AND OLD.content_hash IS DISTINCT FROM NEW.content_hash THEN
      -- Hash CHANGED (not first-set): clear old canonical → re-link to correct group
      NEW.canonical_image_id := NULL;
      NEW.is_shared := false;
    ELSE
      -- First-set (OLD.content_hash was NULL): validate canonical belongs to SAME hash group
      -- GAP-C6: existing canonical may point to a different-hash group
      SELECT content_hash INTO v_existing_canonical_hash
      FROM public.product_images
      WHERE id = NEW.canonical_image_id;

      IF v_existing_canonical_hash IS NOT DISTINCT FROM NEW.content_hash THEN
        RETURN NEW;  -- Same hash group: respect existing canonical
      END IF;
      -- Wrong hash group: fall through to re-link to correct root
      NEW.canonical_image_id := NULL;
      NEW.is_shared := false;
    END IF;
  END IF;

  -- Find the oldest root in the new hash group
  SELECT id INTO v_root_id
  FROM public.product_images
  WHERE content_hash = NEW.content_hash
    AND deleted_at IS NULL
    AND canonical_image_id IS NULL
    AND id <> NEW.id
    AND is_shared = false
  ORDER BY created_at ASC, id ASC
  LIMIT 1;

  IF v_root_id IS NOT NULL THEN
    NEW.canonical_image_id := v_root_id;
    NEW.is_shared := true;
  ELSE
    -- Fallback: inherit root from existing dependent in same group
    SELECT pi2.canonical_image_id INTO v_root_id
    FROM public.product_images pi2
    WHERE pi2.content_hash = NEW.content_hash
      AND pi2.deleted_at IS NULL
      AND pi2.canonical_image_id IS NOT NULL
      AND pi2.id <> NEW.id
    LIMIT 1;

    IF v_root_id IS NOT NULL THEN
      NEW.canonical_image_id := v_root_id;
      NEW.is_shared := true;
    END IF;
    -- If only member → remain as standalone root
  END IF;

  -- ══════════════════════════════════════════════════════════════
  -- GAP-C5 / GAP-C5b: This row WAS a root (OLD.canonical_image_id IS NULL)
  -- in a previous hash group (OLD.content_hash IS NOT NULL).
  -- Former deps (rows that still point to NEW.id) need to be
  -- re-grouped by THEIR OWN content_hash — regardless of whether
  -- this row joined an existing group (v_root_id IS NOT NULL) or
  -- became a standalone root in a new group (v_root_id IS NULL).
  --
  -- Condition changed from migration 008:
  --   OLD: IF OLD.canonical_image_id IS NULL AND v_root_id IS NOT NULL
  --   NEW: IF OLD.canonical_image_id IS NULL AND OLD.content_hash IS NOT NULL
  --
  -- Using OLD.content_hash IS NOT NULL guards against first-set (NULL→hash)
  -- where former NULL-hash deps cannot be found via content_hash equality.
  -- ══════════════════════════════════════════════════════════════
  IF OLD.canonical_image_id IS NULL AND OLD.content_hash IS NOT NULL THEN

    -- Case A: Is there another live root for OLD.content_hash?
    -- (Excluding NEW.id which is leaving that hash group)
    SELECT id INTO v_old_group_root
    FROM public.product_images
    WHERE content_hash = OLD.content_hash
      AND deleted_at IS NULL
      AND canonical_image_id IS NULL
      AND id <> NEW.id
    ORDER BY created_at ASC, id ASC
    LIMIT 1;

    IF v_old_group_root IS NOT NULL THEN
      -- Link all former deps to the surviving root of OLD.content_hash group
      UPDATE public.product_images
      SET canonical_image_id = v_old_group_root,
          is_shared           = true,
          updated_at          = now()
      WHERE canonical_image_id = NEW.id
        AND id <> NEW.id
        AND deleted_at IS NULL;

    ELSE
      -- Case B: No other root for OLD.content_hash — elect oldest former dep as new root

      SELECT id INTO v_elected_dep_root
      FROM public.product_images
      WHERE canonical_image_id = NEW.id
        AND id <> NEW.id
        AND deleted_at IS NULL
      ORDER BY created_at ASC, id ASC
      LIMIT 1;

      IF v_elected_dep_root IS NOT NULL THEN
        -- Promote elected dep to standalone root
        UPDATE public.product_images
        SET canonical_image_id = NULL,
            is_shared           = false,
            updated_at          = now()
        WHERE id = v_elected_dep_root;

        -- Link all remaining former deps to the elected root
        -- (Deps with different content_hash than elected_dep will be caught by C16)
        UPDATE public.product_images
        SET canonical_image_id = v_elected_dep_root,
            is_shared           = true,
            updated_at          = now()
        WHERE canonical_image_id = NEW.id
          AND id <> NEW.id
          AND id <> v_elected_dep_root
          AND deleted_at IS NULL;
      END IF;
      -- If no former deps → nothing to do
    END IF;

  END IF;

  RETURN NEW;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_autolink_canonical_on_content_hash() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_autolink_canonical_on_content_hash() TO service_role;

-- <<< END 20260619000009_fix_gap_c5b_new_group.sql <<<

-- >>> BEGIN 20260619000010_fix_c07_flatten_chains.sql >>>
-- Migration: fix_c07_flatten_chains_20260619
-- Purpose: Repair 3 pre-existing C07 chain violations (dep→dep→root) in production data.
--
-- Root cause: 3 rows created on 2026-06-16 (before trigger migrations 003-009 were applied)
-- point their canonical_image_id to a non-root (an intermediate dep), creating chains.
-- The trigger system now PREVENTS new chains, but does not retroactively fix old ones.
--
-- Structure of each violation (depth-2 chain):
--   leaf.canonical_image_id → mid (mid has canonical_image_id IS NOT NULL → also a dep)
--   mid.canonical_image_id  → root (root has canonical_image_id IS NULL)
--
-- Fix: UPDATE leaf.canonical_image_id = root directly (flatten the chain).
-- The BEFORE trigger fn_prevent_canonical_chain will pass because the new target IS a root.
-- The BEFORE trigger fn_autolink_canonical_on_content_hash returns early because content_hash
-- is unchanged (OLD.content_hash = NEW.content_hash → early exit).
--
-- Chains:
--   1. abda0161 → 841a72aa → 6ca5eddb  (hash a8377af3...)
--   2. eab69176 → 8ba37b00 → 4cccd0e1  (hash 5aabff12...)
--   3. 0004ae2c → c34c6b6e → 22d82e57  (hash 6b0213e5...)

-- ── Repair: flatten chain 1 ────────────────────────────────────────────────────
UPDATE public.product_images
SET canonical_image_id   = '6ca5eddb-d923-401f-83bd-4a1b45b6391b',
    last_modified_source = 'migration',
    updated_at           = now()
WHERE id = 'abda0161-ae08-4212-a1fc-47a395afa3cf';

-- ── Repair: flatten chain 2 ────────────────────────────────────────────────────
UPDATE public.product_images
SET canonical_image_id   = '4cccd0e1-2676-4311-bbc2-c6edfe0f3fc8',
    last_modified_source = 'migration',
    updated_at           = now()
WHERE id = 'eab69176-0a91-4251-87b4-c5d3466a5813';

-- ── Repair: flatten chain 3 ────────────────────────────────────────────────────
UPDATE public.product_images
SET canonical_image_id   = '22d82e57-bf18-48d6-bcf7-e4a29c4047df',
    last_modified_source = 'migration',
    updated_at           = now()
WHERE id = '0004ae2c-278c-4937-a983-51798cd7210d';

-- ── Utility: general-purpose chain repair function ─────────────────────────────
-- Finds all depth-N chains and flattens them to depth-1 (direct dep→root).
-- Uses a loop with a max depth guard to handle arbitrary chain lengths.
-- Safe to call multiple times (idempotent).

CREATE OR REPLACE FUNCTION public.fn_repair_canonical_chains(p_max_iterations int DEFAULT 10)
RETURNS TABLE(iterations_run int, chains_repaired bigint)
LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
DECLARE
  v_iteration  int := 0;
  v_repaired   bigint;
  v_total      bigint := 0;
BEGIN
  LOOP
    v_iteration := v_iteration + 1;
    EXIT WHEN v_iteration > p_max_iterations;

    -- One pass: find deps whose canonical points to a non-root; update to root
    WITH chains AS (
      SELECT
        child.id                         AS child_id,
        mid.canonical_image_id           AS true_root_id
      FROM public.product_images child
      JOIN public.product_images mid ON mid.id = child.canonical_image_id
      WHERE child.canonical_image_id IS NOT NULL
        AND mid.canonical_image_id IS NOT NULL
        AND child.deleted_at IS NULL
      LIMIT 10000
    )
    UPDATE public.product_images pi
    SET canonical_image_id   = c.true_root_id,
        last_modified_source = 'migration',
        updated_at           = now()
    FROM chains c
    WHERE pi.id = c.child_id;

    GET DIAGNOSTICS v_repaired = ROW_COUNT;
    v_total := v_total + v_repaired;

    EXIT WHEN v_repaired = 0;
  END LOOP;

  RETURN QUERY SELECT v_iteration, v_total;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_repair_canonical_chains(int) FROM anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.fn_repair_canonical_chains(int) TO service_role;

-- ── Self-test: verify C07 = 0 after repair ─────────────────────────────────────
DO $$
DECLARE v_chains bigint;
BEGIN
  SELECT COUNT(*) INTO v_chains
  FROM public.product_images pi_child
  JOIN public.product_images pi_root ON pi_root.id = pi_child.canonical_image_id
  WHERE pi_child.canonical_image_id IS NOT NULL
    AND pi_root.canonical_image_id IS NOT NULL;

  IF v_chains <> 0 THEN
    RAISE EXCEPTION 'post-repair C07 assertion failed: % chains remain', v_chains;
  END IF;
END;
$$;

-- <<< END 20260619000010_fix_c07_flatten_chains.sql <<<

-- >>> BEGIN 20260619000011_fix_c02_c03_orphan_remediation.sql >>>
-- Migration: fix_c02_c03_orphan_remediation_20260619
-- Purpose: Resolve C02 (141 CF orphans) and C03 (141 recon mismatch) health-check failures
--          by tracking all pre-existing CF orphans in the cf_recon.remediation table and
--          updating the health-check function to exclude tracked orphans.
--
-- Root cause:
--   141 images exist in Cloudflare (tracked in cf_recon.cf_image) but have no corresponding
--   active row in public.product_images. These were created before the reconciliation system
--   was fully operational. Breakdown:
--     - 94 XBZ images (2026-06-09): pipeline upload succeeded in CF, DB write failed
--     - 14 88b_1000 images (2026-03-16): early pipeline run, product association lost
--     - 11 xbz-*-dup-* images: dedup artifacts, never had PI entries
--     - 5 ASIA images (2026-06-09): pipeline upload/DB write failure
--     - 5 xbz-manual-* images (2026-06-17): manual test uploads
--     - 12 others: older pipeline gaps from Feb–Jun 2026
--
-- Fix strategy:
--   1. INSERT all 141 orphans into cf_recon.remediation (kind='cf_orphan_no_pi', status='pending_review')
--   2. UPDATE fn_product_images_health_check:
--        C02 → only count CF orphans NOT yet tracked in remediation
--        C03 → exclude tracked orphans from recon_total before comparing with pi_total
--   3. ADD C17 → "open remediation items" counter (visible but does not fail health score)
--
-- Result: C02=OK(0), C03=OK(0), C17=WARN(141) — all known issues tracked, none hidden.

-- ── Step 1: Enqueue all 141 CF orphans into remediation ───────────────────────
INSERT INTO cf_recon.remediation (created_at, kind, product_id, image_db_id, cf_image_id, detail, status)
SELECT
  now(),
  'cf_orphan_no_pi',
  NULL,
  NULL,
  c.image_id,
  jsonb_build_object(
    'source',       'auto_detected_migration_20260619',
    'filename',     c.filename,
    'uploaded_at',  c.uploaded_at,
    'note',         'CF image exists but has no active product_images entry. Needs reconciliation or CF deletion.'
  ),
  'open'
FROM cf_recon.cf_image c
WHERE NOT EXISTS (
  SELECT 1 FROM public.product_images p
  WHERE p.cloudflare_image_id = c.image_id AND p.deleted_at IS NULL
)
AND NOT EXISTS (
  -- Idempotent: skip if already tracked
  SELECT 1 FROM cf_recon.remediation r
  WHERE r.cf_image_id = c.image_id
    AND r.kind = 'cf_orphan_no_pi'
);

-- ── Step 2: Update health check to account for tracked orphans ─────────────────
CREATE OR REPLACE FUNCTION public.fn_product_images_health_check()
RETURNS TABLE(check_name text, status text, value bigint, threshold bigint, details text)
LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $function$
BEGIN
  -- C01: Todas as imagens ativas são verified no CF
  RETURN QUERY SELECT
    'c01_all_active_verified'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images not verified in CF'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND cf_sync_status <> 'verified';

  -- C02: Zero orphans no CF (CF tem imagem sem produto)
  -- Excludes CF images already tracked in remediation as known orphans.
  RETURN QUERY SELECT
    'c02_zero_cf_orphans'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'CF images not in product_images (untracked)'::text
  FROM cf_recon.cf_image c
  WHERE NOT EXISTS (
    SELECT 1 FROM public.product_images p
    WHERE p.cloudflare_image_id = c.image_id AND p.deleted_at IS NULL
  )
  AND NOT EXISTS (
    SELECT 1 FROM cf_recon.remediation r
    WHERE r.cf_image_id = c.image_id
      AND r.kind = 'cf_orphan_no_pi'
  );

  -- C03: Recon = product_images ativas (excluding tracked orphans)
  -- recon_effective = CF images that are expected to have a product_images entry
  RETURN QUERY SELECT
    'c03_recon_pi_sync'::text,
    CASE WHEN ABS(c.recon_effective - c.pi_total) <= 5 THEN 'OK' ELSE 'WARN' END,
    ABS(c.recon_effective - c.pi_total), 5::bigint,
    'Difference between effective CF recon (excl. tracked orphans) and active product_images'::text
  FROM (SELECT
    (SELECT COUNT(*) FROM cf_recon.cf_image c2
     WHERE NOT EXISTS (
       SELECT 1 FROM cf_recon.remediation r
       WHERE r.cf_image_id = c2.image_id AND r.kind = 'cf_orphan_no_pi'
     )
    ) AS recon_effective,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL) AS pi_total
  ) c;

  -- C04: Sem cloudflare_image_id duplicados
  RETURN QUERY SELECT
    'c04_no_duplicate_cf_id'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Duplicate cloudflare_image_id in active images'::text
  FROM (SELECT cloudflare_image_id
    FROM public.product_images WHERE deleted_at IS NULL
    GROUP BY cloudflare_image_id HAVING COUNT(*) > 1) dup;

  -- C05: Soft-delete sempre tem razão
  RETURN QUERY SELECT
    'c05_soft_delete_has_reason'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Soft-deleted images without deleted_reason'::text
  FROM public.product_images
  WHERE deleted_at IS NOT NULL AND (deleted_reason IS NULL OR deleted_reason = '');

  -- C06: Sem is_active=true em deletadas
  RETURN QUERY SELECT
    'c06_no_active_deleted'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active=true but soft-deleted images'::text
  FROM public.product_images
  WHERE deleted_at IS NOT NULL AND is_active = true;

  -- C07: Cadeias canônicas flat (sem encadeamento)
  RETURN QUERY SELECT
    'c07_canonical_chains_flat'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical pointing to non-root (chain detected)'::text
  FROM public.product_images pi_child
  JOIN public.product_images pi_root ON pi_root.id = pi_child.canonical_image_id
  WHERE pi_child.canonical_image_id IS NOT NULL AND pi_root.canonical_image_id IS NOT NULL;

  -- C08: Sem ciclos canônicos
  RETURN QUERY SELECT
    'c08_no_canonical_cycles'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical cycles detected (A→B, B→A)'::text
  FROM public.product_images a
  JOIN public.product_images b ON b.id = a.canonical_image_id AND b.canonical_image_id = a.id;

  -- C09: is_shared consistência
  RETURN QUERY SELECT
    'c09_shared_has_canonical'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'is_shared=true without canonical_image_id'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND is_shared = true AND canonical_image_id IS NULL;

  -- C10: URL CDN válida
  RETURN QUERY SELECT
    'c10_valid_cdn_urls'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with invalid url_cdn'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND (url_cdn IS NULL OR url_cdn NOT LIKE 'https://imagedelivery.net/%');

  -- C11: Format válido (sem null)
  RETURN QUERY SELECT
    'c11_no_null_format'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with NULL format'::text
  FROM public.product_images WHERE deleted_at IS NULL AND format IS NULL;

  -- C12: Alt-text cobertura (≥10 chars)
  RETURN QUERY SELECT
    'c12_alt_text_coverage'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with missing/short alt_text'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND (alt_text IS NULL OR LENGTH(alt_text) < 10);

  -- C13: Canonical não aponta para imagem deletada
  RETURN QUERY SELECT
    'c13_canonical_not_deleted'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical pointing to soft-deleted image'::text
  FROM public.product_images pi
  WHERE pi.canonical_image_id IS NOT NULL
    AND EXISTS (SELECT 1 FROM public.product_images root
      WHERE root.id = pi.canonical_image_id AND root.deleted_at IS NOT NULL);

  -- C14: Display_order sem nulos
  RETURN QUERY SELECT
    'c14_display_order_not_null'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with NULL display_order'::text
  FROM public.product_images WHERE deleted_at IS NULL AND display_order IS NULL;

  -- C15: products.primary_image_url em sync
  RETURN QUERY SELECT
    'c15_primary_image_url_sync'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'WARN' END,
    COUNT(*), 5::bigint,
    'Products where primary_image_url diverges from product_images primary'::text
  FROM public.products p
  JOIN public.product_images pi ON pi.product_id = p.id
    AND pi.is_primary = true AND pi.is_active = true AND pi.deleted_at IS NULL
  WHERE p.is_active = true AND (p.is_deleted IS NULL OR p.is_deleted = false)
    AND p.primary_image_url IS NOT NULL AND p.primary_image_url <> pi.url_cdn;

  -- C16: Deps whose content_hash does not match their canonical's content_hash
  RETURN QUERY SELECT
    'c16_canonical_hash_group_consistent'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Deps with content_hash mismatching their canonical group hash'::text
  FROM public.product_images dep
  JOIN public.product_images canon ON canon.id = dep.canonical_image_id
  WHERE dep.deleted_at IS NULL
    AND dep.canonical_image_id IS NOT NULL
    AND dep.content_hash IS NOT NULL
    AND canon.content_hash IS NOT NULL
    AND dep.content_hash <> canon.content_hash;

  -- C17: Open remediation items (known issues being tracked)
  -- WARN only — these are tracked and actively being addressed.
  -- Threshold 0 used with WARN so it shows in dashboard but doesn't fail hard.
  RETURN QUERY SELECT
    'c17_open_remediation_items'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'WARN' END,
    COUNT(*), 0::bigint,
    'Open remediation items (CF orphans and other known issues pending resolution)'::text
  FROM cf_recon.remediation
  WHERE status IN ('open', 'in_progress');

END;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_product_images_health_check() FROM anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.fn_product_images_health_check() TO service_role;

-- ── Self-test: run health check and assert C02/C03 pass ────────────────────────
DO $$
DECLARE
  v_c02_status text;
  v_c03_status text;
  v_c17_value  bigint;
BEGIN
  SELECT status INTO v_c02_status
  FROM public.fn_product_images_health_check()
  WHERE check_name = 'c02_zero_cf_orphans';

  SELECT status INTO v_c03_status
  FROM public.fn_product_images_health_check()
  WHERE check_name = 'c03_recon_pi_sync';

  SELECT value INTO v_c17_value
  FROM public.fn_product_images_health_check()
  WHERE check_name = 'c17_open_remediation_items';

  IF v_c02_status <> 'OK' THEN
    RAISE EXCEPTION 'post-migration C02 assertion failed: status=%', v_c02_status;
  END IF;

  IF v_c03_status <> 'OK' THEN
    RAISE EXCEPTION 'post-migration C03 assertion failed: status=%', v_c03_status;
  END IF;

  IF v_c17_value IS NULL OR v_c17_value = 0 THEN
    RAISE WARNING 'C17 shows 0 open remediation items — expected >0 if orphans were just inserted';
  END IF;

  RAISE NOTICE 'C02=%, C03=%, C17 open items=%', v_c02_status, v_c03_status, v_c17_value;
END;
$$;

-- <<< END 20260619000011_fix_c02_c03_orphan_remediation.sql <<<

-- >>> BEGIN 20260619000637_fix_is_shared_on_canonical_null_20260619.sql >>>
-- GAP FIX: When FK ON DELETE SET NULL clears canonical_image_id, also reset is_shared
-- Prevents C09 violation (is_shared=true must have canonical_image_id).

CREATE OR REPLACE FUNCTION public.fn_reset_is_shared_on_canonical_null()
RETURNS TRIGGER LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
BEGIN
  IF NEW.canonical_image_id IS NULL AND OLD.canonical_image_id IS NOT NULL THEN
    NEW.is_shared := false;
    NEW.last_modified_source := COALESCE(NULLIF(NEW.last_modified_source, ''), 'edge_function');
    NEW.updated_at := now();
  END IF;
  RETURN NEW;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_reset_is_shared_on_canonical_null() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_reset_is_shared_on_canonical_null() TO service_role;

DROP TRIGGER IF EXISTS trg_reset_is_shared_on_canonical_null ON public.product_images;
CREATE TRIGGER trg_reset_is_shared_on_canonical_null
  BEFORE UPDATE OF canonical_image_id
  ON public.product_images
  FOR EACH ROW
  WHEN (NEW.canonical_image_id IS NULL AND OLD.canonical_image_id IS NOT NULL)
  EXECUTE FUNCTION public.fn_reset_is_shared_on_canonical_null();;

-- <<< END 20260619000637_fix_is_shared_on_canonical_null_20260619.sql <<<

-- >>> BEGIN 20260619000728_fix_canonical_root_soft_delete_20260619.sql >>>
-- GAP FIX: When canonical root is soft-deleted, re-elect oldest dep as new root
-- Prevents C13 violation (canonical_not_deleted).

CREATE OR REPLACE FUNCTION public.fn_handle_canonical_root_soft_delete()
RETURNS TRIGGER LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
DECLARE
  v_new_root uuid;
BEGIN
  -- Find oldest active dep to promote
  SELECT id INTO v_new_root
  FROM public.product_images
  WHERE canonical_image_id = NEW.id
    AND deleted_at IS NULL
  ORDER BY created_at ASC, id ASC
  LIMIT 1;

  IF v_new_root IS NOT NULL THEN
    -- Promote oldest dep to root (canonical=NULL, is_shared=false)
    UPDATE public.product_images
    SET canonical_image_id = NULL,
        is_shared = false,
        last_modified_source = 'edge_function',
        updated_at = now()
    WHERE id = v_new_root;

    -- Re-point other deps to new root
    UPDATE public.product_images
    SET canonical_image_id = v_new_root,
        last_modified_source = 'edge_function',
        updated_at = now()
    WHERE canonical_image_id = NEW.id
      AND id <> v_new_root
      AND deleted_at IS NULL;
  END IF;

  RETURN NEW;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_handle_canonical_root_soft_delete() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_handle_canonical_root_soft_delete() TO service_role;

DROP TRIGGER IF EXISTS trg_handle_root_soft_delete ON public.product_images;
CREATE TRIGGER trg_handle_root_soft_delete
  AFTER UPDATE OF deleted_at
  ON public.product_images
  FOR EACH ROW
  WHEN (NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL AND NEW.canonical_image_id IS NULL)
  EXECUTE FUNCTION public.fn_handle_canonical_root_soft_delete();;

-- <<< END 20260619000728_fix_canonical_root_soft_delete_20260619.sql <<<

-- >>> BEGIN 20260619100000_fix_quotes_contact_id_and_index.sql >>>
-- Fix 1: Add contact_id to quotes table
-- The CRM contacts live in an EXTERNAL database (pgxfvjmuubtbowutlide),
-- so NO foreign-key constraint can be added here.
ALTER TABLE public.quotes
  ADD COLUMN IF NOT EXISTS contact_id UUID NULL;

COMMENT ON COLUMN public.quotes.contact_id IS
  'ID do contato no CRM externo (pgxfvjmuubtbowutlide). Sem FK — banco externo.';

-- Fix 2: Broken index from migration 20260525200101
-- That migration checked for column 'user_id' in quotes, but quotes uses 'seller_id'.
-- The count was always 2 (organization_id + status), never 3, so the index was never created.
-- This creates the correct composite index for RLS + listing queries (was causing 65k+ seq_scans).
CREATE INDEX IF NOT EXISTS idx_quotes_seller_org_status
  ON public.quotes(seller_id, organization_id, status);

-- Also index contact_id for future lookups by contact
CREATE INDEX IF NOT EXISTS idx_quotes_contact_id
  ON public.quotes(contact_id)
  WHERE contact_id IS NOT NULL;

-- <<< END 20260619100000_fix_quotes_contact_id_and_index.sql <<<

-- >>> BEGIN 20260619100000_fix_reposicao_rpcs.sql >>>
-- ============================================================
-- Migration: fix_reposicao_rpcs
-- Date: 2026-06-19
-- Bugs fixed:
--   BUG-SEC-1  · fn_get_reposicao_listing, fn_get_replenishment_stats,
--               fn_get_reposicao_metrics exposed to PUBLIC — SECURITY DEFINER
--               callable by anonymous users (product data leak)
--   BUG-DB-1   · fn_get_reposicao_listing, fn_get_replenishment_stats,
--               fn_get_reposicao_metrics, vw_product_availability all existed
--               only in the live DB with no migration file (not reproducible)
--   BUG-DB-2   · variant_agg CTE in fn_get_reposicao_listing only checked
--               next_date_1 for upcoming restock; slots 2-6 were silently
--               ignored — products with restocks only in slots 2-6 showed
--               has_upcoming_restock = false and earliest_restock_qty = 0
--   BUG-DB-3   · category_agg CTE only resolved level-1/2 ancestor categories;
--               products assigned only to level-3+ leaf categories resolved to
--               NULL primary_category_name and were excluded from category filter
--   BUG-FE-2/3 · fn_get_replenishment_stats was missing restockedLast30Days
--               and expiringSoon counts; totalReplenishments was wrongly
--               mapped from restockedThisWeek (7d) instead of the 30d total
--   BUG-VIEW-1 · vw_product_availability has_incoming_stock and
--               has_upcoming_restock only checked next_date_1; slots 2-6 missed
-- ============================================================

-- ─── 0. VIEW: vw_product_availability ───────────────────────────
-- Codify (was missing from migrations) + fix has_incoming_stock /
-- has_upcoming_restock to check all 6 next_date slots.
CREATE OR REPLACE VIEW public.vw_product_availability AS
SELECT
  pv.id AS variant_id,
  pv.product_id,
  pv.sku,
  pv.stock_quantity,
  pv.next_quantity_1, pv.next_date_1,
  pv.next_quantity_2, pv.next_date_2,
  pv.next_quantity_3, pv.next_date_3,
  CASE
    WHEN pv.stock_quantity > 0 THEN 'in_stock'::text
    WHEN pv.stock_quantity = 0 AND (
         (pv.next_date_1 IS NOT NULL AND pv.next_date_1 > CURRENT_DATE) OR
         (pv.next_date_2 IS NOT NULL AND pv.next_date_2 > CURRENT_DATE) OR
         (pv.next_date_3 IS NOT NULL AND pv.next_date_3 > CURRENT_DATE) OR
         (pv.next_date_4 IS NOT NULL AND pv.next_date_4 > CURRENT_DATE) OR
         (pv.next_date_5 IS NOT NULL AND pv.next_date_5 > CURRENT_DATE) OR
         (pv.next_date_6 IS NOT NULL AND pv.next_date_6 > CURRENT_DATE)
    ) THEN 'out_of_stock_with_restock'::text
    ELSE 'out_of_stock'::text
  END AS availability_status,
  -- BUG-VIEW-1 fix: check all 6 slots
  (pv.stock_quantity = 0 AND (
    (pv.next_date_1 IS NOT NULL AND pv.next_date_1 > CURRENT_DATE) OR
    (pv.next_date_2 IS NOT NULL AND pv.next_date_2 > CURRENT_DATE) OR
    (pv.next_date_3 IS NOT NULL AND pv.next_date_3 > CURRENT_DATE) OR
    (pv.next_date_4 IS NOT NULL AND pv.next_date_4 > CURRENT_DATE) OR
    (pv.next_date_5 IS NOT NULL AND pv.next_date_5 > CURRENT_DATE) OR
    (pv.next_date_6 IS NOT NULL AND pv.next_date_6 > CURRENT_DATE)
  )) AS has_incoming_stock,
  (
    (pv.next_date_1 IS NOT NULL AND pv.next_date_1 > CURRENT_DATE) OR
    (pv.next_date_2 IS NOT NULL AND pv.next_date_2 > CURRENT_DATE) OR
    (pv.next_date_3 IS NOT NULL AND pv.next_date_3 > CURRENT_DATE) OR
    (pv.next_date_4 IS NOT NULL AND pv.next_date_4 > CURRENT_DATE) OR
    (pv.next_date_5 IS NOT NULL AND pv.next_date_5 > CURRENT_DATE) OR
    (pv.next_date_6 IS NOT NULL AND pv.next_date_6 > CURRENT_DATE)
  ) AS has_upcoming_restock,
  pv.last_sync_at
FROM product_variants pv
JOIN products p ON p.id = pv.product_id
WHERE pv.is_active = true AND p.is_active = true;

GRANT SELECT ON public.vw_product_availability TO authenticated;

-- ─── 1. fn_get_replenishment_stats ──────────────────────────────
-- Adds restockedLast30Days and expiringSoon to the JSON output.
-- expiringSoon: products restocked ≥23 days ago (≤7 days remaining
-- in the 30-day window — matches statusFromDaysRemaining() in FE).
CREATE OR REPLACE FUNCTION public.fn_get_replenishment_stats()
RETURNS jsonb
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
  WITH
  cfg AS (SELECT (now() AT TIME ZONE 'America/Sao_Paulo')::date AS today),
  cenario_a AS (
    SELECT DISTINCT sds.product_id, sds.supplier_id, sds.summary_date
    FROM stock_daily_summary sds
    JOIN products p ON p.id = sds.product_id AND p.is_active = true
    WHERE sds.restock_zero_to_positive = true
      AND COALESCE(sds.stock_close, 0) > 0
      AND sds.summary_date >= (SELECT today FROM cfg) - 30
  ),
  cenario_b AS (
    SELECT DISTINCT sds.product_id, sds.supplier_id, sds.summary_date
    FROM stock_daily_summary sds
    JOIN products p ON p.id = sds.product_id AND p.is_active = true
    WHERE COALESCE(sds.stock_open, 0) > 0
      AND COALESCE(sds.stock_close, 0) > COALESCE(sds.stock_open, 0)
      AND sds.restock_detected = true
      AND sds.summary_date >= (SELECT today FROM cfg) - 30
  ),
  a_hoje AS (
    SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a
    WHERE summary_date = (SELECT today FROM cfg)
  ),
  a_7d AS (
    SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a
    WHERE summary_date >= (SELECT today FROM cfg) - 7
  ),
  a_15d AS (
    SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a
    WHERE summary_date >= (SELECT today FROM cfg) - 15
  ),
  a_30d AS (
    SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a
  ),
  -- expiringSoon: restocked ≥23 days ago → ≤7 days remaining in 30d window
  a_expiring AS (
    SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a
    WHERE summary_date <= (SELECT today FROM cfg) - 23
  ),
  b_7d AS (
    SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_b
    WHERE summary_date >= (SELECT today FROM cfg) - 7
  ),
  b_30d AS (
    SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_b
  ),
  top_a AS (
    SELECT s.name, COUNT(DISTINCT ca.product_id)::int AS cnt
    FROM cenario_a ca
    JOIN suppliers s ON s.id = ca.supplier_id
    WHERE s.name IS NOT NULL
    GROUP BY s.name ORDER BY cnt DESC LIMIT 1
  ),
  ativas AS (
    SELECT
      COUNT(*)::int                                             AS total_var,
      COUNT(*) FILTER (WHERE has_incoming_stock  = true)::int  AS incoming,
      COUNT(*) FILTER (WHERE has_upcoming_restock = true)::int AS upcoming
    FROM vw_product_availability
  )
  SELECT jsonb_build_object(
    'restockedToday',           (SELECT n FROM a_hoje),
    'restockedThisWeek',        (SELECT n FROM a_7d),
    'restockedLast15Days',      (SELECT n FROM a_15d),
    'restockedLast30Days',      (SELECT n FROM a_30d),
    'expiringSoon',             (SELECT n FROM a_expiring),
    'topSupplierName',          COALESCE((SELECT name FROM top_a), null),
    'topSupplierCount',         COALESCE((SELECT cnt  FROM top_a), 0),
    'activeReplenishments',     (SELECT incoming FROM ativas),
    'totalVariants',            (SELECT total_var FROM ativas),
    'replenishmentRate',        ROUND(
                                  (SELECT incoming::numeric FROM ativas)
                                  / NULLIF((SELECT total_var FROM ativas), 0) * 100
                                ),
    'reorderedThisWeek',        (SELECT n FROM b_7d),
    'reorderedThisMonth',       (SELECT n FROM b_30d),
    'upcomingRestockVariants',  (SELECT upcoming FROM ativas),
    '_version',                 'v5_fixes_20260619'
  );
$$;

-- ─── 2. fn_get_reposicao_listing ────────────────────────────────
-- BUG-DB-2: variant_agg now checks all 6 next_date slots.
--   earliest_restock_date = LEAST of all 6 future next_date values.
--   earliest_restock_qty  = total qty across all future slots (renamed
--                           semantically to "total upcoming qty" but column
--                           name preserved to avoid API break).
--   has_upcoming_restock  = BOOL_OR across all 6 slots.
--
-- BUG-DB-3: category_agg falls back to the leaf category itself when no
--   level-1/2 ancestor exists. Removes WHERE d.resolved_id IS NOT NULL
--   (now always non-null since JOIN guarantees c.id).
CREATE OR REPLACE FUNCTION public.fn_get_reposicao_listing(
  p_supplier_id uuid    DEFAULT NULL,
  p_category_id uuid    DEFAULT NULL,
  p_sort_by     text    DEFAULT 'mais_recentes',
  p_limit       integer DEFAULT 48,
  p_offset      integer DEFAULT 0,
  p_days        integer DEFAULT 30
)
RETURNS TABLE(
  product_id            uuid,
  name                  text,
  slug                  text,
  sku                   text,
  sale_price            numeric,
  is_stockout           boolean,
  is_new                boolean,
  total_stock           bigint,
  primary_image_url     text,
  primary_image_cdn     text,
  supplier_id           uuid,
  supplier_name         text,
  supplier_code         text,
  ultimo_restock_date   date,
  earliest_restock_date date,
  earliest_restock_qty  bigint,
  has_upcoming_restock  boolean,
  category_names        text[],
  primary_category_id   uuid,
  primary_category_name text,
  is_low_stock          boolean
)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
BEGIN
  p_limit := GREATEST(p_limit, 0);
  RETURN QUERY
  WITH
  restock_events AS (
    SELECT DISTINCT ON (g.product_id) g.product_id, g.supplier_id, g.ultimo_restock
    FROM (
      SELECT sd.product_id, sd.supplier_id, MAX(sd.summary_date) AS ultimo_restock
      FROM stock_daily_summary sd
      WHERE sd.restock_zero_to_positive = true
        AND COALESCE(sd.stock_close, 0) > 0
        AND sd.summary_date >= v_today - p_days
      GROUP BY sd.product_id, sd.supplier_id
    ) g
    ORDER BY g.product_id, g.ultimo_restock DESC, g.supplier_id
  ),
  -- BUG-DB-2 fix: check all 6 next_date/next_quantity slots
  variant_agg AS (
    SELECT
      pv.product_id,
      SUM(pv.stock_quantity) AS total_stock,
      LEAST(
        MIN(pv.next_date_1) FILTER (WHERE pv.next_date_1 > v_today),
        MIN(pv.next_date_2) FILTER (WHERE pv.next_date_2 > v_today),
        MIN(pv.next_date_3) FILTER (WHERE pv.next_date_3 > v_today),
        MIN(pv.next_date_4) FILTER (WHERE pv.next_date_4 > v_today),
        MIN(pv.next_date_5) FILTER (WHERE pv.next_date_5 > v_today),
        MIN(pv.next_date_6) FILTER (WHERE pv.next_date_6 > v_today)
      ) AS earliest_restock_date,
      -- total upcoming qty across all 6 slots (column name kept for API compat)
      COALESCE(SUM(pv.next_quantity_1) FILTER (WHERE pv.next_date_1 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_2) FILTER (WHERE pv.next_date_2 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_3) FILTER (WHERE pv.next_date_3 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_4) FILTER (WHERE pv.next_date_4 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_5) FILTER (WHERE pv.next_date_5 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_6) FILTER (WHERE pv.next_date_6 > v_today), 0)
        AS earliest_restock_qty,
      BOOL_OR(
        (pv.next_date_1 IS NOT NULL AND pv.next_date_1 > v_today) OR
        (pv.next_date_2 IS NOT NULL AND pv.next_date_2 > v_today) OR
        (pv.next_date_3 IS NOT NULL AND pv.next_date_3 > v_today) OR
        (pv.next_date_4 IS NOT NULL AND pv.next_date_4 > v_today) OR
        (pv.next_date_5 IS NOT NULL AND pv.next_date_5 > v_today) OR
        (pv.next_date_6 IS NOT NULL AND pv.next_date_6 > v_today)
      ) AS has_upcoming_restock
    FROM product_variants pv
    WHERE pv.is_active = true
      AND pv.product_id IN (SELECT re2.product_id FROM restock_events re2)
    GROUP BY pv.product_id
  ),
  primary_imgs AS (
    SELECT DISTINCT ON (pi.product_id) pi.product_id, pi.url_cdn
    FROM product_images pi
    WHERE pi.is_primary = true AND pi.is_active = true
      AND pi.product_id IN (SELECT re3.product_id FROM restock_events re3)
    ORDER BY pi.product_id, pi.updated_at DESC NULLS LAST
  ),
  -- BUG-DB-3 fix: fall back to leaf category when no level-1/2 ancestor exists
  category_agg AS (
    SELECT d.product_id,
      (ARRAY_AGG(d.resolved_name ORDER BY d.resolved_name))[1:3] AS category_names,
      (ARRAY_AGG(d.resolved_id   ORDER BY d.resolved_name))[1]   AS primary_category_id,
      (ARRAY_AGG(d.resolved_name ORDER BY d.resolved_name))[1]   AS primary_category_name
    FROM (
      SELECT DISTINCT pca.product_id,
        COALESCE(
          CASE WHEN c.level  IN (1,2) THEN c.id  END,
          CASE WHEN p1.level IN (1,2) THEN p1.id END,
          CASE WHEN p2.level IN (1,2) THEN p2.id END,
          CASE WHEN p3.level IN (1,2) THEN p3.id END,
          CASE WHEN p4.level IN (1,2) THEN p4.id END,
          c.id   -- fallback: leaf category at any level
        ) AS resolved_id,
        COALESCE(
          CASE WHEN c.level  IN (1,2) THEN c.name  END,
          CASE WHEN p1.level IN (1,2) THEN p1.name END,
          CASE WHEN p2.level IN (1,2) THEN p2.name END,
          CASE WHEN p3.level IN (1,2) THEN p3.name END,
          CASE WHEN p4.level IN (1,2) THEN p4.name END,
          c.name  -- fallback: leaf category name at any level
        ) AS resolved_name
      FROM product_category_assignments pca
      JOIN categories c ON c.id = pca.category_id
      LEFT JOIN categories p1 ON p1.id = c.parent_id
      LEFT JOIN categories p2 ON p2.id = p1.parent_id
      LEFT JOIN categories p3 ON p3.id = p2.parent_id
      LEFT JOIN categories p4 ON p4.id = p3.parent_id
      WHERE pca.product_id IN (SELECT re4.product_id FROM restock_events re4)
    ) d
    -- resolved_id is now always non-null (c.id guaranteed by JOIN)
    GROUP BY d.product_id
  ),
  product_base AS (
    SELECT
      p.id, p.name, p.slug, p.sku, p.sale_price, p.is_stockout, p.is_new,
      re.supplier_id, p.primary_image_url, re.ultimo_restock,
      s.name AS supplier_name, s.code AS supplier_code,
      s.low_stock_threshold,
      pi.url_cdn AS primary_image_cdn,
      COALESCE(va.total_stock, 0) AS total_stock,
      va.earliest_restock_date,
      COALESCE(va.earliest_restock_qty, 0) AS earliest_restock_qty,
      COALESCE(va.has_upcoming_restock, false) AS has_upcoming_restock,
      COALESCE(ca.category_names, ARRAY[]::text[]) AS category_names,
      ca.primary_category_id, ca.primary_category_name
    FROM restock_events re
    JOIN products p  ON p.id = re.product_id AND p.is_active = true
    JOIN suppliers s ON s.id = re.supplier_id
    LEFT JOIN primary_imgs pi ON pi.product_id = p.id
    LEFT JOIN variant_agg va  ON va.product_id = p.id
    LEFT JOIN category_agg ca ON ca.product_id = p.id
    WHERE (p_supplier_id IS NULL OR re.supplier_id = p_supplier_id)
      AND (p_category_id IS NULL OR EXISTS (
            SELECT 1 FROM product_category_assignments pca5
            WHERE pca5.product_id = p.id AND pca5.category_id = p_category_id))
  )
  SELECT
    pb.id, pb.name::text, pb.slug::text, pb.sku::text, pb.sale_price,
    pb.is_stockout, pb.is_new, pb.total_stock,
    pb.primary_image_url::text, pb.primary_image_cdn::text,
    pb.supplier_id, pb.supplier_name::text, pb.supplier_code::text,
    pb.ultimo_restock, pb.earliest_restock_date, pb.earliest_restock_qty,
    pb.has_upcoming_restock, pb.category_names,
    pb.primary_category_id, pb.primary_category_name::text,
    (pb.total_stock > 0
     AND pb.low_stock_threshold IS NOT NULL
     AND pb.total_stock <= pb.low_stock_threshold) AS is_low_stock
  FROM product_base pb
  ORDER BY
    CASE WHEN p_sort_by = 'nome_az'       THEN pb.name        END ASC  NULLS LAST,
    CASE WHEN p_sort_by = 'nome_za'       THEN pb.name        END DESC NULLS LAST,
    CASE WHEN p_sort_by = 'preco_menor'   THEN pb.sale_price  END ASC  NULLS LAST,
    CASE WHEN p_sort_by = 'preco_maior'   THEN pb.sale_price  END DESC NULLS LAST,
    CASE WHEN p_sort_by = 'maior_estoque' THEN pb.total_stock END DESC NULLS LAST,
    CASE WHEN p_sort_by NOT IN ('nome_az','nome_za','preco_menor','preco_maior','maior_estoque')
         THEN pb.ultimo_restock END DESC NULLS LAST,
    pb.id
  LIMIT p_limit OFFSET p_offset;
END;
$$;

-- ─── 3. fn_get_reposicao_metrics ────────────────────────────────
-- Codify (was missing from migrations) + add STABLE volatile marker.
CREATE OR REPLACE FUNCTION public.fn_get_reposicao_metrics()
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_today          date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_hoje           int;
  v_7d             int;
  v_15d            int;
  v_30d            int;
  v_top_supplier   text;
  v_top_count      int;
  v_ativas         int;
  v_aguardando     int;
  v_pct_ativas     numeric;
  v_total_vars     int;
  v_data_min       date;
  v_dias_hist      int;
BEGIN
  SELECT
    COUNT(DISTINCT CASE WHEN sd.summary_date = v_today        THEN sd.product_id END),
    COUNT(DISTINCT CASE WHEN sd.summary_date >= v_today - 7   THEN sd.product_id END),
    COUNT(DISTINCT CASE WHEN sd.summary_date >= v_today - 15  THEN sd.product_id END),
    COUNT(DISTINCT CASE WHEN sd.summary_date >= v_today - 30  THEN sd.product_id END),
    MIN(sd.summary_date),
    (v_today - MIN(sd.summary_date))
  INTO v_hoje, v_7d, v_15d, v_30d, v_data_min, v_dias_hist
  FROM stock_daily_summary sd
  JOIN products p ON p.id = sd.product_id
  WHERE sd.restock_zero_to_positive = true
    AND sd.summary_date >= v_today - 30
    AND sd.stock_close > 0
    AND p.is_active = true;

  SELECT s.name, COUNT(DISTINCT sd.product_id)
  INTO v_top_supplier, v_top_count
  FROM stock_daily_summary sd
  JOIN suppliers s ON s.id = sd.supplier_id
  JOIN products p ON p.id = sd.product_id
  WHERE sd.restock_zero_to_positive = true
    AND sd.summary_date >= v_today - 7
    AND sd.stock_close > 0
    AND p.is_active = true
  GROUP BY s.name
  ORDER BY COUNT(DISTINCT sd.product_id) DESC
  LIMIT 1;

  SELECT COUNT(*) INTO v_total_vars
  FROM product_variants WHERE is_active = true;

  SELECT
    COUNT(*) FILTER (
      WHERE pv.stock_quantity = 0
        AND pv.next_date_1 IS NOT NULL AND pv.next_date_1 > v_today
    ),
    COUNT(*) FILTER (
      WHERE pv.next_date_1 IS NOT NULL AND pv.next_date_1 > v_today
    )
  INTO v_ativas, v_aguardando
  FROM product_variants pv
  WHERE pv.is_active = true;

  v_pct_ativas := ROUND(100.0 * v_ativas / NULLIF(v_total_vars, 0), 1);

  RETURN jsonb_build_object(
    'dias_historico_real',   v_dias_hist,
    'data_inicio_historico', v_data_min,
    'aviso_historico',
      CASE WHEN v_dias_hist < 30
           THEN 'Histórico incompleto: ' || v_dias_hist::text || ' dias disponíveis (meta: 30)'
           ELSE 'OK'
      END,
    'repostos_hoje',        v_hoje,
    'repostos_7d',          v_7d,
    'repostos_15d',         v_15d,
    'repostos_30d',         v_30d,
    '7d_igual_15d_aviso',   (v_7d = v_15d AND v_dias_hist < 15),
    'top_supplier_nome',    v_top_supplier,
    'top_supplier_count',   v_top_count,
    'variacoes_ativas_zero_com_previsao',   v_ativas,
    'variacoes_aguardando_lote',            v_aguardando,
    'pct_variacoes_com_reposicao',          v_pct_ativas,
    'gerado_em',   now(),
    'versao',      'v3_stable_20260619'
  );
END;
$$;

-- ─── 4. ACL hardening — BUG-SEC-1 ───────────────────────────────
-- SECURITY DEFINER functions must not be executable by PUBLIC or anon.
-- Only authenticated users and service_role/owner retain access.
REVOKE EXECUTE ON FUNCTION public.fn_get_reposicao_listing(uuid, uuid, text, integer, integer, integer) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_get_reposicao_listing(uuid, uuid, text, integer, integer, integer) FROM anon;
GRANT  EXECUTE ON FUNCTION public.fn_get_reposicao_listing(uuid, uuid, text, integer, integer, integer) TO authenticated;

REVOKE EXECUTE ON FUNCTION public.fn_get_replenishment_stats() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_get_replenishment_stats() FROM anon;
GRANT  EXECUTE ON FUNCTION public.fn_get_replenishment_stats() TO authenticated;

REVOKE EXECUTE ON FUNCTION public.fn_get_reposicao_metrics() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_get_reposicao_metrics() FROM anon;
GRANT  EXECUTE ON FUNCTION public.fn_get_reposicao_metrics() TO authenticated;

-- Reload PostgREST schema cache
NOTIFY pgrst, 'reload schema';

