-- >>> BEGIN 20260619100001_fix_fn_set_product_as_new_update.sql >>>
-- Fix: fn_set_product_as_new — adiciona tratamento de UPDATE para is_new false→true
--
-- Problema (auditoria Novidades 2026-06-19):
-- O trigger trg_set_product_as_new disparava apenas em INSERT. Quando um produto
-- era re-ingerido ou atualizado manualmente com is_new = true (ex: via webhook
-- product-webhook, que só escreve is_new sem tocar as datas), o trigger NÃO
-- preenchia novelty_detected_at / novelty_expires_at — os campos ficavam NULL,
-- fazendo o produto desaparecer do predicado `novelty_expires_at > now()`.
--
-- Correção:
-- 1. Altera o trigger para disparar em INSERT e UPDATE
-- 2. Na transição false→true (UPDATE) com campos nulos ou já expirados, preenche
--    novelty_detected_at = NOW() e novelty_expires_at = NOW() + 30 dias
-- 3. Preserva valores existentes quando a expiração ainda é futura (idempotente)

-- ─── Passo 1: substituir a função ───────────────────────────────────────────
CREATE OR REPLACE FUNCTION fn_set_product_as_new()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  -- Só age quando is_new é TRUE no registro final
  IF NEW.is_new IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  -- INSERT: preenche sempre (produto novo)
  IF TG_OP = 'INSERT' THEN
    IF NEW.novelty_detected_at IS NULL THEN
      NEW.novelty_detected_at := NOW();
    END IF;
    IF NEW.novelty_expires_at IS NULL THEN
      NEW.novelty_expires_at := NEW.novelty_detected_at + INTERVAL '30 days';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE: transição false→true OU reativação de flag já expirado
  IF TG_OP = 'UPDATE' THEN
    DECLARE
      was_new BOOLEAN := COALESCE(OLD.is_new, FALSE);
      already_active BOOLEAN := (
        NEW.novelty_expires_at IS NOT NULL AND
        NEW.novelty_expires_at > NOW()
      );
    BEGIN
      -- Se is_new estava FALSE e virou TRUE (ou expiração nula/expirada): reinicia
      IF (was_new = FALSE OR NOT already_active) THEN
        NEW.novelty_detected_at := NOW();
        NEW.novelty_expires_at  := NOW() + INTERVAL '30 days';
      END IF;
      -- Caso contrário (is_new=true antes E expiração ainda futura): não toca
      RETURN NEW;
    END;
  END IF;

  RETURN NEW;
END;
$$;

-- ─── Passo 2: recriar o trigger incluindo UPDATE ─────────────────────────────
DROP TRIGGER IF EXISTS trg_set_product_as_new ON products;

CREATE TRIGGER trg_set_product_as_new
  BEFORE INSERT OR UPDATE OF is_new
  ON products
  FOR EACH ROW
  EXECUTE FUNCTION fn_set_product_as_new();

COMMENT ON FUNCTION fn_set_product_as_new() IS
  'Preenche novelty_detected_at e novelty_expires_at quando is_new=true é definido/reativado. '
  'Dispara em INSERT e UPDATE(is_new). '
  'Idempotente: preserva expiração futura existente.';

-- <<< END 20260619100001_fix_fn_set_product_as_new_update.sql <<<

-- >>> BEGIN 20260619100002_idx_products_novelty_covering.sql >>>
-- Performance: índice cobrindo para queries de novidades com novelty_expires_at
--
-- Problema (auditoria Novidades 2026-06-19):
-- O índice idx_products_new_sort existente cobre (novelty_detected_at DESC, id ASC)
-- com WHERE is_new = true, mas não inclui novelty_expires_at na condição nem nas
-- colunas cobertas. A query do hook useNoveltiesWithDetails filtra por
-- `novelty_expires_at > NOW()`, forçando uma verificação de heap para cada linha
-- encontrada pelo índice — O(n) heap fetches onde n = total de is_new = true.
--
-- Correção:
-- Cria índice parcial que inclui novelty_expires_at na predicado e nas colunas
-- para eliminar heap fetches no filtro de expiração, tornando a query index-only.

-- Remove versão anterior se existir (evita conflito de nome)
DROP INDEX IF EXISTS idx_products_new_active_sort;

CREATE INDEX idx_products_new_active_sort
  ON products (novelty_detected_at DESC, id ASC)
  INCLUDE (novelty_expires_at, sale_price, stock_quantity, is_stockout, primary_image_url, category_id, supplier_id)
  WHERE is_new = true;

COMMENT ON INDEX idx_products_new_active_sort IS
  'Índice cobrindo para queries de novidades ativas. '
  'Predicate: is_new=true. Include: colunas lidas por useNoveltiesWithDetails. '
  'Evita heap fetch para filtro novelty_expires_at > NOW() e filtros de qualidade.';

-- <<< END 20260619100002_idx_products_novelty_covering.sql <<<

-- >>> BEGIN 20260619103311_expand_security_definer_acl_whitelist_20260619.sql >>>
-- ============================================================================
-- MIGRATION: expand_security_definer_acl_whitelist_20260619
-- Expande a whitelist de public_intent em audit_security_definer_acl()
-- para refletir as funções intencionalmente acessíveis via anon/PUBLIC.
--
-- Contexto: após REVOKE em massa (83 funções), restaram 51 "violações" que
-- são todas intencionais — pipeline VPS/n8n (anon key), catálogo público,
-- AI enrichment, MCP KV. Este gate foi atualizado para reconhecê-las.
--
-- Categorias adicionadas à whitelist:
--   anon_pipeline  → VPS/n8n chamam via anon key (sem sessão de usuário)
--   anon_catalog   → catálogo público (usuários não-logados)
--   anon_edge      → edge functions que usam anon key
--   anon_mcp       → MCP server usa anon key
--   public_catalog → catálogo requer PUBLIC (PostgREST não-autenticado)
-- ============================================================================

CREATE OR REPLACE FUNCTION public.audit_security_definer_acl()
RETURNS TABLE(function_name text, arguments text, problem text, granted_to text)
LANGUAGE sql
STABLE
SET search_path TO 'public', 'pg_catalog'
AS $function$
  WITH defs AS (
    SELECT
      p.oid, p.proname,
      pg_get_function_identity_arguments(p.oid) AS args,
      p.proacl,
      (pg_get_function_result(p.oid) = 'trigger') AS is_trigger,

      -- Whitelist original: funções public-intent por design
      (p.proname IN (
        'submit_quote_response',
        'get_quote_token_by_value',
        'check_login_rate_limit'  -- Onda 20.A — B-6 pre-login rate limit
      )) AS public_intent,

      -- Pipeline VPS/n8n: chamadas via anon key sem sessão de usuário
      (p.proname IN (
        'fn_video_queue_next',          -- VPS: pega próximo item da fila
        'fn_xbz_enqueue_videos',        -- n8n: enfileira vídeos XBZ
        'fn_xbz_link_video',            -- VPS: vincula CF Stream ao produto XBZ
        'fn_asia_link_video',           -- VPS: vincula CF Stream ao produto ASIA
        'fn_video_link_to_products',    -- VPS: vincula vídeo SPOT a produtos
        'fn_sm_link_video',             -- VPS: vincula vídeo SóMarcas
        'fn_spot_link_video',           -- VPS: vincula vídeo Spot
        'fn_spot_enqueue_new_videos',   -- VPS: enfileira novos vídeos Spot
        'fn_spot_enqueue_vimeo_eu',     -- VPS: Vimeo EU enqueue Spot
        'fn_spot_vimeo_daily_sync',     -- VPS: sincronização diária Vimeo
        'fn_video_link',                -- VPS: link genérico de vídeo
        'fn_video_queue_old_uid',       -- VPS: busca UID antigo na fila
        'fn_video_queue_recover_stuck', -- VPS: recupera itens travados
        'fn_video_queue_update',        -- VPS: atualiza status na fila
        'fn_video_retry_errors',        -- VPS: reprocessa erros de vídeo
        'fn_video_set_dimensions',      -- VPS: persiste dimensões do vídeo CF
        'fn_video_sim_export',          -- VPS: exporta dados de simulação
        'fn_video_sim_upsert'           -- VPS: upsert de simulação
      )) AS anon_pipeline,

      -- Edge functions que usam anon key (não service_role)
      (p.proname IN (
        'fn_check_login_allowed',           -- check-login edge: pré-autenticação
        'fn_bulk_update_image_dimensions',  -- backfill-image-dimensions edge
        'fn_cf_audit_ingest',               -- CF audit edge: ingestão de audit
        'fn_save_ai_enrichment_results',    -- AI enrichment edge: salva resultado
        'fn_dequeue_ai_enrichment',         -- AI enrichment edge: consome fila
        'fn_enqueue_ai_enrichment'          -- AI enrichment edge: enfileira
      )) AS anon_edge,

      -- MCP server usa anon key para KV store
      (p.proname IN (
        'mcp_kv_get',      -- MCP: lê valor do KV
        'mcp_kv_set',      -- MCP: grava valor no KV
        'mcp_kv_try_lock'  -- MCP: tenta adquirir lock
      )) AS anon_mcp,

      -- Catálogo público: chamadas por usuários não-logados
      (p.proname IN (
        'fn_super_filtro',              -- Super Filtro principal
        'fn_super_filtro_facets',       -- Super Filtro: facets
        'fn_super_filtro_opcoes',       -- Super Filtro: opções de filtro
        'fn_super_filtro_price_range',  -- Super Filtro: range de preço
        'fn_super_filtro_product_ids',  -- Super Filtro: IDs de produtos
        'fn_get_all_leaf_categories',   -- Catálogo: categorias folha
        'fn_get_product_intelligence_all', -- Catálogo: intelligence
        'fn_get_category_breadcrumb',   -- Catálogo: breadcrumb de categoria
        'fn_log_search_analytics',      -- Analytics de busca (anon permitido)
        'get_promo_sales_ranking',      -- Ranking de vendas público
        -- Reposição/análise: mantidos por precaução (chamados em contextos mistos)
        'fn_get_reposicao_listing',
        'fn_get_reposicao_metrics',
        'fn_get_recent_restocks',
        'fn_get_replenishment_stats'
      )) AS catalog_intent

    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.prosecdef = true
  ),
  acl_expanded AS (
    SELECT d.oid, d.proname, d.args, d.is_trigger,
           d.public_intent, d.anon_pipeline, d.anon_edge, d.anon_mcp,
           d.catalog_intent,
           a.grantee::regrole::text AS grantee
    FROM defs d
    LEFT JOIN LATERAL (SELECT (aclexplode(d.proacl)).grantee) a ON true
    WHERE a.grantee IS NOT NULL
  ),
  policy_uses AS (
    SELECT DISTINCT d.oid, d.proname, d.args
    FROM defs d
    JOIN pg_policies pp
      ON pp.schemaname = 'public'
      AND (
        COALESCE(pp.qual, '') ~ ('\m' || d.proname || '\M')
        OR COALESCE(pp.with_check, '') ~ ('\m' || d.proname || '\M')
      )
  )
  SELECT proname, args, 'PUBLIC has EXECUTE'::text, 'PUBLIC'::text
  FROM acl_expanded
  WHERE grantee = '-'
    AND NOT (public_intent OR catalog_intent OR anon_pipeline OR anon_edge OR anon_mcp)
  UNION ALL
  SELECT proname, args, 'anon has EXECUTE (not in public-intent whitelist)'::text, 'anon'
  FROM acl_expanded
  WHERE grantee = 'anon'
    AND NOT (public_intent OR catalog_intent OR anon_pipeline OR anon_edge OR anon_mcp)
  UNION ALL
  SELECT proname, args, 'trigger function has EXECUTE for authenticated'::text, 'authenticated'
  FROM acl_expanded
  WHERE grantee = 'authenticated' AND is_trigger
  UNION ALL
  SELECT pu.proname, pu.args,
         'used in RLS policy but missing EXECUTE for authenticated (RLS will fail with 42501)'::text,
         'authenticated (MISSING)'::text
  FROM policy_uses pu
  WHERE NOT EXISTS (
    SELECT 1 FROM acl_expanded a
    WHERE a.oid = pu.oid AND a.grantee = 'authenticated'
  )
  ORDER BY 1, 2;
$function$;

-- Conceder EXECUTE para authenticated (o gate deve ser auditável por admins)
GRANT EXECUTE ON FUNCTION public.audit_security_definer_acl() TO authenticated;

SELECT 'audit_security_definer_acl atualizado com whitelist expandida' AS status,
       now() AS applied_at;
;

-- <<< END 20260619103311_expand_security_definer_acl_whitelist_20260619.sql <<<

-- >>> BEGIN 20260619103731_fn_get_reposicao_listing_add_is_low_stock_v2_20260619.sql >>>
-- DROP antes de recriar (nova coluna no RETURNS TABLE exige DROP)
DROP FUNCTION IF EXISTS public.fn_get_reposicao_listing(uuid,uuid,text,integer,integer,integer);

CREATE OR REPLACE FUNCTION public.fn_get_reposicao_listing(
  p_supplier_id uuid DEFAULT NULL::uuid,
  p_category_id uuid DEFAULT NULL::uuid,
  p_sort_by text DEFAULT 'mais_recentes'::text,
  p_limit integer DEFAULT 48,
  p_offset integer DEFAULT 0,
  p_days integer DEFAULT 30
)
RETURNS TABLE(
  product_id uuid, name text, slug text, sku text, sale_price numeric,
  is_stockout boolean, is_new boolean, total_stock bigint,
  primary_image_url text, primary_image_cdn text,
  supplier_id uuid, supplier_name text, supplier_code text,
  ultimo_restock_date date, earliest_restock_date date,
  earliest_restock_qty bigint, has_upcoming_restock boolean,
  category_names text[], primary_category_id uuid, primary_category_name text,
  is_low_stock boolean
)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_today date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
BEGIN
  p_limit := GREATEST(p_limit, 0);
  RETURN QUERY
  WITH
  restock_events AS (
    SELECT DISTINCT ON (g.product_id) g.product_id, g.supplier_id, g.ultimo_restock
    FROM (
      SELECT sd.product_id, sd.supplier_id, MAX(sd.summary_date) AS ultimo_restock
      FROM stock_daily_summary sd
      WHERE sd.restock_zero_to_positive = true
        AND COALESCE(sd.stock_close, 0) > 0
        AND sd.summary_date >= v_today - p_days
      GROUP BY sd.product_id, sd.supplier_id
    ) g
    ORDER BY g.product_id, g.ultimo_restock DESC, g.supplier_id
  ),
  variant_agg AS (
    SELECT pv.product_id,
      SUM(pv.stock_quantity) AS total_stock,
      MIN(pv.next_date_1) FILTER (WHERE pv.next_date_1 > v_today) AS earliest_restock_date,
      SUM(pv.next_quantity_1) FILTER (WHERE pv.next_date_1 > v_today) AS earliest_restock_qty,
      BOOL_OR(pv.next_date_1 IS NOT NULL AND pv.next_date_1 > v_today) AS has_upcoming_restock
    FROM product_variants pv
    WHERE pv.is_active = true
      AND pv.product_id IN (SELECT re2.product_id FROM restock_events re2)
    GROUP BY pv.product_id
  ),
  primary_imgs AS (
    SELECT DISTINCT ON (pi.product_id) pi.product_id, pi.url_cdn
    FROM product_images pi
    WHERE pi.is_primary = true AND pi.is_active = true
      AND pi.product_id IN (SELECT re3.product_id FROM restock_events re3)
    ORDER BY pi.product_id, pi.updated_at DESC NULLS LAST
  ),
  category_agg AS (
    SELECT d.product_id,
      (ARRAY_AGG(d.resolved_name ORDER BY d.resolved_name))[1:3] AS category_names,
      (ARRAY_AGG(d.resolved_id   ORDER BY d.resolved_name))[1]   AS primary_category_id,
      (ARRAY_AGG(d.resolved_name ORDER BY d.resolved_name))[1]   AS primary_category_name
    FROM (
      SELECT DISTINCT pca.product_id,
        COALESCE(
          CASE WHEN c.level IN (1,2) THEN c.id END, CASE WHEN p1.level IN (1,2) THEN p1.id END,
          CASE WHEN p2.level IN (1,2) THEN p2.id END, CASE WHEN p3.level IN (1,2) THEN p3.id END,
          CASE WHEN p4.level IN (1,2) THEN p4.id END
        ) AS resolved_id,
        COALESCE(
          CASE WHEN c.level IN (1,2) THEN c.name END, CASE WHEN p1.level IN (1,2) THEN p1.name END,
          CASE WHEN p2.level IN (1,2) THEN p2.name END, CASE WHEN p3.level IN (1,2) THEN p3.name END,
          CASE WHEN p4.level IN (1,2) THEN p4.name END
        ) AS resolved_name
      FROM product_category_assignments pca
      JOIN categories c ON c.id = pca.category_id
      LEFT JOIN categories p1 ON p1.id = c.parent_id
      LEFT JOIN categories p2 ON p2.id = p1.parent_id
      LEFT JOIN categories p3 ON p3.id = p2.parent_id
      LEFT JOIN categories p4 ON p4.id = p3.parent_id
      WHERE pca.product_id IN (SELECT re4.product_id FROM restock_events re4)
    ) d WHERE d.resolved_id IS NOT NULL
    GROUP BY d.product_id
  ),
  product_base AS (
    SELECT
      p.id, p.name, p.slug, p.sku, p.sale_price, p.is_stockout, p.is_new,
      re.supplier_id, p.primary_image_url, re.ultimo_restock,
      s.name AS supplier_name, s.code AS supplier_code,
      s.low_stock_threshold,
      pi.url_cdn AS primary_image_cdn,
      COALESCE(va.total_stock, 0) AS total_stock,
      va.earliest_restock_date,
      COALESCE(va.earliest_restock_qty, 0) AS earliest_restock_qty,
      COALESCE(va.has_upcoming_restock, false) AS has_upcoming_restock,
      COALESCE(ca.category_names, ARRAY[]::text[]) AS category_names,
      ca.primary_category_id, ca.primary_category_name
    FROM restock_events re
    JOIN products p  ON p.id = re.product_id AND p.is_active = true
    JOIN suppliers s ON s.id = re.supplier_id
    LEFT JOIN primary_imgs pi ON pi.product_id = p.id
    LEFT JOIN variant_agg va  ON va.product_id = p.id
    LEFT JOIN category_agg ca ON ca.product_id = p.id
    WHERE (p_supplier_id IS NULL OR re.supplier_id = p_supplier_id)
      AND (p_category_id IS NULL OR EXISTS (
            SELECT 1 FROM product_category_assignments pca5
            WHERE pca5.product_id = p.id AND pca5.category_id = p_category_id))
  )
  SELECT
    pb.id, pb.name::text, pb.slug::text, pb.sku::text, pb.sale_price,
    pb.is_stockout, pb.is_new, pb.total_stock,
    pb.primary_image_url::text, pb.primary_image_cdn::text,
    pb.supplier_id, pb.supplier_name::text, pb.supplier_code::text,
    pb.ultimo_restock, pb.earliest_restock_date, pb.earliest_restock_qty,
    pb.has_upcoming_restock, pb.category_names,
    pb.primary_category_id, pb.primary_category_name::text,
    (pb.total_stock > 0 AND pb.low_stock_threshold IS NOT NULL
     AND pb.total_stock <= pb.low_stock_threshold) AS is_low_stock
  FROM product_base pb
  ORDER BY
    CASE WHEN p_sort_by='nome_az'       THEN pb.name        END ASC  NULLS LAST,
    CASE WHEN p_sort_by='nome_za'       THEN pb.name        END DESC NULLS LAST,
    CASE WHEN p_sort_by='preco_menor'   THEN pb.sale_price  END ASC  NULLS LAST,
    CASE WHEN p_sort_by='preco_maior'   THEN pb.sale_price  END DESC NULLS LAST,
    CASE WHEN p_sort_by='maior_estoque' THEN pb.total_stock END DESC NULLS LAST,
    CASE WHEN p_sort_by NOT IN ('nome_az','nome_za','preco_menor','preco_maior','maior_estoque')
         THEN pb.ultimo_restock END DESC NULLS LAST,
    pb.id
  LIMIT p_limit OFFSET p_offset;
END;
$function$;

-- Re-grant (DROP remove grants)
GRANT EXECUTE ON FUNCTION public.fn_get_reposicao_listing(uuid,uuid,text,integer,integer,integer) TO anon, authenticated;

-- PostgREST schema cache reload
NOTIFY pgrst, 'reload schema';

SELECT 'fn_get_reposicao_listing com is_low_stock deployado' AS status;
;

