-- >>> BEGIN 20260619104544_fn_auto_vincular_cor_variante_use_canonical_matcher_20260619.sql >>>
-- ============================================================================
-- MIGRATION: fn_auto_vincular_cor_variante_use_canonical_matcher_20260619
-- Fecha o silver gap: trigger BEFORE INSERT/UPDATE em product_variants
-- agora usa fn_match_canonical_color como estratégia 3 (fallback canônico),
-- aproveitando todas as 5 prioridades da função mestre de resolução de cores.
--
-- Gap anterior: apenas 2 estratégias (código SPOT + nome exato).
-- Produtos ASIA/XBZ/SóMarcas sem código SPOT e com nome não-exato
-- chegavam a gold com color_id = NULL quando fn_match_canonical_color
-- resolveria via P3/P4 (color_equivalences) ou P5 (color_groups partial).
-- ============================================================================

CREATE OR REPLACE FUNCTION public.fn_auto_vincular_cor_variante()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
    v_codigo_cor     TEXT;
    v_nome_cor       TEXT;
    v_variation_id   UUID;
    v_variation_name TEXT;
    v_variation_hex  TEXT;
BEGIN
    v_codigo_cor := NEW.attributes->>'codigo_cor';
    v_nome_cor   := NEW.attributes->>'cor';

    -- Se já tem color_id preenchido, não sobrescrever
    IF NEW.color_id IS NOT NULL THEN
        RETURN NEW;
    END IF;

    -- ────────────────────────────────────────────────────────────────────────
    -- ESTRATÉGIA 1: código SPOT via color_equivalences (mais específico)
    -- ────────────────────────────────────────────────────────────────────────
    IF v_codigo_cor IS NOT NULL THEN
        SELECT cv.id, cv.name, cv.hex_code
        INTO v_variation_id, v_variation_name, v_variation_hex
        FROM supplier_colors sc
        JOIN color_equivalences ce ON ce.supplier_color_id = sc.id AND ce.is_active = true
        JOIN color_variations cv   ON cv.id = ce.promo_variation_id AND cv.is_active = true
        WHERE sc.code = v_codigo_cor
        ORDER BY ce.confidence_score DESC NULLS LAST
        LIMIT 1;

        IF v_variation_id IS NOT NULL THEN
            NEW.color_id   := v_variation_id;
            NEW.color_name := v_variation_name;
            NEW.color_hex  := v_variation_hex;
            RETURN NEW;
        END IF;
    END IF;

    -- ────────────────────────────────────────────────────────────────────────
    -- ESTRATÉGIA 2: match exato de nome em color_variations (rápido)
    -- ────────────────────────────────────────────────────────────────────────
    IF v_nome_cor IS NOT NULL THEN
        SELECT cv.id, cv.name, cv.hex_code
        INTO v_variation_id, v_variation_name, v_variation_hex
        FROM color_variations cv
        WHERE cv.is_active = true
          AND (
              LOWER(TRIM(cv.name)) = LOWER(TRIM(v_nome_cor))
              OR LOWER(cv.name) LIKE LOWER(TRIM(v_nome_cor)) || '%'
          )
        ORDER BY
            CASE WHEN LOWER(TRIM(cv.name)) = LOWER(TRIM(v_nome_cor)) THEN 1 ELSE 2 END,
            LENGTH(cv.name)
        LIMIT 1;

        IF v_variation_id IS NOT NULL THEN
            NEW.color_id   := v_variation_id;
            NEW.color_name := v_variation_name;
            NEW.color_hex  := v_variation_hex;
            RETURN NEW;
        END IF;
    END IF;

    -- ────────────────────────────────────────────────────────────────────────
    -- ESTRATÉGIA 3 (GAP FIX): fn_match_canonical_color como fallback canônico
    -- Abrange P1-P5: hex exato, supplier_colors por nome/hex via equivalences,
    -- e match parcial via color_groups.
    -- Usa color_name já normalizado em NEW ou extrai de attributes.
    -- ────────────────────────────────────────────────────────────────────────
    DECLARE
        v_match_name TEXT := COALESCE(NEW.color_name, v_nome_cor);
        v_match_hex  TEXT := COALESCE(NEW.color_hex, NEW.attributes->>'hex');
    BEGIN
        IF v_match_name IS NOT NULL OR v_match_hex IS NOT NULL THEN
            v_variation_id := public.fn_match_canonical_color(v_match_name, v_match_hex);

            IF v_variation_id IS NOT NULL THEN
                SELECT cv.name, cv.hex_code
                INTO v_variation_name, v_variation_hex
                FROM color_variations cv
                WHERE cv.id = v_variation_id;

                NEW.color_id   := v_variation_id;
                NEW.color_name := COALESCE(NEW.color_name, v_variation_name);
                NEW.color_hex  := COALESCE(NEW.color_hex, v_variation_hex);
            END IF;
        END IF;
    END;

    RETURN NEW;
END;
$function$;

SELECT 'fn_auto_vincular_cor_variante atualizado com fn_match_canonical_color fallback' AS status;
;

-- <<< END 20260619104544_fn_auto_vincular_cor_variante_use_canonical_matcher_20260619.sql <<<

-- >>> BEGIN 20260619104718_fix_mv_leaf_order_is_primary_first_v4.sql >>>

-- FIX CRÍTICO (2026-06-18): MV estava com ORDER BY errado — c.level DESC antes de pca.is_primary DESC
-- Correto: is_primary DESC deve vir PRIMEIRO (categorias primárias têm precedência sobre qualquer nível)
-- Root cause: feat_mv_product_category_safe e fix_mv_leaf_safe_null_main aplicaram
--   ORDER BY nesta ordem: product_id, is_primary DESC, level DESC
--   Mas pg_get_viewdef mostra: product_id, level DESC, is_primary DESC
-- Possível causa: Supabase reordenou internamente ao parsear (improvável) 
--   ou migrations não executaram na sequência esperada.
-- Fix: recriar com ordem EXPLÍCITA e verificada

DROP MATERIALIZED VIEW IF EXISTS public.mv_product_leaf_category CASCADE;

CREATE MATERIALIZED VIEW public.mv_product_leaf_category AS
SELECT DISTINCT ON (pca.product_id)
  pca.product_id,
  c.id            AS leaf_category_id,
  c.name          AS leaf_category_name,
  c.level         AS leaf_category_level,
  c.parent_id     AS leaf_category_parent_id,
  c.slug          AS leaf_category_slug,
  CASE
    WHEN p.main_category_id IS NULL                            THEN c.id
    WHEN c.id = p.main_category_id                            THEN c.id
    WHEN EXISTS (
      SELECT 1 FROM public.category_ancestors ca
      WHERE ca.descendant_id = c.id AND ca.ancestor_id = p.main_category_id
    )                                                          THEN c.id
    ELSE NULL
  END AS leaf_category_id_safe
FROM public.product_category_assignments pca
JOIN public.categories c ON c.id = pca.category_id
LEFT JOIN public.products p ON p.id = pca.product_id
ORDER BY
  -- CRÍTICO: is_primary DESC DEVE ser o 2º critério (após product_id)
  -- Level vem DEPOIS: categoria primária level 2 > categoria transversal level 5
  pca.product_id        ASC,
  pca.is_primary        DESC NULLS LAST,  -- TRUE (1) > FALSE (0) > NULL
  c.level               DESC NULLS LAST,  -- profundidade máxima dentro da categoria primária
  pca.display_order     ASC  NULLS LAST,  -- display_order baixo = maior prioridade
  c.name                ASC;              -- desempate alfabético

-- Índices completos
CREATE UNIQUE INDEX mv_product_leaf_category_pk
  ON public.mv_product_leaf_category (product_id)
  INCLUDE (leaf_category_id, leaf_category_name, leaf_category_level,
           leaf_category_slug, leaf_category_id_safe);

CREATE INDEX mv_product_leaf_category_cat_idx
  ON public.mv_product_leaf_category (leaf_category_id);

CREATE INDEX mv_product_leaf_category_safe_idx
  ON public.mv_product_leaf_category (leaf_category_id_safe)
  WHERE leaf_category_id_safe IS NOT NULL;

GRANT SELECT ON public.mv_product_leaf_category TO anon, authenticated;

-- Recriar v_products_public
CREATE OR REPLACE VIEW public.v_products_public AS
SELECT
  p.id, p.name, p.description, p.sku, p.category_id, p.supplier_id,
  NULL::numeric AS cost_price, p.sale_price, p.stock_quantity, p.active,
  p.created_at, p.updated_at, NULL::numeric AS suggested_price,
  p.dimensions, p.images, p.primary_image_url, p.videos,
