-- >>> BEGIN 20260619110249_fix_fn_set_product_as_new_update.sql >>>
-- Fix: fn_set_product_as_new — adiciona tratamento de UPDATE para is_new false→true
CREATE OR REPLACE FUNCTION fn_set_product_as_new()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.is_new IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.novelty_detected_at IS NULL THEN
      NEW.novelty_detected_at := NOW();
    END IF;
    IF NEW.novelty_expires_at IS NULL THEN
      NEW.novelty_expires_at := NEW.novelty_detected_at + INTERVAL '30 days';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' THEN
    DECLARE
      was_new BOOLEAN := COALESCE(OLD.is_new, FALSE);
      already_active BOOLEAN := (
        NEW.novelty_expires_at IS NOT NULL AND
        NEW.novelty_expires_at > NOW()
      );
    BEGIN
      IF (was_new = FALSE OR NOT already_active) THEN
        NEW.novelty_detected_at := NOW();
        NEW.novelty_expires_at  := NOW() + INTERVAL '30 days';
      END IF;
      RETURN NEW;
    END;
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_set_product_as_new ON products;

CREATE TRIGGER trg_set_product_as_new
  BEFORE INSERT OR UPDATE OF is_new
  ON products
  FOR EACH ROW
  EXECUTE FUNCTION fn_set_product_as_new();

COMMENT ON FUNCTION fn_set_product_as_new() IS
  'Preenche novelty_detected_at e novelty_expires_at quando is_new=true é definido/reativado. '
  'Dispara em INSERT e UPDATE(is_new). '
  'Idempotente: preserva expiração futura existente.';;

-- <<< END 20260619110249_fix_fn_set_product_as_new_update.sql <<<

-- >>> BEGIN 20260619110311_idx_products_novelty_covering.sql >>>
DROP INDEX IF EXISTS idx_products_new_active_sort;

CREATE INDEX idx_products_new_active_sort
  ON products (novelty_detected_at DESC, id ASC)
  INCLUDE (novelty_expires_at, sale_price, stock_quantity, is_stockout, primary_image_url, category_id, supplier_id)
  WHERE is_new = true;

COMMENT ON INDEX idx_products_new_active_sort IS
  'Índice cobrindo para queries de novidades ativas. '
  'Predicate: is_new=true. Include: colunas lidas por useNoveltiesWithDetails. '
  'Evita heap fetch para filtro novelty_expires_at > NOW() e filtros de qualidade.';;

-- <<< END 20260619110311_idx_products_novelty_covering.sql <<<

-- >>> BEGIN 20260619110352_security_definer_acl_revoke_public_anon_20260619.sql >>>
-- ============================================================================
-- MIGRATION: security_definer_acl_revoke_public_anon_20260619
-- Codifica em migration formal o REVOKE aplicado via execute_sql direto
-- durante a sessão de hardening de segurança de 2026-06-19.
--
-- Contexto: audit_security_definer_acl() identificou 262 violações onde
-- funções SECURITY DEFINER tinham EXECUTE concedido para PUBLIC/anon sem
-- propósito legítimo. O REVOKE em massa foi aplicado via DO block.
--
-- Esta migration é idempotente: REVOKE de privilégio inexistente é no-op.
--
-- Funções whitelistadas (excluídas do REVOKE — têm acesso legítimo):
-- catálogo público, pipeline VPS/n8n, edge functions via anon key, MCP KV.
-- Ver também: expand_security_definer_acl_whitelist_20260619
-- ============================================================================

-- (1) REVOKE das 2 trigger functions com PUBLIC grant residual
--     Triggers executam como owner — PUBLIC é irrelevante e é superfície desnecessária
REVOKE EXECUTE ON FUNCTION public.fn_handle_canonical_root_soft_delete() FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.fn_reset_is_shared_on_canonical_null() FROM PUBLIC, anon;

-- (2) REVOKE em massa via DO block (idempotente)
--     Replica o REVOKE aplicado no DO block de 83 funções em 2026-06-19.
--     Lista de exclusão (whitelist) idêntica à aplicada no DO block original.
DO $$
DECLARE
  r RECORD;
  revoke_sql TEXT;
BEGIN
  FOR r IN (
    SELECT DISTINCT p.proname, pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prosecdef = true
      AND p.proname NOT IN (
        -- Catálogo público
        'fn_super_filtro','fn_super_filtro_facets','fn_super_filtro_opcoes',
        'fn_super_filtro_price_range','fn_super_filtro_product_ids',
        'fn_get_all_leaf_categories','fn_get_product_intelligence_all',
        'fn_get_category_breadcrumb','fn_log_search_analytics','get_promo_sales_ranking',
        -- Pipeline vídeo VPS/n8n
        'fn_video_queue_next','fn_xbz_enqueue_videos','fn_xbz_link_video',
        'fn_asia_link_video','fn_video_link_to_products','fn_sm_link_video',
        'fn_spot_enqueue_new_videos','fn_spot_enqueue_vimeo_eu','fn_spot_link_video',
        'fn_spot_vimeo_daily_sync','fn_video_link','fn_video_queue_old_uid',
        'fn_video_queue_recover_stuck','fn_video_queue_update','fn_video_retry_errors',
        'fn_video_set_dimensions','fn_video_sim_export','fn_video_sim_upsert',
        -- Edge functions via anon key
        'fn_check_login_allowed','fn_bulk_update_image_dimensions','fn_cf_audit_ingest',
        'fn_save_ai_enrichment_results','fn_dequeue_ai_enrichment','fn_enqueue_ai_enrichment',
        -- MCP KV
        'mcp_kv_get','mcp_kv_set','mcp_kv_try_lock',
        -- Whitelist original do gate
        'submit_quote_response','get_quote_token_by_value','check_login_rate_limit',
        -- Reposição/análise
        'fn_get_reposicao_listing','fn_get_reposicao_metrics',
        'fn_get_recent_restocks','fn_get_replenishment_stats'
      )
      AND EXISTS (
        SELECT 1 FROM aclexplode(COALESCE(p.proacl, acldefault('f', p.proowner))) ace
        WHERE ace.privilege_type = 'EXECUTE'
          AND ace.grantee IN (
            (SELECT oid FROM pg_roles WHERE rolname = 'anon'),
            0 -- PUBLIC
          )
      )
    ORDER BY p.proname
  ) LOOP
    IF r.args IS NOT NULL AND r.args != '' THEN
      revoke_sql := format('REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM PUBLIC, anon', r.proname, r.args);
    ELSE
      revoke_sql := format('REVOKE EXECUTE ON FUNCTION public.%I() FROM PUBLIC, anon', r.proname);
    END IF;
    BEGIN
      EXECUTE revoke_sql;
    EXCEPTION WHEN OTHERS THEN
      NULL; -- Ignorar erros (idempotente)
    END;
  END LOOP;
END $$;

-- Verificação: deve retornar 0 ou apenas trigger_normal (ruído esperado)
SELECT COUNT(*) FILTER (WHERE granted_to IN ('PUBLIC','anon')) AS violacoes_restantes,
       COUNT(*) FILTER (WHERE problem LIKE 'trigger function%') AS trigger_noise
FROM public.audit_security_definer_acl();
;

-- <<< END 20260619110352_security_definer_acl_revoke_public_anon_20260619.sql <<<

-- >>> BEGIN 20260619110500_add_covering_index_and_safe_idx_on_mv_leaf.sql >>>

-- FIX: adicionar índices ausentes que foram perdidos após re-aplicação da git migration
-- A migration 20260618205528_mv_product_leaf_category_level_first.sql cria apenas 2 índices simples.
-- Esta migration adiciona o covering index (para Index Only Scan) e o safe_idx.

-- Remover o índice simples sem INCLUDE (será substituído pelo covering)
DROP INDEX IF EXISTS idx_mv_product_leaf_category_product_id;

-- Covering index: UNIQUE em product_id + INCLUDE dos 4 campos mais consultados
-- Benefício: Index Only Scan no JOIN de v_products_public (zero heap access)
CREATE UNIQUE INDEX idx_mv_product_leaf_category_product_id
  ON public.mv_product_leaf_category (product_id)
  INCLUDE (leaf_category_id, leaf_category_name, leaf_category_level,
           leaf_category_slug, leaf_category_id_safe);

COMMENT ON INDEX idx_mv_product_leaf_category_product_id IS
'Covering index com INCLUDE para Index Only Scan no JOIN de v_products_public.
 Substituiu o índice simples original em 2026-06-19.';

-- Partial index para buscas por leaf_category_id_safe (apenas onde safe não é NULL)
CREATE INDEX IF NOT EXISTS idx_mv_product_leaf_category_safe_id
  ON public.mv_product_leaf_category (leaf_category_id_safe)
  WHERE leaf_category_id_safe IS NOT NULL;

COMMENT ON INDEX idx_mv_product_leaf_category_safe_id IS
'Partial index para buscas por leaf_category_id_safe. Criado em 2026-06-19.';

-- Verificação inline
DO $$
DECLARE
  v_unique_count int;
  v_covering_cols int;
BEGIN
  SELECT COUNT(*) INTO v_unique_count
  FROM pg_index ix JOIN pg_class c ON c.oid=ix.indexrelid
  WHERE c.relname='idx_mv_product_leaf_category_product_id' AND ix.indisunique;

  SELECT COUNT(*) INTO v_covering_cols
  FROM pg_attribute pa JOIN pg_class c ON c.oid=pa.attrelid
  WHERE c.relname='idx_mv_product_leaf_category_product_id' AND pa.attnum > 0;

  IF v_unique_count = 0 THEN RAISE EXCEPTION 'UNIQUE index não criado'; END IF;
  IF v_covering_cols < 6 THEN RAISE EXCEPTION 'INCLUDE cols insuficientes: %', v_covering_cols; END IF;

  RAISE NOTICE 'OK: covering index UNIQUE criado com % colunas (key+include)', v_covering_cols;
END;
$$;
;

-- <<< END 20260619110500_add_covering_index_and_safe_idx_on_mv_leaf.sql <<<

-- >>> BEGIN 20260619110629_fix_reposicao_rpcs.sql >>>
-- ─── 0. VIEW: vw_product_availability ───────────────────────────
CREATE OR REPLACE VIEW public.vw_product_availability AS
SELECT
  pv.id AS variant_id,
  pv.product_id,
  pv.sku,
  pv.stock_quantity,
  pv.next_quantity_1, pv.next_date_1,
  pv.next_quantity_2, pv.next_date_2,
  pv.next_quantity_3, pv.next_date_3,
  CASE
    WHEN pv.stock_quantity > 0 THEN 'in_stock'::text
    WHEN pv.stock_quantity = 0 AND (
         (pv.next_date_1 IS NOT NULL AND pv.next_date_1 > CURRENT_DATE) OR
         (pv.next_date_2 IS NOT NULL AND pv.next_date_2 > CURRENT_DATE) OR
         (pv.next_date_3 IS NOT NULL AND pv.next_date_3 > CURRENT_DATE) OR
         (pv.next_date_4 IS NOT NULL AND pv.next_date_4 > CURRENT_DATE) OR
         (pv.next_date_5 IS NOT NULL AND pv.next_date_5 > CURRENT_DATE) OR
         (pv.next_date_6 IS NOT NULL AND pv.next_date_6 > CURRENT_DATE)
    ) THEN 'out_of_stock_with_restock'::text
    ELSE 'out_of_stock'::text
  END AS availability_status,
  (pv.stock_quantity = 0 AND (
    (pv.next_date_1 IS NOT NULL AND pv.next_date_1 > CURRENT_DATE) OR
    (pv.next_date_2 IS NOT NULL AND pv.next_date_2 > CURRENT_DATE) OR
    (pv.next_date_3 IS NOT NULL AND pv.next_date_3 > CURRENT_DATE) OR
    (pv.next_date_4 IS NOT NULL AND pv.next_date_4 > CURRENT_DATE) OR
    (pv.next_date_5 IS NOT NULL AND pv.next_date_5 > CURRENT_DATE) OR
    (pv.next_date_6 IS NOT NULL AND pv.next_date_6 > CURRENT_DATE)
  )) AS has_incoming_stock,
  (
    (pv.next_date_1 IS NOT NULL AND pv.next_date_1 > CURRENT_DATE) OR
    (pv.next_date_2 IS NOT NULL AND pv.next_date_2 > CURRENT_DATE) OR
    (pv.next_date_3 IS NOT NULL AND pv.next_date_3 > CURRENT_DATE) OR
    (pv.next_date_4 IS NOT NULL AND pv.next_date_4 > CURRENT_DATE) OR
    (pv.next_date_5 IS NOT NULL AND pv.next_date_5 > CURRENT_DATE) OR
    (pv.next_date_6 IS NOT NULL AND pv.next_date_6 > CURRENT_DATE)
  ) AS has_upcoming_restock,
  pv.last_sync_at
FROM product_variants pv
JOIN products p ON p.id = pv.product_id
WHERE pv.is_active = true AND p.is_active = true;

GRANT SELECT ON public.vw_product_availability TO authenticated;

-- ─── 1. fn_get_replenishment_stats ──────────────────────────────
CREATE OR REPLACE FUNCTION public.fn_get_replenishment_stats()
RETURNS jsonb
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
  WITH
  cfg AS (SELECT (now() AT TIME ZONE 'America/Sao_Paulo')::date AS today),
  cenario_a AS (
    SELECT DISTINCT sds.product_id, sds.supplier_id, sds.summary_date
    FROM stock_daily_summary sds
    JOIN products p ON p.id = sds.product_id AND p.is_active = true
    WHERE sds.restock_zero_to_positive = true
      AND COALESCE(sds.stock_close, 0) > 0
      AND sds.summary_date >= (SELECT today FROM cfg) - 30
  ),
  cenario_b AS (
    SELECT DISTINCT sds.product_id, sds.supplier_id, sds.summary_date
    FROM stock_daily_summary sds
    JOIN products p ON p.id = sds.product_id AND p.is_active = true
    WHERE COALESCE(sds.stock_open, 0) > 0
      AND COALESCE(sds.stock_close, 0) > COALESCE(sds.stock_open, 0)
      AND sds.restock_detected = true
      AND sds.summary_date >= (SELECT today FROM cfg) - 30
  ),
  a_hoje AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a WHERE summary_date = (SELECT today FROM cfg)),
  a_7d   AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a WHERE summary_date >= (SELECT today FROM cfg) - 7),
  a_15d  AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a WHERE summary_date >= (SELECT today FROM cfg) - 15),
  a_30d  AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a),
  a_expiring AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_a WHERE summary_date <= (SELECT today FROM cfg) - 23),
  b_7d   AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_b WHERE summary_date >= (SELECT today FROM cfg) - 7),
  b_30d  AS (SELECT COUNT(DISTINCT product_id)::int AS n FROM cenario_b),
  top_a AS (
    SELECT s.name, COUNT(DISTINCT ca.product_id)::int AS cnt
    FROM cenario_a ca
    JOIN suppliers s ON s.id = ca.supplier_id
    WHERE s.name IS NOT NULL
    GROUP BY s.name ORDER BY cnt DESC LIMIT 1
  ),
  ativas AS (
    SELECT
      COUNT(*)::int                                             AS total_var,
      COUNT(*) FILTER (WHERE has_incoming_stock  = true)::int  AS incoming,
      COUNT(*) FILTER (WHERE has_upcoming_restock = true)::int AS upcoming
    FROM vw_product_availability
  )
  SELECT jsonb_build_object(
    'restockedToday',           (SELECT n FROM a_hoje),
    'restockedThisWeek',        (SELECT n FROM a_7d),
    'restockedLast15Days',      (SELECT n FROM a_15d),
    'restockedLast30Days',      (SELECT n FROM a_30d),
    'expiringSoon',             (SELECT n FROM a_expiring),
    'topSupplierName',          COALESCE((SELECT name FROM top_a), null),
    'topSupplierCount',         COALESCE((SELECT cnt  FROM top_a), 0),
    'activeReplenishments',     (SELECT incoming FROM ativas),
    'totalVariants',            (SELECT total_var FROM ativas),
    'replenishmentRate',        ROUND((SELECT incoming::numeric FROM ativas) / NULLIF((SELECT total_var FROM ativas), 0) * 100),
    'reorderedThisWeek',        (SELECT n FROM b_7d),
    'reorderedThisMonth',       (SELECT n FROM b_30d),
    'upcomingRestockVariants',  (SELECT upcoming FROM ativas),
    '_version',                 'v5_fixes_20260619'
  );
$$;

-- ─── 2. fn_get_reposicao_listing ────────────────────────────────
CREATE OR REPLACE FUNCTION public.fn_get_reposicao_listing(
  p_supplier_id uuid    DEFAULT NULL,
  p_category_id uuid    DEFAULT NULL,
  p_sort_by     text    DEFAULT 'mais_recentes',
  p_limit       integer DEFAULT 48,
  p_offset      integer DEFAULT 0,
  p_days        integer DEFAULT 30
)
RETURNS TABLE(
  product_id uuid, name text, slug text, sku text, sale_price numeric,
  is_stockout boolean, is_new boolean, total_stock bigint,
  primary_image_url text, primary_image_cdn text,
  supplier_id uuid, supplier_name text, supplier_code text,
  ultimo_restock_date date, earliest_restock_date date, earliest_restock_qty bigint,
  has_upcoming_restock boolean, category_names text[],
  primary_category_id uuid, primary_category_name text, is_low_stock boolean
)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE v_today date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
BEGIN
  p_limit := GREATEST(p_limit, 0);
  RETURN QUERY
  WITH
  restock_events AS (
    SELECT DISTINCT ON (g.product_id) g.product_id, g.supplier_id, g.ultimo_restock
    FROM (
      SELECT sd.product_id, sd.supplier_id, MAX(sd.summary_date) AS ultimo_restock
      FROM stock_daily_summary sd
      WHERE sd.restock_zero_to_positive = true AND COALESCE(sd.stock_close, 0) > 0
        AND sd.summary_date >= v_today - p_days
      GROUP BY sd.product_id, sd.supplier_id
    ) g
    ORDER BY g.product_id, g.ultimo_restock DESC, g.supplier_id
  ),
  variant_agg AS (
    SELECT pv.product_id,
      SUM(pv.stock_quantity) AS total_stock,
      LEAST(
        MIN(pv.next_date_1) FILTER (WHERE pv.next_date_1 > v_today),
        MIN(pv.next_date_2) FILTER (WHERE pv.next_date_2 > v_today),
        MIN(pv.next_date_3) FILTER (WHERE pv.next_date_3 > v_today),
        MIN(pv.next_date_4) FILTER (WHERE pv.next_date_4 > v_today),
        MIN(pv.next_date_5) FILTER (WHERE pv.next_date_5 > v_today),
        MIN(pv.next_date_6) FILTER (WHERE pv.next_date_6 > v_today)
      ) AS earliest_restock_date,
      COALESCE(SUM(pv.next_quantity_1) FILTER (WHERE pv.next_date_1 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_2) FILTER (WHERE pv.next_date_2 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_3) FILTER (WHERE pv.next_date_3 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_4) FILTER (WHERE pv.next_date_4 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_5) FILTER (WHERE pv.next_date_5 > v_today), 0)
      + COALESCE(SUM(pv.next_quantity_6) FILTER (WHERE pv.next_date_6 > v_today), 0)
        AS earliest_restock_qty,
      BOOL_OR(
        (pv.next_date_1 IS NOT NULL AND pv.next_date_1 > v_today) OR
        (pv.next_date_2 IS NOT NULL AND pv.next_date_2 > v_today) OR
        (pv.next_date_3 IS NOT NULL AND pv.next_date_3 > v_today) OR
        (pv.next_date_4 IS NOT NULL AND pv.next_date_4 > v_today) OR
        (pv.next_date_5 IS NOT NULL AND pv.next_date_5 > v_today) OR
        (pv.next_date_6 IS NOT NULL AND pv.next_date_6 > v_today)
      ) AS has_upcoming_restock
    FROM product_variants pv
    WHERE pv.is_active = true AND pv.product_id IN (SELECT re2.product_id FROM restock_events re2)
    GROUP BY pv.product_id
  ),
  primary_imgs AS (
    SELECT DISTINCT ON (pi.product_id) pi.product_id, pi.url_cdn
    FROM product_images pi
    WHERE pi.is_primary = true AND pi.is_active = true
      AND pi.product_id IN (SELECT re3.product_id FROM restock_events re3)
    ORDER BY pi.product_id, pi.updated_at DESC NULLS LAST
  ),
  category_agg AS (
    SELECT d.product_id,
      (ARRAY_AGG(d.resolved_name ORDER BY d.resolved_name))[1:3] AS category_names,
      (ARRAY_AGG(d.resolved_id   ORDER BY d.resolved_name))[1]   AS primary_category_id,
      (ARRAY_AGG(d.resolved_name ORDER BY d.resolved_name))[1]   AS primary_category_name
    FROM (
      SELECT DISTINCT pca.product_id,
        COALESCE(
          CASE WHEN c.level  IN (1,2) THEN c.id  END,
          CASE WHEN p1.level IN (1,2) THEN p1.id END,
          CASE WHEN p2.level IN (1,2) THEN p2.id END,
          CASE WHEN p3.level IN (1,2) THEN p3.id END,
          CASE WHEN p4.level IN (1,2) THEN p4.id END,
          c.id
        ) AS resolved_id,
        COALESCE(
          CASE WHEN c.level  IN (1,2) THEN c.name  END,
          CASE WHEN p1.level IN (1,2) THEN p1.name END,
          CASE WHEN p2.level IN (1,2) THEN p2.name END,
          CASE WHEN p3.level IN (1,2) THEN p3.name END,
          CASE WHEN p4.level IN (1,2) THEN p4.name END,
          c.name
        ) AS resolved_name
      FROM product_category_assignments pca
      JOIN categories c ON c.id = pca.category_id
      LEFT JOIN categories p1 ON p1.id = c.parent_id
      LEFT JOIN categories p2 ON p2.id = p1.parent_id
      LEFT JOIN categories p3 ON p3.id = p2.parent_id
      LEFT JOIN categories p4 ON p4.id = p3.parent_id
      WHERE pca.product_id IN (SELECT re4.product_id FROM restock_events re4)
    ) d
    GROUP BY d.product_id
  ),
  product_base AS (
    SELECT p.id, p.name, p.slug, p.sku, p.sale_price, p.is_stockout, p.is_new,
      re.supplier_id, p.primary_image_url, re.ultimo_restock,
      s.name AS supplier_name, s.code AS supplier_code, s.low_stock_threshold,
      pi.url_cdn AS primary_image_cdn,
      COALESCE(va.total_stock, 0) AS total_stock,
      va.earliest_restock_date,
      COALESCE(va.earliest_restock_qty, 0) AS earliest_restock_qty,
      COALESCE(va.has_upcoming_restock, false) AS has_upcoming_restock,
      COALESCE(ca.category_names, ARRAY[]::text[]) AS category_names,
      ca.primary_category_id, ca.primary_category_name
    FROM restock_events re
    JOIN products p  ON p.id = re.product_id AND p.is_active = true
    JOIN suppliers s ON s.id = re.supplier_id
    LEFT JOIN primary_imgs pi ON pi.product_id = p.id
    LEFT JOIN variant_agg va  ON va.product_id = p.id
    LEFT JOIN category_agg ca ON ca.product_id = p.id
    WHERE (p_supplier_id IS NULL OR re.supplier_id = p_supplier_id)
      AND (p_category_id IS NULL OR EXISTS (
            SELECT 1 FROM product_category_assignments pca5
            WHERE pca5.product_id = p.id AND pca5.category_id = p_category_id))
  )
  SELECT pb.id, pb.name::text, pb.slug::text, pb.sku::text, pb.sale_price,
    pb.is_stockout, pb.is_new, pb.total_stock,
    pb.primary_image_url::text, pb.primary_image_cdn::text,
    pb.supplier_id, pb.supplier_name::text, pb.supplier_code::text,
    pb.ultimo_restock, pb.earliest_restock_date, pb.earliest_restock_qty,
    pb.has_upcoming_restock, pb.category_names,
    pb.primary_category_id, pb.primary_category_name::text,
    (pb.total_stock > 0 AND pb.low_stock_threshold IS NOT NULL
     AND pb.total_stock <= pb.low_stock_threshold) AS is_low_stock
  FROM product_base pb
  ORDER BY
    CASE WHEN p_sort_by = 'nome_az'       THEN pb.name        END ASC  NULLS LAST,
    CASE WHEN p_sort_by = 'nome_za'       THEN pb.name        END DESC NULLS LAST,
    CASE WHEN p_sort_by = 'preco_menor'   THEN pb.sale_price  END ASC  NULLS LAST,
    CASE WHEN p_sort_by = 'preco_maior'   THEN pb.sale_price  END DESC NULLS LAST,
    CASE WHEN p_sort_by = 'maior_estoque' THEN pb.total_stock END DESC NULLS LAST,
    CASE WHEN p_sort_by NOT IN ('nome_az','nome_za','preco_menor','preco_maior','maior_estoque')
         THEN pb.ultimo_restock END DESC NULLS LAST,
    pb.id
  LIMIT p_limit OFFSET p_offset;
END;
$$;

-- ─── 3. fn_get_reposicao_metrics ────────────────────────────────
CREATE OR REPLACE FUNCTION public.fn_get_reposicao_metrics()
RETURNS jsonb
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_today date := (now() AT TIME ZONE 'America/Sao_Paulo')::date;
  v_hoje int; v_7d int; v_15d int; v_30d int;
  v_top_supplier text; v_top_count int;
  v_ativas int; v_aguardando int; v_pct_ativas numeric;
  v_total_vars int; v_data_min date; v_dias_hist int;
BEGIN
  SELECT
    COUNT(DISTINCT CASE WHEN sd.summary_date = v_today       THEN sd.product_id END),
    COUNT(DISTINCT CASE WHEN sd.summary_date >= v_today - 7  THEN sd.product_id END),
    COUNT(DISTINCT CASE WHEN sd.summary_date >= v_today - 15 THEN sd.product_id END),
    COUNT(DISTINCT CASE WHEN sd.summary_date >= v_today - 30 THEN sd.product_id END),
    MIN(sd.summary_date), (v_today - MIN(sd.summary_date))
  INTO v_hoje, v_7d, v_15d, v_30d, v_data_min, v_dias_hist
  FROM stock_daily_summary sd JOIN products p ON p.id = sd.product_id
  WHERE sd.restock_zero_to_positive = true AND sd.summary_date >= v_today - 30
    AND sd.stock_close > 0 AND p.is_active = true;

  SELECT s.name, COUNT(DISTINCT sd.product_id) INTO v_top_supplier, v_top_count
  FROM stock_daily_summary sd JOIN suppliers s ON s.id = sd.supplier_id
  JOIN products p ON p.id = sd.product_id
  WHERE sd.restock_zero_to_positive = true AND sd.summary_date >= v_today - 7
    AND sd.stock_close > 0 AND p.is_active = true
  GROUP BY s.name ORDER BY COUNT(DISTINCT sd.product_id) DESC LIMIT 1;

  SELECT COUNT(*) INTO v_total_vars FROM product_variants WHERE is_active = true;

  SELECT
    COUNT(*) FILTER (WHERE pv.stock_quantity = 0 AND pv.next_date_1 IS NOT NULL AND pv.next_date_1 > v_today),
    COUNT(*) FILTER (WHERE pv.next_date_1 IS NOT NULL AND pv.next_date_1 > v_today)
  INTO v_ativas, v_aguardando FROM product_variants pv WHERE pv.is_active = true;

  v_pct_ativas := ROUND(100.0 * v_ativas / NULLIF(v_total_vars, 0), 1);

  RETURN jsonb_build_object(
    'dias_historico_real', v_dias_hist, 'data_inicio_historico', v_data_min,
    'aviso_historico', CASE WHEN v_dias_hist < 30
      THEN 'Histórico incompleto: ' || v_dias_hist::text || ' dias disponíveis (meta: 30)'
      ELSE 'OK' END,
    'repostos_hoje', v_hoje, 'repostos_7d', v_7d, 'repostos_15d', v_15d, 'repostos_30d', v_30d,
    '7d_igual_15d_aviso', (v_7d = v_15d AND v_dias_hist < 15),
    'top_supplier_nome', v_top_supplier, 'top_supplier_count', v_top_count,
    'variacoes_ativas_zero_com_previsao', v_ativas, 'variacoes_aguardando_lote', v_aguardando,
    'pct_variacoes_com_reposicao', v_pct_ativas, 'gerado_em', now(), 'versao', 'v3_stable_20260619'
  );
END;
$$;

-- ─── 4. ACL hardening ───────────────────────────────────────────
REVOKE EXECUTE ON FUNCTION public.fn_get_reposicao_listing(uuid, uuid, text, integer, integer, integer) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_get_reposicao_listing(uuid, uuid, text, integer, integer, integer) FROM anon;
GRANT  EXECUTE ON FUNCTION public.fn_get_reposicao_listing(uuid, uuid, text, integer, integer, integer) TO authenticated;

REVOKE EXECUTE ON FUNCTION public.fn_get_replenishment_stats() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_get_replenishment_stats() FROM anon;
GRANT  EXECUTE ON FUNCTION public.fn_get_replenishment_stats() TO authenticated;

REVOKE EXECUTE ON FUNCTION public.fn_get_reposicao_metrics() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_get_reposicao_metrics() FROM anon;
GRANT  EXECUTE ON FUNCTION public.fn_get_reposicao_metrics() TO authenticated;

NOTIFY pgrst, 'reload schema';
;

