-- >>> BEGIN 20260619112613_fix_favorites_module.sql >>>

-- BUG #1: fix unique index (COALESCE expression breaks PostgREST upsert → 42P10)
DROP INDEX IF EXISTS public.uniq_fi_list_product_variant;

CREATE UNIQUE INDEX uniq_fi_list_product_variant
  ON public.favorite_items USING btree (list_id, product_id, variant_id)
  NULLS NOT DISTINCT;

-- BUG #2: race-safe ensure_default_favorite_list
CREATE OR REPLACE FUNCTION public.ensure_default_favorite_list(_user_id uuid)
RETURNS uuid
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
  v_list_id uuid;
BEGIN
  SELECT id INTO v_list_id
  FROM public.favorite_lists
  WHERE user_id = _user_id AND is_default = true
  LIMIT 1;

  IF v_list_id IS NOT NULL THEN
    RETURN v_list_id;
  END IF;

  BEGIN
    INSERT INTO public.favorite_lists (
      user_id, name, description, color, icon, is_default, position
    ) VALUES (
      _user_id, 'Meus Favoritos', 'Lista padrão de favoritos', '#3B82F6', 'Heart', true, 0
    )
    RETURNING id INTO v_list_id;
  EXCEPTION WHEN unique_violation THEN
    SELECT id INTO v_list_id
    FROM public.favorite_lists
    WHERE user_id = _user_id AND is_default = true
    LIMIT 1;
  END;

  RETURN v_list_id;
END;
$$;

-- BUG #3: soft-delete trigger SECURITY DEFINER (coordinators deleting other users' items)
CREATE OR REPLACE FUNCTION public.fn_favorite_items_soft_delete()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  INSERT INTO public.favorite_items_trash (
    original_id, list_id, user_id, product_id, variant_id,
    variant_info, note, price_at_save, position, added_at, deleted_at
  ) VALUES (
    OLD.id, OLD.list_id, OLD.user_id, OLD.product_id, OLD.variant_id,
    OLD.variant_info, OLD.note, OLD.price_at_save, OLD.position, OLD.added_at, now()
  )
  ON CONFLICT DO NOTHING;
  RETURN OLD;
END;
$$;

-- BUG #4: atomic restore-from-trash RPC
CREATE OR REPLACE FUNCTION public.restore_favorite_from_trash(
  _trash_id        uuid,
  _user_id         uuid,
  _fallback_list_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
  v_trash           public.favorite_items_trash%ROWTYPE;
  v_list_id         uuid;
  v_item_id         uuid;
  v_original_list   uuid;
BEGIN
  SELECT * INTO v_trash
  FROM public.favorite_items_trash
  WHERE id = _trash_id AND user_id = _user_id;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not-found');
  END IF;

  v_original_list := v_trash.list_id;

  SELECT id INTO v_list_id
  FROM public.favorite_lists
  WHERE id = v_trash.list_id
    AND user_id = _user_id
    AND is_archived = false;

  IF v_list_id IS NULL AND _fallback_list_id IS NOT NULL THEN
    SELECT id INTO v_list_id
    FROM public.favorite_lists
    WHERE id = _fallback_list_id
      AND user_id = _user_id
      AND is_archived = false;
  END IF;

  IF v_list_id IS NULL THEN
    v_list_id := public.ensure_default_favorite_list(_user_id);
  END IF;

  INSERT INTO public.favorite_items (
    list_id, user_id, product_id, variant_id, variant_info,
    note, price_at_save
  ) VALUES (
    v_list_id, _user_id, v_trash.product_id, v_trash.variant_id, v_trash.variant_info,
    v_trash.note, v_trash.price_at_save
  )
  ON CONFLICT (list_id, product_id, variant_id) DO NOTHING
  RETURNING id INTO v_item_id;

  DELETE FROM public.favorite_items_trash WHERE id = _trash_id;

  RETURN jsonb_build_object(
    'ok', true,
    'item_id', v_item_id,
    'list_id', v_list_id,
    'original_list_changed', (v_list_id IS DISTINCT FROM v_original_list)
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.restore_favorite_from_trash(uuid, uuid, uuid)
  TO authenticated;
;

-- <<< END 20260619112613_fix_favorites_module.sql <<<

-- >>> BEGIN 20260619113038_expand_acl_whitelist_bestseller_20260619.sql >>>
-- Adicionar get_catalog_bestseller_page e get_promo_sales_ranking à whitelist
-- Ambas são funções de catálogo público legítimas criadas/atualizadas pelo Lovable.
CREATE OR REPLACE FUNCTION public.audit_security_definer_acl()
RETURNS TABLE(function_name text, arguments text, problem text, granted_to text)
LANGUAGE sql
STABLE
SET search_path TO 'public', 'pg_catalog'
AS $function$
  WITH defs AS (
    SELECT
      p.oid, p.proname,
      pg_get_function_identity_arguments(p.oid) AS args,
      p.proacl,
      (pg_get_function_result(p.oid) = 'trigger') AS is_trigger,
      (p.proname IN (
        'submit_quote_response',
        'get_quote_token_by_value',
        'check_login_rate_limit'
      )) AS public_intent,
      (p.proname IN (
        'fn_video_queue_next','fn_xbz_enqueue_videos','fn_xbz_link_video',
        'fn_asia_link_video','fn_video_link_to_products','fn_sm_link_video',
        'fn_spot_enqueue_new_videos','fn_spot_enqueue_vimeo_eu','fn_spot_link_video',
        'fn_spot_vimeo_daily_sync','fn_video_link','fn_video_queue_old_uid',
        'fn_video_queue_recover_stuck','fn_video_queue_update','fn_video_retry_errors',
        'fn_video_set_dimensions','fn_video_sim_export','fn_video_sim_upsert'
      )) AS anon_pipeline,
      (p.proname IN (
        'fn_check_login_allowed','fn_bulk_update_image_dimensions','fn_cf_audit_ingest',
        'fn_save_ai_enrichment_results','fn_dequeue_ai_enrichment','fn_enqueue_ai_enrichment'
      )) AS anon_edge,
      (p.proname IN (
        'mcp_kv_get','mcp_kv_set','mcp_kv_try_lock'
      )) AS anon_mcp,
      (p.proname IN (
        -- Super Filtro
        'fn_super_filtro','fn_super_filtro_facets','fn_super_filtro_opcoes',
        'fn_super_filtro_price_range','fn_super_filtro_product_ids',
        -- Catálogo público
        'fn_get_all_leaf_categories','fn_get_product_intelligence_all',
        'fn_get_category_breadcrumb','fn_log_search_analytics',
        'get_promo_sales_ranking','get_catalog_bestseller_page',  -- ← NOVO
        -- Reposição/análise
        'fn_get_reposicao_listing','fn_get_reposicao_metrics',
        'fn_get_recent_restocks','fn_get_replenishment_stats'
      )) AS catalog_intent
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.prosecdef = true
  ),
  acl_expanded AS (
    SELECT d.oid, d.proname, d.args, d.is_trigger,
           d.public_intent, d.anon_pipeline, d.anon_edge, d.anon_mcp,
           d.catalog_intent,
           a.grantee::regrole::text AS grantee
    FROM defs d
    LEFT JOIN LATERAL (SELECT (aclexplode(d.proacl)).grantee) a ON true
    WHERE a.grantee IS NOT NULL
  ),
  policy_uses AS (
    SELECT DISTINCT d.oid, d.proname, d.args
    FROM defs d
    JOIN pg_policies pp
      ON pp.schemaname = 'public'
      AND (
        COALESCE(pp.qual, '') ~ ('\m' || d.proname || '\M')
        OR COALESCE(pp.with_check, '') ~ ('\m' || d.proname || '\M')
      )
  )
  SELECT proname, args, 'PUBLIC has EXECUTE'::text, 'PUBLIC'::text
  FROM acl_expanded
  WHERE grantee = '-'
    AND NOT (public_intent OR catalog_intent OR anon_pipeline OR anon_edge OR anon_mcp)
  UNION ALL
  SELECT proname, args, 'anon has EXECUTE (not in public-intent whitelist)'::text, 'anon'
  FROM acl_expanded
  WHERE grantee = 'anon'
    AND NOT (public_intent OR catalog_intent OR anon_pipeline OR anon_edge OR anon_mcp)
  UNION ALL
  SELECT proname, args, 'trigger function has EXECUTE for authenticated'::text, 'authenticated'
  FROM acl_expanded
  WHERE grantee = 'authenticated' AND is_trigger
  UNION ALL
  SELECT pu.proname, pu.args,
         'used in RLS policy but missing EXECUTE for authenticated (RLS will fail with 42501)'::text,
         'authenticated (MISSING)'::text
  FROM policy_uses pu
  WHERE NOT EXISTS (
    SELECT 1 FROM acl_expanded a
    WHERE a.oid = pu.oid AND a.grantee = 'authenticated'
  )
  ORDER BY 1, 2;
$function$;

GRANT EXECUTE ON FUNCTION public.audit_security_definer_acl() TO authenticated;

SELECT 
  COUNT(*) FILTER (WHERE granted_to = 'PUBLIC') AS public_violations,
  COUNT(*) FILTER (WHERE granted_to = 'anon') AS anon_violations,
  COUNT(*) AS total
FROM public.audit_security_definer_acl();
;

-- <<< END 20260619113038_expand_acl_whitelist_bestseller_20260619.sql <<<

-- >>> BEGIN 20260619113123_fix_gaps_j5_and_c6_20260619.sql >>>
-- Migration: fix_gaps_j5_and_c6_20260619
-- Purpose: Close two gaps found in exhaustive round-3 simulation (250+ scenarios)
--
--   GAP-J5: fn_prevent_canonical_chain did NOT check if target canonical was soft-deleted.
--           Both INSERT and UPDATE paths could create dep→deleted_root (C13 violation).
--           Fix: add deleted_at check inside fn_prevent_canonical_chain; if target is
--           soft-deleted, clear canonical_image_id and is_shared before any chain logic.
--
--   GAP-C6: fn_autolink_canonical_on_content_hash "first-set" branch respected existing
--           canonical_image_id even when it pointed to a different hash group.
--           Scenario: row had NULL hash + manual canonical assigned, then hash was set
--           to a different group → row stayed in wrong canonical group, undetected.
--           Fix: in first-set branch, validate canonical's content_hash matches NEW.content_hash;
--           if mismatch → fall through to re-link to correct group.

BEGIN;

-- ══════════════════════════════════════════════════════════════════════
-- FIX GAP-J5: Enhanced canonical chain prevention
-- Also handles UPDATE path (trigger already fired; function shared by INSERT+UPDATE triggers)
-- ══════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_prevent_canonical_chain()
RETURNS TRIGGER LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
DECLARE
  v_target_canonical uuid;
  v_target_deleted_at timestamptz;
BEGIN
  -- Fetch target's own canonical and deleted_at in a single lookup
  SELECT canonical_image_id, deleted_at
  INTO v_target_canonical, v_target_deleted_at
  FROM public.product_images
  WHERE id = NEW.canonical_image_id;

  -- GAP-J5: target is soft-deleted → clear to prevent C13 violation
  IF v_target_deleted_at IS NOT NULL THEN
    NEW.canonical_image_id := NULL;
    NEW.is_shared := false;
    RETURN NEW;
  END IF;

  -- GAP-D: target is itself a dep (non-root) → flatten to the root
  IF v_target_canonical IS NOT NULL THEN
    NEW.canonical_image_id := v_target_canonical;
  END IF;

  -- Prevent self-referential assignment
  IF NEW.canonical_image_id = NEW.id THEN
    NEW.canonical_image_id := NULL;
    NEW.is_shared := false;
  END IF;

  RETURN NEW;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_prevent_canonical_chain() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_prevent_canonical_chain() TO service_role;

-- ══════════════════════════════════════════════════════════════════════
-- FIX GAP-C6: Enhanced autolink with cross-group canonical validation
-- ══════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_autolink_canonical_on_content_hash()
RETURNS TRIGGER LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
DECLARE
  v_root_id uuid;
  v_existing_canonical_hash text;
BEGIN
  -- Only act when content_hash is being set or changed
  IF NEW.content_hash IS NULL OR (OLD.content_hash IS NOT NULL AND OLD.content_hash = NEW.content_hash) THEN
    RETURN NEW;
  END IF;

  -- If image already has a canonical assignment:
  IF NEW.canonical_image_id IS NOT NULL THEN
    IF OLD.content_hash IS NOT NULL AND OLD.content_hash IS DISTINCT FROM NEW.content_hash THEN
      -- Hash CHANGED (not first-set): clear old canonical so we re-link to correct group
      NEW.canonical_image_id := NULL;
      NEW.is_shared := false;
      -- Fall through to find new root for new hash
    ELSE
      -- First-set (OLD.content_hash was NULL): validate canonical belongs to SAME hash group
      -- GAP-C6: existing canonical may point to a different-hash group
      SELECT content_hash INTO v_existing_canonical_hash
      FROM public.product_images
      WHERE id = NEW.canonical_image_id;

      IF v_existing_canonical_hash IS NOT DISTINCT FROM NEW.content_hash THEN
        -- Same hash group: respect existing canonical
        RETURN NEW;
      END IF;
      -- Wrong hash group: fall through to re-link to correct root
      NEW.canonical_image_id := NULL;
      NEW.is_shared := false;
    END IF;
  END IF;

  -- Find the oldest root in the group (is_shared=false, canonical_image_id=NULL)
  SELECT id INTO v_root_id
  FROM public.product_images
  WHERE content_hash = NEW.content_hash
    AND deleted_at IS NULL
    AND canonical_image_id IS NULL
    AND id <> NEW.id
    AND is_shared = false
  ORDER BY created_at ASC, id ASC
  LIMIT 1;

  IF v_root_id IS NOT NULL THEN
    NEW.canonical_image_id := v_root_id;
    NEW.is_shared := true;
  ELSE
    -- Fallback: inherit root from existing dependent in same group
    SELECT pi2.canonical_image_id INTO v_root_id
    FROM public.product_images pi2
    WHERE pi2.content_hash = NEW.content_hash
      AND pi2.deleted_at IS NULL
      AND pi2.canonical_image_id IS NOT NULL
      AND pi2.id <> NEW.id
    LIMIT 1;

    IF v_root_id IS NOT NULL THEN
      NEW.canonical_image_id := v_root_id;
      NEW.is_shared := true;
    END IF;
    -- If only member → remain as standalone root
  END IF;

  RETURN NEW;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_autolink_canonical_on_content_hash() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_autolink_canonical_on_content_hash() TO service_role;

COMMIT;;

-- <<< END 20260619113123_fix_gaps_j5_and_c6_20260619.sql <<<

-- >>> BEGIN 20260619113207_fix_gap_c5_add_c16_20260619.sql >>>
-- Migration: fix_gap_c5_add_c16_20260619
-- Purpose: Close GAP-C5 and add C16 health-check invariant.
--
--   GAP-C5: When a ROOT's content_hash changes and fn_autolink re-assigns it as a
--           dependent of a new root, any rows that previously pointed to that old root
--           still do so — creating dep→dep chains (C07 violation).
--           Fix: AFTER trigger on UPDATE OF canonical_image_id; fires when a row
--           transitions from root (NULL canonical) to dep (non-NULL canonical).
--           Re-links all former deps to the new root.
--
--   C16:    New health-check invariant: deps whose content_hash does not match their
--           canonical's content_hash (cross-group canonical). This catches GAP-C6
--           residual violations and any future manual mis-assignments.

BEGIN;

-- ══════════════════════════════════════════════════════════════════════
-- FIX GAP-C5: Re-link former deps when a root becomes a dep
-- ══════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_relink_former_deps_on_root_becomes_dep()
RETURNS TRIGGER LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
BEGIN
  -- Only act when this row WAS a root and NOW became a dep.
  -- OLD.canonical_image_id IS NULL  → was root
  -- NEW.canonical_image_id IS NOT NULL → now dep
  IF OLD.canonical_image_id IS NOT NULL OR NEW.canonical_image_id IS NULL THEN
    RETURN NULL;
  END IF;

  -- Re-link all live rows that still point to this (now non-root) row.
  -- Point them directly to the new root to restore flat chains.
  UPDATE public.product_images
  SET canonical_image_id = NEW.canonical_image_id,
      updated_at          = now()
  WHERE canonical_image_id = NEW.id
    AND id <> NEW.id
    AND deleted_at IS NULL;

  RETURN NULL;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_relink_former_deps_on_root_becomes_dep() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_relink_former_deps_on_root_becomes_dep() TO service_role;

DROP TRIGGER IF EXISTS trg_relink_former_deps_on_root_becomes_dep ON public.product_images;
CREATE TRIGGER trg_relink_former_deps_on_root_becomes_dep
  AFTER UPDATE OF canonical_image_id
  ON public.product_images
  FOR EACH ROW
  WHEN (OLD.canonical_image_id IS NULL AND NEW.canonical_image_id IS NOT NULL)
  EXECUTE FUNCTION public.fn_relink_former_deps_on_root_becomes_dep();

-- ══════════════════════════════════════════════════════════════════════
-- C16: New health-check invariant — cross-group canonical detection
-- ══════════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_product_images_health_check()
RETURNS TABLE(check_name text, status text, value bigint, threshold bigint, details text)
LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $function$
BEGIN
  -- C01: Todas as imagens ativas são verified no CF
  RETURN QUERY SELECT
    'c01_all_active_verified'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images not verified in CF'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND cf_sync_status <> 'verified';

  -- C02: Zero orphans no CF (CF tem imagem sem produto)
  RETURN QUERY SELECT
    'c02_zero_cf_orphans'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'CF images not in product_images'::text
  FROM cf_recon.cf_image c
  WHERE NOT EXISTS (SELECT 1 FROM public.product_images p
    WHERE p.cloudflare_image_id = c.image_id AND p.deleted_at IS NULL);

  -- C03: Recon = product_images ativas
  RETURN QUERY SELECT
    'c03_recon_pi_sync'::text,
    CASE WHEN ABS(c.recon_total - c.pi_total) = 0 THEN 'OK' ELSE 'WARN' END,
    ABS(c.recon_total - c.pi_total), 5::bigint,
    'Difference between cf_recon.cf_image and active product_images'::text
  FROM (SELECT
    (SELECT COUNT(*) FROM cf_recon.cf_image) AS recon_total,
    (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL) AS pi_total
  ) c;

  -- C04: Sem cloudflare_image_id duplicados
  RETURN QUERY SELECT
    'c04_no_duplicate_cf_id'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Duplicate cloudflare_image_id in active images'::text
  FROM (SELECT cloudflare_image_id
    FROM public.product_images WHERE deleted_at IS NULL
    GROUP BY cloudflare_image_id HAVING COUNT(*) > 1) dup;

  -- C05: Soft-delete sempre tem razão
  RETURN QUERY SELECT
    'c05_soft_delete_has_reason'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Soft-deleted images without deleted_reason'::text
  FROM public.product_images
  WHERE deleted_at IS NOT NULL AND (deleted_reason IS NULL OR deleted_reason = '');

  -- C06: Sem is_active=true em deletadas
  RETURN QUERY SELECT
    'c06_no_active_deleted'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active=true but soft-deleted images'::text
  FROM public.product_images
  WHERE deleted_at IS NOT NULL AND is_active = true;

  -- C07: Cadeias canônicas flat (sem encadeamento)
  RETURN QUERY SELECT
    'c07_canonical_chains_flat'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical pointing to non-root (chain detected)'::text
  FROM public.product_images pi_child
  JOIN public.product_images pi_root ON pi_root.id = pi_child.canonical_image_id
  WHERE pi_child.canonical_image_id IS NOT NULL AND pi_root.canonical_image_id IS NOT NULL;

  -- C08: Sem ciclos canônicos
  RETURN QUERY SELECT
    'c08_no_canonical_cycles'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical cycles detected (A→B, B→A)'::text
  FROM public.product_images a
  JOIN public.product_images b ON b.id = a.canonical_image_id AND b.canonical_image_id = a.id;

  -- C09: is_shared consistência
  RETURN QUERY SELECT
    'c09_shared_has_canonical'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'is_shared=true without canonical_image_id'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND is_shared = true AND canonical_image_id IS NULL;

  -- C10: URL CDN válida
  RETURN QUERY SELECT
    'c10_valid_cdn_urls'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with invalid url_cdn'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND (url_cdn IS NULL OR url_cdn NOT LIKE 'https://imagedelivery.net/%');

  -- C11: Format válido (sem null)
  RETURN QUERY SELECT
    'c11_no_null_format'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with NULL format'::text
  FROM public.product_images WHERE deleted_at IS NULL AND format IS NULL;

  -- C12: Alt-text cobertura (≥10 chars)
  RETURN QUERY SELECT
    'c12_alt_text_coverage'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with missing/short alt_text'::text
  FROM public.product_images
  WHERE deleted_at IS NULL AND (alt_text IS NULL OR LENGTH(alt_text) < 10);

  -- C13: Canonical não aponta para imagem deletada
  RETURN QUERY SELECT
    'c13_canonical_not_deleted'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Canonical pointing to soft-deleted image'::text
  FROM public.product_images pi
  WHERE pi.canonical_image_id IS NOT NULL
    AND EXISTS (SELECT 1 FROM public.product_images root
      WHERE root.id = pi.canonical_image_id AND root.deleted_at IS NOT NULL);

  -- C14: Display_order sem nulos
  RETURN QUERY SELECT
    'c14_display_order_not_null'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Active images with NULL display_order'::text
  FROM public.product_images WHERE deleted_at IS NULL AND display_order IS NULL;

  -- C15: products.primary_image_url em sync
  RETURN QUERY SELECT
    'c15_primary_image_url_sync'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'WARN' END,
    COUNT(*), 5::bigint,
    'Products where primary_image_url diverges from product_images primary'::text
  FROM public.products p
  JOIN public.product_images pi ON pi.product_id = p.id
    AND pi.is_primary = true AND pi.is_active = true AND pi.deleted_at IS NULL
  WHERE p.is_active = true AND (p.is_deleted IS NULL OR p.is_deleted = false)
    AND p.primary_image_url IS NOT NULL AND p.primary_image_url <> pi.url_cdn;

  -- C16: Deps whose content_hash does not match their canonical's content_hash (cross-group)
  -- Catches GAP-C6 residual violations and any future manual mis-assignments
  RETURN QUERY SELECT
    'c16_canonical_hash_group_consistent'::text,
    CASE WHEN COUNT(*) = 0 THEN 'OK' ELSE 'FAIL' END,
    COUNT(*), 0::bigint,
    'Deps with content_hash mismatching their canonical group hash'::text
  FROM public.product_images dep
  JOIN public.product_images canon ON canon.id = dep.canonical_image_id
  WHERE dep.deleted_at IS NULL
    AND dep.canonical_image_id IS NOT NULL
    AND dep.content_hash IS NOT NULL
    AND canon.content_hash IS NOT NULL
    AND dep.content_hash <> canon.content_hash;

END;
$function$;

REVOKE EXECUTE ON FUNCTION public.fn_product_images_health_check() FROM anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_product_images_health_check() TO service_role;

COMMIT;;

