-- >>> BEGIN 20260619155129_56cf9912-fdc6-415c-84f4-3831d472d829.sql >>>
DO $$
DECLARE
  r record;
  whitelist text[] := ARRAY[
    'has_role','has_org_role','get_user_org_ids','is_admin','is_admin_strict','is_dev',
    'is_manager_or_admin','is_supervisor_or_above','is_kit_owner','is_kit_collaborator',
    'is_org_member','is_seller_only','can_approve_discount','can_manage_quotes',
    'can_view_all_sales','can_view_audit_logs','can_view_connections','can_view_telemetry',
    'can_manage_connections',
    'get_bundle_suggestions','get_top_collected_products','get_top_favorited_products',
    'get_top_compared_products','get_user_recent_comparisons','get_collections_weekly_count',
    'get_favorites_weekly_count','get_client_top_products','get_client_seasonality',
    'get_industry_top_products','get_industry_benchmark_stats','ensure_default_favorite_list',
    'restore_favorite_from_trash','check_ai_quota','check_hardening_status',
    'can_grant_mcp_full','check_telemetry_regression','get_app_health_summary',
    'lookup_request_id','get_platform_failure_metrics','get_auto_test_job_status',
    'get_connection_failure_window_minutes','set_connection_failure_window_minutes',
    'get_connections_auto_test_interval','set_connections_auto_test_interval',
    'execute_role_migration_batch','record_dev_route_telemetry','log_rls_denial',
    'log_user_logout','repair_ownership_orphans','search_records_rerank','fn_my_rpc',
    'audit_security_definer_acl'
  ];
BEGIN
  FOR r IN
    SELECT p.oid, p.proname, pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prosecdef = true
      AND NOT (p.proname = ANY (whitelist))
      AND (has_function_privilege('authenticated', p.oid, 'EXECUTE')
        OR has_function_privilege('anon', p.oid, 'EXECUTE'))
  LOOP
    EXECUTE format('REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM authenticated, anon, PUBLIC',
                   r.proname, r.args);
    EXECUTE format('GRANT EXECUTE ON FUNCTION public.%I(%s) TO service_role',
                   r.proname, r.args);
  END LOOP;
END $$;
-- <<< END 20260619155129_56cf9912-fdc6-415c-84f4-3831d472d829.sql <<<

-- >>> BEGIN 20260619160500_062cd222-4cdd-4fe5-a2f4-2a24d0bdc023.sql >>>
-- Onda 7 (corrigida) — RLS WITH CHECK em password_reset_requests + frontend_telemetry

-- 1) password_reset_requests
DO $$
DECLARE pol record;
BEGIN
  FOR pol IN
    SELECT policyname FROM pg_policies
     WHERE schemaname='public' AND tablename='password_reset_requests' AND cmd='INSERT'
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.password_reset_requests', pol.policyname);
  END LOOP;
END $$;

CREATE POLICY "prr_insert_validated"
  ON public.password_reset_requests
  FOR INSERT
  TO anon, authenticated
  WITH CHECK (
    email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
    AND length(email) <= 320
    AND NOT EXISTS (
      SELECT 1 FROM public.password_reset_requests prr
       WHERE lower(prr.email) = lower(password_reset_requests.email)
         AND prr.requested_at > now() - interval '60 seconds'
    )
  );

-- 2) frontend_telemetry
DO $$
DECLARE pol record;
BEGIN
  FOR pol IN
    SELECT policyname FROM pg_policies
     WHERE schemaname='public' AND tablename='frontend_telemetry' AND cmd='INSERT'
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.frontend_telemetry', pol.policyname);
  END LOOP;
END $$;

CREATE POLICY "ft_insert_validated"
  ON public.frontend_telemetry
  FOR INSERT
  TO anon, authenticated
  WITH CHECK (
    event_type IN ('page_view','web_vital','error','perf','interaction')
    AND length(coalesce(metadata::text, '')) < 8000
  );

-- <<< END 20260619160500_062cd222-4cdd-4fe5-a2f4-2a24d0bdc023.sql <<<

-- >>> BEGIN 20260619181554_fix_event_trigger_whitelist_and_restore_anon_grants_20260619.sql >>>
-- ============================================================================
-- FIX CRÍTICO: Restaurar anon EXECUTE nas 4 funções afetadas pelo event trigger
-- + Expandir whitelist do trigger para cobrir TODAS as funções legítimas
--
-- Causa raiz: evt_auto_revoke_secdef_public_execute tem whitelist incompleta.
-- Quando migrations recriaram fn_get_reposicao_listing e fn_xbz_enqueue_videos,
-- o trigger revogou o anon EXECUTE dessas funções.
-- ============================================================================

-- 1. Restaurar EXECUTE para anon nas funções afetadas
GRANT EXECUTE ON FUNCTION public.fn_get_reposicao_listing(uuid, uuid, text, integer, integer, integer) TO anon;
GRANT EXECUTE ON FUNCTION public.fn_get_reposicao_metrics() TO anon;
GRANT EXECUTE ON FUNCTION public.fn_get_replenishment_stats() TO anon;
GRANT EXECUTE ON FUNCTION public.fn_xbz_enqueue_videos() TO anon;

-- 2. Atualizar o event trigger com whitelist completa
CREATE OR REPLACE FUNCTION public.fn_auto_revoke_secdef_public_execute()
RETURNS event_trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_catalog
AS $function$
DECLARE
  obj          record;
  func_name    text;
  func_args    text;
  is_secdef    boolean;
  is_whitelisted boolean;
BEGIN
  FOR obj IN
    SELECT object_type, schema_name, object_identity, objid
    FROM pg_event_trigger_ddl_commands()
    WHERE object_type IN ('function', 'procedure')
      AND schema_name = 'public'
  LOOP
    SELECT p.prosecdef INTO is_secdef
    FROM pg_proc p WHERE p.oid = obj.objid;
    IF NOT is_secdef THEN CONTINUE; END IF;

    SELECT p.proname, pg_get_function_identity_arguments(p.oid)
    INTO func_name, func_args
    FROM pg_proc p WHERE p.oid = obj.objid;

    -- ════════════════════════════════════════════════════════
    -- WHITELIST COMPLETA (funções com acesso público legítimo)
    -- ════════════════════════════════════════════════════════
    is_whitelisted := func_name IN (
      -- Super Filtro (catálogo público)
      'fn_super_filtro', 'fn_super_filtro_facets', 'fn_super_filtro_opcoes',
      'fn_super_filtro_price_range', 'fn_super_filtro_product_ids',
      -- Catálogo e navegação
      'fn_get_all_leaf_categories', 'fn_get_product_intelligence_all',
      'fn_get_category_breadcrumb', 'fn_log_search_analytics',
      'get_promo_sales_ranking', 'get_catalog_bestseller_page',
      'fn_get_catalog_page', 'fn_get_product_detail',
      -- Reposição/análise (EXPANDIDA — afetadas pelo trigger)
      'fn_get_reposicao_listing', 'fn_get_reposicao_metrics',
      'fn_get_recent_restocks', 'fn_get_replenishment_stats',
      -- Pipeline vídeo VPS/n8n (EXPANDIDA)
      'fn_video_queue_next', 'fn_xbz_enqueue_videos', 'fn_xbz_link_video',
      'fn_asia_link_video', 'fn_video_link_to_products', 'fn_sm_link_video',
      'fn_spot_enqueue_new_videos', 'fn_spot_enqueue_vimeo_eu', 'fn_spot_link_video',
      'fn_spot_vimeo_daily_sync', 'fn_video_link', 'fn_video_queue_old_uid',
      'fn_video_queue_recover_stuck', 'fn_video_queue_update', 'fn_video_retry_errors',
      'fn_video_set_dimensions', 'fn_video_sim_export', 'fn_video_sim_upsert',
      -- Edge functions via anon key
      'fn_check_login_allowed', 'fn_bulk_update_image_dimensions', 'fn_cf_audit_ingest',
      'fn_save_ai_enrichment_results', 'fn_dequeue_ai_enrichment', 'fn_enqueue_ai_enrichment',
      -- MCP KV
      'mcp_kv_get', 'mcp_kv_set', 'mcp_kv_try_lock',
      -- Auth pública
      'submit_quote_response', 'get_quote_token_by_value', 'check_login_rate_limit',
      -- Color matching (público via APIs)
      'fn_match_canonical_color',
      -- Meta (funções do próprio sistema de auditoria)
      'fn_auto_revoke_secdef_public_execute',
      'fn_revoke_view_write_grants_on_create',
      'audit_security_definer_acl',
      'fn_get_edge_functions_base_url',
      'get_edge_functions_base_url',
      'get_edge_anon_key',
      'get_edge_function_secret'
    );

    IF NOT is_whitelisted THEN
      BEGIN
        IF func_args IS NOT NULL AND func_args != '' THEN
          EXECUTE format(
            'REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM PUBLIC, anon',
            func_name, func_args
          );
        ELSE
          EXECUTE format(
            'REVOKE EXECUTE ON FUNCTION public.%I() FROM PUBLIC, anon',
            func_name
          );
        END IF;
        RAISE NOTICE 'evt_auto_revoke_secdef: revoked EXECUTE on %.%(%) from PUBLIC, anon',
          'public', func_name, COALESCE(func_args, '');
      EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'evt_auto_revoke_secdef: could not revoke on %.%(%): %',
          'public', func_name, COALESCE(func_args, ''), SQLERRM;
      END;
    END IF;
  END LOOP;
END;
$function$;

-- 3. Atualizar a função audit_security_definer_acl() com whitelist expandida
CREATE OR REPLACE FUNCTION public.audit_security_definer_acl()
RETURNS TABLE(function_name text, arguments text, problem text, granted_to text)
LANGUAGE sql
STABLE
SET search_path TO 'public', 'pg_catalog'
AS $function$
  WITH defs AS (
    SELECT p.oid, p.proname, pg_get_function_identity_arguments(p.oid) AS args,
           p.proacl,
           (pg_get_function_result(p.oid) = 'trigger') AS is_trigger,
           (p.proname IN (
             'submit_quote_response','get_quote_token_by_value','check_login_rate_limit'
           )) AS public_intent,
           (p.proname IN (
             'fn_video_queue_next','fn_xbz_enqueue_videos','fn_xbz_link_video',
             'fn_asia_link_video','fn_video_link_to_products','fn_sm_link_video',
             'fn_spot_enqueue_new_videos','fn_spot_enqueue_vimeo_eu','fn_spot_link_video',
             'fn_spot_vimeo_daily_sync','fn_video_link','fn_video_queue_old_uid',
             'fn_video_queue_recover_stuck','fn_video_queue_update','fn_video_retry_errors',
             'fn_video_set_dimensions','fn_video_sim_export','fn_video_sim_upsert'
           )) AS anon_pipeline,
           (p.proname IN (
             'fn_check_login_allowed','fn_bulk_update_image_dimensions','fn_cf_audit_ingest',
             'fn_save_ai_enrichment_results','fn_dequeue_ai_enrichment','fn_enqueue_ai_enrichment'
           )) AS anon_edge,
           (p.proname IN (
             'mcp_kv_get','mcp_kv_set','mcp_kv_try_lock'
           )) AS anon_mcp,
           (p.proname IN (
             'fn_super_filtro','fn_super_filtro_facets','fn_super_filtro_opcoes',
             'fn_super_filtro_price_range','fn_super_filtro_product_ids',
             'fn_get_all_leaf_categories','fn_get_product_intelligence_all',
             'fn_get_category_breadcrumb','fn_log_search_analytics',
             'get_promo_sales_ranking','get_catalog_bestseller_page',
             'fn_get_reposicao_listing','fn_get_reposicao_metrics',
             'fn_get_recent_restocks','fn_get_replenishment_stats',
             'fn_match_canonical_color',
             'fn_auto_revoke_secdef_public_execute',
             'fn_revoke_view_write_grants_on_create',
             'audit_security_definer_acl',
             'fn_get_edge_functions_base_url',
             'get_edge_functions_base_url',
             'get_edge_anon_key',
             'get_edge_function_secret'
           )) AS catalog_intent
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.prosecdef = true
  ),
  acl_expanded AS (
    SELECT d.oid, d.proname, d.args, d.is_trigger,
           d.public_intent, d.anon_pipeline, d.anon_edge, d.anon_mcp, d.catalog_intent,
           a.grantee::regrole::text AS grantee
    FROM defs d
    LEFT JOIN LATERAL (SELECT (aclexplode(d.proacl)).grantee) a ON true
    WHERE a.grantee IS NOT NULL
  )
  SELECT proname, args, 'PUBLIC has EXECUTE'::text, 'PUBLIC'::text
  FROM acl_expanded
  WHERE grantee = '-'
    AND NOT (public_intent OR catalog_intent OR anon_pipeline OR anon_edge OR anon_mcp)
  UNION ALL
  SELECT proname, args, 'anon has EXECUTE (not in public-intent whitelist)'::text, 'anon'
  FROM acl_expanded
  WHERE grantee = 'anon'
    AND NOT (public_intent OR catalog_intent OR anon_pipeline OR anon_edge OR anon_mcp)
  UNION ALL
  SELECT proname, args, 'trigger function has EXECUTE for authenticated'::text, 'authenticated'
  FROM acl_expanded
  WHERE grantee = 'authenticated' AND is_trigger
  ORDER BY 1, 2;
$function$;

GRANT EXECUTE ON FUNCTION public.audit_security_definer_acl() TO authenticated;

NOTIFY pgrst, 'reload schema';

-- Verificação final
SELECT 
  COUNT(*) FILTER (WHERE granted_to = 'PUBLIC') AS public_violations,
  COUNT(*) FILTER (WHERE granted_to = 'anon') AS anon_violations,
  COUNT(*) FILTER (WHERE problem LIKE 'trigger%') AS trigger_noise
FROM public.audit_security_definer_acl();
;

-- <<< END 20260619181554_fix_event_trigger_whitelist_and_restore_anon_grants_20260619.sql <<<

-- >>> BEGIN 20260619200000_add_keyset_pagination_indexes.sql >>>
-- Keyset pagination indexes for stockFetcher.ts (fetchPaginatedFromBridge).
--
-- Pattern:  SELECT ... FROM <table> WHERE is_active = true AND id > $lastId
--           ORDER BY id ASC LIMIT 1000;
--
-- Without a partial index, PostgreSQL performs a full sequential scan filtered
-- by is_active and then sorts by id — O(N) for every page. With a partial index
-- on (id ASC) WHERE is_active = true, the planner uses a forward index scan
-- starting exactly at lastId, stopping after 1000 rows: O(page_size) per page.
--
-- Tables covered (all three have `is_active = true` filter in stockFetcher):
--   1. products              — filtered via v_products_public view (active alias)
--   2. product_variants      — is_active = true
--   3. variant_supplier_sources — is_active = true
--
-- categories / suppliers / product_images / mv_stock_velocity are fetched
-- without an is_active filter; their primary key already serves the keyset
-- ORDER BY id scan, so no extra index is needed.

-- 1. products: keyset scan WHERE is_active = true ORDER BY id
CREATE INDEX IF NOT EXISTS idx_products_keyset_active
  ON public.products (id ASC)
  WHERE is_active = true;

-- 2. product_variants: keyset scan WHERE is_active = true ORDER BY id
CREATE INDEX IF NOT EXISTS idx_product_variants_keyset_active
  ON public.product_variants (id ASC)
  WHERE is_active = true;

-- 3. variant_supplier_sources: keyset scan WHERE is_active = true ORDER BY id
CREATE INDEX IF NOT EXISTS idx_variant_supplier_sources_keyset_active
  ON public.variant_supplier_sources (id ASC)
  WHERE is_active = true;

-- <<< END 20260619200000_add_keyset_pagination_indexes.sql <<<

-- >>> BEGIN 20260619201113_20260619140400_cf_recon_close_stale_recover_url_remediation.sql >>>

-- Step 1: Backfill image_db_id from product_images via cloudflare_image_id
UPDATE cf_recon.remediation r
SET image_db_id = pi.id
FROM public.product_images pi
WHERE pi.cloudflare_image_id = r.cf_image_id
  AND r.kind = 'recover_url_original'
  AND r.status = 'open'
  AND r.image_db_id IS NULL;

-- Step 2: Backfill product_id from product_images after image_db_id is set
UPDATE cf_recon.remediation r
SET product_id = pi.product_id
FROM public.product_images pi
WHERE pi.id = r.image_db_id
  AND r.kind = 'recover_url_original'
  AND r.status = 'open'
  AND r.product_id IS NULL;

-- Step 3: Log all closures to action_log (immutable audit trail)
INSERT INTO cf_recon.action_log
  (actor, action, image_db_id, cf_image_id, product_id,
   old_status, new_status, evidence, reversible)
SELECT
  'claude',
  'close_stale_remediation',
  r.image_db_id,
  r.cf_image_id,
  r.product_id,
  'remediation_open',
  'remediation_done',
  jsonb_build_object(
    'reason',           'pipeline_verified_since_remediation_opened',
    'remediation_id',   r.id,
    'kind',             r.kind,
    'pi_cf_sync_status', pi.cf_sync_status,
    'pi_is_active',     pi.is_active,
    'pi_id',            pi.id,
    'migration',        '20260619140400_cf_recon_close_stale_recover_url_remediation'
  ),
  false
FROM cf_recon.remediation r
JOIN public.product_images pi ON pi.id = r.image_db_id
WHERE r.kind = 'recover_url_original'
  AND r.status = 'open';

-- Step 4: Close the remediations
UPDATE cf_recon.remediation
SET status = 'done'
WHERE kind = 'recover_url_original'
  AND status = 'open';
;

