-- ── Utility: general-purpose chain repair function ─────────────────────────────
CREATE OR REPLACE FUNCTION public.fn_repair_canonical_chains(p_max_iterations int DEFAULT 10)
RETURNS TABLE(iterations_run int, chains_repaired bigint)
LANGUAGE plpgsql
SECURITY DEFINER SET search_path = pg_catalog, public
AS $$
DECLARE
  v_iteration  int := 0;
  v_repaired   bigint;
  v_total      bigint := 0;
BEGIN
  LOOP
    v_iteration := v_iteration + 1;
    EXIT WHEN v_iteration > p_max_iterations;

    WITH chains AS (
      SELECT
        child.id                         AS child_id,
        mid.canonical_image_id           AS true_root_id
      FROM public.product_images child
      JOIN public.product_images mid ON mid.id = child.canonical_image_id
      WHERE child.canonical_image_id IS NOT NULL
        AND mid.canonical_image_id IS NOT NULL
        AND child.deleted_at IS NULL
      LIMIT 10000
    )
    UPDATE public.product_images pi
    SET canonical_image_id   = c.true_root_id,
        last_modified_source = 'migration',
        updated_at           = now()
    FROM chains c
    WHERE pi.id = c.child_id;

    GET DIAGNOSTICS v_repaired = ROW_COUNT;
    v_total := v_total + v_repaired;

    EXIT WHEN v_repaired = 0;
  END LOOP;

  RETURN QUERY SELECT v_iteration, v_total;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.fn_repair_canonical_chains(int) FROM anon, authenticated;
GRANT  EXECUTE ON FUNCTION public.fn_repair_canonical_chains(int) TO service_role;

-- ── Self-test: verify C07 = 0 after repair ─────────────────────────────────────
DO $$
DECLARE v_chains bigint;
BEGIN
  SELECT COUNT(*) INTO v_chains
  FROM public.product_images pi_child
  JOIN public.product_images pi_root ON pi_root.id = pi_child.canonical_image_id
  WHERE pi_child.canonical_image_id IS NOT NULL
    AND pi_root.canonical_image_id IS NOT NULL;

  IF v_chains <> 0 THEN
    RAISE EXCEPTION 'post-repair C07 assertion failed: % chains remain', v_chains;
  END IF;
END;
$$;;

-- <<< END 20260619201221_fix_c07_flatten_chains_20260619.sql <<<

-- >>> BEGIN 20260619201336_20260619140500_cf_recon_fix_v_divergence_circular.sql >>>

CREATE OR REPLACE VIEW cf_recon.v_divergence AS
SELECT
    pi.id                                                          AS db_id,
    pi.cloudflare_image_id,
    pi.cf_sync_status,
    pi.cf_id_scheme,
    pi.source_supplier,
    pi.is_active,
    pi.deleted_at IS NOT NULL                                      AS is_deleted,
    ci.image_id IS NOT NULL                                        AS exists_in_cf,
    CASE
        WHEN ci.image_id IS NOT NULL
             AND ci.crawl_run_id IS NOT NULL
             AND pi.cf_sync_status = 'verified'                    THEN 'ok'
        WHEN ci.image_id IS NOT NULL
             AND ci.crawl_run_id IS NULL
             AND pi.cf_sync_status = 'verified'                    THEN 'ok_pending_crawl_confirmation'
        WHEN ci.image_id IS NOT NULL
             AND pi.cf_sync_status <> 'verified'                   THEN 'cf_present_db_unverified'
        WHEN ci.image_id IS NULL
             AND pi.deleted_at IS NOT NULL                         THEN 'deleted_noise'
        WHEN ci.image_id IS NULL
             AND pi.is_active                                      THEN 'broken_reference_active'
        WHEN ci.image_id IS NULL
             AND NOT pi.is_active                                  THEN 'broken_reference_inactive'
        ELSE 'ok'
    END                                                            AS divergence_class,
    (ci.image_id IS NOT NULL AND ci.crawl_run_id IS NOT NULL)      AS exists_in_cf_confirmed
FROM public.product_images pi
LEFT JOIN cf_recon.cf_image ci
       ON ci.image_id = pi.cloudflare_image_id::text;
;

-- <<< END 20260619201336_20260619140500_cf_recon_fix_v_divergence_circular.sql <<<

