      ('NAVY BLUE','0904add6-5ac9-43e5-a025-10d561e27f2a'::uuid),
      ('BEIGE','d926a706-b2df-43eb-9200-3c3b15d9ee66'::uuid),
      ('BURGUNDY','8e9984bf-0139-42ed-aa2a-26eb6a121aed'::uuid),
