-- >>> BEGIN 20260620000001_fix_c07_new_chain_violations.sql >>>
-- Migration: fix_c07_new_chain_violations_20260620
-- Purpose: Repair 2 new C07 chain violations (depth-2 canonical chains) discovered 2026-06-20.
--
-- Root cause: On 2026-06-19 ~11:45 UTC, a "claude" session set canonical_image_id on two rows
-- pointing to intermediate nodes. Later that same day (20:34 and 21:50 UTC), separate migrations
-- made those intermediate nodes into deps (linked to their true roots). This created depth-2
-- chains: orphan-dep → intermediate-dep → root.
--
-- Fix: Re-point each orphan-dep directly to its canonical root (skip the intermediate).
--
-- Chain 1 (hash 7c2c81a56e80b1dd...):
--   45c83c45 → d39af6e6 → 254dea34 (ROOT)
--   Fix: 45c83c45 → 254dea34
--
-- Chain 2 (hash 6c2644f5380d97c9...):
--   918192cc → c9d485ea → 2238f75c (ROOT)
--   Fix: 918192cc → 2238f75c

BEGIN;

-- Chain 1: re-point 45c83c45 directly to root 254dea34
UPDATE public.product_images
SET
  canonical_image_id = '254dea34-123d-45ca-9a93-1901c81bc4ef',
  last_modified_source = 'migration',
  updated_at = NOW()
WHERE id = '45c83c45-fbc5-45b2-bed2-0f8a7f32b48a'
  AND canonical_image_id = 'd39af6e6-2b2a-418b-a139-0acda20cb6af'
  AND is_shared = true;

-- Chain 2: re-point 918192cc directly to root 2238f75c
UPDATE public.product_images
SET
  canonical_image_id = '2238f75c-800f-4d18-a499-bddd253824fc',
  last_modified_source = 'migration',
  updated_at = NOW()
WHERE id = '918192cc-6714-452d-9886-f1eb5edc2988'
  AND canonical_image_id = 'c9d485ea-4d41-4873-8ce6-990d1e0f793b'
  AND is_shared = true;

-- Self-test: C07 must be 0 after repair
DO $$
DECLARE
  chain_count int;
  c07_status  text;
  c07_value   int;
BEGIN
  -- Count remaining chain violations directly
  SELECT COUNT(*) INTO chain_count
  FROM public.product_images pi
  JOIN public.product_images root ON root.id = pi.canonical_image_id
  WHERE pi.is_shared = true
    AND pi.canonical_image_id IS NOT NULL
    AND root.canonical_image_id IS NOT NULL;  -- root is itself a dep → chain

  IF chain_count <> 0 THEN
    RAISE EXCEPTION 'C07 still has % chain violation(s) after migration', chain_count;
  END IF;

  -- Verify via health check function
  SELECT status::text, value::int
  INTO c07_status, c07_value
  FROM fn_product_images_health_check()
  WHERE check_name = 'c07_canonical_chains_flat';

  IF c07_status <> 'OK' THEN
    RAISE EXCEPTION 'C07 health check still FAIL: value=%, expected OK', c07_value;
  END IF;

  RAISE NOTICE 'C07 repair verified: % chain violations remain (expected 0)', chain_count;
END;
$$;

COMMIT;

-- <<< END 20260620000001_fix_c07_new_chain_violations.sql <<<

-- >>> BEGIN 20260620000001_mockup_client_logo_rotation_cols.sql >>>
-- Adds missing top-level columns to generated_mockups and tightens storage security.
--
-- Bugs fixed:
--   BUG-CLIENT-ID  : client_id / client_name were never persisted at the row level —
--                    they lived only inside area_config JSONB, making CRM linkage
--                    and server-side filtering impossible.
--   BUG-MISSING-COLS: logo_rotation / logo_scale had no dedicated columns; reads fell
--                    back to area_config which breaks for rows inserted before that JSONB
--                    key existed.
--   BUG-STORAGE-SEC: mockup-assets bucket had no file-size or MIME-type enforcement.
--   BUG-MISSING-IDX : no index on client_id or approval_status — full scans on admin
--                    dashboards that filter by those columns.
--
-- All ALTER TABLE clauses are guarded with IF NOT EXISTS so the migration is idempotent.

DO $$
BEGIN
  -- client_id: stored as text (no FK) to avoid cascade issues when CRM clients are deleted.
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'generated_mockups' AND column_name = 'client_id'
  ) THEN
    ALTER TABLE public.generated_mockups ADD COLUMN client_id TEXT;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'generated_mockups' AND column_name = 'client_name'
  ) THEN
    ALTER TABLE public.generated_mockups ADD COLUMN client_name TEXT;
  END IF;

  -- logo_rotation in degrees (−360 … 360). NUMERIC to allow sub-degree precision.
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'generated_mockups' AND column_name = 'logo_rotation'
  ) THEN
    ALTER TABLE public.generated_mockups ADD COLUMN logo_rotation NUMERIC DEFAULT 0;
  END IF;

  -- logo_scale as percentage (0 … 200).
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'generated_mockups' AND column_name = 'logo_scale'
  ) THEN
    ALTER TABLE public.generated_mockups ADD COLUMN logo_scale NUMERIC DEFAULT 100;
  END IF;
END $$;

-- Backfill client_name from area_config JSONB for existing rows that already have it.
-- Runs only where client_name is still NULL so the UPDATE is safe to re-run.
UPDATE public.generated_mockups
SET client_name = (area_config ->> 'clientName')
WHERE client_name IS NULL
  AND area_config ? 'clientName'
  AND (area_config ->> 'clientName') IS NOT NULL
  AND (area_config ->> 'clientName') <> '';

-- Backfill logo_rotation / logo_scale from area_config for older rows.
-- NOTE: `ADD COLUMN ... DEFAULT <const>` above already filled every existing row with
-- 0/100, so these columns are never NULL. A `WHERE logo_rotation IS NULL` clause would
-- therefore match nothing and silently leave older rows clobbered at the default while
-- their real values still sit in area_config. Backfill wherever the JSONB carries the
-- authoritative value instead, falling back to the current (default) column value.
UPDATE public.generated_mockups
SET
  logo_rotation = COALESCE((area_config ->> 'logoRotation')::numeric, logo_rotation),
  logo_scale    = COALESCE((area_config ->> 'logoScale')::numeric, logo_scale)
WHERE area_config IS NOT NULL
  AND (area_config ? 'logoRotation' OR area_config ? 'logoScale');

-- Index on client_id speeds up admin queries like "all mockups for client X".
CREATE INDEX IF NOT EXISTS idx_generated_mockups_client_id
  ON public.generated_mockups (client_id)
  WHERE client_id IS NOT NULL;

-- Index on approval_status for approval-workflow dashboard queries.
CREATE INDEX IF NOT EXISTS idx_generated_mockups_approval_status
  ON public.generated_mockups (approval_status)
  WHERE approval_status IS NOT NULL;

-- Index on product_id for product-level mockup history views.
CREATE INDEX IF NOT EXISTS idx_generated_mockups_product_id
  ON public.generated_mockups (product_id)
  WHERE product_id IS NOT NULL;

-- Storage bucket: enforce 10 MB limit and restrict to image MIME types.
-- Prevents malicious actors from uploading arbitrary file types (e.g. scripts, executables)
-- and prevents accidental storage-cost blowouts from huge uploads.
UPDATE storage.buckets
SET
  file_size_limit   = 10485760,   -- 10 MB in bytes
  allowed_mime_types = ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/gif']
WHERE id = 'mockup-assets';

-- <<< END 20260620000001_mockup_client_logo_rotation_cols.sql <<<

-- >>> BEGIN 20260620005056_20260619140600_cf_recon_enrich_health_dashboard.sql >>>

CREATE OR REPLACE VIEW cf_recon.v_health_dashboard AS
SELECT
    (SELECT COUNT(*) FROM public.product_images)                               AS db_total,
    (SELECT COUNT(*) FROM public.product_images WHERE is_active)               AS db_active,
    (SELECT COUNT(*) FROM public.product_images WHERE cf_sync_status = 'verified') AS verified,
    (SELECT COUNT(*) FROM public.product_images WHERE cf_sync_status = 'pending')  AS pending,
    (SELECT COUNT(*) FROM public.product_images WHERE cf_sync_status = 'missing')  AS missing,
    (SELECT COUNT(*) FROM public.product_images
     WHERE cf_sync_status = 'missing' AND is_active)                           AS missing_active,
    (SELECT COUNT(*) FROM cf_recon.v_verification_queue)                       AS queue_real,
    (SELECT COUNT(*) FROM cf_recon.remediation WHERE status = 'open')          AS remediation_open,
    (SELECT COUNT(*) FROM cf_recon.cf_image)                                   AS cf_crawled,
    (SELECT COUNT(*) FROM cf_recon.action_log)                                 AS actions_logged,
    (SELECT COUNT(*) FROM cf_recon.cf_image WHERE crawl_run_id IS NULL)        AS cf_backfill_only,
    (SELECT COUNT(*) FROM cf_recon.cf_image WHERE crawl_run_id IS NOT NULL)    AS cf_crawl_confirmed,
    (SELECT COUNT(*) FROM cf_recon.v_divergence
     WHERE divergence_class = 'ok')                                            AS divergence_ok,
    (SELECT COUNT(*) FROM cf_recon.v_divergence
     WHERE divergence_class = 'ok_pending_crawl_confirmation')                 AS divergence_pending,
    (SELECT COUNT(*) FROM cf_recon.v_divergence
     WHERE divergence_class LIKE 'broken%')                                    AS divergence_broken;
;

-- <<< END 20260620005056_20260619140600_cf_recon_enrich_health_dashboard.sql <<<

-- >>> BEGIN 20260620005259_20260619140700_cf_recon_close_stale_cf_orphan_no_pi.sql >>>

INSERT INTO cf_recon.action_log
  (actor, action, image_db_id, cf_image_id, product_id,
   old_status, new_status, evidence, reversible)
SELECT
  'claude',
  'close_stale_remediation',
  NULL,
  r.cf_image_id,
  NULL,
  'remediation_open',
  'remediation_done',
  jsonb_build_object(
    'reason',           'backfill_only_circular_detection_pre_p5',
    'remediation_id',   r.id,
    'kind',             r.kind,
    'cf_image_exists',  (ci.image_id IS NOT NULL),
    'crawl_confirmed',  false,
    'action_required',  're_evaluate_after_full_crawl_v_cf_orphans',
    'migration',        '20260619140700_cf_recon_close_stale_cf_orphan_no_pi'
  ),
  false
FROM cf_recon.remediation r
LEFT JOIN cf_recon.cf_image ci ON ci.image_id = r.cf_image_id
WHERE r.kind = 'cf_orphan_no_pi'
  AND r.status = 'open';

UPDATE cf_recon.remediation
SET status = 'done'
WHERE kind = 'cf_orphan_no_pi'
  AND status = 'open';
;

