-- >>> BEGIN 20260621212000_fn_qa_orcamento_regression.sql >>>
-- APLICADO 2026-06-21 (Supabase MCP execute_sql, projeto doufsxqlfjyuvxuezpln).
-- Rede de regressao permanente do modulo "Novo Orcamento": valida o invariante de que a
-- criacao resolve a organizacao server-side (omitida/fantasma/nao-membro -> canonica) e
-- rejeita com 23502 quem nao tem org. Cada cenario e revertido (savepoint). Restrita a service_role.
-- Uso: SELECT * FROM public.fn_qa_orcamento_regression();
CREATE OR REPLACE FUNCTION public.fn_qa_orcamento_regression()
RETURNS TABLE(cenario text, pass boolean, detalhe text)
LANGUAGE plpgsql
SET search_path TO 'public'
AS $fn$
DECLARE
  ADMIN constant uuid := '75921d8b-611f-4413-9ce5-afccdb733d26';
  CANON constant uuid := '5db5aee1-064b-4ef4-9193-345dcd8274ea';
  r public.quotes; v_pass boolean; v_det text;
  specs jsonb := $j$[
    {"d":"org OMITIDA resolve canonica","q":{"client_name":"QA","subtotal":10,"total":10}},
    {"d":"org FANTASMA resolve canonica","q":{"client_name":"QA","organization_id":"35c6a2a6-5d6d-4ddb-8dbd-8e842a0118e5","subtotal":10,"total":10}},
    {"d":"org nao-membro resolve canonica","q":{"client_name":"QA","organization_id":"11111111-1111-1111-1111-111111111111","subtotal":10,"total":10}}
  ]$j$::jsonb;
  spec jsonb;
BEGIN
  PERFORM set_config('request.jwt.claims', json_build_object('sub',ADMIN,'role','authenticated')::text, true);
  FOR spec IN SELECT * FROM jsonb_array_elements(specs) LOOP
    v_pass := false; v_det := '';
    BEGIN
      r := public.create_quote_transactional(spec->'q',
            jsonb_build_array(jsonb_build_object('product_name','P','quantity',1,'unit_price',10,'subtotal',10)));
      v_pass := (r.organization_id = CANON AND r.created_by = ADMIN AND r.quote_number ~ '^[0-9]+/[0-9]{2}$');
      v_det := format('org=%s num=%s', r.organization_id, r.quote_number);
      RAISE EXCEPTION 'RBK';
    EXCEPTION WHEN OTHERS THEN
      IF SQLERRM <> 'RBK' THEN v_pass := false; v_det := 'ERRO: '||left(SQLERRM,80); END IF;
    END;
    cenario := spec->>'d'; pass := v_pass; detalhe := v_det; RETURN NEXT;
  END LOOP;
  v_pass := false; v_det := '';
  PERFORM set_config('request.jwt.claims', json_build_object('sub','00000000-0000-0000-0000-0000000000aa','role','authenticated')::text, true);
  BEGIN
    r := public.create_quote_transactional(jsonb_build_object('client_name','QA','subtotal',10,'total',10),
          jsonb_build_array(jsonb_build_object('product_name','P','quantity',1,'unit_price',10,'subtotal',10)));
    v_pass := false; v_det := 'FALHA: criou sem org '||r.quote_number; RAISE EXCEPTION 'RBK';
  EXCEPTION WHEN OTHERS THEN
    IF SQLSTATE='23502' OR SQLERRM ILIKE '%organiza%' THEN v_pass := true; v_det := 'rejeitado 23502 (ok)';
    ELSIF SQLERRM='RBK' THEN NULL;
    ELSE v_pass := false; v_det := 'erro inesperado: '||left(SQLERRM,60); END IF;
  END;
  PERFORM set_config('request.jwt.claims', json_build_object('sub',ADMIN,'role','authenticated')::text, true);
  cenario := 'NEGATIVO: usuario sem org -> 23502'; pass := v_pass; detalhe := v_det; RETURN NEXT;
  RETURN;
END;
$fn$;
REVOKE ALL ON FUNCTION public.fn_qa_orcamento_regression() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_qa_orcamento_regression() TO service_role;

-- <<< END 20260621212000_fn_qa_orcamento_regression.sql <<<

-- >>> BEGIN 20260621213000_get_promo_sales_90d_by_product.sql >>>
-- BUG-PROMO-90D-01 FIX (2026-06-21 catalog audit)
-- get_promo_sales_90d_by_product: RPC para contagem de vendas reais (90 dias).
--
-- PROBLEMA: usePromoSales90dByProduct.ts fazia SELECT completo de order_items
-- client-side (.select('product_id, quantity, created_at').gte('created_at', ...))
-- transmitindo potencialmente dezenas de milhares de linhas ao browser para agregar em JS.
-- Mesmo padrão corrigido em get_promo_sales_ranking (quote_items) em 2026-06-18.
--
-- SOLUÇÃO: SUM(quantity) GROUP BY product_id server-side — retorna apenas
-- {product_id, total_qty} com N linhas (N = produtos distintos vendidos).
-- --------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.get_promo_sales_90d_by_product()
RETURNS TABLE(product_id uuid, total_qty bigint)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = 'public'
AS $function$
  SELECT
    oi.product_id,
    COALESCE(SUM(oi.quantity), 0)::bigint AS total_qty
  FROM order_items oi
  WHERE oi.product_id IS NOT NULL
    AND oi.quantity > 0
    AND oi.created_at >= NOW() - INTERVAL '90 days'
  GROUP BY oi.product_id
  ORDER BY total_qty DESC;
$function$;

COMMENT ON FUNCTION public.get_promo_sales_90d_by_product() IS
  'Quantidade vendida por produto nos últimos 90 dias (order_items).
   BUG-PROMO-90D-01 — 2026-06-21. Substitui client-side table scan.';

GRANT EXECUTE ON FUNCTION public.get_promo_sales_90d_by_product()
  TO anon, authenticated;

-- <<< END 20260621213000_get_promo_sales_90d_by_product.sql <<<

-- >>> BEGIN 20260621220000_faxina_restore_kit_builder_family_APLICADO.sql >>>
-- =============================================================================
-- APLICADO em 2026-06-21 via Supabase MCP (apply_migration).
-- Este arquivo é o REGISTRO da migration já executada em produção.
-- Projeto: doufsxqlfjyuvxuezpln (sa-east-1)
-- =============================================================================
--
-- CONTEXTO / CAUSA RAIZ
-- A migration 20260621100100_faxina_restore_active_tables_from_archive.sql
-- restaurou de archive→public apenas as tabelas com referência .from() detectadas
-- por um scan de código. Esse scan teve DOIS pontos cegos:
--   1) Deixou custom_kits e kit_comments em archive MESMO tendo .from() ativo:
--        • custom_kits   → 10 arquivos: useCustomKitPersistence, useKitAutoSave,
--          useGlobalSearch, KitLibraryPage, useDuplicateKitDetector, RecentKitsWidget,
--          KitHealthCard, KitSmartSuggestions, etc.
--        • kit_comments  → useKitComments faz SELECT/INSERT/UPDATE
--      Resultado: 404 PGRST205 ao abrir/salvar kit e ao comentar (mesma classe do
--      bug de expert_conversations).
--   2) O critério ".from() apenas" não cobre tabelas referenciadas SÓ via realtime
--      (.channel().on('postgres_changes',{table})). Ver nota no fim do arquivo.
--
-- ESCOPO DESTA MIGRATION
-- Restaura a família kit-builder como UNIDADE COESA DE FK:
--   custom_kits (parent) + kit_comments + kit_variants + kit_share_tokens
-- kit_collaborators e kit_templates já estavam em public.
-- Deixar dependentes em archive com o parent em public criaria FK cross-schema
-- archive→public. Mover custom_kits p/ public também CORRIGE a FK cross-schema
-- public.kit_collaborators → archive.custom_kits (a constraint segue a tabela por OID).
--
-- SEGURANÇA
-- Todas as 4 tabelas já tinham RLS habilitado com policies owner-scoped
-- (custom_kits: ck_*_own_or_coord; kit_comments: owner/collab; kit_variants: owner;
-- kit_share_tokens: sellers own). Por isso GRANT full DML a authenticated é seguro:
-- o RLS filtra as linhas por dono.
-- =============================================================================

DO $$
DECLARE
  tbl text;
  kit_tables text[] := ARRAY['custom_kits','kit_comments','kit_variants','kit_share_tokens'];
BEGIN
  -- 1) Parent primeiro (custom_kits → FK só p/ auth.users)
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='archive' AND table_name='custom_kits') THEN
    EXECUTE 'ALTER TABLE archive.custom_kits SET SCHEMA public';
  END IF;
  -- 2) Dependentes (FK -> custom_kits)
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='archive' AND table_name='kit_comments') THEN
    EXECUTE 'ALTER TABLE archive.kit_comments SET SCHEMA public';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='archive' AND table_name='kit_variants') THEN
    EXECUTE 'ALTER TABLE archive.kit_variants SET SCHEMA public';
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='archive' AND table_name='kit_share_tokens') THEN
    EXECUTE 'ALTER TABLE archive.kit_share_tokens SET SCHEMA public';
  END IF;

  -- 3) RLS + grants padrão (idempotente). RLS já estava on; policies seguem no SET SCHEMA.
  FOREACH tbl IN ARRAY kit_tables LOOP
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name=tbl) THEN
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', tbl);
      EXECUTE format('REVOKE ALL ON public.%I FROM anon', tbl);
      EXECUTE format('GRANT SELECT, INSERT, UPDATE, DELETE ON public.%I TO authenticated', tbl);
      EXECUTE format('GRANT ALL ON public.%I TO service_role', tbl);
    END IF;
  END LOOP;
END $$;

-- 4) Realtime: custom_kits (useCustomKitsRealtime) e kit_comments (useKitComments) assinam postgres_changes
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='custom_kits') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.custom_kits;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_publication_tables WHERE pubname='supabase_realtime' AND schemaname='public' AND tablename='kit_comments') THEN
    ALTER PUBLICATION supabase_realtime ADD TABLE public.kit_comments;
  END IF;
END $$;

-- 5) Recarrega o cache de schema do PostgREST
NOTIFY pgrst, 'reload schema';

-- =============================================================================
-- VERIFICAÇÃO PÓS-APLICAÇÃO (todas PASS)
--   • 4 tabelas em public + RLS on
--   • authenticated com DML completo; anon revogado
--   • FK kit_collaborators → public.custom_kits (cross-schema landmine resolvido)
--   • realtime publication inclui custom_kits + kit_comments
--   • zero FK cross-schema public→archive restantes
--   • queries .from() reproduzidas sem PGRST205
--
-- PENDÊNCIA P/ ARQUITETO (NÃO aplicada aqui — fora de escopo):
--   usePushNotifications assina realtime em notifications, device_login_notifications
--   (ambas só em archive). Como o hook é realtime-only (sem .from()), NÃO há 404 REST;
--   com o tópico único já aplicado, a falha é graciosa (CHANNEL_ERROR → warn). Suspeita
--   de que foram substituídas por workspace_notifications (já em public+realtime).
--   Decisão de restaurar/remover essas tabelas e o listener fica para o arquiteto.
-- =============================================================================

-- <<< END 20260621220000_faxina_restore_kit_builder_family_APLICADO.sql <<<

-- >>> BEGIN 20260621221500_fix_quotes_validate_discount_xuser_role_check_APLICADO.sql >>>
-- =============================================================================
-- APLICADO em produção (project doufsxqlfjyuvxuezpln) via apply_migration.
-- Migration: fix_quotes_validate_discount_xuser_role_check
-- Data: 2026-06-21
-- =============================================================================
-- PROBLEMA (GAP latente / write-path):
--   trg_quotes_validate_discount (BEFORE INSERT/UPDATE ON public.quotes) chamava
--   public.is_coord_or_above(_seller_id), onde _seller_id = COALESCE(NEW.seller_id,
--   NEW.created_by) -> ou seja, o papel do SELLER da linha, NÃO do editor.
--   is_coord_or_above LANÇA EXCEPTION (ERRCODE 42501, "forbidden: cannot query
--   role of another user") quando _seller_id <> auth.uid() e o editor não é 'dev'.
--   Resultado: qualquer admin/coordenador/supervisor (não-dev) que salvasse ou
--   editasse o orçamento de OUTRO vendedor recebia 42501 ANTES da validação de
--   desconto -> salvamento falhava com erro críptico. Reproduzido ao vivo:
--   admin (não-dev) avaliando is_coord_or_above(<outro_vendedor>) => 42501.
--
-- CAUSA-RAIZ:
--   is_coord_or_above embute um guard de auth.uid() projetado para proteger
--   LEITURA de papéis em RLS (onde o arg é sempre auth.uid()). Aqui o arg é o
--   seller da linha; dentro de um trigger SECURITY DEFINER que legitimamente
--   precisa checar o papel do seller, esse guard é inadequado.
--
-- CORREÇÃO (único delta de lógica):
--   is_coord_or_above(_seller_id) -> is_supervisor_or_above(_seller_id).
--   is_supervisor_or_above é a função-base (SELECT EXISTS em user_roles, sem
--   guard) e retorna o MESMO booleano. A função roda como owner=postgres (SECDEF)
--   -> lê user_roles sem bloqueio de RLS. Todo o resto do corpo é idêntico.
--
-- VALIDAÇÃO:
--   - 38 call-sites de is_coord_or_above auditados: este era o ÚNICO cross-user.
--   - Pós-fix: admin avaliando a expressão p/ os 13 sellers => 13/13 sem 42501.
--   - fn_run_smoke_tests(): 23/23 PASS (0 regressões).
--   - is_coord_or_above permanece INTACTA (proteção de leitura cross-user em RLS
--     preservada em todos os outros 37 call-sites self-scoped).
-- =============================================================================

CREATE OR REPLACE FUNCTION public.fn_quotes_validate_discount()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  _max_allowed numeric;
  _real_discount_pct numeric;
  _has_valid_approval boolean;
  _current_hash text;
  _seller_id uuid;
  _msg text;
BEGIN
  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN NEW;
  END IF;

  _seller_id := COALESCE(NEW.seller_id, NEW.created_by);

  IF _seller_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- BUG-DAR-XUSER FIX: checagem do papel do SELLER sem guard de auth.uid()
  -- (is_coord_or_above estourava 42501 quando _seller_id <> auth.uid() e editor não-dev).
  IF public.is_supervisor_or_above(_seller_id) THEN
    RETURN NEW;
  END IF;

  _real_discount_pct := COALESCE(NEW.real_discount_percent, 0);

  IF _real_discount_pct <= 0 THEN
    RETURN NEW;
  END IF;

  SELECT max_discount_percent INTO _max_allowed
  FROM public.seller_discount_limits
  WHERE user_id = _seller_id;

  IF _max_allowed IS NULL THEN
    RAISE EXCEPTION 'Vendedor sem limite de desconto cadastrado. Solicite ao admin que configure seu limite antes de salvar orcamentos.'
      USING ERRCODE = '23514';
  END IF;

  IF _real_discount_pct <= _max_allowed THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
            ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
            ' por cento. Salve o orcamento com desconto dentro do limite primeiro, depois solicite aprovacao ao coordenador.';
    RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
  END IF;

  _current_hash := public.compute_quote_snapshot_hash(NEW.id);

  SELECT EXISTS (
    SELECT 1 FROM public.discount_approval_requests
    WHERE quote_id = NEW.id
      AND status = 'approved'
      AND (valid_until IS NULL OR valid_until > now())
      AND requested_discount_percent >= _real_discount_pct
      AND quote_snapshot_hash = _current_hash
  ) INTO _has_valid_approval;

  IF _has_valid_approval THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.discount_approval_requests
    WHERE quote_id = NEW.id AND status = 'approved'
      AND (
        (valid_until IS NOT NULL AND valid_until <= now())
        OR quote_snapshot_hash <> _current_hash
      )
  ) THEN
    RAISE EXCEPTION 'Aprovacao anterior nao vale mais (orcamento foi alterado ou aprovacao expirou). Solicite nova aprovacao ao coordenador.'
      USING ERRCODE = '23514';
  END IF;

  _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
          ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
          ' por cento. Solicite aprovacao ao coordenador antes de salvar.';
  RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
END;
$function$;

-- <<< END 20260621221500_fix_quotes_validate_discount_xuser_role_check_APLICADO.sql <<<

-- >>> BEGIN 20260621224723_fix_product_variants_add_next_entry_alias_columns.sql >>>

-- ============================================================
-- FIX #1: Adiciona colunas geradas como alias para next_date_1
-- e next_quantity_1 — resolve 100% dos erros HTTP 400 no
-- endpoint /rest/v1/product_variants
-- 
-- MOTIVO: O frontend solicita `next_entry_date` e
-- `next_entry_quantity`, mas o schema tem next_date_1..6 e
-- next_quantity_1..6. GENERATED ALWAYS AS (STORED) garante
-- sincronia automática em toda escrita em next_date_1 / next_quantity_1.
-- ============================================================

ALTER TABLE public.product_variants
  ADD COLUMN IF NOT EXISTS next_entry_date    date
    GENERATED ALWAYS AS (next_date_1) STORED,
  ADD COLUMN IF NOT EXISTS next_entry_quantity integer
    GENERATED ALWAYS AS (next_quantity_1) STORED;

-- Índice parcial para acelerar filtros de estoque futuro
-- (ex.: variantes com reposição prevista)
CREATE INDEX IF NOT EXISTS idx_pv_next_entry_date_nonnull
  ON public.product_variants (next_entry_date)
  WHERE next_entry_date IS NOT NULL;

-- Notifica PostgREST para recarregar o schema
NOTIFY pgrst, 'reload schema';

-- COMENTÁRIO DESCRITIVO nas colunas geradas
COMMENT ON COLUMN public.product_variants.next_entry_date IS
  'Alias gerado de next_date_1 (primeira data de entrada prevista). Somente leitura — GENERATED STORED.';

COMMENT ON COLUMN public.product_variants.next_entry_quantity IS
  'Alias gerado de next_quantity_1 (quantidade da primeira entrada prevista). Somente leitura — GENERATED STORED.';
;

-- <<< END 20260621224723_fix_product_variants_add_next_entry_alias_columns.sql <<<

-- >>> BEGIN 20260621224737_fix_create_rpc_get_promo_sales_90d_by_product.sql >>>

-- ============================================================
-- FIX #2: Cria RPC get_promo_sales_90d_by_product
-- Resolve HTTP 404 no endpoint /rest/v1/rpc/get_promo_sales_90d_by_product
--
-- Retorna métricas de vendas dos últimos 90 dias agrupadas por
-- product_id — usada pelo frontend para exibir popularidade/
-- histórico de vendas no card e detalhe do produto.
-- ============================================================

CREATE OR REPLACE FUNCTION public.get_promo_sales_90d_by_product()
RETURNS TABLE (
  product_id     uuid,
  total_quantity bigint,
  total_revenue  numeric,
  order_count    bigint
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT
    oi.product_id,
    SUM(oi.quantity)::bigint          AS total_quantity,
    SUM(oi.subtotal)::numeric         AS total_revenue,
    COUNT(DISTINCT oi.order_id)::bigint AS order_count
  FROM order_items oi
  JOIN orders o ON o.id = oi.order_id
  WHERE
    o.created_at >= (NOW() - INTERVAL '90 days')
    -- Exclui pedidos cancelados/estornados (não contam como venda)
    AND o.status NOT IN ('cancelled', 'refunded', 'cancelado', 'estornado')
    AND oi.product_id IS NOT NULL
  GROUP BY oi.product_id
  -- Apenas produtos com ao menos 1 unidade vendida
  HAVING SUM(oi.quantity) > 0;
$$;

-- Permissões: authenticated + service_role
GRANT EXECUTE ON FUNCTION public.get_promo_sales_90d_by_product()
  TO authenticated, service_role;

-- Documenta a função
COMMENT ON FUNCTION public.get_promo_sales_90d_by_product() IS
  'Retorna total de unidades vendidas, receita e número de pedidos dos últimos 90 dias, agrupados por product_id. Pedidos cancelados/estornados são excluídos.';

-- Notifica schema reload
NOTIFY pgrst, 'reload schema';
;

-- <<< END 20260621224737_fix_create_rpc_get_promo_sales_90d_by_product.sql <<<

-- >>> BEGIN 20260621224748_fix_create_rpc_get_favorite_list_counts.sql >>>

-- ============================================================
-- FIX #3: Cria RPC get_favorite_list_counts
-- Resolve HTTP 404 no endpoint /rest/v1/rpc/get_favorite_list_counts
--
-- Retorna a contagem de itens por lista de favoritos do usuário
-- autenticado atual. SECURITY DEFINER + auth.uid() garante que
-- cada usuário vê SOMENTE suas próprias listas.
-- ============================================================

CREATE OR REPLACE FUNCTION public.get_favorite_list_counts()
RETURNS TABLE (
  list_id    uuid,
  item_count bigint
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT
    fl.id          AS list_id,
    COUNT(fi.id)::bigint AS item_count
  FROM favorite_lists fl
  LEFT JOIN favorite_items fi ON fi.list_id = fl.id
  WHERE fl.user_id = (SELECT auth.uid())
    AND fl.is_archived = false  -- não conta listas arquivadas
  GROUP BY fl.id
  ORDER BY fl.position ASC NULLS LAST, fl.created_at ASC;
$$;

-- Apenas authenticated (anon não tem listas)
GRANT EXECUTE ON FUNCTION public.get_favorite_list_counts()
  TO authenticated;

COMMENT ON FUNCTION public.get_favorite_list_counts() IS
  'Retorna list_id + contagem de itens para todas as listas de favoritos ativas do usuário autenticado. SECURITY DEFINER: cada usuário vê somente suas próprias listas.';

NOTIFY pgrst, 'reload schema';
;

-- <<< END 20260621224748_fix_create_rpc_get_favorite_list_counts.sql <<<

