    p.box_length_cm, p.box_width_cm, p.box_height_cm, p.box_volume_cm3,
    p.box_quantity, p.box_inner_quantity, p.packing_type, p.repacking_type,
    p.capacities,
    NULL::timestamp with time zone AS last_sync_at,
    NULL::uuid AS last_sync_supplier_id,
    NULL::character varying AS sync_status,
    p.diameter_cm, p.shape_type,
    p.internal_height_cm, p.internal_width_cm, p.internal_length_cm,
    p.internal_diameter_cm, p.packaging_material, p.packaging_color,
    p.has_inner_cradle, p.cradle_material, p.packaging_finish,
