    p.schema_json, p.canonical_url, p.robots_meta, p.seo_score,
    p.seo_last_audit_at, p.seo_issues, p.og_title, p.og_description,
    p.og_image_url, p.description_packaging_info, p.has_optional_packaging,
    p.optional_packaging_ref, p.packing_classification,
    NULL::numeric AS ipi_rate,
