    p.engraving_type, p.supplier_updated_at, p.has_gift_box,
    p.min_order_quantity, p.ai_title, p.ai_description, p.ai_version,
    p.ai_generated_at, p.ai_model, p.box_image, p.repacking_classification,
    p.has_commercial_packaging, p.packaging_context,
    NULL::integer AS bitrix_product_id,
    p.novelty_detected_at, p.novelty_expires_at,
    NULL::uuid AS ncm_id,
    NULL::timestamp with time zone AS bitrix_images_synced_at,
