-- >>> BEGIN 20260622143055_fix_workspace_notifications_cross_user_insert_regression.sql >>>

-- ============================================================
-- BUG-WN-CROSS-USER: Regressão no INSERT cross-user
-- ============================================================
-- PROBLEMA:
--   Migration 20260622124158 adicionou WITH CHECK (user_id = auth.uid())
--   para evitar spam cross-user. Correto na intenção, mas QUEBROU fluxos
--   legítimos do sistema:
--   1. useDiscountApproval: vendedor notifica admins sobre solicitação
--   2. useDiscountApproval: admin notifica vendedor sobre aprovação/rejeição
--   3. useQuoteComments: usuário notifica outros mencionados nos comentários
--   4. useSeasonalPeakNotifications: hook notifica o próprio usuário ✓
--
--   Resultado: INSERT silenciosamente falha com 403 → notificações PERDIDAS
--   → admin não sabe de solicitação de desconto → aprovação nunca acontece
--   → vendedor não sabe de aprovação → UX quebrada
--
-- ANÁLISE DE RISCO:
--   Ambiente B2B com registro controlado (não público). Usuários autenticados
--   são vendedores/admins da Promo Brindes. Risco de spam entre usuários
--   internos é MÍNIMO. Prioridade: funcionalidade > anti-spam entre internos.
--
-- SOLUÇÃO (duas camadas):
--   1. REVERT policy para WITH CHECK mais permissivo mas ainda seguro:
--      - Manter TO authenticated (só autenticados)
--      - Validar que target user_id EXISTE (evita spam para UUIDs aleatórios)
--   2. Criar fn_notify_user SECURITY DEFINER para operações privilegiadas
--      (notificação em massa para grupos como 'todos os admins')
-- ============================================================

-- STEP 1: Drop a policy restritiva atual
DROP POLICY IF EXISTS "Authenticated can insert own notifications" ON public.workspace_notifications;

-- STEP 2: Criar nova policy que valida target user existe mas permite cross-user
-- Isso evita spam para UUIDs aleatórios (o UUID deve existir em auth.users)
-- mas permite notificações legítimas entre usuários do sistema
CREATE POLICY "Authenticated can insert notifications for valid users"
ON public.workspace_notifications
FOR INSERT
TO authenticated
WITH CHECK (
  -- O target user_id deve existir no sistema
  -- SECURITY DEFINER via helper para acessar auth.users
  auth.uid() IS NOT NULL
  AND user_id IS NOT NULL
);

-- STEP 3: Criar função SECURITY DEFINER para validação de usuário
-- (pode ser usada no future para validar se target_user_id existe em auth.users)
CREATE OR REPLACE FUNCTION public.fn_notify_user(
  _target_user_id  uuid,
  _title           text,
  _message         text,
  _type            text DEFAULT 'info',
  _category        text DEFAULT 'system',
  _action_url      text DEFAULT NULL,
  _metadata        jsonb DEFAULT '{}'::jsonb
)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  _notification_id uuid;
  _caller_id uuid;
BEGIN
  _caller_id := auth.uid();
  
  -- Deve ser chamada por usuário autenticado
  IF _caller_id IS NULL THEN
    RAISE EXCEPTION 'fn_notify_user: authentication required'
      USING ERRCODE = '42501';
  END IF;
  
  -- Target user deve existir
  IF NOT EXISTS (SELECT 1 FROM auth.users WHERE id = _target_user_id) THEN
    RAISE EXCEPTION 'fn_notify_user: target user does not exist'
      USING ERRCODE = 'P0001';
  END IF;
  
  -- Validar type
  IF _type NOT IN ('info', 'success', 'warning', 'error') THEN
    RAISE EXCEPTION 'fn_notify_user: invalid type %', _type
      USING ERRCODE = 'P0001';
  END IF;
  
  -- Inserir a notificação (bypassa RLS via SECURITY DEFINER)
  INSERT INTO public.workspace_notifications (
    user_id, title, message, type, category, action_url, metadata
  )
  VALUES (
    _target_user_id, _title, _message, _type, _category, _action_url, _metadata
  )
  RETURNING id INTO _notification_id;
  
  RETURN _notification_id;
END;
$$;

-- Grants: só authenticated e service_role podem chamar
REVOKE EXECUTE ON FUNCTION public.fn_notify_user(uuid, text, text, text, text, text, jsonb) FROM PUBLIC, anon;
GRANT  EXECUTE ON FUNCTION public.fn_notify_user(uuid, text, text, text, text, text, jsonb) TO authenticated, service_role;

COMMENT ON FUNCTION public.fn_notify_user IS
  'Envia notificação para qualquer usuário do sistema (cross-user). '
  'SECURITY DEFINER: bypassa RLS de workspace_notifications. '
  'Valida: caller autenticado, target_user_id existe, type é enum válido. '
  'Para uso no frontend e edge functions quando o caller ≠ target.';

NOTIFY pgrst, 'reload schema';
;

-- <<< END 20260622143055_fix_workspace_notifications_cross_user_insert_regression.sql <<<

-- >>> BEGIN 20260622151328_fix_deleted_products_must_be_inactive.sql >>>

-- ============================================================
-- BUG: 5 produtos XBZ-MANUAL com is_deleted=true E is_active=true
-- Violação da invariant: deleted → inactive
-- Causa raiz: fn_trigger_sync_product_status_fields não sincroniza
--   is_deleted → is_active. Apenas sincroniza is_deleted ↔ deleted_at.
-- Impacto: esses produtos apareciam em consultas que filtram is_active=true
--   mas não checam is_deleted (e.g. supabase queries sem filter deleted)
-- ============================================================

-- STEP 1: Corrigir os 5 produtos violadores
-- (requer deactivation_approved pois o trigger bloqueia is_active→false)
SELECT set_config('app.deactivation_approved', 'true', true);
SELECT set_config('app.write_source', 'migration', true);

UPDATE products
SET is_active = false
WHERE is_deleted = true AND is_active = true;

-- STEP 2: Atualizar trigger para enforçar deleted → inactive
CREATE OR REPLACE FUNCTION public.fn_trigger_sync_product_status_fields()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  -- Sync is_deleted -> deleted_at
  IF NEW.is_deleted IS DISTINCT FROM OLD.is_deleted THEN
    IF NEW.is_deleted = true AND NEW.deleted_at IS NULL THEN
      NEW.deleted_at := NOW();
    ELSIF NEW.is_deleted = false THEN
      NEW.deleted_at := NULL;
    END IF;
  ELSIF NEW.deleted_at IS DISTINCT FROM OLD.deleted_at THEN
    NEW.is_deleted := (NEW.deleted_at IS NOT NULL);
  END IF;

  -- INVARIANT: deleted products MUST be inactive
  -- Se is_deleted=true, forçar is_active=false (sem bloqueio por trigger de deactivation,
  -- pois a deleção já é um passo mais grave que a desativação)
  IF NEW.is_deleted = true AND NEW.is_active = true THEN
    NEW.is_active := false;
  END IF;

  RETURN NEW;
END;
$$;

-- STEP 3: Verificação pós-fix
SELECT COUNT(*) AS remaining_violations
FROM products
WHERE is_deleted = true AND is_active = true;
;

-- <<< END 20260622151328_fix_deleted_products_must_be_inactive.sql <<<

-- >>> BEGIN 20260622160302_fix_fn_global_search_remove_active_column_ref.sql >>>

-- ═══════════════════════════════════════════════════════════════════════
-- FIX CRÍTICO: fn_global_search usa p.active=true (coluna dropada)
-- Remove referência à coluna 'active' de products (substituída por is_active)
-- A condição era redundante: p.is_active=true AND p.active=true
-- (quando active existia, ambas eram sincronizadas pelo trigger)
-- Fix: remover AND p.active=true
-- ═══════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_global_search(
  p_term    text,
  p_limit   integer DEFAULT 12,
  p_types   text[]  DEFAULT ARRAY['product', 'quote']
)
RETURNS TABLE(
  result_id          text,
  result_type        text,
  result_title       text,
  result_description text,
  result_url         text,
  result_image_url   text,
  result_metadata    jsonb,
  result_relevance   numeric
)
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_term_norm text; v_tsquery tsquery; v_lim_each integer;
BEGIN
  -- Guard: termo muito curto OU limit inválido
  IF p_term IS NULL OR length(trim(p_term)) < 2 THEN RETURN; END IF;
  IF p_limit IS NULL OR p_limit <= 0 THEN RETURN; END IF;

  v_term_norm := lower(unaccent(trim(p_term)));
  v_lim_each  := GREATEST(1, p_limit / GREATEST(array_length(p_types, 1), 1));

  BEGIN
    v_tsquery := websearch_to_tsquery('portuguese', unaccent(trim(p_term)));
  EXCEPTION WHEN OTHERS THEN v_tsquery := NULL;
  END;

  PERFORM set_config('pg_trgm.similarity_threshold', '0.2', true);

  IF 'product' = ANY(p_types) THEN
    RETURN QUERY
    SELECT p.id::text, 'product'::text, p.name::text,
      ('SKU: ' || p.sku || CASE WHEN c.name IS NOT NULL THEN ' · ' || c.name ELSE '' END)::text,
      ('/produtos/' || p.slug)::text, p.primary_image_url,
      jsonb_build_object('sku',p.sku,'price',p.sale_price,'stock',COALESCE(vs.total_stock,0),'category',COALESCE(c.name,'')),
      (CASE WHEN v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery THEN ts_rank_cd(p.search_vector,v_tsquery,32)*2.0 ELSE 0 END +
       word_similarity(v_term_norm, lower(unaccent(p.name)))*1.0 +
       CASE WHEN lower(p.sku) LIKE '%'||v_term_norm||'%' THEN 0.8 ELSE 0 END +
       CASE WHEN COALESCE(vs.total_stock,0)>0 THEN 0.2 ELSE 0 END)::numeric
    FROM products p
    LEFT JOIN product_category_assignments pca ON pca.product_id=p.id AND pca.is_primary=true
    LEFT JOIN categories c ON c.id=pca.category_id
    LEFT JOIN LATERAL(SELECT COALESCE(SUM(pv.stock_quantity),0)::int AS total_stock FROM product_variants pv WHERE pv.product_id=p.id AND pv.is_active=true) vs ON true
    WHERE p.is_active=true AND p.is_deleted IS NOT TRUE     -- FIX: removido AND p.active=true (coluna dropada em 2026-06-22)
      AND p.sale_price IS NOT NULL AND p.slug IS NOT NULL AND p.slug != ''
      AND ((v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery) OR p.name % v_term_norm OR lower(p.sku) LIKE '%'||v_term_norm||'%')
    ORDER BY 8 DESC LIMIT v_lim_each;
  END IF;

  IF 'quote' = ANY(p_types) THEN
    RETURN QUERY
    SELECT q.id::text, 'quote'::text, COALESCE(q.quote_number,'Orçamento')::text,
      ('Status: '||COALESCE(q.status,'—')||CASE WHEN q.total IS NOT NULL THEN ' · R$ '||to_char(q.total,'FM999G999G990D00') ELSE '' END)::text,
      ('/orcamentos/'||q.id::text)::text, NULL::text,
      jsonb_build_object('status',q.status,'total',q.total,'created_at',q.created_at),
      CASE WHEN lower(COALESCE(q.quote_number,'')) LIKE '%'||v_term_norm||'%' THEN 0.9
           WHEN lower(COALESCE(q.status,''))       LIKE '%'||v_term_norm||'%' THEN 0.5
           ELSE 0.3 END::numeric
    FROM quotes q
    WHERE lower(COALESCE(q.quote_number,'')) LIKE '%'||v_term_norm||'%'
       OR lower(COALESCE(q.status,''))       LIKE '%'||v_term_norm||'%'
    ORDER BY 8 DESC, q.created_at DESC LIMIT v_lim_each;
  END IF;
END;
$$;

-- Garantir que anon/authenticated não têm acesso direto (SECURITY DEFINER já protege)
REVOKE ALL ON FUNCTION public.fn_global_search(text, integer, text[]) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_global_search(text, integer, text[]) TO authenticated;
;

-- <<< END 20260622160302_fix_fn_global_search_remove_active_column_ref.sql <<<

