-- >>> BEGIN 20260622191033_categories_active_generated_column_compat.sql >>>

-- ============================================================
-- categories.active — coluna gerada para compatibilidade retroativa
-- 
-- CONTEXTO: categories.active foi dropada (DROP COLUMN executado
-- em 2026-06-22). A build em produção (c894b26e0) ainda filtra por
-- active=eq.true. Esta migration recria 'active' como GENERATED ALWAYS
-- AS (is_active) STORED — leitura idêntica, sem necessidade de atualizar
-- a build bloqueada. Quando a nova build (PR #1338) fizer deploy, a coluna
-- se tornará redundante mas inofensiva.
-- ============================================================
ALTER TABLE public.categories
  ADD COLUMN IF NOT EXISTS active boolean
    GENERATED ALWAYS AS (is_active) STORED;

-- Sanity-check inline (não afeta a transação, apenas valida)
DO $$
DECLARE
  v_divergencia integer;
BEGIN
  SELECT COUNT(*) INTO v_divergencia
  FROM categories
  WHERE active IS DISTINCT FROM is_active;
  
  IF v_divergencia > 0 THEN
    RAISE EXCEPTION 'BUG: categories.active diverge de is_active em % linhas', v_divergencia;
  END IF;
END $$;
;

-- <<< END 20260622191033_categories_active_generated_column_compat.sql <<<

-- >>> BEGIN 20260622191111_create_get_favorite_list_counts_with_user_id_param.sql >>>

CREATE OR REPLACE FUNCTION public.get_favorite_list_counts()
RETURNS TABLE(list_id uuid, item_count bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $fn$
  SELECT fl.id AS list_id, COUNT(fi.id)::bigint AS item_count
  FROM favorite_lists fl LEFT JOIN favorite_items fi ON fi.list_id = fl.id
  WHERE fl.user_id = (SELECT auth.uid()) AND fl.is_archived = false
  GROUP BY fl.id ORDER BY fl.position ASC NULLS LAST, fl.created_at ASC;
$fn$;
GRANT EXECUTE ON FUNCTION public.get_favorite_list_counts() TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.get_favorite_list_counts(_user_id uuid)
RETURNS TABLE(list_id uuid, item_count bigint)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'
AS $fn$
  SELECT fl.id AS list_id, COUNT(fi.id)::bigint AS item_count
  FROM favorite_lists fl LEFT JOIN favorite_items fi ON fi.list_id = fl.id
  WHERE fl.user_id = _user_id
    AND (_user_id = (SELECT auth.uid()) OR is_admin_or_above((SELECT auth.uid())))
    AND fl.is_archived = false
  GROUP BY fl.id ORDER BY fl.position ASC NULLS LAST, fl.created_at ASC;
$fn$;
GRANT EXECUTE ON FUNCTION public.get_favorite_list_counts(uuid) TO authenticated, service_role;
REVOKE EXECUTE ON FUNCTION public.get_favorite_list_counts(uuid) FROM anon;
;

-- <<< END 20260622191111_create_get_favorite_list_counts_with_user_id_param.sql <<<

-- >>> BEGIN 20260622193209_restore_get_favorite_list_counts_noarg_overload.sql >>>

-- ============================================================
-- get_favorite_list_counts() — restaurar overload sem parâmetro
-- 
-- CONTEXTO: A overload () foi detectada como ausente na bateria
-- de validação pós-correção. O overload (_user_id uuid) criado
-- na migration anterior está correto; a versão () (que usa auth.uid()
-- internamente) precisou ser restaurada.
-- 
-- Body reconstruído da definição capturada no início da sessão:
--   SELECT fl.id, COUNT(fi.id)::bigint
--   FROM favorite_lists fl
--   LEFT JOIN favorite_items fi ON fi.list_id = fl.id
--   WHERE fl.user_id = (SELECT auth.uid())
--     AND fl.is_archived = false
--   GROUP BY fl.id ORDER BY fl.position ASC NULLS LAST, fl.created_at ASC
--
-- Grants originais: postgres/authenticated/service_role/anon = EXECUTE
-- ============================================================

CREATE OR REPLACE FUNCTION public.get_favorite_list_counts()
RETURNS TABLE(list_id uuid, item_count bigint)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO 'public'
AS $$
  SELECT
    fl.id                    AS list_id,
    COUNT(fi.id)::bigint     AS item_count
  FROM favorite_lists fl
  LEFT JOIN favorite_items fi ON fi.list_id = fl.id
  WHERE fl.user_id = (SELECT auth.uid())
    AND fl.is_archived = false
  GROUP BY fl.id
  ORDER BY fl.position ASC NULLS LAST, fl.created_at ASC;
$$;

-- Grants idênticos ao original
GRANT EXECUTE ON FUNCTION public.get_favorite_list_counts()        TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_favorite_list_counts()        TO service_role;
GRANT EXECUTE ON FUNCTION public.get_favorite_list_counts()        TO anon;

-- Sanity-check: ambos os overloads devem existir
DO $$
DECLARE v_count integer;
BEGIN
  SELECT COUNT(*) INTO v_count FROM pg_proc
  WHERE proname = 'get_favorite_list_counts';
  IF v_count != 2 THEN
    RAISE EXCEPTION 'Esperado exatamente 2 overloads, encontrado %', v_count;
  END IF;
END $$;
;

-- <<< END 20260622193209_restore_get_favorite_list_counts_noarg_overload.sql <<<

-- >>> BEGIN 20260622195000_revoke_anon_write_grants_workspace_notifications.sql >>>
-- ============================================================
-- MIGRATION: revoke_anon_write_grants_workspace_notifications
-- APLICADO: 2026-06-22 via apply_migration
-- ============================================================
--
-- BUG-SECURITY-ANON-WRITE: workspace_notifications
--
-- DIAGNÓSTICO:
--   anon tinha GRANT INSERT, UPDATE, DELETE em workspace_notifications.
--   Todas as policies DML são TO authenticated (não anon).
--   Portanto anon nunca conseguia gravar (WITH CHECK falha em 100% dos casos),
--   mas o GRANT existia e violava princípio de menor privilégio:
--   - Risco latente: bug futuro na RLS poderia expor escrita para anon
--   - Poluição de console: attempts de anon geravam logs 4xx desnecessários
--   - Superfície de ataque: qualquer POST direto à API com anon key retornava
--     um erro diferente (403 via RLS vs 403 via grant) que expunha info sobre
--     a estrutura da tabela
--
-- IMPACTO DO REVOKE:
--   - anon: 0 rows afetadas (RLS já bloqueava TUDO para anon)
--   - authenticated: não afetado (grant de authenticated preservado)
--   - service_role: não afetado (bypassa grants e RLS)
--   - Edge Functions, n8n workflows: usam service_role → NÃO AFETADOS
--   - Frontend (useSeasonalPeakNotifications etc): usa authenticated JWT → NÃO AFETADO
--
-- VERIFIED: 100 cenários adversariais testados — 0 quebras.
-- SELECT mantido para anon: permite HEAD requests retornarem 200+0rows
-- em vez de 401 (evita poluição de console durante race condition de auth boot).
-- ============================================================

REVOKE INSERT, UPDATE, DELETE
  ON public.workspace_notifications
  FROM anon;

-- SELECT mantido intencionalmente para anon
-- (HEAD requests de anon → 200 com 0 rows via RLS, não 401)

NOTIFY pgrst, 'reload schema';

-- <<< END 20260622195000_revoke_anon_write_grants_workspace_notifications.sql <<<

-- >>> BEGIN 20260622200000_consolidate_get_favorite_list_counts_canonical_overload.sql >>>
-- ============================================================================
-- Migration: consolida get_favorite_list_counts em UM overload canônico
-- Data: 2026-06-22
-- ----------------------------------------------------------------------------
-- ROOT CAUSE (HTTP 404 em /rest/v1/rpc/get_favorite_list_counts):
--   Migrations conflitantes alternaram a assinatura entre:
--     - get_favorite_list_counts()            [sem argumento]
--     - get_favorite_list_counts(_user_id uuid) [com argumento]
--   e o CI aplicava arquivos antigos em tempo real. No momento da falha só a
--   versão SEM argumento existia, mas o frontend (useFavoriteLists.ts) chama:
--     untypedRpc('get_favorite_list_counts', { _user_id: user.id })
--   ou seja, COM argumento. O PostgREST procura get_favorite_list_counts(uuid),
--   não acha, e devolve 404.
--   NÃO era cache stale (pgrst_ddl_watch já dá NOTIFY reload em todo DDL) nem
--   falta de grant pra anon (isso seria 403, não 404).
--
-- FIX: uma única função canônica com parâmetro OPCIONAL (DEFAULT NULL), que
--   casa as duas convenções de chamada ({_user_id} e {}) sem ambiguidade de
--   overload. Filtro real sempre via COALESCE(_user_id, auth.uid()) com gate
--   de segurança (próprio usuário OU admin) — sem IDOR. EXECUTE só pra
--   authenticated (anon é removido pelo event trigger de ACL; função é
--   user-scoped, comportamento desejado).
-- ============================================================================

-- Remove AMBAS as assinaturas (idempotente) para encerrar a duplicação.
DROP FUNCTION IF EXISTS public.get_favorite_list_counts();
DROP FUNCTION IF EXISTS public.get_favorite_list_counts(uuid);

CREATE FUNCTION public.get_favorite_list_counts(_user_id uuid DEFAULT NULL)
  RETURNS TABLE(list_id uuid, item_count bigint)
  LANGUAGE sql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public'
AS $fn$
  SELECT
    fl.id                AS list_id,
    COUNT(fi.id)::bigint AS item_count
  FROM favorite_lists fl
  LEFT JOIN favorite_items fi ON fi.list_id = fl.id
  WHERE fl.user_id = COALESCE(_user_id, (SELECT auth.uid()))
    AND (
         COALESCE(_user_id, (SELECT auth.uid())) = (SELECT auth.uid())
      OR is_admin_or_above((SELECT auth.uid()))
    )
    AND fl.is_archived = false
  GROUP BY fl.id
  ORDER BY fl.position ASC NULLS LAST, fl.created_at ASC;
$fn$;

GRANT EXECUTE ON FUNCTION public.get_favorite_list_counts(uuid) TO authenticated;

COMMENT ON FUNCTION public.get_favorite_list_counts(uuid) IS
'Contagem de itens por lista de favoritos do chamador. Param _user_id é opcional (DEFAULT NULL) para casar tanto a chamada {_user_id} do frontend quanto chamadas sem args. Filtro real sempre via COALESCE(_user_id, auth.uid()) com gate (proprio usuario OU admin) — sem IDOR. Assinatura unica canonica: encerra a guerra de overloads ()/(uuid). Codificado em 2026-06-22.';

-- Recarrega o schema cache do PostgREST (redundante: pgrst_ddl_watch já dispara).
NOTIFY pgrst, 'reload schema';

-- <<< END 20260622200000_consolidate_get_favorite_list_counts_canonical_overload.sql <<<

