-- >>> BEGIN 20260623111049_products_dimensions_2_vproducts_public_computed_dimensions_20260623.sql >>>

-- ══════════════════════════════════════════════════════════════════
-- Melhoria 2: Substituir p.dimensions por jsonb computado dos escalares
-- em v_products_public (contrato de API do frontend)
-- 
-- Antes: p.dimensions  → lê o jsonb bruto (legado, divergências)
-- Depois: jsonb_build_object(...) → usa escalares (fonte de verdade)
-- 
-- BACKWARD COMPAT: mesmas chaves que o frontend consume:
--   length_cm, width_cm, height_cm, weight_g, diameter_cm, shape_type, unit_detected
-- MELHORIA: weight_g agora incluído (antes não estava no jsonb original para muitos)
-- NULL: quando nenhum escalar disponível → NULL (igual ao comportamento anterior)
-- ══════════════════════════════════════════════════════════════════
CREATE OR REPLACE VIEW public.v_products_public AS
 SELECT p.id,
    p.name,
    p.description,
    p.sku,
    p.category_id,
    p.supplier_id,
    NULL::numeric AS cost_price,
    p.sale_price,
    p.stock_quantity,
    p.is_active AS active,
    p.created_at,
    p.updated_at,
    NULL::numeric AS suggested_price,
    -- MELHORIA 2: computed dimensions a partir dos escalares (fonte de verdade)
    -- Antes: p.dimensions (jsonb legado com possíveis divergências)
    -- Após: jsonb construído dos escalares canonicais
    CASE
      WHEN p.length_cm IS NOT NULL
        OR p.width_cm IS NOT NULL
        OR p.height_cm IS NOT NULL
        OR p.weight_g IS NOT NULL
        OR p.diameter_cm IS NOT NULL
        OR p.shape_type IS NOT NULL
      THEN jsonb_build_object(
        'length_cm',    p.length_cm,
        'width_cm',     p.width_cm,
        'height_cm',    p.height_cm,
        'weight_g',     p.weight_g,
        'diameter_cm',  p.diameter_cm,
        'shape_type',   p.shape_type,
        'unit_detected',p.dimensions_source
      )
      ELSE NULL
    END AS dimensions,
