-- >>> BEGIN 20260623112539_fix_webhook_outbox_try_catch_v2_20260623.sql >>>

-- ================================================================
-- MIGRATION: fix_webhook_outbox_try_catch_v2_20260623
-- PROBLEMA: Lovable bot sobrescreveu fn_process_webhook_outbox_batch
--   com versão que usa COALESCE(get_edge_function_secret(...), fallback)
--   mas COALESCE não captura RAISE EXCEPTION → erro propagado → job falha
-- ROOT CAUSE ORIGINAL: WEBHOOK_DISPATCHER_URL não existe no vault
--   → get_edge_function_secret lança RAISE EXCEPTION
--   → COALESCE não captura → 1440 falhas/dia no job 201
-- FIX v2:
--   - TRY-CATCH no bloco de obtenção de secrets (nível externo)
--   - Fallback para URL hardcoded se secret não existe no vault
--   - DEFAULT 50 (Lovable bot mudou para 10)
--   - Comentário anti-regressão
-- ================================================================

-- !! ATENÇÃO: NÃO SOBRESCREVER ESTA FUNÇÃO SEM MANTER O TRY-CATCH !!
-- !! O COALESCE não captura RAISE EXCEPTION do get_edge_function_secret !!
CREATE OR REPLACE FUNCTION public.fn_process_webhook_outbox_batch(
  _batch_size integer DEFAULT 50
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions', 'net'
AS $function$
-- FIX 2026-06-23 v2: TRY-CATCH obrigatório — COALESCE não captura RAISE
DECLARE
  _processed integer := 0;
  _skipped   integer := 0;
  _endpoint  text;
  _secret    text;
  _req_id    bigint;
  rec        RECORD;
BEGIN
  -- ── Endpoint ────────────────────────────────────────────────────────────
  -- OBRIGATÓRIO: TRY-CATCH aqui. COALESCE não funciona pois
  -- get_edge_function_secret usa RAISE EXCEPTION (não retorna NULL).
  BEGIN
    _endpoint := public.get_edge_function_secret('WEBHOOK_DISPATCHER_URL');
  EXCEPTION WHEN OTHERS THEN
    _endpoint := 'https://doufsxqlfjyuvxuezpln.supabase.co/functions/v1/webhook-dispatcher';
  END;

  -- ── Secret de autenticação ───────────────────────────────────────────────
  BEGIN
    _secret := public.get_edge_function_secret('WEBHOOK_SECRET');
  EXCEPTION WHEN OTHERS THEN
    BEGIN
      _secret := public.get_edge_function_secret('WEBHOOK_DISPATCHER_SECRET');
    EXCEPTION WHEN OTHERS THEN
      _secret := '';
    END;
  END;

  -- ── Processar batch ──────────────────────────────────────────────────────
  FOR rec IN
    SELECT id, event, payload, attempts, max_attempts
    FROM public.webhook_outbox
    WHERE status = 'pending'
      AND next_attempt_at <= NOW()
    ORDER BY created_at
    LIMIT _batch_size
    FOR UPDATE SKIP LOCKED
  LOOP
    UPDATE public.webhook_outbox
    SET status     = 'processing',
        attempts   = attempts + 1,
        updated_at = NOW()
    WHERE id = rec.id;

    BEGIN
      SELECT net.http_post(
        url     := _endpoint,
        headers := jsonb_build_object(
          'Content-Type',    'application/json',
          'x-webhook-secret', _secret,
          'x-event-type',    rec.event
        ),
        body := rec.payload::text
      ) INTO _req_id;

      UPDATE public.webhook_outbox
      SET status     = 'sent',
          sent_at    = NOW(),
          updated_at = NOW()
      WHERE id = rec.id;

      _processed := _processed + 1;

    EXCEPTION WHEN OTHERS THEN
      UPDATE public.webhook_outbox
      SET status          = CASE
                              WHEN rec.attempts >= rec.max_attempts THEN 'dead_letter'
                              ELSE 'pending'
                            END,
          error_message   = SQLERRM,
          next_attempt_at = NOW() + (POWER(2, LEAST(rec.attempts, 5)) * INTERVAL '1 minute'),
          updated_at      = NOW()
      WHERE id = rec.id;

      _skipped := _skipped + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'processed', _processed,
    'skipped',   _skipped,
    'endpoint',  _endpoint,
    'fix_version', 'v2_20260623'
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object(
    'error',     SQLERRM,
    'processed', _processed
  );
END;
$function$;

COMMENT ON FUNCTION public.fn_process_webhook_outbox_batch IS
  '!! NÃO USAR COALESCE COM get_edge_function_secret — usa RAISE, não retorna NULL !!
  TRY-CATCH obrigatório no bloco de obtenção de secrets.
  Fix v2 2026-06-23: regressão Lovable bot corrigida.';
;

-- <<< END 20260623112539_fix_webhook_outbox_try_catch_v2_20260623.sql <<<

-- >>> BEGIN 20260623112733_fix_get_top_collected_products_security_definer_20260623.sql >>>

-- =============================================================================
-- FIX: get_top_collected_products → SECURITY DEFINER
-- =============================================================================
-- ROOT CAUSE: função era SECURITY INVOKER e acessa archive.collection_items.
-- authenticated NÃO tem USAGE no schema archive → PostgreSQL retorna
-- "permission denied for schema archive" → PostgREST traduz para HTTP 403.
-- Mesmo bug que afetou get_collections_weekly_count (fix 2026-06-21).
--
-- FIX: SECURITY DEFINER + SET search_path = public, archive
-- A função executa com permissões do owner (postgres), que tem acesso total
-- ao schema archive. RLS de archive.collection_items ainda se aplica.
-- =============================================================================

CREATE OR REPLACE FUNCTION public.get_top_collected_products(
  _days integer DEFAULT 7,
  _limit integer DEFAULT 6
)
RETURNS TABLE(product_id text, col_count bigint)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, archive
AS $$
  SELECT ci.product_id, COUNT(*)::bigint AS col_count
  FROM archive.collection_items ci
  WHERE ci.created_at >= (now() - make_interval(days => GREATEST(_days, 1)))
  GROUP BY ci.product_id
  ORDER BY col_count DESC, MAX(ci.created_at) DESC
  LIMIT GREATEST(_limit, 1);
$$;

-- Re-confirm grants (idempotente)
GRANT EXECUTE ON FUNCTION public.get_top_collected_products(integer, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_top_collected_products(integer, integer) TO anon;
GRANT EXECUTE ON FUNCTION public.get_top_collected_products(integer, integer) TO service_role;

NOTIFY pgrst, 'reload schema';
;

-- <<< END 20260623112733_fix_get_top_collected_products_security_definer_20260623.sql <<<

-- >>> BEGIN 20260623112825_add_icon_lucide_format_constraint_to_categories.sql >>>

-- ═══════════════════════════════════════════════════════════════════════════
-- MIGRAÇÃO: add_icon_lucide_format_constraint_to_categories
-- Objetivo:  Garantir que categories.icon sempre seja um nome válido de
--            ícone Lucide React (PascalCase, somente letras/dígitos,
--            inicia com maiúscula).
-- Impacto:   APENAS VALIDAÇÃO — não altera nenhum dado existente.
-- Rollback:  ALTER TABLE categories DROP CONSTRAINT chk_icon_lucide_format;
-- Autor:     Sistema — Melhoria 1 de 3
-- ═══════════════════════════════════════════════════════════════════════════

-- ── GUARDA: abortar se algum valor existente quebraria a constraint ──────
DO $$
DECLARE
  v_bad_count  INTEGER;
  v_bad_sample TEXT;
BEGIN
  SELECT COUNT(*), STRING_AGG(DISTINCT icon, ', ' ORDER BY icon)
    INTO v_bad_count, v_bad_sample
  FROM public.categories
  WHERE icon IS NOT NULL
    AND NOT (icon ~ '^[A-Z][a-zA-Z0-9]+$');

  IF v_bad_count > 0 THEN
    RAISE EXCEPTION
      'ABORTADO: % valores existentes não passam no regex. Exemplos: [%]. '
      'Corrigir dados antes de aplicar a constraint.',
      v_bad_count, v_bad_sample;
  END IF;

  RAISE NOTICE 'PRÉ-VALIDAÇÃO OK: todos os valores existentes passam no regex.';
END;
$$;

-- ── APLICAR CONSTRAINT ───────────────────────────────────────────────────
ALTER TABLE public.categories
  ADD CONSTRAINT chk_icon_lucide_format
  CHECK (
    icon IS NULL
    OR (icon ~ '^[A-Z][a-zA-Z0-9]+$')
  )
  NOT VALID;          -- Verifica novos registros imediatamente;
                      -- valida rows existentes em background sem lock longo.

-- Validar rows existentes (confirma que TODOS passam — finaliza a constraint)
ALTER TABLE public.categories
  VALIDATE CONSTRAINT chk_icon_lucide_format;

-- ── COMENTÁRIO INLINE para futuros devs ─────────────────────────────────
COMMENT ON COLUMN public.categories.icon IS
  'Nome PascalCase de ícone Lucide React (ex: Coffee, Wine, PawPrint, Gamepad2). '
  'Regra: deve começar com letra maiúscula [A-Z], seguido de letras e/ou dígitos. '
  'Constraint chk_icon_lucide_format garante formato válido. '
  'Usado pelo frontend React para renderizar dinamicamente o ícone de cada categoria. '
  'Fonte de verdade: este campo. Tabela category_icons é legada/redundante.';
;

-- <<< END 20260623112825_add_icon_lucide_format_constraint_to_categories.sql <<<

