-- >>> BEGIN 20260623113125_upgrade_category_icons_uuid_fk_and_sync_trigger.sql >>>

-- ═══════════════════════════════════════════════════════════════════════════
-- MIGRAÇÃO: upgrade_category_icons_uuid_fk_and_sync_trigger
-- Melhoria 2 de 3 — Arquitetura UUID FK + Trigger de sync robusto
-- ═══════════════════════════════════════════════════════════════════════════

-- ── PASSO 1: Coluna category_id (nullable para backfill seguro) ──────────
ALTER TABLE public.category_icons
  ADD COLUMN IF NOT EXISTS category_id UUID
    REFERENCES public.categories(id)
    ON UPDATE CASCADE
    ON DELETE SET NULL;

COMMENT ON COLUMN public.category_icons.category_id IS
  'FK para categories(id). Substitui link frágil por TEXT. '
  'ON UPDATE CASCADE / ON DELETE SET NULL. Backfilled por nome.';

-- ── PASSO 2: Backfill — DISTINCT ON para desambiguar nomes duplicados ────
UPDATE public.category_icons ci
SET category_id = sub.cat_id
FROM (
  SELECT DISTINCT ON (ci2.id)
    ci2.id  AS ci_id,
    c.id    AS cat_id
  FROM public.category_icons ci2
  JOIN public.categories c ON c.name = ci2.category_name
  WHERE ci2.category_id IS NULL
  ORDER BY
    ci2.id,
    c.is_active   DESC,
    c.level       ASC,
    c.display_order ASC,
    c.created_at  ASC
) sub
WHERE ci.id = sub.ci_id;

-- ── PASSO 3: Índice único parcial em category_id ─────────────────────────
CREATE UNIQUE INDEX IF NOT EXISTS idx_category_icons_category_id_unique
  ON public.category_icons (category_id)
  WHERE category_id IS NOT NULL;

-- ── PASSO 4: Função do trigger (UUID-first, fallback por nome) ───────────
CREATE OR REPLACE FUNCTION public.fn_sync_categories_icon_to_registry()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN

  -- ── INSERT em categories → registrar icon ─────────────────────────────
  IF TG_OP = 'INSERT' THEN
    IF NEW.icon IS NOT NULL THEN
      INSERT INTO public.category_icons
        (category_id, category_name, icon, is_active, created_at, updated_at)
      VALUES
        (NEW.id, NEW.name, NEW.icon, NEW.is_active, NOW(), NOW())
      ON CONFLICT (category_id) WHERE category_id IS NOT NULL
        DO UPDATE SET
          icon          = EXCLUDED.icon,
          category_name = EXCLUDED.category_name,
          is_active     = EXCLUDED.is_active,
          updated_at    = NOW();
    END IF;
    RETURN NEW;
  END IF;

  -- ── UPDATE em categories → sincronizar ────────────────────────────────
  IF TG_OP = 'UPDATE' THEN

    -- Early exit se nada relevante mudou
    IF NOT (
      NEW.icon         IS DISTINCT FROM OLD.icon
      OR NEW.name      IS DISTINCT FROM OLD.name
      OR NEW.is_active IS DISTINCT FROM OLD.is_active
    ) THEN
      RETURN NEW;
    END IF;

    -- ── CASO A: Icon removido → desativar ─────────────────────────────
    IF NEW.icon IS NULL THEN
      UPDATE public.category_icons
        SET is_active  = false, updated_at = NOW()
      WHERE category_id = NEW.id;

      IF NOT FOUND THEN
        UPDATE public.category_icons
          SET is_active  = false, updated_at = NOW()
        WHERE category_name = OLD.name AND category_id IS NULL;
      END IF;

    -- ── CASO B: Icon definido → sincronizar ───────────────────────────
    ELSE

      -- Tentativa 1: via UUID (rota precisa)
      UPDATE public.category_icons
        SET icon          = NEW.icon,
            category_name = NEW.name,
            is_active     = NEW.is_active,
            updated_at    = NOW()
      WHERE category_id = NEW.id;

      -- Tentativa 2: adotar entrada legada sem UUID (fallback por nome)
      IF NOT FOUND THEN
        -- CTE para limitar a 1 linha sem LIMIT no UPDATE direto
        WITH legado AS (
          SELECT id
          FROM public.category_icons
          WHERE category_name = OLD.name
            AND category_id IS NULL
          ORDER BY created_at ASC
          LIMIT 1
        )
        UPDATE public.category_icons ci
          SET category_id   = NEW.id,
              icon          = NEW.icon,
              category_name = NEW.name,
              is_active     = NEW.is_active,
              updated_at    = NOW()
        FROM legado
        WHERE ci.id = legado.id;
      END IF;

      -- Tentativa 3: criar nova entrada se nenhuma foi encontrada
      IF NOT FOUND THEN
        INSERT INTO public.category_icons
          (category_id, category_name, icon, is_active, created_at, updated_at)
        VALUES
          (NEW.id, NEW.name, NEW.icon, NEW.is_active, NOW(), NOW())
        ON CONFLICT (category_id) WHERE category_id IS NOT NULL
          DO UPDATE SET
            icon          = EXCLUDED.icon,
            category_name = EXCLUDED.category_name,
            is_active     = EXCLUDED.is_active,
            updated_at    = NOW();
      END IF;

    END IF; -- fim CASO A / CASO B

    RETURN NEW;
  END IF;

  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.fn_sync_categories_icon_to_registry() IS
  'Sincroniza category_icons quando categories.icon/name/is_active mudam. '
  'Estratégia 3 camadas: (1) UUID exact, (2) adotar entrada legada sem UUID, '
  '(3) criar nova entrada. SECURITY DEFINER para contornar RLS em category_icons.';

-- ── PASSO 5: Criar o trigger ──────────────────────────────────────────────
DROP TRIGGER IF EXISTS trg_sync_category_icon ON public.categories;

CREATE TRIGGER trg_sync_category_icon
  AFTER INSERT OR UPDATE OF icon, name, is_active
  ON public.categories
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_sync_categories_icon_to_registry();
;

-- <<< END 20260623113125_upgrade_category_icons_uuid_fk_and_sync_trigger.sql <<<

-- >>> BEGIN 20260623113215_fix_vw_category_completeness_icon_check.sql >>>

-- ═══════════════════════════════════════════════════════════════════════════
-- MIGRAÇÃO: fix_vw_category_completeness_icon_check
-- Objetivo:  Substituir subquery correlacionada em category_icons (frágil,
--            lenta) por verificação direta em categories.icon (fonte real).
-- Mudanças:
--   ANTES: EXISTS (SELECT 1 FROM category_icons WHERE category_name = c.name...)
--   DEPOIS: c.icon IS NOT NULL
-- Benefícios:
--   1. Corretude: usa a fonte de verdade real
--   2. Performance: elimina 2 subqueries correlacionadas por linha
--   3. Consistência: alinhado com a constraint chk_icon_lucide_format
-- Rollback: recriar a versão anterior (backup inline nos comentários abaixo)
-- Autor:  Sistema — Melhoria 3 de 3
-- ═══════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE VIEW public.vw_category_completeness AS
SELECT
  c.id,
  c.name,
  c.slug,
  c.level,
  c.is_active,
  c.is_visible,
  c.products_count,

  -- Contagens de produtos (mantidas idênticas ao original)
  COUNT(DISTINCT p.id)   FILTER (WHERE p.is_active = true) AS produtos_ativos_main,
  COUNT(DISTINCT pca.product_id)                           AS produtos_via_pca,

  -- ── FLAGS DE COMPLETUDE ────────────────────────────────────────────────
  -- copywriting: mantido (subquery correta, não usa category_icons)
  EXISTS (
    SELECT 1 FROM public.category_copywriting_config cfg
    WHERE cfg.category_id = c.id
  ) AS tem_copywriting,

  -- ícone: CORRIGIDO — antes fazia JOIN frágil em category_icons por nome
  -- ANTES: EXISTS (SELECT 1 FROM category_icons ci WHERE ci.category_name = c.name AND ci.is_active = true)
  -- DEPOIS: verifica diretamente a fonte de verdade
  (c.icon IS NOT NULL)   AS tem_icone,

  (c.meta_title IS NOT NULL)    AS tem_seo_title,
  (c.color_hex IS NOT NULL)     AS tem_cor,
  (c.image_url IS NOT NULL)     AS tem_imagem,

  -- ── SCORE DE COMPLETUDE (0–100 pts) ───────────────────────────────────
  ROUND(
    (
      -- meta_title:    20 pts
      CASE WHEN c.meta_title IS NOT NULL THEN 20 ELSE 0 END
      -- copywriting:   20 pts
      + CASE WHEN EXISTS (
          SELECT 1 FROM public.category_copywriting_config cfg
          WHERE cfg.category_id = c.id
        ) THEN 20 ELSE 0 END
      -- ícone:         15 pts — CORRIGIDO (era subquery em category_icons)
      + CASE WHEN c.icon IS NOT NULL THEN 15 ELSE 0 END
      -- cor:           10 pts
      + CASE WHEN c.color_hex IS NOT NULL THEN 10 ELSE 0 END
      -- imagem:        15 pts
      + CASE WHEN c.image_url IS NOT NULL THEN 15 ELSE 0 END
      -- descrição:     10 pts
      + CASE WHEN c.description IS NOT NULL THEN 10 ELSE 0 END
      -- meta_descr:    10 pts
      + CASE WHEN c.meta_description IS NOT NULL THEN 10 ELSE 0 END
    )::NUMERIC,
    0
  ) AS completude_score

FROM public.categories c
LEFT JOIN public.products p
  ON p.main_category_id = c.id
LEFT JOIN public.product_category_assignments pca
  ON pca.category_id = c.id

WHERE c.is_active = true

GROUP BY
  c.id, c.name, c.slug, c.level, c.is_active, c.is_visible,
  c.products_count, c.meta_title, c.color_hex, c.image_url,
  c.description, c.meta_description, c.icon      -- adicionado c.icon ao GROUP BY

ORDER BY
  c.level,
  ROUND(
    (
      CASE WHEN c.meta_title IS NOT NULL THEN 20 ELSE 0 END
      + CASE WHEN EXISTS (
          SELECT 1 FROM public.category_copywriting_config cfg
          WHERE cfg.category_id = c.id
        ) THEN 20 ELSE 0 END
      + CASE WHEN c.icon IS NOT NULL THEN 15 ELSE 0 END
      + CASE WHEN c.color_hex IS NOT NULL THEN 10 ELSE 0 END
      + CASE WHEN c.image_url IS NOT NULL THEN 15 ELSE 0 END
      + CASE WHEN c.description IS NOT NULL THEN 10 ELSE 0 END
      + CASE WHEN c.meta_description IS NOT NULL THEN 10 ELSE 0 END
    )::NUMERIC,
    0
  ) DESC;

COMMENT ON VIEW public.vw_category_completeness IS
  'Score de completude por categoria (0–100 pts). '
  'Pesos: meta_title(20) + copywriting(20) + icone(15) + imagem(15) + '
  'cor(10) + descrição(10) + meta_description(10). '
  'CORRIGIDO em 2024: icone usa categories.icon IS NOT NULL em vez de '
  'subquery em category_icons (que era frágil e lenta).';
;

-- <<< END 20260623113215_fix_vw_category_completeness_icon_check.sql <<<

-- >>> BEGIN 20260623113644_skip_somarcas_stale_bronze_96_rows.sql >>>

-- Marcar 96 rows Só Marcas pendentes como 'skipped'
-- Critério: status=pending, imported_at < now()-1h, product_id já linkado
-- Batch não está mais running → rows são orfanadas seguras para skip
SET LOCAL app.write_source = 'admin';

UPDATE public.supplier_products_raw
SET status = 'skipped'
WHERE supplier_id = (SELECT id FROM suppliers WHERE name='Só Marcas')
  AND status = 'pending'
  AND imported_at < now() - interval '1 hour'
  AND product_id IS NOT NULL;  -- só rows com produto já linkado (seguro)
;

-- <<< END 20260623113644_skip_somarcas_stale_bronze_96_rows.sql <<<

