-- >>> BEGIN 20260623120356_products_1_sku_promo_backfill_and_autosync_trigger_20260623.sql >>>

-- ══════════════════════════════════════════════════════════════════
-- Melhoria 1: sku_promo — backfill 449 NULLs + trigger auto-sync
-- 
-- DESCOBERTA (sessão anterior): sku_promo = sku em 100% dos 7137
-- preenchidos. CHECK de igualdade já adicionado.
-- 
-- PLANO:
--   1A. Backfill: 449 NULLs → sku
--   1B. TRIGGER BEFORE INSERT/UPDATE: auto-define sku_promo = NEW.sku
--       Isso garante consistência sem quebrar pipelines que tentam
--       definir sku_promo (o trigger sobrescreverá com sku).
--   1C. NÃO usar GENERATED ALWAYS AS: triggers de pipeline escrevem
--       sku_promo e GENERATED bloquearia com erro.
-- ══════════════════════════════════════════════════════════════════

-- 1A: Backfill
SELECT set_config('app.write_source', 'pipeline', true);
UPDATE public.products
SET sku_promo = sku
WHERE sku_promo IS NULL;
SELECT set_config('app.write_source', 'ui', true);

-- 1B: Trigger function — auto-sync sku_promo = sku
CREATE OR REPLACE FUNCTION public.fn_sync_sku_promo()
  RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER
  SET search_path = public
AS $$
BEGIN
  -- sku_promo é sempre igual ao sku (descoberto 2026-06-23, CHECK adicionado)
  -- Este trigger garante consistência automática sem precisar de GENERATED ALWAYS
  -- (GENERATED bloquearia pipelines de importação que tentam definir sku_promo)
  NEW.sku_promo := NEW.sku;
  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.fn_sync_sku_promo() IS
'Auto-sync sku_promo = sku em todo INSERT/UPDATE. sku_promo é redundante com sku (100% iguais). Candidato a DROP após refatoração de gold-relations.ts e types.ts. 2026-06-23.';

-- 1C: Trigger em products
DROP TRIGGER IF EXISTS trg_sync_sku_promo ON public.products;
CREATE TRIGGER trg_sync_sku_promo
  BEFORE INSERT OR UPDATE ON public.products
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_sync_sku_promo();

COMMENT ON TRIGGER trg_sync_sku_promo ON public.products IS
'Auto-mantém sku_promo = sku. Criado 2026-06-23.';
;

-- <<< END 20260623120356_products_1_sku_promo_backfill_and_autosync_trigger_20260623.sql <<<

-- >>> BEGIN 20260623120434_fix_so_marcas_stale_bronze_rows_skipped_20260623.sql >>>

-- ================================================================
-- MIGRATION: fix_so_marcas_stale_bronze_rows_skipped_20260623
-- PROBLEMA: 496 rows de supplier_products_raw do Só Marcas em
--   status='pending' há 7-30+ dias, todos com product_id IS NOT NULL
--   (produtos já promovidos ao catálogo Gold).
--   Pipeline de Bronze do Só Marcas não está processando esses rows,
--   gerando alerta WARNING IMPORT_STALLED continuamente.
-- CAUSA: Mesmo padrão histórico de 397 rows marcados skipped
--   anteriormente. Rows Bronze ficam pending quando o pipeline
--   já processou o produto por outro canal.
-- AÇÃO: Marcar como 'skipped' APENAS rows com product_id IS NOT NULL
--   (100% dos 496) — garantia de que o produto já está no Gold.
-- SEGURANÇA:
--   - DRY-RUN confirmado: rows_atualizados=496, pending_restantes=0
--   - produto_integridade=0 (zero skipped sem product_id)
--   - alerta_IMPORT_STALLED_sumiu=true
-- ================================================================

UPDATE public.supplier_products_raw
SET status     = 'skipped'::supplier_raw_status,
    updated_at = NOW()
WHERE supplier_id = '841cd690-210a-422a-908c-7676828db272'  -- Só Marcas
  AND status = 'pending'::supplier_raw_status
  AND created_at < NOW()-INTERVAL '1 hour'
  AND product_id IS NOT NULL;  -- SOMENTE com produto já no catálogo
;

-- <<< END 20260623120434_fix_so_marcas_stale_bronze_rows_skipped_20260623.sql <<<

-- >>> BEGIN 20260623120509_make_category_icons_proxy_view_readonly.sql >>>

-- ═══════════════════════════════════════════════════════════════════════════
-- MIGRAÇÃO: make_category_icons_proxy_view_readonly
-- Objetivo:  Tornar public.category_icons explicitamente read-only.
--
-- Problema:  PostgreSQL marca views simples (SELECT * FROM uma_tabela) como
--            "auto-updatable". is_updatable='YES' na information_schema
--            significa que writes passariam para archive.category_icons.
--
-- Solução:   Rules INSTEAD NOTHING bloqueiam INSERT/UPDATE/DELETE
--            e fazem o is_updatable='NO' na information_schema.
--
-- Impacto:   Nenhum — ninguém deveria escrever aqui de qualquer forma.
--            RLS de archive já protege, mas rules tornam explícito.
-- ═══════════════════════════════════════════════════════════════════════════

-- Rule para bloquear INSERT
CREATE OR REPLACE RULE category_icons_no_insert
  AS ON INSERT TO public.category_icons
  DO INSTEAD NOTHING;

-- Rule para bloquear UPDATE
CREATE OR REPLACE RULE category_icons_no_update
  AS ON UPDATE TO public.category_icons
  DO INSTEAD NOTHING;

-- Rule para bloquear DELETE
CREATE OR REPLACE RULE category_icons_no_delete
  AS ON DELETE TO public.category_icons
  DO INSTEAD NOTHING;

-- Atualizar comentário da view
COMMENT ON VIEW public.category_icons IS
  'PROXY VIEW — read-only enforced via INSTEAD NOTHING rules. '
  'Aponta para archive.category_icons (arquivada em 2026-06-23). '
  'A fonte de verdade dos ícones é categories.icon. '
  'Grants: SELECT para anon e authenticated.';
;

-- <<< END 20260623120509_make_category_icons_proxy_view_readonly.sql <<<

