CREATE OR REPLACE FUNCTION public.check_seller_cart_limit()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock(415264, hashtext(NEW.seller_id::text));
  IF (SELECT COUNT(*) FROM public.seller_carts WHERE seller_id = NEW.seller_id) >= 10 THEN
    RAISE EXCEPTION 'Limite de 10 carrinhos por vendedor atingido' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$;

-- <<< END 20260623124424_6d7c15e4-9aba-4f70-8619-f3ba7af1d5c6.sql <<<

-- >>> BEGIN 20260623130000_cart_batch_sort_order_rpc.sql >>>
-- BUG-6 FIX: updateItemSortOrder executava N requests paralelos via Promise.all.
-- Com carrinhos grandes (50-200 itens) isso gerava N conexões DB simultâneas e
-- risco de rate limit no PostgREST. Esta função substitui por 1 round-trip.
--
-- Segurança: SECURITY DEFINER com SET search_path evita privilege escalation.
-- RLS guard interno: só atualiza itens cujo carrinho-pai pertence a auth.uid().

CREATE OR REPLACE FUNCTION public.fn_batch_update_cart_item_sort_order(
  p_updates jsonb
)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_uid uuid := auth.uid();
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Não autenticado' USING ERRCODE = '28000';
  END IF;

  -- Valida entrada: deve ser um array JSON não-vazio
  IF jsonb_typeof(p_updates) <> 'array' OR jsonb_array_length(p_updates) = 0 THEN
    RETURN; -- no-op silencioso para chamadas vazias/inválidas
  END IF;

  -- Atualiza em um único UPDATE ... FROM (VALUES) com guard de ownership.
  -- RLS não se aplica em SECURITY DEFINER — usamos o EXISTS manual.
  UPDATE public.seller_cart_items sci
  SET
    sort_order = (u->>'sort_order')::integer,
    updated_at = now()
  FROM jsonb_array_elements(p_updates) AS u
  WHERE
    sci.id = (u->>'id')::uuid
    AND EXISTS (
      SELECT 1 FROM public.seller_carts sc
      WHERE sc.id = sci.cart_id
        AND sc.seller_id = v_uid
    );
END;
$$;

GRANT EXECUTE ON FUNCTION public.fn_batch_update_cart_item_sort_order(jsonb) TO authenticated;

-- <<< END 20260623130000_cart_batch_sort_order_rpc.sql <<<

-- >>> BEGIN 20260623130000_fix_restore_trigger_notify_discount_approval.sql >>>
-- =============================================================================
-- FIX: Restaurar trigger trg_notify_discount_approval em discount_approval_requests
-- =============================================================================
-- BUG: A migration 20260414232158_6a8d4128 removeu o trigger sem recriar.
-- IMPACTO: Quando vendedor solicita desconto acima do limite, admins NAO
-- recebem workspace_notification de alerta. Quando admin aprova/rejeita,
-- vendedor NAO recebe workspace_notification de retorno.
-- CONFIRMADO por Joaquim: todo mundo deve receber notificacao automatica.
-- DESCOBERTO: auditoria adversarial 2026-06-23.
--
-- Fluxo do trigger:
--   INSERT + status='pending' -> notifica TODOS os admins (role='admin')
--   UPDATE pending->approved  -> notifica vendedor: desconto aprovado
--   UPDATE pending->rejected  -> notifica vendedor: desconto recusado + motivo
--
-- A funcao notify_discount_approval_request() ja estava:
--   - SECURITY DEFINER
--   - SET search_path = public
--   - Corretamente implementada
-- =============================================================================

DROP TRIGGER IF EXISTS trg_notify_discount_approval ON public.discount_approval_requests;

CREATE TRIGGER trg_notify_discount_approval
  AFTER INSERT OR UPDATE ON public.discount_approval_requests
  FOR EACH ROW
  EXECUTE FUNCTION public.notify_discount_approval_request();

-- <<< END 20260623130000_fix_restore_trigger_notify_discount_approval.sql <<<

-- >>> BEGIN 20260623130516_tighten_icon_constraint_require_lowercase_second_char.sql >>>

-- ═══════════════════════════════════════════════════════════════════════════
-- MIGRAÇÃO: tighten_icon_constraint_require_lowercase_second_char
-- Objetivo:  Fechar os 2 gaps identificados na auditoria exaustiva:
--            Gap B23: "COFFEE" (all-caps) passava no regex antigo
--            Gap B44: "NULL" (string all-caps) passava no regex antigo
--
-- Solução:   Apertar o regex de:
--              ANTIGO: ^[A-Z][a-zA-Z0-9]+$   (2º char pode ser qualquer coisa)
--              NOVO:   ^[A-Z][a-z][a-zA-Z0-9]*$  (2º char DEVE ser minúsculo)
--
-- Fundamento: TODOS os ícones Lucide React reais têm o 2º char em minúsculo.
--             Coffee (Co), Wine (Wi), GlassWater (Gl), PawPrint (Pa), Cpu (Cp)...
--             Nenhum ícone Lucide começa com dois caracteres maiúsculos.
--
-- Verificação prévia: 66 ícones existentes — ZERO seriam bloqueados.
--
-- Rollback:
--   ALTER TABLE categories DROP CONSTRAINT chk_icon_lucide_format;
--   ALTER TABLE categories ADD CONSTRAINT chk_icon_lucide_format
--     CHECK (icon IS NULL OR icon ~ '^[A-Z][a-zA-Z0-9]+$') NOT VALID;
--   ALTER TABLE categories VALIDATE CONSTRAINT chk_icon_lucide_format;
-- ═══════════════════════════════════════════════════════════════════════════

-- GUARDA: confirmar que nenhum valor existente quebraria antes de prosseguir
DO $$
DECLARE
  v_bloqueados INT;
  v_exemplos   TEXT;
BEGIN
  SELECT
    COUNT(*),
    STRING_AGG(DISTINCT icon, ', ' ORDER BY icon)
  INTO v_bloqueados, v_exemplos
  FROM public.categories
  WHERE icon IS NOT NULL
    AND NOT (icon ~ '^[A-Z][a-z][a-zA-Z0-9]*$');

  IF v_bloqueados > 0 THEN
    RAISE EXCEPTION
      'ABORTADO: % valores existentes falhariam no novo regex. Exemplos: [%]',
      v_bloqueados, v_exemplos;
  END IF;

  RAISE NOTICE 'PRE-CHECK OK: 0 valores existentes seriam bloqueados.';
END;
$$;

-- PASSO 1: Remover constraint antiga
ALTER TABLE public.categories
  DROP CONSTRAINT IF EXISTS chk_icon_lucide_format;

-- PASSO 2: Adicionar constraint mais restritiva
ALTER TABLE public.categories
  ADD CONSTRAINT chk_icon_lucide_format
  CHECK (
    icon IS NULL
    OR (icon ~ '^[A-Z][a-z][a-zA-Z0-9]*$')
  )
  NOT VALID;

-- PASSO 3: Validar contra todos os rows existentes
ALTER TABLE public.categories
  VALIDATE CONSTRAINT chk_icon_lucide_format;

-- PASSO 4: Atualizar comentário da coluna
COMMENT ON COLUMN public.categories.icon IS
  'Nome PascalCase de ícone Lucide React (ex: Coffee, Wine, PawPrint, Gamepad2). '
  'Regra: 1º char maiúsculo [A-Z], 2º char MINÚSCULO obrigatório [a-z], resto alphanumerico [a-zA-Z0-9]*. '
  'Constraint chk_icon_lucide_format: ^[A-Z][a-z][a-zA-Z0-9]*$ '
  'Garante que "COFFEE" (all-caps), "NULL" (string), siglas "TV"/"USB" sejam rejeitados. '
  'Todos os ícones reais do Lucide React seguem este padrão. '
  'Fonte de verdade: este campo. archive.category_icons é legada/arquivada.';
;

-- <<< END 20260623130516_tighten_icon_constraint_require_lowercase_second_char.sql <<<

