-- >>> BEGIN 20260623132117_melhoria_2b_propagate_level_path_on_move.sql >>>
CREATE OR REPLACE FUNCTION public.fn_trigger_propagate_fpr()
RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $fn$
BEGIN
    IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;
    IF OLD.name IS NOT DISTINCT FROM NEW.name AND OLD.parent_id IS NOT DISTINCT FROM NEW.parent_id THEN RETURN NEW; END IF;
    IF OLD.parent_id IS DISTINCT FROM NEW.parent_id THEN
        WITH RECURSIVE sub AS (
            SELECT c.id,
                   NEW.full_path_readable||' > '||UPPER(COALESCE(c.name,'')) AS fpr,
                   NEW.path||c.id::TEXT||'/'                                   AS p,
                   NEW.level+1                                                  AS lv
            FROM categories c WHERE c.parent_id = NEW.id
            UNION ALL
            SELECT c2.id, s.fpr||' > '||UPPER(COALESCE(c2.name,'')), s.p||c2.id::TEXT||'/', s.lv+1
            FROM categories c2 JOIN sub s ON c2.parent_id = s.id
        )
        UPDATE categories ct
        SET full_path_readable = s.fpr, path = s.p, level = s.lv
        FROM sub s
        WHERE ct.id = s.id
          AND (ct.full_path_readable IS DISTINCT FROM s.fpr OR ct.path IS DISTINCT FROM s.p OR ct.level IS DISTINCT FROM s.lv);
    ELSE
        WITH RECURSIVE sub AS (
            SELECT c.id, NEW.full_path_readable||' > '||UPPER(COALESCE(c.name,'')) AS chain
            FROM categories c WHERE c.parent_id = NEW.id
            UNION ALL
            SELECT c2.id, s.chain||' > '||UPPER(COALESCE(c2.name,''))
            FROM categories c2 JOIN sub s ON c2.parent_id = s.id
        )
        UPDATE categories ct SET full_path_readable = s.chain FROM sub s
        WHERE ct.id = s.id AND ct.full_path_readable IS DISTINCT FROM s.chain;
    END IF;
    RETURN NEW;
END;
$fn$;;

-- <<< END 20260623132117_melhoria_2b_propagate_level_path_on_move.sql <<<

-- >>> BEGIN 20260623132323_fix_fn_resync_fpr_subtree_ancestor_chain.sql >>>
CREATE OR REPLACE FUNCTION public.fn_resync_full_path_readable(
    p_root_id UUID DEFAULT NULL
)
RETURNS TABLE(updated_count INT, elapsed_ms NUMERIC)
LANGUAGE plpgsql SET search_path TO 'public' AS $fn$
DECLARE
    v_start TIMESTAMPTZ := clock_timestamp();
    v_updated INT;
    v_root_chain TEXT;
BEGIN
    IF p_root_id IS NULL THEN
        -- Resync GLOBAL: partir das raízes reais
        WITH RECURSIVE correct_fpr AS (
            SELECT c.id, UPPER(COALESCE(c.name,'')) AS chain
            FROM categories c WHERE c.parent_id IS NULL
            UNION ALL
            SELECT child.id, cf.chain||' > '||UPPER(COALESCE(child.name,''))
            FROM categories child JOIN correct_fpr cf ON child.parent_id = cf.id
        )
        UPDATE categories cat SET full_path_readable = cf.chain
        FROM correct_fpr cf
        WHERE cat.id = cf.id AND cat.full_path_readable IS DISTINCT FROM cf.chain;
    ELSE
        -- Resync de subárvore: calcular a chain correta a partir dos ancestrais reais
        SELECT CASE WHEN c.parent_id IS NULL THEN UPPER(COALESCE(c.name,''))
                    ELSE (SELECT full_path_readable FROM categories WHERE id = c.parent_id)
                         ||' > '||UPPER(COALESCE(c.name,''))
               END INTO v_root_chain
        FROM categories c WHERE c.id = p_root_id;

        IF v_root_chain IS NULL THEN
            RAISE EXCEPTION 'Category % not found or parent has no full_path_readable', p_root_id;
        END IF;

        WITH RECURSIVE correct_fpr AS (
            SELECT p_root_id AS id, v_root_chain AS chain
            UNION ALL
            SELECT child.id, cf.chain||' > '||UPPER(COALESCE(child.name,''))
            FROM categories child JOIN correct_fpr cf ON child.parent_id = cf.id
        )
        UPDATE categories cat SET full_path_readable = cf.chain
        FROM correct_fpr cf
        WHERE cat.id = cf.id AND cat.full_path_readable IS DISTINCT FROM cf.chain;
    END IF;

    GET DIAGNOSTICS v_updated = ROW_COUNT;
    RETURN QUERY SELECT v_updated, ROUND(EXTRACT(EPOCH FROM (clock_timestamp()-v_start))*1000, 2);
END;
$fn$;;

-- <<< END 20260623132323_fix_fn_resync_fpr_subtree_ancestor_chain.sql <<<

