-- Reescrever fn sem nested aggregates
CREATE OR REPLACE FUNCTION public.fn_products_quality_dashboard()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_total   integer;
  v_ativos  integer;
  v_result  jsonb;
  v_by_sup  jsonb;
BEGIN
  SELECT COUNT(*) INTO v_total FROM products;
  SELECT COUNT(*) INTO v_ativos FROM products WHERE is_active = true;

  -- Pre-compute por_fornecedor separadamente (sem nested aggregate)
  SELECT jsonb_agg(row_data ORDER BY total DESC)
  INTO v_by_sup
  FROM (
    SELECT jsonb_build_object(
      'supplier', COALESCE(s.name,'(sem fornecedor)'),
      'total',  COUNT(*)::int,
      'ativos', COUNT(*) FILTER (WHERE p.is_active)::int
    ) AS row_data
    FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
    GROUP BY s.name
  ) t;

  v_result := jsonb_build_object(
    'snapshot_at', now(),
    'totais', jsonb_build_object(
      'products_total',    v_total,
      'products_ativos',   v_ativos,
      'products_inativos', v_total - v_ativos,
      'is_deleted_true',   (SELECT COUNT(*)::int FROM products WHERE is_deleted = true)
    ),
    'cobertura_pct', jsonb_build_object(
      'description',  ROUND(100.0*(SELECT COUNT(*) FROM products WHERE description IS NOT NULL AND length(description)>10)/NULLIF(v_total,0),1),
      'ncm',          ROUND(100.0*(SELECT COUNT(*) FROM products WHERE ncm_code IS NOT NULL)/NULLIF(v_total,0),1),
      'ipi_rate',     ROUND(100.0*(SELECT COUNT(*) FROM products WHERE ipi_rate IS NOT NULL)/NULLIF(v_total,0),1),
      'weight_g',     ROUND(100.0*(SELECT COUNT(*) FROM products WHERE weight_g IS NOT NULL)/NULLIF(v_total,0),1),
      'dimensions',   ROUND(100.0*(SELECT COUNT(*) FROM products WHERE length_cm IS NOT NULL AND width_cm IS NOT NULL)/NULLIF(v_total,0),1),
      'image',        ROUND(100.0*(SELECT COUNT(*) FROM products WHERE primary_image_url IS NOT NULL)/NULLIF(v_total,0),1),
      'slug',         ROUND(100.0*(SELECT COUNT(*) FROM products WHERE slug IS NOT NULL)/NULLIF(v_total,0),1),
      'category',     ROUND(100.0*(SELECT COUNT(*) FROM products WHERE category_id IS NOT NULL)/NULLIF(v_total,0),1),
      'sku_promo',    ROUND(100.0*(SELECT COUNT(*) FROM products WHERE sku_promo IS NOT NULL)/NULLIF(v_total,0),1),
      'ai_desc',      ROUND(100.0*(SELECT COUNT(*) FROM products WHERE ai_description IS NOT NULL AND length(ai_description)>10)/NULLIF(v_total,0),1)
    ),
    'nome_grade', jsonb_build_object(
      'A', (SELECT COUNT(*)::int FROM products WHERE (fn_product_name_quality_score(name)->>'grade')='A'),
      'B', (SELECT COUNT(*)::int FROM products WHERE (fn_product_name_quality_score(name)->>'grade')='B'),
      'C', (SELECT COUNT(*)::int FROM products WHERE (fn_product_name_quality_score(name)->>'grade')='C'),
      'D', (SELECT COUNT(*)::int FROM products WHERE (fn_product_name_quality_score(name)->>'grade')='D'),
      'F', (SELECT COUNT(*)::int FROM products WHERE (fn_product_name_quality_score(name)->>'grade')='F')
    ),
    'estoque', jsonb_build_object(
      'em_ruptura',  (SELECT COUNT(*)::int FROM products WHERE is_stockout=true AND is_active=true),
      'sem_estoque', (SELECT COUNT(*)::int FROM products WHERE stock_quantity=0 AND is_active=true),
      'com_estoque', (SELECT COUNT(*)::int FROM products WHERE stock_quantity>0 AND is_active=true),
      'avg_estoque', ROUND((SELECT AVG(stock_quantity) FROM products WHERE is_active=true AND stock_quantity>0)::numeric,0)
    ),
    'seo', jsonb_build_object(
      'sem_slug',        (SELECT COUNT(*)::int FROM products WHERE slug IS NULL AND is_deleted IS NOT TRUE),
      'avg_seo_score',   ROUND((SELECT AVG(seo_score) FROM products WHERE seo_score IS NOT NULL)::numeric,1),
      'sem_meta_title',  (SELECT COUNT(*)::int FROM products WHERE meta_title IS NULL AND is_active=true)
    ),
    'ai_queue', jsonb_build_object(
      'pending',    (SELECT COUNT(*)::int FROM ai_enrichment_queue WHERE status='pending'),
      'processing', (SELECT COUNT(*)::int FROM ai_enrichment_queue WHERE status='processing'),
      'done',       (SELECT COUNT(*)::int FROM ai_enrichment_queue WHERE status='done'),
      'error',      (SELECT COUNT(*)::int FROM ai_enrichment_queue WHERE status='error')
    ),
    'por_fornecedor', v_by_sup
  );

  RETURN v_result;
END;
$$;

COMMENT ON FUNCTION public.fn_products_quality_dashboard() IS
'Dashboard de qualidade do catálogo. SELECT fn_products_quality_dashboard(); Criado 2026-06-23.';
GRANT EXECUTE ON FUNCTION public.fn_products_quality_dashboard() TO authenticated;
;

-- <<< END 20260623132942_products_2b_quality_dashboard_fix_20260623.sql <<<

-- >>> BEGIN 20260623133008_products_2c_quality_dashboard_fix2_20260623.sql >>>

-- Fix: ORDER BY na jsonb_agg precisa de coluna visível no outer scope
CREATE OR REPLACE FUNCTION public.fn_products_quality_dashboard()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_total   integer;
  v_ativos  integer;
  v_result  jsonb;
  v_by_sup  jsonb;
BEGIN
  SELECT COUNT(*) INTO v_total FROM products;
  SELECT COUNT(*) INTO v_ativos FROM products WHERE is_active = true;

  SELECT jsonb_agg(t.row_data)
  INTO v_by_sup
  FROM (
    SELECT jsonb_build_object(
      'supplier', COALESCE(s.name,'(sem fornecedor)'),
      'total',  COUNT(*)::int,
      'ativos', COUNT(*) FILTER (WHERE p.is_active)::int
    ) AS row_data,
    COUNT(*) AS cnt
    FROM products p LEFT JOIN suppliers s ON s.id=p.supplier_id
    GROUP BY s.name
    ORDER BY COUNT(*) DESC
  ) t;

  v_result := jsonb_build_object(
    'snapshot_at', now(),
    'totais', jsonb_build_object(
      'total', v_total, 'ativos', v_ativos,
      'inativos', v_total-v_ativos,
      'is_deleted', (SELECT COUNT(*)::int FROM products WHERE is_deleted=true)
    ),
    'cobertura_pct', jsonb_build_object(
      'description',ROUND(100.0*(SELECT COUNT(*) FROM products WHERE description IS NOT NULL AND length(description)>10)/NULLIF(v_total,0),1),
      'ncm',         ROUND(100.0*(SELECT COUNT(*) FROM products WHERE ncm_code IS NOT NULL)/NULLIF(v_total,0),1),
      'ipi_rate',    ROUND(100.0*(SELECT COUNT(*) FROM products WHERE ipi_rate IS NOT NULL)/NULLIF(v_total,0),1),
      'weight',      ROUND(100.0*(SELECT COUNT(*) FROM products WHERE weight_g IS NOT NULL)/NULLIF(v_total,0),1),
      'dimensions',  ROUND(100.0*(SELECT COUNT(*) FROM products WHERE length_cm IS NOT NULL AND width_cm IS NOT NULL)/NULLIF(v_total,0),1),
      'image',       ROUND(100.0*(SELECT COUNT(*) FROM products WHERE primary_image_url IS NOT NULL)/NULLIF(v_total,0),1),
      'slug',        ROUND(100.0*(SELECT COUNT(*) FROM products WHERE slug IS NOT NULL)/NULLIF(v_total,0),1),
      'ai_desc',     ROUND(100.0*(SELECT COUNT(*) FROM products WHERE ai_description IS NOT NULL AND length(ai_description)>10)/NULLIF(v_total,0),1)
    ),
    'nome_grade', jsonb_build_object(
      'A',(SELECT COUNT(*)::int FROM products WHERE (fn_product_name_quality_score(name)->>'grade')='A'),
      'B',(SELECT COUNT(*)::int FROM products WHERE (fn_product_name_quality_score(name)->>'grade')='B'),
      'C',(SELECT COUNT(*)::int FROM products WHERE (fn_product_name_quality_score(name)->>'grade')='C')
    ),
    'estoque', jsonb_build_object(
      'ruptura',(SELECT COUNT(*)::int FROM products WHERE is_stockout=true AND is_active=true),
      'com',(SELECT COUNT(*)::int FROM products WHERE stock_quantity>0 AND is_active=true),
      'avg_qty',ROUND((SELECT AVG(stock_quantity) FROM products WHERE is_active=true AND stock_quantity>0)::numeric,0)
    ),
    'seo', jsonb_build_object(
      'sem_slug',(SELECT COUNT(*)::int FROM products WHERE slug IS NULL AND is_deleted IS NOT TRUE),
      'sem_meta',(SELECT COUNT(*)::int FROM products WHERE meta_title IS NULL AND is_active=true)
    ),
    'ai_queue', jsonb_build_object(
      'pending',(SELECT COUNT(*)::int FROM ai_enrichment_queue WHERE status='pending'),
      'done',(SELECT COUNT(*)::int FROM ai_enrichment_queue WHERE status='done'),
      'error',(SELECT COUNT(*)::int FROM ai_enrichment_queue WHERE status='error')
    ),
    'por_fornecedor', v_by_sup
  );
  RETURN v_result;
END;
$$;
GRANT EXECUTE ON FUNCTION public.fn_products_quality_dashboard() TO authenticated;
;

-- <<< END 20260623133008_products_2c_quality_dashboard_fix2_20260623.sql <<<

-- >>> BEGIN 20260623133053_products_3_new_check_constraints_20260623.sql >>>

-- ══════════════════════════════════════════════════════════════════
-- Melhoria 3: CHECKs adicionais em campos críticos
-- Todos validados com 0 violações existentes
-- ══════════════════════════════════════════════════════════════════

-- 3A: min_quantity >= 1 (quantidade mínima sempre positiva)
ALTER TABLE public.products
  ADD CONSTRAINT chk_products_min_quantity_pos
  CHECK (min_quantity IS NULL OR min_quantity >= 1)
  NOT VALID;
ALTER TABLE public.products VALIDATE CONSTRAINT chk_products_min_quantity_pos;

-- 3B: capacity_ml > 0 (para copos, garrafas — nunca zero ou negativo)
ALTER TABLE public.products
  ADD CONSTRAINT chk_products_capacity_ml_pos
  CHECK (capacity_ml IS NULL OR capacity_ml > 0)
  NOT VALID;
ALTER TABLE public.products VALIDATE CONSTRAINT chk_products_capacity_ml_pos;

-- 3C: lead_time_days >= 0 (prazo nunca negativo)
ALTER TABLE public.products
  ADD CONSTRAINT chk_products_lead_time_nonneg
  CHECK (lead_time_days IS NULL OR lead_time_days >= 0)
  NOT VALID;
ALTER TABLE public.products VALIDATE CONSTRAINT chk_products_lead_time_nonneg;

-- 3D: ipi_rate range 0-100% (taxa fiscal válida)
ALTER TABLE public.products
  ADD CONSTRAINT chk_products_ipi_rate_range
  CHECK (ipi_rate IS NULL OR (ipi_rate >= 0 AND ipi_rate <= 100))
  NOT VALID;
ALTER TABLE public.products VALIDATE CONSTRAINT chk_products_ipi_rate_range;

-- 3E: circumference_cm > 0 quando preenchido
ALTER TABLE public.products
  ADD CONSTRAINT chk_products_circumference_pos
  CHECK (circumference_cm IS NULL OR circumference_cm > 0)
  NOT VALID;
ALTER TABLE public.products VALIDATE CONSTRAINT chk_products_circumference_pos;
;

-- <<< END 20260623133053_products_3_new_check_constraints_20260623.sql <<<

-- >>> BEGIN 20260623133132_products_5_ai_coverage_view_20260623.sql >>>

-- ══════════════════════════════════════════════════════════════════
-- Melhoria 5: v_products_ai_coverage — view de cobertura de enriquecimento AI
-- Monitoramento do progresso da AI enrichment por fornecedor e tipo
-- ══════════════════════════════════════════════════════════════════
CREATE OR REPLACE VIEW public.v_products_ai_coverage AS
SELECT
  s.name AS supplier_name,
  COUNT(p.id) AS total_products,
  COUNT(p.id) FILTER (WHERE p.ai_description IS NOT NULL AND length(p.ai_description) > 20) AS com_ai_desc,
  COUNT(p.id) FILTER (WHERE p.ai_title IS NOT NULL AND length(p.ai_title) > 5) AS com_ai_title,
  COUNT(p.id) FILTER (WHERE p.ai_summary IS NOT NULL) AS com_ai_summary,
  COUNT(p.id) FILTER (WHERE p.ai_generated_at IS NOT NULL) AS com_ai_gerado,
  ROUND(100.0 * COUNT(p.id) FILTER (WHERE p.ai_description IS NOT NULL AND length(p.ai_description) > 20) /
    NULLIF(COUNT(p.id), 0), 1) AS pct_ai_desc,
  MAX(p.ai_generated_at) AS last_ai_generated,
  -- Queue status para este fornecedor
  COUNT(q.id) FILTER (WHERE q.status = 'pending') AS queue_pending,
  COUNT(q.id) FILTER (WHERE q.status = 'processing') AS queue_processing,
  COUNT(q.id) FILTER (WHERE q.status = 'done') AS queue_done,
  COUNT(q.id) FILTER (WHERE q.status = 'error') AS queue_error
FROM products p
LEFT JOIN suppliers s ON s.id = p.supplier_id
LEFT JOIN ai_enrichment_queue q ON q.product_id = p.id
WHERE p.is_active = true
GROUP BY s.name
ORDER BY total_products DESC;

COMMENT ON VIEW public.v_products_ai_coverage IS
'Cobertura de enriquecimento AI por fornecedor. Inclui status da fila. Criado 2026-06-23.';

GRANT SELECT ON public.v_products_ai_coverage TO authenticated;
;

-- <<< END 20260623133132_products_5_ai_coverage_view_20260623.sql <<<

-- >>> BEGIN 20260623134031_optimize_trg_sync_descendants_cte_batch.sql >>>

-- ████████████████████████████████████████████████████████████████████████████
-- MELHORIA #1: fn_trigger_sync_descendants_count
-- ANTES : WHILE loop → N UPDATEs sequenciais (1 por nível de profundidade)
-- DEPOIS: CTE batch  → 1 UPDATE batch para todos os ancestrais
-- GANHO : Inserção nível 4 = 4 round trips → 1 round trip (redução 4x)
-- SEGURO: GREATEST(0,…) guard mantido; depth safety limit = 15; AFTER trigger
-- ████████████████████████████████████████████████████████████████████████████

CREATE OR REPLACE FUNCTION public.fn_trigger_sync_descendants_count()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_delta INTEGER;
BEGIN
  -- ─────────────────────────────────────────────────────────────────────────
  -- INSERT: incrementar todos os ancestrais em +1 — CTE batch (1 UPDATE total)
  -- ─────────────────────────────────────────────────────────────────────────
  IF TG_OP = 'INSERT' AND NEW.parent_id IS NOT NULL THEN
    WITH RECURSIVE ancestors(id, parent_id, depth) AS (
      SELECT c.id, c.parent_id, 1
      FROM   categories c
      WHERE  c.id = NEW.parent_id
      UNION ALL
      SELECT c.id, c.parent_id, a.depth + 1
      FROM   categories c
      JOIN   ancestors a ON c.id = a.parent_id
      WHERE  a.parent_id IS NOT NULL
        AND  a.depth < 15  -- safety: bem acima dos 6 níveis ativos
    )
    UPDATE categories
    SET    descendants_count = descendants_count + 1
    WHERE  id IN (SELECT id FROM ancestors);

    RETURN NEW;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- DELETE: decrementar ancestrais por (1 + subtree) — CTE batch
  -- OLD.descendants_count já reflete o estado pré-deleção (trigger AFTER)
  -- ─────────────────────────────────────────────────────────────────────────
  IF TG_OP = 'DELETE' AND OLD.parent_id IS NOT NULL THEN
    v_delta := 1 + COALESCE(OLD.descendants_count, 0);

    WITH RECURSIVE ancestors(id, parent_id, depth) AS (
      SELECT c.id, c.parent_id, 1
      FROM   categories c
      WHERE  c.id = OLD.parent_id
      UNION ALL
      SELECT c.id, c.parent_id, a.depth + 1
      FROM   categories c
      JOIN   ancestors a ON c.id = a.parent_id
      WHERE  a.parent_id IS NOT NULL
        AND  a.depth < 15
    )
    UPDATE categories
    SET    descendants_count = GREATEST(0, descendants_count - v_delta)
    WHERE  id IN (SELECT id FROM ancestors);

    RETURN OLD;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- UPDATE parent_id: abordagem delta nos dois ramos — 2 CTEs batch
  --
  -- v_delta = subtree sendo movida (a categoria + todos seus descendentes)
  -- Ancestrais compartilhados recebem -delta e +delta → net = 0 ✓
  -- Sem full-recount (que exigia 1 CTE por ancestral no loop anterior)
  -- ─────────────────────────────────────────────────────────────────────────
  IF TG_OP = 'UPDATE' AND OLD.parent_id IS DISTINCT FROM NEW.parent_id THEN
    v_delta := 1 + COALESCE(OLD.descendants_count, 0);

    -- Ramo ANTIGO: decrementar (categoria + subtree saiu)
    IF OLD.parent_id IS NOT NULL THEN
      WITH RECURSIVE old_ancestors(id, parent_id, depth) AS (
        SELECT c.id, c.parent_id, 1
        FROM   categories c
        WHERE  c.id = OLD.parent_id
        UNION ALL
        SELECT c.id, c.parent_id, a.depth + 1
        FROM   categories c
        JOIN   old_ancestors a ON c.id = a.parent_id
        WHERE  a.parent_id IS NOT NULL
          AND  a.depth < 15
      )
      UPDATE categories
      SET    descendants_count = GREATEST(0, descendants_count - v_delta)
      WHERE  id IN (SELECT id FROM old_ancestors);
    END IF;

    -- Ramo NOVO: incrementar (categoria + subtree chegou)
    IF NEW.parent_id IS NOT NULL THEN
      WITH RECURSIVE new_ancestors(id, parent_id, depth) AS (
        SELECT c.id, c.parent_id, 1
        FROM   categories c
        WHERE  c.id = NEW.parent_id
        UNION ALL
        SELECT c.id, c.parent_id, a.depth + 1
        FROM   categories c
        JOIN   new_ancestors a ON c.id = a.parent_id
        WHERE  a.parent_id IS NOT NULL
          AND  a.depth < 15
      )
      UPDATE categories
      SET    descendants_count = descendants_count + v_delta
      WHERE  id IN (SELECT id FROM new_ancestors);
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

-- Garantir permissão
GRANT EXECUTE ON FUNCTION public.fn_trigger_sync_descendants_count() TO postgres, service_role;

COMMENT ON FUNCTION public.fn_trigger_sync_descendants_count() IS
'AFTER trigger (INSERT/DELETE/UPDATE) que mantém descendants_count de todos os
ancestrais de uma categoria. Usa CTE batch recursiva em vez de WHILE loop —
reduz de N round-trips (1/nível) para 1 UPDATE batch. Abordagem delta no UPDATE
parent_id evita full-recount por ancestral. Safety: depth < 15, GREATEST(0,…).
Otimizado em: 2026-06-23.';
;

-- <<< END 20260623134031_optimize_trg_sync_descendants_cte_batch.sql <<<

-- >>> BEGIN 20260623134124_optimize_trigger_prevent_loops_cte_exists.sql >>>

-- ████████████████████████████████████████████████████████████████████████████
-- MELHORIA #2: prevent_category_loops
-- ANTES : WHILE loop com SELECT individual por nível (até 10 round trips)
-- DEPOIS: CTE EXISTS única + depth check integrado na mesma CTE
-- GANHO : Verificação de ciclo: N queries → 1 query
-- PLUS  : Detecção de self-reference imediata (antes de entrar na CTE)
-- ████████████████████████████████████████████████████████████████████████████

CREATE OR REPLACE FUNCTION public.prevent_category_loops()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_max_depth CONSTANT INTEGER := 10;
  v_path_depth INTEGER;
BEGIN
  -- Sem parent_id: categoria raiz, nada a verificar
  IF NEW.parent_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Auto-referência direta (A → A): checar antes da CTE (mais barato)
  IF NEW.parent_id = NEW.id THEN
    RAISE EXCEPTION 'Self-reference: category % cannot be its own parent', NEW.id;
  END IF;

  -- ─────────────────────────────────────────────────────────────────────────
  -- CTE única: percorre a cadeia de ancestrais de NEW.parent_id para cima
  -- Detecta simultaneamente:
  --   (1) Se NEW.id aparece na cadeia → referência circular
  --   (2) Qual a profundidade máxima da cadeia → violação de max_depth
  -- ─────────────────────────────────────────────────────────────────────────
  WITH RECURSIVE ancestor_chain(id, parent_id, depth) AS (
    -- Ponto de partida: o pai direto de NEW
    SELECT c.id, c.parent_id, 1 AS depth
    FROM   categories c
    WHERE  c.id = NEW.parent_id

    UNION ALL

    -- Subir na hierarquia
    SELECT c.id, c.parent_id, a.depth + 1
    FROM   categories c
    JOIN   ancestor_chain a ON c.id = a.parent_id
    WHERE  a.parent_id IS NOT NULL
      AND  a.depth < v_max_depth  -- stopper de segurança
  )
  SELECT MAX(depth) INTO v_path_depth FROM ancestor_chain;

  -- Verificação de ciclo: NEW.id existe como ancestral de NEW.parent_id?
  IF EXISTS (
    WITH RECURSIVE ancestor_chain(id, parent_id, depth) AS (
      SELECT c.id, c.parent_id, 1
      FROM   categories c
      WHERE  c.id = NEW.parent_id
      UNION ALL
      SELECT c.id, c.parent_id, a.depth + 1
      FROM   categories c
      JOIN   ancestor_chain a ON c.id = a.parent_id
      WHERE  a.parent_id IS NOT NULL AND a.depth < v_max_depth
    )
    SELECT 1 FROM ancestor_chain WHERE id = NEW.id
  ) THEN
    RAISE EXCEPTION
      'Circular reference: category % cannot be its own ancestor (detected in chain of %)',
      NEW.id, v_path_depth;
  END IF;

  -- Verificação de profundidade máxima
  -- v_path_depth = profundidade do pai → NEW ficará em depth + 1
  IF COALESCE(v_path_depth, 0) >= v_max_depth THEN
    RAISE EXCEPTION
      'Max hierarchy depth (%) exceeded: parent chain already has % levels',
      v_max_depth, v_path_depth;
  END IF;

  RETURN NEW;
END;
$function$;

GRANT EXECUTE ON FUNCTION public.prevent_category_loops() TO postgres, service_role;

COMMENT ON FUNCTION public.prevent_category_loops() IS
'BEFORE trigger (INSERT/UPDATE) que previne referências circulares na hierarquia.
Substituiu WHILE loop (N SELECTs) por CTE EXISTS única (1 query).
Detecta: (1) self-reference direta, (2) ciclos via ancestral chain, (3) depth > 10.
Otimizado em: 2026-06-23.';
;

-- <<< END 20260623134124_optimize_trigger_prevent_loops_cte_exists.sql <<<

-- >>> BEGIN 20260623134342_add_fn_categories_health_check.sql >>>

-- ████████████████████████████████████████████████████████████████████████████
-- MELHORIA #3: fn_categories_health_check()
-- Monitor de integridade COMPLETO da hierarquia de categorias.
-- Testa 10 invariantes críticos em uma única chamada.
-- Uso: SELECT * FROM fn_categories_health_check();
-- ████████████████████████████████████████████████████████████████████████████

CREATE OR REPLACE FUNCTION public.fn_categories_health_check()
RETURNS TABLE (
    check_id      integer,
    check_name    text,
    result        text,   -- 'PASS' | 'WARN' | 'FAIL'
    details       text,
    affected_rows bigint
)
LANGUAGE plpgsql
STABLE
SET search_path TO 'public'
AS $function$
BEGIN

  -- ── CHECK 1: Órfãos — parent_id aponta para UUID inexistente ───────────────
  RETURN QUERY
  SELECT 1,
    'orphaned_parent_id'::text,
    CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END,
    CASE WHEN COUNT(*) = 0
         THEN 'Nenhum órfão encontrado'
         ELSE COUNT(*)::text || ' categoria(s) com parent_id inexistente'
    END,
    COUNT(*)
  FROM categories c
  LEFT JOIN categories p ON p.id = c.parent_id
  WHERE c.parent_id IS NOT NULL AND p.id IS NULL;

  -- ── CHECK 2: descendants_count divergindo da contagem real ─────────────────
  RETURN QUERY
  WITH RECURSIVE real_tree AS (
      SELECT id AS ancestor, id AS node FROM categories
      UNION ALL
      SELECT rt.ancestor, c.id
      FROM real_tree rt
      JOIN categories c ON c.parent_id = rt.node
  ),
  real_counts AS (
      SELECT ancestor, COUNT(*) - 1 AS real_descendants
      FROM real_tree GROUP BY ancestor
  )
  SELECT 2,
    'descendants_count_drift'::text,
    CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END,
    CASE WHEN COUNT(*) = 0
         THEN 'descendants_count 100% preciso'
         ELSE COUNT(*)::text || ' categoria(s) com descendants_count errado'
    END,
    COUNT(*)
  FROM categories c
  JOIN real_counts rc ON rc.ancestor = c.id
  WHERE c.descendants_count != rc.real_descendants;

  -- ── CHECK 3: children_count divergindo da contagem real ────────────────────
  RETURN QUERY
  SELECT 3,
    'children_count_drift'::text,
    CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END,
    CASE WHEN COUNT(*) = 0
         THEN 'children_count 100% preciso'
         ELSE COUNT(*)::text || ' categoria(s) com children_count errado'
    END,
    COUNT(*)
  FROM categories p
  LEFT JOIN (
      SELECT parent_id, COUNT(*) AS n FROM categories
      WHERE parent_id IS NOT NULL GROUP BY parent_id
  ) ch ON ch.parent_id = p.id
  WHERE p.children_count != COALESCE(ch.n, 0);

  -- ── CHECK 4: level inconsistente com posição real na árvore ───────────────
  RETURN QUERY
  WITH RECURSIVE computed AS (
      SELECT id, 1 AS computed_level FROM categories WHERE parent_id IS NULL
      UNION ALL
      SELECT c.id, cp.computed_level + 1
      FROM categories c JOIN computed cp ON c.parent_id = cp.id
  )
  SELECT 4,
    'level_mismatch'::text,
    CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END,
    CASE WHEN COUNT(*) = 0
         THEN 'level consistente com a árvore real'
         ELSE COUNT(*)::text || ' categoria(s) com level incorreto'
    END,
    COUNT(*)
  FROM categories c
  JOIN computed cp ON cp.id = c.id
  WHERE c.level != cp.computed_level;

  -- ── CHECK 5: category_ancestors desincronizada com parent_id tree ──────────
  RETURN QUERY
  WITH RECURSIVE real_pairs AS (
      SELECT id AS ancestor_id, id AS descendant_id FROM categories
      UNION ALL
      SELECT rp.ancestor_id, c.id
      FROM real_pairs rp JOIN categories c ON c.parent_id = rp.descendant_id
  ),
  delta AS (
      SELECT
          (SELECT COUNT(*) FROM real_pairs WHERE ancestor_id != descendant_id) AS real_n,
          (SELECT COUNT(*) FROM category_ancestors) AS stored_n
  )
  SELECT 5,
    'closure_table_sync'::text,
    CASE WHEN real_n = stored_n THEN 'PASS' ELSE 'FAIL' END,
    'Real pairs: ' || real_n::text || ' | Stored: ' || stored_n::text ||
    CASE WHEN real_n = stored_n THEN ' ✓ sincronizado' ELSE ' ← DESSINCRONIZADO!' END,
    ABS(real_n - stored_n)
  FROM delta;

  -- ── CHECK 6: Filho ATIVO com pai INATIVO (visibilidade quebrada) ──────────
  RETURN QUERY
  SELECT 6,
    'active_child_inactive_parent'::text,
    CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'WARN' END,
    CASE WHEN COUNT(*) = 0
         THEN 'Nenhum filho ativo com pai inativo'
         ELSE COUNT(*)::text || ' filho(s) ativo(s) com pai inativo — verificar visibilidade'
    END,
    COUNT(*)
  FROM categories c
  JOIN categories p ON p.id = c.parent_id
  WHERE c.is_active = true AND p.is_active = false;

  -- ── CHECK 7: Slugs duplicados (violação silenciosa de unique) ─────────────
  RETURN QUERY
  SELECT 7,
    'duplicate_slugs'::text,
    CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END,
    CASE WHEN COUNT(*) = 0
         THEN 'Todos os slugs são únicos'
         ELSE COUNT(*)::text || ' slug(s) duplicado(s) detectado(s)'
    END,
    COUNT(*)
  FROM (
      SELECT slug FROM categories GROUP BY slug HAVING COUNT(*) > 1
  ) dups;

  -- ── CHECK 8: Categorias com path NULL ou malformado ────────────────────────
  RETURN QUERY
  SELECT 8,
    'path_integrity'::text,
    CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END,
    CASE WHEN COUNT(*) = 0
         THEN 'Todos os paths estão bem formados'
         ELSE COUNT(*)::text || ' categoria(s) com path nulo ou malformado'
    END,
    COUNT(*)
  FROM categories
  WHERE path IS NULL
     OR path NOT LIKE '/%/'
     OR id::text NOT IN (SELECT unnest(regexp_split_to_array(
          regexp_replace(path, '^/|/$', '', 'g'), '/'
        )));

  -- ── CHECK 9: Referências circulares residuais ─────────────────────────────
  RETURN QUERY
  WITH RECURSIVE cycle_check(id, visited_ids, has_cycle) AS (
      SELECT id, ARRAY[id], false FROM categories WHERE parent_id IS NULL
      UNION ALL
      SELECT c.id,
             cc.visited_ids || c.id,
             c.id = ANY(cc.visited_ids)
      FROM categories c
      JOIN cycle_check cc ON c.parent_id = cc.id
      WHERE NOT cc.has_cycle
  )
  SELECT 9,
    'circular_references'::text,
    CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'FAIL' END,
    CASE WHEN COUNT(*) = 0
         THEN 'Nenhuma referência circular detectada'
         ELSE COUNT(*)::text || ' referência(s) circular(es) CRÍTICA(S)!'
    END,
    COUNT(*)
  FROM cycle_check
  WHERE has_cycle;

  -- ── CHECK 10: Categorias nível 5+ ainda ativas (limpeza pendente) ──────────
  RETURN QUERY
  SELECT 10,
    'deep_levels_active'::text,
    CASE WHEN COUNT(*) = 0 THEN 'PASS' ELSE 'WARN' END,
    CASE WHEN COUNT(*) = 0
         THEN 'Nenhuma categoria ativa em nível 5+'
         ELSE COUNT(*)::text || ' categoria(s) ativas em nível 5+ — revisar limpeza'
    END,
    COUNT(*)
  FROM categories
  WHERE level >= 5 AND is_active = true;

END;
$function$;

GRANT EXECUTE ON FUNCTION public.fn_categories_health_check() TO postgres, service_role, authenticated;

COMMENT ON FUNCTION public.fn_categories_health_check() IS
'Monitor de integridade da hierarquia categories. Executa 10 checks em 1 chamada:
1) Órfãos, 2) descendants_count drift, 3) children_count drift, 4) level mismatch,
5) closure_table sync, 6) active child/inactive parent, 7) slug duplicates,
8) path integrity, 9) circular refs, 10) deep levels active.
Resultado: PASS/WARN/FAIL por check. Criado: 2026-06-23.';
;

-- <<< END 20260623134342_add_fn_categories_health_check.sql <<<

-- >>> BEGIN 20260623134530_add_fn_rebuild_category_ancestors_and_deactivate_warn_lv5.sql >>>

-- ████████████████████████████████████████████████████████████████████████████
-- MELHORIA #4 — PARTE A: fn_rebuild_category_ancestors()
-- Função de reparo/rebuild da Closure Table.
-- Útil quando: migrações manuais, imports em massa, ou dessincronização detectada.
-- Uso: SELECT fn_rebuild_category_ancestors(); → retorna (deleted, inserted)
-- ████████████████████████████████████████████████████████████████████████████

CREATE OR REPLACE FUNCTION public.fn_rebuild_category_ancestors()
RETURNS TABLE (deleted_rows bigint, inserted_rows bigint, duration_ms numeric)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted  bigint;
  v_inserted bigint;
  v_start    timestamptz := clock_timestamp();
BEGIN
  -- Contar antes para reporting
  SELECT COUNT(*) INTO v_deleted FROM category_ancestors;

  -- Limpar e reconstruir atomicamente
  TRUNCATE category_ancestors;

  -- Inserir todos os pares antepassado→descendente via CTE recursiva
  -- Nota: exclui self-references (ancestor_id != descendant_id)
  WITH RECURSIVE tree AS (
    -- Base: cada categoria é "ancestral de si mesma" (ponto de partida)
    SELECT id AS ancestor_id, id AS node_id, 0 AS depth
    FROM   categories

    UNION ALL

    -- Expandir: cada filho passa a ser descendente de todos os ancestrais do pai
    SELECT t.ancestor_id, c.id AS node_id, t.depth + 1
    FROM   tree t
    JOIN   categories c ON c.parent_id = t.node_id
    WHERE  t.depth < 15  -- safety depth limit
  )
  INSERT INTO category_ancestors (ancestor_id, descendant_id, depth)
  SELECT DISTINCT ancestor_id, node_id, MIN(depth) OVER (PARTITION BY ancestor_id, node_id)
  FROM tree
  WHERE ancestor_id != node_id  -- excluir self-references
  ON CONFLICT (ancestor_id, descendant_id) DO UPDATE
    SET depth = EXCLUDED.depth;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  RETURN QUERY SELECT v_deleted, v_inserted, 
    EXTRACT(milliseconds FROM clock_timestamp() - v_start)::numeric(10,2);
END;
$function$;

GRANT EXECUTE ON FUNCTION public.fn_rebuild_category_ancestors() TO postgres, service_role;

COMMENT ON FUNCTION public.fn_rebuild_category_ancestors() IS
'Rebuild completo da closure table category_ancestors a partir do parent_id tree.
TRUNCATE + INSERT via CTE recursiva com depth safety limit = 15.
Retorna (deleted_rows, inserted_rows, duration_ms). Criado: 2026-06-23.
Uso: SELECT * FROM fn_rebuild_category_ancestors();';


-- ████████████████████████████████████████████████████████████████████████████
-- MELHORIA #4 — PARTE B: Desativar 2 categorias WARN (lv5, já is_visible=false)
-- Investigação confirmou: produtos têm 8-9 categorias; essas são granularidade
-- excessiva de uma taxonomia mais profunda que foi simplificada.
-- ████████████████████████████████████████████████████████████████████████████

UPDATE categories
SET 
    is_active  = false,
    updated_at = now()
WHERE id IN (
    '6b5895e2-a280-4b9f-b23b-b6869c897e75',  -- Kit Churrasco | Emb. Papel | 03 Peças (lv5)
    'cafa5167-927f-4fdc-8dfd-b5fede22a446'   -- Kit Churrasco | Emb. Alumínio | 05 Peças (lv5)
)
AND level >= 5
AND is_visible = false   -- guard: só desativa se já estava oculto
AND is_active = true;    -- idempotente: só atualiza se ainda estava ativo
;

