-- >>> BEGIN 20260623183141_melhoria_01_drop_rls_policies_duplicadas_20260623.sql >>>

-- MELHORIA-01: Remover policies SELECT duplicadas em tabela_preco_gravacao_oficial
-- e tabela_preco_gravacao_oficial_faixa — ambas têm 2 policies SELECT idênticas
-- (mesma expressão USING, mesmo conjunto de roles). PostgreSQL avalia com OR
-- entre elas — não há dano funcional, mas é ruído de governança e overhead de plan.
-- Mantemos a policy original (public_read) e removemos as novas (tpgo_authenticated_read)
-- que criamos redundantemente no fix de ontem.

DROP POLICY IF EXISTS tpgo_authenticated_read ON public.tabela_preco_gravacao_oficial;
DROP POLICY IF EXISTS tpgof_authenticated_read ON public.tabela_preco_gravacao_oficial_faixa;

-- Validação: deve restar exatamente 1 policy SELECT por tabela
SELECT tablename, policyname, cmd
FROM pg_policies
WHERE schemaname='public'
  AND tablename IN ('tabela_preco_gravacao_oficial','tabela_preco_gravacao_oficial_faixa')
  AND cmd='SELECT';
;

-- <<< END 20260623183141_melhoria_01_drop_rls_policies_duplicadas_20260623.sql <<<

-- >>> BEGIN 20260623183156_categories_products_count_reconcile_fn_and_cron.sql >>>
-- APLICADO: 2026-06-23
-- GAP-4b+4c: Função de reconciliação de products_count + pg_cron.
-- PROBLEMA: products_count (counter denormalizado) ficava stale quando
-- o Gold pipeline ativava/desativava produtos (bulk UPDATE com set_config flags
-- que bypassam triggers de counters em products).
-- SOLUÇÃO: Função de reconciliação + cron a cada 15 min como safety net.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.fn_reconcile_category_products_count(
  p_limit INT DEFAULT NULL  -- NULL = todas; número = N categorias mais divergentes
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
DECLARE
  v_updated   INT := 0;
  v_skipped   INT := 0;
  v_started_at TIMESTAMPTZ := clock_timestamp();
BEGIN
  -- Atualizar products_count apenas onde diverge (minimiza writes)
  WITH real_counts AS (
    SELECT
      c.id                                                    AS category_id,
      c.products_count                                        AS cached,
      COALESCE(
        (SELECT count(*) FROM public.products p
         WHERE p.category_id = c.id AND p.is_active = true), 0
      )::integer                                              AS real_count
    FROM public.categories c
    WHERE p_limit IS NULL OR c.id IN (
      -- Se p_limit definido, priorizar os mais divergentes
      SELECT c2.id FROM public.categories c2
      ORDER BY ABS(c2.products_count -
        COALESCE((SELECT count(*) FROM public.products p2
                  WHERE p2.category_id = c2.id AND p2.is_active = true), 0))
        DESC NULLS LAST
      LIMIT p_limit
    )
  ),
  divergentes AS (
    SELECT category_id, cached, real_count
    FROM real_counts
    WHERE cached IS DISTINCT FROM real_count
  )
  UPDATE public.categories c
  SET products_count = d.real_count
  FROM divergentes d
  WHERE c.id = d.category_id;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  v_skipped := (SELECT count(*) FROM public.categories) - v_updated;

  RETURN jsonb_build_object(
    'updated',    v_updated,
    'skipped',    v_skipped,
    'duration_ms', EXTRACT(MILLISECONDS FROM clock_timestamp() - v_started_at)::int,
    'ran_at',     v_started_at
  );
END;
$$;

COMMENT ON FUNCTION public.fn_reconcile_category_products_count(INT) IS
  'Reconcilia categories.products_count com a contagem real de products.is_active=true. '
  'p_limit NULL = todas as categorias; número = N mais divergentes (uso de emergência). '
  'Chamado pelo pg_cron a cada 15min. Criado: 2026-06-23 (GAP-4 fix).';

GRANT EXECUTE ON FUNCTION public.fn_reconcile_category_products_count(INT)
  TO postgres, service_role;

-- ─────────────────────────────────────────────────────────────────────────────
-- pg_cron: reconciliação a cada 15 minutos (safety net do Gold pipeline)
-- Usa fn_cron_safe_run com advisory lock para evitar sobreposição
-- ─────────────────────────────────────────────────────────────────────────────
SELECT cron.schedule(
  'reconcile-category-products-count',
  '3,18,33,48 * * * *',   -- :03, :18, :33, :48 — evita bater com pipeline (:00, :10, etc.)
  $$SELECT public.fn_cron_safe_run(
      NULL::bigint,
      'SELECT public.fn_reconcile_category_products_count()',
      44000,
      'reconcile-products-count'
  );$$
);;

-- <<< END 20260623183156_categories_products_count_reconcile_fn_and_cron.sql <<<

-- >>> BEGIN 20260623183200_pgrst_auto_reload_cron.sql >>>
-- APLICADO 2026-06-23 | Melhoria 3/7: pg_cron auto-reload pgrst + fn_pgrst_reload()
CREATE OR REPLACE FUNCTION public.fn_pgrst_reload() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN PERFORM pg_notify('pgrst', 'reload schema'); END; $$;
COMMENT ON FUNCTION public.fn_pgrst_reload() IS 'Forca reload do schema cache do PostgREST. Usar apos migrations.';
GRANT EXECUTE ON FUNCTION public.fn_pgrst_reload() TO authenticated;
SELECT cron.schedule('pgrst-schema-reload', '*/15 * * * *', $$SELECT public.fn_pgrst_reload();$$);

-- <<< END 20260623183200_pgrst_auto_reload_cron.sql <<<

-- >>> BEGIN 20260623183209_melhoria_02_view_health_gravacao_20260623.sql >>>

-- MELHORIA-02: View consolidada de saúde da arquitetura de gravação
-- Responde em 1 query: quantas técnicas ativas, cobertura de produtos,
-- faixas por técnica, média de locais por produto, paradoxos ativos.

CREATE OR REPLACE VIEW public.v_health_gravacao AS
WITH
tecnicas AS (
  SELECT
    COUNT(*) AS total,
    COUNT(*) FILTER (WHERE ativo) AS ativas,
    COUNT(*) FILTER (WHERE NOT ativo) AS inativas,
    COUNT(*) FILTER (WHERE ativo AND NOT EXISTS (
      SELECT 1 FROM tabela_preco_gravacao_oficial_faixa f
      WHERE f.tabela_preco_gravacao_id = t.id
    )) AS ativas_sem_faixa
  FROM tabela_preco_gravacao_oficial t
),
faixas AS (
  SELECT
    COUNT(*) AS total,
    COUNT(*) FILTER (WHERE f.preco_unitario = 0) AS preco_zero,
    ROUND(AVG(cnt_por_tecnica), 1) AS media_faixas_por_tecnica
  FROM tabela_preco_gravacao_oficial_faixa f
  JOIN (
    SELECT tabela_preco_gravacao_id, COUNT(*) AS cnt_por_tecnica
    FROM tabela_preco_gravacao_oficial_faixa
    GROUP BY tabela_preco_gravacao_id
  ) g ON g.tabela_preco_gravacao_id = f.tabela_preco_gravacao_id
),
pat AS (
  SELECT
    COUNT(*) AS total_rows,
    COUNT(*) FILTER (WHERE is_active) AS ativas,
    COUNT(DISTINCT product_id) AS produtos_com_tecnica,
    COUNT(DISTINCT product_id) FILTER (WHERE is_active) AS produtos_ativos_com_tecnica,
    ROUND(AVG(locais_por_produto), 1) AS media_locais_por_produto
  FROM print_area_techniques,
  LATERAL (
    SELECT COUNT(DISTINCT location_code) AS locais_por_produto
    FROM print_area_techniques p2
    WHERE p2.product_id = print_area_techniques.product_id
      AND p2.is_active = true
  ) loc
),
produtos AS (
  SELECT
    COUNT(*) FILTER (WHERE is_active AND NOT is_deleted) AS ativos,
    COUNT(*) FILTER (
      WHERE is_active AND NOT is_deleted
        AND NOT EXISTS (
          SELECT 1 FROM print_area_techniques pat
          WHERE pat.product_id = p.id AND pat.is_active = true
        )
    ) AS ativos_sem_tecnica
  FROM products p
),
paradoxos AS (
  SELECT
    COUNT(*) FILTER (WHERE status_natural = 'PARADOXO_NATURAL') AS paradoxos_naturais,
    COUNT(*) FILTER (WHERE status_natural = 'OK') AS transicoes_ok
  FROM v_audit_paradoxos_gravacao
)
SELECT
  -- Técnicas
  t.total AS tecnicas_total,
  t.ativas AS tecnicas_ativas,
  t.inativas AS tecnicas_inativas,
  t.ativas_sem_faixa AS tecnicas_ativas_sem_faixa,
  -- Faixas
  f.total AS faixas_total,
  f.preco_zero AS faixas_preco_zero,
  f.media_faixas_por_tecnica,
  -- Vínculos produto↔técnica
  pa.total_rows AS pat_total_rows,
  pa.ativas AS pat_ativas,
  pa.produtos_com_tecnica,
  pa.produtos_ativos_com_tecnica,
  pa.media_locais_por_produto,
  -- Produtos
  pr.ativos AS produtos_ativos,
  pr.ativos_sem_tecnica AS produtos_ativos_sem_tecnica,
  ROUND(100.0 * pa.produtos_ativos_com_tecnica::numeric / NULLIF(pr.ativos, 0), 1) AS cobertura_pct,
  -- Paradoxos de negócio
  p.paradoxos_naturais,
  p.transicoes_ok,
  -- Score de qualidade (0-100)
  ROUND(
    100.0
    - (t.ativas_sem_faixa * 5)
    - (LEAST(f.preco_zero * 10, 20))
    - (LEAST((100 - ROUND(100.0 * pa.produtos_ativos_com_tecnica::numeric / NULLIF(pr.ativos, 0), 1))::int, 30))
    , 0
  ) AS qualidade_score,
  NOW() AS verificado_em
FROM tecnicas t, faixas f, pat pa, produtos pr, paradoxos p;

GRANT SELECT ON public.v_health_gravacao TO authenticated;
COMMENT ON VIEW public.v_health_gravacao IS
  'Dashboard de saúde da arquitetura de gravação — 1 linha, snapshot ao vivo.';
;

