-- >>> BEGIN 20260623183854_melhoria_04_desativar_pat_produtos_inativos.sql >>>

-- ================================================================
-- MELHORIA-04: Desativar técnicas de produtos inativos
-- 879 linhas em print_area_techniques apontam para products.is_active=false
-- Essas linhas aparecem em contagens, poluem queries e confundem auditoria.
-- Solução: set is_active=false + created_at snapshot para rastreabilidade.
-- ================================================================

-- Primeiro: registrar quantas linhas serão afetadas
DO $$
DECLARE v_count int;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM print_area_techniques pat
  JOIN products p ON p.id = pat.product_id
  WHERE p.is_active = false AND pat.is_active = true;
  RAISE NOTICE 'Desativando % linhas de produtos inativos', v_count;
END $$;

-- Executar desativação
UPDATE public.print_area_techniques pat
SET
  is_active   = false,
  updated_at  = now()
FROM products p
WHERE p.id = pat.product_id
  AND p.is_active = false
  AND pat.is_active = true;

-- Confirmar
SELECT
  'after_fix: is_active=true de produtos ativos'   AS check_label,
  COUNT(*) AS qtd
FROM print_area_techniques pat
JOIN products p ON p.id = pat.product_id
WHERE p.is_active = true AND pat.is_active = true
UNION ALL
SELECT
  'after_fix: is_active=true de produtos INATIVOS (deve ser 0)',
  COUNT(*)
FROM print_area_techniques pat
JOIN products p ON p.id = pat.product_id
WHERE p.is_active = false AND pat.is_active = true;
;

-- <<< END 20260623183854_melhoria_04_desativar_pat_produtos_inativos.sql <<<

-- >>> BEGIN 20260623183907_melhoria_05_trigger_sync_pat_on_product_deactivate.sql >>>

-- ================================================================
-- MELHORIA-05: Trigger automático — produto desativado → PAT desativada
-- Previne reacúmulo do problema da MELHORIA-04 no futuro.
-- ================================================================
CREATE OR REPLACE FUNCTION public.fn_sync_pat_on_product_status_change()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Só age quando is_active muda
  IF NEW.is_active = OLD.is_active THEN
    RETURN NEW;
  END IF;

  IF NEW.is_active = false THEN
    -- Produto desativado: desativar todas as PATs
    UPDATE public.print_area_techniques
    SET is_active = false, updated_at = now()
    WHERE product_id = NEW.id AND is_active = true;
  END IF;
  -- Nota: NÃO reativamos PATs ao reativar produto —
  -- reativação é intencional e manual (controle de qualidade)

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_sync_pat_on_product_deactivate ON public.products;
CREATE TRIGGER trg_sync_pat_on_product_deactivate
  AFTER UPDATE OF is_active ON public.products
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_sync_pat_on_product_status_change();

-- Confirmar criação
SELECT trigger_name, event_manipulation, action_timing
FROM information_schema.triggers
WHERE trigger_name = 'trg_sync_pat_on_product_deactivate';
;

-- <<< END 20260623183907_melhoria_05_trigger_sync_pat_on_product_deactivate.sql <<<

