-- >>> BEGIN 20260623184206_melhoria_09_fn_health_check_gravacao_v2.sql >>>

DROP FUNCTION IF EXISTS public.fn_health_check_gravacao();

CREATE FUNCTION public.fn_health_check_gravacao()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_total_tecnicas        INT;
  v_tecnicas_ativas       INT;
  v_tecnicas_sem_faixa    INT;
  v_total_faixas          INT;
  v_total_pat             INT;
  v_pat_ativas            INT;
  v_pat_produto_inativo   INT;
  v_pat_tabela_inativa    INT;
  v_produtos_ativos       INT;
  v_produtos_com_tecnica  INT;
  v_fn_options_ok         BOOLEAN := false;
  v_fn_price_ok           BOOLEAN := false;
  v_test_result           JSONB;
  v_test_area_id          UUID;
  v_test_product_id       UUID;
BEGIN
  SELECT COUNT(*) INTO v_total_tecnicas FROM tabela_preco_gravacao_oficial;
  SELECT COUNT(*) INTO v_tecnicas_ativas FROM tabela_preco_gravacao_oficial WHERE ativo=true;
  SELECT COUNT(*) INTO v_total_faixas FROM tabela_preco_gravacao_oficial_faixa;
  SELECT COUNT(*) INTO v_total_pat FROM print_area_techniques;
  SELECT COUNT(*) INTO v_pat_ativas FROM print_area_techniques WHERE is_active=true;
  SELECT COUNT(*) INTO v_produtos_ativos FROM products WHERE is_active=true;
  SELECT COUNT(*) INTO v_tecnicas_sem_faixa
    FROM tabela_preco_gravacao_oficial t WHERE t.ativo=true
    AND NOT EXISTS (SELECT 1 FROM tabela_preco_gravacao_oficial_faixa f WHERE f.tabela_preco_gravacao_id=t.id);
  SELECT COUNT(*) INTO v_pat_produto_inativo
    FROM print_area_techniques pat JOIN products p ON p.id=pat.product_id
    WHERE pat.is_active=true AND p.is_active=false;
  SELECT COUNT(*) INTO v_pat_tabela_inativa
    FROM print_area_techniques pat JOIN tabela_preco_gravacao_oficial t ON t.id=pat.tabela_preco_id
    WHERE pat.is_active=true AND t.ativo=false;
  SELECT COUNT(DISTINCT product_id) INTO v_produtos_com_tecnica
    FROM print_area_techniques WHERE is_active=true;

  -- Testar RPCs
  BEGIN
    SELECT pat.id, pat.product_id INTO v_test_area_id, v_test_product_id
    FROM print_area_techniques pat
    JOIN products p ON p.id=pat.product_id
    WHERE pat.is_active=true AND p.is_active=true LIMIT 1;
    IF v_test_product_id IS NOT NULL THEN
      SELECT fn_get_product_customization_options(v_test_product_id) INTO v_test_result;
      v_fn_options_ok := (v_test_result IS NOT NULL AND v_test_result ? 'product_id');
    END IF;
  EXCEPTION WHEN OTHERS THEN v_fn_options_ok := false; END;

  BEGIN
    SELECT fn_get_customization_price(v_test_area_id,100,1,NULL,NULL,0) INTO v_test_result;
    v_fn_price_ok := (v_test_result IS NOT NULL);
  EXCEPTION WHEN OTHERS THEN v_fn_price_ok := false; END;

  RETURN jsonb_build_object(
    'timestamp',    now(),
    'status_geral', CASE
      WHEN NOT v_fn_options_ok OR NOT v_fn_price_ok THEN 'CRITICO'
      WHEN v_pat_produto_inativo>0 OR v_pat_tabela_inativa>0 OR v_tecnicas_sem_faixa>0 THEN 'DEGRADADO'
      ELSE 'SAUDAVEL'
    END,
    'funcoes_rpc', jsonb_build_object(
      'fn_get_product_customization_options', v_fn_options_ok,
      'fn_get_customization_price', v_fn_price_ok
    ),
    'tecnicas', jsonb_build_object(
      'total', v_total_tecnicas, 'ativas', v_tecnicas_ativas,
      'sem_faixa_preco', v_tecnicas_sem_faixa
    ),
    'faixas', jsonb_build_object('total', v_total_faixas),
    'print_area_techniques', jsonb_build_object(
      'total', v_total_pat, 'ativas', v_pat_ativas,
      'alerta_produto_inativo', v_pat_produto_inativo,
      'alerta_tabela_inativa', v_pat_tabela_inativa
    ),
    'cobertura', jsonb_build_object(
      'produtos_ativos', v_produtos_ativos,
      'com_tecnica', v_produtos_com_tecnica,
      'sem_tecnica', v_produtos_ativos - v_produtos_com_tecnica,
      'pct_cobertura', ROUND(v_produtos_com_tecnica::numeric/NULLIF(v_produtos_ativos,0)*100,1)
    )
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.fn_health_check_gravacao() TO authenticated;

SELECT fn_health_check_gravacao();
;

-- <<< END 20260623184206_melhoria_09_fn_health_check_gravacao_v2.sql <<<

-- >>> BEGIN 20260623184318_fix_fn_cron_watchdog_search_path_20260623.sql >>>
-- FIX: fn_cron_watchdog — SECURITY DEFINER sem search_path (schema injection vulnerability)
-- Função nova detectada em auditoria Round 5. Acessa pg_stat_activity + public.*
CREATE OR REPLACE FUNCTION public.fn_cron_watchdog()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $function$
DECLARE v_killed int := 0; v_result jsonb; v_rec record;
BEGIN
  FOR v_rec IN
    SELECT a.pid, a.query, a.query_start,
      ROUND(EXTRACT(EPOCH FROM (now() - a.query_start)) * 1000)::bigint AS duration_ms,
      (regexp_match(a.query, '''([^'']+)'''))[1] AS job_label,
      COALESCE(
        (SELECT m.timeout_sec FROM public.cron_job_timeout_map m
         WHERE a.query ILIKE '%' || m.jobname || '%' LIMIT 1), 55
      ) AS timeout_sec
    FROM pg_stat_activity a
    WHERE a.application_name = 'pg_cron' AND a.state = 'active'
      AND a.query_start IS NOT NULL
      AND a.query NOT ILIKE '%fn_cron_watchdog%'
      AND a.pid != pg_backend_pid()
  LOOP
    IF v_rec.duration_ms > (v_rec.timeout_sec * 1000) THEN
      INSERT INTO public.cron_watchdog_log
        (pid, jobname, query_start, duration_ms, query_preview)
      VALUES (v_rec.pid, COALESCE(v_rec.job_label,'unknown'),
              v_rec.query_start, v_rec.duration_ms, LEFT(v_rec.query,200));
      PERFORM pg_cancel_backend(v_rec.pid);
      v_killed := v_killed + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('killed', v_killed, 'action',
    CASE WHEN v_killed > 0 THEN 'KILLED:'||v_killed ELSE 'ALL_OK' END);
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END; $function$;;

-- <<< END 20260623184318_fix_fn_cron_watchdog_search_path_20260623.sql <<<

-- >>> BEGIN 20260623184328_fix_fn_cron_safe_run_search_path_r2_20260623.sql >>>
-- FIX R2: fn_cron_safe_run — revertida pelo Lovable bot, re-aplicando search_path
-- 48 crons dependem. EXECUTE p_sql herda search_path=public (seguro).
CREATE OR REPLACE FUNCTION public.fn_cron_safe_run(
  p_key bigint, p_sql text,
  p_timeout_ms integer DEFAULT 45000,
  p_job_label text DEFAULT 'cron'
)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $function$
DECLARE v_start timestamptz := clock_timestamp(); v_duration_ms int;
BEGIN
  IF NOT pg_try_advisory_xact_lock(p_key) THEN
    RETURN format('[%s] SKIP: job ainda em execução (lock=%s)', p_job_label, p_key);
  END IF;
  EXECUTE format('SET LOCAL statement_timeout = %L', p_timeout_ms || 'ms');
  EXECUTE p_sql;
  v_duration_ms := EXTRACT(EPOCH FROM (clock_timestamp() - v_start)) * 1000;
  RETURN format('[%s] OK: %sms', p_job_label, v_duration_ms);
EXCEPTION
  WHEN query_canceled THEN
    RETURN format('[%s] TIMEOUT após %sms (limite=%sms)', p_job_label,
      EXTRACT(EPOCH FROM (clock_timestamp() - v_start))::int * 1000, p_timeout_ms);
  WHEN OTHERS THEN
    RETURN format('[%s] ERRO: %s', p_job_label, SQLERRM);
END; $function$;;

-- <<< END 20260623184328_fix_fn_cron_safe_run_search_path_r2_20260623.sql <<<

-- >>> BEGIN 20260623184340_fix_fn_capture_connection_snapshot_r2_20260623.sql >>>
-- FIX R2: fn_capture_connection_snapshot — revertida pelo Lovable, re-aplicando
CREATE OR REPLACE FUNCTION public.fn_capture_connection_snapshot()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $function$
DECLARE
  v_total int; v_active int; v_idle_tx int; v_max int;
  v_pct numeric(5,2); v_top_users jsonb; v_result jsonb;
BEGIN
  SELECT COUNT(*), COUNT(*) FILTER (WHERE state='active'),
    COUNT(*) FILTER (WHERE state='idle in transaction'),
    (SELECT setting::int FROM pg_settings WHERE name='max_connections')
  INTO v_total, v_active, v_idle_tx, v_max
  FROM pg_stat_activity WHERE pid != pg_backend_pid();
  v_pct := ROUND((v_total::numeric / NULLIF(v_max,0)) * 100, 2);
  SELECT jsonb_agg(row_to_json(t)) INTO v_top_users FROM (
    SELECT usename, state, COUNT(*) as n FROM pg_stat_activity
    WHERE pid != pg_backend_pid()
    GROUP BY usename, state ORDER BY n DESC LIMIT 8) t;
  INSERT INTO public.db_connection_snapshots
    (total_conns,active_conns,idle_in_tx_conns,max_conns,usage_pct,top_users)
  VALUES(v_total,v_active,v_idle_tx,v_max,v_pct,v_top_users);
  DELETE FROM public.db_connection_snapshots WHERE captured_at < now()-interval '7 days';
  v_result := jsonb_build_object('total',v_total,'active',v_active,
    'idle_in_tx',v_idle_tx,'max',v_max,'usage_pct',v_pct,'alert',v_pct>=75);
  RETURN v_result;
END; $function$;;

-- <<< END 20260623184340_fix_fn_capture_connection_snapshot_r2_20260623.sql <<<

-- >>> BEGIN 20260623184442_melhoria_11_fix_p6_paradoxo_cobra_cor_max1.sql >>>

-- ================================================================
-- MELHORIA-11: Corrigir P6 — cobra_por_cor=true com max_cores=1
-- ADE1-01 "Adesivo | 1 Cor" e ETQ1-01 "Etiqueta | 1 Cor"
-- São técnicas de 1 cor por definição — cobra_por_cor deve ser false.
-- Cobrar "por cor" quando só existe 1 cor é paradoxo lógico que
-- pode gerar erro silencioso no multiplicador de cor da cotação.
-- ================================================================
UPDATE public.tabela_preco_gravacao_oficial
SET
  cobra_por_cor = false,
  updated_at = now()
WHERE codigo_tabela IN ('ADE1-01', 'ETQ1-01')
  AND cobra_por_cor = true
  AND COALESCE(max_cores, 1) <= 1;

-- Confirmar correção
SELECT codigo_tabela, nome, cobra_por_cor, max_cores
FROM tabela_preco_gravacao_oficial
WHERE codigo_tabela IN ('ADE1-01', 'ETQ1-01');
;

-- <<< END 20260623184442_melhoria_11_fix_p6_paradoxo_cobra_cor_max1.sql <<<

-- >>> BEGIN 20260623184459_melhoria_12_v_print_area_techniques_public_rebuild_v2.sql >>>

DROP VIEW IF EXISTS public.v_print_area_techniques_public CASCADE;

CREATE VIEW public.v_print_area_techniques_public AS
SELECT
  id,
  product_id,
  tabela_preco_id,
  location_code,
  location_name,
  location_order,
  max_width,
  max_height,
  is_curved,
  shape,
  technique_order,
  is_active,
  notes,
  unit_cost,
  created_at,
  updated_at
FROM public.print_area_techniques
WHERE is_active = true;

ALTER VIEW public.v_print_area_techniques_public SET (security_invoker = false);
GRANT SELECT ON public.v_print_area_techniques_public TO anon, authenticated;

SELECT COUNT(*) AS total_ativas FROM v_print_area_techniques_public;
;

