CREATE POLICY produtos_site_padronizacao_auth_read
  ON public.produtos_site_padronizacao
  FOR SELECT TO authenticated
  USING (true);

-- Reload pgrst para reconhecer as novas policies
NOTIFY pgrst, 'reload schema';
;

