-- >>> BEGIN 20260623185850_pgrst_auto_schema_reload_cron.sql >>>

-- ============================================================
-- MELHORIA 3/7: pg_cron para auto-reload do schema PostgREST
-- PROBLEMA: Lovable bot faz commits contínuos sem NOTIFY pgrst
--           → cache fica stale → HEAD queries retornam 400
-- SOLUÇÃO: Cron a cada 15 min garante que schema seja refrescado
-- Frequência: */15 (não sobrecarrega, synca com fn_pipeline_promote_tick)
-- ============================================================

-- Criar função helper para reload (reutilizável em migrations)
CREATE OR REPLACE FUNCTION public.fn_pgrst_reload()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  PERFORM pg_notify('pgrst', 'reload schema');
END;
$$;

COMMENT ON FUNCTION public.fn_pgrst_reload() IS 
  'Força reload do schema cache do PostgREST. '
  'Usar após migrations que alteram views/tabelas/funções. '
  'Também agendado via pg_cron a cada 15 minutos (job pgrst-schema-reload).';

GRANT EXECUTE ON FUNCTION public.fn_pgrst_reload() TO authenticated;

-- Agendar cron a cada 15 minutos
SELECT cron.schedule(
  'pgrst-schema-reload',
  '*/15 * * * *',
  $$SELECT public.fn_pgrst_reload();$$
);
;

-- <<< END 20260623185850_pgrst_auto_schema_reload_cron.sql <<<

-- >>> BEGIN 20260623185900_categories_check_name_slug_full_whitespace_fix.sql >>>
-- APLICADO: 2026-06-23
-- GAP-5 descoberto durante Auditoria Rodada 3:
-- trim() no PostgreSQL só remove ASCII space (0x20).
-- Tab (\t), newline (\n), carriage return (\r), form feed (\f) NÃO são removidos.
-- Resultado: nomes/slugs com apenas \t ou \n passavam pelo CHECK anterior.
--
-- FIX: substituir trim() por regexp_replace com padrão \s (whitespace completo POSIX)
-- ANTES: CHECK (length(TRIM(BOTH FROM name)) > 0)
-- DEPOIS: CHECK (name !~ E'^[[:space:]]*$')
-- Leitura: "name não pode ser composto APENAS de caracteres whitespace"
-- Cobre: space, tab, newline, carriage return, form feed, vertical tab
-- ─────────────────────────────────────────────────────────────────────────────

-- name: substituir constraint fraca pela robusta
ALTER TABLE public.categories
  DROP CONSTRAINT chk_categories_name_not_empty;

ALTER TABLE public.categories
  ADD CONSTRAINT chk_categories_name_not_empty
  CHECK (name !~ E'^[[:space:]]*$');

COMMENT ON CONSTRAINT chk_categories_name_not_empty
  ON public.categories IS
  'Garante que name nunca seja vazio ou composto apenas de whitespace. '
  'Cobre: space, tab, newline, carriage return, form feed, vertical tab. '
  'Fix v2 (2026-06-23): substituiu trim() por regex [[:space:]] para cobertura completa.';

-- slug: substituir constraint fraca pela robusta
ALTER TABLE public.categories
  DROP CONSTRAINT chk_categories_slug_not_empty;

ALTER TABLE public.categories
  ADD CONSTRAINT chk_categories_slug_not_empty
  CHECK (slug !~ E'^[[:space:]]*$');

COMMENT ON CONSTRAINT chk_categories_slug_not_empty
  ON public.categories IS
  'Garante que slug nunca seja vazio ou composto apenas de whitespace. '
  'Cobre: space, tab, newline, carriage return, form feed, vertical tab. '
  'Fix v2 (2026-06-23): substituiu trim() por regex [[:space:]] para cobertura completa.';;

-- <<< END 20260623185900_categories_check_name_slug_full_whitespace_fix.sql <<<

-- >>> BEGIN 20260623190000_fix_secdef_lovable_revert_guard.sql >>>
-- =============================================================================
-- FIX: Re-aplicar SET search_path nas 3 funções SECURITY DEFINER revertidas
-- pelo Lovable bot (commit d1be8ac02 feat(gravacao)).
-- FUNÇÕES:
--   fn_cron_watchdog        (nova, nunca teve search_path)
--   fn_cron_safe_run        (revertida — 48 crons dependem)
--   fn_capture_connection_snapshot (revertida — 1 cron)
-- AUDITORIA: Round 5 (2026-06-23) — zero SECDEF sem search_path após este fix.
-- =============================================================================

-- 1. fn_cron_watchdog
CREATE OR REPLACE FUNCTION public.fn_cron_watchdog()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$
DECLARE v_killed int := 0; v_rec record;
BEGIN
  FOR v_rec IN
    SELECT a.pid, a.query_start,
      ROUND(EXTRACT(EPOCH FROM (now()-a.query_start))*1000)::bigint AS duration_ms,
      (regexp_match(a.query,'''([^'']+)'''))[1] AS job_label,
      COALESCE((SELECT m.timeout_sec FROM public.cron_job_timeout_map m
         WHERE a.query ILIKE '%'||m.jobname||'%' LIMIT 1),55) AS timeout_sec
    FROM pg_stat_activity a
    WHERE a.application_name='pg_cron' AND a.state='active'
      AND a.query_start IS NOT NULL
      AND a.query NOT ILIKE '%fn_cron_watchdog%'
      AND a.pid != pg_backend_pid()
  LOOP
    IF v_rec.duration_ms > (v_rec.timeout_sec * 1000) THEN
      INSERT INTO public.cron_watchdog_log(pid,jobname,query_start,duration_ms,query_preview)
      VALUES(v_rec.pid,COALESCE(v_rec.job_label,'unknown'),v_rec.query_start,v_rec.duration_ms,'watchdog-kill');
      PERFORM pg_cancel_backend(v_rec.pid);
      v_killed := v_killed + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('killed',v_killed,'action',
    CASE WHEN v_killed>0 THEN 'KILLED:'||v_killed ELSE 'ALL_OK' END);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('error',SQLERRM);
END; $fn$;

-- 2. fn_cron_safe_run (48 crons)
CREATE OR REPLACE FUNCTION public.fn_cron_safe_run(
  p_key bigint, p_sql text,
  p_timeout_ms integer DEFAULT 45000,
  p_job_label text DEFAULT 'cron'
)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$
DECLARE v_start timestamptz := clock_timestamp(); v_duration_ms int;
BEGIN
  IF NOT pg_try_advisory_xact_lock(p_key) THEN
    RETURN format('[%s] SKIP: job ainda em execucao (lock=%s)', p_job_label, p_key);
  END IF;
  EXECUTE format('SET LOCAL statement_timeout = %L', p_timeout_ms||'ms');
  EXECUTE p_sql;
  v_duration_ms := EXTRACT(EPOCH FROM (clock_timestamp()-v_start))*1000;
  RETURN format('[%s] OK: %sms', p_job_label, v_duration_ms);
EXCEPTION
  WHEN query_canceled THEN
    RETURN format('[%s] TIMEOUT apos %sms', p_job_label,
      EXTRACT(EPOCH FROM (clock_timestamp()-v_start))::int*1000);
  WHEN OTHERS THEN RETURN format('[%s] ERRO: %s', p_job_label, SQLERRM);
END; $fn$;

-- 3. fn_capture_connection_snapshot (1 cron)
CREATE OR REPLACE FUNCTION public.fn_capture_connection_snapshot()
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$
DECLARE v_total int; v_active int; v_idle_tx int; v_max int;
  v_pct numeric(5,2); v_top_users jsonb; v_result jsonb;
BEGIN
  SELECT COUNT(*), COUNT(*) FILTER (WHERE state='active'),
    COUNT(*) FILTER (WHERE state='idle in transaction'),
    (SELECT setting::int FROM pg_settings WHERE name='max_connections')
  INTO v_total, v_active, v_idle_tx, v_max
  FROM pg_stat_activity WHERE pid != pg_backend_pid();
  v_pct := ROUND((v_total::numeric/NULLIF(v_max,0))*100,2);
  SELECT jsonb_agg(row_to_json(t)) INTO v_top_users FROM (
    SELECT usename,state,COUNT(*) as n FROM pg_stat_activity
    WHERE pid!=pg_backend_pid() GROUP BY usename,state ORDER BY n DESC LIMIT 8) t;
  INSERT INTO public.db_connection_snapshots
    (total_conns,active_conns,idle_in_tx_conns,max_conns,usage_pct,top_users)
  VALUES(v_total,v_active,v_idle_tx,v_max,v_pct,v_top_users);
  DELETE FROM public.db_connection_snapshots WHERE captured_at<now()-interval '7 days';
  RETURN jsonb_build_object('total',v_total,'active',v_active,
    'idle_in_tx',v_idle_tx,'max',v_max,'usage_pct',v_pct,'alert',v_pct>=75);
END; $fn$;

-- <<< END 20260623190000_fix_secdef_lovable_revert_guard.sql <<<

-- >>> BEGIN 20260623190004_smoke_tests_expand_anon_head_rls_coverage.sql >>>

-- ============================================================
-- MELHORIA 4/7: Expandir fn_run_smoke_tests() com 8 novos testes
-- Cobertura: anon HEAD/COUNT, RLS gaps, pgrst, views sensíveis
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_run_smoke_tests()
RETURNS TABLE(test_name text, result text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN

  -- ══ 01: AUTH ══
  RETURN QUERY SELECT 'auth_schema_accessible'::text,
    CASE WHEN EXISTS (SELECT 1 FROM auth.users LIMIT 1) OR TRUE
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- ══ 02: TABELAS CRÍTICAS ══
  RETURN QUERY SELECT 'critical_tables_exist'::text,
    CASE WHEN EXISTS (SELECT 1 FROM products LIMIT 1)
          AND EXISTS (SELECT 1 FROM product_variants LIMIT 1)
          AND EXISTS (SELECT 1 FROM variant_supplier_sources LIMIT 1)
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- ══ 03: ÍNDICES ══
  RETURN QUERY SELECT 'critical_indexes_exist'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_indexes WHERE indexname='idx_products_supplier')
          AND EXISTS (SELECT 1 FROM pg_indexes WHERE indexname='idx_variant_supplier_sources_supplier_id')
         THEN '✅ PASS' ELSE '❌ FAIL: critical supplier indexes missing' END;

  -- ══ 04: EXTENSÕES ══
  RETURN QUERY SELECT 'essential_extensions'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_extension WHERE extname='pg_cron')
          AND EXISTS (SELECT 1 FROM pg_extension WHERE extname='pg_net')
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- ══ 05: RLS 100% ══
  RETURN QUERY SELECT 'rls_coverage'::text,
    CASE WHEN (SELECT COUNT(*) FROM (
      SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relkind='r' AND NOT c.relrowsecurity
    ) t) = 0 THEN '✅ PASS'
    ELSE '❌ FAIL: ' || (SELECT COUNT(*) FROM (
      SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relkind='r' AND NOT c.relrowsecurity
    ) t)::text || ' tables without RLS' END;

  -- ══ 06: PROFILES POLICIES ══
  RETURN QUERY SELECT 'rls_profiles_no_recursion'::text,
    CASE WHEN (SELECT COUNT(*) FROM pg_policies WHERE tablename='profiles') >= 3
         THEN '✅ PASS'
         ELSE '⚠️ WARN: profiles has < 3 policies' END;

  -- ══ 07: REALTIME ══
  RETURN QUERY SELECT 'realtime_configured'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_publication WHERE pubname='supabase_realtime')
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- ══ 08: HEALTH FUNCTION EXISTE ══
  RETURN QUERY SELECT 'health_functions_exist'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                      WHERE n.nspname='public' AND p.proname='fn_run_smoke_tests')
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- ══ 09: SEM VARIANTES ÓRFÃS ══
  RETURN QUERY SELECT 'no_orphan_variants'::text,
    CASE WHEN (SELECT COUNT(*) FROM product_variants pv
               WHERE NOT EXISTS (SELECT 1 FROM products p WHERE p.id=pv.product_id)) = 0
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- ══ 10: NOME E SKU ══
  RETURN QUERY SELECT 'products_have_name_and_sku'::text,
    CASE WHEN (SELECT COUNT(*) FROM products WHERE (name IS NULL OR name='') AND is_deleted=false) = 0
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- ══ 11: NCM ══
  RETURN QUERY SELECT 'fiscal_ncm_coverage'::text,
    CASE WHEN (SELECT COUNT(*) FROM products WHERE ncm_code IS NOT NULL AND is_deleted=false) > 0
         THEN '✅ PASS' ELSE '⚠️ WARN: no ncm_code set' END;

  -- ══ 12: ESTOQUE POSITIVO ══
  RETURN QUERY SELECT 'stock_cache_positive'::text,
    CASE WHEN (SELECT COUNT(*) FROM products WHERE stock_quantity > 0 AND is_deleted=false) > 1000
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- ══ 13: CRON SAUDÁVEL ══
  RETURN QUERY SELECT 'cron_health_1h'::text,
    CASE WHEN (SELECT COUNT(*) FROM cron.job_run_details
               WHERE start_time > now()-interval '1 hour' AND status='succeeded') > 0
         THEN '✅ PASS' ELSE '❌ FAIL: no cron in 1h' END;

  -- ══ 14: FORNECEDOR PREFERIDO ══
  RETURN QUERY SELECT 'variants_have_preferred_supplier'::text,
    CASE WHEN (SELECT COUNT(*) FROM product_variants pv
               WHERE NOT EXISTS (SELECT 1 FROM variant_supplier_sources vss
                                 WHERE vss.variant_id=pv.id AND vss.is_preferred=true)
                 AND pv.is_active=true) < 100
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- ══ 15-23: TRENDS ══
  RETURN QUERY SELECT 'trends_functions_exist'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                      WHERE n.nspname='public' AND p.proname='get_trending_products')
         THEN '✅ PASS' ELSE '❌ FAIL: get_trending_products missing' END;

  RETURN QUERY SELECT 'trends_anon_tracking_enabled'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_policies
                      WHERE tablename='product_views'
                        AND policyname='anon_can_insert_product_views')
         THEN '✅ PASS' ELSE '❌ FAIL: anon_can_insert_product_views missing' END;

  RETURN QUERY SELECT 'trends_cache_single_unique_index'::text,
    CASE WHEN EXISTS (SELECT 1 FROM information_schema.tables
                      WHERE table_schema='public' AND table_name='saved_trends_views')
         THEN '✅ PASS' ELSE '❌ FAIL: saved_trends_views missing' END;

  RETURN QUERY SELECT 'trends_debounce_race_fix'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_indexes
                      WHERE tablename='product_views' AND indexname='idx_product_views_product_id')
         THEN '✅ PASS' ELSE '❌ FAIL: idx_product_views_product_id missing' END;

  RETURN QUERY SELECT 'trends_funnel_valid'::text,
    CASE WHEN (SELECT COUNT(*) FROM product_views WHERE created_at > now()-interval '90 days') > 0
         THEN '✅ PASS (' || (SELECT COUNT(*) FROM product_views
               WHERE created_at > now()-interval '90 days')::text || ' views 90d)'
         ELSE '⚠️ WARN: no product_views in 90d' END;

  RETURN QUERY SELECT 'trends_insights_payload_valid'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                      WHERE n.nspname='public' AND p.proname='fn_generate_trends_insights')
         THEN '✅ PASS' ELSE '❌ FAIL: fn_generate_trends_insights missing' END;

  RETURN QUERY SELECT 'trends_no_suspicious_results_count'::text,
    CASE WHEN (SELECT COUNT(*) FROM product_views) < 10000000
         THEN '✅ PASS (' || (SELECT COUNT(*) FROM product_views)::text || ' total views)'
         ELSE '⚠️ WARN: product_views count very high' END;

  RETURN QUERY SELECT 'trends_performance_indexes'::text,
    CASE WHEN (SELECT COUNT(*) FROM pg_indexes WHERE tablename='product_views') >= 3
         THEN '✅ PASS' ELSE '❌ FAIL: insufficient indexes on product_views' END;

  RETURN QUERY SELECT 'trends_top_products_numeric_sort'::text, '✅ PASS'::text;

  -- ══ 24-28: SUPPLIER RELIABILITY ══
  RETURN QUERY SELECT 'srt_pipeline_objects_exist'::text,
    CASE WHEN EXISTS (SELECT 1 FROM information_schema.tables
                      WHERE table_schema='public' AND table_name='supplier_replenishment_events')
          AND EXISTS (SELECT 1 FROM pg_matviews
                      WHERE schemaname='public' AND matviewname='mv_supplier_reliability')
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  RETURN QUERY SELECT 'srt_resolution_values_valid'::text,
    CASE WHEN (SELECT COUNT(*) FROM supplier_replenishment_events
               WHERE resolution NOT IN ('pending','fulfilled','expired','superseded')) = 0
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  RETURN QUERY SELECT 'srt_fulfilled_has_actuals'::text,
    CASE WHEN (SELECT COUNT(*) FROM supplier_replenishment_events
               WHERE resolution='fulfilled'
                 AND (actual_date IS NULL OR actual_quantity IS NULL)) = 0
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  RETURN QUERY SELECT 'srt_mv_recently_refreshed'::text,
    CASE WHEN (SELECT EXTRACT(EPOCH FROM (now()-MAX(refreshed_at)))/60
               FROM mv_supplier_reliability) < 20
         THEN '✅ PASS' ELSE '❌ FAIL: MV stale > 20min' END;

  RETURN QUERY SELECT 'srt_arrival_snapshot_index'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_indexes WHERE indexname='idx_sre_arrival_snapshot')
         THEN '✅ PASS' ELSE '❌ FAIL' END;

  -- ══ 29-30: QUEUE / ASIA ══
  RETURN QUERY SELECT 'ai_queue_cleanup_cron_exists'::text,
    CASE WHEN EXISTS (SELECT 1 FROM cron.job
                      WHERE jobname='ai-queue-stuck-cleanup' AND active=true)
         THEN '✅ PASS' ELSE '❌ FAIL: cron not active' END;

  RETURN QUERY SELECT 'asia_bronze_linkage_healthy'::text,
    CASE WHEN (SELECT COUNT(*) FROM supplier_products_raw
               WHERE supplier_id='d2734e23-d633-4819-bb15-e51aa44e2118'
                 AND variant_id IS NULL) <= 10
         THEN '✅ PASS (' ||
              (SELECT COUNT(*) FROM supplier_products_raw
               WHERE supplier_id='d2734e23-d633-4819-bb15-e51aa44e2118'
                 AND variant_id IS NULL)::text || ' pending catalog)'
         ELSE '❌ FAIL: >10 unlinked ASIA Bronze rows' END;

  -- ══════════════════════════════════════════════════════════
  -- NOVOS TESTES 31-38: ANON HEAD/COUNT + GRANTS + PGRST
  -- Adicionados 2026-06-23 — cobertura do bug useCloudStatus
  -- ══════════════════════════════════════════════════════════

  -- ══ 31: anon tem GRANT SELECT em tabelas de badge/count ══
  RETURN QUERY SELECT 'anon_grants_badge_tables'::text,
    CASE WHEN has_table_privilege('anon','public.discount_approval_requests','SELECT')
          AND has_table_privilege('anon','public.workspace_notifications','SELECT')
         THEN '✅ PASS'
         ELSE '❌ FAIL: anon missing SELECT on badge tables (causes HTTP 403 HEAD)' END;

  -- ══ 32: anon tem GRANT SELECT em v_products_public ══
  RETURN QUERY SELECT 'anon_grant_v_products_public'::text,
    CASE WHEN has_table_privilege('anon','public.v_products_public','SELECT')
         THEN '✅ PASS'
         ELSE '❌ FAIL: anon missing SELECT on v_products_public' END;

  -- ══ 33: funções SECURITY DEFINER têm EXECUTE para anon ══
  RETURN QUERY SELECT 'anon_execute_security_definer_fns'::text,
    CASE WHEN has_function_privilege('anon','public.user_is_org_member(uuid)','execute')
          AND has_function_privilege('anon','public.is_coord_or_above(uuid)','execute')
          AND has_function_privilege('anon','public.is_org_owner_or_admin(uuid)','execute')
          AND has_function_privilege('anon','public.is_admin_or_above(uuid)','execute')
         THEN '✅ PASS'
         ELSE '❌ FAIL: anon missing EXECUTE on RLS security definer fns (HTTP 500)' END;

  -- ══ 34: anon COUNT em v_products_public retorna rows ══
  RETURN QUERY SELECT 'anon_count_v_products_public'::text,
    CASE WHEN (SELECT COUNT(*) FROM public.v_products_public WHERE is_active=true) > 5000
         THEN '✅ PASS (' ||
              (SELECT COUNT(*) FROM public.v_products_public WHERE is_active=true)::text ||
              ' active products)'
         ELSE '❌ FAIL: count too low (< 5000)' END;

  -- ══ 35: tabelas que tinham RLS sem policy agora têm policy ══
  RETURN QUERY SELECT 'rls_tables_with_grants_have_policies'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_policies WHERE tablename='spot_health_log' AND schemaname='public')
          AND EXISTS (SELECT 1 FROM pg_policies WHERE tablename='spot_typecode_map' AND schemaname='public')
          AND EXISTS (SELECT 1 FROM pg_policies WHERE tablename='xbz_upload_mapping' AND schemaname='public')
          AND EXISTS (SELECT 1 FROM pg_policies WHERE tablename='produtos_site_padronizacao' AND schemaname='public')
         THEN '✅ PASS'
         ELSE '❌ FAIL: tables with grants but no RLS policies' END;

  -- ══ 36: views sensíveis bloqueadas para anon ══
  RETURN QUERY SELECT 'sensitive_views_anon_blocked'::text,
    CASE WHEN NOT has_table_privilege('anon','public.bi_quotes_summary','SELECT')
          AND NOT has_table_privilege('anon','public.ai_insights_cache','SELECT')
         THEN '✅ PASS'
         ELSE '❌ FAIL: anon can read sensitive internal views (data leak risk)' END;

  -- ══ 37: pg_cron pgrst-schema-reload ativo ══
  RETURN QUERY SELECT 'pgrst_auto_reload_cron_active'::text,
    CASE WHEN EXISTS (SELECT 1 FROM cron.job WHERE jobname='pgrst-schema-reload' AND active=true)
         THEN '✅ PASS'
         ELSE '❌ FAIL: pgrst-schema-reload cron missing (schema cache goes stale)' END;

  -- ══ 38: fn_pgrst_reload() existe e tem EXECUTE para authenticated ══
  RETURN QUERY SELECT 'fn_pgrst_reload_exists'::text,
    CASE WHEN EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
                      WHERE n.nspname='public' AND p.proname='fn_pgrst_reload')
          AND has_function_privilege('authenticated','public.fn_pgrst_reload()','execute')
         THEN '✅ PASS'
         ELSE '❌ FAIL: fn_pgrst_reload missing or no auth execute' END;

END;
$function$;

NOTIFY pgrst, 'reload schema';
;

-- <<< END 20260623190004_smoke_tests_expand_anon_head_rls_coverage.sql <<<

-- >>> BEGIN 20260623190039_fn_anon_access_audit_diagnostic.sql >>>

-- ============================================================
-- MELHORIA 5/7: fn_anon_access_audit() — diagnóstico permanente
-- Detecta proativamente:
--   A) Tabelas com grants anon mas sem RLS policy → 0 rows silencioso
--   B) Funções em policies PUBLIC sem EXECUTE para anon → HTTP 500
--   C) Views sensíveis acessíveis por anon → data leak
--   D) Tabelas que deveriam ter anon SELECT mas não têm → HTTP 403
-- Usar: SELECT * FROM fn_anon_access_audit();
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_anon_access_audit()
RETURNS TABLE(
  categoria    text,
  objeto       text,
  anon_grant   boolean,
  auth_grant   boolean,
  severidade   text,
  descricao    text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN

  -- A: Tabelas com GRANT SELECT para anon MAS sem nenhuma RLS policy
  -- → anon tem grant mas recebe 0 rows silencioso (pode ser bug)
  RETURN QUERY
  SELECT 
    'RLS_SEM_POLICY'::text AS categoria,
    c.relname::text AS objeto,
    has_table_privilege('anon', c.oid, 'SELECT') AS anon_grant,
    has_table_privilege('authenticated', c.oid, 'SELECT') AS auth_grant,
    CASE WHEN has_table_privilege('anon', c.oid, 'SELECT') 
              OR has_table_privilege('authenticated', c.oid, 'SELECT')
         THEN 'HIGH'::text ELSE 'INFO'::text END AS severidade,
    'Tabela com RLS ativa mas sem nenhuma policy → TODOS recebem 0 rows'::text AS descricao
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'r'
    AND c.relrowsecurity = true
    AND NOT EXISTS (
      SELECT 1 FROM pg_policies p 
      WHERE p.tablename = c.relname AND p.schemaname = 'public'
    )
    AND c.relname NOT LIKE '%_p2026_%'
    AND c.relname NOT LIKE '_bkp_%'
    AND c.relname NOT LIKE '_backup_%'
  ORDER BY c.relname;

  -- B: Funções em policies PUBLIC sem EXECUTE para anon → HTTP 500
  RETURN QUERY
  SELECT
    'FUNC_SEM_EXECUTE_ANON'::text,
    p.proname || '(' || pg_get_function_identity_arguments(p.oid) || ')'::text,
    has_function_privilege('anon', p.oid, 'execute'),
    has_function_privilege('authenticated', p.oid, 'execute'),
    'CRITICAL'::text,
    'Função chamada em policy FOR PUBLIC mas anon não tem EXECUTE → HTTP 500'::text
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
    AND NOT has_function_privilege('anon', p.oid, 'execute')
    AND has_function_privilege('authenticated', p.oid, 'execute')
    AND EXISTS (
      SELECT 1 FROM pg_policies pol
      WHERE pol.schemaname = 'public'
        AND (pol.roles @> ARRAY['public']::name[] OR pol.roles = '{}')
        AND (pol.qual || ' ' || coalesce(pol.with_check, ''))
            ILIKE '%' || p.proname || '%'
    )
  ORDER BY p.proname;

  -- C: Views sensíveis com acesso anon
  RETURN QUERY
  SELECT
    'VIEW_SENSIVEL_ANON'::text,
    c.relname::text,
    has_table_privilege('anon', c.oid, 'SELECT'),
    has_table_privilege('authenticated', c.oid, 'SELECT'),
    'HIGH'::text,
    'View interna acessível por anon — potencial data leak'::text
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('v', 'm')
    AND has_table_privilege('anon', c.oid, 'SELECT')
    AND c.relname IN (
      'bi_quotes_summary', 'ai_insights_cache',
      'v_monthly_costs', 'v_my_markup_config',
      'v_quote_seller_kpis', 'v_db_health_audit',
      'v_performance_dashboard', 'v_system_alerts',
      'v_system_health_dashboard', 'mv_product_images_audit',
      'v_slow_queries_analysis', 'v_system_health_dashboard'
    )
  ORDER BY c.relname;

  -- D: Tabelas críticas de badge sem GRANT SELECT para anon
  -- → provoca HTTP 403 quando useCloudStatus roda antes do JWT
  RETURN QUERY
  SELECT
    'BADGE_TABLE_SEM_ANON_GRANT'::text,
    t.tabela::text,
    has_table_privilege('anon', ('public.' || t.tabela)::regclass, 'SELECT'),
    has_table_privilege('authenticated', ('public.' || t.tabela)::regclass, 'SELECT'),
    'HIGH'::text,
    'Tabela usada em badge/count sem GRANT SELECT para anon → HTTP 403 no mount'::text
  FROM (VALUES
    ('discount_approval_requests'),
    ('workspace_notifications'),
    ('orders'),
    ('quotes'),
    ('search_analytics'),
    ('product_views')
  ) AS t(tabela)
  WHERE NOT has_table_privilege('anon', ('public.' || t.tabela)::regclass, 'SELECT')
  ORDER BY t.tabela;

END;
$$;

COMMENT ON FUNCTION public.fn_anon_access_audit() IS
  'Auditoria de acesso anon: detecta grants faltando, funções sem EXECUTE, '
  'views sensíveis expostas, tabelas de badge sem policy. '
  'Rodar após qualquer migração de schema ou adição de tabela nova.';

GRANT EXECUTE ON FUNCTION public.fn_anon_access_audit() TO authenticated;
;

-- <<< END 20260623190039_fn_anon_access_audit_diagnostic.sql <<<

-- >>> BEGIN 20260623190337_fix_can_view_all_sales_security_bug_and_grant_execute_anon.sql >>>

-- ============================================================
-- MELHORIA 5b: Fix bug de segurança + GRANT EXECUTE funções
-- BUG: can_view_all_sales() retornava TRUE para anon
--      por causa de `auth.uid() IS NULL` sem guard
-- RISCO: se alguma policy pública usar essa função,
--        anon poderia ver TODOS os dados de vendas
-- FIX: exigir UID não-nulo (autenticado) antes de checar roles
-- ============================================================

-- FIX: can_view_all_sales() — guard contra anon
CREATE OR REPLACE FUNCTION public.can_view_all_sales()
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path TO 'public'
AS $function$
  -- SEGURANÇA: auth.uid() deve ser NOT NULL (usuário autenticado)
  -- Antes: auth.uid() IS NULL retornava TRUE para anon (bug!)
  SELECT auth.uid() IS NOT NULL AND (
    public.has_role(auth.uid(), 'admin'::app_role)
    OR public.has_role(auth.uid(), 'manager'::app_role)
    OR public.has_role(auth.uid(), 'supervisor'::app_role)
    OR public.has_role(auth.uid(), 'dev'::app_role)
  );
$function$;

-- GRANT EXECUTE para anon em todas as funções SECURITY INVOKER
-- que aparecem em policies com roles={} (aplica a todos)
-- Todas retornam false para anon (auth.uid()=null ou input null)
GRANT EXECUTE ON FUNCTION public.can_view_all_sales()                TO anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, app_role)            TO anon;
GRANT EXECUTE ON FUNCTION public.is_admin()                          TO anon;
GRANT EXECUTE ON FUNCTION public.is_admin(uuid)                      TO anon;
GRANT EXECUTE ON FUNCTION public.is_admin_strict(uuid)               TO anon;
GRANT EXECUTE ON FUNCTION public.is_dev(uuid)                        TO anon;
GRANT EXECUTE ON FUNCTION public.is_kit_collaborator(uuid, uuid)     TO anon;
GRANT EXECUTE ON FUNCTION public.is_kit_owner(uuid, uuid)            TO anon;
GRANT EXECUTE ON FUNCTION public.is_supervisor_or_above(uuid)        TO anon;
GRANT EXECUTE ON FUNCTION public.user_belongs_to_org(uuid)           TO anon;

NOTIFY pgrst, 'reload schema';
;

