-- >>> BEGIN 20260624135450_kit_silver_item_color_path.sql >>>
-- ============================================================
-- MELHORIA 1: Caminho estrutural da COR de item (prata → gold)
-- Atômico: coluna na prata + wiring em standardize e promote
-- ============================================================

-- 1) Coluna de cor do ITEM na PRATA (espelha o contrato da gold: varchar(50))
ALTER TABLE public.kit_component_padronizacao
  ADD COLUMN IF NOT EXISTS color VARCHAR(50);

COMMENT ON COLUMN public.kit_component_padronizacao.color IS
  'Cor do ITEM (distinta de pkg_color, que é da embalagem). Free-text padronizável. '
  'Alimenta product_kit_components.color via fn_promote_kit_component_padronizacao. NULL = desconhecida.';

-- 2) BRONZE → PRATA: extrair cor do raw_data (preserva search_path e demais lógicas)
CREATE OR REPLACE FUNCTION public.fn_standardize_kit_component(p_raw_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_raw          kit_component_enrichment_raw%ROWTYPE;
  v_pad_id       UUID;
  v_rd           JSONB;
  v_factor       NUMERIC;
  v_shape        VARCHAR(30);
  v_is_pkg       BOOLEAN;
  v_comp_type    VARCHAR(30);
  v_color        VARCHAR(50);
  v_len          INTEGER; v_wid INTEGER; v_hgt INTEGER;
  v_diam         INTEGER; v_wgt INTEGER;
BEGIN
  SELECT * INTO v_raw FROM kit_component_enrichment_raw WHERE id = p_raw_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'kit_component_enrichment_raw % não encontrado', p_raw_id;
  END IF;
  IF v_raw.processed THEN
    RETURN v_raw.promoted_padronizacao_id;
  END IF;

  v_rd     := v_raw.raw_data;
  v_factor := CASE WHEN (v_rd->>'unit') = 'cm' THEN 10 ELSE 1 END;

  v_len  := NULLIF(ROUND(v_factor * COALESCE(
    (v_rd->>'length_mm')::NUMERIC,(v_rd->>'length')::NUMERIC,
    (v_rd->>'profundidade_mm')::NUMERIC,(v_rd->>'profundidade')::NUMERIC,
    (v_rd->>'comprimento_mm')::NUMERIC,(v_rd->>'comprimento')::NUMERIC)), 0)::INTEGER;
  v_wid  := NULLIF(ROUND(v_factor * COALESCE(
    (v_rd->>'width_mm')::NUMERIC,(v_rd->>'width')::NUMERIC,
    (v_rd->>'largura_mm')::NUMERIC,(v_rd->>'largura')::NUMERIC)), 0)::INTEGER;
  v_hgt  := NULLIF(ROUND(v_factor * COALESCE(
    (v_rd->>'height_mm')::NUMERIC,(v_rd->>'height')::NUMERIC,
    (v_rd->>'altura_mm')::NUMERIC,(v_rd->>'altura')::NUMERIC)), 0)::INTEGER;
  v_diam := NULLIF(ROUND(v_factor * COALESCE(
    (v_rd->>'diameter_mm')::NUMERIC,(v_rd->>'diameter')::NUMERIC,
    (v_rd->>'diametro_mm')::NUMERIC,(v_rd->>'diametro')::NUMERIC)), 0)::INTEGER;
  v_wgt  := NULLIF(COALESCE(
    (v_rd->>'weight_g')::NUMERIC,(v_rd->>'peso_g')::NUMERIC,
    (v_rd->>'peso')::NUMERIC), 0)::INTEGER;

  -- NOVO: cor do item (EN/PT, trim, vazio→NULL, truncado a 50)
  v_color := LEFT(NULLIF(TRIM(COALESCE(
    v_rd->>'color', v_rd->>'cor', v_rd->>'colour', v_rd->>'cor_item')),''),50);

  v_comp_type := LEFT(COALESCE(v_rd->>'component_type_code', v_raw.raw_component_type), 30);

  -- REGRA SHAPE (v2: têxteis planos classificados como 'flat')
  v_shape := CASE
    WHEN v_diam IS NOT NULL                                          THEN 'cylindrical'
    WHEN v_comp_type IN ('AVENTAL','TOALHA','FAIXA_ELASTICA',
                         'MASCARA_DORMIR','CAPA_CHUVA','ALMOFADA',
                         'LUVA','MOUSE_PAD')                        THEN 'flat'
    WHEN v_comp_type IN ('BOLSA','MOCHILA','SACOLA','ECOBAG',
                         'NECESSAIRE','BOLSA_TERMICA')               THEN 'irregular'
    WHEN v_hgt IS NOT NULL AND v_hgt < 10                            THEN 'flat'
    ELSE 'rectangular'
  END;

  v_is_pkg := COALESCE(
    (v_rd->>'is_packaging')::BOOLEAN,
    v_comp_type IN ('CAIXA','ESTOJO_NYLON','NECESSAIRE','MOCHILA','BOLSA_PRESENTE',
                    'ESTOJO_ALUMINIO','ESTOJO_BAMBU','ESTOJO_PU','ESTOJO',
                    'ESTOJO_COURO','ESTOJO_MADEIRA','ESTOJO_KRAFT','ESTOJO_CORTICA',
                    'ESTOJO_TNT','CAIXA_XADREZ')
  );

  INSERT INTO kit_component_padronizacao (
    kit_product_id, kit_component_id, raw_id,
    component_name, component_type_code, color, shape_type,
    length_mm, width_mm, height_mm, diameter_mm, weight_g,
    is_packaging,
    pkg_ext_length_mm, pkg_ext_width_mm, pkg_ext_height_mm,
    pkg_int_length_mm, pkg_int_width_mm, pkg_int_height_mm,
    pkg_int_diameter_mm, pkg_weight_g,
    pkg_material, pkg_color, pkg_finish, pkg_type_code,
    allows_personalization, quantity,
    enrichment_source, enrichment_confidence,
    padronizacao_status, notes
  ) VALUES (
    v_raw.kit_product_id, v_raw.kit_component_id, p_raw_id,
    COALESCE(v_rd->>'component_name', v_raw.raw_component_name, 'Componente sem nome'),
    v_comp_type, v_color, v_shape,
    v_len, v_wid, v_hgt, v_diam, v_wgt,
    v_is_pkg,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_ext_length_mm')::NUMERIC),0)::INTEGER END,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_ext_width_mm')::NUMERIC),0)::INTEGER  END,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_ext_height_mm')::NUMERIC),0)::INTEGER END,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_int_length_mm')::NUMERIC),0)::INTEGER END,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_int_width_mm')::NUMERIC),0)::INTEGER  END,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_int_height_mm')::NUMERIC),0)::INTEGER END,
    CASE WHEN v_is_pkg THEN NULLIF(ROUND(v_factor*(v_rd->>'pkg_int_diameter_mm')::NUMERIC),0)::INTEGER END,
    CASE WHEN v_is_pkg THEN NULLIF((v_rd->>'pkg_weight_g')::INTEGER,0) END,
    CASE WHEN v_is_pkg THEN v_rd->>'pkg_material' END,
    CASE WHEN v_is_pkg THEN v_rd->>'pkg_color' END,
    CASE WHEN v_is_pkg THEN v_rd->>'pkg_finish' END,
    CASE WHEN v_is_pkg THEN LEFT(v_comp_type,30) END,
    COALESCE((v_rd->>'allows_personalization')::BOOLEAN, TRUE),
    COALESCE((v_rd->>'quantity')::INTEGER, 1),
    v_raw.source::VARCHAR(50), v_raw.source_confidence,
    'pending', v_rd->>'notes'
  )
  RETURNING id INTO v_pad_id;

  UPDATE kit_component_enrichment_raw
  SET processed = TRUE, processed_at = NOW(),
      promoted_padronizacao_id = v_pad_id, updated_at = NOW()
  WHERE id = p_raw_id;

  RETURN v_pad_id;
EXCEPTION WHEN OTHERS THEN
  UPDATE kit_component_enrichment_raw
  SET process_errors = jsonb_build_object('error', SQLERRM, 'at', NOW()), updated_at = NOW()
  WHERE id = p_raw_id;
  RAISE;
END;
$function$;

-- 3) PRATA → GOLD: propagar color (UPDATE e INSERT)
CREATE OR REPLACE FUNCTION public.fn_promote_kit_component_padronizacao(p_pad_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pad     kit_component_padronizacao%ROWTYPE;
  v_comp_id UUID;
BEGIN
  SELECT * INTO v_pad
  FROM kit_component_padronizacao
  WHERE id = p_pad_id AND padronizacao_status = 'approved';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'kit_component_padronizacao % não encontrada ou não está approved', p_pad_id;
  END IF;

  IF v_pad.kit_component_id IS NOT NULL THEN
    UPDATE product_kit_components SET
      shape_type            = COALESCE(v_pad.shape_type,        shape_type),
      weight_g              = COALESCE(v_pad.weight_g,          weight_g),
      length_mm             = COALESCE(v_pad.length_mm,         length_mm),
      width_mm              = COALESCE(v_pad.width_mm,          width_mm),
      height_mm             = COALESCE(v_pad.height_mm,         height_mm),
      diameter_mm           = COALESCE(v_pad.diameter_mm,       diameter_mm),
      circumference_mm      = COALESCE(v_pad.circumference_mm,  circumference_mm),
      pkg_ext_length_mm     = CASE WHEN v_pad.is_packaging
                                THEN COALESCE(v_pad.pkg_ext_length_mm, pkg_ext_length_mm)
                                ELSE pkg_ext_length_mm END,
      pkg_ext_width_mm      = CASE WHEN v_pad.is_packaging
                                THEN COALESCE(v_pad.pkg_ext_width_mm,  pkg_ext_width_mm)
                                ELSE pkg_ext_width_mm END,
      pkg_ext_height_mm     = CASE WHEN v_pad.is_packaging
                                THEN COALESCE(v_pad.pkg_ext_height_mm, pkg_ext_height_mm)
                                ELSE pkg_ext_height_mm END,
      pkg_int_length_mm     = CASE WHEN v_pad.is_packaging
                                THEN COALESCE(v_pad.pkg_int_length_mm, pkg_int_length_mm)
                                ELSE pkg_int_length_mm END,
      pkg_int_width_mm      = CASE WHEN v_pad.is_packaging
                                THEN COALESCE(v_pad.pkg_int_width_mm,  pkg_int_width_mm)
                                ELSE pkg_int_width_mm END,
      pkg_int_height_mm     = CASE WHEN v_pad.is_packaging
                                THEN COALESCE(v_pad.pkg_int_height_mm, pkg_int_height_mm)
                                ELSE pkg_int_height_mm END,
      pkg_int_diameter_mm   = CASE WHEN v_pad.is_packaging
                                THEN COALESCE(v_pad.pkg_int_diameter_mm, pkg_int_diameter_mm)
                                ELSE pkg_int_diameter_mm END,
      pkg_weight_g          = CASE WHEN v_pad.is_packaging
                                THEN COALESCE(v_pad.pkg_weight_g, pkg_weight_g)
                                ELSE pkg_weight_g END,
      pkg_material          = CASE WHEN v_pad.is_packaging
                                THEN COALESCE(v_pad.pkg_material, pkg_material)
                                ELSE pkg_material END,
      pkg_color             = CASE WHEN v_pad.is_packaging
                                THEN COALESCE(v_pad.pkg_color, pkg_color)
                                ELSE pkg_color END,
      pkg_finish            = CASE WHEN v_pad.is_packaging
                                THEN COALESCE(v_pad.pkg_finish, pkg_finish)
                                ELSE pkg_finish END,
      -- NOVO: cor do item (sempre carregada, NULL-safe)
      color                 = COALESCE(v_pad.color, color),
      component_product_id  = COALESCE(v_pad.component_product_id, component_product_id),
      component_type_code   = COALESCE(v_pad.component_type_code,  component_type_code),
      material_type_id      = COALESCE(v_pad.material_type_id,     material_type_id),
      enrichment_source     = v_pad.enrichment_source,
      enrichment_confidence = v_pad.enrichment_confidence,
      padronizacao_id       = p_pad_id,
      updated_at            = NOW()
    WHERE id = v_pad.kit_component_id
    RETURNING id INTO v_comp_id;

  ELSE
    INSERT INTO product_kit_components (
      kit_product_id, component_name, component_type_code, color,
      material_type_id, secondary_material_type_id, component_product_id,
      quantity, is_optional, is_packaging, allows_personalization,
      shape_type, weight_g, length_mm, width_mm, height_mm,
      diameter_mm, circumference_mm,
      pkg_ext_length_mm, pkg_ext_width_mm, pkg_ext_height_mm,
      pkg_int_length_mm, pkg_int_width_mm, pkg_int_height_mm,
      pkg_int_diameter_mm, pkg_weight_g,
      pkg_material, pkg_color, pkg_finish,
      enrichment_source, enrichment_confidence, padronizacao_id
    ) VALUES (
      v_pad.kit_product_id, v_pad.component_name, v_pad.component_type_code, v_pad.color,
      v_pad.material_type_id, v_pad.secondary_material_type_id, v_pad.component_product_id,
      COALESCE(v_pad.quantity, 1), FALSE, v_pad.is_packaging,
      COALESCE(v_pad.allows_personalization, TRUE),
      v_pad.shape_type, v_pad.weight_g, v_pad.length_mm, v_pad.width_mm, v_pad.height_mm,
      v_pad.diameter_mm, v_pad.circumference_mm,
      v_pad.pkg_ext_length_mm, v_pad.pkg_ext_width_mm, v_pad.pkg_ext_height_mm,
      v_pad.pkg_int_length_mm, v_pad.pkg_int_width_mm, v_pad.pkg_int_height_mm,
      v_pad.pkg_int_diameter_mm, v_pad.pkg_weight_g,
      v_pad.pkg_material, v_pad.pkg_color, v_pad.pkg_finish,
      v_pad.enrichment_source, v_pad.enrichment_confidence, p_pad_id
    )
    RETURNING id INTO v_comp_id;
  END IF;

  UPDATE kit_component_padronizacao
  SET padronizacao_status = 'promoted',
      kit_component_id    = v_comp_id,
      updated_at          = NOW()
  WHERE id = p_pad_id;

  UPDATE kit_component_enrichment_raw
  SET promoted_component_id = v_comp_id, updated_at = NOW()
  WHERE id = v_pad.raw_id;

  RETURN v_comp_id;
END;
$function$;;

-- <<< END 20260624135450_kit_silver_item_color_path.sql <<<

-- >>> BEGIN 20260624135644_kit_backfill_pkg_material_from_item.sql >>>
-- ============================================================
-- MELHORIA 2: pkg_material a partir do material de item deslocado
-- Aditivo (só NULL→valor), reversível via tabela de backup, rerun-safe
-- ============================================================

-- Backup do estado anterior (captura só na 1ª execução)
CREATE TABLE IF NOT EXISTS public._bkp_kit_pkg_material_20260624 AS
SELECT id,
       pkg_material AS old_pkg_material,
       material     AS source_material,
       now()        AS captured_at
FROM product_kit_components
WHERE is_packaging
  AND NULLIF(TRIM(material),'') IS NOT NULL
  AND pkg_material IS NULL;

COMMENT ON TABLE public._bkp_kit_pkg_material_20260624 IS
  'Backup MELHORIA 2 (2026-06-24): estado anterior de pkg_material antes do backfill a partir de material de item em linhas is_packaging. Reversão: UPDATE product_kit_components p SET pkg_material=b.old_pkg_material FROM _bkp_kit_pkg_material_20260624 b WHERE p.id=b.id.';

-- Backfill aditivo
UPDATE product_kit_components
SET pkg_material = TRIM(material),
    updated_at   = now()
WHERE is_packaging
  AND NULLIF(TRIM(material),'') IS NOT NULL
  AND pkg_material IS NULL;;

-- <<< END 20260624135644_kit_backfill_pkg_material_from_item.sql <<<

-- >>> BEGIN 20260624140204_kit_color_from_component_name.sql >>>
-- ============================================================
-- MELHORIA 5: cor do ITEM derivada do NOME (provável), "vinho" excluído
-- Backup + audit; aditivo (só color IS NULL); rerun-safe
-- ============================================================

-- Backup/auditoria (captura id, cor antiga, nome e palavra detectada)
CREATE TABLE IF NOT EXISTS public._bkp_kit_color_from_name_20260624 AS
SELECT k.id,
       k.color AS old_color,
       k.component_name,
       (regexp_match(lower(k.component_name),
         '\m(preto|preta|branco|branca|vermelho|vermelha|azul|verde|amarelo|amarela|rosa|roxo|roxa|laranja|marrom|cinza|prata|prateado|prateada|dourado|dourada|bege|turquesa|lilas|coral|nude|caramelo|grafite|chumbo|creme|transparente|incolor|inox|cobre|bronze)\M'))[1] AS matched_word,
       now() AS captured_at
FROM product_kit_components k
WHERE k.color IS NULL
  AND lower(k.component_name) ~
   '\m(preto|preta|branco|branca|vermelho|vermelha|azul|verde|amarelo|amarela|rosa|roxo|roxa|laranja|marrom|cinza|prata|prateado|prateada|dourado|dourada|bege|turquesa|lilas|coral|nude|caramelo|grafite|chumbo|creme|transparente|incolor|inox|cobre|bronze)\M';

COMMENT ON TABLE public._bkp_kit_color_from_name_20260624 IS
  'Backup/audit MELHORIA 5 (2026-06-24): cor de item derivada do nome do componente. Reversão: UPDATE product_kit_components p SET color=b.old_color FROM _bkp_kit_color_from_name_20260624 b WHERE p.id=b.id.';

-- Extração com normalização canônica
UPDATE product_kit_components k
SET color = CASE (regexp_match(lower(k.component_name),
        '\m(preto|preta|branco|branca|vermelho|vermelha|azul|verde|amarelo|amarela|rosa|roxo|roxa|laranja|marrom|cinza|prata|prateado|prateada|dourado|dourada|bege|turquesa|lilas|coral|nude|caramelo|grafite|chumbo|creme|transparente|incolor|inox|cobre|bronze)\M'))[1]
      WHEN 'preto' THEN 'Preto'        WHEN 'preta' THEN 'Preto'
      WHEN 'branco' THEN 'Branco'      WHEN 'branca' THEN 'Branco'
      WHEN 'vermelho' THEN 'Vermelho'  WHEN 'vermelha' THEN 'Vermelho'
      WHEN 'azul' THEN 'Azul'
      WHEN 'verde' THEN 'Verde'
      WHEN 'amarelo' THEN 'Amarelo'    WHEN 'amarela' THEN 'Amarelo'
      WHEN 'rosa' THEN 'Rosa'
      WHEN 'roxo' THEN 'Roxo'          WHEN 'roxa' THEN 'Roxo'
      WHEN 'laranja' THEN 'Laranja'
      WHEN 'marrom' THEN 'Marrom'
      WHEN 'cinza' THEN 'Cinza'
      WHEN 'prata' THEN 'Prata'        WHEN 'prateado' THEN 'Prata'  WHEN 'prateada' THEN 'Prata'
      WHEN 'dourado' THEN 'Dourado'    WHEN 'dourada' THEN 'Dourado'
      WHEN 'bege' THEN 'Bege'
      WHEN 'turquesa' THEN 'Turquesa'
      WHEN 'lilas' THEN 'Lilás'
      WHEN 'coral' THEN 'Coral'
      WHEN 'nude' THEN 'Nude'
      WHEN 'caramelo' THEN 'Caramelo'
      WHEN 'grafite' THEN 'Grafite'
      WHEN 'chumbo' THEN 'Chumbo'
      WHEN 'creme' THEN 'Creme'
      WHEN 'transparente' THEN 'Transparente'
      WHEN 'incolor' THEN 'Incolor'
      WHEN 'inox' THEN 'Inox'
      WHEN 'cobre' THEN 'Cobre'
      WHEN 'bronze' THEN 'Bronze'
      ELSE initcap((regexp_match(lower(k.component_name),
        '\m(preto|preta|branco|branca|vermelho|vermelha|azul|verde|amarelo|amarela|rosa|roxo|roxa|laranja|marrom|cinza|prata|prateado|prateada|dourado|dourada|bege|turquesa|lilas|coral|nude|caramelo|grafite|chumbo|creme|transparente|incolor|inox|cobre|bronze)\M'))[1])
    END,
    updated_at = now()
WHERE k.color IS NULL
  AND lower(k.component_name) ~
   '\m(preto|preta|branco|branca|vermelho|vermelha|azul|verde|amarelo|amarela|rosa|roxo|roxa|laranja|marrom|cinza|prata|prateado|prateada|dourado|dourada|bege|turquesa|lilas|coral|nude|caramelo|grafite|chumbo|creme|transparente|incolor|inox|cobre|bronze)\M';;

-- <<< END 20260624140204_kit_color_from_component_name.sql <<<

-- >>> BEGIN 20260624140703_kit_honest_completeness_views.sql >>>
-- ============================================================
-- MELHORIA 7: sinal de completude HONESTO (aditivo, não-destrutivo)
-- Não altera enrichment_status (blast radius); adiciona verdade ao lado
-- ============================================================

-- View por componente: flags multi-dimensão + completude verídica
CREATE OR REPLACE VIEW public.v_kit_component_completeness AS
SELECT s.*,
  CASE WHEN s.completude_pct = 100 THEN 'complete'
       WHEN s.completude_pct >= 50  THEN 'partial'
       ELSE 'minimal' END AS true_status
FROM (
  SELECT
    f.component_id, f.kit_product_id, f.component_name, f.component_type_code, f.is_packaging,
    f.has_type, f.has_weight, f.has_dims, f.has_color, f.has_image,
    f.has_pkg_dims, f.has_pkg_material,
    (f.has_pkg_dims AND f.has_pkg_material) AS has_pkg_info,
    CASE WHEN f.is_packaging
         THEN (f.has_type::int + f.has_pkg_dims::int + f.has_pkg_material::int)
         ELSE (f.has_type::int + f.has_weight::int + f.has_dims::int + f.has_color::int + f.has_image::int)
    END AS dims_satisfeitas,
    CASE WHEN f.is_packaging THEN 3 ELSE 5 END AS dims_aplicaveis,
    CASE WHEN f.is_packaging
         THEN round(100.0*(f.has_type::int + f.has_pkg_dims::int + f.has_pkg_material::int)/3.0)::int
         ELSE round(100.0*(f.has_type::int + f.has_weight::int + f.has_dims::int + f.has_color::int + f.has_image::int)/5.0)::int
    END AS completude_pct,
    f.enrichment_status
  FROM (
    SELECT
      pkc.id AS component_id, pkc.kit_product_id, pkc.component_name,
      pkc.component_type_code, pkc.is_packaging,
      (pkc.component_type_code IS NOT NULL) AS has_type,
      (pkc.weight_g IS NOT NULL) AS has_weight,
      (CASE WHEN pkc.shape_type='cylindrical' THEN pkc.diameter_mm IS NOT NULL
            ELSE (pkc.length_mm IS NOT NULL AND pkc.width_mm IS NOT NULL) END) AS has_dims,
      (pkc.color IS NOT NULL) AS has_color,
      (pkc.primary_image_url IS NOT NULL) AS has_image,
      (COALESCE(pkc.pkg_ext_length_mm,pkc.pkg_ext_width_mm,pkc.pkg_ext_height_mm) IS NOT NULL) AS has_pkg_dims,
      (pkc.pkg_material IS NOT NULL) AS has_pkg_material,
      pkc.enrichment_status
    FROM public.product_kit_components pkc
  ) f
) s;

COMMENT ON VIEW public.v_kit_component_completeness IS
  'Completude VERÍDICA por componente (M7/2026-06-24). Itens pontuam em 5 dimensões (tipo, peso, medidas, cor, imagem); embalagens em 3 (tipo, dims externas, material). completude_pct/true_status refletem TODOS os requisitos do negócio — ao contrário de enrichment_status, que só mede dimensão física.';

-- Rollup verídico por fornecedor (espelha o dashboard antigo, porém honesto)
CREATE OR REPLACE VIEW public.v_kit_completeness_by_supplier AS
SELECT
  sup.name AS supplier_name,
  sup.code AS supplier_code,
  count(*) AS total_components,
  count(*) FILTER (WHERE c.true_status='complete') AS truly_complete,
  round(100.0*count(*) FILTER (WHERE c.true_status='complete')/count(*),1) AS pct_truly_complete,
  round(avg(c.completude_pct),1) AS avg_completude_pct,
  round(100.0*count(*) FILTER (WHERE c.has_color)/count(*),1)  AS pct_com_cor,
  round(100.0*count(*) FILTER (WHERE c.has_image)/count(*),1)  AS pct_com_imagem,
  round(100.0*count(*) FILTER (WHERE c.has_dims)/count(*),1)   AS pct_com_dims,
  round(100.0*count(*) FILTER (WHERE c.has_weight)/count(*),1) AS pct_com_peso,
  round(100.0*count(*) FILTER (WHERE c.is_packaging AND c.has_pkg_info)
        /NULLIF(count(*) FILTER (WHERE c.is_packaging),0),1)   AS pct_emb_completa
FROM public.v_kit_component_completeness c
JOIN public.products  p   ON p.id = c.kit_product_id
JOIN public.suppliers sup ON sup.id = p.supplier_id
GROUP BY sup.name, sup.code
ORDER BY pct_truly_complete DESC;

COMMENT ON VIEW public.v_kit_completeness_by_supplier IS
  'Rollup de completude VERÍDICA por fornecedor (M7/2026-06-24). Use em vez de v_kit_enrichment_dashboard quando precisar da verdade incluindo cor/imagem.';

-- Corrige o COMMENT enganoso da coluna que sustentava a "mentira do 100%"
COMMENT ON COLUMN public.product_kit_components.enrichment_status IS
  'ATENÇÃO: mede APENAS completude de dimensão física (peso/medidas), NÃO inclui cor nem imagem. '
  'Para completude verídica multi-dimensional, use v_kit_component_completeness (true_status / completude_pct).';

-- PostgREST: recarrega cache de schema para expor as novas views
NOTIFY pgrst, 'reload schema';;

-- <<< END 20260624140703_kit_honest_completeness_views.sql <<<

-- >>> BEGIN 20260624141116_kit_packing_type_backup_precomputed.sql >>>
CREATE TABLE IF NOT EXISTS public._bkp_kit_packing_type_20260624 AS
WITH derive AS (
  SELECT DISTINCT ON (k.kit_product_id) k.kit_product_id,
    CASE
      WHEN k.component_type_code IN ('CAIXA','CAIXA_XADREZ') THEN 'Caixa'
      WHEN k.component_type_code LIKE 'ESTOJO%' THEN 'Estojo'
      WHEN k.component_type_code='NECESSAIRE' THEN 'Necessaire'
      WHEN k.component_type_code='MOCHILA' THEN 'Mochila'
      WHEN k.component_type_code='BOLSA_TERMICA' THEN 'Bolsa Térmica'
      WHEN k.component_type_code='ECOBAG' THEN 'Ecobag'
      WHEN k.component_type_code='SACOLA' THEN 'Sacola'
      WHEN k.component_type_code='BANDEJA' THEN 'Bandeja'
      ELSE initcap(replace(lower(k.component_type_code),'_',' '))
    END AS dp
  FROM product_kit_components k JOIN products p ON p.id=k.kit_product_id
  WHERE p.is_kit AND NULLIF(TRIM(p.packing_type),'') IS NULL
    AND k.is_packaging AND k.component_type_code IS NOT NULL
    AND NOT ('packing_type' = ANY(COALESCE(p.locked_fields,'{}')))
  ORDER BY k.kit_product_id,
    CASE WHEN k.component_type_code LIKE 'ESTOJO%' OR k.component_type_code IN ('CAIXA','CAIXA_XADREZ') THEN 0 ELSE 1 END,
    k.component_type_code
)
SELECT p.id, p.packing_type AS old_packing_type, d.dp AS new_packing_type, now() AS captured_at
FROM derive d JOIN products p ON p.id=d.kit_product_id;

COMMENT ON TABLE public._bkp_kit_packing_type_20260624 IS
  'Backup MELHORIA 8 (2026-06-24): packing_type antes/depois (derivado do componente-embalagem). Reversão: UPDATE products p SET packing_type=b.old_packing_type FROM _bkp_kit_packing_type_20260624 b WHERE p.id=b.id.';;

-- <<< END 20260624141116_kit_packing_type_backup_precomputed.sql <<<

-- >>> BEGIN 20260624144301_kit_component_canonical_color_id.sql >>>
-- ============================================================
-- AMPLIAR codificação de cor às KITS/COMPONENTES (espelha variações)
-- color_id FK -> color_variations; backfill resolvido por NOME canônico
-- Aditivo, rerun-safe
-- ============================================================
ALTER TABLE public.product_kit_components
  ADD COLUMN IF NOT EXISTS color_id uuid REFERENCES public.color_variations(id);

COMMENT ON COLUMN public.product_kit_components.color_id IS
  'Cor do ITEM normalizada (FK color_variations) — MESMA codificação canônica das variações de produto. '
  'Resolvida do campo color (texto derivado do nome) via dicionário de equivalência. NULL = cor própria desconhecida. '
  'OBS: distinta da cor da VARIANTE do kit (essa vive em product_variants.color_id e alimenta o ref do componente).';

CREATE INDEX IF NOT EXISTS idx_pkc_color_id ON public.product_kit_components(color_id);

WITH mapa(txt, canonico) AS (VALUES
  ('Preto','Preto'),('Inox','Prata Inox'),('Branco','Branco'),('Azul','Azul Royal'),
  ('Verde','Verde Bandeira'),('Vermelho','Vermelho Ferrari'),('Cinza','Cinza Claro'),
  ('Prata','Prata'),('Bege','Bege Nude'),('Rosa','Rosa Bubbaloo'),('Marrom','Marrom Chocolate'),
  ('Grafite','Cinza Chumbo'),('Amarelo','Amarelo Ouro'),('Transparente','Transparente')
)
UPDATE public.product_kit_components k
SET color_id = cv.id, updated_at = now()
FROM mapa m
JOIN public.color_variations cv ON cv.name = m.canonico
WHERE k.color = m.txt AND k.color_id IS NULL;;

-- <<< END 20260624144301_kit_component_canonical_color_id.sql <<<

-- >>> BEGIN 20260624145739_kit_component_slot_and_sku.sql >>>
-- ============================================================
-- Identidade do componente: slot + código com CÓDIGO DA COR
-- Código qualificado = SKU da variante + slot  ->  18891A-PRE-K1
-- (usa o SKU da variante: limpo e idêntico ao que já roda nas variações)
-- ============================================================

-- 1) coluna de slot
ALTER TABLE public.product_kit_components
  ADD COLUMN IF NOT EXISTS slot_code varchar(6);

ALTER TABLE public.product_kit_components
  DROP CONSTRAINT IF EXISTS chk_pkc_slot_fmt;
ALTER TABLE public.product_kit_components
  ADD CONSTRAINT chk_pkc_slot_fmt CHECK (slot_code IS NULL OR slot_code ~ '^(K|E)[0-9]{1,3}$');

-- 2) gerar slot determinístico: itens=K{n}, embalagem=E{n}, por display_order
WITH n AS (
  SELECT id,
    (CASE WHEN is_packaging THEN 'E' ELSE 'K' END) ||
    row_number() OVER (PARTITION BY kit_product_id, is_packaging
                       ORDER BY display_order, component_type_code, id)::text AS slot
  FROM public.product_kit_components
  WHERE slot_code IS NULL
)
UPDATE public.product_kit_components c
SET slot_code = n.slot
FROM n WHERE c.id = n.id;

-- 3) código AGNÓSTICO à cor (espinha dorsal estável): PAI-SLOT  ->  18891A-K1
UPDATE public.product_kit_components c
SET component_code = p.sku || '-' || c.slot_code
FROM public.products p
WHERE p.id = c.kit_product_id
  AND c.slot_code IS NOT NULL
  AND (c.component_code IS NULL OR c.component_code <> p.sku || '-' || c.slot_code);

-- 4) VIEW com o código QUALIFICADO (com a cor): SKU_variante-SLOT -> 18891A-PRE-K1
CREATE OR REPLACE VIEW public.v_kit_component_skus AS
SELECT
  c.id                                   AS component_id,
  c.kit_product_id,
  v.id                                   AS variant_id,
  p.sku                                  AS parent_sku,
  v.sku                                  AS variant_sku,
  v.color_code                           AS variant_color_code,
  v.color_name                           AS variant_color_name,
  c.slot_code,
  c.component_name,
  c.component_type_code,
  c.is_packaging,
  c.color_id                             AS item_color_id,
  c.component_code                        AS component_code_agnostico,
  (v.sku || '-' || c.slot_code)          AS component_sku   -- ex.: 18891A-PRE-K1
FROM public.product_kit_components c
JOIN public.products p          ON p.id = c.kit_product_id
JOIN public.product_variants v  ON v.product_id = c.kit_product_id;

COMMENT ON VIEW public.v_kit_component_skus IS
  'Código qualificado de cada componente por variante: variant_sku || ''-'' || slot_code (ex.: 18891A-PRE-K1). '
  'Itens=K{n}, embalagem=E{n}. Nunca colide com SKU vendável (sufixo -K/-E tem colisão zero). '
  'BOM permanece 1 linha por componente; o código por variante é gerado aqui (sob demanda).';

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260624145739_kit_component_slot_and_sku.sql <<<

-- >>> BEGIN 20260624153343_kit_component_identity_guards.sql >>>
-- ============================================================
-- Travas de integridade da identidade de componente (Plano A)
-- ============================================================

-- Flag explícita: componente nunca é vendável avulso
ALTER TABLE public.product_kit_components
  ADD COLUMN IF NOT EXISTS is_standalone_sellable boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN public.product_kit_components.is_standalone_sellable IS
  'Sempre false: componente de kit NUNCA é vendido separadamente. Reforçado por separação de tabela + guarda anti-colisão.';

-- Unicidade do slot dentro do kit
ALTER TABLE public.product_kit_components DROP CONSTRAINT IF EXISTS uq_pkc_kit_slot;
ALTER TABLE public.product_kit_components ADD CONSTRAINT uq_pkc_kit_slot UNIQUE (kit_product_id, slot_code);

-- Unicidade global do código agnóstico (PAI-SLOT)
DROP INDEX IF EXISTS public.uq_pkc_component_code;
CREATE UNIQUE INDEX uq_pkc_component_code
  ON public.product_kit_components(component_code) WHERE component_code IS NOT NULL;

-- Coerência slot × tipo: item=K, embalagem=E
ALTER TABLE public.product_kit_components DROP CONSTRAINT IF EXISTS chk_pkc_slot_kind;
ALTER TABLE public.product_kit_components ADD CONSTRAINT chk_pkc_slot_kind CHECK (
      slot_code IS NULL
   OR (is_packaging     AND slot_code LIKE 'E%')
   OR (NOT is_packaging AND slot_code LIKE 'K%'));

-- GUARDA anti-vendável: código de componente jamais pode existir em products.sku/sku_promo
CREATE OR REPLACE FUNCTION public.fn_pkc_guard_not_sellable()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $fn$
BEGIN
  IF NEW.component_code IS NOT NULL AND EXISTS (
       SELECT 1 FROM products p WHERE p.sku = NEW.component_code OR p.sku_promo = NEW.component_code) THEN
    RAISE EXCEPTION 'component_code % colide com SKU vendável em products', NEW.component_code;
  END IF;
  IF NEW.component_sku IS NOT NULL AND EXISTS (
       SELECT 1 FROM products p WHERE p.sku = NEW.component_sku OR p.sku_promo = NEW.component_sku) THEN
    RAISE EXCEPTION 'component_sku % colide com SKU vendável em products', NEW.component_sku;
  END IF;
  RETURN NEW;
END;
$fn$;
DROP TRIGGER IF EXISTS trg_pkc_guard_not_sellable ON public.product_kit_components;
CREATE TRIGGER trg_pkc_guard_not_sellable
  BEFORE INSERT OR UPDATE OF component_code, component_sku
  ON public.product_kit_components
  FOR EACH ROW EXECUTE FUNCTION public.fn_pkc_guard_not_sellable();

-- IMUTABILIDADE do slot_code (congelado após 1ª atribuição → estável na re-ingestão)
CREATE OR REPLACE FUNCTION public.fn_pkc_freeze_slot()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $fn$
BEGIN
  IF OLD.slot_code IS NOT NULL AND NEW.slot_code IS DISTINCT FROM OLD.slot_code THEN
    RAISE EXCEPTION 'slot_code é imutável (% -> %) no componente %', OLD.slot_code, NEW.slot_code, OLD.id;
  END IF;
  RETURN NEW;
END;
$fn$;
DROP TRIGGER IF EXISTS trg_pkc_freeze_slot ON public.product_kit_components;
CREATE TRIGGER trg_pkc_freeze_slot
  BEFORE UPDATE OF slot_code
  ON public.product_kit_components
  FOR EACH ROW EXECUTE FUNCTION public.fn_pkc_freeze_slot();;

-- <<< END 20260624153343_kit_component_identity_guards.sql <<<

-- >>> BEGIN 20260624153509_kit_component_variant_skus_table.sql >>>
-- ============================================================
-- Materialização: 1 linha por (componente × variante de kit)
-- component_sku = SKU_variante-slot  (ex.: 18891A-PRE-K1)
-- Destrava asset por componente/cor (primary_image_url)
-- ============================================================
CREATE TABLE IF NOT EXISTS public.kit_component_variant_skus (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  component_id          uuid NOT NULL REFERENCES public.product_kit_components(id) ON DELETE CASCADE,
  variant_id           uuid NOT NULL REFERENCES public.product_variants(id) ON DELETE CASCADE,
  kit_product_id       uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,
  component_sku        varchar(40) NOT NULL,
  slot_code            varchar(6)  NOT NULL,
  is_packaging         boolean     NOT NULL DEFAULT false,
  variant_color_code   varchar(50),
  variant_color_name   varchar(100),
  component_name       varchar(255),
  item_color_id        uuid REFERENCES public.color_variations(id),
  primary_image_url    text,
  image_source         varchar(30),
  is_standalone_sellable boolean   NOT NULL DEFAULT false,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT uq_kcvs_sku          UNIQUE (component_sku),
  CONSTRAINT uq_kcvs_comp_variant UNIQUE (component_id, variant_id),
  CONSTRAINT chk_kcvs_slot_fmt    CHECK (slot_code ~ '^(K|E)[0-9]{1,3}$')
);

COMMENT ON TABLE public.kit_component_variant_skus IS
  'Identidade materializada de cada componente POR VARIANTE de kit. component_sku = SKU_variante-slot (ex.: 18891A-PRE-K1). '
  'Destrava asset por componente/cor (primary_image_url). Sincronizar com fn_refresh_kit_component_variant_skus().';

CREATE INDEX IF NOT EXISTS idx_kcvs_component ON public.kit_component_variant_skus(component_id);
CREATE INDEX IF NOT EXISTS idx_kcvs_variant   ON public.kit_component_variant_skus(variant_id);
CREATE INDEX IF NOT EXISTS idx_kcvs_kit       ON public.kit_component_variant_skus(kit_product_id);

-- Guarda anti-vendável também aqui
CREATE OR REPLACE FUNCTION public.fn_kcvs_guard_not_sellable()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $fn$
BEGIN
  IF EXISTS (SELECT 1 FROM products p WHERE p.sku = NEW.component_sku OR p.sku_promo = NEW.component_sku) THEN
    RAISE EXCEPTION 'component_sku % colide com SKU vendável em products', NEW.component_sku;
  END IF;
  RETURN NEW;
END;
$fn$;
DROP TRIGGER IF EXISTS trg_kcvs_guard ON public.kit_component_variant_skus;
CREATE TRIGGER trg_kcvs_guard
  BEFORE INSERT OR UPDATE OF component_sku
  ON public.kit_component_variant_skus
  FOR EACH ROW EXECUTE FUNCTION public.fn_kcvs_guard_not_sellable();

-- Sincronização idempotente (insere o que falta a partir da view)
CREATE OR REPLACE FUNCTION public.fn_refresh_kit_component_variant_skus()
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $fn$
DECLARE v_ins integer;
BEGIN
  INSERT INTO public.kit_component_variant_skus
    (component_id, variant_id, kit_product_id, component_sku, slot_code, is_packaging,
     variant_color_code, variant_color_name, component_name, item_color_id)
  SELECT s.component_id, s.variant_id, s.kit_product_id, s.component_sku, s.slot_code, s.is_packaging,
         s.variant_color_code, s.variant_color_name, s.component_name, s.item_color_id
  FROM public.v_kit_component_skus s
  ON CONFLICT (component_id, variant_id) DO NOTHING;
  GET DIAGNOSTICS v_ins = ROW_COUNT;
  RETURN v_ins;
END;
$fn$;;

-- <<< END 20260624153509_kit_component_variant_skus_table.sql <<<

-- >>> BEGIN 20260624154320_kit_component_skus_carry_image_v2.sql >>>
CREATE OR REPLACE VIEW public.v_kit_component_skus AS
SELECT
  c.id                          AS component_id,
  c.kit_product_id,
  v.id                          AS variant_id,
  p.sku                         AS parent_sku,
  v.sku                         AS variant_sku,
  v.color_code                  AS variant_color_code,
  v.color_name                  AS variant_color_name,
  c.slot_code,
  c.component_name,
  c.component_type_code,
  c.is_packaging,
  c.color_id                    AS item_color_id,
  c.component_code              AS component_code_agnostico,
  (v.sku || '-' || c.slot_code) AS component_sku,
  c.primary_image_url           AS component_image_url   -- nova coluna ao FINAL
FROM public.product_kit_components c
JOIN public.products p          ON p.id = c.kit_product_id
JOIN public.product_variants v  ON v.product_id = c.kit_product_id;

CREATE OR REPLACE FUNCTION public.fn_refresh_kit_component_variant_skus()
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $fn$
DECLARE v_ins integer;
BEGIN
  INSERT INTO public.kit_component_variant_skus
    (component_id, variant_id, kit_product_id, component_sku, slot_code, is_packaging,
     variant_color_code, variant_color_name, component_name, item_color_id,
     primary_image_url, image_source)
  SELECT s.component_id, s.variant_id, s.kit_product_id, s.component_sku, s.slot_code, s.is_packaging,
         s.variant_color_code, s.variant_color_name, s.component_name, s.item_color_id,
         s.component_image_url,
         CASE WHEN s.component_image_url IS NOT NULL THEN 'inherited_component' END
  FROM public.v_kit_component_skus s
  ON CONFLICT (component_id, variant_id) DO NOTHING;
  GET DIAGNOSTICS v_ins = ROW_COUNT;
  RETURN v_ins;
END;
$fn$;

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260624154320_kit_component_skus_carry_image_v2.sql <<<

-- >>> BEGIN 20260624154640_kit_refresh_self_healing.sql >>>
CREATE OR REPLACE FUNCTION public.fn_refresh_kit_component_variant_skus()
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $fn$
DECLARE v_ins integer; v_heal integer;
BEGIN
  -- 1) inserir novidades (novos componentes/variantes), semeando imagem/cor
  INSERT INTO public.kit_component_variant_skus
    (component_id, variant_id, kit_product_id, component_sku, slot_code, is_packaging,
     variant_color_code, variant_color_name, component_name, item_color_id,
     primary_image_url, image_source)
  SELECT s.component_id, s.variant_id, s.kit_product_id, s.component_sku, s.slot_code, s.is_packaging,
         s.variant_color_code, s.variant_color_name, s.component_name, s.item_color_id,
         s.component_image_url,
         CASE WHEN s.component_image_url IS NOT NULL THEN 'inherited_component' END
  FROM public.v_kit_component_skus s
  ON CONFLICT (component_id, variant_id) DO NOTHING;
  GET DIAGNOSTICS v_ins = ROW_COUNT;

  -- 2) auto-curar imagens que chegaram depois — SOMENTE onde está NULL (nunca sobrescreve)
  UPDATE public.kit_component_variant_skus k
  SET primary_image_url = c.primary_image_url,
      image_source      = 'inherited_component',
      updated_at        = now()
  FROM public.product_kit_components c
  WHERE c.id = k.component_id
    AND k.primary_image_url IS NULL
    AND c.primary_image_url IS NOT NULL;
  GET DIAGNOSTICS v_heal = ROW_COUNT;

  RETURN v_ins + v_heal;
END;
$fn$;
COMMENT ON FUNCTION public.fn_refresh_kit_component_variant_skus() IS
  'Sincroniza kit_component_variant_skus: (1) insere novos pares componente×variante; (2) auto-cura primary_image_url onde estiver NULL a partir do componente. Idempotente, não sobrescreve imagem já definida. Deleções cobertas por ON DELETE CASCADE.';;

-- <<< END 20260624154640_kit_refresh_self_healing.sql <<<

-- >>> BEGIN 20260624154952_kit_component_identity_health_view.sql >>>
CREATE OR REPLACE VIEW public.v_kit_component_identity_health AS
SELECT
  s.name                                                                              AS supplier,
  count(*)                                                                            AS variant_component_rows,
  count(DISTINCT k.kit_product_id)                                                    AS kits,
  count(DISTINCT k.component_id)                                                      AS components,
  count(*) FILTER (WHERE k.component_sku IS NOT NULL)                                 AS with_qualified_code,
  count(*) FILTER (WHERE k.item_color_id IS NOT NULL)                                 AS with_canonical_color,
  count(*) FILTER (WHERE k.primary_image_url IS NOT NULL)                             AS with_image,
  round(100.0*count(*) FILTER (WHERE k.item_color_id   IS NOT NULL)/NULLIF(count(*),0),1) AS pct_color,
  round(100.0*count(*) FILTER (WHERE k.primary_image_url IS NOT NULL)/NULLIF(count(*),0),1) AS pct_image
FROM public.kit_component_variant_skus k
JOIN public.products  p ON p.id = k.kit_product_id
JOIN public.suppliers s ON s.id = p.supplier_id
GROUP BY s.name
ORDER BY 2 DESC;

COMMENT ON VIEW public.v_kit_component_identity_health IS
  'Saúde honesta da identidade de componente por fornecedor: linhas materializadas, cobertura de código qualificado, cor canônica e imagem real. pct_image=0 para XBZ/Asia/Só Marcas é verídico (sem fonte de foto por componente).';

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260624154952_kit_component_identity_health_view.sql <<<

-- >>> BEGIN 20260624162848_kit_component_sku_normalized_color.sql >>>
CREATE OR REPLACE VIEW public.v_kit_component_skus AS
SELECT
  c.id                          AS component_id,
  c.kit_product_id,
  v.id                          AS variant_id,
  p.sku                         AS parent_sku,
  v.sku                         AS variant_sku,
  v.color_code                  AS variant_color_code,
  v.color_name                  AS variant_color_name,
  c.slot_code,
  c.component_name,
  c.component_type_code,
  c.is_packaging,
  c.color_id                    AS item_color_id,
  c.component_code              AS component_code_agnostico,
  -- CÓDIGO QUALIFICADO COLISÃO-SEGURO:
  --  • cor normalizada (internal_code) quando ela identifica unicamente a variante no kit
  --  • fallback para o SKU real da variante quando a cor canônica repete (sub-tons) ou está ausente
  CASE
    WHEN cv.internal_code IS NULL OR cv.internal_code = '' THEN v.sku || '-' || c.slot_code
    WHEN count(*) OVER (PARTITION BY c.kit_product_id, c.slot_code, cv.internal_code) = 1
         THEN p.sku || '-' || cv.internal_code || '-' || c.slot_code
    ELSE v.sku || '-' || c.slot_code
  END                           AS component_sku,
  c.primary_image_url           AS component_image_url,
  cv.internal_code              AS color_internal_code   -- nova coluna ao FINAL
FROM public.product_kit_components c
JOIN public.products p          ON p.id = c.kit_product_id
JOIN public.product_variants v  ON v.product_id = c.kit_product_id
LEFT JOIN public.color_variations cv ON cv.id = v.color_id;

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260624162848_kit_component_sku_normalized_color.sql <<<

-- >>> BEGIN 20260624185240_add_kit_component_dim_provenance.sql >>>
ALTER TABLE public.product_kit_components
  ADD COLUMN IF NOT EXISTS dim_source     varchar(20),
  ADD COLUMN IF NOT EXISTS dim_source_url text;

COMMENT ON COLUMN public.product_kit_components.dim_source IS
  'Procedencia das medidas do componente: ficha (PDF tecnico do fornecedor = REAL por peca), supplier_api, heuristic (estimado/copiado da caixa do kit), manual. NULL=legado/desconhecido. Politica: parse de ficha so sobrescreve heuristic/NULL/supplier_api, nunca ficha/manual.';
COMMENT ON COLUMN public.product_kit_components.dim_source_url IS
  'URL da fonte que originou as medidas (ex.: ficha_tecnica_pdf da XBZ).';

-- Backfill honesto: dimensoes pre-existentes vieram da heuristica de decomposicao
-- (a fonte do fornecedor nunca teve medida por peca; so o PDF tem, e ainda nao foi parseado).
UPDATE public.product_kit_components
SET dim_source='heuristic'
WHERE dim_source IS NULL
  AND kit_product_id <> (SELECT id FROM public.products WHERE sku='19168')
  AND (length_mm IS NOT NULL OR width_mm IS NOT NULL OR height_mm IS NOT NULL OR diameter_mm IS NOT NULL
       OR pkg_ext_length_mm IS NOT NULL OR pkg_ext_width_mm IS NOT NULL OR pkg_ext_height_mm IS NOT NULL);

-- 19168: medidas vieram da ficha tecnica REAL
UPDATE public.product_kit_components
SET dim_source='ficha', dim_source_url='https://www.xbzbrindes.com.br/getPdfProduto/28724'
WHERE kit_product_id=(SELECT id FROM public.products WHERE sku='19168');;

-- <<< END 20260624185240_add_kit_component_dim_provenance.sql <<<

-- >>> BEGIN 20260624185410_create_kit_component_ficha_staging.sql >>>
-- Landing zone: 1 linha por (produto, peca) extraida do PDF da ficha tecnica.
CREATE TABLE IF NOT EXISTS public.kit_component_ficha_staging (
  id                   uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  product_sku          varchar(50)  NOT NULL,
  product_id           uuid,
  piece_label          text         NOT NULL,
  piece_norm           text,
  piece_kind           varchar(12),                 -- item | packaging | outer_box
  dim_a_mm             int,                          -- Altura
  dim_l_mm             int,                          -- Largura
  dim_p_mm             int,                          -- Profundidade (so embalagem A x L x P)
  weight_g             int,                          -- peso por peca (normalmente NULL na ficha)
  raw_text             text,
  source               varchar(30)  NOT NULL DEFAULT 'xbz_ficha_pdf',
  source_url           text,
  parsed_at            timestamptz  NOT NULL DEFAULT now(),
  matched_component_id uuid,
  match_status         varchar(16)  NOT NULL DEFAULT 'pending',  -- pending|promoted|no_component|ambiguous|skipped
  match_confidence     numeric(4,3),
  promoted_at          timestamptz,
  notes                text,
  created_at           timestamptz  NOT NULL DEFAULT now(),
  CONSTRAINT chk_kcfs_dim_a CHECK (dim_a_mm IS NULL OR dim_a_mm BETWEEN 1 AND 20000),
  CONSTRAINT chk_kcfs_dim_l CHECK (dim_l_mm IS NULL OR dim_l_mm BETWEEN 1 AND 20000),
  CONSTRAINT chk_kcfs_dim_p CHECK (dim_p_mm IS NULL OR dim_p_mm BETWEEN 1 AND 20000),
  CONSTRAINT chk_kcfs_status CHECK (match_status IN ('pending','promoted','no_component','ambiguous','skipped'))
);
CREATE INDEX IF NOT EXISTS ix_kcfs_product ON public.kit_component_ficha_staging(product_sku);
CREATE INDEX IF NOT EXISTS ix_kcfs_status  ON public.kit_component_ficha_staging(match_status);
COMMENT ON TABLE public.kit_component_ficha_staging IS
  'Staging do parse da ficha tecnica (PDF XBZ). O job de ingestao (n8n/edge) insere 1 linha por peca; fn_promote_kit_ficha_staging casa cada peca ao componente e grava medida REAL respeitando procedencia.';

-- Helper de normalizacao de rotulo (remove "(A x L)", acentos, baixa caixa)
CREATE OR REPLACE FUNCTION public.fn_norm_piece_label(p text)
RETURNS text LANGUAGE sql STABLE AS $$
  SELECT btrim(regexp_replace(
           lower(extensions.unaccent(coalesce(regexp_replace(p, '\(.*?\)', '', 'g'), ''))),
           '\s+', ' ', 'g'))
$$;;

-- <<< END 20260624185410_create_kit_component_ficha_staging.sql <<<

-- >>> BEGIN 20260624185543_create_fn_promote_kit_ficha_staging.sql >>>
CREATE OR REPLACE FUNCTION public.fn_promote_kit_ficha_staging(p_only_sku text DEFAULT NULL)
RETURNS TABLE(promoted int, no_component int, ambiguous int, skipped int, pending int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public, extensions AS $$
DECLARE
  r record; v_pid uuid; v_norm text; v_kind text; v_comp uuid; v_cnt int; v_conf numeric; v_src_url text;
BEGIN
  FOR r IN
    SELECT * FROM kit_component_ficha_staging
    WHERE match_status='pending' AND (p_only_sku IS NULL OR product_sku=p_only_sku)
    ORDER BY product_sku, id
  LOOP
    v_norm := fn_norm_piece_label(r.piece_label);
    SELECT id INTO v_pid FROM products WHERE sku=r.product_sku AND is_kit=true;
    IF v_pid IS NULL THEN
      UPDATE kit_component_ficha_staging SET match_status='no_component',
             notes='kit nao encontrado ou is_kit=false', piece_norm=v_norm WHERE id=r.id;
      CONTINUE;
    END IF;

    v_kind := r.piece_kind;
    IF v_kind IS NULL THEN
      IF v_norm ~ '(maleta|estojo|pouch|bolsa|sacola|necessaire|\mcase\M)' THEN v_kind:='packaging';
      ELSIF v_norm ~ 'embalagem' OR fn_norm_piece_label(coalesce(r.raw_text,'')) ~ '(papel|papelao)' THEN v_kind:='outer_box';
      ELSE v_kind:='item'; END IF;
    END IF;

    IF v_kind='outer_box' THEN
      UPDATE kit_component_ficha_staging SET match_status='skipped', piece_kind='outer_box', product_id=v_pid,
             piece_norm=v_norm, notes='caixa de transporte (papelao), nao e componente do kit' WHERE id=r.id;
      CONTINUE;
    END IF;

    v_comp := NULL; v_conf := NULL;
    IF v_kind='packaging' THEN
      SELECT count(*) INTO v_cnt FROM product_kit_components WHERE kit_product_id=v_pid AND is_packaging;
      IF v_cnt=1 THEN
        SELECT id INTO v_comp FROM product_kit_components WHERE kit_product_id=v_pid AND is_packaging; v_conf:=0.99;
      ELSIF v_cnt>1 THEN
        SELECT id, extensions.similarity(fn_norm_piece_label(component_name), v_norm) INTO v_comp, v_conf
        FROM product_kit_components WHERE kit_product_id=v_pid AND is_packaging
        ORDER BY extensions.similarity(fn_norm_piece_label(component_name), v_norm) DESC NULLS LAST LIMIT 1;
      END IF;
    ELSE
      SELECT id INTO v_comp FROM product_kit_components
       WHERE kit_product_id=v_pid AND NOT is_packaging AND fn_norm_piece_label(component_name)=v_norm LIMIT 1;
      IF v_comp IS NOT NULL THEN v_conf:=1.0;
      ELSE
        SELECT id, extensions.similarity(fn_norm_piece_label(component_name), v_norm) INTO v_comp, v_conf
        FROM product_kit_components WHERE kit_product_id=v_pid AND NOT is_packaging
        ORDER BY extensions.similarity(fn_norm_piece_label(component_name), v_norm) DESC NULLS LAST LIMIT 1;
        IF v_conf IS NULL OR v_conf < 0.45 THEN v_comp:=NULL; END IF;
      END IF;
    END IF;

    IF v_comp IS NULL THEN
      UPDATE kit_component_ficha_staging SET match_status='no_component', piece_kind=v_kind, product_id=v_pid,
             piece_norm=v_norm, notes='nenhum componente '||v_kind||' casou (kit decomposto?)' WHERE id=r.id;
      CONTINUE;
    END IF;

    v_src_url := coalesce(r.source_url,
      (SELECT spr.site_data->>'ficha_tecnica_pdf' FROM supplier_products_raw spr
        WHERE spr.product_id=v_pid AND spr.site_data ? 'ficha_tecnica_pdf' LIMIT 1));

    IF v_kind='packaging' THEN
      UPDATE product_kit_components
         SET pkg_ext_height_mm=r.dim_a_mm, pkg_ext_width_mm=r.dim_l_mm, pkg_ext_length_mm=r.dim_p_mm,
             dim_source='ficha', dim_source_url=v_src_url
       WHERE id=v_comp AND coalesce(dim_source,'heuristic') IN ('heuristic','supplier_api');
    ELSE
      UPDATE product_kit_components
         SET height_mm=r.dim_a_mm, width_mm=r.dim_l_mm, length_mm=r.dim_p_mm,
             weight_g = CASE WHEN weight_g IS NULL AND r.weight_g IS NOT NULL THEN r.weight_g ELSE weight_g END,
             dim_source='ficha', dim_source_url=v_src_url
       WHERE id=v_comp AND coalesce(dim_source,'heuristic') IN ('heuristic','supplier_api');
    END IF;

    UPDATE kit_component_ficha_staging
       SET match_status='promoted', matched_component_id=v_comp, piece_kind=v_kind, product_id=v_pid,
           piece_norm=v_norm, match_confidence=round(coalesce(v_conf,0)::numeric,3), promoted_at=now(), notes=NULL
     WHERE id=r.id;
  END LOOP;

  RETURN QUERY
    SELECT count(*) FILTER (WHERE match_status='promoted')::int,
           count(*) FILTER (WHERE match_status='no_component')::int,
           count(*) FILTER (WHERE match_status='ambiguous')::int,
           count(*) FILTER (WHERE match_status='skipped')::int,
           count(*) FILTER (WHERE match_status='pending')::int
    FROM kit_component_ficha_staging WHERE (p_only_sku IS NULL OR product_sku=p_only_sku);
END $$;;

-- <<< END 20260624185543_create_fn_promote_kit_ficha_staging.sql <<<

-- >>> BEGIN 20260624185745_create_v_xbz_ficha_parse_queue.sql >>>
CREATE OR REPLACE VIEW public.v_xbz_ficha_parse_queue AS
WITH ficha AS (
  SELECT spr.product_id,
         max(spr.site_data->>'ficha_tecnica_pdf') AS ficha_pdf_url,
         max(spr.site_scraped_at)                 AS last_scraped
  FROM supplier_products_raw spr
  WHERE spr.supplier_id='d6718a29-e954-4c1b-bd84-03ea24884900'
    AND coalesce(spr.site_data->>'ficha_tecnica_pdf','')<>''
  GROUP BY spr.product_id
), comp AS (
  SELECT kit_product_id,
         count(*)                                   AS n_comp,
         count(*) FILTER (WHERE NOT is_packaging)   AS n_itens,
         count(*) FILTER (WHERE dim_source='heuristic') AS n_dim_heuristic,
         count(*) FILTER (WHERE dim_source='ficha')     AS n_dim_ficha
  FROM product_kit_components GROUP BY kit_product_id
)
SELECT
  p.sku  AS product_sku,
  p.id   AS product_id,
  p.name AS product_name,
  p.is_kit,
  (p.name ~* '[0-9]+\s*pe[çc]as') AS nome_indica_pecas,
  f.ficha_pdf_url,
  f.last_scraped,
  coalesce(c.n_comp,0)          AS n_componentes,
  coalesce(c.n_dim_heuristic,0) AS n_dim_heuristicas,
  coalesce(c.n_dim_ficha,0)     AS n_dim_ficha,
  CASE
    WHEN p.is_kit AND coalesce(c.n_dim_heuristic,0)>0 THEN 1
    WHEN p.is_kit AND coalesce(c.n_comp,0)=0          THEN 2
    WHEN (NOT p.is_kit) AND (p.name ~* '[0-9]+\s*pe[çc]as') THEN 3
    WHEN p.is_kit                                     THEN 4
    ELSE 5
  END AS prioridade,
  CASE
    WHEN p.is_kit AND coalesce(c.n_dim_heuristic,0)>0 THEN 'kit_decomposto_dims_heuristicas'
    WHEN p.is_kit AND coalesce(c.n_comp,0)=0          THEN 'kit_sem_componentes'
    WHEN (NOT p.is_kit) AND (p.name ~* '[0-9]+\s*pe[çc]as') THEN 'reclassificar_e_decompor'
    WHEN p.is_kit                                     THEN 'kit_completo_ficha'
    ELSE 'produto_comum_com_ficha'
  END AS motivo
FROM ficha f
JOIN products p ON p.id=f.product_id
LEFT JOIN comp c ON c.kit_product_id=p.id;

COMMENT ON VIEW public.v_xbz_ficha_parse_queue IS
  'Fila de trabalho do parse da ficha tecnica XBZ. prioridade 1=kit decomposto c/ dims heuristicas (parse grava real ja); 2=kit sem componentes; 3=parece kit mas is_kit=false (reclassificar+decompor); 4=kit ja ficha; 5=produto comum. O parser le esta fila, busca ficha_pdf_url, e alimenta kit_component_ficha_staging.';;

-- <<< END 20260624185745_create_v_xbz_ficha_parse_queue.sql <<<

-- >>> BEGIN 20260624190015_create_v_kit_ficha_pipeline_health.sql >>>
CREATE OR REPLACE VIEW public.v_kit_ficha_pipeline_health AS
SELECT
  (SELECT count(*) FROM kit_component_ficha_staging)                                   AS staging_total,
  (SELECT count(*) FROM kit_component_ficha_staging WHERE match_status='pending')      AS staging_pendentes,
  (SELECT count(*) FROM kit_component_ficha_staging WHERE match_status='promoted')     AS staging_promovidos,
  (SELECT count(*) FROM kit_component_ficha_staging WHERE match_status='no_component') AS staging_sem_componente,
  (SELECT count(*) FROM kit_component_ficha_staging WHERE match_status='skipped')      AS staging_skipped,
  (SELECT count(*) FROM product_kit_components WHERE dim_source='ficha')               AS componentes_dim_real_ficha,
  (SELECT count(*) FROM product_kit_components WHERE dim_source='heuristic')           AS componentes_dim_heuristica,
  (SELECT count(*) FROM product_kit_components WHERE dim_source='manual')              AS componentes_dim_manual,
  (SELECT count(*) FROM v_xbz_ficha_parse_queue WHERE prioridade=1)                    AS fila_kits_dims_heuristicas,
  (SELECT count(*) FROM v_xbz_ficha_parse_queue WHERE prioridade=2)                    AS fila_kits_sem_componentes,
  (SELECT count(*) FROM v_xbz_ficha_parse_queue WHERE prioridade=3)                    AS fila_reclassificar,
  (SELECT coalesce(sum(n_dim_heuristicas),0) FROM v_xbz_ficha_parse_queue WHERE prioridade=1) AS dims_heuristicas_corrigiveis_via_ficha,
  round(100.0*(SELECT count(*) FROM product_kit_components WHERE dim_source='ficha')
        / NULLIF((SELECT count(*) FROM product_kit_components WHERE dim_source IS NOT NULL),0),2) AS pct_dims_reais;

COMMENT ON VIEW public.v_kit_ficha_pipeline_health IS
  'Saude do pipeline de ficha tecnica: estado da staging, procedencia das medidas (real vs heuristica) e tamanho da fila acionavel de parse.';;

-- <<< END 20260624190015_create_v_kit_ficha_pipeline_health.sql <<<

-- >>> BEGIN 20260624191050_create_fn_parse_ficha_tecnica_text.sql >>>
-- Extrai linhas "Peca (A x L[ x P]): N cm x N cm[ x N cm]" de um texto (site ou PDF)
-- e insere na staging. Idempotencia fica por conta do fn_promote (procedencia).
CREATE OR REPLACE FUNCTION public.fn_parse_ficha_tecnica_text(
  p_product_sku text, p_text text, p_source_url text DEFAULT NULL,
  p_source text DEFAULT 'xbz_site_caracteristicas')
RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE m text[]; n int := 0;
BEGIN
  IF p_text IS NULL OR btrim(p_text)='' THEN RETURN 0; END IF;
  FOR m IN
    SELECT regexp_match(
             line,
             '^\s*(.+?)\s*\(\s*A\s*x\s*L(?:\s*x\s*P)?\s*\)\s*:\s*([0-9]+(?:,[0-9]+)?)\s*cm\s*x\s*([0-9]+(?:,[0-9]+)?)\s*cm(?:\s*x\s*([0-9]+(?:,[0-9]+)?)\s*cm)?'
           )
    FROM regexp_split_to_table(replace(p_text, E'\r', ''), E'\n') AS line
    WHERE line ~ '\(\s*A\s*x\s*L'
  LOOP
    IF m IS NULL THEN CONTINUE; END IF;
    INSERT INTO kit_component_ficha_staging
      (product_sku, piece_label, dim_a_mm, dim_l_mm, dim_p_mm, raw_text, source, source_url)
    VALUES (
      p_product_sku,
      btrim(m[1]),
      round(replace(m[2],',','.')::numeric*10)::int,
      round(replace(m[3],',','.')::numeric*10)::int,
      CASE WHEN m[4] IS NOT NULL THEN round(replace(m[4],',','.')::numeric*10)::int END,
      btrim(m[1])||' (A x L'||CASE WHEN m[4] IS NOT NULL THEN ' x P' ELSE '' END||'): '
        ||m[2]||' cm x '||m[3]||' cm'||CASE WHEN m[4] IS NOT NULL THEN ' x '||m[4]||' cm' ELSE '' END,
      p_source, p_source_url
    );
    n := n + 1;
  END LOOP;
  RETURN n;
END $$;;

-- <<< END 20260624191050_create_fn_parse_ficha_tecnica_text.sql <<<

-- >>> BEGIN 20260624191218_create_fn_parse_xbz_ficha_site_batch.sql >>>
-- Varre os produtos XBZ cujo site_data ja tenha a seçao de caracteristicas tecnicas
-- (chave configuravel; default 'caracteristicas_tecnicas') e parseia para a staging.
-- No-op enquanto a chave nao existir; pula produtos ja parseados desta fonte.
CREATE OR REPLACE FUNCTION public.fn_parse_xbz_ficha_site_batch(
  p_key text DEFAULT 'caracteristicas_tecnicas', p_limit int DEFAULT NULL)
RETURNS TABLE(produtos_processados int, linhas_extraidas int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE r record; v_prod int:=0; v_lin int:=0; v_n int;
BEGIN
  FOR r IN
    SELECT DISTINCT ON (p.sku) p.sku AS product_sku,
           spr.site_data->>p_key AS texto,
           coalesce(spr.site_data->>'ficha_tecnica_pdf', spr.site_data->>'url') AS src_url
    FROM supplier_products_raw spr
    JOIN products p ON p.id=spr.product_id
    WHERE spr.supplier_id='d6718a29-e954-4c1b-bd84-03ea24884900'
      AND spr.site_data ? p_key
      AND coalesce(spr.site_data->>p_key,'')<>''
      AND NOT EXISTS (SELECT 1 FROM kit_component_ficha_staging s
                       WHERE s.product_sku=p.sku AND s.source='xbz_site_caracteristicas')
    ORDER BY p.sku
    LIMIT p_limit
  LOOP
    v_n := fn_parse_ficha_tecnica_text(r.product_sku, r.texto, r.src_url, 'xbz_site_caracteristicas');
    IF v_n>0 THEN v_prod:=v_prod+1; v_lin:=v_lin+v_n; END IF;
  END LOOP;
  RETURN QUERY SELECT v_prod, v_lin;
END $$;;

-- <<< END 20260624191218_create_fn_parse_xbz_ficha_site_batch.sql <<<

-- >>> BEGIN 20260624193255_enable_http_extension.sql >>>
CREATE EXTENSION IF NOT EXISTS http WITH SCHEMA extensions;;

-- <<< END 20260624193255_enable_http_extension.sql <<<

-- >>> BEGIN 20260624193517_create_fn_fetch_xbz_ficha.sql >>>
CREATE OR REPLACE FUNCTION public.fn_fetch_xbz_ficha(p_product_sku text, p_force boolean DEFAULT false)
RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public, extensions AS $$
DECLARE v_url text; v_pdf text; v_md text; v_status int; v_n int:=0;
BEGIN
  SELECT spr.site_data->>'url', spr.site_data->>'ficha_tecnica_pdf'
    INTO v_url, v_pdf
  FROM supplier_products_raw spr JOIN products p ON p.id=spr.product_id
  WHERE p.sku=p_product_sku AND spr.supplier_id='d6718a29-e954-4c1b-bd84-03ea24884900'
    AND spr.site_data ? 'url'
  ORDER BY spr.site_scraped_at DESC NULLS LAST LIMIT 1;
  IF v_url IS NULL THEN RETURN -1; END IF;

  IF (NOT p_force) AND EXISTS(SELECT 1 FROM kit_component_ficha_staging
         WHERE product_sku=p_product_sku AND source='xbz_site_jina') THEN
    RETURN -2;
  END IF;

  PERFORM extensions.http_set_curlopt('CURLOPT_TIMEOUT','40');
  BEGIN
    SELECT status, content INTO v_status, v_md FROM extensions.http_get('https://r.jina.ai/' || v_url);
  EXCEPTION WHEN OTHERS THEN
    RETURN -3;
  END;
  IF v_status<>200 OR v_md IS NULL THEN RETURN -(1000+coalesce(v_status,0)); END IF;

  v_n := fn_parse_ficha_tecnica_text(p_product_sku, v_md, coalesce(v_pdf,v_url), 'xbz_site_jina');
  RETURN v_n;
END $$;;

-- <<< END 20260624193517_create_fn_fetch_xbz_ficha.sql <<<

-- >>> BEGIN 20260624193801_robusten_ficha_parser_v2.sql >>>
-- Parser robusto: aceita "<peca> (A x L): N cm x N cm", "Medidas <peca>: N cm x N cm",
-- "<peca>: N cm x N cm", com x ou ×; ignora linhas de gravacao; descarta rotulos invalidos.
CREATE OR REPLACE FUNCTION public.fn_parse_ficha_tecnica_text(
  p_product_sku text, p_text text, p_source_url text DEFAULT NULL,
  p_source text DEFAULT 'xbz_ficha')
RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE m text[]; lbl text; n int := 0;
BEGIN
  IF p_text IS NULL OR btrim(p_text)='' THEN RETURN 0; END IF;
  FOR m IN
    SELECT regexp_match(
             line,
             '^(.*?)([0-9]+(?:,[0-9]+)?)\s*cm\s*[x×]\s*([0-9]+(?:,[0-9]+)?)\s*cm(?:\s*[x×]\s*([0-9]+(?:,[0-9]+)?)\s*cm)?',
             'i')
    FROM regexp_split_to_table(replace(p_text, E'\r',''), E'\n') AS line
    WHERE line ~* '[0-9]\s*cm\s*[x×]\s*[0-9]'   -- tem medida cm x cm
      AND line !~* 'grava'                       -- NAO e area de gravacao
      AND line !~* 'aproxim.{0,6}para'           -- "aproximadas para gravacao"
  LOOP
    IF m IS NULL THEN CONTINUE; END IF;
    lbl := m[1];
    lbl := regexp_replace(lbl, '\(.*?\)', '', 'g');                                  -- remove (A x L), (CxL)...
    lbl := regexp_replace(lbl, '(?i)^\s*medidas?\s+(da\s+|de\s+|do\s+|das\s+|dos\s+)?', ''); -- "Medidas (da/de..)"
    lbl := regexp_replace(lbl, '^[\s\-*•\d.|>#]+', '');                               -- bullets/numeros/markdown no inicio
    lbl := regexp_replace(lbl, '[*_:|]+', ' ', 'g');                                  -- markdown/colon
    lbl := btrim(regexp_replace(lbl, '\s+', ' ', 'g'), ' -');
    CONTINUE WHEN lbl IS NULL OR length(lbl) < 2 OR length(lbl) > 60;
    CONTINUE WHEN lbl ~* '^(peso|volume|capacidade|conteudo|conteúdo|cor|cores|material|garantia|composic|composiç|dimens)';
    INSERT INTO kit_component_ficha_staging
      (product_sku, piece_label, dim_a_mm, dim_l_mm, dim_p_mm, raw_text, source, source_url)
    VALUES (
      p_product_sku, lbl,
      round(replace(m[2],',','.')::numeric*10)::int,
      round(replace(m[3],',','.')::numeric*10)::int,
      CASE WHEN m[4] IS NOT NULL THEN round(replace(m[4],',','.')::numeric*10)::int END,
      lbl||': '||m[2]||' cm x '||m[3]||' cm'||COALESCE(' x '||m[4]||' cm',''),
      p_source, p_source_url
    );
    n := n + 1;
  END LOOP;
  RETURN n;
END $$;;

-- <<< END 20260624193801_robusten_ficha_parser_v2.sql <<<

-- >>> BEGIN 20260624193820_fetch_xbz_ficha_prefer_pdf.sql >>>
CREATE OR REPLACE FUNCTION public.fn_fetch_xbz_ficha(p_product_sku text, p_force boolean DEFAULT false)
RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public, extensions AS $$
DECLARE v_url text; v_pdf text; v_md text; v_status int; v_n int:=0; v_target text;
BEGIN
  SELECT spr.site_data->>'url', spr.site_data->>'ficha_tecnica_pdf'
    INTO v_url, v_pdf
  FROM supplier_products_raw spr JOIN products p ON p.id=spr.product_id
  WHERE p.sku=p_product_sku AND spr.supplier_id='d6718a29-e954-4c1b-bd84-03ea24884900'
    AND spr.site_data ? 'url'
  ORDER BY spr.site_scraped_at DESC NULLS LAST LIMIT 1;
  IF v_url IS NULL AND v_pdf IS NULL THEN RETURN -1; END IF;

  IF (NOT p_force) AND EXISTS(SELECT 1 FROM kit_component_ficha_staging
         WHERE product_sku=p_product_sku AND source ILIKE 'xbz_%jina') THEN
    RETURN -2;
  END IF;

  v_target := coalesce(v_pdf, v_url);   -- PDF primeiro (mais confiavel)
  PERFORM extensions.http_set_curlopt('CURLOPT_TIMEOUT','40');
  BEGIN
    SELECT status, content INTO v_status, v_md FROM extensions.http_get('https://r.jina.ai/' || v_target);
  EXCEPTION WHEN OTHERS THEN RETURN -3; END;
  IF v_status=200 AND v_md IS NOT NULL THEN
    v_n := fn_parse_ficha_tecnica_text(p_product_sku, v_md, v_target,
             CASE WHEN v_pdf IS NOT NULL THEN 'xbz_ficha_pdf_jina' ELSE 'xbz_site_jina' END);
  END IF;

  -- fallback: se PDF nao rendeu nada e existe pagina distinta, tenta a pagina
  IF v_n=0 AND v_pdf IS NOT NULL AND v_url IS NOT NULL THEN
    BEGIN
      SELECT status, content INTO v_status, v_md FROM extensions.http_get('https://r.jina.ai/' || v_url);
    EXCEPTION WHEN OTHERS THEN v_status:=0; END;
    IF v_status=200 AND v_md IS NOT NULL THEN
      v_n := fn_parse_ficha_tecnica_text(p_product_sku, v_md, v_url, 'xbz_site_jina');
    END IF;
  END IF;

  RETURN v_n;
END $$;;

-- <<< END 20260624193820_fetch_xbz_ficha_prefer_pdf.sql <<<

-- >>> BEGIN 20260624194049_fetch_with_jina_key_and_batch_runner.sql >>>
-- Busca usando a chave Jina do Vault (Bearer) + sentinela quando a ficha nao tem tabela por peca
CREATE OR REPLACE FUNCTION public.fn_fetch_xbz_ficha(p_product_sku text, p_force boolean DEFAULT false)
RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=public, extensions AS $$
DECLARE v_url text; v_pdf text; v_md text; v_status int; v_n int:=0; v_target text;
        v_key text; v_hdr extensions.http_header[]; v_got200 boolean:=false;
BEGIN
  SELECT spr.site_data->>'url', spr.site_data->>'ficha_tecnica_pdf' INTO v_url, v_pdf
  FROM supplier_products_raw spr JOIN products p ON p.id=spr.product_id
  WHERE p.sku=p_product_sku AND spr.supplier_id='d6718a29-e954-4c1b-bd84-03ea24884900' AND spr.site_data ? 'url'
  ORDER BY spr.site_scraped_at DESC NULLS LAST LIMIT 1;
  IF v_url IS NULL AND v_pdf IS NULL THEN RETURN -1; END IF;
  IF (NOT p_force) AND EXISTS(SELECT 1 FROM kit_component_ficha_staging
        WHERE product_sku=p_product_sku AND source ILIKE 'xbz_%jina') THEN RETURN -2; END IF;

  SELECT decrypted_secret INTO v_key FROM vault.decrypted_secrets WHERE name='jina_api_key' LIMIT 1;
  v_hdr := CASE WHEN v_key IS NOT NULL THEN ARRAY[extensions.http_header('Authorization','Bearer '||v_key)] END;

  PERFORM extensions.http_set_curlopt('CURLOPT_TIMEOUT','45');
  v_target := coalesce(v_pdf, v_url);
  BEGIN
    SELECT status, content INTO v_status, v_md
    FROM extensions.http(('GET','https://r.jina.ai/'||v_target, v_hdr, NULL, NULL)::extensions.http_request);
  EXCEPTION WHEN OTHERS THEN v_status:=0; END;
  IF v_status=200 AND v_md IS NOT NULL THEN
    v_got200:=true;
    v_n := fn_parse_ficha_tecnica_text(p_product_sku, v_md, v_target,
             CASE WHEN v_pdf IS NOT NULL THEN 'xbz_ficha_pdf_jina' ELSE 'xbz_site_jina' END);
  END IF;

  IF v_n=0 AND v_pdf IS NOT NULL AND v_url IS NOT NULL THEN
    BEGIN
      SELECT status, content INTO v_status, v_md
      FROM extensions.http(('GET','https://r.jina.ai/'||v_url, v_hdr, NULL, NULL)::extensions.http_request);
    EXCEPTION WHEN OTHERS THEN v_status:=0; END;
    IF v_status=200 AND v_md IS NOT NULL THEN
      v_got200:=true;
      v_n := fn_parse_ficha_tecnica_text(p_product_sku, v_md, v_url, 'xbz_site_jina');
    END IF;
  END IF;

  -- sentinela: buscou OK mas ficha nao tem tabela por peca -> nao re-buscar
  IF v_got200 AND v_n=0 THEN
    INSERT INTO kit_component_ficha_staging(product_sku, piece_label, source, source_url, match_status, notes)
    VALUES (p_product_sku, '__sem_medidas_por_peca__', 'xbz_ficha_pdf_jina', v_target, 'skipped', 'ficha sem tabela por peca');
  END IF;
  IF NOT v_got200 THEN RETURN -3; END IF;   -- falha de fetch (transitorio): permite retry
  RETURN v_n;
END $$;

-- Executor em lote: busca+promove N kits prioridade-1 ainda nao processados
CREATE OR REPLACE FUNCTION public.fn_xbz_ficha_run_batch(p_limit int DEFAULT 8)
RETURNS TABLE(sku text, extraidas int, promovidas int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public, extensions AS $$
DECLARE r record; v_ext int; v_prom int;
BEGIN
  FOR r IN
    SELECT q.product_sku FROM v_xbz_ficha_parse_queue q
    WHERE q.prioridade=1
      AND NOT EXISTS(SELECT 1 FROM kit_component_ficha_staging s
                      WHERE s.product_sku=q.product_sku AND s.source ILIKE 'xbz_%jina')
    ORDER BY q.n_dim_heuristicas DESC, q.product_sku
    LIMIT p_limit
  LOOP
    v_ext := fn_fetch_xbz_ficha(r.product_sku, false);
    SELECT promoted INTO v_prom FROM fn_promote_kit_ficha_staging(r.product_sku);
    sku:=r.product_sku; extraidas:=coalesce(v_ext,0); promovidas:=coalesce(v_prom,0);
    RETURN NEXT;
  END LOOP;
END $$;;

-- <<< END 20260624194049_fetch_with_jina_key_and_batch_runner.sql <<<

-- >>> BEGIN 20260624195100_promote_matcher_v2_containment.sql >>>
CREATE OR REPLACE FUNCTION public.fn_promote_kit_ficha_staging(p_only_sku text DEFAULT NULL)
RETURNS TABLE(promoted int, no_component int, ambiguous int, skipped int, pending int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public, extensions AS $$
DECLARE r record; v_pid uuid; v_norm text; v_kind text; v_comp uuid; v_cnt int; v_conf numeric; v_src_url text; v_tie int;
BEGIN
  FOR r IN SELECT * FROM kit_component_ficha_staging
           WHERE match_status='pending' AND (p_only_sku IS NULL OR product_sku=p_only_sku)
           ORDER BY product_sku, id
  LOOP
    v_norm := fn_norm_piece_label(r.piece_label);
    SELECT id INTO v_pid FROM products WHERE sku=r.product_sku AND is_kit=true;
    IF v_pid IS NULL THEN
      UPDATE kit_component_ficha_staging SET match_status='no_component', notes='kit nao encontrado/is_kit=false', piece_norm=v_norm WHERE id=r.id; CONTINUE;
    END IF;

    v_kind := r.piece_kind;
    IF v_kind IS NULL THEN
      IF v_norm ~ '(maleta|estojo|pouch|bolsa|sacola|necessaire|\mcase\M)' THEN v_kind:='packaging';
      ELSIF v_norm ~ 'embalagem' OR fn_norm_piece_label(coalesce(r.raw_text,'')) ~ '(papel|papelao)' THEN v_kind:='outer_box';
      ELSE v_kind:='item'; END IF;
    END IF;

    IF v_kind='outer_box' THEN
      UPDATE kit_component_ficha_staging SET match_status='skipped', piece_kind='outer_box', product_id=v_pid, piece_norm=v_norm,
             notes='caixa de transporte, nao e componente' WHERE id=r.id; CONTINUE;
    END IF;

    v_comp:=NULL; v_conf:=NULL; v_tie:=0;
    IF v_kind='packaging' THEN
      SELECT count(*) INTO v_cnt FROM product_kit_components WHERE kit_product_id=v_pid AND is_packaging;
      IF v_cnt=1 THEN SELECT id INTO v_comp FROM product_kit_components WHERE kit_product_id=v_pid AND is_packaging; v_conf:=0.95;
      ELSIF v_cnt>1 THEN
        SELECT id, extensions.similarity(fn_norm_piece_label(component_name), v_norm) INTO v_comp, v_conf
        FROM product_kit_components WHERE kit_product_id=v_pid AND is_packaging
        ORDER BY extensions.similarity(fn_norm_piece_label(component_name), v_norm) DESC NULLS LAST LIMIT 1;
      END IF;
    ELSE
      WITH cand AS (
        SELECT c.id,
          CASE WHEN fn_norm_piece_label(c.component_name)=v_norm THEN 1.00
               WHEN length(fn_norm_piece_label(c.component_name))>=4 AND v_norm LIKE '%'||fn_norm_piece_label(c.component_name)||'%' THEN 0.92
               WHEN length(v_norm)>=4 AND fn_norm_piece_label(c.component_name) LIKE '%'||v_norm||'%' THEN 0.90
               ELSE extensions.similarity(fn_norm_piece_label(c.component_name), v_norm) END AS score
        FROM product_kit_components c WHERE c.kit_product_id=v_pid AND NOT c.is_packaging
      ), ranked AS (SELECT id, score, row_number() OVER (ORDER BY score DESC) rn FROM cand)
      SELECT id, score, (SELECT count(*) FROM ranked r2 WHERE r2.score >= ranked.score - 0.08 AND r2.id<>ranked.id)
        INTO v_comp, v_conf, v_tie FROM ranked WHERE rn=1;
      IF v_conf IS NULL OR v_conf < 0.50 OR v_tie > 0 THEN v_comp:=NULL; END IF;
    END IF;

    IF v_comp IS NULL THEN
      UPDATE kit_component_ficha_staging
        SET match_status = CASE WHEN v_tie>0 THEN 'ambiguous' ELSE 'no_component' END,
            piece_kind=v_kind, product_id=v_pid, piece_norm=v_norm,
            notes = CASE WHEN v_tie>0 THEN 'rotulo casa com multiplos componentes' ELSE 'nenhum componente '||v_kind||' casou' END
        WHERE id=r.id; CONTINUE;
    END IF;

    v_src_url := coalesce(r.source_url, (SELECT spr.site_data->>'ficha_tecnica_pdf' FROM supplier_products_raw spr WHERE spr.product_id=v_pid AND spr.site_data ? 'ficha_tecnica_pdf' LIMIT 1));

    IF v_kind='packaging' THEN
      UPDATE product_kit_components SET pkg_ext_height_mm=r.dim_a_mm, pkg_ext_width_mm=r.dim_l_mm, pkg_ext_length_mm=r.dim_p_mm,
             dim_source='ficha', dim_source_url=v_src_url
       WHERE id=v_comp AND coalesce(dim_source,'heuristic') IN ('heuristic','supplier_api');
    ELSE
      UPDATE product_kit_components SET height_mm=r.dim_a_mm, width_mm=r.dim_l_mm, length_mm=r.dim_p_mm,
             weight_g=CASE WHEN weight_g IS NULL AND r.weight_g IS NOT NULL THEN r.weight_g ELSE weight_g END,
             dim_source='ficha', dim_source_url=v_src_url
       WHERE id=v_comp AND coalesce(dim_source,'heuristic') IN ('heuristic','supplier_api');
    END IF;

    UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_comp, piece_kind=v_kind,
           product_id=v_pid, piece_norm=v_norm, match_confidence=round(coalesce(v_conf,0)::numeric,3), promoted_at=now(), notes=NULL
     WHERE id=r.id;
  END LOOP;

  RETURN QUERY SELECT count(*) FILTER (WHERE match_status='promoted')::int, count(*) FILTER (WHERE match_status='no_component')::int,
                      count(*) FILTER (WHERE match_status='ambiguous')::int, count(*) FILTER (WHERE match_status='skipped')::int,
                      count(*) FILTER (WHERE match_status='pending')::int
               FROM kit_component_ficha_staging WHERE (p_only_sku IS NULL OR product_sku=p_only_sku);
END $$;;

-- <<< END 20260624195100_promote_matcher_v2_containment.sql <<<

-- >>> BEGIN 20260624195559_promote_matcher_v3_exact_wins.sql >>>
CREATE OR REPLACE FUNCTION public.fn_promote_kit_ficha_staging(p_only_sku text DEFAULT NULL)
RETURNS TABLE(promoted int, no_component int, ambiguous int, skipped int, pending int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public, extensions AS $$
DECLARE r record; v_pid uuid; v_norm text; v_kind text; v_comp uuid; v_cnt int; v_conf numeric; v_src_url text; v_tie int;
BEGIN
  FOR r IN SELECT * FROM kit_component_ficha_staging
           WHERE match_status='pending' AND (p_only_sku IS NULL OR product_sku=p_only_sku)
           ORDER BY product_sku, id
  LOOP
    v_norm := fn_norm_piece_label(r.piece_label);
    SELECT id INTO v_pid FROM products WHERE sku=r.product_sku AND is_kit=true;
    IF v_pid IS NULL THEN
      UPDATE kit_component_ficha_staging SET match_status='no_component', notes='kit nao encontrado/is_kit=false', piece_norm=v_norm WHERE id=r.id; CONTINUE;
    END IF;

    v_kind := r.piece_kind;
    IF v_kind IS NULL THEN
      IF v_norm ~ '(maleta|estojo|pouch|bolsa|sacola|necessaire|\mcase\M)' THEN v_kind:='packaging';
      ELSIF v_norm ~ 'embalagem' OR fn_norm_piece_label(coalesce(r.raw_text,'')) ~ '(papel|papelao)' THEN v_kind:='outer_box';
      ELSE v_kind:='item'; END IF;
    END IF;

    IF v_kind='outer_box' THEN
      UPDATE kit_component_ficha_staging SET match_status='skipped', piece_kind='outer_box', product_id=v_pid, piece_norm=v_norm,
             notes='caixa de transporte, nao e componente' WHERE id=r.id; CONTINUE;
    END IF;

    v_comp:=NULL; v_conf:=NULL; v_tie:=0;
    IF v_kind='packaging' THEN
      SELECT count(*) INTO v_cnt FROM product_kit_components WHERE kit_product_id=v_pid AND is_packaging;
      IF v_cnt=1 THEN SELECT id INTO v_comp FROM product_kit_components WHERE kit_product_id=v_pid AND is_packaging; v_conf:=0.95;
      ELSIF v_cnt>1 THEN
        SELECT id, extensions.similarity(fn_norm_piece_label(component_name), v_norm) INTO v_comp, v_conf
        FROM product_kit_components WHERE kit_product_id=v_pid AND is_packaging
        ORDER BY extensions.similarity(fn_norm_piece_label(component_name), v_norm) DESC NULLS LAST LIMIT 1;
      END IF;
    ELSE
      WITH cand AS (
        SELECT c.id,
          CASE WHEN fn_norm_piece_label(c.component_name)=v_norm THEN 1.00
               WHEN length(fn_norm_piece_label(c.component_name))>=4 AND v_norm LIKE '%'||fn_norm_piece_label(c.component_name)||'%' THEN 0.92
               WHEN length(v_norm)>=4 AND fn_norm_piece_label(c.component_name) LIKE '%'||v_norm||'%' THEN 0.90
               ELSE extensions.similarity(fn_norm_piece_label(c.component_name), v_norm) END AS score
        FROM product_kit_components c WHERE c.kit_product_id=v_pid AND NOT c.is_packaging
      ), ranked AS (SELECT id, score, row_number() OVER (ORDER BY score DESC) rn FROM cand)
      SELECT id, score, (SELECT count(*) FROM ranked r2 WHERE r2.score >= ranked.score - 0.08 AND r2.id<>ranked.id)
        INTO v_comp, v_conf, v_tie FROM ranked WHERE rn=1;
      -- exato (>=0.999) vence sempre; nao-exato exige ausencia de empate e >=0.50
      IF v_conf IS NULL OR v_conf < 0.50 OR (v_conf < 0.999 AND v_tie > 0) THEN v_comp:=NULL; END IF;
    END IF;

    IF v_comp IS NULL THEN
      UPDATE kit_component_ficha_staging
        SET match_status = CASE WHEN v_tie>0 THEN 'ambiguous' ELSE 'no_component' END,
            piece_kind=v_kind, product_id=v_pid, piece_norm=v_norm,
            notes = CASE WHEN v_tie>0 THEN 'rotulo casa com multiplos componentes' ELSE 'nenhum componente '||v_kind||' casou' END
        WHERE id=r.id; CONTINUE;
    END IF;

    v_src_url := coalesce(r.source_url, (SELECT spr.site_data->>'ficha_tecnica_pdf' FROM supplier_products_raw spr WHERE spr.product_id=v_pid AND spr.site_data ? 'ficha_tecnica_pdf' LIMIT 1));

    IF v_kind='packaging' THEN
      UPDATE product_kit_components SET pkg_ext_height_mm=r.dim_a_mm, pkg_ext_width_mm=r.dim_l_mm, pkg_ext_length_mm=r.dim_p_mm,
             dim_source='ficha', dim_source_url=v_src_url
       WHERE id=v_comp AND coalesce(dim_source,'heuristic') IN ('heuristic','supplier_api');
    ELSE
      UPDATE product_kit_components SET height_mm=r.dim_a_mm, width_mm=r.dim_l_mm, length_mm=r.dim_p_mm,
             weight_g=CASE WHEN weight_g IS NULL AND r.weight_g IS NOT NULL THEN r.weight_g ELSE weight_g END,
             dim_source='ficha', dim_source_url=v_src_url
       WHERE id=v_comp AND coalesce(dim_source,'heuristic') IN ('heuristic','supplier_api');
    END IF;

    UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_comp, piece_kind=v_kind,
           product_id=v_pid, piece_norm=v_norm, match_confidence=round(coalesce(v_conf,0)::numeric,3), promoted_at=now(), notes=NULL
     WHERE id=r.id;
  END LOOP;

  RETURN QUERY SELECT count(*) FILTER (WHERE match_status='promoted')::int, count(*) FILTER (WHERE match_status='no_component')::int,
                      count(*) FILTER (WHERE match_status='ambiguous')::int, count(*) FILTER (WHERE match_status='skipped')::int,
                      count(*) FILTER (WHERE match_status='pending')::int
               FROM kit_component_ficha_staging WHERE (p_only_sku IS NULL OR product_sku=p_only_sku);
END $$;;

-- <<< END 20260624195559_promote_matcher_v3_exact_wins.sql <<<

-- >>> BEGIN 20260624204327_create_fn_decompose_kit_from_ficha.sql >>>
CREATE OR REPLACE FUNCTION public.fn_decompose_kit_from_ficha(p_sku text, p_dry boolean DEFAULT true)
RETURNS TABLE(acao text, slot text, nome text, tipo text, a int, l int, p int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public, extensions AS $$
DECLARE
  v_kid uuid; v_ph_id uuid; v_ph_slot text; v_ph_pkg boolean; v_ph_sku text; v_ic text; v_ncomp int; v_phnum int;
  r record; v_kidx int:=0; v_eidx int:=0; v_first_item boolean:=false; v_first_pkg boolean:=false;
  v_kind text; v_type text; v_code text; v_csku text; v_a int; v_l int; v_pp int; v_tgt uuid; v_nm text;
BEGIN
  SELECT id INTO v_kid FROM products WHERE sku=p_sku AND is_kit=true;
  IF v_kid IS NULL THEN RAISE EXCEPTION 'kit % nao encontrado', p_sku; END IF;
  SELECT count(*) INTO v_ncomp FROM product_kit_components WHERE kit_product_id=v_kid;
  IF v_ncomp<>1 THEN RAISE EXCEPTION 'kit % tem % componentes (esperado 1) - abortando', p_sku, v_ncomp; END IF;

  SELECT id, slot_code, is_packaging, component_sku INTO v_ph_id, v_ph_slot, v_ph_pkg, v_ph_sku
  FROM product_kit_components WHERE kit_product_id=v_kid;
  v_phnum := (substring(v_ph_slot from 2))::int;
  v_ic := (regexp_match(v_ph_sku, '^'||p_sku||'-([0-9.]+)-(K|E)[0-9]+$'))[1];
  IF v_ic IS NULL THEN RAISE EXCEPTION 'internal_code nao extraivel do sku % (formato legado)', v_ph_sku; END IF;

  FOR r IN
    SELECT s.id sid, s.piece_label, s.source_url, s.dim_a_mm, s.dim_l_mm, s.dim_p_mm, fn_norm_piece_label(s.piece_label) pnorm
    FROM kit_component_ficha_staging s
    WHERE s.product_sku=p_sku AND s.piece_label NOT LIKE '\_\_%'
      AND s.match_status IN ('no_component','ambiguous','pending')
    ORDER BY (CASE WHEN fn_norm_piece_label(s.piece_label) ~ '(maleta|estojo|necessaire|pouch|bolsa|sacola|caixa)' THEN 1 ELSE 0 END), s.id
  LOOP
    v_kind := CASE WHEN r.pnorm ~ '(maleta|estojo|necessaire|pouch|bolsa|sacola|caixa)' THEN 'packaging' ELSE 'item' END;
    v_type := CASE
      WHEN r.pnorm ~ 'faca' THEN 'FACA' WHEN r.pnorm ~ 'tabua' THEN 'TABUA'
      WHEN r.pnorm ~ 'garfo' THEN 'GARFO' WHEN r.pnorm ~ 'espatula' THEN 'ESPATULA'
      WHEN r.pnorm ~ '(colher|concha|escumadeira)' THEN 'COLHER' WHEN r.pnorm ~ 'pegador' THEN 'PEGADOR'
      WHEN r.pnorm ~ 'pincel' THEN 'PINCEL' WHEN r.pnorm ~ '(caderno|caderneta)' THEN 'CADERNO'
      WHEN r.pnorm ~ 'caneta' THEN 'CANETA' WHEN r.pnorm ~ 'copo' THEN 'COPO'
      WHEN r.pnorm ~ 'caneca' THEN 'CANECA' WHEN r.pnorm ~ 'garrafa' THEN 'GARRAFA'
      WHEN r.pnorm ~ 'chaveiro' THEN 'CHAVEIRO' WHEN r.pnorm ~ 'porta ?cart' THEN 'PORTA_CARTAO'
      WHEN r.pnorm ~ 'tesoura' THEN 'TESOURA' WHEN r.pnorm ~ 'canudo' THEN 'CANUDO'
      WHEN r.pnorm ~ 'frasco' THEN 'FRASCO' WHEN r.pnorm ~ 'pote' THEN 'POTE'
      WHEN r.pnorm ~ 'bandeja' THEN 'BANDEJA' WHEN r.pnorm ~ 'squeeze' THEN 'SQUEEZE'
      WHEN r.pnorm ~ 'coquetel' THEN 'COQUETELEIRA' WHEN r.pnorm ~ 'saca.?rolha' THEN 'SACA_ROLHAS'
      WHEN r.pnorm ~ 'dosador' THEN 'BICO_DOSADOR' WHEN r.pnorm ~ 'socador' THEN 'SOCADOR'
      WHEN r.pnorm ~ 'escova' THEN 'ESCOVA' WHEN r.pnorm ~ 'xicara' THEN 'XICARA'
      WHEN r.pnorm ~ 'pires' THEN 'PIRES' WHEN r.pnorm ~ '(taca|taça)' THEN 'TACA_VINHO'
      WHEN r.pnorm ~ 'chaira' THEN 'CHAIRA' WHEN r.pnorm ~ 'avental' THEN 'AVENTAL'
      WHEN r.pnorm ~ 'necessaire' THEN 'NECESSAIRE' WHEN r.pnorm ~ 'fone' THEN 'FONE'
      WHEN r.pnorm ~ 'mochila' THEN 'MOCHILA' WHEN r.pnorm ~ 'caixa' THEN 'CAIXA'
      WHEN r.pnorm ~ 'anel' THEN 'ANEL_SALVA_GOTAS' WHEN r.pnorm ~ 'tampa' THEN 'TAMPA'
      ELSE NULL END;
    v_a := CASE WHEN r.dim_a_mm BETWEEN 1 AND 1500 THEN r.dim_a_mm END;
    v_l := CASE WHEN r.dim_l_mm BETWEEN 1 AND 1500 THEN r.dim_l_mm END;
    v_pp := CASE WHEN r.dim_p_mm BETWEEN 1 AND 1500 THEN r.dim_p_mm END;
    v_nm := left(initcap(r.piece_label), 80);

    IF v_kind='item' THEN
      IF (NOT v_ph_pkg) AND (NOT v_first_item) THEN
        slot:=v_ph_slot; acao:='UPDATE placeholder->item'; v_tgt:=v_ph_id; v_first_item:=true; v_kidx:=greatest(v_kidx,v_phnum);
        IF NOT p_dry THEN
          UPDATE product_kit_components SET component_name=v_nm, component_type_code=v_type,
                 height_mm=v_a, width_mm=v_l, length_mm=v_pp, dim_source='ficha', dim_source_url=r.source_url WHERE id=v_ph_id;
          UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_ph_id, product_id=v_kid,
                 piece_kind='item', piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='decomp:placeholder' WHERE id=r.sid;
        END IF;
      ELSE
        v_kidx:=v_kidx+1; IF (NOT v_ph_pkg) AND v_kidx=v_phnum THEN v_kidx:=v_kidx+1; END IF;
        slot:='K'||v_kidx; acao:='INSERT item'; v_code:=p_sku||'-'||slot; v_csku:=p_sku||'-'||v_ic||'-'||slot;
        IF NOT p_dry THEN
          INSERT INTO product_kit_components(kit_product_id,component_name,component_type_code,slot_code,component_code,component_sku,
            is_packaging,quantity,is_standalone_sellable,height_mm,width_mm,length_mm,dim_source,dim_source_url)
          VALUES (v_kid,v_nm,v_type,slot,v_code,v_csku,false,1,false,v_a,v_l,v_pp,'ficha',r.source_url) RETURNING id INTO v_tgt;
          UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_tgt, product_id=v_kid,
                 piece_kind='item', piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='decomp:novo' WHERE id=r.sid;
        END IF;
      END IF;
    ELSE
      IF v_ph_pkg AND (NOT v_first_pkg) THEN
        slot:=v_ph_slot; acao:='UPDATE placeholder->pkg'; v_tgt:=v_ph_id; v_first_pkg:=true; v_eidx:=greatest(v_eidx,v_phnum);
        IF NOT p_dry THEN
          UPDATE product_kit_components SET component_name=v_nm, component_type_code=coalesce(v_type,'CAIXA'),
                 pkg_ext_height_mm=v_a, pkg_ext_width_mm=v_l, pkg_ext_length_mm=v_pp, dim_source='ficha', dim_source_url=r.source_url WHERE id=v_ph_id;
          UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_ph_id, product_id=v_kid,
                 piece_kind='packaging', piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='decomp:placeholder pkg' WHERE id=r.sid;
        END IF;
      ELSE
        v_eidx:=v_eidx+1; IF v_ph_pkg AND v_eidx=v_phnum THEN v_eidx:=v_eidx+1; END IF;
        slot:='E'||v_eidx; acao:='INSERT pkg'; v_code:=p_sku||'-'||slot; v_csku:=p_sku||'-'||v_ic||'-'||slot;
        IF NOT p_dry THEN
          INSERT INTO product_kit_components(kit_product_id,component_name,component_type_code,slot_code,component_code,component_sku,
            is_packaging,quantity,is_standalone_sellable,pkg_ext_height_mm,pkg_ext_width_mm,pkg_ext_length_mm,dim_source,dim_source_url)
          VALUES (v_kid,v_nm,coalesce(v_type,'CAIXA'),slot,v_code,v_csku,true,1,false,v_a,v_l,v_pp,'ficha',r.source_url) RETURNING id INTO v_tgt;
          UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_tgt, product_id=v_kid,
                 piece_kind='packaging', piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='decomp:novo pkg' WHERE id=r.sid;
        END IF;
      END IF;
    END IF;

    tipo:=v_type; nome:=v_nm; a:=v_a; l:=v_l; p:=v_pp; RETURN NEXT;
  END LOOP;
END $$;;

-- <<< END 20260624204327_create_fn_decompose_kit_from_ficha.sql <<<

-- >>> BEGIN 20260624204942_decompose_fn_support_legacy_colorcode.sql >>>
CREATE OR REPLACE FUNCTION public.fn_decompose_kit_from_ficha(p_sku text, p_dry boolean DEFAULT true)
RETURNS TABLE(acao text, slot text, nome text, tipo text, a int, l int, p int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public, extensions AS $$
DECLARE
  v_kid uuid; v_ph_id uuid; v_ph_slot text; v_ph_pkg boolean; v_ph_sku text; v_ic text; v_ncomp int; v_phnum int; v_legacy boolean:=false;
  r record; v_kidx int:=0; v_eidx int:=0; v_first_item boolean:=false; v_first_pkg boolean:=false;
  v_kind text; v_type text; v_code text; v_csku text; v_a int; v_l int; v_pp int; v_tgt uuid; v_nm text;
BEGIN
  SELECT id INTO v_kid FROM products WHERE sku=p_sku AND is_kit=true;
  IF v_kid IS NULL THEN RAISE EXCEPTION 'kit % nao encontrado', p_sku; END IF;
  SELECT count(*) INTO v_ncomp FROM product_kit_components WHERE kit_product_id=v_kid;
  IF v_ncomp<>1 THEN RAISE EXCEPTION 'kit % tem % componentes (esperado 1)', p_sku, v_ncomp; END IF;

  SELECT id, slot_code, is_packaging, component_sku INTO v_ph_id, v_ph_slot, v_ph_pkg, v_ph_sku
  FROM product_kit_components WHERE kit_product_id=v_kid;
  v_phnum := (substring(v_ph_slot from 2))::int;

  v_ic := (regexp_match(v_ph_sku, '^'||p_sku||'-([0-9.]+)-(K|E)[0-9]+$'))[1];
  IF v_ic IS NULL THEN
    v_ic := (regexp_match(v_ph_sku, '^'||p_sku||'-([A-Za-z]{2,6})$'))[1];
    v_legacy := (v_ic IS NOT NULL);
  END IF;
  IF v_ic IS NULL THEN RAISE EXCEPTION 'internal_code/cor nao extraivel do sku % - defer manual', v_ph_sku; END IF;

  FOR r IN
    SELECT s.id sid, s.piece_label, s.source_url, s.dim_a_mm, s.dim_l_mm, s.dim_p_mm, fn_norm_piece_label(s.piece_label) pnorm
    FROM kit_component_ficha_staging s
    WHERE s.product_sku=p_sku AND s.piece_label NOT LIKE '\_\_%'
      AND s.match_status IN ('no_component','ambiguous','pending')
    ORDER BY (CASE WHEN fn_norm_piece_label(s.piece_label) ~ '(maleta|estojo|necessaire|pouch|bolsa|sacola|caixa)' THEN 1 ELSE 0 END), s.id
  LOOP
    v_kind := CASE WHEN r.pnorm ~ '(maleta|estojo|necessaire|pouch|bolsa|sacola|caixa)' THEN 'packaging' ELSE 'item' END;
    v_type := CASE
      WHEN r.pnorm ~ 'faca' THEN 'FACA' WHEN r.pnorm ~ 'tabua' THEN 'TABUA'
      WHEN r.pnorm ~ 'garfo' THEN 'GARFO' WHEN r.pnorm ~ 'espatula' THEN 'ESPATULA'
      WHEN r.pnorm ~ '(colher|concha|escumadeira)' THEN 'COLHER' WHEN r.pnorm ~ 'pegador' THEN 'PEGADOR'
      WHEN r.pnorm ~ 'pincel' THEN 'PINCEL' WHEN r.pnorm ~ '(caderno|caderneta)' THEN 'CADERNO'
      WHEN r.pnorm ~ 'caneta' THEN 'CANETA' WHEN r.pnorm ~ 'copo' THEN 'COPO'
      WHEN r.pnorm ~ 'caneca' THEN 'CANECA' WHEN r.pnorm ~ 'garrafa' THEN 'GARRAFA'
      WHEN r.pnorm ~ 'chaveiro' THEN 'CHAVEIRO' WHEN r.pnorm ~ 'porta ?cart' THEN 'PORTA_CARTAO'
      WHEN r.pnorm ~ 'tesoura' THEN 'TESOURA' WHEN r.pnorm ~ 'canudo' THEN 'CANUDO'
      WHEN r.pnorm ~ 'frasco' THEN 'FRASCO' WHEN r.pnorm ~ 'pote' THEN 'POTE'
      WHEN r.pnorm ~ 'bandeja' THEN 'BANDEJA' WHEN r.pnorm ~ 'squeeze' THEN 'SQUEEZE'
      WHEN r.pnorm ~ 'coquetel' THEN 'COQUETELEIRA' WHEN r.pnorm ~ 'saca.?rolha' THEN 'SACA_ROLHAS'
      WHEN r.pnorm ~ 'dosador' THEN 'BICO_DOSADOR' WHEN r.pnorm ~ 'socador' THEN 'SOCADOR'
      WHEN r.pnorm ~ 'escova' THEN 'ESCOVA' WHEN r.pnorm ~ 'xicara' THEN 'XICARA'
      WHEN r.pnorm ~ 'pires' THEN 'PIRES' WHEN r.pnorm ~ '(taca|taça)' THEN 'TACA_VINHO'
      WHEN r.pnorm ~ 'chaira' THEN 'CHAIRA' WHEN r.pnorm ~ 'avental' THEN 'AVENTAL'
      WHEN r.pnorm ~ 'necessaire' THEN 'NECESSAIRE' WHEN r.pnorm ~ 'fone' THEN 'FONE'
      WHEN r.pnorm ~ 'mochila' THEN 'MOCHILA' WHEN r.pnorm ~ 'caixa' THEN 'CAIXA'
      WHEN r.pnorm ~ 'anel' THEN 'ANEL_SALVA_GOTAS' WHEN r.pnorm ~ 'tampa' THEN 'TAMPA'
      WHEN r.pnorm ~ 'porta ?copo' THEN 'TAMPA' WHEN r.pnorm ~ 'marmita' THEN 'POTE'
      ELSE NULL END;
    v_a := CASE WHEN r.dim_a_mm BETWEEN 1 AND 1500 THEN r.dim_a_mm END;
    v_l := CASE WHEN r.dim_l_mm BETWEEN 1 AND 1500 THEN r.dim_l_mm END;
    v_pp := CASE WHEN r.dim_p_mm BETWEEN 1 AND 1500 THEN r.dim_p_mm END;
    v_nm := left(initcap(r.piece_label), 80);

    IF v_kind='item' THEN
      IF (NOT v_ph_pkg) AND (NOT v_first_item) THEN
        slot:=v_ph_slot; acao:='UPDATE placeholder->item'; v_tgt:=v_ph_id; v_first_item:=true; v_kidx:=greatest(v_kidx,v_phnum);
        IF NOT p_dry THEN
          UPDATE product_kit_components SET component_name=v_nm, component_type_code=v_type,
                 component_code=CASE WHEN v_legacy THEN p_sku||'-'||v_ph_slot ELSE component_code END,
                 component_sku =CASE WHEN v_legacy THEN p_sku||'-'||v_ic||'-'||v_ph_slot ELSE component_sku END,
                 height_mm=v_a, width_mm=v_l, length_mm=v_pp, dim_source='ficha', dim_source_url=r.source_url WHERE id=v_ph_id;
          UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_ph_id, product_id=v_kid,
                 piece_kind='item', piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='decomp:placeholder' WHERE id=r.sid;
        END IF;
      ELSE
        v_kidx:=v_kidx+1; IF (NOT v_ph_pkg) AND v_kidx=v_phnum THEN v_kidx:=v_kidx+1; END IF;
        slot:='K'||v_kidx; acao:='INSERT item'; v_code:=p_sku||'-'||slot; v_csku:=p_sku||'-'||v_ic||'-'||slot;
        IF NOT p_dry THEN
          INSERT INTO product_kit_components(kit_product_id,component_name,component_type_code,slot_code,component_code,component_sku,
            is_packaging,quantity,is_standalone_sellable,height_mm,width_mm,length_mm,dim_source,dim_source_url)
          VALUES (v_kid,v_nm,v_type,slot,v_code,v_csku,false,1,false,v_a,v_l,v_pp,'ficha',r.source_url) RETURNING id INTO v_tgt;
          UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_tgt, product_id=v_kid,
                 piece_kind='item', piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='decomp:novo' WHERE id=r.sid;
        END IF;
      END IF;
    ELSE
      IF v_ph_pkg AND (NOT v_first_pkg) THEN
        slot:=v_ph_slot; acao:='UPDATE placeholder->pkg'; v_tgt:=v_ph_id; v_first_pkg:=true; v_eidx:=greatest(v_eidx,v_phnum);
        IF NOT p_dry THEN
          UPDATE product_kit_components SET component_name=v_nm, component_type_code=coalesce(v_type,'CAIXA'),
                 component_code=CASE WHEN v_legacy THEN p_sku||'-'||v_ph_slot ELSE component_code END,
                 component_sku =CASE WHEN v_legacy THEN p_sku||'-'||v_ic||'-'||v_ph_slot ELSE component_sku END,
                 pkg_ext_height_mm=v_a, pkg_ext_width_mm=v_l, pkg_ext_length_mm=v_pp, dim_source='ficha', dim_source_url=r.source_url WHERE id=v_ph_id;
          UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_ph_id, product_id=v_kid,
                 piece_kind='packaging', piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='decomp:placeholder pkg' WHERE id=r.sid;
        END IF;
      ELSE
        v_eidx:=v_eidx+1; IF v_ph_pkg AND v_eidx=v_phnum THEN v_eidx:=v_eidx+1; END IF;
        slot:='E'||v_eidx; acao:='INSERT pkg'; v_code:=p_sku||'-'||slot; v_csku:=p_sku||'-'||v_ic||'-'||slot;
        IF NOT p_dry THEN
          INSERT INTO product_kit_components(kit_product_id,component_name,component_type_code,slot_code,component_code,component_sku,
            is_packaging,quantity,is_standalone_sellable,pkg_ext_height_mm,pkg_ext_width_mm,pkg_ext_length_mm,dim_source,dim_source_url)
          VALUES (v_kid,v_nm,coalesce(v_type,'CAIXA'),slot,v_code,v_csku,true,1,false,v_a,v_l,v_pp,'ficha',r.source_url) RETURNING id INTO v_tgt;
          UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_tgt, product_id=v_kid,
                 piece_kind='packaging', piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='decomp:novo pkg' WHERE id=r.sid;
        END IF;
      END IF;
    END IF;

    tipo:=v_type; nome:=v_nm; a:=v_a; l:=v_l; p:=v_pp; RETURN NEXT;
  END LOOP;
END $$;;

-- <<< END 20260624204942_decompose_fn_support_legacy_colorcode.sql <<<

-- >>> BEGIN 20260624205756_create_fn_kit_from_ficha.sql >>>
CREATE OR REPLACE FUNCTION public.fn_kit_from_ficha(p_sku text, p_dry boolean DEFAULT true)
RETURNS TABLE(acao text, slot text, nome text, tipo text, a int, l int, p int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public, extensions AS $$
DECLARE
  v_kid uuid; v_ic text; v_ncomp int; r record; v_kidx int:=0; v_eidx int:=0;
  v_kind text; v_type text; v_a int; v_l int; v_pp int; v_tgt uuid; v_nm text; v_slot text; v_npieces int;
BEGIN
  SELECT id INTO v_kid FROM products WHERE sku=p_sku;
  IF v_kid IS NULL THEN RAISE EXCEPTION 'produto % nao encontrado', p_sku; END IF;
  SELECT count(*) INTO v_ncomp FROM product_kit_components WHERE kit_product_id=v_kid;
  IF v_ncomp>0 THEN RAISE EXCEPTION 'produto % ja tem % componentes', p_sku, v_ncomp; END IF;
  SELECT count(*) INTO v_npieces FROM kit_component_ficha_staging s
   WHERE s.product_sku=p_sku AND s.piece_label NOT LIKE '\_\_%' AND s.match_status IN ('no_component','ambiguous','pending');
  IF v_npieces<2 THEN RAISE EXCEPTION 'produto % tem so % pecas (<2)', p_sku, v_npieces; END IF;

  SELECT cv.internal_code INTO v_ic FROM product_variants v JOIN color_variations cv ON cv.id=v.color_id
   WHERE v.product_id=v_kid AND cv.internal_code IS NOT NULL AND cv.internal_code<>'' ORDER BY v.id LIMIT 1;

  IF NOT p_dry THEN UPDATE products SET is_kit=true WHERE id=v_kid AND is_kit=false; END IF;

  FOR r IN
    SELECT s.id sid, s.piece_label, s.source_url, s.dim_a_mm, s.dim_l_mm, s.dim_p_mm, fn_norm_piece_label(s.piece_label) pnorm
    FROM kit_component_ficha_staging s
    WHERE s.product_sku=p_sku AND s.piece_label NOT LIKE '\_\_%' AND s.match_status IN ('no_component','ambiguous','pending')
    ORDER BY (CASE WHEN fn_norm_piece_label(s.piece_label) ~ '(maleta|estojo|necessaire|pouch|bolsa|sacola|caixa)' THEN 1 ELSE 0 END), s.id
  LOOP
    v_kind := CASE WHEN r.pnorm ~ '(maleta|estojo|necessaire|pouch|bolsa|sacola|caixa)' THEN 'packaging' ELSE 'item' END;
    v_type := CASE
      WHEN r.pnorm ~ 'faca' THEN 'FACA' WHEN r.pnorm ~ 'tabua' THEN 'TABUA'
      WHEN r.pnorm ~ 'garfo' THEN 'GARFO' WHEN r.pnorm ~ 'espatula' THEN 'ESPATULA'
      WHEN r.pnorm ~ '(colher|concha|escumadeira)' THEN 'COLHER' WHEN r.pnorm ~ 'pegador' THEN 'PEGADOR'
      WHEN r.pnorm ~ 'pincel' THEN 'PINCEL' WHEN r.pnorm ~ '(caderno|caderneta)' THEN 'CADERNO'
      WHEN r.pnorm ~ 'caneta' THEN 'CANETA' WHEN r.pnorm ~ 'copo' THEN 'COPO'
      WHEN r.pnorm ~ 'caneca' THEN 'CANECA' WHEN r.pnorm ~ 'garrafa' THEN 'GARRAFA'
      WHEN r.pnorm ~ 'chaveiro' THEN 'CHAVEIRO' WHEN r.pnorm ~ 'porta ?cart' THEN 'PORTA_CARTAO'
      WHEN r.pnorm ~ 'tesoura' THEN 'TESOURA' WHEN r.pnorm ~ 'canudo' THEN 'CANUDO'
      WHEN r.pnorm ~ 'frasco' THEN 'FRASCO' WHEN r.pnorm ~ 'pote' THEN 'POTE'
      WHEN r.pnorm ~ 'bandeja' THEN 'BANDEJA' WHEN r.pnorm ~ 'squeeze' THEN 'SQUEEZE'
      WHEN r.pnorm ~ 'coquetel' THEN 'COQUETELEIRA' WHEN r.pnorm ~ 'saca.?rolha' THEN 'SACA_ROLHAS'
      WHEN r.pnorm ~ 'dosador' THEN 'BICO_DOSADOR' WHEN r.pnorm ~ 'socador' THEN 'SOCADOR'
      WHEN r.pnorm ~ 'escova' THEN 'ESCOVA' WHEN r.pnorm ~ 'xicara' THEN 'XICARA'
      WHEN r.pnorm ~ 'pires' THEN 'PIRES' WHEN r.pnorm ~ '(taca|taça)' THEN 'TACA_VINHO'
      WHEN r.pnorm ~ 'chaira' THEN 'CHAIRA' WHEN r.pnorm ~ 'avental' THEN 'AVENTAL'
      WHEN r.pnorm ~ 'necessaire' THEN 'NECESSAIRE' WHEN r.pnorm ~ 'fone' THEN 'FONE'
      WHEN r.pnorm ~ 'mochila' THEN 'MOCHILA' WHEN r.pnorm ~ 'caixa' THEN 'CAIXA'
      WHEN r.pnorm ~ 'anel' THEN 'ANEL_SALVA_GOTAS' WHEN r.pnorm ~ 'tampa' THEN 'TAMPA'
      WHEN r.pnorm ~ 'taca' THEN 'TACA_VINHO' WHEN r.pnorm ~ 'abridor' THEN 'SACA_ROLHAS'
      ELSE NULL END;
    v_a := CASE WHEN r.dim_a_mm BETWEEN 1 AND 1500 THEN r.dim_a_mm END;
    v_l := CASE WHEN r.dim_l_mm BETWEEN 1 AND 1500 THEN r.dim_l_mm END;
    v_pp := CASE WHEN r.dim_p_mm BETWEEN 1 AND 1500 THEN r.dim_p_mm END;
    v_nm := left(initcap(r.piece_label), 80);

    IF v_kind='item' THEN v_kidx:=v_kidx+1; v_slot:='K'||v_kidx; acao:='INSERT item';
    ELSE v_eidx:=v_eidx+1; v_slot:='E'||v_eidx; acao:='INSERT pkg'; END IF;

    IF NOT p_dry THEN
      IF v_kind='item' THEN
        INSERT INTO product_kit_components(kit_product_id,component_name,component_type_code,slot_code,component_code,component_sku,
          is_packaging,quantity,is_standalone_sellable,height_mm,width_mm,length_mm,dim_source,dim_source_url)
        VALUES (v_kid,v_nm,v_type,v_slot,p_sku||'-'||v_slot, CASE WHEN v_ic IS NOT NULL THEN p_sku||'-'||v_ic||'-'||v_slot END,
                false,1,false,v_a,v_l,v_pp,'ficha',r.source_url) RETURNING id INTO v_tgt;
      ELSE
        INSERT INTO product_kit_components(kit_product_id,component_name,component_type_code,slot_code,component_code,component_sku,
          is_packaging,quantity,is_standalone_sellable,pkg_ext_height_mm,pkg_ext_width_mm,pkg_ext_length_mm,dim_source,dim_source_url)
        VALUES (v_kid,v_nm,coalesce(v_type,'CAIXA'),v_slot,p_sku||'-'||v_slot, CASE WHEN v_ic IS NOT NULL THEN p_sku||'-'||v_ic||'-'||v_slot END,
                true,1,false,v_a,v_l,v_pp,'ficha',r.source_url) RETURNING id INTO v_tgt;
      END IF;
      UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_tgt, product_id=v_kid,
             piece_kind=v_kind, piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='kit_from_ficha' WHERE id=r.sid;
    END IF;

    slot:=v_slot; tipo:=v_type; nome:=v_nm; a:=v_a; l:=v_l; p:=v_pp; RETURN NEXT;
  END LOOP;
END $$;;

-- <<< END 20260624205756_create_fn_kit_from_ficha.sql <<<

-- >>> BEGIN 20260624205955_kit_from_ficha_v2_fixes.sql >>>
CREATE OR REPLACE FUNCTION public.fn_kit_from_ficha(p_sku text, p_dry boolean DEFAULT true)
RETURNS TABLE(acao text, slot text, nome text, tipo text, a int, l int, p int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public, extensions AS $$
DECLARE
  v_kid uuid; v_ic text; v_ncomp int; r record; v_kidx int:=0; v_eidx int:=0;
  v_kind text; v_type text; v_a int; v_l int; v_pp int; v_tgt uuid; v_nm text; v_slot text; v_npieces int;
BEGIN
  SELECT id INTO v_kid FROM products WHERE sku=p_sku;
  IF v_kid IS NULL THEN RAISE EXCEPTION 'produto % nao encontrado', p_sku; END IF;
  SELECT count(*) INTO v_ncomp FROM product_kit_components WHERE kit_product_id=v_kid;
  IF v_ncomp>0 THEN RAISE EXCEPTION 'produto % ja tem % componentes', p_sku, v_ncomp; END IF;
  SELECT count(*) INTO v_npieces FROM kit_component_ficha_staging s
   WHERE s.product_sku=p_sku AND s.piece_label NOT LIKE '\_\_%' AND s.match_status IN ('no_component','ambiguous','pending')
     AND fn_norm_piece_label(s.piece_label) !~ '^(kit|conjunto|jogo completo)( |$)';
  IF v_npieces<2 THEN RAISE EXCEPTION 'produto % tem so % pecas reais (<2)', p_sku, v_npieces; END IF;

  SELECT cv.internal_code INTO v_ic FROM product_variants v JOIN color_variations cv ON cv.id=v.color_id
   WHERE v.product_id=v_kid AND cv.internal_code IS NOT NULL AND cv.internal_code<>'' ORDER BY v.id LIMIT 1;

  IF NOT p_dry THEN UPDATE products SET is_kit=true WHERE id=v_kid AND is_kit=false; END IF;

  FOR r IN
    SELECT s.id sid, s.piece_label, s.source_url, s.dim_a_mm, s.dim_l_mm, s.dim_p_mm, fn_norm_piece_label(s.piece_label) pnorm
    FROM kit_component_ficha_staging s
    WHERE s.product_sku=p_sku AND s.piece_label NOT LIKE '\_\_%' AND s.match_status IN ('no_component','ambiguous','pending')
    ORDER BY (CASE WHEN fn_norm_piece_label(s.piece_label) ~ '(maleta|estojo|necessaire|pouch|bolsa|sacola|caixa|embalagem)' THEN 1 ELSE 0 END), s.id
  LOOP
    -- pula linhas-resumo do kit inteiro (nao sao componentes)
    IF r.pnorm ~ '^(kit|conjunto|jogo completo)( |$)' THEN
      IF NOT p_dry THEN UPDATE kit_component_ficha_staging SET match_status='skipped', piece_norm=r.pnorm,
        product_id=v_kid, notes='linha resumo do kit (nao e componente)' WHERE id=r.sid; END IF;
      CONTINUE;
    END IF;

    v_kind := CASE WHEN r.pnorm ~ '(maleta|estojo|necessaire|pouch|bolsa|sacola|caixa|embalagem)' THEN 'packaging' ELSE 'item' END;
    v_type := CASE
      WHEN r.pnorm ~ 'faca' THEN 'FACA' WHEN r.pnorm ~ 'tabua' THEN 'TABUA'
      WHEN r.pnorm ~ 'garfo' THEN 'GARFO' WHEN r.pnorm ~ 'espatula' THEN 'ESPATULA'
      WHEN r.pnorm ~ '(colher|concha|escumadeira)' THEN 'COLHER' WHEN r.pnorm ~ 'pegador' THEN 'PEGADOR'
      WHEN r.pnorm ~ 'pincel' THEN 'PINCEL' WHEN r.pnorm ~ '(caderno|caderneta)' THEN 'CADERNO'
      WHEN r.pnorm ~ 'caneta' THEN 'CANETA' WHEN r.pnorm ~ 'copo' THEN 'COPO'
      WHEN r.pnorm ~ 'caneca' THEN 'CANECA' WHEN r.pnorm ~ 'garrafa' THEN 'GARRAFA'
      WHEN r.pnorm ~ 'chaveiro' THEN 'CHAVEIRO' WHEN r.pnorm ~ 'porta ?cart' THEN 'PORTA_CARTAO'
      WHEN r.pnorm ~ 'tesoura' THEN 'TESOURA' WHEN r.pnorm ~ 'canudo' THEN 'CANUDO'
      WHEN r.pnorm ~ 'frasco' THEN 'FRASCO' WHEN r.pnorm ~ 'pote' THEN 'POTE'
      WHEN r.pnorm ~ 'bandeja' THEN 'BANDEJA' WHEN r.pnorm ~ 'squeeze' THEN 'SQUEEZE'
      WHEN r.pnorm ~ 'coquetel' THEN 'COQUETELEIRA' WHEN r.pnorm ~ 'saca.?rolha' THEN 'SACA_ROLHAS'
      WHEN r.pnorm ~ 'dosador' THEN 'BICO_DOSADOR' WHEN r.pnorm ~ 'socador' THEN 'SOCADOR'
      WHEN r.pnorm ~ 'escova' THEN 'ESCOVA' WHEN r.pnorm ~ 'xicara' THEN 'XICARA'
      WHEN r.pnorm ~ 'pires' THEN 'PIRES' WHEN r.pnorm ~ '(taca|taça)' THEN 'TACA_VINHO'
      WHEN r.pnorm ~ 'chaira' THEN 'CHAIRA' WHEN r.pnorm ~ 'avental' THEN 'AVENTAL'
      WHEN r.pnorm ~ 'necessaire' THEN 'NECESSAIRE' WHEN r.pnorm ~ 'fone' THEN 'FONE'
      WHEN r.pnorm ~ 'mochila' THEN 'MOCHILA' WHEN r.pnorm ~ 'caixa' THEN 'CAIXA'
      WHEN r.pnorm ~ 'anel' THEN 'ANEL_SALVA_GOTAS' WHEN r.pnorm ~ 'tampa' THEN 'TAMPA'
      WHEN r.pnorm ~ 'abridor' THEN 'SACA_ROLHAS' WHEN r.pnorm ~ 'termometro' THEN 'TERMOMETRO'
      ELSE NULL END;
    v_a := CASE WHEN r.dim_a_mm BETWEEN 1 AND 1500 THEN r.dim_a_mm END;
    v_l := CASE WHEN r.dim_l_mm BETWEEN 1 AND 1500 THEN r.dim_l_mm END;
    v_pp := CASE WHEN r.dim_p_mm BETWEEN 1 AND 1500 THEN r.dim_p_mm END;
    -- limpa cauda de medida que ficou no rotulo (ex.: "Caderneta 21,2 cm x 15,")
    v_nm := left(initcap(btrim(regexp_replace(r.piece_label, '\s+[0-9]+([.,][0-9]+)?\s*cm\s*[x×].*$', '', 'i'))), 80);
    IF length(v_nm)<2 THEN v_nm := left(initcap(r.piece_label),80); END IF;

    IF v_kind='item' THEN v_kidx:=v_kidx+1; v_slot:='K'||v_kidx; acao:='INSERT item';
    ELSE v_eidx:=v_eidx+1; v_slot:='E'||v_eidx; acao:='INSERT pkg'; END IF;

    IF NOT p_dry THEN
      IF v_kind='item' THEN
        INSERT INTO product_kit_components(kit_product_id,component_name,component_type_code,slot_code,component_code,component_sku,
          is_packaging,quantity,is_standalone_sellable,height_mm,width_mm,length_mm,dim_source,dim_source_url)
        VALUES (v_kid,v_nm,v_type,v_slot,p_sku||'-'||v_slot, CASE WHEN v_ic IS NOT NULL THEN p_sku||'-'||v_ic||'-'||v_slot END,
                false,1,false,v_a,v_l,v_pp,'ficha',r.source_url) RETURNING id INTO v_tgt;
      ELSE
        INSERT INTO product_kit_components(kit_product_id,component_name,component_type_code,slot_code,component_code,component_sku,
          is_packaging,quantity,is_standalone_sellable,pkg_ext_height_mm,pkg_ext_width_mm,pkg_ext_length_mm,dim_source,dim_source_url)
        VALUES (v_kid,v_nm,coalesce(v_type,'CAIXA'),v_slot,p_sku||'-'||v_slot, CASE WHEN v_ic IS NOT NULL THEN p_sku||'-'||v_ic||'-'||v_slot END,
                true,1,false,v_a,v_l,v_pp,'ficha',r.source_url) RETURNING id INTO v_tgt;
      END IF;
      UPDATE kit_component_ficha_staging SET match_status='promoted', matched_component_id=v_tgt, product_id=v_kid,
             piece_kind=v_kind, piece_norm=r.pnorm, match_confidence=1.0, promoted_at=now(), notes='kit_from_ficha' WHERE id=r.sid;
    END IF;

    slot:=v_slot; tipo:=v_type; nome:=v_nm; a:=v_a; l:=v_l; p:=v_pp; RETURN NEXT;
  END LOOP;
END $$;;

