-- >>> BEGIN 20260625000001_restore_products_category_name.sql >>>
-- =============================================================================
-- FIX: Restaurar products.category_name (BUG 400 em quoteService.ts:98)
-- Root cause: migrações 20260519163704 e 20260519164522 registradas com
-- statements:[] — ALTER TABLE nunca executou em produção.
-- Impacto: GET /products?select=id,category_id,category_name → HTTP 400
-- Detectado via console do browser em 2026-06-25.
-- Validado: 7/7 checks PASS, trigger funcional, zero divergências.
-- =============================================================================

-- PASSO 1: Adicionar coluna (idempotente)
ALTER TABLE public.products
  ADD COLUMN IF NOT EXISTS category_name TEXT;

COMMENT ON COLUMN public.products.category_name IS
  'Cache desnormalizado de categories.name via category_id. '
  'Mantido sincronizado por trg_sync_product_category_name. '
  'Restaurado em 2026-06-25 após migrations 20260519163704/164522 '
  'não terem executado em produção (statements:[]).';

-- PASSO 2: Backfill completo (IS DISTINCT FROM = idempotente)
UPDATE public.products p
SET category_name = c.name
FROM public.categories c
WHERE c.id = p.category_id
  AND p.category_name IS DISTINCT FROM c.name;

-- PASSO 3: Trigger function para manter sincronizado
CREATE OR REPLACE FUNCTION public.fn_sync_product_category_name()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public
AS $$
BEGIN
  IF NEW.category_id IS NULL THEN
    NEW.category_name := NULL;
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' OR (NEW.category_id IS DISTINCT FROM OLD.category_id) THEN
    SELECT name INTO NEW.category_name
    FROM public.categories
    WHERE id = NEW.category_id;
  END IF;
  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.fn_sync_product_category_name() IS
  'Mantém products.category_name sincronizado com categories.name '
  'quando category_id muda. Instalado por migration 20260625000001.';

-- PASSO 4: Instalar trigger
DROP TRIGGER IF EXISTS trg_sync_product_category_name ON public.products;
CREATE TRIGGER trg_sync_product_category_name
  BEFORE INSERT OR UPDATE OF category_id
  ON public.products
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_sync_product_category_name();

-- PASSO 5: Recarregar schema cache do PostgREST
NOTIFY pgrst, 'reload schema';

-- <<< END 20260625000001_restore_products_category_name.sql <<<

-- >>> BEGIN 20260625103741_add_weight_material_source_columns.sql >>>
-- MELHORIA 1: rastreabilidade de procedência de peso e material
ALTER TABLE public.product_kit_components
  ADD COLUMN IF NOT EXISTS weight_source varchar(30)
    CHECK (weight_source IN ('measured_real','inherited_total','estimated_heuristic','supplier_api','manual')),
  ADD COLUMN IF NOT EXISTS material_source varchar(30)
    CHECK (material_source IN ('ficha','heuristic_type','heuristic_name','supplier_api','manual'));

COMMENT ON COLUMN public.product_kit_components.weight_source IS
  'Procedência do peso por peça: measured_real=medido na ficha técnica; inherited_total=copiado do peso total do produto-pai (NÃO é o peso real da peça); estimated_heuristic=estimativa heurística por volume/proporção; supplier_api=dado estruturado do fornecedor; manual=revisado/corrigido manualmente.';

COMMENT ON COLUMN public.product_kit_components.material_source IS
  'Procedência do material: ficha=ficha técnica verificada; heuristic_type=inferido do component_type_code via kit_component_types; heuristic_name=inferido por keywords do nome do componente; supplier_api=dado estruturado do fornecedor; manual=revisado manualmente.';;

-- <<< END 20260625103741_add_weight_material_source_columns.sql <<<

-- >>> BEGIN 20260625104036_fix_enrich_status_exclude_inherited_weight.sql >>>
-- MELHORIA 3: enrichment_status não conta peso inherited_total como dado real
CREATE OR REPLACE FUNCTION public.fn_pkc_auto_enrich_status()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $function$
DECLARE
  v_has_dims       BOOLEAN;
  v_has_all        BOOLEAN;
  v_real_weight    BOOLEAN;  -- peso real: excluí inherited_total (copiado do total do produto-pai)
BEGIN
  -- circunferência a partir do diâmetro (lógica original preservada)
  IF NEW.shape_type = 'cylindrical' AND NEW.diameter_mm IS NOT NULL
     AND (NEW.circumference_mm IS NULL OR (TG_OP='UPDATE' AND OLD.diameter_mm IS DISTINCT FROM NEW.diameter_mm))
  THEN NEW.circumference_mm := ROUND(PI() * NEW.diameter_mm);
  END IF;

  -- peso "real" = preenchido E NÃO é herança do total do produto-pai
  v_real_weight := (NEW.weight_g IS NOT NULL
    AND coalesce(NEW.weight_source, 'estimated_heuristic') <> 'inherited_total');

  IF NEW.is_packaging = TRUE THEN
    v_has_all  := (NEW.pkg_ext_length_mm IS NOT NULL
                   AND NEW.pkg_ext_width_mm  IS NOT NULL
                   AND NEW.pkg_ext_height_mm IS NOT NULL
                   AND v_real_weight);
    v_has_dims := (NEW.pkg_ext_length_mm IS NOT NULL
                   AND NEW.pkg_ext_width_mm  IS NOT NULL
                   AND NEW.pkg_ext_height_mm IS NOT NULL)
               OR NEW.length_mm IS NOT NULL;
  ELSE
    CASE COALESCE(NEW.shape_type, 'rectangular')
      WHEN 'cylindrical' THEN
        v_has_all  := NEW.diameter_mm IS NOT NULL AND NEW.height_mm IS NOT NULL AND v_real_weight;
        v_has_dims := NEW.diameter_mm IS NOT NULL OR NEW.height_mm IS NOT NULL;
      WHEN 'flat' THEN
        v_has_all  := NEW.length_mm IS NOT NULL AND NEW.width_mm IS NOT NULL AND v_real_weight;
        v_has_dims := NEW.length_mm IS NOT NULL OR v_real_weight;
      WHEN 'spherical' THEN
        v_has_all  := NEW.diameter_mm IS NOT NULL AND v_real_weight;
        v_has_dims := NEW.diameter_mm IS NOT NULL;
      ELSE -- rectangular: weight não é requisito para 'complete' (exige 3 dims)
        v_has_all  := NEW.length_mm IS NOT NULL AND NEW.width_mm IS NOT NULL AND NEW.height_mm IS NOT NULL;
        v_has_dims := NEW.length_mm IS NOT NULL OR v_real_weight OR NEW.diameter_mm IS NOT NULL;
    END CASE;
  END IF;

  NEW.enrichment_status := CASE
    WHEN v_has_all  THEN 'complete'
    WHEN v_has_dims THEN 'partial'
    ELSE 'missing'
  END;
  RETURN NEW;
END;
$function$;;

-- <<< END 20260625104036_fix_enrich_status_exclude_inherited_weight.sql <<<

