-- >>> BEGIN 20260625153327_mask_cost_price_anon_vw_product_novelties_active.sql >>>
-- SEGURANCA: vw_product_novelties_active expunha cost_price REAL para anon (vitrine publica).
-- Mascara fail-safe por papel: revela custo so p/ authenticated/service_role; anon recebe NULL.
-- Mantem acesso anon aos demais campos (nao quebra a vitrine). ANTI-REGRESSAO: preservar o CASE.
CREATE OR REPLACE VIEW public.vw_product_novelties_active AS
 SELECT pn.id AS novelty_id, pn.product_id, pn.supplier_id, pn.supplier_code, pn.supplier_product_code,
    pn.source, pn.detected_at, pn.expires_at, pn.is_active, pn.is_highlighted, pn.notes,
    pn.created_at AS novelty_created_at, pn.updated_at AS novelty_updated_at,
    p.name AS product_name, p.sku AS product_sku, p.supplier_reference, p.primary_image_url, p.sale_price,
    (CASE WHEN auth.role() = ANY (ARRAY['authenticated'::text,'service_role'::text]) THEN p.cost_price ELSE NULL::numeric END)::numeric(10,2) AS cost_price,
    p.stock_quantity, p.is_active AS product_active, p.is_stockout, p.created_at AS product_created_at,
    CASE WHEN pn.expires_at IS NULL THEN NULL::integer ELSE EXTRACT(day FROM pn.expires_at - now())::integer END AS days_remaining,
    CASE WHEN pn.expires_at IS NOT NULL AND (pn.expires_at - now()) < '7 days'::interval THEN true ELSE false END AS expiring_soon
   FROM product_novelties pn
     JOIN products p ON p.id = pn.product_id
  WHERE pn.is_active = true AND (pn.expires_at IS NULL OR pn.expires_at > now()) AND p.is_active = true AND p.is_stockout = false AND p.sale_price IS NOT NULL AND p.sale_price > 0::numeric AND p.primary_image_url IS NOT NULL AND p.primary_image_url <> ''::text;;

-- <<< END 20260625153327_mask_cost_price_anon_vw_product_novelties_active.sql <<<

-- >>> BEGIN 20260625153447_mask_cost_price_anon_vw_product_notebook_complete.sql >>>
-- SEGURANCA: vw_product_notebook_complete expunha cost_price REAL para anon.
-- Mascara fail-safe por papel (revela so authenticated/service_role). GROUP BY mantido (p.cost_price segue agrupado).
-- ANTI-REGRESSAO: preservar o CASE na coluna cost_price.
CREATE OR REPLACE VIEW public.vw_product_notebook_complete AS
 SELECT p.id AS product_id, p.name AS product_name, p.sku,
    (CASE WHEN auth.role() = ANY (ARRAY['authenticated'::text,'service_role'::text]) THEN p.cost_price ELSE NULL::numeric END)::numeric(10,2) AS cost_price,
    p.is_active, s.name AS supplier_name, pf.code AS format_code, pf.name AS format_name, pf.width_cm, pf.height_cm,
    pr.code AS ruling_code, pr.name AS ruling_name, pw.weight_gsm, pw.description AS weight_description,
    pc.code AS paper_color_code, pc.name AS paper_color_name, pns.sheet_count, bt.code AS binding_code, bt.name_pt AS binding_name,
    bc.code AS binding_color_code, bc.name AS binding_color_name, ct.code AS cover_type_code, ct.name AS cover_type_name,
    cm.code AS cover_material_code, cm.name AS cover_material_name, cm.is_eco_friendly, cf.code AS cover_finish_code, cf.name AS cover_finish_name,
    pns.source_supplier, pns.confidence_score, pns.manually_reviewed, pns.created_at AS spec_created_at, pns.updated_at AS spec_updated_at,
    COALESCE(array_agg(nf.code ORDER BY nf.display_order) FILTER (WHERE nf.code IS NOT NULL), ARRAY[]::text[]::character varying[]) AS feature_codes,
    COALESCE(array_agg(nf.name ORDER BY nf.display_order) FILTER (WHERE nf.name IS NOT NULL), ARRAY[]::text[]::character varying[]) AS feature_names
   FROM products p
     JOIN suppliers s ON s.id = p.supplier_id
     JOIN product_notebook_specs pns ON pns.product_id = p.id
     LEFT JOIN paper_formats pf ON pf.id = pns.paper_format_id
     LEFT JOIN paper_rulings pr ON pr.id = pns.paper_ruling_id
     LEFT JOIN paper_weights pw ON pw.id = pns.paper_weight_id
     LEFT JOIN paper_colors pc ON pc.id = pns.paper_color_id
     LEFT JOIN binding_types bt ON bt.id = pns.binding_type_id
     LEFT JOIN binding_colors bc ON bc.id = pns.binding_color_id
     LEFT JOIN cover_types ct ON ct.id = pns.cover_type_id
     LEFT JOIN cover_materials cm ON cm.id = pns.cover_material_id
     LEFT JOIN cover_finishes cf ON cf.id = pns.cover_finish_id
     LEFT JOIN product_notebook_features pnf ON pnf.product_id = p.id
     LEFT JOIN notebook_features nf ON nf.id = pnf.feature_id
  GROUP BY p.id, p.name, p.sku, p.cost_price, p.is_active, s.name, pf.code, pf.name, pf.width_cm, pf.height_cm, pr.code, pr.name, pw.weight_gsm, pw.description, pc.code, pc.name, pns.sheet_count, bt.code, bt.name_pt, bc.code, bc.name, ct.code, ct.name, cm.code, cm.name, cm.is_eco_friendly, cf.code, cf.name, pns.source_supplier, pns.confidence_score, pns.manually_reviewed, pns.created_at, pns.updated_at;;

-- <<< END 20260625153447_mask_cost_price_anon_vw_product_notebook_complete.sql <<<

-- >>> BEGIN 20260625153536_mask_cost_price_anon_vw_products_packaging_info.sql >>>
-- SEGURANCA: vw_products_packaging_info expunha cost_price REAL para anon.
-- Mascara fail-safe por papel (revela so authenticated/service_role). ANTI-REGRESSAO: preservar o CASE.
CREATE OR REPLACE VIEW public.vw_products_packaging_info AS
 SELECT p.id, p.sku, p.supplier_reference, p.name, p.product_type, p.shape_type,
    p.height_cm, p.width_cm, p.length_cm, p.diameter_cm, p.weight_g,
    CASE p.shape_type
        WHEN 'cylindrical'::text THEN ((('ø'::text || COALESCE(p.diameter_cm::text, '?'::text)) || 'x'::text) || COALESCE(p.height_cm::text, '?'::text)) || 'cm'::text
        ELSE ((((COALESCE(p.width_cm::text, '?'::text) || 'x'::text) || COALESCE(p.height_cm::text, '?'::text)) || 'x'::text) || COALESCE(p.length_cm::text, '?'::text)) || 'cm'::text
    END AS dimensoes,
    (EXISTS ( SELECT 1 FROM product_included_packagings pip WHERE pip.product_id = p.id AND pip.active = true)) AS tem_embalagem_inclusa,
    ( SELECT count(*) AS count FROM product_included_packagings pip WHERE pip.product_id = p.id AND pip.active = true) AS qtd_inclusas,
    ( SELECT count(*) AS count FROM product_packaging_compatibility ppc WHERE ppc.product_id = p.id AND ppc.active = true) AS qtd_compativeis,
    p.supplier_id, s.name AS fornecedor,
    (CASE WHEN auth.role() = ANY (ARRAY['authenticated'::text,'service_role'::text]) THEN p.cost_price ELSE NULL::numeric END)::numeric(10,2) AS cost_price,
    p.is_active AS active
   FROM products p
     LEFT JOIN suppliers s ON s.id = p.supplier_id
  WHERE p.product_type = 'product'::text;;

