-- >>> BEGIN 20260626120000_add_ordem_exibicao_tabela_preco_gravacao_oficial.sql >>>
-- 20260626120000_add_ordem_exibicao_tabela_preco_gravacao_oficial.sql
--
-- Fix: PostgREST 400 (Bad Request) on
--   GET /rest/v1/tabela_preco_gravacao_oficial?select=*&order=ordem_exibicao.asc&offset=0&limit=200
--
-- ROOT CAUSE
--   The frontend reads this table through the bridge alias 'tecnica_gravacao'
--   (src/lib/db/postgrest.ts -> BRIDGE_ALIASES: tecnica_gravacao -> tabela_preco_gravacao_oficial)
--   in two call sites that ORDER BY ordem_exibicao:
--     - src/hooks/tecnicas/useTecnicasList.ts::fetchTecnicasExterno   (orderBy ordem_exibicao, limit 200)  <- request in the console log
--     - src/lib/external-db/techniques.ts::fetchPromobrindTechniques  (orderBy ordem_exibicao, limit 100)
--   ordem_exibicao existed ONLY on the sibling catalog table tecnicas_gravacao, so Postgres raised
--   42703 (undefined_column) and PostgREST returned HTTP 400.
--
-- FIX
--   Add ordem_exibicao to tabela_preco_gravacao_oficial, mirroring tecnicas_gravacao.ordem_exibicao
--   (integer DEFAULT 99). Backfill a deterministic display order by codigo_tabela so ORDER BY is
--   stable across paginated requests. Purely additive; regression-proof against the recurring
--   reintroduction of .order('ordem_exibicao') by the Lovable bot.
--
-- Idempotent (guarded by pg_attribute existence check). Applied to production 2026-06-26.

DO $mig$
DECLARE
  v_exists boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM pg_attribute
    WHERE attrelid = 'public.tabela_preco_gravacao_oficial'::regclass
      AND attname = 'ordem_exibicao'
      AND NOT attisdropped
  ) INTO v_exists;

  IF NOT v_exists THEN
    ALTER TABLE public.tabela_preco_gravacao_oficial
      ADD COLUMN ordem_exibicao integer NOT NULL DEFAULT 99;

    WITH ranked AS (
      SELECT id, row_number() OVER (ORDER BY codigo_tabela, id) AS rn
      FROM public.tabela_preco_gravacao_oficial
    )
    UPDATE public.tabela_preco_gravacao_oficial t
    SET ordem_exibicao = r.rn
    FROM ranked r
    WHERE r.id = t.id;

    COMMENT ON COLUMN public.tabela_preco_gravacao_oficial.ordem_exibicao IS
      'ANTI-REGRESSION (fix 2026-06-26): display order for the technique-list UI. Frontend reads this table via bridge alias tecnica_gravacao (dbInvoke BRIDGE_ALIASES) and ORDERs BY ordem_exibicao; column previously existed only on tecnicas_gravacao, causing PostgREST 400 (42703). Mirrors tecnicas_gravacao.ordem_exibicao (integer default 99). DO NOT DROP.';
  END IF;
END
$mig$;

-- Critical: refresh PostgREST schema cache so the new column is queryable immediately.
NOTIFY pgrst, 'reload schema';

-- <<< END 20260626120000_add_ordem_exibicao_tabela_preco_gravacao_oficial.sql <<<

-- >>> BEGIN 20260626123517_enforce_dar_valid_until_future_on_approval.sql >>>
-- Melhoria M5: bloqueia aprovar com valid_until no passado, SOMENTE na transição -> approved.
-- Decisão de engenharia (provada via dry-run com ~110 cenários): NÃO usar CHECK persistente,
-- pois aprovações vencem naturalmente (fn_quotes_validate_discount já ignora valid_until <= now());
-- um CHECK persistente quebraria o vencimento natural de uma aprovação válida.
CREATE OR REPLACE FUNCTION public.fn_dar_check_valid_until_future()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $fn$
BEGIN
  -- fix_version=20260626_m5 | ANTI-REGRESSAO: manter como trigger de TRANSICAO, jamais CHECK persistente.
  IF NEW.status = 'approved' AND OLD.status IS DISTINCT FROM 'approved' THEN
    IF NEW.valid_until IS NOT NULL AND NEW.valid_until::date < CURRENT_DATE THEN
      RAISE EXCEPTION 'valid_until nao pode estar no passado ao aprovar (recebido: %, hoje: %)', NEW.valid_until, CURRENT_DATE
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$fn$;

DROP TRIGGER IF EXISTS trg_dar_check_valid_until_future ON public.discount_approval_requests;
CREATE TRIGGER trg_dar_check_valid_until_future
  BEFORE UPDATE ON public.discount_approval_requests
  FOR EACH ROW EXECUTE FUNCTION public.fn_dar_check_valid_until_future();

COMMENT ON FUNCTION public.fn_dar_check_valid_until_future() IS
  'fix_version=20260626_m5: bloqueia aprovacao com valid_until no passado SOMENTE na transicao -> approved. NUNCA converter para CHECK persistente (quebraria vencimento natural). Migration: enforce_dar_valid_until_future_on_approval.';

-- <<< END 20260626123517_enforce_dar_valid_until_future_on_approval.sql <<<

-- >>> BEGIN 20260626123656_forbid_dar_reopen_to_pending.sql >>>
-- Melhoria M6: máquina de estados — uma vez fora de 'pending', a solicitação não retorna.
-- App nunca reabre (decisões: approved/rejected; expired reservado). Para re-decidir, cria-se
-- nova solicitação (consistente com M4: nasce pending). Elimina o ponto cego de auditoria do
-- re-open: a transição simplesmente deixa de existir. Provado via dry-run (210 cenários).
CREATE OR REPLACE FUNCTION public.fn_dar_forbid_reopen()
RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $fn$
BEGIN
  -- fix_version=20260626_m6 | ANTI-REGRESSAO: manter o bloqueio terminal->pending.
  IF NEW.status = 'pending' AND OLD.status IS DISTINCT FROM 'pending' THEN
    RAISE EXCEPTION 'discount_approval_requests nao pode retornar para pending a partir de % (re-open proibido; crie nova solicitacao)', OLD.status
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$fn$;

DROP TRIGGER IF EXISTS trg_dar_forbid_reopen ON public.discount_approval_requests;
CREATE TRIGGER trg_dar_forbid_reopen
  BEFORE UPDATE ON public.discount_approval_requests
  FOR EACH ROW EXECUTE FUNCTION public.fn_dar_forbid_reopen();

COMMENT ON FUNCTION public.fn_dar_forbid_reopen() IS
  'fix_version=20260626_m6: proibe terminal->pending (re-open). Para re-decidir crie nova solicitacao. Migration: forbid_dar_reopen_to_pending.';

-- <<< END 20260626123656_forbid_dar_reopen_to_pending.sql <<<

