-- >>> BEGIN 20260626124204_fn_spr_before_write_status_on_gold_link.sql >>>
-- ============================================================================
-- Melhoria 1/4 — Invariante de processamento no Bronze
-- fix_version = 2026-06-26_status_on_link
-- Torna a coluna supplier_products_raw.status confiável para TODOS os
-- fornecedores: no instante em que a linha Bronze é vinculada a um produto
-- Gold (product_id NULL->NOT NULL), o status passa a 'processed'.
-- Resolve o drift histórico em que XBZ/Só Marcas promoviam por caminho
-- próprio sem atualizar o status canônico.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.fn_spr_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_clean    jsonb;
  v_hashbase jsonb;
  v_excl     text[];
  v_k        text;
BEGIN
  IF NEW.raw_data ? '_source' AND COALESCE(NEW.source_channel,'') IN ('','n8n','legacy') THEN
    NEW.source_channel := NEW.raw_data->>'_source';
  END IF;
  IF NEW.raw_data ? '_imported_at' AND NEW.imported_at IS NULL THEN
    BEGIN NEW.imported_at := (NEW.raw_data->>'_imported_at')::timestamptz;
    EXCEPTION WHEN others THEN NULL; END;
  END IF;

  -- Remove chaves de controle (prefixo '_') do payload antes de hashear/persistir.
  -- (Hardening 2026-06-26: left(k,1)='_' substitui LIKE E'\\_%' — semântica idêntica, sem ambiguidade de escape.)
  v_clean := NEW.raw_data;
  FOR v_k IN SELECT k FROM jsonb_object_keys(NEW.raw_data) k WHERE left(k,1) = '_' LOOP
    v_clean := v_clean - v_k;
  END LOOP;
  NEW.raw_data := v_clean;

  SELECT ss.hash_excluded_fields INTO v_excl
    FROM public.supplier_settings ss
   WHERE ss.supplier_id = NEW.supplier_id;
  v_hashbase := CASE WHEN v_excl IS NOT NULL AND array_length(v_excl,1) > 0
                     THEN v_clean - v_excl ELSE v_clean END;
  NEW.content_hash := encode(extensions.digest(v_hashbase::text, 'sha256'), 'hex');

  IF TG_OP = 'INSERT' THEN
    NEW.imported_at := COALESCE(NEW.imported_at, now());
    IF NEW.process_errors IS NOT NULL AND NEW.last_error IS NULL THEN
      NEW.last_error := NEW.process_errors;
    END IF;
  ELSE
    NEW.updated_at := now();

    IF NEW.process_errors IS DISTINCT FROM OLD.process_errors
       AND NEW.process_errors IS NOT NULL THEN
      NEW.last_error := NEW.process_errors;
      NEW.attempts   := COALESCE(OLD.attempts, 0) + 1;
      IF NEW.status <> 'processed'::supplier_raw_status THEN
        NEW.status := CASE WHEN NEW.attempts >= 5
                           THEN 'quarantined'::supplier_raw_status
                           ELSE 'failed'::supplier_raw_status END;
      END IF;
    END IF;

    -- ════════════════════════════════════════════════════════════════════
    -- INVARIANTE DE PROCESSAMENTO (fix_version=2026-06-26_status_on_link)
    -- ANTI-REGRESSÃO (Lovable bot): NÃO REMOVER ESTE BLOCO.
    -- Assim que product_id passa de NULL->NOT NULL, a linha está promovida
    -- ao Gold => processed. Dispara 1x por linha (primeira promoção) e NÃO
    -- interfere em reprocesso (reprocesso nunca volta product_id para NULL).
    -- ════════════════════════════════════════════════════════════════════
    IF NEW.product_id IS NOT NULL AND OLD.product_id IS NULL
       AND NEW.status IN ('pending'::supplier_raw_status,'processing'::supplier_raw_status) THEN
      NEW.status := 'processed'::supplier_raw_status;
    END IF;

    IF NEW.status = 'processed'::supplier_raw_status
       AND NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.processed_at := COALESCE(NEW.processed_at, now());
    END IF;
  END IF;

  RETURN NEW;
END $function$;;

-- <<< END 20260626124204_fn_spr_before_write_status_on_gold_link.sql <<<

-- >>> BEGIN 20260626124225_add_is_primary_color_equivalences_resolution.sql >>>
-- ============================================================================
-- MELHORIA 1/3 — Resolucao deterministica de cor de fornecedor -> variacao Ouro
-- Camada: PRATA (color_equivalences). Resolve mapeamento ambiguo (1 cor->N variacoes)
-- ANTI-REGRESSAO (Lovable bot): NAO remover a coluna is_primary nem o indice
--   uq_color_equivalences_one_primary. Eles garantem 1 primaria ativa por cor.
-- fix_version: 2026-06-26_color_isprimary
-- ============================================================================

ALTER TABLE color_equivalences
  ADD COLUMN IF NOT EXISTS is_primary boolean NOT NULL DEFAULT false;

COMMENT ON COLUMN color_equivalences.is_primary IS
  'Equivalencia primaria/canonica desta supplier_color. Backfill por precedencia: '
  'match_quality(exact>close>approximate) > confidence_score DESC > internal_code num ASC > id. '
  'Garantido <=1 ativa por supplier_color via uq_color_equivalences_one_primary. '
  'fix_version 2026-06-26 - NAO REMOVER (anti-regressao).';

WITH ranked AS (
  SELECT ce.id,
    ROW_NUMBER() OVER (
      PARTITION BY ce.supplier_color_id
      ORDER BY
        (CASE ce.match_quality WHEN 'exact' THEN 1 WHEN 'close' THEN 2
                               WHEN 'approximate' THEN 3 ELSE 4 END) ASC,
        ce.confidence_score DESC NULLS LAST,
        COALESCE(NULLIF(split_part(cv.internal_code,'.',1),'')::int, 9999) ASC,
        COALESCE(NULLIF(split_part(cv.internal_code,'.',2),'')::int, 9999) ASC,
        ce.id ASC
    ) AS rn
  FROM color_equivalences ce
  JOIN color_variations cv ON cv.id = ce.promo_variation_id
  WHERE ce.is_active
)
UPDATE color_equivalences ce
SET is_primary = true
FROM ranked r
WHERE ce.id = r.id AND r.rn = 1;

CREATE UNIQUE INDEX IF NOT EXISTS uq_color_equivalences_one_primary
  ON color_equivalences (supplier_color_id)
  WHERE (is_primary AND is_active);

COMMENT ON INDEX uq_color_equivalences_one_primary IS
  'Garante <=1 equivalencia primaria ATIVA por supplier_color. fix_version 2026-06-26. NAO REMOVER.';

NOTIFY pgrst, 'reload schema';

-- <<< END 20260626124225_add_is_primary_color_equivalences_resolution.sql <<<

-- >>> BEGIN 20260626124226_melhoria1_sync_has_optional_packaging.sql >>>
-- ════════════════════════════════════════════════════════════════════════
-- MELHORIA 1: Sincronização canônica de products.has_optional_packaging
-- Definição: flag = (menção do fornecedor) OR (existe compat dimensional ativa)
-- Corrige 1.435 falsos-negativos (têm caixa, flag dizia não) e
--         1.347 falsos-positivos (polybag 'protective', sem evidência)
-- fix_version: 2026-06-26.m1 | ANTI-REGRESSÃO: não remover SET search_path
-- ════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION fn_recalc_has_optional_packaging(p_product_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  UPDATE products p
  SET has_optional_packaging = (
        COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
        OR p.optional_packaging_ref IS NOT NULL
        OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active)
      )
  WHERE p.id = p_product_id
    AND p.has_optional_packaging IS DISTINCT FROM (
        COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
        OR p.optional_packaging_ref IS NOT NULL
        OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active)
      );
END$$;
COMMENT ON FUNCTION fn_recalc_has_optional_packaging(uuid) IS
  'fix_version 2026-06-26.m1 — recalcula has_optional_packaging (menção OR compat ativa). Mantém SET search_path=public.';

CREATE OR REPLACE FUNCTION fn_trg_compat_sync_optional()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF TG_OP='DELETE' THEN
    PERFORM fn_recalc_has_optional_packaging(OLD.product_id); RETURN OLD;
  ELSE
    PERFORM fn_recalc_has_optional_packaging(NEW.product_id);
    IF TG_OP='UPDATE' AND NEW.product_id IS DISTINCT FROM OLD.product_id THEN
      PERFORM fn_recalc_has_optional_packaging(OLD.product_id);
    END IF;
    RETURN NEW;
  END IF;
END$$;
COMMENT ON FUNCTION fn_trg_compat_sync_optional() IS
  'fix_version 2026-06-26.m1 — mantém products.has_optional_packaging sincronizada com compat. Mantém SET search_path=public.';

REVOKE EXECUTE ON FUNCTION fn_recalc_has_optional_packaging(uuid) FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION fn_trg_compat_sync_optional() FROM PUBLIC, anon;

DROP TRIGGER IF EXISTS trg_compat_sync_optional ON product_packaging_compatibility;
CREATE TRIGGER trg_compat_sync_optional
AFTER INSERT OR UPDATE OR DELETE ON product_packaging_compatibility
FOR EACH ROW EXECUTE FUNCTION fn_trg_compat_sync_optional();

-- Backfill canônico (set-based)
UPDATE products p
SET has_optional_packaging = (
      COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
      OR p.optional_packaging_ref IS NOT NULL
      OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active)
    )
WHERE p.product_type IN ('product','kit')
  AND p.has_optional_packaging IS DISTINCT FROM (
      COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
      OR p.optional_packaging_ref IS NOT NULL
      OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active)
    );;

-- <<< END 20260626124226_melhoria1_sync_has_optional_packaging.sql <<<

