-- >>> BEGIN 20260626124626_mod03_backfill_auto_material_and_missing_materials.sql >>>
-- ============================================================================
-- Módulo 03 (Materiais) — Backfill alinhado ao pipeline Bronze->Prata->Ouro
-- A2: insere material normalizado p/ 2 produtos ativos sem material
--     (o extrator de nome não reconhece "Caderno"->Papel nem "plástica"->Plástico;
--      provado via fn_extract_material_from_name() => []). Inserimos na fonte de
--      verdade (product_materials) e os triggers cascateiam materials + auto_material.
-- A1: recomputa auto_material para a "dívida de derivação" (322 produtos com
--     product_materials ativo porém auto_material NULL, pois a lógica de auto_material
--     foi adicionada à fn_sync depois). Usa a MESMA regra do trigger:
--     material dominante por percentage DESC NULLS LAST, sort_order ASC.
--     Não altera 'materials' => WHEN dos triggers de extração ficam falsos => sem cascata.
-- Guard: bulk_import_mode=true (defense-in-depth contra cascata reversa).
-- fix_version: 2026-06-26-mod03-backfill
-- ============================================================================
SELECT set_config('app.bulk_import_mode', 'true', true);

-- A2 ------------------------------------------------------------------------
INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, sort_order, is_active)
SELECT p.organization_id, p.id, v.mat_id, 'corpo', 100, 1, true
FROM products p
JOIN (VALUES
  ('15466F',  '5d1195c5-2f09-4403-b9dc-b3db0ad0f30f'::uuid),   -- Caderno -> Papel Genérico
  ('P@13190C','e0a1a83e-7ea7-41c8-87f9-87b2ad85be9e'::uuid)    -- Caneta plástica -> Plástico Genérico
) AS v(sku, mat_id) ON v.sku = p.sku_promo
WHERE p.is_active
  AND NOT EXISTS (SELECT 1 FROM product_materials pm WHERE pm.product_id = p.id AND pm.is_active);

-- A1 ------------------------------------------------------------------------
WITH dom AS (
  SELECT p.id AS pid,
         (SELECT mt.name
            FROM product_materials pm
            JOIN material_types mt ON mt.id = pm.material_id
           WHERE pm.product_id = p.id AND pm.is_active
           ORDER BY pm.percentage DESC NULLS LAST, pm.sort_order ASC
           LIMIT 1) AS primary_mat
  FROM products p
  WHERE p.auto_material IS NULL
    AND EXISTS (SELECT 1 FROM product_materials pm WHERE pm.product_id = p.id AND pm.is_active)
)
UPDATE products p
   SET auto_material = dom.primary_mat,
       updated_at    = now()
  FROM dom
 WHERE p.id = dom.pid
   AND dom.primary_mat IS NOT NULL;;

-- <<< END 20260626124626_mod03_backfill_auto_material_and_missing_materials.sql <<<

-- >>> BEGIN 20260626124627_sync_color_variations_dual_fk_and_notnull.sql >>>
-- ============================================================================
-- MELHORIA 2/3 — Elimina debito da dupla FK em color_variations (camada OURO)
-- group_id (legado, NOT NULL) e color_group_id (canonico) sao espelhados por
-- trigger BEFORE: preenche o que falta, propaga update de coluna unica e BLOQUEIA
-- divergencia genuina. color_group_id passa a NOT NULL.
-- ANTI-REGRESSAO (Lovable bot): NAO remover fn_sync_color_variation_group nem o
--   trigger trg_sync_color_variation_group; NAO reverter color_group_id p/ NULLABLE.
-- fix_version: 2026-06-26_color_dualfk_sync
-- ============================================================================

CREATE OR REPLACE FUNCTION fn_sync_color_variation_group()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public           -- anti-regressao: NAO remover search_path
AS $fn$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.color_group_id IS DISTINCT FROM OLD.color_group_id
       AND NEW.group_id IS NOT DISTINCT FROM OLD.group_id THEN
      NEW.group_id := NEW.color_group_id;           -- canonico mudou -> espelha legado
    ELSIF NEW.group_id IS DISTINCT FROM OLD.group_id
       AND NEW.color_group_id IS NOT DISTINCT FROM OLD.color_group_id THEN
      NEW.color_group_id := NEW.group_id;           -- legado mudou -> espelha canonico
    END IF;
  END IF;
  IF NEW.color_group_id IS NULL AND NEW.group_id IS NOT NULL THEN
    NEW.color_group_id := NEW.group_id;
  ELSIF NEW.group_id IS NULL AND NEW.color_group_id IS NOT NULL THEN
    NEW.group_id := NEW.color_group_id;
  ELSIF NEW.group_id IS NOT NULL AND NEW.color_group_id IS NOT NULL
        AND NEW.group_id <> NEW.color_group_id THEN
    RAISE EXCEPTION 'color_variations: group_id(%) <> color_group_id(%) — divergencia bloqueada (fn_sync_color_variation_group)',
      NEW.group_id, NEW.color_group_id;
  END IF;
  RETURN NEW;
END;
$fn$;

COMMENT ON FUNCTION fn_sync_color_variation_group() IS
  'Mantem group_id (legado) e color_group_id (canonico) sempre identicos em color_variations. '
  'fix_version 2026-06-26 - anti-regressao, NAO REMOVER.';

DROP TRIGGER IF EXISTS trg_sync_color_variation_group ON color_variations;
CREATE TRIGGER trg_sync_color_variation_group
  BEFORE INSERT OR UPDATE OF group_id, color_group_id ON color_variations
  FOR EACH ROW EXECUTE FUNCTION fn_sync_color_variation_group();

ALTER TABLE color_variations ALTER COLUMN color_group_id SET NOT NULL;

NOTIFY pgrst, 'reload schema';

