-- >>> BEGIN 20260626134648_fn_spr_before_write_reland_guard.sql >>>
-- Melhoria 1/4 (reparo durável) — RE-LAND GUARD por content_hash.
-- fix_version=2026-06-26_status_reland_guard
-- Problema observado: re-ingestão Só Marcas re-enfileirou ~1.296 linhas JÁ
-- vinculadas ao Gold de volta para status='pending'. O invariante de 1ª
-- vinculação (product_id NULL->NOT NULL) não cobre re-land de linha já vinculada.
-- Solução: se a linha já tem product_id, está indo para 'pending' e o conteúdo
-- NÃO mudou (content_hash inalterado), trata-se de re-enqueue espúrio de pipeline
-- que não consome 'status' (XBZ/Só Marcas) => mantém 'processed'. Quando o
-- conteúdo MUDA (hash difere), 'pending' é respeitado (reprocesso real STRICKER/ASIA).
CREATE OR REPLACE FUNCTION public.fn_spr_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_clean    jsonb;
  v_hashbase jsonb;
  v_excl     text[];
  v_k        text;
BEGIN
  IF NEW.raw_data ? '_source' AND COALESCE(NEW.source_channel,'') IN ('','n8n','legacy') THEN
    NEW.source_channel := NEW.raw_data->>'_source';
  END IF;
  IF NEW.raw_data ? '_imported_at' AND NEW.imported_at IS NULL THEN
    BEGIN NEW.imported_at := (NEW.raw_data->>'_imported_at')::timestamptz;
    EXCEPTION WHEN others THEN NULL; END;
  END IF;

  -- Remove chaves de controle (prefixo '_') antes de hashear/persistir.
  v_clean := NEW.raw_data;
  FOR v_k IN SELECT k FROM jsonb_object_keys(NEW.raw_data) k WHERE left(k,1) = '_' LOOP
    v_clean := v_clean - v_k;
  END LOOP;
  NEW.raw_data := v_clean;

  SELECT ss.hash_excluded_fields INTO v_excl
    FROM public.supplier_settings ss
   WHERE ss.supplier_id = NEW.supplier_id;
  v_hashbase := CASE WHEN v_excl IS NOT NULL AND array_length(v_excl,1) > 0
                     THEN v_clean - v_excl ELSE v_clean END;
  NEW.content_hash := encode(extensions.digest(v_hashbase::text, 'sha256'), 'hex');

  IF TG_OP = 'INSERT' THEN
    NEW.imported_at := COALESCE(NEW.imported_at, now());
    IF NEW.process_errors IS NOT NULL AND NEW.last_error IS NULL THEN
      NEW.last_error := NEW.process_errors;
    END IF;
  ELSE
    NEW.updated_at := now();

    IF NEW.process_errors IS DISTINCT FROM OLD.process_errors
       AND NEW.process_errors IS NOT NULL THEN
      NEW.last_error := NEW.process_errors;
      NEW.attempts   := COALESCE(OLD.attempts, 0) + 1;
      IF NEW.status <> 'processed'::supplier_raw_status THEN
        NEW.status := CASE WHEN NEW.attempts >= 5
                           THEN 'quarantined'::supplier_raw_status
                           ELSE 'failed'::supplier_raw_status END;
      END IF;
    END IF;

    -- ════════════════════════════════════════════════════════════════════
    -- INVARIANTE DE PROCESSAMENTO — 1ª VINCULAÇÃO (fix_version=2026-06-26_status_on_link)
    -- ANTI-REGRESSÃO (Lovable bot): NÃO REMOVER.
    -- product_id NULL->NOT NULL => linha promovida ao Gold => processed.
    -- ════════════════════════════════════════════════════════════════════
    IF NEW.product_id IS NOT NULL AND OLD.product_id IS NULL
       AND NEW.status IN ('pending'::supplier_raw_status,'processing'::supplier_raw_status) THEN
      NEW.status := 'processed'::supplier_raw_status;
    END IF;

    -- ════════════════════════════════════════════════════════════════════
    -- RE-LAND GUARD (fix_version=2026-06-26_status_reland_guard)
    -- ANTI-REGRESSÃO (Lovable bot): NÃO REMOVER.
    -- Linha já vinculada (product_id NOT NULL) re-marcada 'pending' SEM mudança
    -- de conteúdo (content_hash inalterado) = re-enqueue espúrio de pipeline que
    -- não consome 'status' (XBZ/Só Marcas) => mantém 'processed'.
    -- Se o conteúdo MUDOU (hash difere), respeita 'pending' (reprocesso real).
    -- ════════════════════════════════════════════════════════════════════
    IF NEW.product_id IS NOT NULL
       AND NEW.status = 'pending'::supplier_raw_status
       AND NEW.content_hash IS NOT DISTINCT FROM OLD.content_hash THEN
      NEW.status := 'processed'::supplier_raw_status;
    END IF;

    IF NEW.status = 'processed'::supplier_raw_status
       AND NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.processed_at := COALESCE(NEW.processed_at, now());
    END IF;
  END IF;

  RETURN NEW;
END $function$;;

-- <<< END 20260626134648_fn_spr_before_write_reland_guard.sql <<<

-- >>> BEGIN 20260626134734_rebackfill_bronze_status_after_reland_guard.sql >>>
-- Melhoria 1/4 (reparo durável) — re-backfill dos falsos-pendentes (re-land SM).
-- Linhas já vinculadas ao Gold (product_id) e processadas antes (processed_at)
-- presas em 'pending' por re-enqueue espúrio. O re-land guard (já aplicado)
-- impede recorrência no momento da ingestão.
UPDATE public.supplier_products_raw
   SET status = 'processed'
 WHERE status = 'pending'
   AND product_id IS NOT NULL
   AND processed_at IS NOT NULL;;

-- <<< END 20260626134734_rebackfill_bronze_status_after_reland_guard.sql <<<

-- >>> BEGIN 20260626134930_harden_validate_material_percentages_onconflict_safe.sql >>>
-- ENDURECIMENTO M3: validate_material_percentages bloqueava falsamente um
-- INSERT ... ON CONFLICT (product_id, material_id) DO NOTHING/UPDATE quando o par ja existia
-- COM percentage preenchido (somava a linha que iria colidir + a nova proposta = >100).
-- Correcao: em INSERT, excluir da soma a linha do MESMO material_id (que colidiria pela UNIQUE
-- global product_id+material_id); em UPDATE, manter exclusao por id. Premissa garantida pela
-- UNIQUE (product_id, material_id) ser GLOBAL -> mesmo material nunca em 2 partes (0 casos).
-- Mantem TODAS as protecoes: estouro por material novo, update que estoura, NULL-safe por parte.
-- ANTI-REGRESSAO: preservar o CASE TG_OP na exclusao.
CREATE OR REPLACE FUNCTION public.validate_material_percentages()
 RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public'
AS $function$
DECLARE total_percentage DECIMAL;
BEGIN
  SELECT COALESCE(SUM(percentage),0) INTO total_percentage
  FROM product_materials
  WHERE product_id = NEW.product_id
    AND organization_id = NEW.organization_id
    AND part IS NOT DISTINCT FROM NEW.part
    AND is_active = true
    AND (
      CASE WHEN TG_OP = 'UPDATE' THEN id <> NEW.id
           ELSE material_id <> NEW.material_id
      END
    );
  IF total_percentage + COALESCE(NEW.percentage, 0) > 100 THEN
    RAISE EXCEPTION 'Total de percentuais da parte "%" excede 100%% (atual: %, novo: %)',
      COALESCE(NEW.part,'(sem parte)'), total_percentage, NEW.percentage;
  END IF;
  RETURN NEW;
END;
$function$;;

-- <<< END 20260626134930_harden_validate_material_percentages_onconflict_safe.sql <<<

-- >>> BEGIN 20260626134951_mod03_reconcile_jsonb_richer_than_normalized.sql >>>
-- Reconciliacao Modulo 03: jsonb mais rico que normalizado (MV800P, BAC003P)
-- Reconstroi product_materials a partir do jsonb (fonte mais completa), distribuicao uniforme.
SELECT set_config('app.bulk_import_mode','true', true);

UPDATE product_materials
   SET is_active = false, updated_at = now()
 WHERE is_active = true
   AND product_id IN (SELECT id FROM products WHERE sku_promo IN ('MV800P','BAC003P'));

WITH tgt AS (
  SELECT id AS product_id, organization_id, materials
  FROM products WHERE sku_promo IN ('MV800P','BAC003P')
),
resolved AS (
  SELECT t.product_id, t.organization_id,
         public.fn_find_material_type_id(e.name) AS type_id,
         min(e.ord) AS ord
  FROM tgt t,
       LATERAL jsonb_array_elements_text(t.materials) WITH ORDINALITY AS e(name, ord)
  WHERE public.fn_find_material_type_id(e.name) IS NOT NULL
  GROUP BY t.product_id, t.organization_id, public.fn_find_material_type_id(e.name)
),
counted AS (
  SELECT r.*,
         count(*)     OVER (PARTITION BY product_id)            AS n,
         row_number() OVER (PARTITION BY product_id ORDER BY ord) AS rn
  FROM resolved r
)
INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, sort_order, notes, is_active)
SELECT organization_id, product_id, type_id, 'corpo',
       round(100.0 / n, 2), rn::int, 'reconc mod03 2026-06-26', true
FROM counted
ON CONFLICT (product_id, material_id) DO UPDATE SET
  is_active       = true,
  part            = 'corpo',
  percentage      = EXCLUDED.percentage,
  sort_order      = EXCLUDED.sort_order,
  notes           = EXCLUDED.notes,
  organization_id = EXCLUDED.organization_id,
  updated_at      = now();;

-- <<< END 20260626134951_mod03_reconcile_jsonb_richer_than_normalized.sql <<<

-- >>> BEGIN 20260626135003_packaging_reclassify_by_profile_v1.sql >>>
-- ════════════════════════════════════════════════════════════════════
-- MELHORIA 2 (parte B): reclassificar 8.987 compat por perfil inferido
-- + refinar flag (so conta compat COMPATIVEL) + re-eleger is_recommended
-- fix_version=2026-06-26_perfis_v1
-- ════════════════════════════════════════════════════════════════════

-- Flag: so conta compat com rating compativel (tight/good/loose)
CREATE OR REPLACE FUNCTION public.fn_trigger_set_has_optional_packaging()
 RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $function$
BEGIN
  -- ANTI-REGRESSAO(canonical_v2): inclui compat COMPATIVEL (rating tight/good/loose). Nao remover.
  NEW.has_optional_packaging :=
        COALESCE((NEW.description_packaging_info->>'has_optional_mention')::boolean,false)
        OR NEW.optional_packaging_ref IS NOT NULL OR NEW.packing_classification = 'protective'
        OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id = NEW.id AND c.active AND c.fit_rating IN ('tight','good','loose'));
  RETURN NEW;
END;$function$;

CREATE OR REPLACE FUNCTION public.fn_recalc_has_optional_packaging(p_product_id uuid)
 RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$
BEGIN
  UPDATE products p SET has_optional_packaging = (
        COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
        OR p.optional_packaging_ref IS NOT NULL OR p.packing_classification='protective'
        OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active AND c.fit_rating IN ('tight','good','loose')))
  WHERE p.id=p_product_id AND p.has_optional_packaging IS DISTINCT FROM (
        COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
        OR p.optional_packaging_ref IS NOT NULL OR p.packing_classification='protective'
        OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active AND c.fit_rating IN ('tight','good','loose')));
END$function$;

-- Reclassificar rating + config_type por perfil (max=50 p/ todos)
WITH lim AS (SELECT ppc.id, fn_infer_packaging_config_type(ppc.product_id) AS perfil, ppc.fit_gap_min_mm AS gmin, ppc.needs_padding FROM product_packaging_compatibility ppc WHERE ppc.active=true),
final AS (SELECT id, perfil,
    CASE WHEN gmin IS NULL THEN NULL
      WHEN gmin < 0 OR gmin < (CASE perfil WHEN 'bottles' THEN 3 WHEN 'fragile' THEN 5 WHEN 'precision' THEN 1 ELSE 2 END) THEN 'too_tight'
      WHEN gmin <= (CASE perfil WHEN 'bottles' THEN 8 WHEN 'fragile' THEN 10 WHEN 'precision' THEN 3 ELSE 5 END) THEN 'tight'
      WHEN gmin <= (CASE perfil WHEN 'bottles' THEN 20 WHEN 'fragile' THEN 20 WHEN 'precision' THEN 8 ELSE 15 END) THEN 'good'
      WHEN gmin <= 50 THEN 'loose' ELSE 'too_large' END AS nr0, needs_padding FROM lim),
fin2 AS (SELECT id, perfil, CASE WHEN needs_padding AND nr0 IN ('tight','good') THEN 'loose' ELSE nr0 END AS nr FROM final)
UPDATE product_packaging_compatibility ppc SET fit_rating=f.nr, config_type_used=f.perfil
FROM fin2 f WHERE ppc.id=f.id AND (ppc.fit_rating IS DISTINCT FROM f.nr OR ppc.config_type_used IS DISTINCT FROM f.perfil);

-- Re-eleger is_recommended (compativel ANTES de source)
WITH ranked AS (
  SELECT id, fit_rating, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY
      (fit_rating IN ('tight','good','loose')) DESC,
      CASE compatibility_source WHEN 'supplier_indicated' THEN 1 WHEN 'dimension_matching' THEN 2 WHEN 'dimension_calculated' THEN 3 ELSE 4 END,
      CASE fit_rating WHEN 'tight' THEN 1 WHEN 'good' THEN 2 WHEN 'loose' THEN 3 ELSE 4 END,
      COALESCE(fit_gap_min_mm,99999)) rn
  FROM product_packaging_compatibility WHERE active=true)
UPDATE product_packaging_compatibility ppc SET is_recommended=(r.rn=1 AND r.fit_rating IN ('tight','good','loose'))
FROM ranked r WHERE ppc.id=r.id AND ppc.is_recommended IS DISTINCT FROM (r.rn=1 AND r.fit_rating IN ('tight','good','loose'));

-- Re-backfill flag
UPDATE products p SET has_optional_packaging = (
      COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
      OR p.optional_packaging_ref IS NOT NULL OR p.packing_classification='protective'
      OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active AND c.fit_rating IN ('tight','good','loose')))
WHERE p.product_type IN ('product','kit') AND COALESCE(p.has_optional_packaging,false) IS DISTINCT FROM (
      COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
      OR p.optional_packaging_ref IS NOT NULL OR p.packing_classification='protective'
      OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active AND c.fit_rating IN ('tight','good','loose')));

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260626135003_packaging_reclassify_by_profile_v1.sql <<<

-- >>> BEGIN 20260626135209_packaging_ranking_null_safe_fix.sql >>>
-- MELHORIA 2 (fix ranking): NULL-safe — rankeia somente compat compativel,
-- evitando que registros manual com fit_rating NULL bloqueiem a eleicao.
-- fix_version=2026-06-26_perfis_v1
WITH ranked AS (
  SELECT id, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY
      CASE compatibility_source WHEN 'supplier_indicated' THEN 1 WHEN 'dimension_matching' THEN 2 WHEN 'dimension_calculated' THEN 3 ELSE 4 END,
      CASE fit_rating WHEN 'tight' THEN 1 WHEN 'good' THEN 2 WHEN 'loose' THEN 3 ELSE 4 END,
      COALESCE(fit_gap_min_mm,99999)) rn
  FROM product_packaging_compatibility WHERE active=true AND fit_rating IN ('tight','good','loose'))
UPDATE product_packaging_compatibility ppc SET is_recommended = COALESCE(r.rn=1,false)
FROM ranked r WHERE r.id=ppc.id AND ppc.is_recommended IS DISTINCT FROM COALESCE(r.rn=1,false);

UPDATE product_packaging_compatibility SET is_recommended=false
WHERE active AND is_recommended AND COALESCE(fit_rating,'x') NOT IN ('tight','good','loose');;

-- <<< END 20260626135209_packaging_ranking_null_safe_fix.sql <<<

