-- ════════════════════════════════════════════════════════════════════
-- MELHORIA 3: robustez
-- 3a updated_at em included_packaging_techniques + trigger
-- 3b validacao de hierarquia min<tight<good<=max na config EAV (statement-level)
-- 3c preencher os 3 registros manual com fit_rating NULL (recalculo)
-- fix_version=2026-06-26_robustness_v1
-- ════════════════════════════════════════════════════════════════════

-- 3a
ALTER TABLE included_packaging_techniques ADD COLUMN IF NOT EXISTS updated_at timestamptz DEFAULT now();
UPDATE included_packaging_techniques SET updated_at = created_at WHERE updated_at IS NULL OR updated_at < created_at;
DROP TRIGGER IF EXISTS set_updated_at_trigger ON included_packaging_techniques;
CREATE TRIGGER set_updated_at_trigger BEFORE UPDATE ON included_packaging_techniques FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- 3b
CREATE OR REPLACE FUNCTION public.fn_validate_packaging_config_hierarchy()
RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $function$
DECLARE v_bad TEXT;
BEGIN
  -- ANTI-REGRESSAO: garante hierarquia min<tight<good<=max por perfil na config EAV.
  WITH cfg AS (
    SELECT CASE WHEN config_key LIKE 'bottles%' THEN 'bottles' WHEN config_key LIKE 'fragile%' THEN 'fragile' WHEN config_key LIKE 'precision%' THEN 'precision' ELSE 'default' END AS perfil,
           CASE WHEN config_key LIKE '%min_gap_mm' THEN 'min' WHEN config_key LIKE '%tight%' THEN 'tight' WHEN config_key LIKE '%good%' THEN 'good' WHEN config_key LIKE '%max_gap_mm' THEN 'max' END AS lvl,
           config_value::numeric AS val
    FROM packaging_compatibility_config WHERE config_key ~ '(min_gap_mm|tight.*max|good.*max|max_gap_mm)'),
  piv AS (SELECT perfil, MAX(val) FILTER (WHERE lvl='min') vmin, MAX(val) FILTER (WHERE lvl='tight') vtight, MAX(val) FILTER (WHERE lvl='good') vgood, MAX(val) FILTER (WHERE lvl='max') vmax FROM cfg WHERE lvl IS NOT NULL GROUP BY perfil)
  SELECT string_agg(perfil,', ') INTO v_bad FROM piv WHERE NOT (vmin < vtight AND vtight < vgood AND vgood <= vmax);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'Hierarquia de folgas invalida (min<tight<good<=max) no(s) perfil(is): %', v_bad; END IF;
  RETURN NULL;
END$function$;
DROP TRIGGER IF EXISTS trg_validate_config_hierarchy ON packaging_compatibility_config;
CREATE TRIGGER trg_validate_config_hierarchy AFTER INSERT OR UPDATE OR DELETE ON packaging_compatibility_config FOR EACH STATEMENT EXECUTE FUNCTION fn_validate_packaging_config_hierarchy();

-- 3c
WITH calc AS (
  SELECT ppc.id, fn_infer_packaging_config_type(ppc.product_id) AS perfil,
         fn_calculate_packaging_fit(ppc.product_id, ppc.packaging_id, fn_infer_packaging_config_type(ppc.product_id)) AS fit
  FROM product_packaging_compatibility ppc WHERE ppc.fit_rating IS NULL AND ppc.active)
UPDATE product_packaging_compatibility ppc
SET fit_rating = NULLIF(c.fit->>'fit_rating','error'), config_type_used = c.perfil,
    fit_gap_min_mm = (c.fit->>'gap_min_mm')::numeric, fit_gap_avg_mm = (c.fit->>'gap_avg_mm')::numeric,
    fit_gap_height_mm = (c.fit->>'gap_height_mm')::numeric, fit_gap_width_mm = (c.fit->>'gap_width_mm')::numeric,
    fit_gap_length_mm = (c.fit->>'gap_length_mm')::numeric, fit_gap_diameter_mm = (c.fit->>'gap_diameter_mm')::numeric
FROM calc c WHERE ppc.id = c.id;

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260626141540_packaging_robustness_techniques_config_nulls.sql <<<

-- >>> BEGIN 20260626141713_fn_spr_before_write_guards_respect_errors.sql >>>
-- Melhoria 1/4 (hardening) — guards constraint-safe.
-- fix_version=2026-06-26_status_guards_respect_errors
-- Descoberto em teste: chk_spr_no_processed_with_errors proíbe processed+process_errors.
-- Os guards (1ª vinculação / re-land) NÃO devem forçar 'processed' enquanto houver
-- process_errors (senão violam o constraint e abortam o promote). Solução: só
-- auto-promover quando process_errors IS NULL. Respeita o estado de erro e preserva
-- a info do erro; o fix do re-drift SM permanece (aquelas linhas não têm erro).
CREATE OR REPLACE FUNCTION public.fn_spr_before_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_clean    jsonb;
  v_hashbase jsonb;
  v_excl     text[];
  v_k        text;
BEGIN
  IF NEW.raw_data ? '_source' AND COALESCE(NEW.source_channel,'') IN ('','n8n','legacy') THEN
    NEW.source_channel := NEW.raw_data->>'_source';
  END IF;
  IF NEW.raw_data ? '_imported_at' AND NEW.imported_at IS NULL THEN
    BEGIN NEW.imported_at := (NEW.raw_data->>'_imported_at')::timestamptz;
    EXCEPTION WHEN others THEN NULL; END;
  END IF;

  v_clean := NEW.raw_data;
  FOR v_k IN SELECT k FROM jsonb_object_keys(NEW.raw_data) k WHERE left(k,1) = '_' LOOP
    v_clean := v_clean - v_k;
  END LOOP;
  NEW.raw_data := v_clean;

  SELECT ss.hash_excluded_fields INTO v_excl
    FROM public.supplier_settings ss
   WHERE ss.supplier_id = NEW.supplier_id;
  v_hashbase := CASE WHEN v_excl IS NOT NULL AND array_length(v_excl,1) > 0
                     THEN v_clean - v_excl ELSE v_clean END;
  NEW.content_hash := encode(extensions.digest(v_hashbase::text, 'sha256'), 'hex');

  IF TG_OP = 'INSERT' THEN
    NEW.imported_at := COALESCE(NEW.imported_at, now());
    IF NEW.process_errors IS NOT NULL AND NEW.last_error IS NULL THEN
      NEW.last_error := NEW.process_errors;
    END IF;
  ELSE
    NEW.updated_at := now();

    IF NEW.process_errors IS DISTINCT FROM OLD.process_errors
       AND NEW.process_errors IS NOT NULL THEN
      NEW.last_error := NEW.process_errors;
      NEW.attempts   := COALESCE(OLD.attempts, 0) + 1;
      IF NEW.status <> 'processed'::supplier_raw_status THEN
        NEW.status := CASE WHEN NEW.attempts >= 5
                           THEN 'quarantined'::supplier_raw_status
                           ELSE 'failed'::supplier_raw_status END;
      END IF;
    END IF;

    -- INVARIANTE 1ª VINCULAÇÃO (fix_version=2026-06-26_status_on_link) — ANTI-REGRESSÃO: NÃO REMOVER.
    -- Só promove se não houver erro ativo (respeita chk_spr_no_processed_with_errors).
    IF NEW.product_id IS NOT NULL AND OLD.product_id IS NULL
       AND NEW.status IN ('pending'::supplier_raw_status,'processing'::supplier_raw_status)
       AND NEW.process_errors IS NULL THEN
      NEW.status := 'processed'::supplier_raw_status;
    END IF;

    -- RE-LAND GUARD (fix_version=2026-06-26_status_reland_guard) — ANTI-REGRESSÃO: NÃO REMOVER.
    -- Re-enqueue espúrio (linha já vinculada, conteúdo inalterado) e SEM erro ativo => processed.
    IF NEW.product_id IS NOT NULL
       AND NEW.status = 'pending'::supplier_raw_status
       AND NEW.content_hash IS NOT DISTINCT FROM OLD.content_hash
       AND NEW.process_errors IS NULL THEN
      NEW.status := 'processed'::supplier_raw_status;
    END IF;

    IF NEW.status = 'processed'::supplier_raw_status
       AND NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.processed_at := COALESCE(NEW.processed_at, now());
    END IF;
  END IF;

  RETURN NEW;
END $function$;;

-- <<< END 20260626141713_fn_spr_before_write_guards_respect_errors.sql <<<

