-- >>> BEGIN 20260626145051_fix_zero_dims_to_null_gold_quality_20260626.sql >>>
-- MELHORIA 1 (satélites/drift) — correção de qualidade no Ouro.
-- Contexto: 7 produtos ativos tinham height/width/length = 0.00 (lixo = "desconhecido"),
-- exibidos como "0 cm" via v_products_public. product_physical (satélite) já mantinha NULL
-- corretamente (fn_sync aplica NULLIF(x,0)). Normalizamos 0 -> NULL no Ouro para:
--   (a) corrigir display "0 cm" ao cliente; (b) zerar a divergência products<->product_physical
--       no lado "products tem valor". O trigger trg_sync_product_physical propaga e mantém coerência.
-- Idempotente: re-execução afeta 0 linhas. NULLIF preserva quaisquer valores não-zero.
UPDATE public.products
SET height_cm   = NULLIF(height_cm, 0),
    width_cm    = NULLIF(width_cm, 0),
    length_cm   = NULLIF(length_cm, 0),
    weight_g    = NULLIF(weight_g, 0),
    diameter_cm = NULLIF(diameter_cm, 0)
WHERE is_active
  AND (height_cm = 0 OR width_cm = 0 OR length_cm = 0 OR weight_g = 0 OR diameter_cm = 0);;

-- <<< END 20260626145051_fix_zero_dims_to_null_gold_quality_20260626.sql <<<

-- >>> BEGIN 20260626145058_fix_physical_guard_shape_on_existing_satellite.sql >>>
-- Refina o early-return guard de fn_sync_product_physical_from_products:
-- products é fonte da verdade; product_physical é projeção fiel.
-- Regra: NÃO criar linha nova só-com-shape (sem valor de frete), MAS
-- atualizar shape em linha de satélite que JÁ EXISTE (projeção fiel).
-- Corrige 62 produtos XBZ com satélite vazio + shape NULL onde products.shape_type='rectangular'.
-- Patch dinâmico idempotente, preserva SET search_path, resiliente ao bot Lovable.
DO $$
DECLARE v_def text; v_new text;
BEGIN
  v_def := pg_get_functiondef('public.fn_sync_product_physical_from_products(uuid)'::regprocedure);

  -- idempotência
  IF v_def ~ 'v_sat_existe' THEN
    RAISE NOTICE 'fix_version physical_guard_shape_existing_row_v1 já aplicado — pulando';
    RETURN;
  END IF;

  -- validar unicidade das âncoras antes de mexer
  IF (SELECT count(*) FROM regexp_matches(v_def,'v_boxlen_mm  numeric; v_boxwid_mm  numeric; v_boxhei_mm  numeric;','g')) <> 1
     OR (SELECT count(*) FROM regexp_matches(v_def,'IF NOT FOUND THEN RETURN FALSE; END IF;','g')) <> 1
     OR (SELECT count(*) FROM regexp_matches(v_def,'AND v_bqty IS NULL AND v_bwkg IS NULL AND v_bvol_cm3 IS NULL THEN','g')) <> 1 THEN
    RAISE EXCEPTION 'Âncoras de patch inesperadas — abortando (possível reescrita pelo bot)';
  END IF;

  v_new := v_def;
  v_new := replace(v_new,
    'v_boxlen_mm  numeric; v_boxwid_mm  numeric; v_boxhei_mm  numeric;',
    'v_boxlen_mm  numeric; v_boxwid_mm  numeric; v_boxhei_mm  numeric; v_sat_existe boolean;');
  v_new := replace(v_new,
    'IF NOT FOUND THEN RETURN FALSE; END IF;',
    'IF NOT FOUND THEN RETURN FALSE; END IF;' || chr(10) ||
    '    v_sat_existe := EXISTS(SELECT 1 FROM product_physical WHERE product_id = p_product_id); -- fix_version: physical_guard_shape_existing_row_v1');
  v_new := replace(v_new,
    'AND v_bqty IS NULL AND v_bwkg IS NULL AND v_bvol_cm3 IS NULL THEN',
    'AND v_bqty IS NULL AND v_bwkg IS NULL AND v_bvol_cm3 IS NULL AND (v_shape IS NULL OR NOT v_sat_existe) THEN');

  EXECUTE v_new;
  RAISE NOTICE 'fix_version physical_guard_shape_existing_row_v1 aplicado com sucesso';
END $$;;

-- <<< END 20260626145058_fix_physical_guard_shape_on_existing_satellite.sql <<<

-- >>> BEGIN 20260626145127_backfill_physical_shape_62_xbz.sql >>>
-- Backfill único dos 62 produtos XBZ com shape stale (satélite existente, shape NULL).
-- A projeção (products=fonte da verdade) preenche product_physical.shape_type.
-- Seguro: dry-run provou delta_linhas=0, internal_perda=0, outras_cols=0.
DO $$
DECLARE v_id uuid; v_ok int := 0; v_total int := 0;
BEGIN
  FOR v_id IN
    SELECT pp.product_id
    FROM product_physical pp JOIN products p ON p.id=pp.product_id
    WHERE pp.shape_type IS DISTINCT FROM COALESCE(p.shape_type, pp.shape_type)
  LOOP
    v_total := v_total + 1;
    IF fn_sync_product_physical_from_products(v_id) THEN v_ok := v_ok + 1; END IF;
  END LOOP;
  RAISE NOTICE 'Backfill shape: total=% sync_ok=%', v_total, v_ok;
END $$;;

-- <<< END 20260626145127_backfill_physical_shape_62_xbz.sql <<<

