-- >>> BEGIN 20260626150046_schema_drift_local_guard_create_20260626.sql >>>
-- ============================================================================
-- MELHORIA 4: Guard de schema-drift INTRA-PROJETO (self-contained, sem HTTP)
-- Fecha o gap real: bot Lovable rodando ALTER TABLE no projeto OFICIAL
-- (ex.: products drift 152->158). Complementa (nao substitui) o checker
-- cross-project fn_run_schema_drift_check (que compara contra sombra Lovable
-- via HTTP e esta cronicamente em timeout).
-- fix_version: schema_drift_local_guard_v1 (2026-06-26)
-- ANTI-REGRESSAO: se o bot Lovable regenerar estas funcoes, RESTAURAR
--   SECURITY DEFINER + SET search_path=public + os REVOKE/GRANT abaixo.
-- ============================================================================

-- 1) Baseline aprovada (granularidade de COLUNA) ----------------------------
CREATE TABLE IF NOT EXISTS public.schema_signature_baseline (
  table_name     text NOT NULL,
  column_name    text NOT NULL,
  data_type      text NOT NULL,
  baseline_label text NOT NULL DEFAULT 'init',
  captured_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (table_name, column_name)
);
COMMENT ON TABLE public.schema_signature_baseline IS
  'MELHORIA4 schema_drift_local_guard_v1: snapshot APROVADO de colunas do schema public. Recapturar via fn_capture_schema_baseline() apos mudancas intencionais. NAO DROPAR.';

-- 2) Allowlist coluna-aware (column_name NULL = tabela inteira ignorada) -----
CREATE TABLE IF NOT EXISTS public.schema_signature_drift_allowlist (
  table_name  text NOT NULL,
  column_name text,                      -- NULL => ignora a tabela toda
  reason      text NOT NULL,
  added_by    text NOT NULL DEFAULT 'manual',
  added_at    timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_schema_sig_allowlist
  ON public.schema_signature_drift_allowlist (table_name, COALESCE(column_name, '*'));
COMMENT ON TABLE public.schema_signature_drift_allowlist IS
  'MELHORIA4 schema_drift_local_guard_v1: mudancas de schema intencionais a ignorar no drift local. column_name NULL = tabela inteira.';

-- 3) Log de execucoes -------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.schema_signature_drift_log (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  ran_at          timestamptz NOT NULL DEFAULT now(),
  has_drift       boolean NOT NULL DEFAULT false,
  n_added         int NOT NULL DEFAULT 0,
  n_removed       int NOT NULL DEFAULT 0,
  n_retyped       int NOT NULL DEFAULT 0,
  columns_added   jsonb NOT NULL DEFAULT '{}'::jsonb,
  columns_removed jsonb NOT NULL DEFAULT '{}'::jsonb,
  columns_retyped jsonb NOT NULL DEFAULT '{}'::jsonb,
  tables_added    text[] NOT NULL DEFAULT '{}',
  tables_removed  text[] NOT NULL DEFAULT '{}',
  baseline_label  text
);
CREATE INDEX IF NOT EXISTS idx_schema_sig_drift_log_ran_at
  ON public.schema_signature_drift_log (ran_at DESC);
COMMENT ON TABLE public.schema_signature_drift_log IS
  'MELHORIA4 schema_drift_local_guard_v1: historico de checagens de drift intra-projeto.';

-- 4) Captura/recaptura da baseline ------------------------------------------
CREATE OR REPLACE FUNCTION public.fn_capture_schema_baseline(p_label text DEFAULT 'manual')
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  -- fix_version: schema_drift_local_guard_v1
  DELETE FROM public.schema_signature_baseline;
  INSERT INTO public.schema_signature_baseline (table_name, column_name, data_type, baseline_label, captured_at)
  SELECT table_name, column_name, data_type, p_label, now()
  FROM information_schema.columns
  WHERE table_schema='public'
    AND table_name NOT LIKE 'pg_%'
    AND table_name NOT LIKE '_backup_%';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$;

-- 5) Checagem de drift (zero HTTP, imune a timeout) -------------------------
CREATE OR REPLACE FUNCTION public.fn_check_schema_signature_drift()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_added    jsonb := '{}'::jsonb;
  v_removed  jsonb := '{}'::jsonb;
  v_retyped  jsonb := '{}'::jsonb;
  v_tadded   text[];
  v_tremoved text[];
  v_n_add int; v_n_rem int; v_n_ret int;
  v_has_drift boolean;
  v_label text;
  v_log_id uuid;
BEGIN
  -- fix_version: schema_drift_local_guard_v1
  SELECT baseline_label INTO v_label FROM public.schema_signature_baseline LIMIT 1;

  CREATE TEMP TABLE _live ON COMMIT DROP AS
    SELECT table_name, column_name, data_type
    FROM information_schema.columns
    WHERE table_schema='public'
      AND table_name NOT LIKE 'pg_%' AND table_name NOT LIKE '_backup_%';

  CREATE TEMP TABLE _diff ON COMMIT DROP AS
    SELECT
      COALESCE(b.table_name, l.table_name) AS table_name,
      COALESCE(b.column_name, l.column_name) AS column_name,
      b.data_type AS base_type, l.data_type AS live_type,
      CASE
        WHEN b.column_name IS NULL THEN 'added'
        WHEN l.column_name IS NULL THEN 'removed'
        WHEN b.data_type IS DISTINCT FROM l.data_type THEN 'retyped'
        ELSE 'same'
      END AS verdict
    FROM public.schema_signature_baseline b
    FULL OUTER JOIN _live l
      ON b.table_name=l.table_name AND b.column_name=l.column_name;

  -- aplica allowlist: remove linhas cobertas por (tabela,*) ou (tabela,coluna)
  DELETE FROM _diff d
  USING public.schema_signature_drift_allowlist a
  WHERE d.table_name = a.table_name
    AND (a.column_name IS NULL OR a.column_name = d.column_name);

  -- tabelas inteiramente novas / removidas (set difference de table_name)
  SELECT array_agg(t ORDER BY t) INTO v_tadded FROM (
    SELECT DISTINCT table_name t FROM _live
    EXCEPT SELECT DISTINCT table_name FROM public.schema_signature_baseline
  ) x WHERE t NOT IN (SELECT table_name FROM public.schema_signature_drift_allowlist WHERE column_name IS NULL);

  SELECT array_agg(t ORDER BY t) INTO v_tremoved FROM (
    SELECT DISTINCT table_name t FROM public.schema_signature_baseline
    EXCEPT SELECT DISTINCT table_name FROM _live
  ) x WHERE t NOT IN (SELECT table_name FROM public.schema_signature_drift_allowlist WHERE column_name IS NULL);

  v_tadded   := COALESCE(v_tadded, '{}');
  v_tremoved := COALESCE(v_tremoved, '{}');

  -- agrega por tabela {table: [col, ...]}
  SELECT COALESCE(jsonb_object_agg(table_name, cols), '{}'::jsonb) INTO v_added
  FROM (SELECT table_name, jsonb_agg(column_name ORDER BY column_name) cols
        FROM _diff WHERE verdict='added' GROUP BY table_name) s;

  SELECT COALESCE(jsonb_object_agg(table_name, cols), '{}'::jsonb) INTO v_removed
  FROM (SELECT table_name, jsonb_agg(column_name ORDER BY column_name) cols
        FROM _diff WHERE verdict='removed' GROUP BY table_name) s;

  SELECT COALESCE(jsonb_object_agg(table_name, cols), '{}'::jsonb) INTO v_retyped
  FROM (SELECT table_name, jsonb_agg(jsonb_build_object('column',column_name,'from',base_type,'to',live_type) ORDER BY column_name) cols
        FROM _diff WHERE verdict='retyped' GROUP BY table_name) s;

  SELECT count(*) FILTER (WHERE verdict='added'),
         count(*) FILTER (WHERE verdict='removed'),
         count(*) FILTER (WHERE verdict='retyped')
    INTO v_n_add, v_n_rem, v_n_ret
  FROM _diff;

  v_has_drift := (v_n_add + v_n_rem + v_n_ret) > 0
                 OR array_length(v_tadded,1) > 0
                 OR array_length(v_tremoved,1) > 0;

  INSERT INTO public.schema_signature_drift_log
    (has_drift, n_added, n_removed, n_retyped, columns_added, columns_removed, columns_retyped, tables_added, tables_removed, baseline_label)
  VALUES
    (v_has_drift, v_n_add, v_n_rem, v_n_ret, v_added, v_removed, v_retyped, v_tadded, v_tremoved, v_label)
  RETURNING id INTO v_log_id;

  RETURN jsonb_build_object(
    'ok', true, 'has_drift', v_has_drift, 'log_id', v_log_id,
    'baseline_label', v_label,
    'n_added', v_n_add, 'n_removed', v_n_rem, 'n_retyped', v_n_ret,
    'columns_added', v_added, 'columns_removed', v_removed, 'columns_retyped', v_retyped,
    'tables_added', to_jsonb(v_tadded), 'tables_removed', to_jsonb(v_tremoved)
  );
END;
$function$;

-- 6) Seguranca: revoke PUBLIC/anon, grant explicito --------------------------
REVOKE ALL ON FUNCTION public.fn_capture_schema_baseline(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_check_schema_signature_drift() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_capture_schema_baseline(text) TO service_role;
GRANT EXECUTE ON FUNCTION public.fn_check_schema_signature_drift() TO service_role, authenticated;

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260626150046_schema_drift_local_guard_create_20260626.sql <<<

-- >>> BEGIN 20260626151155_harden_quote_subsystem_anon_grants.sql >>>
-- ============================================================================
-- HARDENING DE GRANTS (defense-in-depth) — subsistema de orçamentos (quotes)
-- ----------------------------------------------------------------------------
-- Contexto: 6 tabelas do subsistema quotes ainda carregavam os grants default
-- do Supabase (INSERT/SELECT/UPDATE/DELETE para anon; REFERENCES/TRIGGER para
-- authenticated), protegidas apenas por RLS. Nenhuma dessas tabelas possui
-- policy que conceda acesso ao papel anon (todas as policies sao authenticated/
-- service_role com predicados auth.uid()/can_access_quote()). O fluxo publico de
-- e-assinatura usa RPCs SECURITY DEFINER (get_quote_token_by_value,
-- submit_quote_response) que ignoram grants de tabela. Portanto remover o acesso
-- direto do anon e os privilegios REFERENCES/TRIGGER do authenticated e seguro e
-- fecha a porta de acesso direto (camada extra alem da RLS).
--
-- Mantido: SELECT/INSERT/UPDATE/DELETE do authenticated (RLS gateia as linhas).
-- Validado: dry-run com 22 asserções (anon negado/42501 funcional em quote_items,
-- authenticated mantem SELECT, RPCs publicas anon-EXECUTE intactas).
-- Alinhado ao padrao ja aplicado em quotes/quote_history/quote_approval_tokens.
-- fix_version: 20260626_quote_grants_hardening
-- ============================================================================
REVOKE ALL ON public.quote_items FROM anon;
REVOKE REFERENCES, TRIGGER ON public.quote_items FROM authenticated;

REVOKE ALL ON public.quote_versions FROM anon;
REVOKE REFERENCES, TRIGGER ON public.quote_versions FROM authenticated;

REVOKE ALL ON public.quote_drafts FROM anon;
REVOKE REFERENCES, TRIGGER ON public.quote_drafts FROM authenticated;

REVOKE ALL ON public.quote_item_personalizations FROM anon;
REVOKE REFERENCES, TRIGGER ON public.quote_item_personalizations FROM authenticated;

REVOKE ALL ON public.quote_comments FROM anon;
REVOKE REFERENCES, TRIGGER ON public.quote_comments FROM authenticated;

REVOKE ALL ON public.quote_templates FROM anon;
REVOKE REFERENCES, TRIGGER ON public.quote_templates FROM authenticated;

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260626151155_harden_quote_subsystem_anon_grants.sql <<<

-- >>> BEGIN 20260626151211_complete_schema_drift_local_guard_baseline_cron_surface_20260626.sql >>>
-- =====================================================================
-- MELHORIA 4 (conclusão) — Guard local anti-drift Lovable: 100% funcional
-- Sessão anterior criou as funções/tabelas mas deixou:
--   (a) baseline VAZIO  -> guard reportava tudo como drift (n_added=6965)
--   (b) cron 245 apontando p/ fn_run_schema_drift_check (REMOTO via pg_net,
--       que SEMPRE dá timeout pois pg_net só envia após commit da txn)
--   (c) drift sem superfície de alerta (log silencioso)
-- Esta migration finaliza: baseline + cron->local + surface em v_system_alerts
-- fix_version: schema_drift_local_guard_v2
-- =====================================================================

-- (1) Captura a baseline certificada de HOJE (idempotente: DELETE+INSERT)
SELECT public.fn_capture_schema_baseline('certified_baseline_20260626');

-- (2) Reaponta o cron 245 para o guard LOCAL (síncrono, sem dependência externa)
SELECT cron.alter_job(
  job_id => 245,
  command => $cmd$SELECT public.fn_cron_safe_run(25::bigint, $q$SELECT public.fn_check_schema_signature_drift();$q$, 30000, 'schema-drift-local');$cmd$
);

-- (3) Documenta o mecanismo REMOTO como desativado (mantido p/ refactor async futuro)
COMMENT ON FUNCTION public.fn_run_schema_drift_check() IS
  '[DESATIVADO 2026-06-26] Compara schema vs projeto Lovable via pg_net. NAO agendado: pg_net so envia HTTP apos commit da txn, entao polling sincrono sempre da timeout. Substituido no cron 245 pelo guard LOCAL fn_check_schema_signature_drift(). Manter so se for refatorado p/ padrao async (trigger fetch + finalize separado).';

-- (4) Superfície de alerta: drift de schema aparece em v_system_alerts (read-only)
CREATE OR REPLACE VIEW public.v_system_alerts AS
 WITH cron_alerts AS (
         SELECT 'CRON_FAIL_RECENT'::text AS codigo,
            'critical'::text AS severidade,
            ((('Job '::text || j.jobid) || ' ('::text) || j.jobname) || ') com falhas na ultima hora'::text AS mensagem,
            count(CASE WHEN d.status = 'failed'::text THEN 1 ELSE NULL::integer END)::text AS detalhe
           FROM cron.job_run_details d
             JOIN cron.job j ON j.jobid = d.jobid
          WHERE d.start_time > (now() - '01:00:00'::interval)
          GROUP BY j.jobid, j.jobname
         HAVING count(CASE WHEN d.status = 'failed'::text THEN 1 ELSE NULL::integer END) >= 3
             OR count(CASE WHEN d.status = 'failed'::text THEN 1 ELSE NULL::integer END) >= 1
                AND max(CASE WHEN d.status = 'failed'::text THEN d.start_time ELSE NULL::timestamp with time zone END) >
                    max(CASE WHEN d.status = 'succeeded'::text THEN d.start_time ELSE NULL::timestamp with time zone END)
        ), import_stalled AS (
         SELECT 'IMPORT_STALLED'::text AS codigo,
            'warning'::text AS severidade,
            'Batches Bronze pendentes ha mais de 1h'::text AS mensagem,
            count(DISTINCT COALESCE(supplier_products_raw.import_batch_id::text, supplier_products_raw.supplier_id::text))::text AS detalhe
           FROM supplier_products_raw
          WHERE (supplier_products_raw.status = ANY (ARRAY['pending'::supplier_raw_status, 'processing'::supplier_raw_status]))
            AND supplier_products_raw.imported_at < (now() - '01:00:00'::interval)
         HAVING count(*) > 0
        ), products_no_image AS (
         SELECT 'PRODUCTS_NO_IMAGE'::text AS codigo,
            'info'::text AS severidade,
            'Produtos ativos sem imagem principal'::text AS mensagem,
            count(*)::text AS detalhe
           FROM products
          WHERE products.is_active = true AND products.primary_image_url IS NULL
         HAVING count(*) > 0
        ), vss_no_preferred AS (
         SELECT 'VSS_NO_PREFERRED'::text AS codigo,
            'warning'::text AS severidade,
            'Variantes ativas sem fornecedor preferido'::text AS mensagem,
            count(*)::text AS detalhe
           FROM product_variants pv
          WHERE pv.is_active = true AND NOT (EXISTS ( SELECT 1
                   FROM variant_supplier_sources v
                  WHERE v.variant_id = pv.id AND v.is_preferred = true AND v.is_active = true))
         HAVING count(*) > 0
        ), ai_queue_stale AS (
         SELECT 'AI_QUEUE_STALE'::text AS codigo,
            'info'::text AS severidade,
            'Itens na fila IA ha mais de 7 dias (worker inativo > 24h)'::text AS mensagem,
            count(*)::text AS detalhe
           FROM ai_enrichment_queue
          WHERE ai_enrichment_queue.status = 'pending'::text AND ai_enrichment_queue.created_at < (now() - '7 days'::interval)
            AND NOT (EXISTS ( SELECT 1
                   FROM ai_enrichment_queue w
                  WHERE w.status = 'processing'::text AND w.locked_at > (now() - '04:00:00'::interval)
                     OR w.status = 'done'::text AND w.completed_at > (now() - '24:00:00'::interval)
                 LIMIT 1))
         HAVING count(*) > 0
        ), products_no_ncm AS (
         SELECT 'PRODUCTS_NO_NCM'::text AS codigo,
            'critical'::text AS severidade,
            'Produtos ativos sem NCM (fiscal)'::text AS mensagem,
            count(*)::text AS detalhe
           FROM products
          WHERE products.is_active = true AND products.ncm_id IS NULL
         HAVING count(*) > 0
        ), stock_critical AS (
         SELECT 'STOCK_CRITICAL_LOW'::text AS codigo,
            'info'::text AS severidade,
            'Variantes ativas com estoque zero'::text AS mensagem,
            count(*)::text AS detalhe
           FROM product_variants pv
             JOIN variant_supplier_sources v ON v.variant_id = pv.id
          WHERE pv.is_active = true AND v.is_active = true AND v.quantity = 0
         HAVING count(*) > 0
        ), stale_sync AS (
         SELECT 'SUPPLIER_SYNC_STALE'::text AS codigo,
            'warning'::text AS severidade,
            ((('Fornecedor "'::text || s.name) || '" sem sync ha '::text) || round(EXTRACT(epoch FROM now() - s.last_full_sync_at) / 3600::numeric, 1)::text) || 'h'::text AS mensagem,
            s.last_full_sync_at::text AS detalhe
           FROM suppliers s
          WHERE s.sync_enabled = true
            AND (s.last_full_sync_at IS NULL OR s.last_full_sync_at < (now() - ((LEAST(GREATEST(COALESCE(s.sync_interval_minutes, 60) * 4, 240), 1440) || ' minutes'::text)::interval)))
        ), locked_by_residual AS (
         SELECT 'AI_QUEUE_LOCKED_RESIDUAL'::text AS codigo,
            'warning'::text AS severidade,
            'Items ai_enrichment_queue com locked_by residual em estado terminal'::text AS mensagem,
            count(*)::text AS detalhe
           FROM ai_enrichment_queue
          WHERE ai_enrichment_queue.locked_by IS NOT NULL AND (ai_enrichment_queue.status <> ALL (ARRAY['processing'::text, 'pending'::text]))
         HAVING count(*) > 100
        ), schema_drift AS (
         -- MELHORIA 4: drift de schema detectado pelo guard local (vs baseline certificada)
         SELECT 'SCHEMA_DRIFT_DETECTED'::text AS codigo,
            'warning'::text AS severidade,
            'Schema divergente da baseline certificada (possivel alteracao do bot Lovable)'::text AS mensagem,
            format('cols +%s/-%s/~%s; tabelas +%s/-%s (baseline=%s; verificado %s)',
                   l.n_added, l.n_removed, l.n_retyped,
                   COALESCE(array_length(l.tables_added, 1), 0),
                   COALESCE(array_length(l.tables_removed, 1), 0),
                   l.baseline_label, l.ran_at::timestamp(0) without time zone)::text AS detalhe
           FROM public.schema_signature_drift_log l
          WHERE l.ran_at = (SELECT max(l2.ran_at) FROM public.schema_signature_drift_log l2)
            AND l.has_drift = true
        )
 SELECT codigo, severidade, mensagem, detalhe, now() AS detected_at
   FROM ( SELECT cron_alerts.codigo, cron_alerts.severidade, cron_alerts.mensagem, cron_alerts.detalhe FROM cron_alerts
        UNION ALL SELECT import_stalled.codigo, import_stalled.severidade, import_stalled.mensagem, import_stalled.detalhe FROM import_stalled
        UNION ALL SELECT products_no_image.codigo, products_no_image.severidade, products_no_image.mensagem, products_no_image.detalhe FROM products_no_image
        UNION ALL SELECT vss_no_preferred.codigo, vss_no_preferred.severidade, vss_no_preferred.mensagem, vss_no_preferred.detalhe FROM vss_no_preferred
        UNION ALL SELECT ai_queue_stale.codigo, ai_queue_stale.severidade, ai_queue_stale.mensagem, ai_queue_stale.detalhe FROM ai_queue_stale
        UNION ALL SELECT products_no_ncm.codigo, products_no_ncm.severidade, products_no_ncm.mensagem, products_no_ncm.detalhe FROM products_no_ncm
        UNION ALL SELECT stock_critical.codigo, stock_critical.severidade, stock_critical.mensagem, stock_critical.detalhe FROM stock_critical
        UNION ALL SELECT stale_sync.codigo, stale_sync.severidade, stale_sync.mensagem, stale_sync.detalhe FROM stale_sync
        UNION ALL SELECT locked_by_residual.codigo, locked_by_residual.severidade, locked_by_residual.mensagem, locked_by_residual.detalhe FROM locked_by_residual
        UNION ALL SELECT schema_drift.codigo, schema_drift.severidade, schema_drift.mensagem, schema_drift.detalhe FROM schema_drift) c
  ORDER BY (CASE severidade WHEN 'critical'::text THEN 1 WHEN 'warning'::text THEN 2 ELSE 3 END);

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260626151211_complete_schema_drift_local_guard_baseline_cron_surface_20260626.sql <<<

-- >>> BEGIN 20260626151302_fix_schema_drift_guard_null_has_drift_on_clean_state_20260626.sql >>>
-- BUG FIX: fn_check_schema_signature_drift gravava has_drift=NULL no estado LIMPO
-- (sem drift), violando NOT NULL. Causa: array_length('{}',1) => NULL, e
-- false OR NULL OR NULL => NULL (lógica ternária). Troca por cardinality() (=>0).
-- fix_version: schema_drift_local_guard_v3
CREATE OR REPLACE FUNCTION public.fn_check_schema_signature_drift()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_added    jsonb := '{}'::jsonb;
  v_removed  jsonb := '{}'::jsonb;
  v_retyped  jsonb := '{}'::jsonb;
  v_tadded   text[];
  v_tremoved text[];
  v_n_add int; v_n_rem int; v_n_ret int;
  v_has_drift boolean;
  v_label text;
  v_log_id uuid;
BEGIN
  -- fix_version: schema_drift_local_guard_v3 (cardinality em vez de array_length p/ evitar NULL no estado limpo)
  SELECT baseline_label INTO v_label FROM public.schema_signature_baseline LIMIT 1;

  CREATE TEMP TABLE _live ON COMMIT DROP AS
    SELECT table_name, column_name, data_type
    FROM information_schema.columns
    WHERE table_schema='public'
      AND table_name NOT LIKE 'pg_%' AND table_name NOT LIKE '_backup_%';

  CREATE TEMP TABLE _diff ON COMMIT DROP AS
    SELECT
      COALESCE(b.table_name, l.table_name) AS table_name,
      COALESCE(b.column_name, l.column_name) AS column_name,
      b.data_type AS base_type, l.data_type AS live_type,
      CASE
        WHEN b.column_name IS NULL THEN 'added'
        WHEN l.column_name IS NULL THEN 'removed'
        WHEN b.data_type IS DISTINCT FROM l.data_type THEN 'retyped'
        ELSE 'same'
      END AS verdict
    FROM public.schema_signature_baseline b
    FULL OUTER JOIN _live l
      ON b.table_name=l.table_name AND b.column_name=l.column_name;

  -- aplica allowlist: remove linhas cobertas por (tabela,*) ou (tabela,coluna)
  DELETE FROM _diff d
  USING public.schema_signature_drift_allowlist a
  WHERE d.table_name = a.table_name
    AND (a.column_name IS NULL OR a.column_name = d.column_name);

  -- tabelas inteiramente novas / removidas (set difference de table_name)
  SELECT array_agg(t ORDER BY t) INTO v_tadded FROM (
    SELECT DISTINCT table_name t FROM _live
    EXCEPT SELECT DISTINCT table_name FROM public.schema_signature_baseline
  ) x WHERE t NOT IN (SELECT table_name FROM public.schema_signature_drift_allowlist WHERE column_name IS NULL);

  SELECT array_agg(t ORDER BY t) INTO v_tremoved FROM (
    SELECT DISTINCT table_name t FROM public.schema_signature_baseline
    EXCEPT SELECT DISTINCT table_name FROM _live
  ) x WHERE t NOT IN (SELECT table_name FROM public.schema_signature_drift_allowlist WHERE column_name IS NULL);

  v_tadded   := COALESCE(v_tadded, '{}');
  v_tremoved := COALESCE(v_tremoved, '{}');

  -- agrega por tabela {table: [col, ...]}
  SELECT COALESCE(jsonb_object_agg(table_name, cols), '{}'::jsonb) INTO v_added
  FROM (SELECT table_name, jsonb_agg(column_name ORDER BY column_name) cols
        FROM _diff WHERE verdict='added' GROUP BY table_name) s;

  SELECT COALESCE(jsonb_object_agg(table_name, cols), '{}'::jsonb) INTO v_removed
  FROM (SELECT table_name, jsonb_agg(column_name ORDER BY column_name) cols
        FROM _diff WHERE verdict='removed' GROUP BY table_name) s;

  SELECT COALESCE(jsonb_object_agg(table_name, cols), '{}'::jsonb) INTO v_retyped
  FROM (SELECT table_name, jsonb_agg(jsonb_build_object('column',column_name,'from',base_type,'to',live_type) ORDER BY column_name) cols
        FROM _diff WHERE verdict='retyped' GROUP BY table_name) s;

  SELECT count(*) FILTER (WHERE verdict='added'),
         count(*) FILTER (WHERE verdict='removed'),
         count(*) FILTER (WHERE verdict='retyped')
    INTO v_n_add, v_n_rem, v_n_ret
  FROM _diff;

  -- FIX v3: cardinality() retorna 0 para array vazio (array_length retorna NULL),
  -- evitando v_has_drift = NULL no estado limpo (false OR NULL = NULL).
  v_has_drift := (COALESCE(v_n_add,0) + COALESCE(v_n_rem,0) + COALESCE(v_n_ret,0)) > 0
                 OR cardinality(v_tadded) > 0
                 OR cardinality(v_tremoved) > 0;

  INSERT INTO public.schema_signature_drift_log
    (has_drift, n_added, n_removed, n_retyped, columns_added, columns_removed, columns_retyped, tables_added, tables_removed, baseline_label)
  VALUES
    (v_has_drift, v_n_add, v_n_rem, v_n_ret, v_added, v_removed, v_retyped, v_tadded, v_tremoved, v_label)
  RETURNING id INTO v_log_id;

  RETURN jsonb_build_object(
    'ok', true, 'has_drift', v_has_drift, 'log_id', v_log_id,
    'baseline_label', v_label,
    'n_added', v_n_add, 'n_removed', v_n_rem, 'n_retyped', v_n_ret,
    'columns_added', v_added, 'columns_removed', v_removed, 'columns_retyped', v_retyped,
    'tables_added', to_jsonb(v_tadded), 'tables_removed', to_jsonb(v_tremoved)
  );
END;
$function$;;

-- <<< END 20260626151302_fix_schema_drift_guard_null_has_drift_on_clean_state_20260626.sql <<<

-- >>> BEGIN 20260626151333_harden_generate_quote_number_int4_overflow.sql >>>
-- ============================================================================
-- BLINDAGEM contra overflow int4 na numeração de orçamentos
-- ----------------------------------------------------------------------------
-- generate_quote_number() calcula MAX(prefixo) dos quote_number do ano. O guard
-- antigo usava a regex '^\d+$', que casa prefixos de QUALQUER tamanho. Se um
-- quote_number malformado com 10+ dígitos entrasse na tabela (import/migração/
-- edição manual), o cast ::integer estouraria (SQLSTATE 22003 numeric_value_out_
-- _of_range) e QUEBRARIA a geração de número para o ano inteiro.
--
-- Correção: '^\d{1,9}$' aceita no máximo 9 dígitos (<= 999.999.999, dentro de
-- int4 com folga). Prefixos de 10+ dígitos são ignorados (tratados como 0), em
-- vez de estourar. Operação normal é idêntica: números reais têm ~5 dígitos
-- (10001, 10002, ...), folga de 5 ordens de magnitude.
--
-- Preservado integralmente: SECURITY DEFINER, search_path=public, advisory lock
-- transaction-scoped (pg_advisory_xact_lock) que serializa a geração por ano e
-- previne race condition, e toda a lógica de formatação.
--
-- Validado: dry-run provou (a) regex antiga estoura 22003 com lixo de 11 dígitos,
-- (b) regex nova retorna o MAX real (10007) ignorando o lixo, (c) equivalência
-- exata em operação normal, (d) boundary 9 dígitos aceito / 10 dígitos ignorado.
-- fix_version: 20260626_quote_number_int4_guard
-- ANTI-REGRESSAO: NAO trocar '^\d{1,9}$' de volta por '^\d+$' (reabre o overflow).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.generate_quote_number()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE year_short text; max_num integer; new_number text;
BEGIN
  -- Só calcula/gera se o número ainda não foi informado.
  IF NEW.quote_number IS NOT NULL AND NEW.quote_number <> '' THEN
    RETURN NEW;
  END IF;

  year_short := to_char(now(), 'YY');

  -- Serializa a geração por ano (transaction-scoped: liberado no commit/rollback).
  PERFORM pg_advisory_xact_lock(hashtext('quote_number:' || year_short)::bigint);

  -- ANTI-REGRESSAO (20260626_quote_number_int4_guard): '^\d{1,9}$' (NAO '^\d+$')
  -- evita overflow de int4 caso um prefixo malformado com 10+ digitos exista.
  SELECT COALESCE(MAX(
    CASE WHEN split_part(quote_number, '/', 1) ~ '^\d{1,9}$'
         THEN split_part(quote_number, '/', 1)::integer ELSE 0 END
  ), 10000) INTO max_num
  FROM public.quotes WHERE quote_number LIKE '%/' || year_short;

  new_number := (max_num + 1)::text || '/' || year_short;
  NEW.quote_number := new_number;
  RETURN NEW;
END;
$function$;;

-- <<< END 20260626151333_harden_generate_quote_number_int4_overflow.sql <<<

-- >>> BEGIN 20260626152341_harden_product_variants_stock_nonneg.sql >>>
-- Guardas de integridade de estoque em product_variants (estoque negativo é sem sentido em catálogo B2B).
-- stock_quantity: lido pela vitrine; CHECK alcançável (nenhum trigger sobrescreve estoque de variante ATIVA;
--   fn_enforce_inactive_variant_zero_stock só zera inativos).
-- next_quantity_1..6: quantidades de reposição futura; CHECK alcançável quando pareadas com next_date futura
--   (trg_fn_sanitize_restock_dates anula órfãos e janelas passadas).
-- next_entry_quantity NÃO recebe CHECK: é derivado (:= next_quantity_1) por fn_sync_product_variants_next_entry,
--   portanto guardar next_quantity_1 já o cobre — evita constraint redundante que poderia travar UPDATEs.
-- Verificado empiricamente: 0 violações em 18.580 variantes; dry-run adversarial 7/7 OK.
ALTER TABLE public.product_variants
  ADD CONSTRAINT chk_pv_stock_quantity_nonneg CHECK (stock_quantity >= 0),
  ADD CONSTRAINT chk_pv_next_quantities_nonneg CHECK (
    next_quantity_1 >= 0 AND next_quantity_2 >= 0 AND next_quantity_3 >= 0
    AND next_quantity_4 >= 0 AND next_quantity_5 >= 0 AND next_quantity_6 >= 0);

-- <<< END 20260626152341_harden_product_variants_stock_nonneg.sql <<<

-- >>> BEGIN 20260626152721_m3_xbz_price_last_verified_honest_passo4_plus_backfill_20260626.sql >>>
-- ============================================================================
-- MELHORIA 3 (price freshness honesto) — 2026-06-26
-- fix_version = price_freshness_honest_v1
-- PROBLEMA: 224 produtos XBZ apareciam com is_price_stale=true (badge
--   v_product_active_badge) apesar de o produto ser reconfirmado na API XBZ a
--   cada <=12h. Causa: o badge lê products.price_last_verified_at, que só era
--   carimbado pelo trigger trg_update_price_last_verified quando last_sync_at OU
--   price_updated_at mudavam. O stock-sync XBZ grava product_variants.last_sync_at
--   (não products.last_sync_at) e só bumpa products.price_verified_at (coluna
--   DIFERENTE). Para produtos de preço ESTÁVEL (>60d sem mudança), nada bumpava
--   price_last_verified_at -> falso-positivo de "preço velho".
-- FIX: o PASSO 4 (rollup, roda a cada <=12h por produto) passa a carimbar TAMBÉM
--   price_last_verified_at=now(), ao lado de price_verified_at. Blast radius
--   mínimo: price_last_verified_at é lido SOMENTE por v_product_active_badge.
-- PROVA: dry-run 1 (224->0) + dry-run 2 (réplica real do PASSO 4, 224->0).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.fn_import_stock_xbz(p_parent_reference text DEFAULT NULL::text)
 RETURNS TABLE(vss_atualizadas integer, bronze_fechadas integer, produtos_rollup integer, bronze_sem_vss integer, details jsonb)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_supplier_id uuid;
  v_updated int := 0; v_closed int := 0; v_rollup int := 0; v_skipped int := 0;
  v_pv_updated int := 0;
BEGIN
  SELECT id INTO v_supplier_id FROM public.suppliers WHERE code='XBZ' LIMIT 1;
  IF v_supplier_id IS NULL THEN RAISE EXCEPTION 'Fornecedor XBZ nao encontrado'; END IF;

  -- PASSO 1: Bronze → VSS (stock + next_date_1 com sentinela filtrada)
  WITH src AS (
    SELECT spr.supplier_sku,
           GREATEST(COALESCE(NULLIF(spr.stock_data->>'Quantity','')::int,0),0) AS q,
           NULLIF(NULLIF(LEFT(COALESCE(spr.stock_data->>'NextDate1',''),10),'0001-01-01'),'')::date AS nd1
    FROM public.supplier_products_raw spr
    WHERE spr.supplier_id=v_supplier_id AND spr.stock_data ? 'Quantity'
      AND (p_parent_reference IS NULL OR spr.supplier_reference=p_parent_reference)
  ),
  upd AS (
    UPDATE public.variant_supplier_sources vss
       SET quantity=src.q, stock_main_warehouse=src.q, stock_other_warehouses=0,
           next_date_1     = CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss.next_quantity_1,0)>0
                                  THEN src.nd1 ELSE NULL END,
           next_quantity_1 = CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss.next_quantity_1,0)>0
                                  THEN vss.next_quantity_1 ELSE NULL END,
           last_synced_at=now(), sync_status='synced',
           sync_error=NULL, source='xbz_api', updated_at=now()
    FROM src
    WHERE vss.supplier_id=v_supplier_id AND vss.supplier_sku=src.supplier_sku
      AND (
        vss.quantity IS DISTINCT FROM src.q
        OR vss.next_date_1 IS DISTINCT FROM
           CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss.next_quantity_1,0)>0
                THEN src.nd1 ELSE NULL END
        OR (src.nd1 IS NULL AND COALESCE(vss.next_quantity_1, 0) > 0)
        OR (src.nd1 IS NOT NULL AND COALESCE(vss.next_quantity_1,0)=0 AND vss.next_date_1 IS NOT NULL)
      )
    RETURNING vss.id
  )
  SELECT count(*) INTO v_updated FROM upd;

  -- PASSO 2: VSS → product_variants
  PERFORM set_config('app.bulk_import_mode', 'true', true);
  WITH src AS (
    SELECT spr.supplier_sku,
           GREATEST(COALESCE(NULLIF(spr.stock_data->>'Quantity','')::int,0),0) AS q,
           NULLIF(NULLIF(LEFT(COALESCE(spr.stock_data->>'NextDate1',''),10),'0001-01-01'),'')::date AS nd1
    FROM public.supplier_products_raw spr
    WHERE spr.supplier_id=v_supplier_id AND spr.stock_data ? 'Quantity'
      AND (p_parent_reference IS NULL OR spr.supplier_reference=p_parent_reference)
  )
  UPDATE public.product_variants pv
  SET stock_quantity  = src.q,
      next_date_1     = CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss2.next_quantity_1,0)>0
                             THEN src.nd1 ELSE NULL END,
      next_quantity_1 = CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss2.next_quantity_1,0)>0
                             THEN vss2.next_quantity_1 ELSE NULL END,
      last_sync_at    = now()
  FROM src
  JOIN public.variant_supplier_sources vss2
    ON vss2.supplier_sku = src.supplier_sku
   AND vss2.supplier_id  = v_supplier_id
   AND vss2.is_active    = true
  WHERE pv.supplier_sku = src.supplier_sku
    AND pv.is_active    = true
    AND (
      pv.stock_quantity IS DISTINCT FROM src.q
      OR pv.next_date_1 IS DISTINCT FROM
         CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss2.next_quantity_1,0)>0
              THEN src.nd1 ELSE NULL END
      OR pv.next_quantity_1 IS DISTINCT FROM
         CASE WHEN src.nd1 IS NOT NULL AND COALESCE(vss2.next_quantity_1,0)>0
              THEN vss2.next_quantity_1 ELSE NULL END
    );
  GET DIAGNOSTICS v_pv_updated = ROW_COUNT;

  -- PASSO 3: Fechar Bronze processados
  WITH closed AS (
    UPDATE public.supplier_products_raw spr
       SET stock_status='processed', stock_synced_at=now()
    WHERE spr.supplier_id=v_supplier_id AND spr.stock_data ? 'Quantity'
      AND (p_parent_reference IS NULL OR spr.supplier_reference=p_parent_reference)
      AND spr.stock_status IS DISTINCT FROM 'processed'
      AND EXISTS (SELECT 1 FROM public.variant_supplier_sources vss
                  WHERE vss.supplier_id=v_supplier_id AND vss.supplier_sku=spr.supplier_sku)
    RETURNING spr.id
  )
  SELECT count(*) INTO v_closed FROM closed;

  -- PASSO 4: Rollup produto-pai
  WITH agg AS (
    SELECT p2.id, COALESCE(SUM(pv.stock_quantity),0) AS sum_v
    FROM public.products p2
    LEFT JOIN public.product_variants pv ON pv.product_id=p2.id AND pv.is_active=true
    WHERE p2.supplier_id=v_supplier_id
      AND (p_parent_reference IS NULL OR p2.supplier_reference=p_parent_reference)
    GROUP BY p2.id
  ),
  rollup AS (
    UPDATE public.products p
       SET stock_quantity=agg.sum_v, is_stockout=(agg.sum_v<=0),
           last_stock_update_at=now(), price_verified_at=now(),
           -- FIX M3 2026-06-26 (fix_version=price_freshness_honest_v1):
           -- carimbar TAMBÉM price_last_verified_at (lido por v_product_active_badge).
           -- O rollup roda a cada <=12h por produto e reconfirma os dados do
           -- fornecedor; sem este carimbo, produtos de preço ESTÁVEL (>60d sem
           -- mudança) apareciam como is_price_stale=true (falso-positivo).
           -- ANTI-REGRESSAO: NAO remover esta linha — mantém o badge de frescor honesto.
           price_last_verified_at=now()
    FROM agg WHERE p.id=agg.id
      AND (p.stock_quantity IS DISTINCT FROM agg.sum_v
        OR p.is_stockout IS DISTINCT FROM (agg.sum_v<=0)
        OR p.price_verified_at IS NULL
        OR p.price_verified_at < now() - INTERVAL '12 hours')
    RETURNING p.id
  )
  SELECT count(*) INTO v_rollup FROM rollup;

  SELECT count(*) INTO v_skipped
  FROM public.supplier_products_raw spr
  WHERE spr.supplier_id=v_supplier_id AND spr.stock_data ? 'Quantity'
    AND (p_parent_reference IS NULL OR spr.supplier_reference=p_parent_reference)
    AND NOT EXISTS (SELECT 1 FROM public.variant_supplier_sources vss
                    WHERE vss.supplier_id=v_supplier_id AND vss.supplier_sku=spr.supplier_sku);

  -- HEARTBEAT FIX 2026-06-22: Atualiza last_full_sync_at SEMPRE (independente de mudanças)
  -- Permite que v_system_alerts detecte corretamente se o sync está rodando
  UPDATE public.suppliers
    SET last_full_sync_at = now(), last_sync_status = 'completed'
  WHERE id = v_supplier_id;

  RETURN QUERY SELECT v_updated, v_closed, v_rollup, v_skipped,
    jsonb_build_object(
      'supplier_id', v_supplier_id,
      'scope', COALESCE(p_parent_reference,'ALL'),
      'pv_updated', v_pv_updated,
      'fixes', jsonb_build_array(
        'nd1_null_clears_nq1_residual',
        'pv_is_active_guard',
        'nd1_only_when_nq1_positive',
        'heartbeat_last_full_sync_at',
        'price_last_verified_at_honest_v1'  -- NOVO: badge de frescor honesto (M3)
      )
    );
END;
$function$;

-- ----------------------------------------------------------------------------
-- BACKFILL ÚNICO: zerar os 224 falsos-positivos XBZ existentes imediatamente
-- (o fix acima os mantém frescos a partir de agora; este UPDATE limpa o backlog)
-- ----------------------------------------------------------------------------
UPDATE public.products
   SET price_last_verified_at = now()
 WHERE supplier_id = (SELECT id FROM public.suppliers WHERE code='XBZ' LIMIT 1)
   AND is_active = true
   AND price_last_verified_at IS NOT NULL
   AND (EXTRACT(epoch FROM now() - price_last_verified_at)/86400)
       > COALESCE(price_freshness_threshold_days, 60);

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260626152721_m3_xbz_price_last_verified_honest_passo4_plus_backfill_20260626.sql <<<

-- >>> BEGIN 20260626152810_harden_discount_approval_requests_grants.sql >>>
-- Defesa-em-profundidade na própria tabela discount_approval_requests (dado interno vendedor/admin).
-- As 4 RLS policies são TO authenticated => anon já não enxerga linhas; aqui removemos o grant
-- residual de tabela do anon (default do Supabase) e REFERENCES/TRIGGER do authenticated, ficando
-- consistente com o hardening já feito em quotes, quote_approval_tokens e discount_approval_audit (M2).
-- authenticated MANTÉM SELECT/INSERT/UPDATE/DELETE (gateados por RLS); service_role MANTÉM ALL.
-- Obs.: TRIGGER/REFERENCES são privilégios de CRIAR trigger/FK — revogá-los NÃO afeta triggers já
-- existentes (auditoria/notify/M1-M6 seguem disparando normalmente).
REVOKE ALL ON public.discount_approval_requests FROM anon;
REVOKE REFERENCES, TRIGGER ON public.discount_approval_requests FROM authenticated;

