-- >>> BEGIN 20260626182002_mod03_xgroup_norm_confirmed_regen.sql >>>
-- 21 cross-grupo onde o NOME confirma o normalizado (e não o jsonb) => normalizado correto, jsonb stale.
-- Regen jsonb a partir do normalizado. bulk_import_mode suprime cascata.
SELECT set_config('app.bulk_import_mode','true', true);

WITH d AS (
  SELECT p.id, extensions.unaccent(lower(p.name)) AS lname, p.materials,
    (SELECT array_agg(DISTINCT mt.group_id) FROM (SELECT public.fn_find_material_type_id(e) AS tid FROM jsonb_array_elements_text(p.materials) j(e)) s JOIN material_types mt ON mt.id=s.tid) AS jgroups,
    (SELECT array_agg(DISTINCT mt.group_id) FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id WHERE pm.product_id=p.id AND pm.is_active) AS ngroups,
    (SELECT array_agg(DISTINCT s.tid) FROM (SELECT public.fn_find_material_type_id(e) AS tid FROM jsonb_array_elements_text(p.materials) j(e)) s WHERE s.tid IS NOT NULL) AS jids,
    (SELECT array_agg(DISTINCT pm.material_id) FROM product_materials pm WHERE pm.product_id=p.id AND pm.is_active) AS nids
  FROM products p WHERE p.is_active
),
c462 AS (
  SELECT * FROM d WHERE jids IS NOT NULL AND nids IS NOT NULL AND NOT (jids @> nids AND nids @> jids) AND NOT (ngroups @> jgroups)
),
corr AS (
  SELECT t.id,
    (SELECT bool_or(t.lname LIKE '%'||left(extensions.unaccent(lower(w)),5)||'%') FROM jsonb_array_elements_text(t.materials) j(e), unnest(string_to_array(e,' ')) w WHERE length(w)>=5) AS jcorr,
    (SELECT bool_or(t.lname LIKE '%'||left(extensions.unaccent(lower(w)),5)||'%') FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id, unnest(string_to_array(mt.name,' ')) w WHERE pm.product_id=t.id AND pm.is_active AND length(w)>=5 AND w NOT ILIKE 'gen%rico') AS ncorr
  FROM c462 t
),
tgt AS (SELECT id FROM corr WHERE ncorr AND NOT jcorr)
UPDATE products p SET
  materials = COALESCE((SELECT jsonb_agg(mt.name ORDER BY pm.sort_order, mt.name)
                        FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id
                        WHERE pm.product_id=p.id AND pm.is_active),'[]'::jsonb),
  auto_material = (SELECT mt.name FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id
                   WHERE pm.product_id=p.id AND pm.is_active
                   ORDER BY pm.percentage DESC NULLS LAST, pm.sort_order ASC LIMIT 1),
  updated_at = now()
WHERE p.id IN (SELECT id FROM tgt);;

-- <<< END 20260626182002_mod03_xgroup_norm_confirmed_regen.sql <<<

-- >>> BEGIN 20260626182116_m6_add_silver_promote_stalled_alert_20260626.sql >>>
-- ============================================================================
-- M6 (guarda): adiciona SILVER_PROMOTE_STALLED a v_system_alerts.
-- Torna VISIVEL o halt de promocao Prata->Ouro que ficou silencioso por 3 dias
-- (registros 'standardized' nao promovidos nao geravam nenhum alerta; o
--  IMPORT_STALLED existente so cobre Bronze pendente, nao o backlog da Prata).
-- fix_version = silver_promote_stalled_alert_v1
-- ANTI-REGRESSAO: preservar TODAS as 10 CTEs originais + a nova abaixo.
-- ============================================================================
CREATE OR REPLACE VIEW public.v_system_alerts AS
WITH cron_alerts AS (
  SELECT 'CRON_FAIL_RECENT'::text AS codigo,
         'critical'::text AS severidade,
         ((('Job '::text || j.jobid) || ' ('::text) || j.jobname) || ') com falhas na ultima hora'::text AS mensagem,
         count(CASE WHEN d.status = 'failed'::text THEN 1 ELSE NULL::integer END)::text AS detalhe
    FROM cron.job_run_details d
    JOIN cron.job j ON j.jobid = d.jobid
   WHERE d.start_time > (now() - '01:00:00'::interval)
   GROUP BY j.jobid, j.jobname
  HAVING count(CASE WHEN d.status = 'failed'::text THEN 1 ELSE NULL::integer END) >= 3
      OR (count(CASE WHEN d.status = 'failed'::text THEN 1 ELSE NULL::integer END) >= 1
          AND max(CASE WHEN d.status = 'failed'::text THEN d.start_time ELSE NULL::timestamptz END)
            > max(CASE WHEN d.status = 'succeeded'::text THEN d.start_time ELSE NULL::timestamptz END))
), import_stalled AS (
  SELECT 'IMPORT_STALLED'::text AS codigo,
         'warning'::text AS severidade,
         'Batches Bronze pendentes ha mais de 1h'::text AS mensagem,
         count(DISTINCT COALESCE(supplier_products_raw.import_batch_id::text, supplier_products_raw.supplier_id::text))::text AS detalhe
    FROM supplier_products_raw
   WHERE (supplier_products_raw.status = ANY (ARRAY['pending'::supplier_raw_status, 'processing'::supplier_raw_status]))
     AND supplier_products_raw.imported_at < (now() - '01:00:00'::interval)
  HAVING count(*) > 0
), products_no_image AS (
  SELECT 'PRODUCTS_NO_IMAGE'::text AS codigo, 'info'::text AS severidade,
         'Produtos ativos sem imagem principal'::text AS mensagem, count(*)::text AS detalhe
    FROM products
   WHERE products.is_active = true AND products.primary_image_url IS NULL
  HAVING count(*) > 0
), vss_no_preferred AS (
  SELECT 'VSS_NO_PREFERRED'::text AS codigo, 'warning'::text AS severidade,
         'Variantes ativas sem fornecedor preferido'::text AS mensagem, count(*)::text AS detalhe
    FROM product_variants pv
   WHERE pv.is_active = true
     AND NOT (EXISTS (SELECT 1 FROM variant_supplier_sources v
                       WHERE v.variant_id = pv.id AND v.is_preferred = true AND v.is_active = true))
  HAVING count(*) > 0
), ai_queue_stale AS (
  SELECT 'AI_QUEUE_STALE'::text AS codigo, 'info'::text AS severidade,
         'Itens na fila IA ha mais de 7 dias (worker inativo > 24h)'::text AS mensagem, count(*)::text AS detalhe
    FROM ai_enrichment_queue
   WHERE ai_enrichment_queue.status = 'pending'::text
     AND ai_enrichment_queue.created_at < (now() - '7 days'::interval)
     AND NOT (EXISTS (SELECT 1 FROM ai_enrichment_queue w
                       WHERE (w.status = 'processing'::text AND w.locked_at > (now() - '04:00:00'::interval))
                          OR (w.status = 'done'::text AND w.completed_at > (now() - '24:00:00'::interval))
                       LIMIT 1))
  HAVING count(*) > 0
), products_no_ncm AS (
  SELECT 'PRODUCTS_NO_NCM'::text AS codigo, 'critical'::text AS severidade,
         'Produtos ativos sem NCM (fiscal)'::text AS mensagem, count(*)::text AS detalhe
    FROM products
   WHERE products.is_active = true AND products.ncm_id IS NULL
  HAVING count(*) > 0
), stock_critical AS (
  SELECT 'STOCK_CRITICAL_LOW'::text AS codigo, 'info'::text AS severidade,
         'Variantes ativas com estoque zero'::text AS mensagem, count(*)::text AS detalhe
    FROM product_variants pv
    JOIN variant_supplier_sources v ON v.variant_id = pv.id
   WHERE pv.is_active = true AND v.is_active = true AND v.quantity = 0
  HAVING count(*) > 0
), stale_sync AS (
  SELECT 'SUPPLIER_SYNC_STALE'::text AS codigo, 'warning'::text AS severidade,
         ((('Fornecedor "'::text || s.name) || '" sem sync ha '::text)
            || round(EXTRACT(epoch FROM now() - s.last_full_sync_at) / 3600::numeric, 1)::text) || 'h'::text AS mensagem,
         s.last_full_sync_at::text AS detalhe
    FROM suppliers s
   WHERE s.sync_enabled = true
     AND (s.last_full_sync_at IS NULL
          OR s.last_full_sync_at < (now() - ((LEAST(GREATEST(COALESCE(s.sync_interval_minutes, 60) * 4, 240), 1440) || ' minutes'::text)::interval)))
), locked_by_residual AS (
  SELECT 'AI_QUEUE_LOCKED_RESIDUAL'::text AS codigo, 'warning'::text AS severidade,
         'Items ai_enrichment_queue com locked_by residual em estado terminal'::text AS mensagem, count(*)::text AS detalhe
    FROM ai_enrichment_queue
   WHERE ai_enrichment_queue.locked_by IS NOT NULL
     AND (ai_enrichment_queue.status <> ALL (ARRAY['processing'::text, 'pending'::text]))
  HAVING count(*) > 100
), schema_drift AS (
  SELECT 'SCHEMA_DRIFT_DETECTED'::text AS codigo, 'warning'::text AS severidade,
         'Schema divergente da baseline certificada (possivel alteracao do bot Lovable)'::text AS mensagem,
         format('cols +%s/-%s/~%s; tabelas +%s/-%s (baseline=%s; verificado %s)'::text,
                l.n_added, l.n_removed, l.n_retyped,
                COALESCE(array_length(l.tables_added, 1), 0), COALESCE(array_length(l.tables_removed, 1), 0),
                l.baseline_label, l.ran_at::timestamp(0) without time zone) AS detalhe
    FROM schema_signature_drift_log l
   WHERE l.ran_at = (SELECT max(l2.ran_at) FROM schema_signature_drift_log l2)
     AND l.has_drift = true
), silver_promote_stalled AS (
  SELECT 'SILVER_PROMOTE_STALLED'::text AS codigo,
         'warning'::text AS severidade,
         'Promocao Prata->Ouro possivelmente parada (pads padronizados ha >2h ou variantes orfas com pai ja promovido)'::text AS mensagem,
         format('pads_std_2h=%s, variantes_orfas=%s',
            (SELECT count(*) FROM produtos_padronizacao pp
              WHERE pp.status::text = 'standardized' AND pp.standardized_at < (now() - '02:00:00'::interval)),
            (SELECT count(*) FROM produtos_padronizacao_variantes pv
              WHERE pv.status::text = 'standardized'
                AND EXISTS (SELECT 1 FROM produtos_padronizacao pp2
                             WHERE pp2.supplier_id = pv.supplier_id
                               AND pp2.supplier_reference = pv.parent_reference
                               AND pp2.status::text = 'promoted'))
         ) AS detalhe
   WHERE (
       (SELECT count(*) FROM produtos_padronizacao pp
         WHERE pp.status::text = 'standardized' AND pp.standardized_at < (now() - '02:00:00'::interval))
     + (SELECT count(*) FROM produtos_padronizacao_variantes pv
         WHERE pv.status::text = 'standardized'
           AND EXISTS (SELECT 1 FROM produtos_padronizacao pp2
                        WHERE pp2.supplier_id = pv.supplier_id
                          AND pp2.supplier_reference = pv.parent_reference
                          AND pp2.status::text = 'promoted'))
   ) > 0
)
SELECT codigo, severidade, mensagem, detalhe, now() AS detected_at
  FROM (
        SELECT codigo, severidade, mensagem, detalhe FROM cron_alerts
  UNION ALL SELECT codigo, severidade, mensagem, detalhe FROM import_stalled
  UNION ALL SELECT codigo, severidade, mensagem, detalhe FROM products_no_image
  UNION ALL SELECT codigo, severidade, mensagem, detalhe FROM vss_no_preferred
  UNION ALL SELECT codigo, severidade, mensagem, detalhe FROM ai_queue_stale
  UNION ALL SELECT codigo, severidade, mensagem, detalhe FROM products_no_ncm
  UNION ALL SELECT codigo, severidade, mensagem, detalhe FROM stock_critical
  UNION ALL SELECT codigo, severidade, mensagem, detalhe FROM stale_sync
  UNION ALL SELECT codigo, severidade, mensagem, detalhe FROM locked_by_residual
  UNION ALL SELECT codigo, severidade, mensagem, detalhe FROM schema_drift
  UNION ALL SELECT codigo, severidade, mensagem, detalhe FROM silver_promote_stalled
  ) c
 ORDER BY (CASE severidade WHEN 'critical'::text THEN 1 WHEN 'warning'::text THEN 2 ELSE 3 END);

NOTIFY pgrst, 'reload schema';
;

-- <<< END 20260626182116_m6_add_silver_promote_stalled_alert_20260626.sql <<<

-- >>> BEGIN 20260626182213_mod03_xgroup_multipart_union.sql >>>
-- 45 cross-grupo onde o NOME cita ambos materiais (jsonb E normalizado) => produto multi-material.
-- União NÃO-destrutiva: adiciona ao normalizado os tipos resolvidos do jsonb que faltam (percentage=NULL).
-- fn_sync regenera o jsonb = união. organization_id derivado das linhas pm existentes do produto.
SELECT set_config('app.bulk_import_mode','true', true);

WITH d AS (
  SELECT p.id, extensions.unaccent(lower(p.name)) AS lname, p.materials,
    (SELECT array_agg(DISTINCT mt.group_id) FROM (SELECT public.fn_find_material_type_id(e) AS tid FROM jsonb_array_elements_text(p.materials) j(e)) s JOIN material_types mt ON mt.id=s.tid) AS jgroups,
    (SELECT array_agg(DISTINCT mt.group_id) FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id WHERE pm.product_id=p.id AND pm.is_active) AS ngroups,
    (SELECT array_agg(DISTINCT s.tid) FROM (SELECT public.fn_find_material_type_id(e) AS tid FROM jsonb_array_elements_text(p.materials) j(e)) s WHERE s.tid IS NOT NULL) AS jids,
    (SELECT array_agg(DISTINCT pm.material_id) FROM product_materials pm WHERE pm.product_id=p.id AND pm.is_active) AS nids
  FROM products p WHERE p.is_active
),
c462 AS (SELECT * FROM d WHERE jids IS NOT NULL AND nids IS NOT NULL AND NOT (jids @> nids AND nids @> jids) AND NOT (ngroups @> jgroups)),
corr AS (
  SELECT t.id,
    (SELECT bool_or(t.lname LIKE '%'||left(extensions.unaccent(lower(w)),5)||'%') FROM jsonb_array_elements_text(t.materials) j(e), unnest(string_to_array(e,' ')) w WHERE length(w)>=5) AS jcorr,
    (SELECT bool_or(t.lname LIKE '%'||left(extensions.unaccent(lower(w)),5)||'%') FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id, unnest(string_to_array(mt.name,' ')) w WHERE pm.product_id=t.id AND pm.is_active AND length(w)>=5 AND w NOT ILIKE 'gen%rico') AS ncorr
  FROM c462 t
),
tgt AS (SELECT id FROM corr WHERE jcorr AND ncorr),
to_add AS (
  SELECT t.id AS product_id, s.tid AS material_id,
    (SELECT pm.organization_id FROM product_materials pm WHERE pm.product_id=t.id LIMIT 1) AS org
  FROM tgt t JOIN products p ON p.id=t.id
  CROSS JOIN LATERAL (SELECT DISTINCT public.fn_find_material_type_id(e) AS tid FROM jsonb_array_elements_text(p.materials) j(e)) s
  WHERE s.tid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM product_materials pm2 WHERE pm2.product_id=t.id AND pm2.material_id=s.tid AND pm2.is_active)
)
INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, is_active, sort_order)
SELECT org, product_id, material_id, 'corpo', NULL, true, 200 FROM to_add
ON CONFLICT (product_id, material_id) DO UPDATE SET is_active=true, updated_at=now();;

-- <<< END 20260626182213_mod03_xgroup_multipart_union.sql <<<

-- >>> BEGIN 20260626182352_fix_has_optional_flag_trigger_scope_and_residue.sql >>>
-- ════════════════════════════════════════════════════════════════════
-- CORRECAO DE GAP (achado em teste adversarial): trg_set_has_optional_packaging
-- so observava packing_classification, deixando 2 produtos com flag dessincronizada
-- (residuo historico) e nao ressincronizando mudancas de optional_packaging_ref /
-- description_packaging_info. Correcao: re-backfill global + ampliar escopo do trigger.
-- A sincronizacao por mudanca de COMPAT continua coberta por trg_compat_sync_optional.
-- fix_version=2026-06-26_flag_trigger_scope_v1
-- ════════════════════════════════════════════════════════════════════

UPDATE products p SET has_optional_packaging = (
      COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
      OR p.optional_packaging_ref IS NOT NULL OR p.packing_classification='protective'
      OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active AND c.fit_rating IN ('tight','good','loose')))
WHERE p.product_type IN ('product','kit') AND COALESCE(p.has_optional_packaging,false) IS DISTINCT FROM (
      COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
      OR p.optional_packaging_ref IS NOT NULL OR p.packing_classification='protective'
      OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active AND c.fit_rating IN ('tight','good','loose')));

-- ANTI-REGRESSAO: o trigger DEVE observar as 3 colunas de sinal (nao apenas packing_classification)
DROP TRIGGER IF EXISTS trg_set_has_optional_packaging ON products;
CREATE TRIGGER trg_set_has_optional_packaging
  BEFORE INSERT OR UPDATE OF packing_classification, optional_packaging_ref, description_packaging_info
  ON products FOR EACH ROW EXECUTE FUNCTION fn_trigger_set_has_optional_packaging();

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260626182352_fix_has_optional_flag_trigger_scope_and_residue.sql <<<

-- >>> BEGIN 20260626182411_mod03_xgroup_jsonb_confirmed_replace.sql >>>
-- 170 cross-grupo onde o NOME confirma o jsonb e NENHUM material normalizado => normalizado ERRADO.
-- REPLACE: captura tipos do jsonb ANTES (evita armadilha cascata), desativa pm errados, insere os corretos.
-- jsonb-confirmado pelo nome = alta confiança. Reversível (is_active). fn_sync regenera o jsonb.
DO $$
BEGIN
  PERFORM set_config('app.bulk_import_mode','true', true);

  CREATE TEMP TABLE _fix ON COMMIT DROP AS
  WITH d AS (
    SELECT p.id, extensions.unaccent(lower(p.name)) AS lname, p.materials,
      (SELECT array_agg(DISTINCT mt.group_id) FROM (SELECT public.fn_find_material_type_id(e) AS tid FROM jsonb_array_elements_text(p.materials) j(e)) s JOIN material_types mt ON mt.id=s.tid) AS jgroups,
      (SELECT array_agg(DISTINCT mt.group_id) FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id WHERE pm.product_id=p.id AND pm.is_active) AS ngroups,
      (SELECT array_agg(DISTINCT s.tid) FROM (SELECT public.fn_find_material_type_id(e) AS tid FROM jsonb_array_elements_text(p.materials) j(e)) s WHERE s.tid IS NOT NULL) AS jids,
      (SELECT array_agg(DISTINCT pm.material_id) FROM product_materials pm WHERE pm.product_id=p.id AND pm.is_active) AS nids
    FROM products p WHERE p.is_active
  ),
  c462 AS (SELECT * FROM d WHERE jids IS NOT NULL AND nids IS NOT NULL AND NOT (jids @> nids AND nids @> jids) AND NOT (ngroups @> jgroups)),
  corr AS (
    SELECT t.id,
      (SELECT bool_or(t.lname LIKE '%'||left(extensions.unaccent(lower(w)),5)||'%') FROM jsonb_array_elements_text(t.materials) j(e), unnest(string_to_array(e,' ')) w WHERE length(w)>=5) AS jcorr,
      (SELECT bool_or(t.lname LIKE '%'||left(extensions.unaccent(lower(w)),5)||'%') FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id, unnest(string_to_array(mt.name,' ')) w WHERE pm.product_id=t.id AND pm.is_active AND length(w)>=5 AND w NOT ILIKE 'gen%rico') AS ncorr
    FROM c462 t
  ),
  tgt AS (SELECT id FROM corr WHERE jcorr AND NOT ncorr)
  SELECT t.id AS product_id, s.tid AS material_id,
    (SELECT pm.organization_id FROM product_materials pm WHERE pm.product_id=t.id LIMIT 1) AS org
  FROM tgt t JOIN products p ON p.id=t.id
  CROSS JOIN LATERAL (SELECT DISTINCT public.fn_find_material_type_id(e) AS tid FROM jsonb_array_elements_text(p.materials) j(e)) s
  WHERE s.tid IS NOT NULL;

  UPDATE product_materials SET is_active=false, updated_at=now()
  WHERE product_id IN (SELECT DISTINCT product_id FROM _fix) AND is_active;

  INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, is_active, sort_order)
  SELECT org, product_id, material_id, 'corpo', NULL, true, 100 FROM _fix
  ON CONFLICT (product_id, material_id) DO UPDATE SET is_active=true, updated_at=now();
END $$;;

-- <<< END 20260626182411_mod03_xgroup_jsonb_confirmed_replace.sql <<<

-- >>> BEGIN 20260626182418_fix_role_sync_derole_to_null.sql >>>
-- GAP FIX revelado por teste: ao remover TODAS as roles, profiles.role vira NULL
-- (sem papel) em vez de manter o ultimo valor (stale/phantom). role e nullable e o
-- CHECK aceita NULL. Sem impacto em dados atuais (0 usuarios sem role).
CREATE OR REPLACE FUNCTION public.fn_sync_profile_role_from_user_roles(p_user_id uuid)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $func$
DECLARE v_enum text; v_mapped text;
BEGIN
  SELECT ur.role::text INTO v_enum
  FROM public.user_roles ur
  WHERE ur.user_id = p_user_id
  ORDER BY CASE ur.role::text
    WHEN 'dev' THEN 1 WHEN 'admin' THEN 2 WHEN 'coordenador' THEN 3
    WHEN 'supervisor' THEN 4 WHEN 'manager' THEN 5 WHEN 'agente' THEN 6
    WHEN 'vendedor' THEN 7 ELSE 99 END
  LIMIT 1;

  v_mapped := CASE WHEN v_enum IS NULL THEN NULL
                   ELSE public.fn_map_role_enum_to_profile(v_enum) END;

  UPDATE public.profiles
     SET role = v_mapped, updated_at = now()
   WHERE user_id = p_user_id AND role IS DISTINCT FROM v_mapped;
END; $func$;;

-- <<< END 20260626182418_fix_role_sync_derole_to_null.sql <<<

-- >>> BEGIN 20260626183215_mod03_restore_emptied_via_extraction.sql >>>
-- Restaura material dos produtos ativos esvaziados (jsonb=[] e zero pm) usando a função oficial
-- fn_extract_materials_from_name (varre nome+descrição). Resolve ~11; os demais (sem keyword) ficam para etapa manual.
-- p_replace_existing=false: como não há pm, procede com a extração. fn_sync regenera jsonb+auto_material.
DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN SELECT p.id FROM products p
           WHERE p.is_active AND NOT EXISTS (SELECT 1 FROM product_materials pm WHERE pm.product_id=p.id AND pm.is_active)
  LOOP
    PERFORM public.fn_extract_materials_from_name(r.id, false);
  END LOOP;
END $$;;

-- <<< END 20260626183215_mod03_restore_emptied_via_extraction.sql <<<

-- >>> BEGIN 20260626183355_mod03_restore_emptied_manual_mapping.sql >>>
-- Restaura os 10 produtos esvaziados que a extração automática não cobriu (nome sem keyword de material).
-- Material derivado de nome+categoria (domínio): sacola/mochila->Poliéster, régua plástica->Plástico Genérico,
-- agenda/caderno/bloco cromato/papel->Cartão/Papel, garrafa/copo térmico->Aço Inox, lanterna->Alumínio.
-- Resolução por NOME do tipo (sem hardcode de UUID). Idempotente (só atinge ainda-vazios). fn_sync regenera jsonb.
WITH mapping(sku,matname) AS (
  VALUES ('09276','Poliéster'),('09277','Alumínio'),('13763A','Plástico Genérico'),
         ('14707','Poliéster'),('14930','Cartão'),('14932','Cartão'),
         ('15466A','Papel Genérico'),('E@09291','Aço Inox'),('E@09292','Aço Inox'),
         ('P@11933','Papel Genérico')
),
resolved AS (
  SELECT p.id AS product_id, p.organization_id AS org, mt.id AS material_id
  FROM mapping m
  JOIN products p ON p.sku_promo=m.sku
  JOIN material_types mt ON mt.name=m.matname AND mt.is_active
  WHERE p.is_active AND NOT EXISTS (SELECT 1 FROM product_materials pm WHERE pm.product_id=p.id AND pm.is_active)
)
INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, is_active, sort_order)
SELECT org, product_id, material_id, 'corpo', 100, true, 1 FROM resolved
ON CONFLICT (product_id, material_id) DO UPDATE SET is_active=true, updated_at=now();;

