-- >>> BEGIN 20260626183609_reconcile_eco_date_active_products_missing_20260626.sql >>>
-- Reconciliação: 2 produtos ATIVOS com material eco têm a categoria Ecologia mas faltava
-- a data comemorativa "Dia do Meio Ambiente" que o trigger fn_auto_link_eco_material vincula.
-- Aplica a MESMA regra canônica (set-based, idempotente, shape espelhado). Reversível via log.
-- ANTI-REGRESSAO: NÃO remover; alinha eco-material -> eco-date para produtos ativos.

CREATE TABLE IF NOT EXISTS public.eco_date_reconcile_log_20260626 (
  product_id uuid PRIMARY KEY,
  sku text,
  name text,
  commemorative_date_id uuid,
  reconciled_at timestamptz DEFAULT now()
);

INSERT INTO public.eco_date_reconcile_log_20260626(product_id, sku, name, commemorative_date_id)
SELECT DISTINCT pm.product_id, p.sku, p.name, '11b59fa3-14f1-4f5b-8c92-2e9bcb03e216'::uuid
FROM product_materials pm
JOIN eco_material_config e ON e.material_id=pm.material_id AND COALESCE(e.is_active,true)
JOIN products p ON p.id=pm.product_id
WHERE pm.is_active AND p.is_active AND p.is_deleted IS NOT TRUE
  AND NOT EXISTS (SELECT 1 FROM product_commemorative_dates pcd
                  WHERE pcd.product_id=pm.product_id
                    AND pcd.commemorative_date_id='11b59fa3-14f1-4f5b-8c92-2e9bcb03e216')
ON CONFLICT (product_id) DO NOTHING;

INSERT INTO product_commemorative_dates
  (product_id, commemorative_date_id, source, category_id, is_featured, relevance_score, display_order, is_active)
SELECT DISTINCT pm.product_id, '11b59fa3-14f1-4f5b-8c92-2e9bcb03e216'::uuid,
       'category', NULL::uuid, false, 5, 0, true
FROM product_materials pm
JOIN eco_material_config e ON e.material_id=pm.material_id AND COALESCE(e.is_active,true)
JOIN products p ON p.id=pm.product_id
WHERE pm.is_active AND p.is_active AND p.is_deleted IS NOT TRUE
  AND NOT EXISTS (SELECT 1 FROM product_commemorative_dates pcd
                  WHERE pcd.product_id=pm.product_id
                    AND pcd.commemorative_date_id='11b59fa3-14f1-4f5b-8c92-2e9bcb03e216')
ON CONFLICT (product_id, commemorative_date_id) DO NOTHING;;

-- <<< END 20260626183609_reconcile_eco_date_active_products_missing_20260626.sql <<<

-- >>> BEGIN 20260626183832_mod03_review_regen_textconfirmed.sql >>>
-- 28 cross-grupo onde nome+descrição confirmam o NORMALIZADO (e não o jsonb) => jsonb stale. Regen do normalizado.
SELECT set_config('app.bulk_import_mode','true', true);
WITH d AS (
  SELECT p.id,
    extensions.unaccent(lower(COALESCE(p.name,'')||' '||COALESCE(p.description,'')||' '||COALESCE(p.short_description,''))) AS ltext,
    p.materials,
    (SELECT array_agg(e ORDER BY e) FROM jsonb_array_elements_text(p.materials) j(e)) AS jn,
    (SELECT array_agg(mt.name::text ORDER BY mt.name::text) FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id WHERE pm.product_id=p.id AND pm.is_active) AS nn
  FROM products p WHERE p.is_active
),
div AS (SELECT * FROM d WHERE jn IS DISTINCT FROM nn),
corr AS (
  SELECT t.id,
    (SELECT bool_or(t.ltext LIKE '%'||left(extensions.unaccent(lower(w)),5)||'%') FROM jsonb_array_elements_text(t.materials) j(e), unnest(string_to_array(e,' ')) w WHERE length(w)>=5) AS jcorr_text,
    (SELECT bool_or(t.ltext LIKE '%'||left(extensions.unaccent(lower(w)),5)||'%') FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id, unnest(string_to_array(mt.name,' ')) w WHERE pm.product_id=t.id AND pm.is_active AND length(w)>=5 AND w NOT ILIKE 'gen%rico') AS ncorr_text
  FROM div t
),
tgt AS (SELECT id FROM corr WHERE ncorr_text AND NOT jcorr_text)
UPDATE products p SET
  materials = COALESCE((SELECT jsonb_agg(mt.name ORDER BY pm.sort_order, mt.name) FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id WHERE pm.product_id=p.id AND pm.is_active),'[]'::jsonb),
  auto_material = (SELECT mt.name FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id WHERE pm.product_id=p.id AND pm.is_active ORDER BY pm.percentage DESC NULLS LAST, pm.sort_order ASC LIMIT 1),
  updated_at=now()
WHERE p.id IN (SELECT id FROM tgt);;

-- <<< END 20260626183832_mod03_review_regen_textconfirmed.sql <<<

-- >>> BEGIN 20260626184039_revoke_anon_internal_analytics_rupture_kpi_20260626.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- SECURITY: Revogar EXECUTE de anon em funções analytics internas
-- que expõem dados de estoque, EMA, ruptura, valor de inventário.
--
-- Funções alvo:
--   fn_rupture_quick_stats()               — stock value, gap, anomalias
--   fn_ema_kpi_by_level(boolean)           — KPI de cobertura por nível
--   fn_rupture_anomalia_report(numeric)    — anomalias de velocidade/EMA
--   fn_rupture_by_level(text,int,int,bool) — variantes em ruptura por nível
--   fn_rupture_health_check()              — saúde geral de ruptura
--
-- Evidências:
--   0 cron references, 0 RLS policy references, 0 function body refs
--   NOT in event trigger whitelist → inadvertidamente não incluídas no
--   mass REVOKE de 2026-06-19 (criadas antes do event trigger ou reaprovadas)
--
-- Impacto: apenas anon perde EXECUTE. service_role e authenticated mantêm.
-- Idempotente: REVOKE de grant inexistente é no-op.
--
-- fix_version=2026-06-26_revoke_rupture_kpi_anon
-- ANTI-REGRESSÃO: NÃO reconceder anon EXECUTE nestas funções.
-- ═══════════════════════════════════════════════════════════════════

REVOKE EXECUTE ON FUNCTION public.fn_rupture_quick_stats()                                            FROM anon, PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_ema_kpi_by_level(boolean)                                        FROM anon, PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_rupture_anomalia_report(numeric)                                  FROM anon, PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_rupture_by_level(text, integer, integer, boolean)                 FROM anon, PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_rupture_health_check()                                            FROM anon, PUBLIC;

-- Auto-validação
DO $$
DECLARE v_fn text; v_has_anon boolean;
BEGIN
  FOR v_fn IN VALUES ('fn_rupture_quick_stats'),('fn_ema_kpi_by_level'),('fn_rupture_anomalia_report'),('fn_rupture_by_level'),('fn_rupture_health_check') LOOP
    SELECT EXISTS (
      SELECT 1 FROM pg_proc p2 JOIN pg_namespace n2 ON n2.oid=p2.pronamespace
      CROSS JOIN LATERAL aclexplode(COALESCE(p2.proacl,acldefault('f',p2.proowner))) ace
      WHERE n2.nspname='public' AND p2.proname=v_fn
        AND ace.privilege_type='EXECUTE' AND ace.grantee IN (0,(SELECT oid FROM pg_roles WHERE rolname='anon'))
    ) INTO v_has_anon;
    IF v_has_anon THEN
      RAISE EXCEPTION 'FALHA: % ainda tem anon EXECUTE', v_fn;
    END IF;
  END LOOP;
  RAISE NOTICE 'OK: 5 rupture/KPI fns sem anon EXECUTE';
END $$;

NOTIFY pgrst, 'reload schema';
;

-- <<< END 20260626184039_revoke_anon_internal_analytics_rupture_kpi_20260626.sql <<<

-- >>> BEGIN 20260626190428_mod03_review_union_textconfirmed.sql >>>
