-- União NÃO-destrutiva: adiciona ao normalizado os tipos do jsonb que faltam, com part=NULL/percentage=NULL
-- (não viola validate_material_percentages: NULL contribui 0 e cada parte já soma <=100). fn_sync regenera o jsonb.
-- Exclui (por construção) qualquer caso jsonb-confirmado-por-NOME que exigiria replace (b_replace_nome=0).
SELECT set_config('app.bulk_import_mode','true', true);
WITH d AS (
  SELECT p.id,
    extensions.unaccent(lower(p.name)) AS lname,
    extensions.unaccent(lower(COALESCE(p.name,'')||' '||COALESCE(p.description,'')||' '||COALESCE(p.short_description,''))) AS ltext,
    p.materials,
    (SELECT array_agg(e ORDER BY e) FROM jsonb_array_elements_text(p.materials) j(e)) AS jn,
    (SELECT array_agg(mt.name::text ORDER BY mt.name::text) FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id WHERE pm.product_id=p.id AND pm.is_active) AS nn
  FROM products p WHERE p.is_active
),
div AS (SELECT * FROM d WHERE jn IS DISTINCT FROM nn),
corr AS (
  SELECT t.id,
    (SELECT bool_or(t.lname LIKE '%'||left(extensions.unaccent(lower(w)),5)||'%') FROM jsonb_array_elements_text(t.materials) j(e), unnest(string_to_array(e,' ')) w WHERE length(w)>=5) AS jcorr_name,
    (SELECT bool_or(t.ltext LIKE '%'||left(extensions.unaccent(lower(w)),5)||'%') FROM jsonb_array_elements_text(t.materials) j(e), unnest(string_to_array(e,' ')) w WHERE length(w)>=5) AS jcorr_text,
    (SELECT bool_or(t.ltext LIKE '%'||left(extensions.unaccent(lower(w)),5)||'%') FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id, unnest(string_to_array(mt.name,' ')) w WHERE pm.product_id=t.id AND pm.is_active AND length(w)>=5 AND w NOT ILIKE 'gen%rico') AS ncorr_text
  FROM div t
),
tgt AS (SELECT id FROM corr WHERE jcorr_text AND NOT (jcorr_name AND NOT ncorr_text)),
to_add AS (
  SELECT t.id AS product_id, s.tid AS material_id,
    (SELECT pm.organization_id FROM product_materials pm WHERE pm.product_id=t.id LIMIT 1) AS org
  FROM tgt t JOIN products p ON p.id=t.id
  CROSS JOIN LATERAL (SELECT DISTINCT public.fn_find_material_type_id(e) AS tid FROM jsonb_array_elements_text(p.materials) j(e)) s
  WHERE s.tid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM product_materials pm2 WHERE pm2.product_id=t.id AND pm2.material_id=s.tid AND pm2.is_active)
)
INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, is_active, sort_order)
SELECT org, product_id, material_id, NULL, NULL, true, 200 FROM to_add
ON CONFLICT (product_id, material_id) DO UPDATE SET is_active=true, percentage=NULL, updated_at=now();;

-- <<< END 20260626190428_mod03_review_union_textconfirmed.sql <<<

-- >>> BEGIN 20260626190543_packaging_compat_auto_recalc_on_dim_change.sql >>>
-- ════════════════════════════════════════════════════════════════════
-- PREVENCAO DE GAP ARQUITETURAL (achado em teste adversarial):
-- dimensoes de produtos/embalagens mudam no pipeline de ingestao e a
-- compatibilidade ficava STALE (87 registros diziam "cabe" sem caber, 43
-- produtos recomendavam caixa que nao cabe). Este trigger recalcula a
-- compat via fn_calculate_packaging_fit (fonte de verdade) sempre que
-- alguma dimensao relevante muda, e re-elege o recomendado.
-- Cobre mudanca de dims do PRODUTO (product_id=NEW.id) e da EMBALAGEM (packaging_id=NEW.id).
-- Sem recursao: UPDATE em compat dispara trg_compat_sync_optional (flag),
-- cujo UPDATE em products.has_optional_packaging nao toca dims nem as 3
-- colunas observadas por trg_set_has_optional_packaging.
-- fix_version=2026-06-26_compat_dim_recalc_v1
-- ════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION fn_recalc_compat_on_dim_change() RETURNS trigger
LANGUAGE plpgsql SET search_path TO 'public' AS $fn$
BEGIN
  UPDATE product_packaging_compatibility c
  SET fit_rating=(f.fit->>'fit_rating'),
      fit_gap_min_mm=NULLIF(f.fit->>'gap_min_mm','')::numeric,
      fit_gap_avg_mm=NULLIF(f.fit->>'gap_avg_mm','')::numeric,
      fit_gap_height_mm=NULLIF(f.fit->>'gap_height_mm','')::numeric,
      fit_gap_width_mm=NULLIF(f.fit->>'gap_width_mm','')::numeric,
      fit_gap_length_mm=NULLIF(f.fit->>'gap_length_mm','')::numeric,
      fit_gap_diameter_mm=NULLIF(f.fit->>'gap_diameter_mm','')::numeric,
      needs_padding=COALESCE((f.fit->>'needs_padding')::boolean,false),
      updated_at=now()
  FROM (SELECT cc.id, fn_calculate_packaging_fit(cc.product_id, cc.packaging_id, cc.config_type_used) AS fit
        FROM product_packaging_compatibility cc WHERE (cc.product_id=NEW.id OR cc.packaging_id=NEW.id) AND cc.active) f
  WHERE c.id=f.id
    AND (c.fit_rating IS DISTINCT FROM (f.fit->>'fit_rating')
         OR c.fit_gap_min_mm IS DISTINCT FROM NULLIF(f.fit->>'gap_min_mm','')::numeric);

  WITH ranked AS (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY
      CASE compatibility_source WHEN 'supplier_indicated' THEN 1 WHEN 'dimension_matching' THEN 2 WHEN 'dimension_calculated' THEN 3 ELSE 4 END,
      CASE fit_rating WHEN 'tight' THEN 1 WHEN 'good' THEN 2 WHEN 'loose' THEN 3 ELSE 4 END, COALESCE(fit_gap_min_mm,99999)) rn
    FROM product_packaging_compatibility
    WHERE product_id IN (SELECT DISTINCT product_id FROM product_packaging_compatibility WHERE (product_id=NEW.id OR packaging_id=NEW.id) AND active)
      AND active AND fit_rating IN ('tight','good','loose'))
  UPDATE product_packaging_compatibility c SET is_recommended=COALESCE(r.rn=1,false)
  FROM ranked r WHERE c.id=r.id AND c.is_recommended IS DISTINCT FROM COALESCE(r.rn=1,false);

  UPDATE product_packaging_compatibility SET is_recommended=false
  WHERE active AND is_recommended AND COALESCE(fit_rating,'x') NOT IN ('tight','good','loose')
    AND product_id IN (SELECT DISTINCT product_id FROM product_packaging_compatibility WHERE (product_id=NEW.id OR packaging_id=NEW.id) AND active);
  RETURN NEW;
END$fn$;

DROP TRIGGER IF EXISTS trg_recalc_compat_on_dims ON products;
CREATE TRIGGER trg_recalc_compat_on_dims
AFTER UPDATE OF height_cm, width_cm, length_cm, diameter_cm, shape_type, internal_height_cm, internal_width_cm, internal_length_cm
ON products FOR EACH ROW
WHEN (OLD.height_cm IS DISTINCT FROM NEW.height_cm OR OLD.width_cm IS DISTINCT FROM NEW.width_cm OR OLD.length_cm IS DISTINCT FROM NEW.length_cm
   OR OLD.diameter_cm IS DISTINCT FROM NEW.diameter_cm OR OLD.shape_type IS DISTINCT FROM NEW.shape_type
   OR OLD.internal_height_cm IS DISTINCT FROM NEW.internal_height_cm OR OLD.internal_width_cm IS DISTINCT FROM NEW.internal_width_cm OR OLD.internal_length_cm IS DISTINCT FROM NEW.internal_length_cm)
EXECUTE FUNCTION fn_recalc_compat_on_dim_change();

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260626190543_packaging_compat_auto_recalc_on_dim_change.sql <<<

-- >>> BEGIN 20260626190708_packaging_compat_stale_refresh_v1.sql >>>
-- ════════════════════════════════════════════════════════════════════
-- REFRESH do estado STALE (achado em teste adversarial): 107 compat
-- desatualizadas por mudanca de dimensoes (87 diziam "cabe" sem caber,
-- 43 produtos recomendavam caixa que nao cabe). Recalcula via fit-funcao
-- (fonte de verdade) os candidatos detectados + re-elege recomendados +
-- ressincroniza a flag. A prevencao (trg_recalc_compat_on_dims) impede recorrencia.
-- fix_version=2026-06-26_compat_stale_refresh_v1
-- ════════════════════════════════════════════════════════════════════

-- (1) Refresh dos candidatos (gap recalculado das dims atuais difere do armazenado)
WITH cand AS (
  SELECT c.id FROM product_packaging_compatibility c JOIN products p ON p.id=c.product_id JOIN products pk ON pk.id=c.packaging_id
  WHERE c.active AND ROUND((CASE WHEN p.shape_type='cylindrical'
        THEN LEAST((GREATEST(pk.internal_height_cm,pk.internal_width_cm,pk.internal_length_cm)-p.height_cm)*10,(LEAST(pk.internal_height_cm,pk.internal_width_cm,pk.internal_length_cm)-COALESCE(p.diameter_cm,p.width_cm))*10)
        ELSE LEAST((pk.internal_height_cm-p.height_cm)*10,(pk.internal_width_cm-p.width_cm)*10,(pk.internal_length_cm-p.length_cm)*10) END)::numeric,0)
      IS DISTINCT FROM ROUND(c.fit_gap_min_mm,0)
),
recalc AS (SELECT c.id, fn_calculate_packaging_fit(c.product_id,c.packaging_id,c.config_type_used) AS fit
           FROM product_packaging_compatibility c WHERE c.id IN (SELECT id FROM cand))
UPDATE product_packaging_compatibility c
SET fit_rating=(r.fit->>'fit_rating'), fit_gap_min_mm=NULLIF(r.fit->>'gap_min_mm','')::numeric, fit_gap_avg_mm=NULLIF(r.fit->>'gap_avg_mm','')::numeric,
    fit_gap_height_mm=NULLIF(r.fit->>'gap_height_mm','')::numeric, fit_gap_width_mm=NULLIF(r.fit->>'gap_width_mm','')::numeric,
    fit_gap_length_mm=NULLIF(r.fit->>'gap_length_mm','')::numeric, fit_gap_diameter_mm=NULLIF(r.fit->>'gap_diameter_mm','')::numeric,
    needs_padding=COALESCE((r.fit->>'needs_padding')::boolean,false), updated_at=now()
FROM recalc r WHERE c.id=r.id;

-- (2) Re-eleger recomendados (NULL-safe) globalmente
WITH ranked AS (
  SELECT id, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY
      CASE compatibility_source WHEN 'supplier_indicated' THEN 1 WHEN 'dimension_matching' THEN 2 WHEN 'dimension_calculated' THEN 3 ELSE 4 END,
      CASE fit_rating WHEN 'tight' THEN 1 WHEN 'good' THEN 2 WHEN 'loose' THEN 3 ELSE 4 END, COALESCE(fit_gap_min_mm,99999)) rn
  FROM product_packaging_compatibility WHERE active AND fit_rating IN ('tight','good','loose'))
UPDATE product_packaging_compatibility c SET is_recommended=COALESCE(r.rn=1,false)
FROM ranked r WHERE r.id=c.id AND c.is_recommended IS DISTINCT FROM COALESCE(r.rn=1,false);

UPDATE product_packaging_compatibility SET is_recommended=false
WHERE active AND is_recommended AND COALESCE(fit_rating,'x') NOT IN ('tight','good','loose');

-- (3) Ressincronizar flag has_optional_packaging
UPDATE products p SET has_optional_packaging = (
      COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
      OR p.optional_packaging_ref IS NOT NULL OR p.packing_classification='protective'
      OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active AND c.fit_rating IN ('tight','good','loose')))
WHERE p.product_type IN ('product','kit') AND COALESCE(p.has_optional_packaging,false) IS DISTINCT FROM (
      COALESCE((p.description_packaging_info->>'has_optional_mention')::boolean,false)
      OR p.optional_packaging_ref IS NOT NULL OR p.packing_classification='protective'
      OR EXISTS (SELECT 1 FROM product_packaging_compatibility c WHERE c.product_id=p.id AND c.active AND c.fit_rating IN ('tight','good','loose')));

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260626190708_packaging_compat_stale_refresh_v1.sql <<<

-- >>> BEGIN 20260626190738_mod03_review_regen_hybrid4.sql >>>
-- 4 cross-grupo (matcher híbrido nome+desc, siglas curtas) onde o normalizado é confirmado e o jsonb não. Regen do normalizado.
SELECT set_config('app.bulk_import_mode','true', true);
WITH d AS (
  SELECT p.id,
    extensions.unaccent(lower(p.name)) AS lname,
    extensions.unaccent(lower(COALESCE(p.name,'')||' '||COALESCE(p.description,'')||' '||COALESCE(p.short_description,''))) AS ltext,
    p.materials,
    (SELECT array_agg(e ORDER BY e) FROM jsonb_array_elements_text(p.materials) j(e)) AS jn,
    (SELECT array_agg(mt.name::text ORDER BY mt.name::text) FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id WHERE pm.product_id=p.id AND pm.is_active) AS nn
  FROM products p WHERE p.is_active
),
div AS (SELECT * FROM d WHERE jn IS DISTINCT FROM nn),
corr AS (
  SELECT t.id,
    (SELECT bool_or(CASE WHEN length(tok)>=5 THEN t.lname LIKE '%'||left(tok,5)||'%' WHEN length(tok)>=2 THEN t.lname ~ ('\m'||tok||'\M') ELSE false END)
       FROM jsonb_array_elements_text(t.materials) j(e), LATERAL (SELECT regexp_replace(extensions.unaccent(lower(w)),'[^a-z0-9]','','g') AS tok FROM unnest(string_to_array(e,' ')) w) z) AS jcorr_text,
    (SELECT bool_or(CASE WHEN length(tok)>=5 THEN t.ltext LIKE '%'||left(tok,5)||'%' WHEN length(tok)>=2 THEN t.ltext ~ ('\m'||tok||'\M') ELSE false END)
       FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id, LATERAL (SELECT regexp_replace(extensions.unaccent(lower(w)),'[^a-z0-9]','','g') AS tok FROM unnest(string_to_array(mt.name,' ')) w) z
       WHERE pm.product_id=t.id AND pm.is_active AND tok NOT ILIKE 'gen%rico') AS ncorr_text
  FROM div t
),
tgt AS (SELECT id FROM corr WHERE ncorr_text AND NOT jcorr_text)
UPDATE products p SET
  materials = COALESCE((SELECT jsonb_agg(mt.name ORDER BY pm.sort_order, mt.name) FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id WHERE pm.product_id=p.id AND pm.is_active),'[]'::jsonb),
  auto_material = (SELECT mt.name FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id WHERE pm.product_id=p.id AND pm.is_active ORDER BY pm.percentage DESC NULLS LAST, pm.sort_order ASC LIMIT 1),
  updated_at=now()
WHERE p.id IN (SELECT id FROM tgt);;

-- <<< END 20260626190738_mod03_review_regen_hybrid4.sql <<<

-- >>> BEGIN 20260626190800_mod03_review_union_hybrid15.sql >>>
-- 15 cross-grupo (matcher híbrido) onde nome+desc confirmam o material do jsonb (multi-material). União não-destrutiva.
SELECT set_config('app.bulk_import_mode','true', true);
WITH d AS (
  SELECT p.id,
    extensions.unaccent(lower(p.name)) AS lname,
    extensions.unaccent(lower(COALESCE(p.name,'')||' '||COALESCE(p.description,'')||' '||COALESCE(p.short_description,''))) AS ltext,
    p.materials,
    (SELECT array_agg(e ORDER BY e) FROM jsonb_array_elements_text(p.materials) j(e)) AS jn,
    (SELECT array_agg(mt.name::text ORDER BY mt.name::text) FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id WHERE pm.product_id=p.id AND pm.is_active) AS nn
  FROM products p WHERE p.is_active
),
div AS (SELECT * FROM d WHERE jn IS DISTINCT FROM nn),
corr AS (
  SELECT t.id,
    (SELECT bool_or(CASE WHEN length(tok)>=5 THEN t.lname LIKE '%'||left(tok,5)||'%' WHEN length(tok)>=2 THEN t.lname ~ ('\m'||tok||'\M') ELSE false END)
       FROM jsonb_array_elements_text(t.materials) j(e), LATERAL (SELECT regexp_replace(extensions.unaccent(lower(w)),'[^a-z0-9]','','g') AS tok FROM unnest(string_to_array(e,' ')) w) z) AS jcorr_name,
    (SELECT bool_or(CASE WHEN length(tok)>=5 THEN t.ltext LIKE '%'||left(tok,5)||'%' WHEN length(tok)>=2 THEN t.ltext ~ ('\m'||tok||'\M') ELSE false END)
       FROM jsonb_array_elements_text(t.materials) j(e), LATERAL (SELECT regexp_replace(extensions.unaccent(lower(w)),'[^a-z0-9]','','g') AS tok FROM unnest(string_to_array(e,' ')) w) z) AS jcorr_text,
    (SELECT bool_or(CASE WHEN length(tok)>=5 THEN t.ltext LIKE '%'||left(tok,5)||'%' WHEN length(tok)>=2 THEN t.ltext ~ ('\m'||tok||'\M') ELSE false END)
       FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id, LATERAL (SELECT regexp_replace(extensions.unaccent(lower(w)),'[^a-z0-9]','','g') AS tok FROM unnest(string_to_array(mt.name,' ')) w) z
       WHERE pm.product_id=t.id AND pm.is_active AND tok NOT ILIKE 'gen%rico') AS ncorr_text
  FROM div t
),
tgt AS (SELECT id FROM corr WHERE jcorr_text AND NOT (jcorr_name AND NOT ncorr_text)),
to_add AS (
  SELECT t.id AS product_id, s.tid AS material_id,
    (SELECT pm.organization_id FROM product_materials pm WHERE pm.product_id=t.id LIMIT 1) AS org
  FROM tgt t JOIN products p ON p.id=t.id
  CROSS JOIN LATERAL (SELECT DISTINCT public.fn_find_material_type_id(e) AS tid FROM jsonb_array_elements_text(p.materials) j(e)) s
  WHERE s.tid IS NOT NULL AND NOT EXISTS (SELECT 1 FROM product_materials pm2 WHERE pm2.product_id=t.id AND pm2.material_id=s.tid AND pm2.is_active)
)
INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, is_active, sort_order)
SELECT org, product_id, material_id, NULL, NULL, true, 200 FROM to_add
ON CONFLICT (product_id, material_id) DO UPDATE SET is_active=true, percentage=NULL, updated_at=now();;

