-- >>> BEGIN 20260626190845_mod03_review_replace_hybrid4.sql >>>
-- 4 cross-grupo onde o NOME confirma o jsonb e não o normalizado (ex.: Caderno cartão rotulado "Aço Inox", Esteira ptfe rotulada "Plástico Genérico").
-- REPLACE name-confirmado: captura tipo do jsonb ANTES, desativa pm errado, insere o correto (100% corpo). Reversível.
DO $$
BEGIN
  PERFORM set_config('app.bulk_import_mode','true', true);
  CREATE TEMP TABLE _fix ON COMMIT DROP AS
  WITH d AS (
    SELECT p.id,
      extensions.unaccent(lower(p.name)) AS lname,
      extensions.unaccent(lower(COALESCE(p.name,'')||' '||COALESCE(p.description,'')||' '||COALESCE(p.short_description,''))) AS ltext,
      p.materials,
      (SELECT array_agg(e ORDER BY e) FROM jsonb_array_elements_text(p.materials) j(e)) AS jn,
      (SELECT array_agg(mt.name::text ORDER BY mt.name::text) FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id WHERE pm.product_id=p.id AND pm.is_active) AS nn
    FROM products p WHERE p.is_active
  ),
  div AS (SELECT * FROM d WHERE jn IS DISTINCT FROM nn),
  corr AS (
    SELECT t.id,
      (SELECT bool_or(CASE WHEN length(tok)>=5 THEN t.lname LIKE '%'||left(tok,5)||'%' WHEN length(tok)>=2 THEN t.lname ~ ('\m'||tok||'\M') ELSE false END)
         FROM jsonb_array_elements_text(t.materials) j(e), LATERAL (SELECT regexp_replace(extensions.unaccent(lower(w)),'[^a-z0-9]','','g') AS tok FROM unnest(string_to_array(e,' ')) w) z) AS jcorr_name,
      (SELECT bool_or(CASE WHEN length(tok)>=5 THEN t.ltext LIKE '%'||left(tok,5)||'%' WHEN length(tok)>=2 THEN t.ltext ~ ('\m'||tok||'\M') ELSE false END)
         FROM product_materials pm JOIN material_types mt ON mt.id=pm.material_id, LATERAL (SELECT regexp_replace(extensions.unaccent(lower(w)),'[^a-z0-9]','','g') AS tok FROM unnest(string_to_array(mt.name,' ')) w) z
         WHERE pm.product_id=t.id AND pm.is_active AND tok NOT ILIKE 'gen%rico') AS ncorr_text
    FROM div t
  ),
  tgt AS (SELECT id FROM corr WHERE jcorr_name AND NOT ncorr_text)
  SELECT t.id AS product_id, s.tid AS material_id,
    (SELECT pm.organization_id FROM product_materials pm WHERE pm.product_id=t.id LIMIT 1) AS org
  FROM tgt t JOIN products p ON p.id=t.id
  CROSS JOIN LATERAL (SELECT DISTINCT public.fn_find_material_type_id(e) AS tid FROM jsonb_array_elements_text(p.materials) j(e)) s
  WHERE s.tid IS NOT NULL;

  UPDATE product_materials SET is_active=false, updated_at=now() WHERE product_id IN (SELECT DISTINCT product_id FROM _fix) AND is_active;
  INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, is_active, sort_order)
  SELECT org, product_id, material_id, 'corpo', 100, true, 1 FROM _fix
  ON CONFLICT (product_id, material_id) DO UPDATE SET is_active=true, percentage=100, part='corpo', updated_at=now();
END $$;;

-- <<< END 20260626190845_mod03_review_replace_hybrid4.sql <<<

-- >>> BEGIN 20260626190952_m7_fix_supplier_sync_interval_xbz_stricker_20260626.sql >>>
-- ============================================================================
-- M7: corrige sync_interval_minutes de XBZ e STRICKER.
-- Estavam em 30 (cadencia do FAST-sync), mas o alerta stale_sync usa
-- sync_interval_minutes*4 como threshold sobre last_full_sync_at (full import,
-- cadencia real ~4h) => threshold 4h ~ cadencia => FLAP de SUPPLIER_SYNC_STALE.
-- Correcao: 240 (=> threshold LEAST(GREATEST(240*4,240),1440)=16h, igual ASIA).
-- Elimina o flap; mantem deteccao de stall real (>16h). Coberto em granularidade
-- fina por IMPORT_STALLED (1h) e SILVER_PROMOTE_STALLED (2h).
-- SEGURANCA: sync_interval_minutes e ALERT-ONLY (nenhuma funcao em pg_proc a le; verificado).
-- PROVA (dry-run BEGIN/ROLLBACK): dispara_agora=false, flaparia_se_8h=false, detecta_stall_20h=true.
-- fix_version = supplier_sync_interval_honest_v1
-- ============================================================================
UPDATE public.suppliers
   SET sync_interval_minutes = 240
 WHERE code IN ('XBZ','STRICKER')
   AND sync_interval_minutes IS DISTINCT FROM 240;
;

-- <<< END 20260626190952_m7_fix_supplier_sync_interval_xbz_stricker_20260626.sql <<<

-- >>> BEGIN 20260626191306_mod03_review_curate_final17.sql >>>
-- Curadoria manual dos 17 cross-grupo multi-material (kits, cadernos capa+miolo, caneca palha-de-trigo, chaveiros zinco+PU),
-- derivada de leitura nome+descrição. REPLACE define o conjunto correto de materiais por produto (part=corpo, %=NULL).
-- Resolução por NOME do tipo (sem hardcode de UUID). Reversível. fn_sync regenera o jsonb = conjunto definido.
DO $$
BEGIN
  PERFORM set_config('app.bulk_import_mode','true', true);
  CREATE TEMP TABLE _map ON COMMIT DROP AS
  WITH mapping(sku, matname) AS (
    VALUES
    ('01644','Aço Inox'),('01644','Alumínio'),
    ('04098','Aço Inox'),
    ('05617','Nylon'),('05617','Couro Sintético (Ecológico)'),
    ('08542','Bambu'),('08542','Aço Inox'),
    ('10081','Aço Inox'),('10081','Alumínio'),
    ('12071','Aço Inox'),('12071','Nylon'),
    ('15160','Aço Inox'),
    ('18862','Fibras Naturais'),('18862','Polipropileno (PP)'),
    ('51738','Madeira'),
    ('93726','Cartão'),('93726','Papel Genérico'),
    ('93727','Cartão'),('93727','Papel Genérico'),
    ('93728','Cartão'),('93728','Papel Genérico'),
    ('CAD011P','Fibras Naturais'),('CAD011P','Papel Genérico'),
    ('CAD165','Plástico - rPET'),('CAD165','Papel Genérico'),
    ('CAD170','Plástico - rPET'),('CAD170','Papel Genérico'),
    ('CH7035P','Metal Genérico'),('CH7035P','Couro Sintético (Ecológico)'),
    ('CH7055P','Metal Genérico'),('CH7055P','Couro Sintético (Ecológico)')
  )
  SELECT p.id AS product_id, p.organization_id AS org, mt.id AS material_id
  FROM mapping m
  JOIN products p ON p.sku_promo = m.sku AND p.is_active
  JOIN material_types mt ON mt.name = m.matname AND mt.is_active;

  UPDATE product_materials SET is_active=false, updated_at=now()
  WHERE product_id IN (SELECT DISTINCT product_id FROM _map) AND is_active;

  INSERT INTO product_materials (organization_id, product_id, material_id, part, percentage, is_active, sort_order)
  SELECT org, product_id, material_id, 'corpo', NULL, true, 1 FROM _map
  ON CONFLICT (product_id, material_id) DO UPDATE SET is_active=true, percentage=NULL, part='corpo', updated_at=now();
END $$;;

