-- >>> BEGIN 20260626191915_mod03_fix_process_auto_multielement.sql >>>
CREATE OR REPLACE FUNCTION public.fn_process_product_materials_auto(p_product_id uuid, p_replace_existing boolean DEFAULT false)
 RETURNS TABLE(material_name text, material_type_id uuid, status text)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
-- [fix_version: mod03_fix_multielement_2026-06] Corrige bug de array multi-elemento.
-- ANTES: o loop por elemento do jsonb desligava p_replace_existing após a 1ª iteração; aí
-- fn_process_composite_materials abortava nos elementos seguintes (guard "já tem materiais"),
-- criando pm SOMENTE do 1º elemento em arrays multi-elemento (ex.: ["Aço Inox","Alumínio"] => só Aço Inox).
-- AGORA: concatena TODOS os elementos num único string delimitado por ', ' (delimitador reconhecido por
-- fn_split_materials) e chama fn_process_composite_materials UMA vez, distribuindo % entre todos.
-- NÃO reverter para loop-por-elemento (regressão conhecida).
DECLARE
    v_product RECORD;
    v_combined TEXT;
BEGIN
    SELECT id, name, organization_id, materials
    INTO v_product
    FROM products
    WHERE id = p_product_id;

    IF v_product IS NULL THEN
        material_name := 'ERRO'; material_type_id := NULL;
        status := 'Produto não encontrado: ' || p_product_id;
        RETURN NEXT; RETURN;
    END IF;

    IF v_product.materials IS NULL
       OR v_product.materials = '[]'::jsonb
       OR jsonb_array_length(v_product.materials) = 0 THEN
        material_name := 'AVISO'; material_type_id := NULL;
        status := 'Produto "' || v_product.name || '" não tem materials preenchido';
        RETURN NEXT; RETURN;
    END IF;

    SELECT string_agg(elem #>> '{}', ', ')
      INTO v_combined
      FROM jsonb_array_elements(v_product.materials) elem
      WHERE NULLIF(TRIM(elem #>> '{}'), '') IS NOT NULL;

    IF NULLIF(TRIM(COALESCE(v_combined,'')), '') IS NULL THEN
        material_name := 'AVISO'; material_type_id := NULL;
        status := 'Materials vazio após normalização';
        RETURN NEXT; RETURN;
    END IF;

    RETURN QUERY
    SELECT * FROM fn_process_composite_materials(
        p_product_id, v_combined, v_product.organization_id, p_replace_existing
    );
    RETURN;
END;
$function$;;

-- <<< END 20260626191915_mod03_fix_process_auto_multielement.sql <<<

-- >>> BEGIN 20260626192059_m10_recreate_purge_old_stock_snapshots_and_daily_cron_20260626.sql >>>
-- ============================================================================
-- M10: recria fn_purge_old_stock_snapshots (REMOVIDA -> cron 272 chamava funcao
-- inexistente; halt silencioso classe M6) e converte o job para cadencia DIARIA.
--
-- CONTEXTO (medido 2026-06-26): stock_snapshots = 3,87M linhas / 1,3GB, change-log
-- de estoque com ~184k linhas/dia, dados desde 2026-06-05 (21d). Nada >60d hoje
-- => primeira execucao apaga 0 (zero-risco), mas sem purga cresce ilimitado.
-- Leitor vinculante: fn_capacity_forecast usa lookback de 30 dias => retencao 60d
-- (buffer 2x). stock_daily_summary (336k lin) preserva o historico AGREGADO.
--
-- DESIGN: DELETE bounded por subquery LIMIT (usa idx_snapshots_captured_at,
-- Index Scan Backward) -> cabe no timeout; advisory_xact_lock evita concorrencia;
-- cadencia DIARIA pois o inflow diario (~184k) << batch (500k) mantem o ritmo
-- (purga semanal nao acompanharia 1,3M/semana dentro do timeout).
-- SEGURANCA: SECURITY DEFINER + SET search_path=public; EXECUTE revogado de
-- public/anon/authenticated (nao expor como RPC PostgREST).
-- ANTI-REGRESSAO: nao remover novamente; cron 272 deve chamar esta funcao.
-- fix_version = purge_stock_snapshots_bounded_daily_v1
-- ============================================================================
CREATE OR REPLACE FUNCTION public.fn_purge_old_stock_snapshots(
  p_retention_days integer DEFAULT 60,
  p_batch          integer DEFAULT 500000
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_cutoff timestamptz := now() - make_interval(days => GREATEST(p_retention_days, 31));
  v_deleted integer := 0;
BEGIN
  -- lock transacional: se outra execucao roda, sai sem erro
  IF NOT pg_try_advisory_xact_lock(91010060) THEN
    RETURN jsonb_build_object('status','skipped_locked','ts',now());
  END IF;

  -- piso de seguranca: nunca apaga abaixo de 31 dias (protege o lookback de 30d do forecast)
  DELETE FROM public.stock_snapshots
   WHERE id IN (
     SELECT id FROM public.stock_snapshots
      WHERE captured_at < v_cutoff
      ORDER BY captured_at
      LIMIT GREATEST(p_batch, 1)
   );
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'status','ok',
    'cutoff', v_cutoff,
    'retention_days_efetivo', GREATEST(p_retention_days, 31),
    'batch', GREATEST(p_batch, 1),
    'deletados', v_deleted,
    'ts', now()
  );
END
$function$;

REVOKE ALL ON FUNCTION public.fn_purge_old_stock_snapshots(integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.fn_purge_old_stock_snapshots(integer, integer) TO service_role;

-- Reescalona o cron 272: semanal -> DIARIO 03:11, timeout 180s, args explicitos.
SELECT cron.alter_job(
  job_id   := 272,
  schedule := '11 3 * * *',
  command  := $cmd$SELECT public.fn_cron_safe_run(5::bigint, 'SELECT public.fn_purge_old_stock_snapshots(60, 500000);', 180000, 'stock-snapshots-purge');$cmd$
);
;

-- <<< END 20260626192059_m10_recreate_purge_old_stock_snapshots_and_daily_cron_20260626.sql <<<

-- >>> BEGIN 20260626193153_color_rebuild_missing_swatches.sql >>>
-- 22 produtos ativos com cores (color_name nas variantes) porém color_swatches vazio/nulo (cache stale).
-- Regenera via builder oficial fn_rebuild_color_swatches (dedupe por color_id, hex/nome/stock corretos, image_url com fallback).
-- Idempotente: só atinge os de swatch vazio. Não dispara cascata (triggers de rebuild são em product_images/product_variants).
UPDATE products SET color_swatches = public.fn_rebuild_color_swatches(id)
WHERE is_active
  AND EXISTS(SELECT 1 FROM product_variants v WHERE v.product_id=products.id AND v.is_active AND NULLIF(TRIM(v.color_name),'') IS NOT NULL)
  AND (color_swatches IS NULL OR jsonb_array_length(COALESCE(color_swatches,'[]'::jsonb))=0);;

-- <<< END 20260626193153_color_rebuild_missing_swatches.sql <<<

