-- >>> BEGIN 20260626202240_20260626_backfill_ordem_exibicao_curated_order_tpgo.sql >>>
-- CORRECTIVE BACKFILL (fix 2026-06-26): ordem_exibicao on tabela_preco_gravacao_oficial must honor
-- the curated catalog order defined in tecnicas_gravacao (parent technique linked via
-- grupo_tecnica = tecnicas_gravacao.codigo), then codigo_tabela within each group.
-- The initial backfill (migration 20260626120000) used pure alphabetical codigo_tabela order, which
-- ignored the curated tecnicas_gravacao.ordem_exibicao (16 distinct values 10..100, deliberate gaps).
-- This corrects all rows to the curated grouping order. Deterministic & idempotent (re-running is a no-op).
WITH ranked AS (
  SELECT t.id,
         row_number() OVER (ORDER BY g.ordem_exibicao, t.codigo_tabela, t.id) AS new_ord
  FROM public.tabela_preco_gravacao_oficial t
  JOIN public.tecnicas_gravacao g ON g.codigo::text = t.grupo_tecnica::text
)
UPDATE public.tabela_preco_gravacao_oficial t
SET ordem_exibicao = ranked.new_ord
FROM ranked
WHERE ranked.id = t.id
  AND t.ordem_exibicao IS DISTINCT FROM ranked.new_ord;

COMMENT ON COLUMN public.tabela_preco_gravacao_oficial.ordem_exibicao IS
'ANTI-REGRESSION (fix 2026-06-26): display order for the technique-list UI. Frontend reads this table via bridge alias tecnica_gravacao (dbInvoke BRIDGE_ALIASES) and ORDERs BY ordem_exibicao; column previously existed only on tecnicas_gravacao, causing PostgREST 400 (42703). NOT NULL DEFAULT 99 (intentionally STRICTER than tecnicas_gravacao.ordem_exibicao which is nullable - prevents ordering surprises). Values backfilled to honor the CURATED order: parent technique tecnicas_gravacao.ordem_exibicao (joined via grupo_tecnica=tecnicas_gravacao.codigo), then codigo_tabela within group. DO NOT DROP.';;

-- <<< END 20260626202240_20260626_backfill_ordem_exibicao_curated_order_tpgo.sql <<<

-- >>> BEGIN 20260626202310_color_rebuild_stale_swatches.sql >>>
-- Produtos cujo conjunto de color_ids no color_swatches != conjunto de color_ids das variantes ativas (cache stale,
-- variantes adicionadas/alteradas sem disparar rebuild — ex.: bulk import). Regenera via builder oficial fn_rebuild_color_swatches.
-- Idempotente; só atinge os stale. Garante 1 chip por cor real da variante.
UPDATE products p SET color_swatches = public.fn_rebuild_color_swatches(p.id)
WHERE p.is_active
  AND (SELECT array_agg(DISTINCT v.color_id::text ORDER BY v.color_id::text) FROM product_variants v WHERE v.product_id=p.id AND v.is_active AND v.color_id IS NOT NULL) IS NOT NULL
  AND COALESCE((SELECT array_agg(DISTINCT (s->>'color_id') ORDER BY (s->>'color_id')) FROM jsonb_array_elements(p.color_swatches) s WHERE jsonb_typeof(p.color_swatches)='array' AND (s->>'color_id') IS NOT NULL),'{}'::text[])
      IS DISTINCT FROM COALESCE((SELECT array_agg(DISTINCT v.color_id::text ORDER BY v.color_id::text) FROM product_variants v WHERE v.product_id=p.id AND v.is_active AND v.color_id IS NOT NULL),'{}'::text[]);;

-- <<< END 20260626202310_color_rebuild_stale_swatches.sql <<<

-- >>> BEGIN 20260626202323_m10b_purge_inbody_fixversion_marker_20260626.sql >>>
-- M10b: move o marcador fix_version para DENTRO do corpo de fn_purge_old_stock_snapshots
-- (estava so no cabecalho da migration M10, invisivel a pg_get_functiondef). Logica inalterada:
-- mesmo piso de 31d, advisory lock, delete bounded, retorno jsonb (tudo ja validado).
-- Assim o marcador some se o bot Lovable reescrever o corpo -> deteccao de regressao.
CREATE OR REPLACE FUNCTION public.fn_purge_old_stock_snapshots(p_retention_days integer DEFAULT 60, p_batch integer DEFAULT 500000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cutoff timestamptz := now() - make_interval(days => GREATEST(p_retention_days, 31));
  v_deleted integer := 0;
BEGIN
  -- fix_version: purge_stock_snapshots_bounded_daily_v1
  -- lock transacional: se outra execucao roda, sai sem erro
  IF NOT pg_try_advisory_xact_lock(91010060) THEN
    RETURN jsonb_build_object('status','skipped_locked','ts',now());
  END IF;

  -- piso de seguranca: nunca apaga abaixo de 31 dias (protege o lookback de 30d do forecast)
  DELETE FROM public.stock_snapshots
   WHERE id IN (
     SELECT id FROM public.stock_snapshots
      WHERE captured_at < v_cutoff
      ORDER BY captured_at
      LIMIT GREATEST(p_batch, 1)
   );
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN jsonb_build_object(
    'status','ok',
    'cutoff', v_cutoff,
    'retention_days_efetivo', GREATEST(p_retention_days, 31),
    'batch', GREATEST(p_batch, 1),
    'deletados', v_deleted,
    'ts', now()
  );
END
$function$;;

