-- >>> BEGIN 20260626202945_color_fix_sync_colors_filter_is_active.sql >>>
-- [anti-regressao 2026-06 | fix_version color_sync_isactive] BUG: fn_sync_product_colors_from_variants e
-- fn_sync_all_product_colors agregavam color_name SEM filtrar is_active, enquanto fn_rebuild_color_swatches
-- filtra is_active=true. Assimetria: ao desativar uma variante, o swatch removia a cor mas products.colors NAO
-- (recomputava incluindo a variante inativa) => colors podia ficar stale com cores descontinuadas.
-- Semantica correta: colors/has_colors refletem variantes ATIVAS. Impacto na aplicacao = 0 (nenhum produto
-- atualmente tem cor exclusiva de variante inativa). NAO REMOVER o filtro is_active.

CREATE OR REPLACE FUNCTION public.fn_sync_product_colors_from_variants(p_product_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_colors JSONB;
    v_has_colors BOOLEAN;
BEGIN
    SELECT
        COALESCE(jsonb_agg(DISTINCT color_name ORDER BY color_name), '[]'::JSONB),
        COUNT(DISTINCT color_name) > 0
    INTO v_colors, v_has_colors
    FROM product_variants
    WHERE product_id = p_product_id
      AND is_active = true                         -- [fix color_sync_isactive] so cores de variantes ATIVAS
      AND color_name IS NOT NULL
      AND color_name != '';

    UPDATE products
    SET colors = v_colors, has_colors = v_has_colors
    WHERE id = p_product_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.fn_sync_all_product_colors()
 RETURNS TABLE(total_products integer, products_with_colors integer, products_without_colors integer)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    v_total INTEGER := 0;
    v_with_colors INTEGER := 0;
    v_without_colors INTEGER := 0;
BEGIN
    UPDATE products p
    SET
        colors = COALESCE((
            SELECT jsonb_agg(DISTINCT v.color_name ORDER BY v.color_name)
            FROM product_variants v
            WHERE v.product_id = p.id
              AND v.is_active = true               -- [fix color_sync_isactive]
              AND v.color_name IS NOT NULL
              AND v.color_name != ''
        ), '[]'::JSONB),
        has_colors = EXISTS (
            SELECT 1 FROM product_variants v
            WHERE v.product_id = p.id
              AND v.is_active = true               -- [fix color_sync_isactive]
              AND v.color_name IS NOT NULL
              AND v.color_name != ''
        );

    SELECT COUNT(*) INTO v_total FROM products;
    SELECT COUNT(*) INTO v_with_colors FROM products WHERE has_colors = true;
    v_without_colors := v_total - v_with_colors;
    RETURN QUERY SELECT v_total, v_with_colors, v_without_colors;
END;
$function$;;

-- <<< END 20260626202945_color_fix_sync_colors_filter_is_active.sql <<<

-- >>> BEGIN 20260626203128_color_fix_sync_colors_trigger_on_isactive.sql >>>
-- [anti-regressao 2026-06 | fix_version color_sync_isactive] GAP: trg_sync_colors_to_product disparava apenas em
-- UPDATE OF color_name, color_id -- NAO em is_active. Resultado: ao desativar/reativar uma variante, o swatch era
-- reconstruido (trg_rebuild_swatches_on_variant ja inclui is_active) mas products.colors NAO era ressincronizado,
-- podendo ficar stale (listar cor de variante descontinuada). Alinha a lista de colunas com o trigger de swatch.
-- NAO REMOVER is_active da lista de colunas.
DROP TRIGGER IF EXISTS trg_sync_colors_to_product ON public.product_variants;
CREATE TRIGGER trg_sync_colors_to_product
  AFTER INSERT OR DELETE OR UPDATE OF color_name, color_id, is_active
  ON public.product_variants
  FOR EACH ROW EXECUTE FUNCTION fn_trigger_sync_colors_to_product();;

-- <<< END 20260626203128_color_fix_sync_colors_trigger_on_isactive.sql <<<

-- >>> BEGIN 20260626203142_m14_fix_drift_check_temptable_idempotent_20260626.sql >>>
-- M14: torna fn_check_schema_signature_drift idempotente DENTRO de uma transacao.
-- BUG: cria TEMP TABLE _live e _diff com ON COMMIT DROP; como ON COMMIT DROP so limpa no
-- COMMIT, chamar a funcao 2x na MESMA transacao colidia com 42P07 "_live already exists".
-- Em producao o cron 245 chama 1x/dia (nao disparava), mas era fragil. Correcao: DROP IF
-- EXISTS das 2 temp tables no inicio. Logica de comparacao/allowlist/log inalterada.
-- fix_version: schema_drift_local_guard_v4
CREATE OR REPLACE FUNCTION public.fn_check_schema_signature_drift()
 RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_added jsonb := '{}'::jsonb; v_removed jsonb := '{}'::jsonb; v_retyped jsonb := '{}'::jsonb;
  v_tadded text[]; v_tremoved text[];
  v_n_add int; v_n_rem int; v_n_ret int;
  v_has_drift boolean; v_label text; v_log_id uuid;
BEGIN
  -- fix_version: schema_drift_local_guard_v4 (idempotente intra-transacao: DROP IF EXISTS
  --   das TEMP TABLEs _live/_diff; ON COMMIT DROP so limpa no commit, entao 2 chamadas na
  --   mesma transacao colidiam com 42P07 relation "_live" already exists)
  DROP TABLE IF EXISTS _live;
  DROP TABLE IF EXISTS _diff;
  SELECT baseline_label INTO v_label FROM public.schema_signature_baseline LIMIT 1;
  CREATE TEMP TABLE _live ON COMMIT DROP AS
    SELECT table_name, column_name, data_type FROM information_schema.columns
    WHERE table_schema='public' AND table_name NOT LIKE 'pg_%' AND table_name NOT LIKE '_backup_%';
  CREATE TEMP TABLE _diff ON COMMIT DROP AS
    SELECT COALESCE(b.table_name,l.table_name) AS table_name, COALESCE(b.column_name,l.column_name) AS column_name,
      b.data_type AS base_type, l.data_type AS live_type,
      CASE WHEN b.column_name IS NULL THEN 'added' WHEN l.column_name IS NULL THEN 'removed'
           WHEN b.data_type IS DISTINCT FROM l.data_type THEN 'retyped' ELSE 'same' END AS verdict
    FROM public.schema_signature_baseline b
    FULL OUTER JOIN _live l ON b.table_name=l.table_name AND b.column_name=l.column_name;
  DELETE FROM _diff d USING public.schema_signature_drift_allowlist a
   WHERE d.table_name=a.table_name AND (a.column_name IS NULL OR a.column_name=d.column_name);
  SELECT array_agg(t ORDER BY t) INTO v_tadded FROM (
    SELECT DISTINCT table_name t FROM _live EXCEPT SELECT DISTINCT table_name FROM public.schema_signature_baseline
  ) x WHERE t NOT IN (SELECT table_name FROM public.schema_signature_drift_allowlist WHERE column_name IS NULL);
  SELECT array_agg(t ORDER BY t) INTO v_tremoved FROM (
    SELECT DISTINCT table_name t FROM public.schema_signature_baseline EXCEPT SELECT DISTINCT table_name FROM _live
  ) x WHERE t NOT IN (SELECT table_name FROM public.schema_signature_drift_allowlist WHERE column_name IS NULL);
  v_tadded := COALESCE(v_tadded,'{}'); v_tremoved := COALESCE(v_tremoved,'{}');
  SELECT COALESCE(jsonb_object_agg(table_name,cols),'{}'::jsonb) INTO v_added
   FROM (SELECT table_name, jsonb_agg(column_name ORDER BY column_name) cols FROM _diff WHERE verdict='added' GROUP BY table_name) s;
  SELECT COALESCE(jsonb_object_agg(table_name,cols),'{}'::jsonb) INTO v_removed
   FROM (SELECT table_name, jsonb_agg(column_name ORDER BY column_name) cols FROM _diff WHERE verdict='removed' GROUP BY table_name) s;
  SELECT COALESCE(jsonb_object_agg(table_name,cols),'{}'::jsonb) INTO v_retyped
   FROM (SELECT table_name, jsonb_agg(jsonb_build_object('column',column_name,'from',base_type,'to',live_type) ORDER BY column_name) cols FROM _diff WHERE verdict='retyped' GROUP BY table_name) s;
  SELECT count(*) FILTER (WHERE verdict='added'), count(*) FILTER (WHERE verdict='removed'), count(*) FILTER (WHERE verdict='retyped')
    INTO v_n_add, v_n_rem, v_n_ret FROM _diff;
  v_has_drift := (COALESCE(v_n_add,0)+COALESCE(v_n_rem,0)+COALESCE(v_n_ret,0))>0 OR cardinality(v_tadded)>0 OR cardinality(v_tremoved)>0;
  INSERT INTO public.schema_signature_drift_log
    (has_drift,n_added,n_removed,n_retyped,columns_added,columns_removed,columns_retyped,tables_added,tables_removed,baseline_label)
  VALUES (v_has_drift,v_n_add,v_n_rem,v_n_ret,v_added,v_removed,v_retyped,v_tadded,v_tremoved,v_label)
  RETURNING id INTO v_log_id;
  RETURN jsonb_build_object('ok',true,'has_drift',v_has_drift,'log_id',v_log_id,'baseline_label',v_label,
    'n_added',v_n_add,'n_removed',v_n_rem,'n_retyped',v_n_ret,
    'columns_added',v_added,'columns_removed',v_removed,'columns_retyped',v_retyped,
    'tables_added',to_jsonb(v_tadded),'tables_removed',to_jsonb(v_tremoved));
END;
$function$;;

-- <<< END 20260626203142_m14_fix_drift_check_temptable_idempotent_20260626.sql <<<

-- >>> BEGIN 20260626203246_resync_product_physical_eliminate_drift_20260626.sql >>>
-- ============================================================
-- MELHORIA 5: Zerar o drift residual de product_physical (espelho de products)
-- Causa: fn_sync usa COALESCE(EXCLUDED.x, antigo) — quando products.x vira
-- NULL/0, o espelho mantinha o valor velho. 357 produtos divergiam.
-- Correção fiel: DELETE das linhas divergentes + re-sync (re-insere puro,
-- sem merge com valor antigo; produtos sem dims ficam corretamente sem espelho).
-- product_physical não tem FKs entrando nem consumidores no código → seguro.
-- NÃO altera a semântica da fn_sync (decisão de design → futura PR).
-- ============================================================
DO $$
DECLARE
  v_ids uuid[];
  r uuid;
BEGIN
  SELECT array_agg(pf.product_id) INTO v_ids
  FROM product_physical pf JOIN products p ON p.id = pf.product_id
  WHERE pf.weight_g       IS DISTINCT FROM NULLIF(p.weight_g,0)
     OR pf.height_cm      IS DISTINCT FROM NULLIF(p.height_cm,0)
     OR pf.width_cm       IS DISTINCT FROM NULLIF(p.width_cm,0)
     OR pf.length_cm      IS DISTINCT FROM NULLIF(p.length_cm,0)
     OR pf.diameter_cm    IS DISTINCT FROM NULLIF(p.diameter_cm,0)
     OR pf.capacity_ml    IS DISTINCT FROM NULLIF(p.capacity_ml,0)
     OR pf.box_volume_cm3 IS DISTINCT FROM NULLIF(p.box_volume_cm3,0)
     OR pf.box_quantity   IS DISTINCT FROM p.box_quantity;

  IF v_ids IS NULL THEN RETURN; END IF;

  DELETE FROM product_physical WHERE product_id = ANY(v_ids);

  FOREACH r IN ARRAY v_ids LOOP
    PERFORM fn_sync_product_physical_from_products(r);
  END LOOP;
END $$;;

-- <<< END 20260626203246_resync_product_physical_eliminate_drift_20260626.sql <<<

