-- ============================================================
-- MELHORIA 9: Remover índices plain redundantes (duplicatas exatas de
-- um UNIQUE/PK na mesma coluna). Reduz overhead de escrita e espaço.
-- Em cada caso o índice mantido (unique/pk) cobre as mesmas buscas;
-- 0 referências por nome em funções/crons. Os unique de matview são
-- preservados (exigidos por REFRESH CONCURRENTLY).
-- product_ai_history deixado intacto (ASC vs DESC não é duplicata pura).
-- ============================================================
DROP INDEX IF EXISTS analytics.idx_mv_product_intelligence_product_id;  -- dup de _unique (0 scans)
DROP INDEX IF EXISTS analytics.idx_mv_stock_velocity_vss_id;            -- dup de mv_stock_velocity_pk
DROP INDEX IF EXISTS public.cat_ancestors_desc_idx;                     -- dup de category_ancestors_pkey
DROP INDEX IF EXISTS public.idx_pns_product_id;                         -- dup de product_notebook_specs_product_id_key
DROP INDEX IF EXISTS public.idx_pn_product_active;                      -- dup de uq_pn_product_one_active;

-- <<< END 20260626203929_drop_duplicate_indexes_20260626.sql <<<

-- >>> BEGIN 20260627111109_products_sku_set_not_null_20260627.sql >>>
-- ============================================================
-- FIX DO GAP DETECTADO NA VALIDAÇÃO ADVERSARIAL (2026-06-27)
-- Causa: sku era nullable mas trigger trg_sync_sku_promo faz
-- NEW.sku_promo := NEW.sku, então sku=NULL → sku_promo=NULL
-- violaria NOT NULL em sku_promo (adicionado em migration anterior).
-- O erro seria em sku_promo, não em sku — mensagem confusa.
-- Fix: tornar o contrato explícito adicionando NOT NULL em sku.
-- Pré-condições verificadas: 0 nulos, sku_max_len=19 < 50.
-- A única função que insere em products (insert_or_update_product)
-- sempre gera sku = supplier_code || '-' || supplier_reference.
-- ============================================================
ALTER TABLE products ALTER COLUMN sku SET NOT NULL;;

-- <<< END 20260627111109_products_sku_set_not_null_20260627.sql <<<

-- >>> BEGIN 20260627111118_cleanup_dead_sku_promo_check_20260627.sql >>>
-- ============================================================
-- FIX: Remover cláusula IS NULL morta do check constraint.
-- Após sku_promo = NOT NULL (migration anterior) + sku = NOT NULL (migration acima),
-- a condição "sku_promo IS NULL" nunca pode ser verdadeira.
-- CHECK antigo: (sku_promo IS NULL) OR (sku_promo::text = sku)
-- CHECK novo:   sku_promo::text = sku
-- Equivalente em prática, mas o novo é mais rigoroso e explícito.
-- Pré-condição: 0 violações do novo CHECK verificadas em dry-run.
-- fix_version: v20260627_sku_promo_check_cleanup
-- anti-regression: bot Lovable pode reintroduzir IS NULL — monitorar.
-- ============================================================
ALTER TABLE products DROP CONSTRAINT IF EXISTS chk_products_sku_promo_equals_sku;
ALTER TABLE products ADD CONSTRAINT chk_products_sku_promo_equals_sku
  CHECK (sku_promo::text = sku);;

-- <<< END 20260627111118_cleanup_dead_sku_promo_check_20260627.sql <<<

-- >>> BEGIN 20260627111134_resync_product_physical_drift_20260627.sql >>>
-- ============================================================
-- RE-SYNC product_physical: eliminar os 6 drifts residuais
-- acumulados desde o re-sync de 2026-06-26.
-- CAUSA-RAIZ (documentada, NÃO corrigida aqui — requer PR):
--   fn_sync_product_physical_from_products usa
--   ON CONFLICT DO UPDATE SET x = COALESCE(EXCLUDED.x, product_physical.x)
--   Quando products.x vai para NULL/0, o espelho MANTÉM o valor antigo
--   porque COALESCE(NULL, antigo) = antigo.
-- CONSEQUÊNCIA: drift recorrente toda vez que o pipeline limpa um campo.
-- AÇÃO CORRETIVA AQUI: DELETE das linhas divergentes + re-sync puro
--   (sem COALESCE com valor antigo, a inserção é limpa).
-- RECOMENDAÇÃO PARA PR: mudar a semântica para overwrite
--   ou adicionar cron de re-sync semanal.
-- ============================================================
DO $$
DECLARE
  v_ids uuid[];
  r uuid;
BEGIN
  SELECT array_agg(pf.product_id) INTO v_ids
  FROM product_physical pf JOIN products p ON p.id = pf.product_id
  WHERE pf.weight_g       IS DISTINCT FROM NULLIF(p.weight_g,0)
     OR pf.height_cm      IS DISTINCT FROM NULLIF(p.height_cm,0)
     OR pf.width_cm       IS DISTINCT FROM NULLIF(p.width_cm,0)
     OR pf.length_cm      IS DISTINCT FROM NULLIF(p.length_cm,0)
     OR pf.diameter_cm    IS DISTINCT FROM NULLIF(p.diameter_cm,0)
     OR pf.capacity_ml    IS DISTINCT FROM NULLIF(p.capacity_ml,0)
     OR pf.box_volume_cm3 IS DISTINCT FROM NULLIF(p.box_volume_cm3,0)
     OR pf.box_quantity   IS DISTINCT FROM p.box_quantity;

  IF v_ids IS NULL THEN
    RAISE NOTICE 'Nenhum drift encontrado — produto_physical já consistente.';
    RETURN;
  END IF;

  RAISE NOTICE 'Re-sincronizando % linhas divergentes...', array_length(v_ids,1);
  DELETE FROM product_physical WHERE product_id = ANY(v_ids);

  FOREACH r IN ARRAY v_ids LOOP
    PERFORM fn_sync_product_physical_from_products(r);
  END LOOP;
  RAISE NOTICE 'Re-sync concluído.';
END $$;;

-- <<< END 20260627111134_resync_product_physical_drift_20260627.sql <<<

