-- >>> BEGIN 20260627111707_20260627000002_fn_auto_classify_product_image_anti_uuid_hardcode.sql >>>
-- ============================================================
-- Blindagem anti-regressão Lovable: substituir 10 UUIDs hardcoded
-- em fn_auto_classify_product_image por lookup dinâmico via code.
-- fix_version: anti_uuid_hardcode_20260627
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_auto_classify_product_image()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
-- ============================================================
-- fix_version: anti_uuid_hardcode_20260627
-- ANTI-REGRESSÃO LOVABLE: UUIDs resolvidos dinamicamente via code.
-- NUNCA hardcode UUIDs de image_types nesta função.
-- Se image_types for recriada/alterada, IDs são atualizados automaticamente.
-- ============================================================
DECLARE
    v_filename TEXT;
    v_image_type TEXT;
    v_image_type_id UUID;
    v_is_primary BOOLEAN := FALSE;
    v_display_order INTEGER;
    v_existing_primary_count INTEGER;
    v_color_id UUID;
    v_variant_id UUID;
    v_n_cores INTEGER;
    -- IDs resolvidos dinamicamente (anti-hardcode, anti-Lovable)
    v_id_set       UUID;
    v_id_logo      UUID;
    v_id_box       UUID;
    v_id_pouch     UUID;
    v_id_bag       UUID;
    v_id_ambient   UUID;
    v_id_detail    UUID;
    v_id_gallery   UUID;
    v_id_main      UUID;
    v_id_other     UUID;
BEGIN
    -- Resolver UUIDs por code (1 query, 18 linhas em cache permanente ~0.01ms)
    SELECT
      MAX(CASE WHEN code='set'     THEN id END),
      MAX(CASE WHEN code='logo'    THEN id END),
      MAX(CASE WHEN code='box'     THEN id END),
      MAX(CASE WHEN code='pouch'   THEN id END),
      MAX(CASE WHEN code='bag'     THEN id END),
      MAX(CASE WHEN code='ambient' THEN id END),
      MAX(CASE WHEN code='detail'  THEN id END),
      MAX(CASE WHEN code='gallery' THEN id END),
      MAX(CASE WHEN code='main'    THEN id END),
      MAX(CASE WHEN code='other'   THEN id END)
    INTO
      v_id_set, v_id_logo, v_id_box, v_id_pouch, v_id_bag,
      v_id_ambient, v_id_detail, v_id_gallery, v_id_main, v_id_other
    FROM image_types;

    IF v_id_gallery IS NULL OR v_id_main IS NULL THEN
      RAISE EXCEPTION 'fn_auto_classify: image_types incompleta — tipos essenciais (gallery, main) ausentes. fix_version:anti_uuid_hardcode_20260627';
    END IF;

    -- PRÉ-RESOLUÇÃO: se caller forneceu image_type válido sem image_type_id,
    -- resolver agora para garantir consistência com fn_sync_image_type_code
    IF NEW.image_type IS NOT NULL 
       AND NEW.image_type NOT IN ('other', '')
       AND NEW.image_type_id IS NULL THEN
        SELECT id INTO NEW.image_type_id 
        FROM image_types WHERE code = NEW.image_type LIMIT 1;
    END IF;

    v_filename := LOWER(COALESCE(
        SUBSTRING(NEW.url_original FROM '[^/]+$'),
        SUBSTRING(NEW.url_cdn FROM '[^/]+$'),
        ''
    ));

    -- ============================================================
    -- 1. Padrões baseados no filename
    -- ============================================================
    IF v_filename ~ '[-_]set[._-]' OR v_filename ~ '[-_]set$' THEN
        v_image_type := 'set';
        v_image_type_id := v_id_set;

    ELSIF v_filename ~ '[-_]c\.' THEN
        v_image_type := 'logo';
        v_image_type_id := v_id_logo;

    ELSIF v_filename ~ '[-_]box[._-]' OR v_filename ~ '[-_]box$' THEN
        v_image_type := 'box';
        v_image_type_id := v_id_box;

    ELSIF v_filename ~ '[-_]pouch[._-]' OR v_filename ~ '[-_]estojo[._-]' OR v_filename ~ '[-_]pouch$' THEN
        v_image_type := 'pouch';
        v_image_type_id := v_id_pouch;

    ELSIF v_filename ~ '[-_]bag[._-]' OR v_filename ~ '[-_]sacola[._-]' OR v_filename ~ '[-_]bag$' THEN
        v_image_type := 'bag';
        v_image_type_id := v_id_bag;

    ELSIF v_filename ~ '[-_]amb[._-]' OR v_filename ~ '[-_]ambiente[._-]' OR v_filename ~ '[-_]lifestyle[._-]'
       OR v_filename ~ '[-_]amb$' THEN
        v_image_type := 'ambient';
        v_image_type_id := v_id_ambient;

    ELSIF v_filename ~ '[-_]det[._-]' OR v_filename ~ '[-_]detalhe[._-]' OR v_filename ~ '[-_]detail[._-]'
       OR v_filename ~ '[-_]det$' THEN
        v_image_type := 'detail';
        v_image_type_id := v_id_detail;

    ELSIF v_filename ~ '[-_][de]\.' THEN
        v_image_type := 'gallery';
        v_image_type_id := v_id_gallery;

    ELSIF v_filename ~ '_\d{3}\.' THEN
        SELECT COUNT(*) INTO v_existing_primary_count
        FROM product_images 
        WHERE product_id = NEW.product_id 
          AND is_primary = TRUE AND is_active = TRUE;
        IF v_existing_primary_count = 0 THEN
            v_image_type := 'main';
            v_image_type_id := v_id_main;
            v_is_primary := TRUE;
        ELSE
            v_image_type := 'gallery';
            v_image_type_id := v_id_gallery;
        END IF;

    ELSIF v_filename ~ '_[a-z]\.' AND v_filename !~ '[-_]c\.' THEN
        v_image_type := 'gallery';
        v_image_type_id := v_id_gallery;

    -- ============================================================
    -- 2. Padrões baseados no cloudflare_image_id (fallback quando filename não resolve)
    -- NOTE ADR-001: preferir classificação via filename; CF ID é opaco por design.
    -- Este bloco existe para compatibilidade com IDs legados de fornecedores.
    -- ============================================================
    ELSIF NEW.cloudflare_image_id ~ '-gal-\d+$' OR NEW.cloudflare_image_id ~ '-d\d+$' THEN
        v_image_type := 'gallery';
        v_image_type_id := v_id_gallery;

    ELSIF NEW.cloudflare_image_id ~ '-main$' THEN
        SELECT COUNT(*) INTO v_existing_primary_count
        FROM product_images 
        WHERE product_id = NEW.product_id 
          AND is_primary = TRUE AND is_active = TRUE;
        IF v_existing_primary_count = 0 THEN
            v_image_type := 'main';
            v_image_type_id := v_id_main;
            v_is_primary := TRUE;
        ELSE
            v_image_type := 'gallery';
            v_image_type_id := v_id_gallery;
        END IF;

    ELSIF NEW.cloudflare_image_id ~ '-set$' OR NEW.cloudflare_image_id ~ '_set$' THEN
        v_image_type := 'set';
        v_image_type_id := v_id_set;

    ELSIF NEW.cloudflare_image_id ~ '-amb$' OR NEW.cloudflare_image_id ~ '_amb$' THEN
        v_image_type := 'ambient';
        v_image_type_id := v_id_ambient;

    ELSIF NEW.cloudflare_image_id ~ '-det$' OR NEW.cloudflare_image_id ~ '_det$' THEN
        v_image_type := 'detail';
        v_image_type_id := v_id_detail;

    ELSIF NEW.cloudflare_image_id ~ '-logo$' OR NEW.cloudflare_image_id ~ '-logo-[a-z]' OR NEW.cloudflare_image_id ~ '_logo$' THEN
        v_image_type := 'logo';
        v_image_type_id := v_id_logo;

    ELSIF NEW.cloudflare_image_id ~ '-box$' OR NEW.cloudflare_image_id ~ '_box$' THEN
        v_image_type := 'box';
        v_image_type_id := v_id_box;

    -- ============================================================
    -- 3. Caller explicitou um tipo válido → respeitar
    -- ============================================================
    ELSIF NEW.image_type IS NOT NULL AND NEW.image_type NOT IN ('other', '') THEN
        v_image_type := NEW.image_type;
        v_image_type_id := COALESCE(
            NEW.image_type_id,
            (SELECT id FROM image_types WHERE code = NEW.image_type LIMIT 1)
        );

    ELSE
        v_image_type := 'other';
        v_image_type_id := v_id_other;
    END IF;

    IF NOT v_is_primary THEN
        SELECT COUNT(*) INTO v_existing_primary_count
        FROM product_images 
        WHERE product_id = NEW.product_id 
          AND is_primary = TRUE AND is_active = TRUE;
        IF v_existing_primary_count = 0 AND v_image_type = 'main' THEN
            v_is_primary := TRUE;
        END IF;
    END IF;

    IF NEW.display_order IS NULL OR NEW.display_order = 0 THEN
        SELECT COALESCE(MAX(display_order), 0) + 1 INTO v_display_order
        FROM product_images WHERE product_id = NEW.product_id AND is_active = TRUE;
    ELSE
        v_display_order := NEW.display_order;
    END IF;

    NEW.image_type    := v_image_type;
    NEW.image_type_id := v_image_type_id;
    NEW.is_primary    := v_is_primary;
    NEW.display_order := v_display_order;

    IF v_is_primary THEN NEW.is_og_image := TRUE; END IF;
    IF NEW.is_active IS NULL THEN NEW.is_active := TRUE; END IF;

    -- Resolução automática de color_id e variant_id (XBZ)
    IF NEW.color_id IS NULL AND NEW.supplier_code = 'XBZ' THEN
        IF NEW.variant_id IS NOT NULL THEN
            SELECT color_id INTO v_color_id
            FROM product_variants
            WHERE id = NEW.variant_id AND is_active = true;
            IF v_color_id IS NOT NULL THEN
                NEW.color_id := v_color_id;
            END IF;
        ELSE
            SELECT COUNT(DISTINCT pv.color_id) INTO v_n_cores
            FROM product_variants pv
            WHERE pv.product_id = NEW.product_id
              AND pv.is_active = true AND pv.color_id IS NOT NULL;

            IF v_n_cores = 1 THEN
                SELECT pv.id, pv.color_id INTO v_variant_id, v_color_id
                FROM product_variants pv
                WHERE pv.product_id = NEW.product_id
                  AND pv.is_active = true AND pv.color_id IS NOT NULL
                ORDER BY pv.id LIMIT 1;
                NEW.color_id   := v_color_id;
                NEW.variant_id := v_variant_id;
            ELSIF v_n_cores > 1 THEN
                SELECT pv.id, pv.color_id INTO v_variant_id, v_color_id
                FROM product_variants pv
                WHERE pv.product_id = NEW.product_id
                  AND pv.is_active = true AND pv.color_id IS NOT NULL
                  AND NEW.url_original ILIKE '%' || REPLACE(pv.color_name, ' ', '-') || '%'
                GROUP BY pv.id, pv.color_id
                HAVING COUNT(*) = 1
                LIMIT 1;

                IF v_color_id IS NOT NULL AND (
                  SELECT COUNT(DISTINCT pv2.color_id)
                  FROM product_variants pv2
                  WHERE pv2.product_id = NEW.product_id
                    AND pv2.is_active = true AND pv2.color_id IS NOT NULL
                    AND NEW.url_original ILIKE '%' || REPLACE(pv2.color_name, ' ', '-') || '%'
                ) = 1 THEN
                    NEW.color_id   := v_color_id;
                    NEW.variant_id := v_variant_id;
                END IF;
            END IF;
        END IF;
    END IF;

    RETURN NEW;
END;
$function$;
;

-- <<< END 20260627111707_20260627000002_fn_auto_classify_product_image_anti_uuid_hardcode.sql <<<

-- >>> BEGIN 20260627111905_r8_fix_monitoring_analyze_dictionaries_cron_20260627.sql >>>
-- ═══════════════════════════════════════════════════════════════════
-- R8 · Fix cegueira de monitoramento: ANALYZE cron para dicionários
-- fix_version: analyze_dicts_20260627
-- ═══════════════════════════════════════════════════════════════════

-- 1. Função de ANALYZE das tabelas dicionário (low-write)
CREATE OR REPLACE FUNCTION public.fn_analyze_dictionaries()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $fn$
-- fix_version: analyze_dicts_20260627
-- anti-regression: manter search_path + SECURITY DEFINER.
-- Propósito: corrigir n_live_tup=0 (falso) em tabelas que raramente recebem
--            writes e por isso o autovacuum não dispara ANALYZE automático.
BEGIN
  ANALYZE public.property_definitions;
  ANALYZE public.attribute_definitions;
  ANALYZE public.material_types;
  ANALYZE public.commemorative_dates;
  ANALYZE public.color_groups;
  ANALYZE public.color_nuances;
  ANALYZE public.variation_types;
  ANALYZE public.variation_values;
  ANALYZE public.attribute_groups;
  ANALYZE public.packaging_types;
  ANALYZE public.collections;
  ANALYZE public.tags;
  ANALYZE public.eco_material_config;
  ANALYZE public.feminine_color_config;
  ANALYZE public.material_equivalences;
  ANALYZE public.color_equivalences;
  ANALYZE public.supplier_property_mappings;
END;
$fn$;

COMMENT ON FUNCTION public.fn_analyze_dictionaries() IS
'[fix_version:analyze_dicts_20260627] Atualiza estatísticas de tabelas dicionário
 (low-write) para manter n_live_tup preciso em pg_stat_user_tables.
 Agendado via pg_cron analyze-dictionaries-daily às 02:00 UTC.
 Não remover/alterar sem atualizar o cron correspondente.';

REVOKE EXECUTE ON FUNCTION public.fn_analyze_dictionaries() FROM PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_analyze_dictionaries() TO service_role;

-- 2. Executar imediatamente para corrigir stats agora
SELECT public.fn_analyze_dictionaries();

-- 3. Agendar cron (idempotente via DO block — unschedule silencia erro se inexistente)
DO $$
BEGIN
  PERFORM cron.unschedule('analyze-dictionaries-daily');
EXCEPTION WHEN OTHERS THEN NULL;
END;
$$;

SELECT cron.schedule(
  'analyze-dictionaries-daily',
  '0 2 * * *',
  'SELECT public.fn_analyze_dictionaries()'
);;

-- <<< END 20260627111905_r8_fix_monitoring_analyze_dictionaries_cron_20260627.sql <<<

-- >>> BEGIN 20260627111927_20260627000003_product_videos_normalize_source_supplier.sql >>>
-- ============================================================
-- Trigger BEFORE INSERT OR UPDATE para normalizar source_supplier
-- em product_videos (espelho de fn_normalize_source_supplier de product_images)
-- fix_version: normalize_video_supplier_20260627
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_normalize_source_supplier_videos()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
-- fix_version: normalize_video_supplier_20260627
-- Espelho de fn_normalize_source_supplier de product_images para product_videos.
-- Garante UPPER + nome canônico de todos os suppliers.
-- NUNCA remover ou renomear sem atualizar a listagem de suppliers ativos.
BEGIN
  NEW.source_supplier := CASE UPPER(COALESCE(NEW.source_supplier,''))
    WHEN 'STRICKER'  THEN 'SPOT'
    WHEN 'SPOT'      THEN 'SPOT'
    WHEN 'XBZ'       THEN 'XBZ'
    WHEN 'ASIA'      THEN 'ASIA'
    WHEN 'SOMARCAS'  THEN 'SOMARCAS'
    WHEN '88BRINDES' THEN '88BRINDES'
    WHEN ''          THEN NEW.source_supplier
    ELSE UPPER(NEW.source_supplier)
  END;
  RETURN NEW;
END;
$function$;

CREATE TRIGGER trg_normalize_source_supplier_videos
  BEFORE INSERT OR UPDATE ON product_videos
  FOR EACH ROW EXECUTE FUNCTION public.fn_normalize_source_supplier_videos();

-- Backfill: normalizar todos os valores sujos já existentes
-- O trigger BEFORE já está ativo, então o UPDATE passa pelo normalizador
UPDATE product_videos
SET source_supplier = source_supplier
WHERE source_supplier IS DISTINCT FROM UPPER(source_supplier);
;

-- <<< END 20260627111927_20260627000003_product_videos_normalize_source_supplier.sql <<<

-- >>> BEGIN 20260627112025_r6_fix_fn_super_filtro_ambiguity_drop_5arg_20260627.sql >>>
-- ═══════════════════════════════════════════════════════════════════
-- R6 · Desambiguar fn_super_filtro_product_ids — drop overload 5-arg
-- fix_version: super_filtro_dedup_20260627
--
-- Problema: dois overloads com todos os parâmetros DEFAULT='{}'
--   5-arg: (_datas, _tags, _ramos, _segmentos, _publico)
--   6-arg: (_datas, _tags, _ramos, _segmentos, _publico, _endomarketing)
-- Ao chamar sem argumentos, PostgreSQL lança 42725 (operador ambíguo).
--
-- Solução: DROP do overload 5-arg (subconjunto lógico do 6-arg).
-- O overload 6-arg com _endomarketing='{}'::text[] é funcionalmente
-- idêntico ao 5-arg para todos os callers existentes.
--
-- Retrocompatibilidade:
--   - Chamadas com 0 args: resolvem para 6-arg ✅
--   - Chamadas com 1-5 args posicionais: 6-arg aceita (params restantes = '{}') ✅
--   - Chamadas com params nomeados sem _endomarketing: 6-arg resolve ✅
--   - Nenhuma VIEW referencia este overload especificamente ✅
-- ═══════════════════════════════════════════════════════════════════

DROP FUNCTION IF EXISTS public.fn_super_filtro_product_ids(
  text[], text[], text[], text[], text[]
);

-- Recriar o overload 6-arg com comentário fix_version (anti-Lovable-bot)
CREATE OR REPLACE FUNCTION public.fn_super_filtro_product_ids(
  _datas         text[] DEFAULT '{}'::text[],
  _tags          text[] DEFAULT '{}'::text[],
  _ramos         text[] DEFAULT '{}'::text[],
  _segmentos     text[] DEFAULT '{}'::text[],
  _publico       text[] DEFAULT '{}'::text[],
  _endomarketing text[] DEFAULT '{}'::text[]
)
RETURNS TABLE(product_id uuid)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $fn$
-- fix_version: super_filtro_dedup_20260627
-- anti-regression: manter search_path=public + SECURITY DEFINER.
-- Histórico: overload 5-arg removido em 20260627 para eliminar 42725.
-- Este é o único overload — NÃO recriar versão sem _endomarketing.
  SELECT b.id
  FROM products b
  WHERE b.is_active = true AND b.is_deleted IS NOT TRUE
    AND ( cardinality(COALESCE(_datas,'{}'))=0 OR EXISTS (
        SELECT 1 FROM product_commemorative_dates pcd
        JOIN commemorative_dates cd ON cd.id = pcd.commemorative_date_id AND cd.is_active
        WHERE pcd.product_id = b.id AND pcd.is_active AND cd.slug = ANY(_datas) ) )
    AND ( cardinality(COALESCE(_tags,'{}'))=0 OR EXISTS (
        SELECT 1 FROM product_tags pt
        JOIN tags t ON t.id = pt.tag_id AND t.is_active
        WHERE pt.product_id = b.id AND pt.tag_id = ANY( ARRAY(
            SELECT x::uuid FROM unnest(_tags) AS x
            WHERE x ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
        ) ) ) )
    AND ( cardinality(COALESCE(_ramos,'{}'))=0 OR EXISTS (
        SELECT 1 FROM produto_ramo_atividade pra
        JOIN ramo_atividade_filho raf ON raf.id = pra.ramo_atividade_filho_id
        JOIN ramo_atividade ra ON ra.id = raf.ramo_atividade_id
        WHERE pra.produto_id = b.id AND ra.slug = ANY(_ramos) ) )
    AND ( cardinality(COALESCE(_segmentos,'{}'))=0 OR EXISTS (
        SELECT 1 FROM produto_ramo_atividade pra
        JOIN ramo_atividade_filho raf ON raf.id = pra.ramo_atividade_filho_id
        WHERE pra.produto_id = b.id AND raf.slug = ANY(_segmentos) ) )
    AND ( cardinality(COALESCE(_publico,'{}'))=0 OR b.target_audience && _publico )
    AND ( cardinality(COALESCE(_endomarketing,'{}'))=0 OR EXISTS (
        SELECT 1 FROM product_tags pt
        JOIN tags t ON t.id = pt.tag_id AND t.is_active
        WHERE pt.product_id = b.id AND t.slug = ANY(_endomarketing) ) );
$fn$;

COMMENT ON FUNCTION public.fn_super_filtro_product_ids(text[],text[],text[],text[],text[],text[]) IS
'[fix_version:super_filtro_dedup_20260627] Super-filtro de produtos por múltiplas dimensões.
 Overload 5-arg (sem _endomarketing) foi REMOVIDO em 20260627 para eliminar ambiguidade 42725.
 Este é o ÚNICO overload. Chamar com 0 a 6 args — todos têm DEFAULT.
 Parâmetros: _datas (slug de datas comemorativas), _tags (UUIDs), _ramos (slug ramo),
 _segmentos (slug segmento), _publico (texto ex: feminino), _endomarketing (slug tag).';

REVOKE EXECUTE ON FUNCTION public.fn_super_filtro_product_ids(text[],text[],text[],text[],text[],text[]) FROM PUBLIC;
GRANT  EXECUTE ON FUNCTION public.fn_super_filtro_product_ids(text[],text[],text[],text[],text[],text[]) TO anon, authenticated, service_role;;

-- <<< END 20260627112025_r6_fix_fn_super_filtro_ambiguity_drop_5arg_20260627.sql <<<

