    WHERE pd.code = CASE property_code
      WHEN 'OTHER_MARCADOR_DE_P_GINA' THEN 'PAGE_MARKER'
      WHEN 'OTHER_ACABAMENTO_FOSCO'   THEN 'MATTE_FINISH'
      WHEN 'OTHER_ISOLADA_A_V_CUO_'   THEN 'VACUUM_INSULATED'
