-- >>> BEGIN 20260627113120_20260627000007_enqueue_xbz_products_without_images.sql >>>
-- ============================================================
-- Criar product_images (cf_sync_status=pending) para 17 produtos XBZ
-- ativos que têm ImageLink no Bronze mas nenhuma imagem no Gold.
-- A fn_get_image_upload_queue() repassará ao worker n8n noturno.
-- Os 13 restantes (dos 30) têm ImageLink vazio — sem URL disponível.
-- ============================================================
SET LOCAL app.write_source = 'pipeline';

WITH candidatos AS (
  SELECT DISTINCT ON (pp.product_id)
    pp.product_id,
    spr.raw_data->>'ImageLink' AS image_url,
    left('xbz-' || lower(
        regexp_replace(
          regexp_replace(spr.raw_data->>'ImageLink', '^.*/([^/?]+)(\?.*)?$', '\1'),
          '\.[^.]{2,5}$', ''
        )
    ), 100) AS cf_id
  FROM produtos_padronizacao pp
  JOIN supplier_products_raw spr ON spr.id = pp.raw_id
  WHERE pp.product_id IN (
    SELECT p.id FROM products p WHERE p.is_active
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.is_active)
  )
  AND spr.raw_data->>'ImageLink' ILIKE 'http%'
  ORDER BY pp.product_id, spr.id
)
INSERT INTO product_images (
  product_id, cloudflare_image_id, url_cdn, url_original,
  image_type, is_primary, source_supplier, supplier_code, cf_sync_status, is_active
)
SELECT
  c.product_id,
  c.cf_id,
  c.image_url,
  c.image_url,
  'main',
  true,
  'XBZ', 'XBZ', 'pending', true
FROM candidatos c
ON CONFLICT (cloudflare_image_id) DO NOTHING;
;

-- <<< END 20260627113120_20260627000007_enqueue_xbz_products_without_images.sql <<<

-- >>> BEGIN 20260627113307_20260627000008_image_types_zombie_cleanup.sql >>>
-- ============================================================
-- Higiene de image_types: tipos zumbis (0 linhas ativas)
-- 1. product → is_active=false (0 usos, never emitted by classifier)
-- 2. mockup, thumbnail → is_internal_only=true (flags inconsistentes)
-- 3. other → nota no description (FALLBACK CRÍTICO do classificador)
-- ============================================================

-- 1. Desativar tipo 'product' (semanticamente redundante; classifier nunca o emite;
--    ADR-001 usa gallery+color_id como substituto; 0 linhas ativas na product_images FK)
UPDATE image_types
SET is_active = false
WHERE code = 'product';

-- 2. Corrigir flags is_internal_only incorretas
UPDATE image_types
SET is_internal_only = true
WHERE code IN ('mockup', 'thumbnail');

-- 3. Documentar 'other' como fallback crítico para evitar desativação acidental
UPDATE image_types
SET description = description || E'\n[27/06/2026] FALLBACK DO CLASSIFICADOR: fn_auto_classify_product_image retorna este tipo quando nenhum padrão de filename ou CF ID casa. NUNCA desativar.'
WHERE code = 'other';
;

