-- >>> BEGIN 20260627150057_harden_pbd_projection_typesafe_min_pbd_v1_1.sql >>>
-- Hardening do trigger de projecao: parse TYPE-SAFE de minAvgDailyDepletion7d.
-- Antes: (config->>'minAvgDailyDepletion7d')::numeric podia lancar 22P02 (invalid_text_representation)
--        para valores nao-numericos (string nao-numerica, boolean, objeto, array), abortando o UPDATE
--        legitimo de best_seller. Agora: so converte se for number JSON ou string que casa regex numerico;
--        qualquer outro valor cai no fallback 15. Nunca lanca 22P02.
-- fix_version=pbd_v1_1_20260627
CREATE OR REPLACE FUNCTION public.fn_pbd_project_intelligence_settings()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO public AS $fn$
DECLARE v_hot boolean; v_best_enabled boolean; v_best_min numeric; v_cfg jsonb;
BEGIN
  -- fix_version=pbd_v1_1_20260627 | ANTI-REGRESSAO: SECURITY DEFINER + SET search_path obrigatorios.
  -- Parse TYPE-SAFE de minAvgDailyDepletion7d: nunca lanca 22P02 em config arbitrario.
  IF COALESCE(NEW.badge_key, OLD.badge_key) NOT IN ('hot_item','best_seller') THEN RETURN NULL; END IF;
  SELECT is_enabled INTO v_hot FROM public.product_badge_definitions WHERE badge_key='hot_item';
  SELECT is_enabled, config INTO v_best_enabled, v_cfg FROM public.product_badge_definitions WHERE badge_key='best_seller';
  v_best_min := CASE
    WHEN jsonb_typeof(v_cfg->'minAvgDailyDepletion7d')='number'
      THEN (v_cfg->>'minAvgDailyDepletion7d')::numeric
    WHEN jsonb_typeof(v_cfg->'minAvgDailyDepletion7d')='string'
         AND (v_cfg->>'minAvgDailyDepletion7d') ~ '^-?[0-9]+(\.[0-9]+)?$'
      THEN (v_cfg->>'minAvgDailyDepletion7d')::numeric
    ELSE NULL END;
  INSERT INTO public.admin_settings(key, value, updated_at)
  VALUES ('intelligence_badges', jsonb_build_object(
            'hotItem',    jsonb_build_object('enabled', COALESCE(v_hot, true)),
            'bestSeller', jsonb_build_object('enabled', COALESCE(v_best_enabled, true), 'minAvgDailyDepletion7d', COALESCE(v_best_min, 15))
          ), now())
  ON CONFLICT (key) DO UPDATE SET value=EXCLUDED.value, updated_at=now();
  RETURN NULL;
END;$fn$;

COMMENT ON FUNCTION public.fn_pbd_project_intelligence_settings() IS 'fix_version=pbd_v1_1_20260627. Projeta hot_item/best_seller para admin_settings.intelligence_badges (compat ProductCard). Parse type-safe de minAvgDailyDepletion7d (nunca lanca 22P02 em config arbitrario; fallback 15).';

-- <<< END 20260627150057_harden_pbd_projection_typesafe_min_pbd_v1_1.sql <<<

-- >>> BEGIN 20260627153820_harden_pbd_revoke_anon_writes_defense_in_depth.sql >>>
-- Defense-in-depth: anon nao deve ter grants de escrita na tabela de governanca de badges.
-- Alinhamento com o padrao do projeto (ex.: public.products tem anon sem INSERT/UPDATE/DELETE).
-- A RLS ja bloqueia anon (policies de escrita exigem is_admin_or_above), mas remover o grant
-- elimina a dependencia exclusiva da RLS (se uma policy fosse afrouxada por engano, o grant
-- ausente ainda protege). SELECT permanece (leitura publica do catalogo, via policy pbd_public_read).
-- fix_version=pbd_v1_2_20260627
REVOKE INSERT, UPDATE, DELETE ON public.product_badge_definitions FROM anon;

-- <<< END 20260627153820_harden_pbd_revoke_anon_writes_defense_in_depth.sql <<<

-- >>> BEGIN 20260627154718_harden_pbd_before_write_symmetric_is_system_insert_pbd_v1_3.sql >>>
-- Simetria da protecao de is_system entre INSERT e UPDATE.
-- Antes: a protecao de is_system so existia no UPDATE (nao-dev nao podia alterar). No INSERT
--        nao havia protecao, entao um usuario autenticado nao-dev podia CRIAR badge com
--        is_system=true (ou omitir, herdando o default true) e ela ficava nao-deletavel por
--        ninguem (fn_pbd_block_system_delete bloqueia todos). Defense-in-depth: o banco nao deve
--        depender do frontend (que ja envia is_system=false) para garantir a integridade.
-- Agora: usuario autenticado nao-dev nao pode criar is_system=true (forcado para false).
--        Preserva seed/migracao (auth.uid() IS NULL) e dev (has_role dev).
-- fix_version=pbd_v1_3_20260627
CREATE OR REPLACE FUNCTION public.fn_pbd_before_write()
RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public' AS $function$
BEGIN
  -- fix_version=pbd_v1_3_20260627 | ANTI-REGRESSAO: manter SET search_path
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := COALESCE(NEW.created_at, now());
    NEW.updated_at := now();
    IF NEW.created_by IS NULL THEN NEW.created_by := auth.uid(); END IF;
    NEW.updated_by := COALESCE(auth.uid(), NEW.updated_by);
    -- Simetria com UPDATE: usuario autenticado nao-dev nao pode CRIAR badge de sistema.
    -- Preserva seed/migracao (auth.uid() IS NULL) e dev.
    IF NEW.is_system = true AND auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(), 'dev'::app_role) THEN
      NEW.is_system := false;
    END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.badge_key IS DISTINCT FROM OLD.badge_key THEN
      RAISE EXCEPTION 'badge_key e imutavel (% -> %)', OLD.badge_key, NEW.badge_key USING ERRCODE = '23514';
    END IF;
    IF NEW.is_system IS DISTINCT FROM OLD.is_system AND NOT public.has_role(auth.uid(), 'dev'::app_role) THEN
      NEW.is_system := OLD.is_system;
    END IF;
    NEW.created_at := OLD.created_at;
    NEW.created_by := OLD.created_by;
    NEW.updated_at := now();
    NEW.updated_by := COALESCE(auth.uid(), OLD.updated_by);
  END IF;
  RETURN NEW;
END;$function$;

COMMENT ON FUNCTION public.fn_pbd_before_write() IS 'fix_version=pbd_v1_3_20260627. BEFORE INSERT/UPDATE de product_badge_definitions: auditoria (created_*/updated_*), badge_key imutavel, is_system protegido SIMETRICAMENTE (nao-dev autenticado nao cria nem altera badge de sistema; seed sem-JWT e dev preservados).';

-- <<< END 20260627154718_harden_pbd_before_write_symmetric_is_system_insert_pbd_v1_3.sql <<<

