-- >>> BEGIN 20260627191603_fix_price_last_verified_drift_and_harden_trigger_20260627.sql >>>
-- ============================================================
-- FIX: price_last_verified_at drift em 65 produtos ativos
-- fix_version: price_verified_drift_harden_20260627
-- ANTI-REGRESSÃO: NÃO REMOVER o cron guard abaixo.
-- ============================================================

-- PASSO 1: Corrigir os 65 produtos com drift atual
UPDATE products
SET price_last_verified_at = GREATEST(
      COALESCE(price_last_verified_at, '2000-01-01'::timestamptz),
      COALESCE(price_updated_at,       '2000-01-01'::timestamptz),
      COALESCE(last_sync_at,           '2000-01-01'::timestamptz)
    )
WHERE price_last_verified_at < price_updated_at
  AND is_active = TRUE;

-- PASSO 2: Hardening do trigger — adiciona CASO C anti-drift
-- fix_version: price_verified_harden_trigger_20260627
CREATE OR REPLACE FUNCTION public.fn_trigger_update_price_last_verified()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
BEGIN
  -- CASO A: last_sync_at atualizado → confirma preço verificado
  IF NEW.last_sync_at IS DISTINCT FROM OLD.last_sync_at
     AND NEW.last_sync_at IS NOT NULL THEN
    NEW.price_last_verified_at := GREATEST(
      COALESCE(NEW.price_last_verified_at, '2000-01-01'::timestamptz),
      NEW.last_sync_at
    );
  END IF;

  -- CASO B: price_updated_at explicitamente mudado (pipeline promoção)
  IF NEW.price_updated_at IS DISTINCT FROM OLD.price_updated_at
     AND NEW.price_updated_at IS NOT NULL THEN
    NEW.price_last_verified_at := GREATEST(
      COALESCE(NEW.price_last_verified_at, '2000-01-01'::timestamptz),
      NEW.price_updated_at
    );
  END IF;

  -- CASO C (NOVO): anti-drift — se price_updated_at > price_last_verified_at
  -- mesmo sem ter mudado neste UPDATE, corrige na hora.
  -- Cobre o caso do Lovable bot que seta price_updated_at via outro caminho.
  -- fix_version: price_verified_harden_trigger_20260627
  IF NEW.price_updated_at IS NOT NULL
     AND NEW.price_last_verified_at IS NOT NULL
     AND NEW.price_updated_at > NEW.price_last_verified_at THEN
    NEW.price_last_verified_at := NEW.price_updated_at;
  END IF;

  RETURN NEW;
END;
$$;

-- PASSO 3: Cron de guarda diária — detecta e corrige drift residual às 03:15 UTC
-- ANTI-REGRESSÃO: não remover — guarda contra regressões do Lovable bot.
DO $$
BEGIN
  PERFORM cron.unschedule('fix_price_verified_drift_daily');
EXCEPTION WHEN OTHERS THEN NULL;
END $$;

SELECT cron.schedule(
  'fix_price_verified_drift_daily',
  '15 3 * * *',
  $cron$
  UPDATE public.products
  SET price_last_verified_at = GREATEST(
        COALESCE(price_last_verified_at, '2000-01-01'::timestamptz),
        COALESCE(price_updated_at,       '2000-01-01'::timestamptz),
        COALESCE(last_sync_at,           '2000-01-01'::timestamptz)
      )
  WHERE price_last_verified_at < price_updated_at
    AND is_active = TRUE;
  $cron$
);;

-- <<< END 20260627191603_fix_price_last_verified_drift_and_harden_trigger_20260627.sql <<<

-- >>> BEGIN 20260627191644_fn_capture_schema_baseline_v2_allowlist_aware_20260627.sql >>>

-- ===================================================================
-- PATCH: fn_capture_schema_baseline → respeitar schema_signature_drift_allowlist
-- fix_version: baseline_capture_allowlist_aware_v2_20260627
-- ===================================================================
CREATE OR REPLACE FUNCTION public.fn_capture_schema_baseline(
  p_label text DEFAULT 'manual'::text
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
BEGIN
  -- fix_version: baseline_capture_allowlist_aware_v2_20260627
  -- PATCH 2026-06-27: exclui tabelas na schema_signature_drift_allowlist
  --   (coluna IS NULL = exclusão de tabela inteira) para manter o baseline
  --   limpo de objetos de teste/infra que não devem ser monitorados.
  DELETE FROM public.schema_signature_baseline;

  INSERT INTO public.schema_signature_baseline
    (table_name, column_name, data_type, baseline_label, captured_at)
  SELECT
    c.table_name, c.column_name, c.data_type, p_label, now()
  FROM information_schema.columns c
  WHERE c.table_schema = 'public'
    AND c.table_name NOT LIKE 'pg_%'
    AND c.table_name NOT LIKE '_backup_%'
    -- excluir tabelas/views inteiras da allowlist
    AND c.table_name NOT IN (
      SELECT a.table_name
      FROM public.schema_signature_drift_allowlist a
      WHERE a.column_name IS NULL
    );

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$;
;

-- <<< END 20260627191644_fn_capture_schema_baseline_v2_allowlist_aware_20260627.sql <<<

-- >>> BEGIN 20260627191755_fn_sync_local_drift_to_schema_drift_log_20260627.sql >>>

-- ===================================================================
-- FIX: Ponte entre schema_signature_drift_log (local, funciona) e
-- schema_drift_log (Lovable HTTP, morto). A partir de agora o
-- schema_drift_log mostra dados reais vindos do check local, nunca mais
-- timeouts falsos.
--
-- fix_version: drift_log_bridge_v1_20260627
-- ===================================================================
CREATE OR REPLACE FUNCTION public.fn_sync_local_drift_to_schema_drift_log()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_rec RECORD;
  v_only_oficial text[];
  v_only_lovable  text[];
BEGIN
  -- fix_version: drift_log_bridge_v1_20260627
  -- Busca a entrada mais recente de schema_signature_drift_log (check local)
  SELECT * INTO v_rec
  FROM schema_signature_drift_log
  ORDER BY ran_at DESC
  LIMIT 1;

  IF v_rec IS NULL THEN
    RETURN;
  END IF;

  -- Mapeia: tabelas adicionadas ao schema real = "only_oficial" (existem no
  -- Supabase oficial mas não no ponto de referência anterior).
  -- Tabelas removidas = "only_lovable" (estavam e sumiram).
  v_only_oficial := COALESCE(v_rec.tables_added, '{}');
  v_only_lovable  := COALESCE(v_rec.tables_removed, '{}');

  INSERT INTO schema_drift_log (
    ran_at,
    has_drift,
    tables_oficial,
    tables_lovable,
    only_oficial,
    only_lovable,
    schema_diff,
    notification_sent,
    error_message
  )
  VALUES (
    now(),
    v_rec.has_drift,
    (SELECT COUNT(DISTINCT table_name)
     FROM information_schema.tables
     WHERE table_schema = 'public'),
    (SELECT COUNT(DISTINCT table_name)
     FROM schema_signature_baseline),
    v_only_oficial,
    v_only_lovable,
    jsonb_build_object(
      'source',          'fn_check_schema_signature_drift',
      'baseline_label',  v_rec.baseline_label,
      'n_added',         v_rec.n_added,
      'n_removed',       v_rec.n_removed,
      'n_retyped',       v_rec.n_retyped,
      'columns_added',   v_rec.columns_added,
      'columns_removed', v_rec.columns_removed,
      'columns_retyped', v_rec.columns_retyped,
      'note',
        'Dados do check local (não HTTP Lovable) — bridged por fn_sync_local_drift_to_schema_drift_log'
    ),
    false,
    NULL  -- sem erro: veio do check local que funciona
  );
END;
$function$;

-- Chamar imediatamente para popular schema_drift_log com dados reais
SELECT public.fn_sync_local_drift_to_schema_drift_log();
;

-- <<< END 20260627191755_fn_sync_local_drift_to_schema_drift_log_20260627.sql <<<

-- >>> BEGIN 20260627191759_optimize_fn_spr_before_write_session_cache_20260627.sql >>>
-- ============================================================
-- OTIMIZAÇÃO: fn_spr_before_write — session-level cache para supplier_settings
-- Problema: 124M seq_scans em tabela de 5 rows por inexistência de cache.
-- Solução: set_config(app.spr_excl_<uuid>, value, false) → cache por sessão.
-- Cada conexão do pooler faz 1 lookup no banco por fornecedor e depois
-- usa o cache para todas as rows do batch (~300 rows por tick de pipeline).
-- fix_version: spr_before_write_session_cache_20260627
-- ANTI-REGRESSÃO: NÃO REMOVER o bloco EXCEPTION WHEN undefined_object.
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_spr_before_write()
RETURNS trigger
LANGUAGE plpgsql
SET search_path TO 'public'
AS $$
DECLARE
  v_clean    jsonb;
  v_hashbase jsonb;
  v_excl     text[];
  v_k        text;
  v_cached   text;
  v_cfg_key  text;
BEGIN
  -- ── Normalizar source_channel e imported_at ────────────────────────────
  IF NEW.raw_data ? '_source' AND COALESCE(NEW.source_channel,'') IN ('','n8n','legacy') THEN
    NEW.source_channel := NEW.raw_data->>'_source';
  END IF;
  IF NEW.raw_data ? '_imported_at' AND NEW.imported_at IS NULL THEN
    BEGIN NEW.imported_at := (NEW.raw_data->>'_imported_at')::timestamptz;
    EXCEPTION WHEN others THEN NULL; END;
  END IF;

  -- ── Limpar chaves internas (_*) do raw_data ───────────────────────────
  v_clean := NEW.raw_data;
  FOR v_k IN SELECT k FROM jsonb_object_keys(NEW.raw_data) k WHERE left(k,1) = '_' LOOP
    v_clean := v_clean - v_k;
  END LOOP;
  NEW.raw_data := v_clean;

  -- ── Session-level cache para supplier_settings ────────────────────────
  -- fix_version: spr_before_write_session_cache_20260627
  -- Converte supplier_id UUID para chave GUC válida (sem hífens).
  -- Cache persiste por conexão/sessão (is_local=false), sobrevive a commits.
  -- Cada fornecedor gera 1 lookup por sessão em vez de 1 por row.
  -- ANTI-REGRESSÃO: manter o EXCEPTION WHEN undefined_object abaixo.
  IF NEW.supplier_id IS NOT NULL THEN
    v_cfg_key := 'app.spr_excl_' || replace(NEW.supplier_id::text, '-', '_');
    BEGIN
      v_cached := current_setting(v_cfg_key);
    EXCEPTION WHEN undefined_object THEN
      v_cached := NULL;
    END;

    IF v_cached IS NULL THEN
      -- Cache MISS: único SELECT por supplier por sessão
      SELECT COALESCE(array_to_string(ss.hash_excluded_fields, ','), '')
      INTO v_cached
      FROM public.supplier_settings ss
      WHERE ss.supplier_id = NEW.supplier_id;
      -- is_local=false → persiste para a sessão inteira (não é revertido em ROLLBACK)
      PERFORM set_config(v_cfg_key, COALESCE(v_cached, ''), false);
    END IF;

    IF v_cached IS NOT NULL AND v_cached <> '' THEN
      v_excl := string_to_array(v_cached, ',');
    ELSE
      v_excl := NULL;
    END IF;
  END IF;

  -- ── Calcular content_hash ─────────────────────────────────────────────
  v_hashbase := CASE WHEN v_excl IS NOT NULL AND array_length(v_excl,1) > 0
                     THEN v_clean - v_excl ELSE v_clean END;
  NEW.content_hash := encode(extensions.digest(v_hashbase::text, 'sha256'), 'hex');

  -- ── Lógica de INSERT ──────────────────────────────────────────────────
  IF TG_OP = 'INSERT' THEN
    NEW.imported_at := COALESCE(NEW.imported_at, now());
    IF NEW.process_errors IS NOT NULL AND NEW.last_error IS NULL THEN
      NEW.last_error := NEW.process_errors;
    END IF;
  ELSE
    -- ── Lógica de UPDATE ──────────────────────────────────────────────
    NEW.updated_at := now();

    IF NEW.process_errors IS DISTINCT FROM OLD.process_errors
       AND NEW.process_errors IS NOT NULL THEN
      NEW.last_error := NEW.process_errors;
      NEW.attempts   := COALESCE(OLD.attempts, 0) + 1;
      IF NEW.status <> 'processed'::supplier_raw_status THEN
        NEW.status := CASE WHEN NEW.attempts >= 5
                           THEN 'quarantined'::supplier_raw_status
                           ELSE 'failed'::supplier_raw_status END;
      END IF;
    END IF;

    -- INVARIANTE 1ª VINCULAÇÃO (fix_version=2026-06-26_status_on_link) — ANTI-REGRESSÃO: NÃO REMOVER.
    IF NEW.product_id IS NOT NULL AND OLD.product_id IS NULL
       AND NEW.status IN ('pending'::supplier_raw_status,'processing'::supplier_raw_status)
       AND NEW.process_errors IS NULL THEN
      NEW.status := 'processed'::supplier_raw_status;
    END IF;

    -- RE-LAND GUARD (fix_version=2026-06-26_status_reland_guard) — ANTI-REGRESSÃO: NÃO REMOVER.
    IF NEW.product_id IS NOT NULL
       AND NEW.status = 'pending'::supplier_raw_status
       AND NEW.content_hash IS NOT DISTINCT FROM OLD.content_hash
       AND NEW.process_errors IS NULL THEN
      NEW.status := 'processed'::supplier_raw_status;
    END IF;

    IF NEW.status = 'processed'::supplier_raw_status
       AND NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.processed_at := COALESCE(NEW.processed_at, now());
    END IF;
  END IF;

  RETURN NEW;
END;
$$;;

-- <<< END 20260627191759_optimize_fn_spr_before_write_session_cache_20260627.sql <<<

-- >>> BEGIN 20260627191805_cron_schema_drift_4x_day_20260627.sql >>>

