-- >>> BEGIN 20260628192131_add_art_file_attachments_lookup_indexes_step6.sql >>>
-- fix_version: 2026-06-28 logo-hi-res | Passo 6 da feature "logo cliente colorida/mono" (Gerador de Mockup).
-- Indices para lookup de anexos de arte de PRODUCAO por mockup e por orcamento.
-- O backfill (frontend) vincula art_file_attachments.mockup_id ao generated_mockups.id
-- apos saveMockupToDb; as telas de historico/anexos consultam por mockup_id e quote_id.
-- Parciais (WHERE ... IS NOT NULL): o upload do vetor ocorre na config (ANTES do mockup
-- existir) -> muitas linhas terao mockup_id NULL ate o backfill; o parcial so indexa as
-- linhas ja vinculadas (economia de espaco, indice quente). Simulacao adversarial provou
-- Index Scan + predicado parcial correto antes da aplicacao.
-- ANTI-REGRESSAO (Lovable bot): NAO remover sem substituir o caminho de consulta de anexos
-- por mockup/orcamento. IF NOT EXISTS => idempotente (seguro a reaplicacao/regeneracao).
CREATE INDEX IF NOT EXISTS idx_art_file_attachments_mockup_id
  ON public.art_file_attachments (mockup_id)
  WHERE mockup_id IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_art_file_attachments_quote_id
  ON public.art_file_attachments (quote_id)
  WHERE quote_id IS NOT NULL;

COMMENT ON INDEX public.idx_art_file_attachments_mockup_id IS
  'fix_version: 2026-06-28 logo-hi-res. Lookup de anexos de arte por mockup (Passo 6: backfill de mockup_id pos saveMockupToDb). Parcial WHERE mockup_id IS NOT NULL.';
COMMENT ON INDEX public.idx_art_file_attachments_quote_id IS
  'fix_version: 2026-06-28 logo-hi-res. Lookup de anexos de arte por orcamento. Parcial WHERE quote_id IS NOT NULL.';;

-- <<< END 20260628192131_add_art_file_attachments_lookup_indexes_step6.sql <<<

-- >>> BEGIN 20260629102207_seller_carts_status_two_state_em_separacao.sql >>>
-- Carrinhos: ciclo de vida de 2 estados.
-- em_separacao (default) -> pronto_orcamento.
-- Legado 'novo' e 'em_negociacao' colapsam em 'em_separacao'.
-- fix_version: 20260629_cart_status_two_state
-- ANTI-REGRESSAO (Lovable bot): NAO reintroduzir 'novo'/'em_negociacao' nem alterar o default.

-- 1) Remove a constraint antiga (3 estados)
ALTER TABLE public.seller_carts DROP CONSTRAINT chk_sc_status;

-- 2) Migra dados preservando os timestamps reais de atividade dos carrinhos
--    (desabilita o trigger de updated_at apenas para este UPDATE mecânico)
ALTER TABLE public.seller_carts DISABLE TRIGGER trg_seller_carts_updated_at;
UPDATE public.seller_carts SET status = 'em_separacao' WHERE status IN ('novo', 'em_negociacao');
ALTER TABLE public.seller_carts ENABLE TRIGGER trg_seller_carts_updated_at;

-- 3) Novo default
ALTER TABLE public.seller_carts ALTER COLUMN status SET DEFAULT 'em_separacao';

-- 4) Nova constraint (2 estados)
ALTER TABLE public.seller_carts ADD CONSTRAINT chk_sc_status
  CHECK (status = ANY (ARRAY['em_separacao'::text, 'pronto_orcamento'::text]));

COMMENT ON CONSTRAINT chk_sc_status ON public.seller_carts IS
  'Cart lifecycle 2-state (desde 2026-06-29): em_separacao (default) -> pronto_orcamento. Legado novo/em_negociacao colapsado em em_separacao. Nao reintroduzir valores antigos.';;

-- <<< END 20260629102207_seller_carts_status_two_state_em_separacao.sql <<<

-- >>> BEGIN 20260629142224_7e644177-527b-4b92-93a3-79ffee40ca4a.sql >>>
-- Trigger anti-fraude: bloqueia alteração de quote_items.unit_price por usuários
-- sem permissão administrativa/comercial ampla. RLS sozinho não consegue restringir
-- coluna específica em UPDATE — por isso usamos trigger BEFORE UPDATE.
--
-- Admins/supervisores (has_role('admin') / has_role('supervisor') / can_view_all_sales())
-- continuam podendo ajustar preço quando necessário. Sellers comuns NÃO.

CREATE OR REPLACE FUNCTION public.prevent_non_admin_quote_item_price_change()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_is_admin boolean := false;
BEGIN
  -- INSERTs e mudanças sem auth context (service_role / jobs) passam direto.
  IF v_uid IS NULL THEN
    RETURN NEW;
  END IF;

  -- Se unit_price não mudou, nada a validar.
  IF NEW.unit_price IS NOT DISTINCT FROM OLD.unit_price THEN
    RETURN NEW;
  END IF;

  -- Verifica privilégio (admin OU supervisor OU can_view_all_sales).
  BEGIN
    v_is_admin := public.has_role(v_uid, 'admin'::app_role)
               OR public.has_role(v_uid, 'supervisor'::app_role)
               OR public.can_view_all_sales();
  EXCEPTION WHEN OTHERS THEN
    v_is_admin := false;
  END;

  IF NOT v_is_admin THEN
    RAISE EXCEPTION 'Preço unitário (unit_price) não pode ser alterado por este usuário. O preço vem do catálogo e é somente leitura.'
      USING ERRCODE = '42501', HINT = 'Solicite a um administrador para ajustar o preço, se necessário.';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_prevent_non_admin_quote_item_price_change ON public.quote_items;
CREATE TRIGGER trg_prevent_non_admin_quote_item_price_change
  BEFORE UPDATE OF unit_price ON public.quote_items
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_non_admin_quote_item_price_change();
-- <<< END 20260629142224_7e644177-527b-4b92-93a3-79ffee40ca4a.sql <<<

