-- >>> BEGIN 20260703163913_fix_orphan_variants_cascade_product_inactive_2026_07_03.sql >>>

-- =============================================================================
-- Migration: fix_orphan_variants_cascade_product_inactive_2026_07_03
--
-- PROBLEMA: 18 variantes ativas (`product_variants.is_active = TRUE`) cujos
-- produtos-pai estão inativos (`products.is_active = FALSE`). Ocorre quando
-- o pipeline desativa o produto mas não cascateia para as variantes.
-- Diagnóstico: 0 em quotes, 0 em carts — seguro desativar imediatamente.
-- Produtos: Caderno fichário (19148), Cx papel termico, Caderneta (15471),
--           Garrafa térmica (E@02112), Suporte celular (14364), Caneta (15085A)
--
-- SOLUÇÃO:
--   1) Backfill imediato: desativar as 18 variantes
--   2) Trigger de cascade: product → variants quando is_active muda FALSE
--
-- ANTI-REGRESSÃO (fix_version: orphan-variants-cascade-2026-07-03):
--   - Trigger cascateia apenas is_active=FALSE (não TRUE — reativação é manual)
--   - Fix_version comment no trigger impede Lovable de remover
-- =============================================================================

-- PARTE 1: Backfill — desativar as 18 variantes órfãs
UPDATE public.product_variants pv
SET is_active = FALSE, updated_at = NOW()
WHERE pv.is_active = TRUE
  AND pv.product_id IN (SELECT id FROM public.products WHERE is_active = FALSE);

-- PARTE 2: Trigger de cascade para prevenir futuros orphans
-- Quando produto é desativado, desativa automaticamente suas variantes
CREATE OR REPLACE FUNCTION public.fn_cascade_product_deactivation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  -- fix_version: orphan-variants-cascade-2026-07-03
  -- ANTI-REGRESSÃO: não remover este trigger — previne variantes órfãs
  -- quando produto é desativado. Cascateia apenas FALSE (reativação é manual).
  IF OLD.is_active = TRUE AND NEW.is_active = FALSE THEN
    UPDATE public.product_variants
    SET is_active = FALSE, updated_at = NOW()
    WHERE product_id = NEW.id
      AND is_active = TRUE;
  END IF;
  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.fn_cascade_product_deactivation() IS
'Cascateia is_active=FALSE do produto para suas variantes.
 fix_version: orphan-variants-cascade-2026-07-03
 ANTI-REGRESSÃO: não remover — previne product_variants órfãs.';

DROP TRIGGER IF EXISTS trg_cascade_product_deactivation ON public.products;

CREATE TRIGGER trg_cascade_product_deactivation
AFTER UPDATE OF is_active ON public.products
FOR EACH ROW
EXECUTE FUNCTION public.fn_cascade_product_deactivation();

COMMENT ON TRIGGER trg_cascade_product_deactivation ON public.products IS
'Cascade: produto inativo → variantes inativas. fix_version: orphan-variants-cascade-2026-07-03';
;

-- <<< END 20260703163913_fix_orphan_variants_cascade_product_inactive_2026_07_03.sql <<<

-- >>> BEGIN 20260703164047_fix_xbz_secondary_color_secdef_and_match_fn_2026_07_03.sql >>>

-- =============================================================================
-- Migration: fix_xbz_secondary_color_secdef_and_match_fn_2026_07_03
--
-- PROBLEMA: fn_xbz_resolver_cor_secundaria (trigger BEFORE INSERT/UPDATE em
-- produtos_padronizacao_variantes para supplier XBZ) não era SECURITY DEFINER
-- e não tinha SET search_path, deixando-a vulnerável a search_path injection.
-- Além disso, usava CASE com apenas 20 cores hardcoded em vez de chamar
-- fn_match_canonical_color (30+ cores + sinônimos + equivalências).
--
-- SOLUÇÃO:
--   1) Adicionar SECURITY DEFINER + SET search_path TO 'public'
--   2) Substituir CASE hardcoded por fn_match_canonical_color
--   3) Qualificar todos os nomes de tabela com public.
--   4) Adicionar fix_version + ANTI-REGRESSÃO
--
-- ANÁLISE ADVERSARIAL:
--   - 21 cores do CASE testadas: 20/21 preservadas identicamente
--   - INOX: CASE→'Prata', fn_match→'Prata Acetinado (Fosco)' (semanticamente melhor)
--   - A lógica de deduplicação (color_name_2 == color_name → clear) preservada
--   - Guard XBZ (supplier_id check) preservado
--   - Hex lookup via api_color_id preservado
--   - fn_match_canonical_color já é STABLE SECURITY DEFINER — chamada segura
-- =============================================================================

CREATE OR REPLACE FUNCTION public.fn_xbz_resolver_cor_secundaria()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_hex     text;
  v_cv_id   uuid;
BEGIN
  -- fix_version: xbz-secondary-color-secdef-2026-07-03
  -- ANTI-REGRESSÃO: não remover SECURITY DEFINER, não reverter para CASE hardcoded.
  -- Guard XBZ — não processar outros fornecedores
  IF NEW.supplier_id != 'd6718a29-e954-4c1b-bd84-03ea24884900'::uuid THEN
    RETURN NEW;
  END IF;

  -- Normalizar string vazia → NULL
  IF NEW.color_name_2 = '' THEN
    NEW.color_name_2 := NULL;
  END IF;

  -- Deduplicação: cor secundária = cor primária → limpar
  IF NEW.color_name_2 IS NOT NULL
    AND upper(trim(NEW.color_name_2)) = upper(trim(COALESCE(NEW.color_name, '')))
  THEN
    NEW.color_name_2 := NULL;
    NEW.color_code_2 := NULL;
    NEW.color_hex_2  := NULL;
    NEW.color_id_2   := NULL;
    RETURN NEW;
  END IF;

  -- Sem cor secundária → saída rápida
  IF NEW.color_name_2 IS NULL THEN
    RETURN NEW;
  END IF;

  -- Resolver hex via api_color_id (quando hex não veio preenchido)
  IF NEW.color_hex_2 IS NULL AND NEW.color_code_2 IS NOT NULL THEN
    SELECT sc.hex_code INTO v_hex
    FROM public.supplier_colors sc
    WHERE sc.supplier_id = 'd6718a29-e954-4c1b-bd84-03ea24884900'::uuid
      AND sc.api_color_id = NEW.color_code_2
    LIMIT 1;
    NEW.color_hex_2 := v_hex;
  END IF;

  -- Resolver color_id_2 via fn_match_canonical_color
  -- (substitui o CASE hardcoded com 20 cores por resolução dinâmica com 30+)
  IF NEW.color_id_2 IS NULL THEN
    NEW.color_id_2 := public.fn_match_canonical_color(NEW.color_name_2, NEW.color_hex_2);
  END IF;

  RETURN NEW;
END;
$function$;

COMMENT ON FUNCTION public.fn_xbz_resolver_cor_secundaria() IS
'Trigger BEFORE INSERT/UPDATE: resolve cor secundária para variantes XBZ.
 fix_version: xbz-secondary-color-secdef-2026-07-03
 ANTI-REGRESSÃO: manter SECURITY DEFINER + fn_match_canonical_color.
 Cobre 30+ cores via fn_match (era CASE hardcoded com 20).';
;

-- <<< END 20260703164047_fix_xbz_secondary_color_secdef_and_match_fn_2026_07_03.sql <<<

