-- >>> BEGIN 20260707113531_205c38da-b21e-455b-bf0a-fe762e894e57.sql >>>
-- ═══════════════════════════════════════════════════════════════════════
-- IMP08 — Monitor diário de "dead letters" de callback do CRM
-- ═══════════════════════════════════════════════════════════════════════
-- Fonte: public.crm_callback_events (tabela real). Como v4_callback_dead_letters
-- e maintenance_log não existem neste banco, usamos:
--   • result='error' em janela de 24h como proxy de "não resolvido"
--   • RAISE WARNING para deixar rastro em cron.job_run_details.return_message
--     (evita criar tabela nova sem aprovação explícita do PO).
-- ═══════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_check_dead_letters(_window_hours integer DEFAULT 24)
RETURNS TABLE(unresolved_count bigint, alert text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_count  BIGINT;
  v_alert  TEXT;
BEGIN
  SELECT count(*) INTO v_count
  FROM public.crm_callback_events
  WHERE result = 'error'
    AND created_at >= now() - make_interval(hours => _window_hours);

  IF v_count > 0 THEN
    v_alert := format(
      '⚠️  %s callback(s) do CRM com result=error nas últimas %s h — investigar em crm_callback_events.',
      v_count, _window_hours
    );
    -- WARNING é capturado em cron.job_run_details.return_message
    RAISE WARNING '[dead-letters-check] %', v_alert;
  ELSE
    v_alert := '✅ Nenhum callback com result=error na janela.';
    RAISE NOTICE '[dead-letters-check] %', v_alert;
  END IF;

  RETURN QUERY SELECT v_count, v_alert;
END;
$$;

COMMENT ON FUNCTION public.fn_check_dead_letters(integer) IS
  'IMP08: conta callbacks do CRM com result=error na janela (default 24h) e emite WARNING no pg_cron quando houver pendências. Executada diariamente pelo job check-dead-letters-daily.';

-- ACL: só service_role executa. Sem PUBLIC/anon/authenticated.
REVOKE ALL ON FUNCTION public.fn_check_dead_letters(integer) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.fn_check_dead_letters(integer) FROM anon;
REVOKE ALL ON FUNCTION public.fn_check_dead_letters(integer) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.fn_check_dead_letters(integer) TO service_role;

-- Remove agendamento anterior (idempotência da migration)
DO $$
DECLARE
  v_jobid bigint;
BEGIN
  SELECT jobid INTO v_jobid FROM cron.job WHERE jobname = 'check-dead-letters-daily';
  IF v_jobid IS NOT NULL THEN
    PERFORM cron.unschedule(v_jobid);
  END IF;
END $$;

-- Agenda: todo dia às 08:00 UTC (05:00 America/Sao_Paulo)
SELECT cron.schedule(
  'check-dead-letters-daily',
  '0 8 * * *',
  $cron$ SELECT * FROM public.fn_check_dead_letters(24); $cron$
);
-- <<< END 20260707113531_205c38da-b21e-455b-bf0a-fe762e894e57.sql <<<

-- >>> BEGIN 20260708123135_723b07ad-7c94-4e76-91ce-599dace6f0ce.sql >>>
-- ═══════════════════════════════════════════════════════════════════════
-- Security fixes — findings de scan (2026-07-08)
--   1) can_view_all_sales() escalando acesso a todo autenticado
--   2) quote_items policy sem checagem de dono
--   3) conversation_event_history policy sem checagem de dono
--   4) system_settings com policies USING true que anulam a whitelist
-- ═══════════════════════════════════════════════════════════════════════

-- ─── 1) can_view_all_sales() ─────────────────────────────────────────
-- Antes: SELECT _user_id IS NOT NULL  → qualquer autenticado = TRUE
-- Depois: só admin/dev/supervisor/manager. Mantém assinatura para não
-- quebrar as policies quote_items_*_scope, quotes_*_scope, orders_*_scope
-- que já chamam esta função.
CREATE OR REPLACE FUNCTION public.can_view_all_sales(_user_id uuid DEFAULT auth.uid())
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE(
    _user_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM public.user_roles
      WHERE user_id = _user_id
        AND role = ANY (ARRAY['admin'::app_role, 'dev'::app_role, 'supervisor'::app_role, 'manager'::app_role])
    ),
    false
  );
$$;

-- ─── 2) quote_items · policy permissiva ─────────────────────────────
-- A policy "Acesso a itens via orcamento" só verificava que existia a
-- quote-pai, sem checar dono. Como policies são OR-ed, ela anulava as
-- restritas quote_items_*_scope. As restritas já cobrem o acesso legítimo
-- (dono, supervisor da org, admin via can_view_all_sales), então basta
-- remover a permissiva.
DROP POLICY IF EXISTS "Acesso a itens via orcamento" ON public.quote_items;

-- ─── 3) conversation_event_history · adicionar checagem de dono ─────
DROP POLICY IF EXISTS "Acesso ao histórico de eventos segue o log de auditoria"
  ON public.conversation_event_history;

CREATE POLICY "Acesso ao histórico de eventos segue o log de auditoria"
  ON public.conversation_event_history
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.conversation_audit_logs cal
      WHERE cal.id = conversation_event_history.conversation_id
        AND (
          cal.user_id = auth.uid()
          OR public.has_role(auth.uid(), 'admin'::app_role)
          OR public.has_role(auth.uid(), 'dev'::app_role)
        )
    )
  );

-- ─── 4) system_settings · remover policies USING true ───────────────
-- Ambas expunham TODAS as chaves para qualquer autenticado, bypassando
-- a whitelist "Permitir leitura pública de configurações básicas".
DROP POLICY IF EXISTS "Everyone can view settings" ON public.system_settings;
DROP POLICY IF EXISTS "system_settings readable by authenticated" ON public.system_settings;

-- Autenticados sem role especial passam a ler apenas via a policy
-- whitelist já existente ("Permitir leitura pública de configurações
-- básicas", role public/authenticated, key IN (maintenance_mode,
-- app_version, public_announcement)). Admins/devs/supervisores mantêm
-- acesso total via "Acesso total para administradores" (FOR ALL).
-- <<< END 20260708123135_723b07ad-7c94-4e76-91ce-599dace6f0ce.sql <<<

-- >>> BEGIN 20260708123339_2b83e1a9-4b54-473f-bbc0-1e6b0170bf0c.sql >>>
-- Tighten SELECT policies on collection_item_reactions to add explicit
-- ownership check for authenticated path and restrict public path to anon.
DROP POLICY IF EXISTS "Public can view reactions for public collections" ON public.collection_item_reactions;

CREATE POLICY "Owners can view own collection reactions"
  ON public.collection_item_reactions
  FOR SELECT
  TO authenticated
  USING (
    auth.uid() IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public.collections c
      WHERE c.id = collection_item_reactions.collection_id
        AND c.user_id = auth.uid()
    )
  );

CREATE POLICY "Public can view reactions via valid share token"
  ON public.collection_item_reactions
  FOR SELECT
  TO anon
  USING (
    EXISTS (
      SELECT 1 FROM public.collections c
      WHERE c.id = collection_item_reactions.collection_id
        AND c.is_public = true
        AND c.share_token IS NOT NULL
        AND (c.share_expires_at IS NULL OR c.share_expires_at > now())
    )
  );
-- <<< END 20260708123339_2b83e1a9-4b54-473f-bbc0-1e6b0170bf0c.sql <<<

