-- >>> BEGIN 20260710101513_fix_cascade_deactivation_orphan_variants_images_2026_07.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- MIGRATION: fix_cascade_deactivation_orphan_variants_images_2026_07
--
-- Corrige dois gaps de consistência identificados na Auditoria v5 Battery Q:
--
-- BUG Q06: produto 19148 tem is_active=false mas 3 variantes com is_active=true
--   → O trigger fn_cascade_product_deactivation deveria ter cascateado,
--     mas não o fez (produto foi desativado via mecanismo alternativo)
--
-- BUG Q10: BAC005P e CJ405 (desativados em 2026-06-27) têm product_images
--   com is_active=true — trigger não existia ou não cascateou para images
--
-- FIX: Aplicar o cascade manualmente para os dois casos
-- ═══════════════════════════════════════════════════════════════════

-- FIX Q06: Desativar variantes órfãs de produtos inativos
-- Aplica a mesma lógica que fn_cascade_product_deactivation deveria ter aplicado
UPDATE product_variants pv
SET is_active  = false,
    updated_at = NOW()
FROM products p
WHERE pv.product_id = p.id
  AND p.is_active    = false
  AND pv.is_active   = true;

-- FIX Q10: Desativar product_images de produtos inativos
-- Se o produto está inativo, suas imagens devem estar inativas também
UPDATE product_images pi
SET is_active  = false,
    updated_at = NOW()
FROM products p
WHERE pi.product_id = p.id
  AND p.is_active   = false
  AND pi.is_active  = true;
;

-- <<< END 20260710101513_fix_cascade_deactivation_orphan_variants_images_2026_07.sql <<<

-- >>> BEGIN 20260710104139_fix_color_swatches_dedup_2026_07.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- MIGRATION: fix_color_swatches_dedup_2026_07
--
-- BUG: 11 produtos têm entradas duplicadas em color_swatches JSONB
-- (mesmo color_name + image_url aparece 2x no array)
-- CAUSA: pipeline XBZ inseriu duplicatas antes de nossas migrações
-- FIX: deduplicar preservando primeiro elemento de cada par único
-- ═══════════════════════════════════════════════════════════════════

UPDATE products p
SET color_swatches = (
  SELECT jsonb_agg(cs ORDER BY cs_idx)
  FROM (
    SELECT DISTINCT ON (cs->>'color_name', cs->>'image_url')
      cs, ordinality AS cs_idx
    FROM jsonb_array_elements(p.color_swatches) WITH ORDINALITY AS arr(cs, ordinality)
    ORDER BY cs->>'color_name', cs->>'image_url', ordinality
  ) deduped
),
updated_at = NOW()
WHERE p.is_active = true
  AND p.sku_promo IN (
    SELECT DISTINCT sku_promo FROM products p2,
      jsonb_array_elements(CASE jsonb_typeof(p2.color_swatches) WHEN 'array' THEN p2.color_swatches ELSE '[]'::jsonb END) cs2
    WHERE p2.is_active=true AND cs2->>'image_url' IS NOT NULL AND cs2->>'color_name' IS NOT NULL
    GROUP BY p2.id, p2.sku_promo, cs2->>'color_name', cs2->>'image_url'
    HAVING COUNT(*)>1
  );
;

-- <<< END 20260710104139_fix_color_swatches_dedup_2026_07.sql <<<

-- >>> BEGIN 20260710111116_fix_p12214_invalid_image_url_2026_07.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- MIGRATION: fix_p12214_invalid_image_url_2026_07
--
-- BUG: P@12214 tem primary_image_url = 'https://cdn.xbzbrindes.com.br/12214'
-- Este URL retorna text/html (página web), NÃO uma imagem.
-- Quando o frontend tenta renderizar como <img>, resulta em broken image.
-- NULL é tratado com placeholder e é semanticamente correto.
-- ═══════════════════════════════════════════════════════════════════
UPDATE products
SET
  primary_image_url = NULL,
  og_image_url      = CASE WHEN og_image_url = 'https://cdn.xbzbrindes.com.br/12214' THEN NULL ELSE og_image_url END,
  updated_at        = NOW()
WHERE sku_promo = 'P@12214'
  AND primary_image_url = 'https://cdn.xbzbrindes.com.br/12214';
;

-- <<< END 20260710111116_fix_p12214_invalid_image_url_2026_07.sql <<<

-- >>> BEGIN 20260710111155_create_fn_pipeline_health_monitor_2026_07.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- MIGRATION: create_fn_pipeline_health_monitor_2026_07
--
-- Função de monitoramento contínuo do pipeline de imagens.
-- Detecta automaticamente os problemas que encontramos nas auditorias:
-- 1. Produtos com primary_image_url CF sem verified primary record
-- 2. Orphan variants (active variant de produto inativo)
-- 3. Orphan images (active image de produto inativo)
-- 4. Imagens pending bloqueadas (sem tentativas há > 1h)
-- 5. Produtos ativos sem nenhuma imagem (gap)
-- 6. Swatches duplicados no JSONB
-- 7. Tokens de desativação expirados sem uso
-- ═══════════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.fn_pipeline_health_monitor()
RETURNS TABLE (
  check_name        text,
  status            text,    -- 'OK' | 'WARNING' | 'CRITICAL'
  value             bigint,
  target            bigint,
  details           text
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
BEGIN

  -- 1. Gap de imagens — produtos ativos sem CF verified
  RETURN QUERY SELECT
    'gap_sem_cf_images'::text,
    CASE WHEN (SELECT COUNT(*) FROM products p WHERE p.is_active=true
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.cf_sync_status='verified' AND pi.is_active=true)) > 50
      THEN 'CRITICAL' WHEN (SELECT COUNT(*) FROM products p WHERE p.is_active=true
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.cf_sync_status='verified' AND pi.is_active=true)) > 0
      THEN 'WARNING' ELSE 'OK' END,
    (SELECT COUNT(*) FROM products p WHERE p.is_active=true
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.cf_sync_status='verified' AND pi.is_active=true))::bigint,
    0::bigint,
    'Produtos ativos sem imagem verificada no Cloudflare'::text;

  -- 2. Primary consistency — CF URL sem verified primary record
  RETURN QUERY SELECT
    'primary_cf_without_verified_record'::text,
    CASE WHEN (SELECT COUNT(*) FROM products p WHERE p.is_active=true AND p.primary_image_url LIKE '%imagedelivery.net%'
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.is_primary=true AND pi.cf_sync_status='verified' AND pi.is_active=true)) > 0
      THEN 'CRITICAL' ELSE 'OK' END,
    (SELECT COUNT(*) FROM products p WHERE p.is_active=true AND p.primary_image_url LIKE '%imagedelivery.net%'
      AND NOT EXISTS (SELECT 1 FROM product_images pi WHERE pi.product_id=p.id AND pi.is_primary=true AND pi.cf_sync_status='verified' AND pi.is_active=true))::bigint,
    0::bigint,
    'primary_image_url aponta CF mas sem product_images.is_primary=true verified'::text;

  -- 3. Orphan variants
  RETURN QUERY SELECT
    'orphan_variants'::text,
    CASE WHEN (SELECT COUNT(*) FROM product_variants pv JOIN products p ON p.id=pv.product_id WHERE p.is_active=false AND pv.is_active=true) > 0
      THEN 'CRITICAL' ELSE 'OK' END,
    (SELECT COUNT(*) FROM product_variants pv JOIN products p ON p.id=pv.product_id WHERE p.is_active=false AND pv.is_active=true)::bigint,
    0::bigint,
    'Variantes ativas pertencendo a produtos inativos'::text;

  -- 4. Orphan images
  RETURN QUERY SELECT
    'orphan_images'::text,
    CASE WHEN (SELECT COUNT(*) FROM product_images pi JOIN products p ON p.id=pi.product_id WHERE p.is_active=false AND pi.is_active=true) > 0
      THEN 'CRITICAL' ELSE 'OK' END,
    (SELECT COUNT(*) FROM product_images pi JOIN products p ON p.id=pi.product_id WHERE p.is_active=false AND pi.is_active=true)::bigint,
    0::bigint,
    'Imagens ativas pertencendo a produtos inativos'::text;

  -- 5. Imagens pending há muito tempo (> 6h)
  RETURN QUERY SELECT
    'pending_images_stuck'::text,
    CASE WHEN (SELECT COUNT(*) FROM product_images WHERE cf_sync_status='pending' AND is_active=true AND updated_at < NOW() - INTERVAL '6 hours') > 0
      THEN 'WARNING' ELSE 'OK' END,
    (SELECT COUNT(*) FROM product_images WHERE cf_sync_status='pending' AND is_active=true AND updated_at < NOW() - INTERVAL '6 hours')::bigint,
    0::bigint,
    'Imagens pending sem atualização há > 6h (pipeline pode estar preso)'::text;

  -- 6. Swatches duplicados
  RETURN QUERY SELECT
    'swatch_duplicates'::text,
    CASE WHEN (
      SELECT COUNT(*) FROM (
        SELECT p.id FROM products p,
          jsonb_array_elements(CASE jsonb_typeof(p.color_swatches) WHEN 'array' THEN p.color_swatches ELSE '[]'::jsonb END) cs
        WHERE p.is_active=true AND cs->>'image_url' IS NOT NULL AND cs->>'color_name' IS NOT NULL
        GROUP BY p.id, cs->>'color_name', cs->>'image_url' HAVING COUNT(*)>1
      ) t) > 0 THEN 'WARNING' ELSE 'OK' END,
    (SELECT COUNT(*) FROM (
        SELECT p.id FROM products p,
          jsonb_array_elements(CASE jsonb_typeof(p.color_swatches) WHEN 'array' THEN p.color_swatches ELSE '[]'::jsonb END) cs
        WHERE p.is_active=true AND cs->>'image_url' IS NOT NULL AND cs->>'color_name' IS NOT NULL
        GROUP BY p.id, cs->>'color_name', cs->>'image_url' HAVING COUNT(*)>1
      ) t)::bigint,
    0::bigint,
    'Produtos com entradas duplicadas em color_swatches'::text;

  -- 7. Tokens expirados sem uso
  RETURN QUERY SELECT
    'expired_unused_tokens'::text,
    CASE WHEN (SELECT COUNT(*) FROM product_deactivation_tokens WHERE used=false AND expires_at < NOW()) > 0
      THEN 'WARNING' ELSE 'OK' END,
    (SELECT COUNT(*) FROM product_deactivation_tokens WHERE used=false AND expires_at < NOW())::bigint,
    0::bigint,
    'Tokens de autorização de desativação expirados sem uso'::text;

  -- 8. primary_image_url inválida (HTML em vez de imagem)
  RETURN QUERY SELECT
    'invalid_primary_image_url'::text,
    CASE WHEN (SELECT COUNT(*) FROM products WHERE is_active=true
      AND primary_image_url IS NOT NULL
      AND primary_image_url NOT LIKE '%imagedelivery.net%'
      AND primary_image_url NOT LIKE '%.jpg%'
      AND primary_image_url NOT LIKE '%.png%'
      AND primary_image_url NOT LIKE '%.webp%'
    ) > 0 THEN 'WARNING' ELSE 'OK' END,
    (SELECT COUNT(*) FROM products WHERE is_active=true
      AND primary_image_url IS NOT NULL
      AND primary_image_url NOT LIKE '%imagedelivery.net%'
      AND primary_image_url NOT LIKE '%.jpg%'
      AND primary_image_url NOT LIKE '%.png%'
      AND primary_image_url NOT LIKE '%.webp%'
    )::bigint,
    0::bigint,
    'primary_image_url aponta para URL não-imagem (HTML, texto, etc.)'::text;

END $$;

COMMENT ON FUNCTION public.fn_pipeline_health_monitor IS
'Monitor de saúde do pipeline de imagens CF. Detecta orphans, inconsistências,
 imagens stuck, swatches duplicados e tokens expirados. Criado em 2026-07-10.';
;

-- <<< END 20260710111155_create_fn_pipeline_health_monitor_2026_07.sql <<<

-- >>> BEGIN 20260710111227_create_pipeline_health_cron_2026_07.sql >>>

-- ═══════════════════════════════════════════════════════════════════
-- MIGRATION: create_pipeline_health_cron_2026_07
--
-- Tabela de log + cron job que roda fn_pipeline_health_monitor()
-- a cada 4 horas. Registra resultados e pode alertar via trigger.
-- ═══════════════════════════════════════════════════════════════════

-- Tabela de log de saúde do pipeline
CREATE TABLE IF NOT EXISTS public.pipeline_health_log (
  id            uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  checked_at    timestamptz DEFAULT NOW() NOT NULL,
  critical_count bigint NOT NULL DEFAULT 0,
  warning_count  bigint NOT NULL DEFAULT 0,
  ok_count       bigint NOT NULL DEFAULT 0,
  results        jsonb NOT NULL DEFAULT '[]'::jsonb
);

-- Habilitar RLS
ALTER TABLE public.pipeline_health_log ENABLE ROW LEVEL SECURITY;

-- Policy: apenas service_role pode escrever
CREATE POLICY "pipeline_health_log_service_only"
  ON public.pipeline_health_log FOR ALL
  USING (auth.role() = 'service_role');

-- Função que executa o monitor e registra no log
CREATE OR REPLACE FUNCTION public.fn_run_pipeline_health_check()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_results    jsonb;
  v_critical   bigint;
  v_warning    bigint;
  v_ok         bigint;
BEGIN
  -- Coletar resultados
  SELECT
    jsonb_agg(jsonb_build_object(
      'check', check_name, 'status', status, 'value', value, 'target', target
    )),
    COUNT(*) FILTER (WHERE status='CRITICAL'),
    COUNT(*) FILTER (WHERE status='WARNING'),
    COUNT(*) FILTER (WHERE status='OK')
  INTO v_results, v_critical, v_warning, v_ok
  FROM fn_pipeline_health_monitor();

  -- Registrar no log
  INSERT INTO public.pipeline_health_log (critical_count, warning_count, ok_count, results)
  VALUES (v_critical, v_warning, v_ok, COALESCE(v_results, '[]'::jsonb));

  -- Limpar logs antigos (manter apenas 7 dias)
  DELETE FROM public.pipeline_health_log
  WHERE checked_at < NOW() - INTERVAL '7 days';
END $$;

-- Cron job: executar a cada 4 horas
SELECT cron.schedule(
  'pipeline-health-check-4h',
  '0 */4 * * *',
  $$SELECT public.fn_run_pipeline_health_check()$$
);
;

-- <<< END 20260710111227_create_pipeline_health_cron_2026_07.sql <<<

