-- >>> BEGIN 20260712231443_magazine_fix_rollup_exactly_once_watermark.sql >>>
-- ============================================================================
-- FIX P0 — magazines.view_count era inflado toda noite (double-count).
--
-- CAUSA: magazine_rollup_view_counts() somava `view_count = view_count + c`
-- sobre uma janela DESLIZANTE (`viewed_at >= now() - interval '1 hour'`), e era
-- chamada por DOIS crons:
--   • magazine-view-rollup-hourly  → '5 * * * *'  → roda 03:05, conta 02:05→03:05
--   • magazine-cleanup-nightly     → '15 3 * * *' → roda 03:15, chama
--     magazine_cleanup_all(), cujo 4º passo é o MESMO rollup → conta 02:15→03:15
-- Sobreposição: 02:15→03:05 = 50 min de eventos somados DUAS VEZES, toda noite.
--
-- Além disso, a janela deslizante presumia que o cron nunca atrasa: qualquer
-- jitter criava buraco (eventos perdidos) ou sobreposição (contados 2x).
--
-- CORREÇÃO: marca d'água (watermark) + SELECT ... FOR UPDATE.
-- O FOR UPDATE serializa execuções concorrentes; a 2ª a entrar lê o watermark já
-- avançado e conta o intervalo [now, now) = 0 linhas. Vira exactly-once.
-- Isso torna a chamada dentro de magazine_cleanup_all() INÓCUA — e por isso ela
-- pode (e deve) continuar lá, como rede de segurança caso o cron horário morra.
-- ============================================================================

CREATE TABLE IF NOT EXISTS public.magazine_view_rollup_watermark (
  id             boolean     NOT NULL DEFAULT true PRIMARY KEY CHECK (id),  -- singleton
  last_rolled_at timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.magazine_view_rollup_watermark IS
  'Singleton. Marca d''água do rollup de view_count. Garante exactly-once entre o cron horário e o nightly.';

INSERT INTO public.magazine_view_rollup_watermark (id, last_rolled_at)
VALUES (true, now())
ON CONFLICT (id) DO NOTHING;

GRANT ALL ON public.magazine_view_rollup_watermark TO service_role;
ALTER TABLE public.magazine_view_rollup_watermark ENABLE ROW LEVEL SECURITY;
-- Sem policies: fail-closed. Só SECURITY DEFINER / service_role acessa.

CREATE OR REPLACE FUNCTION public.magazine_rollup_view_counts()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  _from         timestamptz;
  _to           timestamptz := now();
  updated_count integer := 0;
BEGIN
  -- Serializa execuções concorrentes (horário x nightly) e lê a marca d'água.
  SELECT last_rolled_at INTO _from
  FROM public.magazine_view_rollup_watermark
  WHERE id
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.magazine_view_rollup_watermark (id, last_rolled_at)
    VALUES (true, _to)
    ON CONFLICT (id) DO NOTHING;
    RETURN 0;
  END IF;

  -- Execução duplicada dentro da mesma janela: nada novo para somar.
  IF _from >= _to THEN
    RETURN 0;
  END IF;

  WITH counts AS (
    SELECT magazine_id, count(*) AS c
    FROM public.magazine_public_view_events
    WHERE viewed_at >= _from
      AND viewed_at <  _to          -- half-open [_from, _to): sem overlap entre janelas
    GROUP BY magazine_id
  )
  UPDATE public.magazines m
  SET view_count = m.view_count + counts.c
  FROM counts
  WHERE m.id = counts.magazine_id;

  GET DIAGNOSTICS updated_count = ROW_COUNT;

  UPDATE public.magazine_view_rollup_watermark
  SET last_rolled_at = _to
  WHERE id;

  RETURN updated_count;
END;
$function$;

COMMENT ON FUNCTION public.magazine_rollup_view_counts() IS
  'Exactly-once. Soma view_count no intervalo half-open [watermark, now()) e avança o watermark sob FOR UPDATE. Seguro para chamar N vezes.';;

-- <<< END 20260712231443_magazine_fix_rollup_exactly_once_watermark.sql <<<

-- >>> BEGIN 20260712231511_magazine_fix_partition_retention_and_lookahead.sql >>>
-- ============================================================================
-- FIX P1 (a) — RETENTION SILENCIOSAMENTE QUEBRADA
--
-- magazine_cleanup_view_events() fazia:
--     DELETE FROM public.magazine_public_view_events_default WHERE viewed_at < cutoff
--                                                  ^^^^^^^^ SÓ a partição DEFAULT
--
-- Hoje isso "funciona" por acidente: a DEFAULT é a única partição que existe.
-- No dia 25, o cron magazine-partition-maintenance cria a partição mensal —
-- e a partir daí TODAS as linhas novas caem nela, onde o DELETE nunca olha.
-- Resultado: retention de 180 dias vira crescimento ILIMITADO, em silêncio.
--
-- CORREÇÃO: deletar pela TABELA PAI. O Postgres roteia o DELETE para todas as
-- partições, inclusive a DEFAULT.
--
-- FIX P1 (b) — BOMBA-RELÓGIO DO PARTICIONAMENTO
--
-- A manutenção rodava só no dia 25 e criava APENAS o mês seguinte. Duas falhas:
--   1. NÃO EXISTE partição do mês corrente. Todo evento de julho/2026 está indo
--      para a DEFAULT.
--   2. Se o cron falhar UMA vez, as linhas do mês seguinte caem na DEFAULT — e aí
--      `CREATE TABLE ... PARTITION OF` daquele mês passa a FALHAR PARA SEMPRE:
--      o Postgres precisa provar que a DEFAULT não tem linha no range novo, pega
--      ACCESS EXCLUSIVE, faz full scan e aborta com
--      "updated partition constraint for default partition would be violated".
--      Quebra permanente e silenciosa.
--
-- CORREÇÃO: função idempotente que garante [mês corrente .. +N meses], rodando
-- DIARIAMENTE. Um dia de falha deixa de ser fatal (há 3 meses de folga).
--
-- JANELA LIVRE: a tabela tem 0 linhas AGORA. Anexar a partição do mês corrente
-- neste momento é instantâneo e sem risco. Com dados dentro, custaria downtime.
-- ============================================================================

-- (a) Retention correta: DELETE no PAI roteia para todas as partições.
CREATE OR REPLACE FUNCTION public.magazine_cleanup_view_events(_ttl_days integer DEFAULT 180)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  deleted_count integer := 0;
BEGIN
  DELETE FROM public.magazine_public_view_events   -- PAI: roteia p/ TODAS as partições
  WHERE viewed_at < now() - make_interval(days => _ttl_days);

  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$function$;

COMMENT ON FUNCTION public.magazine_cleanup_view_events(integer) IS
  'Retention de view events. DELETE na tabela PAI (roteia p/ todas as partições). Antes apagava só da DEFAULT.';

-- (b) Manutenção de partições: idempotente, com lookahead.
CREATE OR REPLACE FUNCTION public.magazine_ensure_view_event_partitions(_months_ahead integer DEFAULT 3)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  _created integer := 0;
  _i       integer;
  _m       date;
  _name    text;
BEGIN
  -- i = 0 garante o MÊS CORRENTE (que hoje não existe).
  FOR _i IN 0.._months_ahead LOOP
    _m    := (date_trunc('month', now()) + make_interval(months => _i))::date;
    _name := 'magazine_public_view_events_' || to_char(_m, 'YYYY_MM');

    IF NOT EXISTS (
      SELECT 1 FROM pg_class
      WHERE relname = _name AND relnamespace = 'public'::regnamespace
    ) THEN
      EXECUTE format(
        'CREATE TABLE public.%I PARTITION OF public.magazine_public_view_events FOR VALUES FROM (%L) TO (%L)',
        _name, _m, (_m + interval '1 month')::date
      );
      _created := _created + 1;
    END IF;
  END LOOP;

  RETURN _created;
END;
$function$;

COMMENT ON FUNCTION public.magazine_ensure_view_event_partitions(integer) IS
  'Idempotente. Garante partições de [mês corrente .. +N]. Rodar DIARIAMENTE: lookahead evita que uma falha de cron quebre o particionamento permanentemente.';;

-- <<< END 20260712231511_magazine_fix_partition_retention_and_lookahead.sql <<<

-- >>> BEGIN 20260712231546_magazine_fix_indexes_and_rls_initplan.sql >>>
-- ============================================================================
-- FIX P2 — Índices redundantes, FK sem índice e RLS reavaliada por linha.
-- ============================================================================

-- (a) REDUNDANTES — mesmas colunas na mesma ordem que um UNIQUE já existente.
--     Índice redundante = custo de escrita e storage por zero ganho de leitura.

-- idx_magazine_items_mag_pos (magazine_id, position)
--   ⊂ magazine_items_position_unique UNIQUE (magazine_id, position)
DROP INDEX IF EXISTS public.idx_magazine_items_mag_pos;

-- idx_magazines_owner (owner_id) WHERE deleted_at IS NULL
--   ⊂ idx_magazines_not_deleted (owner_id, updated_at DESC) WHERE deleted_at IS NULL
--     (mesmo predicado, owner_id como coluna líder → serve as mesmas queries)
DROP INDEX IF EXISTS public.idx_magazines_owner;

-- (b) FK SEM ÍNDICE — magazine_public_reactions.item_id → magazine_items(id) ON DELETE CASCADE.
--     Sem índice, todo DELETE em magazine_items faz SEQ SCAN em reactions para
--     achar as linhas a cascatear. Itens são removidos a cada edição de revista.
CREATE INDEX IF NOT EXISTS idx_mag_reactions_item
  ON public.magazine_public_reactions (item_id)
  WHERE item_id IS NOT NULL;

-- (c) RLS: auth.uid() direto no predicado é reavaliado POR LINHA.
--     Envolver em (SELECT auth.uid()) força um InitPlan → avaliado UMA vez.
--     Recomendação oficial do Supabase p/ RLS em escala. Semântica idêntica.

DROP POLICY IF EXISTS magazines_owner_all ON public.magazines;
CREATE POLICY magazines_owner_all ON public.magazines
  FOR ALL TO authenticated
  USING      (owner_id = (SELECT auth.uid()) AND deleted_at IS NULL)
  WITH CHECK (owner_id = (SELECT auth.uid()));

DROP POLICY IF EXISTS magazines_org_read ON public.magazines;
CREATE POLICY magazines_org_read ON public.magazines
  FOR SELECT TO authenticated
  USING (
    organization_id IS NOT NULL
    AND deleted_at IS NULL
    AND EXISTS (
      SELECT 1 FROM public.organization_members om
      WHERE om.organization_id = magazines.organization_id
        AND om.user_id = (SELECT auth.uid())
    )
  );

DROP POLICY IF EXISTS magazine_items_via_owner_or_org ON public.magazine_items;
CREATE POLICY magazine_items_via_owner_or_org ON public.magazine_items
  FOR ALL TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.magazines m
      WHERE m.id = magazine_items.magazine_id
        AND (
          m.owner_id = (SELECT auth.uid())
          OR (
            m.organization_id IS NOT NULL
            AND EXISTS (
              SELECT 1 FROM public.organization_members om
              WHERE om.organization_id = m.organization_id
                AND om.user_id = (SELECT auth.uid())
            )
          )
        )
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.magazines m
      WHERE m.id = magazine_items.magazine_id
        AND m.owner_id = (SELECT auth.uid())
    )
  );

DROP POLICY IF EXISTS templates_owner_all ON public.magazine_templates;
CREATE POLICY templates_owner_all ON public.magazine_templates
  FOR ALL TO authenticated
  USING      (owner_id = (SELECT auth.uid()))
  WITH CHECK (owner_id = (SELECT auth.uid()));

DROP POLICY IF EXISTS templates_org_read ON public.magazine_templates;
CREATE POLICY templates_org_read ON public.magazine_templates
  FOR SELECT TO authenticated
  USING (
    shared_in_org = true
    AND organization_id IS NOT NULL
    AND EXISTS (
      SELECT 1 FROM public.organization_members om
      WHERE om.organization_id = magazine_templates.organization_id
        AND om.user_id = (SELECT auth.uid())
    )
  );

-- (d) Índice de cobertura para o EXISTS das policies acima.
CREATE INDEX IF NOT EXISTS idx_org_members_org_user
  ON public.organization_members (organization_id, user_id);;

