-- >>> BEGIN 20260714112457_fix_auth_hydration_rpc_and_rls.sql >>>

-- ============================================================
-- MIGRATION: fix_auth_hydration_rpc_and_rls
-- Resolve hydration_timeout:profile+roles:5000ms
-- Combina 2 round-trips em 1 RPC + corrige RLS profiles_select
-- ============================================================

-- 1. RPC combinada: perfil + roles em um único round-trip
CREATE OR REPLACE FUNCTION public.get_profile_and_roles(_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
DECLARE
  v_profile jsonb;
  v_roles   jsonb;
BEGIN
  -- Guard: só o próprio usuário (ou dev) pode buscar
  IF _user_id IS DISTINCT FROM auth.uid()
     AND NOT public.has_role(auth.uid(), 'dev'::app_role)
  THEN
    RAISE EXCEPTION 'forbidden: cannot query profile of another user'
      USING ERRCODE = '42501';
  END IF;

  -- Busca profile pela coluna correta (user_id, não id)
  SELECT to_jsonb(p) INTO v_profile
  FROM public.profiles p
  WHERE p.user_id = _user_id
  LIMIT 1;

  -- Agrega roles em array JSON
  SELECT jsonb_agg(ur.role ORDER BY ur.role) INTO v_roles
  FROM public.user_roles ur
  WHERE ur.user_id = _user_id;

  RETURN jsonb_build_object(
    'profile', v_profile,
    'roles',   COALESCE(v_roles, '[]'::jsonb)
  );
END;
$$;

-- Permissões: apenas authenticated pode invocar
REVOKE ALL ON FUNCTION public.get_profile_and_roles(uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_profile_and_roles(uuid) TO authenticated;

-- 2. Corrige RLS profiles_select: usar user_id em vez de id (gen_random_uuid())
--    Antes: auth.uid() = id    (semanticamente errado — id é gen_random_uuid())
--    Depois: auth.uid() = user_id  (correto — user_id é a FK para auth.users)
DROP POLICY IF EXISTS "profiles_select" ON public.profiles;
CREATE POLICY "profiles_select"
  ON public.profiles
  FOR SELECT
  TO authenticated
  USING (
    (( SELECT auth.uid() AS uid) = user_id)
    OR is_admin_or_above(( SELECT auth.uid() AS uid))
  );

-- 3. Corrige também profiles_update: mesma inconsistência
DROP POLICY IF EXISTS "profiles_update" ON public.profiles;
CREATE POLICY "profiles_update"
  ON public.profiles
  FOR UPDATE
  TO public
  USING      ((( SELECT auth.uid() AS uid) = user_id))
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));
;

-- <<< END 20260714112457_fix_auth_hydration_rpc_and_rls.sql <<<

-- >>> BEGIN 20260714112808_fix_auth_hydration_rpc_and_rls.sql >>>
-- ============================================================
-- MIGRATION: fix_auth_hydration_rpc_and_rls
-- Data: 2026-07-14
-- Autor: ti@promobrindes.com.br (BUG-AUTH-HYDRATION-v2)
--
-- Resolve hydration_timeout:profile+roles:5000ms
-- Causa raiz: 2 round-trips separados (profiles + user_roles) onde
-- qualquer latência de rede ou cold start consumia todo o budget de 5s.
-- Além disso, a policy profiles_select comparava auth.uid() com id
-- (gen_random_uuid()) em vez de user_id (FK para auth.users).
-- ============================================================

-- 1. RPC combinada: perfil + roles em um único round-trip
--    Antes: Promise.all([SELECT profiles, SELECT user_roles]) = 2 round-trips
--    Depois: rpc('get_profile_and_roles') = 1 round-trip → ~50% menos latência
CREATE OR REPLACE FUNCTION public.get_profile_and_roles(_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
DECLARE
  v_profile jsonb;
  v_roles   jsonb;
BEGIN
  -- Guard: só o próprio usuário (ou dev impersonando) pode buscar
  IF _user_id IS DISTINCT FROM auth.uid()
     AND NOT public.has_role(auth.uid(), 'dev'::app_role)
  THEN
    RAISE EXCEPTION 'forbidden: cannot query profile of another user'
      USING ERRCODE = '42501';
  END IF;

  -- Busca profile pela coluna correta (user_id, não id/gen_random_uuid())
  SELECT to_jsonb(p) INTO v_profile
  FROM public.profiles p
  WHERE p.user_id = _user_id
  LIMIT 1;

  -- Agrega roles em array JSON (ordenado para determinismo)
  SELECT jsonb_agg(ur.role ORDER BY ur.role) INTO v_roles
  FROM public.user_roles ur
  WHERE ur.user_id = _user_id;

  RETURN jsonb_build_object(
    'profile', v_profile,
    'roles',   COALESCE(v_roles, '[]'::jsonb)
  );
END;
$$;

-- Permissões: anon não acessa; authenticated pode invocar
REVOKE ALL ON FUNCTION public.get_profile_and_roles(uuid) FROM anon;
GRANT EXECUTE ON FUNCTION public.get_profile_and_roles(uuid) TO authenticated;

-- 2. Corrige RLS profiles_select: user_id em vez de id
--    Bug: auth.uid() = id → SEMPRE falso para usuários não-admin
--         pois id é gen_random_uuid(), não auth.uid()
--    Fix: auth.uid() = user_id (FK correta para auth.users)
DROP POLICY IF EXISTS "profiles_select" ON public.profiles;
CREATE POLICY "profiles_select"
  ON public.profiles
  FOR SELECT
  TO authenticated
  USING (
    (( SELECT auth.uid() AS uid) = user_id)
    OR is_admin_or_above(( SELECT auth.uid() AS uid))
  );

-- 3. Corrige RLS profiles_update com a mesma inconsistência
DROP POLICY IF EXISTS "profiles_update" ON public.profiles;
CREATE POLICY "profiles_update"
  ON public.profiles
  FOR UPDATE
  TO public
  USING      ((( SELECT auth.uid() AS uid) = user_id))
  WITH CHECK ((( SELECT auth.uid() AS uid) = user_id));

-- <<< END 20260714112808_fix_auth_hydration_rpc_and_rls.sql <<<

-- >>> BEGIN 20260714120601_fix_auth_hydration_v2_insert_policy_null_guard.sql >>>

-- ============================================================
-- MIGRATION v2: fix_auth_hydration_insert_policy_null_guard
-- Bugs encontrados na auditoria exaustiva pós-deploy
-- ============================================================

-- BUG 3: profiles_insert usava `id` em vez de `user_id` como WITH CHECK
-- Inconsistência: SELECT e UPDATE já usam user_id (corrigidos na v1)
-- INSERT ainda checa `auth.uid() = id` — se uma linha for criada com
-- id=auth.uid() mas user_id≠auth.uid(), fica invisível via SELECT/UPDATE
-- Fix: add WITH CHECK em user_id também (mantendo id para compatibilidade)
DROP POLICY IF EXISTS "profiles_insert" ON public.profiles;
CREATE POLICY "profiles_insert"
  ON public.profiles
  FOR INSERT
  TO public
  WITH CHECK (
    (( SELECT auth.uid() AS uid) = user_id)
    AND (( SELECT auth.uid() AS uid) = id)
  );

-- BUG 4: RPC sem guard contra _user_id = NULL
-- NULL IS DISTINCT FROM NULL = FALSE → guard não dispara → retorna vazio
-- Correto adicionar checagem explícita
CREATE OR REPLACE FUNCTION public.get_profile_and_roles(_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
DECLARE
  v_profile jsonb;
  v_roles   jsonb;
BEGIN
  -- Guard NULL: _user_id nulo não tem significado válido
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'get_profile_and_roles: _user_id cannot be null'
      USING ERRCODE = '22004';  -- null_value_not_allowed
  END IF;

  -- Guard cross-user: só o próprio usuário (ou dev) pode buscar
  IF _user_id IS DISTINCT FROM auth.uid()
     AND NOT public.has_role(auth.uid(), 'dev'::app_role)
  THEN
    RAISE EXCEPTION 'forbidden: cannot query profile of another user'
      USING ERRCODE = '42501';
  END IF;

  -- Busca profile pela coluna correta (user_id, não id)
  SELECT to_jsonb(p) INTO v_profile
  FROM public.profiles p
  WHERE p.user_id = _user_id
  LIMIT 1;

  -- Agrega roles em array JSON (ordenado para determinismo)
  SELECT jsonb_agg(ur.role ORDER BY ur.role) INTO v_roles
  FROM public.user_roles ur
  WHERE ur.user_id = _user_id;

  RETURN jsonb_build_object(
    'profile', v_profile,
    'roles',   COALESCE(v_roles, '[]'::jsonb)
  );
END;
$$;
;

-- <<< END 20260714120601_fix_auth_hydration_v2_insert_policy_null_guard.sql <<<

-- >>> BEGIN 20260714121200_fix_auth_hydration_v3_perf_safety.sql >>>
-- ============================================================
-- MIGRATION v3: fix_auth_hydration_v3_perf_safety
-- Data: 2026-07-14
-- Autor: ti@promobrindes.com.br (BUG-AUTH-HYDRATION-v2.2)
--
-- Melhorias de performance e seguranca identificadas na auditoria
-- exaustiva pos-deploy (31 blocos de teste + 300+ simulacoes):
--
-- 1. statement_timeout=6000ms na RPC (fail-fast antes do withTimeout=7s)
-- 2. Covering index idx_user_roles_user_id_covering (escala futura)
-- 3. COMMENT na funcao para documentacao e manutenção futura
-- ============================================================

-- MELHORIA 1: statement_timeout interno a RPC
-- Garante que se Supabase travar (lock contention, pool exhaustion),
-- a funcao falha em 6s no servidor — antes do withTimeout(7s) do cliente.
CREATE OR REPLACE FUNCTION public.get_profile_and_roles(_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = public
SET statement_timeout = '6000ms'
AS $$
DECLARE
  v_profile jsonb;
  v_roles   jsonb;
BEGIN
  -- Guard NULL: _user_id nulo nao tem significado valido
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'get_profile_and_roles: _user_id cannot be null'
      USING ERRCODE = '22004';
  END IF;

  -- Guard cross-user: so o proprio usuario (ou dev) pode buscar
  IF _user_id IS DISTINCT FROM auth.uid()
     AND NOT public.has_role(auth.uid(), 'dev'::app_role)
  THEN
    RAISE EXCEPTION 'forbidden: cannot query profile of another user'
      USING ERRCODE = '42501';
  END IF;

  -- Busca profile pela coluna correta (user_id, nao id)
  SELECT to_jsonb(p) INTO v_profile
  FROM public.profiles p
  WHERE p.user_id = _user_id
  LIMIT 1;

  -- Agrega roles em array JSON (ordenado para determinismo)
  SELECT jsonb_agg(ur.role ORDER BY ur.role) INTO v_roles
  FROM public.user_roles ur
  WHERE ur.user_id = _user_id;

  RETURN jsonb_build_object(
    'profile', v_profile,
    'roles',   COALESCE(v_roles, '[]'::jsonb)
  );
END;
$$;

-- MELHORIA 2: Covering index em user_roles
-- O planner usa seq scan com 13 usuarios (correto — custo < index scan).
-- Este index sera usado automaticamente quando o time crescer > ~50 usuarios.
CREATE INDEX IF NOT EXISTS idx_user_roles_user_id_covering
  ON public.user_roles (user_id, role);

-- MELHORIA 3: COMMENT para documentacao
COMMENT ON FUNCTION public.get_profile_and_roles(uuid) IS
  'RPC combinada: retorna {profile, roles} em 1 round-trip. '
  'SECURITY DEFINER — garante que vendedor nao veja perfil alheio. '
  'statement_timeout=6s (< 7s do withTimeout no cliente). '
  'Caller: useProfileRoles.fetchUserData via asTypedRPC<GetProfileAndRolesResult>. '
  'Criada em 2026-07-14 para resolver hydration_timeout:profile+roles:5000ms. '
  'Migration: 20260714112808_fix_auth_hydration_rpc_and_rls.';

-- <<< END 20260714121200_fix_auth_hydration_v3_perf_safety.sql <<<

-- >>> BEGIN 20260714121410_fix_auth_hydration_v3_perf_safety.sql >>>

-- ============================================================
-- MIGRATION v3: fix_auth_hydration_v3_perf_safety
-- 2026-07-14 — DB-statement-timeout + DB-covering-index + DB-comment
-- ============================================================

-- MELHORIA 1: statement_timeout interno à RPC
-- Garante que se Supabase travar (ex: lock contention, pool exhaustion),
-- a função falha em 6s no servidor — antes do withTimeout(7s) do cliente.
-- Isso evita que a RPC rode "para sempre" na conexão e libera o pool.
CREATE OR REPLACE FUNCTION public.get_profile_and_roles(_user_id uuid)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
STABLE
SET search_path = public
SET statement_timeout = '6000ms'
AS $$
DECLARE
  v_profile jsonb;
  v_roles   jsonb;
BEGIN
  -- Guard NULL: _user_id nulo não tem significado válido
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'get_profile_and_roles: _user_id cannot be null'
      USING ERRCODE = '22004';
  END IF;

  -- Guard cross-user: só o próprio usuário (ou dev) pode buscar
  IF _user_id IS DISTINCT FROM auth.uid()
     AND NOT public.has_role(auth.uid(), 'dev'::app_role)
  THEN
    RAISE EXCEPTION 'forbidden: cannot query profile of another user'
      USING ERRCODE = '42501';
  END IF;

  -- Busca profile em index covering (user_id)
  SELECT to_jsonb(p) INTO v_profile
  FROM public.profiles p
  WHERE p.user_id = _user_id
  LIMIT 1;

  -- Agrega roles (covering index user_id+role entra em ação aqui)
  SELECT jsonb_agg(ur.role ORDER BY ur.role) INTO v_roles
  FROM public.user_roles ur
  WHERE ur.user_id = _user_id;

  RETURN jsonb_build_object(
    'profile', v_profile,
    'roles',   COALESCE(v_roles, '[]'::jsonb)
  );
END;
$$;

-- MELHORIA 2: Covering index em user_roles
-- O planner usa seq scan hoje (13 linhas) mas com > 50 usuários vai usar index.
-- INCLUDE 'role' elimina heap fetch (index-only scan) para a query de roles.
-- Partial index: exclui roles raros (dev/supervisor/admin) que já têm
-- idx_user_roles_user_id_role dedicado — foca nos vendedores/agentes.
CREATE INDEX IF NOT EXISTS idx_user_roles_user_id_covering
  ON public.user_roles (user_id, role);

-- MELHORIA 3: COMMENT na função para manutenção futura
COMMENT ON FUNCTION public.get_profile_and_roles(uuid) IS
  'RPC combinada: retorna {profile, roles} em 1 round-trip. '
  'SECURITY DEFINER — garante que vendedor não veja perfil alheio. '
  'statement_timeout=6s (< 7s do withTimeout no cliente). '
  'Caller: useProfileRoles.fetchUserData via supabase.rpc. '
  'Criada em 2026-07-14 para resolver hydration_timeout:profile+roles:5000ms. '
  'Migration: 20260714112808_fix_auth_hydration_rpc_and_rls.';
;

-- <<< END 20260714121410_fix_auth_hydration_v3_perf_safety.sql <<<

-- >>> BEGIN 20260714123908_fix_auth_hydration_v4_drop_redundant_index.sql >>>

-- ============================================================
-- MIGRATION v4: fix_auth_hydration_v4_drop_redundant_index
-- 2026-07-14 — BUG detectado na auditoria exaustiva pós-v3
--
-- PROBLEMA: idx_user_roles_user_id_covering criado em v3 com
--   INDEX ON user_roles (user_id, role)
-- é IDÊNTICO ao user_roles_pkey:
--   UNIQUE INDEX ON user_roles USING btree (user_id, role)
--
-- A PRIMARY KEY em PostgreSQL já cria automaticamente um B-tree
-- index nos campos (user_id, role), o que torna o índice adicional
-- 100% redundante — write overhead + 16KB de storage desperdiçados.
--
-- SOLUÇÃO: Drop do índice redundante.
-- A PK continua existindo e cobre todas as queries relevantes:
--   - WHERE user_id = ? (leading column do índice composto)
--   - WHERE user_id = ? AND role = ? (cobertura completa)
-- ============================================================

DROP INDEX IF EXISTS public.idx_user_roles_user_id_covering;

-- Confirma que o PK ainda está presente
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE tablename = 'user_roles' AND indexname = 'user_roles_pkey'
  ) THEN
    RAISE EXCEPTION 'user_roles_pkey não encontrado — PK foi dropada acidentalmente!';
  END IF;
  RAISE NOTICE 'OK: user_roles_pkey ainda presente após drop do índice redundante';
END;
$$;
;

-- <<< END 20260714123908_fix_auth_hydration_v4_drop_redundant_index.sql <<<

-- >>> BEGIN 20260714130000_fix_auth_hydration_v4_drop_redundant_index.sql >>>
-- ============================================================
-- MIGRATION v4: fix_auth_hydration_v4_drop_redundant_index
-- 2026-07-14 — BUG detectado na auditoria exaustiva pós-deploy
--
-- BUG: idx_user_roles_user_id_covering criado em v3 com
--   INDEX ON user_roles (user_id, role)
-- é IDÊNTICO ao user_roles_pkey:
--   UNIQUE INDEX ON user_roles USING btree (user_id, role)
--
-- A PRIMARY KEY em PostgreSQL cria automaticamente um B-tree
-- index nos campos (user_id, role). O índice adicional era
-- 100% redundante — write overhead + 16KB de storage desperdiçados.
--
-- CAUSA: Foi criado sem verificar antes os índices existentes.
-- REGRA ADICIONADA: antes de criar qualquer índice, verificar
-- se a PK ou outro índice existente já cobre os mesmos campos.
-- ============================================================

DROP INDEX IF EXISTS public.idx_user_roles_user_id_covering;

-- Guard: confirma que PK não foi dropada acidentalmente
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE tablename = 'user_roles' AND indexname = 'user_roles_pkey'
  ) THEN
    RAISE EXCEPTION 'user_roles_pkey nao encontrado — PK foi dropada acidentalmente!';
  END IF;
  RAISE NOTICE 'OK: user_roles_pkey presente apos drop do indice redundante';
END;
$$;

