-- >>> BEGIN 20260716000001_p0_magazine_partition_rls_hardening.sql >>>
-- P0-1: magazine_public_view_events partition RLS hardening
-- Audit 2026-07-16: partições _2026_07..10 tinham rls_enabled=FALSE + GRANT ALL para anon.
-- Qualquer não-autenticado podia SELECT/INSERT/UPDATE/DELETE PII (session_id, token_hash).
--
-- Estratégia:
--   • ENABLE ROW LEVEL SECURITY em cada partição (deny-all por padrão para não-service_role)
--   • REVOKE ALL de anon e authenticated nas partições
--     (acesso legítimo de authenticated ao parent é via parent table que tem RLS+policies)
--   • Sem policies nas partições = deny-all via RLS para acesso direto via PostgREST
--   • service_role bypassa RLS por design → edge function magazine-public-view não é afetada
--   • Atualiza a função trigger para hardenar partições futuras automaticamente

-- ───────────────────────────────────────────────────────────────────
-- 1. Habilitar RLS + revogar grants nas partições existentes
-- ───────────────────────────────────────────────────────────────────
ALTER TABLE public.magazine_public_view_events_2026_07 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.magazine_public_view_events_2026_08 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.magazine_public_view_events_2026_09 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.magazine_public_view_events_2026_10 ENABLE ROW LEVEL SECURITY;
-- _default já tinha RLS=true mas incluímos para garantir idempotência

REVOKE ALL ON TABLE public.magazine_public_view_events_2026_07 FROM anon, authenticated;
REVOKE ALL ON TABLE public.magazine_public_view_events_2026_08 FROM anon, authenticated;
REVOKE ALL ON TABLE public.magazine_public_view_events_2026_09 FROM anon, authenticated;
REVOKE ALL ON TABLE public.magazine_public_view_events_2026_10 FROM anon, authenticated;
REVOKE ALL ON TABLE public.magazine_public_view_events_default  FROM anon, authenticated;

-- ───────────────────────────────────────────────────────────────────
-- 2. Atualizar trigger para hardenar partições futuras
-- ───────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.magazine_ensure_view_event_partitions(
  _months_ahead integer DEFAULT 3
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  _created integer := 0;
  _i       integer;
  _m       date;
  _name    text;
BEGIN
  -- i = 0 garante o MÊS CORRENTE (que hoje não existe).
  FOR _i IN 0.._months_ahead LOOP
    _m    := (date_trunc('month', now()) + make_interval(months => _i))::date;
    _name := 'magazine_public_view_events_' || to_char(_m, 'YYYY_MM');

    IF NOT EXISTS (
      SELECT 1 FROM pg_class
      WHERE relname = _name AND relnamespace = 'public'::regnamespace
    ) THEN
      EXECUTE format(
        'CREATE TABLE public.%I PARTITION OF public.magazine_public_view_events'
        ' FOR VALUES FROM (%L) TO (%L)',
        _name, _m, (_m + interval '1 month')::date
      );

      -- HARDENING CRÍTICO: novas partições herdam o schema mas NÃO herdam RLS/grants.
      -- Habilitar RLS imediatamente — deny-all para acesso direto (PostgREST/GraphQL).
      -- service_role bypassa RLS; INSERT da edge function não é afetado.
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', _name);
      EXECUTE format(
        'REVOKE ALL ON TABLE public.%I FROM anon, authenticated',
        _name
      );

      _created := _created + 1;
    END IF;
  END LOOP;

  RETURN _created;
END;
$function$;

-- Confirmar: nenhum grant perigoso restante nas partições
DO $$
DECLARE
  _bad_count integer;
BEGIN
  SELECT count(*)
  INTO   _bad_count
  FROM   information_schema.role_table_grants g
  WHERE  g.table_schema = 'public'
    AND  g.table_name   LIKE 'magazine_public_view_events_20%'
    AND  g.grantee      IN ('anon', 'authenticated');

  IF _bad_count > 0 THEN
    RAISE EXCEPTION 'REVOKE incompleto: ainda existem % grant(s) anon/authenticated em partições de magazine_public_view_events', _bad_count;
  END IF;

  RAISE NOTICE 'P0-1 OK: todas as partições magazine_public_view_events_20%% estão hardenadas.';
END $$;

-- <<< END 20260716000001_p0_magazine_partition_rls_hardening.sql <<<

-- >>> BEGIN 20260716000002_perf_auth_rls_initplan_fix.sql >>>
-- PERF: fix auth_rls_initplan — substituir auth.uid() bare por (SELECT auth.uid())
-- nas políticas RLS de tabelas de alto tráfego.
--
-- Motivo: auth.uid() sem subquery é um "InitPlan" que o PG reavalia por linha.
-- (SELECT auth.uid()) é um "SubPlan" constante — avaliado 1× por query.
-- Em tabelas com 10k+ rows, a diferença é 10–100× na latência da query.
--
-- Abordagem: DROP POLICY + CREATE POLICY (único caminho para alterar USING/CHECK).
-- Idempotente: DROP IF EXISTS + CREATE OR REPLACE não existe para policies.

-- ─── content_articles ────────────────────────────────────────────────────────
DROP POLICY IF EXISTS content_articles_author_delete ON public.content_articles;
CREATE POLICY content_articles_author_delete ON public.content_articles
  FOR DELETE TO authenticated
  USING (author_id = (SELECT auth.uid()));

DROP POLICY IF EXISTS content_articles_author_insert ON public.content_articles;
CREATE POLICY content_articles_author_insert ON public.content_articles
  FOR INSERT TO authenticated
  WITH CHECK (author_id = (SELECT auth.uid()));

DROP POLICY IF EXISTS content_articles_author_update ON public.content_articles;
CREATE POLICY content_articles_author_update ON public.content_articles
  FOR UPDATE TO authenticated
  USING (author_id = (SELECT auth.uid()))
  WITH CHECK (author_id = (SELECT auth.uid()));

-- ─── crm_callback_events ─────────────────────────────────────────────────────
DROP POLICY IF EXISTS "Admins can view crm callback events" ON public.crm_callback_events;
CREATE POLICY "Admins can view crm callback events" ON public.crm_callback_events
  FOR SELECT TO authenticated
  USING (has_role((SELECT auth.uid()), 'admin'::app_role));

-- ─── discount_approval_audit ─────────────────────────────────────────────────
DROP POLICY IF EXISTS daa_select_scope ON public.discount_approval_audit;
CREATE POLICY daa_select_scope ON public.discount_approval_audit
  FOR SELECT TO authenticated
  USING (
    can_view_all_sales()
    OR has_role((SELECT auth.uid()), 'supervisor'::app_role)
    OR (EXISTS (
      SELECT 1 FROM discount_approval_requests r
      WHERE r.id = discount_approval_audit.request_id
        AND r.seller_id = (SELECT auth.uid())
    ))
  );

-- ─── magazine_public_view_events ──────────────────────────────────────────────
DROP POLICY IF EXISTS view_events_read_admin ON public.magazine_public_view_events;
CREATE POLICY view_events_read_admin ON public.magazine_public_view_events
  FOR SELECT TO authenticated
  USING (has_role((SELECT auth.uid()), 'admin'::app_role));

DROP POLICY IF EXISTS view_events_read_owner ON public.magazine_public_view_events;
CREATE POLICY view_events_read_owner ON public.magazine_public_view_events
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM magazines m
    WHERE m.id = magazine_public_view_events.magazine_id
      AND m.owner_id = (SELECT auth.uid())
  ));

-- ─── magazines ───────────────────────────────────────────────────────────────
DROP POLICY IF EXISTS magazines_admin_all ON public.magazines;
CREATE POLICY magazines_admin_all ON public.magazines
  FOR ALL TO authenticated
  USING (has_role((SELECT auth.uid()), 'admin'::app_role))
  WITH CHECK (has_role((SELECT auth.uid()), 'admin'::app_role));

-- ─── product_badge_definitions ───────────────────────────────────────────────
DROP POLICY IF EXISTS pbd_admin_delete ON public.product_badge_definitions;
CREATE POLICY pbd_admin_delete ON public.product_badge_definitions
  FOR DELETE TO authenticated
  USING (is_admin_or_above((SELECT auth.uid())) AND is_system = false);

DROP POLICY IF EXISTS pbd_admin_insert ON public.product_badge_definitions;
CREATE POLICY pbd_admin_insert ON public.product_badge_definitions
  FOR INSERT TO authenticated
  WITH CHECK (is_admin_or_above((SELECT auth.uid())));

DROP POLICY IF EXISTS pbd_admin_update ON public.product_badge_definitions;
CREATE POLICY pbd_admin_update ON public.product_badge_definitions
  FOR UPDATE TO authenticated
  USING (is_admin_or_above((SELECT auth.uid())))
  WITH CHECK (is_admin_or_above((SELECT auth.uid())));

-- ─── product_views ───────────────────────────────────────────────────────────
DROP POLICY IF EXISTS "Admins can read all views" ON public.product_views;
CREATE POLICY "Admins can read all views" ON public.product_views
  FOR SELECT TO authenticated
  USING (has_role((SELECT auth.uid()), 'admin'::app_role));

DROP POLICY IF EXISTS "Users can read own views" ON public.product_views;
CREATE POLICY "Users can read own views" ON public.product_views
  FOR SELECT TO authenticated
  USING (seller_id = (SELECT auth.uid()));

-- ─── quote_history ───────────────────────────────────────────────────────────
DROP POLICY IF EXISTS "Sellers and coord view quote_history" ON public.quote_history;
CREATE POLICY "Sellers and coord view quote_history" ON public.quote_history
  FOR SELECT TO authenticated
  USING (
    is_coord_or_above((SELECT auth.uid()))
    OR (EXISTS (
      SELECT 1 FROM quotes q
      WHERE q.id = quote_history.quote_id
        AND (
          q.seller_id    = (SELECT auth.uid())
          OR q.created_by = (SELECT auth.uid())
          OR q.assigned_to = (SELECT auth.uid())
        )
    ))
  );

DROP POLICY IF EXISTS "Sellers and coord create quote_history" ON public.quote_history;
CREATE POLICY "Sellers and coord create quote_history" ON public.quote_history
  FOR INSERT TO authenticated
  WITH CHECK (
    user_id = (SELECT auth.uid())
    AND (
      is_coord_or_above((SELECT auth.uid()))
      OR (EXISTS (
        SELECT 1 FROM quotes q
        WHERE q.id = quote_history.quote_id
          AND (
            q.seller_id    = (SELECT auth.uid())
            OR q.created_by = (SELECT auth.uid())
            OR q.assigned_to = (SELECT auth.uid())
          )
      ))
    )
  );

-- <<< END 20260716000002_perf_auth_rls_initplan_fix.sql <<<

