-- EXEC-8: Dedup indexes, missing FK indexes, policy consolidation & hardening
--
-- (A) Drop 4 exact duplicate indexes on kit_component tables (same column, no WHERE diff)
-- (B) Create 2 missing FK indexes on magazine_templates + magazines
-- (C) Remove superseded SELECT policy on product_views (was covered by two specific ones)
-- (D) Harden 3 USING(true) ALL policies for `authenticated` on QA/reference tables

-- ─── (A) Drop exact duplicate indexes ────────────────────────────────────────
-- Long-name auto-generated duplicates of the short idx_kcer_* / idx_kcpad_* aliases.
DROP INDEX IF EXISTS public.idx_kit_component_enrichment_raw_kit_product_id;
DROP INDEX IF EXISTS public.idx_kit_component_enrichment_raw_kit_component_id;
DROP INDEX IF EXISTS public.idx_kit_component_padronizacao_kit_product_id;
DROP INDEX IF EXISTS public.idx_kit_component_padronizacao_kit_component_id;

-- ─── (B) Missing FK indexes ───────────────────────────────────────────────────
-- FK joins on template_id were doing sequential scans on parent tables.
CREATE INDEX IF NOT EXISTS idx_magazine_templates_template_id
  ON public.magazine_templates (template_id);

CREATE INDEX IF NOT EXISTS idx_magazines_template_id
  ON public.magazines (template_id);

-- ─── (C) Consolidate product_views SELECT policies ───────────────────────────
-- "Users can view own views" (is_admin OR seller_id) is superseded by the two
-- explicit policies created in migration 000002 (admin via has_role, own via seller_id).
-- Keeping three permissive SELECT policies forces PG to evaluate all three per row.
DROP POLICY IF EXISTS "Users can view own views" ON public.product_views;

-- ─── (D) Fix USING(true)/WITH CHECK(true) ALL for authenticated role ──────────
-- These granted any authenticated user full DML on reference/QA tables.
-- Pattern: split into SELECT-for-all + ALL-for-admin.

-- color_synonym_map ───────────────────────────────────────────────────────────
DROP POLICY IF EXISTS rls_authenticated_all_color_synonym_map ON public.color_synonym_map;
-- Read: same as anon (already has rls_anon_read_color_synonym_map)
CREATE POLICY csm_read_authenticated ON public.color_synonym_map
  FOR SELECT TO authenticated
  USING (true);
-- Write: admin only
CREATE POLICY csm_write_admin ON public.color_synonym_map
  FOR ALL TO authenticated
  USING (is_admin_or_above((SELECT auth.uid())))
  WITH CHECK (is_admin_or_above((SELECT auth.uid())));

-- product_qa_image_alerts ─────────────────────────────────────────────────────
DROP POLICY IF EXISTS rls_authenticated_all_qa_alerts ON public.product_qa_image_alerts;
CREATE POLICY qa_alerts_read_authenticated ON public.product_qa_image_alerts
  FOR SELECT TO authenticated
  USING (true);
CREATE POLICY qa_alerts_write_admin ON public.product_qa_image_alerts
  FOR ALL TO authenticated
  USING (is_admin_or_above((SELECT auth.uid())))
  WITH CHECK (is_admin_or_above((SELECT auth.uid())));

-- qa_image_coverage_log ───────────────────────────────────────────────────────
DROP POLICY IF EXISTS rls_authenticated_all_qa_coverage_log ON public.qa_image_coverage_log;
CREATE POLICY qa_coverage_read_authenticated ON public.qa_image_coverage_log
  FOR SELECT TO authenticated
  USING (true);
CREATE POLICY qa_coverage_write_admin ON public.qa_image_coverage_log
  FOR ALL TO authenticated
  USING (is_admin_or_above((SELECT auth.uid())))
  WITH CHECK (is_admin_or_above((SELECT auth.uid())));

-- <<< END 20260716000003_perf_sec_dedup_indexes_policy_hardening.sql <<<

-- >>> BEGIN 20260716000004_sec_revoke_archive_backup_schemas.sql >>>
-- SEC: Revoke public access to archive.* and backup.* schemas
--
-- These schemas contain historical backups and deprecated tables.
-- They were accidentally granted to anon/authenticated via the default
-- public role USAGE, exposing internal business data (audit_log,
-- auth_login_attempts, staging data, deprecated pipelines, etc.).
--
-- After this migration, only postgres + service_role (and superusers)
-- can access these schemas. Edge functions using service_role are unaffected.
--
-- Idempotent: REVOKE is a no-op when the privilege doesn't exist.

-- ─── archive schema ───────────────────────────────────────────────────────────
REVOKE USAGE ON SCHEMA archive FROM anon, authenticated;
REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA archive FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA archive REVOKE ALL ON TABLES FROM anon, authenticated;

-- ─── backup schema ────────────────────────────────────────────────────────────
REVOKE USAGE ON SCHEMA backup FROM anon, authenticated;
REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA backup FROM anon, authenticated;
ALTER DEFAULT PRIVILEGES IN SCHEMA backup REVOKE ALL ON TABLES FROM anon, authenticated;

-- Validation: confirm no more dangerous grants exist
DO $$
DECLARE
  v_count integer;
BEGIN
  SELECT count(*) INTO v_count
  FROM information_schema.role_table_grants
  WHERE table_schema IN ('archive', 'backup')
    AND grantee IN ('anon', 'authenticated');

  IF v_count > 0 THEN
    RAISE EXCEPTION
      'archive/backup schema hardening FAILED — % grants remain for anon/authenticated', v_count;
  END IF;
END;
$$;

-- <<< END 20260716000004_sec_revoke_archive_backup_schemas.sql <<<

-- >>> BEGIN 20260716000005_sec_revoke_secdef_functions.sql >>>
-- SEC P1-2: Revoke overly-broad EXECUTE on SECURITY DEFINER functions
--
-- Problem: ~200 internal pipeline/credential functions are callable by anon
-- and/or authenticated via PostgREST RPC. Critical examples:
--   fn_get_asia_api_key, fn_get_cf_api_token, fn_get_vault_secret,
--   fn_get_sm_session_cookie, fn_get_spot_access_key, get_edge_anon_key
--   fn_pgrst_reload, fn_cascade_product_deactivation, fn_revoke_*,
--   fn_auto_revoke_secdef_public_execute, fn_vacuum_high_dead_tuples
--
-- Strategy:
--   (A) Revoke ALL secdef functions from anon, keeping only the tiny set
--       needed for unauthenticated flows (login rate-limit, quote sharing).
--
--   (B) Revoke credential-leaking + destructive-admin functions from
--       authenticated (preserving admin/seller UI functions).
--
-- NOTE: RLS helper functions (is_admin_or_above, has_role, etc.) are kept
--       for anon/authenticated because PG requires EXECUTE on functions used
--       in RLS USING clauses by the querying role. Revoking them breaks RLS.

-- ─── (A) Revoke pipeline/internal functions from anon ────────────────────────
DO $$
DECLARE
  r record;
  -- Whitelist: anon legitimately calls these RPCs (login flows, public catalog)
  keep_for_anon text[] := ARRAY[
    -- Login/auth flows
    'check_login_rate_limit',
    'fn_check_login_allowed',
    'enforce_password_reset_rate_limit',
    -- Quote sharing (public/anon)
    'get_quote_token_by_value',
    'submit_quote_response',
    -- Public catalog (storefront, no auth required)
    'get_catalog_bestseller_page',
    'get_top_collected_products',
    'get_promo_sales_ranking',
    'get_collections_weekly_count',
    'fn_super_filtro',
    'fn_super_filtro_facets',
    'fn_super_filtro_opcoes',
    'fn_super_filtro_price_range',
    'fn_super_filtro_product_ids',
    'fn_get_category_breadcrumb',
    'fn_get_all_leaf_categories',
    'fn_global_search',
    'fn_get_similar_products',
    'fn_get_color_swatches_batch',
    'fn_get_product_customization_options',
    'fn_get_customization_price',
    'fn_log_search_analytics',
    'fn_get_product_intelligence_all',
    -- RLS helper functions (PG requires EXECUTE for roles used in USING clauses)
    'has_role',
    'is_admin',
    'is_admin_or_above',
    'is_coord_or_above',
    'can_view_all_sales',
    'can_manage_org',
    'can_access_quote',
    'is_org_member',
    'is_org_owner_or_admin',
    'user_is_org_member',
    'org_has_any_members',
    'get_organization_id_for_user',
    'get_user_organization_id',
    -- MCP session
    'mcp_kv_get'
  ];
BEGIN
  FOR r IN
    SELECT DISTINCT p.proname, pg_get_function_identity_arguments(p.oid) AS args, p.oid
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prosecdef = true
      AND NOT (p.proname = ANY(keep_for_anon))
      AND has_function_privilege('anon', p.oid, 'EXECUTE')
  LOOP
    BEGIN
      EXECUTE format('REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM anon',
                     r.proname, r.args);
    EXCEPTION WHEN others THEN
      -- Log but don't abort — some functions may already lack grant
      RAISE WARNING 'Could not revoke anon EXECUTE on %.%(%): %',
        'public', r.proname, r.args, SQLERRM;
    END;
  END LOOP;
END;
$$;

-- ─── (B) Revoke credential-leaking + destructive functions from authenticated ─
-- These functions expose API secrets, modify DB grants/permissions, or run
-- destructive bulk operations that must only run via service_role (cron/edge).
DO $$
DECLARE
  r record;
  revoke_from_auth text[] := ARRAY[
    -- Credential exposure (CRITICAL)
    'fn_get_asia_api_key',
    'fn_get_asia_secret_key',
    'fn_get_cf_api_token',
    'fn_get_cf_credentials',
    'fn_get_cf_account_id',
    'fn_get_sm_session_cookie',
    'fn_get_spot_access_key',
    'get_edge_anon_key',
    'get_vault_secret',
    -- Grant/permission manipulation
    'fn_audit_and_fix_grants',
    'fn_auto_revoke_secdef_public_execute',
    'fn_revoke_truncate_public',
    'fn_revoke_view_write_grants_on_create',
    'fn_grant_default_role_on_profile',
    'execute_role_migration_batch',
    -- Destructive pipeline-only operations
    'fn_pgrst_reload',
    'fn_vacuum_high_dead_tuples',
    'fn_cascade_deactivate_vss',
    'fn_cascade_product_deactivation',
    'fn_admin_sync_external_connections',
    'fn_capture_schema_baseline',
    'fn_run_schema_drift_check',
    'fn_compute_and_record_drift',
    'fn_check_schema_signature_drift',
    'fn_capture_connection_snapshot',
    'fn_bulk_request_deactivation',
    'fn_cleanup_log_tables',
    'fn_cleanup_webhook_dispatcher_log',
    'fn_purge_spr_history',
    'fn_purge_old_stock_snapshots',
    'fn_purge_expired_restock_dates',
    'fn_site_promote_to_gold',
    'fn_asia_site_promote_to_gold'
  ];
BEGIN
  FOR r IN
    SELECT DISTINCT p.proname, pg_get_function_identity_arguments(p.oid) AS args, p.oid
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prosecdef = true
      AND p.proname = ANY(revoke_from_auth)
      AND has_function_privilege('authenticated', p.oid, 'EXECUTE')
  LOOP
    BEGIN
      EXECUTE format('REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM authenticated',
                     r.proname, r.args);
    EXCEPTION WHEN others THEN
      RAISE WARNING 'Could not revoke authenticated EXECUTE on %.%(%): %',
        'public', r.proname, r.args, SQLERRM;
    END;
  END LOOP;
END;
$$;

-- <<< END 20260716000005_sec_revoke_secdef_functions.sql <<<

