-- >>> BEGIN 20260716000024_revoke_anon_internal_mvs.sql >>>
-- Migration: Revoke anon SELECT from internal materialized views
--
-- Problem (Supabase advisor: materialized_view_in_api):
--   4 materialized views are accessible to the `anon` role via the PostgREST
--   Data API. Three of these contain sensitive operational / BI data that
--   anonymous users have no business reading:
--
--     mv_stock_rupture_alert   — stock rupture alerts (EMA-based, operational)
--     mv_ema_kpi_by_level      — EMA KPI metrics by stock level (BI/internal)
--     mv_supplier_reliability  — supplier delivery reliability KPIs (BI/internal)
--
--   These views are used exclusively by authenticated admin users through
--   React hooks (useRuptureAlerts, useSupplierReliabilityServer). Anon access
--   is purely accidental and was never intended.
--
--   mv_product_leaf_category is intentionally kept anon-accessible because
--   v_products_public (public catalog, security_invoker=on) references it and
--   anon must be able to resolve the JOIN.
--
-- Fix:
--   REVOKE anon SELECT from the 3 sensitive MVs.
--   Verify that authenticated still has SELECT (dashboard must keep working).
--
-- Safety:
--   - All 3 MVs are read only by authenticated-role code (supabase client with JWT)
--   - PostgREST enforces the role grants; no app code passes anon to these MVs
--   - Materialized views don't support RLS natively — REVOKE is the correct fix
--   - PostgreSQL 17 (Supabase PG17): REVOKE is idempotent when combined with
--     IF EXISTS semantics in DO block validation below

-- ─── 1. mv_stock_rupture_alert ────────────────────────────────────────────────
REVOKE SELECT ON public.mv_stock_rupture_alert FROM anon;
-- Keep authenticated access (admin stock dashboard)
GRANT SELECT ON public.mv_stock_rupture_alert TO authenticated;

-- ─── 2. mv_ema_kpi_by_level ──────────────────────────────────────────────────
REVOKE SELECT ON public.mv_ema_kpi_by_level FROM anon;
GRANT SELECT ON public.mv_ema_kpi_by_level TO authenticated;

-- ─── 3. mv_supplier_reliability ──────────────────────────────────────────────
REVOKE SELECT ON public.mv_supplier_reliability FROM anon;
-- Keep authenticated access (useSupplierReliabilityServer)
GRANT SELECT ON public.mv_supplier_reliability TO authenticated;

-- ─── Validate ─────────────────────────────────────────────────────────────────
DO $$
DECLARE
  mv_name text;
  has_anon_select boolean;
BEGIN
  FOREACH mv_name IN ARRAY ARRAY[
    'mv_stock_rupture_alert',
    'mv_ema_kpi_by_level',
    'mv_supplier_reliability'
  ] LOOP
    SELECT EXISTS (
      SELECT 1
      FROM information_schema.role_table_grants
      WHERE table_schema = 'public'
        AND table_name = mv_name
        AND privilege_type = 'SELECT'
        AND grantee = 'anon'
    ) INTO has_anon_select;

    IF has_anon_select THEN
      RAISE EXCEPTION 'REVOKE FAILED: anon still has SELECT on public.%', mv_name;
    END IF;
    RAISE NOTICE '✓ anon SELECT revoked from public.%', mv_name;
  END LOOP;

  RAISE NOTICE 'mv_stock_rupture_alert, mv_ema_kpi_by_level, mv_supplier_reliability — anon revoked OK';
  RAISE NOTICE 'mv_product_leaf_category intentionally kept anon-accessible (public catalog JOIN)';
END;
$$;

-- <<< END 20260716000024_revoke_anon_internal_mvs.sql <<<

-- >>> BEGIN 20260716000025_revoke_anon_backup_tables_analytics_schema.sql >>>
-- Migration: Revoke anon access from backup tables and analytics schema
--
-- Problem (Supabase advisor: pg_graphql_anon_table_exposed):
--   Two categories of objects are wrongly accessible to the anon role:
--
--   A) Backup / archive / QA tables in the public schema
--      These are point-in-time snapshots created during migrations for safety.
--      They contain historical data and should never be publicly accessible.
--      They are NOT used by any app code (confirmed: grep src/ -r finds 0 references).
--
--      public._archive_product_ai_20260626
--      public._archive_product_seo_20260626
--      public._archive_supplier_price_tiers_20260626
--      public._bkp_kcvs_pre_normalize_20260624
--      public._bkp_kit_color_from_name_20260624
--      public._bkp_kit_packing_type_20260624
--      public._bkp_kit_pkg_material_20260624
--      public._qa_pct_results
--      public.backup_produto_ramo_atividade_20260625
--
--   B) analytics schema (4 materialized views)
--      analytics.categories_tree_visual
--      analytics.mv_product_cards
--      analytics.mv_product_compositions
--      analytics.mv_product_intelligence
--
--      The analytics schema provides reporting mirrors of public catalog MVs.
--      App code (src/) never directly queries the analytics schema — all access
--      goes through public schema views/RPCs. Revoking anon USAGE on the schema
--      removes all GraphQL and PostgREST exposure at once.
--
-- Fix:
--   (A) REVOKE SELECT FROM anon on each backup/archive/qa table (IF EXISTS guards)
--   (B) REVOKE USAGE ON SCHEMA analytics FROM anon (removes schema-level access)
--
-- Safety:
--   - All backup tables are snapshot-only; no foreign keys reference them
--   - analytics schema is not in PostgREST search_path config (public only)
--   - authenticated users retain their existing access to the analytics schema

-- ─── Part A: Backup / archive / QA tables ────────────────────────────────────
DO $$
DECLARE
  tbl text;
  backup_tables text[] := ARRAY[
    '_archive_product_ai_20260626',
    '_archive_product_seo_20260626',
    '_archive_supplier_price_tiers_20260626',
    '_bkp_kcvs_pre_normalize_20260624',
    '_bkp_kit_color_from_name_20260624',
    '_bkp_kit_packing_type_20260624',
    '_bkp_kit_pkg_material_20260624',
    '_qa_pct_results',
    'backup_produto_ramo_atividade_20260625'
  ];
BEGIN
  FOREACH tbl IN ARRAY backup_tables LOOP
    IF EXISTS (
      SELECT 1 FROM pg_tables
      WHERE schemaname = 'public' AND tablename = tbl
    ) THEN
      EXECUTE format('REVOKE ALL ON public.%I FROM anon', tbl);
      EXECUTE format('REVOKE ALL ON public.%I FROM authenticated', tbl);
      RAISE NOTICE '✓ REVOKE ALL on public.% (anon + authenticated)', tbl;
    ELSE
      RAISE NOTICE '⚠ table public.% not found — skipping', tbl;
    END IF;
  END LOOP;
END;
$$;

-- ─── Part B: analytics schema — revoke anon schema-level access ───────────────
-- REVOKE USAGE prevents anon from resolving any object in the analytics schema
-- via PostgREST, GraphQL, or direct SQL query (they get "permission denied for schema").
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.schemata
    WHERE schema_name = 'analytics'
  ) THEN
    REVOKE USAGE ON SCHEMA analytics FROM anon;
    RAISE NOTICE '✓ REVOKE USAGE ON SCHEMA analytics FROM anon';
  ELSE
    RAISE NOTICE '⚠ schema analytics not found — skipping';
  END IF;
END;
$$;

-- ─── Validate ─────────────────────────────────────────────────────────────────
DO $$
DECLARE
  has_anon_usage boolean;
BEGIN
  -- Check analytics schema USAGE
  SELECT EXISTS (
    SELECT 1 FROM information_schema.role_usage_grants
    WHERE object_schema = 'analytics'
      AND object_name = 'analytics'
      AND grantee = 'anon'
      AND privilege_type = 'USAGE'
  ) INTO has_anon_usage;

  IF has_anon_usage THEN
    RAISE WARNING 'anon still has USAGE on analytics schema — check if schema exists';
  ELSE
    RAISE NOTICE '✓ anon no longer has USAGE on analytics schema (or schema absent)';
  END IF;
END;
$$;

-- <<< END 20260716000025_revoke_anon_backup_tables_analytics_schema.sql <<<

-- >>> BEGIN 20260716000026_revoke_supplier_stricker_schema.sql >>>
-- Migration: Revoke access to supplier_stricker staging schema
--
-- Problem (Supabase advisor: pg_graphql_authenticated_table_exposed):
--   The `supplier_stricker` schema contains ~51 staging/import tables that are
--   visible to the `authenticated` role via GraphQL and PostgREST.
--
--   These tables are:
--     - Stricker supplier staging/import data (not business logic)
--     - NOT referenced by any app src/ code (confirmed: grep src/ -r finds 0 references)
--     - Referenced only in FK index migrations for relational integrity
--
--   Exposing a staging schema to authenticated users via the API is a security
--   smell: it leaks internal data pipeline structure and supplier raw data.
--
-- Fix:
--   REVOKE USAGE ON SCHEMA supplier_stricker FROM anon, authenticated
--
--   This removes ALL GraphQL and PostgREST exposure of the schema at once.
--   service_role retains full access (bypasses RLS and schema grants).
--
-- Safety:
--   - App code (src/) has zero references to `supplier_stricker` schema
--   - No Edge Functions query this schema (functions use `public` schema only)
--   - FK indexes referencing this schema were created by migrations only — not runtime
--   - authenticated users will get "permission denied for schema" via PostgREST/GraphQL
--   - Verified: schema exists as a staging pipeline for Stricker supplier data import

-- ─── Revoke anon and authenticated from supplier_stricker schema ──────────────
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.schemata
    WHERE schema_name = 'supplier_stricker'
  ) THEN
    REVOKE USAGE ON SCHEMA supplier_stricker FROM anon;
    REVOKE USAGE ON SCHEMA supplier_stricker FROM authenticated;
    RAISE NOTICE '✓ REVOKE USAGE ON SCHEMA supplier_stricker FROM anon, authenticated';
  ELSE
    RAISE NOTICE '⚠ schema supplier_stricker not found — skipping';
  END IF;
END;
$$;

-- ─── Validate ─────────────────────────────────────────────────────────────────
DO $$
DECLARE
  has_anon_usage     boolean;
  has_auth_usage     boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM information_schema.role_usage_grants
    WHERE object_schema = 'supplier_stricker'
      AND object_name   = 'supplier_stricker'
      AND grantee       = 'anon'
      AND privilege_type = 'USAGE'
  ) INTO has_anon_usage;

  SELECT EXISTS (
    SELECT 1 FROM information_schema.role_usage_grants
    WHERE object_schema = 'supplier_stricker'
      AND object_name   = 'supplier_stricker'
      AND grantee       = 'authenticated'
      AND privilege_type = 'USAGE'
  ) INTO has_auth_usage;

  IF has_anon_usage THEN
    RAISE WARNING 'anon still has USAGE on supplier_stricker — check if schema exists';
  ELSE
    RAISE NOTICE '✓ anon: no USAGE on supplier_stricker (or schema absent)';
  END IF;

  IF has_auth_usage THEN
    RAISE WARNING 'authenticated still has USAGE on supplier_stricker — check if schema exists';
  ELSE
    RAISE NOTICE '✓ authenticated: no USAGE on supplier_stricker (or schema absent)';
  END IF;
END;
$$;

-- <<< END 20260716000026_revoke_supplier_stricker_schema.sql <<<

-- >>> BEGIN 20260716000027_revoke_anon_internal_tables_views.sql >>>
-- Migration: Revoke anon SELECT from internal tables and admin-only views
--
-- Problem (Supabase advisor: pg_graphql_anon_table_exposed):
--   Multiple tables and views in the public schema are accessible to the
--   `anon` role via GraphQL and PostgREST, but have zero legitimate anon use.
--
--   Categories revoked:
--
--   A) Dated log tables (backfill / reconcile / audit):
--      eco_backfill_log_20260625, eco_date_reconcile_log_20260626,
--      material_reconcile_log_20260626, cnpj_backfill_audit
--
--   B) Queue / job tables (system pipeline, admin-only):
--      asia_image_import_queue, mockup_generation_jobs, optimization_queue_runs
--
--   C) Ingestion / staging / raw history tables:
--      ingestion_run_log, kit_component_enrichment_raw, kit_component_ficha_staging,
--      kit_ficha_session_log, supplier_import_batches,
--      supplier_products_raw_history_p2026_06 through _10,
--      supplier_customization_options_raw
--
--   D) Pipeline / health / QA logs:
--      pipeline_health_log, pipeline_run_log, qa_image_coverage_log,
--      schema_signature_drift_log, spot_health_log, ops_grant_audit
--
--   E) Config tables (admin UI only):
--      category_copywriting_config, eco_material_config, feminine_color_config,
--      packaging_compatibility_config, mockup_prompt_configs
--
--   F) Admin / system tables:
--      markup_configurations, system_changelog, system_documentation,
--      dashboard_insights_cache, conversation_delivery_status,
--      role_migration_batches, role_migration_items
--
--   G) Admin-only monitoring views:
--      v_audit_paradoxos_gravacao, v_blurhash_coverage, v_blurhash_summary,
--      v_color_coverage_monitor, v_connection_health, v_crm_callback_health,
--      v_db_health_check, v_dimensions_source_divergence, v_enrichment_stats,
--      v_gravacao_cobertura, v_image_quality_stats, v_kit_completeness_by_supplier,
--      v_kit_component_completeness, v_kit_component_identity_health,
--      v_kit_enrichment_dashboard, v_kit_ficha_pipeline_health,
--      v_kit_pipeline_health, v_media_statistics
--
-- Objects intentionally kept anon-accessible (public catalog):
--   system_kill_switches   — anon reads for frontend feature flags (kill-switch-client.ts)
--   catalog_analytics      — anon inserts sort events; SELECT not needed (revoked here)
--   mv_product_cards       — public product cards (rest-native.ts external-db layer)
--   mv_product_intelligence — public product badges (useProductIntelligenceBadges.ts)
--   mv_stock_velocity      — public stock display (stockFetcher.ts)
--   v_catalog_stats        — public catalog stats (useCatalogRealStats.ts)
--   v_media_stats          — public product media counts (rest-native.ts)
--
-- Safety:
--   - All 55+ objects confirmed absent from src/ anon-accessible code paths
--   - Config/admin tables used only via authenticated admin components
--   - Monitoring views are internal dashboards (admin-only)
--   - History partition tables never queried by app code
--   - authenticated role retains SELECT on all tables used by admin flows
--   - IF EXISTS guards on each REVOKE make migration idempotent

DO $$
DECLARE
  obj text;

  -- Group A: Dated log / backfill / audit tables
  log_tables text[] := ARRAY[
    'eco_backfill_log_20260625',
    'eco_date_reconcile_log_20260626',
    'material_reconcile_log_20260626',
    'cnpj_backfill_audit'
  ];

  -- Group B: Queue / job tables
  queue_tables text[] := ARRAY[
    'asia_image_import_queue',
    'mockup_generation_jobs',
    'optimization_queue_runs'
  ];

  -- Group C: Ingestion / staging / raw history
  staging_tables text[] := ARRAY[
    'ingestion_run_log',
    'kit_component_enrichment_raw',
    'kit_component_ficha_staging',
    'kit_ficha_session_log',
    'supplier_import_batches',
    'supplier_products_raw_history_p2026_06',
    'supplier_products_raw_history_p2026_07',
    'supplier_products_raw_history_p2026_08',
    'supplier_products_raw_history_p2026_09',
    'supplier_products_raw_history_p2026_10',
    'supplier_customization_options_raw'
  ];

  -- Group D: Pipeline / health / QA logs
  pipeline_tables text[] := ARRAY[
    'pipeline_health_log',
    'pipeline_run_log',
    'qa_image_coverage_log',
    'schema_signature_drift_log',
    'spot_health_log',
    'ops_grant_audit'
  ];

  -- Group E: Config tables (admin UI only)
  config_tables text[] := ARRAY[
    'category_copywriting_config',
    'eco_material_config',
    'feminine_color_config',
    'packaging_compatibility_config',
    'mockup_prompt_configs'
  ];

  -- Group F: Admin / system tables
  admin_tables text[] := ARRAY[
    'markup_configurations',
    'system_changelog',
    'system_documentation',
    'dashboard_insights_cache',
    'conversation_delivery_status',
    'role_migration_batches',
    'role_migration_items'
  ];

  -- Group G: Admin-only monitoring views
  monitoring_views text[] := ARRAY[
    'v_audit_paradoxos_gravacao',
    'v_blurhash_coverage',
    'v_blurhash_summary',
    'v_color_coverage_monitor',
    'v_connection_health',
    'v_crm_callback_health',
    'v_db_health_check',
    'v_dimensions_source_divergence',
    'v_enrichment_stats',
    'v_gravacao_cobertura',
    'v_image_quality_stats',
    'v_kit_completeness_by_supplier',
    'v_kit_component_completeness',
    'v_kit_component_identity_health',
    'v_kit_enrichment_dashboard',
    'v_kit_ficha_pipeline_health',
    'v_kit_pipeline_health',
    'v_media_statistics'
  ];

BEGIN
  -- Process all groups: REVOKE SELECT FROM anon (IF EXISTS guard via pg_class)
  FOREACH obj IN ARRAY (
    log_tables || queue_tables || staging_tables ||
    pipeline_tables || config_tables || admin_tables ||
    monitoring_views
  ) LOOP
    IF EXISTS (
      SELECT 1 FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relname = obj
        AND c.relkind IN ('r', 'v', 'm', 'p')  -- table, view, matview, partitioned
    ) THEN
      EXECUTE format('REVOKE SELECT ON public.%I FROM anon', obj);
