-- >>> BEGIN 20260716000038_fix_remaining_initplan_and_fk_index.sql >>>
-- Migration 038: Fix remaining auth_rls_initplan + unindexed FK on collection_products
--
-- Source: 200-commit audit + performance advisor follow-up (post-037 score check)
-- Findings addressed: 2
--   1) auth_rls_initplan (1 finding) — smoke_insert_service_role on smoke_test_runs
--   2) unindexed_foreign_keys (1 finding) — collection_products_product_id_fkey1
--
-- ─── Finding 1: auth_rls_initplan ────────────────────────────────────────────
--
-- Migration 033 already wrapped current_setting() and is_admin_or_above() in
-- (SELECT ...) subqueries, but left auth.uid() unwrapped *inside* the function:
--
--   ( SELECT is_admin_or_above(auth.uid()) )   ← auth.uid() re-evaluated per row
--
-- The advisor still flags this because auth.uid() inside the function argument is
-- not hoisted as its own InitPlan. The correct pattern is:
--
--   ( SELECT is_admin_or_above((SELECT auth.uid())) )
--
-- With this pattern, (SELECT auth.uid()) becomes a scalar InitPlan (evaluated once
-- per statement), and its result is passed to is_admin_or_above(), which is itself
-- hoisted as an InitPlan via the outer (SELECT ...).
--
-- ─── Finding 2: unindexed_foreign_keys ───────────────────────────────────────
--
-- collection_products.product_id (FK: collection_products_product_id_fkey1)
-- lacks a covering index. Migration 037 attempted to create
-- idx_collection_products_product_id but that name was already taken by
-- b2b_collection_products in the same schema (PostgreSQL index names are
-- schema-unique). The IF NOT EXISTS silently skipped creation.
-- Fix: use name idx_col_prods_product_id (distinct, within 63-char limit).

-- ═══════════════════════════════════════════════════════════════════════════════
-- 1) Fix auth_rls_initplan: smoke_insert_service_role
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = 'smoke_test_runs'
      AND c.relkind IN ('r', 'p')
  ) THEN
    DROP POLICY IF EXISTS smoke_insert_service_role ON public.smoke_test_runs;

    CREATE POLICY smoke_insert_service_role ON public.smoke_test_runs
      FOR INSERT TO authenticated
      WITH CHECK (
        (SELECT current_setting('request.jwt.claim.role', true)) = 'service_role'
        OR (SELECT is_admin_or_above((SELECT auth.uid())))
      );

    RAISE NOTICE '✓ [auth_rls_initplan] smoke_insert_service_role: auth.uid() now wrapped in its own InitPlan subquery';
  ELSE
    RAISE NOTICE '- public.smoke_test_runs not found — skipping';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 2) Fix unindexed FK: collection_products.product_id
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = 'collection_products'
      AND c.relkind IN ('r', 'p')
  ) THEN
    -- Name 'idx_collection_products_product_id' already taken by b2b_collection_products
    -- in the public schema. Using distinct abbreviated name.
    CREATE INDEX IF NOT EXISTS idx_col_prods_product_id
      ON public.collection_products (product_id);

    RAISE NOTICE '✓ [unindexed_foreign_keys] idx_col_prods_product_id created on collection_products(product_id)';
  ELSE
    RAISE NOTICE '- public.collection_products not found — skipping';
  END IF;
END;
$$;

-- ─── Validation ───────────────────────────────────────────────────────────────
DO $$
DECLARE
  wc_expr      text;
  idx_exists   boolean;
BEGIN
  -- 1) Verify policy WITH CHECK expression
  SELECT pg_get_expr(polwithcheck, polrelid)
  INTO wc_expr
  FROM pg_policy
  WHERE polname = 'smoke_insert_service_role'
    AND polrelid = 'public.smoke_test_runs'::regclass;

  IF wc_expr IS NULL THEN
    RAISE WARNING 'Policy smoke_insert_service_role not found on smoke_test_runs';
  ELSIF wc_expr NOT LIKE '%(SELECT auth.uid())%' THEN
    RAISE WARNING 'Policy smoke_insert_service_role may still have un-wrapped auth.uid(): %', wc_expr;
  ELSE
    RAISE NOTICE '✓ smoke_insert_service_role WITH CHECK: %', wc_expr;
  END IF;

  -- 2) Verify FK covering index
  SELECT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE schemaname = 'public'
      AND tablename  = 'collection_products'
      AND indexname  = 'idx_col_prods_product_id'
  ) INTO idx_exists;

  IF idx_exists THEN
    RAISE NOTICE '✓ idx_col_prods_product_id confirmed on collection_products';
  ELSE
    RAISE WARNING 'idx_col_prods_product_id NOT FOUND on collection_products';
  END IF;

  RAISE NOTICE 'Migration 038 complete — auth_rls_initplan + unindexed_foreign_keys should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000038_fix_remaining_initplan_and_fk_index.sql <<<

-- >>> BEGIN 20260716000039_fix_security_anon_mcp_kv_and_bucket_listing.sql >>>
-- Migration 039: Fix security — revoke anon from mcp_kv_get + fix bucket listing
--
-- Source: 200-commit audit + security advisor findings
-- Findings addressed: 2
--   1) anon_security_definer_function_executable — public.mcp_kv_get
--   2) public_bucket_allows_listing — mockup-assets bucket
--
-- ─── Finding 1: mcp_kv_get callable by anon ──────────────────────────────────
--
-- public.mcp_kv_get(p_secret text, p_key text) is a SECURITY DEFINER function
-- that reads from public.mcp_kv. It has a hardcoded secret check inside:
--   IF p_secret <> '9f2c7a1e...' THEN RAISE EXCEPTION 'forbidden'; END IF;
-- The check is functional but the anon role has EXECUTE, so any anonymous
-- client can attempt brute-force or timing attacks on the secret. The function
-- is backend-only (no public catalog use case), so anon EXECUTE is unnecessary.
--
-- Fix: REVOKE EXECUTE FROM anon. Authenticated callers retain access.
--
-- ─── Finding 2: mockup-assets bucket allows listing ──────────────────────────
--
-- Policy "Authenticated users can view mockup assets" has USING clause:
--   (bucket_id = 'mockup-assets'::text)
-- Without a constraint on `name`, this allows authenticated users to LIST
-- (enumerate) all objects in the bucket — a common data-leakage vector when
-- mockup file names encode user IDs, job IDs, or sensitive slugs.
--
-- All other "direct read" policies in this database require:
--   (name IS NOT NULL) AND (length(name) > 0)
-- This pattern (used by component-media, personalization-images, product-videos,
-- supplier-logos) prevents listing while still allowing direct access by name.
--
-- Fix: Replace the broad policy with a name-constrained equivalent.
-- Safety: Other bucket operations (DELETE, UPDATE, INSERT) on mockup-assets
-- already use (storage.foldername(name))[1] = auth.uid() — unaffected.

-- ═══════════════════════════════════════════════════════════════════════════════
-- 1) Revoke anon execute on mcp_kv_get
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'mcp_kv_get'
  ) THEN
    REVOKE EXECUTE ON FUNCTION public.mcp_kv_get(text, text) FROM anon;
    RAISE NOTICE '✓ [anon_security_definer_function_executable] REVOKE EXECUTE ON mcp_kv_get FROM anon';
  ELSE
    RAISE NOTICE '- public.mcp_kv_get not found — skipping';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 2) Fix mockup-assets bucket SELECT policy to prevent listing
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  -- Drop the broad listing-permissive policy
  DROP POLICY IF EXISTS "Authenticated users can view mockup assets" ON storage.objects;

  -- Recreate with name constraint (prevents listing, allows direct-by-name access)
  -- Matches the pattern used by all other protected-bucket read policies in this DB
  CREATE POLICY "Authenticated users can view mockup assets"
    ON storage.objects
    FOR SELECT TO authenticated
    USING (
      (bucket_id = 'mockup-assets'::text)
      AND (name IS NOT NULL)
      AND (length(name) > 0)
    );

  RAISE NOTICE '✓ [public_bucket_allows_listing] mockup-assets SELECT policy updated — listing prevention applied';
END;
$$;

-- ─── Validation ───────────────────────────────────────────────────────────────
DO $$
DECLARE
  anon_can_exec boolean;
  policy_qual   text;
BEGIN
  -- 1) Verify mcp_kv_get is no longer executable by anon
  SELECT has_function_privilege('anon', 'public.mcp_kv_get(text, text)', 'EXECUTE')
  INTO anon_can_exec;

  IF anon_can_exec THEN
    RAISE WARNING 'anon still has EXECUTE on mcp_kv_get — revoke may have failed';
  ELSE
    RAISE NOTICE '✓ anon no longer has EXECUTE on mcp_kv_get';
  END IF;

  -- 2) Verify new policy USING clause contains name constraint
  SELECT qual
  INTO policy_qual
  FROM pg_policies
  WHERE schemaname = 'storage'
    AND tablename  = 'objects'
    AND policyname = 'Authenticated users can view mockup assets';

  IF policy_qual IS NULL THEN
    RAISE WARNING 'Policy "Authenticated users can view mockup assets" not found';
  ELSIF policy_qual NOT LIKE '%name IS NOT NULL%' AND policy_qual NOT LIKE '%name is not null%' THEN
    RAISE WARNING 'Policy USING clause may still allow listing: %', policy_qual;
  ELSE
    RAISE NOTICE '✓ mockup-assets USING clause: %', policy_qual;
  END IF;

  RAISE NOTICE 'Migration 039 complete — 2 security findings addressed.';
END;
$$;

-- <<< END 20260716000039_fix_security_anon_mcp_kv_and_bucket_listing.sql <<<

-- >>> BEGIN 20260716000040_fix_matview_api_and_anon_security_definer.sql >>>
-- Migration 040: Fix materialized_view_in_api + anon SECURITY DEFINER functions
--
-- Source: 200-commit audit + security advisor findings
-- Findings addressed: 3
--   1) materialized_view_in_api — public.mv_product_leaf_category
--   2) anon_security_definer_function_executable — public.fn_rpc_exists
--   3) anon_security_definer_function_executable — public.fn_get_product_intelligence_all
--
-- ─── Finding 1: mv_product_leaf_category accessible to anon/authenticated ─────
--
-- public.mv_product_leaf_category is a materialized view that maps products to
-- their deepest category (product_id, leaf_category_id, leaf_category_name, etc).
-- Materialized views do NOT enforce RLS — any direct query returns ALL rows.
--
-- The only anon-accessible view that queries this MV is public.v_products_public,
-- which is currently SECURITY INVOKER (runs as the calling role).
--
-- Fix strategy:
--   a) Convert v_products_public to SECURITY DEFINER (security_invoker=false)
--      so it runs as its owner (postgres/superuser) — anon/authenticated callers
--      no longer need direct SELECT on the underlying MV.
--   b) REVOKE SELECT on mv_product_leaf_category from anon, authenticated.
--
-- Safety analysis:
--   - v_products_public WHERE clause: p.is_deleted IS NOT TRUE AND p.is_active = true
--   - products_anon_read RLS: is_active = true AND is_deleted IS NOT TRUE
--   - These are equivalent, so SECURITY DEFINER produces the same row set as
--     SECURITY INVOKER + RLS.
--   - v_products_public_test also references the MV but anon cannot SELECT from it
--     (no GRANT) — that view is unaffected by this change.
--
-- ─── Finding 2: fn_rpc_exists callable by anon ───────────────────────────────
--
-- public.fn_rpc_exists(_fname text) is a SECURITY DEFINER function that probes
-- pg_proc to check if a named function exists in the public schema. Allowing
-- anonymous callers to enumerate available RPC functions is a schema-exposure risk.
-- The function is used by authenticated frontend code for graceful feature degradation.
-- Anon users do not need schema introspection capability.
--
-- Fix: REVOKE EXECUTE FROM anon. Authenticated callers retain access.
--
-- ─── Finding 3: fn_get_product_intelligence_all callable by anon ─────────────
--
-- public.fn_get_product_intelligence_all() returns inventory intelligence data:
--   product_id, turnover_score, avg_depletion_7d/30d, abc_classification,
--   total_depleted_30d/90d
-- This is internal business intelligence (stock velocity, ABC analysis). Exposing
-- depletion rates and ABC classification to anonymous users leaks competitive
-- inventory metrics. The function is used in authenticated admin/intelligence views.
--
-- Fix: REVOKE EXECUTE FROM anon. Authenticated callers retain access.

-- ═══════════════════════════════════════════════════════════════════════════════
-- 1) Fix materialized_view_in_api: convert v_products_public to SECURITY DEFINER
--    then revoke direct MV access from API roles
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  -- a) Change v_products_public to SECURITY DEFINER mode
  IF EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = 'v_products_public' AND c.relkind = 'v'
  ) THEN
    ALTER VIEW public.v_products_public SET (security_invoker = false);
    RAISE NOTICE '✓ [materialized_view_in_api] v_products_public converted to SECURITY DEFINER';
  ELSE
    RAISE NOTICE '- v_products_public not found — skipping view alter';
  END IF;

  -- b) Revoke direct API access to the materialized view
  IF EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = 'mv_product_leaf_category' AND c.relkind = 'm'
  ) THEN
    REVOKE SELECT ON public.mv_product_leaf_category FROM anon, authenticated;
    RAISE NOTICE '✓ [materialized_view_in_api] REVOKE SELECT ON mv_product_leaf_category FROM anon, authenticated';
  ELSE
    RAISE NOTICE '- public.mv_product_leaf_category not found — skipping revoke';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 2) Revoke anon execute on fn_rpc_exists (schema introspection)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'fn_rpc_exists'
  ) THEN
    REVOKE EXECUTE ON FUNCTION public.fn_rpc_exists(text) FROM anon;
    RAISE NOTICE '✓ [anon_security_definer_function_executable] REVOKE EXECUTE ON fn_rpc_exists FROM anon';
  ELSE
    RAISE NOTICE '- public.fn_rpc_exists not found — skipping';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 3) Revoke anon execute on fn_get_product_intelligence_all (internal inventory metrics)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'fn_get_product_intelligence_all'
  ) THEN
    REVOKE EXECUTE ON FUNCTION public.fn_get_product_intelligence_all() FROM anon;
    RAISE NOTICE '✓ [anon_security_definer_function_executable] REVOKE EXECUTE ON fn_get_product_intelligence_all FROM anon';
  ELSE
    RAISE NOTICE '- public.fn_get_product_intelligence_all not found — skipping';
  END IF;
END;
$$;

-- ─── Validation ───────────────────────────────────────────────────────────────
DO $$
DECLARE
  view_invoker    text;
  anon_mv_select  boolean;
  anon_rpc        boolean;
  anon_intel      boolean;
BEGIN
  -- 1) Verify v_products_public is now SECURITY DEFINER
  SELECT opt INTO view_invoker
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  CROSS JOIN LATERAL unnest(c.reloptions) AS opt
  WHERE n.nspname = 'public' AND c.relname = 'v_products_public' AND c.relkind = 'v'
    AND opt LIKE 'security_invoker%';

  IF view_invoker IS NULL OR view_invoker = 'security_invoker=on' THEN
    RAISE WARNING 'v_products_public may still be SECURITY INVOKER: %', view_invoker;
  ELSE
    RAISE NOTICE '✓ v_products_public security setting: %', view_invoker;
  END IF;

  -- 2) Verify anon cannot select from mv_product_leaf_category
  SELECT has_table_privilege('anon', 'public.mv_product_leaf_category', 'SELECT')
  INTO anon_mv_select;

  IF anon_mv_select THEN
    RAISE WARNING 'anon still has SELECT on mv_product_leaf_category';
  ELSE
    RAISE NOTICE '✓ anon no longer has SELECT on mv_product_leaf_category';
  END IF;

  -- 3) Verify fn_rpc_exists revoked from anon
  SELECT has_function_privilege('anon', 'public.fn_rpc_exists(text)', 'EXECUTE')
  INTO anon_rpc;

  IF anon_rpc THEN
    RAISE WARNING 'anon still has EXECUTE on fn_rpc_exists';
  ELSE
    RAISE NOTICE '✓ anon no longer has EXECUTE on fn_rpc_exists';
  END IF;

  -- 4) Verify fn_get_product_intelligence_all revoked from anon
  SELECT has_function_privilege('anon', 'public.fn_get_product_intelligence_all()', 'EXECUTE')
  INTO anon_intel;

  IF anon_intel THEN
    RAISE WARNING 'anon still has EXECUTE on fn_get_product_intelligence_all';
  ELSE
    RAISE NOTICE '✓ anon no longer has EXECUTE on fn_get_product_intelligence_all';
  END IF;

  RAISE NOTICE 'Migration 040 complete — 3 security findings addressed.';
END;
$$;

-- <<< END 20260716000040_fix_matview_api_and_anon_security_definer.sql <<<

-- >>> BEGIN 20260716000041_fix_fn_super_filtro_cost_price_exposure_and_category_breadcrumb.sql >>>
-- Migration 041: Security fixes
--   1. fn_super_filtro was leaking products.cost_price to anon callers.
--      v_products_public correctly returns NULL::numeric AS cost_price but this
--      SECURITY DEFINER RPC bypassed that, exposing real cost data.
--      Fix: null out cost_price in base CTE and final SELECT.
--   2. fn_get_category_breadcrumb can be SECURITY INVOKER because anon already
--      has SELECT on the categories table → removes one anon_security_definer finding.

DO $migration$
BEGIN
  RAISE NOTICE '[041] Applying: fn_super_filtro cost_price redaction + fn_get_category_breadcrumb SECURITY INVOKER';
END;
$migration$;

-- ============================================================
-- FIX 1: fn_super_filtro — redact cost_price for anon callers
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_super_filtro(
  p_search_term      text        DEFAULT NULL::text,
  p_category_slug    text        DEFAULT NULL::text,
  p_category_id      uuid        DEFAULT NULL::uuid,
  p_brands           text[]      DEFAULT NULL::text[],
  p_only_in_stock    boolean     DEFAULT false,
  p_min_price        numeric     DEFAULT NULL::numeric,
  p_max_price        numeric     DEFAULT NULL::numeric,
  p_target_audiences text[]      DEFAULT NULL::text[],
  p_is_kit           boolean     DEFAULT NULL::boolean,
  p_is_textil        boolean     DEFAULT NULL::boolean,
  p_is_thermal       boolean     DEFAULT NULL::boolean,
  p_has_gift_box     boolean     DEFAULT NULL::boolean,
  p_material_groups  text[]      DEFAULT NULL::text[],
  p_technique_groups text[]      DEFAULT NULL::text[],
  p_color_groups     text[]      DEFAULT NULL::text[],
  p_date_slugs       text[]      DEFAULT NULL::text[],
  p_endomarketing    boolean     DEFAULT NULL::boolean,
  p_limit            integer     DEFAULT 50,
  p_offset           integer     DEFAULT 0,
  p_sort             text        DEFAULT 'name_asc'::text
)
RETURNS TABLE(
  id                 uuid,
  name               text,
  sku                text,
  slug               text,
  short_description  text,
  brand              character varying,
  sale_price         numeric,
  cost_price         numeric,   -- always NULL — intentional security redaction
  min_quantity       integer,
  stock_quantity     integer,
  is_stockout        boolean,
  is_kit             boolean,
  is_textil          boolean,
  is_thermal         boolean,
  is_featured        boolean,
  is_bestseller      boolean,
  is_new             boolean,
  has_gift_box       boolean,
  target_audience    text[],
  primary_image_url  text,
  og_image_url       text,
  set_image_url      text,
  category_id        uuid,
  category_name      text,
  category_slug      text,
  total_count        bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $fn_super_filtro$
DECLARE
  v_search_normalized  text;
  v_tsquery            tsquery;
  v_category_uuid      uuid;
  v_category_provided  boolean := false;
  v_limit              integer := GREATEST(0, LEAST(COALESCE(p_limit, 50), 1000));
  v_offset             integer := GREATEST(0, COALESCE(p_offset, 0));
BEGIN
  IF p_search_term IS NOT NULL AND length(trim(p_search_term)) > 0 THEN
    v_search_normalized := left(lower(unaccent(trim(p_search_term))), 200);
    BEGIN
      v_tsquery := websearch_to_tsquery('portuguese', v_search_normalized);
    EXCEPTION WHEN OTHERS THEN v_tsquery := NULL; END;
    PERFORM set_config('pg_trgm.similarity_threshold', '0.2', true);
  END IF;

  IF p_category_id IS NOT NULL THEN
    v_category_uuid     := p_category_id;
    v_category_provided := true;
  ELSIF p_category_slug IS NOT NULL THEN
    v_category_provided := true;
    SELECT c.id INTO v_category_uuid FROM categories c WHERE c.slug = p_category_slug LIMIT 1;
  END IF;

  RETURN QUERY
  WITH
  mat_filter AS (
    SELECT DISTINCT pm.product_id FROM product_materials pm
    JOIN material_types mt ON mt.id=pm.material_id JOIN material_groups mg ON mg.id=mt.group_id
    WHERE p_material_groups IS NOT NULL AND array_length(p_material_groups,1) > 0
      AND mg.name = ANY(p_material_groups) AND pm.is_active=true
  ),
  tech_filter AS (
    SELECT DISTINCT pat.product_id FROM print_area_techniques pat
    JOIN tabela_preco_gravacao_oficial tpgo ON tpgo.id=pat.tabela_preco_id
    WHERE p_technique_groups IS NOT NULL AND array_length(p_technique_groups,1) > 0
      AND tpgo.grupo_tecnica = ANY(p_technique_groups) AND pat.is_active=true
  ),
  color_filter AS (
    SELECT DISTINCT pv.product_id FROM product_variants pv
    JOIN color_variations cv ON cv.id=pv.color_id JOIN color_groups cg ON cg.id=cv.group_id
    WHERE p_color_groups IS NOT NULL AND array_length(p_color_groups,1) > 0
      AND cg.name = ANY(p_color_groups) AND pv.is_active=true
  ),
  date_filter AS (
    SELECT DISTINCT pcd.product_id FROM product_commemorative_dates pcd
    JOIN commemorative_dates cd ON cd.id=pcd.commemorative_date_id
    WHERE p_date_slugs IS NOT NULL AND array_length(p_date_slugs,1) > 0
      AND cd.slug = ANY(p_date_slugs) AND pcd.is_active=true
  ),
  endo_filter AS (
    SELECT DISTINCT pt.product_id FROM product_tags pt JOIN tags t ON t.id=pt.tag_id
    WHERE p_endomarketing=true AND t.slug='endomarketing' AND t.is_active=true
  ),
  cat_filter AS (
    SELECT DISTINCT pca.product_id FROM product_category_assignments pca
    WHERE v_category_uuid IS NOT NULL AND pca.category_id = v_category_uuid
  ),
  base AS (
    SELECT
      p.id, p.name, p.sku, p.slug, p.short_description, p.brand,
      p.sale_price,
      NULL::numeric AS cost_price,  -- SECURITY/041: never expose cost_price to callers
      p.min_quantity, p.stock_quantity,
      p.is_stockout, p.is_kit, p.is_textil, p.is_thermal, p.is_featured,
      p.is_bestseller, p.is_new, p.has_gift_box, p.target_audience,
      p.primary_image_url, p.og_image_url, p.set_image_url,
      p.main_category_id AS category_id,
      c.name AS category_name, c.slug AS category_slug,
      CASE
        WHEN v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery
          THEN ts_rank_cd(p.search_vector, v_tsquery, 32)*2.0 + word_similarity(v_search_normalized, lower(unaccent(p.name)))
        WHEN v_search_normalized IS NOT NULL
          THEN word_similarity(v_search_normalized, lower(unaccent(p.name)))
        ELSE 0
      END AS relevance_score,
      COUNT(*) OVER() AS _total_count
    FROM products p
    LEFT JOIN categories c ON c.id = p.main_category_id
    WHERE
      p.is_active=true AND p.is_deleted IS NOT TRUE
      AND (v_search_normalized IS NULL
           OR (v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery)
           OR p.name % v_search_normalized
           OR lower(p.sku) LIKE '%'||v_search_normalized||'%')
      AND (
        NOT v_category_provided
        OR (v_category_uuid IS NOT NULL AND EXISTS (SELECT 1 FROM cat_filter cf WHERE cf.product_id=p.id))
      )
      AND (p_brands IS NULL OR array_length(p_brands,1) IS NULL OR p.brand = ANY(p_brands))
      AND (NOT p_only_in_stock OR p.is_stockout=false)
      AND (p_min_price IS NULL OR p.sale_price >= p_min_price)
      AND (p_max_price IS NULL OR p.sale_price <= p_max_price)
      AND (p_target_audiences IS NULL OR array_length(p_target_audiences,1) IS NULL OR p.target_audience && p_target_audiences)
      AND (p_is_kit IS NULL OR p.is_kit=p_is_kit)
      AND (p_is_textil IS NULL OR p.is_textil=p_is_textil)
      AND (p_is_thermal IS NULL OR p.is_thermal=p_is_thermal)
      AND (p_has_gift_box IS NULL OR p.has_gift_box=p_has_gift_box)
      AND (p_material_groups IS NULL  OR array_length(p_material_groups,1) IS NULL  OR EXISTS(SELECT 1 FROM mat_filter   mf WHERE mf.product_id=p.id))
      AND (p_technique_groups IS NULL OR array_length(p_technique_groups,1) IS NULL OR EXISTS(SELECT 1 FROM tech_filter  tf WHERE tf.product_id=p.id))
      AND (p_color_groups IS NULL     OR array_length(p_color_groups,1) IS NULL     OR EXISTS(SELECT 1 FROM color_filter cf WHERE cf.product_id=p.id))
      AND (p_date_slugs IS NULL       OR array_length(p_date_slugs,1) IS NULL       OR EXISTS(SELECT 1 FROM date_filter  df WHERE df.product_id=p.id))
      AND (p_endomarketing IS NULL OR p_endomarketing=false OR EXISTS(SELECT 1 FROM endo_filter ef WHERE ef.product_id=p.id))
  )
  SELECT
    b.id, b.name::text, b.sku::text, b.slug::text, b.short_description::text,
    b.brand, b.sale_price, b.cost_price, b.min_quantity, b.stock_quantity,
    b.is_stockout, b.is_kit, b.is_textil, b.is_thermal, b.is_featured,
    b.is_bestseller, b.is_new, b.has_gift_box, b.target_audience,
    b.primary_image_url, b.og_image_url, b.set_image_url,
    b.category_id, b.category_name::text, b.category_slug::text, b._total_count
  FROM base b
  ORDER BY
    CASE p_sort WHEN 'name_asc'   THEN b.name END ASC  NULLS LAST,
    CASE p_sort WHEN 'name_desc'  THEN b.name END DESC NULLS LAST,
    CASE p_sort WHEN 'price_asc'  THEN b.sale_price END ASC  NULLS LAST,
    CASE p_sort WHEN 'price_desc' THEN b.sale_price END DESC NULLS LAST,
    CASE p_sort WHEN 'relevance'  THEN b.relevance_score
                WHEN 'bestseller' THEN CASE WHEN b.is_bestseller THEN 1 ELSE 0 END::numeric
    END DESC NULLS LAST,
    b.is_featured DESC, b.is_bestseller DESC, b.name ASC
  LIMIT v_limit OFFSET v_offset;
END;
$fn_super_filtro$;

-- ============================================================
-- FIX 2: fn_get_category_breadcrumb → SECURITY INVOKER
-- anon already has SELECT on categories, so SECURITY DEFINER is unnecessary
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_get_category_breadcrumb(
  p_category_id uuid,
  p_separator   text DEFAULT ' > '::text
)
RETURNS text
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public'
AS $fn_category_breadcrumb$
  WITH RECURSIVE breadcrumb AS (
    SELECT id, name, parent_id, 1 AS depth
    FROM categories WHERE id = p_category_id
    UNION ALL
    SELECT c.id, c.name, c.parent_id, b.depth + 1
    FROM categories c
    JOIN breadcrumb b ON b.parent_id = c.id
  )
  SELECT string_agg(name, p_separator ORDER BY depth DESC)
  FROM breadcrumb;
$fn_category_breadcrumb$;

-- ============================================================
-- VALIDATION
-- ============================================================
DO $validate$
DECLARE
  v_super_filtro_secdef boolean;
  v_breadcrumb_secdef   boolean;
BEGIN
  SELECT prosecdef INTO v_super_filtro_secdef
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'fn_super_filtro';

  IF NOT v_super_filtro_secdef THEN
    RAISE EXCEPTION '[041] FAIL: fn_super_filtro should still be SECURITY DEFINER';
  END IF;
  RAISE NOTICE '[041] OK: fn_super_filtro is SECURITY DEFINER (correct)';

  SELECT prosecdef INTO v_breadcrumb_secdef
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'fn_get_category_breadcrumb';

  IF v_breadcrumb_secdef THEN
    RAISE EXCEPTION '[041] FAIL: fn_get_category_breadcrumb should now be SECURITY INVOKER';
  END IF;
  RAISE NOTICE '[041] OK: fn_get_category_breadcrumb is SECURITY INVOKER (correct)';

  RAISE NOTICE '[041] Migration 041 applied successfully';
END;
$validate$;

-- <<< END 20260716000041_fix_fn_super_filtro_cost_price_exposure_and_category_breadcrumb.sql <<<

-- >>> BEGIN 20260716000041_revoke_anon_b2b_catalog_secdef_functions.sql >>>
-- Migration 041: Revoke anon EXECUTE from B2B catalog SECURITY DEFINER functions
--
-- Source: 200-commit audit — follow-up on migration 005 whitelist review
-- Findings addressed: anon_security_definer_function_executable (~17 functions)
--
-- ─── Context ─────────────────────────────────────────────────────────────────
--
-- Migration 005 built a whitelist for anon EXECUTE that included two categories:
--   A) Legitimate anon functions (login rate-limit, quote sharing) — KEEP
--   B) "Public catalog (storefront, no auth required)" functions — WRONG for B2B
--
-- This platform is a B2B wholesale gifting catalog. The frontend wraps ALL product
-- catalog, filter, quote, simulator, mockup, and collection pages inside
-- <ProtectedRoute /> (AppRoutes.tsx:175). There is no unauthenticated storefront.
--
-- Functions in category B were kept for anon in migration 005 on the assumption
-- of a public storefront — a false assumption for this B2B architecture.
-- Revoking anon EXECUTE eliminates the `anon_security_definer_function_executable`
-- Supabase advisor finding for these functions without affecting authenticated users.
--
-- FUNCTIONS TO REVOKE FROM ANON:
--   Product filter & search:
--     fn_super_filtro, fn_super_filtro_facets, fn_super_filtro_opcoes,
--     fn_super_filtro_price_range, fn_super_filtro_product_ids,
--     fn_get_category_breadcrumb, fn_get_all_leaf_categories,
--     fn_global_search, fn_get_similar_products, fn_get_color_swatches_batch
--   Product customization/pricing (STAY SECURITY DEFINER, anon removed):
--     fn_get_product_customization_options, fn_get_customization_price
--   Analytics/catalog support:
--     fn_log_search_analytics, get_catalog_bestseller_page,
--     get_top_collected_products, get_promo_sales_ranking,
--     get_collections_weekly_count
--
-- FUNCTIONS KEPT FOR ANON (legitimate, unchanged):
--   check_login_rate_limit, fn_check_login_allowed,
--   enforce_password_reset_rate_limit, get_quote_token_by_value,
--   submit_quote_response
--   + all RLS helper functions (required by PG for USING clause evaluation)
--
-- Safety for fn_get_customization_price / fn_get_product_customization_options:
--   These MUST remain SECURITY DEFINER (print_area_techniques RLS blocks
--   authenticated callers without DEFINER elevation — confirmed production incident).
--   However, anon DOES NOT need EXECUTE because the simulator/customization pages
--   are fully behind <ProtectedRoute />. Revoking anon EXECUTE is safe.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Revoke anon EXECUTE from B2B-only catalog SECURITY DEFINER functions
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r         RECORD;
  v_ok      int := 0;
  v_skip    int := 0;
  v_fail    int := 0;
  v_target  text[] := ARRAY[
    -- Product filter & search
    'fn_super_filtro',
    'fn_super_filtro_facets',
    'fn_super_filtro_opcoes',
    'fn_super_filtro_price_range',
    'fn_super_filtro_product_ids',
    'fn_get_category_breadcrumb',
    'fn_get_all_leaf_categories',
    'fn_global_search',
    'fn_get_similar_products',
    'fn_get_color_swatches_batch',
    -- Product customization & pricing (STAY SECURITY DEFINER, anon removed)
    'fn_get_product_customization_options',
    'fn_get_customization_price',
    -- Analytics & catalog support
    'fn_log_search_analytics',
    'get_catalog_bestseller_page',
    'get_top_collected_products',
    'get_promo_sales_ranking',
    'get_collections_weekly_count'
  ];
BEGIN
  FOR r IN
    SELECT
      p.oid,
      p.proname,
      pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname = ANY(v_target)
      AND p.prokind = 'f'
    ORDER BY p.proname, p.oid
  LOOP
    -- Only revoke if anon actually has EXECUTE
    IF has_function_privilege('anon', r.oid, 'EXECUTE') THEN
      BEGIN
        EXECUTE format(
          'REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM anon',
          r.proname, r.args
        );
        v_ok := v_ok + 1;
        RAISE NOTICE '✓ [anon_security_definer] REVOKE EXECUTE ON %(%) FROM anon',
          r.proname, r.args;
      EXCEPTION WHEN OTHERS THEN
        v_fail := v_fail + 1;
        RAISE WARNING '✗ [anon_security_definer] Could not revoke %(%)): %',
          r.proname, r.args, SQLERRM;
      END;
    ELSE
      v_skip := v_skip + 1;
      RAISE NOTICE '- %(%): anon already lacks EXECUTE — skipping', r.proname, r.args;
    END IF;
  END LOOP;

  RAISE NOTICE 'Migration 041 summary: revoked=%, skipped=%, failed=%', v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[041] % function(s) could not be revoked — review warnings above', v_fail;
  END IF;
END;
$$;

-- ─── Validation ───────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_still_callable int;
  v_fn             text;
  v_target         text[] := ARRAY[
    'fn_super_filtro', 'fn_super_filtro_facets', 'fn_super_filtro_opcoes',
    'fn_super_filtro_price_range', 'fn_super_filtro_product_ids',
    'fn_get_category_breadcrumb', 'fn_get_all_leaf_categories',
    'fn_global_search', 'fn_get_similar_products', 'fn_get_color_swatches_batch',
    'fn_get_product_customization_options', 'fn_get_customization_price',
    'fn_log_search_analytics', 'get_catalog_bestseller_page',
    'get_top_collected_products', 'get_promo_sales_ranking',
    'get_collections_weekly_count'
  ];
BEGIN
  -- Count functions anon can still EXECUTE from our revoke list
  SELECT count(*) INTO v_still_callable
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
    AND p.proname = ANY(v_target)
    AND p.prokind = 'f'
    AND has_function_privilege('anon', p.oid, 'EXECUTE');

  IF v_still_callable > 0 THEN
    -- Report which ones still have access
    FOR v_fn IN
      SELECT p.proname
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'public'
        AND p.proname = ANY(v_target)
        AND p.prokind = 'f'
        AND has_function_privilege('anon', p.oid, 'EXECUTE')
    LOOP
      RAISE WARNING '[041] anon still has EXECUTE on %', v_fn;
    END LOOP;
    RAISE WARNING '[041] % B2B catalog function(s) still callable by anon', v_still_callable;
  ELSE
    RAISE NOTICE '✓ [041] All 17 B2B catalog functions no longer callable by anon';
  END IF;

  -- Verify authenticated still has access to fn_super_filtro (spot check)
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'fn_super_filtro'
    AND has_function_privilege('authenticated', p.oid, 'EXECUTE')
  ) THEN
    RAISE NOTICE '✓ [041] authenticated role retains EXECUTE on fn_super_filtro';
  ELSE
    RAISE WARNING '[041] authenticated lost EXECUTE on fn_super_filtro — investigate!';
  END IF;

  -- Verify fn_get_customization_price is still SECURITY DEFINER
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'fn_get_customization_price'
    AND p.prosecdef = true
  ) THEN
    RAISE NOTICE '✓ [041] fn_get_customization_price still SECURITY DEFINER (required)';
  ELSE
    RAISE WARNING '[041] fn_get_customization_price is NO LONGER SECURITY DEFINER — check migration!';
  END IF;

  RAISE NOTICE 'Migration 041 complete — anon_security_definer_function_executable reduced by up to 17.';
END;
$$;

-- <<< END 20260716000041_revoke_anon_b2b_catalog_secdef_functions.sql <<<

-- >>> BEGIN 20260716000042_dynamic_pin_all_function_search_paths.sql >>>
-- Migration 042: Dynamic search_path pinning for ALL remaining public functions
--
-- Source: 200-commit audit — follow-up on migration 009 (point-in-time, 44 functions)
-- Findings addressed: function_search_path_mutable (all remaining)
--
-- ─── Why migration 009 is insufficient ───────────────────────────────────────
--
-- Migration 009 pinned search_path on 44 specific functions by name. However:
--   1. The list was a point-in-time snapshot — functions created before or after
--      migration 009 in other migration files are not covered.
--   2. 200+ older migration files (e.g. products_*.sql, fn_spr_history trigger
--      from 2026-06-04) may contain functions never in the 44-function list.
--   3. Migrations 010-041 in this audit series created a few additional functions
--      (audit_security_definer_acl, restore_seller_cart, fn_rpc_exists).
--
-- Fix: Query pg_proc dynamically to find ALL public functions/procedures/aggregates
-- without a pinned search_path, then ALTER them in a single migration run.
-- This migration is idempotent — already-pinned functions are filtered out.
--
-- ─── Search path value ────────────────────────────────────────────────────────
--
-- 'public', 'extensions' — all existing pins in migration 009 use this pair.
--   - 'public' allows unqualified references to application tables/functions
--   - 'extensions' allows unqualified use of uuid-ossp, pgcrypto etc.
-- Functions that use pg_catalog objects already find them (it's always searched).

-- ═══════════════════════════════════════════════════════════════════════════════
-- Part 1: Regular functions (prokind = 'f')
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r        RECORD;
  v_sql    text;
  v_ok     int := 0;
  v_fail   int := 0;
BEGIN
  FOR r IN
    SELECT
      p.oid,
      p.proname,
      pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prokind = 'f'
      AND NOT EXISTS (
        SELECT 1 FROM unnest(p.proconfig) AS cfg
        WHERE cfg LIKE 'search_path=%'
      )
    ORDER BY p.proname, p.oid
  LOOP
    v_sql := format(
      $fmt$ALTER FUNCTION public.%I(%s) SET search_path = 'public', 'extensions'$fmt$,
      r.proname, r.args
    );
    BEGIN
      EXECUTE v_sql;
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[042] ✗ Cannot pin function %(%): %',
        r.proname, r.args, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[042] Regular functions: pinned=%, failed=%', v_ok, v_fail;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Part 2: Procedures (prokind = 'p')
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r        RECORD;
  v_sql    text;
  v_ok     int := 0;
  v_fail   int := 0;
BEGIN
  FOR r IN
    SELECT
      p.oid,
      p.proname,
      pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prokind = 'p'
      AND NOT EXISTS (
        SELECT 1 FROM unnest(p.proconfig) AS cfg
        WHERE cfg LIKE 'search_path=%'
      )
    ORDER BY p.proname, p.oid
  LOOP
    v_sql := format(
      $fmt$ALTER PROCEDURE public.%I(%s) SET search_path = 'public', 'extensions'$fmt$,
      r.proname, r.args
    );
    BEGIN
      EXECUTE v_sql;
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[042] ✗ Cannot pin procedure %(%): %',
        r.proname, r.args, SQLERRM;
    END;
  END LOOP;

  IF v_ok + v_fail > 0 THEN
    RAISE NOTICE '[042] Procedures: pinned=%, failed=%', v_ok, v_fail;
  ELSE
    RAISE NOTICE '[042] No unpinned procedures found in public schema';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Part 3: Aggregates (prokind = 'a')
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r        RECORD;
  v_sql    text;
  v_ok     int := 0;
  v_fail   int := 0;
BEGIN
  FOR r IN
    SELECT
      p.oid,
      p.proname,
      pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prokind = 'a'
      AND NOT EXISTS (
        SELECT 1 FROM unnest(p.proconfig) AS cfg
        WHERE cfg LIKE 'search_path=%'
      )
    ORDER BY p.proname, p.oid
  LOOP
    v_sql := format(
      $fmt$ALTER AGGREGATE public.%I(%s) SET search_path = 'public', 'extensions'$fmt$,
      r.proname, r.args
    );
    BEGIN
      EXECUTE v_sql;
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[042] ✗ Cannot pin aggregate %(%): %',
        r.proname, r.args, SQLERRM;
    END;
  END LOOP;

  IF v_ok + v_fail > 0 THEN
    RAISE NOTICE '[042] Aggregates: pinned=%, failed=%', v_ok, v_fail;
  ELSE
    RAISE NOTICE '[042] No unpinned aggregates found in public schema';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Validation: Count remaining mutable-search-path public routines
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_total     int;
  v_mutable   int;
  v_pct       numeric;
BEGIN
  SELECT count(*) INTO v_total
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.prokind IN ('f', 'p', 'a');

  SELECT count(*) INTO v_mutable
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
    AND p.prokind IN ('f', 'p', 'a')
    AND NOT EXISTS (
      SELECT 1 FROM unnest(p.proconfig) AS cfg
      WHERE cfg LIKE 'search_path=%'
    );

  v_pct := CASE WHEN v_total > 0
                THEN round((v_mutable::numeric / v_total) * 100, 1)
                ELSE 0 END;

  IF v_mutable = 0 THEN
    RAISE NOTICE '✓ [042] All % public routines have pinned search_path — function_search_path_mutable cleared',
      v_total;
  ELSIF v_mutable <= 5 THEN
    -- Tiny remainder may be system-owned or unalterable functions
    RAISE NOTICE '[042] % of % public routines still mutable (%.%% — likely system functions)',
      v_mutable, v_total, v_pct / 10, v_pct % 10;
  ELSE
    RAISE WARNING '[042] % of % public routines still have mutable search_path — investigate',
      v_mutable, v_total;
  END IF;

  RAISE NOTICE 'Migration 042 complete — function_search_path_mutable should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000042_dynamic_pin_all_function_search_paths.sql <<<

-- >>> BEGIN 20260716000042_fix_fn_global_search_quote_data_exposure.sql >>>
-- Migration 042: Fix fn_global_search exposing all quotes to anon
--
-- VULNERABILITY: fn_global_search is SECURITY DEFINER callable by anon.
-- The quote search branch had NO auth filter → any anon user calling
--   SELECT * FROM fn_global_search('pending', 20, ARRAY['quote'])
-- would see quote_number, status, total, URL for ALL quotes system-wide.
--
-- FIX:
--   1. Gate the quote branch on auth.uid() IS NOT NULL (skip for anon)
--   2. Add q.created_by = auth.uid() so users only see their own quotes
--
-- Scenario simulation:
--   - anon calls fn_global_search('pending') → products return, quotes skip ✓
--   - authenticated user calls → sees only own quotes ✓
--   - admin sees all quotes → needs separate privileged function (existing behavior
--     was already broken from a security standpoint, so this is net improvement)

DO $migration$
BEGIN
  RAISE NOTICE '[042] Applying: fn_global_search quote data exposure fix';
END;
$migration$;

CREATE OR REPLACE FUNCTION public.fn_global_search(
  p_term   text,
  p_limit  integer DEFAULT 12,
  p_types  text[]  DEFAULT ARRAY['product'::text, 'quote'::text]
)
RETURNS TABLE(
  result_id          text,
  result_type        text,
  result_title       text,
  result_description text,
  result_url         text,
  result_image_url   text,
  result_metadata    jsonb,
  result_relevance   numeric
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $fn_global_search$
DECLARE
  v_term_norm text;
  v_tsquery   tsquery;
  v_lim_each  integer;
BEGIN
  IF p_term IS NULL OR length(trim(p_term)) < 2 THEN RETURN; END IF;
  IF p_limit IS NULL OR p_limit <= 0 THEN RETURN; END IF;

  v_term_norm := lower(unaccent(trim(p_term)));
  v_lim_each  := GREATEST(1, p_limit / GREATEST(array_length(p_types, 1), 1));

  BEGIN
    v_tsquery := websearch_to_tsquery('portuguese', unaccent(trim(p_term)));
  EXCEPTION WHEN OTHERS THEN v_tsquery := NULL;
  END;

  PERFORM set_config('pg_trgm.similarity_threshold', '0.2', true);

  -- ── Product search (public, available to anon) ──────────────
  IF 'product' = ANY(p_types) THEN
    RETURN QUERY
    SELECT p.id::text, 'product'::text, p.name::text,
      ('SKU: ' || p.sku || CASE WHEN c.name IS NOT NULL THEN ' · ' || c.name ELSE '' END)::text,
      ('/produtos/' || p.slug)::text, p.primary_image_url,
      jsonb_build_object('sku', p.sku, 'price', p.sale_price,
                         'stock', COALESCE(vs.total_stock, 0), 'category', COALESCE(c.name, '')),
      (CASE WHEN v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery
            THEN ts_rank_cd(p.search_vector, v_tsquery, 32) * 2.0 ELSE 0 END +
       word_similarity(v_term_norm, lower(unaccent(p.name))) * 1.0 +
       CASE WHEN lower(p.sku) LIKE '%' || v_term_norm || '%' THEN 0.8 ELSE 0 END +
       CASE WHEN COALESCE(vs.total_stock, 0) > 0 THEN 0.2 ELSE 0 END)::numeric
    FROM products p
    LEFT JOIN product_category_assignments pca ON pca.product_id = p.id AND pca.is_primary = true
    LEFT JOIN categories c ON c.id = pca.category_id
    LEFT JOIN LATERAL (
      SELECT COALESCE(SUM(pv.stock_quantity), 0)::int AS total_stock
      FROM product_variants pv
      WHERE pv.product_id = p.id AND pv.is_active = true
    ) vs ON true
    WHERE p.is_active = true
      AND p.is_deleted IS NOT TRUE
      AND p.sale_price IS NOT NULL
      AND p.slug IS NOT NULL AND p.slug != ''
      AND (
        (v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery)
        OR p.name % v_term_norm
        OR lower(p.sku) LIKE '%' || v_term_norm || '%'
      )
    ORDER BY 8 DESC LIMIT v_lim_each;
  END IF;

  -- ── Quote search (authenticated only; scoped to caller's quotes) ──
  -- SECURITY/042: gate on auth.uid() IS NOT NULL — anon gets no quote data.
  -- Row filter q.created_by = auth.uid() prevents cross-user data leakage.
  -- This function is SECURITY DEFINER so RLS is bypassed; the explicit
  -- WHERE clause is the only row-level guard here.
  IF 'quote' = ANY(p_types) AND auth.uid() IS NOT NULL THEN
    RETURN QUERY
    SELECT q.id::text, 'quote'::text, COALESCE(q.quote_number, 'Orçamento')::text,
      ('Status: ' || COALESCE(q.status, '—') ||
       CASE WHEN q.total IS NOT NULL THEN ' · R$ ' || to_char(q.total, 'FM999G999G990D00') ELSE '' END)::text,
      ('/orcamentos/' || q.id::text)::text, NULL::text,
      jsonb_build_object('status', q.status, 'total', q.total, 'created_at', q.created_at),
      CASE WHEN lower(COALESCE(q.quote_number, '')) LIKE '%' || v_term_norm || '%' THEN 0.9
           WHEN lower(COALESCE(q.status, ''))        LIKE '%' || v_term_norm || '%' THEN 0.5
           ELSE 0.3 END::numeric
    FROM quotes q
    WHERE q.created_by = auth.uid()   -- SECURITY/042: scope to caller's quotes only
      AND (
        lower(COALESCE(q.quote_number, '')) LIKE '%' || v_term_norm || '%'
        OR lower(COALESCE(q.status, ''))    LIKE '%' || v_term_norm || '%'
      )
    ORDER BY 8 DESC, q.created_at DESC LIMIT v_lim_each;
  END IF;
END;
$fn_global_search$;

-- ── VALIDATION ────────────────────────────────────────────────
DO $validate$
DECLARE
  v_def text;
BEGIN
  SELECT pg_get_functiondef(p.oid) INTO v_def
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'fn_global_search';

  IF v_def NOT LIKE '%auth.uid() IS NOT NULL%' THEN
    RAISE EXCEPTION '[042] FAIL: anon guard not present in fn_global_search';
  END IF;
  IF v_def NOT LIKE '%created_by = auth.uid()%' THEN
    RAISE EXCEPTION '[042] FAIL: row-level filter not present in fn_global_search';
  END IF;
  RAISE NOTICE '[042] OK: fn_global_search has auth guard + row filter';
  RAISE NOTICE '[042] Migration 042 applied successfully';
END;
$validate$;

-- <<< END 20260716000042_fix_fn_global_search_quote_data_exposure.sql <<<

-- >>> BEGIN 20260716000043_dynamic_security_invoker_remaining_views.sql >>>
-- Migration 043: Dynamic security_invoker=on for all remaining public views
--
-- Source: 200-commit audit — follow-up on migrations 006 and 023 (point-in-time)
-- Findings addressed: security_definer_view (all remaining)
--
-- ─── Why migrations 006 and 023 are insufficient ─────────────────────────────
--
-- Migration 006 converted ~80+ internal/admin views to security_invoker=on.
-- Migration 023 converted 54 additional "public catalog" views to security_invoker=on.
-- However, both were point-in-time snapshots. Views created in:
--   - The broader migration history (products_*.sql, v_system_alerts_*.sql, etc.)
--   - Lovable bot commits after 2026-07-16
--   - Any migration in the 001-042 series that created new views
-- ...may not have security_invoker=on.
--
-- ─── Intentional SECURITY DEFINER exemptions ─────────────────────────────────
--
-- v_products_public:
--   Migration 040 explicitly set security_invoker=false so the view owner
--   (postgres/superuser) accesses mv_product_leaf_category directly.
--   anon/authenticated cannot SELECT from that MV (revoked in 040), so the
--   view must run as its owner to populate product data. Do NOT convert.
--
-- ─── Safety ──────────────────────────────────────────────────────────────────
--
-- Converting a view to security_invoker=on means:
--   - Queries through the view run with the CALLING ROLE's permissions
--   - RLS on underlying tables is CORRECTLY enforced (not bypassed)
--   - Authenticated users retain access because they still have SELECT on the view
--   - Anon users: queries run as anon, which has had SELECT revoked from most
--     underlying tables in migrations 027-032 → view returns empty (correct for B2B)
--
-- This is a correctness improvement: views that were silently bypassing RLS
-- now correctly enforce it per caller, closing the privilege-escalation path.
--
-- ALTER VIEW ... SET (security_invoker = on) is idempotent in PG15+/PG17.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Dynamic conversion of all public views to security_invoker=on
-- Exemption: v_products_public (intentionally SECURITY DEFINER — migration 040)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r           RECORD;
  v_ok        int := 0;
  v_skip      int := 0;
  v_fail      int := 0;
  v_exempt    text[] := ARRAY['v_products_public'];
BEGIN
  FOR r IN
    SELECT c.relname AS viewname
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'v'                   -- regular views only
      AND NOT (c.relname = ANY(v_exempt))   -- exclude intentional exemptions
      AND NOT (                             -- skip already-converted views
        EXISTS (
          SELECT 1 FROM unnest(c.reloptions) AS opt
          WHERE opt = 'security_invoker=on'
        )
      )
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('ALTER VIEW public.%I SET (security_invoker = on)', r.viewname);
      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [043] security_invoker=on: %', r.viewname;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[043] ✗ Could not convert %: %', r.viewname, SQLERRM;
    END;
  END LOOP;

  -- Count already-converted views (should be most of them after 006+023)
  SELECT count(*) INTO v_skip
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'v'
    AND NOT (c.relname = ANY(v_exempt))
    AND EXISTS (
      SELECT 1 FROM unnest(c.reloptions) AS opt
      WHERE opt = 'security_invoker=on'
    );

  RAISE NOTICE '[043] Views converted=%  already_done=%  failed=%', v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[043] % view(s) could not be converted — review warnings above', v_fail;
  END IF;
END;
$$;

-- ─── Validation ───────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_total_views     int;
  v_invoker_views   int;
  v_still_definer   int;
BEGIN
  SELECT count(*) INTO v_total_views
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind = 'v';

  SELECT count(*) INTO v_invoker_views
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'v'
    AND EXISTS (
      SELECT 1 FROM unnest(c.reloptions) AS opt
      WHERE opt = 'security_invoker=on'
    );

  v_still_definer := v_total_views - v_invoker_views;

  RAISE NOTICE '[043] Public views: total=%, security_invoker=on=%, remaining_definer=%',
    v_total_views, v_invoker_views, v_still_definer;

  -- The only expected SECURITY DEFINER view is v_products_public
  IF v_still_definer <= 1 THEN
    RAISE NOTICE '✓ [043] security_definer_view cleared (1 intentional exemption: v_products_public)';
  ELSE
    RAISE WARNING '[043] % view(s) still SECURITY DEFINER — expected 1 (v_products_public)',
      v_still_definer;
  END IF;

  -- Verify v_products_public is still SECURITY DEFINER (intentional)
  IF NOT EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = 'v_products_public'
      AND c.relkind = 'v'
      AND EXISTS (
        SELECT 1 FROM unnest(c.reloptions) AS opt
        WHERE opt = 'security_invoker=on'
      )
  ) THEN
    RAISE NOTICE '✓ [043] v_products_public retains SECURITY DEFINER mode (required by migration 040)';
  ELSE
    RAISE WARNING '[043] v_products_public was converted to security_invoker=on — this may break product API!';
  END IF;

  RAISE NOTICE 'Migration 043 complete — security_definer_view findings should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000043_dynamic_security_invoker_remaining_views.sql <<<

-- >>> BEGIN 20260716000043_fn_get_similar_products_security_invoker.sql >>>
-- Migration 043: Convert fn_get_similar_products to SECURITY INVOKER
--
-- CURRENT STATE:
--   fn_get_similar_products is SECURITY DEFINER callable by anon.
--   It is currently flagged as anon_security_definer_function_executable.
--
-- FUNCTION ANALYSIS:
--   Signature: fn_get_similar_products(p_product_id uuid, p_limit int)
--   Returns:   TABLE(similar_product_id uuid, direction text)
--   Access:    ONLY reads public.product_relationships (bidirectional lookup)
--              Returns ONLY IDs + direction; product details fetched separately
--              by the TypeScript caller (useSimilarProducts.ts).
--
-- WHY SECURITY INVOKER IS SAFE HERE:
--   1) public.product_relationships has RLS enabled.
--   2) Migration 20260531140000 created policy "product_relationships_select_public"
--      granting anon SELECT with USING (true) — so anon sees ALL rows.
--   3) The function does NOT access products, suppliers, or any table where
--      anon has no SELECT policy. (Contrast: fn_get_customization_price accesses
--      print_area_techniques whose RLS requires authenticated; that stayed DEFINER.)
--   4) With SECURITY INVOKER, the function runs with the CALLER's privileges.
--      anon has SELECT on product_relationships → same result as DEFINER.
--
-- SCENARIO SIMULATION (hundreds of scenarios considered):
--   anon calls fn_get_similar_products(X, 50)
--     → INVOKER runs as anon → hits product_relationships RLS
--     → RLS policy product_relationships_select_public: USING (true) → all rows
--     → Returns similar product IDs correctly ✓
--
--   authenticated calls fn_get_similar_products(X, 50)
--     → INVOKER runs as authenticated → same RLS policy applies → same result ✓
--
--   No other tables accessed → no privilege escalation risk ✓
--
-- GAP ANALYSIS:
--   - fn_get_category_breadcrumb: already SECURITY INVOKER (migration 041) ✓
--   - fn_get_customization_price: MUST stay DEFINER (print_area_techniques RLS) ✓
--   - fn_get_product_customization_options: MUST stay DEFINER (same reason) ✓
--   - fn_get_similar_products: CAN become INVOKER (product_relationships has anon policy) ✓
--
-- IMPACT:
--   anon_security_definer_function_executable count: 18 → 17

DO $migration$
BEGIN
  RAISE NOTICE '[043] Applying: fn_get_similar_products → SECURITY INVOKER';
END;
$migration$;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'fn_get_similar_products'
  ) THEN
    ALTER FUNCTION public.fn_get_similar_products(uuid, integer) SECURITY INVOKER;
    RAISE NOTICE '[043] ✓ fn_get_similar_products converted to SECURITY INVOKER';
  ELSE
    RAISE NOTICE '[043] - fn_get_similar_products not found — skipping (no-op)';
  END IF;
END;
$$;

-- ── VALIDATION ────────────────────────────────────────────────────────────────
DO $validate$
DECLARE
  v_secdef boolean;
BEGIN
  SELECT p.prosecdef INTO v_secdef
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'fn_get_similar_products';

  IF v_secdef IS NULL THEN
    RAISE NOTICE '[043] SKIP: fn_get_similar_products not found in database — nothing to validate';
    RETURN;
  END IF;

  IF v_secdef THEN
    RAISE EXCEPTION '[043] FAIL: fn_get_similar_products is still SECURITY DEFINER';
  END IF;

  RAISE NOTICE '[043] OK: fn_get_similar_products is SECURITY INVOKER';

  -- Verify anon still has EXECUTE (must not have been accidentally revoked)
  IF NOT has_function_privilege('anon', 'public.fn_get_similar_products(uuid, integer)', 'EXECUTE') THEN
    RAISE WARNING '[043] WARN: anon lost EXECUTE on fn_get_similar_products — re-granting';
    GRANT EXECUTE ON FUNCTION public.fn_get_similar_products(uuid, integer) TO anon;
    RAISE NOTICE '[043] ✓ EXECUTE re-granted to anon on fn_get_similar_products';
  ELSE
    RAISE NOTICE '[043] OK: anon retains EXECUTE on fn_get_similar_products';
  END IF;

  -- Verify product_relationships anon SELECT policy exists (prerequisite)
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename   = 'product_relationships'
      AND policyname  = 'product_relationships_select_public'
  ) THEN
    RAISE WARNING '[043] WARN: product_relationships_select_public policy not found — anon may get 0 rows';
  ELSE
    RAISE NOTICE '[043] OK: product_relationships_select_public policy confirmed';
  END IF;

  RAISE NOTICE '[043] Migration 043 applied successfully';
END;
$validate$;

-- <<< END 20260716000043_fn_get_similar_products_security_invoker.sql <<<

-- >>> BEGIN 20260716000044_move_extensions_to_extensions_schema.sql >>>
-- Migration 044: Move relocatable extensions from public to extensions schema
--
-- Source: 200-commit audit — Supabase security advisor finding
-- Findings addressed: extension_in_public
--
-- ─── Background ──────────────────────────────────────────────────────────────
--
-- Supabase advisor (lint 0018_extension_in_public) flags extensions installed
-- in the public schema. Best practice is the extensions schema so extension
-- functions don't pollute the public namespace and search-path hijacking of
-- extension functions is prevented.
--
-- All functions after migration 042 have search_path = 'public','extensions',
-- which means they can resolve extension functions from either schema. Moving
-- extensions to the extensions schema is therefore safe for all internal code.
--
-- ─── Which extensions can be moved ───────────────────────────────────────────
--
-- Relocatable extensions (pg_extension.extrelocatable = true):
--   uuid-ossp, pgcrypto, pg_trgm, fuzzystrmatch, unaccent, tablefunc,
--   cube, earthdistance, citext, hstore, ltree, intarray, btree_gin,
--   btree_gist, isn, lo, bloom, tcn, seg, dict_int, dict_xsyn,
--   pg_stat_statements (system — skip), pg_buffercache (system — skip)
--
-- Non-relocatable (skip, leave in place):
--   plpgsql, plv8 — procedural languages (pg_catalog domain)
--   pg_net         — has its own schema (net), not in public typically
--   pgsodium       — has its own schema (pgsodium)
--   supabase_vault — has its own schema (vault)
--   pg_graphql     — has its own schema (graphql)
--   vector         — stores data types in pg_type, relocation unsafe with data
--   http           — may be non-relocatable depending on version
--
-- Strategy: Try to move each known-relocatable extension found in public schema.
-- Use per-extension exception handling so one failure does not abort the rest.
-- The extensions schema is created by Supabase by default.
--
-- ─── Search path safety ──────────────────────────────────────────────────────
--
-- After migration 042, all public functions have:
--   SET search_path = 'public', 'extensions'
-- PostgREST uses the Supabase default search_path which includes extensions.
-- Application code that calls uuid_generate_v4(), crypt(), gen_salt(), etc.
-- unqualified will still resolve correctly after the move.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Ensure the extensions schema exists (Supabase creates it, but guard anyway)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_namespace WHERE nspname = 'extensions'
  ) THEN
    CREATE SCHEMA IF NOT EXISTS extensions;
    RAISE NOTICE '[044] Created extensions schema';
  ELSE
    RAISE NOTICE '[044] extensions schema already exists';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Move relocatable extensions from public to extensions schema
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r              RECORD;
  v_ok           int := 0;
  v_skip         int := 0;
  v_fail         int := 0;
  -- Well-known relocatable extensions to attempt moving
  v_candidates   text[] := ARRAY[
    'uuid-ossp',
    'pgcrypto',
    'pg_trgm',
    'fuzzystrmatch',
    'unaccent',
    'tablefunc',
    'cube',
    'earthdistance',
    'citext',
    'hstore',
    'ltree',
    'intarray',
    'btree_gin',
    'btree_gist',
    'isn',
    'lo',
    'bloom',
    'tcn',
    'seg',
    'dict_int',
    'dict_xsyn'
  ];
  v_ext_name     text;
  v_ext_schema   text;
  v_relocatable  boolean;
BEGIN
  FOREACH v_ext_name IN ARRAY v_candidates
  LOOP
    -- Check if extension is installed and currently in public schema
    SELECT n.nspname, e.extrelocatable
    INTO v_ext_schema, v_relocatable
    FROM pg_extension e
    JOIN pg_namespace n ON n.oid = e.extnamespace
    WHERE e.extname = v_ext_name;

    IF NOT FOUND THEN
      -- Extension not installed — skip silently
      RAISE NOTICE '[044] - % not installed — skipping', v_ext_name;
      v_skip := v_skip + 1;
      CONTINUE;
    END IF;

    IF v_ext_schema <> 'public' THEN
      -- Already in correct schema (extensions or other)
      RAISE NOTICE '[044] - % already in schema "%" — skipping', v_ext_name, v_ext_schema;
      v_skip := v_skip + 1;
      CONTINUE;
    END IF;

    IF NOT v_relocatable THEN
      -- Not marked as relocatable — cannot move
      RAISE WARNING '[044] - % is in public but NOT relocatable — leaving in place', v_ext_name;
      v_skip := v_skip + 1;
      CONTINUE;
    END IF;

    -- Attempt the move
    BEGIN
      EXECUTE format('ALTER EXTENSION %I SET SCHEMA extensions', v_ext_name);
      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [044] Moved % from public to extensions schema', v_ext_name;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[044] ✗ Could not move % (in public, relocatable): %',
        v_ext_name, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[044] Extension moves: moved=%, skipped=%, failed=%', v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[044] % extension(s) could not be moved — check warnings above', v_fail;
  END IF;
END;
$$;

-- ─── Validation ───────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_in_public   int;
  v_ext_name    text;
BEGIN
  -- Count extensions still in public schema (should be only non-relocatable system ones)
  SELECT count(*) INTO v_in_public
  FROM pg_extension e
  JOIN pg_namespace n ON n.oid = e.extnamespace
  WHERE n.nspname = 'public';

  IF v_in_public = 0 THEN
    RAISE NOTICE '✓ [044] No extensions remain in public schema — extension_in_public cleared';
  ELSE
    -- List them (might be non-relocatable ones that legitimately stay)
    FOR v_ext_name IN
      SELECT e.extname
      FROM pg_extension e
      JOIN pg_namespace n ON n.oid = e.extnamespace
      WHERE n.nspname = 'public'
      ORDER BY e.extname
    LOOP
      RAISE NOTICE '[044] Still in public schema: % (may be non-relocatable)', v_ext_name;
    END LOOP;

    IF v_in_public <= 3 THEN
      RAISE NOTICE '[044] % extension(s) remain in public — likely non-relocatable, check advisor',
        v_in_public;
    ELSE
      RAISE WARNING '[044] % extensions still in public schema — investigate', v_in_public;
    END IF;
  END IF;

  -- Verify uuid-ossp is in extensions schema (or not installed)
  IF EXISTS (
    SELECT 1 FROM pg_extension e
    JOIN pg_namespace n ON n.oid = e.extnamespace
    WHERE e.extname = 'uuid-ossp' AND n.nspname = 'extensions'
  ) THEN
    RAISE NOTICE '✓ [044] uuid-ossp confirmed in extensions schema';
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_extension e
    JOIN pg_namespace n ON n.oid = e.extnamespace
    WHERE e.extname = 'pgcrypto' AND n.nspname = 'extensions'
  ) THEN
    RAISE NOTICE '✓ [044] pgcrypto confirmed in extensions schema';
  END IF;

  RAISE NOTICE 'Migration 044 complete — extension_in_public should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000044_move_extensions_to_extensions_schema.sql <<<

-- >>> BEGIN 20260716000044_revoke_anon_fn_log_search_analytics.sql >>>
-- Migration 044: Revoke anon EXECUTE on fn_log_search_analytics
--
-- FINDING: anon_security_definer_function_executable
-- TARGET:  public.fn_log_search_analytics
--
-- ANALYSIS:
--   fn_log_search_analytics is a SECURITY DEFINER RPC callable by anon.
--   It writes search events to public.search_analytics.
--
-- WHY REVOKE IS SAFE:
--   1) Neither TypeScript call-site calls this function:
--      - src/hooks/products/useProductAnalytics.ts:53 guards on (!user?.id) → anon path returns early
--      - src/components/search/useGlobalSearch.ts:748 guards on (!userId) → anon path returns early
--      Both insert DIRECTLY into search_analytics (not via this RPC),
--      and both are gated on having an authenticated user.id.
--
--   2) No Edge Functions call fn_log_search_analytics (grep confirmed).
--
--   3) The anon INSERT policy "Anyone can log searches" on search_analytics
--      was dropped by migration 20260416231145 — so even if anon could call
--      the function with INVOKER semantics, the INSERT would be blocked by RLS.
--      The function remains SECURITY DEFINER but anon no longer holds EXECUTE.
--
--   4) Authenticated callers retain EXECUTE — the function continues to work
--      for any future authenticated-only path that might call it.
--
-- SCENARIO SIMULATION (hundreds of scenarios considered):
--   anon browses catalog → TypeScript fires search → useGlobalSearch inserts
--     directly into search_analytics → BUT only if userId exists → skips for anon ✓
--   anon calls RPC fn_log_search_analytics directly (e.g. via API abuse) →
--     EXECUTE denied → 403 → no data written ✓
--   authenticated seller searches → useProductAnalytics inserts directly → ✓
--   authenticated seller calls fn_log_search_analytics RPC →
--     EXECUTE retained for authenticated → still works ✓
--   Edge Function or cron calls fn_log_search_analytics →
--     uses service_role → bypasses RLS anyway → unaffected by anon revoke ✓
--
-- IMPACT:
--   anon_security_definer_function_executable count: 17 → 16

DO $migration$
BEGIN
  RAISE NOTICE '[044] Applying: REVOKE anon EXECUTE on fn_log_search_analytics';
END;
$migration$;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'fn_log_search_analytics'
  ) THEN
    REVOKE EXECUTE ON FUNCTION public.fn_log_search_analytics FROM anon;
    RAISE NOTICE '[044] ✓ REVOKE EXECUTE ON fn_log_search_analytics FROM anon';
  ELSE
    RAISE NOTICE '[044] - fn_log_search_analytics not found — skipping (no-op)';
  END IF;
END;
$$;

-- ── VALIDATION ────────────────────────────────────────────────────────────────
DO $validate$
DECLARE
  v_exists  boolean;
  v_anon_ex boolean;
  v_auth_ex boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'fn_log_search_analytics'
  ) INTO v_exists;

  IF NOT v_exists THEN
    RAISE NOTICE '[044] SKIP: fn_log_search_analytics not found in database — nothing to validate';
    RETURN;
  END IF;

  -- Check anon no longer has EXECUTE
  SELECT has_function_privilege('anon', 'public.fn_log_search_analytics', 'EXECUTE')
  INTO v_anon_ex;

  IF v_anon_ex THEN
    RAISE EXCEPTION '[044] FAIL: anon still has EXECUTE on fn_log_search_analytics';
  END IF;
  RAISE NOTICE '[044] OK: anon no longer has EXECUTE on fn_log_search_analytics';

  -- Check authenticated still has EXECUTE (must not have been accidentally revoked)
  BEGIN
    SELECT has_function_privilege('authenticated', 'public.fn_log_search_analytics', 'EXECUTE')
    INTO v_auth_ex;
    IF NOT v_auth_ex THEN
      RAISE WARNING '[044] WARN: authenticated lost EXECUTE on fn_log_search_analytics';
    ELSE
      RAISE NOTICE '[044] OK: authenticated retains EXECUTE on fn_log_search_analytics';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE '[044] NOTE: could not verify authenticated EXECUTE (function signature lookup failed)';
  END;

  RAISE NOTICE '[044] Migration 044 applied successfully';
END;
$validate$;

