    v_qual  := replace(v_qual,  'auth.email()', '(SELECT auth.email())');
    v_check := replace(v_check, 'auth.email()', '(SELECT auth.email())');

    v_qual  := replace(v_qual,  c_ph, '(SELECT auth.email())');
