    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[050] ✗ auth.email() — could not optimize %.% (%): %',
        r.tablename, r.policyname, r.cmd, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[050] Pass 2 auth.email(): optimized=%, skipped=%, failed=%',
