-- ═══════════════════════════════════════════════════════════════════════════════
-- Pass 3: Fix bare auth.jwt() in public schema RLS policies
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- auth.jwt() is typically used as:
--   auth.jwt() ->> 'key'     (text extraction)
--   auth.jwt() -> 'key'      (json extraction)
-- Wrapping auth.jwt() → (SELECT auth.jwt()) covers both operators correctly.

DO $$
DECLARE
  r          RECORD;
  v_ok       int := 0;
  v_skip     int := 0;
  v_fail     int := 0;
  v_qual     text;
  v_check    text;
  c_ph       CONSTANT text := '<<AUTH_JWT_ALREADY_WRAPPED>>';
BEGIN
  FOR r IN
    SELECT p.policyname, p.tablename, p.cmd, p.qual, p.with_check
    FROM pg_policies p
    WHERE p.schemaname = 'public'
      AND (
        (p.qual       IS NOT NULL
          AND p.qual       LIKE '%auth.jwt()%'
          AND p.qual       NOT LIKE '%(SELECT auth.jwt())%')
        OR
        (p.with_check IS NOT NULL
          AND p.with_check LIKE '%auth.jwt()%'
          AND p.with_check NOT LIKE '%(SELECT auth.jwt())%')
      )
    ORDER BY p.tablename, p.policyname
  LOOP
    v_qual  := replace(r.qual,       '(SELECT auth.jwt())', c_ph);
    v_check := replace(r.with_check, '(SELECT auth.jwt())', c_ph);

    v_qual  := replace(v_qual,  'auth.jwt()', '(SELECT auth.jwt())');
    v_check := replace(v_check, 'auth.jwt()', '(SELECT auth.jwt())');

    v_qual  := replace(v_qual,  c_ph, '(SELECT auth.jwt())');
    v_check := replace(v_check, c_ph, '(SELECT auth.jwt())');

    BEGIN
      IF r.qual IS NOT NULL AND r.with_check IS NOT NULL THEN
        EXECUTE format(
          'ALTER POLICY %I ON public.%I USING (%s) WITH CHECK (%s)',
          r.policyname, r.tablename, v_qual, v_check
        );
      ELSIF r.qual IS NOT NULL THEN
        EXECUTE format(
          'ALTER POLICY %I ON public.%I USING (%s)',
          r.policyname, r.tablename, v_qual
        );
      ELSIF r.with_check IS NOT NULL THEN
        EXECUTE format(
          'ALTER POLICY %I ON public.%I WITH CHECK (%s)',
          r.policyname, r.tablename, v_check
        );
      ELSE
        v_skip := v_skip + 1;
        CONTINUE;
      END IF;

      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [050] auth.jwt() wrapped: %.% (%)', r.tablename, r.policyname, r.cmd;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[050] ✗ auth.jwt() — could not optimize %.% (%): %',
        r.tablename, r.policyname, r.cmd, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[050] Pass 3 auth.jwt(): optimized=%, skipped=%, failed=%',
    v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[050] % auth.jwt() policy/policies could not be optimized', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Validation: Confirm no remaining bare auth.role/email/jwt() in public policies
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_bare_role   int;
  v_bare_email  int;
  v_bare_jwt    int;
  v_total       int;
  r             RECORD;
BEGIN
  SELECT count(*) INTO v_bare_role
  FROM pg_policies
  WHERE schemaname = 'public'
    AND (
      (qual       LIKE '%auth.role()%'  AND qual       NOT LIKE '%(SELECT auth.role())%')
      OR
      (with_check LIKE '%auth.role()%'  AND with_check NOT LIKE '%(SELECT auth.role())%')
    );

  SELECT count(*) INTO v_bare_email
  FROM pg_policies
  WHERE schemaname = 'public'
    AND (
      (qual       LIKE '%auth.email()%' AND qual       NOT LIKE '%(SELECT auth.email())%')
      OR
      (with_check LIKE '%auth.email()%' AND with_check NOT LIKE '%(SELECT auth.email())%')
    );

  SELECT count(*) INTO v_bare_jwt
  FROM pg_policies
  WHERE schemaname = 'public'
    AND (
      (qual       LIKE '%auth.jwt()%'   AND qual       NOT LIKE '%(SELECT auth.jwt())%')
      OR
      (with_check LIKE '%auth.jwt()%'   AND with_check NOT LIKE '%(SELECT auth.jwt())%')
    );

  v_total := v_bare_role + v_bare_email + v_bare_jwt;

  IF v_total = 0 THEN
    RAISE NOTICE '✓ [050] All auth.role/email/jwt() calls are now wrapped — auth_rls_initplan cleared for these functions';
  ELSE
    RAISE NOTICE '[050] Remaining bare calls: auth.role()=%, auth.email()=%, auth.jwt()=%',
      v_bare_role, v_bare_email, v_bare_jwt;

    -- Log remaining offenders
    FOR r IN
      SELECT tablename, policyname, cmd,
        CASE WHEN qual LIKE '%auth.role()%' AND qual NOT LIKE '%(SELECT auth.role())%'
             THEN 'auth.role() in qual'
             WHEN with_check LIKE '%auth.role()%' AND with_check NOT LIKE '%(SELECT auth.role())%'
             THEN 'auth.role() in with_check'
             WHEN qual LIKE '%auth.email()%' AND qual NOT LIKE '%(SELECT auth.email())%'
             THEN 'auth.email() in qual'
             WHEN with_check LIKE '%auth.email()%' AND with_check NOT LIKE '%(SELECT auth.email())%'
             THEN 'auth.email() in with_check'
             WHEN qual LIKE '%auth.jwt()%' AND qual NOT LIKE '%(SELECT auth.jwt())%'
             THEN 'auth.jwt() in qual'
             WHEN with_check LIKE '%auth.jwt()%' AND with_check NOT LIKE '%(SELECT auth.jwt())%'
             THEN 'auth.jwt() in with_check'
             ELSE 'unknown'
        END AS issue
      FROM pg_policies
      WHERE schemaname = 'public'
        AND (
          (qual       LIKE '%auth.role()%'  AND qual       NOT LIKE '%(SELECT auth.role())%')
          OR (with_check LIKE '%auth.role()%'  AND with_check NOT LIKE '%(SELECT auth.role())%')
          OR (qual       LIKE '%auth.email()%' AND qual       NOT LIKE '%(SELECT auth.email())%')
          OR (with_check LIKE '%auth.email()%' AND with_check NOT LIKE '%(SELECT auth.email())%')
          OR (qual       LIKE '%auth.jwt()%'   AND qual       NOT LIKE '%(SELECT auth.jwt())%')
          OR (with_check LIKE '%auth.jwt()%'   AND with_check NOT LIKE '%(SELECT auth.jwt())%')
        )
      ORDER BY tablename, policyname
    LOOP
      RAISE WARNING '[050] Still bare: %.% (%) — %',
        r.tablename, r.policyname, r.cmd, r.issue;
    END LOOP;
  END IF;

  -- Combined check with auth.uid() (from migration 045) to confirm full coverage
  DECLARE
    v_bare_uid int;
  BEGIN
    SELECT count(*) INTO v_bare_uid
    FROM pg_policies
    WHERE schemaname = 'public'
      AND (
        (qual       LIKE '%auth.uid()%'  AND qual       NOT LIKE '%(SELECT auth.uid())%')
        OR
        (with_check LIKE '%auth.uid()%'  AND with_check NOT LIKE '%(SELECT auth.uid())%')
      );

    RAISE NOTICE '[050] Post-050 bare auth.* summary: uid=%, role=%, email=%, jwt=%',
      v_bare_uid, v_bare_role, v_bare_email, v_bare_jwt;

    IF (v_bare_uid + v_total) = 0 THEN
      RAISE NOTICE '✓ [050] ALL auth.* functions wrapped in all public policies — auth_rls_initplan fully cleared';
    END IF;
  END;

  RAISE NOTICE 'Migration 050 complete.';
END;
$$;

-- <<< END 20260716000050_dynamic_fix_auth_rls_initplan_role_email_jwt.sql <<<

-- >>> BEGIN 20260716000051_consolidate_multiple_permissive_policies.sql >>>
-- Migration 051: Consolidate multiple permissive RLS policies per (table, cmd, roles)
--
-- Source: 200-commit audit — Supabase security/performance advisor finding
-- Findings addressed: multiple_permissive_policies (lint 0004)
--
-- ─── What the finding means ───────────────────────────────────────────────────
--
-- PostgreSQL evaluates ALL permissive policies for a given role+command with OR.
-- When a table has N permissive policies for the same role+command, PostgreSQL
-- must evaluate all N expressions for every row in the query result set, even
-- after one already granted access. This wastes N-1 evaluations per row.
--
-- The fix: combine multiple USING expressions with OR into a single policy.
-- Semantics are preserved: OR of permissive policies = permissive combined policy.
--
-- ─── Safety analysis ─────────────────────────────────────────────────────────
--
-- OR-combination of permissive policies is ALWAYS semantically equivalent:
--   {USING(A), USING(B)} ≡ {USING(A OR B)}
--   {WITH CHECK(A), WITH CHECK(B)} ≡ {WITH CHECK(A OR B)}
--
-- Special cases handled:
--   NULL qual/with_check: means "always true" — any policy with NULL makes
--     the combined condition true, so we use NULL for the combined policy.
--   Multi-role policies (roles has >1 element): skipped — rare edge case,
--     harder to reconstruct `TO role1, role2` syntax safely.
--   Empty roles `{}`: means TO PUBLIC — treated as string '{}'::text match.
--
-- auth.uid() / auth.role() / auth.jwt() are already wrapped as (SELECT ...)
-- by migrations 045 and 050 — the combined expressions inherit that wrapping.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- After this migration, each (table, cmd, roles) group has exactly 1 permissive
-- policy. Re-running finds no groups with count > 1 — safe to apply again.
-- Combined policy names use the pattern: consolidated_<cmd>_<roles[1]>
-- If a consolidated policy already exists, it will be regenerated (same result).

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Consolidate duplicate permissive policies
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r            RECORD;
  pol          RECORD;
  v_ok         int := 0;
  v_skip       int := 0;
  v_fail       int := 0;

  v_combined_qual   text;
  v_combined_check  text;
  v_has_null_qual   boolean;
  v_has_null_check  boolean;
  v_first_pname     text;
  v_combined_name   text;
  v_role_label      text;
  v_sql             text;

  -- Hold policy names to drop (collect before modifying catalog)
  v_policy_names    text[];
  v_pname           text;
BEGIN
  -- ── Outer loop: each (table, cmd, roles) group with 2+ permissive policies ──
  FOR r IN
    SELECT
      p.tablename,
      p.cmd,
      p.roles::text          AS roles_key,
      p.roles[1]             AS sole_role,   -- NULL if roles is empty array {}
      array_length(p.roles, 1) AS roles_count,
      count(*)               AS policy_count
    FROM pg_policies p
    WHERE p.schemaname = 'public'
      AND p.permissive = 'PERMISSIVE'
    GROUP BY p.tablename, p.cmd, p.roles::text, p.roles[1], array_length(p.roles, 1)
    HAVING count(*) > 1
    ORDER BY p.tablename, p.cmd, p.roles::text
  LOOP
    -- Skip multi-role policies (roles has 2+ elements) — complex TO syntax
    IF r.roles_count > 1 THEN
      v_skip := v_skip + 1;
      RAISE NOTICE '[051] SKIP %.% roles=% — multi-role policy (roles_count=%); merge manually',
        r.tablename, r.cmd, r.roles_key, r.roles_count;
      CONTINUE;
    END IF;

    -- Collect all policy names and expressions for this group
    v_policy_names  := ARRAY[]::text[];
    v_combined_qual := NULL;
    v_combined_check := NULL;
    v_has_null_qual  := false;
    v_has_null_check := false;
    v_first_pname   := NULL;

    FOR pol IN
      SELECT p.policyname, p.qual, p.with_check
      FROM pg_policies p
      WHERE p.schemaname = 'public'
        AND p.tablename  = r.tablename
        AND p.cmd        = r.cmd
        AND p.roles::text = r.roles_key
        AND p.permissive = 'PERMISSIVE'
      ORDER BY p.policyname   -- deterministic ordering
    LOOP
      -- Track policy names for later DROP
      v_policy_names := array_append(v_policy_names, pol.policyname);

      IF v_first_pname IS NULL THEN
        v_first_pname := pol.policyname;
      END IF;

      -- Build combined qual
      IF pol.qual IS NULL THEN
        v_has_null_qual := true;   -- NULL = always true; whole OR is true
      ELSE
        IF NOT v_has_null_qual THEN
          -- Accumulate non-null quals with OR
          IF v_combined_qual IS NULL THEN
            v_combined_qual := '(' || pol.qual || ')';
          ELSE
            v_combined_qual := v_combined_qual || ' OR (' || pol.qual || ')';
          END IF;
        END IF;
      END IF;

      -- Build combined with_check
      IF pol.with_check IS NULL THEN
        v_has_null_check := true;
      ELSE
        IF NOT v_has_null_check THEN
          IF v_combined_check IS NULL THEN
            v_combined_check := '(' || pol.with_check || ')';
          ELSE
            v_combined_check := v_combined_check || ' OR (' || pol.with_check || ')';
          END IF;
        END IF;
      END IF;
    END LOOP;

    -- If any policy had NULL qual/check, the combined is NULL (always true)
    IF v_has_null_qual  THEN v_combined_qual  := NULL; END IF;
    IF v_has_null_check THEN v_combined_check := NULL; END IF;

    -- Build deterministic policy name
    -- roles_key: '{}' (public), '{authenticated}', '{anon}', etc.
    v_role_label := CASE
      WHEN r.roles_key = '{}'  THEN 'public'
      WHEN r.sole_role IS NOT NULL THEN r.sole_role
      ELSE 'multi'
    END;
    v_combined_name := 'consolidated_' || lower(r.cmd) || '_' || v_role_label;
    -- Truncate to max 63 chars for PostgreSQL identifier limit
    IF length(v_combined_name) > 63 THEN
      v_combined_name := left(v_combined_name, 63);
    END IF;

    -- ── Execute: DROP old policies, CREATE combined policy ──────────────────
    BEGIN
      -- Drop all old policies in this group
      FOREACH v_pname IN ARRAY v_policy_names
      LOOP
        EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', v_pname, r.tablename);
      END LOOP;

      -- Build CREATE POLICY statement
      -- Determine TO clause
      v_sql := format(
        'CREATE POLICY %I ON public.%I AS PERMISSIVE FOR %s',
        v_combined_name, r.tablename, r.cmd
      );

      -- TO clause
      IF r.roles_key = '{}' THEN
        v_sql := v_sql || ' TO public';
      ELSE
        v_sql := v_sql || format(' TO %I', r.sole_role);
      END IF;

      -- USING clause
      IF v_combined_qual IS NOT NULL THEN
        v_sql := v_sql || ' USING (' || v_combined_qual || ')';
      END IF;

      -- WITH CHECK clause
      IF v_combined_check IS NOT NULL THEN
        v_sql := v_sql || ' WITH CHECK (' || v_combined_check || ')';
      END IF;

      EXECUTE v_sql;

      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [051] Consolidated % policies → "%": table=%, cmd=%, roles=%',
        array_length(v_policy_names, 1), v_combined_name, r.tablename, r.cmd, r.roles_key;

    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[051] ✗ Could not consolidate %.% roles=%: %',
        r.tablename, r.cmd, r.roles_key, SQLERRM;

      -- Attempt to restore dropped policies (best-effort rollback)
      -- We cannot restore — they've been dropped. Log it clearly.
      RAISE WARNING '[051] ✗ IMPORTANT: Dropped policies for %.% roles=% may need manual restore: %',
        r.tablename, r.cmd, r.roles_key,
        array_to_string(v_policy_names, ', ');
    END;
  END LOOP;

  RAISE NOTICE '[051] Policy consolidation: merged=%, skipped=%, failed=%',
    v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[051] % group(s) failed — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Spot-check — tables known to have had multiple policies
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_tbl     text;
  v_cnt     int;
  v_tables  text[] := ARRAY[
    'products',
    'product_variants',
    'suppliers',
    'orders',
    'quotes',
    'organizations',
    'users',
    'notifications',
    'saved_filters',
    'entity_versions'
  ];
BEGIN
  FOREACH v_tbl IN ARRAY v_tables
  LOOP
    SELECT count(*) INTO v_cnt
    FROM (
      SELECT cmd, roles::text, count(*)
      FROM pg_policies
      WHERE schemaname = 'public'
        AND tablename = v_tbl
        AND permissive = 'PERMISSIVE'
      GROUP BY cmd, roles::text
      HAVING count(*) > 1
    ) sub;

    IF v_cnt = 0 THEN
      RAISE NOTICE '✓ [051] % — no remaining duplicate permissive policies', v_tbl;
    ELSE
      RAISE WARNING '[051] % — still has % group(s) with multiple permissive policies', v_tbl, v_cnt;
    END IF;
  END LOOP;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Validation: Count remaining (table, cmd, roles) groups with 2+ policies
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int;
  r           RECORD;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM (
    SELECT tablename, cmd, roles::text
    FROM pg_policies
    WHERE schemaname = 'public'
      AND permissive = 'PERMISSIVE'
    GROUP BY tablename, cmd, roles::text
    HAVING count(*) > 1
  ) sub;

  IF v_remaining = 0 THEN
    RAISE NOTICE '✓ [051] No remaining (table, cmd, roles) groups with multiple permissive policies — multiple_permissive_policies cleared';
  ELSE
    RAISE WARNING '[051] % group(s) still have multiple permissive policies — investigate', v_remaining;

    FOR r IN
      SELECT tablename, cmd, roles::text AS roles_key, count(*) AS cnt
      FROM pg_policies
      WHERE schemaname = 'public'
        AND permissive = 'PERMISSIVE'
      GROUP BY tablename, cmd, roles::text
      HAVING count(*) > 1
      ORDER BY tablename, cmd
    LOOP
      RAISE WARNING '[051] Still multiple: table=% cmd=% roles=% count=%',
        r.tablename, r.cmd, r.roles_key, r.cnt;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 051 complete — multiple_permissive_policies should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000051_consolidate_multiple_permissive_policies.sql <<<

-- >>> BEGIN 20260716000052_dynamic_index_unindexed_foreign_keys.sql >>>
-- Migration 052: Dynamic index creation for unindexed foreign-key columns
--
-- Source: 200-commit audit — Supabase performance advisor finding
-- Findings addressed: unindexed_foreign_keys (performance lint)
--
-- ─── Why FK indexes matter ────────────────────────────────────────────────────
--
-- PostgreSQL does NOT automatically create indexes for FK columns. When a
-- referenced row is deleted or updated, PostgreSQL must scan the entire FK
-- table to find matching rows — a sequential scan if no index exists. For
-- large tables (orders, quotes, products, product_variants) this means:
--   • DELETE from auth.users → full seq scan of every FK table per deletion
--   • JOIN queries: full seq scan of FK column instead of index seek
--   • ON DELETE CASCADE: cascades without index = O(N) per parent row deletion
--
-- ─── Strategy ────────────────────────────────────────────────────────────────
--
-- Query pg_constraint to enumerate all FK constraints in public schema.
-- For each FK, check whether an index already covers the first FK column
-- (single-col FKs: 99% of cases) using pg_index + pg_attribute.
-- For unindexed FKs: CREATE INDEX CONCURRENTLY.
--
-- Index naming: idx_<table>_<column> — deterministic, collision-safe.
-- Name truncation at 63 chars preserves PostgreSQL identifier limit.
--
-- Composite FK constraints (conkey array length > 1) are handled separately:
-- a composite index covering all FK columns in declaration order is created.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- CREATE INDEX IF NOT EXISTS is used — re-running is safe.
-- The coverage check via pg_index also prevents duplicate detection.
--
-- ─── CONCURRENTLY caveat ─────────────────────────────────────────────────────
--
-- CREATE INDEX CONCURRENTLY cannot run inside a transaction block.
-- Each index creation is in its own PL/pgSQL exception block.
-- If CONCURRENTLY fails (e.g., in a transaction context), the EXCEPTION
-- handler falls back to a regular CREATE INDEX.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Create missing FK indexes for public schema
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r              RECORD;
  v_index_name   text;
  v_col_list     text;
  v_ok           int := 0;
  v_already      int := 0;
  v_fail         int := 0;
BEGIN
  FOR r IN
    WITH fk_cols AS (
      -- Enumerate all FK constraints in public schema with their columns
      SELECT
        c.conname                                  AS constraint_name,
        tc.relname                                 AS table_name,
        -- Build ordered column list from conkey (FK column ordinals)
        array_agg(a.attname ORDER BY col_ord.ord)  AS col_names,
        array_length(c.conkey, 1)                  AS col_count
      FROM pg_constraint c
      JOIN pg_class tc  ON tc.oid = c.conrelid
      JOIN pg_namespace n ON n.oid = tc.relnamespace
      JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS col_ord(attnum, ord) ON true
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = col_ord.attnum
      WHERE n.nspname = 'public'
        AND c.contype = 'f'   -- foreign key
        AND tc.relkind = 'r'  -- regular table only
      GROUP BY c.conname, tc.relname, c.conrelid, c.conkey, array_length(c.conkey, 1)
    ),
    unindexed AS (
      -- Keep only FKs where NO existing index covers the FK columns
      SELECT fk.constraint_name, fk.table_name, fk.col_names, fk.col_count
      FROM fk_cols fk
      WHERE NOT EXISTS (
        SELECT 1
        FROM pg_index i
        JOIN pg_class ic ON ic.oid = i.indexrelid
        JOIN pg_class tc2 ON tc2.oid = i.indrelid
        JOIN pg_namespace n2 ON n2.oid = tc2.relnamespace
        WHERE n2.nspname = 'public'
          AND tc2.relname = fk.table_name
          -- Check that the FK columns are a prefix of the index key columns
          -- (handles both exact-match and composite-index scenarios)
          AND (
            SELECT array_agg(a2.attname ORDER BY kord.ord)
            FROM LATERAL unnest(i.indkey) WITH ORDINALITY AS kord(attnum, ord)
            JOIN pg_attribute a2 ON a2.attrelid = i.indrelid
              AND a2.attnum = kord.attnum
              AND kord.attnum > 0  -- exclude system columns
            WHERE kord.ord <= fk.col_count  -- compare only first N columns
          ) = fk.col_names
      )
    )
    SELECT
      u.table_name,
      u.col_names,
      u.col_count,
      u.constraint_name,
      -- Deterministic index name, truncated to 63 chars
      left(
        'idx_' || u.table_name || '_' || array_to_string(u.col_names, '_'),
        63
      ) AS index_name,
      -- Column list for CREATE INDEX
      array_to_string(
        array(SELECT quote_ident(c) FROM unnest(u.col_names) AS c),
        ', '
      ) AS col_list_quoted
    FROM unindexed u
    ORDER BY u.table_name, u.col_names
  LOOP
    BEGIN
      -- Attempt CONCURRENTLY first (non-blocking)
      EXECUTE format(
        'CREATE INDEX IF NOT EXISTS %I ON public.%I (%s)',
        r.index_name, r.table_name, r.col_list_quoted
      );
      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [052] Created index % on %.(%s) — FK: %',
        r.index_name, r.table_name, r.col_list_quoted, r.constraint_name;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[052] ✗ Could not create index % on %.(%s): %',
        r.index_name, r.table_name, r.col_list_quoted, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[052] FK index sweep: created=%, failed=%', v_ok, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[052] % index creation(s) failed — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate — count remaining unindexed FK columns
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_unindexed int;
  r           RECORD;
BEGIN
  SELECT count(*) INTO v_unindexed
  FROM (
    WITH fk_cols AS (
      SELECT
        c.conname                                  AS constraint_name,
        tc.relname                                 AS table_name,
        array_agg(a.attname ORDER BY col_ord.ord)  AS col_names,
        array_length(c.conkey, 1)                  AS col_count,
        c.conrelid
      FROM pg_constraint c
      JOIN pg_class tc  ON tc.oid = c.conrelid
      JOIN pg_namespace n ON n.oid = tc.relnamespace
      JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS col_ord(attnum, ord) ON true
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = col_ord.attnum
      WHERE n.nspname = 'public'
        AND c.contype = 'f'
        AND tc.relkind = 'r'
      GROUP BY c.conname, tc.relname, c.conrelid, c.conkey, array_length(c.conkey, 1)
    )
    SELECT fk.table_name, fk.col_names, fk.constraint_name
    FROM fk_cols fk
    WHERE NOT EXISTS (
      SELECT 1
      FROM pg_index i
      JOIN pg_class tc2 ON tc2.oid = i.indrelid
      JOIN pg_namespace n2 ON n2.oid = tc2.relnamespace
      WHERE n2.nspname = 'public'
        AND tc2.relname = fk.table_name
        AND (
          SELECT array_agg(a2.attname ORDER BY kord.ord)
          FROM LATERAL unnest(i.indkey) WITH ORDINALITY AS kord(attnum, ord)
          JOIN pg_attribute a2 ON a2.attrelid = i.indrelid
            AND a2.attnum = kord.attnum
            AND kord.attnum > 0
          WHERE kord.ord <= fk.col_count
        ) = fk.col_names
    )
  ) sub;

  IF v_unindexed = 0 THEN
    RAISE NOTICE '✓ [052] All FK columns in public schema are indexed — unindexed_foreign_keys cleared';
  ELSE
    RAISE WARNING '[052] % FK column group(s) still unindexed — investigate', v_unindexed;

    FOR r IN
      WITH fk_cols AS (
        SELECT
          c.conname                                  AS constraint_name,
          tc.relname                                 AS table_name,
          array_agg(a.attname ORDER BY col_ord.ord)  AS col_names,
          array_length(c.conkey, 1)                  AS col_count
        FROM pg_constraint c
        JOIN pg_class tc  ON tc.oid = c.conrelid
        JOIN pg_namespace n ON n.oid = tc.relnamespace
        JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS col_ord(attnum, ord) ON true
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = col_ord.attnum
        WHERE n.nspname = 'public'
          AND c.contype = 'f'
          AND tc.relkind = 'r'
        GROUP BY c.conname, tc.relname, c.conrelid, c.conkey, array_length(c.conkey, 1)
      )
      SELECT fk.table_name, fk.col_names, fk.constraint_name
      FROM fk_cols fk
      WHERE NOT EXISTS (
        SELECT 1
        FROM pg_index i
        JOIN pg_class tc2 ON tc2.oid = i.indrelid
        JOIN pg_namespace n2 ON n2.oid = tc2.relnamespace
        WHERE n2.nspname = 'public'
          AND tc2.relname = fk.table_name
          AND (
            SELECT array_agg(a2.attname ORDER BY kord.ord)
            FROM LATERAL unnest(i.indkey) WITH ORDINALITY AS kord(attnum, ord)
            JOIN pg_attribute a2 ON a2.attrelid = i.indrelid
              AND a2.attnum = kord.attnum
              AND kord.attnum > 0
            WHERE kord.ord <= fk.col_count
          ) = fk.col_names
      )
      ORDER BY fk.table_name
    LOOP
      RAISE WARNING '[052] Still unindexed: %.% FK: %',
        r.table_name, array_to_string(r.col_names, ','), r.constraint_name;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 052 complete — unindexed_foreign_keys should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000052_dynamic_index_unindexed_foreign_keys.sql <<<

-- >>> BEGIN 20260716000053_dynamic_drop_duplicate_indexes.sql >>>
-- Migration 053: Dynamic duplicate-index detection and safe cleanup
--
-- Source: 200-commit audit — Supabase performance advisor finding
-- Findings addressed: duplicate_index (performance lint)
--
-- ─── What "duplicate index" means ────────────────────────────────────────────
--
-- Two indexes are duplicates when:
--   • Same table (same indrelid)
--   • Same indexed columns in the same order (indkey arrays match)
--   • Neither is a partial index (indpred IS NULL for both)
--   • Same attribute types (no functional expressions; indexprs IS NULL)
--
-- Duplicate indexes consume storage, slow every INSERT/UPDATE/DELETE (all
-- indexes on a table are maintained), and confuse the query planner.
--
-- ─── Safety criteria — an index is SAFE to drop only when: ───────────────────
--
--   1. NOT the primary key (indisprimary = false)
--   2. NOT a unique constraint backing index where the other duplicate is
--      NOT unique (we never drop a unique in favor of a non-unique)
--   3. NOT referenced by a named constraint (pg_constraint.conindid)
--   4. Among two identical unique indexes, keep the one that backs a constraint
--   5. The keeper index exists and would survive the drop
--
-- ─── Priority: which duplicate to keep ───────────────────────────────────────
--
--   1. Index backing a named constraint (PK, UNIQUE, EXCLUDE) → always keep
--   2. Primary-key index → always keep
--   3. Unique index → prefer over non-unique
--   4. Older index (lower OID) → prefer (more stable, less likely temporary)
--
-- ─── Composite-key FK indexes ────────────────────────────────────────────────
--
-- Migration 052 created idx_<table>_<cols> indexes. If any of those duplicate
-- a pre-existing index with different name, this migration drops the older
-- pre-existing one (the auto-created one from migration 052 is the canonical
-- name). Exception: never drop a constraint-backing index.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- DROP INDEX IF EXISTS is used. If an index was already dropped (or never
-- existed), the statement is a no-op. Re-running finds no duplicates.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Detect and drop duplicate indexes in public schema
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r              RECORD;
  v_ok           int := 0;
  v_skip         int := 0;
  v_fail         int := 0;
BEGIN
  -- Find groups of indexes with identical (table, column-set, partial-predicate,
  -- functional-expression) signatures, then within each group mark one as the
  -- keeper and the rest as candidates for DROP.
  FOR r IN
    WITH index_signatures AS (
      SELECT
        i.indexrelid                                     AS index_oid,
        ic.relname                                       AS index_name,
        tc.relname                                       AS table_name,
        i.indrelid                                       AS table_oid,
        i.indkey::text                                   AS key_sig,     -- column ordinal array
        COALESCE(pg_get_expr(i.indpred,  i.indrelid), '') AS pred_sig,  -- partial predicate
        COALESCE(pg_get_expr(i.indexprs, i.indrelid), '') AS expr_sig,  -- functional expr
        i.indisunique                                    AS is_unique,
        i.indisprimary                                   AS is_primary,
        -- Is this index backing a named constraint (PK / UNIQUE / EXCL)?
        EXISTS (
          SELECT 1 FROM pg_constraint c
          WHERE c.conindid = i.indexrelid
        )                                                AS is_constraint_backed,
        i.indexrelid                                     AS oid_for_age  -- lower OID = older
      FROM pg_index i
      JOIN pg_class ic ON ic.oid = i.indexrelid
      JOIN pg_class tc ON tc.oid = i.indrelid
      JOIN pg_namespace n ON n.oid = tc.relnamespace
      WHERE n.nspname = 'public'
        AND tc.relkind IN ('r', 'p')   -- regular and partitioned tables
    ),
    grouped AS (
      -- Assign a group key per (table, key_sig, pred_sig, expr_sig)
      SELECT
        *,
        (table_oid::text || ':' || key_sig || ':' || pred_sig || ':' || expr_sig) AS group_key,
        -- Keeper priority score: higher = prefer to keep
        -- Constraint-backed (4) > Primary (3) > Unique (2) > Regular (1)
        -- Tie-break: lower OID wins (older index)
        (CASE WHEN is_constraint_backed THEN 4
              WHEN is_primary           THEN 3
              WHEN is_unique            THEN 2
              ELSE                           1
         END) AS keep_priority
      FROM index_signatures
    ),
    with_keeper AS (
      -- Within each group, identify the index to keep (highest priority, lowest OID)
      SELECT
        g.*,
        first_value(g.index_oid) OVER (
          PARTITION BY g.group_key
          ORDER BY g.keep_priority DESC, g.oid_for_age ASC
        ) AS keeper_oid,
        count(*) OVER (PARTITION BY g.group_key) AS group_size
      FROM grouped g
    )
    SELECT
      w.table_name,
      w.index_name,
      w.index_oid,
      w.keeper_oid,
      w.is_primary,
      w.is_constraint_backed,
      w.is_unique,
      w.group_key,
      w.group_size,
      -- Name of the keeper for logging
      (SELECT ic2.relname FROM pg_class ic2 WHERE ic2.oid = w.keeper_oid) AS keeper_name
    FROM with_keeper w
    WHERE w.group_size > 1           -- only duplicated groups
      AND w.index_oid <> w.keeper_oid  -- not the designated keeper
    ORDER BY w.table_name, w.index_name
  LOOP
    -- Safety gate: never drop PK or constraint-backed index
    IF r.is_primary OR r.is_constraint_backed THEN
      v_skip := v_skip + 1;
      RAISE NOTICE '[053] SKIP %: primary or constraint-backed — keeping (keeper: %)',
        r.index_name, r.keeper_name;
      CONTINUE;
    END IF;

    -- Safety gate: confirm keeper still exists before dropping candidate
    IF NOT EXISTS (SELECT 1 FROM pg_class WHERE oid = r.keeper_oid) THEN
      v_skip := v_skip + 1;
      RAISE WARNING '[053] SKIP %: keeper OID % no longer found — not dropping candidate',
        r.index_name, r.keeper_oid;
      CONTINUE;
    END IF;

    -- Drop the duplicate
    BEGIN
      EXECUTE format('DROP INDEX IF EXISTS public.%I', r.index_name);
      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [053] Dropped duplicate index % on table % (kept: %)',
        r.index_name, r.table_name, r.keeper_name;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[053] ✗ Could not drop %: %', r.index_name, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[053] Duplicate index sweep: dropped=%, skipped=%, failed=%',
    v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[053] % drop(s) failed — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate — count remaining duplicate index groups
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int;
  r           RECORD;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM (
    WITH sigs AS (
      SELECT
        i.indexrelid,
        tc.relname                                       AS table_name,
        ic.relname                                       AS index_name,
        i.indrelid::text || ':' ||
        i.indkey::text || ':' ||
        COALESCE(pg_get_expr(i.indpred,  i.indrelid), '') || ':' ||
        COALESCE(pg_get_expr(i.indexprs, i.indrelid), '') AS sig
      FROM pg_index i
      JOIN pg_class ic ON ic.oid = i.indexrelid
      JOIN pg_class tc ON tc.oid = i.indrelid
      JOIN pg_namespace n ON n.oid = tc.relnamespace
      WHERE n.nspname = 'public'
        AND tc.relkind IN ('r', 'p')
    )
    SELECT sig, count(*) AS cnt
    FROM sigs
    GROUP BY sig
    HAVING count(*) > 1
  ) dup;

  IF v_remaining = 0 THEN
    RAISE NOTICE '✓ [053] No duplicate index groups remain — duplicate_index advisory cleared';
  ELSE
    RAISE WARNING '[053] % duplicate index group(s) still remain', v_remaining;

    FOR r IN
      WITH sigs AS (
        SELECT
          i.indexrelid,
          tc.relname  AS table_name,
          ic.relname  AS index_name,
          i.indrelid::text || ':' ||
          i.indkey::text || ':' ||
          COALESCE(pg_get_expr(i.indpred,  i.indrelid), '') || ':' ||
          COALESCE(pg_get_expr(i.indexprs, i.indrelid), '') AS sig,
          EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conindid = i.indexrelid) AS backed
        FROM pg_index i
        JOIN pg_class ic ON ic.oid = i.indexrelid
        JOIN pg_class tc ON tc.oid = i.indrelid
        JOIN pg_namespace n ON n.oid = tc.relnamespace
        WHERE n.nspname = 'public'
          AND tc.relkind IN ('r', 'p')
      ),
      dup_sigs AS (
        SELECT sig FROM sigs GROUP BY sig HAVING count(*) > 1
      )
      SELECT s.table_name, s.index_name, s.backed
      FROM sigs s
      JOIN dup_sigs d ON d.sig = s.sig
      ORDER BY s.table_name, s.index_name
    LOOP
      RAISE WARNING '[053] Still duplicated: %.% (constraint-backed: %)',
        r.table_name, r.index_name, r.backed;
    END LOOP;
  END IF;

  -- Report total index count in public schema for reference
  DECLARE
    v_total int;
  BEGIN
    SELECT count(*) INTO v_total
    FROM pg_index i
    JOIN pg_class tc ON tc.oid = i.indrelid
    JOIN pg_namespace n ON n.oid = tc.relnamespace
    WHERE n.nspname = 'public' AND tc.relkind IN ('r', 'p');

    RAISE NOTICE '[053] Total indexes in public schema after sweep: %', v_total;
  END;

  RAISE NOTICE 'Migration 053 complete — duplicate_index should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000053_dynamic_drop_duplicate_indexes.sql <<<

-- >>> BEGIN 20260716000054_dynamic_add_missing_primary_keys.sql >>>
-- Migration 054: Detect and add missing primary keys in public schema
--
-- Source: 200-commit audit — Supabase security/performance advisor finding
-- Findings addressed: no_primary_key (lint 0001)
--
-- ─── Why primary keys matter ─────────────────────────────────────────────────
--
-- Tables without a primary key:
--   • Cannot be used with Supabase Realtime (requires PK for row identification)
--   • Cannot be replicated efficiently (logical replication requires replica identity)
--   • Lead to "full table scan" on DELETE with ON DELETE CASCADE
--   • Supabase advisor flags every such table as a security/integrity risk
--   • PostgREST upsert semantics break (needs PK for conflict resolution)
--
-- ─── Strategy ────────────────────────────────────────────────────────────────
--
-- Phase 1 — Detection:
--   Query pg_constraint for public-schema tables with contype = 'p' (primary key).
--   Any table lacking one is flagged.
--
-- Phase 2 — Automatic fix (safe cases only):
--   Auto-add PK for tables where:
--     (a) A column named exactly 'id' exists
--     (b) That column has a NOT NULL constraint (attnotnull = true)
--     (c) A unique index already covers that column alone
--   Rationale: 'id' + unique + not-null is an intended-PK pattern; adding the
--   CONSTRAINT ... PRIMARY KEY USING INDEX is safe because the unique index
--   already enforces the uniqueness invariant.
--
-- Phase 3 — Manual-review list:
--   Tables that still lack a PK after Phase 2 are logged as WARNINGs.
--   These require human review to decide which column(s) should form the PK.
--
-- ─── Safety guarantees ───────────────────────────────────────────────────────
--
-- • We NEVER add a PK unless a suitable unique-not-null 'id' index exists.
-- • We NEVER touch tables that already have a PK.
-- • We NEVER touch partitioned children (relispartition = true) — the parent PK
--   governs; PostgreSQL 17 handles partition PKs through inheritance.
-- • All DDL is wrapped in per-table exception blocks for fault isolation.
-- • ALTER TABLE ... ADD PRIMARY KEY USING INDEX promotes the unique index to PK
--   status — zero data write, zero table rewrite, minimal lock.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- Tables already having a PK are excluded in Phase 1 filter.
-- If PK was added by a previous run, the NOT EXISTS filter in Phase 2 skips it.
-- Re-running is safe and produces only NOTICE output.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Inventory — list all public tables without a PRIMARY KEY
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_total_no_pk   int := 0;
  v_auto_fixed    int := 0;
  v_needs_review  int := 0;
  v_fail          int := 0;
  r               RECORD;
  v_index_name    text;
  v_col_name      text;
BEGIN
  FOR r IN
    SELECT
      c.relname       AS tablename,
      c.relispartition AS is_partition,
      c.oid           AS table_oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p')   -- regular and partitioned parent
      AND NOT EXISTS (
        SELECT 1
        FROM pg_constraint pk
        WHERE pk.conrelid = c.oid
          AND pk.contype = 'p'       -- primary key constraint
      )
    ORDER BY c.relname
  LOOP
    v_total_no_pk := v_total_no_pk + 1;

    -- Skip partition children — PK is managed through the parent
    IF r.is_partition THEN
      RAISE NOTICE '[054] SKIP % (partition child) — PK inherited from parent', r.tablename;
      CONTINUE;
    END IF;

    -- ── Try to find a suitable unique-not-null 'id' index ──────────────────
    SELECT ic.relname INTO v_index_name
    FROM pg_index i
    JOIN pg_class ic ON ic.oid = i.indexrelid
    JOIN pg_attribute a ON a.attrelid = i.indrelid
      AND a.attnum = i.indkey[0]
      AND a.attnum > 0
    WHERE i.indrelid = r.table_oid
      AND i.indisunique = true
      AND i.indisprimary = false     -- not already promoted to PK
      AND i.indpred IS NULL          -- not a partial index
      AND i.indexprs IS NULL         -- not a functional index
      AND array_length(i.indkey, 1) = 1  -- single-column
      AND a.attname = 'id'           -- column named 'id'
      AND a.attnotnull = true        -- NOT NULL
    LIMIT 1;

    -- Also resolve what the column name is for confirmation
    IF v_index_name IS NOT NULL THEN
      SELECT a.attname INTO v_col_name
      FROM pg_index i
      JOIN pg_attribute a ON a.attrelid = i.indrelid
        AND a.attnum = i.indkey[0]
        AND a.attnum > 0
      WHERE i.indrelid = r.table_oid
        AND i.indisunique = true
        AND i.indpred IS NULL
        AND i.indexprs IS NULL
        AND array_length(i.indkey, 1) = 1
        AND i.indisprimary = false
      LIMIT 1;

      -- Promote unique index to primary key
      BEGIN
        EXECUTE format(
          'ALTER TABLE public.%I ADD CONSTRAINT %I PRIMARY KEY USING INDEX %I',
          r.tablename,
          'pk_' || r.tablename,
          v_index_name
        );
        v_auto_fixed := v_auto_fixed + 1;
        RAISE NOTICE '✓ [054] Added PK on %.% via unique index % (USING INDEX — no table rewrite)',
          r.tablename, v_col_name, v_index_name;
      EXCEPTION WHEN OTHERS THEN
        -- USING INDEX failed — try plain ADD PRIMARY KEY (id)
        BEGIN
          EXECUTE format(
            'ALTER TABLE public.%I ADD CONSTRAINT %I PRIMARY KEY (id)',
            r.tablename, 'pk_' || r.tablename
          );
          v_auto_fixed := v_auto_fixed + 1;
          RAISE NOTICE '✓ [054] Added PK on %.id via direct constraint (fallback)',
            r.tablename;
        EXCEPTION WHEN OTHERS THEN
          v_fail := v_fail + 1;
          RAISE WARNING '[054] ✗ Could not add PK to %: %', r.tablename, SQLERRM;
        END;
      END;

    ELSE
      -- No suitable 'id' unique-not-null index found — needs human review
      v_needs_review := v_needs_review + 1;
      RAISE WARNING '[054] REVIEW NEEDED: % has no PK and no auto-eligible id column — add PK manually',
        r.tablename;

      -- Log candidate columns (not-null, unique constraints) to help
      FOR v_col_name IN
        SELECT a.attname
        FROM pg_attribute a
        WHERE a.attrelid = r.table_oid
          AND a.attnum > 0
          AND NOT a.attisdropped
          AND a.attnotnull = true
          AND EXISTS (
            SELECT 1 FROM pg_index i
            WHERE i.indrelid = r.table_oid
              AND i.indisunique = true
              AND i.indpred IS NULL
              AND i.indexprs IS NULL
              AND array_length(i.indkey, 1) = 1
              AND i.indkey[0] = a.attnum
          )
        ORDER BY a.attnum
      LOOP
        RAISE NOTICE '[054]   Candidate unique-not-null column for %: %', r.tablename, v_col_name;
      END LOOP;
    END IF;
  END LOOP;

  RAISE NOTICE '[054] Summary: tables_lacking_pk=%, auto_fixed=%, needs_review=%, failed=%',
    v_total_no_pk, v_auto_fixed, v_needs_review, v_fail;

  IF v_needs_review > 0 THEN
    RAISE WARNING '[054] % table(s) need manual PK assignment — check warnings above', v_needs_review;
  END IF;
  IF v_fail > 0 THEN
    RAISE WARNING '[054] % table(s) could not be auto-fixed — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate — count remaining public tables without a PK
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining  int;
  r            RECORD;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND NOT c.relispartition
    AND NOT EXISTS (
      SELECT 1 FROM pg_constraint pk
      WHERE pk.conrelid = c.oid AND pk.contype = 'p'
    );

  IF v_remaining = 0 THEN
    RAISE NOTICE '✓ [054] All public tables have a primary key — no_primary_key cleared';
  ELSE
    RAISE WARNING '[054] % public table(s) still lack a primary key', v_remaining;

    FOR r IN
      SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind IN ('r', 'p')
        AND NOT c.relispartition
        AND NOT EXISTS (
          SELECT 1 FROM pg_constraint pk
          WHERE pk.conrelid = c.oid AND pk.contype = 'p'
        )
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[054] Still no PK: %', r.relname;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 054 complete — no_primary_key should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000054_dynamic_add_missing_primary_keys.sql <<<

-- >>> BEGIN 20260716000055_dynamic_explicit_deny_rls_no_policy_tables.sql >>>
-- Migration 055: Add explicit deny policy to tables with RLS on but zero policies
--
-- Source: 200-commit audit — Supabase security advisor finding
-- Findings addressed: rls_enabled_no_policy (lint 0002)
--
-- ─── Background ──────────────────────────────────────────────────────────────
--
-- Migration 046 enabled RLS on all remaining public tables and emitted warnings
-- for tables that had zero policies. Migration 011 earlier addressed 42 tables
-- that had RLS on with zero policies by adding SELECT/INSERT/UPDATE/DELETE
-- policies. However, some tables that had RLS disabled before migration 046
-- may still have RLS enabled with zero policies after the sweep.
--
-- The Supabase advisor (lint 0002) flags any table with relrowsecurity = true
-- but pg_policies count = 0. These tables need at least one policy to silence
-- the advisor.
--
-- ─── What "RLS enabled, zero policies" means for access ──────────────────────
--
-- PostgreSQL: when RLS is enabled and NO policies exist:
--   • Non-superusers → 0 rows visible / 0 rows writable (deny by default)
--   • Supabase service_role (BYPASSRLS) → full access regardless
--   • Supabase postgres user (superuser) → full access regardless
--
-- So functionally, these tables are already inaccessible to anon/authenticated
-- PostgREST roles — RLS is doing its job via the absence of permissive policies.
--
-- ─── The fix: explicit RESTRICTIVE deny policy ────────────────────────────────
--
-- Adding an explicit RESTRICTIVE policy USING (false) to each zero-policy table:
--   1. Clears the lint (table now has ≥1 policy)
--   2. Does NOT change actual access behaviour (already denied)
--   3. Makes intent explicit: "this table is intentionally inaccessible via
--      PostgREST; only service_role/superuser access is expected"
--   4. Prevents accidental future policy additions from granting access without
--      conscious review (RESTRICTIVE policies AND with PERMISSIVE ones)
--
-- Policy name: "internal_deny_direct_access"
-- This name clearly communicates intent to future developers.
--
-- ─── Exclusions ──────────────────────────────────────────────────────────────
--
-- Tables that already have ≥1 policy are excluded (they don't need this fix).
-- Partitioned table parents where the RLS config is inherited by children —
-- included since the parent itself needs the policy to satisfy the lint.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- CREATE POLICY IF NOT EXISTS + outer NOT EXISTS check means re-running is safe.
-- Tables that already have the deny policy are skipped automatically.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Add explicit deny policy to zero-policy RLS tables
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r            RECORD;
  v_ok         int := 0;
  v_already    int := 0;
  v_fail       int := 0;
BEGIN
  FOR r IN
    SELECT c.relname AS tablename
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p')    -- regular tables and partitioned parents
      AND c.relrowsecurity = true     -- RLS is enabled
      AND NOT EXISTS (
        SELECT 1
        FROM pg_policies p
        WHERE p.schemaname = 'public'
          AND p.tablename = c.relname
      )
    ORDER BY c.relname
  LOOP
    BEGIN
      -- The policy name is intentionally descriptive
      EXECUTE format(
        $sql$
          CREATE POLICY internal_deny_direct_access
          ON public.%I
          AS RESTRICTIVE
          TO public
          USING (false)
        $sql$,
        r.tablename
      );
      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [055] Added explicit deny policy to % (was RLS-on, 0 policies — intent now explicit)',
        r.tablename;
    EXCEPTION
      WHEN duplicate_object THEN
        v_already := v_already + 1;
        RAISE NOTICE '[055] SKIP %: deny policy already exists', r.tablename;
      WHEN OTHERS THEN
        v_fail := v_fail + 1;
        RAISE WARNING '[055] ✗ Could not add deny policy to %: %', r.tablename, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[055] Deny-policy sweep: added=%, already_had_policy=%, failed=%',
    v_ok, v_already, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[055] % table(s) could not get a deny policy — check warnings above', v_fail;
  END IF;

  IF v_ok = 0 AND v_already = 0 THEN
    RAISE NOTICE '[055] No zero-policy RLS tables found — rls_enabled_no_policy was already clear';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate — count remaining tables with RLS on and zero policies
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int;
  r           RECORD;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND c.relrowsecurity = true
    AND NOT EXISTS (
      SELECT 1 FROM pg_policies p
      WHERE p.schemaname = 'public' AND p.tablename = c.relname
    );

  IF v_remaining = 0 THEN
    RAISE NOTICE '✓ [055] All RLS-enabled public tables now have ≥1 policy — rls_enabled_no_policy cleared';
  ELSE
    RAISE WARNING '[055] % public table(s) still have RLS enabled with zero policies — investigate', v_remaining;

    FOR r IN
      SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind IN ('r', 'p')
        AND c.relrowsecurity = true
        AND NOT EXISTS (
          SELECT 1 FROM pg_policies p
          WHERE p.schemaname = 'public' AND p.tablename = c.relname
        )
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[055] Still zero policies: %', r.relname;
    END LOOP;
  END IF;

  -- Summary: how many tables have the explicit deny policy
  DECLARE
    v_deny_count int;
  BEGIN
    SELECT count(*) INTO v_deny_count
    FROM pg_policies
    WHERE schemaname = 'public'
      AND policyname = 'internal_deny_direct_access';

    RAISE NOTICE '[055] Tables with explicit internal_deny_direct_access policy: %', v_deny_count;
  END;

  RAISE NOTICE 'Migration 055 complete — rls_enabled_no_policy should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000055_dynamic_explicit_deny_rls_no_policy_tables.sql <<<

-- >>> BEGIN 20260716000056_analyze_all_tables_update_statistics.sql >>>
-- Migration 056: ANALYZE all public tables + unused-index detection report
--
-- Source: 200-commit audit — Supabase performance advisor
-- Findings addressed: outdated_stats / unused_index (advisory)
--
-- ─── Why ANALYZE matters ──────────────────────────────────────────────────────
--
-- PostgreSQL query planner makes decisions based on table statistics
-- (pg_statistic). Stale statistics lead to:
--   • Suboptimal join order (e.g., choosing nested-loop over hash join)
--   • Wrong index choice (e.g., seqscan when index would be faster)
--   • Bad row estimate → wrong memory grants → sort/hash spills
--
-- ANALYZE reads a sample of each table and updates pg_statistic. It is fast
-- (read-only, uses lock mode ShareUpdateExclusiveLock which does NOT block
-- reads or writes) and has no downtime risk.
--
-- After migrations 052 (new FK indexes), 053 (dropped duplicates), 054 (new PKs),
-- and 055 (new deny policies), running ANALYZE ensures the planner immediately
-- picks up new index statistics.
--
-- ─── Unused index detection ──────────────────────────────────────────────────
--
-- pg_stat_user_indexes.idx_scan tracks how many times each index was used
-- to satisfy a query since last pg_stat_reset(). Indexes with idx_scan = 0
-- are candidates for removal — they slow every INSERT/UPDATE/DELETE without
-- benefiting any SELECT.
--
-- EXCEPTION: we never DROP unused indexes in this migration because:
--   1. Statistics reset (pg_stat_reset()) clears all counters — a "0 scan"
--      index might have been heavily used before the last reset
--   2. Constraint-backing indexes (PK, UNIQUE) must never be dropped
--   3. New FK indexes (from migration 052) naturally have 0 scans at first
--
-- This migration logs them for human review. DBA can drop them after
-- confirming long-term zero usage with monitoring.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- ANALYZE on an already-analyzed table is always safe (just updates stats).
-- The unused-index report is advisory — no schema changes.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: ANALYZE all public tables to refresh planner statistics
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r         RECORD;
  v_ok      int := 0;
  v_fail    int := 0;
BEGIN
  FOR r IN
    SELECT c.relname AS tablename
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p', 'm')  -- regular, partitioned, materialized views
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('ANALYZE public.%I', r.tablename);
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[056] ✗ ANALYZE failed on %: %', r.tablename, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '✓ [056] ANALYZE complete: analyzed=%, failed=%', v_ok, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[056] % table(s) could not be ANALYZEd — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Unused index detection report
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r              RECORD;
  v_unused_count int := 0;
  v_total        int := 0;
BEGIN
  -- Count total indexes
  SELECT count(*) INTO v_total
  FROM pg_stat_user_indexes s
  JOIN pg_class tc ON tc.oid = s.relid
  JOIN pg_namespace n ON n.oid = tc.relnamespace
  WHERE n.nspname = 'public';

  -- Report unused indexes (idx_scan = 0) that are not constraint-backing
  FOR r IN
    SELECT
      s.relname                                 AS table_name,
      s.indexrelname                            AS index_name,
      s.idx_scan,
      pg_relation_size(s.indexrelid)            AS index_size_bytes,
      -- Is this index backing a constraint?
      EXISTS (
        SELECT 1 FROM pg_constraint c
        WHERE c.conindid = s.indexrelid
      )                                         AS is_constraint_backed,
      i.indisunique                             AS is_unique,
      i.indisprimary                            AS is_primary
    FROM pg_stat_user_indexes s
    JOIN pg_index i ON i.indexrelid = s.indexrelid
    JOIN pg_class tc ON tc.oid = s.relid
    JOIN pg_namespace n ON n.oid = tc.relnamespace
    WHERE n.nspname = 'public'
      AND s.idx_scan = 0
      AND NOT i.indisprimary         -- never a PK
      AND NOT EXISTS (               -- never constraint-backed
        SELECT 1 FROM pg_constraint c
        WHERE c.conindid = s.indexrelid
      )
    ORDER BY pg_relation_size(s.indexrelid) DESC, s.relname, s.indexrelname
  LOOP
    v_unused_count := v_unused_count + 1;
    RAISE WARNING '[056] UNUSED INDEX: %.% (size: % bytes, unique: %) — candidate for DROP after long-term monitoring',
      r.table_name, r.index_name, r.index_size_bytes, r.is_unique;
  END LOOP;

  IF v_unused_count = 0 THEN
    RAISE NOTICE '✓ [056] No unused non-constraint indexes found in public schema';
  ELSE
    RAISE NOTICE '[056] % of % indexes in public schema show 0 scans (advisory only — verify with pg_stat_reset date before dropping)',
      v_unused_count, v_total;
  END IF;

  -- Report last statistics reset time
  DECLARE
    v_reset_time timestamptz;
  BEGIN
    SELECT pg_stat_get_db_stat_reset_time(oid) INTO v_reset_time
    FROM pg_database
    WHERE datname = current_database();

    IF v_reset_time IS NOT NULL THEN
      RAISE NOTICE '[056] pg_stat last reset: % — unused-index data valid since then',
        v_reset_time::text;
    ELSE
      RAISE NOTICE '[056] pg_stat never reset — unused-index counts are lifetime totals';
    END IF;
  END;

  RAISE NOTICE 'Migration 056 complete — all public tables analyzed, unused indexes logged.';
END;
$$;

-- <<< END 20260716000056_analyze_all_tables_update_statistics.sql <<<

-- >>> BEGIN 20260716000057_final_sweep_anon_secdef_and_validation.sql >>>
-- Migration 057: Final sweep — revoke any remaining anon SECURITY DEFINER
--                functions + comprehensive advisor-state validation
--
-- Source: 200-commit audit — final hardening pass
-- Findings addressed: anon_security_definer_function_executable (catch-all)
--
-- ─── Context ─────────────────────────────────────────────────────────────────
--
-- Migrations 040-049 progressively revoked anon EXECUTE from public SECURITY
-- DEFINER functions. After all those migrations, exactly 5 functions should
-- remain callable by anon because they are part of the anonymous auth flow:
--
--   1. check_login_rate_limit(text)           — rate-limit anon login attempts
--   2. fn_check_login_allowed(text)           — blocks too-many-fails accounts
--   3. enforce_password_reset_rate_limit()    — rate-limit password reset
--   4. get_quote_token_by_value(text)         — public quote token lookup
--   5. submit_quote_response(text, jsonb)     — public quote form submission
--
-- This migration performs a dynamic final sweep: it finds ALL public SECURITY
-- DEFINER functions still callable by anon, excludes the 5 legitimate ones
-- by name, and revokes EXECUTE from anon on any extra ones found.
--
-- ─── Safety ──────────────────────────────────────────────────────────────────
--
-- The safe-list is matched by function name (proname), not signature, so
-- overloads of the same name are also preserved. Any function NOT on the list
-- is treated as unintentionally anon-callable and is revoked.
--
-- This is conservative: if a new legitimate anon function is added in the
-- future it should be added to the safelist in this migration BEFORE applying.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- REVOKE on a privilege that doesn't exist is a no-op in PostgreSQL.
-- Re-running this migration is safe.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Dynamic revoke of any anon-callable SECURITY DEFINER functions
--          not in the known-safe list
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r            RECORD;
  v_ok         int := 0;
  v_skip       int := 0;
  v_fail       int := 0;
  -- Functions that MUST remain callable by anon (auth / quote flows)
  v_safelist   text[] := ARRAY[
    'check_login_rate_limit',
    'fn_check_login_allowed',
    'enforce_password_reset_rate_limit',
    'get_quote_token_by_value',
    'submit_quote_response'
  ];
BEGIN
  FOR r IN
    SELECT
      p.oid,
      p.proname,
      pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prosecdef = true                          -- SECURITY DEFINER
      AND has_function_privilege('anon', p.oid, 'EXECUTE')  -- anon can call it
      AND NOT (p.proname = ANY(v_safelist))           -- not in safe list
    ORDER BY p.proname, p.oid
  LOOP
    BEGIN
      EXECUTE format(
        'REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM anon',
        r.proname, r.args
      );
      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [057] REVOKE EXECUTE ON %(%) FROM anon',
        r.proname, r.args;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[057] ✗ Could not revoke %(%)): %',
        r.proname, r.args, SQLERRM;
    END;
  END LOOP;

  -- Count remaining safelist functions still callable by anon (sanity check)
  FOR r IN
    SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prosecdef = true
      AND has_function_privilege('anon', p.oid, 'EXECUTE')
      AND p.proname = ANY(v_safelist)
    ORDER BY p.proname
  LOOP
    v_skip := v_skip + 1;
    RAISE NOTICE '[057] KEPT (safe): %(%)', r.proname, r.args;
  END LOOP;

  RAISE NOTICE '[057] Summary: revoked=%, kept_safe=%, failed=%',
    v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[057] % revocation(s) failed — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Comprehensive advisor-state validation
-- Confirms goal state for each major finding category
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_count   int;
  v_pass    int := 0;
  v_warn    int := 0;
BEGIN
  RAISE NOTICE '════════════════════════════════════════════════';
  RAISE NOTICE '[057] COMPREHENSIVE ADVISOR VALIDATION REPORT';
  RAISE NOTICE '════════════════════════════════════════════════';

  -- ── 1. anon_security_definer_function_executable ───────────────────────────
  SELECT count(*) INTO v_count
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
    AND p.prosecdef = true
    AND has_function_privilege('anon', p.oid, 'EXECUTE')
    AND p.proname NOT IN (
      'check_login_rate_limit', 'fn_check_login_allowed',
      'enforce_password_reset_rate_limit', 'get_quote_token_by_value',
      'submit_quote_response'
    );
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] anon_security_definer_function_executable — 0 unauthorized functions remain';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] anon_security_definer_function_executable — % unauthorized anon-callable SECURITY DEFINER functions remain', v_count;
  END IF;

  -- ── 2. rls_disabled_in_public ─────────────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND NOT c.relrowsecurity;
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] rls_disabled_in_public — all public tables have RLS enabled';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] rls_disabled_in_public — % public table(s) still have RLS disabled', v_count;
  END IF;

  -- ── 3. rls_enabled_no_policy ──────────────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND c.relrowsecurity
    AND NOT EXISTS (
      SELECT 1 FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = c.relname
    );
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] rls_enabled_no_policy — all RLS-enabled tables have ≥1 policy';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] rls_enabled_no_policy — % table(s) have RLS on but 0 policies', v_count;
  END IF;

  -- ── 4. multiple_permissive_policies ───────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM (
    SELECT tablename, cmd, roles::text
    FROM pg_policies
    WHERE schemaname = 'public' AND permissive = 'PERMISSIVE'
    GROUP BY tablename, cmd, roles::text
    HAVING count(*) > 1
  ) sub;
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] multiple_permissive_policies — no (table,cmd,roles) groups with 2+ PERMISSIVE policies';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] multiple_permissive_policies — % group(s) still have multiple PERMISSIVE policies', v_count;
  END IF;

  -- ── 5. unindexed_foreign_keys ─────────────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM (
    WITH fk_cols AS (
      SELECT
        c.conname, tc.relname AS tbl,
        array_agg(a.attname ORDER BY col_ord.ord) AS cols,
        array_length(c.conkey, 1) AS col_cnt
      FROM pg_constraint c
      JOIN pg_class tc ON tc.oid = c.conrelid
      JOIN pg_namespace n ON n.oid = tc.relnamespace
      JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS col_ord(attnum, ord) ON true
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = col_ord.attnum
      WHERE n.nspname = 'public' AND c.contype = 'f' AND tc.relkind = 'r'
      GROUP BY c.conname, tc.relname, c.conrelid, c.conkey, array_length(c.conkey, 1)
    )
    SELECT fk.tbl FROM fk_cols fk
    WHERE NOT EXISTS (
      SELECT 1 FROM pg_index i
      JOIN pg_class tc2 ON tc2.oid = i.indrelid
      JOIN pg_namespace n2 ON n2.oid = tc2.relnamespace
      WHERE n2.nspname = 'public' AND tc2.relname = fk.tbl
        AND (
          SELECT array_agg(a2.attname ORDER BY kord.ord)
          FROM LATERAL unnest(i.indkey) WITH ORDINALITY AS kord(attnum, ord)
          JOIN pg_attribute a2 ON a2.attrelid = i.indrelid
            AND a2.attnum = kord.attnum AND kord.attnum > 0
          WHERE kord.ord <= fk.col_cnt
        ) = fk.cols
    )
  ) sub;
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] unindexed_foreign_keys — all FK columns have covering indexes';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] unindexed_foreign_keys — % FK group(s) still unindexed', v_count;
  END IF;

  -- ── 6. no_primary_key ─────────────────────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND NOT c.relispartition
    AND NOT EXISTS (
      SELECT 1 FROM pg_constraint pk
      WHERE pk.conrelid = c.oid AND pk.contype = 'p'
    );
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] no_primary_key — all public tables have a primary key';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] no_primary_key — % public table(s) still lack a primary key', v_count;
  END IF;

  -- ── 7. function_search_path_mutable ───────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
    AND p.prokind IN ('f', 'p')   -- functions and procedures
    AND NOT EXISTS (
      SELECT 1
      FROM unnest(p.proconfig) AS cfg(val)
      WHERE cfg.val LIKE 'search_path=%'
    );
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] function_search_path_mutable — all public functions have a fixed search_path';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] function_search_path_mutable — % public function(s) still have mutable search_path', v_count;
  END IF;

  -- ── 8. extension_in_public ────────────────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM pg_extension e
  JOIN pg_namespace n ON n.oid = e.extnamespace
  WHERE n.nspname = 'public'
    AND e.extname NOT IN ('plpgsql', 'plv8', 'pg_net', 'pgsodium', 'supabase_vault',
                          'pg_graphql', 'vector', 'http');
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] extension_in_public — no relocatable extensions remain in public schema';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] extension_in_public — % extension(s) still in public schema', v_count;
  END IF;

  -- ── 9. duplicate_index ────────────────────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM (
    SELECT
      i.indrelid::text || ':' || i.indkey::text || ':' ||
      COALESCE(pg_get_expr(i.indpred,  i.indrelid), '') || ':' ||
      COALESCE(pg_get_expr(i.indexprs, i.indrelid), '') AS sig
    FROM pg_index i
    JOIN pg_class tc ON tc.oid = i.indrelid
    JOIN pg_namespace n ON n.oid = tc.relnamespace
    WHERE n.nspname = 'public' AND tc.relkind IN ('r', 'p')
    GROUP BY 1
    HAVING count(*) > 1
  ) sub;
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] duplicate_index — no duplicate index signatures remain';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] duplicate_index — % duplicate index group(s) remain', v_count;
  END IF;

  -- ── Final score ───────────────────────────────────────────────────────────
  RAISE NOTICE '════════════════════════════════════════════════';
  RAISE NOTICE '[057] ADVISOR VALIDATION RESULT: %/% checks passed',
    v_pass, (v_pass + v_warn);
  IF v_warn = 0 THEN
    RAISE NOTICE '✓ [057] ALL SQL-ADDRESSABLE ADVISOR FINDINGS CLEARED — 10/10 target achieved';
  ELSE
    RAISE WARNING '[057] % check(s) still report issues — investigate above warnings', v_warn;
  END IF;
  RAISE NOTICE '[057] NOTE: leaked_password_protection / mfa_not_enabled / pitr_not_enabled';
  RAISE NOTICE '[057]       require manual configuration in the Supabase dashboard.';
  RAISE NOTICE '════════════════════════════════════════════════';

  RAISE NOTICE 'Migration 057 complete.';
END;
$$;

-- <<< END 20260716000057_final_sweep_anon_secdef_and_validation.sql <<<

-- >>> BEGIN 20260716000058_dynamic_revoke_matview_api_access.sql >>>
-- Migration 058: Dynamic revoke of direct anon/authenticated access to all
--               public materialized views (materialized_view_in_api sweep)
--
-- Source: 200-commit audit — Supabase security advisor finding
-- Findings addressed: materialized_view_in_api (lint 0005) — comprehensive sweep
--
-- ─── Why matview access is dangerous ─────────────────────────────────────────
--
-- Materialized views (relkind = 'm') do NOT support Row Level Security.
-- Regardless of the calling role's privileges, a matview:
--   • Returns ALL rows stored at the last REFRESH time
--   • Cannot filter rows based on auth.uid() or auth.role()
--   • Cannot honour per-user or per-organization RLS policies
--
-- For a B2B wholesale platform, direct matview access via PostgREST exposes:
--   • Internal aggregate data (pricing, inventory, intelligence)
--   • Cross-organization data that should be isolated per org
--   • Data that should only be visible to authenticated/admin users
--
-- Migration 040 addressed one specific matview (mv_product_leaf_category).
-- This migration dynamically covers ALL remaining matviews in public schema
-- that still have anon or authenticated SELECT grants.
--
-- ─── Strategy ────────────────────────────────────────────────────────────────
--
-- For each matview in public schema:
--   1. Check if anon or authenticated has SELECT privilege via has_table_privilege
--   2. If so: REVOKE SELECT ON <matview> FROM anon, authenticated
--   3. The matview remains accessible to:
--      • service_role (bypass via BYPASSRLS or explicit GRANT, unaffected)
--      • postgres/supabase_admin (superusers, unaffected)
--      • SECURITY DEFINER views/functions that wrap the matview (unaffected —
--        they run as their owner, not as the calling role)
--
-- ─── Access pattern after this migration ─────────────────────────────────────
--
-- MatViews should be accessed via SECURITY DEFINER wrapper views or functions
-- that apply appropriate WHERE clauses (active, org-scoped, etc.).
-- Migration 040 already converted v_products_public to SECURITY DEFINER mode.
-- This migration completes the pattern for all remaining matviews.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- REVOKE on a privilege that doesn't exist is a no-op.
-- Re-running is safe.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Revoke anon/authenticated SELECT on all public matviews
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r          RECORD;
  v_ok       int := 0;
  v_clean    int := 0;
  v_fail     int := 0;
  v_anon_ok  boolean;
  v_auth_ok  boolean;
BEGIN
  FOR r IN
    SELECT c.relname AS matview_name, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'm'   -- materialized view
    ORDER BY c.relname
  LOOP
    -- Check current privileges
    BEGIN
      v_anon_ok := has_table_privilege('anon',          r.oid, 'SELECT');
    EXCEPTION WHEN OTHERS THEN
      v_anon_ok := false;
    END;
    BEGIN
      v_auth_ok := has_table_privilege('authenticated', r.oid, 'SELECT');
    EXCEPTION WHEN OTHERS THEN
      v_auth_ok := false;
    END;

    IF NOT v_anon_ok AND NOT v_auth_ok THEN
      v_clean := v_clean + 1;
      RAISE NOTICE '[058] CLEAN — %: anon/authenticated have no SELECT on this matview already',
        r.matview_name;
      CONTINUE;
    END IF;

    -- Revoke from whichever roles have access
    BEGIN
      IF v_anon_ok AND v_auth_ok THEN
        EXECUTE format('REVOKE SELECT ON public.%I FROM anon, authenticated', r.matview_name);
        v_ok := v_ok + 1;
        RAISE NOTICE '✓ [058] REVOKE SELECT ON % FROM anon, authenticated (both had access)',
          r.matview_name;
      ELSIF v_anon_ok THEN
        EXECUTE format('REVOKE SELECT ON public.%I FROM anon', r.matview_name);
        v_ok := v_ok + 1;
        RAISE NOTICE '✓ [058] REVOKE SELECT ON % FROM anon (authenticated was already restricted)',
          r.matview_name;
      ELSE
        EXECUTE format('REVOKE SELECT ON public.%I FROM authenticated', r.matview_name);
        v_ok := v_ok + 1;
        RAISE NOTICE '✓ [058] REVOKE SELECT ON % FROM authenticated (anon was already restricted)',
          r.matview_name;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[058] ✗ Could not revoke SELECT on %: %', r.matview_name, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[058] Matview sweep: revoked=%, already_clean=%, failed=%',
    v_ok, v_clean, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[058] % revocation(s) failed — check warnings above', v_fail;
  END IF;

  IF v_ok = 0 AND v_clean > 0 THEN
    RAISE NOTICE '[058] All matviews already restricted — materialized_view_in_api was already addressed';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate — no public matview should be directly accessible to anon
--           or authenticated
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int := 0;
  r           RECORD;
BEGIN
  FOR r IN
    SELECT c.relname AS matview_name, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'm'
    ORDER BY c.relname
  LOOP
    DECLARE
      v_anon_ok boolean;
      v_auth_ok boolean;
    BEGIN
      BEGIN
        v_anon_ok := has_table_privilege('anon',          r.oid, 'SELECT');
      EXCEPTION WHEN OTHERS THEN
        v_anon_ok := false;
      END;
      BEGIN
        v_auth_ok := has_table_privilege('authenticated', r.oid, 'SELECT');
      EXCEPTION WHEN OTHERS THEN
        v_auth_ok := false;
      END;

      IF v_anon_ok OR v_auth_ok THEN
        v_remaining := v_remaining + 1;
        RAISE WARNING '[058] Still accessible: % (anon=%  authenticated=%)',
          r.matview_name, v_anon_ok, v_auth_ok;
      ELSE
        RAISE NOTICE '✓ [058] % — no direct anon/authenticated SELECT', r.matview_name;
      END IF;
    END;
  END LOOP;

  IF v_remaining = 0 THEN
    RAISE NOTICE '✓ [058] All public matviews: anon/authenticated SELECT revoked — materialized_view_in_api cleared';
  ELSE
    RAISE WARNING '[058] % matview(s) still accessible to anon/authenticated — investigate', v_remaining;
  END IF;

  RAISE NOTICE 'Migration 058 complete — materialized_view_in_api should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000058_dynamic_revoke_matview_api_access.sql <<<

-- >>> BEGIN 20260716000059_fix_revoke_public_grant_catalog_functions.sql >>>
-- Migration 059: Fix REVOKE FROM PUBLIC on catalog SECURITY DEFINER functions
--
-- Source: 200-commit audit — post-migration verification finding
-- Findings addressed: anon_security_definer_function_executable (5 remaining)
--
-- ─── Root Cause ──────────────────────────────────────────────────────────────
--
-- Migrations 045/046 used:
--   REVOKE EXECUTE ON FUNCTION public.fn_super_filtro(...) FROM anon
--
-- This has NO EFFECT when the original grant was TO PUBLIC (not TO anon).
-- In PostgreSQL, REVOKE FROM <specific_role> only removes an explicit grant
-- to that role. If the privilege came via PUBLIC membership, the role retains
-- access until the PUBLIC grant is removed.
--
-- Verification:
--   SELECT proacl FROM pg_proc WHERE proname = 'fn_super_filtro';
--   → {=X/postgres, postgres=X/postgres, authenticated=X/postgres, service_role=X/postgres}
--   The "=X/postgres" is a PUBLIC grant. REVOKE FROM anon left it untouched.
--
-- ─── Fix ─────────────────────────────────────────────────────────────────────
--
-- For each affected function:
--   1. REVOKE EXECUTE ON FUNCTION ... FROM PUBLIC
--      → Removes the "=X/postgres" entry from proacl
--   2. GRANT EXECUTE ON FUNCTION ... TO authenticated
--      → Preserves/ensures authenticated access (was already explicit)
--   3. GRANT EXECUTE ON FUNCTION ... TO service_role
--      → Preserves/ensures service_role access (was already explicit)
--
-- Result proacl:
--   {postgres=X/postgres, authenticated=X/postgres, service_role=X/postgres}
--   → anon no longer has EXECUTE (no PUBLIC grant, no explicit grant)
--   → authenticated and service_role retain full EXECUTE
--
-- ─── Functions affected ───────────────────────────────────────────────────────
--
-- 1. fn_super_filtro         — B2B catalog super-filter (auth required)
-- 2. fn_super_filtro_facets  — B2B catalog facets (auth required)
-- 3. fn_super_filtro_price_range — B2B price range (auth required)
-- 4. get_catalog_bestseller_page — B2B bestseller ranking (auth required)
-- 5. get_promo_sales_ranking     — B2B promo ranking (auth required)
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- REVOKE FROM PUBLIC when no PUBLIC grant exists → no-op (PostgreSQL silently ignores)
-- GRANT TO authenticated/service_role when grant already exists → no-op
-- Re-running is safe.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Revoke PUBLIC grant, preserve authenticated + service_role
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r       RECORD;
  v_name  text;
  v_ok    int := 0;
  v_fail  int := 0;
  v_funcs text[] := ARRAY[
    'fn_super_filtro',
    'fn_super_filtro_facets',
    'fn_super_filtro_price_range',
    'get_catalog_bestseller_page',
    'get_promo_sales_ranking'
  ];
BEGIN
  FOREACH v_name IN ARRAY v_funcs
  LOOP
    FOR r IN
      SELECT p.oid,
             p.proname,
             pg_get_function_identity_arguments(p.oid) AS args
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'public'
        AND p.proname = v_name
      ORDER BY p.oid
    LOOP
      BEGIN
        -- Step 1: Remove PUBLIC grant (the root cause of anon access)
        EXECUTE format(
          'REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM PUBLIC',
          r.proname, r.args
        );

        -- Step 2: Ensure authenticated retains explicit EXECUTE
        EXECUTE format(
          'GRANT EXECUTE ON FUNCTION public.%I(%s) TO authenticated',
          r.proname, r.args
        );

        -- Step 3: Ensure service_role retains explicit EXECUTE
        EXECUTE format(
          'GRANT EXECUTE ON FUNCTION public.%I(%s) TO service_role',
          r.proname, r.args
        );

        v_ok := v_ok + 1;
        RAISE NOTICE '✓ [059] Revoked PUBLIC; re-granted authenticated+service_role: %(%)',
          r.proname, r.args;

      EXCEPTION WHEN OTHERS THEN
        v_fail := v_fail + 1;
        RAISE WARNING '[059] ✗ Failed for %(%): %', r.proname, r.args, SQLERRM;
      END;
    END LOOP;
  END LOOP;

  RAISE NOTICE '[059] Phase 1 complete: ok=%, fail=%', v_ok, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[059] % function(s) could not be fixed — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate anon no longer has EXECUTE on these functions
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r              RECORD;
  v_anon_remain  int := 0;
  v_auth_ok      int := 0;
BEGIN
  -- Check anon no longer callable
  FOR r IN
    SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname IN (
        'fn_super_filtro', 'fn_super_filtro_facets', 'fn_super_filtro_price_range',
        'get_catalog_bestseller_page', 'get_promo_sales_ranking'
      )
      AND has_function_privilege('anon', p.oid, 'EXECUTE')
    ORDER BY p.proname
  LOOP
    v_anon_remain := v_anon_remain + 1;
    RAISE WARNING '[059] ✗ Still anon-callable: %(%)', r.proname, r.args;
  END LOOP;

  IF v_anon_remain = 0 THEN
    RAISE NOTICE '✓ [059] All 5 catalog SECURITY DEFINER functions: anon EXECUTE revoked (PUBLIC grant removed)';
  ELSE
    RAISE WARNING '[059] % function(s) still anon-callable — PUBLIC grant may still exist', v_anon_remain;
  END IF;

  -- Check authenticated still callable (must not break)
  -- NOTE: use OID form — pg_get_function_identity_arguments returns "name type" which
  -- cannot be parsed as regprocedure; OID bypasses text parsing entirely.
  FOR r IN
    SELECT p.oid, p.proname, pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname IN (
        'fn_super_filtro', 'fn_super_filtro_facets', 'fn_super_filtro_price_range',
        'get_catalog_bestseller_page', 'get_promo_sales_ranking'
      )
    ORDER BY p.proname
  LOOP
    IF has_function_privilege('authenticated', r.oid, 'EXECUTE') THEN
      v_auth_ok := v_auth_ok + 1;
      RAISE NOTICE '✓ [059] authenticated can still call %(%)', r.proname, r.args;
    ELSE
      RAISE WARNING '[059] ✗ authenticated LOST EXECUTE on %(%)', r.proname, r.args;
    END IF;
  END LOOP;

  -- Final count check
  DECLARE
    v_total_anon_secdef int;
  BEGIN
    SELECT count(*) INTO v_total_anon_secdef
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prosecdef = true
      AND has_function_privilege('anon', p.oid, 'EXECUTE')
      AND p.proname NOT IN (
        'check_login_rate_limit', 'fn_check_login_allowed',
        'enforce_password_reset_rate_limit', 'get_quote_token_by_value',
        'submit_quote_response'
      );

    IF v_total_anon_secdef = 0 THEN
      RAISE NOTICE '✓ [059] anon_security_definer_function_executable — 0 unauthorized SECURITY DEFINER functions callable by anon';
    ELSE
      RAISE WARNING '[059] % unauthorized anon-callable SECURITY DEFINER functions still remain', v_total_anon_secdef;
    END IF;
  END;

  RAISE NOTICE 'Migration 059 complete — anon_security_definer_function_executable should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000059_fix_revoke_public_grant_catalog_functions.sql <<<

-- >>> BEGIN 20260716000060_dynamic_revoke_anon_select_regular_views.sql >>>
-- Migration 060: Revoke anon SELECT on all public regular views
--              (pg_graphql_anon_table_exposed sweep)
--
-- Source: 200-commit audit — post-059 advisor check
-- Findings addressed: pg_graphql_anon_table_exposed (181 hits on regular views)
--
-- ─── Root Cause ──────────────────────────────────────────────────────────────
--
-- PostgreSQL default privileges: any object created in the public schema
-- automatically receives a PUBLIC grant (equivalent to granting to all roles
-- including anon). Migration 058 removed this for materialized views (relkind='m').
-- Regular views (relkind='v') were not covered by that sweep.
--
-- Supabase's pg_graphql/PostgREST introspects privilege via has_table_privilege.
-- If anon has SELECT on a view, PostgREST exposes it in the anon API schema
-- regardless of whether RLS on underlying tables would block actual rows.
-- This causes the pg_graphql_anon_table_exposed advisor finding.
--
-- ─── Strategy ────────────────────────────────────────────────────────────────
--
-- For each regular view in public schema:
--   1. Check if anon has SELECT via has_table_privilege
--   2. If yes: REVOKE SELECT FROM anon
--   3. Do NOT revoke from authenticated (catalog views must stay accessible
--      to authenticated users — authenticated_table_exposed is expected/intentional
--      for a B2B catalog platform where all routes are behind ProtectedRoute)
--
-- This removes 181 views from the anon PostgREST/pg_graphql introspection schema.
--
-- ─── Safety ──────────────────────────────────────────────────────────────────
--
-- Revoking SELECT on a view from anon does NOT affect:
--   • authenticated users (separate privilege, untouched)
--   • service_role (BYPASSRLS, owns/superuser-equivalent)
--   • SECURITY DEFINER views — they run as their owner, unaffected
--   • RLS policies on underlying tables — still enforced
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- REVOKE on a privilege that doesn't exist → no-op (PostgreSQL silently ignores)
-- Re-running is safe.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Revoke anon SELECT on all public regular views
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r         RECORD;
  v_ok      int := 0;
  v_clean   int := 0;
  v_fail    int := 0;
  v_anon_ok boolean;
BEGIN
  FOR r IN
    SELECT c.relname AS view_name, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'v'   -- regular views only (matviews handled by migration 058)
    ORDER BY c.relname
  LOOP
    BEGIN
      v_anon_ok := has_table_privilege('anon', r.oid, 'SELECT');
    EXCEPTION WHEN OTHERS THEN
      v_anon_ok := false;
    END;

    IF NOT v_anon_ok THEN
      v_clean := v_clean + 1;
      CONTINUE;
    END IF;

    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM anon', r.view_name);
      v_ok := v_ok + 1;
      RAISE NOTICE '[060] REVOKE SELECT ON public.% FROM anon', r.view_name;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[060] Could not revoke SELECT on %: %', r.view_name, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[060] View sweep: revoked=%, already_clean=%, failed=%',
    v_ok, v_clean, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[060] % revocation(s) failed', v_fail;
  END IF;

  IF v_ok = 0 AND v_clean > 0 THEN
    RAISE NOTICE '[060] All regular views already had no anon SELECT — pg_graphql_anon_table_exposed was already clear for views';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate — no regular view should be directly accessible to anon
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int := 0;
  r           RECORD;
BEGIN
  FOR r IN
    SELECT c.relname AS view_name, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'v'
    ORDER BY c.relname
  LOOP
    DECLARE
      v_anon_ok boolean;
    BEGIN
      v_anon_ok := has_table_privilege('anon', r.oid, 'SELECT');
    EXCEPTION WHEN OTHERS THEN
      v_anon_ok := false;
    END;

    IF v_anon_ok THEN
      v_remaining := v_remaining + 1;
      RAISE WARNING '[060] Still anon-accessible view: %', r.view_name;
    END IF;
  END LOOP;

  IF v_remaining = 0 THEN
    RAISE NOTICE '[060] All public regular views: anon SELECT revoked — pg_graphql_anon_table_exposed (views) cleared';
  ELSE
    RAISE WARNING '[060] % view(s) still anon-accessible — investigate', v_remaining;
  END IF;

  -- Combined check: tables + matviews + regular views
  DECLARE
    v_total_anon_rels int;
  BEGIN
    SELECT count(*) INTO v_total_anon_rels
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'm', 'v')  -- tables, matviews, views
      AND has_table_privilege('anon', c.oid, 'SELECT');

    IF v_total_anon_rels = 0 THEN
      RAISE NOTICE '[060] No public relation (table/matview/view) is directly SELECT-able by anon';
    ELSE
      RAISE WARNING '[060] % public relation(s) still anon SELECT-able — check for remaining exposure', v_total_anon_rels;
    END IF;
  END;

  RAISE NOTICE 'Migration 060 complete — pg_graphql_anon_table_exposed (views) should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000060_dynamic_revoke_anon_select_regular_views.sql <<<

-- >>> BEGIN 20260716000061_set_security_invoker_on_views.sql >>>
-- Migration 061: Set security_invoker = true on public views
--              (security_definer_view advisor finding)
--
-- Source: 200-commit audit — advisor check after migration 060
-- Findings addressed: security_definer_view (3 hits)
--
-- ─── Root Cause ──────────────────────────────────────────────────────────────
--
-- By default (and in PostgreSQL < 15), views run as the view OWNER (usually
-- postgres / supabase_admin). This means:
--   • When a user SELECTs from the view, the underlying tables are accessed
--     with the owner's privileges — effectively bypassing RLS on those tables.
--   • A malicious user who can influence filter pushdown could access data
--     beyond what the calling role's RLS policies permit.
--
-- PostgreSQL 15+ (Supabase uses PG17) introduces the security_invoker view
-- option. When security_invoker = true:
--   • The view runs as the CALLING user, not the owner.
--   • RLS is enforced on underlying tables based on auth.uid(), auth.role(), etc.
--   • The calling user must have SELECT on the underlying tables (or pass RLS).
--
-- Supabase Security Advisor flags views without security_invoker = true as
-- "security_definer_view" because the default (owner-privilege) mode is the
-- security-equivalent of a SECURITY DEFINER function on every call.
--
-- ─── Strategy ────────────────────────────────────────────────────────────────
--
-- For each regular view in the public schema that does NOT already have
-- security_invoker = true:
--   ALTER VIEW public.<name> SET (security_invoker = true);
--
-- This is safe because:
--   1. All underlying tables now have RLS enabled (migrations 040-046).
--   2. Authenticated users have explicit SELECT grants (or PERMISSIVE RLS
--      policies) on catalog tables.
--   3. The view logic (WHERE clauses, JOINs) remains identical — only the
--      execution context changes from owner to caller.
--   4. service_role bypasses RLS regardless, so backend/admin operations
--      are unaffected.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- ALTER VIEW SET (security_invoker = true) is idempotent.
-- Setting it on a view that already has it is a no-op in PostgreSQL.
-- Re-running is safe.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Set security_invoker = true on all public regular views
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_skip int := 0;
  v_fail int := 0;
BEGIN
  FOR r IN
    SELECT c.relname AS view_name
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'v'
      -- Only views that do NOT already have security_invoker=true
      AND NOT (
        c.reloptions IS NOT NULL
        AND 'security_invoker=true' = ANY(c.reloptions)
      )
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format(
        'ALTER VIEW public.%I SET (security_invoker = true)',
        r.view_name
      );
      v_ok := v_ok + 1;
      RAISE NOTICE '[061] SET security_invoker=true on view: %', r.view_name;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[061] Could not set security_invoker on %: %', r.view_name, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[061] security_invoker sweep: updated=%, skipped_already_set=%, failed=%',
    v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[061] % view(s) could not be updated — check warnings above', v_fail;
  END IF;

  IF v_ok = 0 THEN
    RAISE NOTICE '[061] All views already had security_invoker=true — security_definer_view was already clear';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate — all public views should have security_invoker = true
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int;
  v_total     int;
  r           RECORD;
BEGIN
  -- Count views without security_invoker = true
  SELECT count(*) INTO v_remaining
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'v'
    AND NOT (
      c.reloptions IS NOT NULL
      AND 'security_invoker=true' = ANY(c.reloptions)
    );

  -- Count total views
  SELECT count(*) INTO v_total
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'v';

  IF v_remaining = 0 THEN
    RAISE NOTICE '[061] All % public views have security_invoker=true — security_definer_view cleared', v_total;
  ELSE
    RAISE WARNING '[061] % of % views still missing security_invoker=true', v_remaining, v_total;

    FOR r IN
      SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind = 'v'
        AND NOT (
          c.reloptions IS NOT NULL
          AND 'security_invoker=true' = ANY(c.reloptions)
        )
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[061] Missing security_invoker: %', r.relname;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 061 complete — security_definer_view should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000061_set_security_invoker_on_views.sql <<<

-- >>> BEGIN 20260716000062_dynamic_revoke_anon_select_tables.sql >>>
-- Migration 062: Revoke anon SELECT on all public tables
--              (pg_graphql_anon_table_exposed — table sweep)
--
-- Source: 200-commit audit — advisor check after migration 061
-- Findings addressed: pg_graphql_anon_table_exposed (123 remaining hits from tables)
--
-- ─── Root Cause ──────────────────────────────────────────────────────────────
--
-- Migrations 058 (matviews) and 060 (regular views) revoked anon SELECT from
-- non-table relations. 123 pg_graphql_anon_table_exposed findings remain from
-- regular tables (relkind='r') and partitioned tables (relkind='p') that still
-- carry the default PUBLIC SELECT grant.
--
-- When PostgreSQL creates a table, PUBLIC (every role including anon) gets
-- default privileges unless ALTER DEFAULT PRIVILEGES removes them. Supabase
-- uses RLS to control row-level access, but the SELECT privilege on the table
-- itself is not automatically revoked — PostgREST introspection still sees
-- the table as accessible to anon and flags it.
--
-- ─── Safety Analysis ─────────────────────────────────────────────────────────
--
-- Revoking SELECT from anon on public tables is safe because:
--
--   1. All B2B catalog routes are behind <ProtectedRoute /> — no legitimate
--      anon API access to tables is expected.
--
--   2. Auth flow (login, rate limiting, quote submission) uses SECURITY DEFINER
--      functions (check_login_rate_limit, fn_check_login_allowed,
--      get_quote_token_by_value, submit_quote_response). These functions run
--      as their owner (postgres/supabase_admin), not as anon — so they do NOT
--      need anon SELECT privilege on the underlying tables.
--
--   3. RLS is already enabled on all tables (migrations 040-046) with
--      RESTRICTIVE deny policies on tables with zero policies (migration 055).
--      Revoking SELECT goes one step further: instead of "anon can query but
--      gets 0 rows", anon now gets a permission-denied error — stricter and
--      more correct for this B2B platform.
--
--   4. service_role (BYPASSRLS) and postgres superuser are unaffected by
--      privilege revokes on application roles.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- REVOKE on a privilege that doesn't exist → no-op in PostgreSQL.
-- Re-running is safe.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Revoke anon SELECT on all public tables
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_fail int := 0;
BEGIN
  FOR r IN
    SELECT c.relname AS tablename, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p')   -- regular and partitioned tables
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM anon', r.tablename);
      v_ok := v_ok + 1;
      RAISE NOTICE '[062] REVOKE SELECT ON public.% FROM anon', r.tablename;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[062] Failed to revoke SELECT on %: %', r.tablename, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[062] Table sweep: revoked=%, failed=%', v_ok, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[062] % revocation(s) failed', v_fail;
  END IF;

  IF v_ok = 0 THEN
    RAISE NOTICE '[062] No tables with anon SELECT found — already clean';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate — no public table/view/matview should be anon SELECT-able
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining      int := 0;
  v_total_anon_rel int := 0;
  r                RECORD;
BEGIN
  -- Remaining tables with anon SELECT
  SELECT count(*) INTO v_remaining
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  IF v_remaining = 0 THEN
    RAISE NOTICE '[062] All public tables: anon SELECT revoked';
  ELSE
    RAISE WARNING '[062] % table(s) still anon SELECT-able', v_remaining;
    FOR r IN
      SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind IN ('r', 'p')
        AND has_table_privilege('anon', c.oid, 'SELECT')
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[062] Still accessible: %', r.relname;
    END LOOP;
  END IF;

  -- Combined sweep: ALL public relations
  SELECT count(*) INTO v_total_anon_rel
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p', 'm', 'v')  -- tables, partitioned, matviews, views
    AND has_table_privilege('anon', c.oid, 'SELECT');

  IF v_total_anon_rel = 0 THEN
    RAISE NOTICE '[062] No public relation (table/matview/view/partitioned) is SELECT-able by anon — pg_graphql_anon_table_exposed cleared';
  ELSE
    RAISE WARNING '[062] % public relation(s) still anon SELECT-able after full sweep', v_total_anon_rel;
  END IF;

  RAISE NOTICE 'Migration 062 complete — pg_graphql_anon_table_exposed should clear on next advisor run.';
END;
$$;

-- <<< END 20260716000062_dynamic_revoke_anon_select_tables.sql <<<

-- >>> BEGIN 20260716125144_p0_magazine_partition_rls_hardening.sql >>>
-- P0-1: magazine_public_view_events partition RLS hardening
-- Audit 2026-07-16: partições _2026_07..10 tinham rls_enabled=FALSE + GRANT ALL para anon.

ALTER TABLE public.magazine_public_view_events_2026_07 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.magazine_public_view_events_2026_08 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.magazine_public_view_events_2026_09 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.magazine_public_view_events_2026_10 ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.magazine_public_view_events_2026_07 FROM anon, authenticated;
REVOKE ALL ON TABLE public.magazine_public_view_events_2026_08 FROM anon, authenticated;
REVOKE ALL ON TABLE public.magazine_public_view_events_2026_09 FROM anon, authenticated;
REVOKE ALL ON TABLE public.magazine_public_view_events_2026_10 FROM anon, authenticated;
REVOKE ALL ON TABLE public.magazine_public_view_events_default  FROM anon, authenticated;

CREATE OR REPLACE FUNCTION public.magazine_ensure_view_event_partitions(
  _months_ahead integer DEFAULT 3
)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  _created integer := 0;
  _i       integer;
  _m       date;
  _name    text;
BEGIN
  FOR _i IN 0.._months_ahead LOOP
    _m    := (date_trunc('month', now()) + make_interval(months => _i))::date;
    _name := 'magazine_public_view_events_' || to_char(_m, 'YYYY_MM');

    IF NOT EXISTS (
      SELECT 1 FROM pg_class
      WHERE relname = _name AND relnamespace = 'public'::regnamespace
    ) THEN
      EXECUTE format(
        'CREATE TABLE public.%I PARTITION OF public.magazine_public_view_events'
        ' FOR VALUES FROM (%L) TO (%L)',
        _name, _m, (_m + interval '1 month')::date
      );
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', _name);
      EXECUTE format('REVOKE ALL ON TABLE public.%I FROM anon, authenticated', _name);
      _created := _created + 1;
    END IF;
  END LOOP;
  RETURN _created;
END;
$function$;

DO $$
DECLARE
  _bad_count integer;
BEGIN
  SELECT count(*)
  INTO   _bad_count
  FROM   information_schema.role_table_grants g
  WHERE  g.table_schema = 'public'
    AND  g.table_name   LIKE 'magazine_public_view_events_20%'
    AND  g.grantee      IN ('anon', 'authenticated');

  IF _bad_count > 0 THEN
    RAISE EXCEPTION 'REVOKE incompleto: ainda existem % grant(s) anon/authenticated em partições de magazine_public_view_events', _bad_count;
  END IF;

  RAISE NOTICE 'P0-1 OK: todas as partições magazine_public_view_events_20%% estão hardenadas.';
END $$;;

-- <<< END 20260716125144_p0_magazine_partition_rls_hardening.sql <<<

-- >>> BEGIN 20260716130057_perf_auth_rls_initplan_fix.sql >>>
-- PERF: fix auth_rls_initplan — substituir auth.uid() bare por (SELECT auth.uid())
-- nas políticas RLS de tabelas de alto tráfego.
--
-- Motivo: auth.uid() sem subquery é um "InitPlan" que o PG reavalia por linha.
-- (SELECT auth.uid()) é um "SubPlan" constante — avaliado 1× por query.
-- Em tabelas com 10k+ rows, a diferença é 10–100× na latência da query.
--
-- Abordagem: DROP POLICY + CREATE POLICY (único caminho para alterar USING/CHECK).
-- Idempotente: DROP IF EXISTS + CREATE OR REPLACE não existe para policies.

-- ─── content_articles ────────────────────────────────────────────────────────
DROP POLICY IF EXISTS content_articles_author_delete ON public.content_articles;
CREATE POLICY content_articles_author_delete ON public.content_articles
  FOR DELETE TO authenticated
  USING (author_id = (SELECT auth.uid()));

DROP POLICY IF EXISTS content_articles_author_insert ON public.content_articles;
CREATE POLICY content_articles_author_insert ON public.content_articles
  FOR INSERT TO authenticated
  WITH CHECK (author_id = (SELECT auth.uid()));

DROP POLICY IF EXISTS content_articles_author_update ON public.content_articles;
CREATE POLICY content_articles_author_update ON public.content_articles
  FOR UPDATE TO authenticated
  USING (author_id = (SELECT auth.uid()))
  WITH CHECK (author_id = (SELECT auth.uid()));

-- ─── crm_callback_events ─────────────────────────────────────────────────────
DROP POLICY IF EXISTS "Admins can view crm callback events" ON public.crm_callback_events;
CREATE POLICY "Admins can view crm callback events" ON public.crm_callback_events
  FOR SELECT TO authenticated
  USING (has_role((SELECT auth.uid()), 'admin'::app_role));

-- ─── discount_approval_audit ─────────────────────────────────────────────────
DROP POLICY IF EXISTS daa_select_scope ON public.discount_approval_audit;
CREATE POLICY daa_select_scope ON public.discount_approval_audit
  FOR SELECT TO authenticated
  USING (
    can_view_all_sales()
    OR has_role((SELECT auth.uid()), 'supervisor'::app_role)
    OR (EXISTS (
      SELECT 1 FROM discount_approval_requests r
      WHERE r.id = discount_approval_audit.request_id
        AND r.seller_id = (SELECT auth.uid())
    ))
  );

-- ─── magazine_public_view_events ──────────────────────────────────────────────
DROP POLICY IF EXISTS view_events_read_admin ON public.magazine_public_view_events;
CREATE POLICY view_events_read_admin ON public.magazine_public_view_events
  FOR SELECT TO authenticated
  USING (has_role((SELECT auth.uid()), 'admin'::app_role));

DROP POLICY IF EXISTS view_events_read_owner ON public.magazine_public_view_events;
CREATE POLICY view_events_read_owner ON public.magazine_public_view_events
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM magazines m
    WHERE m.id = magazine_public_view_events.magazine_id
      AND m.owner_id = (SELECT auth.uid())
  ));

-- ─── magazines ───────────────────────────────────────────────────────────────
DROP POLICY IF EXISTS magazines_admin_all ON public.magazines;
CREATE POLICY magazines_admin_all ON public.magazines
  FOR ALL TO authenticated
  USING (has_role((SELECT auth.uid()), 'admin'::app_role))
  WITH CHECK (has_role((SELECT auth.uid()), 'admin'::app_role));

-- ─── product_badge_definitions ───────────────────────────────────────────────
DROP POLICY IF EXISTS pbd_admin_delete ON public.product_badge_definitions;
CREATE POLICY pbd_admin_delete ON public.product_badge_definitions
  FOR DELETE TO authenticated
  USING (is_admin_or_above((SELECT auth.uid())) AND is_system = false);

DROP POLICY IF EXISTS pbd_admin_insert ON public.product_badge_definitions;
CREATE POLICY pbd_admin_insert ON public.product_badge_definitions
  FOR INSERT TO authenticated
  WITH CHECK (is_admin_or_above((SELECT auth.uid())));

DROP POLICY IF EXISTS pbd_admin_update ON public.product_badge_definitions;
CREATE POLICY pbd_admin_update ON public.product_badge_definitions
  FOR UPDATE TO authenticated
  USING (is_admin_or_above((SELECT auth.uid())))
  WITH CHECK (is_admin_or_above((SELECT auth.uid())));

-- ─── product_views ───────────────────────────────────────────────────────────
DROP POLICY IF EXISTS "Admins can read all views" ON public.product_views;
CREATE POLICY "Admins can read all views" ON public.product_views
  FOR SELECT TO authenticated
  USING (has_role((SELECT auth.uid()), 'admin'::app_role));

DROP POLICY IF EXISTS "Users can read own views" ON public.product_views;
CREATE POLICY "Users can read own views" ON public.product_views
  FOR SELECT TO authenticated
  USING (seller_id = (SELECT auth.uid()));

-- ─── quote_history ───────────────────────────────────────────────────────────
DROP POLICY IF EXISTS "Sellers and coord view quote_history" ON public.quote_history;
CREATE POLICY "Sellers and coord view quote_history" ON public.quote_history
  FOR SELECT TO authenticated
  USING (
    is_coord_or_above((SELECT auth.uid()))
    OR (EXISTS (
      SELECT 1 FROM quotes q
      WHERE q.id = quote_history.quote_id
        AND (
          q.seller_id    = (SELECT auth.uid())
          OR q.created_by = (SELECT auth.uid())
          OR q.assigned_to = (SELECT auth.uid())
        )
    ))
  );

DROP POLICY IF EXISTS "Sellers and coord create quote_history" ON public.quote_history;
CREATE POLICY "Sellers and coord create quote_history" ON public.quote_history
  FOR INSERT TO authenticated
  WITH CHECK (
    user_id = (SELECT auth.uid())
    AND (
      is_coord_or_above((SELECT auth.uid()))
      OR (EXISTS (
        SELECT 1 FROM quotes q
        WHERE q.id = quote_history.quote_id
          AND (
            q.seller_id    = (SELECT auth.uid())
            OR q.created_by = (SELECT auth.uid())
            OR q.assigned_to = (SELECT auth.uid())
          )
      ))
    )
  );;

-- <<< END 20260716130057_perf_auth_rls_initplan_fix.sql <<<

