-- >>> BEGIN 20260716133708_20260716000010_sec_rls_policy_always_true.sql >>>
-- SEC: Drop two INSERT policies with WITH CHECK = true (rls_policy_always_true WARN)
--
-- Supabase linter lint=0009_rls_policy_always_true flagged:
--   kit_component_enrichment_raw  → kcer_pipeline_insert  (WITH CHECK = true)
--   kit_component_padronizacao    → kcpad_pipeline_insert  (WITH CHECK = true)
--
-- Both policies apply to the {public} (= every role) pseudo-role, allowing any
-- authenticated or anonymous caller to INSERT into these tables unchecked.
--
-- Fix: DROP the open INSERT policies. Pipeline processes use service_role which
-- bypasses RLS entirely, so drops are non-breaking. Admin inserts remain covered
-- by the existing ALL policies (kcer_admin_all / kcpad_admin_write).

DROP POLICY IF EXISTS kcer_pipeline_insert  ON public.kit_component_enrichment_raw;
DROP POLICY IF EXISTS kcpad_pipeline_insert ON public.kit_component_padronizacao;

-- ─── Validate ─────────────────────────────────────────────────────────────────
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_policies
    WHERE tablename IN ('kit_component_enrichment_raw', 'kit_component_padronizacao')
      AND policyname IN ('kcer_pipeline_insert', 'kcpad_pipeline_insert')
  ) THEN
    RAISE EXCEPTION 'rls_policy_always_true fix FAILED — open INSERT policies still exist';
  END IF;

  RAISE NOTICE 'Dropped kcer_pipeline_insert and kcpad_pipeline_insert — WITH CHECK=true policies removed';
END;
$$;;

-- <<< END 20260716133708_20260716000010_sec_rls_policy_always_true.sql <<<

-- >>> BEGIN 20260716133953_20260716000011_sec_rls_enabled_no_policy.sql >>>
-- SEC: Add explicit policies to 42 tables with rls_enabled_no_policy (INFO)
--
-- Supabase linter lint=0008_rls_enabled_no_policy flagged 42 tables that have
-- RLS enabled but zero policies — all rows are blocked for every non-service_role
-- caller, which is usually a misconfiguration.
--
-- Three groups:
--   A) Partition tables: mirror parent's policies verbatim
--   B) Internal/pipeline/backup tables: admin-only ALL (non-admins stay blocked)
--   C) cf_recon schema: same admin-only pattern, fully-qualified function name
--
-- (SELECT auth.uid()) pattern used throughout — evaluated once per statement,
-- not once per row (auth_rls_initplan performance fix already applied).

-- ═══════════════════════════════════════════════════════════════════════════════
-- A) magazine_public_view_events partitions — mirror parent policies
-- ═══════════════════════════════════════════════════════════════════════════════

DO $do$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'magazine_public_view_events_2026_07',
    'magazine_public_view_events_2026_08',
    'magazine_public_view_events_2026_09',
    'magazine_public_view_events_2026_10',
    'magazine_public_view_events_default'
  ]
  LOOP
    EXECUTE format(
      'CREATE POLICY view_events_service_all ON public.%I
         FOR ALL TO service_role USING (true) WITH CHECK (true)',
      t
    );
    EXECUTE format(
      'CREATE POLICY view_events_read_admin ON public.%I
         FOR SELECT TO authenticated
         USING (has_role((SELECT auth.uid()), ''admin''::app_role))',
      t
    );
    EXECUTE format(
      'CREATE POLICY view_events_read_owner ON public.%I
         FOR SELECT TO authenticated
         USING (EXISTS (
           SELECT 1 FROM public.magazines m
           WHERE m.id = magazine_id
             AND m.owner_id = (SELECT auth.uid())
         ))',
      t
    );
  END LOOP;
END;
$do$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- A) supplier_products_raw_history partitions — mirror parent policies
-- ═══════════════════════════════════════════════════════════════════════════════

DO $do$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'supplier_products_raw_history_p2026_06',
    'supplier_products_raw_history_p2026_07',
    'supplier_products_raw_history_p2026_08',
    'supplier_products_raw_history_p2026_09',
    'supplier_products_raw_history_p2026_10'
  ]
  LOOP
    EXECUTE format(
      'CREATE POLICY hist_all_service ON public.%I
         FOR ALL TO service_role USING (true) WITH CHECK (true)',
      t
    );
    EXECUTE format(
      'CREATE POLICY hist_select_admin ON public.%I
         FOR SELECT TO authenticated
         USING (is_admin_or_above((SELECT auth.uid())))',
      t
    );
  END LOOP;
END;
$do$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- B) Internal / pipeline / backup tables in public schema — admin-only ALL
-- ═══════════════════════════════════════════════════════════════════════════════

DO $do$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    '_archive_product_ai_20260626',
    '_archive_product_seo_20260626',
    '_archive_supplier_price_tiers_20260626',
    '_bkp_kcvs_pre_normalize_20260624',
    '_bkp_kit_color_from_name_20260624',
    '_bkp_kit_packing_type_20260624',
    '_bkp_kit_pkg_material_20260624',
    '_qa_pct_results',
    'backup_produto_ramo_atividade_20260625',
    'cf_recon_inflight',
    'cron_job_timeout_map',
    'cron_watchdog_log',
    'eco_backfill_log_20260625',
    'eco_date_reconcile_log_20260626',
    'kit_component_ficha_staging',
    'kit_component_variant_skus',
    'kit_ficha_session_log',
    'magazine_view_rollup_watermark',
    'material_reconcile_log_20260626',
    'mcp_kv',
    'personalization_technique_mappings',
    'schema_signature_baseline',
    'schema_signature_drift_allowlist',
    'schema_signature_drift_log',
    'supplier_customization_raw',
    'webhook_delivery_locks'
  ]
  LOOP
    EXECUTE format(
      'CREATE POLICY admin_only ON public.%I
         FOR ALL TO authenticated
         USING (is_admin_or_above((SELECT auth.uid())))
         WITH CHECK (is_admin_or_above((SELECT auth.uid())))',
      t
    );
  END LOOP;
END;
$do$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- C) cf_recon schema — admin-only ALL (fully-qualified function)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $do$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'action_log',
    'cf_ghost_check_queue',
    'cf_image',
    'crawl_run',
    'metric_snapshot',
    'remediation'
  ]
  LOOP
    EXECUTE format(
      'CREATE POLICY admin_only ON cf_recon.%I
         FOR ALL TO authenticated
         USING (public.is_admin_or_above((SELECT auth.uid())))
         WITH CHECK (public.is_admin_or_above((SELECT auth.uid())))',
      t
    );
  END LOOP;
END;
$do$;

-- ─── Validate ─────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_still_no_policy integer;
BEGIN
  SELECT count(*) INTO v_still_no_policy
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE c.relkind = 'r'
    AND c.relrowsecurity = true
    AND n.nspname IN ('public', 'cf_recon')
    AND c.relname = ANY(ARRAY[
      'magazine_public_view_events_2026_07','magazine_public_view_events_2026_08',
      'magazine_public_view_events_2026_09','magazine_public_view_events_2026_10',
      'magazine_public_view_events_default',
      'supplier_products_raw_history_p2026_06','supplier_products_raw_history_p2026_07',
      'supplier_products_raw_history_p2026_08','supplier_products_raw_history_p2026_09',
      'supplier_products_raw_history_p2026_10',
      '_archive_product_ai_20260626','_archive_product_seo_20260626',
      '_archive_supplier_price_tiers_20260626','_bkp_kcvs_pre_normalize_20260624',
      '_bkp_kit_color_from_name_20260624','_bkp_kit_packing_type_20260624',
      '_bkp_kit_pkg_material_20260624','_qa_pct_results',
      'backup_produto_ramo_atividade_20260625','cf_recon_inflight',
      'cron_job_timeout_map','cron_watchdog_log','eco_backfill_log_20260625',
      'eco_date_reconcile_log_20260626','kit_component_ficha_staging',
      'kit_component_variant_skus','kit_ficha_session_log',
      'magazine_view_rollup_watermark','material_reconcile_log_20260626',
      'mcp_kv','personalization_technique_mappings','schema_signature_baseline',
      'schema_signature_drift_allowlist','schema_signature_drift_log',
      'supplier_customization_raw','webhook_delivery_locks',
      'action_log','cf_ghost_check_queue','cf_image','crawl_run',
      'metric_snapshot','remediation'
    ])
    AND NOT EXISTS (
      SELECT 1 FROM pg_policies p
      WHERE p.schemaname = n.nspname AND p.tablename = c.relname
    );

  IF v_still_no_policy > 0 THEN
    RAISE EXCEPTION 'rls_enabled_no_policy fix FAILED — % tables still have no policies', v_still_no_policy;
  END IF;

  RAISE NOTICE 'Policies added to 42 tables — rls_enabled_no_policy warnings resolved';
END;
$$;;

-- <<< END 20260716133953_20260716000011_sec_rls_enabled_no_policy.sql <<<

-- >>> BEGIN 20260716140313_perf_auth_rls_initplan_remaining.sql >>>
-- PERF: Fix remaining auth_rls_initplan — 10 policies across 8 tables
-- lint=0003_auth_rls_initplan WARN
--
-- Migration 000002 fixed high-traffic tables. This covers the 8 remaining
-- tables still calling auth.uid() / auth.role() / current_setting() without
-- the (SELECT ...) wrapper that prevents per-row re-evaluation.
--
-- Reference: https://supabase.com/docs/guides/database/database-linter?lint=0003_auth_rls_initplan

-- ─── kit_component_enrichment_raw ─────────────────────────────────────────────

DROP POLICY IF EXISTS kcer_admin_all ON public.kit_component_enrichment_raw;
CREATE POLICY kcer_admin_all ON public.kit_component_enrichment_raw
  FOR ALL TO public
  USING (is_admin_or_above((SELECT auth.uid())))
  WITH CHECK (is_admin_or_above((SELECT auth.uid())));

DROP POLICY IF EXISTS kcer_read_auth ON public.kit_component_enrichment_raw;
CREATE POLICY kcer_read_auth ON public.kit_component_enrichment_raw
  FOR SELECT TO public
  USING ((SELECT auth.uid()) IS NOT NULL);

-- ─── kit_component_padronizacao ───────────────────────────────────────────────

DROP POLICY IF EXISTS kcpad_admin_write ON public.kit_component_padronizacao;
CREATE POLICY kcpad_admin_write ON public.kit_component_padronizacao
  FOR ALL TO public
  USING (is_admin_or_above((SELECT auth.uid())))
  WITH CHECK (is_admin_or_above((SELECT auth.uid())));

DROP POLICY IF EXISTS kcpad_read_auth ON public.kit_component_padronizacao;
CREATE POLICY kcpad_read_auth ON public.kit_component_padronizacao
  FOR SELECT TO public
  USING ((SELECT auth.uid()) IS NOT NULL);

-- ─── magazine_public_reactions ────────────────────────────────────────────────

DROP POLICY IF EXISTS reactions_read_owner ON public.magazine_public_reactions;
CREATE POLICY reactions_read_owner ON public.magazine_public_reactions
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.magazines m
    WHERE m.id = magazine_public_reactions.magazine_id
      AND m.owner_id = (SELECT auth.uid())
  ));

-- ─── magazine_reader_state ────────────────────────────────────────────────────

DROP POLICY IF EXISTS reader_state_owner_read ON public.magazine_reader_state;
CREATE POLICY reader_state_owner_read ON public.magazine_reader_state
  FOR SELECT TO authenticated
  USING (user_id = (SELECT auth.uid()));

-- ─── pipeline_health_log ──────────────────────────────────────────────────────

DROP POLICY IF EXISTS pipeline_health_log_service_only ON public.pipeline_health_log;
CREATE POLICY pipeline_health_log_service_only ON public.pipeline_health_log
  FOR ALL TO public
  USING ((SELECT auth.role()) = 'service_role');

-- ─── smoke_test_runs ──────────────────────────────────────────────────────────
-- current_setting() also re-evaluates per-row without (SELECT ...)

DROP POLICY IF EXISTS smoke_insert_service_role ON public.smoke_test_runs;
CREATE POLICY smoke_insert_service_role ON public.smoke_test_runs
  FOR INSERT TO authenticated
  WITH CHECK (
    (SELECT COALESCE(current_setting('request.jwt.claim.role', true), '')) = 'service_role'
    OR is_admin_or_above((SELECT auth.uid()))
  );

-- ─── webhook_dispatcher_log ───────────────────────────────────────────────────

DROP POLICY IF EXISTS "Admins podem ler dispatcher_log" ON public.webhook_dispatcher_log;
CREATE POLICY "Admins podem ler dispatcher_log" ON public.webhook_dispatcher_log
  FOR SELECT TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.profiles
    WHERE profiles.id = (SELECT auth.uid())
      AND profiles.role = 'admin'
  ));

-- ─── workspace_notifications ─────────────────────────────────────────────────

DROP POLICY IF EXISTS "Authenticated can insert notifications for valid users" ON public.workspace_notifications;
CREATE POLICY "Authenticated can insert notifications for valid users" ON public.workspace_notifications
  FOR INSERT TO authenticated
  WITH CHECK (
    (SELECT auth.uid()) IS NOT NULL
    AND user_id IS NOT NULL
  );

-- ─── Validate ─────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_count integer;
BEGIN
  SELECT count(*) INTO v_count
  FROM pg_policies
  WHERE schemaname = 'public'
    AND (
      (tablename = 'kit_component_enrichment_raw' AND policyname IN ('kcer_admin_all', 'kcer_read_auth'))
      OR (tablename = 'kit_component_padronizacao'  AND policyname IN ('kcpad_admin_write', 'kcpad_read_auth'))
      OR (tablename = 'magazine_public_reactions'   AND policyname = 'reactions_read_owner')
      OR (tablename = 'magazine_reader_state'       AND policyname = 'reader_state_owner_read')
      OR (tablename = 'pipeline_health_log'         AND policyname = 'pipeline_health_log_service_only')
      OR (tablename = 'smoke_test_runs'             AND policyname = 'smoke_insert_service_role')
      OR (tablename = 'webhook_dispatcher_log'      AND policyname = 'Admins podem ler dispatcher_log')
      OR (tablename = 'workspace_notifications'     AND policyname = 'Authenticated can insert notifications for valid users')
    );

  IF v_count <> 10 THEN
    RAISE EXCEPTION 'auth_rls_initplan fix FAILED — expected 10 policies, found %', v_count;
  END IF;

  RAISE NOTICE 'auth_rls_initplan fixed — 10 policies across 8 tables now use (SELECT auth.*()) pattern';
END;
$$;;

-- <<< END 20260716140313_perf_auth_rls_initplan_remaining.sql <<<

-- >>> BEGIN 20260716140340_perf_multiple_permissive_policies.sql >>>
-- PERF: Consolidate multiple permissive RLS policies into single OR-ed policies
-- lint=0006_multiple_permissive_policies WARN — 10 combos across 9 tables
--
-- Multiple PERMISSIVE policies for the same (table, role, cmd) are OR-ed by
-- Postgres, forcing evaluation of every policy per row. A single policy with
-- an explicit OR condition is semantically identical but incurs only one
-- policy evaluation per row, reducing planner overhead significantly.
--
-- Reference: https://supabase.com/docs/guides/database/database-linter?lint=0006_multiple_permissive_policies

-- ─── catalog_analytics — SELECT authenticated ─────────────────────────────────
-- Merges: managers_read_all_catalog_analytics + users_read_own_analytics

DROP POLICY IF EXISTS managers_read_all_catalog_analytics ON public.catalog_analytics;
DROP POLICY IF EXISTS users_read_own_analytics             ON public.catalog_analytics;
CREATE POLICY catalog_analytics_read ON public.catalog_analytics
  FOR SELECT TO authenticated
  USING (
    is_manager_or_admin()
    OR (SELECT auth.uid()) = user_id
  );

-- ─── magazine_public_view_events (parent) — SELECT authenticated ──────────────
-- Merges: view_events_read_admin + view_events_read_owner

DROP POLICY IF EXISTS view_events_read_admin ON public.magazine_public_view_events;
DROP POLICY IF EXISTS view_events_read_owner ON public.magazine_public_view_events;
CREATE POLICY view_events_read ON public.magazine_public_view_events
  FOR SELECT TO authenticated
  USING (
    has_role((SELECT auth.uid()), 'admin'::app_role)
    OR EXISTS (
      SELECT 1 FROM public.magazines m
      WHERE m.id = magazine_public_view_events.magazine_id
        AND m.owner_id = (SELECT auth.uid())
    )
  );

-- ─── magazine_public_view_events partitions — SELECT authenticated ────────────

DO $do$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'magazine_public_view_events_2026_07',
    'magazine_public_view_events_2026_08',
    'magazine_public_view_events_2026_09',
    'magazine_public_view_events_2026_10',
    'magazine_public_view_events_default'
  ]
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS view_events_read_admin ON public.%I', t);
    EXECUTE format('DROP POLICY IF EXISTS view_events_read_owner ON public.%I', t);
    EXECUTE format(
      $fmt$
      CREATE POLICY view_events_read ON public.%I
        FOR SELECT TO authenticated
        USING (
          has_role((SELECT auth.uid()), 'admin'::app_role)
          OR EXISTS (
            SELECT 1 FROM public.magazines m
            WHERE m.id = %I.magazine_id
              AND m.owner_id = (SELECT auth.uid())
          )
        )
      $fmt$,
      t, t
    );
  END LOOP;
END;
$do$;

-- ─── magazines — ALL authenticated ────────────────────────────────────────────
-- Merges: magazines_admin_all + magazines_owner_all
-- USING: owner check includes deleted_at guard; admin check does not
-- WITH CHECK: owner check allows inserts (no deleted_at); admin check allows all

DROP POLICY IF EXISTS magazines_admin_all ON public.magazines;
DROP POLICY IF EXISTS magazines_owner_all ON public.magazines;
CREATE POLICY magazines_all ON public.magazines
  FOR ALL TO authenticated
  USING (
    has_role((SELECT auth.uid()), 'admin'::app_role)
    OR ((owner_id = (SELECT auth.uid())) AND (deleted_at IS NULL))
  )
  WITH CHECK (
    has_role((SELECT auth.uid()), 'admin'::app_role)
    OR (owner_id = (SELECT auth.uid()))
  );

-- ─── product_views — SELECT authenticated ─────────────────────────────────────
-- Merges: "Admins can read all views" + "Users can read own views"

DROP POLICY IF EXISTS "Admins can read all views" ON public.product_views;
DROP POLICY IF EXISTS "Users can read own views"  ON public.product_views;
CREATE POLICY product_views_read ON public.product_views
  FOR SELECT TO authenticated
  USING (
    has_role((SELECT auth.uid()), 'admin'::app_role)
    OR (seller_id = (SELECT auth.uid()))
  );

-- ─── smoke_test_runs — INSERT authenticated ───────────────────────────────────
-- smoke_insert_service_role (fixed in 000012) covers: service_role JWT OR admin
-- smoke_test_runs_insert_admin is a strict subset — drop it to eliminate
-- the multiple-policy overhead on every INSERT

DROP POLICY IF EXISTS smoke_test_runs_insert_admin ON public.smoke_test_runs;

-- ─── Validate ─────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_still_multiple integer;
BEGIN
  SELECT count(*) INTO v_still_multiple
  FROM (
    SELECT tablename, cmd, roles
    FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename IN (
        'catalog_analytics',
        'magazine_public_view_events',
        'magazine_public_view_events_2026_07',
        'magazine_public_view_events_2026_08',
        'magazine_public_view_events_2026_09',
        'magazine_public_view_events_2026_10',
        'magazine_public_view_events_default',
        'magazines',
        'product_views',
        'smoke_test_runs'
      )
      AND permissive = 'PERMISSIVE'
    GROUP BY tablename, cmd, roles
    HAVING count(*) > 1
  ) dup;

  IF v_still_multiple > 0 THEN
    RAISE EXCEPTION 'multiple_permissive_policies fix FAILED — % combos still have multiple permissive policies', v_still_multiple;
  END IF;

  RAISE NOTICE 'Consolidated multiple permissive policies — 10 combos across 9 tables resolved';
END;
$$;;

-- <<< END 20260716140340_perf_multiple_permissive_policies.sql <<<

