-- >>> BEGIN 20260716203920_fix_remaining_initplan_and_fk_index.sql >>>
-- Migration 038: Fix remaining auth_rls_initplan + unindexed FK on collection_products
--
-- Source: 200-commit audit + performance advisor follow-up (post-037 score check)
-- Findings addressed: 2
--   1) auth_rls_initplan (1 finding) — smoke_insert_service_role on smoke_test_runs
--   2) unindexed_foreign_keys (1 finding) — collection_products_product_id_fkey1
--
-- ─── Finding 1: auth_rls_initplan ────────────────────────────────────────────
--
-- Migration 033 already wrapped current_setting() and is_admin_or_above() in
-- (SELECT ...) subqueries, but left auth.uid() unwrapped *inside* the function:
--
--   ( SELECT is_admin_or_above(auth.uid()) )   ← auth.uid() re-evaluated per row
--
-- The correct pattern is:
--   ( SELECT is_admin_or_above((SELECT auth.uid())) )
--
-- ─── Finding 2: unindexed_foreign_keys ───────────────────────────────────────
--
-- collection_products.product_id (FK: collection_products_product_id_fkey1)
-- lacks a covering index. Migration 037 attempted to create
-- idx_collection_products_product_id but that name was already taken by
-- b2b_collection_products in the same schema. Fix: use idx_col_prods_product_id.

-- ═══════════════════════════════════════════════════════════════════════════════
-- 1) Fix auth_rls_initplan: smoke_insert_service_role
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = 'smoke_test_runs'
      AND c.relkind IN ('r', 'p')
  ) THEN
    DROP POLICY IF EXISTS smoke_insert_service_role ON public.smoke_test_runs;

    CREATE POLICY smoke_insert_service_role ON public.smoke_test_runs
      FOR INSERT TO authenticated
      WITH CHECK (
        (SELECT current_setting('request.jwt.claim.role', true)) = 'service_role'
        OR (SELECT is_admin_or_above((SELECT auth.uid())))
      );

    RAISE NOTICE '✓ [auth_rls_initplan] smoke_insert_service_role: auth.uid() now wrapped in its own InitPlan subquery';
  ELSE
    RAISE NOTICE '- public.smoke_test_runs not found — skipping';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 2) Fix unindexed FK: collection_products.product_id
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = 'collection_products'
      AND c.relkind IN ('r', 'p')
  ) THEN
    CREATE INDEX IF NOT EXISTS idx_col_prods_product_id
      ON public.collection_products (product_id);

    RAISE NOTICE '✓ [unindexed_foreign_keys] idx_col_prods_product_id created on collection_products(product_id)';
  ELSE
    RAISE NOTICE '- public.collection_products not found — skipping';
  END IF;
END;
$$;

-- ─── Validation ───────────────────────────────────────────────────────────────
DO $$
DECLARE
  wc_expr      text;
  idx_exists   boolean;
BEGIN
  SELECT pg_get_expr(polwithcheck, polrelid)
  INTO wc_expr
  FROM pg_policy
  WHERE polname = 'smoke_insert_service_role'
    AND polrelid = 'public.smoke_test_runs'::regclass;

  IF wc_expr IS NULL THEN
    RAISE WARNING 'Policy smoke_insert_service_role not found on smoke_test_runs';
  ELSIF wc_expr NOT LIKE '%(SELECT auth.uid())%' THEN
    RAISE WARNING 'Policy smoke_insert_service_role may still have un-wrapped auth.uid(): %', wc_expr;
  ELSE
    RAISE NOTICE '✓ smoke_insert_service_role WITH CHECK: %', wc_expr;
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE schemaname = 'public'
      AND tablename  = 'collection_products'
      AND indexname  = 'idx_col_prods_product_id'
  ) INTO idx_exists;

  IF idx_exists THEN
    RAISE NOTICE '✓ idx_col_prods_product_id confirmed on collection_products';
  ELSE
    RAISE WARNING 'idx_col_prods_product_id NOT FOUND on collection_products';
  END IF;

  RAISE NOTICE 'Migration 038 complete — auth_rls_initplan + unindexed_foreign_keys should clear on next advisor run.';
END;
$$;;

-- <<< END 20260716203920_fix_remaining_initplan_and_fk_index.sql <<<

-- >>> BEGIN 20260716204944_fix_security_anon_mcp_kv_and_bucket_listing.sql >>>
-- Migration 039: Fix security — revoke anon from mcp_kv_get + fix bucket listing

-- ═══════════════════════════════════════════════════════════════════════════════
-- 1) Revoke anon execute on mcp_kv_get
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'mcp_kv_get'
  ) THEN
    REVOKE EXECUTE ON FUNCTION public.mcp_kv_get(text, text) FROM anon;
    RAISE NOTICE '✓ [anon_security_definer_function_executable] REVOKE EXECUTE ON mcp_kv_get FROM anon';
  ELSE
    RAISE NOTICE '- public.mcp_kv_get not found — skipping';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 2) Fix mockup-assets bucket SELECT policy to prevent listing
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  DROP POLICY IF EXISTS "Authenticated users can view mockup assets" ON storage.objects;

  CREATE POLICY "Authenticated users can view mockup assets"
    ON storage.objects
    FOR SELECT TO authenticated
    USING (
      (bucket_id = 'mockup-assets'::text)
      AND (name IS NOT NULL)
      AND (length(name) > 0)
    );

  RAISE NOTICE '✓ [public_bucket_allows_listing] mockup-assets SELECT policy updated — listing prevention applied';
END;
$$;

-- ─── Validation ───────────────────────────────────────────────────────────────
DO $$
DECLARE
  anon_can_exec boolean;
  policy_qual   text;
BEGIN
  SELECT has_function_privilege('anon', 'public.mcp_kv_get(text, text)', 'EXECUTE')
  INTO anon_can_exec;

  IF anon_can_exec THEN
    RAISE WARNING 'anon still has EXECUTE on mcp_kv_get — revoke may have failed';
  ELSE
    RAISE NOTICE '✓ anon no longer has EXECUTE on mcp_kv_get';
  END IF;

  SELECT qual
  INTO policy_qual
  FROM pg_policies
  WHERE schemaname = 'storage'
    AND tablename  = 'objects'
    AND policyname = 'Authenticated users can view mockup assets';

  IF policy_qual IS NULL THEN
    RAISE WARNING 'Policy "Authenticated users can view mockup assets" not found';
  ELSIF policy_qual NOT LIKE '%name IS NOT NULL%' AND policy_qual NOT LIKE '%name is not null%' THEN
    RAISE WARNING 'Policy USING clause may still allow listing: %', policy_qual;
  ELSE
    RAISE NOTICE '✓ mockup-assets USING clause: %', policy_qual;
  END IF;

  RAISE NOTICE 'Migration 039 complete — 2 security findings addressed.';
END;
$$;;

-- <<< END 20260716204944_fix_security_anon_mcp_kv_and_bucket_listing.sql <<<

-- >>> BEGIN 20260716210637_fix_matview_api_and_anon_security_definer.sql >>>
-- Migration 040: Fix materialized_view_in_api + anon SECURITY DEFINER functions
--
-- Source: 200-commit audit + security advisor findings
-- Findings addressed: 3
--   1) materialized_view_in_api — public.mv_product_leaf_category
--   2) anon_security_definer_function_executable — public.fn_rpc_exists
--   3) anon_security_definer_function_executable — public.fn_get_product_intelligence_all

-- ═══════════════════════════════════════════════════════════════════════════════
-- 1) Fix materialized_view_in_api: convert v_products_public to SECURITY DEFINER
--    then revoke direct MV access from API roles
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = 'v_products_public' AND c.relkind = 'v'
  ) THEN
    ALTER VIEW public.v_products_public SET (security_invoker = false);
    RAISE NOTICE '✓ [materialized_view_in_api] v_products_public converted to SECURITY DEFINER';
  ELSE
    RAISE NOTICE '- v_products_public not found — skipping view alter';
  END IF;

  IF EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = 'mv_product_leaf_category' AND c.relkind = 'm'
  ) THEN
    REVOKE SELECT ON public.mv_product_leaf_category FROM anon, authenticated;
    RAISE NOTICE '✓ [materialized_view_in_api] REVOKE SELECT ON mv_product_leaf_category FROM anon, authenticated';
  ELSE
    RAISE NOTICE '- public.mv_product_leaf_category not found — skipping revoke';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 2) Revoke anon execute on fn_rpc_exists (schema introspection)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'fn_rpc_exists'
  ) THEN
    REVOKE EXECUTE ON FUNCTION public.fn_rpc_exists(text) FROM anon;
    RAISE NOTICE '✓ [anon_security_definer_function_executable] REVOKE EXECUTE ON fn_rpc_exists FROM anon';
  ELSE
    RAISE NOTICE '- public.fn_rpc_exists not found — skipping';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- 3) Revoke anon execute on fn_get_product_intelligence_all (internal inventory metrics)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'fn_get_product_intelligence_all'
  ) THEN
    REVOKE EXECUTE ON FUNCTION public.fn_get_product_intelligence_all() FROM anon;
    RAISE NOTICE '✓ [anon_security_definer_function_executable] REVOKE EXECUTE ON fn_get_product_intelligence_all FROM anon';
  ELSE
    RAISE NOTICE '- public.fn_get_product_intelligence_all not found — skipping';
  END IF;
END;
$$;

-- ─── Validation ───────────────────────────────────────────────────────────────
DO $$
DECLARE
  view_invoker    text;
  anon_mv_select  boolean;
  anon_rpc        boolean;
  anon_intel      boolean;
BEGIN
  SELECT opt INTO view_invoker
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  CROSS JOIN LATERAL unnest(c.reloptions) AS opt
  WHERE n.nspname = 'public' AND c.relname = 'v_products_public' AND c.relkind = 'v'
    AND opt LIKE 'security_invoker%';

  IF view_invoker IS NULL OR view_invoker = 'security_invoker=on' THEN
    RAISE WARNING 'v_products_public may still be SECURITY INVOKER: %', view_invoker;
  ELSE
    RAISE NOTICE '✓ v_products_public security setting: %', view_invoker;
  END IF;

  SELECT has_table_privilege('anon', 'public.mv_product_leaf_category', 'SELECT')
  INTO anon_mv_select;

  IF anon_mv_select THEN
    RAISE WARNING 'anon still has SELECT on mv_product_leaf_category';
  ELSE
    RAISE NOTICE '✓ anon no longer has SELECT on mv_product_leaf_category';
  END IF;

  SELECT has_function_privilege('anon', 'public.fn_rpc_exists(text)', 'EXECUTE')
  INTO anon_rpc;

  IF anon_rpc THEN
    RAISE WARNING 'anon still has EXECUTE on fn_rpc_exists';
  ELSE
    RAISE NOTICE '✓ anon no longer has EXECUTE on fn_rpc_exists';
  END IF;

  SELECT has_function_privilege('anon', 'public.fn_get_product_intelligence_all()', 'EXECUTE')
  INTO anon_intel;

  IF anon_intel THEN
    RAISE WARNING 'anon still has EXECUTE on fn_get_product_intelligence_all';
  ELSE
    RAISE NOTICE '✓ anon no longer has EXECUTE on fn_get_product_intelligence_all';
  END IF;

  RAISE NOTICE 'Migration 040 complete — 3 security findings addressed.';
END;
$$;;

