-- >>> BEGIN 20260716213415_fix_fn_super_filtro_cost_price_exposure_and_category_breadcrumb.sql >>>

-- Migration 041: Security fixes
--   1. fn_super_filtro was leaking products.cost_price to anon callers.
--      v_products_public correctly returns NULL::numeric AS cost_price but this
--      SECURITY DEFINER RPC bypassed that, exposing real cost data.
--      Fix: null out cost_price in base CTE and final SELECT.
--   2. fn_get_category_breadcrumb can be SECURITY INVOKER because anon already
--      has SELECT on the categories table → removes one anon_security_definer finding.

DO $migration$
BEGIN
  RAISE NOTICE '[041] Applying: fn_super_filtro cost_price redaction + fn_get_category_breadcrumb SECURITY INVOKER';
END;
$migration$;

-- ============================================================
-- FIX 1: fn_super_filtro — redact cost_price for anon callers
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_super_filtro(
  p_search_term      text        DEFAULT NULL::text,
  p_category_slug    text        DEFAULT NULL::text,
  p_category_id      uuid        DEFAULT NULL::uuid,
  p_brands           text[]      DEFAULT NULL::text[],
  p_only_in_stock    boolean     DEFAULT false,
  p_min_price        numeric     DEFAULT NULL::numeric,
  p_max_price        numeric     DEFAULT NULL::numeric,
  p_target_audiences text[]      DEFAULT NULL::text[],
  p_is_kit           boolean     DEFAULT NULL::boolean,
  p_is_textil        boolean     DEFAULT NULL::boolean,
  p_is_thermal       boolean     DEFAULT NULL::boolean,
  p_has_gift_box     boolean     DEFAULT NULL::boolean,
  p_material_groups  text[]      DEFAULT NULL::text[],
  p_technique_groups text[]      DEFAULT NULL::text[],
  p_color_groups     text[]      DEFAULT NULL::text[],
  p_date_slugs       text[]      DEFAULT NULL::text[],
  p_endomarketing    boolean     DEFAULT NULL::boolean,
  p_limit            integer     DEFAULT 50,
  p_offset           integer     DEFAULT 0,
  p_sort             text        DEFAULT 'name_asc'::text
)
RETURNS TABLE(
  id                 uuid,
  name               text,
  sku                text,
  slug               text,
  short_description  text,
  brand              character varying,
  sale_price         numeric,
  cost_price         numeric,   -- always NULL — intentional security redaction
  min_quantity       integer,
  stock_quantity     integer,
  is_stockout        boolean,
  is_kit             boolean,
  is_textil          boolean,
  is_thermal         boolean,
  is_featured        boolean,
  is_bestseller      boolean,
  is_new             boolean,
  has_gift_box       boolean,
  target_audience    text[],
  primary_image_url  text,
  og_image_url       text,
  set_image_url      text,
  category_id        uuid,
  category_name      text,
  category_slug      text,
  total_count        bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $fn_super_filtro$
DECLARE
  v_search_normalized  text;
  v_tsquery            tsquery;
  v_category_uuid      uuid;
  v_category_provided  boolean := false;
  v_limit              integer := GREATEST(0, LEAST(COALESCE(p_limit, 50), 1000));
  v_offset             integer := GREATEST(0, COALESCE(p_offset, 0));
BEGIN
  IF p_search_term IS NOT NULL AND length(trim(p_search_term)) > 0 THEN
    v_search_normalized := left(lower(unaccent(trim(p_search_term))), 200);
    BEGIN
      v_tsquery := websearch_to_tsquery('portuguese', v_search_normalized);
    EXCEPTION WHEN OTHERS THEN v_tsquery := NULL; END;
    PERFORM set_config('pg_trgm.similarity_threshold', '0.2', true);
  END IF;

  IF p_category_id IS NOT NULL THEN
    v_category_uuid     := p_category_id;
    v_category_provided := true;
  ELSIF p_category_slug IS NOT NULL THEN
    v_category_provided := true;
    SELECT c.id INTO v_category_uuid FROM categories c WHERE c.slug = p_category_slug LIMIT 1;
  END IF;

  RETURN QUERY
  WITH
  mat_filter AS (
    SELECT DISTINCT pm.product_id FROM product_materials pm
    JOIN material_types mt ON mt.id=pm.material_id JOIN material_groups mg ON mg.id=mt.group_id
    WHERE p_material_groups IS NOT NULL AND array_length(p_material_groups,1) > 0
      AND mg.name = ANY(p_material_groups) AND pm.is_active=true
  ),
  tech_filter AS (
    SELECT DISTINCT pat.product_id FROM print_area_techniques pat
    JOIN tabela_preco_gravacao_oficial tpgo ON tpgo.id=pat.tabela_preco_id
    WHERE p_technique_groups IS NOT NULL AND array_length(p_technique_groups,1) > 0
      AND tpgo.grupo_tecnica = ANY(p_technique_groups) AND pat.is_active=true
  ),
  color_filter AS (
    SELECT DISTINCT pv.product_id FROM product_variants pv
    JOIN color_variations cv ON cv.id=pv.color_id JOIN color_groups cg ON cg.id=cv.group_id
    WHERE p_color_groups IS NOT NULL AND array_length(p_color_groups,1) > 0
      AND cg.name = ANY(p_color_groups) AND pv.is_active=true
  ),
  date_filter AS (
    SELECT DISTINCT pcd.product_id FROM product_commemorative_dates pcd
    JOIN commemorative_dates cd ON cd.id=pcd.commemorative_date_id
    WHERE p_date_slugs IS NOT NULL AND array_length(p_date_slugs,1) > 0
      AND cd.slug = ANY(p_date_slugs) AND pcd.is_active=true
  ),
  endo_filter AS (
    SELECT DISTINCT pt.product_id FROM product_tags pt JOIN tags t ON t.id=pt.tag_id
    WHERE p_endomarketing=true AND t.slug='endomarketing' AND t.is_active=true
  ),
  cat_filter AS (
    SELECT DISTINCT pca.product_id FROM product_category_assignments pca
    WHERE v_category_uuid IS NOT NULL AND pca.category_id = v_category_uuid
  ),
  base AS (
    SELECT
      p.id, p.name, p.sku, p.slug, p.short_description, p.brand,
      p.sale_price,
      NULL::numeric AS cost_price,  -- SECURITY DEFINER/041: never expose cost_price to callers
      p.min_quantity, p.stock_quantity,
      p.is_stockout, p.is_kit, p.is_textil, p.is_thermal, p.is_featured,
      p.is_bestseller, p.is_new, p.has_gift_box, p.target_audience,
      p.primary_image_url, p.og_image_url, p.set_image_url,
      p.main_category_id AS category_id,
      c.name AS category_name, c.slug AS category_slug,
      CASE
        WHEN v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery
          THEN ts_rank_cd(p.search_vector, v_tsquery, 32)*2.0 + word_similarity(v_search_normalized, lower(unaccent(p.name)))
        WHEN v_search_normalized IS NOT NULL
          THEN word_similarity(v_search_normalized, lower(unaccent(p.name)))
        ELSE 0
      END AS relevance_score,
      COUNT(*) OVER() AS _total_count
    FROM products p
    LEFT JOIN categories c ON c.id = p.main_category_id
    WHERE
      p.is_active=true AND p.is_deleted IS NOT TRUE
      AND (v_search_normalized IS NULL
           OR (v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery)
           OR p.name % v_search_normalized
           OR lower(p.sku) LIKE '%'||v_search_normalized||'%')
      AND (
        NOT v_category_provided
        OR (v_category_uuid IS NOT NULL AND EXISTS (SELECT 1 FROM cat_filter cf WHERE cf.product_id=p.id))
      )
      AND (p_brands IS NULL OR array_length(p_brands,1) IS NULL OR p.brand = ANY(p_brands))
      AND (NOT p_only_in_stock OR p.is_stockout=false)
      AND (p_min_price IS NULL OR p.sale_price >= p_min_price)
      AND (p_max_price IS NULL OR p.sale_price <= p_max_price)
      AND (p_target_audiences IS NULL OR array_length(p_target_audiences,1) IS NULL OR p.target_audience && p_target_audiences)
      AND (p_is_kit IS NULL OR p.is_kit=p_is_kit)
      AND (p_is_textil IS NULL OR p.is_textil=p_is_textil)
      AND (p_is_thermal IS NULL OR p.is_thermal=p_is_thermal)
      AND (p_has_gift_box IS NULL OR p.has_gift_box=p_has_gift_box)
      AND (p_material_groups IS NULL  OR array_length(p_material_groups,1) IS NULL  OR EXISTS(SELECT 1 FROM mat_filter   mf WHERE mf.product_id=p.id))
      AND (p_technique_groups IS NULL OR array_length(p_technique_groups,1) IS NULL OR EXISTS(SELECT 1 FROM tech_filter  tf WHERE tf.product_id=p.id))
      AND (p_color_groups IS NULL     OR array_length(p_color_groups,1) IS NULL     OR EXISTS(SELECT 1 FROM color_filter cf WHERE cf.product_id=p.id))
      AND (p_date_slugs IS NULL       OR array_length(p_date_slugs,1) IS NULL       OR EXISTS(SELECT 1 FROM date_filter  df WHERE df.product_id=p.id))
      AND (p_endomarketing IS NULL OR p_endomarketing=false OR EXISTS(SELECT 1 FROM endo_filter ef WHERE ef.product_id=p.id))
  )
  SELECT
    b.id, b.name::text, b.sku::text, b.slug::text, b.short_description::text,
    b.brand, b.sale_price, b.cost_price, b.min_quantity, b.stock_quantity,
    b.is_stockout, b.is_kit, b.is_textil, b.is_thermal, b.is_featured,
    b.is_bestseller, b.is_new, b.has_gift_box, b.target_audience,
    b.primary_image_url, b.og_image_url, b.set_image_url,
    b.category_id, b.category_name::text, b.category_slug::text, b._total_count
  FROM base b
  ORDER BY
    CASE p_sort WHEN 'name_asc'   THEN b.name END ASC  NULLS LAST,
    CASE p_sort WHEN 'name_desc'  THEN b.name END DESC NULLS LAST,
    CASE p_sort WHEN 'price_asc'  THEN b.sale_price END ASC  NULLS LAST,
    CASE p_sort WHEN 'price_desc' THEN b.sale_price END DESC NULLS LAST,
    CASE p_sort WHEN 'relevance'  THEN b.relevance_score
                WHEN 'bestseller' THEN CASE WHEN b.is_bestseller THEN 1 ELSE 0 END::numeric
    END DESC NULLS LAST,
    b.is_featured DESC, b.is_bestseller DESC, b.name ASC
  LIMIT v_limit OFFSET v_offset;
END;
$fn_super_filtro$;

-- ============================================================
-- FIX 2: fn_get_category_breadcrumb → SECURITY INVOKER
-- anon already has SELECT on categories, so SECURITY DEFINER is unnecessary
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_get_category_breadcrumb(
  p_category_id uuid,
  p_separator   text DEFAULT ' > '::text
)
RETURNS text
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path TO 'public'
AS $fn_category_breadcrumb$
  WITH RECURSIVE breadcrumb AS (
    SELECT id, name, parent_id, 1 AS depth
    FROM categories WHERE id = p_category_id
    UNION ALL
    SELECT c.id, c.name, c.parent_id, b.depth + 1
    FROM categories c
    JOIN breadcrumb b ON b.parent_id = c.id
  )
  SELECT string_agg(name, p_separator ORDER BY depth DESC)
  FROM breadcrumb;
$fn_category_breadcrumb$;

-- ============================================================
-- VALIDATION
-- ============================================================
DO $validate$
DECLARE
  v_super_filtro_secdef boolean;
  v_breadcrumb_secdef   boolean;
BEGIN
  -- Verify fn_super_filtro still SECURITY DEFINER (intentional, needed for products access)
  SELECT prosecdef INTO v_super_filtro_secdef
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'fn_super_filtro';

  IF NOT v_super_filtro_secdef THEN
    RAISE EXCEPTION '[041] FAIL: fn_super_filtro should still be SECURITY DEFINER';
  END IF;
  RAISE NOTICE '[041] OK: fn_super_filtro is SECURITY DEFINER (correct)';

  -- Verify fn_get_category_breadcrumb is now SECURITY INVOKER
  SELECT prosecdef INTO v_breadcrumb_secdef
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'fn_get_category_breadcrumb';

  IF v_breadcrumb_secdef THEN
    RAISE EXCEPTION '[041] FAIL: fn_get_category_breadcrumb should now be SECURITY INVOKER';
  END IF;
  RAISE NOTICE '[041] OK: fn_get_category_breadcrumb is SECURITY INVOKER (correct)';

  RAISE NOTICE '[041] Migration 041 applied successfully';
END;
$validate$;
;

-- <<< END 20260716213415_fix_fn_super_filtro_cost_price_exposure_and_category_breadcrumb.sql <<<

-- >>> BEGIN 20260716214659_fix_fn_global_search_quote_data_exposure.sql >>>

-- Migration 042: Fix fn_global_search exposing all quotes to anon
--
-- VULNERABILITY: fn_global_search is SECURITY DEFINER callable by anon.
-- The quote search branch had NO auth filter → any anon user calling
--   SELECT * FROM fn_global_search('pending', 20, ARRAY['quote'])
-- would see quote_number, status, total, URL for ALL quotes system-wide.
--
-- FIX:
--   1. Gate the quote branch on auth.uid() IS NOT NULL (skip for anon)
--   2. Add q.created_by = auth.uid() so users only see their own quotes
--
-- Scenario simulation:
--   - anon calls fn_global_search('pending') → products return, quotes skip ✓
--   - authenticated user calls → sees only own quotes ✓
--   - admin sees all quotes → needs separate privileged function (existing behavior
--     was already broken from a security standpoint, so this is net improvement)

DO $migration$
BEGIN
  RAISE NOTICE '[042] Applying: fn_global_search quote data exposure fix';
END;
$migration$;

CREATE OR REPLACE FUNCTION public.fn_global_search(
  p_term   text,
  p_limit  integer DEFAULT 12,
  p_types  text[]  DEFAULT ARRAY['product'::text, 'quote'::text]
)
RETURNS TABLE(
  result_id          text,
  result_type        text,
  result_title       text,
  result_description text,
  result_url         text,
  result_image_url   text,
  result_metadata    jsonb,
  result_relevance   numeric
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $fn_global_search$
DECLARE
  v_term_norm text;
  v_tsquery   tsquery;
  v_lim_each  integer;
BEGIN
  IF p_term IS NULL OR length(trim(p_term)) < 2 THEN RETURN; END IF;
  IF p_limit IS NULL OR p_limit <= 0 THEN RETURN; END IF;

  v_term_norm := lower(unaccent(trim(p_term)));
  v_lim_each  := GREATEST(1, p_limit / GREATEST(array_length(p_types, 1), 1));

  BEGIN
    v_tsquery := websearch_to_tsquery('portuguese', unaccent(trim(p_term)));
  EXCEPTION WHEN OTHERS THEN v_tsquery := NULL;
  END;

  PERFORM set_config('pg_trgm.similarity_threshold', '0.2', true);

  -- ── Product search (public, available to anon) ──────────────
  IF 'product' = ANY(p_types) THEN
    RETURN QUERY
    SELECT p.id::text, 'product'::text, p.name::text,
      ('SKU: ' || p.sku || CASE WHEN c.name IS NOT NULL THEN ' · ' || c.name ELSE '' END)::text,
      ('/produtos/' || p.slug)::text, p.primary_image_url,
      jsonb_build_object('sku', p.sku, 'price', p.sale_price,
                         'stock', COALESCE(vs.total_stock, 0), 'category', COALESCE(c.name, '')),
      (CASE WHEN v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery
            THEN ts_rank_cd(p.search_vector, v_tsquery, 32) * 2.0 ELSE 0 END +
       word_similarity(v_term_norm, lower(unaccent(p.name))) * 1.0 +
       CASE WHEN lower(p.sku) LIKE '%' || v_term_norm || '%' THEN 0.8 ELSE 0 END +
       CASE WHEN COALESCE(vs.total_stock, 0) > 0 THEN 0.2 ELSE 0 END)::numeric
    FROM products p
    LEFT JOIN product_category_assignments pca ON pca.product_id = p.id AND pca.is_primary = true
    LEFT JOIN categories c ON c.id = pca.category_id
    LEFT JOIN LATERAL (
      SELECT COALESCE(SUM(pv.stock_quantity), 0)::int AS total_stock
      FROM product_variants pv
      WHERE pv.product_id = p.id AND pv.is_active = true
    ) vs ON true
    WHERE p.is_active = true
      AND p.is_deleted IS NOT TRUE
      AND p.sale_price IS NOT NULL
      AND p.slug IS NOT NULL AND p.slug != ''
      AND (
        (v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery)
        OR p.name % v_term_norm
        OR lower(p.sku) LIKE '%' || v_term_norm || '%'
      )
    ORDER BY 8 DESC LIMIT v_lim_each;
  END IF;

  -- ── Quote search (authenticated only; scoped to caller's quotes) ──
  -- SECURITY/042: gate on auth.uid() IS NOT NULL — anon gets no quote data.
  -- Row filter q.created_by = auth.uid() prevents cross-user data leakage.
  -- This function is SECURITY DEFINER so RLS is bypassed; the explicit
  -- WHERE clause is the only row-level guard here.
  IF 'quote' = ANY(p_types) AND auth.uid() IS NOT NULL THEN
    RETURN QUERY
    SELECT q.id::text, 'quote'::text, COALESCE(q.quote_number, 'Orçamento')::text,
      ('Status: ' || COALESCE(q.status, '—') ||
       CASE WHEN q.total IS NOT NULL THEN ' · R$ ' || to_char(q.total, 'FM999G999G990D00') ELSE '' END)::text,
      ('/orcamentos/' || q.id::text)::text, NULL::text,
      jsonb_build_object('status', q.status, 'total', q.total, 'created_at', q.created_at),
      CASE WHEN lower(COALESCE(q.quote_number, '')) LIKE '%' || v_term_norm || '%' THEN 0.9
           WHEN lower(COALESCE(q.status, ''))        LIKE '%' || v_term_norm || '%' THEN 0.5
           ELSE 0.3 END::numeric
    FROM quotes q
    WHERE q.created_by = auth.uid()   -- SECURITY/042: scope to caller's quotes only
      AND (
        lower(COALESCE(q.quote_number, '')) LIKE '%' || v_term_norm || '%'
        OR lower(COALESCE(q.status, ''))    LIKE '%' || v_term_norm || '%'
      )
    ORDER BY 8 DESC, q.created_at DESC LIMIT v_lim_each;
  END IF;
END;
$fn_global_search$;

-- ── VALIDATION ────────────────────────────────────────────────
DO $validate$
DECLARE
  v_def text;
BEGIN
  SELECT pg_get_functiondef(p.oid) INTO v_def
  FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'fn_global_search';

  IF v_def NOT LIKE '%auth.uid() IS NOT NULL%' THEN
    RAISE EXCEPTION '[042] FAIL: anon guard not present in fn_global_search';
  END IF;
  IF v_def NOT LIKE '%created_by = auth.uid()%' THEN
    RAISE EXCEPTION '[042] FAIL: row-level filter not present in fn_global_search';
  END IF;
  RAISE NOTICE '[042] OK: fn_global_search has auth guard + row filter';
  RAISE NOTICE '[042] Migration 042 applied successfully';
END;
$validate$;
;

-- <<< END 20260716214659_fix_fn_global_search_quote_data_exposure.sql <<<

-- >>> BEGIN 20260717000063_fix_public_grant_revoke_and_analytics_schema.sql >>>
-- Migration 063: Fix remaining pg_graphql_anon_table_exposed + security_definer_view
--
-- Source: 200-commit audit — post-062 advisor check
-- Findings addressed:
--   pg_graphql_anon_table_exposed : 9 → 0 (public + analytics schemas)
--   security_definer_view         : 3 → 0 (views missing security_invoker=true)
--
-- ─── Root Causes ─────────────────────────────────────────────────────────────
--
-- 1. PUBLIC grant problem (public schema tables/views):
--    Migrations 060 and 062 used REVOKE FROM anon — a no-op when the privilege
--    came from a PUBLIC grant (=SELECT/postgres in proacl). The tables
--    categories, products, suppliers and views category_icons, v_suppliers_public
--    have PUBLIC SELECT; anon is a member of PUBLIC, so it inherits that access.
--    Fix: REVOKE FROM PUBLIC + GRANT TO authenticated (preserve app access).
--
-- 2. Analytics schema not covered:
--    Migrations 058–062 targeted only public schema. Four materialized views in
--    the analytics schema still have anon SELECT via PUBLIC grants.
--    Fix: dynamic sweep of analytics schema — REVOKE FROM PUBLIC, anon, authenticated.
--
-- 3. security_invoker not set on 3 views:
--    Migration 061 silently failed (EXCEPTION caught) for category_icons,
--    v_suppliers_public, mv_stock_velocity. These still have reloptions=null.
--    Fix for category_icons and v_suppliers_public: CREATE OR REPLACE VIEW WITH
--    (security_invoker = true) using the exact same definition.
--    Fix for mv_stock_velocity: ALTER VIEW with fallback to revoke direct access
--    (wraps analytics.mv_stock_velocity which authenticated cannot access directly).
--
-- ─── Safety Analysis ─────────────────────────────────────────────────────────
--
-- REVOKE FROM PUBLIC + GRANT TO authenticated:
--   • anon loses SELECT (no longer member-of-PUBLIC path) — correct for B2B
--   • authenticated gains explicit SELECT, same effective access as before
--   • service_role (BYPASSRLS) and postgres superuser: unaffected
--   • SECURITY DEFINER functions (run as owner): unaffected
--
-- ALTER DEFAULT PRIVILEGES: prevents future DDL from re-adding PUBLIC SELECT.
--   Only affects future objects; no impact on existing grants.
--
-- CREATE OR REPLACE VIEW preserves existing grants to other roles (authenticated).
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- REVOKE when grant doesn't exist → no-op
-- GRANT when already granted → no-op
-- ALTER DEFAULT PRIVILEGES → idempotent
-- CREATE OR REPLACE VIEW → idempotent

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: ALTER DEFAULT PRIVILEGES — prevent future PUBLIC grants
-- ═══════════════════════════════════════════════════════════════════════════════

ALTER DEFAULT PRIVILEGES IN SCHEMA public
  REVOKE SELECT ON TABLES FROM PUBLIC;

ALTER DEFAULT PRIVILEGES IN SCHEMA analytics
  REVOKE SELECT ON TABLES FROM PUBLIC;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Fix public schema tables with PUBLIC SELECT grants
--          (categories, products, suppliers confirmed still anon-accessible)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r    RECORD;
  v_ok int := 0;
BEGIN
  FOR r IN
    SELECT c.relname, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p')
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM PUBLIC', r.relname);
      EXECUTE format('GRANT SELECT ON public.%I TO authenticated', r.relname);
      v_ok := v_ok + 1;
      RAISE NOTICE '[063] table public.%: REVOKE FROM PUBLIC + GRANT TO authenticated', r.relname;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[063] table public.%: failed: %', r.relname, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 THEN
    RAISE NOTICE '[063] Phase 2: no public tables with anon SELECT found — already clean';
  ELSE
    RAISE NOTICE '[063] Phase 2: fixed % public table(s)', v_ok;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 3: Fix public schema views with PUBLIC SELECT grants
--          (category_icons, v_suppliers_public confirmed still anon-accessible)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r    RECORD;
  v_ok int := 0;
BEGIN
  FOR r IN
    SELECT c.relname, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'v'
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM PUBLIC', r.relname);
      EXECUTE format('GRANT SELECT ON public.%I TO authenticated', r.relname);
      v_ok := v_ok + 1;
      RAISE NOTICE '[063] view public.%: REVOKE FROM PUBLIC + GRANT TO authenticated', r.relname;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[063] view public.%: failed: %', r.relname, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 THEN
    RAISE NOTICE '[063] Phase 3: no public views with anon SELECT found — already clean';
  ELSE
    RAISE NOTICE '[063] Phase 3: fixed % public view(s)', v_ok;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 4: Set security_invoker=true on views that still lack it
--          Use CREATE OR REPLACE VIEW (avoids ALTER VIEW silent failure)
-- ═══════════════════════════════════════════════════════════════════════════════

-- 4a: category_icons — queries: SELECT ... FROM categories WHERE icon IS NOT NULL
CREATE OR REPLACE VIEW public.category_icons
  WITH (security_invoker = true)
AS
 SELECT id,
    name AS category_name,
    icon,
    NULL::text AS description,
    is_active
   FROM categories c
  WHERE icon IS NOT NULL;

-- 4b: v_suppliers_public — queries: SELECT ... FROM suppliers
CREATE OR REPLACE VIEW public.v_suppliers_public
  WITH (security_invoker = true)
AS
 SELECT id,
    name,
    code,
    trading_name,
    logo_url,
    website,
    active,
    is_product_supplier,
    is_engraving_supplier,
    state_uf,
    low_stock_threshold
   FROM suppliers;

-- 4c: mv_stock_velocity — wraps analytics.mv_stock_velocity (cross-schema)
--     authenticated cannot SELECT from analytics matviews directly (migration 058)
--     so we try ALTER VIEW; if that fails, revoke direct access as fallback
DO $$
BEGIN
  ALTER VIEW public.mv_stock_velocity SET (security_invoker = true);
  RAISE NOTICE '[063] mv_stock_velocity: SET (security_invoker = true) — ok';
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[063] mv_stock_velocity: ALTER VIEW failed (%), revoking direct access', SQLERRM;
  BEGIN
    REVOKE SELECT ON public.mv_stock_velocity FROM PUBLIC, anon, authenticated;
    RAISE NOTICE '[063] mv_stock_velocity: direct access revoked (fallback)';
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[063] mv_stock_velocity: fallback revoke also failed: %', SQLERRM;
  END;
END;
$$;

-- 4d: Final sweep — catch any remaining views without security_invoker=true
DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_fail int := 0;
BEGIN
  FOR r IN
    SELECT c.relname
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'v'
      AND NOT (
        c.reloptions IS NOT NULL
        AND 'security_invoker=true' = ANY(c.reloptions)
      )
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('ALTER VIEW public.%I SET (security_invoker = true)', r.relname);
      v_ok := v_ok + 1;
      RAISE NOTICE '[063] sweep: SET security_invoker=true on public.%', r.relname;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[063] sweep: could not set security_invoker on public.%: %',
        r.relname, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[063] Phase 4 sweep: updated=%, failed=%', v_ok, v_fail;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 5: Analytics schema — revoke direct access from all relations
--          (matviews have no RLS; should only be accessed via SECURITY DEFINER)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r       RECORD;
  v_ok    int := 0;
  v_clean int := 0;
  v_anon_ok  boolean;
  v_auth_ok  boolean;
BEGIN
  -- Check if analytics schema exists first
  IF NOT EXISTS (
    SELECT 1 FROM pg_namespace WHERE nspname = 'analytics'
  ) THEN
    RAISE NOTICE '[063] analytics schema does not exist — skipping Phase 5';
    RETURN;
  END IF;

  FOR r IN
    SELECT c.relname, c.oid, c.relkind
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'analytics'
      AND c.relkind IN ('r', 'p', 'm', 'v')
    ORDER BY c.relname
  LOOP
    BEGIN
      v_anon_ok := has_table_privilege('anon', r.oid, 'SELECT');
    EXCEPTION WHEN OTHERS THEN
      v_anon_ok := false;
    END;
    BEGIN
      v_auth_ok := has_table_privilege('authenticated', r.oid, 'SELECT');
    EXCEPTION WHEN OTHERS THEN
      v_auth_ok := false;
    END;

    IF NOT v_anon_ok AND NOT v_auth_ok THEN
      v_clean := v_clean + 1;
      CONTINUE;
    END IF;

    BEGIN
      EXECUTE format(
        'REVOKE SELECT ON analytics.%I FROM PUBLIC, anon, authenticated',
        r.relname
      );
      v_ok := v_ok + 1;
      RAISE NOTICE '[063] analytics.%: revoked (relkind=%)', r.relname, r.relkind;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[063] analytics.%: revoke failed: %', r.relname, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[063] Phase 5: analytics revoked=%, already_clean=%', v_ok, v_clean;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 6: Validation
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_anon_public    int;
  v_anon_analytics int;
  v_secdef_views   int;
  r                RECORD;
BEGIN
  SELECT count(*) INTO v_anon_public
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p', 'm', 'v')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  SELECT count(*) INTO v_anon_analytics
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'analytics'
    AND c.relkind IN ('r', 'p', 'm', 'v')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  SELECT count(*) INTO v_secdef_views
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'v'
    AND NOT (
      c.reloptions IS NOT NULL
      AND 'security_invoker=true' = ANY(c.reloptions)
    );

  RAISE NOTICE '[063] Validation: public anon=%, analytics anon=%, views_without_securityinvoker=%',
    v_anon_public, v_anon_analytics, v_secdef_views;

  IF v_anon_public = 0 THEN
    RAISE NOTICE '[063] pg_graphql_anon_table_exposed (public): CLEARED';
  ELSE
    RAISE WARNING '[063] % public relation(s) still anon-accessible:', v_anon_public;
    FOR r IN
      SELECT c.relname, c.relkind
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind IN ('r', 'p', 'm', 'v')
        AND has_table_privilege('anon', c.oid, 'SELECT')
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[063]   still accessible: public.% (relkind=%)', r.relname, r.relkind;
    END LOOP;
  END IF;

  IF v_anon_analytics = 0 THEN
    RAISE NOTICE '[063] pg_graphql_anon_table_exposed (analytics): CLEARED';
  ELSE
    RAISE WARNING '[063] % analytics relation(s) still anon-accessible', v_anon_analytics;
  END IF;

  IF v_secdef_views = 0 THEN
    RAISE NOTICE '[063] security_definer_view: CLEARED — all public views have security_invoker=true';
  ELSE
    RAISE WARNING '[063] % public view(s) still missing security_invoker=true', v_secdef_views;
    FOR r IN
      SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind = 'v'
        AND NOT (
          c.reloptions IS NOT NULL
          AND 'security_invoker=true' = ANY(c.reloptions)
        )
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[063]   missing security_invoker: public.%', r.relname;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 063 complete.';
END;
$$;

-- <<< END 20260717000063_fix_public_grant_revoke_and_analytics_schema.sql <<<

-- >>> BEGIN 20260717000064_revoke_direct_anon_select_remaining.sql >>>
-- Migration 064: Revoke direct anon SELECT on remaining 3 public objects
--
-- Source: 200-commit audit — post-063 ACL inspection
-- Findings addressed: pg_graphql_anon_table_exposed (remaining 3 real hits)
--
-- ─── Root Cause ──────────────────────────────────────────────────────────────
--
-- After migration 063 revoked the PUBLIC SELECT grant:
--   • products and suppliers became clean (anon had only PUBLIC access)
--   • categories, category_icons, v_suppliers_public still have anon access
--
-- Direct ACL inspection reveals explicit grants to anon:
--   categories       → anon=rm/postgres  (SELECT+MAINTAIN directly granted to anon)
--   category_icons   → anon=rm/postgres  (same)
--   v_suppliers_public → anon=rm/postgres  (same)
--
-- These explicit grants survived REVOKE FROM PUBLIC because they are separate
-- ACL entries. The fix is REVOKE SELECT FROM anon (not FROM PUBLIC).
--
-- ─── Safety Analysis ─────────────────────────────────────────────────────────
--
-- • categories: authenticated=arwdxtm (has SELECT) — revoke only affects anon
-- • category_icons: authenticated=rm (has SELECT) — revoke only affects anon
-- • v_suppliers_public: authenticated=rm (has SELECT) — revoke only affects anon
--
-- Auth flow functions (SECURITY DEFINER, run as owner): unaffected.
-- service_role (BYPASSRLS): unaffected.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- REVOKE when grant doesn't exist → no-op in PostgreSQL.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Revoke explicit anon SELECT on the 3 remaining objects
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_skip int := 0;
BEGIN
  FOR r IN
    SELECT c.relname, c.oid, c.relkind
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p', 'v', 'm')
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      -- REVOKE explicit anon SELECT (direct grant, not via PUBLIC)
      EXECUTE format('REVOKE SELECT ON public.%I FROM anon', r.relname);
      v_ok := v_ok + 1;
      RAISE NOTICE '[064] REVOKE SELECT ON public.% FROM anon (relkind=%)',
        r.relname, r.relkind;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[064] Failed REVOKE on public.%: %', r.relname, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 THEN
    RAISE NOTICE '[064] Phase 1: No public objects with anon SELECT found — already clean';
  ELSE
    RAISE NOTICE '[064] Phase 1: Revoked anon SELECT on % object(s)', v_ok;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Also ensure no PUBLIC grant lingered (belt-and-suspenders)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r    RECORD;
  v_ok int := 0;
BEGIN
  FOR r IN
    SELECT c.relname, c.oid, c.relkind
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p', 'v', 'm')
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM PUBLIC', r.relname);
      v_ok := v_ok + 1;
      RAISE NOTICE '[064] Belt-and-suspenders: REVOKE FROM PUBLIC on public.%', r.relname;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[064] Failed PUBLIC revoke on public.%: %', r.relname, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 THEN
    RAISE NOTICE '[064] Phase 2: No residual PUBLIC grants found';
  ELSE
    RAISE NOTICE '[064] Phase 2: Removed % PUBLIC grant(s)', v_ok;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 3: Validate
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int;
  r           RECORD;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p', 'v', 'm')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  IF v_remaining = 0 THEN
    RAISE NOTICE '[064] All public relations: anon SELECT fully revoked — pg_graphql_anon_table_exposed (public) CLEARED';
  ELSE
    RAISE WARNING '[064] % public relation(s) still anon-accessible:', v_remaining;
    FOR r IN
      SELECT c.relname, c.relkind
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind IN ('r', 'p', 'v', 'm')
        AND has_table_privilege('anon', c.oid, 'SELECT')
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[064]   still accessible: public.% (relkind=%)', r.relname, r.relkind;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 064 complete.';
END;
$$;

-- <<< END 20260717000064_revoke_direct_anon_select_remaining.sql <<<

-- >>> BEGIN 20260717000065_drop_unused_indexes.sql >>>
-- Migration 065: Drop unused indexes (performance — unused_index)
--
-- Source: 200-commit audit — Supabase performance advisor
-- Findings addressed: unused_index (215 hits)
--
-- ─── Root Cause ──────────────────────────────────────────────────────────────
--
-- Many indexes were created speculatively or by ORM tooling and have never
-- been used (idx_scan = 0 in pg_stat_user_indexes). Unused indexes:
--   • Impose write overhead on every INSERT/UPDATE/DELETE
--   • Consume disk space and shared_buffers
--   • Slow VACUUM (more pages to update)
--   • Confuse the query planner (more choices → more planning time)
--
-- ─── Safety Analysis ─────────────────────────────────────────────────────────
--
-- Excluded from drop:
--   • Primary key indexes (indisprimary = true)
--   • Unique constraint indexes (indisunique = true)
--   • Exclusion constraint indexes (indisexclusion = true)
--   • Any index the DROP fails on (per-index EXCEPTION handler)
--
-- If a DROP fails (e.g. index has dependents), the EXCEPTION handler logs a
-- WARNING and continues. The migration never fails hard.
--
-- Note: pg_stat_user_indexes.idx_scan resets on pg_stat_reset() or restart.
-- We trust the Supabase advisor's 215-finding output as ground truth.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- DROP INDEX IF EXISTS → no-op if already dropped.
-- Re-running is safe.
--
-- ─── Note on CONCURRENTLY ────────────────────────────────────────────────────
--
-- DROP INDEX CONCURRENTLY cannot run inside a transaction block.
-- Supabase migrations run inside transactions, so we use regular DROP INDEX.
-- Brief table locks are acceptable during a planned migration window.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Drop unused non-constraint indexes in public schema
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_skip int := 0;
BEGIN
  FOR r IN
    SELECT
      psi.indexrelname  AS index_name,
      psi.relname       AS table_name,
      psi.idx_scan
    FROM pg_stat_user_indexes psi
    JOIN pg_index          pi  ON pi.indexrelid  = psi.indexrelid
    JOIN pg_class          ic  ON ic.oid          = psi.indexrelid
    JOIN pg_namespace      n   ON n.oid           = ic.relnamespace
    WHERE psi.schemaname = 'public'
      AND psi.idx_scan   = 0          -- never used
      AND NOT pi.indisprimary         -- not primary key
      AND NOT pi.indisunique          -- not unique constraint
      AND NOT pi.indisexclusion       -- not exclusion constraint
    ORDER BY psi.relname, psi.indexrelname
  LOOP
    BEGIN
      EXECUTE format('DROP INDEX IF EXISTS public.%I', r.index_name);
      v_ok := v_ok + 1;
      RAISE NOTICE '[065] Dropped index: public.% (table=%, scans=%)',
        r.index_name, r.table_name, r.idx_scan;
    EXCEPTION WHEN OTHERS THEN
      v_skip := v_skip + 1;
      RAISE WARNING '[065] Could not drop public.%: %', r.index_name, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 AND v_skip = 0 THEN
    RAISE NOTICE '[065] Phase 1: No unused non-constraint indexes found — already clean';
  ELSE
    RAISE NOTICE '[065] Phase 1: dropped=%, failed=%', v_ok, v_skip;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Same sweep for analytics schema (if exists)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_skip int := 0;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'analytics') THEN
    RAISE NOTICE '[065] Phase 2: analytics schema does not exist — skipping';
    RETURN;
  END IF;

  FOR r IN
    SELECT
      psi.indexrelname  AS index_name,
      psi.relname       AS table_name,
      psi.idx_scan
    FROM pg_stat_user_indexes psi
    JOIN pg_index          pi  ON pi.indexrelid  = psi.indexrelid
    JOIN pg_class          ic  ON ic.oid          = psi.indexrelid
    JOIN pg_namespace      n   ON n.oid           = ic.relnamespace
    WHERE psi.schemaname = 'analytics'
      AND psi.idx_scan   = 0
      AND NOT pi.indisprimary
      AND NOT pi.indisunique
      AND NOT pi.indisexclusion
    ORDER BY psi.relname, psi.indexrelname
  LOOP
    BEGIN
      EXECUTE format('DROP INDEX IF EXISTS analytics.%I', r.index_name);
      v_ok := v_ok + 1;
      RAISE NOTICE '[065] Dropped index: analytics.% (table=%)', r.index_name, r.table_name;
    EXCEPTION WHEN OTHERS THEN
      v_skip := v_skip + 1;
      RAISE WARNING '[065] Could not drop analytics.%: %', r.index_name, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 AND v_skip = 0 THEN
    RAISE NOTICE '[065] Phase 2: No unused analytics indexes found — already clean';
  ELSE
    RAISE NOTICE '[065] Phase 2: dropped=%, failed=%', v_ok, v_skip;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 3: Validate — count remaining unused indexes
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining_public    int;
  v_remaining_analytics int;
  r                     RECORD;
BEGIN
  SELECT count(*) INTO v_remaining_public
  FROM pg_stat_user_indexes psi
  JOIN pg_index pi ON pi.indexrelid = psi.indexrelid
  WHERE psi.schemaname = 'public'
    AND psi.idx_scan   = 0
    AND NOT pi.indisprimary
    AND NOT pi.indisunique
    AND NOT pi.indisexclusion;

  SELECT count(*) INTO v_remaining_analytics
  FROM pg_stat_user_indexes psi
  JOIN pg_index pi ON pi.indexrelid = psi.indexrelid
  WHERE psi.schemaname = 'analytics'
    AND psi.idx_scan   = 0
    AND NOT pi.indisprimary
    AND NOT pi.indisunique
    AND NOT pi.indisexclusion;

  RAISE NOTICE '[065] Validation: remaining unused public=%, analytics=%',
    v_remaining_public, v_remaining_analytics;

  IF v_remaining_public = 0 THEN
    RAISE NOTICE '[065] public schema: unused_index CLEARED';
  ELSE
    RAISE WARNING '[065] % unused index(es) remain in public (check warnings above)', v_remaining_public;
    FOR r IN
      SELECT psi.indexrelname, psi.relname
      FROM pg_stat_user_indexes psi
      JOIN pg_index pi ON pi.indexrelid = psi.indexrelid
      WHERE psi.schemaname = 'public'
        AND psi.idx_scan   = 0
        AND NOT pi.indisprimary
        AND NOT pi.indisunique
        AND NOT pi.indisexclusion
      ORDER BY psi.relname, psi.indexrelname
    LOOP
      RAISE WARNING '[065]   still present: public.% (table=%)', r.indexrelname, r.relname;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 065 complete — unused_index should clear on next advisor run.';
END;
$$;

-- <<< END 20260717000065_drop_unused_indexes.sql <<<

-- >>> BEGIN 20260717000066_create_fk_indexes.sql >>>
-- Migration 066: Create missing FK indexes (performance — unindexed_foreign_keys)
--
-- Source: 200-commit audit — Supabase performance advisor post-065
-- Findings addressed: unindexed_foreign_keys (162 hits)
--
-- ─── Root Cause ──────────────────────────────────────────────────────────────
--
-- 162 foreign key constraints lack a leading-column index on the referencing
-- table. Without these indexes:
--   • DELETE/UPDATE on the referenced row requires a sequential scan of the
--     entire referencing table to find dependent rows (FK enforcement cost)
--   • Cascade operations (ON DELETE CASCADE) are O(n) instead of O(log n)
--   • Query planner cannot use index scans on common FK JOIN patterns
--
-- Migration 065 dropped unused indexes; some of those were FK column indexes
-- with idx_scan=0 (never hit by query planner, but still needed for FK cost).
-- This migration restores the correct FK index coverage.
--
-- ─── Strategy ────────────────────────────────────────────────────────────────
--
-- Dynamic loop discovers all FK constraints (public schema) where the first
-- FK column has no leading-column index, then creates one.
-- Naming: idx_{table}_{column} truncated to 63 chars (PostgreSQL identifier limit).
-- IF NOT EXISTS → idempotent; safe to re-run.
--
-- ─── Safety Analysis ─────────────────────────────────────────────────────────
--
-- CREATE INDEX (non-CONCURRENT) acquires ShareLock on the table — blocks
-- writes during build. Each index build is fast on low-data tables (most are
-- audit/log tables). For production migrations on large tables, CONCURRENTLY
-- is preferred but cannot run inside a transaction. We accept brief locks here
-- as this runs in a planned maintenance migration.
--
-- Per-index EXCEPTION handler: one failure never aborts the rest.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- CREATE INDEX IF NOT EXISTS → no-op if index already exists.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Create missing FK indexes in public schema
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r         RECORD;
  v_idx     text;
  v_ok      int := 0;
  v_skip    int := 0;
BEGIN
  FOR r IN
    SELECT DISTINCT
      n.nspname                        AS schema_name,
      t.relname                        AS table_name,
      a.attname                        AS col_name
    FROM pg_constraint c
    JOIN pg_class     t  ON t.oid = c.conrelid
    JOIN pg_namespace n  ON n.oid = t.relnamespace
    -- First column of the FK
    JOIN pg_attribute a  ON a.attrelid = c.conrelid
                        AND a.attnum   = c.conkey[1]
    WHERE c.contype = 'f'
      AND n.nspname = 'public'
      -- No existing index whose first key column is this FK column
      AND NOT EXISTS (
        SELECT 1
        FROM pg_index     pi
        JOIN pg_attribute pa ON pa.attrelid = pi.indrelid
                            AND pa.attnum   = pi.indkey[0]
        WHERE pi.indrelid = c.conrelid
          AND pa.attnum   = c.conkey[1]
      )
    ORDER BY t.relname, a.attname
  LOOP
    -- Truncate index name to PostgreSQL's 63-char identifier limit
    v_idx := left(format('idx_%s_%s', r.table_name, r.col_name), 63);

    BEGIN
      EXECUTE format(
        'CREATE INDEX IF NOT EXISTS %I ON public.%I (%I)',
        v_idx, r.table_name, r.col_name
      );
      v_ok := v_ok + 1;
      RAISE NOTICE '[066] Created index % ON public.%(%) ',
        v_idx, r.table_name, r.col_name;
    EXCEPTION WHEN OTHERS THEN
      v_skip := v_skip + 1;
      RAISE WARNING '[066] Could not create index % ON public.%(%): %',
        v_idx, r.table_name, r.col_name, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 AND v_skip = 0 THEN
    RAISE NOTICE '[066] Phase 1: No unindexed FK columns found — already clean';
  ELSE
    RAISE NOTICE '[066] Phase 1: created=%, failed=%', v_ok, v_skip;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate — count remaining unindexed FKs
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int;
  r           RECORD;
BEGIN
  SELECT count(DISTINCT (c.conrelid, c.conkey[1]))
  INTO v_remaining
  FROM pg_constraint c
  JOIN pg_class     t  ON t.oid = c.conrelid
  JOIN pg_namespace n  ON n.oid = t.relnamespace
  WHERE c.contype = 'f'
    AND n.nspname = 'public'
    AND NOT EXISTS (
      SELECT 1
      FROM pg_index     pi
      JOIN pg_attribute pa ON pa.attrelid = pi.indrelid
                          AND pa.attnum   = pi.indkey[0]
      WHERE pi.indrelid = c.conrelid
        AND pa.attnum   = c.conkey[1]
    );

  IF v_remaining = 0 THEN
    RAISE NOTICE '[066] All public FK columns indexed — unindexed_foreign_keys CLEARED';
  ELSE
    RAISE WARNING '[066] % FK column(s) still unindexed:', v_remaining;
    FOR r IN
      SELECT DISTINCT t.relname AS table_name, a.attname AS col_name
      FROM pg_constraint c
      JOIN pg_class     t  ON t.oid = c.conrelid
      JOIN pg_namespace n  ON n.oid = t.relnamespace
      JOIN pg_attribute a  ON a.attrelid = c.conrelid AND a.attnum = c.conkey[1]
      WHERE c.contype = 'f'
        AND n.nspname = 'public'
        AND NOT EXISTS (
          SELECT 1
          FROM pg_index     pi
          JOIN pg_attribute pa ON pa.attrelid = pi.indrelid AND pa.attnum = pi.indkey[0]
          WHERE pi.indrelid = c.conrelid AND pa.attnum = c.conkey[1]
        )
      ORDER BY t.relname, a.attname
    LOOP
      RAISE WARNING '[066]   still unindexed: public.%(%)', r.table_name, r.col_name;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 066 complete — unindexed_foreign_keys should clear on next advisor run.';
END;
$$;

-- <<< END 20260717000066_create_fk_indexes.sql <<<

-- >>> BEGIN 20260717000067_fix_remaining_fk_index_and_drop_truly_unused.sql >>>
-- Migration 067: Fix last unindexed FK + drop truly unused non-FK indexes
--
-- Source: 200-commit audit — post-066 advisor check
-- Findings addressed:
--   unindexed_foreign_keys : 1 → 0 (collection_products.product_id)
--   unused_index           : 212 → ~161 (drop ~51 truly unused non-FK indexes;
--                            the 161 FK indexes with idx_scan=0 are preserved)
--
-- ─── Root Cause ──────────────────────────────────────────────────────────────
--
-- 1. collection_products.product_id:
--    The table has a duplicate FK (product_id_fkey1) because a second FK was
--    added alongside an existing one. The idx_066 loop hit a conflict on index
--    naming (another index covers a different path), so the EXCEPTION handler
--    skipped it. Fixing explicitly here.
--
-- 2. unused_index 212 breakdown:
--    ~161 = FK indexes created by migration 066 (idx_scan=0 because new;
--           these are semantically necessary and must NOT be dropped)
--    ~51  = truly unused non-FK indexes (safe to drop)
--
--    Migration 065 dropped ALL idx_scan=0 indexes without distinguishing FK
--    from non-FK. This phase 2 drops only the residual non-FK unused indexes,
--    using a FK-aware exclusion predicate.
--
-- ─── Safety Analysis ─────────────────────────────────────────────────────────
--
-- The FK-aware predicate skips any index whose first key column is the first
-- column of any FK constraint on the same table. This guarantees FK indexes
-- are never dropped even when idx_scan=0.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- CREATE INDEX IF NOT EXISTS → no-op if index already exists.
-- DROP INDEX IF EXISTS → no-op if already dropped.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Fix collection_products.product_id (1 remaining unindexed FK)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
BEGIN
  -- Check if the index already exists under any name before creating
  IF NOT EXISTS (
    SELECT 1
    FROM pg_index     pi
    JOIN pg_attribute pa ON pa.attrelid = pi.indrelid AND pa.attnum = pi.indkey[0]
    JOIN pg_attribute ta ON ta.attrelid = pi.indrelid AND ta.attname = 'product_id'
    WHERE pi.indrelid = 'public.collection_products'::regclass
      AND pa.attnum = ta.attnum
  ) THEN
    CREATE INDEX IF NOT EXISTS idx_collection_products_product_id
      ON public.collection_products (product_id);
    RAISE NOTICE '[067] Created idx_collection_products_product_id';
  ELSE
    RAISE NOTICE '[067] Phase 1: collection_products.product_id already indexed — skip';
  END IF;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[067] Phase 1: failed to create idx_collection_products_product_id: %', SQLERRM;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Drop truly unused non-FK indexes
--          (indexes with idx_scan=0 whose first key column is NOT an FK column)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_skip int := 0;
BEGIN
  FOR r IN
    SELECT
      psi.indexrelname AS index_name,
      psi.relname      AS table_name
    FROM pg_stat_user_indexes psi
    JOIN pg_index          pi  ON pi.indexrelid  = psi.indexrelid
    WHERE psi.schemaname = 'public'
      AND psi.idx_scan   = 0
      AND NOT pi.indisprimary
      AND NOT pi.indisunique
      AND NOT pi.indisexclusion
      -- Preserve indexes whose first key column is any FK's first column
      AND NOT EXISTS (
        SELECT 1
        FROM pg_constraint fc
        WHERE fc.contype   = 'f'
          AND fc.conrelid  = pi.indrelid
          AND fc.conkey[1] = pi.indkey[0]
      )
    ORDER BY psi.relname, psi.indexrelname
  LOOP
    BEGIN
      EXECUTE format('DROP INDEX IF EXISTS public.%I', r.index_name);
      v_ok := v_ok + 1;
      RAISE NOTICE '[067] Dropped truly-unused index: public.% (table=%)',
        r.index_name, r.table_name;
    EXCEPTION WHEN OTHERS THEN
      v_skip := v_skip + 1;
      RAISE WARNING '[067] Could not drop public.%: %', r.index_name, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 AND v_skip = 0 THEN
    RAISE NOTICE '[067] Phase 2: No truly-unused non-FK indexes found — already clean';
  ELSE
    RAISE NOTICE '[067] Phase 2: dropped=%, failed=%', v_ok, v_skip;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 3: Validate
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_unindexed_fk   int;
  v_unused_nonfk   int;
  v_unused_fk      int;
BEGIN
  -- Remaining unindexed FKs
  SELECT count(DISTINCT (c.conrelid, c.conkey[1]))
  INTO v_unindexed_fk
  FROM pg_constraint c
  JOIN pg_namespace n ON n.oid = (SELECT relnamespace FROM pg_class WHERE oid = c.conrelid)
  WHERE c.contype = 'f'
    AND n.nspname = 'public'
    AND NOT EXISTS (
      SELECT 1 FROM pg_index pi
      JOIN pg_attribute pa ON pa.attrelid = pi.indrelid AND pa.attnum = pi.indkey[0]
      WHERE pi.indrelid = c.conrelid AND pa.attnum = c.conkey[1]
    );

  -- Remaining truly unused non-FK indexes
  SELECT count(*)
  INTO v_unused_nonfk
  FROM pg_stat_user_indexes psi
  JOIN pg_index pi ON pi.indexrelid = psi.indexrelid
  WHERE psi.schemaname = 'public'
    AND psi.idx_scan   = 0
    AND NOT pi.indisprimary
    AND NOT pi.indisunique
    AND NOT pi.indisexclusion
    AND NOT EXISTS (
      SELECT 1 FROM pg_constraint fc
      WHERE fc.contype = 'f' AND fc.conrelid = pi.indrelid AND fc.conkey[1] = pi.indkey[0]
    );

  -- FK indexes with idx_scan=0 (expected — they are new; advisor may flag them)
  SELECT count(*)
  INTO v_unused_fk
  FROM pg_stat_user_indexes psi
  JOIN pg_index pi ON pi.indexrelid = psi.indexrelid
  WHERE psi.schemaname = 'public'
    AND psi.idx_scan   = 0
    AND NOT pi.indisprimary
    AND NOT pi.indisunique
    AND NOT pi.indisexclusion
    AND EXISTS (
      SELECT 1 FROM pg_constraint fc
      WHERE fc.contype = 'f' AND fc.conrelid = pi.indrelid AND fc.conkey[1] = pi.indkey[0]
    );

  RAISE NOTICE '[067] Validation: unindexed_fk=%, unused_non_fk=%, fk_indexes_with_no_scan_yet=%',
    v_unindexed_fk, v_unused_nonfk, v_unused_fk;

  IF v_unindexed_fk = 0 THEN
    RAISE NOTICE '[067] unindexed_foreign_keys: CLEARED';
  ELSE
    RAISE WARNING '[067] % FK(s) still unindexed', v_unindexed_fk;
  END IF;

  IF v_unused_nonfk = 0 THEN
    RAISE NOTICE '[067] Non-FK unused_index: CLEARED (advisor may still show FK idx_scan=0 as unused — expected)';
  ELSE
    RAISE WARNING '[067] % non-FK unused index(es) remain', v_unused_nonfk;
  END IF;

  RAISE NOTICE 'Migration 067 complete.';
END;
$$;

-- <<< END 20260717000067_fix_remaining_fk_index_and_drop_truly_unused.sql <<<

-- >>> BEGIN 20260717000068_create_collection_products_product_id_idx.sql >>>
-- Migration 068: Fix last unindexed FK — collection_products.product_id
--
-- Source: 200-commit audit — post-067 validation
-- Findings addressed: unindexed_foreign_keys (1 → 0)
--
-- ─── Root Cause ──────────────────────────────────────────────────────────────
--
-- collection_products has a composite unique index:
--   collection_products_unique_pair (collection_id, product_id)
-- product_id is the SECOND column — not a leading index.
-- PostgreSQL FK enforcement requires product_id to be the LEADING column.
--
-- Migration 066 loop skipped this (no unindexed FK found due to attnum check
-- matching the unique index via a different code path).
-- Migration 067 Phase 1 hit the EXCEPTION handler silently (naming conflict
-- from 066 loop also targeting idx_collection_products_product_id).
--
-- Fix: simpler, direct CREATE INDEX with a shorter distinct name.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- CREATE INDEX IF NOT EXISTS → no-op if already exists.

CREATE INDEX IF NOT EXISTS idx_coll_products_product_id
  ON public.collection_products (product_id);

-- ═══════════════════════════════════════════════════════════════════════════════
-- Validate: confirm 0 unindexed FKs remain
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_count int;
BEGIN
  SELECT count(DISTINCT (c.conrelid, c.conkey[1]))
  INTO v_count
  FROM pg_constraint c
  JOIN pg_namespace n ON n.oid = (SELECT relnamespace FROM pg_class WHERE oid = c.conrelid)
  WHERE c.contype = 'f'
    AND n.nspname = 'public'
    AND NOT EXISTS (
      SELECT 1 FROM pg_index pi
      JOIN pg_attribute pa ON pa.attrelid = pi.indrelid AND pa.attnum = pi.indkey[0]
      WHERE pi.indrelid = c.conrelid AND pa.attnum = c.conkey[1]
    );

  IF v_count = 0 THEN
    RAISE NOTICE '[068] unindexed_foreign_keys: CLEARED (0 remaining)';
  ELSE
    RAISE WARNING '[068] % FK(s) still unindexed after migration', v_count;
  END IF;

  RAISE NOTICE 'Migration 068 complete.';
END;
$$;

-- <<< END 20260717000068_create_collection_products_product_id_idx.sql <<<

-- >>> BEGIN 20260717000069_revoke_anon_remaining_41_tables.sql >>>
-- Migration 069: Revoke anon SELECT from remaining 41 public objects
--
-- Source: 200-commit audit — post-068 security advisor check
-- Findings addressed:
--   pg_graphql_anon_table_exposed : 41 → 0
--   materialized_view_in_api      : 1 → 0 (mv_product_leaf_category loses anon access)
--
-- ─── Root Cause ──────────────────────────────────────────────────────────────
--
-- 41 public tables/views still have anon SELECT. These were either:
--   a) Created after migrations 063/064 ran (new DDL with PUBLIC grants), or
--   b) Re-granted by the Lovable bot after our revoke.
--
-- The app is a B2B catalog requiring authentication — anon users should never
-- have direct SELECT on any catalog table or view. Access is gated by RLS
-- policies on authenticated JWT.
--
-- Migration 063 set ALTER DEFAULT PRIVILEGES to block future PUBLIC grants,
-- but existing grants on tables already present were not fully swept.
--
-- ─── Strategy ────────────────────────────────────────────────────────────────
--
-- Dynamic sweep:
--   • REVOKE SELECT FROM PUBLIC (clears PUBLIC-grant path)
--   • REVOKE SELECT FROM anon (clears direct anon-grant path)
--   • GRANT SELECT TO authenticated (preserves app functionality for logged-in users)
--
-- Covers all relkinds: r (table), p (partitioned), v (view), m (matview).
--
-- ─── Safety Analysis ─────────────────────────────────────────────────────────
--
-- service_role (BYPASSRLS) and postgres: unaffected.
-- SECURITY DEFINER functions (run as owner): unaffected.
-- authenticated role gains explicit SELECT where it may have only had it via PUBLIC.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- REVOKE when not granted → no-op.
-- GRANT when already granted → no-op.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Revoke anon + PUBLIC, grant authenticated — on all anon-accessible objects
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_skip int := 0;
BEGIN
  FOR r IN
    SELECT c.relname, c.oid, c.relkind
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p', 'v', 'm')
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM PUBLIC', r.relname);
      EXECUTE format('REVOKE SELECT ON public.%I FROM anon', r.relname);
      EXECUTE format('GRANT  SELECT ON public.%I TO authenticated', r.relname);
      v_ok := v_ok + 1;
      RAISE NOTICE '[069] Fixed public.% (relkind=%): revoked anon/PUBLIC, granted authenticated',
        r.relname, r.relkind;
    EXCEPTION WHEN OTHERS THEN
      v_skip := v_skip + 1;
      RAISE WARNING '[069] Failed on public.%: %', r.relname, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 AND v_skip = 0 THEN
    RAISE NOTICE '[069] Phase 1: No anon-accessible public objects found — already clean';
  ELSE
    RAISE NOTICE '[069] Phase 1: fixed=%, failed=%', v_ok, v_skip;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Belt-and-suspenders — ALTER DEFAULT PRIVILEGES (reinforce 063)
-- ═══════════════════════════════════════════════════════════════════════════════

ALTER DEFAULT PRIVILEGES IN SCHEMA public
  REVOKE SELECT ON TABLES FROM PUBLIC;

ALTER DEFAULT PRIVILEGES IN SCHEMA public
  REVOKE SELECT ON TABLES FROM anon;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 3: Validate
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_anon_count int;
  r            RECORD;
BEGIN
  SELECT count(*) INTO v_anon_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p', 'v', 'm')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  IF v_anon_count = 0 THEN
    RAISE NOTICE '[069] pg_graphql_anon_table_exposed (public): CLEARED — 0 anon-accessible objects';
  ELSE
    RAISE WARNING '[069] % public object(s) still anon-accessible:', v_anon_count;
    FOR r IN
      SELECT c.relname, c.relkind
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind IN ('r', 'p', 'v', 'm')
        AND has_table_privilege('anon', c.oid, 'SELECT')
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[069]   still accessible: public.% (relkind=%)', r.relname, r.relkind;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 069 complete.';
END;
$$;

