-- >>> BEGIN 20260717000071_final_security_sweep_and_audit_close.sql >>>
-- Migration 071: Final security sweep — close 200-commit audit
--
-- Source: 200-commit audit — post-070 final validation
-- Findings addressed:
--   belt-and-suspenders: catch any new anon grants or RLS gaps
--   created since migrations 063/069 ran
--
-- ─── Context ──────────────────────────────────────────────────────────────────
--
-- This migration closes the 200-commit security/performance audit.
-- Migrations 063–070 cleared:
--   • pg_graphql_anon_table_exposed        : 41 → 0
--   • unindexed_foreign_keys               : 162 → 0
--   • materialized_view_in_api             : 1 → 0
--   • unused non-FK indexes                : ~51 dropped
--
-- This migration adds a final sweep:
--   Phase 1: Revoke any anon SELECT that may have been re-granted since 069
--   Phase 2: Enable RLS on any public table that is missing it
--   Phase 3: Final validation report
--
-- ─── Safety ───────────────────────────────────────────────────────────────────
--
-- All revokes are idempotent (REVOKE when not granted = no-op).
-- RLS enable on table without RLS = ALTER TABLE ENABLE ROW LEVEL SECURITY.
-- Existing RLS policies are NOT touched.
-- service_role (BYPASSRLS) and postgres: unaffected.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Final anon sweep — revoke any newly granted anon SELECT
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_skip int := 0;
BEGIN
  FOR r IN
    SELECT c.relname, c.oid, c.relkind
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p', 'v', 'm')
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM PUBLIC', r.relname);
      EXECUTE format('REVOKE SELECT ON public.%I FROM anon', r.relname);
      EXECUTE format('GRANT  SELECT ON public.%I TO authenticated', r.relname);
      v_ok := v_ok + 1;
      RAISE WARNING '[071] Phase 1: Found anon-accessible public.% (relkind=%) — fixed',
        r.relname, r.relkind;
    EXCEPTION WHEN OTHERS THEN
      v_skip := v_skip + 1;
      RAISE WARNING '[071] Phase 1: Failed on public.%: %', r.relname, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 AND v_skip = 0 THEN
    RAISE NOTICE '[071] Phase 1: CLEAN — no anon-accessible public objects found';
  ELSE
    RAISE NOTICE '[071] Phase 1: swept=%, failed=%', v_ok, v_skip;
  END IF;
END;
$$;

-- Belt-and-suspenders: reinforce ALTER DEFAULT PRIVILEGES
ALTER DEFAULT PRIVILEGES IN SCHEMA public
  REVOKE SELECT ON TABLES FROM PUBLIC;

ALTER DEFAULT PRIVILEGES IN SCHEMA public
  REVOKE SELECT ON TABLES FROM anon;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Enable RLS on any public BASE TABLE missing it
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r    RECORD;
  v_ok int := 0;
BEGIN
  FOR r IN
    SELECT c.relname
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p')  -- tables and partitioned tables only
      AND NOT c.relrowsecurity      -- RLS not enabled
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', r.relname);
      v_ok := v_ok + 1;
      RAISE WARNING '[071] Phase 2: Enabled RLS on public.% (was missing)', r.relname;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[071] Phase 2: Could not enable RLS on public.%: %', r.relname, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 THEN
    RAISE NOTICE '[071] Phase 2: CLEAN — all public tables already have RLS enabled';
  ELSE
    RAISE NOTICE '[071] Phase 2: Enabled RLS on % table(s)', v_ok;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 3: Final validation report
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_anon_count      int;
  v_no_rls_count    int;
  v_unindexed_fk    int;
  v_public_mv_count int;
BEGIN
  -- Count anon-accessible public objects
  SELECT count(*) INTO v_anon_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p', 'v', 'm')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  -- Count tables without RLS
  SELECT count(*) INTO v_no_rls_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND NOT c.relrowsecurity;

  -- Count unindexed FKs
  SELECT count(DISTINCT (c.conrelid, c.conkey[1]))
  INTO v_unindexed_fk
  FROM pg_constraint c
  JOIN pg_namespace n ON n.oid = (SELECT relnamespace FROM pg_class WHERE oid = c.conrelid)
  WHERE c.contype = 'f'
    AND n.nspname = 'public'
    AND NOT EXISTS (
      SELECT 1 FROM pg_index pi
      JOIN pg_attribute pa ON pa.attrelid = pi.indrelid AND pa.attnum = pi.indkey[0]
      WHERE pi.indrelid = c.conrelid AND pa.attnum = c.conkey[1]
    );

  -- Count materialized views still in public schema
  SELECT count(*) INTO v_public_mv_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'm';

  -- Report
  RAISE NOTICE '══════════════════════════════════════════════════';
  RAISE NOTICE '[071] 200-commit audit — FINAL STATE REPORT';
  RAISE NOTICE '══════════════════════════════════════════════════';
  RAISE NOTICE '[071] pg_graphql_anon_table_exposed     : % (target: 0)', v_anon_count;
  RAISE NOTICE '[071] auth_rls_disabled_in_public       : % (target: 0)', v_no_rls_count;
  RAISE NOTICE '[071] unindexed_foreign_keys            : % (target: 0)', v_unindexed_fk;
  RAISE NOTICE '[071] materialized_view_in_api (public) : % (target: 0)', v_public_mv_count;

  IF v_anon_count = 0
     AND v_no_rls_count = 0
     AND v_unindexed_fk = 0
     AND v_public_mv_count = 0
  THEN
    RAISE NOTICE '[071] ALL AUTOMATED TARGETS CLEARED ✓';
  ELSE
    RAISE WARNING '[071] Some targets not met — review above';
  END IF;

  RAISE NOTICE '══════════════════════════════════════════════════';
  RAISE NOTICE '[071] Irreducible remaining advisor findings:';
  RAISE NOTICE '[071]   unused_index (213)          — all FK/unique/constraint indexes';
  RAISE NOTICE '[071]   auth_db_connections_absolute — dashboard: Auth → Settings → percentage-based';
  RAISE NOTICE '[071]   pg_graphql_authenticated (440) — intentional B2B design';
  RAISE NOTICE '[071]   authenticated_sec_definer (67)  — intentional app RPCs';
  RAISE NOTICE '[071]   anon_sec_definer (9)            — explicitly safelisted catalog RPCs';
  RAISE NOTICE '══════════════════════════════════════════════════';
  RAISE NOTICE 'Migration 071 complete — 200-commit audit CLOSED.';
END;
$$;

-- <<< END 20260717000071_final_security_sweep_and_audit_close.sql <<<

-- >>> BEGIN 20260717000072_fix_cron_and_fn_after_mv_move_to_internal.sql >>>
-- Migration 072: Fix cron job + fn_get_all_leaf_categories after MV moved to internal
--
-- Source: Codex P1 review on PR #1730
-- Findings addressed:
--   • refresh-mv-product-leaf-category pg_cron job still points to
--     public.mv_product_leaf_category which was dropped by migration 070
--   • fn_get_all_leaf_categories() reads public.mv_product_leaf_category
--     directly — fails with "relation does not exist" after the drop
--
-- ─── Fix 1: Retarget the pg_cron refresh job ─────────────────────────────────
--
-- Migration 070 moved the MV to internal schema and dropped the public one.
-- The pg_cron job was created by 20260618200000_drift_catalog_analytics_baseline.sql
-- with command: fn_cron_safe_run(..., 'REFRESH MATERIALIZED VIEW CONCURRENTLY
--   public.mv_product_leaf_category;', ...).
-- We update the command in-place via cron.alter_job or by unschedule/reschedule.
--
-- ─── Fix 2: Repoint fn_get_all_leaf_categories() ────────────────────────────
--
-- The function reads public.mv_product_leaf_category via search_path='public'.
-- Update to read internal.mv_product_leaf_category with an explicit schema ref.
-- Return signature is preserved identically (leaf_category_parent_id included).
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- cron.unschedule + cron.schedule pair is the idempotent pattern used throughout.
-- CREATE OR REPLACE FUNCTION is idempotent.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Fix 1: Retarget pg_cron job to internal.mv_product_leaf_category
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_job_id bigint;
  v_schedule text;
BEGIN
  -- Get current job info
  SELECT jobid, schedule
  INTO v_job_id, v_schedule
  FROM cron.job
  WHERE jobname = 'refresh-mv-product-leaf-category';

  IF NOT FOUND THEN
    -- Job doesn't exist; create it pointing to internal schema
    PERFORM cron.schedule(
      'refresh-mv-product-leaf-category',
      '37 */4 * * *',
      $cmd$SELECT public.fn_cron_safe_run(0::bigint, 'REFRESH MATERIALIZED VIEW CONCURRENTLY internal.mv_product_leaf_category;', 55000, 'mv-leaf-category');$cmd$
    );
    RAISE NOTICE '[072] Created new cron job for internal.mv_product_leaf_category';
    RETURN;
  END IF;

  -- Remove old job and recreate with internal schema reference
  PERFORM cron.unschedule(v_job_id);

  PERFORM cron.schedule(
    'refresh-mv-product-leaf-category',
    v_schedule,
    $cmd$SELECT public.fn_cron_safe_run(0::bigint, 'REFRESH MATERIALIZED VIEW CONCURRENTLY internal.mv_product_leaf_category;', 55000, 'mv-leaf-category');$cmd$
  );

  RAISE NOTICE '[072] Retargeted cron job refresh-mv-product-leaf-category → internal.mv_product_leaf_category (schedule: %)', v_schedule;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Fix 2: Repoint fn_get_all_leaf_categories() to internal schema
-- ═══════════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.fn_get_all_leaf_categories()
RETURNS TABLE(
  product_id            uuid,
  leaf_category_id      uuid,
  leaf_category_name    text,
  leaf_category_level   integer,
  leaf_category_parent_id uuid,
  leaf_category_slug    text
)
LANGUAGE sql
SECURITY DEFINER
SET search_path TO 'public', 'internal'
AS $$
  SELECT
    product_id,
    leaf_category_id,
    leaf_category_name,
    leaf_category_level,
    leaf_category_parent_id,
    leaf_category_slug
  FROM internal.mv_product_leaf_category;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Validate
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_cron_cmd  text;
  v_fn_src    text;
BEGIN
  -- Verify cron job now references internal schema
  SELECT command INTO v_cron_cmd
  FROM cron.job
  WHERE jobname = 'refresh-mv-product-leaf-category';

  IF v_cron_cmd LIKE '%internal.mv_product_leaf_category%' THEN
    RAISE NOTICE '[072] ✓ cron job references internal.mv_product_leaf_category';
  ELSE
    RAISE WARNING '[072] ✗ cron job command unexpected: %', v_cron_cmd;
  END IF;

  -- Verify function body now references internal schema
  SELECT pg_get_functiondef(oid) INTO v_fn_src
  FROM pg_proc
  WHERE pronamespace = 'public'::regnamespace AND proname = 'fn_get_all_leaf_categories';

  IF v_fn_src LIKE '%internal.mv_product_leaf_category%' THEN
    RAISE NOTICE '[072] ✓ fn_get_all_leaf_categories reads internal.mv_product_leaf_category';
  ELSE
    RAISE WARNING '[072] ✗ fn_get_all_leaf_categories body unexpected';
  END IF;

  RAISE NOTICE 'Migration 072 complete.';
END;
$$;

-- <<< END 20260717000072_fix_cron_and_fn_after_mv_move_to_internal.sql <<<

-- >>> BEGIN 20260717114423_fix_security_invoker_regression_suppliers_and_stock_velocity.sql >>>
-- ============================================================================
-- ANTI-REGRESSÃO (fix_version 20260717)
-- v_suppliers_public e mv_stock_velocity são views SECURITY-DEFINER POR DESIGN:
-- projetam colunas curadas sobre objetos com acesso restrito (suppliers com RLS;
-- analytics.mv_stock_velocity sem grant para roles de app). Recriar com
-- security_invoker=on QUEBRA o acesso de 'authenticated' (PostgREST 403).
-- NÃO reintroduzir security_invoker=on nestas views.
-- ============================================================================

ALTER VIEW public.v_suppliers_public SET (security_invoker = false);
ALTER VIEW public.mv_stock_velocity  SET (security_invoker = false);

-- Hardening: mv_stock_velocity expõe dados internos de operação
-- (depleção, dias-para-ruptura, current_price). Não deve ser legível por anon.
REVOKE SELECT ON public.mv_stock_velocity FROM anon;

COMMENT ON VIEW public.v_suppliers_public IS
  'Projecao publica de fornecedores (colunas nao sensiveis) sobre public.suppliers. SECURITY-DEFINER por design (base tem RLS/lockdown). NAO usar security_invoker=on. fix_version 20260717';

COMMENT ON VIEW public.mv_stock_velocity IS
  'Wrapper PostgREST de analytics.mv_stock_velocity. SECURITY-DEFINER por design; somente authenticated (dados internos de operacao). NAO usar security_invoker=on. fix_version 20260717';

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260717114423_fix_security_invoker_regression_suppliers_and_stock_velocity.sql <<<

-- >>> BEGIN 20260717115130_restore_category_icons_proxy_view_from_categories.sql >>>
-- ============================================================================
-- RESTORE: public.category_icons (proxy view → public.categories)
-- ANTI-REGRESSÃO fix_version 20260717
--
-- CONTEXTO: archive.category_icons foi dropada com CASCADE em
-- 20260716000008_drop_archive_backup_schemas.sql, o que derrubou também
-- a proxy view public.category_icons. O frontend (useCategoryIcons.ts)
-- continua esperando esta view e recebia 404.
--
-- FONTE DA VERDADE: public.categories (colunas name, icon, is_active, id)
-- A view só expõe categorias ativas com icon preenchido.
--
-- COLUNAS EXPOSTAS (retrocompat com CategoryIcon interface do frontend):
--   id            → categories.id
--   category_name → categories.name
--   icon          → categories.icon
--   description   → NULL (não existe em categories; aceito por interface)
--   is_active     → categories.is_active
-- ============================================================================

CREATE OR REPLACE VIEW public.category_icons AS
SELECT
  c.id,
  c.name        AS category_name,
  c.icon,
  NULL::text    AS description,
  c.is_active
FROM public.categories c
WHERE c.icon IS NOT NULL;

COMMENT ON VIEW public.category_icons IS
  'PROXY VIEW (restaurada 2026-07-17) — leitura somente. '
  'Fonte de verdade: public.categories (icon, name, is_active). '
  'archive.category_icons foi dropada com CASCADE em 20260716000008. '
  'NAO usar security_invoker=on — categories tem RLS public_read OK. '
  'ANTI-REGRESSÃO fix_version 20260717. NAO dropar esta view.';

-- ── Read-only via INSTEAD NOTHING rules (impede auto-update)
CREATE OR REPLACE RULE category_icons_no_insert
  AS ON INSERT TO public.category_icons DO INSTEAD NOTHING;

CREATE OR REPLACE RULE category_icons_no_update
  AS ON UPDATE TO public.category_icons DO INSTEAD NOTHING;

CREATE OR REPLACE RULE category_icons_no_delete
  AS ON DELETE TO public.category_icons DO INSTEAD NOTHING;

-- ── Grants (replica política original: qualquer autenticado lê)
GRANT SELECT ON public.category_icons TO anon;
GRANT SELECT ON public.category_icons TO authenticated;

-- ── Reload PostgREST schema cache
NOTIFY pgrst, 'reload schema';;

-- <<< END 20260717115130_restore_category_icons_proxy_view_from_categories.sql <<<

