-- >>> BEGIN 20260717115437_dynamic_pin_all_function_search_paths_and_fix_fn_global_search.sql >>>
-- Migration 042a: Fix fn_global_search quote data exposure
CREATE OR REPLACE FUNCTION public.fn_global_search(
  p_term   text,
  p_limit  integer DEFAULT 12,
  p_types  text[]  DEFAULT ARRAY['product'::text, 'quote'::text]
)
RETURNS TABLE(
  result_id          text,
  result_type        text,
  result_title       text,
  result_description text,
  result_url         text,
  result_image_url   text,
  result_metadata    jsonb,
  result_relevance   numeric
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $fn_global_search$
DECLARE
  v_term_norm text;
  v_tsquery   tsquery;
  v_lim_each  integer;
BEGIN
  IF p_term IS NULL OR length(trim(p_term)) < 2 THEN RETURN; END IF;
  IF p_limit IS NULL OR p_limit <= 0 THEN RETURN; END IF;
  v_term_norm := lower(unaccent(trim(p_term)));
  v_lim_each  := GREATEST(1, p_limit / GREATEST(array_length(p_types, 1), 1));
  BEGIN
    v_tsquery := websearch_to_tsquery('portuguese', unaccent(trim(p_term)));
  EXCEPTION WHEN OTHERS THEN v_tsquery := NULL;
  END;
  PERFORM set_config('pg_trgm.similarity_threshold', '0.2', true);
  IF 'product' = ANY(p_types) THEN
    RETURN QUERY
    SELECT p.id::text, 'product'::text, p.name::text,
      ('SKU: ' || p.sku || CASE WHEN c.name IS NOT NULL THEN ' · ' || c.name ELSE '' END)::text,
      ('/produtos/' || p.slug)::text, p.primary_image_url,
      jsonb_build_object('sku', p.sku, 'price', p.sale_price,
                         'stock', COALESCE(vs.total_stock, 0), 'category', COALESCE(c.name, '')),
      (CASE WHEN v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery
            THEN ts_rank_cd(p.search_vector, v_tsquery, 32) * 2.0 ELSE 0 END +
       word_similarity(v_term_norm, lower(unaccent(p.name))) * 1.0 +
       CASE WHEN lower(p.sku) LIKE '%' || v_term_norm || '%' THEN 0.8 ELSE 0 END +
       CASE WHEN COALESCE(vs.total_stock, 0) > 0 THEN 0.2 ELSE 0 END)::numeric
    FROM products p
    LEFT JOIN product_category_assignments pca ON pca.product_id = p.id AND pca.is_primary = true
    LEFT JOIN categories c ON c.id = pca.category_id
    LEFT JOIN LATERAL (
      SELECT COALESCE(SUM(pv.stock_quantity), 0)::int AS total_stock
      FROM product_variants pv WHERE pv.product_id = p.id AND pv.is_active = true
    ) vs ON true
    WHERE p.is_active = true AND p.is_deleted IS NOT TRUE
      AND p.sale_price IS NOT NULL AND p.slug IS NOT NULL AND p.slug != ''
      AND (
        (v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery)
        OR p.name % v_term_norm OR lower(p.sku) LIKE '%' || v_term_norm || '%'
      )
    ORDER BY 8 DESC LIMIT v_lim_each;
  END IF;
  -- SECURITY/042: gate quotes on auth.uid() IS NOT NULL — anon gets no quote data
  IF 'quote' = ANY(p_types) AND auth.uid() IS NOT NULL THEN
    RETURN QUERY
    SELECT q.id::text, 'quote'::text, COALESCE(q.quote_number, 'Orçamento')::text,
      ('Status: ' || COALESCE(q.status, '—') ||
       CASE WHEN q.total IS NOT NULL THEN ' · R$ ' || to_char(q.total, 'FM999G999G990D00') ELSE '' END)::text,
      ('/orcamentos/' || q.id::text)::text, NULL::text,
      jsonb_build_object('status', q.status, 'total', q.total, 'created_at', q.created_at),
      CASE WHEN lower(COALESCE(q.quote_number, '')) LIKE '%' || v_term_norm || '%' THEN 0.9
           WHEN lower(COALESCE(q.status, ''))        LIKE '%' || v_term_norm || '%' THEN 0.5
           ELSE 0.3 END::numeric
    FROM quotes q
    WHERE q.created_by = auth.uid()
      AND (
        lower(COALESCE(q.quote_number, '')) LIKE '%' || v_term_norm || '%'
        OR lower(COALESCE(q.status, ''))    LIKE '%' || v_term_norm || '%'
      )
    ORDER BY 8 DESC, q.created_at DESC LIMIT v_lim_each;
  END IF;
END;
$fn_global_search$;

-- Migration 042b: Dynamic search_path pinning for ALL remaining public functions
DO $$
DECLARE
  r        RECORD;
  v_ok     int := 0;
  v_fail   int := 0;
BEGIN
  FOR r IN
    SELECT p.oid, p.proname, pg_get_function_identity_arguments(p.oid) AS args, p.prokind
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prokind IN ('f', 'p')
      AND NOT EXISTS (
        SELECT 1 FROM unnest(p.proconfig) AS cfg WHERE cfg LIKE 'search_path=%'
      )
    ORDER BY p.prokind, p.proname, p.oid
  LOOP
    BEGIN
      IF r.prokind = 'f' THEN
        EXECUTE format($fmt$ALTER FUNCTION public.%I(%s) SET search_path = 'public', 'extensions'$fmt$, r.proname, r.args);
      ELSE
        EXECUTE format($fmt$ALTER PROCEDURE public.%I(%s) SET search_path = 'public', 'extensions'$fmt$, r.proname, r.args);
      END IF;
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[042] ✗ Cannot pin %(%): %', r.proname, r.args, SQLERRM;
    END;
  END LOOP;
  RAISE NOTICE '[042] Search path pinning: pinned=%, failed=%', v_ok, v_fail;
END;
$$;;

-- <<< END 20260717115437_dynamic_pin_all_function_search_paths_and_fix_fn_global_search.sql <<<

-- >>> BEGIN 20260717115513_dynamic_security_invoker_all_views.sql >>>
-- Migration 043: Dynamic security_invoker=on for all remaining public views
-- Exemption: v_products_public (intentionally SECURITY DEFINER — migration 040)
DO $$
DECLARE
  r           RECORD;
  v_ok        int := 0;
  v_skip      int := 0;
  v_fail      int := 0;
  v_exempt    text[] := ARRAY['v_products_public'];
BEGIN
  -- Convert fn_get_similar_products to SECURITY INVOKER if it exists (any signature)
  FOR r IN
    SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'fn_get_similar_products' AND p.prosecdef = true
  LOOP
    BEGIN
      EXECUTE format('ALTER FUNCTION public.fn_get_similar_products(%s) SECURITY INVOKER', r.args);
      RAISE NOTICE '[043] ✓ fn_get_similar_products(%) → SECURITY INVOKER', r.args;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[043] ✗ Cannot convert fn_get_similar_products(%): %', r.args, SQLERRM;
    END;
  END LOOP;

  -- Convert views to security_invoker=on
  FOR r IN
    SELECT c.relname AS viewname
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relkind = 'v'
      AND NOT (c.relname = ANY(v_exempt))
      AND NOT EXISTS (
        SELECT 1 FROM unnest(c.reloptions) AS opt WHERE opt = 'security_invoker=on'
      )
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('ALTER VIEW public.%I SET (security_invoker = on)', r.viewname);
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[043] ✗ Could not convert %: %', r.viewname, SQLERRM;
    END;
  END LOOP;
  SELECT count(*) INTO v_skip
  FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind = 'v'
    AND NOT (c.relname = ANY(v_exempt))
    AND EXISTS (SELECT 1 FROM unnest(c.reloptions) AS opt WHERE opt = 'security_invoker=on');
  RAISE NOTICE '[043] Views: converted=%, already_done=%, failed=%', v_ok, v_skip, v_fail;
END;
$$;;

-- <<< END 20260717115513_dynamic_security_invoker_all_views.sql <<<

