-- Migration 044b: Move relocatable extensions from public to extensions schema
DO $$
DECLARE
  r              RECORD;
  v_ok           int := 0;
  v_skip         int := 0;
  v_fail         int := 0;
  v_candidates   text[] := ARRAY[
    'uuid-ossp', 'pgcrypto', 'pg_trgm', 'fuzzystrmatch', 'unaccent',
    'tablefunc', 'cube', 'earthdistance', 'citext', 'hstore', 'ltree',
    'intarray', 'btree_gin', 'btree_gist', 'isn', 'lo', 'bloom', 'tcn',
    'seg', 'dict_int', 'dict_xsyn'
  ];
  v_ext_name     text;
  v_ext_schema   text;
  v_relocatable  boolean;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'extensions') THEN
    CREATE SCHEMA IF NOT EXISTS extensions;
  END IF;

  FOREACH v_ext_name IN ARRAY v_candidates
  LOOP
    SELECT n.nspname, e.extrelocatable
    INTO v_ext_schema, v_relocatable
    FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace
    WHERE e.extname = v_ext_name;

    IF NOT FOUND THEN v_skip := v_skip + 1; CONTINUE; END IF;
    IF v_ext_schema <> 'public' THEN v_skip := v_skip + 1; CONTINUE; END IF;
    IF NOT v_relocatable THEN
      RAISE WARNING '[044] % is in public but NOT relocatable — leaving', v_ext_name;
      v_skip := v_skip + 1; CONTINUE;
    END IF;

    BEGIN
      EXECUTE format('ALTER EXTENSION %I SET SCHEMA extensions', v_ext_name);
      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [044] Moved % from public to extensions schema', v_ext_name;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[044] ✗ Could not move %: %', v_ext_name, SQLERRM;
    END;
  END LOOP;
  RAISE NOTICE '[044] Extension moves: moved=%, skipped=%, failed=%', v_ok, v_skip, v_fail;
END;
$$;;

-- <<< END 20260717115536_revoke_anon_fn_log_search_analytics_and_move_extensions.sql <<<

-- >>> BEGIN 20260717115930_dynamic_fix_auth_rls_initplan_and_revoke_anon_catalog_functions.sql >>>

-- ═══════════════════════════════════════════════════════════════════════════════
-- Migration 045a: Dynamic auth_rls_initplan fix — ALL remaining public policies
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r          RECORD;
  v_ok       int := 0;
  v_skip     int := 0;
  v_fail     int := 0;
  v_qual     text;
  v_check    text;
  c_ph       CONSTANT text := '<<AUTH_UID_ALREADY_WRAPPED>>';
BEGIN
  FOR r IN
    SELECT
      p.policyname,
      p.tablename,
      p.cmd,
      p.qual,
      p.with_check
    FROM pg_policies p
    WHERE p.schemaname = 'public'
      AND (
        (p.qual       IS NOT NULL
          AND p.qual       LIKE '%auth.uid()%'
          AND p.qual       NOT LIKE '%(SELECT auth.uid())%')
        OR
        (p.with_check IS NOT NULL
          AND p.with_check LIKE '%auth.uid()%'
          AND p.with_check NOT LIKE '%(SELECT auth.uid())%')
      )
    ORDER BY p.tablename, p.policyname
  LOOP
    v_qual  := replace(r.qual,       '(SELECT auth.uid())', c_ph);
    v_check := replace(r.with_check, '(SELECT auth.uid())', c_ph);
    v_qual  := replace(v_qual,  'auth.uid()', '(SELECT auth.uid())');
    v_check := replace(v_check, 'auth.uid()', '(SELECT auth.uid())');
    v_qual  := replace(v_qual,  c_ph, '(SELECT auth.uid())');
    v_check := replace(v_check, c_ph, '(SELECT auth.uid())');

    BEGIN
      IF r.qual IS NOT NULL AND r.with_check IS NOT NULL THEN
        EXECUTE format(
          'ALTER POLICY %I ON public.%I USING (%s) WITH CHECK (%s)',
          r.policyname, r.tablename, v_qual, v_check
        );
      ELSIF r.qual IS NOT NULL THEN
        EXECUTE format(
          'ALTER POLICY %I ON public.%I USING (%s)',
          r.policyname, r.tablename, v_qual
        );
      ELSIF r.with_check IS NOT NULL THEN
        EXECUTE format(
          'ALTER POLICY %I ON public.%I WITH CHECK (%s)',
          r.policyname, r.tablename, v_check
        );
      ELSE
        v_skip := v_skip + 1;
        CONTINUE;
      END IF;

      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [045] Optimized %.% (%)', r.tablename, r.policyname, r.cmd;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[045] ✗ Could not optimize %.% (%): %',
        r.tablename, r.policyname, r.cmd, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[045] auth_rls_initplan sweep: optimized=%, skipped=%, failed=%',
    v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[045] % policy/policies could not be optimized — check warnings above', v_fail;
  END IF;
END;
$$;

-- Phase 2: target spot-checks
DO $$
DECLARE
  v_tbl        text;
  v_bare_count int;
  v_tables     text[] := ARRAY[
    'entity_versions', 'saved_filters', 'product_badge_definitions',
    'discount_approval_requests', 'workspace_notifications', 'ai_insights_cache',
    'notifications', 'user_organizations', 'quotes', 'orders'
  ];
BEGIN
  FOREACH v_tbl IN ARRAY v_tables
  LOOP
    SELECT count(*) INTO v_bare_count
    FROM pg_policies
    WHERE schemaname = 'public'
      AND tablename = v_tbl
      AND (
        (qual       LIKE '%auth.uid()%' AND qual       NOT LIKE '%(SELECT auth.uid())%')
        OR
        (with_check LIKE '%auth.uid()%' AND with_check NOT LIKE '%(SELECT auth.uid())%')
      );

    IF v_bare_count = 0 THEN
      RAISE NOTICE '✓ [045] % — no remaining bare auth.uid() policies', v_tbl;
    ELSE
      RAISE WARNING '[045] % still has % bare auth.uid() policy/policies', v_tbl, v_bare_count;
    END IF;
  END LOOP;
END;
$$;

-- Validation
DO $$
DECLARE
  v_total_policies  int;
  v_bare_remaining  int;
BEGIN
  SELECT count(*) INTO v_total_policies FROM pg_policies WHERE schemaname = 'public';
  SELECT count(*) INTO v_bare_remaining
  FROM pg_policies
  WHERE schemaname = 'public'
    AND (
      (qual       LIKE '%auth.uid()%' AND qual       NOT LIKE '%(SELECT auth.uid())%')
      OR
      (with_check LIKE '%auth.uid()%' AND with_check NOT LIKE '%(SELECT auth.uid())%')
    );

  IF v_bare_remaining = 0 THEN
    RAISE NOTICE '✓ [045] All % public policies use (SELECT auth.uid()) — auth_rls_initplan cleared', v_total_policies;
  ELSE
    RAISE WARNING '[045] % of % public policies still have bare auth.uid()', v_bare_remaining, v_total_policies;
  END IF;
  RAISE NOTICE 'Migration 045a complete.';
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Migration 045b: Revoke anon EXECUTE on 4 authenticated-only catalog RPCs
-- Dynamic: uses pg_proc OIDs + pg_get_function_identity_arguments to handle overloads
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r            RECORD;
  v_ok         int := 0;
  v_skip       int := 0;
  v_fail       int := 0;
  v_targets    text[] := ARRAY[
    'get_catalog_bestseller_page',
    'get_promo_sales_ranking',
    'get_top_collected_products',
    'get_collections_weekly_count'
  ];
  v_name       text;
BEGIN
  FOREACH v_name IN ARRAY v_targets LOOP
    FOR r IN
      SELECT
        p.oid,
        p.proname,
        pg_get_function_identity_arguments(p.oid) AS args
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'public'
        AND p.proname = v_name
        AND has_function_privilege('anon', p.oid, 'EXECUTE')
    LOOP
      BEGIN
        EXECUTE format(
          'REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM anon',
          r.proname, r.args
        );
        v_ok := v_ok + 1;
        RAISE NOTICE '[045] ✓ REVOKE EXECUTE ON %(%) FROM anon', r.proname, r.args;
      EXCEPTION WHEN OTHERS THEN
        v_fail := v_fail + 1;
        RAISE WARNING '[045] ✗ Could not revoke %(%)): %', r.proname, r.args, SQLERRM;
      END;
    END LOOP;

    IF NOT EXISTS (
      SELECT 1 FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'public' AND p.proname = v_name
    ) THEN
      v_skip := v_skip + 1;
      RAISE NOTICE '[045] - % not found in database — skipping', v_name;
    END IF;
  END LOOP;

  RAISE NOTICE '[045] Catalog function revoke: revoked=%, skipped=%, failed=%',
    v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[045] % revocation(s) failed', v_fail;
  END IF;
END;
$$;

-- Validate 045b
DO $$
DECLARE
  v_name         text;
  v_anon_ex      boolean;
  v_targets      text[] := ARRAY[
    'get_catalog_bestseller_page', 'get_promo_sales_ranking',
    'get_top_collected_products', 'get_collections_weekly_count'
  ];
  v_still_granted int := 0;
BEGIN
  FOREACH v_name IN ARRAY v_targets LOOP
    IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = v_name) THEN
      RAISE NOTICE '[045] SKIP: % not found', v_name;
      CONTINUE;
    END IF;

    SELECT has_function_privilege('anon',
      (SELECT p.oid FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = v_name LIMIT 1),
      'EXECUTE') INTO v_anon_ex;

    IF v_anon_ex THEN
      RAISE WARNING '[045] WARN: anon still has EXECUTE on % (may have multiple overloads)', v_name;
      v_still_granted := v_still_granted + 1;
    ELSE
      RAISE NOTICE '[045] OK: anon no longer has EXECUTE on %', v_name;
    END IF;
  END LOOP;

  IF v_still_granted > 0 THEN
    RAISE WARNING '[045] % function(s) still grant EXECUTE to anon — check overloads', v_still_granted;
  END IF;

  RAISE NOTICE '[045] Migration 045b complete — 045a+045b applied successfully.';
END;
$$;
;

-- <<< END 20260717115930_dynamic_fix_auth_rls_initplan_and_revoke_anon_catalog_functions.sql <<<

-- >>> BEGIN 20260717120020_dynamic_enable_rls_and_revoke_anon_catalog_functions.sql >>>

-- ═══════════════════════════════════════════════════════════════════════════════
-- Migration 046a: Enable RLS on all remaining public tables
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r              RECORD;
  v_ok           int := 0;
  v_no_policy    int := 0;
  v_fail         int := 0;
BEGIN
  FOR r IN
    SELECT
      c.relname    AS tablename,
      c.relkind,
      (SELECT count(*)::int FROM pg_policies p
       WHERE p.schemaname = 'public' AND p.tablename = c.relname) AS policy_count
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p')
      AND NOT c.relrowsecurity
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', r.tablename);
      v_ok := v_ok + 1;
      IF r.policy_count = 0 THEN
        v_no_policy := v_no_policy + 1;
        RAISE WARNING '[046] % — RLS ENABLED, but NO policies (service_role bypasses via BYPASSRLS)', r.tablename;
      ELSE
        RAISE NOTICE '✓ [046] Enabled RLS on % (% existing policies now active)', r.tablename, r.policy_count;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[046] ✗ Could not enable RLS on %: %', r.tablename, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[046] RLS enable sweep: enabled=%, of_which_no_policy=%, failed=%', v_ok, v_no_policy, v_fail;

  IF v_no_policy > 0 THEN
    RAISE WARNING '[046] % table(s) now have RLS enabled with ZERO policies — review and add appropriate policies', v_no_policy;
  END IF;

  IF v_fail > 0 THEN
    RAISE WARNING '[046] % table(s) could not have RLS enabled', v_fail;
  END IF;
END;
$$;

-- Target-check known tables
DO $$
DECLARE
  v_tbl     text;
  v_has_rls boolean;
  v_tables  text[] := ARRAY[
    'products', 'product_variants', 'suppliers', 'supplier_products_raw',
    'categories', 'users', 'organizations', 'orders', 'quotes',
    'notifications', 'saved_filters', 'entity_versions', 'ai_insights_cache',
    'workspace_notifications', 'discount_approval_requests', 'product_badge_definitions'
  ];
BEGIN
  FOREACH v_tbl IN ARRAY v_tables LOOP
    SELECT c.relrowsecurity INTO v_has_rls
    FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = v_tbl;

    IF NOT FOUND THEN
      RAISE NOTICE '[046] % — not found in public schema', v_tbl;
    ELSIF v_has_rls THEN
      RAISE NOTICE '✓ [046] % — RLS confirmed enabled', v_tbl;
    ELSE
      RAISE WARNING '[046] % — RLS STILL DISABLED after sweep — investigate', v_tbl;
    END IF;
  END LOOP;
END;
$$;

-- Validation
DO $$
DECLARE
  v_total_tables int;
  v_rls_enabled  int;
  v_rls_disabled int;
  r              RECORD;
BEGIN
  SELECT count(*) INTO v_total_tables FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p');

  SELECT count(*) INTO v_rls_enabled FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p') AND c.relrowsecurity;

  v_rls_disabled := v_total_tables - v_rls_enabled;

  IF v_rls_disabled = 0 THEN
    RAISE NOTICE '✓ [046] All % public tables have RLS enabled — rls_disabled_in_public cleared', v_total_tables;
  ELSE
    FOR r IN
      SELECT c.relname FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p') AND NOT c.relrowsecurity
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[046] Still disabled: %', r.relname;
    END LOOP;
    RAISE WARNING '[046] % of % public tables still have RLS disabled', v_rls_disabled, v_total_tables;
  END IF;

  RAISE NOTICE 'Migration 046a complete.';
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Migration 046b: Revoke anon EXECUTE on 9 remaining catalog SECURITY DEFINER functions
-- Uses dynamic OID-based revoke to handle overloaded functions
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r         RECORD;
  v_ok      int := 0;
  v_skip    int := 0;
  v_fail    int := 0;
  v_targets text[] := ARRAY[
    'fn_super_filtro',
    'fn_super_filtro_facets',
    'fn_super_filtro_opcoes',
    'fn_super_filtro_price_range',
    'fn_super_filtro_product_ids',
    'fn_get_all_leaf_categories',
    'fn_get_color_swatches_batch',
    'fn_get_product_customization_options',
    'fn_get_customization_price'
  ];
  v_name    text;
  v_found   boolean;
BEGIN
  FOREACH v_name IN ARRAY v_targets LOOP
    v_found := false;
    FOR r IN
      SELECT p.oid, p.proname, pg_get_function_identity_arguments(p.oid) AS args
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'public' AND p.proname = v_name
        AND has_function_privilege('anon', p.oid, 'EXECUTE')
    LOOP
      v_found := true;
      BEGIN
        EXECUTE format('REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM anon', r.proname, r.args);
        v_ok := v_ok + 1;
        RAISE NOTICE '[046] ✓ REVOKE EXECUTE ON %(%) FROM anon', r.proname, r.args;
      EXCEPTION WHEN OTHERS THEN
        v_fail := v_fail + 1;
        RAISE WARNING '[046] ✗ Could not revoke %(%)): %', r.proname, r.args, SQLERRM;
      END;
    END LOOP;

    IF NOT v_found THEN
      v_skip := v_skip + 1;
      IF NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname = v_name) THEN
        RAISE NOTICE '[046] - % not found in database', v_name;
      ELSE
        RAISE NOTICE '[046] - % already has no anon EXECUTE', v_name;
      END IF;
    END IF;
  END LOOP;

  RAISE NOTICE '[046] Catalog SECDEF revoke: revoked=%, skipped=%, failed=%', v_ok, v_skip, v_fail;
END;
$$;

-- Validate 046b — verify critical SECURITY DEFINER functions retained their mode
DO $$
DECLARE
  v_secdef boolean;
  v_name   text;
BEGIN
  FOREACH v_name IN ARRAY ARRAY['fn_get_product_customization_options', 'fn_get_customization_price'] LOOP
    SELECT p.prosecdef INTO v_secdef FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = v_name LIMIT 1;

    IF NOT FOUND THEN
      RAISE NOTICE '[046] % not found — skip SECDEF check', v_name;
    ELSIF NOT COALESCE(v_secdef, false) THEN
      RAISE EXCEPTION '[046] CRITICAL: % lost SECURITY DEFINER — engraving would break', v_name;
    ELSE
      RAISE NOTICE '[046] ✓ % remains SECURITY DEFINER (invariant preserved)', v_name;
    END IF;
  END LOOP;

  RAISE NOTICE '[046] Migration 046b complete — 046a+046b applied successfully.';
END;
$$;
;

