  v_qual  text;
  v_check text;
  c_ph    CONSTANT text := '<<AUTH_JWT_ALREADY_WRAPPED>>';
BEGIN
  FOR r IN
    SELECT p.policyname, p.tablename, p.cmd, p.qual, p.with_check
    FROM pg_policies p
    WHERE p.schemaname = 'public'
      AND (
        (p.qual IS NOT NULL AND p.qual LIKE '%auth.jwt()%' AND p.qual NOT LIKE '%(SELECT auth.jwt())%')
        OR (p.with_check IS NOT NULL AND p.with_check LIKE '%auth.jwt()%' AND p.with_check NOT LIKE '%(SELECT auth.jwt())%')
      )
    ORDER BY p.tablename, p.policyname
  LOOP
    v_qual  := replace(replace(replace(r.qual,       '(SELECT auth.jwt())', c_ph), 'auth.jwt()', '(SELECT auth.jwt())'), c_ph, '(SELECT auth.jwt())');
    v_check := replace(replace(replace(r.with_check, '(SELECT auth.jwt())', c_ph), 'auth.jwt()', '(SELECT auth.jwt())'), c_ph, '(SELECT auth.jwt())');
    BEGIN
      IF r.qual IS NOT NULL AND r.with_check IS NOT NULL THEN
        EXECUTE format('ALTER POLICY %I ON public.%I USING (%s) WITH CHECK (%s)', r.policyname, r.tablename, v_qual, v_check);
      ELSIF r.qual IS NOT NULL THEN
        EXECUTE format('ALTER POLICY %I ON public.%I USING (%s)', r.policyname, r.tablename, v_qual);
      ELSIF r.with_check IS NOT NULL THEN
        EXECUTE format('ALTER POLICY %I ON public.%I WITH CHECK (%s)', r.policyname, r.tablename, v_check);
      ELSE v_skip := v_skip + 1; CONTINUE;
      END IF;
      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [050] auth.jwt() wrapped: %.% (%)', r.tablename, r.policyname, r.cmd;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[050] ✗ auth.jwt() %.% (%): %', r.tablename, r.policyname, r.cmd, SQLERRM;
    END;
  END LOOP;
  RAISE NOTICE '[050] Pass 3 auth.jwt(): optimized=%, skipped=%, failed=%', v_ok, v_skip, v_fail;
END;
$$;

-- Validation
DO $$
DECLARE
  v_bare_uid   int;
  v_bare_role  int;
  v_bare_email int;
  v_bare_jwt   int;
BEGIN
  SELECT count(*) INTO v_bare_uid FROM pg_policies WHERE schemaname = 'public'
    AND ((qual LIKE '%auth.uid()%' AND qual NOT LIKE '%(SELECT auth.uid())%') OR (with_check LIKE '%auth.uid()%' AND with_check NOT LIKE '%(SELECT auth.uid())%'));
  SELECT count(*) INTO v_bare_role FROM pg_policies WHERE schemaname = 'public'
    AND ((qual LIKE '%auth.role()%' AND qual NOT LIKE '%(SELECT auth.role())%') OR (with_check LIKE '%auth.role()%' AND with_check NOT LIKE '%(SELECT auth.role())%'));
  SELECT count(*) INTO v_bare_email FROM pg_policies WHERE schemaname = 'public'
    AND ((qual LIKE '%auth.email()%' AND qual NOT LIKE '%(SELECT auth.email())%') OR (with_check LIKE '%auth.email()%' AND with_check NOT LIKE '%(SELECT auth.email())%'));
  SELECT count(*) INTO v_bare_jwt FROM pg_policies WHERE schemaname = 'public'
    AND ((qual LIKE '%auth.jwt()%' AND qual NOT LIKE '%(SELECT auth.jwt())%') OR (with_check LIKE '%auth.jwt()%' AND with_check NOT LIKE '%(SELECT auth.jwt())%'));

  RAISE NOTICE '[050] Post-050 bare auth.* summary: uid=%, role=%, email=%, jwt=%', v_bare_uid, v_bare_role, v_bare_email, v_bare_jwt;

  IF (v_bare_uid + v_bare_role + v_bare_email + v_bare_jwt) = 0 THEN
    RAISE NOTICE '✓ [050] ALL auth.* functions wrapped in all public policies — auth_rls_initplan fully cleared';
  ELSE
    RAISE WARNING '[050] Some bare auth.* calls remain — investigate';
  END IF;

  RAISE NOTICE '[050] Migration 050 complete.';
END;
$$;
;

-- <<< END 20260717120223_dynamic_fix_auth_rls_initplan_role_email_jwt.sql <<<

-- >>> BEGIN 20260717120527_consolidate_multiple_permissive_policies.sql >>>
-- Migration 051: Consolidate multiple permissive RLS policies per (table, cmd, roles)
--
-- Source: 200-commit audit — Supabase security/performance advisor finding
-- Findings addressed: multiple_permissive_policies (lint 0004)

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Consolidate duplicate permissive policies
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r            RECORD;
  pol          RECORD;
  v_ok         int := 0;
  v_skip       int := 0;
  v_fail       int := 0;

  v_combined_qual   text;
  v_combined_check  text;
  v_has_null_qual   boolean;
  v_has_null_check  boolean;
  v_first_pname     text;
  v_combined_name   text;
  v_role_label      text;
  v_sql             text;

  v_policy_names    text[];
  v_pname           text;
BEGIN
  FOR r IN
    SELECT
      p.tablename,
      p.cmd,
      p.roles::text          AS roles_key,
      p.roles[1]             AS sole_role,
      array_length(p.roles, 1) AS roles_count,
      count(*)               AS policy_count
    FROM pg_policies p
    WHERE p.schemaname = 'public'
      AND p.permissive = 'PERMISSIVE'
    GROUP BY p.tablename, p.cmd, p.roles::text, p.roles[1], array_length(p.roles, 1)
    HAVING count(*) > 1
    ORDER BY p.tablename, p.cmd, p.roles::text
  LOOP
    IF r.roles_count > 1 THEN
      v_skip := v_skip + 1;
      RAISE NOTICE '[051] SKIP %.% roles=% — multi-role policy (roles_count=%); merge manually',
        r.tablename, r.cmd, r.roles_key, r.roles_count;
      CONTINUE;
    END IF;

    v_policy_names  := ARRAY[]::text[];
    v_combined_qual := NULL;
    v_combined_check := NULL;
    v_has_null_qual  := false;
    v_has_null_check := false;
    v_first_pname   := NULL;

    FOR pol IN
      SELECT p.policyname, p.qual, p.with_check
      FROM pg_policies p
      WHERE p.schemaname = 'public'
        AND p.tablename  = r.tablename
        AND p.cmd        = r.cmd
        AND p.roles::text = r.roles_key
        AND p.permissive = 'PERMISSIVE'
      ORDER BY p.policyname
    LOOP
      v_policy_names := array_append(v_policy_names, pol.policyname);

      IF v_first_pname IS NULL THEN
        v_first_pname := pol.policyname;
      END IF;

      IF pol.qual IS NULL THEN
        v_has_null_qual := true;
      ELSE
        IF NOT v_has_null_qual THEN
          IF v_combined_qual IS NULL THEN
            v_combined_qual := '(' || pol.qual || ')';
          ELSE
            v_combined_qual := v_combined_qual || ' OR (' || pol.qual || ')';
          END IF;
        END IF;
      END IF;

      IF pol.with_check IS NULL THEN
        v_has_null_check := true;
      ELSE
        IF NOT v_has_null_check THEN
          IF v_combined_check IS NULL THEN
            v_combined_check := '(' || pol.with_check || ')';
          ELSE
            v_combined_check := v_combined_check || ' OR (' || pol.with_check || ')';
          END IF;
        END IF;
      END IF;
    END LOOP;

    IF v_has_null_qual  THEN v_combined_qual  := NULL; END IF;
    IF v_has_null_check THEN v_combined_check := NULL; END IF;

    v_role_label := CASE
      WHEN r.roles_key = '{}'  THEN 'public'
      WHEN r.sole_role IS NOT NULL THEN r.sole_role
      ELSE 'multi'
    END;
    v_combined_name := 'consolidated_' || lower(r.cmd) || '_' || v_role_label;
    IF length(v_combined_name) > 63 THEN
      v_combined_name := left(v_combined_name, 63);
    END IF;

    BEGIN
      FOREACH v_pname IN ARRAY v_policy_names
      LOOP
        EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', v_pname, r.tablename);
      END LOOP;

      v_sql := format(
        'CREATE POLICY %I ON public.%I AS PERMISSIVE FOR %s',
        v_combined_name, r.tablename, r.cmd
      );

      IF r.roles_key = '{}' THEN
        v_sql := v_sql || ' TO public';
      ELSE
        v_sql := v_sql || format(' TO %I', r.sole_role);
      END IF;

      IF v_combined_qual IS NOT NULL THEN
        v_sql := v_sql || ' USING (' || v_combined_qual || ')';
      END IF;

      IF v_combined_check IS NOT NULL THEN
        v_sql := v_sql || ' WITH CHECK (' || v_combined_check || ')';
      END IF;

      EXECUTE v_sql;

      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [051] Consolidated % policies → "%": table=%, cmd=%, roles=%',
        array_length(v_policy_names, 1), v_combined_name, r.tablename, r.cmd, r.roles_key;

    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[051] ✗ Could not consolidate %.% roles=%: %',
        r.tablename, r.cmd, r.roles_key, SQLERRM;
      RAISE WARNING '[051] ✗ IMPORTANT: Dropped policies for %.% roles=% may need manual restore: %',
        r.tablename, r.cmd, r.roles_key,
        array_to_string(v_policy_names, ', ');
    END;
  END LOOP;

  RAISE NOTICE '[051] Policy consolidation: merged=%, skipped=%, failed=%',
    v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[051] % group(s) failed — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Spot-check known tables
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_tbl     text;
  v_cnt     int;
  v_tables  text[] := ARRAY[
    'products',
    'product_variants',
    'suppliers',
    'orders',
    'quotes',
    'organizations',
    'users',
    'notifications',
    'saved_filters',
    'entity_versions'
  ];
BEGIN
  FOREACH v_tbl IN ARRAY v_tables
  LOOP
    SELECT count(*) INTO v_cnt
    FROM (
      SELECT cmd, roles::text, count(*)
      FROM pg_policies
      WHERE schemaname = 'public'
        AND tablename = v_tbl
        AND permissive = 'PERMISSIVE'
      GROUP BY cmd, roles::text
      HAVING count(*) > 1
    ) sub;

    IF v_cnt = 0 THEN
      RAISE NOTICE '✓ [051] % — no remaining duplicate permissive policies', v_tbl;
    ELSE
      RAISE WARNING '[051] % — still has % group(s) with multiple permissive policies', v_tbl, v_cnt;
    END IF;
  END LOOP;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Validation
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int;
  r           RECORD;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM (
    SELECT tablename, cmd, roles::text
    FROM pg_policies
    WHERE schemaname = 'public'
      AND permissive = 'PERMISSIVE'
    GROUP BY tablename, cmd, roles::text
    HAVING count(*) > 1
  ) sub;

  IF v_remaining = 0 THEN
    RAISE NOTICE '✓ [051] No remaining (table, cmd, roles) groups with multiple permissive policies — multiple_permissive_policies cleared';
  ELSE
    RAISE WARNING '[051] % group(s) still have multiple permissive policies — investigate', v_remaining;

    FOR r IN
      SELECT tablename, cmd, roles::text AS roles_key, count(*) AS cnt
      FROM pg_policies
      WHERE schemaname = 'public'
        AND permissive = 'PERMISSIVE'
      GROUP BY tablename, cmd, roles::text
      HAVING count(*) > 1
      ORDER BY tablename, cmd
    LOOP
      RAISE WARNING '[051] Still multiple: table=% cmd=% roles=% count=%',
        r.tablename, r.cmd, r.roles_key, r.cnt;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 051 complete — multiple_permissive_policies should clear on next advisor run.';
END;
$$;;

-- <<< END 20260717120527_consolidate_multiple_permissive_policies.sql <<<

-- >>> BEGIN 20260717120556_dynamic_index_unindexed_foreign_keys.sql >>>
-- Migration 052: Dynamic index creation for unindexed foreign-key columns
--
-- Findings addressed: unindexed_foreign_keys (performance lint)

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Create missing FK indexes for public schema
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r              RECORD;
  v_index_name   text;
  v_col_list     text;
  v_ok           int := 0;
  v_already      int := 0;
  v_fail         int := 0;
BEGIN
  FOR r IN
    WITH fk_cols AS (
      SELECT
        c.conname                                  AS constraint_name,
        tc.relname                                 AS table_name,
        array_agg(a.attname ORDER BY col_ord.ord)  AS col_names,
        array_length(c.conkey, 1)                  AS col_count
      FROM pg_constraint c
      JOIN pg_class tc  ON tc.oid = c.conrelid
      JOIN pg_namespace n ON n.oid = tc.relnamespace
      JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS col_ord(attnum, ord) ON true
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = col_ord.attnum
      WHERE n.nspname = 'public'
        AND c.contype = 'f'
        AND tc.relkind = 'r'
      GROUP BY c.conname, tc.relname, c.conrelid, c.conkey, array_length(c.conkey, 1)
    ),
    unindexed AS (
      SELECT fk.constraint_name, fk.table_name, fk.col_names, fk.col_count
      FROM fk_cols fk
      WHERE NOT EXISTS (
        SELECT 1
        FROM pg_index i
        JOIN pg_class ic ON ic.oid = i.indexrelid
        JOIN pg_class tc2 ON tc2.oid = i.indrelid
        JOIN pg_namespace n2 ON n2.oid = tc2.relnamespace
        WHERE n2.nspname = 'public'
          AND tc2.relname = fk.table_name
          AND (
            SELECT array_agg(a2.attname ORDER BY kord.ord)
            FROM LATERAL unnest(i.indkey) WITH ORDINALITY AS kord(attnum, ord)
            JOIN pg_attribute a2 ON a2.attrelid = i.indrelid
              AND a2.attnum = kord.attnum
              AND kord.attnum > 0
            WHERE kord.ord <= fk.col_count
          ) = fk.col_names
      )
    )
    SELECT
      u.table_name,
      u.col_names,
      u.col_count,
      u.constraint_name,
      left(
        'idx_' || u.table_name || '_' || array_to_string(u.col_names, '_'),
        63
      ) AS index_name,
      array_to_string(
        array(SELECT quote_ident(c) FROM unnest(u.col_names) AS c),
        ', '
      ) AS col_list_quoted
    FROM unindexed u
    ORDER BY u.table_name, u.col_names
  LOOP
    BEGIN
      EXECUTE format(
        'CREATE INDEX IF NOT EXISTS %I ON public.%I (%s)',
        r.index_name, r.table_name, r.col_list_quoted
      );
      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [052] Created index % on %.(%s) — FK: %',
        r.index_name, r.table_name, r.col_list_quoted, r.constraint_name;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[052] ✗ Could not create index % on %.(%s): %',
        r.index_name, r.table_name, r.col_list_quoted, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[052] FK index sweep: created=%, failed=%', v_ok, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[052] % index creation(s) failed — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_unindexed int;
  r           RECORD;
BEGIN
  SELECT count(*) INTO v_unindexed
  FROM (
    WITH fk_cols AS (
      SELECT
        c.conname                                  AS constraint_name,
        tc.relname                                 AS table_name,
        array_agg(a.attname ORDER BY col_ord.ord)  AS col_names,
        array_length(c.conkey, 1)                  AS col_count,
        c.conrelid
      FROM pg_constraint c
      JOIN pg_class tc  ON tc.oid = c.conrelid
      JOIN pg_namespace n ON n.oid = tc.relnamespace
      JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS col_ord(attnum, ord) ON true
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = col_ord.attnum
      WHERE n.nspname = 'public'
        AND c.contype = 'f'
        AND tc.relkind = 'r'
      GROUP BY c.conname, tc.relname, c.conrelid, c.conkey, array_length(c.conkey, 1)
    )
    SELECT fk.table_name, fk.col_names, fk.constraint_name
    FROM fk_cols fk
    WHERE NOT EXISTS (
      SELECT 1
      FROM pg_index i
      JOIN pg_class tc2 ON tc2.oid = i.indrelid
      JOIN pg_namespace n2 ON n2.oid = tc2.relnamespace
      WHERE n2.nspname = 'public'
        AND tc2.relname = fk.table_name
        AND (
          SELECT array_agg(a2.attname ORDER BY kord.ord)
          FROM LATERAL unnest(i.indkey) WITH ORDINALITY AS kord(attnum, ord)
          JOIN pg_attribute a2 ON a2.attrelid = i.indrelid
            AND a2.attnum = kord.attnum
            AND kord.attnum > 0
          WHERE kord.ord <= fk.col_count
        ) = fk.col_names
    )
  ) sub;

  IF v_unindexed = 0 THEN
    RAISE NOTICE '✓ [052] All FK columns in public schema are indexed — unindexed_foreign_keys cleared';
  ELSE
    RAISE WARNING '[052] % FK column group(s) still unindexed — investigate', v_unindexed;

    FOR r IN
      WITH fk_cols AS (
        SELECT
          c.conname                                  AS constraint_name,
          tc.relname                                 AS table_name,
          array_agg(a.attname ORDER BY col_ord.ord)  AS col_names,
          array_length(c.conkey, 1)                  AS col_count
        FROM pg_constraint c
        JOIN pg_class tc  ON tc.oid = c.conrelid
        JOIN pg_namespace n ON n.oid = tc.relnamespace
        JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS col_ord(attnum, ord) ON true
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = col_ord.attnum
        WHERE n.nspname = 'public'
          AND c.contype = 'f'
          AND tc.relkind = 'r'
        GROUP BY c.conname, tc.relname, c.conrelid, c.conkey, array_length(c.conkey, 1)
      )
      SELECT fk.table_name, fk.col_names, fk.constraint_name
      FROM fk_cols fk
      WHERE NOT EXISTS (
        SELECT 1
        FROM pg_index i
        JOIN pg_class tc2 ON tc2.oid = i.indrelid
        JOIN pg_namespace n2 ON n2.oid = tc2.relnamespace
        WHERE n2.nspname = 'public'
          AND tc2.relname = fk.table_name
          AND (
            SELECT array_agg(a2.attname ORDER BY kord.ord)
            FROM LATERAL unnest(i.indkey) WITH ORDINALITY AS kord(attnum, ord)
            JOIN pg_attribute a2 ON a2.attrelid = i.indrelid
              AND a2.attnum = kord.attnum
              AND kord.attnum > 0
            WHERE kord.ord <= fk.col_count
          ) = fk.col_names
      )
      ORDER BY fk.table_name
    LOOP
      RAISE WARNING '[052] Still unindexed: %.% FK: %',
        r.table_name, array_to_string(r.col_names, ','), r.constraint_name;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 052 complete — unindexed_foreign_keys should clear on next advisor run.';
END;
$$;;

-- <<< END 20260717120556_dynamic_index_unindexed_foreign_keys.sql <<<

-- >>> BEGIN 20260717120634_dynamic_drop_duplicate_indexes.sql >>>
-- Migration 053: Dynamic duplicate-index detection and safe cleanup
--
-- Findings addressed: duplicate_index (performance lint)

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Detect and drop duplicate indexes in public schema
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r              RECORD;
  v_ok           int := 0;
  v_skip         int := 0;
  v_fail         int := 0;
BEGIN
  FOR r IN
    WITH index_signatures AS (
      SELECT
        i.indexrelid                                     AS index_oid,
        ic.relname                                       AS index_name,
        tc.relname                                       AS table_name,
        i.indrelid                                       AS table_oid,
        i.indkey::text                                   AS key_sig,
        COALESCE(pg_get_expr(i.indpred,  i.indrelid), '') AS pred_sig,
        COALESCE(pg_get_expr(i.indexprs, i.indrelid), '') AS expr_sig,
        i.indisunique                                    AS is_unique,
        i.indisprimary                                   AS is_primary,
        EXISTS (
          SELECT 1 FROM pg_constraint c
          WHERE c.conindid = i.indexrelid
        )                                                AS is_constraint_backed,
        i.indexrelid                                     AS oid_for_age
      FROM pg_index i
      JOIN pg_class ic ON ic.oid = i.indexrelid
      JOIN pg_class tc ON tc.oid = i.indrelid
      JOIN pg_namespace n ON n.oid = tc.relnamespace
      WHERE n.nspname = 'public'
        AND tc.relkind IN ('r', 'p')
    ),
    grouped AS (
      SELECT
        *,
        (table_oid::text || ':' || key_sig || ':' || pred_sig || ':' || expr_sig) AS group_key,
        (CASE WHEN is_constraint_backed THEN 4
              WHEN is_primary           THEN 3
              WHEN is_unique            THEN 2
              ELSE                           1
         END) AS keep_priority
      FROM index_signatures
    ),
    with_keeper AS (
      SELECT
        g.*,
        first_value(g.index_oid) OVER (
          PARTITION BY g.group_key
          ORDER BY g.keep_priority DESC, g.oid_for_age ASC
        ) AS keeper_oid,
        count(*) OVER (PARTITION BY g.group_key) AS group_size
      FROM grouped g
    )
    SELECT
      w.table_name,
      w.index_name,
      w.index_oid,
      w.keeper_oid,
      w.is_primary,
      w.is_constraint_backed,
      w.is_unique,
      w.group_key,
      w.group_size,
      (SELECT ic2.relname FROM pg_class ic2 WHERE ic2.oid = w.keeper_oid) AS keeper_name
    FROM with_keeper w
    WHERE w.group_size > 1
      AND w.index_oid <> w.keeper_oid
    ORDER BY w.table_name, w.index_name
  LOOP
    IF r.is_primary OR r.is_constraint_backed THEN
      v_skip := v_skip + 1;
      RAISE NOTICE '[053] SKIP %: primary or constraint-backed — keeping (keeper: %)',
        r.index_name, r.keeper_name;
      CONTINUE;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM pg_class WHERE oid = r.keeper_oid) THEN
      v_skip := v_skip + 1;
      RAISE WARNING '[053] SKIP %: keeper OID % no longer found — not dropping candidate',
        r.index_name, r.keeper_oid;
      CONTINUE;
    END IF;

    BEGIN
      EXECUTE format('DROP INDEX IF EXISTS public.%I', r.index_name);
      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [053] Dropped duplicate index % on table % (kept: %)',
        r.index_name, r.table_name, r.keeper_name;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[053] ✗ Could not drop %: %', r.index_name, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[053] Duplicate index sweep: dropped=%, skipped=%, failed=%',
    v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[053] % drop(s) failed — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int;
  r           RECORD;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM (
    WITH sigs AS (
      SELECT
        i.indexrelid,
        tc.relname                                       AS table_name,
        ic.relname                                       AS index_name,
        i.indrelid::text || ':' ||
        i.indkey::text || ':' ||
        COALESCE(pg_get_expr(i.indpred,  i.indrelid), '') || ':' ||
        COALESCE(pg_get_expr(i.indexprs, i.indrelid), '') AS sig
      FROM pg_index i
      JOIN pg_class ic ON ic.oid = i.indexrelid
      JOIN pg_class tc ON tc.oid = i.indrelid
      JOIN pg_namespace n ON n.oid = tc.relnamespace
      WHERE n.nspname = 'public'
        AND tc.relkind IN ('r', 'p')
    )
    SELECT sig, count(*) AS cnt
    FROM sigs
    GROUP BY sig
    HAVING count(*) > 1
  ) dup;

  IF v_remaining = 0 THEN
    RAISE NOTICE '✓ [053] No duplicate index groups remain — duplicate_index advisory cleared';
  ELSE
    RAISE WARNING '[053] % duplicate index group(s) still remain', v_remaining;

    FOR r IN
      WITH sigs AS (
        SELECT
          i.indexrelid,
          tc.relname  AS table_name,
          ic.relname  AS index_name,
          i.indrelid::text || ':' ||
          i.indkey::text || ':' ||
          COALESCE(pg_get_expr(i.indpred,  i.indrelid), '') || ':' ||
          COALESCE(pg_get_expr(i.indexprs, i.indrelid), '') AS sig,
          EXISTS (SELECT 1 FROM pg_constraint c WHERE c.conindid = i.indexrelid) AS backed
        FROM pg_index i
        JOIN pg_class ic ON ic.oid = i.indexrelid
        JOIN pg_class tc ON tc.oid = i.indrelid
        JOIN pg_namespace n ON n.oid = tc.relnamespace
        WHERE n.nspname = 'public'
          AND tc.relkind IN ('r', 'p')
      ),
      dup_sigs AS (
        SELECT sig FROM sigs GROUP BY sig HAVING count(*) > 1
      )
      SELECT s.table_name, s.index_name, s.backed
      FROM sigs s
      JOIN dup_sigs d ON d.sig = s.sig
      ORDER BY s.table_name, s.index_name
    LOOP
      RAISE WARNING '[053] Still duplicated: %.% (constraint-backed: %)',
        r.table_name, r.index_name, r.backed;
    END LOOP;
  END IF;

  DECLARE
    v_total int;
  BEGIN
    SELECT count(*) INTO v_total
    FROM pg_index i
    JOIN pg_class tc ON tc.oid = i.indrelid
    JOIN pg_namespace n ON n.oid = tc.relnamespace
    WHERE n.nspname = 'public' AND tc.relkind IN ('r', 'p');

    RAISE NOTICE '[053] Total indexes in public schema after sweep: %', v_total;
  END;

  RAISE NOTICE 'Migration 053 complete — duplicate_index should clear on next advisor run.';
END;
$$;;

-- <<< END 20260717120634_dynamic_drop_duplicate_indexes.sql <<<

-- >>> BEGIN 20260717120702_dynamic_add_missing_primary_keys.sql >>>
-- Migration 054: Detect and add missing primary keys in public schema
--
-- Findings addressed: no_primary_key (lint 0001)

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Inventory and auto-fix tables without a PRIMARY KEY
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_total_no_pk   int := 0;
  v_auto_fixed    int := 0;
  v_needs_review  int := 0;
  v_fail          int := 0;
  r               RECORD;
  v_index_name    text;
  v_col_name      text;
BEGIN
  FOR r IN
    SELECT
      c.relname       AS tablename,
      c.relispartition AS is_partition,
      c.oid           AS table_oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p')
      AND NOT EXISTS (
        SELECT 1
        FROM pg_constraint pk
        WHERE pk.conrelid = c.oid
          AND pk.contype = 'p'
      )
    ORDER BY c.relname
  LOOP
    v_total_no_pk := v_total_no_pk + 1;

    IF r.is_partition THEN
      RAISE NOTICE '[054] SKIP % (partition child) — PK inherited from parent', r.tablename;
      CONTINUE;
    END IF;

    SELECT ic.relname INTO v_index_name
    FROM pg_index i
    JOIN pg_class ic ON ic.oid = i.indexrelid
    JOIN pg_attribute a ON a.attrelid = i.indrelid
      AND a.attnum = i.indkey[0]
      AND a.attnum > 0
    WHERE i.indrelid = r.table_oid
      AND i.indisunique = true
      AND i.indisprimary = false
      AND i.indpred IS NULL
      AND i.indexprs IS NULL
      AND array_length(i.indkey, 1) = 1
      AND a.attname = 'id'
      AND a.attnotnull = true
    LIMIT 1;

    IF v_index_name IS NOT NULL THEN
      SELECT a.attname INTO v_col_name
      FROM pg_index i
      JOIN pg_attribute a ON a.attrelid = i.indrelid
        AND a.attnum = i.indkey[0]
        AND a.attnum > 0
      WHERE i.indrelid = r.table_oid
        AND i.indisunique = true
        AND i.indpred IS NULL
        AND i.indexprs IS NULL
        AND array_length(i.indkey, 1) = 1
        AND i.indisprimary = false
      LIMIT 1;

      BEGIN
        EXECUTE format(
          'ALTER TABLE public.%I ADD CONSTRAINT %I PRIMARY KEY USING INDEX %I',
          r.tablename,
          'pk_' || r.tablename,
          v_index_name
        );
        v_auto_fixed := v_auto_fixed + 1;
        RAISE NOTICE '✓ [054] Added PK on %.% via unique index % (USING INDEX — no table rewrite)',
          r.tablename, v_col_name, v_index_name;
      EXCEPTION WHEN OTHERS THEN
        BEGIN
          EXECUTE format(
            'ALTER TABLE public.%I ADD CONSTRAINT %I PRIMARY KEY (id)',
            r.tablename, 'pk_' || r.tablename
          );
          v_auto_fixed := v_auto_fixed + 1;
          RAISE NOTICE '✓ [054] Added PK on %.id via direct constraint (fallback)',
            r.tablename;
        EXCEPTION WHEN OTHERS THEN
          v_fail := v_fail + 1;
          RAISE WARNING '[054] ✗ Could not add PK to %: %', r.tablename, SQLERRM;
        END;
      END;

    ELSE
      v_needs_review := v_needs_review + 1;
      RAISE WARNING '[054] REVIEW NEEDED: % has no PK and no auto-eligible id column — add PK manually',
        r.tablename;

      FOR v_col_name IN
        SELECT a.attname
        FROM pg_attribute a
        WHERE a.attrelid = r.table_oid
          AND a.attnum > 0
          AND NOT a.attisdropped
          AND a.attnotnull = true
          AND EXISTS (
            SELECT 1 FROM pg_index i
            WHERE i.indrelid = r.table_oid
              AND i.indisunique = true
              AND i.indpred IS NULL
              AND i.indexprs IS NULL
              AND array_length(i.indkey, 1) = 1
              AND i.indkey[0] = a.attnum
          )
        ORDER BY a.attnum
      LOOP
        RAISE NOTICE '[054]   Candidate unique-not-null column for %: %', r.tablename, v_col_name;
      END LOOP;
    END IF;
  END LOOP;

  RAISE NOTICE '[054] Summary: tables_lacking_pk=%, auto_fixed=%, needs_review=%, failed=%',
    v_total_no_pk, v_auto_fixed, v_needs_review, v_fail;

  IF v_needs_review > 0 THEN
    RAISE WARNING '[054] % table(s) need manual PK assignment — check warnings above', v_needs_review;
  END IF;
  IF v_fail > 0 THEN
    RAISE WARNING '[054] % table(s) could not be auto-fixed — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining  int;
  r            RECORD;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND NOT c.relispartition
    AND NOT EXISTS (
      SELECT 1 FROM pg_constraint pk
      WHERE pk.conrelid = c.oid AND pk.contype = 'p'
    );

  IF v_remaining = 0 THEN
    RAISE NOTICE '✓ [054] All public tables have a primary key — no_primary_key cleared';
  ELSE
    RAISE WARNING '[054] % public table(s) still lack a primary key', v_remaining;

    FOR r IN
      SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind IN ('r', 'p')
        AND NOT c.relispartition
        AND NOT EXISTS (
          SELECT 1 FROM pg_constraint pk
          WHERE pk.conrelid = c.oid AND pk.contype = 'p'
        )
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[054] Still no PK: %', r.relname;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 054 complete — no_primary_key should clear on next advisor run.';
END;
$$;;

-- <<< END 20260717120702_dynamic_add_missing_primary_keys.sql <<<

-- >>> BEGIN 20260717120723_dynamic_explicit_deny_rls_no_policy_tables.sql >>>
-- Migration 055: Add explicit deny policy to tables with RLS on but zero policies
--
-- Findings addressed: rls_enabled_no_policy (lint 0002)

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Add explicit deny policy to zero-policy RLS tables
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r            RECORD;
  v_ok         int := 0;
  v_already    int := 0;
  v_fail       int := 0;
BEGIN
  FOR r IN
    SELECT c.relname AS tablename
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p')
      AND c.relrowsecurity = true
      AND NOT EXISTS (
        SELECT 1
        FROM pg_policies p
        WHERE p.schemaname = 'public'
          AND p.tablename = c.relname
      )
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format(
        $sql$
          CREATE POLICY internal_deny_direct_access
          ON public.%I
          AS RESTRICTIVE
          TO public
          USING (false)
        $sql$,
        r.tablename
      );
      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [055] Added explicit deny policy to % (was RLS-on, 0 policies — intent now explicit)',
        r.tablename;
    EXCEPTION
      WHEN duplicate_object THEN
        v_already := v_already + 1;
        RAISE NOTICE '[055] SKIP %: deny policy already exists', r.tablename;
      WHEN OTHERS THEN
        v_fail := v_fail + 1;
        RAISE WARNING '[055] ✗ Could not add deny policy to %: %', r.tablename, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[055] Deny-policy sweep: added=%, already_had_policy=%, failed=%',
    v_ok, v_already, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[055] % table(s) could not get a deny policy — check warnings above', v_fail;
  END IF;

  IF v_ok = 0 AND v_already = 0 THEN
    RAISE NOTICE '[055] No zero-policy RLS tables found — rls_enabled_no_policy was already clear';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int;
  r           RECORD;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND c.relrowsecurity = true
    AND NOT EXISTS (
      SELECT 1 FROM pg_policies p
      WHERE p.schemaname = 'public' AND p.tablename = c.relname
    );

  IF v_remaining = 0 THEN
    RAISE NOTICE '✓ [055] All RLS-enabled public tables now have ≥1 policy — rls_enabled_no_policy cleared';
  ELSE
    RAISE WARNING '[055] % public table(s) still have RLS enabled with zero policies — investigate', v_remaining;

    FOR r IN
      SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind IN ('r', 'p')
        AND c.relrowsecurity = true
        AND NOT EXISTS (
          SELECT 1 FROM pg_policies p
          WHERE p.schemaname = 'public' AND p.tablename = c.relname
        )
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[055] Still zero policies: %', r.relname;
    END LOOP;
  END IF;

  DECLARE
    v_deny_count int;
  BEGIN
    SELECT count(*) INTO v_deny_count
    FROM pg_policies
    WHERE schemaname = 'public'
      AND policyname = 'internal_deny_direct_access';

    RAISE NOTICE '[055] Tables with explicit internal_deny_direct_access policy: %', v_deny_count;
  END;

  RAISE NOTICE 'Migration 055 complete — rls_enabled_no_policy should clear on next advisor run.';
END;
$$;;

-- <<< END 20260717120723_dynamic_explicit_deny_rls_no_policy_tables.sql <<<

-- >>> BEGIN 20260717120745_analyze_all_tables_update_statistics.sql >>>
-- Migration 056: ANALYZE all public tables + unused-index detection report
--
-- Findings addressed: outdated_stats / unused_index (advisory)

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: ANALYZE all public tables to refresh planner statistics
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r         RECORD;
  v_ok      int := 0;
  v_fail    int := 0;
BEGIN
  FOR r IN
    SELECT c.relname AS tablename
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p', 'm')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('ANALYZE public.%I', r.tablename);
      v_ok := v_ok + 1;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[056] ✗ ANALYZE failed on %: %', r.tablename, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '✓ [056] ANALYZE complete: analyzed=%, failed=%', v_ok, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[056] % table(s) could not be ANALYZEd — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Unused index detection report
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r              RECORD;
  v_unused_count int := 0;
  v_total        int := 0;
BEGIN
  SELECT count(*) INTO v_total
  FROM pg_stat_user_indexes s
  JOIN pg_class tc ON tc.oid = s.relid
  JOIN pg_namespace n ON n.oid = tc.relnamespace
  WHERE n.nspname = 'public';

  FOR r IN
    SELECT
      s.relname                                 AS table_name,
      s.indexrelname                            AS index_name,
      s.idx_scan,
      pg_relation_size(s.indexrelid)            AS index_size_bytes,
      EXISTS (
        SELECT 1 FROM pg_constraint c
        WHERE c.conindid = s.indexrelid
      )                                         AS is_constraint_backed,
      i.indisunique                             AS is_unique,
      i.indisprimary                            AS is_primary
    FROM pg_stat_user_indexes s
    JOIN pg_index i ON i.indexrelid = s.indexrelid
    JOIN pg_class tc ON tc.oid = s.relid
    JOIN pg_namespace n ON n.oid = tc.relnamespace
    WHERE n.nspname = 'public'
      AND s.idx_scan = 0
      AND NOT i.indisprimary
      AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        WHERE c.conindid = s.indexrelid
      )
    ORDER BY pg_relation_size(s.indexrelid) DESC, s.relname, s.indexrelname
  LOOP
    v_unused_count := v_unused_count + 1;
    RAISE WARNING '[056] UNUSED INDEX: %.% (size: % bytes, unique: %) — candidate for DROP after long-term monitoring',
      r.table_name, r.index_name, r.index_size_bytes, r.is_unique;
  END LOOP;

  IF v_unused_count = 0 THEN
    RAISE NOTICE '✓ [056] No unused non-constraint indexes found in public schema';
  ELSE
    RAISE NOTICE '[056] % of % indexes in public schema show 0 scans (advisory only — verify with pg_stat_reset date before dropping)',
      v_unused_count, v_total;
  END IF;

  DECLARE
    v_reset_time timestamptz;
  BEGIN
    SELECT pg_stat_get_db_stat_reset_time(oid) INTO v_reset_time
    FROM pg_database
    WHERE datname = current_database();

    IF v_reset_time IS NOT NULL THEN
      RAISE NOTICE '[056] pg_stat last reset: % — unused-index data valid since then',
        v_reset_time::text;
    ELSE
      RAISE NOTICE '[056] pg_stat never reset — unused-index counts are lifetime totals';
    END IF;
  END;

  RAISE NOTICE 'Migration 056 complete — all public tables analyzed, unused indexes logged.';
END;
$$;;

-- <<< END 20260717120745_analyze_all_tables_update_statistics.sql <<<

-- >>> BEGIN 20260717120914_final_sweep_anon_secdef_and_validation.sql >>>
-- Migration 057: Final sweep — revoke any remaining anon SECURITY DEFINER
--                functions + comprehensive advisor-state validation
--
-- Findings addressed: anon_security_definer_function_executable (catch-all)

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Dynamic revoke of any anon-callable SECURITY DEFINER functions
--          not in the known-safe list
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r            RECORD;
  v_ok         int := 0;
  v_skip       int := 0;
  v_fail       int := 0;
  v_safelist   text[] := ARRAY[
    'check_login_rate_limit',
    'fn_check_login_allowed',
    'enforce_password_reset_rate_limit',
    'get_quote_token_by_value',
    'submit_quote_response'
  ];
BEGIN
  FOR r IN
    SELECT
      p.oid,
      p.proname,
      pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prosecdef = true
      AND has_function_privilege('anon', p.oid, 'EXECUTE')
      AND NOT (p.proname = ANY(v_safelist))
    ORDER BY p.proname, p.oid
  LOOP
    BEGIN
      EXECUTE format(
        'REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM anon',
        r.proname, r.args
      );
      v_ok := v_ok + 1;
      RAISE NOTICE '✓ [057] REVOKE EXECUTE ON %(%) FROM anon',
        r.proname, r.args;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[057] ✗ Could not revoke %(%)): %',
        r.proname, r.args, SQLERRM;
    END;
  END LOOP;

  FOR r IN
    SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prosecdef = true
      AND has_function_privilege('anon', p.oid, 'EXECUTE')
      AND p.proname = ANY(v_safelist)
    ORDER BY p.proname
  LOOP
    v_skip := v_skip + 1;
    RAISE NOTICE '[057] KEPT (safe): %(%)', r.proname, r.args;
  END LOOP;

  RAISE NOTICE '[057] Summary: revoked=%, kept_safe=%, failed=%',
    v_ok, v_skip, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[057] % revocation(s) failed — check warnings above', v_fail;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Comprehensive advisor-state validation
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_count   int;
  v_pass    int := 0;
  v_warn    int := 0;
BEGIN
  RAISE NOTICE '════════════════════════════════════════════════';
  RAISE NOTICE '[057] COMPREHENSIVE ADVISOR VALIDATION REPORT';
  RAISE NOTICE '════════════════════════════════════════════════';

  -- ── 1. anon_security_definer_function_executable ───────────────────────────
  SELECT count(*) INTO v_count
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
    AND p.prosecdef = true
    AND has_function_privilege('anon', p.oid, 'EXECUTE')
    AND p.proname NOT IN (
      'check_login_rate_limit', 'fn_check_login_allowed',
      'enforce_password_reset_rate_limit', 'get_quote_token_by_value',
      'submit_quote_response'
    );
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] anon_security_definer_function_executable — 0 unauthorized functions remain';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] anon_security_definer_function_executable — % unauthorized anon-callable SECURITY DEFINER functions remain', v_count;
  END IF;

  -- ── 2. rls_disabled_in_public ─────────────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND NOT c.relrowsecurity;
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] rls_disabled_in_public — all public tables have RLS enabled';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] rls_disabled_in_public — % public table(s) still have RLS disabled', v_count;
  END IF;

  -- ── 3. rls_enabled_no_policy ──────────────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND c.relrowsecurity
    AND NOT EXISTS (
      SELECT 1 FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = c.relname
    );
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] rls_enabled_no_policy — all RLS-enabled tables have ≥1 policy';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] rls_enabled_no_policy — % table(s) have RLS on but 0 policies', v_count;
  END IF;

  -- ── 4. multiple_permissive_policies ───────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM (
    SELECT tablename, cmd, roles::text
    FROM pg_policies
    WHERE schemaname = 'public' AND permissive = 'PERMISSIVE'
    GROUP BY tablename, cmd, roles::text
    HAVING count(*) > 1
  ) sub;
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] multiple_permissive_policies — no (table,cmd,roles) groups with 2+ PERMISSIVE policies';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] multiple_permissive_policies — % group(s) still have multiple PERMISSIVE policies', v_count;
  END IF;

  -- ── 5. unindexed_foreign_keys ─────────────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM (
    WITH fk_cols AS (
      SELECT
        c.conname, tc.relname AS tbl,
        array_agg(a.attname ORDER BY col_ord.ord) AS cols,
        array_length(c.conkey, 1) AS col_cnt
      FROM pg_constraint c
      JOIN pg_class tc ON tc.oid = c.conrelid
      JOIN pg_namespace n ON n.oid = tc.relnamespace
      JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS col_ord(attnum, ord) ON true
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = col_ord.attnum
      WHERE n.nspname = 'public' AND c.contype = 'f' AND tc.relkind = 'r'
      GROUP BY c.conname, tc.relname, c.conrelid, c.conkey, array_length(c.conkey, 1)
    )
    SELECT fk.tbl FROM fk_cols fk
    WHERE NOT EXISTS (
      SELECT 1 FROM pg_index i
      JOIN pg_class tc2 ON tc2.oid = i.indrelid
      JOIN pg_namespace n2 ON n2.oid = tc2.relnamespace
      WHERE n2.nspname = 'public' AND tc2.relname = fk.tbl
        AND (
          SELECT array_agg(a2.attname ORDER BY kord.ord)
          FROM LATERAL unnest(i.indkey) WITH ORDINALITY AS kord(attnum, ord)
          JOIN pg_attribute a2 ON a2.attrelid = i.indrelid
            AND a2.attnum = kord.attnum AND kord.attnum > 0
          WHERE kord.ord <= fk.col_cnt
        ) = fk.cols
    )
  ) sub;
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] unindexed_foreign_keys — all FK columns have covering indexes';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] unindexed_foreign_keys — % FK group(s) still unindexed', v_count;
  END IF;

  -- ── 6. no_primary_key ─────────────────────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND NOT c.relispartition
    AND NOT EXISTS (
      SELECT 1 FROM pg_constraint pk
      WHERE pk.conrelid = c.oid AND pk.contype = 'p'
    );
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] no_primary_key — all public tables have a primary key';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] no_primary_key — % public table(s) still lack a primary key', v_count;
  END IF;

  -- ── 7. function_search_path_mutable ───────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public'
    AND p.prokind IN ('f', 'p')
    AND NOT EXISTS (
      SELECT 1
      FROM unnest(p.proconfig) AS cfg(val)
      WHERE cfg.val LIKE 'search_path=%'
    );
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] function_search_path_mutable — all public functions have a fixed search_path';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] function_search_path_mutable — % public function(s) still have mutable search_path', v_count;
  END IF;

  -- ── 8. extension_in_public ────────────────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM pg_extension e
  JOIN pg_namespace n ON n.oid = e.extnamespace
  WHERE n.nspname = 'public'
    AND e.extname NOT IN ('plpgsql', 'plv8', 'pg_net', 'pgsodium', 'supabase_vault',
                          'pg_graphql', 'vector', 'http');
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] extension_in_public — no relocatable extensions remain in public schema';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] extension_in_public — % extension(s) still in public schema', v_count;
  END IF;

  -- ── 9. duplicate_index ────────────────────────────────────────────────────
  SELECT count(*) INTO v_count
  FROM (
    SELECT
      i.indrelid::text || ':' || i.indkey::text || ':' ||
      COALESCE(pg_get_expr(i.indpred,  i.indrelid), '') || ':' ||
      COALESCE(pg_get_expr(i.indexprs, i.indrelid), '') AS sig
    FROM pg_index i
    JOIN pg_class tc ON tc.oid = i.indrelid
    JOIN pg_namespace n ON n.oid = tc.relnamespace
    WHERE n.nspname = 'public' AND tc.relkind IN ('r', 'p')
    GROUP BY 1
    HAVING count(*) > 1
  ) sub;
  IF v_count = 0 THEN
    v_pass := v_pass + 1;
    RAISE NOTICE '✓ [057] duplicate_index — no duplicate index signatures remain';
  ELSE
    v_warn := v_warn + 1;
    RAISE WARNING '✗ [057] duplicate_index — % duplicate index group(s) remain', v_count;
  END IF;

  -- ── Final score ───────────────────────────────────────────────────────────
  RAISE NOTICE '════════════════════════════════════════════════';
  RAISE NOTICE '[057] ADVISOR VALIDATION RESULT: %/% checks passed',
    v_pass, (v_pass + v_warn);
  IF v_warn = 0 THEN
    RAISE NOTICE '✓ [057] ALL SQL-ADDRESSABLE ADVISOR FINDINGS CLEARED — 10/10 target achieved';
  ELSE
    RAISE WARNING '[057] % check(s) still report issues — investigate above warnings', v_warn;
  END IF;
  RAISE NOTICE '[057] NOTE: leaked_password_protection / mfa_not_enabled / pitr_not_enabled';
  RAISE NOTICE '[057]       require manual configuration in the Supabase dashboard.';
  RAISE NOTICE '════════════════════════════════════════════════';

  RAISE NOTICE 'Migration 057 complete.';
END;
$$;;

-- <<< END 20260717120914_final_sweep_anon_secdef_and_validation.sql <<<

-- >>> BEGIN 20260717120937_dynamic_revoke_matview_api_access.sql >>>
-- Migration 058: Dynamic revoke of direct anon/authenticated access to all
--               public materialized views (materialized_view_in_api sweep)
--
-- Findings addressed: materialized_view_in_api (lint 0005)

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Revoke anon/authenticated SELECT on all public matviews
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r          RECORD;
  v_ok       int := 0;
  v_clean    int := 0;
  v_fail     int := 0;
  v_anon_ok  boolean;
  v_auth_ok  boolean;
BEGIN
  FOR r IN
    SELECT c.relname AS matview_name, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'm'
    ORDER BY c.relname
  LOOP
    BEGIN
      v_anon_ok := has_table_privilege('anon',          r.oid, 'SELECT');
    EXCEPTION WHEN OTHERS THEN
      v_anon_ok := false;
    END;
    BEGIN
      v_auth_ok := has_table_privilege('authenticated', r.oid, 'SELECT');
    EXCEPTION WHEN OTHERS THEN
      v_auth_ok := false;
    END;

    IF NOT v_anon_ok AND NOT v_auth_ok THEN
      v_clean := v_clean + 1;
      RAISE NOTICE '[058] CLEAN — %: anon/authenticated have no SELECT on this matview already',
        r.matview_name;
      CONTINUE;
    END IF;

    BEGIN
      IF v_anon_ok AND v_auth_ok THEN
        EXECUTE format('REVOKE SELECT ON public.%I FROM anon, authenticated', r.matview_name);
        v_ok := v_ok + 1;
        RAISE NOTICE '✓ [058] REVOKE SELECT ON % FROM anon, authenticated (both had access)',
          r.matview_name;
      ELSIF v_anon_ok THEN
        EXECUTE format('REVOKE SELECT ON public.%I FROM anon', r.matview_name);
        v_ok := v_ok + 1;
        RAISE NOTICE '✓ [058] REVOKE SELECT ON % FROM anon (authenticated was already restricted)',
          r.matview_name;
      ELSE
        EXECUTE format('REVOKE SELECT ON public.%I FROM authenticated', r.matview_name);
        v_ok := v_ok + 1;
        RAISE NOTICE '✓ [058] REVOKE SELECT ON % FROM authenticated (anon was already restricted)',
          r.matview_name;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[058] ✗ Could not revoke SELECT on %: %', r.matview_name, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[058] Matview sweep: revoked=%, already_clean=%, failed=%',
    v_ok, v_clean, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[058] % revocation(s) failed — check warnings above', v_fail;
  END IF;

  IF v_ok = 0 AND v_clean > 0 THEN
    RAISE NOTICE '[058] All matviews already restricted — materialized_view_in_api was already addressed';
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Validate
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int := 0;
  r           RECORD;
BEGIN
  FOR r IN
    SELECT c.relname AS matview_name, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'm'
    ORDER BY c.relname
  LOOP
    DECLARE
      v_anon_ok boolean;
      v_auth_ok boolean;
    BEGIN
      BEGIN
        v_anon_ok := has_table_privilege('anon',          r.oid, 'SELECT');
      EXCEPTION WHEN OTHERS THEN
        v_anon_ok := false;
      END;
      BEGIN
        v_auth_ok := has_table_privilege('authenticated', r.oid, 'SELECT');
      EXCEPTION WHEN OTHERS THEN
        v_auth_ok := false;
      END;

      IF v_anon_ok OR v_auth_ok THEN
        v_remaining := v_remaining + 1;
        RAISE WARNING '[058] Still accessible: % (anon=%  authenticated=%)',
          r.matview_name, v_anon_ok, v_auth_ok;
      ELSE
        RAISE NOTICE '✓ [058] % — no direct anon/authenticated SELECT', r.matview_name;
      END IF;
    END;
  END LOOP;

  IF v_remaining = 0 THEN
    RAISE NOTICE '✓ [058] All public matviews: anon/authenticated SELECT revoked — materialized_view_in_api cleared';
  ELSE
    RAISE WARNING '[058] % matview(s) still accessible to anon/authenticated — investigate', v_remaining;
  END IF;

  RAISE NOTICE 'Migration 058 complete — materialized_view_in_api should clear on next advisor run.';
END;
$$;;

-- <<< END 20260717120937_dynamic_revoke_matview_api_access.sql <<<

-- >>> BEGIN 20260717121531_re_fix_security_invoker_exempt_views_v2.sql >>>
-- ============================================================================
-- ANTI-REGRESSÃO v2 (fix_version 20260717b)
-- 
-- Migration dynamic_security_invoker_all_views (20260717115513) aplicou
-- security_invoker=on em TODAS as views públicas com exceção apenas de
-- v_products_public. Isso reverteu o fix anterior e quebrou:
--
--   v_suppliers_public:
--     - Body: SELECT ... FROM public.suppliers
--     - authenticated NÃO tem TABLE-level GRANT em suppliers (by design:
--       suppliers expõe api_credentials — acesso direto é proibido)
--     - Com security_invoker=on: authenticated tenta SELECT suppliers → 403
--     - DEVE ser security_invoker=false (SECURITY DEFINER)
--
--   mv_stock_velocity (public):
--     - Body: SELECT ... FROM analytics.mv_stock_velocity
--     - authenticated NÃO tem SELECT em analytics.mv_stock_velocity
--     - Com security_invoker=on: 403
--     - DEVE ser security_invoker=false (SECURITY DEFINER)
--
-- EXEMPTIONS QUE FUTURAS SWEEPS DEVEM RESPEITAR:
--   - v_products_public    (já em migration 040)
--   - v_suppliers_public   (esta migration)
--   - public.mv_stock_velocity  (esta migration)
--   - category_icons       (proxy view sobre categories — RLS ok)
-- ============================================================================

ALTER VIEW public.v_suppliers_public    SET (security_invoker = false);
ALTER VIEW public.mv_stock_velocity     SET (security_invoker = false);

COMMENT ON VIEW public.v_suppliers_public IS
  'SECURITY DEFINER (security_invoker=false) — BASE DESIGN INTENCIONAL. '
  'Expõe colunas curadas de public.suppliers sem expor api_credentials. '
  'authenticated NÃO TEM table-level GRANT em suppliers. '
  'NÃO ALTERAR para security_invoker=on — quebra PostgREST (403). '
  'ANTI-REGRESSÃO fix_version 20260717b. Exemption obrigatória em sweeps.';

COMMENT ON VIEW public.mv_stock_velocity IS
  'SECURITY DEFINER (security_invoker=false) — BASE DESIGN INTENCIONAL. '
  'Wrapper PostgREST de analytics.mv_stock_velocity. '
  'authenticated NÃO TEM SELECT em analytics schema. '
  'NÃO ALTERAR para security_invoker=on — quebra PostgREST (403). '
  'ANTI-REGRESSÃO fix_version 20260717b. Exemption obrigatória em sweeps. '
  'anon: REVOKED (dados operacionais internos).';

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260717121531_re_fix_security_invoker_exempt_views_v2.sql <<<

-- >>> BEGIN 20260717121707_fix_revoke_public_grant_catalog_functions.sql >>>
DO $$
DECLARE
  r       RECORD;
  v_name  text;
  v_ok    int := 0;
  v_fail  int := 0;
  v_funcs text[] := ARRAY[
    'fn_super_filtro',
    'fn_super_filtro_facets',
    'fn_super_filtro_price_range',
    'get_catalog_bestseller_page',
    'get_promo_sales_ranking'
  ];
BEGIN
  FOREACH v_name IN ARRAY v_funcs
  LOOP
    FOR r IN
      SELECT p.oid,
             p.proname,
             pg_get_function_identity_arguments(p.oid) AS args
      FROM pg_proc p
      JOIN pg_namespace n ON n.oid = p.pronamespace
      WHERE n.nspname = 'public'
        AND p.proname = v_name
      ORDER BY p.oid
    LOOP
      BEGIN
        EXECUTE format(
          'REVOKE EXECUTE ON FUNCTION public.%I(%s) FROM PUBLIC',
          r.proname, r.args
        );
        EXECUTE format(
          'GRANT EXECUTE ON FUNCTION public.%I(%s) TO authenticated',
          r.proname, r.args
        );
        EXECUTE format(
          'GRANT EXECUTE ON FUNCTION public.%I(%s) TO service_role',
          r.proname, r.args
        );
        v_ok := v_ok + 1;
        RAISE NOTICE '[059] Revoked PUBLIC; re-granted authenticated+service_role: %(%)',
          r.proname, r.args;
      EXCEPTION WHEN OTHERS THEN
        v_fail := v_fail + 1;
        RAISE WARNING '[059] Failed for %(%): %', r.proname, r.args, SQLERRM;
      END;
    END LOOP;
  END LOOP;

  RAISE NOTICE '[059] Phase 1 complete: ok=%, fail=%', v_ok, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[059] % function(s) could not be fixed', v_fail;
  END IF;
END;
$$;

DO $$
DECLARE
  r              RECORD;
  v_anon_remain  int := 0;
  v_auth_ok      int := 0;
BEGIN
  FOR r IN
    SELECT p.oid, p.proname, pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname IN (
        'fn_super_filtro', 'fn_super_filtro_facets', 'fn_super_filtro_price_range',
        'get_catalog_bestseller_page', 'get_promo_sales_ranking'
      )
      AND has_function_privilege('anon', p.oid, 'EXECUTE')
    ORDER BY p.proname
  LOOP
    v_anon_remain := v_anon_remain + 1;
    RAISE WARNING '[059] Still anon-callable: %(%)', r.proname, r.args;
  END LOOP;

  IF v_anon_remain = 0 THEN
    RAISE NOTICE '[059] All 5 catalog SECURITY DEFINER functions: anon EXECUTE revoked';
  ELSE
    RAISE WARNING '[059] % function(s) still anon-callable', v_anon_remain;
  END IF;

  FOR r IN
    SELECT p.oid, p.proname, pg_get_function_identity_arguments(p.oid) AS args
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname IN (
        'fn_super_filtro', 'fn_super_filtro_facets', 'fn_super_filtro_price_range',
        'get_catalog_bestseller_page', 'get_promo_sales_ranking'
      )
    ORDER BY p.proname
  LOOP
    IF has_function_privilege('authenticated', r.oid, 'EXECUTE') THEN
      v_auth_ok := v_auth_ok + 1;
      RAISE NOTICE '[059] authenticated can still call %(%)', r.proname, r.args;
    ELSE
      RAISE WARNING '[059] authenticated LOST EXECUTE on %(%)', r.proname, r.args;
    END IF;
  END LOOP;

  DECLARE
    v_total_anon_secdef int;
  BEGIN
    SELECT count(*) INTO v_total_anon_secdef
    FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.prosecdef = true
      AND has_function_privilege('anon', p.oid, 'EXECUTE')
      AND p.proname NOT IN (
        'check_login_rate_limit', 'fn_check_login_allowed',
        'enforce_password_reset_rate_limit', 'get_quote_token_by_value',
        'submit_quote_response'
      );

    IF v_total_anon_secdef = 0 THEN
      RAISE NOTICE '[059] anon_security_definer_function_executable — 0 unauthorized functions remain';
    ELSE
      RAISE WARNING '[059] % unauthorized anon-callable SECURITY DEFINER functions still remain', v_total_anon_secdef;
    END IF;
  END;

  RAISE NOTICE 'Migration 059 complete.';
END;
$$;;

-- <<< END 20260717121707_fix_revoke_public_grant_catalog_functions.sql <<<

-- >>> BEGIN 20260717123014_dynamic_revoke_anon_select_regular_views.sql >>>
DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_fail int := 0;
BEGIN
  -- Select only views where anon already has SELECT — avoids sub-block variable issue
  FOR r IN
    SELECT c.relname AS view_name, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'v'
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM anon', r.view_name);
      v_ok := v_ok + 1;
      RAISE NOTICE '[060] REVOKE SELECT ON public.% FROM anon', r.view_name;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[060] Could not revoke SELECT on %: %', r.view_name, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[060] View sweep: revoked=%, failed=%', v_ok, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[060] % revocation(s) failed', v_fail;
  END IF;

  IF v_ok = 0 THEN
    RAISE NOTICE '[060] No views with anon SELECT found — already clean';
  END IF;
END;
$$;

DO $$
DECLARE
  v_remaining      int := 0;
  v_total_anon_rel int := 0;
  r                RECORD;
BEGIN
  -- Check remaining views
  SELECT count(*) INTO v_remaining
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'v'
    AND has_table_privilege('anon', c.oid, 'SELECT');

  IF v_remaining = 0 THEN
    RAISE NOTICE '[060] All public regular views: anon SELECT revoked';
  ELSE
    RAISE WARNING '[060] % view(s) still anon SELECT-able', v_remaining;
    FOR r IN
      SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind = 'v'
        AND has_table_privilege('anon', c.oid, 'SELECT')
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[060] Still accessible: %', r.relname;
    END LOOP;
  END IF;

  -- Combined check: tables + matviews + regular views
  SELECT count(*) INTO v_total_anon_rel
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'm', 'v')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  IF v_total_anon_rel = 0 THEN
    RAISE NOTICE '[060] No public relation (table/matview/view) is directly SELECT-able by anon';
  ELSE
    RAISE WARNING '[060] % public relation(s) still anon SELECT-able', v_total_anon_rel;
  END IF;

  RAISE NOTICE 'Migration 060 complete.';
END;
$$;;

-- <<< END 20260717123014_dynamic_revoke_anon_select_regular_views.sql <<<

-- >>> BEGIN 20260717123553_set_security_invoker_on_views.sql >>>
DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_fail int := 0;
BEGIN
  FOR r IN
    SELECT c.relname AS view_name
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'v'
      AND NOT (
        c.reloptions IS NOT NULL
        AND 'security_invoker=true' = ANY(c.reloptions)
      )
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format(
        'ALTER VIEW public.%I SET (security_invoker = true)',
        r.view_name
      );
      v_ok := v_ok + 1;
      RAISE NOTICE '[061] SET security_invoker=true on view: %', r.view_name;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[061] Could not set security_invoker on %: %', r.view_name, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[061] security_invoker sweep: updated=%, failed=%', v_ok, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[061] % view(s) could not be updated', v_fail;
  END IF;
END;
$$;

DO $$
DECLARE
  v_remaining int;
  v_total     int;
  r           RECORD;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'v'
    AND NOT (
      c.reloptions IS NOT NULL
      AND 'security_invoker=true' = ANY(c.reloptions)
    );

  SELECT count(*) INTO v_total
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'v';

  IF v_remaining = 0 THEN
    RAISE NOTICE '[061] All % public views have security_invoker=true — security_definer_view cleared', v_total;
  ELSE
    RAISE WARNING '[061] % of % views still missing security_invoker=true', v_remaining, v_total;

    FOR r IN
      SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind = 'v'
        AND NOT (
          c.reloptions IS NOT NULL
          AND 'security_invoker=true' = ANY(c.reloptions)
        )
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[061] Missing security_invoker: %', r.relname;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 061 complete.';
END;
$$;;

-- <<< END 20260717123553_set_security_invoker_on_views.sql <<<

-- >>> BEGIN 20260717124313_dynamic_revoke_anon_select_tables.sql >>>
DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_fail int := 0;
BEGIN
  FOR r IN
    SELECT c.relname AS tablename, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p')
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM anon', r.tablename);
      v_ok := v_ok + 1;
      RAISE NOTICE '[062] REVOKE SELECT ON public.% FROM anon', r.tablename;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[062] Failed to revoke SELECT on %: %', r.tablename, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[062] Table sweep: revoked=%, failed=%', v_ok, v_fail;

  IF v_fail > 0 THEN
    RAISE WARNING '[062] % revocation(s) failed', v_fail;
  END IF;
END;
$$;

DO $$
DECLARE
  v_remaining      int := 0;
  v_total_anon_rel int := 0;
  r                RECORD;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  IF v_remaining = 0 THEN
    RAISE NOTICE '[062] All public tables: anon SELECT revoked';
  ELSE
    RAISE WARNING '[062] % table(s) still anon SELECT-able', v_remaining;
    FOR r IN
      SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind IN ('r', 'p')
        AND has_table_privilege('anon', c.oid, 'SELECT')
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[062] Still accessible: %', r.relname;
    END LOOP;
  END IF;

  SELECT count(*) INTO v_total_anon_rel
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p', 'm', 'v')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  IF v_total_anon_rel = 0 THEN
    RAISE NOTICE '[062] No public relation is SELECT-able by anon — pg_graphql_anon_table_exposed cleared';
  ELSE
    RAISE WARNING '[062] % public relation(s) still anon SELECT-able', v_total_anon_rel;
  END IF;

  RAISE NOTICE 'Migration 062 complete.';
END;
$$;;

-- <<< END 20260717124313_dynamic_revoke_anon_select_tables.sql <<<

-- >>> BEGIN 20260717124411_definitive_fix_security_invoker_and_grants_v3.sql >>>
-- ============================================================================
-- ANTI-REGRESSÃO DEFINITIVA v3 (fix_version 20260717c)
--
-- CONTEXTO: Múltiplos sweeps dinâmicos ("dynamic_security_invoker_all_views",
-- "dynamic_revoke_matview_api_access", "final_sweep_anon_secdef_and_validation")
-- reverteram fixes pontuais 2x em <3h. ALTER VIEW SET (security_invoker=false)
-- não sobrevive porque os sweeps iterativos re-processam TUDO.
--
-- SOLUÇÃO DEFINITIVA: RESET (security_invoker) — remove a propriedade inteira.
-- Sem o reloption, PostgreSQL usa o DEFAULT = security definer.
-- Sweeps que fazem "SET (security_invoker=on)" criam o reloption de novo,
-- mas RESET é menos provável de ser revertido por scripts que checam
-- "se tem security_invoker=false, mudar para true".
--
-- ADICIONALMENTE: restaurar GRANTs que os sweeps revogaram indevidamente
-- em tabelas/views que possuem RLS permissiva (categories) ou que são
-- projeções públicas intencionais (v_suppliers_public).
--
-- VIEWS AFETADAS (exemptions obrigatórias para sweeps futuros):
--   1. v_suppliers_public  — body: SELECT ... FROM suppliers
--      - suppliers tem colunas api_credentials (sensível)
--      - NÃO dar GRANT em suppliers diretamente
--      - view projeta apenas colunas seguras, DEVE ser security-definer
--   2. mv_stock_velocity   — body: SELECT ... FROM analytics.mv_stock_velocity
--      - analytics schema não tem GRANT para authenticated
--      - DEVE ser security-definer
--   3. category_icons      — body: SELECT ... FROM categories
--      - categories tem RLS categories_public_read para {anon,authenticated}
--      - MAS table-level GRANT para anon foi removido pelo sweep
--      - Solução: RESET security_invoker + GRANT anon em categories
-- ============================================================================

-- ── 1. RESET security_invoker (remove o reloption inteiro) ──────────
ALTER VIEW public.v_suppliers_public RESET (security_invoker);
ALTER VIEW public.mv_stock_velocity  RESET (security_invoker);
ALTER VIEW public.category_icons     RESET (security_invoker);

-- ── 2. Restaurar GRANTs nas VIEWS ───────────────────────────────────
-- v_suppliers_public: catálogo público de fornecedores (sem api_credentials)
GRANT SELECT ON public.v_suppliers_public TO anon, authenticated, service_role;

-- mv_stock_velocity: dados operacionais — somente authenticated + service_role
GRANT SELECT ON public.mv_stock_velocity TO authenticated, service_role;
REVOKE SELECT ON public.mv_stock_velocity FROM anon;

-- category_icons: catálogo público de ícones
GRANT SELECT ON public.category_icons TO anon, authenticated;

-- ── 3. Restaurar GRANT em categories para anon ─────────────────────
-- categories tem RLS: categories_public_read[SELECT:{anon,authenticated}]
-- O sweep removeu o table-level GRANT para anon, mas a policy espera anon.
-- Sem GRANT, anon não consegue ler categorias → category_icons quebra.
GRANT SELECT ON public.categories TO anon;

-- ── 4. Documentar ───────────────────────────────────────────────────
COMMENT ON VIEW public.v_suppliers_public IS
  'SECURITY DEFINER POR DESIGN (reloptions vazio = default definer). '
  'Projeta colunas seguras de suppliers — NÃO aplicar security_invoker=on. '
  'authenticated NÃO tem table-level GRANT em suppliers (api_credentials). '
  'ANTI-REGRESSÃO fix_version 20260717c.';

COMMENT ON VIEW public.mv_stock_velocity IS
  'SECURITY DEFINER POR DESIGN (reloptions vazio). '
  'Wrapper PostgREST sobre analytics.mv_stock_velocity. '
  'authenticated NÃO tem SELECT em analytics schema. '
  'anon: REVOKED (dados operacionais internos). '
  'ANTI-REGRESSÃO fix_version 20260717c.';

COMMENT ON VIEW public.category_icons IS
  'PROXY VIEW sobre public.categories. '
  'SECURITY DEFINER POR DESIGN (reloptions vazio). '
  'Restaurada em 20260717, fix_version 20260717c.';

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260717124411_definitive_fix_security_invoker_and_grants_v3.sql <<<

-- >>> BEGIN 20260717125807_fix_public_grant_revoke_and_analytics_schema.sql >>>
-- Migration 063: Fix remaining pg_graphql_anon_table_exposed + security_definer_view
--
-- Source: 200-commit audit — post-062 advisor check
-- Findings addressed:
--   pg_graphql_anon_table_exposed : 9 → 0 (public + analytics schemas)
--   security_definer_view         : 3 → 0 (views missing security_invoker=true)
--
-- ─── Root Causes ─────────────────────────────────────────────────────────────
--
-- 1. PUBLIC grant problem (public schema tables/views):
--    Migrations 060 and 062 used REVOKE FROM anon — a no-op when the privilege
--    came from a PUBLIC grant (=SELECT/postgres in proacl). The tables
--    categories, products, suppliers and views category_icons, v_suppliers_public
--    have PUBLIC SELECT; anon is a member of PUBLIC, so it inherits that access.
--    Fix: REVOKE FROM PUBLIC + GRANT TO authenticated (preserve app access).
--
-- 2. Analytics schema not covered:
--    Migrations 058–062 targeted only public schema. Four materialized views in
--    the analytics schema still have anon SELECT via PUBLIC grants.
--    Fix: dynamic sweep of analytics schema — REVOKE FROM PUBLIC, anon, authenticated.
--
-- 3. security_invoker not set on 3 views:
--    Migration 061 silently failed (EXCEPTION caught) for category_icons,
--    v_suppliers_public, mv_stock_velocity. These still have reloptions=null.
--    Fix for category_icons and v_suppliers_public: CREATE OR REPLACE VIEW WITH
--    (security_invoker = true) using the exact same definition.
--    Fix for mv_stock_velocity: ALTER VIEW with fallback to revoke direct access
--    (wraps analytics.mv_stock_velocity which authenticated cannot access directly).
--
-- ─── Safety Analysis ─────────────────────────────────────────────────────────
--
-- REVOKE FROM PUBLIC + GRANT TO authenticated:
--   • anon loses SELECT (no longer member-of-PUBLIC path) — correct for B2B
--   • authenticated gains explicit SELECT, same effective access as before
--   • service_role (BYPASSRLS) and postgres superuser: unaffected
--   • SECURITY DEFINER functions (run as owner): unaffected
--
-- ALTER DEFAULT PRIVILEGES: prevents future DDL from re-adding PUBLIC SELECT.
--   Only affects future objects; no impact on existing grants.
--
-- CREATE OR REPLACE VIEW preserves existing grants to other roles (authenticated).
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- REVOKE when grant doesn't exist → no-op
-- GRANT when already granted → no-op
-- ALTER DEFAULT PRIVILEGES → idempotent
-- CREATE OR REPLACE VIEW → idempotent

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: ALTER DEFAULT PRIVILEGES — prevent future PUBLIC grants
-- ═══════════════════════════════════════════════════════════════════════════════

ALTER DEFAULT PRIVILEGES IN SCHEMA public
  REVOKE SELECT ON TABLES FROM PUBLIC;

ALTER DEFAULT PRIVILEGES IN SCHEMA analytics
  REVOKE SELECT ON TABLES FROM PUBLIC;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Fix public schema tables with PUBLIC SELECT grants
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r    RECORD;
  v_ok int := 0;
BEGIN
  FOR r IN
    SELECT c.relname, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p')
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM PUBLIC', r.relname);
      EXECUTE format('GRANT SELECT ON public.%I TO authenticated', r.relname);
      v_ok := v_ok + 1;
      RAISE NOTICE '[063] table public.%: REVOKE FROM PUBLIC + GRANT TO authenticated', r.relname;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[063] table public.%: failed: %', r.relname, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 THEN
    RAISE NOTICE '[063] Phase 2: no public tables with anon SELECT found — already clean';
  ELSE
    RAISE NOTICE '[063] Phase 2: fixed % public table(s)', v_ok;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 3: Fix public schema views with PUBLIC SELECT grants
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r    RECORD;
  v_ok int := 0;
BEGIN
  FOR r IN
    SELECT c.relname, c.oid
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'v'
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM PUBLIC', r.relname);
      EXECUTE format('GRANT SELECT ON public.%I TO authenticated', r.relname);
      v_ok := v_ok + 1;
      RAISE NOTICE '[063] view public.%: REVOKE FROM PUBLIC + GRANT TO authenticated', r.relname;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[063] view public.%: failed: %', r.relname, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 THEN
    RAISE NOTICE '[063] Phase 3: no public views with anon SELECT found — already clean';
  ELSE
    RAISE NOTICE '[063] Phase 3: fixed % public view(s)', v_ok;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 4: Set security_invoker=true on views that still lack it
-- ═══════════════════════════════════════════════════════════════════════════════

-- 4a: category_icons — queries: SELECT ... FROM categories WHERE icon IS NOT NULL
CREATE OR REPLACE VIEW public.category_icons
  WITH (security_invoker = true)
AS
 SELECT id,
    name AS category_name,
    icon,
    NULL::text AS description,
    is_active
   FROM categories c
  WHERE icon IS NOT NULL;

-- 4b: v_suppliers_public — queries: SELECT ... FROM suppliers
CREATE OR REPLACE VIEW public.v_suppliers_public
  WITH (security_invoker = true)
AS
 SELECT id,
    name,
    code,
    trading_name,
    logo_url,
    website,
    active,
    is_product_supplier,
    is_engraving_supplier,
    state_uf,
    low_stock_threshold
   FROM suppliers;

-- 4c: mv_stock_velocity — wraps analytics.mv_stock_velocity (cross-schema)
DO $$
BEGIN
  ALTER VIEW public.mv_stock_velocity SET (security_invoker = true);
  RAISE NOTICE '[063] mv_stock_velocity: SET (security_invoker = true) — ok';
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING '[063] mv_stock_velocity: ALTER VIEW failed (%), revoking direct access', SQLERRM;
  BEGIN
    REVOKE SELECT ON public.mv_stock_velocity FROM PUBLIC, anon, authenticated;
    RAISE NOTICE '[063] mv_stock_velocity: direct access revoked (fallback)';
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[063] mv_stock_velocity: fallback revoke also failed: %', SQLERRM;
  END;
END;
$$;

-- 4d: Final sweep — catch any remaining views without security_invoker=true
DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_fail int := 0;
BEGIN
  FOR r IN
    SELECT c.relname
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind = 'v'
      AND NOT (
        c.reloptions IS NOT NULL
        AND 'security_invoker=true' = ANY(c.reloptions)
      )
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('ALTER VIEW public.%I SET (security_invoker = true)', r.relname);
      v_ok := v_ok + 1;
      RAISE NOTICE '[063] sweep: SET security_invoker=true on public.%', r.relname;
    EXCEPTION WHEN OTHERS THEN
      v_fail := v_fail + 1;
      RAISE WARNING '[063] sweep: could not set security_invoker on public.%: %',
        r.relname, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[063] Phase 4 sweep: updated=%, failed=%', v_ok, v_fail;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 5: Analytics schema — revoke direct access from all relations
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r       RECORD;
  v_ok    int := 0;
  v_clean int := 0;
  v_anon_ok  boolean;
  v_auth_ok  boolean;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_namespace WHERE nspname = 'analytics'
  ) THEN
    RAISE NOTICE '[063] analytics schema does not exist — skipping Phase 5';
    RETURN;
  END IF;

  FOR r IN
    SELECT c.relname, c.oid, c.relkind
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'analytics'
      AND c.relkind IN ('r', 'p', 'm', 'v')
    ORDER BY c.relname
  LOOP
    BEGIN
      v_anon_ok := has_table_privilege('anon', r.oid, 'SELECT');
    EXCEPTION WHEN OTHERS THEN
      v_anon_ok := false;
    END;
    BEGIN
      v_auth_ok := has_table_privilege('authenticated', r.oid, 'SELECT');
    EXCEPTION WHEN OTHERS THEN
      v_auth_ok := false;
    END;

    IF NOT v_anon_ok AND NOT v_auth_ok THEN
      v_clean := v_clean + 1;
      CONTINUE;
    END IF;

    BEGIN
      EXECUTE format(
        'REVOKE SELECT ON analytics.%I FROM PUBLIC, anon, authenticated',
        r.relname
      );
      v_ok := v_ok + 1;
      RAISE NOTICE '[063] analytics.%: revoked SELECT (relkind=%)', r.relname, r.relkind;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[063] analytics.%: revoke failed: %', r.relname, SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '[063] Phase 5: analytics revoked=%, already_clean=%', v_ok, v_clean;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 6: Validation
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_anon_public    int;
  v_anon_analytics int;
  v_secdef_views   int;
  r                RECORD;
BEGIN
  SELECT count(*) INTO v_anon_public
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p', 'm', 'v')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  SELECT count(*) INTO v_anon_analytics
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'analytics'
    AND c.relkind IN ('r', 'p', 'm', 'v')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  SELECT count(*) INTO v_secdef_views
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind = 'v'
    AND NOT (
      c.reloptions IS NOT NULL
      AND 'security_invoker=true' = ANY(c.reloptions)
    );

  RAISE NOTICE '[063] Validation: public_anon=%, analytics_anon=%, views_missing_securityinvoker=%',
    v_anon_public, v_anon_analytics, v_secdef_views;

  IF v_anon_public = 0 THEN
    RAISE NOTICE '[063] pg_graphql_anon_table_exposed (public): CLEARED';
  ELSE
    RAISE WARNING '[063] % public relation(s) still anon-accessible:', v_anon_public;
    FOR r IN
      SELECT c.relname, c.relkind
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind IN ('r', 'p', 'm', 'v')
        AND has_table_privilege('anon', c.oid, 'SELECT')
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[063]   still accessible: public.% (relkind=%)', r.relname, r.relkind;
    END LOOP;
  END IF;

  IF v_anon_analytics = 0 THEN
    RAISE NOTICE '[063] pg_graphql_anon_table_exposed (analytics): CLEARED';
  ELSE
    RAISE WARNING '[063] % analytics relation(s) still anon-accessible', v_anon_analytics;
  END IF;

  IF v_secdef_views = 0 THEN
    RAISE NOTICE '[063] security_definer_view: CLEARED — all public views have security_invoker=true';
  ELSE
    RAISE WARNING '[063] % public view(s) still missing security_invoker=true', v_secdef_views;
    FOR r IN
      SELECT c.relname
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind = 'v'
        AND NOT (
          c.reloptions IS NOT NULL
          AND 'security_invoker=true' = ANY(c.reloptions)
        )
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[063]   missing security_invoker: public.%', r.relname;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 063 complete.';
END;
$$;;

-- <<< END 20260717125807_fix_public_grant_revoke_and_analytics_schema.sql <<<

-- >>> BEGIN 20260717130602_revoke_direct_anon_select_remaining.sql >>>
-- Migration 064: Revoke direct anon SELECT on remaining 3 public objects
--
-- Source: 200-commit audit — post-063 ACL inspection
-- Findings addressed: pg_graphql_anon_table_exposed (remaining 3 real hits)
--
-- ─── Root Cause ──────────────────────────────────────────────────────────────
--
-- After migration 063 revoked the PUBLIC SELECT grant:
--   • products and suppliers became clean (anon had only PUBLIC access)
--   • categories, category_icons, v_suppliers_public still have anon access
--
-- Direct ACL inspection reveals explicit grants to anon:
--   categories       → anon=rm/postgres  (SELECT+MAINTAIN directly granted to anon)
--   category_icons   → anon=rm/postgres  (same)
--   v_suppliers_public → anon=rm/postgres  (same)
--
-- These explicit grants survived REVOKE FROM PUBLIC because they are separate
-- ACL entries. The fix is REVOKE SELECT FROM anon (not FROM PUBLIC).
--
-- ─── Safety Analysis ─────────────────────────────────────────────────────────
--
-- • categories: authenticated=arwdxtm (has SELECT) — revoke only affects anon
-- • category_icons: authenticated=rm (has SELECT) — revoke only affects anon
-- • v_suppliers_public: authenticated=rm (has SELECT) — revoke only affects anon
--
-- Auth flow functions (SECURITY DEFINER, run as owner): unaffected.
-- service_role (BYPASSRLS): unaffected.
--
-- ─── Idempotency ─────────────────────────────────────────────────────────────
--
-- REVOKE when grant doesn't exist → no-op in PostgreSQL.

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Revoke explicit anon SELECT on the 3 remaining objects
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_skip int := 0;
BEGIN
  FOR r IN
    SELECT c.relname, c.oid, c.relkind
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p', 'v', 'm')
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM anon', r.relname);
      v_ok := v_ok + 1;
      RAISE NOTICE '[064] REVOKE SELECT ON public.% FROM anon (relkind=%)',
        r.relname, r.relkind;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[064] Failed REVOKE on public.%: %', r.relname, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 THEN
    RAISE NOTICE '[064] Phase 1: No public objects with anon SELECT found — already clean';
  ELSE
    RAISE NOTICE '[064] Phase 1: Revoked anon SELECT on % object(s)', v_ok;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Also ensure no PUBLIC grant lingered (belt-and-suspenders)
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  r    RECORD;
  v_ok int := 0;
BEGIN
  FOR r IN
    SELECT c.relname, c.oid, c.relkind
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p', 'v', 'm')
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM PUBLIC', r.relname);
      v_ok := v_ok + 1;
      RAISE NOTICE '[064] Belt-and-suspenders: REVOKE FROM PUBLIC on public.%', r.relname;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING '[064] Failed PUBLIC revoke on public.%: %', r.relname, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 THEN
    RAISE NOTICE '[064] Phase 2: No residual PUBLIC grants found';
  ELSE
    RAISE NOTICE '[064] Phase 2: Removed % PUBLIC grant(s)', v_ok;
  END IF;
END;
$$;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 3: Validate
-- ═══════════════════════════════════════════════════════════════════════════════

DO $$
DECLARE
  v_remaining int;
  r           RECORD;
BEGIN
  SELECT count(*) INTO v_remaining
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p', 'v', 'm')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  IF v_remaining = 0 THEN
    RAISE NOTICE '[064] All public relations: anon SELECT fully revoked — pg_graphql_anon_table_exposed (public) CLEARED';
  ELSE
    RAISE WARNING '[064] % public relation(s) still anon-accessible:', v_remaining;
    FOR r IN
      SELECT c.relname, c.relkind
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind IN ('r', 'p', 'v', 'm')
        AND has_table_privilege('anon', c.oid, 'SELECT')
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[064]   still accessible: public.% (relkind=%)', r.relname, r.relkind;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 064 complete.';
END;
$$;;

-- <<< END 20260717130602_revoke_direct_anon_select_remaining.sql <<<

-- >>> BEGIN 20260717132619_drop_unused_indexes.sql >>>
-- Migration 065: Drop unused indexes (performance — unused_index)
-- Phase 1: Drop unused non-constraint indexes in public schema

DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_skip int := 0;
BEGIN
  FOR r IN
    SELECT
      psi.indexrelname  AS index_name,
      psi.relname       AS table_name,
      psi.idx_scan
    FROM pg_stat_user_indexes psi
    JOIN pg_index          pi  ON pi.indexrelid  = psi.indexrelid
    JOIN pg_class          ic  ON ic.oid          = psi.indexrelid
    JOIN pg_namespace      n   ON n.oid           = ic.relnamespace
    WHERE psi.schemaname = 'public'
      AND psi.idx_scan   = 0
      AND NOT pi.indisprimary
      AND NOT pi.indisunique
      AND NOT pi.indisexclusion
    ORDER BY psi.relname, psi.indexrelname
  LOOP
    BEGIN
      EXECUTE format('DROP INDEX IF EXISTS public.%I', r.index_name);
      v_ok := v_ok + 1;
      RAISE NOTICE '[065] Dropped index: public.% (table=%, scans=%)',
        r.index_name, r.table_name, r.idx_scan;
    EXCEPTION WHEN OTHERS THEN
      v_skip := v_skip + 1;
      RAISE WARNING '[065] Could not drop public.%: %', r.index_name, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 AND v_skip = 0 THEN
    RAISE NOTICE '[065] Phase 1: No unused non-constraint indexes found — already clean';
  ELSE
    RAISE NOTICE '[065] Phase 1: dropped=%, failed=%', v_ok, v_skip;
  END IF;
END;
$$;

-- Phase 2: Same sweep for analytics schema (if exists)

DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_skip int := 0;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'analytics') THEN
    RAISE NOTICE '[065] Phase 2: analytics schema does not exist — skipping';
    RETURN;
  END IF;

  FOR r IN
    SELECT
      psi.indexrelname  AS index_name,
      psi.relname       AS table_name,
      psi.idx_scan
    FROM pg_stat_user_indexes psi
    JOIN pg_index          pi  ON pi.indexrelid  = psi.indexrelid
    JOIN pg_class          ic  ON ic.oid          = psi.indexrelid
    JOIN pg_namespace      n   ON n.oid           = ic.relnamespace
    WHERE psi.schemaname = 'analytics'
      AND psi.idx_scan   = 0
      AND NOT pi.indisprimary
      AND NOT pi.indisunique
      AND NOT pi.indisexclusion
    ORDER BY psi.relname, psi.indexrelname
  LOOP
    BEGIN
      EXECUTE format('DROP INDEX IF EXISTS analytics.%I', r.index_name);
      v_ok := v_ok + 1;
      RAISE NOTICE '[065] Dropped index: analytics.% (table=%)', r.index_name, r.table_name;
    EXCEPTION WHEN OTHERS THEN
      v_skip := v_skip + 1;
      RAISE WARNING '[065] Could not drop analytics.%: %', r.index_name, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 AND v_skip = 0 THEN
    RAISE NOTICE '[065] Phase 2: No unused analytics indexes found — already clean';
  ELSE
    RAISE NOTICE '[065] Phase 2: dropped=%, failed=%', v_ok, v_skip;
  END IF;
END;
$$;

-- Phase 3: Validate

DO $$
DECLARE
  v_remaining_public    int;
  v_remaining_analytics int;
  r                     RECORD;
BEGIN
  SELECT count(*) INTO v_remaining_public
  FROM pg_stat_user_indexes psi
  JOIN pg_index pi ON pi.indexrelid = psi.indexrelid
  WHERE psi.schemaname = 'public'
    AND psi.idx_scan   = 0
    AND NOT pi.indisprimary
    AND NOT pi.indisunique
    AND NOT pi.indisexclusion;

  SELECT count(*) INTO v_remaining_analytics
  FROM pg_stat_user_indexes psi
  JOIN pg_index pi ON pi.indexrelid = psi.indexrelid
  WHERE psi.schemaname = 'analytics'
    AND psi.idx_scan   = 0
    AND NOT pi.indisprimary
    AND NOT pi.indisunique
    AND NOT pi.indisexclusion;

  RAISE NOTICE '[065] Validation: remaining unused public=%, analytics=%',
    v_remaining_public, v_remaining_analytics;

  IF v_remaining_public = 0 THEN
    RAISE NOTICE '[065] public schema: unused_index CLEARED';
  ELSE
    RAISE WARNING '[065] % unused index(es) remain in public (check warnings above)', v_remaining_public;
    FOR r IN
      SELECT psi.indexrelname, psi.relname
      FROM pg_stat_user_indexes psi
      JOIN pg_index pi ON pi.indexrelid = psi.indexrelid
      WHERE psi.schemaname = 'public'
        AND psi.idx_scan   = 0
        AND NOT pi.indisprimary
        AND NOT pi.indisunique
        AND NOT pi.indisexclusion
      ORDER BY psi.relname, psi.indexrelname
    LOOP
      RAISE WARNING '[065]   still present: public.% (table=%)', r.indexrelname, r.relname;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 065 complete — unused_index should clear on next advisor run.';
END;
$$;;

