-- >>> BEGIN 20260717135935_revoke_anon_remaining_41_tables.sql >>>

DO $$
DECLARE
  r      RECORD;
  v_ok   int := 0;
  v_skip int := 0;
BEGIN
  FOR r IN
    SELECT c.relname, c.oid, c.relkind
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public'
      AND c.relkind IN ('r', 'p', 'v', 'm')
      AND has_table_privilege('anon', c.oid, 'SELECT')
    ORDER BY c.relname
  LOOP
    BEGIN
      EXECUTE format('REVOKE SELECT ON public.%I FROM PUBLIC', r.relname);
      EXECUTE format('REVOKE SELECT ON public.%I FROM anon', r.relname);
      EXECUTE format('GRANT  SELECT ON public.%I TO authenticated', r.relname);
      v_ok := v_ok + 1;
      RAISE NOTICE '[069] Fixed public.% (relkind=%): revoked anon/PUBLIC, granted authenticated',
        r.relname, r.relkind;
    EXCEPTION WHEN OTHERS THEN
      v_skip := v_skip + 1;
      RAISE WARNING '[069] Failed on public.%: %', r.relname, SQLERRM;
    END;
  END LOOP;

  IF v_ok = 0 AND v_skip = 0 THEN
    RAISE NOTICE '[069] Phase 1: No anon-accessible public objects found — already clean';
  ELSE
    RAISE NOTICE '[069] Phase 1: fixed=%, failed=%', v_ok, v_skip;
  END IF;
END;
$$;

ALTER DEFAULT PRIVILEGES IN SCHEMA public
  REVOKE SELECT ON TABLES FROM PUBLIC;

ALTER DEFAULT PRIVILEGES IN SCHEMA public
  REVOKE SELECT ON TABLES FROM anon;

DO $$
DECLARE
  v_anon_count int;
  r            RECORD;
BEGIN
  SELECT count(*) INTO v_anon_count
  FROM pg_class c
  JOIN pg_namespace n ON n.oid = c.relnamespace
  WHERE n.nspname = 'public'
    AND c.relkind IN ('r', 'p', 'v', 'm')
    AND has_table_privilege('anon', c.oid, 'SELECT');

  IF v_anon_count = 0 THEN
    RAISE NOTICE '[069] pg_graphql_anon_table_exposed (public): CLEARED — 0 anon-accessible objects';
  ELSE
    RAISE WARNING '[069] % public object(s) still anon-accessible:', v_anon_count;
    FOR r IN
      SELECT c.relname, c.relkind
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public'
        AND c.relkind IN ('r', 'p', 'v', 'm')
        AND has_table_privilege('anon', c.oid, 'SELECT')
      ORDER BY c.relname
    LOOP
      RAISE WARNING '[069]   still accessible: public.% (relkind=%)', r.relname, r.relkind;
    END LOOP;
  END IF;

  RAISE NOTICE 'Migration 069 complete.';
END;
$$;
;

-- <<< END 20260717135935_revoke_anon_remaining_41_tables.sql <<<

-- >>> BEGIN 20260717141215_move_mv_product_leaf_category_to_internal.sql >>>
-- Migration 070: Move mv_product_leaf_category out of public schema
--
-- Source: 200-commit audit — post-069 security advisor
-- Findings addressed: materialized_view_in_api (1 → 0)

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 1: Create internal schema
-- ═══════════════════════════════════════════════════════════════════════════════

CREATE SCHEMA IF NOT EXISTS internal;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 2: Create MV in internal schema (same definition as public one)
-- ═══════════════════════════════════════════════════════════════════════════════

CREATE MATERIALIZED VIEW IF NOT EXISTS internal.mv_product_leaf_category AS
 SELECT DISTINCT ON (pca.product_id) pca.product_id,
    c.id AS leaf_category_id,
    c.name AS leaf_category_name,
    c.level AS leaf_category_level,
    c.parent_id AS leaf_category_parent_id,
    c.slug AS leaf_category_slug,
        CASE
            WHEN p.main_category_id IS NULL THEN c.id
            WHEN c.id = p.main_category_id THEN c.id
            WHEN (EXISTS ( SELECT 1
               FROM category_ancestors ca
              WHERE ca.descendant_id = c.id AND ca.ancestor_id = p.main_category_id)) THEN c.id
            ELSE NULL::uuid
        END AS leaf_category_id_safe
   FROM product_category_assignments pca
     JOIN categories c ON c.id = pca.category_id
     LEFT JOIN products p ON p.id = pca.product_id
  ORDER BY pca.product_id, c.level DESC NULLS LAST, pca.is_primary DESC NULLS LAST, pca.display_order, c.name;

-- ═══════════════════════════════════════════════════════════════════════════════
-- Phase 3: Recreate indexes on internal MV
-- ═══════════════════════════════════════════════════════════════════════════════

CREATE UNIQUE INDEX IF NOT EXISTS idx_mv_product_leaf_category_product_id
  ON internal.mv_product_leaf_category USING btree (product_id)
  INCLUDE (leaf_category_id, leaf_category_name, leaf_category_level, leaf_category_slug, leaf_category_id_safe);

