-- >>> BEGIN 20260717144444_grant_anon_variant_sale_prices_definer_v1.sql >>>
-- ============================================================================
-- fix_version: 20260717_grant_anon_variant_sale_prices_definer_v1
-- Item 3: expõe preços escalonados (min_qty -> sale_price) ao anon no detalhe de produto.
-- A view projeta APENAS preços finais (custo x markup calculado internamente); custo e
-- markup NUNCA saem como coluna. Tornada SECURITY DEFINER (security_invoker=false) de
-- PROPOSITO: lê variant_supplier_sources/markup_configurations (SENSIVEIS) como owner,
-- mantendo essas tabelas inacessiveis ao anon via REST. NAO conceder anon nessas bases.
-- ANTI-REGRESSAO: NAO reverter para security_invoker=true (quebraria ou vazaria custo).
--   Advisor 'security_definer_view' vai sinalizar esta view: e INTENCIONAL e documentado.
-- ============================================================================
ALTER VIEW public.v_variant_sale_prices_public SET (security_invoker = false);
GRANT SELECT ON public.v_variant_sale_prices_public TO anon;

COMMENT ON VIEW public.v_variant_sale_prices_public IS
  'PUBLIC PRICE PROJECTION (SECURITY DEFINER intencional / fix_version 20260717_v1). '
  'Emite apenas preco de venda por faixa de quantidade; custo/markup usados no calculo '
  'nunca sao expostos. Roda como owner para ler variant_supplier_sources/markup_configurations '
  'sem conceder essas tabelas sensiveis ao anon. NAO alterar para security_invoker=true.';

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260717144444_grant_anon_variant_sale_prices_definer_v1.sql <<<

-- >>> BEGIN 20260717144724_create_fn_verify_anon_catalog_grants_v1.sql >>>
-- ============================================================================
-- fix_version: 20260717_fn_verify_anon_catalog_grants_v1
-- Tripwire anti-regressão: valida o baseline de acesso anônimo do catálogo.
-- Retorna SOMENTE violações (0 linhas = saudável). Rodar manual ou via cron.
-- Cobre: grants obrigatórios (RPCs + tabelas/views + matviews cross-schema) e
--        travas obrigatórias (objetos sensíveis que NÃO podem ter acesso anon).
-- ============================================================================
CREATE OR REPLACE FUNCTION public.fn_verify_anon_catalog_grants()
RETURNS TABLE(object_name text, object_kind text, issue text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
BEGIN
  -- (1) Tabelas/Views que DEVEM ter anon SELECT
  RETURN QUERY
  WITH req(sch, nm) AS (VALUES
    ('public','products'),('public','suppliers'),('public','v_products_public'),('public','v_suppliers_public'),
    ('public','categories'),('public','collection_products'),('public','collections'),('public','color_groups'),
    ('public','color_synonym_map'),('public','color_variations'),('public','content_articles'),
    ('public','favorite_item_reactions'),('public','favorite_items'),('public','favorite_lists'),
    ('public','kit_typical_dims'),('public','material_types'),('public','mockup_approval_links'),
    ('public','print_area_techniques'),('public','product_ai_content'),('public','product_attributes'),
    ('public','product_badge_definitions'),('public','product_commemorative_dates'),('public','product_fiscal'),
    ('public','product_kit_components'),('public','product_materials'),('public','product_novelties'),
    ('public','product_physical'),('public','product_seo'),('public','product_supply'),('public','product_variants'),
    ('public','produto_ramo_atividade'),('public','ramo_atividade'),('public','ramo_atividade_filho'),
    ('public','spot_typecode_map'),('public','supplier_sub_brands'),('public','system_kill_switches'),
    ('public','tabela_preco_gravacao_oficial'),('public','tabela_preco_gravacao_oficial_faixa'),
    ('public','tecnicas_gravacao'),('public','video_sim_results'),
    ('public','color_nuances'),('public','kit_component_print_areas'),('public','personalization_techniques'),
    ('public','product_properties'),('public','tags'),('public','product_tags'),
    ('public','v_color_nuances_public'),('public','v_kit_component_media_public'),
    ('public','v_kit_component_print_areas_public'),('public','v_personalization_techniques_public'),
    ('public','v_print_area_techniques_public'),('public','v_product_compositions_public'),
    ('public','v_product_properties_public'),('public','v_product_tags_public'),('public','v_tags_public'),
    ('public','v_variant_sale_prices_public'),('public','mv_product_compositions'),
    ('internal','mv_product_leaf_category'),('analytics','mv_product_compositions')
  )
  SELECT req.sch||'.'||req.nm, 'table/view'::text, 'FALTA anon SELECT (read-path quebrado)'::text
  FROM req
  WHERE to_regclass(req.sch||'.'||req.nm) IS NULL
     OR NOT has_table_privilege('anon', (req.sch||'.'||req.nm)::regclass, 'SELECT');

  -- (2) Funções que DEVEM ter anon EXECUTE
  RETURN QUERY
  SELECT 'public.'||v.fn, 'function'::text, 'FALTA anon EXECUTE'::text
  FROM (VALUES ('fn_super_filtro'),('fn_super_filtro_facets'),('fn_super_filtro_price_range'),
               ('fn_global_search'),('get_catalog_bestseller_page')) v(fn)
  WHERE EXISTS (SELECT 1 FROM pg_proc WHERE proname=v.fn AND pronamespace='public'::regnamespace)
    AND NOT has_function_privilege('anon',
          (SELECT oid FROM pg_proc WHERE proname=v.fn AND pronamespace='public'::regnamespace LIMIT 1),'EXECUTE');

  -- (3) Tabelas SENSÍVEIS que NÃO podem ter acesso anon
  RETURN QUERY
  SELECT 'public.'||v.nm, 'table'::text, 'VAZAMENTO: anon tem SELECT em tabela sensível'::text
  FROM (VALUES ('variant_supplier_sources'),('markup_configurations'),('user_organizations'),
               ('quotes'),('quote_items')) v(nm)
  WHERE to_regclass('public.'||v.nm) IS NOT NULL
    AND has_table_privilege('anon', ('public.'||v.nm)::regclass, 'SELECT');

  -- (4) Função sensível que NÃO pode ter anon EXECUTE
  RETURN QUERY
  SELECT 'public.get_promo_sales_ranking', 'function'::text, 'VAZAMENTO: anon pode executar ranking de vendas'::text
  WHERE EXISTS (SELECT 1 FROM pg_proc WHERE proname='get_promo_sales_ranking' AND pronamespace='public'::regnamespace)
    AND has_function_privilege('anon',
          (SELECT oid FROM pg_proc WHERE proname='get_promo_sales_ranking' AND pronamespace='public'::regnamespace LIMIT 1),'EXECUTE');
END $fn$;

COMMENT ON FUNCTION public.fn_verify_anon_catalog_grants() IS
  'Tripwire anti-regressao do read-path anonimo do catalogo (fix_version 20260717_v1). '
  'Retorna somente violacoes; 0 linhas = saudavel. Rodar apos deploys/sweeps de advisor.';;

-- <<< END 20260717144724_create_fn_verify_anon_catalog_grants_v1.sql <<<

-- >>> BEGIN 20260717144811_schedule_anon_catalog_grant_audit_v1.sql >>>
-- ============================================================================
-- fix_version: 20260717_schedule_anon_catalog_grant_audit_v1
-- Auditoria automática do read-path anônimo (detecta regressão de bot/sweep).
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.anon_catalog_grant_audit_log (
  id              bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  checked_at      timestamptz NOT NULL DEFAULT now(),
  violation_count int         NOT NULL,
  violations      jsonb
);
ALTER TABLE public.anon_catalog_grant_audit_log ENABLE ROW LEVEL SECURITY;

CREATE OR REPLACE FUNCTION public.fn_anon_catalog_grant_audit_run()
RETURNS int
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
DECLARE v jsonb; c int;
BEGIN
  SELECT coalesce(jsonb_agg(to_jsonb(t)), '[]'::jsonb), count(*) INTO v, c
  FROM public.fn_verify_anon_catalog_grants() t;
  INSERT INTO public.anon_catalog_grant_audit_log(violation_count, violations)
  VALUES (c, CASE WHEN c > 0 THEN v ELSE NULL END);
  RETURN c;
END $fn$;

-- Agenda a cada 6h (remove agendamento anterior de mesmo nome se existir)
DO $sched$
BEGIN
  PERFORM cron.unschedule('anon-catalog-grant-audit-6h')
  WHERE EXISTS (SELECT 1 FROM cron.job WHERE jobname='anon-catalog-grant-audit-6h');
  PERFORM cron.schedule('anon-catalog-grant-audit-6h', '0 */6 * * *',
                        'SELECT public.fn_anon_catalog_grant_audit_run()');
END $sched$;;

-- <<< END 20260717144811_schedule_anon_catalog_grant_audit_v1.sql <<<

-- >>> BEGIN 20260717145632_fix_cron_and_fn_after_mv_move_to_internal.sql >>>
-- Migration 072: Fix cron job + fn_get_all_leaf_categories after MV moved to internal

DO $$
DECLARE
  v_job_id bigint;
  v_schedule text;
BEGIN
  SELECT jobid, schedule
  INTO v_job_id, v_schedule
  FROM cron.job
  WHERE jobname = 'refresh-mv-product-leaf-category';

  IF NOT FOUND THEN
    PERFORM cron.schedule(
      'refresh-mv-product-leaf-category',
      '37 */4 * * *',
      $cmd$SELECT public.fn_cron_safe_run(0::bigint, 'REFRESH MATERIALIZED VIEW CONCURRENTLY internal.mv_product_leaf_category;', 55000, 'mv-leaf-category');$cmd$
    );
    RAISE NOTICE '[072] Created new cron job for internal.mv_product_leaf_category';
    RETURN;
  END IF;

  PERFORM cron.unschedule(v_job_id);

  PERFORM cron.schedule(
    'refresh-mv-product-leaf-category',
    v_schedule,
    $cmd$SELECT public.fn_cron_safe_run(0::bigint, 'REFRESH MATERIALIZED VIEW CONCURRENTLY internal.mv_product_leaf_category;', 55000, 'mv-leaf-category');$cmd$
  );

  RAISE NOTICE '[072] Retargeted cron job refresh-mv-product-leaf-category → internal.mv_product_leaf_category (schedule: %)', v_schedule;
END;
$$;

CREATE OR REPLACE FUNCTION public.fn_get_all_leaf_categories()
RETURNS TABLE(
  product_id            uuid,
  leaf_category_id      uuid,
  leaf_category_name    text,
  leaf_category_level   integer,
  leaf_category_parent_id uuid,
  leaf_category_slug    text
)
LANGUAGE sql
SECURITY DEFINER
SET search_path TO 'public', 'internal'
AS $$
  SELECT
    product_id,
    leaf_category_id,
    leaf_category_name,
    leaf_category_level,
    leaf_category_parent_id,
    leaf_category_slug
  FROM internal.mv_product_leaf_category;
$$;

DO $$
DECLARE
  v_cron_cmd  text;
  v_fn_src    text;
BEGIN
  SELECT command INTO v_cron_cmd
  FROM cron.job
  WHERE jobname = 'refresh-mv-product-leaf-category';

  IF v_cron_cmd LIKE '%internal.mv_product_leaf_category%' THEN
    RAISE NOTICE '[072] ✓ cron job references internal.mv_product_leaf_category';
  ELSE
    RAISE WARNING '[072] ✗ cron job command unexpected: %', v_cron_cmd;
  END IF;

  SELECT pg_get_functiondef(oid) INTO v_fn_src
  FROM pg_proc
  WHERE pronamespace = 'public'::regnamespace AND proname = 'fn_get_all_leaf_categories';

  IF v_fn_src LIKE '%internal.mv_product_leaf_category%' THEN
    RAISE NOTICE '[072] ✓ fn_get_all_leaf_categories reads internal.mv_product_leaf_category';
  ELSE
    RAISE WARNING '[072] ✗ fn_get_all_leaf_categories body unexpected';
  END IF;

  RAISE NOTICE 'Migration 072 complete.';
END;
$$;;

-- <<< END 20260717145632_fix_cron_and_fn_after_mv_move_to_internal.sql <<<

-- >>> BEGIN 20260717151138_secure_anon_products_suppliers_definer_v1.sql >>>
-- ============================================================================
-- fix_version: 20260717_secure_anon_products_suppliers_definer_v1
-- CORREÇÃO CRÍTICA: products e suppliers tinham SELECT direto para anon,
-- expondo cost_price (R$0.19–R$826.42 reais) e api_credentials (3 fornecedores).
-- SOLUÇÃO: v_products_public e v_suppliers_public → SECURITY DEFINER (security_invoker=false).
-- As views já mascaram explicitamente: cost_price=NULL::numeric, api_credentials=ausente,
-- default_markup_percent=ausente, organization_id=NULL::uuid, created_by=NULL::uuid, etc.
-- Rodando como owner, anon só vê o output das views (colunas seguras).
-- Advisor 'security_definer_view' vai sinalizar estas views: INTENCIONAL e documentado.
-- ANTI-REGRESSAO: NAO reverter para security_invoker=true sem rever exposição de custo.
-- ============================================================================

-- (A) Converter views para SECURITY DEFINER
ALTER VIEW public.v_products_public  SET (security_invoker = false);
ALTER VIEW public.v_suppliers_public SET (security_invoker = false);

-- (B) Revogar SELECT direto nas tabelas base (anon usa SOMENTE as views)
REVOKE SELECT ON public.products  FROM anon;
REVOKE SELECT ON public.suppliers FROM anon;

-- (C) Documentar a decisão nas views
COMMENT ON VIEW public.v_products_public IS
  'PUBLIC PRODUCT PROJECTION (SECURITY DEFINER intencional / fix_version 20260717_v1). '
  'Mascara explicitamente cost_price=NULL, organization_id=NULL, created_by=NULL, etc. '
  'Roda como owner para ler products sem conceder acesso direto ao anon. '
  'NAO alterar para security_invoker=true (expoeria cost_price real ao anon via REST). '
  'Filter: is_active=true AND is_deleted IS NOT TRUE.';

COMMENT ON VIEW public.v_suppliers_public IS
  'PUBLIC SUPPLIER PROJECTION (SECURITY DEFINER intencional / fix_version 20260717_v1). '
  'Expoe apenas: id, name, code, trading_name, logo_url, website, active, flags, state_uf. '
  'Mascara: api_credentials, api_base_url, default_markup_percent, cnpj, email, phone, etc. '
  'NAO alterar para security_invoker=true (expoeria api_credentials ao anon via REST).';

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260717151138_secure_anon_products_suppliers_definer_v1.sql <<<

