  SELECT req.sch||'.'||req.nm, 'table/view'::text, 'FALTA anon SELECT'::text
  FROM req
  WHERE to_regclass(req.sch||'.'||req.nm) IS NULL
     OR NOT has_table_privilege('anon', (req.sch||'.'||req.nm)::regclass, 'SELECT');

  -- (2) Funções que DEVEM ter anon EXECUTE
  RETURN QUERY
  SELECT 'public.'||v.fn, 'function'::text, 'FALTA anon EXECUTE'::text
  FROM (VALUES ('fn_super_filtro'),('fn_super_filtro_facets'),('fn_super_filtro_price_range'),
               ('fn_global_search'),('get_catalog_bestseller_page')) v(fn)
  WHERE EXISTS (SELECT 1 FROM pg_proc WHERE proname=v.fn AND pronamespace='public'::regnamespace)
    AND NOT has_function_privilege('anon',
          (SELECT oid FROM pg_proc WHERE proname=v.fn AND pronamespace='public'::regnamespace LIMIT 1),'EXECUTE');

  -- (3) Tabelas/colunas SENSÍVEIS que NÃO podem ter acesso anon direto
  RETURN QUERY
  SELECT 'public.'||v.nm, 'table'::text, 'VAZAMENTO: anon tem SELECT direto em tabela sensível'::text
  FROM (VALUES ('variant_supplier_sources'),('markup_configurations'),('user_organizations'),
               ('quotes'),('quote_items'),
               -- NOVO: products e suppliers bloqueados (cost_price / api_credentials)
               ('products'),('suppliers')) v(nm)
  WHERE to_regclass('public.'||v.nm) IS NOT NULL
    AND has_table_privilege('anon', ('public.'||v.nm)::regclass, 'SELECT');

  -- (4) Funções sensíveis que NÃO devem ter anon EXECUTE
  RETURN QUERY
  SELECT 'public.get_promo_sales_ranking', 'function'::text, 'VAZAMENTO: anon executa ranking de vendas'::text
  WHERE EXISTS (SELECT 1 FROM pg_proc WHERE proname='get_promo_sales_ranking' AND pronamespace='public'::regnamespace)
    AND has_function_privilege('anon',
          (SELECT oid FROM pg_proc WHERE proname='get_promo_sales_ranking' AND pronamespace='public'::regnamespace LIMIT 1),'EXECUTE');

  -- (5) Views críticas devem ser SECURITY DEFINER (security_invoker=false)
  RETURN QUERY
  SELECT 'public.'||v.nm, 'view'::text, 'RISCO: view sensível voltou para security_invoker=true'::text
  FROM (VALUES ('v_products_public'),('v_suppliers_public'),
               ('v_variant_sale_prices_public')) v(nm)
  WHERE to_regclass('public.'||v.nm) IS NOT NULL
    AND COALESCE((SELECT option_value FROM pg_options_to_table(
        (SELECT reloptions FROM pg_class WHERE relname=v.nm AND relnamespace='public'::regnamespace))
      WHERE option_name='security_invoker'), 'false') = 'true';
END $fn$;

COMMENT ON FUNCTION public.fn_verify_anon_catalog_grants() IS
  'Tripwire anti-regressao v2 (fix_version 20260717). '
  'Cobre: grants anon obrigatórios, travas de sensíveis (products/suppliers/VSS/markup), '
  'RPCs seguros/bloqueados, e security_definer em views com custo/credenciais. '
  '0 linhas = saudável.';;

-- <<< END 20260717151231_update_fn_verify_anon_catalog_grants_v2.sql <<<

-- >>> BEGIN 20260717161443_secure_catalog_views_definer_v1.sql >>>
-- ============================================================================
-- fix_version: 20260717_secure_catalog_views_definer_v1
-- Converte para SECURITY DEFINER as 5 views _public que dependem de products
-- (v_kit_component_media, v_kit_component_print_areas, v_product_compositions,
--  v_product_properties, v_product_tags). Com security_invoker=true e products
-- revogado do anon, essas views quebravam. Com DEFINER, rodam como owner e lêem
-- products internamente (para filtro is_active) sem expor cost_price ao anon.
-- As colunas de output (kit media, print areas, compositions, properties, tags)
-- NÃO contêm dados financeiros ou operacionais sensíveis (confirmado por inspeção).
-- ANTI-REGRESSAO: NAO reverter para security_invoker=true sem rever dependência de products.
-- ============================================================================
ALTER VIEW public.v_kit_component_media_public       SET (security_invoker = false);
ALTER VIEW public.v_kit_component_print_areas_public SET (security_invoker = false);
ALTER VIEW public.v_product_compositions_public      SET (security_invoker = false);
ALTER VIEW public.v_product_properties_public        SET (security_invoker = false);
ALTER VIEW public.v_product_tags_public              SET (security_invoker = false);

COMMENT ON VIEW public.v_kit_component_media_public IS
  'SECURITY DEFINER intencional (fix_version 20260717). Depende de products para '
  'filtro is_active. Colunas de output: kit_component_id, component_code/name, primary_image_url.';
COMMENT ON VIEW public.v_kit_component_print_areas_public IS
  'SECURITY DEFINER intencional (fix_version 20260717). Colunas: áreas de impressão do kit.';
COMMENT ON VIEW public.v_product_compositions_public IS
  'SECURITY DEFINER intencional (fix_version 20260717). Depende de products e analytics.mv_product_compositions.';
COMMENT ON VIEW public.v_product_properties_public IS
  'SECURITY DEFINER intencional (fix_version 20260717). Colunas: property_code, property_value.';
COMMENT ON VIEW public.v_product_tags_public IS
  'SECURITY DEFINER intencional (fix_version 20260717). Colunas: product_id, tag_id.';

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260717161443_secure_catalog_views_definer_v1.sql <<<

-- >>> BEGIN 20260717161653_fix_rls_exists_products_definer_v1.sql >>>
-- ============================================================================
-- fix_version: 20260717_fix_rls_exists_products_definer_v1
-- As políticas anon em product_properties e product_tags usavam EXISTS no products.
-- Com products revogado do anon, o EXISTS falhava com 42501.
-- Solução: função helper SECURITY DEFINER que verifica atividade do produto.
-- A função roda como owner, lê products sem conceder SELECT ao anon.
-- ============================================================================

-- Helper SECURITY DEFINER para EXISTS checks em políticas RLS
CREATE OR REPLACE FUNCTION public.fn_product_active_for_rls(p_id uuid)
RETURNS boolean
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path TO 'public'
AS $$
  SELECT EXISTS(
    SELECT 1 FROM products
    WHERE id = p_id AND is_active = true AND is_deleted IS NOT TRUE
  );
$$;

COMMENT ON FUNCTION public.fn_product_active_for_rls(uuid) IS
  'Helper SECURITY DEFINER para políticas RLS anon (fix_version 20260717). '
  'Verifica se produto está ativo sem conceder SELECT direto em products ao anon. '
  'Usada em: product_properties_anon_read, product_tags_anon_read.';

-- Recriar as duas políticas usando a função helper
DROP POLICY IF EXISTS product_properties_anon_read ON public.product_properties;
CREATE POLICY product_properties_anon_read ON public.product_properties
  FOR SELECT TO anon
  USING (public.fn_product_active_for_rls(product_id));

DROP POLICY IF EXISTS product_tags_anon_read ON public.product_tags;
CREATE POLICY product_tags_anon_read ON public.product_tags
  FOR SELECT TO anon
  USING (public.fn_product_active_for_rls(product_id));;

-- <<< END 20260717161653_fix_rls_exists_products_definer_v1.sql <<<

-- >>> BEGIN 20260717161748_grant_anon_fn_product_active_rls_v1.sql >>>
-- fix_version: 20260717_grant_anon_fn_product_active_rls_v1
-- Anon precisa de EXECUTE em fn_product_active_for_rls para a RLS avaliá-la.
-- A função é SECURITY DEFINER: roda como owner, lê products internamente.
-- Conceder EXECUTE não expõe dados de products diretamente ao anon.
GRANT EXECUTE ON FUNCTION public.fn_product_active_for_rls(uuid) TO anon;;

-- <<< END 20260717161748_grant_anon_fn_product_active_rls_v1.sql <<<

-- >>> BEGIN 20260717172936_fix_product_variants_anon_policy_v1.sql >>>
-- ============================================================================
-- fix_version: 20260717_fix_product_variants_anon_policy_v1
-- MELHORIA 1/6: Elimina exposição de 202 variantes inativas ao anon.
-- A política product_variants_public_read tinha qual=true (TO anon,authenticated).
-- Nova estratégia: separar em duas políticas escopadas por role:
--   - anon: USING (is_active=true) — só variantes ativas
--   - authenticated: mantém true — gestão interna pode ver inativas
-- As 202 variantes inativas pertencem a produtos inativos (confirmado na simulação),
-- portanto a restrição é correta e não quebra nenhum fluxo legítimo.
-- ANTI-REGRESSAO: se bot reverter para qual=true, anon volta a ver variantes inativas.
-- ============================================================================

-- (A) Re-escopar política existente para authenticated apenas
ALTER POLICY product_variants_public_read ON public.product_variants TO authenticated;

-- (B) Nova política anon com filtro is_active
DROP POLICY IF EXISTS product_variants_anon_read ON public.product_variants;
CREATE POLICY product_variants_anon_read ON public.product_variants
  FOR SELECT TO anon
  USING (is_active = true);

COMMENT ON TABLE public.product_variants IS
  'Políticas RLS: product_variants_anon_read (is_active=true) + product_variants_public_read (authenticated, true). '
  'Separação fix_version 20260717 — anon não vê variantes inativas.';;

-- <<< END 20260717172936_fix_product_variants_anon_policy_v1.sql <<<

-- >>> BEGIN 20260717173228_fix_fn_super_filtro_null_stock_v1.sql >>>
-- ============================================================================
-- fix_version: 20260717_fix_fn_super_filtro_null_stock_v1
-- MELHORIA 2/6: Corrige bug SQL 3-valued logic em fn_super_filtro.
-- Bug: AND (NOT p_only_in_stock OR p.is_stockout=false)
--   com p_only_in_stock=NULL→NOT NULL=NULL→NULL OR FALSE=NULL→produto excluído.
--   1.395 produtos com is_stockout=true sumiam silenciosamente do catálogo padrão.
-- Fix: IS NOT TRUE — NULL IS NOT TRUE=TRUE (sem filtro), TRUE IS NOT TRUE=FALSE (só estoque).
-- ANTI-REGRESSAO: manter IS NOT TRUE; comentário explicativo no corpo.
-- ============================================================================

-- DROP+CREATE é necessário pois STABLE differe do original (que não tem STABLE declarado)
-- Preservar exatamente: DEFAULT values, tipos de retorno (brand character varying), search_path
DROP FUNCTION IF EXISTS public.fn_super_filtro(text,text,uuid,text[],boolean,numeric,numeric,text[],boolean,boolean,boolean,boolean,text[],text[],text[],text[],boolean,integer,integer,text);

CREATE OR REPLACE FUNCTION public.fn_super_filtro(
  p_search_term text DEFAULT NULL::text,
  p_category_slug text DEFAULT NULL::text,
  p_category_id uuid DEFAULT NULL::uuid,
  p_brands text[] DEFAULT NULL::text[],
  p_only_in_stock boolean DEFAULT false,
  p_min_price numeric DEFAULT NULL::numeric,
  p_max_price numeric DEFAULT NULL::numeric,
  p_target_audiences text[] DEFAULT NULL::text[],
  p_is_kit boolean DEFAULT NULL::boolean,
  p_is_textil boolean DEFAULT NULL::boolean,
  p_is_thermal boolean DEFAULT NULL::boolean,
  p_has_gift_box boolean DEFAULT NULL::boolean,
  p_material_groups text[] DEFAULT NULL::text[],
  p_technique_groups text[] DEFAULT NULL::text[],
  p_color_groups text[] DEFAULT NULL::text[],
  p_date_slugs text[] DEFAULT NULL::text[],
  p_endomarketing boolean DEFAULT NULL::boolean,
  p_limit integer DEFAULT 50,
  p_offset integer DEFAULT 0,
  p_sort text DEFAULT 'name_asc'::text
)
RETURNS TABLE(
  id uuid, name text, sku text, slug text, short_description text,
  brand character varying,   -- preservar tipo original
  sale_price numeric, cost_price numeric, min_quantity integer,
  stock_quantity integer, is_stockout boolean, is_kit boolean, is_textil boolean,
  is_thermal boolean, is_featured boolean, is_bestseller boolean, is_new boolean,
  has_gift_box boolean, target_audience text[], primary_image_url text,
  og_image_url text, set_image_url text, category_id uuid, category_name text,
  category_slug text, total_count bigint
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $fn$
DECLARE
  v_search_normalized  text;
  v_tsquery            tsquery;
  v_category_uuid      uuid;
  v_category_provided  boolean := false;
  v_limit              integer := GREATEST(0, LEAST(COALESCE(p_limit, 50), 1000));
  v_offset             integer := GREATEST(0, COALESCE(p_offset, 0));
BEGIN
  IF p_search_term IS NOT NULL AND length(trim(p_search_term)) > 0 THEN
    v_search_normalized := left(lower(unaccent(trim(p_search_term))), 200);
    BEGIN
      v_tsquery := websearch_to_tsquery('portuguese', v_search_normalized);
    EXCEPTION WHEN OTHERS THEN v_tsquery := NULL; END;
    PERFORM set_config('pg_trgm.similarity_threshold', '0.2', true);
  END IF;

  IF p_category_id IS NOT NULL THEN
    v_category_uuid     := p_category_id;
    v_category_provided := true;
  ELSIF p_category_slug IS NOT NULL THEN
    v_category_provided := true;
    SELECT c.id INTO v_category_uuid FROM categories c WHERE c.slug = p_category_slug LIMIT 1;
  END IF;

  RETURN QUERY
  WITH
  mat_filter AS (
    SELECT DISTINCT pm.product_id FROM product_materials pm
    JOIN material_types mt ON mt.id=pm.material_id JOIN material_groups mg ON mg.id=mt.group_id
    WHERE p_material_groups IS NOT NULL AND array_length(p_material_groups,1) > 0
      AND mg.name = ANY(p_material_groups) AND pm.is_active=true
  ),
  tech_filter AS (
    SELECT DISTINCT pat.product_id FROM print_area_techniques pat
    JOIN tabela_preco_gravacao_oficial tpgo ON tpgo.id=pat.tabela_preco_id
    WHERE p_technique_groups IS NOT NULL AND array_length(p_technique_groups,1) > 0
      AND tpgo.grupo_tecnica = ANY(p_technique_groups) AND pat.is_active=true
  ),
  color_filter AS (
    SELECT DISTINCT pv.product_id FROM product_variants pv
    JOIN color_variations cv ON cv.id=pv.color_id JOIN color_groups cg ON cg.id=cv.group_id
    WHERE p_color_groups IS NOT NULL AND array_length(p_color_groups,1) > 0
      AND cg.name = ANY(p_color_groups) AND pv.is_active=true
  ),
  date_filter AS (
    SELECT DISTINCT pcd.product_id FROM product_commemorative_dates pcd
    JOIN commemorative_dates cd ON cd.id=pcd.commemorative_date_id
    WHERE p_date_slugs IS NOT NULL AND array_length(p_date_slugs,1) > 0
      AND cd.slug = ANY(p_date_slugs) AND pcd.is_active=true
  ),
  endo_filter AS (
    SELECT DISTINCT pt.product_id FROM product_tags pt JOIN tags t ON t.id=pt.tag_id
    WHERE p_endomarketing=true AND t.slug='endomarketing' AND t.is_active=true
  ),
  cat_filter AS (
    SELECT DISTINCT pca.product_id FROM product_category_assignments pca
    WHERE v_category_uuid IS NOT NULL AND pca.category_id = v_category_uuid
  ),
  base AS (
    SELECT
      p.id, p.name, p.sku, p.slug, p.short_description, p.brand,
      p.sale_price,
      NULL::numeric AS cost_price,  -- fix_version 20260717: NUNCA expor custo ao anon
      p.min_quantity, p.stock_quantity,
      p.is_stockout, p.is_kit, p.is_textil, p.is_thermal, p.is_featured,
      p.is_bestseller, p.is_new, p.has_gift_box, p.target_audience,
      p.primary_image_url, p.og_image_url, p.set_image_url,
      p.main_category_id AS category_id,
      c.name AS category_name, c.slug AS category_slug,
      CASE
        WHEN v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery
          THEN ts_rank_cd(p.search_vector, v_tsquery, 32)*2.0 + word_similarity(v_search_normalized, lower(unaccent(p.name)))
        WHEN v_search_normalized IS NOT NULL
          THEN word_similarity(v_search_normalized, lower(unaccent(p.name)))
        ELSE 0
      END AS relevance_score,
      COUNT(*) OVER() AS _total_count
    FROM products p
    LEFT JOIN categories c ON c.id = p.main_category_id
    WHERE
      p.is_active=true AND p.is_deleted IS NOT TRUE
      AND (v_search_normalized IS NULL
           OR (v_tsquery IS NOT NULL AND p.search_vector @@ v_tsquery)
           OR p.name % v_search_normalized
           OR lower(p.sku) LIKE '%'||v_search_normalized||'%')
      AND (
        NOT v_category_provided
        OR (v_category_uuid IS NOT NULL AND EXISTS (SELECT 1 FROM cat_filter cf WHERE cf.product_id=p.id))
      )
      AND (p_brands IS NULL OR array_length(p_brands,1) IS NULL OR p.brand = ANY(p_brands))
      -- fix_version 20260717: IS NOT TRUE corrige 3-valued logic (NOT NULL=NULL→excluía produtos).
      -- NULL IS NOT TRUE=TRUE (sem filtro=todos) | TRUE IS NOT TRUE=FALSE (só em estoque).
      -- Bug original: AND (NOT p_only_in_stock OR p.is_stockout=false) excluía 1.395 produtos.
      AND (p_only_in_stock IS NOT TRUE OR p.is_stockout=false)
      AND (p_min_price IS NULL OR p.sale_price >= p_min_price)
      AND (p_max_price IS NULL OR p.sale_price <= p_max_price)
      AND (p_target_audiences IS NULL OR array_length(p_target_audiences,1) IS NULL OR p.target_audience && p_target_audiences)
      AND (p_is_kit IS NULL OR p.is_kit=p_is_kit)
      AND (p_is_textil IS NULL OR p.is_textil=p_is_textil)
      AND (p_is_thermal IS NULL OR p.is_thermal=p_is_thermal)
      AND (p_has_gift_box IS NULL OR p.has_gift_box=p_has_gift_box)
      AND (p_material_groups IS NULL  OR array_length(p_material_groups,1) IS NULL  OR EXISTS(SELECT 1 FROM mat_filter   mf WHERE mf.product_id=p.id))
      AND (p_technique_groups IS NULL OR array_length(p_technique_groups,1) IS NULL OR EXISTS(SELECT 1 FROM tech_filter  tf WHERE tf.product_id=p.id))
      AND (p_color_groups IS NULL     OR array_length(p_color_groups,1) IS NULL     OR EXISTS(SELECT 1 FROM color_filter cf WHERE cf.product_id=p.id))
      AND (p_date_slugs IS NULL       OR array_length(p_date_slugs,1) IS NULL       OR EXISTS(SELECT 1 FROM date_filter  df WHERE df.product_id=p.id))
      AND (p_endomarketing IS NULL OR p_endomarketing=false OR EXISTS(SELECT 1 FROM endo_filter ef WHERE ef.product_id=p.id))
  )
  SELECT
    b.id, b.name::text, b.sku::text, b.slug::text, b.short_description::text,
    b.brand, b.sale_price, b.cost_price, b.min_quantity, b.stock_quantity,
    b.is_stockout, b.is_kit, b.is_textil, b.is_thermal, b.is_featured,
    b.is_bestseller, b.is_new, b.has_gift_box, b.target_audience,
    b.primary_image_url, b.og_image_url, b.set_image_url,
    b.category_id, b.category_name::text, b.category_slug::text, b._total_count
  FROM base b
  ORDER BY
    CASE p_sort WHEN 'name_asc'   THEN b.name END ASC  NULLS LAST,
    CASE p_sort WHEN 'name_desc'  THEN b.name END DESC NULLS LAST,
    CASE p_sort WHEN 'price_asc'  THEN b.sale_price END ASC  NULLS LAST,
    CASE p_sort WHEN 'price_desc' THEN b.sale_price END DESC NULLS LAST,
    CASE p_sort WHEN 'relevance'  THEN b.relevance_score
                WHEN 'bestseller' THEN CASE WHEN b.is_bestseller THEN 1 ELSE 0 END::numeric
    END DESC NULLS LAST,
    b.is_featured DESC, b.is_bestseller DESC, b.name ASC
  LIMIT v_limit OFFSET v_offset;
END;
$fn$;

-- Re-conceder EXECUTE ao anon (DROP removeu os grants)
GRANT EXECUTE ON FUNCTION public.fn_super_filtro TO anon;
GRANT EXECUTE ON FUNCTION public.fn_super_filtro TO authenticated;

COMMENT ON FUNCTION public.fn_super_filtro IS
  'Catálogo principal do storefront (SECURITY DEFINER). fix_version 20260717: '
  'bug p_only_in_stock=NULL corrigido via IS NOT TRUE. cost_price=NULL::numeric. '
  'ANTI-REGRESSAO: manter IS NOT TRUE no predicado de estoque.';;

-- <<< END 20260717173228_fix_fn_super_filtro_null_stock_v1.sql <<<

-- >>> BEGIN 20260717173348_secure_tabela_gravacao_anon_definer_v1.sql >>>
-- ============================================================================
-- fix_version: 20260717_secure_tabela_gravacao_anon_definer_v1
-- MELHORIA 3/6: Protege custo/markup da tabela de gravação oficial.
-- tabela_preco_gravacao_oficial tinha anon SELECT com: custo_setup (56 rows, max R$325),
-- markup_percent (58 rows, max 115%), custo_aplicacao, custo_termo_transferencia, 
-- custo_queima_forno, faturamento_minimo — dados operacionais/financeiros internos.
-- SOLUÇÃO: View pública SECURITY DEFINER com apenas colunas seguras (nome, grupo,
-- flags de cobrança, faixas de preço de venda, flags técnicos). REVOKE tabela base.
-- tabela_preco_gravacao_oficial_faixa mantém acesso direto (só preco_unitario = venda).
-- ============================================================================

-- (A) View pública sem colunas de custo/markup
CREATE OR REPLACE VIEW public.v_tabela_preco_gravacao_oficial_public AS
SELECT
  id, codigo_tabela, codigo, codigo_curto, nome, nome_grupo, descricao,
  grupo_tecnica, cobra_por_cor, max_cores,
  desconto_segunda_cor, desconto_terceira_cor, desconto_quarta_cor_mais,
  preco_minimo_unitario, preco_maximo_unitario,
  cobra_por_area, area_maxima_cm2, area_maxima_texto,
  cobra_por_pontos, max_pontos,
  usa_faixa_dimensional, opcoes_modificadores, tom_options,
  cobra_aplicacao, cobra_queima_forno, cobra_termo_transferencia,
  custo_setup_por_cor,      -- boolean (se cobra setup por cor) — não é valor monetário
  custo_manuseio_por_peca,  -- boolean (se cobra manuseio por peça) — não é valor monetário
  quantidade_corte, tipo_setup,
  validade_inicio, validade_fim,
  ordem_exibicao, tecnica_variante_id, ativo,
  created_at, updated_at
  -- EXCLUÍDOS INTENCIONALMENTE (sensíveis):
  -- custo_setup, custo_manuseio, custo_aplicacao, custo_termo_transferencia,
  -- custo_queima_forno, markup_percent, faturamento_minimo
FROM public.tabela_preco_gravacao_oficial
WHERE ativo = true;

-- (B) SECURITY DEFINER — anon só precisa de SELECT na view, não na tabela base
ALTER VIEW public.v_tabela_preco_gravacao_oficial_public SET (security_invoker = false);

-- (C) Grants: view concedida, tabela base revogada
GRANT SELECT ON public.v_tabela_preco_gravacao_oficial_public TO anon;
REVOKE SELECT ON public.tabela_preco_gravacao_oficial FROM anon;

-- (D) Documentação
COMMENT ON VIEW public.v_tabela_preco_gravacao_oficial_public IS
  'PUBLIC ENGRAVING TABLE PROJECTION (SECURITY DEFINER / fix_version 20260717). '
  'Expõe apenas colunas de cobrança e preços de venda. '
  'EXCLUÍDOS: custo_setup (R$325 max), markup_percent (115% max), custo_aplicacao, '
  'custo_termo_transferencia, custo_queima_forno, faturamento_minimo. '
  'NAO reverter para security_invoker=true nem re-expor a tabela base ao anon.';

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260717173348_secure_tabela_gravacao_anon_definer_v1.sql <<<

-- >>> BEGIN 20260717173416_revoke_anon_pg_stat_statements_v1.sql >>>
-- ============================================================================
-- fix_version: 20260717_revoke_anon_pg_stat_statements_v1
-- MELHORIA 4/6: Revogar acesso do anon a pg_stat_statements (extensions schema).
-- pg_stat_statements expunha ao anon: 4.980 queries SQL, incluindo 104 com
-- referência a 'cost_price' e 10 com 'api_credential' — information disclosure
-- sobre estrutura interna e dados sensíveis. Grant vinha via PUBLIC role.
-- SOLUÇÃO: REVOKE de PUBLIC. postgres/service_role mantêm acesso (superuser).
-- authenticated também perde acesso — aceitável (app não usa pg_stat_statements).
-- ============================================================================
REVOKE SELECT ON extensions.pg_stat_statements      FROM PUBLIC;
REVOKE SELECT ON extensions.pg_stat_statements_info FROM PUBLIC;;

