-- >>> BEGIN 20260717173510_update_fn_verify_anon_catalog_grants_v3.sql >>>
-- ============================================================================
-- fix_version: 20260717_fn_verify_anon_catalog_grants_v3
-- MELHORIA 5/6: Tripwire v3 — cobertura completa de todos os fixes desta sessão.
-- Adicionado: v_tabela_preco_gravacao_oficial_public, fn_product_active_for_rls EXECUTE,
-- pg_stat_statements bloqueado, tabela_preco_gravacao_oficial bloqueada,
-- product_variants_anon_read is_active check, 9 views DEFINER completas.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.fn_verify_anon_catalog_grants()
RETURNS TABLE(object_name text, object_kind text, issue text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $fn$
BEGIN
  -- (1) Views/tabelas que DEVEM ter anon SELECT
  RETURN QUERY
  WITH req(sch, nm) AS (VALUES
    -- Views DEFINER (catálogo principal)
    ('public','v_products_public'),('public','v_suppliers_public'),
    ('public','v_variant_sale_prices_public'),
    ('public','v_tabela_preco_gravacao_oficial_public'),
    -- 9 views _public
    ('public','v_color_nuances_public'),('public','v_kit_component_media_public'),
    ('public','v_kit_component_print_areas_public'),
    ('public','v_personalization_techniques_public'),
    ('public','v_print_area_techniques_public'),('public','v_product_compositions_public'),
    ('public','v_product_properties_public'),('public','v_product_tags_public'),
    ('public','v_tags_public'),
    -- Matviews cross-schema
    ('public','mv_product_compositions'),
    ('internal','mv_product_leaf_category'),('analytics','mv_product_compositions'),
    -- Tabelas de catálogo (não sensíveis)
    ('public','categories'),('public','collection_products'),('public','collections'),
    ('public','color_groups'),('public','color_synonym_map'),('public','color_variations'),
    ('public','content_articles'),('public','favorite_item_reactions'),
    ('public','favorite_items'),('public','favorite_lists'),('public','kit_typical_dims'),
    ('public','material_types'),('public','mockup_approval_links'),
    ('public','print_area_techniques'),('public','product_ai_content'),
    ('public','product_attributes'),('public','product_badge_definitions'),
    ('public','product_commemorative_dates'),('public','product_fiscal'),
    ('public','product_kit_components'),('public','product_materials'),
    ('public','product_novelties'),('public','product_physical'),('public','product_seo'),
    ('public','product_supply'),('public','product_variants'),
    ('public','produto_ramo_atividade'),('public','ramo_atividade'),
    ('public','ramo_atividade_filho'),('public','spot_typecode_map'),
    ('public','supplier_sub_brands'),('public','system_kill_switches'),
    ('public','tabela_preco_gravacao_oficial_faixa'),  -- faixa de preço de venda OK
    ('public','tecnicas_gravacao'),('public','video_sim_results'),
    ('public','color_nuances'),('public','kit_component_print_areas'),
    ('public','personalization_techniques'),('public','product_properties'),
    ('public','tags'),('public','product_tags')
  )
  SELECT req.sch||'.'||req.nm, 'table/view'::text, 'FALTA anon SELECT'::text
  FROM req
  WHERE to_regclass(req.sch||'.'||req.nm) IS NULL
     OR NOT has_table_privilege('anon', (req.sch||'.'||req.nm)::regclass, 'SELECT');

  -- (2) Funções com anon EXECUTE obrigatório
  RETURN QUERY
  SELECT 'public.'||v.fn, 'function'::text, 'FALTA anon EXECUTE'::text
  FROM (VALUES ('fn_super_filtro'),('fn_super_filtro_facets'),('fn_super_filtro_price_range'),
               ('fn_global_search'),('get_catalog_bestseller_page'),
               ('fn_product_active_for_rls')) v(fn)  -- NOVO v3
  WHERE EXISTS (SELECT 1 FROM pg_proc WHERE proname=v.fn AND pronamespace='public'::regnamespace)
    AND NOT has_function_privilege('anon',
          (SELECT oid FROM pg_proc WHERE proname=v.fn AND pronamespace='public'::regnamespace LIMIT 1),'EXECUTE');

  -- (3) Tabelas SENSÍVEIS que NÃO podem ter anon SELECT
  RETURN QUERY
  SELECT 'public.'||v.nm, 'table'::text, 'VAZAMENTO: anon SELECT em tabela sensível'::text
  FROM (VALUES ('variant_supplier_sources'),('markup_configurations'),('user_organizations'),
               ('quotes'),('quote_items'),
               ('products'),('suppliers'),   -- custo/credenciais
               ('tabela_preco_gravacao_oficial'))  -- NOVO v3: custo_setup/markup
             v(nm)
  WHERE to_regclass('public.'||v.nm) IS NOT NULL
    AND has_table_privilege('anon', ('public.'||v.nm)::regclass, 'SELECT');

  -- (4) pg_stat_statements NÃO pode ter anon SELECT (information disclosure de queries)
  RETURN QUERY
  SELECT 'extensions.pg_stat_statements', 'system_view'::text,
         'VAZAMENTO: anon lê queries SQL internas'::text
  WHERE has_table_privilege('anon', 'extensions.pg_stat_statements'::regclass, 'SELECT');

  -- (5) Funções sensíveis que NÃO devem ter anon EXECUTE
  RETURN QUERY
  SELECT 'public.get_promo_sales_ranking', 'function'::text,
         'VAZAMENTO: anon executa ranking de vendas'::text
  WHERE EXISTS (SELECT 1 FROM pg_proc WHERE proname='get_promo_sales_ranking' AND pronamespace='public'::regnamespace)
    AND has_function_privilege('anon',
          (SELECT oid FROM pg_proc WHERE proname='get_promo_sales_ranking' AND pronamespace='public'::regnamespace LIMIT 1),'EXECUTE');

  -- (6) Views críticas devem ser SECURITY DEFINER (security_invoker=false)
  RETURN QUERY
  SELECT 'public.'||v.nm, 'view'::text, 'RISCO: view sensível com security_invoker=true'::text
  FROM (VALUES ('v_products_public'),('v_suppliers_public'),
               ('v_variant_sale_prices_public'),
               ('v_tabela_preco_gravacao_oficial_public'),  -- NOVO v3
               ('v_kit_component_media_public'),('v_kit_component_print_areas_public'),
               ('v_product_compositions_public'),('v_product_properties_public'),
               ('v_product_tags_public')) v(nm)
  WHERE to_regclass('public.'||v.nm) IS NOT NULL
    AND COALESCE((SELECT option_value FROM pg_options_to_table(
        (SELECT reloptions FROM pg_class WHERE relname=v.nm AND relnamespace='public'::regnamespace))
      WHERE option_name='security_invoker'), 'false') = 'true';

  -- (7) NOVO v3: product_variants anon deve ter política com is_active filter
  RETURN QUERY
  SELECT 'public.product_variants', 'rls_policy'::text,
         'RISCO: política anon sem filtro is_active (202 variantes inativas expostas)'::text
  WHERE EXISTS (
    SELECT 1 FROM pg_policies
    WHERE schemaname='public' AND tablename='product_variants'
      AND cmd IN ('SELECT','ALL')
      AND 'anon'=ANY(roles)
      AND qual='true'
  );
END $fn$;

COMMENT ON FUNCTION public.fn_verify_anon_catalog_grants() IS
  'Tripwire anti-regressao v3 (fix_version 20260717). Cobre: 56+ objetos obrigatórios, '
  '8 travas de sensíveis (products/suppliers/tabela_gravacao/pg_stat_statements), '
  '6 RPCs (5 seguros + fn_product_active_for_rls), 9 views DEFINER, '
  'produto_variants is_active policy. 0 linhas = saudável.';;

-- <<< END 20260717173510_update_fn_verify_anon_catalog_grants_v3.sql <<<

-- >>> BEGIN 20260717181201_fix_analytics_matview_grants_after_security_invoker.sql >>>
-- APLICADO: SIM — 2026-07-17 18:12 UTC (via MCP, version 20260717181201)
-- Migration: fix_analytics_matview_grants_after_security_invoker
-- Resultado: 5 views wrapper public.* voltaram a responder 200 para authenticated
-- Assertivas: SELECT real em toda view/matview de public como authenticated e anon
--             → 0 erros 42501. anon segue bloqueado nas MVs sensíveis.
-- Reversível: REVOKE SELECT ON analytics.<matview> FROM authenticated, service_role;
-- Guards: cada objeto pode não existir em preview snapshots (criados out-of-band),
--         mesmo padrão de 20260531220000_grant_select_analytics_views_authenticated.sql
--
-- ═══════════════════════════════════════════════════════════════════════════════
-- SINTOMA
-- ═══════════════════════════════════════════════════════════════════════════════
-- PostgREST devolvia 403 em /rest/v1/mv_stock_velocity e /rest/v1/mv_product_intelligence.
-- Console do catálogo com centenas de "403 (Forbidden)" em FiltersPage/ProductGrid.
--
-- ═══════════════════════════════════════════════════════════════════════════════
-- CAUSA RAIZ — migration 063 se auto-sabotou
-- ═══════════════════════════════════════════════════════════════════════════════
-- A 20260717000063 fez, no mesmo arquivo, duas coisas incompatíveis entre si:
--
--   Phase 4: ALTER VIEW public.mv_stock_velocity SET (security_invoker = true)
--            + sweep aplicando invoker em toda view de public sem ele
--   Phase 5: revoke direct access em analytics.* FROM PUBLIC, anon E authenticated
--
-- Uma fez a view depender do privilégio do CHAMADOR; a outra tirou esse privilégio:
--
--   public.mv_stock_velocity (view, invoker)   authenticated TEM select  ✓
--     └─> analytics.mv_stock_velocity (matview) ACL = NULL               ✗ 42501 → 403
--
-- Matview NÃO suporta RLS: o único gate possível é o GRANT. Sem ele a cadeia quebra.
-- A 063 previu o efeito (linha 27: "wraps analytics.mv_stock_velocity which
-- authenticated cannot access directly") e seguiu assim mesmo, com "fallback" de
-- revogar a view — na prática, aceitar que a feature morre. O objetivo era zerar o
-- advisor (security_definer_view 3→0); o custo foi 5 telas.
--
-- Precedente: 20260531220000 corrigiu ESTE MESMO bug em 31/05. É recorrente.
--
-- ═══════════════════════════════════════════════════════════════════════════════
-- CORREÇÃO
-- ═══════════════════════════════════════════════════════════════════════════════
-- A intenção da 063 era fechar o `anon` (findings: pg_graphql_anon_table_exposed).
-- O erro foi a marreta da Phase 5 pegar `authenticated` junto. Restauramos apenas
-- `authenticated`/`service_role`, preservando o fechamento do `anon`.
--
-- Princípio: a view wrapper de public já declara a intenção de acesso; espelhamos
-- essa intenção exata na matview subjacente. Nenhuma política nova inventada.
--
-- ESCOPO (encontrado por sweep do grafo de dependências, não pelo console):
-- O log mostrava 2 objetos; o sweep revelou 5.

DO $$
DECLARE
  o        text;
  schema_n text;
  obj_n    text;
  -- Matviews em analytics que alimentam wrappers security_invoker em public.
  -- authenticated + service_role precisam de SELECT direto para a cadeia funcionar.
  objs_read text[] := ARRAY[
    'analytics.categories_tree_visual',
    'analytics.mv_product_cards',
    'analytics.mv_product_compositions',
    'analytics.mv_product_intelligence',
    'analytics.mv_stock_velocity'
  ];
  -- Objetos onde privilégio de escrita para anon/authenticated é lixo:
  -- matview não é atualizável. Havia `anon=awdxtm` (write sem read!) em
  -- public.mv_supplier_reliability.
  objs_clean text[] := ARRAY[
    'analytics.categories_tree_visual',
    'analytics.mv_product_cards',
    'analytics.mv_product_compositions',
    'analytics.mv_product_intelligence',
    'analytics.mv_stock_velocity',
    'public.categories_tree_visual',
    'public.mv_product_cards',
    'public.mv_product_compositions',
    'public.mv_product_intelligence',
    'public.mv_stock_velocity',
    'public.mv_supplier_reliability',
    'public.mv_ema_kpi_by_level',
    'public.mv_stock_rupture_alert',
    'public.mv_product_images_audit'
  ];
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'analytics') THEN
    RAISE NOTICE '[181201] schema analytics ausente — nada a fazer';
    RETURN;
  END IF;

  -- Pré-requisito: USAGE no schema (já existia; idempotente)
  GRANT USAGE ON SCHEMA analytics TO authenticated, anon, service_role;

  -- 1) Restaura o SELECT que a Phase 5 da 063 removeu, só para os roles logados.
  FOREACH o IN ARRAY objs_read LOOP
    schema_n := split_part(o, '.', 1);
    obj_n    := split_part(o, '.', 2);
    IF EXISTS (
      SELECT 1 FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = schema_n AND c.relname = obj_n AND c.relkind IN ('r','v','m','f','p')
    ) THEN
      EXECUTE format('GRANT SELECT ON %s TO authenticated, service_role', o);
      RAISE NOTICE '[181201] GRANT SELECT em % → authenticated, service_role', o;
    ELSE
      RAISE NOTICE '[181201] % ausente (preview snapshot) — pulado', o;
    END IF;
  END LOOP;

  -- 2) anon permanece FORA das MVs com supplier_id / preço / velocidade.
  --    Preserva o objetivo da 063 e a negação que a view wrapper já declarava.
  --    mv_product_compositions é a única sem coluna sensível → anon mantém leitura.
  FOREACH o IN ARRAY ARRAY[
    'analytics.categories_tree_visual',
    'analytics.mv_product_cards',
    'analytics.mv_product_intelligence',
    'analytics.mv_stock_velocity'
  ] LOOP
    schema_n := split_part(o, '.', 1);
    obj_n    := split_part(o, '.', 2);
    IF EXISTS (
      SELECT 1 FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = schema_n AND c.relname = obj_n AND c.relkind IN ('r','v','m','f','p')
    ) THEN
      EXECUTE format('REVOKE ALL ON %s FROM anon', o);
    END IF;
  END LOOP;

  IF EXISTS (
    SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'analytics' AND c.relname = 'mv_product_compositions'
  ) THEN
    GRANT SELECT ON analytics.mv_product_compositions TO anon;
  END IF;

  -- 3) Higiene: matview não é atualizável — remove write concedido a anon/authenticated.
  FOREACH o IN ARRAY objs_clean LOOP
    schema_n := split_part(o, '.', 1);
    obj_n    := split_part(o, '.', 2);
    IF EXISTS (
      SELECT 1 FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = schema_n AND c.relname = obj_n AND c.relkind IN ('v','m')
    ) THEN
      EXECUTE format(
        'REVOKE INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON %s FROM anon, authenticated',
        o
      );
    END IF;
  END LOOP;
END $$;

-- NOTA sobre blindagem contra recorrência:
-- A primeira versão desta migration usava
--   ALTER DEFAULT PRIVILEGES IN SCHEMA analytics GRANT SELECT ON TABLES TO authenticated
-- para impedir a repetição. Removido após review: concederia SELECT direto em
-- QUALQUER objeto futuro de analytics, não só nas matviews que alimentam wrappers —
-- contrariando a Phase 5 da 063, que fecha o schema deliberadamente.
-- Ver 20260717190000_narrow_analytics_default_privileges_to_explicit_grants.sql.
-- A proteção correta é um gate de CI que rode o sweep de 403, não um privilégio amplo.

NOTIFY pgrst, 'reload schema';

-- <<< END 20260717181201_fix_analytics_matview_grants_after_security_invoker.sql <<<

-- >>> BEGIN 20260717185945_narrow_analytics_default_privileges_to_explicit_grants.sql >>>
-- Corrige a blindagem de 20260717181201 apos review (codex P1).
--
-- O ALTER DEFAULT PRIVILEGES ... GRANT SELECT ON TABLES TO authenticated era
-- amplo demais: concedia SELECT direto em QUALQUER tabela/view futura de
-- analytics, nao apenas nas matviews que alimentam wrappers de public. Isso
-- contraria a Phase 5 da migration 063 ("analytics ... revoke direct access
-- from all relations"), que fechou o schema deliberadamente.
--
-- Grants explicitos por objeto (ja aplicados) continuam valendo. A protecao
-- contra recorrencia passa a ser um gate de CI, nao um privilegio amplo.
ALTER DEFAULT PRIVILEGES IN SCHEMA analytics
  REVOKE SELECT ON TABLES FROM authenticated, service_role;

-- O REVOKE para anon permanece: e restritivo e alinhado a Phase 1 da 063.
ALTER DEFAULT PRIVILEGES IN SCHEMA analytics
  REVOKE ALL ON TABLES FROM anon;

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260717185945_narrow_analytics_default_privileges_to_explicit_grants.sql <<<

-- >>> BEGIN 20260717190000_narrow_analytics_default_privileges_to_explicit_grants.sql >>>
-- APLICADO: SIM — 2026-07-17 19:00 UTC (via MCP)
-- Migration: narrow_analytics_default_privileges_to_explicit_grants
-- Resultado: pg_default_acl do schema analytics volta a ficar vazio
-- Assertivas: 5 views wrapper seguem servindo authenticated; anon segue 42501
-- Reversível: ALTER DEFAULT PRIVILEGES IN SCHEMA analytics GRANT SELECT ON TABLES TO authenticated;
--
-- CONTEXTO:
-- A versão original de 20260717181201 tentava impedir a recorrência do 403 com:
--   ALTER DEFAULT PRIVILEGES IN SCHEMA analytics GRANT SELECT ON TABLES TO authenticated
--
-- Review (codex, P1) apontou corretamente que isso é amplo demais: concede SELECT
-- direto em QUALQUER tabela ou view futura criada em analytics — não apenas nas
-- matviews que alimentam wrappers de public. Como authenticated também tem USAGE
-- no schema, dados internos futuros de analytics ficariam expostos por padrão.
--
-- Isso contraria a Phase 5 da migration 20260717000063, que fecha analytics
-- deliberadamente ("revoke direct access from all relations").
--
-- DECISÃO:
-- Grants explícitos por objeto (aplicados em 181201, com guard de existência)
-- continuam valendo — são o que faz as 5 telas funcionarem. A proteção contra
-- recorrência passa a ser um gate de CI que roda o sweep de 403, não um
-- privilégio amplo que reabre o schema.

ALTER DEFAULT PRIVILEGES IN SCHEMA analytics
  REVOKE SELECT ON TABLES FROM authenticated, service_role;

-- O REVOKE para anon permanece: é restritivo e alinhado à Phase 1 da 063
-- (ALTER DEFAULT PRIVILEGES IN SCHEMA analytics REVOKE SELECT ON TABLES FROM PUBLIC).
ALTER DEFAULT PRIVILEGES IN SCHEMA analytics
  REVOKE ALL ON TABLES FROM anon;

NOTIFY pgrst, 'reload schema';

-- <<< END 20260717190000_narrow_analytics_default_privileges_to_explicit_grants.sql <<<

-- >>> BEGIN 20260717235313_fix_stock_rupture_kpi_matview_grants_for_authenticated.sql >>>
-- Bug pré-existente: mv_stock_rupture_alert, mv_ema_kpi_by_level e vw_rupture_*
-- estavam em 403 para authenticated desde a migration 20260626184039 (revoke_anon)
-- e consolidados pela Phase 5 da 063. Descoberto por teste de stress pós-PR #1731.

DO $$
DECLARE v_vw text;
BEGIN
  -- mv_stock_rupture_alert (usada por useRuptureAlerts, StockRiskHero, VariantStockTable)
  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
             WHERE n.nspname='public' AND c.relname='mv_stock_rupture_alert' AND c.relkind='m')
  THEN
    GRANT SELECT ON public.mv_stock_rupture_alert TO authenticated, service_role;
  ELSE
    RAISE NOTICE '[rupture_fix] mv_stock_rupture_alert ausente — skip';
  END IF;

  -- mv_ema_kpi_by_level (KPI de nível EMA, carregado por StockRiskHero)
  IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
             WHERE n.nspname='public' AND c.relname='mv_ema_kpi_by_level' AND c.relkind='m')
  THEN
    GRANT SELECT ON public.mv_ema_kpi_by_level TO authenticated, service_role;
  ELSE
    RAISE NOTICE '[rupture_fix] mv_ema_kpi_by_level ausente — skip';
  END IF;

  -- Wrappers vw_rupture_* com security_invoker=true: grant na view + no dep já resolvido acima
  FOREACH v_vw IN ARRAY ARRAY['vw_rupture_confidence_audit','vw_rupture_gap_purchase',
                              'vw_rupture_live_divergence'] LOOP
    IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
               WHERE n.nspname='public' AND c.relname=v_vw AND c.relkind='v')
    THEN
      EXECUTE format('GRANT SELECT ON public.%I TO authenticated', v_vw);
    END IF;
  END LOOP;

  -- Confirmar que anon NÃO recebe acesso (dados operacionais internos)
  FOREACH v_vw IN ARRAY ARRAY['mv_stock_rupture_alert','mv_ema_kpi_by_level',
    'vw_rupture_confidence_audit','vw_rupture_gap_purchase','vw_rupture_live_divergence'] LOOP
    IF EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
               WHERE n.nspname='public' AND c.relname=v_vw)
    THEN
      EXECUTE format('REVOKE SELECT ON public.%I FROM anon', v_vw);
    END IF;
  END LOOP;
END $$;

NOTIFY pgrst, 'reload schema';;

-- <<< END 20260717235313_fix_stock_rupture_kpi_matview_grants_for_authenticated.sql <<<

-- >>> BEGIN 20260717235500_fix_stock_rupture_kpi_matview_grants.sql >>>
-- APLICADO: 2026-07-17 23:45 UTC (via MCP)
-- Bug pré-existente encontrado por teste de stress pós-PR #1731.
--
-- CAUSA: migration 20260626184039 removeu anon das MVs de ruptura/kpi (correto).
-- A Phase 5 da 063 (20260717000063) varreu analytics.* mas deixou
-- public.mv_stock_rupture_alert e public.mv_ema_kpi_by_level sem authenticated.
-- Resultado: useRuptureAlerts, StockRiskHero, VariantStockTable → 403.
-- vw_rupture_* com security_invoker=true dependem de mv_stock_rupture_alert → 403 cascata.

DO $$
DECLARE v_vw text;
BEGIN
  -- mv_stock_rupture_alert (useRuptureAlerts, StockRiskHero, VariantStockTable)
  IF EXISTS (
    SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname='public' AND c.relname='mv_stock_rupture_alert' AND c.relkind='m'
  ) THEN
    GRANT SELECT ON public.mv_stock_rupture_alert TO authenticated, service_role;
    RAISE NOTICE '[rupture_fix] GRANT SELECT mv_stock_rupture_alert';
  ELSE
    RAISE NOTICE '[rupture_fix] mv_stock_rupture_alert ausente (preview) — skip';
  END IF;

  -- mv_ema_kpi_by_level (StockRiskHero — KPI de nível EMA)
  IF EXISTS (
    SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
    WHERE n.nspname='public' AND c.relname='mv_ema_kpi_by_level' AND c.relkind='m'
  ) THEN
    GRANT SELECT ON public.mv_ema_kpi_by_level TO authenticated, service_role;
    RAISE NOTICE '[rupture_fix] GRANT SELECT mv_ema_kpi_by_level';
  ELSE
    RAISE NOTICE '[rupture_fix] mv_ema_kpi_by_level ausente (preview) — skip';
  END IF;

  -- vw_rupture_* precisam de grant na view (security_invoker verifica o dep E a view)
  FOREACH v_vw IN ARRAY ARRAY[
    'vw_rupture_confidence_audit','vw_rupture_gap_purchase','vw_rupture_live_divergence'
  ] LOOP
    IF EXISTS (
      SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relname=v_vw AND c.relkind='v'
    ) THEN
      EXECUTE format('GRANT SELECT ON public.%I TO authenticated', v_vw);
      RAISE NOTICE '[rupture_fix] GRANT SELECT % → authenticated', v_vw;
    END IF;
  END LOOP;

  -- anon permanece bloqueado nestas MVs operacionais
  FOREACH v_vw IN ARRAY ARRAY[
    'mv_stock_rupture_alert','mv_ema_kpi_by_level',
    'vw_rupture_confidence_audit','vw_rupture_gap_purchase','vw_rupture_live_divergence'
  ] LOOP
    IF EXISTS (
      SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relname=v_vw
    ) THEN
      EXECUTE format('REVOKE SELECT ON public.%I FROM anon', v_vw);
    END IF;
  END LOOP;
END $$;

NOTIFY pgrst, 'reload schema';

