CREATE OR REPLACE FUNCTION public.create_quote_transactional(_quote jsonb, _items jsonb)
RETURNS public.quotes
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path TO public
AS $function$
DECLARE
  _new_quote    public.quotes;
  _new_quote_id uuid;
  _item         jsonb;
  _pers         jsonb;
  _new_item_id  uuid;
  _actor_id     uuid;
  _uid          uuid := auth.uid();
  _org_id       uuid := nullif(_quote->>'organization_id', '')::uuid;
  _seller_id    uuid := nullif(_quote->>'seller_id', '')::uuid;
BEGIN
  -- Usuários autenticados só podem usar uma organização à qual pertencem.
  -- Chamadas internas sem auth.uid() preservam os IDs explícitos e continuam
  -- sujeitas ao contexto/RLS do chamador porque a função é SECURITY INVOKER.
  IF _uid IS NOT NULL THEN
    IF _org_id IS NULL OR NOT public.user_is_org_member(_org_id) THEN
      SELECT uo.organization_id
      INTO _org_id
      FROM public.user_organizations uo
      WHERE uo.user_id = _uid
      ORDER BY uo.created_at ASC, uo.organization_id ASC
      LIMIT 1;
    END IF;

    IF _seller_id IS NULL THEN
      _seller_id := _uid;
    END IF;
  END IF;

  IF _org_id IS NULL THEN
    RAISE EXCEPTION 'Não foi possível determinar a organização do orçamento: usuário sem organização vinculada.'
      USING ERRCODE = '23502';
  END IF;

  INSERT INTO public.quotes (
    quote_number, client_id, contact_id,
    client_name, client_email, client_phone, client_company, client_cnpj,
    seller_id, created_by, organization_id, status,
    subtotal, discount_percent, discount_amount, total, negotiation_markup_percent,
    payment_method, payment_terms, delivery_time, shipping_type, shipping_cost,
    notes, internal_notes, valid_until
  )
  VALUES (
    coalesce(_quote->>'quote_number', ''),
    nullif(_quote->>'client_id', '')::uuid,
    nullif(_quote->>'contact_id', '')::uuid,
    coalesce(_quote->>'client_name', ''),
    _quote->>'client_email',
    _quote->>'client_phone',
    _quote->>'client_company',
    nullif(_quote->>'client_cnpj', ''),
    _seller_id,
    coalesce(_uid, _seller_id),
    _org_id,
    coalesce(_quote->>'status', 'draft'),
    coalesce((_quote->>'subtotal')::numeric, 0),
    coalesce((_quote->>'discount_percent')::numeric, 0),
    coalesce((_quote->>'discount_amount')::numeric, 0),
    coalesce((_quote->>'total')::numeric, 0),
    coalesce((_quote->>'negotiation_markup_percent')::numeric, 0),
    _quote->>'payment_method',
    _quote->>'payment_terms',
    _quote->>'delivery_time',
    _quote->>'shipping_type',
    coalesce((_quote->>'shipping_cost')::numeric, 0),
    _quote->>'notes',
    _quote->>'internal_notes',
    nullif(_quote->>'valid_until', '')::date
  )
  RETURNING * INTO _new_quote;

  _new_quote_id := _new_quote.id;

  FOR _item IN
    SELECT value FROM jsonb_array_elements(coalesce(_items, '[]'::jsonb))
  LOOP
    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, subtotal,
      discount_percentage, discount_amount,
      color_name, color_hex, size_code, gender,
      sort_order, notes, kit_group_id, kit_name,
      price_confirmed_at, price_updated_at, price_freshness_threshold_days,
      bitrix_product_id, personalization_cost
    )
    VALUES (
      _new_quote_id,
      nullif(_item->>'product_id', '')::uuid,
      _item->>'product_name',
      _item->>'product_sku',
      _item->>'product_image_url',
      coalesce((_item->>'quantity')::integer, 0),
      coalesce((_item->>'unit_price')::numeric, 0),
      coalesce((_item->>'subtotal')::numeric, 0),
      coalesce((_item->>'discount_percentage')::numeric, 0),
      coalesce((_item->>'discount_amount')::numeric, 0),
      _item->>'color_name',
      _item->>'color_hex',
      nullif(_item->>'size_code', ''),
      nullif(_item->>'gender', ''),
      coalesce((_item->>'sort_order')::integer, 0),
      _item->>'notes',
      nullif(_item->>'kit_group_id', '')::uuid,
      nullif(_item->>'kit_name', ''),
      nullif(_item->>'price_confirmed_at', '')::timestamptz,
      nullif(_item->>'price_updated_at', '')::timestamptz,
      coalesce(nullif(_item->>'price_freshness_threshold_days', '')::integer, 60),
      nullif(_item->>'bitrix_product_id', ''),
      coalesce((_item->>'personalization_cost')::numeric, 0)
    )
    RETURNING id INTO _new_item_id;

    FOR _pers IN
      SELECT value
      FROM jsonb_array_elements(coalesce(_item->'personalizations', '[]'::jsonb))
    LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name,
        location_code, location_name,
        personalized_quantity, colors_count, positions_count,
        area_cm2, width_cm, height_cm,
        setup_cost, unit_cost, total_cost, notes
      )
      VALUES (
        _new_item_id,
        nullif(_pers->>'technique_id', '')::uuid,
        _pers->>'technique_name',
        _pers->>'location_code',
        _pers->>'location_name',
        nullif(_pers->>'personalized_quantity', '')::integer,
        coalesce((_pers->>'colors_count')::integer, 1),
        coalesce((_pers->>'positions_count')::integer, 1),
        nullif(_pers->>'area_cm2', '')::numeric,
        nullif(_pers->>'width_cm', '')::numeric,
        nullif(_pers->>'height_cm', '')::numeric,
        coalesce((_pers->>'setup_cost')::numeric, 0),
        coalesce((_pers->>'unit_cost')::numeric, 0),
        coalesce((_pers->>'total_cost')::numeric, 0),
        _pers->>'notes'
      );
    END LOOP;
  END LOOP;

  SELECT * INTO _new_quote FROM public.quotes WHERE id = _new_quote_id;

  _actor_id := coalesce(_uid, _seller_id);
  IF _actor_id IS NOT NULL THEN
    INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
    VALUES (
      _new_quote_id,
      _actor_id,
      'created',
      format(
        'Orçamento %s criado com %s item(s) via RPC',
        _new_quote.quote_number,
        (SELECT count(*) FROM public.quote_items WHERE quote_id = _new_quote_id)
      ),
      jsonb_build_object(
        'status', _new_quote.status,
        'subtotal', _new_quote.subtotal,
        'total', _new_quote.total,
        'markup', _new_quote.negotiation_markup_percent,
        'n_items', (SELECT count(*) FROM public.quote_items WHERE quote_id = _new_quote_id)
      )
    );
  END IF;

  RETURN _new_quote;
END;
$function$;

COMMENT ON FUNCTION public.create_quote_transactional(jsonb, jsonb) IS
  'Criação atômica de orçamento; resolve organização autenticada no servidor e preserva custos de personalização.';

DO $postcondition$
DECLARE
  _definition text;
BEGIN
  SELECT pg_get_functiondef('public.create_quote_transactional(jsonb,jsonb)'::regprocedure)
  INTO _definition;

  IF strpos(_definition, 'public.user_is_org_member(_org_id)') = 0
     OR strpos(_definition, 'personalization_cost') = 0
     OR strpos(_definition, 'contact_id') = 0
     OR strpos(_definition, 'client_cnpj') = 0
     OR strpos(_definition, 'created_by') = 0 THEN
    RAISE EXCEPTION 'Postcondition failed: reconciled create_quote_transactional body is incomplete';
  END IF;
END
$postcondition$;

-- <<< END 20260828141100_forward_only_create_quote_transactional_auth_scope.sql <<<

-- >>> BEGIN 20260828141200_forward_only_fn_quotes_validate_discount_cross_user.sql >>>
-- Forward-only: corrige o único uso cross-user de is_coord_or_above, sem
-- perder os bypasses legítimos de expiração/cron/service-role existentes live.
-- PREPARADA, NÃO APLICADA ao projeto canônico em 2026-08-28.

DO $precondition$
DECLARE
  _definition text;
  _security_definer boolean;
BEGIN
  IF to_regprocedure('public.fn_quotes_validate_discount()') IS NULL THEN
    RAISE EXCEPTION 'Precondition failed: fn_quotes_validate_discount() does not exist';
  END IF;
  IF to_regprocedure('public.is_supervisor_or_above(uuid)') IS NULL THEN
    RAISE EXCEPTION 'Precondition failed: is_supervisor_or_above(uuid) does not exist';
  END IF;
  IF to_regprocedure('public.compute_quote_snapshot_hash(uuid)') IS NULL THEN
    RAISE EXCEPTION 'Precondition failed: compute_quote_snapshot_hash(uuid) does not exist';
  END IF;

  SELECT pg_get_functiondef(p.oid), p.prosecdef
  INTO _definition, _security_definer
  FROM pg_catalog.pg_proc p
  WHERE p.oid = 'public.fn_quotes_validate_discount()'::regprocedure;

  -- Drift guard: preserva os bypasses e a semântica da versão live auditada.
  -- Se qualquer agente já tiver reconciliado ou evoluído a função, reauditar.
  IF NOT _security_definer
     OR strpos(_definition, 'is_coord_or_above(_seller_id)') = 0
     OR strpos(_definition, 'auth.uid() IS NULL') = 0
     OR strpos(_definition, 'cron_expire') = 0
     OR strpos(_definition, 'pending_approval') = 0
     OR strpos(_definition, 'valid_until IS NULL OR valid_until > now()') = 0 THEN
    RAISE EXCEPTION 'Precondition failed: fn_quotes_validate_discount drifted from the audited 2026-08-28 live definition';
  END IF;
END
$precondition$;

CREATE OR REPLACE FUNCTION public.fn_quotes_validate_discount()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO public
AS $function$
DECLARE
  _max_allowed numeric;
  _real_discount_pct numeric;
  _has_valid_approval boolean;
  _current_hash text;
  _seller_id uuid;
  _msg text;
BEGIN
  -- Expiração automática só muda status e não pode ser bloqueada por alçada.
  IF NEW.status = 'expired' THEN
    RETURN NEW;
  END IF;

  IF current_setting('app.write_source', true) = 'cron_expire' THEN
    RETURN NEW;
  END IF;

  IF current_setting('request.jwt.claim.role', true) = 'service_role' THEN
    RETURN NEW;
  END IF;

  -- Contextos internos sem usuário continuam protegidos pela RLS/role externa.
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  _seller_id := COALESCE(NEW.seller_id, NEW.created_by);
  IF _seller_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Cross-user intencional: valida o papel do dono do orçamento. O helper
  -- is_coord_or_above protege leituras self-scoped e lançava 42501 neste caso.
  IF public.is_supervisor_or_above(_seller_id) THEN
    RETURN NEW;
  END IF;

  _real_discount_pct := COALESCE(NEW.real_discount_percent, 0);
  IF _real_discount_pct <= 0 THEN
    RETURN NEW;
  END IF;

  SELECT max_discount_percent
  INTO _max_allowed
  FROM public.seller_discount_limits
  WHERE user_id = _seller_id;

  IF _max_allowed IS NULL THEN
    RAISE EXCEPTION 'Vendedor sem limite de desconto cadastrado. Solicite ao admin que configure seu limite antes de salvar orcamentos.'
      USING ERRCODE = '23514';
  END IF;

  IF _real_discount_pct <= _max_allowed THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF COALESCE(NEW.status, 'draft') = 'pending_approval' THEN
      RETURN NEW;
    END IF;
    _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
            ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
            ' por cento. Para solicitar aprovacao, use o botao "Solicitar aprovacao ao coordenador"' ||
            ' que cria o orcamento em status pendente.';
    RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
  END IF;

  _current_hash := public.compute_quote_snapshot_hash(NEW.id);

  SELECT EXISTS (
    SELECT 1
    FROM public.discount_approval_requests
    WHERE quote_id = NEW.id
      AND status = 'approved'
      AND (valid_until IS NULL OR valid_until > now())
      AND requested_discount_percent >= _real_discount_pct
      AND quote_snapshot_hash = _current_hash
  ) INTO _has_valid_approval;

  IF _has_valid_approval THEN
    RETURN NEW;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.discount_approval_requests
    WHERE quote_id = NEW.id
      AND status = 'approved'
      AND (
        (valid_until IS NOT NULL AND valid_until <= now())
        OR quote_snapshot_hash <> _current_hash
      )
  ) THEN
    RAISE EXCEPTION 'Aprovacao anterior nao vale mais (orcamento foi alterado ou aprovacao expirou). Solicite nova aprovacao ao coordenador.'
      USING ERRCODE = '23514';
  END IF;

  IF COALESCE(NEW.status, 'draft') = 'pending_approval' THEN
    RETURN NEW;
  END IF;

  _msg := 'Desconto de ' || ROUND(_real_discount_pct, 2)::text ||
          ' por cento acima do seu limite de ' || ROUND(_max_allowed, 2)::text ||
          ' por cento. Solicite aprovacao ao coordenador antes de salvar.';
  RAISE EXCEPTION '%', _msg USING ERRCODE = '23514';
END;
$function$;

COMMENT ON FUNCTION public.fn_quotes_validate_discount() IS
  'Valida alçada real; cross-user usa is_supervisor_or_above e preserva bypasses internos/expiração.';

DO $postcondition$
DECLARE
  _definition text;
BEGIN
  SELECT pg_get_functiondef('public.fn_quotes_validate_discount()'::regprocedure)
  INTO _definition;

  IF strpos(_definition, 'is_supervisor_or_above(_seller_id)') = 0
     OR strpos(_definition, 'auth.uid() IS NULL') = 0
     OR strpos(_definition, 'cron_expire') = 0
     OR strpos(_definition, 'pending_approval') = 0
     OR strpos(_definition, 'valid_until IS NULL OR valid_until > now()') = 0 THEN
    RAISE EXCEPTION 'Postcondition failed: reconciled fn_quotes_validate_discount body is incomplete';
  END IF;
  IF strpos(_definition, 'is_coord_or_above(_seller_id)') > 0 THEN
    RAISE EXCEPTION 'Postcondition failed: unsafe cross-user helper remains';
  END IF;
END
$postcondition$;

-- <<< END 20260828141200_forward_only_fn_quotes_validate_discount_cross_user.sql <<<

