  END IF;
END
$pre$;

REVOKE SELECT ON public.products FROM anon;
REVOKE SELECT ON public.product_kit_components FROM anon;
REVOKE SELECT ON public.kit_component_print_areas FROM anon;

GRANT SELECT (id, is_active, is_deleted)
