-- >>> BEGIN 20260902220900_fix_smoke_persist_signature_drift.sql >>>
-- Cron 32 (smoke_tests_monthly) falhava: fn_run_smoke_tests() foi simplificada
-- para TABLE(test_name, result), mas a persist ainda selecionava
-- test_category/details/duration_ms (colunas nullable em smoke_test_runs).
-- Aplicada em produção via MCP em 2026-09-02.
CREATE OR REPLACE FUNCTION public.fn_run_and_persist_smoke_tests()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ran_at timestamptz := now();
BEGIN
  -- Permite: pg_cron (current_user='postgres', auth.uid()=NULL)
  -- Permite: service_role (request.jwt.claim.role='service_role')
  -- Bloqueia: chamadas HTTP de usuários não-admin
  IF auth.uid() IS NOT NULL
     AND coalesce(current_setting('request.jwt.claim.role', true), '') NOT IN ('', 'service_role')
     AND NOT public.is_admin_or_above((SELECT auth.uid()))
  THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  INSERT INTO public.smoke_test_runs (ran_at, test_name, result)
  SELECT v_ran_at, test_name, result
  FROM public.fn_run_smoke_tests();
END
$function$;

-- <<< END 20260902220900_fix_smoke_persist_signature_drift.sql <<<

-- >>> BEGIN 20260902221000_fix_vacuum_cron_single_statement.sql >>>
-- Job "vacuum-high-dead-tuples" nunca executou: comando multi-statement roda
-- em bloco de transação no pg_cron e VACUUM é proibido ali. Um único statement
-- VACUUM com lista de tabelas executa fora de transação.
-- Validado em produção em 2026-09-02 com job temporário (2 runs succeeded).
-- Replay-safe: resolve o job pelo jobname (jobid varia entre ambientes) e
-- é no-op com NOTICE onde o job não existir.
DO $$
DECLARE
  v_jobid bigint;
BEGIN
  SELECT jobid INTO v_jobid
  FROM cron.job
  WHERE jobname = 'vacuum-high-dead-tuples';

  IF v_jobid IS NULL THEN
    RAISE NOTICE 'job vacuum-high-dead-tuples ausente neste ambiente — nada a alterar';
    RETURN;
  END IF;

  PERFORM cron.alter_job(
    v_jobid,
    command => 'VACUUM ANALYZE public.mv_product_images_audit, public.mv_stock_rupture_alert, public.stock_snapshots, public.stock_daily_summary'
  );
END $$;

-- <<< END 20260902221000_fix_vacuum_cron_single_statement.sql <<<

