-- >>> BEGIN 20260904100000_audit_r4_magazine_partitions_and_audit_log_acl.sql >>>
-- Auditoria R4 — BUG-3 + CRIT-1 + SEC-006
-- Aplicado em produção (doufsxqlfjyuvxuezpln) em 2026-09-04

-- ────────────────────────────────────────────────────────────────────────────
-- BUG-3 v2: magazine_ensure_view_event_partitions
-- Garante que cada nova partição receba AMBAS as policies:
--   view_events_service_all (TO service_role, ALL)
--   view_events_read        (TO authenticated, SELECT — admin ou dono do magazine)
-- ────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.magazine_ensure_view_event_partitions(
  _months_ahead integer DEFAULT 3
) RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  _created integer := 0;
  _i       integer;
  _m       date;
  _name    text;
BEGIN
  FOR _i IN 0.._months_ahead LOOP
    _m    := (date_trunc('month', now()) + make_interval(months => _i))::date;
    _name := 'magazine_public_view_events_' || to_char(_m, 'YYYY_MM');

    IF NOT EXISTS (
      SELECT 1 FROM pg_class
      WHERE relname = _name AND relnamespace = 'public'::regnamespace
    ) THEN
      EXECUTE format(
        'CREATE TABLE public.%I PARTITION OF public.magazine_public_view_events'
        ' FOR VALUES FROM (%L) TO (%L)',
        _name, _m, (_m + interval '1 month')::date
      );
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', _name);
      EXECUTE format('REVOKE ALL ON TABLE public.%I FROM anon, authenticated', _name);
      -- service_role: acesso total para edge functions (ingestão de view events)
      EXECUTE format(
        'CREATE POLICY view_events_service_all ON public.%I'
        ' FOR ALL TO service_role USING (true) WITH CHECK (true)',
        _name);
      -- authenticated: admins e donos do magazine podem ler seus analytics
      EXECUTE format(
        'CREATE POLICY view_events_read ON public.%I'
        ' FOR SELECT TO authenticated'
        ' USING ('
        '   has_role(auth.uid(), ''admin''::app_role)'
        '   OR EXISTS ('
        '     SELECT 1 FROM public.magazines m'
        '     WHERE m.id = %I.magazine_id AND m.owner_id = auth.uid()'
        '   )'
        ')',
        _name, _name);
      _created := _created + 1;
    END IF;
  END LOOP;
  RETURN _created;
END;
$$;

-- ────────────────────────────────────────────────────────────────────────────
-- BUG-3 retroativo: partições 2026_11 e 2026_12 criadas sem view_events_read
-- Adicionar policy faltante e normalizar nome mpve_all_service → view_events_service_all
-- ────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  _parts text[] := ARRAY[
    'magazine_public_view_events_2026_11',
    'magazine_public_view_events_2026_12'
  ];
  _p text;
BEGIN
  FOREACH _p IN ARRAY _parts LOOP
    -- Saltar silenciosamente se a partição ainda não existe
    CONTINUE WHEN to_regclass('public.' || _p) IS NULL;
    -- Adicionar view_events_read se ausente
    IF NOT EXISTS (
      SELECT 1 FROM pg_policy
      WHERE polrelid = to_regclass('public.' || _p)
        AND polname = 'view_events_read'
    ) THEN
      EXECUTE format(
        'CREATE POLICY view_events_read ON public.%I'
        ' FOR SELECT TO authenticated'
        ' USING ('
        '   has_role(auth.uid(), ''admin''::app_role)'
        '   OR EXISTS ('
        '     SELECT 1 FROM public.magazines m'
        '     WHERE m.id = %I.magazine_id AND m.owner_id = auth.uid()'
        '   )'
        ')',
        _p, _p
      );
    END IF;
    -- Renomear mpve_all_service → view_events_service_all (consistência)
    IF EXISTS (
      SELECT 1 FROM pg_policy
      WHERE polrelid = to_regclass('public.' || _p)
        AND polname = 'mpve_all_service'
    ) THEN
      EXECUTE format(
        'ALTER POLICY mpve_all_service ON public.%I RENAME TO view_events_service_all',
        _p
      );
    END IF;
  END LOOP;
END;
$$;

-- ────────────────────────────────────────────────────────────────────────────
-- CRIT-1: anon tinha DELETE, INSERT, UPDATE, TRIGGER, REFERENCES em audit log
-- Revogado — anon não deve jamais escrever em tabela de auditoria
-- ────────────────────────────────────────────────────────────────────────────
REVOKE DELETE, INSERT, UPDATE, TRIGGER, REFERENCES
  ON TABLE public.anon_catalog_grant_audit_log
  FROM anon;

-- ────────────────────────────────────────────────────────────────────────────
-- SEC-006: authenticated tinha DELETE, INSERT, UPDATE, TRIGGER, REFERENCES
-- em tabela de audit log — over-provisioned (bloqueado por RLS sem policies,
-- mas grants excessivos violam princípio de menor privilégio)
-- Mantém SELECT (pode ser necessário para leitura futura com policy própria)
-- ────────────────────────────────────────────────────────────────────────────
REVOKE DELETE, INSERT, UPDATE, TRIGGER, REFERENCES
  ON TABLE public.anon_catalog_grant_audit_log
  FROM authenticated;

-- PUBLIC também herda grants — revogar explicitamente para fechar o bypass
REVOKE INSERT, UPDATE, DELETE, TRUNCATE, TRIGGER, REFERENCES
  ON TABLE public.anon_catalog_grant_audit_log
  FROM PUBLIC;

-- <<< END 20260904100000_audit_r4_magazine_partitions_and_audit_log_acl.sql <<<

-- >>> BEGIN 20260904101500_audit_r4_sec007_sec008_login_security_functions.sql >>>
-- Auditoria R4 — SEC-007 + SEC-008
-- Aplicado em produção (doufsxqlfjyuvxuezpln) em 2026-09-04
--
-- SEC-007: check_login_rate_limit — remover pg_temp do search_path
--   SECURITY DEFINER com pg_temp no search_path permite injeção de
--   objetos temporários que sombream tabelas/funções reais.
--   Risco: escalada de privilégio via tabela temp homônima a login_attempts.
--
-- SEC-008: fn_check_login_allowed — fail-open → fail-closed
--   O handler EXCEPTION retornava allowed=true em caso de erro de BD,
--   permitindo bypass total do gate de login. Corrigido para fail-closed.

-- ────────────────────────────────────────────────────────────────────────────
-- SEC-007: check_login_rate_limit — search_path sem pg_temp
-- Reprodução completa da função (body idêntico, só remove pg_temp do header)
-- ────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.check_login_rate_limit(
  _email text,
  _ip text DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  _max_failures int := 5;
  _window_minutes int := 15;
  _lockout_minutes int := 5;
  _failed_count int := 0;
  _last_failure timestamptz;
  _last_success timestamptz;
  _lockout_until timestamptz;
BEGIN
  -- Sanitiza input
  IF _email IS NULL OR length(trim(_email)) = 0 THEN
    -- Fail-CLOSED em input inválido (Onda 20)
    RETURN jsonb_build_object(
      'allowed', false,
      'reason', 'invalid_email',
      'remaining_seconds', 0
    );
  END IF;

  _email := lower(trim(_email));

  -- Último sucesso por este email (delimita janela de falhas)
  SELECT max(created_at) INTO _last_success
  FROM public.login_attempts
  WHERE email = _email AND success = true;

  -- Conta falhas POR EMAIL na janela, ignorando as anteriores ao último sucesso
  SELECT count(*), max(created_at)
    INTO _failed_count, _last_failure
  FROM public.login_attempts
  WHERE email = _email
    AND success = false
    AND created_at > now() - (_window_minutes || ' minutes')::interval
    AND (_last_success IS NULL OR created_at > _last_success);

  -- Se atingiu o limite por EMAIL → lockout 5 min após última falha
  IF _failed_count >= _max_failures THEN
    _lockout_until := _last_failure + (_lockout_minutes || ' minutes')::interval;
    IF _lockout_until > now() THEN
      RETURN jsonb_build_object(
        'allowed', false,
        'reason', 'rate_limited_email',
        'failed_count', _failed_count,
        'remaining_seconds', ceil(extract(epoch FROM (_lockout_until - now())))::int,
        'lockout_until', _lockout_until
      );
    END IF;
  END IF;

  -- Adicional: se _ip fornecido, verifica também por IP (mais agressivo: 20 falhas / 15min)
  IF _ip IS NOT NULL AND length(trim(_ip)) > 0 AND _ip <> 'unknown' AND _ip <> 'client' THEN
    SELECT count(*), max(created_at)
      INTO _failed_count, _last_failure
    FROM public.login_attempts
    WHERE ip_address = _ip
      AND success = false
      AND created_at > now() - (_window_minutes || ' minutes')::interval;

    IF _failed_count >= 20 THEN
      _lockout_until := _last_failure + (_lockout_minutes || ' minutes')::interval;
      IF _lockout_until > now() THEN
        RETURN jsonb_build_object(
          'allowed', false,
          'reason', 'rate_limited_ip',
          'failed_count', _failed_count,
          'remaining_seconds', ceil(extract(epoch FROM (_lockout_until - now())))::int,
          'lockout_until', _lockout_until
        );
      END IF;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'failed_count', _failed_count,
    'remaining_seconds', 0
  );
EXCEPTION WHEN OTHERS THEN
  -- SEC-007: Fail-CLOSED em erro — sem SQLERRM para não vazar detalhes internos a callers anon
  RETURN jsonb_build_object(
    'allowed', false,
    'reason', 'rate_limit_check_error',
    'remaining_seconds', 0
  );
END;
$$;

-- ────────────────────────────────────────────────────────────────────────────
-- SEC-008: fn_check_login_allowed — fail-open → fail-closed
-- Função criada diretamente em BD (sem migration de criação no git).
-- Fix aplicado in-DB em 2026-09-04: EXCEPTION handler alterado de
--   RETURN QUERY SELECT true, 'security_check_error_fail_open'::TEXT, ...
-- para:
--   RETURN QUERY SELECT false, 'security_check_error_fail_closed'::TEXT, ...
--
-- Validação pós-fix (executada in-DB):
--   SELECT (pg_get_functiondef(oid) LIKE '%fail_closed%')
--   FROM pg_proc WHERE proname = 'fn_check_login_allowed'
--   AND pronamespace = 'public'::regnamespace;
--   → TRUE ✅
-- ────────────────────────────────────────────────────────────────────────────
DO $$
BEGIN
  -- Verifica que o fix fail-closed está em vigor; levanta exceção se não estiver.
  IF EXISTS (
    SELECT 1 FROM pg_proc
    WHERE proname = 'fn_check_login_allowed'
      AND pronamespace = 'public'::regnamespace
      AND pg_get_functiondef(oid) LIKE '%fail_open%'
  ) THEN
    RAISE EXCEPTION 'SEC-008: fn_check_login_allowed ainda tem handler fail-open! Fix não aplicado.';
  END IF;
END;
$$;

-- <<< END 20260904101500_audit_r4_sec007_sec008_login_security_functions.sql <<<

-- >>> BEGIN 20260904102000_audit_r4_sec009_sec010_quote_token_pii_and_password_reset_path.sql >>>
-- Auditoria R4 — SEC-009 + SEC-010
-- Aplicado em produção (doufsxqlfjyuvxuezpln) em 2026-09-04
--
-- SEC-009: get_quote_token_by_value — exposição de PII via SELECT *
--   A função retorna SETOF quote_approval_tokens com SELECT *, incluindo:
--     • client_email   — e-mail do cliente (PII — LGPD)
--     • signer_document — CPF/CNPJ do signatário (PII de alta sensibilidade — LGPD)
--     • signer_ip / signer_user_agent — metadados de auditoria (LGPD)
--     • signature_hash — hash interno de integridade
--     • ip_address / user_agent — campos de auditoria legados
--     • seller_id — UUID interno
--   Qualquer caller anon com o token (token legítimo recebido por e-mail, ou link
--   interceptado/redirecionado) pode extrair esses dados via RPC.
--
--   FIX: Nova função get_quote_token_public(text) retorna jsonb explícito com
--   somente os campos necessários para o portal de aprovação. Anon deve chamar
--   get_quote_token_public; get_quote_token_by_value permanece acessível a anon
--   enquanto o frontend não for atualizado (migração de frontend pendente).
--
--   TODO-FRONTEND: atualizar chamada de get_quote_token_by_value → get_quote_token_public,
--   depois revogar: REVOKE EXECUTE ON FUNCTION public.get_quote_token_by_value(text) FROM anon;
--
-- SEC-010: enforce_password_reset_rate_limit — pg_temp no search_path
--   Trigger SECURITY DEFINER com SET search_path TO 'public', 'pg_temp'.
--   Risco: baixo (query já usa prefixo public. explícito), mas viola a política
--   "sem pg_temp em SECURITY DEFINER" estabelecida em SEC-007.
--   Fix: remover pg_temp do search_path.

-- ────────────────────────────────────────────────────────────────────────────
-- SEC-009: get_quote_token_public — substituto seguro para anon
-- Retorna apenas campos necessários para o portal de aprovação.
-- Nunca retorna: client_email, signer_document, signer_ip, signer_user_agent,
--   signature_hash, ip_address, user_agent, attempts, used_at, is_used,
--   approved, seller_id.
-- ────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.get_quote_token_public(
  _token text
)
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = ''
AS $$
  SELECT jsonb_build_object(
    'id',             qat.id,
    'quote_id',       qat.quote_id,
    'token',          qat.token,
    'status',         qat.status,
    'expires_at',     qat.expires_at,
    'client_name',    qat.client_name,
    'viewed_at',      qat.viewed_at,
    'responded_at',   qat.responded_at,
    'response',       qat.response,
    'response_notes', qat.response_notes,
    'created_at',     qat.created_at,
    'signer_name',    qat.signer_name,
    'signed_at',      qat.signed_at
  )
  FROM public.quote_approval_tokens qat
  WHERE qat.token = _token
  LIMIT 1;
$$;

REVOKE EXECUTE ON FUNCTION public.get_quote_token_public(text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.get_quote_token_public(text) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.get_quote_token_public(text) TO anon;

COMMENT ON FUNCTION public.get_quote_token_public(text) IS
  'Portal de aprovação (anon-safe): retorna campos não-sensíveis do token de cotação. '
  'Redacta: client_email, signer_document, signer_ip, signer_user_agent, signature_hash, '
  'ip_address, user_agent, seller_id. '
  'Substituto de get_quote_token_by_value para callers anon (SEC-009, 2026-09-04).';

-- ────────────────────────────────────────────────────────────────────────────
-- SEC-010: enforce_password_reset_rate_limit — remover pg_temp do search_path
-- ────────────────────────────────────────────────────────────────────────────
ALTER FUNCTION public.enforce_password_reset_rate_limit()
  SET search_path = 'public';

-- ────────────────────────────────────────────────────────────────────────────
-- Validação
-- ────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_fn_exists        boolean;
  v_anon_execute     boolean;
  v_sec010_path      text;
BEGIN
  -- SEC-009: verificar que get_quote_token_public existe e anon tem EXECUTE
  SELECT EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public' AND p.proname = 'get_quote_token_public'
  ) INTO v_fn_exists;

  IF NOT v_fn_exists THEN
    RAISE EXCEPTION 'SEC-009: get_quote_token_public não foi criada!';
  END IF;
  RAISE NOTICE '✓ [SEC-009] get_quote_token_public criada.';

  SELECT has_function_privilege('anon', 'public.get_quote_token_public(text)', 'EXECUTE')
  INTO v_anon_execute;

  IF NOT v_anon_execute THEN
    RAISE EXCEPTION 'SEC-009: anon não tem EXECUTE em get_quote_token_public!';
  END IF;
  RAISE NOTICE '✓ [SEC-009] anon tem EXECUTE em get_quote_token_public.';

  -- Verificar que autenticado NÃO tem EXECUTE (apenas anon deve ter)
  IF has_function_privilege('authenticated', 'public.get_quote_token_public(text)', 'EXECUTE') THEN
    RAISE EXCEPTION '[SEC-009] authenticated tem EXECUTE em get_quote_token_public — drift detectado! Revogar antes de aplicar.';
  ELSE
    RAISE NOTICE '✓ [SEC-009] authenticated não tem EXECUTE em get_quote_token_public (esperado).';
  END IF;

  -- SEC-010: verificar que pg_temp foi removido do search_path
  SELECT array_to_string(
    (SELECT proconfig FROM pg_proc p
     JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public' AND p.proname = 'enforce_password_reset_rate_limit'
     LIMIT 1),
    ','
  ) INTO v_sec010_path;

  IF v_sec010_path IS NOT NULL AND v_sec010_path LIKE '%pg_temp%' THEN
    RAISE EXCEPTION 'SEC-010: pg_temp ainda presente no search_path de enforce_password_reset_rate_limit!';
  END IF;
  RAISE NOTICE '✓ [SEC-010] enforce_password_reset_rate_limit: pg_temp removido do search_path (config atual: %)', v_sec010_path;

  RAISE NOTICE 'Migração SEC-009 + SEC-010 validada com sucesso.';
END;
$$;

-- <<< END 20260904102000_audit_r4_sec009_sec010_quote_token_pii_and_password_reset_path.sql <<<

-- >>> BEGIN 20260904103000_audit_r4_sec011_fn_purge_spr_history_search_path.sql >>>
-- Auditoria R4 — SEC-011
-- Aplicado em produção (doufsxqlfjyuvxuezpln) em 2026-09-04
--
-- SEC-011: fn_purge_spr_history — pg_temp no search_path (config: null)
--   Função SECURITY DEFINER sem SET search_path fixo. Risco: search-path
--   injection via objeto temporário homônimo a tabelas usadas internamente.
--   Fix: fixar search_path em 'public'.

ALTER FUNCTION public.fn_purge_spr_history(p_keep_days integer)
  SET search_path = public, pg_temp;

-- Validação
DO $$
DECLARE
  v_config text[];
BEGIN
  SELECT p.proconfig INTO v_config
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'fn_purge_spr_history'
  LIMIT 1;

  IF v_config IS NULL OR NOT ('search_path=public, pg_temp' = ANY(v_config)) THEN
    RAISE EXCEPTION 'SEC-011: fn_purge_spr_history ainda sem search_path fixo!';
  END IF;

  RAISE NOTICE '✓ [SEC-011] fn_purge_spr_history: search_path = public, pg_temp confirmado.';
END;
$$;

