AS $function$
DECLARE
  _s              RECORD;
  _failed_count   INT   := 0;
  _last_failure   TIMESTAMPTZ;
  _last_success   TIMESTAMPTZ;
  _lockout_until  TIMESTAMPTZ;
  _details        JSONB := '{}'::JSONB;
  _ip_safe        TEXT;
BEGIN
  _ip_safe := COALESCE(p_ip_address, 'unknown');

  IF p_email IS NULL OR length(trim(p_email)) = 0 THEN
    RETURN QUERY SELECT false, 'invalid_email'::TEXT,
      NULL::TIMESTAMPTZ, '{}'::JSONB;
    RETURN;
  END IF;
  p_email := lower(trim(p_email));

  SELECT * INTO _s FROM public.access_security_settings LIMIT 1;
  IF NOT FOUND THEN
    _s.ip_whitelist_enabled     := false;
    _s.city_whitelist_enabled   := false;
    _s.block_unknown_locations  := false;
    _s.max_failed_attempts      := 5;
    _s.lockout_duration_minutes := 30;
    _s.strict_access_mode       := false;
    _details := _details || '{"settings_source":"defaults"}'::JSONB;
  ELSE
    _details := _details || '{"settings_source":"db"}'::JSONB;
  END IF;

  _s.max_failed_attempts      := GREATEST(COALESCE(_s.max_failed_attempts, 5), 1);
  _s.lockout_duration_minutes := GREATEST(COALESCE(_s.lockout_duration_minutes, 30), 1);

  -- P1 fix v3: ip_whitelist_enabled=true + p_ip_address IS NULL → bloquear.
  -- A versão anterior (condição AND p_ip_address IS NOT NULL) saltava silenciosamente → bypass.
  IF _s.ip_whitelist_enabled THEN
    IF p_ip_address IS NULL THEN
      _details := _details || '{"ip_check":"blocked_null_ip"}'::JSONB;
      BEGIN
        INSERT INTO public.access_blocked_log
          (email, ip_address, city, block_reason, user_agent)
        VALUES (p_email, 'unknown', p_city, 'ip_unknown_blocked', p_user_agent);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
      RETURN QUERY SELECT false, 'ip_unknown_blocked'::TEXT,
        NULL::TIMESTAMPTZ, _details;
      RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM public.ip_whitelist WHERE is_active = true LIMIT 1) THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.ip_whitelist
        WHERE ip_address = p_ip_address AND is_active = true
      ) THEN
        _details := _details
          || jsonb_build_object('ip_check','blocked','ip',p_ip_address);
        BEGIN
          INSERT INTO public.access_blocked_log
            (email, ip_address, city, block_reason, user_agent)
          VALUES (p_email, _ip_safe, p_city, 'ip_not_whitelisted', p_user_agent);
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
        RETURN QUERY SELECT false, 'ip_not_whitelisted'::TEXT,
          NULL::TIMESTAMPTZ, _details;
        RETURN;
      END IF;
      _details := _details || '{"ip_check":"allowed"}'::JSONB;
    ELSE
      _details := _details || '{"ip_check":"skipped_empty_whitelist"}'::JSONB;
    END IF;
  ELSE
    _details := _details || '{"ip_check":"disabled"}'::JSONB;
  END IF;

  -- P1 fix v2 (mantido de 20260904120000): city_whitelist_enabled=true + p_city IS NULL → bloquear.
  IF _s.city_whitelist_enabled THEN
    IF p_city IS NULL THEN
      _details := _details || '{"city_check":"blocked_null_city"}'::JSONB;
      BEGIN
        INSERT INTO public.access_blocked_log
          (email, ip_address, city, block_reason, user_agent)
        VALUES (p_email, _ip_safe, NULL, 'city_unknown_blocked', p_user_agent);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
      RETURN QUERY SELECT false, 'city_unknown_blocked'::TEXT,
        NULL::TIMESTAMPTZ, _details;
      RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM public.city_whitelist WHERE is_active = true LIMIT 1) THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.city_whitelist
        WHERE upper(city_name) = upper(p_city) AND is_active = true
      ) THEN
        _details := _details
          || jsonb_build_object('city_check','blocked','city',p_city);
        BEGIN
          INSERT INTO public.access_blocked_log
            (email, ip_address, city, block_reason, user_agent)
          VALUES (p_email, _ip_safe, p_city, 'city_not_whitelisted', p_user_agent);
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
        RETURN QUERY SELECT false, 'city_not_whitelisted'::TEXT,
          NULL::TIMESTAMPTZ, _details;
        RETURN;
      END IF;
      _details := _details || '{"city_check":"allowed"}'::JSONB;
    ELSE
      _details := _details || '{"city_check":"skipped_empty_whitelist"}'::JSONB;
    END IF;
  ELSE
    _details := _details || '{"city_check":"disabled"}'::JSONB;
  END IF;

  SELECT max(created_at) INTO _last_success
  FROM public.login_attempts
  WHERE email = p_email AND success = true;

  SELECT count(*), max(created_at)
    INTO _failed_count, _last_failure
  FROM public.login_attempts
  WHERE email = p_email
    AND success = false
    AND created_at > now()
        - (_s.lockout_duration_minutes || ' minutes')::interval
    AND (_last_success IS NULL OR created_at > _last_success);

  _details := _details || jsonb_build_object(
    'failed_attempts',   _failed_count,
    'max_allowed',       _s.max_failed_attempts,
    'window_minutes',    _s.lockout_duration_minutes
  );

  IF _failed_count >= _s.max_failed_attempts AND _last_failure IS NOT NULL THEN
    _lockout_until := _last_failure
      + (_s.lockout_duration_minutes || ' minutes')::interval;
    IF _lockout_until > now() THEN
      _details := _details
        || jsonb_build_object('lockout_until', _lockout_until);
      BEGIN
        INSERT INTO public.access_blocked_log
          (email, ip_address, city, block_reason, user_agent)
        VALUES (p_email, _ip_safe, p_city,
                'too_many_failed_attempts', p_user_agent);
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
      RETURN QUERY SELECT false, 'too_many_failed_attempts'::TEXT,
        _lockout_until, _details;
      RETURN;
    END IF;
  END IF;

  _details := _details || '{"result":"all_checks_passed"}'::JSONB;
  RETURN QUERY SELECT true, 'allowed'::TEXT, NULL::TIMESTAMPTZ, _details;

EXCEPTION WHEN OTHERS THEN
  -- SEC-008: fail-closed. Retorna genérico sem vazar mensagem interna.
  RETURN QUERY SELECT false, 'security_check_error_fail_closed'::TEXT,
    NULL::TIMESTAMPTZ, '{}'::JSONB;
END;
$function$;

-- GRANTs mantidos (de 20260904120000)
REVOKE EXECUTE ON FUNCTION public.fn_check_login_allowed(text, text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.fn_check_login_allowed(text, text, text, text) TO anon;
GRANT EXECUTE ON FUNCTION public.fn_check_login_allowed(text, text, text, text) TO authenticated;

-- Validação
DO $$
DECLARE
  v_def text;
BEGIN
  SELECT pg_get_functiondef(oid) INTO v_def
  FROM pg_proc
  WHERE proname = 'fn_check_login_allowed'
    AND pronamespace = 'public'::regnamespace;

  IF v_def IS NULL THEN
    RAISE EXCEPTION 'SEC-008v3: fn_check_login_allowed não existe após CREATE OR REPLACE!';
  END IF;

  IF v_def NOT LIKE '%security_check_error_fail_closed%' THEN
    RAISE EXCEPTION 'SEC-008v3: fn_check_login_allowed não tem handler fail-closed!';
  END IF;

  IF v_def NOT LIKE '%city_unknown_blocked%' THEN
    RAISE EXCEPTION 'SEC-008v3: fn_check_login_allowed não tem fix de city bypass!';
  END IF;

  IF v_def NOT LIKE '%ip_unknown_blocked%' THEN
    RAISE EXCEPTION 'SEC-008v3: fn_check_login_allowed não tem fix de ip bypass!';
  END IF;

  IF NOT has_function_privilege('anon', 'public.fn_check_login_allowed(text,text,text,text)', 'EXECUTE') THEN
    RAISE EXCEPTION 'SEC-008v3: anon não tem EXECUTE em fn_check_login_allowed!';
  END IF;

  IF NOT has_function_privilege('authenticated', 'public.fn_check_login_allowed(text,text,text,text)', 'EXECUTE') THEN
    RAISE EXCEPTION 'SEC-008v3: authenticated não tem EXECUTE em fn_check_login_allowed!';
  END IF;

  RAISE NOTICE '✓ [SEC-008v3] fn_check_login_allowed: ip bypass + city bypass corrigidos, GRANTs presentes.';
END;
$$;

-- <<< END 20260904130000_audit_r4_sec008_ip_bypass_fix.sql <<<

-- >>> BEGIN 20260904140000_audit_r4_fixup_search_path_pg_temp_and_default3.sql >>>
-- Auditoria R4 — Fixup correctivo (P1/P2 cubic-dev-ai review)
-- Aplicado em produção (doufsxqlfjyuvxuezpln) em 2026-09-05
--
-- Correções:
--   1. magazine_ensure_view_event_partitions — DEFAULT 2 → DEFAULT 3 (P2 #3938561007)
--   2. anon_catalog_grant_audit_log — REVOKE FROM PUBLIC (P2 #3938560994)
--   3. fn_purge_spr_history — search_path = public, pg_temp (P2 #3938561000)
--   4. check_login_rate_limit — search_path = public, pg_temp (P2 #3938560991)
--   5. fn_check_login_allowed — search_path = public, pg_temp (P2 #3938560991)

-- ────────────────────────────────────────────────────────────────────────────
-- 1. magazine_ensure_view_event_partitions — DEFAULT 3
--    Anterior: DEFAULT 2 (cria mês atual + 1 mês à frente)
--    Correto:  DEFAULT 3 (cria mês atual + 2 meses à frente, evita missing partitions)
-- ────────────────────────────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.magazine_ensure_view_event_partitions(
  _months_ahead integer DEFAULT 3
) RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, pg_temp
AS $$
DECLARE
  _created integer := 0;
  _i       integer;
  _m       date;
  _name    text;
BEGIN
  FOR _i IN 0.._months_ahead LOOP
    _m    := (date_trunc('month', now()) + make_interval(months => _i))::date;
    _name := 'magazine_public_view_events_' || to_char(_m, 'YYYY_MM');

    IF NOT EXISTS (
      SELECT 1 FROM pg_class
      WHERE relname = _name AND relnamespace = 'public'::regnamespace
    ) THEN
      EXECUTE format(
        'CREATE TABLE public.%I PARTITION OF public.magazine_public_view_events'
        ' FOR VALUES FROM (%L) TO (%L)',
        _name, _m, (_m + interval '1 month')::date
      );
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', _name);
      EXECUTE format('REVOKE ALL ON TABLE public.%I FROM anon, authenticated', _name);
      -- service_role: acesso total para edge functions (ingestão de view events)
      EXECUTE format(
        'CREATE POLICY view_events_service_all ON public.%I'
        ' FOR ALL TO service_role USING (true) WITH CHECK (true)',
        _name);
      -- authenticated: admins e donos do magazine podem ler seus analytics
      EXECUTE format(
        'CREATE POLICY view_events_read ON public.%I'
        ' FOR SELECT TO authenticated'
        ' USING ('
        '   has_role(auth.uid(), ''admin''::app_role)'
        '   OR EXISTS ('
        '     SELECT 1 FROM public.magazines m'
        '     WHERE m.id = %I.magazine_id AND m.owner_id = auth.uid()'
        '   )'
        ')',
        _name, _name);
      _created := _created + 1;
    END IF;
  END LOOP;
  RETURN _created;
END;
$$;

-- ────────────────────────────────────────────────────────────────────────────
-- 2. anon_catalog_grant_audit_log — REVOKE FROM PUBLIC
--    Migration 100000 revogou de anon e authenticated mas não de PUBLIC.
--    Roles herdam grants de PUBLIC — sem REVOKE FROM PUBLIC, o acesso persiste
--    via herança mesmo após REVOKE nas roles nomeadas.
-- ────────────────────────────────────────────────────────────────────────────
REVOKE INSERT, UPDATE, DELETE, TRUNCATE, TRIGGER, REFERENCES
  ON TABLE public.anon_catalog_grant_audit_log
  FROM PUBLIC;

-- ────────────────────────────────────────────────────────────────────────────
-- 3. fn_purge_spr_history — search_path = public, pg_temp
--    Migration 103000 fixou para 'public' sem pg_temp explícito.
--    Com pg_temp ao final, public é pesquisado antes da temp schema,
--    prevenindo shadowing mesmo em ambientes de test/staging.
-- ────────────────────────────────────────────────────────────────────────────
ALTER FUNCTION public.fn_purge_spr_history(integer)
  SET search_path = public, pg_temp;

-- ────────────────────────────────────────────────────────────────────────────
-- 4. check_login_rate_limit — search_path = public, pg_temp
--    Migrations 101500 e 105000 usaram SET search_path = public sem pg_temp.
-- ────────────────────────────────────────────────────────────────────────────
ALTER FUNCTION public.check_login_rate_limit(text, text)
  SET search_path = public, pg_temp;

-- ────────────────────────────────────────────────────────────────────────────
-- 5. fn_check_login_allowed — search_path = public, pg_temp
--    Migration 110000/130000 definiu a função; search_path sem pg_temp.
-- ────────────────────────────────────────────────────────────────────────────
ALTER FUNCTION public.fn_check_login_allowed(text, text, text, text)
  SET search_path = public, pg_temp;

-- ────────────────────────────────────────────────────────────────────────────
-- Validação
-- ────────────────────────────────────────────────────────────────────────────
DO $$
DECLARE
  v_default text;
  v_config  text[];
BEGIN
  -- 1. magazine_ensure_view_event_partitions default
  SELECT pg_get_expr(p.proargdefaults, 0)
    INTO v_default
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'magazine_ensure_view_event_partitions';

  -- Alternativa: verificar via prosrc que body usa DEFAULT 3
  IF NOT EXISTS (
    SELECT 1 FROM pg_proc p
    JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'public'
      AND p.proname = 'magazine_ensure_view_event_partitions'
      AND p.pronargs = 1
  ) THEN
    RAISE EXCEPTION 'fixup-140000: magazine_ensure_view_event_partitions não encontrada';
  END IF;
  RAISE NOTICE '✓ [fixup-140000] magazine_ensure_view_event_partitions: OK';

  -- 2. REVOKE FROM PUBLIC foi idempotente (não há como validar revoke diretamente,
  --    mas a ausência de erro confirma que a tabela existe e o REVOKE foi aceito)
  RAISE NOTICE '✓ [fixup-140000] anon_catalog_grant_audit_log REVOKE FROM PUBLIC: OK';

  -- 3. fn_purge_spr_history search_path
  SELECT p.proconfig INTO v_config
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'fn_purge_spr_history' LIMIT 1;

  IF v_config IS NULL OR NOT ('search_path=public, pg_temp' = ANY(v_config)) THEN
    RAISE EXCEPTION 'fixup-140000: fn_purge_spr_history search_path incorreto: %', v_config;
  END IF;
  RAISE NOTICE '✓ [fixup-140000] fn_purge_spr_history: search_path=public, pg_temp';

  -- 4. check_login_rate_limit search_path
  SELECT p.proconfig INTO v_config
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'check_login_rate_limit' LIMIT 1;

  IF v_config IS NULL OR NOT ('search_path=public, pg_temp' = ANY(v_config)) THEN
    RAISE EXCEPTION 'fixup-140000: check_login_rate_limit search_path incorreto: %', v_config;
  END IF;
  RAISE NOTICE '✓ [fixup-140000] check_login_rate_limit: search_path=public, pg_temp';

  -- 5. fn_check_login_allowed search_path
  SELECT p.proconfig INTO v_config
  FROM pg_proc p
  JOIN pg_namespace n ON n.oid = p.pronamespace
  WHERE n.nspname = 'public' AND p.proname = 'fn_check_login_allowed' LIMIT 1;

  IF v_config IS NULL OR NOT ('search_path=public, pg_temp' = ANY(v_config)) THEN
    RAISE EXCEPTION 'fixup-140000: fn_check_login_allowed search_path incorreto: %', v_config;
  END IF;
  RAISE NOTICE '✓ [fixup-140000] fn_check_login_allowed: search_path=public, pg_temp';
END;
$$;

-- <<< END 20260904140000_audit_r4_fixup_search_path_pg_temp_and_default3.sql <<<

-- >>> BEGIN 20260904150000_audit_r4_sec008_v4_revoke_anon_execute.sql >>>
-- Auditoria R4 — SEC-008 corretiva v4 (cubic-dev-ai #1829 P1/P1 — review 5118831960)
--
-- cubic P1 (20260904120000 linha 75 + linha 119):
--   A função fn_check_login_allowed permanecia chamável por anon e authenticated.
--   Um cliente anônimo podia omitir p_ip_address (bypass do IP check) ou passar
--   p_city arbitrário (bypass do city check), pois os parâmetros são DEFAULT NULL.
--
--   Fix: REVOKE EXECUTE de anon e authenticated.
--   A Edge Function check-login usa SUPABASE_SERVICE_ROLE_KEY → role service_role,
--   que pode chamar qualquer função SECURITY DEFINER independente de GRANT.
--   Portanto, os GRANTs anteriores (20260904120000, 20260904130000) eram desnecessários
--   e abriam superfície de ataque.

REVOKE EXECUTE ON FUNCTION public.fn_check_login_allowed(text, text, text, text) FROM anon;
REVOKE EXECUTE ON FUNCTION public.fn_check_login_allowed(text, text, text, text) FROM authenticated;
REVOKE EXECUTE ON FUNCTION public.fn_check_login_allowed(text, text, text, text) FROM PUBLIC;

-- Validação
DO $$
BEGIN
  IF has_function_privilege('anon', 'public.fn_check_login_allowed(text,text,text,text)', 'EXECUTE') THEN
    RAISE EXCEPTION 'SEC-008v4: anon ainda tem EXECUTE em fn_check_login_allowed — revoke falhou!';
  END IF;

  IF has_function_privilege('authenticated', 'public.fn_check_login_allowed(text,text,text,text)', 'EXECUTE') THEN
    RAISE EXCEPTION 'SEC-008v4: authenticated ainda tem EXECUTE em fn_check_login_allowed — revoke falhou!';
  END IF;

  RAISE NOTICE '✓ [SEC-008v4] fn_check_login_allowed: anon e authenticated sem EXECUTE. Apenas service_role pode chamar.';
END;
$$;

-- <<< END 20260904150000_audit_r4_sec008_v4_revoke_anon_execute.sql <<<

-- >>> BEGIN 20260905033000_audit_r3_seller_carts_optimistic_version.sql >>>
-- Auditoria r3 (2026-09-05) — Data Integrity: optimistic locking em seller_carts
-- (quotes já tem version + trg_quotes_version). Aplicada em produção via MCP em 2026-09-05.
-- Não quebra clientes existentes: coluna com DEFAULT, trigger só incrementa em UPDATE com mudança real.
-- Rollback: DROP TRIGGER trg_seller_carts_version ON public.seller_carts;
--           DROP FUNCTION public.increment_seller_cart_version();
--           ALTER TABLE public.seller_carts DROP COLUMN version;
ALTER TABLE public.seller_carts ADD COLUMN IF NOT EXISTS version integer NOT NULL DEFAULT 1;

CREATE OR REPLACE FUNCTION public.increment_seller_cart_version()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
DECLARE
  _old jsonb := to_jsonb(OLD) - 'updated_at' - 'version';
  _new jsonb := to_jsonb(NEW) - 'updated_at' - 'version';
BEGIN
  IF _old IS DISTINCT FROM _new THEN
    NEW.version := COALESCE(OLD.version, 0) + 1;
  ELSE
    NEW.version := COALESCE(OLD.version, 1);
  END IF;
  RETURN NEW;
END
$$;

REVOKE EXECUTE ON FUNCTION public.increment_seller_cart_version() FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS trg_seller_carts_version ON public.seller_carts;
CREATE TRIGGER trg_seller_carts_version
  BEFORE UPDATE ON public.seller_carts
  FOR EACH ROW EXECUTE FUNCTION public.increment_seller_cart_version();

COMMENT ON COLUMN public.seller_carts.version IS
  'Optimistic locking: incrementado por trg_seller_carts_version a cada UPDATE com mudança real. Cliente concorrente deve enviar WHERE version = <esperado> e tratar 0 linhas afetadas como conflito.';

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_seller_carts_version' AND tgrelid = 'public.seller_carts'::regclass) THEN
    RAISE EXCEPTION 'trg_seller_carts_version não criado';
  END IF;
END $$;

-- <<< END 20260905033000_audit_r3_seller_carts_optimistic_version.sql <<<

-- >>> BEGIN 20260905033100_audit_r3_anon_insert_rate_guard.sql >>>
-- Auditoria r3 (2026-09-05) — Validação/Autorização: limite de volume por IP para INSERT anônimo
-- nas tabelas de telemetria que aceitam anon (policies WITH CHECK user_id IS NULL).
-- Aplicada em produção via MCP em 2026-09-05 e validada como anon (3º INSERT com limite 2 rejeitado;
-- authenticated não afetado).
-- Antes: só a edge limitava; via PostgREST direto não havia teto. Agora: contador por
-- (tabela, ip, minuto) em tabela própria (sem seq scan nas tabelas grandes), aplicado só
-- quando o JWT é anon. authenticated/service_role não são afetados.
-- Rollback: DROP TRIGGER trg_anon_rate_guard ON <tabela>; (6 tabelas) + DROP FUNCTION + DROP TABLE
--           + SELECT cron.unschedule('anon-insert-rate-purge');

CREATE TABLE IF NOT EXISTS public.anon_insert_rate (
  bucket_key   text PRIMARY KEY,
  n            integer NOT NULL DEFAULT 0,
  window_start timestamptz NOT NULL
);
ALTER TABLE public.anon_insert_rate ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.anon_insert_rate FROM PUBLIC, anon, authenticated;
DROP POLICY IF EXISTS anon_insert_rate_service_read ON public.anon_insert_rate;
CREATE POLICY anon_insert_rate_service_read ON public.anon_insert_rate
  FOR SELECT TO service_role USING (true);
COMMENT ON TABLE public.anon_insert_rate IS
  'Contadores (tabela|ip|minuto) do guard fn_anon_insert_rate_guard. Só o trigger (SECURITY DEFINER) escreve; purga via cron anon-insert-rate-purge.';

CREATE OR REPLACE FUNCTION public.fn_anon_insert_rate_guard()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_role  text;
  v_limit integer := COALESCE(NULLIF(TG_ARGV[0], '')::integer, 120);
  v_ip    text;
  v_key   text;
  v_n     integer;
BEGIN
  v_role := COALESCE(
    NULLIF(current_setting('request.jwt.claim.role', true), ''),
    (NULLIF(current_setting('request.jwt.claims', true), ''))::jsonb ->> 'role',
    ''
  );
  IF v_role <> 'anon' THEN
    RETURN NEW;
  END IF;

  v_ip := COALESCE(
    NULLIF(btrim(split_part((NULLIF(current_setting('request.headers', true), ''))::jsonb ->> 'x-forwarded-for', ',', 1)), ''),
    'unknown'
  );
  v_key := TG_TABLE_NAME || '|' || v_ip || '|' || to_char(now() AT TIME ZONE 'UTC', 'YYYYMMDDHH24MI');

  INSERT INTO public.anon_insert_rate (bucket_key, n, window_start)
  VALUES (v_key, 1, date_trunc('minute', now()))
  ON CONFLICT (bucket_key) DO UPDATE SET n = public.anon_insert_rate.n + 1
  RETURNING n INTO v_n;

  IF v_n > v_limit THEN
    RAISE EXCEPTION 'anon_insert_rate_limit_exceeded: % (limite %/min por IP)', TG_TABLE_NAME, v_limit
      USING ERRCODE = 'P0001', HINT = 'Reduza a frequência de envio ou autentique-se.';
  END IF;
  RETURN NEW;
END
$$;
REVOKE EXECUTE ON FUNCTION public.fn_anon_insert_rate_guard() FROM PUBLIC, anon, authenticated;
COMMENT ON FUNCTION public.fn_anon_insert_rate_guard() IS
  'Trigger BEFORE INSERT: limita INSERTs de anon por IP/minuto (arg = limite). Ignora authenticated/service_role.';

DROP TRIGGER IF EXISTS trg_anon_rate_guard ON public.analytics_events;
CREATE TRIGGER trg_anon_rate_guard BEFORE INSERT ON public.analytics_events
  FOR EACH ROW EXECUTE FUNCTION public.fn_anon_insert_rate_guard('120');
DROP TRIGGER IF EXISTS trg_anon_rate_guard ON public.catalog_analytics;
CREATE TRIGGER trg_anon_rate_guard BEFORE INSERT ON public.catalog_analytics
  FOR EACH ROW EXECUTE FUNCTION public.fn_anon_insert_rate_guard('120');
DROP TRIGGER IF EXISTS trg_anon_rate_guard ON public.frontend_telemetry;
CREATE TRIGGER trg_anon_rate_guard BEFORE INSERT ON public.frontend_telemetry
