-- Forward-only, prepared for explicit production approval. Do not apply implicitly.
CREATE OR REPLACE FUNCTION public.magazine_remove_items_atomic(
  p_magazine_id UUID,
  p_expected_updated_at TIMESTAMPTZ,
  p_item_ids UUID[]
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_owner UUID;
  v_status TEXT;
  v_updated_at TIMESTAMPTZ;
  v_matched INTEGER;
  v_removed INTEGER;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'magazine_auth_required' USING ERRCODE = '42501'; END IF;
  IF p_item_ids IS NULL OR cardinality(p_item_ids) NOT BETWEEN 1 AND 500 OR array_position(p_item_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'magazine_item_ids_invalid' USING ERRCODE = '22023';
  END IF;
  IF (SELECT COUNT(DISTINCT id) FROM unnest(p_item_ids) AS ids(id)) <> cardinality(p_item_ids) THEN
    RAISE EXCEPTION 'magazine_item_ids_duplicated' USING ERRCODE = '22023';
  END IF;

  SELECT owner_id, status::TEXT, updated_at INTO v_owner, v_status, v_updated_at
    FROM public.magazines WHERE id = p_magazine_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'magazine_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_owner <> v_actor AND NOT COALESCE(public.has_role(v_actor, 'admin'::public.app_role), FALSE) THEN
    RAISE EXCEPTION 'magazine_forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_status <> 'draft' THEN RAISE EXCEPTION 'magazine_not_editable' USING ERRCODE = '55000'; END IF;
  IF v_updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'magazine_edit_conflict' USING ERRCODE = '40001';
  END IF;

  SELECT COUNT(*) INTO v_matched FROM public.magazine_items
   WHERE magazine_id = p_magazine_id AND id = ANY(p_item_ids);
  IF v_matched <> cardinality(p_item_ids) THEN
    RAISE EXCEPTION 'magazine_item_not_found' USING ERRCODE = 'P0002';
  END IF;
  DELETE FROM public.magazine_items WHERE magazine_id = p_magazine_id AND id = ANY(p_item_ids);
  GET DIAGNOSTICS v_removed = ROW_COUNT;
  UPDATE public.magazines SET updated_at = clock_timestamp() WHERE id = p_magazine_id
  RETURNING updated_at INTO v_updated_at;
  RETURN jsonb_build_object('removed', v_removed, 'updated_at', v_updated_at);
END;
$$;

REVOKE ALL ON FUNCTION public.magazine_remove_items_atomic(UUID, TIMESTAMPTZ, UUID[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.magazine_remove_items_atomic(UUID, TIMESTAMPTZ, UUID[]) TO authenticated, service_role;

-- <<< END 20260909181100_magazine_remove_items_atomic.sql <<<

-- >>> BEGIN 20260909181200_magazine_reorder_items_atomic.sql >>>
-- Forward-only, prepared for explicit production approval. Do not apply implicitly.
CREATE OR REPLACE FUNCTION public.magazine_reorder_items_atomic(
  p_magazine_id UUID,
  p_expected_updated_at TIMESTAMPTZ,
  p_ordered_item_ids UUID[]
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_owner UUID;
  v_status TEXT;
  v_updated_at TIMESTAMPTZ;
  v_total INTEGER;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'magazine_auth_required' USING ERRCODE = '42501'; END IF;
  IF p_ordered_item_ids IS NULL OR cardinality(p_ordered_item_ids) > 500 OR array_position(p_ordered_item_ids, NULL) IS NOT NULL THEN
    RAISE EXCEPTION 'magazine_item_ids_invalid' USING ERRCODE = '22023';
  END IF;
  IF (SELECT COUNT(DISTINCT id) FROM unnest(p_ordered_item_ids) AS ids(id)) <> cardinality(p_ordered_item_ids) THEN
    RAISE EXCEPTION 'magazine_item_ids_duplicated' USING ERRCODE = '22023';
  END IF;

  SELECT owner_id, status::TEXT, updated_at INTO v_owner, v_status, v_updated_at
    FROM public.magazines WHERE id = p_magazine_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'magazine_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_owner <> v_actor AND NOT COALESCE(public.has_role(v_actor, 'admin'::public.app_role), FALSE) THEN
    RAISE EXCEPTION 'magazine_forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_status <> 'draft' THEN RAISE EXCEPTION 'magazine_not_editable' USING ERRCODE = '55000'; END IF;
  IF v_updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'magazine_edit_conflict' USING ERRCODE = '40001';
  END IF;

  SELECT COUNT(*) INTO v_total FROM public.magazine_items WHERE magazine_id = p_magazine_id;
  IF v_total <> cardinality(p_ordered_item_ids)
     OR EXISTS (
       SELECT 1 FROM unnest(p_ordered_item_ids) AS ids(id)
        WHERE NOT EXISTS (
          SELECT 1 FROM public.magazine_items mi
           WHERE mi.magazine_id = p_magazine_id AND mi.id = ids.id
        )
     ) THEN
    RAISE EXCEPTION 'magazine_reorder_requires_complete_item_set' USING ERRCODE = '22023';
  END IF;

  WITH desired AS (
    SELECT id, ordinality - 1 AS position
      FROM unnest(p_ordered_item_ids) WITH ORDINALITY AS ids(id, ordinality)
  )
  UPDATE public.magazine_items AS mi
     SET position = desired.position,
         updated_at = clock_timestamp()
    FROM desired
   WHERE mi.magazine_id = p_magazine_id AND mi.id = desired.id;

  UPDATE public.magazines SET updated_at = clock_timestamp() WHERE id = p_magazine_id
  RETURNING updated_at INTO v_updated_at;
  RETURN jsonb_build_object('reordered', v_total, 'updated_at', v_updated_at);
END;
$$;

REVOKE ALL ON FUNCTION public.magazine_reorder_items_atomic(UUID, TIMESTAMPTZ, UUID[]) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.magazine_reorder_items_atomic(UUID, TIMESTAMPTZ, UUID[]) TO authenticated, service_role;

-- <<< END 20260909181200_magazine_reorder_items_atomic.sql <<<

-- >>> BEGIN 20260909181300_magazine_duplicate_atomic.sql >>>
-- Forward-only, prepared for explicit production approval. Do not apply implicitly.
CREATE OR REPLACE FUNCTION public.magazine_duplicate_atomic(
  p_source_magazine_id UUID,
  p_title TEXT DEFAULT NULL
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_source public.magazines%ROWTYPE;
  v_new_id UUID;
  v_item_count INTEGER;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'magazine_auth_required' USING ERRCODE = '42501'; END IF;
  SELECT * INTO v_source FROM public.magazines
   WHERE id = p_source_magazine_id AND deleted_at IS NULL FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'magazine_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_source.owner_id <> v_actor
     AND NOT COALESCE(public.has_role(v_actor, 'admin'::public.app_role), FALSE) THEN
    RAISE EXCEPTION 'magazine_forbidden' USING ERRCODE = '42501';
  END IF;

  INSERT INTO public.magazines (
    owner_id, organization_id, title, subtitle, template_id, branding,
    content_settings, page_order, status, public_token, published_at, archived_at
  ) VALUES (
    v_actor, v_source.organization_id,
    LEFT(COALESCE(NULLIF(BTRIM(p_title), ''), v_source.title || ' (cópia)'), 200),
    v_source.subtitle, v_source.template_id, v_source.branding,
    v_source.content_settings, v_source.page_order, 'draft', NULL, NULL, NULL
  ) RETURNING id INTO v_new_id;

  INSERT INTO public.magazine_items (
    magazine_id, product_id, product_snapshot, variant_color_name,
    position, page_number, overrides
  )
  SELECT v_new_id, product_id, product_snapshot, variant_color_name,
         position, page_number, overrides
    FROM public.magazine_items
   WHERE magazine_id = p_source_magazine_id
   ORDER BY position;
  GET DIAGNOSTICS v_item_count = ROW_COUNT;
  RETURN jsonb_build_object('magazine_id', v_new_id, 'items_copied', v_item_count);
END;
$$;

