-- >>> BEGIN 20260909190200_magazine_add_items_null_safe.sql >>>
-- Forward-only correction: SQL NULL must not become a successful no-op.
CREATE OR REPLACE FUNCTION public.magazine_add_items_atomic(
  p_magazine_id UUID,
  p_expected_updated_at TIMESTAMPTZ,
  p_items JSONB
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_owner UUID;
  v_status TEXT;
  v_updated_at TIMESTAMPTZ;
  v_base_position NUMERIC;
  v_current_count INTEGER;
  v_new_count INTEGER;
  v_inserted INTEGER;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'magazine_auth_required' USING ERRCODE = '42501';
  END IF;
  IF p_items IS NULL OR jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'magazine_items_invalid' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(p_items) NOT BETWEEN 1 AND 500 THEN
    RAISE EXCEPTION 'magazine_items_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT owner_id, status::TEXT, updated_at
    INTO v_owner, v_status, v_updated_at
    FROM public.magazines
   WHERE id = p_magazine_id AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'magazine_not_found' USING ERRCODE = 'P0002';
  END IF;
  IF v_owner <> v_actor AND NOT COALESCE(public.has_role(v_actor, 'admin'::public.app_role), FALSE) THEN
    RAISE EXCEPTION 'magazine_forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'magazine_not_editable' USING ERRCODE = '55000';
  END IF;
  IF v_updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION 'magazine_edit_conflict' USING ERRCODE = '40001';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM jsonb_array_elements(p_items) AS entry(value)
     WHERE jsonb_typeof(value) IS DISTINCT FROM 'object'
        OR value->>'product_id' IS NULL
        OR jsonb_typeof(value->'product_snapshot') IS DISTINCT FROM 'object'
  ) THEN
    RAISE EXCEPTION 'magazine_items_invalid' USING ERRCODE = '22023';
  END IF;

  SELECT COUNT(*), COALESCE(MAX(position), -1) + 1
    INTO v_current_count, v_base_position
    FROM public.magazine_items
   WHERE magazine_id = p_magazine_id;
  SELECT COUNT(*) INTO v_new_count
    FROM (
      SELECT DISTINCT (entry.value->>'product_id')::UUID AS product_id
        FROM jsonb_array_elements(p_items) AS entry(value)
    ) AS payload
   WHERE NOT EXISTS (
     SELECT 1 FROM public.magazine_items mi
      WHERE mi.magazine_id = p_magazine_id AND mi.product_id = payload.product_id
   );
  IF v_current_count + v_new_count > 500 THEN
    RAISE EXCEPTION 'magazine_item_limit_exceeded' USING ERRCODE = '22023';
  END IF;

  WITH payload AS (
    SELECT DISTINCT ON ((entry.value->>'product_id')::UUID)
           (entry.value->>'product_id')::UUID AS product_id,
           entry.value->'product_snapshot' AS product_snapshot,
           NULLIF(entry.value->>'variant_color_name', '') AS variant_color_name,
           CASE WHEN entry.value ? 'page_number' THEN (entry.value->>'page_number')::INTEGER END AS page_number,
           COALESCE(entry.value->'overrides', '{}'::JSONB) AS overrides,
           entry.ordinality
      FROM jsonb_array_elements(p_items) WITH ORDINALITY AS entry(value, ordinality)
     ORDER BY (entry.value->>'product_id')::UUID, entry.ordinality
  ), ordered AS (
    SELECT *, ROW_NUMBER() OVER (ORDER BY ordinality) - 1 AS position_offset
      FROM payload
  )
  INSERT INTO public.magazine_items (
    magazine_id, product_id, product_snapshot, variant_color_name, position, page_number, overrides
  )
  SELECT p_magazine_id, product_id, product_snapshot, variant_color_name,
         v_base_position + position_offset, page_number, overrides
    FROM ordered
  ON CONFLICT (magazine_id, product_id) DO NOTHING;
  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  UPDATE public.magazines SET updated_at = clock_timestamp() WHERE id = p_magazine_id
  RETURNING updated_at INTO v_updated_at;
  RETURN jsonb_build_object('inserted', v_inserted, 'updated_at', v_updated_at);
END;
$$;

REVOKE ALL ON FUNCTION public.magazine_add_items_atomic(UUID, TIMESTAMPTZ, JSONB) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.magazine_add_items_atomic(UUID, TIMESTAMPTZ, JSONB) TO authenticated, service_role;

-- <<< END 20260909190200_magazine_add_items_null_safe.sql <<<

-- >>> BEGIN 20260909190300_magazine_publish_atomic.sql >>>
-- Forward-only: status and trigger-issued public token are confirmed atomically.
CREATE OR REPLACE FUNCTION public.magazine_publish_atomic(
  p_magazine_id UUID
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_owner UUID;
  v_status TEXT;
  v_title TEXT;
  v_public_token TEXT;
  v_published_at TIMESTAMPTZ;
  v_updated_at TIMESTAMPTZ;
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'magazine_auth_required' USING ERRCODE = '42501'; END IF;

  SELECT owner_id, status::TEXT, title, public_token, published_at, updated_at
    INTO v_owner, v_status, v_title, v_public_token, v_published_at, v_updated_at
    FROM public.magazines
   WHERE id = p_magazine_id AND deleted_at IS NULL
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'magazine_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_owner <> v_actor AND NOT COALESCE(public.has_role(v_actor, 'admin'::public.app_role), FALSE) THEN
    RAISE EXCEPTION 'magazine_forbidden' USING ERRCODE = '42501';
  END IF;

  IF v_status = 'published' THEN
    IF v_public_token IS NULL OR BTRIM(v_public_token) = '' THEN
      RAISE EXCEPTION 'magazine_publish_token_missing' USING ERRCODE = '55000';
    END IF;
    RETURN jsonb_build_object(
      'public_token', v_public_token,
      'published_at', v_published_at,
      'updated_at', v_updated_at
    );
  END IF;
  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'magazine_not_publishable' USING ERRCODE = '55000';
  END IF;
  IF BTRIM(COALESCE(v_title, '')) = '' OR NOT EXISTS (
    SELECT 1 FROM public.magazine_items WHERE magazine_id = p_magazine_id
  ) THEN
    RAISE EXCEPTION 'magazine_publish_requirements_not_met' USING ERRCODE = '22023';
  END IF;

  UPDATE public.magazines
     SET status = 'published'
   WHERE id = p_magazine_id
   RETURNING public_token, published_at, updated_at
        INTO v_public_token, v_published_at, v_updated_at;

  -- The canonical BEFORE trigger owns token generation. Raising here rolls
  -- the status change back in the same transaction if that contract breaks.
  IF v_public_token IS NULL OR BTRIM(v_public_token) = '' THEN
    RAISE EXCEPTION 'magazine_publish_token_missing' USING ERRCODE = '55000';
  END IF;

  RETURN jsonb_build_object(
    'public_token', v_public_token,
    'published_at', v_published_at,
    'updated_at', v_updated_at
  );
END;
$$;

REVOKE ALL ON FUNCTION public.magazine_publish_atomic(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.magazine_publish_atomic(UUID) TO authenticated, service_role;

-- <<< END 20260909190300_magazine_publish_atomic.sql <<<

-- >>> BEGIN 20260909190400_magazine_page_order_numeric_version.sql >>>
-- Forward-only correction: the v2 discriminator must be the JSON number 2.
CREATE OR REPLACE FUNCTION public.magazine_update_metadata_atomic(
  p_magazine_id UUID,
  p_expected_updated_at TIMESTAMPTZ,
  p_patch JSONB
) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'pg_temp'
AS $$
DECLARE
  v_actor UUID := auth.uid();
  v_owner UUID;
  v_status TEXT;
  v_updated_at TIMESTAMPTZ;
  v_unknown_keys TEXT[];
BEGIN
  IF v_actor IS NULL THEN RAISE EXCEPTION 'magazine_auth_required' USING ERRCODE = '42501'; END IF;
  IF jsonb_typeof(p_patch) IS DISTINCT FROM 'object' OR p_patch = '{}'::JSONB THEN
    RAISE EXCEPTION 'magazine_patch_invalid' USING ERRCODE = '22023';
  END IF;
  SELECT ARRAY(
    SELECT key FROM jsonb_object_keys(p_patch) AS keys(key)
     WHERE key <> ALL (ARRAY['title', 'subtitle', 'template_id', 'branding', 'content_settings', 'page_order'])
  ) INTO v_unknown_keys;
  IF cardinality(v_unknown_keys) > 0 THEN
    RAISE EXCEPTION 'magazine_patch_unknown_fields: %', array_to_string(v_unknown_keys, ',')
      USING ERRCODE = '22023';
  END IF;
  IF p_patch ? 'title' AND (
    jsonb_typeof(p_patch->'title') IS DISTINCT FROM 'string'
    OR char_length(BTRIM(p_patch->>'title')) NOT BETWEEN 1 AND 200
  ) THEN RAISE EXCEPTION 'magazine_title_invalid' USING ERRCODE = '22023'; END IF;
  IF p_patch ? 'subtitle' AND p_patch->'subtitle' <> 'null'::JSONB
     AND (jsonb_typeof(p_patch->'subtitle') IS DISTINCT FROM 'string' OR char_length(p_patch->>'subtitle') > 300) THEN
    RAISE EXCEPTION 'magazine_subtitle_invalid' USING ERRCODE = '22023';
  END IF;
  IF p_patch ? 'branding' AND jsonb_typeof(p_patch->'branding') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'magazine_branding_invalid' USING ERRCODE = '22023';
  END IF;
  IF p_patch ? 'content_settings' AND jsonb_typeof(p_patch->'content_settings') IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'magazine_content_invalid' USING ERRCODE = '22023';
  END IF;
  IF p_patch ? 'page_order' AND p_patch->'page_order' <> 'null'::JSONB
     AND (
       jsonb_typeof(p_patch->'page_order') = 'array'
       OR (
         jsonb_typeof(p_patch->'page_order') = 'object'
         AND jsonb_typeof(p_patch->'page_order'->'version') = 'number'
         AND (p_patch->'page_order'->>'version')::NUMERIC = 2
         AND jsonb_typeof(p_patch->'page_order'->'pages') = 'array'
         AND jsonb_array_length(p_patch->'page_order'->'pages') <= 200
       )
     ) IS NOT TRUE THEN RAISE EXCEPTION 'magazine_page_order_invalid' USING ERRCODE = '22023'; END IF;
  IF p_patch ? 'page_order'
     AND jsonb_typeof(p_patch->'page_order') = 'object'
     AND (
       jsonb_array_length(p_patch->'page_order'->'pages') < 2
       OR p_patch->'page_order'->'pages'->0->>'kind' IS DISTINCT FROM 'cover'
       OR NOT COALESCE(
         p_patch->'page_order'->'pages'->-1->>'kind' = ANY (ARRAY['contact', 'back-cover']),
         FALSE
       )
       OR (
         SELECT COUNT(*) FROM jsonb_array_elements(p_patch->'page_order'->'pages') AS page(value)
          WHERE value->>'kind' = 'cover'
       ) <> 1
       OR (
         SELECT COUNT(*) FROM jsonb_array_elements(p_patch->'page_order'->'pages') AS page(value)
          WHERE value->>'kind' IN ('contact', 'back-cover')
       ) <> 1
       OR EXISTS (
         SELECT 1 FROM jsonb_array_elements(p_patch->'page_order'->'pages') AS page(value)
          WHERE jsonb_typeof(value) IS DISTINCT FROM 'object'
             OR jsonb_typeof(value->'id') IS DISTINCT FROM 'string'
             OR char_length(value->>'id') NOT BETWEEN 1 AND 120
             OR jsonb_typeof(value->'kind') IS DISTINCT FROM 'string'
             OR NOT COALESCE(
               value->>'kind' = ANY (
                 ARRAY['cover', 'institutional', 'section', 'products', 'contact', 'back-cover']
               ),
               FALSE
             )
             OR (value ? 'title' AND (jsonb_typeof(value->'title') IS DISTINCT FROM 'string' OR char_length(value->>'title') > 120))
             OR (value ? 'body' AND (jsonb_typeof(value->'body') IS DISTINCT FROM 'string' OR char_length(value->>'body') > 800))
             OR (value ? 'itemIds' AND jsonb_typeof(value->'itemIds') IS DISTINCT FROM 'array')
             OR (value ? 'itemIds' AND jsonb_typeof(value->'itemIds') = 'array' AND jsonb_array_length(value->'itemIds') > 500)
             OR (value ? 'itemIds' AND jsonb_typeof(value->'itemIds') = 'array' AND EXISTS (
               SELECT 1 FROM jsonb_array_elements(
                 CASE WHEN jsonb_typeof(value->'itemIds') = 'array' THEN value->'itemIds' ELSE '[]'::JSONB END
               ) AS item_id(value)
                WHERE jsonb_typeof(item_id.value) IS DISTINCT FROM 'string'
             ))
             OR (value ? 'itemIds' AND jsonb_typeof(value->'itemIds') = 'array' AND (
               SELECT COUNT(*) FROM jsonb_array_elements(
                 CASE WHEN jsonb_typeof(value->'itemIds') = 'array' THEN value->'itemIds' ELSE '[]'::JSONB END
               ) AS item_id(value)
             ) <> (
               SELECT COUNT(DISTINCT item_id.value) FROM jsonb_array_elements(
                 CASE WHEN jsonb_typeof(value->'itemIds') = 'array' THEN value->'itemIds' ELSE '[]'::JSONB END
               ) AS item_id(value)
             ))
       )
       OR (
         SELECT COUNT(*) FROM jsonb_array_elements(p_patch->'page_order'->'pages') AS page(value)
       ) <> (
         SELECT COUNT(DISTINCT value->>'id')
           FROM jsonb_array_elements(p_patch->'page_order'->'pages') AS page(value)
       )
     ) THEN RAISE EXCEPTION 'magazine_page_order_invalid' USING ERRCODE = '22023'; END IF;

  SELECT owner_id, status::TEXT, updated_at INTO v_owner, v_status, v_updated_at
    FROM public.magazines WHERE id = p_magazine_id AND deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'magazine_not_found' USING ERRCODE = 'P0002'; END IF;
  IF v_owner <> v_actor AND NOT COALESCE(public.has_role(v_actor, 'admin'::public.app_role), FALSE) THEN
    RAISE EXCEPTION 'magazine_forbidden' USING ERRCODE = '42501';
  END IF;
  IF v_status <> 'draft' THEN RAISE EXCEPTION 'magazine_not_editable' USING ERRCODE = '55000'; END IF;
  IF v_updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RETURN jsonb_build_object('conflict', TRUE, 'current_updated_at', v_updated_at);
  END IF;

  UPDATE public.magazines
     SET title = CASE WHEN p_patch ? 'title' THEN BTRIM(p_patch->>'title') ELSE title END,
         subtitle = CASE WHEN p_patch ? 'subtitle' THEN COALESCE(p_patch->>'subtitle', '') ELSE subtitle END,
         template_id = CASE WHEN p_patch ? 'template_id' THEN p_patch->>'template_id' ELSE template_id END,
         branding = CASE WHEN p_patch ? 'branding' THEN p_patch->'branding' ELSE branding END,
         content_settings = CASE WHEN p_patch ? 'content_settings' THEN p_patch->'content_settings' ELSE content_settings END,
         page_order = CASE WHEN p_patch ? 'page_order' THEN NULLIF(p_patch->'page_order', 'null'::JSONB) ELSE page_order END,
         updated_at = clock_timestamp()
   WHERE id = p_magazine_id
   RETURNING updated_at INTO v_updated_at;
  RETURN jsonb_build_object('conflict', FALSE, 'updated_at', v_updated_at);
END;
$$;

REVOKE ALL ON FUNCTION public.magazine_update_metadata_atomic(UUID, TIMESTAMPTZ, JSONB) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.magazine_update_metadata_atomic(UUID, TIMESTAMPTZ, JSONB) TO authenticated, service_role;

