-- Forward-only: idempotent quote creation for Kit Maker.
--
-- This migration is intentionally NOT applied by the repository. Apply only
-- after reconciling the remote migration ledger for doufsxqlfjyuvxuezpln.
-- It wraps the existing audited writer instead of changing its contract, so
-- other quote entry points remain untouched.

DO $precondition$
BEGIN
  IF to_regprocedure('public.create_quote_transactional(jsonb,jsonb)') IS NULL THEN
    RAISE EXCEPTION
      'Precondition failed: public.create_quote_transactional(jsonb,jsonb) is required';
  END IF;

  IF to_regclass('public.quotes') IS NULL THEN
    RAISE EXCEPTION 'Precondition failed: public.quotes is required';
  END IF;
END
$precondition$;

CREATE TABLE IF NOT EXISTS public.kit_quote_requests (
  request_id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  quote_id uuid NOT NULL REFERENCES public.quotes(id) ON DELETE RESTRICT,
  payload_hash text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT kit_quote_requests_payload_hash_not_empty CHECK (length(payload_hash) > 0)
);

COMMENT ON TABLE public.kit_quote_requests IS
  'Idempotency ledger for authenticated Kit Maker quote submissions.';

ALTER TABLE public.kit_quote_requests ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS kit_quote_requests_select_own ON public.kit_quote_requests;
CREATE POLICY kit_quote_requests_select_own
  ON public.kit_quote_requests
  FOR SELECT
  TO authenticated
  USING ((SELECT auth.uid()) = user_id);

-- The wrapper function is SECURITY INVOKER and performs the insert as the
-- authenticated caller. This policy is deliberately narrow; clients never
-- need UPDATE or DELETE access to the ledger.
DROP POLICY IF EXISTS kit_quote_requests_insert_own ON public.kit_quote_requests;
CREATE POLICY kit_quote_requests_insert_own
  ON public.kit_quote_requests
  FOR INSERT
  TO authenticated
  WITH CHECK ((SELECT auth.uid()) = user_id);

REVOKE ALL ON TABLE public.kit_quote_requests FROM PUBLIC;
GRANT SELECT, INSERT ON TABLE public.kit_quote_requests TO authenticated;

CREATE OR REPLACE FUNCTION public.create_kit_quote_transactional(
  _request_id uuid,
  _quote jsonb,
  _items jsonb
)
RETURNS public.quotes
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public
AS $function$
DECLARE
  _actor_id uuid := auth.uid();
  _payload_hash text;
  _existing public.kit_quote_requests%ROWTYPE;
  _quote_result public.quotes;
BEGIN
  IF _actor_id IS NULL THEN
    RAISE EXCEPTION 'Authentication is required to create a Kit Maker quote'
      USING ERRCODE = '28000';
  END IF;

  IF _request_id IS NULL THEN
    RAISE EXCEPTION 'A request id is required for idempotent quote creation'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(_quote) IS DISTINCT FROM 'object'
     OR jsonb_typeof(_items) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Invalid quote payload'
      USING ERRCODE = '22023';
  END IF;

  _payload_hash := md5(_quote::text || E'\n' || _items::text);

  -- Serializes equal request ids before the underlying writer is invoked.
  -- This closes both double-click and response-timeout retry races.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(_actor_id::text || ':' || _request_id::text, 0)
  );

  SELECT *
  INTO _existing
  FROM public.kit_quote_requests
  WHERE request_id = _request_id
    AND user_id = _actor_id;

  IF FOUND THEN
    IF _existing.payload_hash <> _payload_hash THEN
      RAISE EXCEPTION 'The request id was already used with a different payload'
        USING ERRCODE = '22023';
    END IF;

    SELECT * INTO _quote_result
    FROM public.quotes
    WHERE id = _existing.quote_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Idempotency ledger references a missing quote'
        USING ERRCODE = '23503';
    END IF;

    RETURN _quote_result;
  END IF;

  SELECT * INTO _quote_result
  FROM public.create_quote_transactional(_quote, _items);

  INSERT INTO public.kit_quote_requests (request_id, user_id, quote_id, payload_hash)
  VALUES (_request_id, _actor_id, _quote_result.id, _payload_hash);

  RETURN _quote_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.create_kit_quote_transactional(uuid, jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_kit_quote_transactional(uuid, jsonb, jsonb)
  TO authenticated;

COMMENT ON FUNCTION public.create_kit_quote_transactional(uuid, jsonb, jsonb) IS
  'Kit Maker idempotent wrapper around create_quote_transactional; same request id returns the original quote.';

DO $postcondition$
BEGIN
  IF to_regprocedure('public.create_kit_quote_transactional(uuid,jsonb,jsonb)') IS NULL THEN
    RAISE EXCEPTION 'Postcondition failed: Kit Maker idempotent RPC was not created';
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_class relation
    JOIN pg_catalog.pg_namespace namespace ON namespace.oid = relation.relnamespace
    WHERE namespace.nspname = 'public'
      AND relation.relname = 'kit_quote_requests'
      AND relation.relrowsecurity
  ) THEN
    RAISE EXCEPTION 'Postcondition failed: kit_quote_requests RLS is not enabled';
  END IF;
END
$postcondition$;

-- <<< END 20260911172000_kit_maker_quote_idempotency.sql <<<

-- >>> BEGIN 20260912150000_kit_maker_quote_lineage_forward_only.sql >>>
-- Forward-only Kit Maker quote lineage.
--
-- Persists the selected variant, approved artwork references and Kit Maker
-- context in the *idempotent Kit Maker wrapper*.  The generic quote writer is
-- deliberately left untouched: other quote entry points retain their audited
-- contract while this path gains the metadata its UI actually sends.
--
-- Apply only after checking the live function definition below.  Every
-- precondition fails closed if another agent has updated this contract.

DO $precondition$
DECLARE
  _definition text;
BEGIN
  IF to_regprocedure('public.create_kit_quote_transactional(uuid,jsonb,jsonb)') IS NULL THEN
    RAISE EXCEPTION 'Precondition failed: create_kit_quote_transactional(uuid,jsonb,jsonb) is required';
  END IF;
  IF to_regprocedure('public.create_quote_transactional(jsonb,jsonb)') IS NULL THEN
    RAISE EXCEPTION 'Precondition failed: create_quote_transactional(jsonb,jsonb) is required';
  END IF;
  IF to_regclass('public.quote_items') IS NULL
     OR to_regclass('public.quotes') IS NULL
     OR to_regclass('public.product_variants') IS NULL THEN
    RAISE EXCEPTION 'Precondition failed: quote_items, quotes and product_variants are required';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'quote_items' AND column_name = 'artwork_urls'
  ) OR NOT EXISTS (
    SELECT 1
    FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'quotes' AND column_name = 'tags'
  ) THEN
    RAISE EXCEPTION 'Precondition failed: expected quote metadata columns are missing';
  END IF;

  SELECT pg_get_functiondef('public.create_kit_quote_transactional(uuid,jsonb,jsonb)'::regprocedure)
  INTO _definition;
  IF strpos(_definition, 'public.create_quote_transactional(_quote, _items)') = 0
     OR strpos(_definition, 'kit_quote_requests') = 0
     OR strpos(_definition, 'payload_hash') = 0
     OR strpos(_definition, 'product_variant_id') > 0 THEN
    RAISE EXCEPTION 'Precondition failed: Kit Maker quote wrapper drifted; re-audit before replacing it';
  END IF;
END
$precondition$;

ALTER TABLE public.quote_items
  ADD COLUMN IF NOT EXISTS product_variant_id uuid;

DO $foreign_key$
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM pg_catalog.pg_constraint
    WHERE conrelid = 'public.quote_items'::regclass
      AND conname = 'quote_items_product_variant_id_fkey'
  ) THEN
    ALTER TABLE public.quote_items
      ADD CONSTRAINT quote_items_product_variant_id_fkey
      FOREIGN KEY (product_variant_id)
      REFERENCES public.product_variants(id)
      ON DELETE SET NULL;
  END IF;
END
$foreign_key$;

CREATE INDEX IF NOT EXISTS idx_quote_items_product_variant_id
  ON public.quote_items (product_variant_id);

CREATE OR REPLACE FUNCTION public.create_kit_quote_transactional(
  _request_id uuid,
  _quote jsonb,
  _items jsonb
)
RETURNS public.quotes
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public
AS $function$
DECLARE
  _actor_id uuid := auth.uid();
  _payload_hash text;
  _existing public.kit_quote_requests%ROWTYPE;
  _quote_result public.quotes;
  _item jsonb;
  _ordinality bigint;
  _variant_id uuid;
  _product_id uuid;
  _artwork_urls jsonb;
  _updated_count integer;
BEGIN
  IF _actor_id IS NULL THEN
    RAISE EXCEPTION 'Authentication is required to create a Kit Maker quote'
      USING ERRCODE = '28000';
  END IF;

  IF _request_id IS NULL THEN
    RAISE EXCEPTION 'A request id is required for idempotent quote creation'
      USING ERRCODE = '22023';
  END IF;

  IF jsonb_typeof(_quote) IS DISTINCT FROM 'object'
     OR jsonb_typeof(_items) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'Invalid quote payload'
      USING ERRCODE = '22023';
  END IF;

  IF _quote ? 'tags' AND jsonb_typeof(_quote->'tags') <> 'object' THEN
    RAISE EXCEPTION 'Kit Maker quote tags must be a JSON object'
      USING ERRCODE = '22023';
  END IF;

  _payload_hash := md5(_quote::text || E'\n' || _items::text);

  -- Serializes equal request ids before the underlying writer is invoked.
  PERFORM pg_advisory_xact_lock(
    hashtextextended(_actor_id::text || ':' || _request_id::text, 0)
  );

  SELECT *
  INTO _existing
  FROM public.kit_quote_requests
  WHERE request_id = _request_id
    AND user_id = _actor_id;

  IF FOUND THEN
    IF _existing.payload_hash <> _payload_hash THEN
      RAISE EXCEPTION 'The request id was already used with a different payload'
        USING ERRCODE = '22023';
    END IF;

    SELECT * INTO _quote_result
    FROM public.quotes
    WHERE id = _existing.quote_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'Idempotency ledger references a missing quote'
        USING ERRCODE = '23503';
    END IF;

    RETURN _quote_result;
  END IF;

  SELECT * INTO _quote_result
  FROM public.create_quote_transactional(_quote, _items);

  IF _quote ? 'tags' THEN
    UPDATE public.quotes
    SET tags = _quote->'tags'
    WHERE id = _quote_result.id;
  END IF;

  FOR _item, _ordinality IN
    SELECT value, ordinality
    FROM jsonb_array_elements(_items) WITH ORDINALITY
  LOOP
    IF _item ? 'artwork_urls' AND jsonb_typeof(_item->'artwork_urls') <> 'array' THEN
      RAISE EXCEPTION 'artwork_urls must be a JSON array'
        USING ERRCODE = '22023';
    END IF;

    _product_id := nullif(_item->>'product_id', '')::uuid;
    _variant_id := nullif(_item->>'product_variant_id', '')::uuid;
    _artwork_urls := CASE
      WHEN _item ? 'artwork_urls' THEN _item->'artwork_urls'
      ELSE '[]'::jsonb
    END;

    IF _variant_id IS NOT NULL AND NOT EXISTS (
      SELECT 1
      FROM public.product_variants variant
      WHERE variant.id = _variant_id
        AND variant.product_id = _product_id
    ) THEN
      RAISE EXCEPTION 'Selected variant does not belong to the quoted product'
        USING ERRCODE = '23503';
    END IF;

    UPDATE public.quote_items
    SET artwork_urls = _artwork_urls,
        product_variant_id = _variant_id
    WHERE quote_id = _quote_result.id
      AND sort_order = coalesce(nullif(_item->>'sort_order', '')::integer, _ordinality::integer - 1)
      AND product_id IS NOT DISTINCT FROM _product_id;

    GET DIAGNOSTICS _updated_count = ROW_COUNT;
    IF _updated_count <> 1 THEN
      RAISE EXCEPTION 'Kit Maker quote lineage could not match exactly one quote item (sort order %, product %)',
        coalesce(nullif(_item->>'sort_order', '')::integer, _ordinality::integer - 1),
        _product_id
        USING ERRCODE = '23505';
    END IF;
  END LOOP;

  INSERT INTO public.kit_quote_requests (request_id, user_id, quote_id, payload_hash)
  VALUES (_request_id, _actor_id, _quote_result.id, _payload_hash);

  RETURN _quote_result;
END;
$function$;

REVOKE ALL ON FUNCTION public.create_kit_quote_transactional(uuid, jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.create_kit_quote_transactional(uuid, jsonb, jsonb)
  TO authenticated;

COMMENT ON FUNCTION public.create_kit_quote_transactional(uuid, jsonb, jsonb) IS
  'Idempotent Kit Maker quote writer; persists Kit context, artwork URLs and the selected catalog variant.';

DO $postcondition$
DECLARE
  _definition text;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'quote_items' AND column_name = 'product_variant_id'
  ) THEN
    RAISE EXCEPTION 'Postcondition failed: quote_items.product_variant_id was not created';
  END IF;

  SELECT pg_get_functiondef('public.create_kit_quote_transactional(uuid,jsonb,jsonb)'::regprocedure)
  INTO _definition;
  IF strpos(_definition, 'artwork_urls') = 0
     OR strpos(_definition, 'product_variant_id') = 0
     OR strpos(_definition, 'SET tags = _quote') = 0
     OR NOT has_function_privilege(
       'authenticated',
       'public.create_kit_quote_transactional(uuid,jsonb,jsonb)',
       'EXECUTE'
     ) THEN
    RAISE EXCEPTION 'Postcondition failed: Kit Maker quote lineage contract is incomplete';
  END IF;
END
$postcondition$;

-- <<< END 20260912150000_kit_maker_quote_lineage_forward_only.sql <<<

-- >>> BEGIN 20260912151000_kit_maker_atomic_pin_forward_only.sql >>>
-- Forward-only: one pinned Kit Maker draft per authenticated owner.
-- Replaces the former client-side "unpin then pin" pair, which could race
-- across two tabs and leave no pin or two visible candidates.

DO $precondition$
BEGIN
  IF to_regclass('public.custom_kits') IS NULL THEN
    RAISE EXCEPTION 'Precondition failed: public.custom_kits is required';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'custom_kits' AND column_name = 'is_pinned'
  ) THEN
    RAISE EXCEPTION 'Precondition failed: custom_kits.is_pinned is required';
  END IF;
  IF EXISTS (
    SELECT 1
    FROM public.custom_kits
    WHERE is_pinned
    GROUP BY user_id
    HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'Precondition failed: existing duplicate pinned kits require explicit reconciliation';
  END IF;
END
$precondition$;

CREATE UNIQUE INDEX IF NOT EXISTS custom_kits_one_pinned_per_user_idx
  ON public.custom_kits (user_id)
  WHERE is_pinned;

CREATE OR REPLACE FUNCTION public.set_custom_kit_pinned(
  _kit_id uuid,
  _is_pinned boolean
)
RETURNS public.custom_kits
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = pg_catalog, public
AS $function$
DECLARE
  _actor_id uuid := auth.uid();
  _kit public.custom_kits;
BEGIN
  IF _actor_id IS NULL THEN
    RAISE EXCEPTION 'Authentication is required to change a pinned kit'
      USING ERRCODE = '28000';
  END IF;
  IF _kit_id IS NULL THEN
    RAISE EXCEPTION 'A kit id is required'
      USING ERRCODE = '22023';
  END IF;

  -- Serialise all pin changes for one owner before unpinning any row.
  PERFORM pg_advisory_xact_lock(hashtextextended(_actor_id::text || ':custom-kit-pin', 0));

  SELECT *
  INTO _kit
  FROM public.custom_kits
  WHERE id = _kit_id
    AND user_id = _actor_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Kit not found or not owned by the authenticated user'
      USING ERRCODE = '42501';
  END IF;

  IF _is_pinned THEN
    UPDATE public.custom_kits
    SET is_pinned = false
    WHERE user_id = _actor_id
      AND is_pinned
      AND id <> _kit_id;
  END IF;

  UPDATE public.custom_kits
  SET is_pinned = _is_pinned
  WHERE id = _kit_id
    AND user_id = _actor_id
  RETURNING * INTO _kit;

  RETURN _kit;
END;
$function$;

REVOKE ALL ON FUNCTION public.set_custom_kit_pinned(uuid, boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_custom_kit_pinned(uuid, boolean) TO authenticated;

COMMENT ON FUNCTION public.set_custom_kit_pinned(uuid, boolean) IS
  'Atomically pins or unpins one owned Kit Maker draft; serializes concurrent tabs per user.';

DO $postcondition$
BEGIN
  IF to_regprocedure('public.set_custom_kit_pinned(uuid,boolean)') IS NULL
     OR NOT EXISTS (
       SELECT 1
       FROM pg_indexes
       WHERE schemaname = 'public'
         AND indexname = 'custom_kits_one_pinned_per_user_idx'
     )
     OR NOT has_function_privilege(
       'authenticated',
       'public.set_custom_kit_pinned(uuid,boolean)',
       'EXECUTE'
     ) THEN
    RAISE EXCEPTION 'Postcondition failed: atomic Kit Maker pin contract is incomplete';
  END IF;
END
$postcondition$;

-- <<< END 20260912151000_kit_maker_atomic_pin_forward_only.sql <<<

